<?php
namespace App\Http\Controllers;
use Illuminate\Http\Response;
use Illuminate\Http\Request;
use App\Models\Userprofile;
use App\Traits\Common;
use App\Models\User;
use Exception;
use Log;

class TestController extends Controller
{
	use Common;

   	public function index(Request $request)
   	{
	   	try
	   	{
		   	if($request->key==='123')
		   	{
		   		$user=new User;

		   		$user->name=$request->data['subscriber']['firstname'];
		   		$user->email=$request->data['subscriber']['email'];
		   		$user->mobile_no='7412589635';
		   		$user->password=$request->data['subscriber']['lastname'];

		   		$user->save();
		   	}
		}
		catch(Exception $e)
		{
            Log::info($e->getMessage());

		}
   }

   	public function createaudio()
   	{
   	  	return view('audio');
   	} 

   	public function storeAudio(Request $request)
   	{
		try
		{
			$filename= date('Y-m-dHis').'.'.$request->encoding;
			
		    $this->putContentsByFilename('uploads/audio',$request->file,$filename);
		}
		catch(Exception $e)
		{
            Log::info($e->getMessage());
		}
   	}

   	public function download()
   	{
	   	$path = $this->getFilePathforDownload(env('FILESYSTEM_DRIVER'),'apk/ucf.apk');
	   	
	   	return response()->download($path);
   	}

   	public function verses(Request $request)
   	{
   		$f1="INSERT INTO `bible_verses` (`id`, `english_verse`, `tamil_verse`, `book_id`, `chapter_id`, `verse_id`) VALUES
(1,	'In the beginning God created the heaven and the earth.',	'ஆதியிலே தேவன் வானத்தையும் பூமியையும் சிருஷ்டித்தார்.',	1,	1,	1),
(2,	'And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters.',	'பூமியானது ஒழுங்கின்மையும் வெறுமையுமாய் இருந்தது; ஆழத்தின்மேல் இருள் இருந்தது; தேவ ஆவியானவர் ஜலத்தின்மேல் அசைவாடிக்கொண்டிருந்தார்.',	1,	1,	2),
(3,	'And God said, Let there be light: and there was light.',	'தேவன் வெளிச்சம் உண்டாகக்கடவது என்றார். வெளிச்சம் உண்டாயிற்று.',	1,	1,	3),
(4,	'And God saw the light, that it was good: and God divided the light from the darkness.',	'வெளிச்சம் நல்லது என்று தேவன் கண்டார்; வெளிச்சத்தையும் இருளையும் தேவன் வெவ்வேறாகப் பிரித்தார்.',	1,	1,	4),
(5,	'And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day.',	'தேவன் வெளிச்சத்துக்குப் பகல் என்று பேரிட்டார், இருளுக்கு இரவு என்று பேரிட்டார்; சாயங்காலமும் விடியற்காலமுமாகி முதலாம் நாள் ஆயிற்று.',	1,	1,	5),
(6,	'And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters.',	'பின்பு தேவன்; ஜலத்தின் மத்தியில் ஆகாயவிரிவு உண்டாகக்கடவது என்றும், அது ஜலத்தினின்று ஜலத்தைப் பிரிக்கக்கடவது என்றும் சொன்னார்.',	1,	1,	6),
(7,	'And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so.',	'தேவன் ஆகாயவிரிவை உண்டுபண்ணி, ஆகாயவிரிவுக்குக் கீழே இருக்கிற ஜலத்திற்கும் ஆகாயவிரிவுக்கு மேலே இருக்கிற ஜலத்திற்கும் பிரிவுண்டாக்கினார்; அது அப்படியே ஆயிற்று.',	1,	1,	7),
(8,	'And God called the firmament Heaven. And the evening and the morning were the second day.',	'தேவன் ஆகாயவிரிவுக்கு வானம் என்று பேரிட்டார்; சாயங்காலமும் விடியற்காலமுமாகி, இரண்டாம் நாள் ஆயிற்று.',	1,	1,	8),
(9,	'And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so.',	'பின்பு தேவன்: வானத்தின் கீழே இருக்கிற ஜலம் ஓரிடத்தில் சேரவும், வெட்டாந்தரை காணப்படவும் கடவது என்றார்; அது அப்படியே ஆயிற்று.',	1,	1,	9),
(10,	'And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good.',	'தேவன் வெட்டாந்தரைக்குப் பூமி என்றும், சேர்ந்த ஜலத்திற்குச் சமுத்திரம் என்றும் பேரிட்டார்; தேவன் அது நல்லது என்று கண்டார்.',	1,	1,	10),
(11,	'And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so.',	'அப்பொழுது தேவன்: பூமியானது புல்லையும், விதையைப் பிறப்பிக்கும் பூண்டுகளையும், பூமியின்மேல் தங்களில் தங்கள் விதையையுடைய கனிகளைத் தங்கள் தங்கள் ஜாதியின்படியே கொடுக்கும் கனிவிருட்சங்களையும் முளைப்பிக்கக்கடவது என்றார்; அது அப்படியே ஆயிற்று.',	1,	1,	11),
(12,	'And the earth brought forth grass, and herb yielding seed after his kind, and the tree yielding fruit, whose seed was in itself, after his kind: and God saw that it was good.',	'பூமியானது புல்லையும், தங்கள் தங்கள் ஜாதியின்படியே விதையைப் பிறப்பிக்கும் பூண்டுகளையும், தங்கள் தங்கள் ஜாதியின்படியே தங்களில் தங்கள் விதையையுடைய கனிகளைக் கொடுக்கும் விருட்சங்களையும் முளைப்பித்தது; தேவன் அது நல்லது என்று கண்டார்.',	1,	1,	12),
(13,	'And the evening and the morning were the third day.',	'சாயங்காலமும் விடியற்காலமுமாகி மூன்றாம் நாள் ஆயிற்று.',	1,	1,	13),
(14,	'And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:',	'பின்பு தேவன்: பகலுக்கும் இரவுக்கும் வித்தியாசம் உண்டாகத்தக்கதாக வானம் என்கிற ஆகாயவிரிவிலே சுடர்கள் உண்டாகக்கடவது, அவைகள் அடையாளங்களுக்காகவும், காலங்களையும் நாட்களையும் வருஷங்களையும் குறிக்கிறதற்காகவும் இருக்கக்கடவது என்றார்.',	1,	1,	14),
(15,	'And let them be for lights in the firmament of the heaven to give light upon the earth: and it was so.',	'அவைகள் பூமியின்மேல் பிரகாசிக்கும்படிக்கு வானம் என்கிற ஆகாயவிரிவிலே சுடர்களாயிருக்கக்கடவது என்றார்; அது அப்படியே ஆயிற்று.',	1,	1,	15),
(16,	'And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also.',	'தேவன், பகலை ஆளப் பெரிய சுடரும், இரவை ஆளச் சிறிய சுடரும் ஆகிய இரண்டு மகத்தான சுடர்களையும், நட்சத்திரங்களையும் உண்டாக்கினார்.',	1,	1,	16),
(17,	'And God set them in the firmament of the heaven to give light upon the earth,',	'அவைகள் பூமியின்மேல் பிரகாசிக்கவும்,',	1,	1,	17),
(18,	'And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good.',	'பகலையும் இரவையும் ஆளவும், வெளிச்சத்துக்கும் இருளுக்கும் வித்தியாசம் உண்டாக்கவும், தேவன் அவைகளை வானம் என்கிற ஆகாயவிரிவிலே வைத்தார்; தேவன் அது நல்லது என்று கண்டார்.',	1,	1,	18),
(19,	'And the evening and the morning were the fourth day.',	'சாயங்காலமும் விடியற்காலமுமாகி நாலாம் நாள் ஆயிற்று.',	1,	1,	19),
(20,	'And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl that may fly above the earth in the open firmament of heaven.',	'பின்பு தேவன்: நீந்தும் ஜீவஜந்துக்களையும், பூமியின்மேல் வானம் என்கிற ஆகாயவிரிவிலே பறக்கும் பறவைகளையும், ஜலமானது திரளாய் ஜநிப்பிக்கக்கடவது என்றார்.',	1,	1,	20),
(21,	'And God created great whales, and every living creature that moveth, which the waters brought forth abundantly, after their kind, and every winged fowl after his kind: and God saw that it was good.',	'தேவன், மகா மச்சங்களையும், ஜலத்தில் தங்கள் தங்கள் ஜாதியின்படியே திரளாய் ஜநிப்பிக்கப்பட்ட சகலவித நீர் வாழும் ஜந்துக்களையும், சிறகுள்ள ஜாதிஜாதியான சகலவிதப் பட்சிகளையும் சிருஷ்டித்தார்; தேவன் அது நல்லது என்று கண்டார்.',	1,	1,	21),
(22,	'And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth.',	'தேவன் அவைகளை ஆசீர்வதித்து, நீங்கள் பலுகிப் பெருகி, சமுத்திர ஜலத்தை நிரப்புங்கள் என்றும், பறவைகள் பூமியில் பெருகக்கடவது என்றும் சொன்னார்.',	1,	1,	22),
(23,	'And the evening and the morning were the fifth day.',	'சாயங்காலமும் விடியற்காலமுமாகி ஐந்தாம் நாள் ஆயிற்று.',	1,	1,	23),
(24,	'And God said, Let the earth bring forth the living creature after his kind, cattle, and creeping thing, and beast of the earth after his kind: and it was so.',	'பின்பு தேவன்: பூமியானது ஜாதிஜாதியான ஜீவஜந்துக்களாகிய நாட்டு மிருகங்களையும், ஊரும் பிராணிகளையும், காட்டுமிருகங்களையும், ஜாதிஜாதியாகப் பிறப்பிக்கக்கடவது என்றார்; அது அப்படியே ஆயிற்று.',	1,	1,	24),
(25,	'And God made the beast of the earth after his kind, and cattle after their kind, and every thing that creepeth upon the earth after his kind: and God saw that it was good.',	'தேவன் பூமியிலுள்ள ஜாதிஜாதியான காட்டுமிருகங்களையும், ஜாதிஜாதியான நாட்டுமிருகங்களையும், பூமியில் ஊரும் பிராணிகள் எல்லாவற்றையும் உண்டாக்கினார்; தேவன் அது நல்லது என்று கண்டார்.',	1,	1,	25),
(26,	'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth.',	'பின்பு தேவன்: நமது சாயலாகவும் நமது ரூபத்தின்படியேயும் மனுஷனை உண்டாக்குவோமாக; அவர்கள் சமுத்திரத்தின் மச்சங்களையும், ஆகாயத்துப் பறவைகளையும், மிருகஜீவன்களையும், பூமியனைத்தையும், பூமியின்மேல் ஊரும் சகலப் பிராணிகளையும் ஆளக்கடவர்கள் என்றார்.',	1,	1,	26),
(27,	'So God created man in his own image, in the image of God created he him; male and female created he them.',	'தேவன் தம்முடைய சாயலாக மனுஷனைச் சிருஷ்டித்தார், அவனைத் தேவசாயலாகவே சிருஷ்டித்தார்; ஆணும் பெண்ணுமாக அவர்களைச் சிருஷ்டித்தார்.',	1,	1,	27),
(28,	'And God blessed them, and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth.',	'பின்பு தேவன் அவர்களை நோக்கி: நீங்கள் பலுகிப் பெருகி, பூமியை நிரப்பி, அதைக் கீழ்ப்படுத்தி, சமுத்திரத்தின் மச்சங்களையும் ஆகாயத்துப் பறவைகளையும், பூமியின்மேல் நடமாடுகிற சகல ஜீவஜந்துக்களையும் ஆண்டுகொள்ளுங்கள் என்று சொல்லி, தேவன் அவர்களை ஆசீர்வதித்தார்.',	1,	1,	28),
(29,	'And God said, Behold, I have given you every herb bearing seed, which is upon the face of all the earth, and every tree, in the which is the fruit of a tree yielding seed; to you it shall be for meat.',	'பின்னும் தேவன்: இதோ, பூமியின்மேல் எங்கும் விதைதரும் சகலவிதப் பூண்டுகளையும், விதைதரும் கனிமரங்களாகிய சகலவித விருட்சங்களையும் உங்களுக்குக் கொடுத்தேன், அவைகள் உங்களுக்கு ஆகாரமாயிருக்கக்கடவது;',	1,	1,	29),
(30,	'And to every beast of the earth, and to every fowl of the air, and to every thing that creepeth upon the earth, wherein there is life, I have given every green herb for meat: and it was so.',	'பூமியிலுள்ள சகல மிருகஜீவன்களுக்கும், ஆகாயத்திலுள்ள சகல பறவைகளுக்கும், பூமியின்மேல் ஊரும் பிராணிகள் எல்லாவற்றிற்கும் பசுமையான சகல பூண்டுகளையும் ஆகாரமாகக் கொடுத்தேன் என்றார்; அது அப்படியே ஆயிற்று.',	1,	1,	30),
(31,	'And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day.',	'அப்பொழுது தேவன் தாம் உண்டாக்கின எல்லாவற்றையும் பார்த்தார், அது மிகவும் நன்றாயிருந்தது; சாயங்காலமும் விடியற்காலமுமாகி ஆறாம் நாள் ஆயிற்று.  ',	1,	1,	31),
(32,	'Thus the heavens and the earth were finished, and all the host of them.',	'இவ்விதமாக வானமும் பூமியும், அவைகளின் சர்வசேனையும் உண்டாக்கப்பட்டுத் தீர்ந்தன.',	1,	2,	1),
(33,	'And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made.',	'தேவன் தாம் செய்த தம்முடைய கிரியையை ஏழாம் நாளிலே நிறைவேற்றி, தாம் உண்டாக்கின தம்முடைய கிரியைகளையெல்லாம் முடித்தபின்பு, ஏழாம் நாளிலே ஓய்ந்திருந்தார்.',	1,	2,	2),
(34,	'And God blessed the seventh day, and sanctified it: because that in it he had rested from all his work which God created and made.',	'தேவன் தாம் சிருஷ்டித்து உண்டுபண்ணின தம்முடைய கிரியைகளையெல்லாம் முடித்தபின்பு அதிலே ஓய்ந்திருந்தபடியால், தேவன் ஏழாம் நாளை ஆசீர்வதித்து, அதைப் பரிசுத்தமாக்கினார்.',	1,	2,	3),
(35,	'These are the generations of the heavens and of the earth when they were created, in the day that the LORD God made the earth and the heavens,',	'தேவனாகிய கர்த்தர் பூமியையும் வானத்தையும் உண்டாக்கின நாளிலே, வானமும் பூமியும் சிருஷ்டிக்கப்பட்ட வரலாறு இவைகளே.',	1,	2,	4),
(36,	'And every plant of the field before it was in the earth, and every herb of the field before it grew: for the LORD God had not caused it to rain upon the earth, and there was not a man to till the ground.',	'நிலத்தினுடைய சகலவிதச் செடிகளும் பூமியின்மேல் இன்னும் உண்டாகவில்லை, நிலத்தினுடைய சகலவிதப் பூண்டுகளும் இன்னும் முளைக்கவில்லை; ஏனெனில் தேவனாகிய கர்த்தர் பூமியின்மேல் இன்னும் மழையைப் பெய்யப்பண்ணவில்லை; நிலத்தைப் பண்படுத்த மனுஷனும் இருந்ததில்லை.',	1,	2,	5),
(37,	'But there went up a mist from the earth, and watered the whole face of the ground.',	'அப்பொழுது மூடுபனி பூமியிலிருந்து எழும்பி, பூமியையெல்லாம் நனைத்தது.',	1,	2,	6),
(38,	'And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.',	'தேவனாகிய கர்த்தர் மனுஷனைப் பூமியின் மண்ணினாலே உருவாக்கி, ஜீவசுவாசத்தை அவன் நாசியிலே ஊதினார், மனுஷன் ஜீவாத்துமாவானான்.',	1,	2,	7),
(39,	'And the LORD God planted a garden eastward in Eden; and there he put the man whom he had formed.',	'தேவனாகிய கர்த்தர் கிழக்கே ஏதேன் என்னும் ஒரு தோட்டத்தை உண்டாக்கி, தாம் உருவாக்கின மனுஷனை அதிலே வைத்தார்.',	1,	2,	8),
(40,	'And out of the ground made the LORD God to grow every tree that is pleasant to the sight, and good for food; the tree of life also in the midst of the garden, and the tree of knowledge of good and evil.',	'தேவனாகிய கர்த்தர், பார்வைக்கு அழகும் புசிப்புக்கு நலமுமான சகலவித விருட்சங்களையும், தோட்டத்தின் நடுவிலே ஜீவவிருட்சத்தையும், நன்மை தீமை அறியத்தக்க விருட்சத்தையும் பூமியிலிருந்து முளைக்கப்பண்ணினார்.',	1,	2,	9),
(41,	'And a river went out of Eden to water the garden; and from thence it was parted, and became into four heads.',	'தோட்டத்துக்குத் தண்ணீர் பாயும்படி ஏதேனிலிருந்து ஒரு நதி ஓடி, அங்கேயிருந்து பிரிந்து நாலு பெரிய ஆறுகளாயிற்று.',	1,	2,	10),
(42,	'The name of the first is Pison: that is it which compasseth the whole land of Havilah, where there is gold;',	'முதலாம் ஆற்றுக்குப் பைசோன் என்று பேர், அது ஆவிலா தேசம் முழுவதையும் சுற்றி ஓடும்; அவ்விடத்திலே பொன் விளையும்.',	1,	2,	11),
(43,	'And the gold of that land is good: there is bdellium and the onyx stone.',	'அந்தத் தேசத்தின் பொன் நல்லது; அவ்விடத்திலே பிதோலாகும், கோமேதகக்கல்லும் உண்டு.',	1,	2,	12),
(44,	'And the name of the second river is Gihon: the same is it that compasseth the whole land of Ethiopia.',	'இரண்டாம் ஆற்றுக்குக் கீகோன் என்று பேர், அது எத்தியோப்பியா தேசம் முழுவதையும் சுற்றி ஓடும்.',	1,	2,	13),
(45,	'And the name of the third river is Hiddekel: that is it which goeth toward the east of Assyria. And the fourth river is Euphrates.',	'மூன்றாம் ஆற்றுக்கு இதெக்கேல் என்று பேர், அது அசீரியாவுக்குக் கிழக்கே ஓடும்; நாலாம் ஆற்றுக்கு ஐபிராத்து என்று பேர்.',	1,	2,	14),
(46,	'And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it.',	'தேவனாகிய கர்த்தர் மனுஷனை ஏதேன் தோட்டத்தில் அழைத்துக் கொண்டுவந்து, அதைப் பண்படுத்தவும் காக்கவும் வைத்தார்.',	1,	2,	15),
(47,	'And the LORD God commanded the man, saying, Of every tree of the garden thou mayest freely eat:',	'தேவனாகிய கர்த்தர் மனுஷனை நோக்கி: நீ தோட்டத்திலுள்ள சகல விருட்சத்தின் கனியையும் புசிக்கவே புசிக்கலாம்.',	1,	2,	16),
(48,	'But of the tree of the knowledge of good and evil, thou shalt not eat of it: for in the day that thou eatest thereof thou shalt surely die.',	'ஆனாலும் நன்மை தீமை அறியத்தக்க விருட்சத்தின் கனியைப் புசிக்கவேண்டாம்; அதை நீ புசிக்கும் நாளில் சாகவே சாவாய் என்று கட்டளையிட்டார்.',	1,	2,	17),
(49,	'And the LORD God said, It is not good that the man should be alone; I will make him an help meet for him.',	'பின்பு, தேவனாகிய கர்த்தர்: மனுஷன் தனிமையாயிருப்பது நல்லதல்ல, ஏற்ற துணையை அவனுக்கு உண்டாக்குவேன் என்றார்.',	1,	2,	18),
(50,	'And out of the ground the LORD God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof.',	'தேவனாகிய கர்த்தர் வெளியின் சகலவித மிருகங்களையும், ஆகாயத்தின் சகலவிதப் பறவைகளையும் மண்ணினாலே உருவாக்கி, ஆதாம் அவைகளுக்கு என்ன பேரிடுவான் என்று பார்க்கும்படி அவைகளை அவனிடத்தில் கொண்டுவந்தார்; அந்தந்த ஜீவஜந்துக்கு ஆதாம் எந்தெந்தப் பேரிட்டானோ அதுவே அதற்குப் பேராயிற்று.',	1,	2,	19),
(51,	'And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him.',	'அப்படியே ஆதாம் சகலவித நாட்டு மிருகங்களுக்கும், ஆகாயத்துப் பறவைகளுக்கும், சகலவிதக் காட்டுமிருகங்களுக்கும் பேரிட்டான்; ஆதாமுக்கோ ஏற்ற துணை இன்னும் காணப்படவில்லை.',	1,	2,	20),
(52,	'And the LORD God caused a deep sleep to fall upon Adam, and he slept: and he took one of his ribs, and closed up the flesh instead thereof;',	'அப்பொழுது தேவனாகிய கர்த்தர் ஆதாமுக்கு அயர்ந்த நித்திரையை வரப்பண்ணினார், அவன் நித்திரையடைந்தான்; அவர் அவன் விலா எலும்புகளில் ஒன்றை எடுத்து, அந்த இடத்தைச் சதையினால் அடைத்தார்.',	1,	2,	21),
(53,	'And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man.',	'தேவனாகிய கர்த்தர் தாம் மனுஷனில் எடுத்த விலா எலும்பை மனுஷியாக உருவாக்கி, அவளை மனுஷனிடத்தில் கொண்டுவந்தார்.',	1,	2,	22),
(54,	'And Adam said, This is now bone of my bones, and flesh of my flesh: she shall be called Woman, because she was taken out of Man.',	'அப்பொழுது ஆதாம்: இவள் என் எலும்பில் எலும்பும், என் மாம்சத்தில் மாம்சமுமாய் இருக்கிறாள்; இவள் மனுஷனில் எடுக்கப்பட்டபடியினால் மனுஷி என்னப்படுவாள் என்றான்.',	1,	2,	23),
(55,	'Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh.',	'இதினிமித்தம் புருஷன் தன் தகப்பனையும் தன் தாயையும் விட்டு, தன் மனைவியோடே இசைந்திருப்பான்; அவர்கள் ஒரே மாம்சமாயிருப்பார்கள்.',	1,	2,	24),
(56,	'And they were both naked, the man and his wife, and were not ashamed.',	'ஆதாமும் அவன் மனைவியுமாகிய இருவரும் நிர்வாணிகளாயிருந்தும், வெட்கப்படாதிருந்தார்கள்.  ',	1,	2,	25),
(57,	'Now the serpent was more subtil than any beast of the field which the LORD God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?',	'தேவனாகிய கர்த்தர் உண்டாக்கின சகல காட்டு ஜீவன்களைப்பார்க்கிலும் சர்ப்பமானது தந்திரமுள்ளதாயிருந்தது. அது ஸ்திரீயை நோக்கி: நீங்கள் தோட்டத்திலுள்ள சகல விருட்சங்களின் கனியையும் புசிக்கவேண்டாம் என்று தேவன் சொன்னது உண்டோ என்றது.',	1,	3,	1),
(58,	'And the woman said unto the serpent, We may eat of the fruit of the trees of the garden:',	'ஸ்திரீ சர்ப்பத்தைப் பார்த்து: நாங்கள் தோட்டத்திலுள்ள விருட்சங்களின் கனிகளைப் புசிக்கலாம்;',	1,	3,	2),
(59,	'But of the fruit of the tree which is in the midst of the garden, God hath said, Ye shall not eat of it, neither shall ye touch it, lest ye die.',	'ஆனாலும், தோட்டத்தின் நடுவில் இருக்கிற விருட்சத்தின் கனியைக்குறித்து, தேவன்: நீங்கள் சாகாதபடிக்கு அதைப் புசிக்கவும் அதைத் தொடவும் வேண்டாம் என்று சொன்னார் என்றாள்.',	1,	3,	3),
(60,	'And the serpent said unto the woman, Ye shall not surely die:',	'அப்பொழுது சர்ப்பம் ஸ்திரீயை நோக்கி: நீங்கள் சாகவே சாவதில்லை;',	1,	3,	4),
(61,	'For God doth know that in the day ye eat thereof, then your eyes shall be opened, and ye shall be as gods, knowing good and evil.',	'நீங்கள் இதைப் புசிக்கும் நாளிலே உங்கள் கண்கள் திறக்கப்படும் என்றும், நீங்கள் நன்மை தீமை அறிந்து தேவர்களைப்போல் இருப்பீர்கள் என்றும் தேவன் அறிவார் என்றது.',	1,	3,	5),
(62,	'And when the woman saw that the tree was good for food, and that it was pleasant to the eyes, and a tree to be desired to make one wise, she took of the fruit thereof, and did eat, and gave also unto her husband with her; and he did eat.',	'அப்பொழுது ஸ்திரீயானவள், அந்த விருட்சம் புசிப்புக்கு நல்லதும், பார்வைக்கு இன்பமும், புத்தியைத் தெளிவிக்கிறதற்கு இச்சிக்கப்படத்தக்க விருட்சமுமாய் இருக்கிறது என்று கண்டு, அதின் கனியைப் பறித்து, புசித்து, தன் புருஷனுக்கும் கொடுத்தாள்; அவனும் புசித்தான்.',	1,	3,	6),
(63,	'And the eyes of them both were opened, and they knew that they were naked; and they sewed fig leaves together, and made themselves aprons.',	'அப்பொழுது அவர்கள் இருவருடைய கண்களும் திறக்கப்பட்டது; அவர்கள் தாங்கள் நிர்வாணிகள் என்று அறிந்து, அத்தியிலைகளைத் தைத்து, தங்களுக்கு அரைக்கச்சைகளை உண்டுபண்ணினார்கள்.',	1,	3,	7),
(64,	'And they heard the voice of the LORD God walking in the garden in the cool of the day: and Adam and his wife hid themselves from the presence of the LORD God amongst the trees of the garden.',	'பகலில் குளிர்ச்சியான வேளையிலே தோட்டத்தில் உலாவுகிற தேவனாகிய கர்த்தருடைய சத்தத்தை அவர்கள் கேட்டார்கள். அப்பொழுது ஆதாமும் அவன் மனைவியும் தேவனாகிய கர்த்தருடைய சந்நிதிக்கு விலகி, தோட்டத்தின் விருட்சங்களுக்குள்ளே ஒளித்துக்கொண்டார்கள்.',	1,	3,	8),
(65,	'And the LORD God called unto Adam, and said unto him, Where art thou?',	'அப்பொழுது தேவனாகிய கர்த்தர் ஆதாமைக் கூப்பிட்டு: நீ எங்கே இருக்கிறாய் என்றார்.',	1,	3,	9),
(66,	'And he said, I heard thy voice in the garden, and I was afraid, because I was naked; and I hid myself.',	'அதற்கு அவன்: நான் தேவரீருடைய சத்தத்தைத் தோட்டத்திலே கேட்டு, நான் நிர்வாணியாயிருப்பதினால் பயந்து, ஒளித்துக்கொண்டேன் என்றான்.',	1,	3,	10),
(67,	'And he said, Who told thee that thou wast naked? Hast thou eaten of the tree, whereof I commanded thee that thou shouldest not eat?',	'அப்பொழுது அவர்: நீ நிர்வாணி என்று உனக்கு அறிவித்தவன் யார்? புசிக்கவேண்டாம் என்று நான் உனக்கு விலக்கின விருட்சத்தின் கனியைப் புசித்தாயோ என்றார்.',	1,	3,	11),
(68,	'And the man said, The woman whom thou gavest to be with me, she gave me of the tree, and I did eat.',	'அதற்கு ஆதாம்: என்னுடனே இருக்கும்படி தேவரீர் தந்த ஸ்திரீயானவள் அவ்விருட்சத்தின் கனியை எனக்குக் கொடுத்தாள், நான் புசித்தேன் என்றான்.',	1,	3,	12),
(69,	'And the LORD God said unto the woman, What is this that thou hast done? And the woman said, The serpent beguiled me, and I did eat.',	'அப்பொழுது தேவனாகிய கர்த்தர் ஸ்திரீயை நோக்கி: நீ இப்படிச் செய்தது என்ன என்றார். ஸ்திரீயானவள்: சர்ப்பம் என்னை வஞ்சித்தது, நான் புசித்தேன் என்றாள்.',	1,	3,	13),
(70,	'And the LORD God said unto the serpent, Because thou hast done this, thou art cursed above all cattle, and above every beast of the field; upon thy belly shalt thou go, and dust shalt thou eat all the days of thy life:',	'அப்பொழுது தேவனாகிய கர்த்தர் சர்ப்பத்தைப் பார்த்து: நீ இதைச் செய்தபடியால் சகல நாட்டு மிருகங்களிலும் சகல காட்டு மிருகங்களிலும் சபிக்கப்பட்டிருப்பாய், நீ உன் வயிற்றினால் நகர்ந்து, உயிரோடிருக்கும் நாளெல்லாம் மண்ணைத் தின்பாய்;',	1,	3,	14),
(71,	'And I will put enmity between thee and the woman, and between thy seed and her seed; it shall bruise thy head, and thou shalt bruise his heel.',	'உனக்கும் ஸ்திரீக்கும், உன் வித்துக்கும் அவள் வித்துக்கும் பகை உண்டாக்குவேன்; அவர் உன் தலையை நசுக்குவார், நீ அவர் குதிங்காலை நசுக்குவாய் என்றார்.',	1,	3,	15),
(72,	'Unto the woman he said, I will greatly multiply thy sorrow and thy conception; in sorrow thou shalt bring forth children; and thy desire shall be to thy husband, and he shall rule over thee.',	'அவர் ஸ்திரீயை நோக்கி: நீ கர்ப்பவதியாயிருக்கும்போது உன் வேதனையை மிகவும் பெருகப்பண்ணுவேன்; வேதனையோடே பிள்ளை பெறுவாய்; உன் ஆசை உன் புருஷனைப் பற்றியிருக்கும், அவன் உன்னை ஆண்டுகொள்ளுவான் என்றார்.',	1,	3,	16),
(73,	'And unto Adam he said, Because thou hast hearkened unto the voice of thy wife, and hast eaten of the tree, of which I commanded thee, saying, Thou shalt not eat of it: cursed is the ground for thy sake; in sorrow shalt thou eat of it all the days of thy life;',	'பின்பு அவர் ஆதாமை நோக்கி: நீ உன் மனைவியின் வார்த்தைக்குச் செவிகொடுத்து, புசிக்கவேண்டாம் என்று நான் உனக்கு விலக்கின விருட்சத்தின் கனியைப் புசித்தபடியினாலே, பூமி உன் நிமித்தம் சபிக்கப்பட்டிருக்கும்; நீ உயிரோடிருக்கும் நாளெல்லாம் வருத்தத்தோடே அதின் பலனைப் புசிப்பாய்.',	1,	3,	17),
(74,	'Thorns also and thistles shall it bring forth to thee; and thou shalt eat the herb of the field;',	'அது உனக்கு முள்ளும் குருக்கும் முளைப்பிக்கும்; வெளியின் பயிர்வகைகளைப் புசிப்பாய்.',	1,	3,	18),
(75,	'In the sweat of thy face shalt thou eat bread, till thou return unto the ground; for out of it wast thou taken: for dust thou art, and unto dust shalt thou return.',	'நீ பூமியிலிருந்து எடுக்கப்பட்டபடியால், நீ பூமிக்குத் திரும்புமட்டும் உன் முகத்தின் வேர்வையால் ஆகாரம் புசிப்பாய்; நீ மண்ணாயிருக்கிறாய், மண்ணுக்குத் திரும்புவாய் என்றார்.',	1,	3,	19),
(76,	'And Adam called his wife\'s name Eve; because she was the mother of all living.',	'ஆதாம் தன் மனைவிக்கு ஏவாள் என்று பேரிட்டான்; ஏனெனில், அவள் ஜீவனுள்ளோருக்கெல்லாம் தாயானவள்.',	1,	3,	20),
(77,	'Unto Adam also and to his wife did the LORD God make coats of skins, and clothed them.',	'தேவனாகிய கர்த்தர் ஆதாமுக்கும் அவன் மனைவிக்கும் தோல் உடைகளை உண்டாக்கி அவர்களுக்கு உடுத்தினார்.',	1,	3,	21),
(78,	'And the LORD God said, Behold, the man is become as one of us, to know good and evil: and now, lest he put forth his hand, and take also of the tree of life, and eat, and live for ever:',	'பின்பு தேவனாகிய கர்த்தர்: இதோ, மனுஷன் நன்மை தீமை அறியத்தக்கவனாய் நம்மில் ஒருவரைப்போல் ஆனான்; இப்பொழுதும் அவன் தன் கையை நீட்டி ஜீவவிருட்சத்தின் கனியையும் பறித்து, புசித்து, என்றைக்கும் உயிரோடிராதபடிக்குச் செய்யவேண்டும் என்று,',	1,	3,	22),
(79,	'Therefore the LORD God sent him forth from the garden of Eden, to till the ground from whence he was taken.',	'அவன் எடுக்கப்பட்ட மண்ணைப்பண்படுத்த தேவனாகிய கர்த்தர் அவனை ஏதேன் தோட்டத்திலிருந்து அனுப்பிவிட்டார்.',	1,	3,	23),
(80,	'So he drove out the man; and he placed at the east of the garden of Eden Cherubims, and a flaming sword which turned every way, to keep the way of the tree of life.',	'அவர் மனுஷனைத் துரத்திவிட்டு, ஜீவவிருட்சத்துக்குப் போகும் வழியைக் காவல்செய்ய ஏதேன் தோட்டத்துக்குக் கிழக்கே கேருபீன்களையும், வீசிக்கொண்டிருக்கிற சுடரொளி பட்டயத்தையும் வைத்தார்.  ',	1,	3,	24),
(81,	'And Adam knew Eve his wife; and she conceived, and bare Cain, and said, I have gotten a man from the LORD.',	'ஆதாம் தன் மனைவியாகிய ஏவாளை அறிந்தான்; அவள் கர்ப்பவதியாகி, காயீனைப் பெற்று, கர்த்தரால் ஒரு மனுஷனைப் பெற்றேன் என்றாள்.',	1,	4,	1),
(82,	'And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground.',	'பின்பு அவனுடைய சகோதரனாகிய ஆபேலைப் பெற்றாள்; ஆபேல் ஆடுகளை மேய்க்கிறவனானான், காயீன் நிலத்தைப் பயிரிடுகிறவனானான்.',	1,	4,	2),
(83,	'And in process of time it came to pass, that Cain brought of the fruit of the ground an offering unto the LORD.',	'சிலநாள் சென்றபின்பு, காயீன் நிலத்தின் கனிகளைக் கர்த்தருக்குக் காணிக்கையாகக் கொண்டுவந்தான்.',	1,	4,	3),
(84,	'And Abel, he also brought of the firstlings of his flock and of the fat thereof. And the LORD had respect unto Abel and to his offering:',	'ஆபேலும் தன் மந்தையின் தலையீற்றுகளிலும் அவைகளின் கொழுமையானவைகளிலும் சிலவற்றைக் கொண்டுவந்தான். ஆபேலையும் அவன் காணிக்கையையும் கர்த்தர் அங்கிகரித்தார்.',	1,	4,	4),
(85,	'But unto Cain and to his offering he had not respect. And Cain was very wroth, and his countenance fell.',	'காயீனையும் அவன் காணிக்கையையும் அவர் அங்கிகரிக்கவில்லை. அப்பொழுது காயீனுக்கு மிகவும் எரிச்சல் உண்டாகி, அவன் முகநாடி வேறுபட்டது.',	1,	4,	5),
(86,	'And the LORD said unto Cain, Why art thou wroth? and why is thy countenance fallen?',	'அப்பொழுது கர்த்தர் காயீனை நோக்கி: உனக்கு ஏன் எரிச்சல் உண்டாயிற்று? உன் முகநாடி ஏன் வேறுபட்டது?',	1,	4,	6),
(87,	'If thou doest well, shalt thou not be accepted? and if thou doest not well, sin lieth at the door. And unto thee shall be his desire, and thou shalt rule over him.',	'நீ நன்மைசெய்தால் மேன்மை இல்லையோ? நீ நன்மைசெய்யாதிருந்தால் பாவம் வாசற்படியில் படுத்திருக்கும்; அவன் ஆசை உன்னைப் பற்றியிருக்கும், நீ அவனை ஆண்டுகொள்ளுவாய் என்றார்.',	1,	4,	7),
(88,	'And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him.',	'காயீன் தன் சகோதரனாகிய ஆபேலோடே பேசினான்; அவர்கள் வயல்வெளியில் இருக்கும் சமயத்தில், காயீன் தன் சகோதரனாகிய ஆபேலுக்கு விரோதமாய் எழும்பி, அவனைக் கொலைசெய்தான்.',	1,	4,	8),
(89,	'And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother\'s keeper?',	'கர்த்தர் காயீனை நோக்கி: உன் சகோதரனாகிய ஆபேல் எங்கே என்றார்; அதற்கு அவன்: நான் அறியேன்; என் சகோதரனுக்கு நான் காவலாளியோ என்றான்.',	1,	4,	9),
(90,	'And he said, What hast thou done? the voice of thy brother\'s blood crieth unto me from the ground.',	'அதற்கு அவர்: என்ன செய்தாய்? உன் சகோதரனுடைய இரத்தத்தின் சத்தம் பூமியிலிருந்து என்னை நோக்கிக் கூப்பிடுகிறது.',	1,	4,	10),
(91,	'And now art thou cursed from the earth, which hath opened her mouth to receive thy brother\'s blood from thy hand;',	'இப்பொழுது உன் சகோதரனுடைய இரத்தத்தை உன் கையிலே வாங்கிக் கொள்ள தன் வாயைத் திறந்த இந்தப் பூமியில் நீ சபிக்கப்பட்டிருப்பாய்.',	1,	4,	11),
(92,	'When thou tillest the ground, it shall not henceforth yield unto thee her strength; a fugitive and a vagabond shalt thou be in the earth.',	'நீ நிலத்தைப் பயிரிடும்போது, அது தன் பலனை இனி உனக்குக் கொடாது; நீ பூமியில் நிலையற்று அலைகிறவனாயிருப்பாய் என்றார்.',	1,	4,	12),
(93,	'And Cain said unto the LORD, My punishment is greater than I can bear.',	'அப்பொழுது காயீன் கர்த்தரை நோக்கி: எனக்கு இட்ட தண்டனை என்னால் சகிக்கமுடியாது.',	1,	4,	13),
(94,	'Behold, thou hast driven me out this day from the face of the earth; and from thy face shall I be hid; and I shall be a fugitive and a vagabond in the earth; and it shall come to pass, that every one that findeth me shall slay me.',	'இன்று என்னை இந்தத் தேசத்திலிருந்து துரத்திவிடுகிறீர்; நான் உமது சமுகத்துக்கு விலகி மறைந்து, பூமியில் நிலையற்று அலைகிறவனாயிருப்பேன்; என்னைக் கண்டுபிடிக்கிறவன் எவனும் என்னைக் கொன்றுபோடுவானே என்றான்.',	1,	4,	14),
(95,	'And the LORD said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the LORD set a mark upon Cain, lest any finding him should kill him.',	'அப்பொழுது கர்த்தர் அவனை நோக்கி: காயீனைக் கொல்லுகிற எவன் மேலும் ஏழு பழி சுமரும் என்று சொல்லி; காயீனைக் கண்டுபிடிக்கிறவன் எவனும் அவனைக் கொன்றுபோடாதபடிக்குக் கர்த்தர் அவன்மேல் ஒரு அடையாளத்தைப் போட்டார்.',	1,	4,	15),
(96,	'And Cain went out from the presence of the LORD, and dwelt in the land of Nod, on the east of Eden.',	'அப்படியே காயீன் கர்த்தருடைய சந்நிதியைவிட்டுப் புறப்பட்டு, ஏதேனுக்குக் கிழக்கான நோத் என்னும் தேசத்தில் குடியிருந்தான்.',	1,	4,	16),
(97,	'And Cain knew his wife; and she conceived, and bare Enoch: and he builded a city, and called the name of the city, after the name of his son, Enoch.',	'காயீன் தன் மனைவியை அறிந்தான்; அவள் கர்ப்பவதியாகி, ஏனோக்கைப் பெற்றாள்; அப்பொழுது அவன் ஒரு பட்டணத்தைக் கட்டி, அந்தப் பட்டணத்துக்குத் தன் குமாரனாகிய ஏனோக்குடைய பேரை இட்டான்.',	1,	4,	17),
(98,	'And unto Enoch was born Irad: and Irad begat Mehujael: and Mehujael begat Methusael: and Methusael begat Lamech.',	'ஏனோக்குக்கு ஈராத் பிறந்தான்; ஈராத் மெகுயவேலைப் பெற்றான்; மெகுயவேல் மெத்தூசவேலைப் பெற்றான்; மெத்தூசவேல் லாமேக்கைப் பெற்றான்.',	1,	4,	18),
(99,	'And Lamech took unto him two wives: the name of the one was Adah, and the name of the other Zillah.',	'லாமேக்கு இரண்டு ஸ்திரீகளை விவாகம்பண்ணினான்; ஒருத்திக்கு ஆதாள் என்று பேர், மற்றொருத்திக்குச் சில்லாள் என்று பேர்.',	1,	4,	19),
(100,	'And Adah bare Jabal: he was the father of such as dwell in tents, and of such as have cattle.',	'ஆதாள் யாபாலைப் பெற்றாள்; அவன் கூடாரங்களில் வாசம்பண்ணுகிறவர்களுக்கும், மந்தை மேய்க்கிறவர்களுக்கும் தகப்பனானான்.',	1,	4,	20),
(101,	'And his brother\'s name was Jubal: he was the father of all such as handle the harp and organ.',	'அவன் சகோதரனுடைய பேர் யூபால்; அவன் கின்னரக்காரர், நாகசுரக்காரர் யாவருக்கும் தகப்பனானான்.',	1,	4,	21),
(102,	'And Zillah, she also bare Tubalcain, an instructer of every artificer in brass and iron: and the sister of Tubalcain was Naamah.',	'சில்லாளும் தூபால் காயீனைப் பெற்றாள்; அவன் பித்தளை, இரும்பு முதலியவற்றின் தொழிலாளர் யாவருக்கும் ஆசாரியனானான்; தூபால் காயீனுடைய சகோதரி நாமாள்.',	1,	4,	22),
(103,	'And Lamech said unto his wives, Adah and Zillah, Hear my voice; ye wives of Lamech, hearken unto my speech: for I have slain a man to my wounding, and a young man to my hurt.',	'லாமேக்கு தன் மனைவிகளைப் பார்த்து: ஆதாளே, சில்லாளே, நான் சொல்வதைக் கேளுங்கள்; லாமேக்கின் மனைவிகளே, என் சத்தத்துக்குச் செவி கொடுங்கள்; எனக்குக் காயமுண்டாக ஒரு மனுஷனைக் கொன்றேன்; எனக்குத் தழும்புண்டாக ஒரு வாலிபனைக் கொலைசெய்தேன்;',	1,	4,	23),
(104,	'If Cain shall be avenged sevenfold, truly Lamech seventy and sevenfold.',	'காயீனுக்காக ஏழு பழி சுமருமானால், லாமேக்குக்காக எழுபத்தேழு பழி சுமரும் என்றான்.',	1,	4,	24),
(105,	'And Adam knew his wife again; and she bare a son, and called his name Seth: For God, said she, hath appointed me another seed instead of Abel, whom Cain slew.',	'பின்னும் ஆதாம் தன் மனைவியை அறிந்தான்; அவள் ஒரு குமாரனைப் பெற்று: காயீன் கொலை செய்த ஆபேலுக்குப் பதிலாக, தேவன் எனக்கு வேறொரு புத்திரனைக் கொடுத்தார் என்று சொல்லி, அவனுக்குச் சேத் என்று பேரிட்டாள்.',	1,	4,	25),
(106,	'And to Seth, to him also there was born a son; and he called his name Enos: then began men to call upon the name of the LORD.',	'சேத்துக்கும் ஒரு குமாரன் பிறந்தான்; அவனுக்கு ஏனோஸ் என்று பேரிட்டான்; அப்பொழுது மனுஷர் கர்த்தருடைய நாமத்தைத் தொழுதுகொள்ள ஆரம்பித்தார்கள்.  ',	1,	4,	26),
(107,	'This is the book of the generations of Adam. In the day that God created man, in the likeness of God made he him;',	'ஆதாமின் வம்சவரலாறு: தேவன் மனுஷனைச் சிருஷ்டித்த நாளிலே அவனைத் தேவசாயலாக உண்டாக்கினார்.',	1,	5,	1),
(108,	'Male and female created he them; and blessed them, and called their name Adam, in the day when they were created.',	'அவர்களை ஆணும் பெண்ணுமாகச் சிருஷ்டித்து, அவர்களை ஆசீர்வதித்து, அவர்களைச் சிருஷ்டித்த நாளிலே அவர்களுக்கு மனுஷர் என்று பேரிட்டார்.',	1,	5,	2),
(109,	'And Adam lived an hundred and thirty years, and begat a son in his own likeness, and after his image; and called his name Seth:',	'ஆதாம் நூற்று முப்பது வயதானபோது, தன் சாயலாகத் தன் ரூபத்தின்படியே ஒரு குமாரனைப் பெற்று, அவனுக்குச் சேத் என்று பேரிட்டான்.',	1,	5,	3),
(110,	'And the days of Adam after he had begotten Seth were eight hundred years: and he begat sons and daughters:',	'ஆதாம் சேத்தைப் பெற்றபின், எண்ணூறு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	4),
(111,	'And all the days that Adam lived were nine hundred and thirty years: and he died.',	'ஆதாம் உயிரோடிருந்த நாளெல்லாம் தொளாயிரத்து முப்பது வருஷம்; அவன் மரித்தான்.',	1,	5,	5),
(112,	'And Seth lived an hundred and five years, and begat Enos:',	'சேத் நூற்றைந்து வயதானபோது, ஏனோசைப் பெற்றான்.',	1,	5,	6),
(113,	'And Seth lived after he begat Enos eight hundred and seven years, and begat sons and daughters:',	'சேத் ஏனோசைப் பெற்றபின், எண்ணூற்றேழு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	7),
(114,	'And all the days of Seth were nine hundred and twelve years: and he died.',	'சேத்துடைய நாளெல்லாம் தொளாயிரத்துப் பன்னிரண்டு வருஷம்; அவன் மரித்தான்.',	1,	5,	8),
(115,	'And Enos lived ninety years, and begat Cainan:',	'ஏனோஸ் தொண்ணூறு வயதானபோது, கேனானைப் பெற்றான்.',	1,	5,	9),
(116,	'And Enos lived after he begat Cainan eight hundred and fifteen years, and begat sons and daughters:',	'ஏனோஸ் கேனானைப் பெற்றபின், எண்ணூற்றுப் பதினைந்து வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	10),
(117,	'And all the days of Enos were nine hundred and five years: and he died.',	'ஏனோசுடைய நாளெல்லாம் தொளாயிரத்து ஐந்து வருஷம், அவன் மரித்தான்.',	1,	5,	11),
(118,	'And Cainan lived seventy years and begat Mahalaleel:',	'கேனான் எழுபது வயதானபோது, மகலாலெயேலைப் பெற்றான்.',	1,	5,	12),
(119,	'And Cainan lived after he begat Mahalaleel eight hundred and forty years, and begat sons and daughters:',	'கேனான் மகலாலெயேலைப் பெற்றபின், எண்ணூற்று நாற்பது வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	13),
(120,	'And all the days of Cainan were nine hundred and ten years: and he died.',	'கேனானுடைய நாளெல்லாம் தொளாயிரத்துப் பத்து வருஷம்; அவன் மரித்தான்.',	1,	5,	14),
(121,	'And Mahalaleel lived sixty and five years, and begat Jared:',	'மகலாலெயேல் அறுபத்தைந்து வயதானபோது, யாரேதைப் பெற்றான்.',	1,	5,	15),
(122,	'And Mahalaleel lived after he begat Jared eight hundred and thirty years, and begat sons and daughters:',	'மகலாலெயேல் யாரேதைப் பெற்றபின், எண்ணூற்று முப்பது வருஷம் உயிரோடிருந்து, குமாரரையும், குமாரத்திகளையும் பெற்றான்.',	1,	5,	16),
(123,	'And all the days of Mahalaleel were eight hundred ninety and five years: and he died.',	'மகலாலெயேலுடைய நாளெல்லாம் எண்ணூற்றுத் தொண்ணூற்று ஐந்து வருஷம்; அவன் மரித்தான்.',	1,	5,	17),
(124,	'And Jared lived an hundred sixty and two years, and he begat Enoch:',	'யாரேத் நூற்று அறுபத்திரண்டு வயதானபோது, ஏனோக்கைப் பெற்றான்.',	1,	5,	18),
(125,	'And Jared lived after he begat Enoch eight hundred years, and begat sons and daughters:',	'யாரேத் ஏனோக்கைப் பெற்றபின், எண்ணூறு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	19),
(126,	'And all the days of Jared were nine hundred sixty and two years: and he died.',	'யாரேதுடைய நாளெல்லாம் தொளாயிரத்து அறுபத்திரண்டு வருஷம்; அவன் மரித்தான்.',	1,	5,	20),
(127,	'And Enoch lived sixty and five years, and begat Methuselah:',	'ஏனோக்கு அறுபத்தைந்து வயதானபோது, மெத்தூசலாவைப் பெற்றான்.',	1,	5,	21),
(128,	'And Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters:',	'ஏனோக்கு மெத்தூசலாவைப் பெற்றபின், முந்நூறு வருஷம் தேவனோடே சஞ்சரித்துக்கொண்டிருந்து, குமாரரையும், குமாரத்திகளையும் பெற்றான்.',	1,	5,	22),
(129,	'And all the days of Enoch were three hundred sixty and five years:',	'ஏனோக்குடைய நாளெல்லாம் முந்நூற்று அறுபத்தைந்து வருஷம்.',	1,	5,	23),
(130,	'And Enoch walked with God: and he was not; for God took him.',	'ஏனோக்கு தேவனோடே சஞ்சரித்துக்கொண்டிருக்கையில், காணப்படாமற்போனான்; தேவன் அவனை எடுத்துக்கொண்டார்.',	1,	5,	24),
(131,	'And Methuselah lived an hundred eighty and seven years, and begat Lamech.',	'மெத்தூசலா நூற்றெண்பத்தேழு வயதானபோது, லாமேக்கைப் பெற்றான்.',	1,	5,	25),
(132,	'And Methuselah lived after he begat Lamech seven hundred eighty and two years, and begat sons and daughters:',	'மெத்தூசலா லாமேக்கைப் பெற்றபின், எழுநூற்று எண்பத்திரண்டு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	5,	26),
(133,	'And all the days of Methuselah were nine hundred sixty and nine years: and he died.',	'மெத்தூசலாவுடைய நாளெல்லாம் தொளாயிரத்து அறுபத்தொன்பது வருஷம்; அவன் மரித்தான்.',	1,	5,	27),
(134,	'And Lamech lived an hundred eighty and two years, and begat a son:',	'லாமேக்கு நூற்றெண்பத்திரண்டு வயதானபோது, ஒரு குமாரனைப் பெற்று,',	1,	5,	28),
(135,	'And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which the LORD hath cursed.',	'கர்த்தர் சபித்த பூமியிலே நமக்கு உண்டான வேலையிலும், நம்முடைய கைகளின் பிரயாசத்திலும், இவன் நம்மைத் தேற்றுவான் என்று சொல்லி, அவனுக்கு நோவா என்று பேரிட்டான்.',	1,	5,	29),
(136,	'And Lamech lived after he begat Noah five hundred ninety and five years, and begat sons and daughters:',	'லாமேக்கு நோவாவைப் பெற்றபின், ஐந்நூற்றுத் தொண்ணூற்று ஐந்து வருஷம் உயிரோடிருந்து, குமாரரையும், குமாரத்திகளையும் பெற்றான்.',	1,	5,	30),
(137,	'And all the days of Lamech were seven hundred seventy and seven years: and he died.',	'லாமேக்குடைய நாளெல்லாம் எழுநூற்று எழுபத்தேழு வருஷம்; அவன் மரித்தான்.',	1,	5,	31),
(138,	'And Noah was five hundred years old: and Noah begat Shem, Ham, and Japheth.',	'நோவா ஐந்நூறு வயதானபோது, சேம், காம், யாப்பேத் என்பவர்களைப் பெற்றான்.  ',	1,	5,	32),
(139,	'And it came to pass, when men began to multiply on the face of the earth, and daughters were born unto them,',	'மனுஷர் பூமியின்மேல் பெருகத்துவக்கி, அவர்களுக்குக் குமாரத்திகள் பிறந்தபோது:',	1,	6,	1),
(140,	'That the sons of God saw the daughters of men that they were fair; and they took them wives of all which they chose.',	'தேவகுமாரர் மனுஷகுமாரத்திகளை அதிக செளந்தரியமுள்ளவர்களென்று கண்டு, அவர்களுக்குள்ளே தங்களுக்குப் பெண்களைத் தெரிந்துகொண்டார்கள்.',	1,	6,	2),
(141,	'And the LORD said, My spirit shall not always strive with man, for that he also is flesh: yet his days shall be an hundred and twenty years.',	'அப்பொழுது கர்த்தர்: என் ஆவி என்றைக்கும் மனுஷனோடே போராடுவதில்லை; அவன் மாம்சந்தானே, அவன் இருக்கப்போகிற நாட்கள் நூற்றிருபது வருஷம் என்றார்.',	1,	6,	3),
(142,	'There were giants in the earth in those days; and also after that, when the sons of God came in unto the daughters of men, and they bare children to them, the same became mighty men which were of old, men of renown.',	'அந்நாட்களில் இராட்சதர் பூமியிலே இருந்தார்கள்; பின்பு தேவகுமாரர் மனுஷகுமாரத்திகளோடே கூடுகிறதினால், இவர்கள் அவர்களுக்குப் பிள்ளைகளைப் பெற்றபோது, இவர்களும் பூர்வத்தில் பேர்பெற்ற மனுஷராகிய பலவான்களானார்கள்.',	1,	6,	4),
(143,	'And God saw that the wickedness of man was great in the earth, and that every imagination of the thoughts of his heart was only evil continually.',	'மனுஷனுடைய அக்கிரமம் பூமியிலே பெருகினது என்றும், அவன் இருதயத்து நினைவுகளின் தோற்றமெல்லாம் நித்தமும் பொல்லாததே என்றும், கர்த்தர் கண்டு,',	1,	6,	5),
(144,	'And it repented the LORD that he had made man on the earth, and it grieved him at his heart.',	'தாம் பூமியிலே மனுஷனை உண்டாக்கினதற்காகக் கர்த்தர் மனஸ்தாபப்பட்டார்; அது அவர் இருதயத்துக்கு விசனமாயிருந்தது.',	1,	6,	6),
(145,	'And the LORD said, I will destroy man whom I have created from the face of the earth; both man, and beast, and the creeping thing, and the fowls of the air; for it repenteth me that I have made them.',	'அப்பொழுது கர்த்தர்: நான் சிருஷ்டித்த மனுஷனைப் பூமியின்மேல் வைக்காமல், மனுஷன் முதற்கொண்டு, மிருகங்கள் ஊரும் பிராணிகள் ஆகாயத்துப் பறவைகள் பரியந்தமும் உண்டாயிருக்கிறவைகளை நிக்கிரகம்பண்ணுவேன்; நான் அவர்களை உண்டாக்கினது எனக்கு மனஸ்தாபமாயிருக்கிறது என்றார்.',	1,	6,	7),
(146,	'But Noah found grace in the eyes of the LORD.',	'நோவாவுக்கோ, கர்த்தருடைய கண்களில் கிருபை கிடைத்தது.',	1,	6,	8),
(147,	'These are the generations of Noah: Noah was a just man and perfect in his generations, and Noah walked with God.',	'நோவாவின் வம்சவரலாறு: நோவா தன் காலத்தில் இருந்தவர்களுக்குள்ளே நீதிமானும் உத்தமனுமாயிருந்தான்; நோவா தேவனோடே சஞ்சரித்துக்கொண்டிருந்தான்.',	1,	6,	9),
(148,	'And Noah begat three sons, Shem, Ham, and Japheth.',	'நோவா சேம், காம், யாப்பேத் என்னும் மூன்று குமாரரைப் பெற்றான்.',	1,	6,	10),
(149,	'The earth also was corrupt before God, and the earth was filled with violence.',	'பூமியானது தேவனுக்கு முன்பாகச் சீர்கெட்டதாயிருந்தது; பூமி கொடுமையினால் நிறைந்திருந்தது.',	1,	6,	11),
(150,	'And God looked upon the earth, and, behold, it was corrupt; for all flesh had corrupted his way upon the earth.',	'தேவன் பூமியைப் பார்த்தார்; இதோ அது சீர்கெட்டதாயிருந்தது; மாம்சமான யாவரும் பூமியின்மேல் தங்கள் வழியைக் கெடுத்துக்கொண்டிருந்தார்கள்.',	1,	6,	12),
(151,	'And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth.',	'அப்பொழுது தேவன் நோவாவை நோக்கி: மாம்சமான யாவரின் முடிவும் எனக்கு முன்பாக வந்தது; அவர்களாலே பூமி கொடுமையினால் நிறைந்தது; நான் அவர்களைப் பூமியோடுங்கூட அழித்துப்போடுவேன்.',	1,	6,	13),
(152,	'Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch.',	'நீ கொப்பேர் மரத்தால் உனக்கு ஒரு பேழையை உண்டாக்கு; அந்தப் பேழையிலே அறைகளை உண்டுபண்ணி, அதை உள்ளும் புறம்புமாகக் கீல்பூசு.',	1,	6,	14),
(153,	'And this is the fashion which thou shalt make it of: The length of the ark shall be three hundred cubits, the breadth of it fifty cubits, and the height of it thirty cubits.',	'நீ அதைப் பண்ணவேண்டிய விதம் என்னவென்றால், பேழையின் நீளம் முந்நூறு முழமும், அதின் அகலம் ஐம்பது முழமும், அதின் உயரம் முப்பது முழமுமாய் இருக்கவேண்டும்.',	1,	6,	15),
(154,	'A window shalt thou make to the ark, and in a cubit shalt thou finish it above; and the door of the ark shalt thou set in the side thereof; with lower, second, and third stories shalt thou make it.',	'நீ பேழைக்கு ஓர் ஜன்னலை உண்டுபண்ணி, மேல்தட்டுக்கு ஒரு முழத் தாழ்த்தியிலே அதைச் செய்துமுடித்து, பேழையின் கதவை அதின் பக்கத்தில் வைத்து, கீழ் அறைகளையும், இரண்டாம் தட்டின் அறைகளையும், மூன்றாம் தட்டின் அறைகளையும் பண்ணவேண்டும்.',	1,	6,	16),
(155,	'And, behold, I, even I, do bring a flood of waters upon the earth, to destroy all flesh, wherein is the breath of life, from under heaven; and every thing that is in the earth shall die.',	'வானத்தின்கீழே ஜீவசுவாசமுள்ள சகல மாம்ச ஜந்துக்களையும் அழிக்க நான் பூமியின்மேல் ஜலப்பிரளயத்தை வரப்பண்ணுவேன்; பூமியிலுள்ள யாவும் மாண்டுபோம்.',	1,	6,	17),
(156,	'But with thee will I establish my covenant; and thou shalt come into the ark, thou, and thy sons, and thy wife, and thy sons\' wives with thee.',	'ஆனாலும் உன்னுடனே என் உடன்படிக்கையை ஏற்படுத்துவேன்; நீயும், உன்னோடேகூட உன் குமாரரும், உன் மனைவியும், உன் குமாரரின் மனைவிகளும், பேழைக்குள் பிரவேசியுங்கள்.',	1,	6,	18),
(157,	'And of every living thing of all flesh, two of every sort shalt thou bring into the ark, to keep them alive with thee; they shall be male and female.',	'சகலவித மாம்சமான ஜீவன்களிலும் ஆணும் பெண்ணுமாக வகை ஒன்றுக்கு ஒவ்வொரு ஜோடு உன்னுடன் உயிரோடே காக்கப்படுவதற்கு, பேழைக்குள்ளே சேர்த்துக்கொள்.',	1,	6,	19),
(158,	'Of fowls after their kind, and of cattle after their kind, of every creeping thing of the earth after his kind, two of every sort shall come unto thee, to keep them alive.',	'ஜாதிஜாதியான பறவைகளிலும், ஜாதிஜாதியான மிருகங்களிலும், பூமியிலுள்ள சகல ஜாதிஜாதியான ஊரும் பிராணிகளிலும், வகை ஒன்றுக்கு ஒவ்வொரு ஜோடு உயிரோடே காக்கப்படுவதற்கு உன்னிடத்திலே வரக்கடவது.',	1,	6,	20),
(159,	'And take thou unto thee of all food that is eaten, and thou shalt gather it to thee; and it shall be for food for thee, and for them.',	'உனக்கும் அவைகளுக்கும் ஆகாரமாகச் சகலவித போஜனபதார்த்தங்களையும் சேர்த்து, உன்னிடத்தில் வைத்துக்கொள் என்றார்.',	1,	6,	21),
(160,	'Thus did Noah; according to all that God commanded him, so did he.',	'நோவா அப்படியே செய்தான்; தேவன் தனக்குக் கட்டளையிட்டபடியெல்லாம் அவன் செய்து முடித்தான்.  ',	1,	6,	22),
(161,	'And the LORD said unto Noah, Come thou and all thy house into the ark; for thee have I seen righteous before me in this generation.',	'கர்த்தர் நோவாவை நோக்கி: நீயும் உன் வீட்டார் அனைவரும் பேழைக்குள் பிரவேசியுங்கள்; இந்தச் சந்ததியில் உன்னை எனக்கு முன்பாக நீதிமானாகக் கண்டேன்.',	1,	7,	1),
(162,	'Of every clean beast thou shalt take to thee by sevens, the male and his female: and of beasts that are not clean by two, the male and his female.',	'பூமியின்மீதெங்கும் வித்தை உயிரோடே காக்கும்பொருட்டு, நீ சுத்தமான சகல மிருகங்களிலும், ஆணும் பெண்ணுமாக எவ்வேழு ஜோடும், சுத்தமில்லாத மிருகங்களில் ஆணும் பெண்ணுமாக ஒவ்வொரு ஜோடும்,',	1,	7,	2),
(163,	'Of fowls also of the air by sevens, the male and the female; to keep seed alive upon the face of all the earth.',	'ஆகாயத்துப் பறவைகளிலும், சேவலும் பேடுமாக எவ்வேழு ஜோடும் உன்னிடத்தில் சேர்த்துக்கொள்.',	1,	7,	3),
(164,	'For yet seven days, and I will cause it to rain upon the earth forty days and forty nights; and every living substance that I have made will I destroy from off the face of the earth.',	'இன்னும் ஏழுநாள் சென்றபின்பு, நாற்பதுநாள் இரவும் பகலும் பூமியின்மேல் மழையை வருஷிக்கப்பண்ணி, நான் உண்டாக்கின ஜீவஜந்துக்கள் அனைத்தையும் பூமியின்மேல் இராதபடிக்கு நிக்கிரகம்பண்ணுவேன் என்றார்.',	1,	7,	4),
(165,	'And Noah did according unto all that the LORD commanded him.',	'நோவா தனக்குக் கர்த்தர் கட்டளையிட்டபடியெல்லாம் செய்தான்.',	1,	7,	5),
(166,	'And Noah was six hundred years old when the flood of waters was upon the earth.',	'ஜலப்பிரளயம் பூமியின்மேல் உண்டானபோது, நோவா அறுநூறு வயதாயிருந்தான்.',	1,	7,	6),
(167,	'And Noah went in, and his sons, and his wife, and his sons\' wives with him, into the ark, because of the waters of the flood.',	'ஜலப்பிரளயத்துக்குத் தப்பும்படி நோவாவும் அவனுடனேகூட அவன் குமாரரும், அவன் மனைவியும், அவன் குமாரரின் மனைவிகளும் பேழைக்குள் பிரவேசித்தார்கள்.',	1,	7,	7),
(168,	'Of clean beasts, and of beasts that are not clean, and of fowls, and of every thing that creepeth upon the earth,',	'தேவன் நோவாவுக்குக் கட்டளையிட்டபடியே, சுத்தமான மிருகங்களிலும், சுத்தமல்லாத மிருகங்களிலும், பூமியின்மேல் ஊரும் பிராணிகள் எல்லாவற்றிலும்,',	1,	7,	8),
(169,	'There went in two and two unto Noah into the ark, the male and the female, as God had commanded Noah.',	'ஆணும் பெண்ணும் ஜோடுஜோடாக நோவாவிடத்தில் பேழைக்குட்பட்டன.',	1,	7,	9),
(170,	'And it came to pass after seven days, that the waters of the flood were upon the earth.',	'ஏழுநாள் சென்றபின்பு பூமியின்மேல் ஜலப்பிரளயம் உண்டாயிற்று.',	1,	7,	10),
(171,	'In the six hundredth year of Noah\'s life, in the second month, the seventeenth day of the month, the same day were all the fountains of the great deep broken up, and the windows of heaven were opened.',	'நோவாவுக்கு அறுநூறாம் வயதாகும் வருஷம் இரண்டாம் மாதம் பதினேழாம் தேதியாகிய அந்நாளிலே, மகா ஆழத்தின் ஊற்றுக்கண்களெல்லாம் பிளந்தன; வானத்தின் மதகுகளும் திறவுண்டன.',	1,	7,	11),
(172,	'And the rain was upon the earth forty days and forty nights.',	'நாற்பதுநாள் இரவும் பகலும் பூமியின்மேல் பெருமழை பெய்தது.',	1,	7,	12),
(173,	'In the selfsame day entered Noah, and Shem, and Ham, and Japheth, the sons of Noah, and Noah\'s wife, and the three wives of his sons with them, into the ark;',	'அன்றைத்தினமே நோவாவும், நோவாவின் குமாரராகிய சேமும் காமும் யாப்பேத்தும், அவர்களுடனேகூட நோவாவின் மனைவியும், அவன் குமாரரின் மூன்று மனைவிகளும், பேழைக்குள் பிரவேசித்தார்கள்.',	1,	7,	13),
(174,	'They, and every beast after his kind, and all the cattle after their kind, and every creeping thing that creepeth upon the earth after his kind, and every fowl after his kind, every bird of every sort.',	'அவர்களோடு ஜாதிஜாதியான சகலவிதக் காட்டு மிருகங்களும், ஜாதிஜாதியான சகலவித நாட்டு மிருகங்களும், பூமியின்மேல் ஊருகிற ஜாதிஜாதியான சகலவித ஊரும் பிராணிகளும், ஜாதிஜாதியான சகலவிதப் பறவைகளும், பலவிதமான சிறகுகளுள்ள சகலவிதப் பட்சிகளும் பிரவேசித்தன.',	1,	7,	14),
(175,	'And they went in unto Noah into the ark, two and two of all flesh, wherein is the breath of life.',	'இப்படியே ஜீவசுவாசமுள்ள மாம்ச ஜந்துக்களெல்லாம் ஜோடுஜோடாக நோவாவிடத்தில் பேழைக்குள் பிரவேசித்தன.',	1,	7,	15),
(176,	'And they that went in, went in male and female of all flesh, as God had commanded him: and the LORD shut him in.',	'தேவன் அவனுக்குக் கட்டளையிட்டபடியே, ஆணும் பெண்ணுமாக சகலவித மாம்சஜந்துக்களும் உள்ளே பிரவேசித்தன; அப்பொழுது கர்த்தர் அவனை உள்ளே விட்டுக் கதவை அடைத்தார்.',	1,	7,	16),
(177,	'And the flood was forty days upon the earth; and the waters increased, and bare up the ark, and it was lift up above the earth.',	'ஜலப்பிரளயம் நாற்பது நாள் பூமியின்மேல் உண்டானபோது, ஜலம் பெருகி, பேழையைக் கிளம்பப்பண்ணிற்று; அது பூமிக்குமேல் மிதந்தது.',	1,	7,	17),
(178,	'And the waters prevailed, and were increased greatly upon the earth; and the ark went upon the face of the waters.',	'ஜலம் பெருவெள்ளமாகி, பூமியின்மேல் மிகவும் பெருகிற்று; பேழையானது ஜலத்தின்மேல் மிதந்துகொண்டிருந்தது.',	1,	7,	18),
(179,	'And the waters prevailed exceedingly upon the earth; and all the high hills, that were under the whole heaven, were covered.',	'ஜலம் பூமியின்மேல் மிகவும் அதிகமாய்ப் பெருகினதினால், வானத்தின்கீழ் எங்குமுள்ள உயர்ந்த மலைகளெல்லாம் மூடப்பட்டன.',	1,	7,	19),
(180,	'Fifteen cubits upward did the waters prevail; and the mountains were covered.',	'மூடப்பட்ட மலைகளுக்கு மேலாய்ப் பதினைந்துமுழ உயரத்திற்கு ஜலம் பெருகிற்று.',	1,	7,	20),
(181,	'And all flesh died that moved upon the earth, both of fowl, and of cattle, and of beast, and of every creeping thing that creepeth upon the earth, and every man:',	'அப்பொழுது மாம்சஜந்துக்களாகிய பறவைகளும், நாட்டு மிருகங்களும், காட்டு மிருகங்களும், பூமியின்மேல் ஊரும் பிராணிகள் யாவும், எல்லா நரஜீவன்களும், பூமியின்மேல் சஞ்சரிக்கிறவைகள் யாவும் மாண்டன.',	1,	7,	21),
(182,	'All in whose nostrils was the breath of life, of all that was in the dry land, died.',	'வெட்டாந்தரையில் உண்டான எல்லாவற்றிலும் நாசியிலே ஜீவசுவாசமுள்ளவைகள் எல்லாம் மாண்டுபோயின.',	1,	7,	22),
(183,	'And every living substance was destroyed which was upon the face of the ground, both man, and cattle, and the creeping things, and the fowl of the heaven; and they were destroyed from the earth: and Noah only remained alive, and they that were with him in the ark.',	'மனுஷர் முதல், மிருகங்கள், ஊரும் பிராணிகள், ஆகாயத்துப் பறவைகள் பரியந்தமும், பூமியின்மேல் இருந்த உயிருள்ள வஸ்துக்கள் யாவும் அழிந்து, அவைகள் பூமியில் இராதபடிக்கு நிக்கிரகமாயின; நோவாவும் அவனோடே பேழையிலிருந்த உயிர்களும் மாத்திரம் காக்கப்பட்டன.',	1,	7,	23),
(184,	'And the waters prevailed upon the earth an hundred and fifty days.',	'ஜலம் பூமியின்மேல் நூற்றைம்பது நாள் மிகவும் பிரவாகித்துக்கொண்டிருந்தது.  ',	1,	7,	24),
(185,	'And God remembered Noah, and every living thing, and all the cattle that was with him in the ark: and God made a wind to pass over the earth, and the waters assuaged;',	'தேவன் நோவாவையும், அவனுடனே பேழையிலிருந்த சகல காட்டு மிருகங்களையும், சகல நாட்டு மிருகங்களையும் நினைத்தருளினார்; தேவன் பூமியின்மேல் காற்றை வீசப்பண்ணினார், அப்பொழுது ஜலம் அமர்ந்தது.',	1,	8,	1),
(186,	'The fountains also of the deep and the windows of heaven were stopped, and the rain from heaven was restrained;',	'ஆழத்தின் ஊற்றுக்கண்களும், வானத்தின் மதகுகளும் அடைபட்டன; வானத்து மழையும் நின்றுபோயிற்று.',	1,	8,	2),
(187,	'And the waters returned from off the earth continually: and after the end of the hundred and fifty days the waters were abated.',	'ஜலம் பூமியிலிருந்து நாளுக்குநாள் வற்றிக்கொண்டே வந்தது; நூற்றைம்பது நாளுக்குப்பின்பு ஜலம் வடிந்தது.',	1,	8,	3),
(188,	'And the ark rested in the seventh month, on the seventeenth day of the month, upon the mountains of Ararat.',	'ஏழாம் மாதம் பதினேழாம் தேதியிலே பேழை அரராத் என்னும் மலைகளின்மேல் தங்கிற்று.',	1,	8,	4),
(189,	'And the waters decreased continually until the tenth month: in the tenth month, on the first day of the month, were the tops of the mountains seen.',	'பத்தாம் மாதம் மட்டும் ஜலம் வடிந்துகொண்டே வந்தது; பத்தாம் மாதம் முதல் தேதியிலே மலைச்சிகரங்கள் காணப்பட்டன.',	1,	8,	5),
(190,	'And it came to pass at the end of forty days, that Noah opened the window of the ark which he had made:',	'நாற்பது நாள் சென்றபின், நோவா தான் பேழையில் செய்திருந்த ஜன்னலைத் திறந்து,',	1,	8,	6),
(191,	'And he sent forth a raven, which went forth to and fro, until the waters were dried up from off the earth.',	'ஒரு காகத்தை வெளியே விட்டான்; அது புறப்பட்டுப் பூமியின்மேல் இருந்த ஜலம் வற்றிப்போகும்வரைக்கும் போகிறதும் வருகிறதுமாய் இருந்தது.',	1,	8,	7),
(192,	'Also he sent forth a dove from him, to see if the waters were abated from off the face of the ground;',	'பின்பு பூமியின்மேல் ஜலம் குறைந்து போயிற்றோ என்று அறியும்படி, ஒரு புறாவைத் தன்னிடத்திலிருந்து வெளியே விட்டான்.',	1,	8,	8),
(193,	'But the dove found no rest for the sole of her foot, and she returned unto him into the ark, for the waters were on the face of the whole earth: then he put forth his hand, and took her, and pulled her in unto him into the ark.',	'பூமியின்மீதெங்கும் ஜலம் இருந்தபடியால், அந்தப் புறா தன் உள்ளங்கால் வைத்து இளைப்பாற இடம் காணாமல், திரும்பிப் பேழையிலே அவனிடத்தில் வந்தது; அவன் தன் கையை நீட்டி அதைப்பிடித்துத் தன்னிடமாகப் பேழைக்குள் சேர்த்துக்கொண்டான்.',	1,	8,	9),
(194,	'And he stayed yet other seven days; and again he sent forth the dove out of the ark;',	'பின்னும் ஏழு நாள் பொறுத்து, மறுபடியும் புறாவைப் பேழையிலிருந்து வெளியே விட்டான்.',	1,	8,	10),
(195,	'And the dove came in to him in the evening; and, lo, in her mouth was an olive leaf pluckt off: so Noah knew that the waters were abated from off the earth.',	'அந்தப் புறா சாயங்காலத்தில் அவனிடத்தில் வந்து சேர்ந்தது; இதோ, அது கொத்திக்கொண்டுவந்த ஒரு ஒலிவமரத்தின் இலை அதின் வாயில் இருந்தது; அதினாலே நோவா பூமியின்மேல் ஜலம் குறைந்துபோயிற்று என்று அறிந்தான்.',	1,	8,	11),
(196,	'And he stayed yet other seven days; and sent forth the dove; which returned not again unto him any more.',	'பின்னும் ஏழு நாள் பொறுத்து, அவன் புறாவை வெளியே விட்டான்; அது அவனிடத்திற்குத் திரும்பி வரவில்லை.',	1,	8,	12),
(197,	'And it came to pass in the six hundredth and first year, in the first month, the first day of the month, the waters were dried up from off the earth: and Noah removed the covering of the ark, and looked, and, behold, the face of the ground was dry.',	'அவனுக்கு அறுநூற்றொரு வயதாகும் வருஷத்தில், முதல் மாதம் முதல் தேதியிலே பூமியின்மேல் இருந்த ஜலம் வற்றிப்போயிற்று; நோவா பேழையின் மேல்தட்டை எடுத்துப்பார்த்தான்; பூமியின்மேல் ஜலம் இல்லாதிருந்தது.',	1,	8,	13),
(198,	'And in the second month, on the seven and twentieth day of the month, was the earth dried.',	'இரண்டாம் மாதம் இருபத்தேழாம் தேதியிலே பூமி காய்ந்திருந்தது.',	1,	8,	14),
(199,	'And God spake unto Noah, saying,',	'அப்பொழுது தேவன் நோவாவை நோக்கி:',	1,	8,	15),
(200,	'Go forth of the ark, thou, and thy wife, and thy sons, and thy sons\' wives with thee.',	'நீயும், உன்னோடேகூட உன் மனைவியும், உன் குமாரரும், உன் குமாரரின் மனைவிகளும் பேழையை விட்டுப் புறப்படுங்கள்.',	1,	8,	16),
(201,	'Bring forth with thee every living thing that is with thee, of all flesh, both of fowl, and of cattle, and of every creeping thing that creepeth upon the earth; that they may breed abundantly in the earth, and be fruitful, and multiply upon the earth.',	'உன்னிடத்தில் இருக்கிற சகலவித மாம்சஜந்துக்களாகிய பறவைகளையும், மிருகங்களையும், பூமியின்மேல் ஊருகிற சகல பிராணிகளையும் உன்னோடே வெளியே வரவிடு; அவைகள் பூமியிலே திரளாய் வர்த்தித்து, பூமியின்மேல் பலுகிப் பெருகக்கடவது என்றார்.',	1,	8,	17),
(202,	'And Noah went forth, and his sons, and his wife, and his sons\' wives with him:',	'அப்பொழுது நோவாவும், அவன் குமாரரும், அவன் மனைவியும், அவன் குமாரரின் மனைவிகளும் புறப்பட்டு வந்தார்கள்.',	1,	8,	18),
(203,	'Every beast, every creeping thing, and every fowl, and whatsoever creepeth upon the earth, after their kinds, went forth out of the ark.',	'பூமியின்மேல் நடமாடுகிற சகல மிருகங்களும், ஊருகிற சகல பிராணிகளும், சகல பறவைகளும் ஜாதிஜாதியாய்ப் பேழையிலிருந்து புறப்பட்டு வந்தன.',	1,	8,	19),
(204,	'And Noah builded an altar unto the LORD; and took of every clean beast, and of every clean fowl, and offered burnt offerings on the altar.',	'அப்பொழுது நோவா கர்த்தருக்கு ஒரு பலிபீடம் கட்டி, சுத்தமான சகல மிருகங்களிலும், சுத்தமான சகல பறவைகளிலும் சிலவற்றைத் தெரிந்துகொண்டு, அவைகளைப் பலிபீடத்தின்மேல் தகனபலிகளாகப் பலியிட்டான்.',	1,	8,	20),
(205,	'And the LORD smelled a sweet savour; and the LORD said in his heart, I will not again curse the ground any more for man\'s sake; for the imagination of man\'s heart is evil from his youth; neither will I again smite any more every thing living, as I have done.',	'சுகந்த வாசனையைக் கர்த்தர் முகர்ந்தார். அப்பொழுது கர்த்தர்: இனி நான் மனுஷன் நிமித்தம் பூமியைச் சபிப்பதில்லை; மனுஷனுடைய இருதயத்தின் நினைவுகள் அவன் சிறுவயது தொடங்கி பொல்லாததாயிருக்கிறது; நான் இப்பொழுது செய்ததுபோல, இனி சகல ஜீவன்களையும் சங்கரிப்பதில்லை.',	1,	8,	21),
(206,	'While the earth remaineth, seedtime and harvest, and cold and heat, and summer and winter, and day and night shall not cease.',	'பூமியுள்ள நாளளவும் விதைப்பும் அறுப்பும், சீதளமும் உஷ்ணமும், கோடைகாலமும் மாரிகாலமும், பகலும் இரவும் ஒழிவதில்லை என்று தம்முடைய உள்ளத்தில் சொன்னார்.  ',	1,	8,	22),
(207,	'And God blessed Noah and his sons, and said unto them, Be fruitful, and multiply, and replenish the earth.',	'பின்பு தேவன் நோவாவையும், அவன் குமாரரையும் ஆசீர்வதித்து: நீங்கள் பலுகிப் பெருகி, பூமியை நிரப்புங்கள்.',	1,	9,	1),
(208,	'And the fear of you and the dread of you shall be upon every beast of the earth, and upon every fowl of the air, upon all that moveth upon the earth, and upon all the fishes of the sea; into your hand are they delivered.',	'உங்களைப்பற்றிய பயமும் அச்சமும் பூமியிலுள்ள சகல மிருகங்களுக்கும், ஆகாயத்திலுள்ள சகல பறவைகளுக்கும் உண்டாயிருக்கும்; பூமியிலே நடமாடுகிற யாவும், சமுத்திரத்தின் மச்சங்கள் யாவும், உங்களுக்குக் கையளிக்கப்பட்டன.',	1,	9,	2),
(209,	'Every moving thing that liveth shall be meat for you; even as the green herb have I given you all things.',	'நடமாடுகிற ஜீவஜந்துக்கள் யாவும், உங்களுக்கு ஆகாரமாய் இருப்பதாக; பசும் பூண்டுகளை உங்களுக்குத் தந்தது போல, அவைகள் எல்லாவற்றையும் உங்களுக்குத் தந்தேன்.',	1,	9,	3),
(210,	'But flesh with the life thereof, which is the blood thereof, shall ye not eat.',	'மாம்சத்தை அதின் உயிராகிய இரத்தத்தோடே புசிக்கவேண்டாம்.',	1,	9,	4),
(211,	'And surely your blood of your lives will I require; at the hand of every beast will I require it, and at the hand of man; at the hand of every man\'s brother will I require the life of man.',	'உங்களுக்கு உயிராயிருக்கிற உங்கள் இரத்தத்திற்காகப் பழிவாங்குவேன்; சகல ஜீவஜந்துக்களிடத்திலும் மனுஷனிடத்திலும் பழிவாங்குவேன்; மனுஷனுடைய உயிருக்காக அவனவன் சகோதரனிடத்தில் பழிவாங்குவேன்.',	1,	9,	5),
(212,	'Whoso sheddeth man\'s blood, by man shall his blood be shed: for in the image of God made he man.',	'மனுஷன் தேவசாயலில் உண்டாக்கப்பட்டபடியால், மனுஷனுடைய இரத்தத்தை எவன் சிந்துகிறானோ, அவனுடைய இரத்தம் மனுஷனாலே சிந்தப்படக்கடவது.',	1,	9,	6),
(213,	'And you, be ye fruitful, and multiply; bring forth abundantly in the earth, and multiply therein.',	'நீங்கள் பலுகிப் பெருகி, பூமியிலே திரளாய் வர்த்தித்து விர்த்தியாகுங்கள் என்றார்.',	1,	9,	7),
(214,	'And God spake unto Noah, and to his sons with him, saying,',	'பின்னும் தேவன் நோவாவையும், அவன் குமாரரையும் நோக்கி:',	1,	9,	8),
(215,	'And I, behold, I establish my covenant with you, and with your seed after you;',	'நான் உங்களோடும், உங்களுக்குப் பின்வரும் உங்கள் சந்ததியோடும்,',	1,	9,	9),
(216,	'And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you; from all that go out of the ark, to every beast of the earth.',	'உங்களோடே பேழையிலிருந்து புறப்பட்ட சகல ஜீவஜந்துக்கள்முதல் இனிப் பூமியில் உண்டாகப்போகிற சகல ஜீவஜந்துக்கள்பரியந்தம், பறவைகளோடும், நாட்டு மிருகங்களோடும், உங்களிடத்தில் இருக்கிற பூமியிலுள்ள சகல காட்டு மிருகங்களோடும் என் உடன்படிக்கையை ஏற்படுத்துகிறேன்.',	1,	9,	10),
(217,	'And I will establish my covenant with you, neither shall all flesh be cut off any more by the waters of a flood; neither shall there any more be a flood to destroy the earth.',	'இனி மாம்சமானவைகளெல்லாம் ஜலப்பிரளயத்தினால் சங்கரிக்கப்படுவதில்லையென்றும், பூமியை அழிக்க இனி ஜலப்பிரளயம் உண்டாவதில்லையென்றும், உங்களோடே என் உடன்படிக்கையை ஏற்படுத்துகிறேன் என்றார்.',	1,	9,	11),
(218,	'And God said, This is the token of the covenant which I make between me and you and every living creature that is with you, for perpetual generations:',	'அன்றியும் தேவன்: எனக்கும் உங்களுக்கும், உங்களிடத்தில் இருக்கும் சகல ஜீவஜந்துக்களுக்கும், நித்திய தலைமுறைகளுக்கென்று நான் செய்கிற உடன்படிக்கையின் அடையாளமாக:',	1,	9,	12),
(219,	'I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth.',	'நான் என் வில்லை மேகத்தில் வைத்தேன்; அது எனக்கும் பூமிக்கும் உண்டான உடன்படிக்கைக்கு அடையாளமாயிருக்கும்.',	1,	9,	13),
(220,	'And it shall come to pass, when I bring a cloud over the earth, that the bow shall be seen in the cloud:',	'நான் பூமிக்கு மேலாய் மேகத்தை வருவிக்கும்போது, அந்த வில் மேகத்தில் தோன்றும்.',	1,	9,	14),
(221,	'And I will remember my covenant, which is between me and you and every living creature of all flesh; and the waters shall no more become a flood to destroy all flesh.',	'அப்பொழுது எல்லா மாம்சஜீவன்களையும் அழிக்க இனி ஜலமானது பிரளயமாய்ப் பெருகாதபடிக்கு எனக்கும் உங்களுக்கும் மாம்சமான சகல ஜீவஜந்துக்களுக்கும் உண்டான என் உடன்படிக்கையை நினைவுகூருவேன்.',	1,	9,	15),
(222,	'And the bow shall be in the cloud; and I will look upon it, that I may remember the everlasting covenant between God and every living creature of all flesh that is upon the earth.',	'அந்த வில் மேகத்தில் தோன்றும்போது, தேவனுக்கும் பூமியின்மேலுள்ள சகலவித மாம்சஜீவன்களுக்கும் உண்டான நித்திய உடன்படிக்கையை நான் நினைவுகூரும்படிக்கு அதை நோக்கிப்பார்ப்பேன்.',	1,	9,	16),
(223,	'And God said unto Noah, This is the token of the covenant, which I have established between me and all flesh that is upon the earth.',	'இது எனக்கும், பூமியின்மேலுள்ள மாம்சமான யாவுக்கும், நான் ஏற்படுத்தின உடன்படிக்கையின் அடையாளம் என்று நோவாவோடே சொன்னார்.',	1,	9,	17),
(224,	'And the sons of Noah, that went forth of the ark, were Shem, and Ham, and Japheth: and Ham is the father of Canaan.',	'பேழையிலிருந்து புறப்பட்ட நோவாவின் குமாரர், சேம், காம், யாப்பேத் என்பவர்களே. காம் கானானுக்குத் தகப்பன்.',	1,	9,	18),
(225,	'These are the three sons of Noah: and of them was the whole earth overspread.',	'இம்மூவரும் நோவாவின் குமாரர்; இவர்களாலே பூமியெங்கும் ஜனங்கள் பரம்பினார்கள்.',	1,	9,	19),
(226,	'And Noah began to be an husbandman, and he planted a vineyard:',	'நோவா பயிரிடுகிறவனாகி, திராட்சத்தோட்டத்தை நாட்டினான்.',	1,	9,	20),
(227,	'And he drank of the wine, and was drunken; and he was uncovered within his tent.',	'அவன் திராட்சரசத்தைக் குடித்து, வெறிகொண்டு, தன் கூடாரத்தில் வஸ்திரம் விலகிப் படுத்திருந்தான்.',	1,	9,	21),
(228,	'And Ham, the father of Canaan, saw the nakedness of his father, and told his two brethren without.',	'அப்பொழுது கானானுக்குத் தகப்பனாகிய காம் தன் தகப்பனுடைய நிர்வாணத்தைத் கண்டு, வெளியில் இருந்த தன் சகோதரர் இருவருக்கும் அறிவித்தான்.',	1,	9,	22),
(229,	'And Shem and Japheth took a garment, and laid it upon both their shoulders, and went backward, and covered the nakedness of their father; and their faces were backward, and they saw not their father\'s nakedness.',	'அப்பொழுது சேமும், யாப்பேத்தும் ஒரு வஸ்திரத்தை எடுத்துத் தங்கள் இருவருடைய தோள்மேலும் போட்டுக்கொண்டு, பின்னிட்டு வந்து, தங்கள் தகப்பனுடைய நிர்வாணத்தை மூடினார்கள்; அவர்கள் எதிர்முகமாய்ப் போகாதபடியினால், தங்கள் தகப்பனுடைய நிர்வாணத்தைக் காணவில்லை.',	1,	9,	23),
(230,	'And Noah awoke from his wine, and knew what his younger son had done unto him.',	'நோவா திராட்சரசத்தின் வெறி தெளிந்து விழித்தபோது, தன் இளையகுமாரன் தனக்குச் செய்ததை அறிந்து:',	1,	9,	24),
(231,	'And he said, Cursed be Canaan; a servant of servants shall he be unto his brethren.',	'கானான் சபிக்கப்பட்டவன், தன் சகோதரரிடத்தில் அடிமைகளுக்கு அடிமையாயிருப்பான் என்றான்.',	1,	9,	25),
(232,	'And he said, Blessed be the LORD God of Shem; and Canaan shall be his servant.',	'சேமுடைய தேவனாகிய கர்த்தருக்கு ஸ்தோத்திரம் உண்டாவதாக; கானான் அவனுக்கு அடிமையாயிருப்பான்.',	1,	9,	26),
(233,	'God shall enlarge Japheth, and he shall dwell in the tents of Shem; and Canaan shall be his servant.',	'யாப்பேத்தை தேவன் விர்த்தியாக்குவார்; அவன் சேமுடைய கூடாரங்களில் குடியிருப்பான்; கானான் அவனுக்கு அடிமையாயிருப்பான் என்றான்.',	1,	9,	27),
(234,	'And Noah lived after the flood three hundred and fifty years.',	'ஜலப்பிரளயத்துக்குப்பின்பு நோவா முந்நூற்று ஐம்பது வருஷம் உயிரோடிருந்தான்.',	1,	9,	28),
(235,	'And all the days of Noah were nine hundred and fifty years: and he died.',	'நோவாவின் நாட்களெல்லாம் தொளாயிரத்து ஐம்பது வருஷம்; அவன் மரித்தான்.  ',	1,	9,	29),
(236,	'Now these are the generations of the sons of Noah, Shem, Ham, and Japheth: and unto them were sons born after the flood.',	'நோவாவின் குமாரராகிய சேம், காம், யாப்பேத் என்பவர்களின் வம்சவரலாறு: ஜலப்பிரளயத்துக்குப்பின்பு அவர்களுக்குக் குமாரர் பிறந்தார்கள்.',	1,	10,	1),
(237,	'The sons of Japheth; Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras.',	'யாப்பேத்தின் குமாரர், கோமர், மாகோகு, மாதாய், யாவான், தூபால், மேசேக்கு, தீராஸ் என்பவர்கள்.',	1,	10,	2),
(238,	'And the sons of Gomer; Ashkenaz, and Riphath, and Togarmah.',	'கோமரின் குமாரர், அஸ்கினாஸ், ரீப்பாத்து, தொகர்மா என்பவர்கள்.',	1,	10,	3),
(239,	'And the sons of Javan; Elishah, and Tarshish, Kittim, and Dodanim.',	'யாவானின் குமாரர், எலீசா, தர்ஷீஸ், கித்தீம், தொதானீம் என்பவர்கள்.',	1,	10,	4),
(240,	'By these were the isles of the Gentiles divided in their lands; every one after his tongue, after their families, in their nations.',	'இவர்களால் ஜாதிகளுடைய தீவுகள், அவனவன் பாஷையின்படியேயும், அவரவர்கள் கோத்திரத்தின்படியேயும், ஜாதியின்படியேயும், வேறுவேறு தேசங்களாய்ப் பகுக்கப்பட்டன.',	1,	10,	5),
(241,	'And the sons of Ham; Cush, and Mizraim, and Phut, and Canaan.',	'காமுடைய குமாரர், கூஷ், மிஸ்ராயீம், பூத், கானான் என்பவர்கள்.',	1,	10,	6),
(242,	'And the sons of Cush; Seba, and Havilah, and Sabtah, and Raamah, and Sabtechah: and the sons of Raamah; Sheba, and Dedan.',	'கூஷூடைய குமாரர், சேபா, ஆவிலா, சப்தா, ராமா, சப்திகா என்பவர்கள். ராமாவின் குமாரர், சேபா, திதான் என்பவர்கள்.',	1,	10,	7),
(243,	'And Cush begat Nimrod: he began to be a mighty one in the earth.',	'கூஷ் நிம்ரோதைப் பெற்றான்; இவன் பூமியிலே பராக்கிரமசாலியானான்.',	1,	10,	8),
(244,	'He was a mighty hunter before the LORD: wherefore it is said, Even as Nimrod the mighty hunter before the LORD.',	'இவன் கர்த்தருக்கு முன்பாகப் பலத்த வேட்டைக்காரனாயிருந்தான்; ஆகையால், கர்த்தருக்கு முன்பாகப் பலத்த வேட்டைக்காரனான நிம்ரோதைப்போல என்னும் வழக்கச்சொல் உண்டாயிற்று.',	1,	10,	9),
(245,	'And the beginning of his kingdom was Babel, and Erech, and Accad, and Calneh, in the land of Shinar.',	'சிநெயார் தேசத்திலுள்ள பாபேல், ஏரேக், அக்காத், கல்னே என்னும் இடங்கள் அவன் ஆண்ட ராஜ்யத்திற்கு ஆதி ஸ்தானங்கள்.',	1,	10,	10),
(246,	'Out of that land went forth Asshur, and builded Nineveh, and the city Rehoboth, and Calah,',	'அந்தத் தேசத்திலிருந்து அசூர் புறப்பட்டுப்போய், நினிவேயையும், ரெகொபோத் பட்டணத்தையும், காலாகையும்,',	1,	10,	11),
(247,	'And Resen between Nineveh and Calah: the same is a great city.',	'நினிவேக்கும் காலாகுக்கும் நடுவாக ரெசேனையும் கட்டினான்; இது பெரிய பட்டணம்.',	1,	10,	12),
(248,	'And Mizraim begat Ludim, and Anamim, and Lehabim, and Naphtuhim,',	'மிஸ்ராயீம், லூதீமையும், அனாமீமையும், லெகாபீமையும், நப்தூகீமையும்,',	1,	10,	13),
(249,	'And Pathrusim, and Casluhim, (out of whom came Philistim,) and Caphtorim.',	'பத்ருசீமையும், பெலிஸ்தரின் சந்ததிக்குத் தலைவனாகிய கஸ்லூகீமையும், கப்தொரீமையும் பெற்றான்.',	1,	10,	14),
(250,	'And Canaan begat Sidon his first born, and Heth,',	'கானான் தன் மூத்தமகனாகிய சீதோனையும், கேத்தையும்,',	1,	10,	15),
(251,	'And the Jebusite, and the Amorite, and the Girgasite,',	'எபூசியரையும், எமோரியரையும், கிர்காசியரையும்,',	1,	10,	16),
(252,	'And the Hivite, and the Arkite, and the Sinite,',	'ஈவியரையும், அர்கீரியரையும், சீநியரையும்,',	1,	10,	17),
(253,	'And the Arvadite, and the Zemarite, and the Hamathite: and afterward were the families of the Canaanites spread abroad.',	'அர்வாதியரையும், செமாரியரையும், காமாத்தியரையும் பெற்றான்; பின்பு கானானியரின் வம்சத்தார் எங்கும் பரவினார்கள்.',	1,	10,	18),
(254,	'And the border of the Canaanites was from Sidon, as thou comest to Gerar, unto Gaza; as thou goest, unto Sodom, and Gomorrah, and Admah, and Zeboim, even unto Lasha.',	'கானானியரின் எல்லை, சீதோன் முதல் கேரார் வழியாய்க் காசாமட்டுக்கும், அது முதல் சோதோம், கொமோரா, அத்மா, செபோயிம் வழியாய் லாசாமட்டுக்கும் இருந்தது.',	1,	10,	19),
(255,	'These are the sons of Ham, after their families, after their tongues, in their countries, and in their nations.',	'இவர்கள் தங்கள் தேசங்களிலும், தங்கள் ஜாதிகளிலுமுள்ள தங்கள் வம்சங்களின்படியேயும், தங்கள் பாஷைகளின்படியேயும் காமுடைய சந்ததியார்.',	1,	10,	20),
(256,	'Unto Shem also, the father of all the children of Eber, the brother of Japheth the elder, even to him were children born.',	'சேமுக்கும் பிள்ளைகள் பிறந்தார்கள்; அவன் ஏபேருடைய சந்ததியார் எல்லாருக்கும் தகப்பனும், மூத்தவனாகிய யாப்பேத்துக்குத் தம்பியுமாய் இருந்தான்.',	1,	10,	21),
(257,	'The children of Shem; Elam, and Asshur, and Arphaxad, and Lud, and Aram.',	'சேமுடைய குமாரர், ஏலாம், அசூர், அர்பக்சாத், லூத், ஆராம் என்பவர்கள்.',	1,	10,	22),
(258,	'And the children of Aram; Uz, and Hul, and Gether, and Mash.',	'ஆராமுடைய குமாரர், ஊத்ஸ், கூல், கேத்தெர், மாஸ் என்பவர்கள்.',	1,	10,	23),
(259,	'And Arphaxad begat Salah; and Salah begat Eber.',	'அர்பக்சாத் சாலாவைப் பெற்றான்; சாலா ஏபேரைப் பெற்றான்.',	1,	10,	24),
(260,	'And unto Eber were born two sons: the name of one was Peleg; for in his days was the earth divided; and his brother\'s name was Joktan.',	'ஏபேருக்கு இரண்டு குமாரர் பிறந்தார்கள்; ஒருவனுக்குப் பேலேகு என்று பேர்; ஏனெனில் அவனுடைய நாட்களில் பூமி பகுக்கப்பட்டது; அவனுடைய சகோதரன் பேர் யொக்தான்.',	1,	10,	25),
(261,	'And Joktan begat Almodad, and Sheleph, and Hazarmaveth, and Jerah,',	'யொக்தான் அல்மோதாதையும், சாலேப்பையும், அசர்மாவேத்தையும், யேராகையும்,',	1,	10,	26),
(262,	'And Hadoram, and Uzal, and Diklah,',	'அதோராமையும், ஊசாலையும், திக்லாவையும்,',	1,	10,	27),
(263,	'And Obal, and Abimael, and Sheba,',	'ஓபாலையும், அபிமாவேலையும், சேபாவையும்,',	1,	10,	28),
(264,	'And Ophir, and Havilah, and Jobab: all these were the sons of Joktan.',	'ஒப்பீரையும், ஆவிலாவையும், யோபாபையும் பெற்றான்; இவர்கள் அனைவரும் யொக்தானுடைய குமாரர்.',	1,	10,	29),
(265,	'And their dwelling was from Mesha, as thou goest unto Sephar a mount of the east.',	'இவர்களுடைய குடியிருப்பு மேசா துவக்கி, கிழக்கேயுள்ள மலையாகிய செப்பாருக்குப் போகிற வழிமட்டும் இருந்தது.',	1,	10,	30),
(266,	'These are the sons of Shem, after their families, after their tongues, in their lands, after their nations.',	'இவர்களே தங்கள் தேசங்களிலும், தங்கள் ஜாதிகளிலுமுள்ள தங்கள் வம்சங்களின்படியேயும், தங்கள் பாஷைகளின்படியேயும் சேமுடைய சந்ததியார்.',	1,	10,	31),
(267,	'These are the families of the sons of Noah, after their generations, in their nations: and by these were the nations divided in the earth after the flood.',	'தங்கள் ஜாதிகளிலுள்ள தங்களுடைய சந்ததிகளின்படியே நோவாவுடைய குமாரரின் வம்சங்கள் இவைகளே; ஜலப்பிரளயத்துக்குப்பின்பு இவர்களால் பூமியிலே ஜாதிகள் பிரிந்தன.  ',	1,	10,	32),
(268,	'And the whole earth was of one language, and of one speech.',	'பூமியெங்கும் ஒரே பாஷையும், ஒரே விதமான பேச்சும் இருந்தது.',	1,	11,	1),
(269,	'And it came to pass, as they journeyed from the east, that they found a plain in the land of Shinar; and they dwelt there.',	'ஜனங்கள் கிழக்கேயிருந்து பிரயாணம்பண்ணுகையில், சிநெயார் தேசத்திலே சமபூமியைக்கண்டு, அங்கே குடியிருந்தார்கள்.',	1,	11,	2),
(270,	'And they said one to another, Go to, let us make brick, and burn them thoroughly. And they had brick for stone, and slime had they for morter.',	'அப்பொழுது அவர்கள்: நாம் செங்கல் அறுத்து, அதை நன்றாய்ச் சுடுவோம் வாருங்கள் என்று ஒருவரோடொருவர் பேசிக்கொண்டார்கள்; கல்லுக்குப் பதிலாக செங்கலும், சாந்துக்குப் பதிலாக நிலக்கீலும் அவர்களுக்கு இருந்தது.',	1,	11,	3),
(271,	'And they said, Go to, let us build us a city and a tower, whose top may reach unto heaven; and let us make us a name, lest we be scattered abroad upon the face of the whole earth.',	'பின்னும் அவர்கள்: நாம் பூமியின் மீதெங்கும் சிதறிப்போகாதபடிக்கு, நமக்கு ஒரு நகரத்தையும், வானத்தை அளாவும் சிகரமுள்ள ஒரு கோபுரத்தையும் கட்டி, நமக்குப் பேர் உண்டாகப் பண்ணுவோம் வாருங்கள் என்று சொல்லிக்கொண்டார்கள்.',	1,	11,	4),
(272,	'And the LORD came down to see the city and the tower, which the children of men builded.',	'மனுபுத்திரர் கட்டுகிற நகரத்தையும் கோபுரத்தையும் பார்க்கிறதற்குக் கர்த்தர் இறங்கினார்.',	1,	11,	5),
(273,	'And the LORD said, Behold, the people is one, and they have all one language; and this they begin to do: and now nothing will be restrained from them, which they have imagined to do.',	'அப்பொழுது கர்த்தர்: இதோ, ஜனங்கள் ஒரே கூட்டமாய் இருக்கிறார்கள்; அவர்கள் அனைவருக்கும் ஒரே பாஷையும் இருக்கிறது; அவர்கள் இதைச் செய்யத்தொடங்கினார்கள்; இப்பொழுதும் தாங்கள் செய்ய நினைத்தது ஒன்றும் தடைபடமாட்டாது என்று இருக்கிறார்கள்.',	1,	11,	6),
(274,	'Go to, let us go down, and there confound their language, that they may not understand one another\'s speech.',	'நாம் இறங்கிப்போய், ஒருவர் பேசுவதை மற்றொருவர் அறியாதபடிக்கு, அங்கே அவர்கள் பாஷையைத் தாறுமாறாக்குவோம் என்றார்.',	1,	11,	7),
(275,	'So the LORD scattered them abroad from thence upon the face of all the earth: and they left off to build the city.',	'அப்படியே கர்த்தர் அவர்களை அவ்விடத்திலிருந்து பூமியின்மீதெங்கும் சிதறிப்போகப்பண்ணினார்; அப்பொழுது நகரம் கட்டுகிறதை விட்டுவிட்டார்கள்.',	1,	11,	8),
(276,	'Therefore is the name of it called Babel; because the LORD did there confound the language of all the earth: and from thence did the LORD scatter them abroad upon the face of all the earth.',	'பூமியெங்கும் வழங்கின பாஷையைக் கர்த்தர் அவ்விடத்தில் தாறுமாறாக்கினபடியால், அதின் பேர் பாபேல் என்னப்பட்டது; கர்த்தர் அவர்களை அவ்விடத்திலிருந்து பூமியின்மீதெங்கும் சிதறிப்போகப்பண்ணினார்.',	1,	11,	9),
(277,	'These are the generations of Shem: Shem was an hundred years old, and begat Arphaxad two years after the flood:',	'சேமுடைய வம்சவரலாறு: ஜலப்பிரளயம் உண்டாகி இரண்டு வருஷத்திற்குப் பின்பு, சேம் நூறுவயதானபோது, அர்பக்சாத்தைப் பெற்றான்.',	1,	11,	10),
(278,	'And Shem lived after he begat Arphaxad five hundred years, and begat sons and daughters.',	'சேம் அர்பக்சாத்தைப் பெற்றபின் ஐந்நூறு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	11),
(279,	'And Arphaxad lived five and thirty years, and begat Salah:',	'அர்பக்சாத் முப்பத்தைந்து வயதானபோது சாலாவைப் பெற்றான்.',	1,	11,	12),
(280,	'And Arphaxad lived after he begat Salah four hundred and three years, and begat sons and daughters.',	'சாலாவைப் பெற்றபின் அர்பக்சாத் நானூற்று மூன்று வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	13),
(281,	'And Salah lived thirty years, and begat Eber:',	'சாலா முப்பது வயதானபோது, ஏபேரைப் பெற்றான்.',	1,	11,	14),
(282,	'And Salah lived after he begat Eber four hundred and three years, and begat sons and daughters.',	'ஏபேரைப் பெற்றபின் சாலா நானூற்று மூன்று வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	15),
(283,	'And Eber lived four and thirty years, and begat Peleg:',	'ஏபேர் முப்பத்துநாலு வயதானபோது, பேலேகைப் பெற்றான்.',	1,	11,	16),
(284,	'And Eber lived after he begat Peleg four hundred and thirty years, and begat sons and daughters.',	'பேலேகைப் பெற்றபின் ஏபேர் நானூற்று முப்பது வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	17),
(285,	'And Peleg lived thirty years, and begat Reu:',	'பேலேகு முப்பது வயதானபோது, ரெகூவைப் பெற்றான்.',	1,	11,	18),
(286,	'And Peleg lived after he begat Reu two hundred and nine years, and begat sons and daughters.',	'ரெகூவைப் பெற்றபின் பேலேகு இருநூற்றொன்பது வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	19),
(287,	'And Reu lived two and thirty years, and begat Serug:',	'ரெகூ முப்பத்திரண்டு வயதானபோது, செரூகைப் பெற்றான்.',	1,	11,	20),
(288,	'And Reu lived after he begat Serug two hundred and seven years, and begat sons and daughters.',	'செரூகைப் பெற்றபின் ரெகூ இருநூற்றேழு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	21),
(289,	'And Serug lived thirty years, and begat Nahor:',	'செரூகு முப்பது வயதானபோது, நாகோரைப் பெற்றான்.',	1,	11,	22),
(290,	'And Serug lived after he begat Nahor two hundred years, and begat sons and daughters.',	'நாகோரைப் பெற்றபின் செரூகு இருநூறு வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	23),
(291,	'And Nahor lived nine and twenty years, and begat Terah:',	'நாகோர் இருபத்தொன்பது வயதானபோது, தேராகைப் பெற்றான்.',	1,	11,	24),
(292,	'And Nahor lived after he begat Terah an hundred and nineteen years, and begat sons and daughters.',	'தேராகைப் பெற்றபின் நாகோர் நூற்றுப்பத்தொன்பது வருஷம் உயிரோடிருந்து, குமாரரையும் குமாரத்திகளையும் பெற்றான்.',	1,	11,	25),
(293,	'And Terah lived seventy years, and begat Abram, Nahor, and Haran.',	'தேராகு எழுபது வயதானபோது, ஆபிராம், நாகோர், ஆரான் என்பவர்களைப் பெற்றான்.',	1,	11,	26),
(294,	'Now these are the generations of Terah: Terah begat Abram, Nahor, and Haran; and Haran begat Lot.',	'தேராகுடைய வம்சவரலாறு: தேராகு ஆபிராம், நாகோர், ஆரான் என்பவர்களைப் பெற்றான்; ஆரான் லோத்தைப் பெற்றான்.',	1,	11,	27),
(295,	'And Haran died before his father Terah in the land of his nativity, in Ur of the Chaldees.',	'ஆரான் தன் ஜந்மபூமியாகிய ஊர் என்கிற கல்தேயர் தேசத்துப் பட்டணத்திலே தன் தகப்பனாகிய தேராகு மரிக்குமுன்னே மரித்தான்.',	1,	11,	28),
(296,	'And Abram and Nahor took them wives: the name of Abram\'s wife was Sarai; and the name of Nahor\'s wife, Milcah, the daughter of Haran, the father of Milcah, and the father of Iscah.',	'ஆபிராமும் நாகோரும் தங்களுக்குப் பெண் கொண்டார்கள்; ஆபிராமுடைய மனைவிக்குச் சாராய் என்று பேர்; நாகோருடைய மனைவிக்கு மில்க்காள் என்று பேர்; இவள் ஆரானுடைய குமாரத்தி; அந்த ஆரான் மில்க்காளுக்கும் இஸ்காளுக்கும் தகப்பன்.',	1,	11,	29),
(297,	'But Sarai was barren; she had no child.',	'சாராய்க்குப் பிள்ளையில்லை; மலடியாயிருந்தாள்.',	1,	11,	30),
(298,	'And Terah took Abram his son, and Lot the son of Haran his son\'s son, and Sarai his daughter in law, his son Abram\'s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there.',	'தேராகு தன் குமாரனாகிய ஆபிராமையும், ஆரானுடைய குமாரனும், தன் பேரனுமாயிருந்த லோத்தையும், தன் குமாரன் ஆபிராமுடைய மனைவியாகிய தன் மருமகள் சாராயையும் அழைத்துக்கொண்டு, அவர்களுடனே ஊர் என்கிற கல்தேயருடைய பட்டணத்தை விட்டு, கானான் தேசத்துக்குப் போகப் புறப்பட்டான்; அவர்கள் ஆரான் மட்டும் வந்தபோது, அங்கே இருந்துவிட்டார்கள்.',	1,	11,	31),
(299,	'And the days of Terah were two hundred and five years: and Terah died in Haran.',	'தேராகுடைய ஆயுசு நாட்கள் இருநூற்றைந்து வருஷம்; தேராகு ஆரானிலே மரித்தான்.  ',	1,	11,	32),
(300,	'Now the LORD had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father\'s house, unto a land that I will shew thee:',	'கர்த்தர் ஆபிராமை நோக்கி: நீ உன் தேசத்தையும், உன் இனத்தையும், உன் தகப்பனுடைய வீட்டையும் விட்டுப் புறப்பட்டு, நான் உனக்குக் காண்பிக்கும் தேசத்துக்குப் போ.',	1,	12,	1),
(301,	'And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing:',	'நான் உன்னைப் பெரிய ஜாதியாக்கி, உன்னை ஆசீர்வதித்து, உன் பேரைப் பெருமைப்படுத்துவேன்; நீ ஆசீர்வாதமாய் இருப்பாய்.',	1,	12,	2),
(302,	'And I will bless them that bless thee, and curse him that curseth thee: and in thee shall all families of the earth be blessed.',	'உன்னை ஆசீர்வதிக்கிறவர்களை ஆசீர்வதிப்பேன், உன்னைச் சபிக்கிறவனைச் சபிப்பேன்; பூமியிலுள்ள வம்சங்களெல்லாம் உனக்குள் ஆசீர்வதிக்கப்படும் என்றார்.',	1,	12,	3),
(303,	'So Abram departed, as the LORD had spoken unto him; and Lot went with him: and Abram was seventy and five years old when he departed out of Haran.',	'கர்த்தர் ஆபிராமுக்குச் சொன்னபடியே அவன் புறப்பட்டுப்போனான்; லோத்தும் அவனோடேகூடப் போனான். ஆபிராம் ஆரானைவிட்டுப் புறப்பட்டபோது, எழுபத்தைந்து வயதுள்ளவனாயிருந்தான்.',	1,	12,	4),
(304,	'And Abram took Sarai his wife, and Lot his brother\'s son, and all their substance that they had gathered, and the souls that they had gotten in Haran; and they went forth to go into the land of Canaan; and into the land of Canaan they came.',	'ஆபிராம் தன் மனைவியாகிய சாராயையும், தன் சகோதரனுடைய குமாரனாகிய லோத்தையும், தாங்கள் சம்பாதித்திருந்த தங்கள் சம்பத்தெல்லாவற்றையும், ஆரானிலே சவதரித்த ஜனங்களையும் கூட்டிக்கொண்டு, அவர்கள் கானான் தேசத்துக்குப் புறப்பட்டுப்போய், கானான் தேசத்தில் சேர்ந்தார்கள்.',	1,	12,	5),
(305,	'And Abram passed through the land unto the place of Sichem, unto the plain of Moreh. And the Canaanite was then in the land.',	'ஆபிராம் அந்தத் தேசத்தில் சுற்றித் திரிந்து சீகேம் என்னும் இடத்துக்குச் சமீபமான மோரே என்னும் சமபூமிமட்டும் வந்தான்; அக்காலத்திலே கானானியர் அத்தேசத்தில் இருந்தார்கள்.',	1,	12,	6),
(306,	'And the LORD appeared unto Abram, and said, Unto thy seed will I give this land: and there builded he an altar unto the LORD, who appeared unto him.',	'கர்த்தர் ஆபிராமுக்குத் தரிசனமாகி: உன் சந்ததிக்கு இந்தத் தேசத்தைக் கொடுப்பேன் என்றார். அப்பொழுது அவன் தனக்குத் தரிசனமான கர்த்தருக்கு அங்கே ஒரு பலிபீடத்தைக் கட்டினான்.',	1,	12,	7),
(307,	'And he removed from thence unto a mountain on the east of Bethel, and pitched his tent, having Bethel on the west, and Hai on the east: and there he builded an altar unto the LORD, and called upon the name of the LORD.',	'பின்பு அவன் அவ்விடம்விட்டுப்பெயர்ந்து, பெத்தேலுக்குக் கிழக்கே இருக்கும் மலைக்குப் போய், பெத்தேல் தனக்கு மேற்காகவும் ஆயீ கிழக்காகவும் இருக்கக் கூடாரம்போட்டு, அங்கே கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டி, கர்த்தருடைய நாமத்தைத் தொழுதுகொண்டான்.',	1,	12,	8),
(308,	'And Abram journeyed, going on still toward the south.',	'அதின்பின் ஆபிராம் புறப்பட்டு, தெற்கே பிரயாணம்பண்ணிக்கொண்டு போனான்.',	1,	12,	9),
(309,	'And there was a famine in the land: and Abram went down into Egypt to sojourn there; for the famine was grievous in the land.',	'அத்தேசத்திலே பஞ்சம் உண்டாயிற்று; தேசத்திலே பஞ்சம் கொடிதாயிருந்தபடியால், ஆபிராம் எகிப்து தேசத்திலே தங்கும்படி அவ்விடத்துக்குப் போனான்.',	1,	12,	10),
(310,	'And it came to pass, when he was come near to enter into Egypt, that he said unto Sarai his wife, Behold now, I know that thou art a fair woman to look upon:',	'அவன் எகிப்துக்குச் சமீபமாய் வந்தபோது, தன் மனைவி சாராயைப் பார்த்து: நீ பார்வைக்கு அழகுள்ள ஸ்திரீ என்று அறிவேன்.',	1,	12,	11),
(311,	'Therefore it shall come to pass, when the Egyptians shall see thee, that they shall say, This is his wife: and they will kill me, but they will save thee alive.',	'எகிப்தியர் உன்னைக் காணும்போது, இவள் அவனுடைய மனைவி என்று சொல்லி, என்னைக் கொன்றுபோட்டு, உன்னை உயிரோடே வைப்பார்கள்.',	1,	12,	12),
(312,	'Say, I pray thee, thou art my sister: that it may be well with me for thy sake; and my soul shall live because of thee.',	'ஆகையால், உன்னிமித்தம் எனக்கு நன்மை உண்டாகும்படிக்கும், உன்னாலே என் உயிர் பிழைக்கும்படிக்கும், நீ உன்னை என் சகோதரி என்று சொல் என்றான்.',	1,	12,	13),
(313,	'And it came to pass, that, when Abram was come into Egypt, the Egyptians beheld the woman that she was very fair.',	'ஆபிராம் எகிப்திலே வந்தபோது, எகிப்தியர் அந்த ஸ்திரீயை மிகுந்த அழகுள்ளவளென்று கண்டார்கள்.',	1,	12,	14),
(314,	'The princes also of Pharaoh saw her, and commended her before Pharaoh: and the woman was taken into Pharaoh\'s house.',	'பார்வோனுடைய பிரபுக்களும் அவளைக்கண்டு, பார்வோனுக்கு முன்பாக அவளைப் புகழ்ந்தார்கள். அப்பொழுது அந்த ஸ்திரீ பார்வோனுடைய அரமனைக்குக் கொண்டுபோகப்பட்டாள்.',	1,	12,	15),
(315,	'And he entreated Abram well for her sake: and he had sheep, and oxen, and he asses, and menservants, and maidservants, and she asses, and camels.',	'அவள் நிமித்தம் அவன் ஆபிராமுக்குத் தயைபாராட்டினான்; அவனுக்கு ஆடுமாடுகளும், கழுதைகளும், வேலைக்காரரும், வேலைக்காரிகளும், கோளிகைக் கழுதைகளும், ஒட்டகங்களும் கிடைத்தது.',	1,	12,	16),
(316,	'And the LORD plagued Pharaoh and his house with great plagues because of Sarai Abram\'s wife.',	'ஆபிராமுடைய மனைவியாகிய சாராயின் நிமித்தம் கர்த்தர் பார்வோனையும், அவன் வீட்டாரையும் மகா வாதைகளால் வாதித்தார்.',	1,	12,	17),
(317,	'And Pharaoh called Abram and said, What is this that thou hast done unto me? why didst thou not tell me that she was thy wife?',	'அப்பொழுது பார்வோன் ஆபிராமை அழைத்து: நீ எனக்கு ஏன் இப்படிச் செய்தாய்? இவள் உன் மனைவி என்று நீ எனக்கு அறிவியாமற்போனதென்ன?',	1,	12,	18),
(318,	'Why saidst thou, She is my sister? so I might have taken her to me to wife: now therefore behold thy wife, take her, and go thy way.',	'இவளை உன் சகோதரி என்று நீ சொல்லவேண்டுவது என்ன? இவளை நான் எனக்கு மனைவியாகக்கொண்டிருப்பேனே; இதோ உன் மனைவி; இவளை அழைத்துக்கொண்டுபோ என்று சொன்னான்.',	1,	12,	19),
(319,	'And Pharaoh commanded his men concerning him: and they sent him away, and his wife, and all that he had.',	'பார்வோன் அவனைக் குறித்துத் தன் மனுஷருக்குக் கட்டளை கொடுத்தான்; அவர்கள் அவனையும், அவன் மனைவியையும் அவனுக்கு உண்டான எல்லாவற்றையும் அனுப்பிவிட்டார்கள்.  ',	1,	12,	20),
(320,	'And Abram went up out of Egypt, he, and his wife, and all that he had, and Lot with him, into the south.',	'ஆபிராமும், அவன் மனைவியும், அவனுக்கு உண்டான யாவும், அவனுடனே லோத்தும், எகிப்தை விட்டு, தென்திசையில் வந்தார்கள்.',	1,	13,	1),
(321,	'And Abram was very rich in cattle, in silver, and in gold.',	'ஆபிராம் மிருகஜீவன்களும் வெள்ளியும் பொன்னுமான ஆஸ்திகளை உடைய சீமானாயிருந்தான்.',	1,	13,	2),
(322,	'And he went on his journeys from the south even to Bethel, unto the place where his tent had been at the beginning, between Bethel and Hai;',	'அவன் தன் பிரயாணங்களிலே தெற்கேயிருந்து பெத்தேல்மட்டும், பெத்தேலுக்கும் ஆயீக்கும் நடுவாகத் தான் முன்பு கூடாரம்போட்டதும்,',	1,	13,	3),
(323,	'Unto the place of the altar, which he had make there at the first: and there Abram called on the name of the LORD.',	'தான் முதல்முதல் ஒரு பலிபீடத்தை உண்டாக்கினதுமான ஸ்தலமட்டும் போனான்; அங்கே ஆபிராம் கர்த்தருடைய நாமத்தைத் தொழுதுகொண்டான்.',	1,	13,	4),
(324,	'And Lot also, which went with Abram, had flocks, and herds, and tents.',	'ஆபிராமுடனே வந்த லோத்துக்கும் ஆடுமாடுகளும் கூடாரங்களும் இருந்தன.',	1,	13,	5),
(325,	'And the land was not able to bear them, that they might dwell together: for their substance was great, so that they could not dwell together.',	'அவர்கள் ஒருமித்துக் குடியிருக்க அந்தப் பூமி அவர்களைத் தாங்கக்கூடாதிருந்தது; அவர்களுடைய ஆஸ்தி மிகுதியாயிருந்தபடியால், அவர்கள் ஒருமித்து வாசம்பண்ண ஏதுவில்லாமற்போயிற்று.',	1,	13,	6),
(326,	'And there was a strife between the herdmen of Abram\'s cattle and the herdmen of Lot\'s cattle: and the Canaanite and the Perizzite dwelled then in the land.',	'ஆபிராமுடைய மந்தைமேய்ப்பருக்கும் லோத்துடைய மந்தைமேய்ப்பருக்கும் வாக்குவாதம் உண்டாயிற்று. அக்காலத்திலே கானானியரும் பெரிசியரும் அத்தேசத்தில் குடியிருந்தார்கள்.',	1,	13,	7),
(327,	'And Abram said unto Lot, Let there be no strife, I pray thee, between me and thee, and between my herdmen and thy herdmen; for we be brethren.',	'ஆபிராம் லோத்தை நோக்கி: எனக்கும் உனக்கும், என் மேய்ப்பருக்கும் உன் மேய்ப்பருக்கும் வாக்குவாதம் வேண்டாம்; நாம் சகோதரர்.',	1,	13,	8),
(328,	'Is not the whole land before thee? separate thyself, I pray thee, from me: if thou wilt take the left hand, then I will go to the right; or if thou depart to the right hand, then I will go to the left.',	'இந்தத் தேசமெல்லாம் உனக்குமுன் இருக்கிறது அல்லவா? நீ என்னைவிட்டுப் பிரிந்துபோகலாம்; நீ இடதுபுறம் போனால், நான் வலதுபுறம் போகிறேன்; நீ வலதுபுறம் போனால், நான் இடதுபுறம் போகிறேன் என்றான்.',	1,	13,	9),
(329,	'And Lot lifted up his eyes, and beheld all the plain of Jordan, that it was well watered every where, before the LORD destroyed Sodom and Gomorrah, even as the garden of the LORD, like the land of Egypt, as thou comest unto Zoar.',	'அப்பொழுது லோத்து தன் கண்களை ஏறெடுத்துப்பார்த்து: யோர்தான் நதிக்கு அருகான சமபூமி முழுவதும் நீர்வளம் பொருந்தினதாயிருக்கக்கண்டான். கர்த்தர் சோதோமையும் கொமோராவையும் அழிக்கும்முன்னே, சோவாருக்குப் போகும் வழிமட்டும் அது கர்த்தருடைய தோட்டத்தைப்போலவும் எகிப்து தேசத்தைப்போலவும் இருந்தது.',	1,	13,	10),
(330,	'Then Lot chose him all the plain of Jordan; and Lot journeyed east: and they separated themselves the one from the other.',	'அப்பொழுது லோத்து யோர்தானுக்கு அருகான சமபூமி முழுவதையும் தெரிந்துகொண்டு, கிழக்கே பிரயாணப்பட்டுப்போனான். இப்படி அவர்கள் ஒருவரை ஒருவர் விட்டுப் பிரிந்தார்கள்.',	1,	13,	11),
(331,	'Abram dwelled in the land of Canaan, and Lot dwelled in the cities of the plain, and pitched his tent toward Sodom.',	'ஆபிராம் கானான் தேசத்தில் குடியிருந்தான்; லோத்து அந்த யோர்தானுக்கு அருகான சமபூமியிலுள்ள பட்டணங்களில் வாசம்பண்ணி, சோதோமுக்கு நேரே கூடாரம் போட்டான்.',	1,	13,	12),
(332,	'But the men of Sodom were wicked and sinners before the LORD exceedingly.',	'சோதோமின் ஜனங்கள் பொல்லாதவர்களும் கர்த்தருக்கு முன்பாக மகாபாவிகளுமாய் இருந்தார்கள்.',	1,	13,	13),
(333,	'And the LORD said unto Abram, after that Lot was separated from him, Lift up now thine eyes, and look from the place where thou art northward, and southward, and eastward, and westward:',	'லோத்து ஆபிராமைவிட்டுப் பிரிந்த பின்பு, கர்த்தர் ஆபிராமை நோக்கி: உன் கண்களை ஏறெடுத்து, நீ இருக்கிற இடத்திலிருந்து வடக்கேயும், தெற்கேயும், கிழக்கேயும், மேற்கேயும் நோக்கிப்பார்.',	1,	13,	14),
(334,	'For all the land which thou seest, to thee will I give it, and to thy seed for ever.',	'நீ பார்க்கிற இந்தப் பூமி முழுவதையும் நான் உனக்கும் உன் சந்ததிக்கும் என்றைக்கும் இருக்கும்படி கொடுத்து,',	1,	13,	15),
(335,	'And I will make thy seed as the dust of the earth: so that if a man can number the dust of the earth, then shall thy seed also be numbered.',	'உன் சந்ததியைப் பூமியின் தூளைப்போலப் பெருகப்பண்ணுவேன்; ஒருவன் பூமியின் தூளை எண்ணக்கூடுமானால், உன் சந்ததியும் எண்ணப்படும்.',	1,	13,	16),
(336,	'Arise, walk through the land in the length of it and in the breadth of it; for I will give it unto thee.',	'நீ எழுந்து தேசத்தின் நீளமும் அகலமும் எம்மட்டோ, அம்மட்டும் நடந்து திரி; உனக்கு அதைத் தருவேன் என்றார்.',	1,	13,	17),
(337,	'Then Abram removed his tent, and came and dwelt in the plain of Mamre, which is in Hebron, and built there an altar unto the LORD.',	'அப்பொழுது ஆபிராம் கூடாரத்தைப் பெயர்த்துக்கொண்டுபோய், எபிரோனிலிருக்கும் மம்ரேயின் சமபூமியில் சேர்ந்து குடியிருந்து, அங்கே கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டினான்.  ',	1,	13,	18),
(338,	'And it came to pass in the days of Amraphel king of Shinar, Arioch king of Ellasar, Chedorlaomer king of Elam, and Tidal king of nations;',	'சிநெயாரின் ராஜாவாகிய அம்ராப்பேலும், ஏலாசாரின் ராஜாவாகிய அரியோகும், ஏலாமின் ராஜாவாகிய கெதர்லா கோமேரும், ஜாதிகளின் ராஜாவாகிய திதியாலும் இருந்த நாட்களில்;',	1,	14,	1),
(339,	'That these made war with Bera king of Sodom, and with Birsha king of Gomorrah, Shinab king of Admah, and Shemeber king of Zeboiim, and the king of Bela, which is Zoar.',	'அவர்கள் சோதோமின் ராஜாவாகிய பேராவோடும், கொமோராவின் ராஜாவாகிய பிர்சாவோடும், அத்மாவின் ராஜாவாகிய சிநெயாவோடும், செபோயீமின் ராஜாவாகிய செமேபரோடும், சோவார் என்னும் பேலாவின் ராஜாவோடும் யுத்தம்பண்ணினார்கள்.',	1,	14,	2),
(340,	'All these were joined together in the vale of Siddim, which is the salt sea.',	'இவர்களெல்லாரும் உப்புக்கடலாகிய சித்தீம் பள்ளத்தாக்கிலே கூடினார்கள்.',	1,	14,	3),
(341,	'Twelve years they served Chedorlaomer, and in the thirteenth year they rebelled.',	'இவர்கள் பன்னிரண்டு வருஷம் கெதர்லாகோமேரைச் சேவித்து, பதின்மூன்றாம் வருஷத்திலே கலகம் பண்ணினார்கள்.',	1,	14,	4),
(342,	'And in the fourteenth year came Chedorlaomer, and the kings that were with him, and smote the Rephaims in Ashteroth Karnaim, and the Zuzims in Ham, and the Emins in Shaveh Kiriathaim,',	'பதினாலாம் வருஷத்திலே கெதர்லாகோமேரும், அவனோடே கூடியிருந்த ராஜாக்களும் வந்து, அஸ்தரோத்கர்னாயீமிலே இருந்த ரெப்பாயீமியரையும், காமிலே இருந்த சூசிமியரையும், சாவேகீரியத்தாயீமிலே இருந்த ஏமியரையும்,',	1,	14,	5),
(343,	'And the Horites in their mount Seir, unto Elparan, which is by the wilderness.',	'சேயீர் மலைகளில் இருந்த ஓரியரையும், வனாந்தரத்துக்கு அருகான எல்பாரான்மட்டும் முறியடித்து,',	1,	14,	6),
(344,	'And they returned, and came to Enmishpat, which is Kadesh, and smote all the country of the Amalekites, and also the Amorites, that dwelt in Hazezontamar.',	'திரும்பிக் காதேஸ் என்னும் என்மிஸ்பாத்துக்கு வந்து, அமலேக்கியருடைய நாடனைத்தையும், அத்சாத்சோன் தாமாரிலே குடியிருந்த எமோரியரையும் கூடச் சங்கரித்தார்கள்.',	1,	14,	7),
(345,	'And there went out the king of Sodom, and the king of Gomorrah, and the king of Admah, and the king of Zeboiim, and the king of Bela (the same is Zoar;) and they joined battle with them in the vale of Siddim;',	'அப்பொழுது சோதோமின் ராஜாவும், கொமோராவின் ராஜாவும், அத்மாவின் ராஜாவும், செபோயீமின் ராஜாவும், சோவார் என்னும் பேலாவின் ராஜாவும் புறப்பட்டுச் சித்தீம் பள்ளத்தாக்கிலே,',	1,	14,	8),
(346,	'With Chedorlaomer the king of Elam, and with Tidal king of nations, and Amraphel king of Shinar, and Arioch king of Ellasar; four kings with five.',	'ஏலாமின் ராஜாவாகிய கெதர்லாகோமேரோடும், ஜாதிகளின் ராஜாவாகிய திதியாலோடும், சிநெயாரின் ராஜாவாகிய அம்ராப்பேலோடும், ஏலாசாரின் ராஜாவாகிய அரியோகோடும் யுத்தம்பண்ணப் புறப்பட்டு, அந்த ஐந்து ராஜாக்களோடும் இந்த நாலு ராஜாக்களும் யுத்தம்பண்ணினார்கள்.',	1,	14,	9),
(347,	'And the vale of Siddim was full of slimepits; and the kings of Sodom and Gomorrah fled, and fell there; and they that remained fled to the mountain.',	'அந்தச் சித்தீம் பள்ளத்தாக்கு எங்கும் நிலக்கீல் உண்டாகும் கேணிகள் இருந்தது. சோதோம் கொமோராவின் ராஜாக்கள் முறிந்தோடி அங்கே விழுந்தார்கள்; மீந்தவர்கள் மலைகளுக்கு ஓடிப்போனார்கள்.',	1,	14,	10),
(348,	'And they took all the goods of Sodom and Gomorrah, and all their victuals, and went their way.',	'அப்பொழுது அவர்கள் சோதோமிலும் கோமோராவிலுமுள்ள பொருள்கள் எல்லாவற்றையும், போஜனபதார்த்தங்கள் எல்லாவற்றையும் எடுத்துக்கொண்டு போய்விட்டார்கள்.',	1,	14,	11),
(349,	'And they took Lot, Abram\'s brother\'s son, who dwelt in Sodom, and his goods, and departed.',	'ஆபிராமின் சகோதரனுடைய குமாரனாகிய லோத்து சோதோமிலே குடியிருந்தபடியால், அவனையும், அவன் பொருள்களையும் கொண்டுபோய்விட்டார்கள்.',	1,	14,	12),
(350,	'And there came one that had escaped, and told Abram the Hebrew; for he dwelt in the plain of Mamre the Amorite, brother of Eshcol, and brother of Aner: and these were confederate with Abram.',	'தப்பியோடின ஒருவன் எபிரெயனாகிய ஆபிராமிடத்தில் வந்து அதை அறிவித்தான்; ஆபிராம் தன்னோடே உடன்படிக்கை செய்திருந்த மனிதராகிய எஸ்கோலுக்கும், ஆநேருக்கும் சகோதரனாகிய மம்ரே என்னும் எமோரியனுடைய சமபூமியிலே அப்பொழுது குடியிருந்தான்.',	1,	14,	13),
(351,	'And when Abram heard that his brother was taken captive, he armed his trained servants, born in his own house, three hundred and eighteen, and pursued them unto Dan.',	'தன் சகோதரன் சிறையாகக் கொண்டுபோகப்பட்டதை ஆபிராம் கேள்விப்பட்டபோது, அவன் தன் வீட்டிலே பிறந்த கைபடிந்தவர்களாகிய முந்நூற்றுப் பதினெட்டு ஆட்களுக்கும் ஆயுதம் தரிப்பித்து, தாண் என்னும் ஊர் மட்டும் அவர்களைத் தொடர்ந்து,',	1,	14,	14),
(352,	'And he divided himself against them, he and his servants, by night, and smote them, and pursued them unto Hobah, which is on the left hand of Damascus.',	'இராக்காலத்திலே அவனும், அவன் வேலைக்காரரும் பிரிந்து, பவிஞ்சுகளாய் அவர்கள்மேல் விழுந்து, அவர்களை முறியடித்து, தமஸ்குவுக்கு இடதுபுறமான ஓபாமட்டும் துரத்தி,',	1,	14,	15),
(353,	'And he brought back all the goods, and also brought again his brother Lot, and his goods, and the women also, and the people.',	'சகல பொருள்களையும் திருப்பிக்கொண்டுவந்தான்; தன் சகோதரனாகிய லோத்தையும், அவனுடைய பொருள்களையும், ஸ்திரீகளையும், ஜனங்களையும் திருப்பிக்கொண்டுவந்தான்.',	1,	14,	16),
(354,	'And the king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer, and of the kings that were with him, at the valley of Shaveh, which is the king\'s dale.',	'அவன் கெதர்லாகோமேரையும், அவனோடிருந்த ராஜாக்களையும் முறியடித்துத் திரும்பிவருகிறபோது, சோதோமின் ராஜா புறப்பட்டு, ராஜாவின் பள்ளத்தாக்கு என்னும் சாவே பள்ளத்தாக்குமட்டும் அவனுக்கு எதிர்கொண்டுபோனான்.',	1,	14,	17),
(355,	'And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God.',	'அன்றியும், உன்னதமான தேவனுடைய ஆசாரியனாயிருந்த சாலேமின் ராஜாவாகிய மெல்கிசேதேக்கு அப்பமும் திராட்சரசமும் கொண்டுவந்து,',	1,	14,	18),
(356,	'And he blessed him, and said, Blessed be Abram of the most high God, possessor of heaven and earth:',	'அவனை ஆசீர்வதித்து: வானத்தையும் பூமியையும் உடையவராகிய உன்னதமான தேவனுடைய ஆசீர்வாதம் ஆபிராமுக்கு உண்டாவதாக.',	1,	14,	19),
(357,	'And blessed be the most high God, which hath delivered thine enemies into thy hand. And he gave him tithes of all.',	'உன் சத்துருக்களை உன் கையில் ஒப்புக்கொடுத்த உன்னதமான தேவனுக்கு ஸ்தோத்திரம் என்று சொன்னான். இவனுக்கு ஆபிராம் எல்லாவற்றிலும் தசமபாகம் கொடுத்தான்.',	1,	14,	20),
(358,	'And the king of Sodom said unto Abram, Give me the persons, and take the goods to thyself.',	'சோதோமின் ராஜா ஆபிராமை நோக்கி: ஜனங்களை எனக்குத் தாரும், பொருள்களை நீர் எடுத்துக்கொள்ளும் என்றான்.',	1,	14,	21),
(359,	'And Abram said to the king of Sodom, I have lift up mine hand unto the LORD, the most high God, the possessor of heaven and earth,',	'அதற்கு, ஆபிராம் சோதோமின் ராஜாவைப் பார்த்து; ஆபிராமை ஐசுவரியவனாக்கினேன் என்று நீர் சொல்லாதபடிக்கு நான் ஒரு சரட்டையாகிலும் பாதரட்சையின் வாரையாகிலும், உமக்கு உண்டானவைகளில் யாதொன்றையாகிலும் எடுத்துக்கொள்ளேன் என்று,',	1,	14,	22),
(360,	'That I will not take from a thread even to a shoelatchet, and that I will not take any thing that is thine, lest thou shouldest say, I have made Abram rich:',	'வானத்தையும் பூமியையும் உடையவராகிய உன்னதமான தேவனாகிய கர்த்தருக்கு நேராக என் கையை உயர்த்துகிறேன்.',	1,	14,	23),
(361,	'Save only that which the young men have eaten, and the portion of the men which went with me, Aner, Eshcol, and Mamre; let them take their portion.',	'வாலிபர் சாப்பிட்டதுபோக, என்னுடனே வந்த ஆநேர், எஸ்கோல், மம்ரே என்னும் புருஷருடைய பங்குமாத்திரமே வரவேண்டும்; இவர்கள் தங்கள் பங்கை எடுத்துக்கொள்ளட்டும் என்றான்.  ',	1,	14,	24),
(362,	'After these things the word of the LORD came unto Abram in a vision, saying, Fear not, Abram: I am thy shield, and thy exceeding great reward.',	'இந்தக் காரியங்கள் நடந்தபின்பு, கர்த்தருடைய வார்த்தை ஆபிராமுக்குத் தரிசனத்திலே உண்டாகி, அவர்: ஆபிராமே, நீ பயப்படாதே; நான் உனக்குக் கேடகமும், உனக்கு மகா பெரிய பலனுமாயிருக்கிறேன் என்றார்.',	1,	15,	1),
(363,	'And Abram said, LORD God, what wilt thou give me, seeing I go childless, and the steward of my house is this Eliezer of Damascus?',	'அதற்கு ஆபிராம்: கர்த்தராகிய ஆண்டவரே, அடியேனுக்கு என்ன தருவீர்? நான் பிள்ளையில்லாமல் இருக்கிறேனே; தமஸ்கு ஊரானாகிய இந்த எலியேசர் என் வீட்டு விசாரணைக்கர்த்தனாய் இருக்கிறானே என்றான்.',	1,	15,	2),
(364,	'And Abram said, Behold, to me thou hast given no seed: and, lo, one born in my house is mine heir.',	'பின்னும் ஆபிராம்: தேவரீர் எனக்குப் புத்திரசந்தானம் அருளவில்லை; இதோ என் வீட்டிலே பிறந்த பிள்ளை எனக்குச் சுதந்தரவாளியாய் இருக்கிறான் என்றான்.',	1,	15,	3),
(365,	'And, behold, the word of the LORD came unto him, saying, This shall not be thine heir; but he that shall come forth out of thine own bowels shall be thine heir.',	'அப்பொழுது கர்த்தருடைய வார்த்தை அவனுக்கு உண்டாகி: இவன் உனக்குச் சுதந்தரவாளியல்ல, உன் கர்ப்பப்பிறப்பாயிருப்பவனே உனக்குச் சுதந்தரவாளியாவான் என்று சொல்லி,',	1,	15,	4),
(366,	'And he brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be.',	'அவர் அவனை வெளியே அழைத்து: நீ வானத்தை அண்ணாந்துபார், நட்சத்திரங்களை எண்ண உன்னாலே கூடுமானால், அவைகளை எண்ணு என்று சொல்லி; பின்பு அவனை நோக்கி: உன் சந்ததி இவ்வண்ணமாய் இருக்கும் என்றார்.',	1,	15,	5),
(367,	'And he believed in the LORD; and he counted it to him for righteousness.',	'அவன் கர்த்தரை விசுவாசித்தான், அதை அவர் அவனுக்கு நீதியாக எண்ணினார்.',	1,	15,	6),
(368,	'And he said unto him, I am the LORD that brought thee out of Ur of the Chaldees, to give thee this land to inherit it.',	'பின்னும் அவர் அவனை நோக்கி: இந்தத் தேசத்தை உனக்குச் சுதந்தரமாகக் கொடுக்கும்பொருட்டு, உன்னை ஊர் என்கிற கல்தேயருடைய பட்டணத்திலிருந்து அழைத்துவந்த கர்த்தர் நானே என்றார்.',	1,	15,	7),
(369,	'And he said, LORD God, whereby shall I know that I shall inherit it?',	'அதற்கு அவன்: கர்த்தராகிய ஆண்டவரே, நான் அதைச் சுதந்தரித்துக்கொள்வேன் என்று எதினால் அறிவேன் என்றான்.',	1,	15,	8),
(370,	'And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon.',	'அதற்கு அவர்: மூன்றுவயதுக் கிடாரியையும், மூன்றுவயது வெள்ளாட்டையும், மூன்றுவயது ஆட்டுக்கிடாவையும், ஒரு காட்டுப்புறாவையும், ஒரு புறாக்குஞ்சையும், என்னிடத்தில் கொண்டுவா என்றார்.',	1,	15,	9),
(371,	'And he took unto him all these, and divided them in the midst, and laid each piece one against another: but the birds divided he not.',	'அவன் அவைகள் எல்லாவற்றையும் அவரிடத்தில் கொண்டுவந்து, அவைகளை நடுவாகத் துண்டித்து, துண்டங்களை ஒன்றுக்கொன்று எதிராக வைத்தான்; பட்சிகளை அவன் துண்டிக்கவில்லை.',	1,	15,	10),
(372,	'And when the fowls came down upon the carcases, Abram drove them away.',	'பறவைகள் அந்த உடல்களின்மேல் இறங்கின; அவைகளை ஆபிராம் துரத்தினான்.',	1,	15,	11),
(373,	'And when the sun was going down, a deep sleep fell upon Abram; and, lo, an horror of great darkness fell upon him.',	'சூரியன் அஸ்தமிக்கும்போது, ஆபிராமுக்கு அயர்ந்த நித்திரை வந்தது; திகிலும் காரிருளும் அவனை மூடிக்கொண்டது.',	1,	15,	12),
(374,	'And he said unto Abram, Know of a surety that thy seed shall be a stranger in a land that is not theirs, and shall serve them; and they shall afflict them four hundred years;',	'அப்பொழுது அவர் ஆபிராமை நோக்கி: உன் சந்ததியார் தங்களுடையதல்லாத அந்நிய தேசத்திலே பரதேசிகளாயிருந்து, அத்தேசத்தாரைச் சேவிப்பார்கள் என்றும், அவர்களால் நானூறு வருஷம் உபத்திரவப்படுவார்கள் என்றும், நீ நிச்சயமாய் அறியக்கடவாய்.',	1,	15,	13),
(375,	'And also that nation, whom they shall serve, will I judge: and afterward shall they come out with great substance.',	'இவர்கள் சேவிக்கும் ஜாதிகளை நான் நியாயந்தீர்ப்பேன்; பின்பு மிகுந்த பொருள்களுடனே புறப்பட்டு வருவார்கள்.',	1,	15,	14),
(376,	'And thou shalt go to thy fathers in peace; thou shalt be buried in a good old age.',	'நீ சமாதானத்தோடே உன் பிதாக்களிடத்தில் சேருவாய்; நல்ல முதிர்வயதிலே அடக்கம்பண்ணப்படுவாய்.',	1,	15,	15),
(377,	'But in the fourth generation they shall come hither again: for the iniquity of the Amorites is not yet full.',	'நாலாம் தலைமுறையிலே அவர்கள் இவ்விடத்துக்குத் திரும்ப வருவார்கள்; ஏனென்றால் எமோரியருடைய அக்கிரமம் இன்னும் நிறைவாகவில்லை என்றார்.',	1,	15,	16),
(378,	'And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces.',	'சூரியன் அஸ்தமித்து காரிருள் உண்டானபின்பு, இதோ, புகைகிற சூளையும், அந்தத் துண்டங்களின் நடுவே கடந்துபோகிற அக்கினிஜூவாலையும் தோன்றின.',	1,	15,	17),
(379,	'In the same day the LORD made a covenant with Abram, saying, Unto thy seed have I given this land, from the river of Egypt unto the great river, the river Euphrates:',	'அந்நாளிலே கர்த்தர் ஆபிராமோடே உடன்படிக்கைபண்ணி, எகிப்தின் நதிதுவக்கி ஐபிராத்து நதி என்னும் பெரிய நதிமட்டுமுள்ளதும்,',	1,	15,	18),
(380,	'The Kenites, and the Kenizzites, and the Kadmonites,',	'கேனியரும், கெனிசியரும், கத்மோனியரும்,',	1,	15,	19),
(381,	'And the Hittites, and the Perizzites, and the Rephaims,',	'ஏத்தியரும், பெரிசியரும், ரெப்பாயீமியரும்,',	1,	15,	20),
(382,	'And the Amorites, and the Canaanites, and the Girgashites, and the Jebusites.',	'எமோரியரும், கானானியரும், கிர்காசியரும், எபூசியரும் என்பவர்கள் இருக்கிறதுமான இந்தத் தேசத்தை உன் சந்ததிக்குக் கொடுத்தேன் என்றார்.  ',	1,	15,	21),
(383,	'Now Sarai Abram\'s wife bare him no children: and she had an handmaid, an Egyptian, whose name was Hagar.',	'ஆபிராமுடைய மனைவியாகிய சாராய்க்குப் பிள்ளையில்லாதிருந்தது. எகிப்து தேசத்தாளாகிய ஆகார் என்னும் பேர்கொண்ட ஒரு அடிமைப்பெண் அவளுக்கு இருந்தாள்.',	1,	16,	1),
(384,	'And Sarai said unto Abram, Behold now, the LORD hath restrained me from bearing: I pray thee, go in unto my maid; it may be that I may obtain children by her. And Abram hearkened to the voice of Sarai.',	'சாராய் ஆபிராமை நோக்கி: நான் பிள்ளைபெறாதபடிக்குக் கர்த்தர் என் கர்ப்பத்தை அடைத்திருக்கிறார்; என் அடிமைப்பெண்ணோடே சேரும், ஒருவேளை அவளால் என் வீடு கட்டப்படும் என்றாள். சாராயின் வார்த்தைக்கு ஆபிராம் செவிகொடுத்தான்.',	1,	16,	2),
(385,	'And Sarai Abram\'s wife took Hagar her maid the Egyptian, after Abram had dwelt ten years in the land of Canaan, and gave her to her husband Abram to be his wife.',	'ஆபிராம் கானான்தேசத்தில் பத்து வருஷம் குடியிருந்தபின்பு, ஆபிராமின் மனைவியாகிய சாராய் எகிப்து தேசத்தாளான தன் அடிமைப்பெண்ணாகிய ஆகாரை அழைத்து, அவளைத் தன் புருஷனாகிய ஆபிராமுக்கு மறுமனையாட்டியாகக் கொடுத்தாள்.',	1,	16,	3),
(386,	'And he went in unto Hagar, and she conceived: and when she saw that she had conceived, her mistress was despised in her eyes.',	'அவன் ஆகாரோடே சேர்ந்தபோது, அவள் கர்ப்பந்தரித்தாள்; அவள் தான் கர்ப்பவதியானதைக் கண்டபோது, தன் நாச்சியாரை அற்பமாக எண்ணினாள்.',	1,	16,	4),
(387,	'And Sarai said unto Abram, My wrong be upon thee: I have given my maid into thy bosom; and when she saw that she had conceived, I was despised in her eyes: the LORD judge between me and thee.',	'அப்பொழுது சாராய் ஆபிராமை நோக்கி: எனக்கு நேரிட்ட அநியாயம் உமதுமேல் சுமரும்; என் அடிமைப்பெண்ணை உம்முடைய மடியிலே கொடுத்தேன்; அவள் தான் கர்ப்பவதியானதைக் கண்டு என்னை அற்பமாக எண்ணுகிறாள்; கர்த்தர் எனக்கும் உமக்கும் நடுநின்று நியாயந்தீர்பாராக என்றாள்.',	1,	16,	5),
(388,	'But Abram said unto Sarai, Behold, thy maid is in thine hand; do to her as it pleaseth thee. And when Sarai dealt hardly with her, she fled from her face.',	'அதற்கு ஆபிராம் சாராயை நோக்கி: இதோ, உன் அடிமைப்பெண் உன் கைக்குள் இருக்கிறாள்; உன் பார்வைக்கு நலமானபடி அவளுக்குச் செய் என்றான். அப்பொழுது சாராய் அவளைக் கடினமாய் நடத்தினபடியால் அவள் அவளை விட்டு ஓடிப்போனாள்.',	1,	16,	6),
(389,	'And the angel of the LORD found her by a fountain of water in the wilderness, by the fountain in the way to Shur.',	'கர்த்தருடைய தூதனானவர் அவளை வனாந்தரத்திலே சூருக்குப்போகிற வழியருகே இருக்கிற நீரூற்றண்டையில் கண்டு:',	1,	16,	7),
(390,	'And he said, Hagar, Sarai\'s maid, whence camest thou? and whither wilt thou go? And she said, I flee from the face of my mistress Sarai.',	'சாராயின் அடிமைப்பெண்ணாகிய ஆகாரே, எங்கேயிருந்து வருகிறாய்? எங்கே போகிறாய்? என்று கேட்டார்; அவள்: நான் என் நாச்சியாராகிய சாராயைவிட்டு ஓடிப்போகிறேன் என்றாள்.',	1,	16,	8),
(391,	'And the angel of the LORD said unto her, Return to thy mistress, and submit thyself under her hands.',	'அப்பொழுது கர்த்தருடைய தூதனானவர்: நீ உன் நாச்சியாரண்டைக்குத் திரும்பிப்போய், அவள் கையின்கீழ் அடங்கியிரு என்றார்.',	1,	16,	9),
(392,	'And the angel of the LORD said unto her, I will multiply thy seed exceedingly, that it shall not be numbered for multitude.',	'பின்னும் கர்த்தருடைய தூதனானவர் அவளை நோக்கி: உன் சந்ததியை மிகவும் பெருகப்பண்ணுவேன்; அது பெருகி, எண்ணிமுடியாததாயிருக்கும் என்றார்.',	1,	16,	10),
(393,	'And the angel of the LORD said unto her, Behold, thou art with child and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction.',	'பின்னும் கர்த்தருடைய தூதனானவர் அவளை நோக்கி: நீ கர்ப்பவதியாயிருக்கிறாய், ஒரு குமாரனைப் பெறுவாய்; கர்த்தர் உன் அங்கலாய்ப்பைக் கேட்டபடியினால், அவனுக்கு இஸ்மவேல் என்று பேரிடுவாயாக.',	1,	16,	11),
(394,	'And he will be a wild man; his hand will be against every man, and every man\'s hand against him; and he shall dwell in the presence of all his brethren.',	'அவன் துஷ்டமனுஷனாயிருப்பான்; அவனுடைய கை எல்லாருக்கும் விரோதமாகவும், எல்லாருடைய கையும் அவனுக்கு விரோதமாகவும் இருக்கும்; தன் சகோதரர் எல்லாருக்கும் எதிராகக் குடியிருப்பான் என்றார்.',	1,	16,	12),
(395,	'And she called the name of the LORD that spake unto her, Thou God seest me: for she said, Have I also here looked after him that seeth me?',	'அப்பொழுது அவள்: என்னைக்காண்பவரை நானும் இவ்விடத்தில் கண்டேன் அல்லவா என்று சொல்லி, தன்னோடே பேசின கர்த்தருக்கு நீர் என்னைக்காண்கிற தேவன் என்று பேரிட்டாள்.',	1,	16,	13),
(396,	'Wherefore the well was called Beerlahairoi; behold, it is between Kadesh and Bered.',	'ஆகையால், அந்தத் துரவு பெயர் லகாய்ரோயீ என்னப்பட்டது; அது காதேசுக்கும் பாரேத்துக்கும் நடுவே இருக்கிறது.',	1,	16,	14),
(397,	'And Hagar bare Abram a son: and Abram called his son\'s name, which Hagar bare, Ishmael.',	'ஆகார் ஆபிராமுக்கு ஒரு குமாரனைப் பெற்றாள்; ஆபிராம் ஆகார் பெற்ற தன் குமாரனுக்கு இஸ்மவேல் என்று பேரிட்டான்.',	1,	16,	15),
(398,	'And Abram was fourscore and six years old, when Hagar bare Ishmael to Abram.',	'ஆகார் ஆபிராமுக்கு இஸ்மவேலைப் பெற்றபோது, ஆபிராம் எண்பத்தாறு வயதாயிருந்தான்.  ',	1,	16,	16),
(399,	'And when Abram was ninety years old and nine, the LORD appeared to Abram, and said unto him, I am the Almighty God; walk before me, and be thou perfect.',	'ஆபிராம் தொண்ணூற்றொன்பது வயதானபோது, கர்த்தர் ஆபிராமுக்குத் தரிசனமாகி: நான் சர்வவல்லமையுள்ள தேவன்; நீ எனக்கு முன்பாக நடந்துகொண்டு உத்தமனாயிரு.',	1,	17,	1),
(400,	'And I will make my covenant between me and thee, and will multiply thee exceedingly.',	'நான் உனக்கும் எனக்கும் நடுவாக என் உடன்படிக்கையை ஏற்படுத்தி, உன்னை மிகவும் திரளாய்ப் பெருகப்பண்ணுவேன் என்றார்.',	1,	17,	2),
(401,	'And Abram fell on his face: and God talked with him, saying,',	'அப்பொழுது ஆபிராம் முகங்குப்புற விழுந்து வணங்கினான். தேவன் அவனோடே பேசி:',	1,	17,	3),
(402,	'As for me, behold, my covenant is with thee, and thou shalt be a father of many nations.',	'நான் உன்னோடே பண்ணுகிற என் உடன்படிக்கை என்னவென்றால், நீ திரளான ஜாதிகளுக்குத் தகப்பனாவாய்.',	1,	17,	4),
(403,	'Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee.',	'இனி உன் பேர் ஆபிராம் என்னப்படாமல், நான் உன்னைத் திரளான ஜாதிகளுக்குத் தகப்பனாக ஏற்படுத்தினபடியால், உன் பேர் ஆபிரகாம் என்னப்படும்.',	1,	17,	5),
(404,	'And I will make thee exceeding fruitful, and I will make nations of thee, and kings shall come out of thee.',	'உன்னை மிகவும் அதிகமாய்ப் பலுகப்பண்ணி, உன்னிலே ஜாதிகளை உண்டாக்குவேன்; உன்னிடத்திலிருந்து ராஜாக்கள் தோன்றுவார்கள்.',	1,	17,	6),
(405,	'And I will establish my covenant between me and thee and thy seed after thee in their generations for an everlasting covenant, to be a God unto thee, and to thy seed after thee.',	'உனக்கும் உனக்குப் பின்வரும் உன் சந்ததிக்கும் நான் தேவனாயிருக்கும்படி எனக்கும் உனக்கும், உனக்குப்பின் தலைமுறை தலைமுறையாக வரும் உன் சந்ததிக்கும் நடுவே, என் உடன்படிக்கையை நித்திய உடன்படிக்கையாக ஸ்தாபிப்பேன்.',	1,	17,	7),
(406,	'And I will give unto thee, and to thy seed after thee, the land wherein thou art a stranger, all the land of Canaan, for an everlasting possession; and I will be their God.',	'நீ பரதேசியாய்த் தங்கிவருகிற கானான் தேசமுழுவதையும், உனக்கும் உனக்குப் பின்வரும் உன் சந்ததிக்கும் நித்திய சுதந்தரமாகக் கொடுத்து, நான் அவர்களுக்குத் தேவனாயிருப்பேன் என்றார்.',	1,	17,	8),
(407,	'And God said unto Abraham, Thou shalt keep my covenant therefore, thou, and thy seed after thee in their generations.',	'பின்னும் தேவன் ஆபிரகாமை நோக்கி: இப்பொழுது நீயும், உனக்குப்பின் தலைமுறை தலைமுறையாக வரும் உன் சந்ததியும், என் உடன்படிக்கையைக் கைக்கொள்ளுங்கள்.',	1,	17,	9),
(408,	'This is my covenant, which ye shall keep, between me and you and thy seed after thee; Every man child among you shall be circumcised.',	'எனக்கும் உங்களுக்கும், உனக்குப் பின்வரும் உன் சந்ததிக்கும் நடுவே உண்டாகிறதும், நீங்கள் கைக்கொள்ள வேண்டியதுமான என் உடன்படிக்கை என்னவென்றால், உங்களுக்குள் பிறக்கும் சகல ஆண்பிள்ளைகளும் விருத்தசேதனம்பண்ணப்படவேண்டும்;',	1,	17,	10),
(409,	'And ye shall circumcise the flesh of your foreskin; and it shall be a token of the covenant betwixt me and you.',	'உங்கள் நுனித்தோலின் மாம்சத்தை விருத்தசேதனம்பண்ணக்கடவீர்கள்; அது எனக்கும் உங்களுக்குமுள்ள உடன்படிக்கைக்கு அடையாளமாயிருக்கும்.',	1,	17,	11),
(410,	'And he that is eight days old shall be circumcised among you, every man child in your generations, he that is born in the house, or bought with money of any stranger, which is not of thy seed.',	'உங்களில் தலைமுறை தலைமுறையாகப் பிறக்கும் ஆண்பிள்ளைகளெல்லாம் எட்டாம் நாளிலே விருத்தசேதனம்பண்ணப்படவேண்டும்; வீட்டிலே பிறந்த பிள்ளையும் உன் வித்தல்லாத அந்நியனிடத்தில் பணத்திற்குக் கொள்ளப்பட்ட எந்தப் பிள்ளையும், அப்படியே விருத்தசேதனம்பண்ணப்படவேண்டும்.',	1,	17,	12),
(411,	'He that is born in thy house, and he that is bought with thy money, must needs be circumcised: and my covenant shall be in your flesh for an everlasting covenant.',	'உன் வீட்டிலே பிறந்த பிள்ளையும், உன் பணத்திற்குக் கொள்ளப்பட்டவனும், விருத்தசேதனம்பண்ணப்படவேண்டியது அவசியம்; இப்படி என் உடன்படிக்கை உங்கள் மாம்சத்திலே நித்திய உடன்படிக்கையாக இருக்கக்கடவது.',	1,	17,	13),
(412,	'And the uncircumcised man child whose flesh of his foreskin is not circumcised, that soul shall be cut off from his people; he hath broken my covenant.',	'நுனித்தோலின் மாம்சம் விருத்தசேதனம்பண்ணப்படாதிருக்கிற நுனித்தோலுள்ள ஆண்பிள்ளையிருந்தால், அந்த ஆத்துமா என் உடன்படிக்கையை மீறினபடியால், தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோவான் என்றார்.',	1,	17,	14),
(413,	'And God said unto Abraham, As for Sarai thy wife, thou shalt not call her name Sarai, but Sarah shall her name be.',	'பின்னும் தேவன் ஆபிரகாமை நோக்கி: உன் மனைவி சாராயை இனி சாராய் என்று அழையாதிருப்பாயாக; சாராள் என்பது அவளுக்குப் பேராயிருக்கும்.',	1,	17,	15),
(414,	'And I will bless her, and give thee a son also of her: yea, I will bless her, and she shall be a mother of nations; kings of people shall be of her.',	'நான் அவளை ஆசீர்வதித்து, அவளாலே உனக்கு ஒரு குமாரனையும் தருவேன்; அவள் ஜாதிகளுக்குத் தாயாகவும், அவளாலே ஜாதிகளின் ராஜாக்கள் உண்டாகவும், அவளை ஆசீர்வதிப்பேன் என்றார்.',	1,	17,	16),
(415,	'Then Abraham fell upon his face, and laughed, and said in his heart, Shall a child be born unto him that is an hundred years old? and shall Sarah, that is ninety years old, bear?',	'அப்பொழுது ஆபிரகாம் முகங்குப்புற விழுந்து நகைத்து: நூறுவயதானவனுக்குப் பிள்ளை பிறக்குமோ? தொண்ணூறு வயதான சாராள் பிள்ளை பெறுவாளோ? என்று தன் இருதயத்திலே சொல்லிக்கொண்டு,',	1,	17,	17),
(416,	'And Abraham said unto God, O that Ishmael might live before thee!',	'இஸ்மவேல் உமக்கு முன்பாகப் பிழைப்பானாக! என்று ஆபிரகாம் தேவனிடத்தில் விண்ணப்பம்பண்ணினான்.',	1,	17,	18),
(417,	'And God said, Sarah thy wife shall bear thee a son indeed; and thou shalt call his name Isaac: and I will establish my covenant with him for an everlasting covenant, and with his seed after him.',	'அப்பொழுது தேவன்: உன் மனைவியாகிய சாராள் நிச்சயமாய் உனக்கு ஒரு குமாரனைப் பெறுவாள், அவனுக்கு ஈசாக்கு என்று பேரிடுவாயாக; என் உடன்படிக்கையை அவனுக்கும் அவனுக்குப் பின்வரும் அவன் சந்ததிக்கும் நித்திய உடன்படிக்கையாக ஸ்தாபிப்பேன்.',	1,	17,	19),
(418,	'And as for Ishmael, I have heard thee: Behold, I have blessed him, and will make him fruitful, and will multiply him exceedingly; twelve princes shall he beget, and I will make him a great nation.',	'இஸ்மவேலுக்காகவும் நீ செய்த விண்ணப்பத்தைக் கேட்டேன்; நான் அவனை ஆசீர்வதித்து, அவனை மிகவும் அதிகமாகப் பலுகவும் பெருகவும் பண்ணுவேன்; அவன் பன்னிரண்டு பிரபுக்களைப் பெறுவான்; அவனைப் பெரிய ஜாதியாக்குவேன்.',	1,	17,	20),
(419,	'But my covenant will I establish with Isaac, which Sarah shall bear unto thee at this set time in the next year.',	'வருகிற வருஷத்தில் குறித்தக்காலத்திலே சாராள் உனக்குப் பெறப்போகிற ஈசாக்கோடே நான் என் உடன்படிக்கையை ஏற்படுத்துவேன் என்றார்.',	1,	17,	21),
(420,	'And he left off talking with him, and God went up from Abraham.',	'தேவன் ஆபிரகாமோடே பேசிமுடிந்தபின்பு, அவர் அவனைவிட்டு எழுந்தருளினார்.',	1,	17,	22),
(421,	'And Abraham took Ishmael his son, and all that were born in his house, and all that were bought with his money, every male among the men of Abraham\'s house; and circumcised the flesh of their foreskin in the selfsame day, as God had said unto him.',	'அப்பொழுது ஆபிரகாம் தன் குமாரனாகிய இஸ்மவேலையும், தன் வீட்டிலே பிறந்த யாவரையும், தான் பணத்திற்குக் கொண்ட அனைவருமாகிய தன் வீட்டிலுள்ள ஆண்பிள்ளைகள் எல்லாரையும் சேர்த்து, தேவன் தனக்குச் சொன்னபடி, அவர்கள் நுனித்தோலின் மாம்சத்தை அந்நாளிலேதானே விருத்தசேதனம் பண்ணினான்.',	1,	17,	23),
(422,	'And Abraham was ninety years old and nine, when he was circumcised in the flesh of his foreskin.',	'ஆபிரகாமுடைய நுனித்தோலின் மாம்சம் விருத்தசேதனம்பண்ணப்படும்போது, அவன் தொண்ணூற்றொன்பது வயதாயிருந்தான்.',	1,	17,	24),
(423,	'And Ishmael his son was thirteen years old, when he was circumcised in the flesh of his foreskin.',	'அவனுடைய குமாரன் இஸ்மவேலுடைய நுனித்தோலின் மாம்சம் விருத்தசேதனம் பண்ணப்படும்போது, அவன் பதின்மூன்று வயதாயிருந்தான்.',	1,	17,	25),
(424,	'In the selfsame day was Abraham circumcised, and Ishmael his son.',	'ஒரே நாளில் ஆபிரகாமும் அவன் குமாரன் இஸ்மவேலும் விருத்தசேதனம்பண்ணப்பட்டார்கள்.',	1,	17,	26),
(425,	'And all the men of his house, born in the house, and bought with money of the stranger, were circumcised with him.',	'வீட்டிலே பிறந்தவர்களும் அந்நியரிடத்திலே பணத்திற்குக் கொள்ளப்பட்டவர்களுமாகிய அவன் வீட்டு மனுஷர்கள் எல்லாரும் அவனோடேகூட விருத்தசேதனம்பண்ணப்பட்டார்கள்.  ',	1,	17,	27),
(426,	'And the LORD appeared unto him in the plains of Mamre: and he sat in the tent door in the heat of the day;',	'பின்பு கர்த்தர் மம்ரேயின் சமபூமியிலே அவனுக்குத் தரிசனமானார். அவன் பகலின் உஷ்ணவேளையில் கூடாரவாசலிலே உட்கார்ந்திருந்து,',	1,	18,	1),
(427,	'And he lift up his eyes and looked, and, lo, three men stood by him: and when he saw them, he ran to meet them from the tent door, and bowed himself toward the ground,',	'தன் கண்களை ஏறெடுத்துப் பார்க்கும்போது, இதோ, மூன்று புருஷர் அவனுக்கு எதிரே நின்றார்கள்; அவர்களைக் கண்டவுடனே, அவன் கூடாரவாசலிலிருந்து அவர்களுக்கு எதிர்கொண்டு ஓடித் தரைமட்டும் குனிந்து:',	1,	18,	2),
(428,	'And said, My LORD, if now I have found favour in thy sight, pass not away, I pray thee, from thy servant:',	'ஆண்டவரே, உம்முடைய கண்களில் எனக்குக் கிருபை கிடைத்ததானால், நீர் உமது அடியேனைவிட்டுக் கடந்துபோகவேண்டாம்.',	1,	18,	3),
(429,	'Let a little water, I pray you, be fetched, and wash your feet, and rest yourselves under the tree:',	'கொஞ்சம் தண்ணீர் கொண்டுவரட்டும், உங்கள் கால்களைக் கழுவி, மரத்தடியில் சாய்ந்துகொண்டிருங்கள்.',	1,	18,	4),
(430,	'And I will fetch a morsel of bread, and comfort ye your hearts; after that ye shall pass on: for therefore are ye come to your servant. And they said, So do, as thou hast said.',	'நீங்கள் உங்கள் இருதயங்களைத் திடப்படுத்தக் கொஞ்சம் அப்பம் கொண்டுவருகிறேன்; அப்புறம் நீங்கள் உங்கள் வழியே போகலாம்; இதற்காகவே அடியேன் இடம்வரைக்கும் வந்தீர்கள் என்றான். அதற்கு அவர்கள்: நீ சொன்னபடி செய் என்றார்கள்.',	1,	18,	5),
(431,	'And Abraham hastened into the tent unto Sarah, and said, Make ready quickly three measures of fine meal, knead it, and make cakes upon the hearth.',	'அப்பொழுது ஆபிரகாம் தீவிரமாய்க் கூடாரத்தில் சாராளிடத்திற்குப் போய்: நீ சீக்கிரமாய் மூன்றுபடி மெல்லிய மாவு எடுத்துப் பிசைந்து, அப்பம் சுடு என்றான்.',	1,	18,	6),
(432,	'And Abraham ran unto the herd, and fetcht a calf tender and good, and gave it unto a young man; and he hasted to dress it.',	'ஆபிரகாம் மாட்டுமந்தைக்கு ஓடி, ஒரு நல்ல இளங்கன்றைப் பிடித்து, வேலைக்காரன் கையிலே கொடுத்தான்; அவன் அதைச் சீக்கிரத்தில் சமைத்தான்.',	1,	18,	7),
(433,	'And he took butter, and milk, and the calf which he had dressed, and set it before them; and he stood by them under the tree, and they did eat.',	'ஆபிரகாம் வெண்ணெயையும் பாலையும் சமைப்பித்த கன்றையும் எடுத்து வந்து, அவர்கள் முன்பாக வைத்து, அவர்கள் அருகே மரத்தடியில் நின்றுகொண்டிருந்தான்; அவர்கள் புசித்தார்கள்.',	1,	18,	8),
(434,	'And they said unto him, Where is Sarah thy wife? And he said, Behold, in the tent.',	'அவர்கள் அவனை நோக்கி: உன் மனைவி சாராள் எங்கே என்றார்கள்? அதோ கூடாரத்தில் இருக்கிறாள் என்றான்.',	1,	18,	9),
(435,	'And he said, I will certainly return unto thee according to the time of life; and, lo, Sarah thy wife shall have a son. And Sarah heard it in the tent door, which was behind him.',	'அப்பொழுது அவர்: ஒரு உற்பவகாலத்திட்டத்தில் நிச்சயமாய் உன்னிடத்திற்குத் திரும்ப வருவேன்; அப்பொழுது உன் மனைவியாகிய சாராளுக்கு ஒரு குமாரன் இருப்பான் என்றார். சாராள் அவருக்குப் பின்புறமாய்க் கூடாரவாசலில் இதைக் கேட்டுக்கொண்டிருந்தாள்.',	1,	18,	10),
(436,	'Now Abraham and Sarah were old and well stricken in age; and it ceased to be with Sarah after the manner of women.',	'ஆபிரகாமும் சாராளும் வயது சென்று முதிர்ந்தவர்களாயிருந்தார்கள்; ஸ்திரீகளுக்குள்ள வழிபாடு சாராளுக்கு நின்றுபோயிற்று.',	1,	18,	11),
(437,	'Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?',	'ஆகையால், சாராள் தன் உள்ளத்திலே நகைத்து: நான் கிழவியும், என் ஆண்டவன் முதிர்ந்த வயதுள்ளவருமான பின்பு, எனக்கு இன்பம் உண்டாயிருக்குமோ என்றாள்.',	1,	18,	12),
(438,	'And the LORD said unto Abraham, Wherefore did Sarah laugh, saying, Shall I of a surety bear a child, which am old?',	'அப்பொழுது கர்த்தர் ஆபிரகாமை நோக்கி: சாராள் நகைத்து, நான் கிழவியாயிருக்கப் பிள்ளைபெறுவது மெய்யோ என்று சொல்வானேன்?',	1,	18,	13),
(439,	'Is any thing too hard for the LORD? At the time appointed I will return unto thee, according to the time of life, and Sarah shall have a son.',	'கர்த்தரால் ஆகாத காரியம் உண்டோ? உற்பவகாலத்திட்டத்தில் உன்னிடத்திற்குத் திரும்ப வருவேன்; அப்பொழுது சாராளுக்கு ஒரு குமாரன் இருப்பான் என்றார்.',	1,	18,	14),
(440,	'Then Sarah denied, saying, I laughed not; for she was afraid. And he said, Nay; but thou didst laugh.',	'சாராள் பயந்து, நான் நகைக்கவில்லை என்று மறுத்தாள். அதற்கு அவர்: இல்லை, நீ நகைத்தாய் என்றார்.',	1,	18,	15),
(441,	'And the men rose up from thence, and looked toward Sodom: and Abraham went with them to bring them on the way.',	'பின்பு அந்தப் புருஷர் எழுந்து அவ்விடம் விட்டு, சோதோமை நோக்கிப் போனார்கள்; ஆபிரகாமும் அவர்களோடே கூடப்போய் வழிவிட்டனுப்பினான்.',	1,	18,	16),
(442,	'And the LORD said, Shall I hide from Abraham that thing which I do;',	'அப்பொழுது கர்த்தர்: ஆபிரகாம் பெரிய பலத்த ஜாதியாவதினாலும், அவனுக்குள் பூமியிலுள்ள சகல ஜாதிகளும் ஆசீர்வதிக்கப்படுவதினாலும்,',	1,	18,	17),
(443,	'Seeing that Abraham shall surely become a great and mighty nation, and all the nations of the earth shall be blessed in him?',	'நான் செய்யப்போகிறதை ஆபிரகாமுக்கு மறைப்பேனோ?',	1,	18,	18),
(444,	'For I know him, that he will command his children and his household after him, and they shall keep the way of the LORD, to do justice and judgment; that the LORD may bring upon Abraham that which he hath spoken of him.',	'கர்த்தர் ஆபிரகாமுக்குச் சொன்னதை நிறைவேற்றும்படியாய் அவன் தன் பிள்ளைகளுக்கும், தனக்குப் பின்வரும் தன் வீட்டாருக்கும்: நீங்கள் நீதியையும் நியாயத்தையும் செய்து, கர்த்தருடைய வழியைக் காத்து நடவுங்கள் என்று கட்டளையிடுவான் என்பதை அறிந்திருக்கிறேன் என்றார்.',	1,	18,	19),
(445,	'And the LORD said, Because the cry of Sodom and Gomorrah is great, and because their sin is very grievous;',	'பின்பு கர்த்தர் சோதோம் கொமோராவின் கூக்குரல் பெரிதாயிருப்பதினாலும், அவைகளின் பாவம் மிகவும் கொடிதாயிருப்பதினாலும்,',	1,	18,	20),
(446,	'I will go down now, and see whether they have done altogether according to the cry of it, which is come unto me; and if not, I will know.',	'நான் இறங்கிப்போய், என்னிடத்தில் வந்து எட்டின அதின் கூக்குரலின்படியே அவர்கள் செய்திருக்கிறார்களோ இல்லையோ என்று பார்த்து அறிவேன் என்றார்.',	1,	18,	21),
(447,	'And the men turned their faces from thence, and went toward Sodom: but Abraham stood yet before the LORD.',	'அப்பொழுது அந்தப் புருஷர் அவ்விடம் விட்டுச் சோதோமை நோக்கிப் போனார்கள்; ஆபிரகாமோ பின்னும் கர்த்தருக்கு முன்பாக நின்றுகொண்டிருந்தான்.',	1,	18,	22),
(448,	'And Abraham drew near, and said, Wilt thou also destroy the righteous with the wicked?',	'அப்பொழுது ஆபிரகாம் சமீபமாய்ச் சேர்ந்து: துன்மார்க்கனோடே நீதிமானையும் அழிப்பீரோ?',	1,	18,	23),
(449,	'Peradventure there be fifty righteous within the city: wilt thou also destroy and not spare the place for the fifty righteous that are therein?',	'பட்டணத்துக்குள்ளே ஒருவேளை ஐம்பது நீதிமான்கள் இருப்பார்கள், அதற்குள் இருக்கும் அந்த ஐம்பது நீதிமான்கள் நிமித்தம் இரட்சியாமல் அந்த ஸ்தலத்தை அழிப்பீரோ?',	1,	18,	24),
(450,	'That be far from thee to do after this manner, to slay the righteous with the wicked: and that the righteous should be as the wicked, that be far from thee: Shall not the Judge of all the earth do right?',	'துன்மார்க்கனோடே நீதிமானையும் சங்கரிப்பது உமக்குத் தூரமாயிருப்பதாக; நீதிமானையும் துன்மார்க்கனையும் சமமாய் நடப்பிப்பது உமக்குத் தூரமாயிருப்பதாக; சர்வலோக நியாயாதிபதி நீதிசெய்யாதிருப்பாரோ என்றான்.',	1,	18,	25),
(451,	'And the LORD said, If I find in Sodom fifty righteous within the city, then I will spare all the place for their sakes.',	'அதற்குக் கர்த்தர்: நான் சோதோமில் ஐம்பது நீதிமான்களைக் கண்டால், அவர்கள் நிமித்தம் அந்த ஸ்தலமுழுதையும் இரட்சிப்பேன் என்றார்.',	1,	18,	26),
(452,	'And Abraham answered and said, Behold now, I have taken upon me to speak unto the LORD, which am but dust and ashes:',	'அப்பொழுது ஆபிரகாம் பிரதியுத்தரமாக: இதோ, தூளும் சாம்பலுமாயிருக்கிற அடியேன் ஆண்டவரோடே பேசத்துணிந்தேன்.',	1,	18,	27),
(453,	'Peradventure there shall lack five of the fifty righteous: wilt thou destroy all the city for lack of five? And he said, If I find there forty and five, I will not destroy it.',	'ஒருவேளை ஐம்பது நீதிமான்களுக்கு ஐந்துபேர் குறைந்திருப்பார்கள்; அந்த ஐந்துபேர்நிமித்தம் பட்டணமுழுதையும் அழிப்பீரோ என்றான். அதற்கு அவர்: நான் நாற்பத்தைந்து நீதிமான்களை அங்கே கண்டால், அதை அழிப்பதில்லை என்றார்.',	1,	18,	28),
(454,	'And he spake unto him yet again, and said, Peradventure there shall be forty found there. And he said, I will not do it for forty\'s sake.',	'அவன் பின்னும் அவரோடே பேசி: நாற்பது நீதிமான்கள் அங்கே காணப்பட்டாலோ என்றான். அதற்கு அவர்: நாற்பது நீதிமான்கள்நிமித்தம் அதை அழிப்பதில்லை என்றார்.',	1,	18,	29),
(455,	'And he said unto him, Oh let not the LORD be angry, and I will speak: Peradventure there shall thirty be found there. And he said, I will not do it, if I find thirty there.',	'அப்பொழுது அவன்: நான் இன்னும் பேசுகிறேன், ஆண்டவருக்குக் கோபம் வராமலிருப்பதாக; முப்பது நீதிமான்கள் அங்கே காணப்பட்டாலோ என்றான். அதற்கு அவர்: நான் முப்பது நீதிமான்களை அங்கே கண்டால், அதை அழிப்பதில்லை என்றார்.',	1,	18,	30),
(456,	'And he said, Behold now, I have taken upon me to speak unto the LORD: Peradventure there shall be twenty found there. And he said, I will not destroy it for twenty\'s sake.',	'அப்பொழுது அவன்: இதோ, ஆண்டவரோடே பேசத்துணிந்தேன்; இருபது நீதிமான்கள் அங்கே காணப்பட்டாலோ என்றான். அதற்கு அவர்: இருபது நீதிமான்கள்நிமித்தம் அதை அழிப்பதில்லை என்றார்.',	1,	18,	31),
(457,	'And he said, Oh let not the LORD be angry, and I will speak yet but this once: Peradventure ten shall be found there. And he said, I will not destroy it for ten\'s sake.',	'அப்பொழுது அவன்: ஆண்டவருக்குக் கோபம் வராதிருப்பதாக; நான் இன்னும் இந்த ஒருவிசைமாத்திரம் பேசுகிறேன்; பத்து நீதிமான்கள் அங்கே காணப்பட்டாலோ என்றான். அதற்கு அவர்: பத்து நீதிமான்கள்நிமித்தம் அதை அழிப்பதில்லை என்றார்.',	1,	18,	32),
(458,	'And the LORD went his way, as soon as he had left communing with Abraham: and Abraham returned unto his place.',	'கர்த்தர் ஆபிரகாமோடே பேசிமுடிந்தபின்பு போய்விட்டார்; ஆபிரகாமும் தன்னுடைய இடத்துக்குத் திரும்பினான்.  ',	1,	18,	33),
(459,	'And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground;',	'அந்த இரண்டு தூதரும் சாயங்காலத்திலே சோதோமுக்கு வந்தார்கள். லோத்து சோதோமின் வாசலிலே உட்கார்ந்திருந்தான். அவர்களைக் கண்டு, லோத்து எழுந்து எதிர்கொண்டு தரைமட்டும் குனிந்து:',	1,	19,	1),
(460,	'And he said, Behold now, my lords, turn in, I pray you, into your servant\'s house, and tarry all night, and wash your feet, and ye shall rise up early, and go on your ways. And they said, Nay; but we will abide in the street all night.',	'ஆண்டவன்மார்களே, அடியேனுடைய வீட்டு முகமாய் நீங்கள் திரும்பி, உங்கள் கால்களைக் கழுவி, இராத்தங்கி, காலையில் எழுந்து பிரயாணப்பட்டுப் போகலாம் என்றான். அதற்கு அவர்கள்: அப்படியல்ல, வீதியிலே இராத்தங்குவோம் என்றார்கள்.',	1,	19,	2),
(461,	'And he pressed upon them greatly; and they turned in unto him, and entered into his house; and he made them a feast, and did bake unleavened bread, and they did eat.',	'அவன் அவர்களை மிகவும் வருந்திக்கேட்டுக்கொண்டான்; அப்பொழுது அவனிடத்திற்குத் திரும்பி, அவன் வீட்டிலே பிரவேசித்தார்கள். அவன் புளிப்பில்லா அப்பங்களைச் சுட்டு, அவர்களுக்கு விருந்துபண்ணினான், அவர்கள் புசித்தார்கள்.',	1,	19,	3),
(462,	'But before they lay down, the men of the city, even the men of Sodom, compassed the house round, both old and young, all the people from every quarter:',	'அவர்கள் படுக்கும்முன்னே, சோதோம் பட்டணத்து மனிதராகிய வாலிபர் முதல் கிழவர்மட்டுமுள்ள ஜனங்கள் அனைவரும் நானாதிசைகளிலுமிருந்து வந்து, வீட்டைச் சூழ்ந்துகொண்டு,',	1,	19,	4),
(463,	'And they called unto Lot, and said unto him, Where are the men which came in to thee this night? bring them out unto us, that we may know them.',	'லோத்தைக் கூப்பிட்டு: இந்த இராத்திரி உன்னிடத்தில் வந்த மனுஷர் எங்கே? நாங்கள் அவர்களை அறியும்படிக்கு அவர்களை எங்களிடத்தில் வெளியே கொண்டுவா என்றார்கள்.',	1,	19,	5),
(464,	'And Lot went out at the door unto them, and shut the door after him,',	'அப்பொழுது லோத்து வாசலுக்கு வெளியே வந்து, தனக்குப் பின்னாலே கதவைப் பூட்டி, அவர்களிடத்தில் போய்:',	1,	19,	6),
(465,	'And said, I pray you, brethren, do not so wickedly.',	'சகோதரரே, இந்த அக்கிரமம் செய்யவேண்டாம்.',	1,	19,	7),
(466,	'Behold now, I have two daughters which have not known man; let me, I pray you, bring them out unto you, and do ye to them as is good in your eyes: only unto these men do nothing; for therefore came they under the shadow of my roof.',	'இதோ, புருஷரை அறியாத இரண்டு குமாரத்திகள் எனக்கு உண்டு; அவர்களை உங்களிடத்திற்கு வெளியே கொண்டுவருகிறேன், அவர்களுக்கு உங்கள் இஷ்டப்படி செய்யுங்கள்; இந்தப் புருஷர் என் கூரையின் நிழலிலே வந்தபடியால், இவர்களுக்கு மாத்திரம் ஒன்றும் செய்யவேண்டாம் என்றான்.',	1,	19,	8),
(467,	'And they said, Stand back. And they said again, This one fellow came in to sojourn, and he will needs be a judge: now will we deal worse with thee, than with them. And they pressed sore upon the man, even Lot, and came near to break the door.',	'அதற்கு அவர்கள்: அப்பாலே போ; பரதேசியாய் வந்த இவனா நியாயம் பேசுகிறது? இப்பொழுது அவர்களுக்குச் செய்வதைப்பார்க்கிலும் உனக்கு அதிக பொல்லாப்புச் செய்வோம் என்று சொல்லி, லோத்து என்பவனை மிகவும் நெருக்கிக் கதவை உடைக்கக் கிட்டினார்கள்.',	1,	19,	9),
(468,	'But the men put forth their hand, and pulled Lot into the house to them, and shut to the door.',	'அப்பொழுது அந்தப் புருஷர்கள் தங்கள் கைகளை வெளியே நீட்டி, லோத்தைத் தங்கள் அண்டைக்கு வீட்டுக்குள் இழுத்துக்கொண்டு, கதவைப்பூட்டி,',	1,	19,	10),
(469,	'And they smote the men that were at the door of the house with blindness, both small and great: so that they wearied themselves to find the door.',	'தெருவாசலிலிருந்த சிறியோரும் பெரியோருமாகிய மனிதருக்குக் குருட்டாட்டம் பிடிக்கப்பண்ணினார்கள்; அப்பொழுது அவர்கள் வாசலைத் தேடித்தேடி அலுத்துப்போனார்கள்.',	1,	19,	11),
(470,	'And the men said unto Lot, Hast thou here any besides? son in law, and thy sons, and thy daughters, and whatsoever thou hast in the city, bring them out of this place:',	'பின்பு அந்தப் புருஷர் லோத்தை நோக்கி: இவ்விடத்தில் இன்னும் உனக்கு யார் இருக்கிறார்கள்? மருமகனாவது, உன் குமாரராவது, உன் குமாரத்திகளாவது, பட்டணத்தில் உனக்குரிய எவர்களாவது இருந்தால், அவர்களை இந்த ஸ்தலத்திலிருந்து வெளியே அழைத்துக்கொண்டு போ.',	1,	19,	12),
(471,	'For we will destroy this place, because the cry of them is waxen great before the face of the LORD; and the LORD hath sent us to destroy it.',	'நாங்கள் இந்த ஸ்தலத்தை அழிக்கப்போகிறோம்; இவர்கள் கூக்குரல் கர்த்தருடைய சமூகத்தில் பெரிதாயிருக்கிறது; இதை அழிக்கக் கர்த்தர் எங்களை அனுப்பினார் என்றார்கள்.',	1,	19,	13),
(472,	'And Lot went out, and spake unto his sons in law, which married his daughters, and said, Up, get you out of this place; for the LORD will destroy this city. But he seemed as one that mocked unto his sons in law.',	'அப்பொழுது லோத்து புறப்பட்டு, தன் குமாரத்திகளை விவாகம்பண்ணப்போகிற தன் மருமக்கள்மாரோடே பேசி: நீங்கள் எழுந்து இந்த ஸ்தலத்தை விட்டுப் புறப்படுங்கள்; கர்த்தர் இந்தப் பட்டணத்தை அழிக்கப்போகிறார் என்றான்; அவனுடைய மருமக்கள்மாரின் பார்வைக்கு அவன் பரியாசம்பண்ணுகிறதாகக் கண்டது.',	1,	19,	14),
(473,	'And when the morning arose, then the angels hastened Lot, saying, Arise, take thy wife, and thy two daughters, which are here; lest thou be consumed in the iniquity of the city.',	'கிழக்கு வெளுக்கும்போது அந்தத் தூதர் லோத்தை நோக்கி: பட்டணத்திற்கு வரும் தண்டனையில் நீ அழியாதபடிக்கு எழுந்து, உன் மனைவியையும், இங்கே இருக்கிற உன் இரண்டு குமாரத்திகளையும் அழைத்துக்கொண்டுபோ என்று சொல்லி, அவனைத் துரிதப்படுத்தினார்கள்.',	1,	19,	15),
(474,	'And while he lingered, the men laid hold upon his hand, and upon the hand of his wife, and upon the hand of his two daughters; the LORD being merciful unto him: and they brought him forth, and set him without the city.',	'அவன் தாமதித்துக்கொண்டிருக்கும்போது, கர்த்தர் அவன்மேல் வைத்த இரக்கத்தினாலே, அந்தப் புருஷர் அவன் கையையும், அவன் மனைவியின் கையையும், அவன் இரண்டு குமாரத்திகளின் கையையும் பிடித்து, அவனைப் பட்டணத்திற்கு வெளியே கொண்டுபோய் விட்டார்கள்.',	1,	19,	16),
(475,	'And it came to pass, when they had brought them forth abroad, that he said, Escape for thy life; look not behind thee, neither stay thou in all the plain; escape to the mountain, lest thou be consumed.',	'அவர்களை வெளியே கொண்டுபோய்விட்டபின்பு, அவர்: உன் ஜீவன் தப்ப ஓடிப்போ, பின்னிட்டுப் பாராதே; இந்தச் சமபூமியில் எங்கும் நில்லாதே; நீ அழியாதபடிக்கு மலைக்கு ஓடிப்போ என்றார்.',	1,	19,	17),
(476,	'And Lot said unto them, Oh, not so, my LORD:',	'அதற்கு லோத்து: அப்படியல்ல ஆண்டவரே,',	1,	19,	18),
(477,	'Behold now, thy servant hath found grace in thy sight, and thou hast magnified thy mercy, which thou hast shewed unto me in saving my life; and I cannot escape to the mountain, lest some evil take me, and I die:',	'உமது கண்களில் உமது அடியேனுக்குக் கிருபைகிடைத்ததே; என் பிராணனைக் காக்கத் தேவரீர் எனக்குச் செய்த கிருபையைப் பெரிதாக விளங்கப்பண்ணினீர்; மலைக்கு ஓடிப்போக என்னால் முடியாது, தீங்கு என்னைத் தொடரும், நான் மரித்துப்போவேன்.',	1,	19,	19),
(478,	'Behold now, this city is near to flee unto, and it is a little one: Oh, let me escape thither, (is it not a little one?) and my soul shall live.',	'அதோ, அந்த ஊர் இருக்கிறதே, நான் அதற்கு ஓடிப்போகத்தக்கதாய் அது கிட்ட இருக்கிறது, சின்னதுமாய் இருக்கிறது; என் பிராணன் பிழைக்க நான் அங்கே ஓடிப்போகட்டும், அது சின்ன ஊர்தானே என்றான்.',	1,	19,	20),
(479,	'And he said unto him, See, I have accepted thee concerning this thing also, that I will not overthrow this city, for the which thou hast spoken.',	'அதற்கு அவர்: நீ கேட்டுக்கொண்ட ஊரை நான் கவிழ்த்துப்போடாதபடிக்கு, இந்த விஷயத்திலும் உனக்கு அநுக்கிரகம் பண்ணினேன்.',	1,	19,	21),
(480,	'Haste thee, escape thither; for I cannot do anything till thou be come thither. Therefore the name of the city was called Zoar.',	'தீவிரமாய் அங்கே ஓடித் தப்பித்துக்கொள்; நீ அங்கே போய்ச் சேருமட்டும் நான் ஒன்றும் செய்யக்கூடாது என்றார்; ஆகையால் அந்த ஊர் சோவார் என்னப்பட்டது.',	1,	19,	22),
(481,	'The sun was risen upon the earth when Lot entered into Zoar.',	'லோத்து சோவாருக்குள் வரும்போது பூமியின்மேல் சூரியன் உதித்தது.',	1,	19,	23),
(482,	'Then the LORD rained upon Sodom and upon Gomorrah brimstone and fire from the LORD out of heaven;',	'அப்பொழுது கர்த்தர் சோதோமின் மேலும் கொமோராவின்மேலும், கர்த்தராலே வானத்திலிருந்து கந்தகத்தையும் அக்கினியையும் வருஷிக்கப்பண்ணி,',	1,	19,	24),
(483,	'And he overthrew those cities, and all the plain, and all the inhabitants of the cities, and that which grew upon the ground.',	'அந்தப் பட்டணங்களையும், அந்தச் சமபூமியனைத்தையும், அந்தப் பட்டணங்களின் எல்லாக் குடிகளையும், பூமியின் பயிரையும் அழித்துப்போட்டார்.',	1,	19,	25),
(484,	'But his wife looked back from behind him, and she became a pillar of salt.',	'அவன் மனைவியோ பின்னிட்டுப்பார்த்து, உப்புத்தூண் ஆனாள்.',	1,	19,	26),
(485,	'And Abraham gat up early in the morning to the place where he stood before the LORD:',	'விடியற்காலத்தில் ஆபிரகாம் எழுந்து தான் கர்த்தருக்கு முன்பாக நின்ற இடத்திற்குப் போய்,',	1,	19,	27),
(486,	'And he looked toward Sodom and Gomorrah, and toward all the land of the plain, and beheld, and, lo, the smoke of the country went up as the smoke of a furnace.',	'சோதோம் கொமோரா பட்டணங்களின் திசையையும், சமபூமியாகிய தேசம் முழுவதையும் நோக்கிப் பார்த்தான்; அந்தப் பூமியின் புகை சூளையின் புகையைப்போல எழும்பிற்று.',	1,	19,	28),
(487,	'And it came to pass, when God destroyed the cities of the plain, that God remembered Abraham, and sent Lot out of the midst of the overthrow, when he overthrew the cities in the which Lot dwelt.',	'தேவன் அந்தச் சமபூமியின் பட்டணங்களை அழிக்கும்போது, தேவன் ஆபிரகாமை நினைத்து, லோத்து குடியிருந்த பட்டணங்களைத் தாம் கவிழ்த்துப்போடுகையில், லோத்தை அந்த அழிவின் நடுவிலிருந்து தப்பிப்போகும்படி அனுப்பிவிட்டார்.',	1,	19,	29),
(488,	'And Lot went up out of Zoar, and dwelt in the mountain, and his two daughters with him; for he feared to dwell in Zoar: and he dwelt in a cave, he and his two daughters.',	'பின்பு லோத்து சோவாரிலே குடியிருக்கப் பயந்து, சோவாரை விட்டுப்போய், அவனும் அவனோடேகூட அவனுடைய இரண்டு குமாரத்திகளும் மலையிலே வாசம்பண்ணினார்கள்; அங்கே அவனும் அவனுடைய இரண்டு குமாரத்திகளும் ஒரு கெபியிலே குடியிருந்தார்கள்.',	1,	19,	30),
(489,	'And the firstborn said unto the younger, Our father is old, and there is not a man in the earth to come in unto us after the manner of all the earth:',	'அப்பொழுது மூத்தவள் இளையவளைப் பார்த்து: நம்முடைய தகப்பன் முதிர்வயதானார், பூமியெங்கும் நடக்கிற முறைமையின்படியே நம்மோடே சேரப்பூமியிலே ஒரு புருஷனும் இல்லை.',	1,	19,	31),
(490,	'Come, let us make our father drink wine, and we will lie with him, that we may preserve seed of our father.',	'நம்முடைய தகப்பனால் சந்ததி உண்டாகும்படிக்கு, அவருக்கு மதுவைக் குடிக்கக்கொடுத்து, அவரோடே சயனிப்போம் வா என்றாள்.',	1,	19,	32),
(491,	'And they made their father drink wine that night: and the firstborn went in, and lay with her father; and he perceived not when she lay down, nor when she arose.',	'அப்படியே அன்று இரவிலே, தங்கள் தகப்பனுக்கு மதுவைக் குடிக்கக் கொடுத்தார்கள். மூத்தவள் போய், தன் தகப்பனோடே சயனித்தாள்: அவள் சயனித்ததையும் எழுந்திருந்ததையும் அவன் உணராதிருந்தான்.',	1,	19,	33),
(492,	'And it came to pass on the morrow, that the firstborn said unto the younger, Behold, I lay yesternight with my father: let us make him drink wine this night also; and go thou in, and lie with him, that we may preserve seed of our father.',	'மறுநாளிலே மூத்தவள் இளையவளைப் பார்த்து: நேற்று ராத்திரி நான் தகப்பனோடே சயனித்தேன்; இன்று ராத்திரியும் மதுவைக் குடிக்கக்கொடுப்போம், நம்முடைய தகப்பனால் சந்ததி உண்டாகும்படி நீ போய் அவரோடே சயனி என்றாள்.',	1,	19,	34),
(493,	'And they made their father drink wine that night also: and the younger arose, and lay with him; and he perceived not when she lay down, nor when she arose.',	'அப்படியே அன்று ராத்திரியிலும் தங்கள் தகப்பனுக்கு மதுவைக் குடிக்கக் கொடுத்தார்கள். அப்பொழுது இளையவள் எழுந்துபோய், அவனோடே சயனித்தாள்; அவள் சயனித்ததையும் எழுந்திருந்ததையும் அவன் உணராதிருந்தான்.',	1,	19,	35),
(494,	'Thus were both the daughters of Lot with child by their father.',	'இவ்விதமாய் லோத்தின் குமாரத்திகள் இருவரும் தங்கள் தகப்பனாலே கர்ப்பவதியானார்கள்.',	1,	19,	36),
(495,	'And the first born bare a son, and called his name Moab: the same is the father of the Moabites unto this day.',	'மூத்தவள் ஒரு குமாரனைப்பெற்று, அவனுக்கு மோவாப் என்று பேரிட்டாள்; அவன் இந்நாள்வரைக்கும் இருக்கிற மோவாபியருக்குத் தகப்பன்.',	1,	19,	37),
(496,	'And the younger, she also bare a son, and called his name Benammi: the same is the father of the children of Ammon unto this day.',	'இளையவளும் ஒரு குமாரனைப்பெற்று, அவனுக்குப் பென்னம்மி என்று பேரிட்டாள்; அவன் இந்நாள்வரைக்கும் இருக்கிற அம்மோன் புத்திரருக்குத் தகப்பன்.  ',	1,	19,	38),
(497,	'And Abraham journeyed from thence toward the south country, and dwelled between Kadesh and Shur, and sojourned in Gerar.',	'ஆபிரகாம் அவ்விடம் விட்டு, தென்தேசத்திற்குப் பிரயாணம்பண்ணி, காதேசுக்கும் சூருக்கும் நடுவாகக் குடியேறி, கேராரிலே தங்கினான்.',	1,	20,	1),
(498,	'And Abraham said of Sarah his wife, She is my sister: and Abimelech king of Gerar sent, and took Sarah.',	'அங்கே ஆபிரகாம் தன் மனைவியாகிய சாராளைத் தன் சகோதரி என்று சொன்னதினாலே, கேராரின் ராஜாவாகிய அபிமெலேக்கு ஆள் அனுப்பிச் சாராளை அழைப்பித்தான்.',	1,	20,	2),
(499,	'But God came to Abimelech in a dream by night, and said to him, Behold, thou art but a dead man, for the woman which thou hast taken; for she is a man\'s wife.',	'தேவன் இரவிலே அபிமெலேக்குக்குச் சொப்பனத்திலே தோன்றி: நீ அழைப்பித்த ஸ்திரீயின்நிமித்தம் நீ செத்தாய்; அவள் ஒருவனுடைய மனைவியாயிருக்கிறாளே என்றார்.',	1,	20,	3),
(500,	'But Abimelech had not come near her: and he said, LORD, wilt thou slay also a righteous nation?',	'அபிமெலேக்கு அவளைச் சேராதிருந்தான். ஆகையால் அவன்: ஆண்டவரே, நீதியுள்ள ஜனங்களை அழிப்பீரோ?',	1,	20,	4),
(501,	'Said he not unto me, She is my sister? and she, even she herself said, He is my brother: in the integrity of my heart and innocency of my hands have I done this.',	'இவள் தன் சகோதரி என்று அவன் என்னோடே சொல்லவில்லையா? அவன் தன் சகோதரன் என்று இவளும் சொன்னாளே; உத்தம இருதயத்தோடும் சுத்தமான கைகளோடும் இதைச் செய்தேன் என்று சொன்னான்.',	1,	20,	5),
(502,	'And God said unto him in a dream, Yea, I know that thou didst this in the integrity of thy heart; for I also withheld thee from sinning against me: therefore suffered I thee not to touch her.',	'அப்பொழுது தேவன்: உத்தம இருதயத்தோடே நீ இதைச் செய்தாய் என்று நான் அறிந்திருக்கிறேன்; நீ எனக்கு விரோதமாகப் பாவம் செய்யாதபடிக்கு உன்னைத் தடுத்தேன்; ஆகையால், நீ அவளைத் தொட நான் உனக்கு இடங்கொடுக்கவில்லை.',	1,	20,	6),
(503,	'Now therefore restore the man his wife; for he is a prophet, and he shall pray for thee, and thou shalt live: and if thou restore her not, know thou that thou shalt surely die, thou, and all that are thine.',	'அந்த மனுஷனுடைய மனைவியை அவனிடத்திற்கு அனுப்பிவிடு; அவன் ஒரு தீர்க்கதரிசி; நீ பிழைக்கும்படிக்கு அவன் உனக்காக வேண்டுதல் செய்வான்; நீ அவளை அனுப்பிவிடாதிருந்தால், நீயும் உன்னைச் சேர்ந்த யாவரும் சாகவே சாவீர்கள் என்று அறிவாயாக என்று சொப்பனத்திலே அவனுக்குச் சொன்னார்.',	1,	20,	7),
(504,	'Therefore Abimelech rose early in the morning, and called all his servants, and told all these things in their ears: and the men were sore afraid.',	'அபிமெலேக்கு அதிகாலையில் எழுந்து, தன் ஊழியக்காரரையெல்லாம் அழைப்பித்து, இந்தச் சங்கதிகளையெல்லாம் அவர்கள் கேட்கும்படி சொன்னான்; அந்த மனுஷர் மிகவும் பயந்தார்கள்.',	1,	20,	8),
(505,	'Then Abimelech called Abraham, and said unto him, What hast thou done unto us? and what have I offended thee, that thou hast brought on me and on my kingdom a great sin? thou hast done deeds unto me that ought not to be done.',	'அப்பொழுது அபிமெலேக்கு ஆபிரகாமை அழைப்பித்து: நீ எங்களுக்கு என்ன காரியஞ்செய்தாய், நீ என்மேலும், என் ராஜ்யத்தின்மேலும் கொடிய பாவம் சுமரப்பண்ணுகிறதற்கு உனக்கு நான் என்ன குற்றம் செய்தேன்? செய்யத்தகாத காரியங்களை என்னிடத்தில் செய்தாயே என்றான்.',	1,	20,	9),
(506,	'And Abimelech said unto Abraham, What sawest thou, that thou hast done this thing?',	'பின்னும் அபிமெலேக்கு ஆபிரகாமை நோக்கி: என்னத்தைக் கண்டு நீ இந்தக் காரியத்தைச் செய்தாய் என்றான்.',	1,	20,	10),
(507,	'And Abraham said, Because I thought, Surely the fear of God is not in this place; and they will slay me for my wife\'s sake.',	'அதற்கு ஆபிரகாம்: இவ்விடத்தில் தெய்வபயம் இல்லையென்றும், என் மனைவியினிமித்தம் என்னைக் கொன்றுபோடுவார்கள் என்றும் நான் நினைத்தேன்.',	1,	20,	11),
(508,	'And yet indeed she is my sister; she is the daughter of my father, but not the daughter of my mother; and she became my wife.',	'அவள் என் சகோதரி என்பதும் மெய்தான்; அவள் என் தகப்பனுக்குக் குமாரத்தி, என் தாய்க்குக் குமாரத்தியல்ல; அவள் எனக்கு மனைவியானாள்.',	1,	20,	12),
(509,	'And it came to pass, when God caused me to wander from my father\'s house, that I said unto her, This is thy kindness which thou shalt shew unto me; at every place whither we shall come, say of me, He is my brother.',	'என் தகப்பன் வீட்டைவிட்டு தேவன் என்னைத் தேசாந்தரியாய்த்திரியும்படி செய்தபோது, நான் அவளை நோக்கி: நாம் போகும் இடமெங்கும், நீ என்னைச் சகோதரன் என்று சொல்வது நீ எனக்குச் செய்யவேண்டிய தயை என்று அவளிடத்தில் சொல்லியிருந்தேன் என்றான்.',	1,	20,	13),
(510,	'And Abimelech took sheep, and oxen, and menservants, and womenservants, and gave them unto Abraham, and restored him Sarah his wife.',	'அப்பொழுது அபிமெலேக்கு ஆடுமாடுகளையும், வேலைக்காரரையும், வேலைக்காரிகளையும் ஆபிரகாமுக்குக் கொடுத்து, அவன் மனைவியாகிய சாராளையும் அவனிடத்தில் திரும்ப ஒப்புவித்தான்.',	1,	20,	14),
(511,	'And Abimelech said, Behold, my land is before thee: dwell where it pleaseth thee.',	'பின்னும் அபிமெலேக்கு: இதோ, என் தேசம் உனக்கு முன்பாக இருக்கிறது; உன் பார்வைக்குச் சம்மதியான இடத்திலே குடியிரு என்று சொன்னான்.',	1,	20,	15),
(512,	'And unto Sarah he said, Behold, I have given thy brother a thousand pieces of silver: behold, he is to thee a covering of the eyes, unto all that are with thee, and with all other: thus she was reproved.',	'பின்பு சாராளை நோக்கி: உன் சகோதரனுக்கு ஆயிரம் வெள்ளிக்காசு கொடுத்தேன்; இதோ, உன்னோடிருக்கிற எல்லார் முன்பாகவும், மற்ற யாவர் முன்பாகவும், இது உன் முகத்து முக்காட்டுக்காவதாக என்றான்; இப்படி அவள் கடிந்துகொள்ளப்பட்டாள்.',	1,	20,	16),
(513,	'So Abraham prayed unto God: and God healed Abimelech, and his wife, and his maidservants; and they bare children.',	'ஆபிரகாமுடைய மனைவியாகிய சாராளின் நிமித்தம் கர்த்தர் அபிமெலேக்குடைய வீட்டாரின் கர்ப்பங்களையெல்லாம் அடைத்திருந்தபடியால்,',	1,	20,	17),
(514,	'For the LORD had fast closed up all the wombs of the house of Abimelech, because of Sarah Abraham\'s wife.',	'ஆபிரகாம் தேவனை நோக்கி வேண்டிக்கொண்டான்; அப்பொழுது தேவன் அபிமெலேக்கையும், அவன் மனைவியையும், அவன் வேலைக்காரிகளையும் குணமாக்கி, பிள்ளைபெறும்படி அநுக்கிரகம் பண்ணினார்.  ',	1,	20,	18),
(515,	'And the LORD visited Sarah as he had said, and the LORD did unto Sarah as he had spoken.',	'கர்த்தர் தாம் சொல்லியிருந்தபடி சாராள்பேரில் கடாட்சமானார்; கர்த்தர் தாம் உரைத்தபடியே சாராளுக்குச் செய்தருளினார்.',	1,	21,	1),
(516,	'For Sarah conceived, and bare Abraham a son in his old age, at the set time of which God had spoken to him.',	'ஆபிரகாம் முதிர்வயதாயிருக்கையில், சாராள் கர்ப்பவதியாகி, தேவன் குறித்திருந்த காலத்திலே அவனுக்கு ஒரு குமாரனைப் பெற்றாள்.',	1,	21,	2),
(517,	'And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac.',	'அப்பொழுது ஆபிரகாம் தனக்குச் சாராள் பெற்ற குமாரனுக்கு ஈசாக்கு என்று பேரிட்டான்.',	1,	21,	3),
(518,	'And Abraham circumcised his son Isaac being eight days old, as God had commanded him.',	'தன் குமாரனாகிய ஈசாக்கு பிறந்த எட்டாம் நாளிலே, ஆபிரகாம் தனக்குத் தேவன் கட்டளையிட்டிருந்தபடி அவனுக்கு விருத்தசேதனம்பண்ணினான்.',	1,	21,	4),
(519,	'And Abraham was an hundred years old, when his son Isaac was born unto him.',	'தன் குமாரனாகிய ஈசாக்கு பிறந்தபோது ஆபிரகாம் நூறுவயதாயிருந்தான்.',	1,	21,	5),
(520,	'And Sarah said, God hath made me to laugh, so that all that hear will laugh with me.',	'அப்பொழுது சாராள்: தேவன் என்னை நகைக்கப்பண்ணினார்; இதைக்கேட்கிற யாவரும் என்னோடகூட நகைப்பார்கள்.',	1,	21,	6),
(521,	'And she said, Who would have said unto Abraham, that Sarah should have given children suck? for I have born him a son in his old age.',	'சாராள் பிள்ளைகளுக்குப் பால்கொடுப்பாள் என்று ஆபிரகாமுக்கு எவன் சொல்லுவான்? அவருடைய முதிர்வயதிலே அவருக்கு ஒரு குமாரனைப் பெற்றேனே என்றாள்.',	1,	21,	7),
(522,	'And the child grew, and was weaned: and Abraham made a great feast the same day that Isaac was weaned.',	'பிள்ளை வளர்ந்து, பால் மறந்தது; ஈசாக்கு பால் மறந்தநாளிலே ஆபிரகாம் பெரிய விருந்து பண்ணினான்.',	1,	21,	8),
(523,	'And Sarah saw the son of Hagar the Egyptian, which she had born unto Abraham, mocking.',	'பின்பு எகிப்து தேசத்தாளாகிய ஆகார் ஆபிரகாமுக்குப் பெற்ற குமாரன் பரியாசம்பண்ணுகிறதைச் சாராள் கண்டு,',	1,	21,	9),
(524,	'Wherefore she said unto Abraham, Cast out this bondwoman and her son: for the son of this bondwoman shall not be heir with my son, even with Isaac.',	'ஆபிரகாமை நோக்கி: இந்த அடிமைப்பெண்ணையும் அவள் மகனையும் புறம்பே தள்ளும்; இந்த அடிமைப்பெண்ணின் மகன் என் குமாரனாகிய ஈசாக்கோடே சுதந்திரவாளியாயிருப்பதில்லை என்றாள்.',	1,	21,	10),
(525,	'And the thing was very grievous in Abraham\'s sight because of his son.',	'தன் மகனைக்குறித்துச் சொல்லப்பட்ட இந்தக் காரியம் ஆபிரகாமுக்கு மிகவும் துக்கமாயிருந்தது.',	1,	21,	11),
(526,	'And God said unto Abraham, Let it not be grievous in thy sight because of the lad, and because of thy bondwoman; in all that Sarah hath said unto thee, hearken unto her voice; for in Isaac shall thy seed be called.',	'அப்பொழுது தேவன் ஆபிரகாமை நோக்கி: அந்தப் பிள்ளையையும், உன் அடிமைப்பெண்ணையும் குறித்துச் சொல்லப்பட்டது உனக்குத் துக்கமாயிருக்க வேண்டாம்; ஈசாக்கினிடத்தில் உன் சந்ததி விளங்கும்; ஆதலால் சாராள் உனக்குச் சொல்வதெல்லாவற்றையும் கேள்.',	1,	21,	12),
(527,	'And also of the son of the bondwoman will I make a nation, because he is thy seed.',	'அடிமைப்பெண்ணின் மகனும் உன் வித்தாயிருக்கிறபடியால், அவனையும் ஒரு ஜாதியாக்குவேன் என்றார்.',	1,	21,	13),
(528,	'And Abraham rose up early in the morning, and took bread, and a bottle of water, and gave it unto Hagar, putting it on her shoulder, and the child, and sent her away: and she departed, and wandered in the wilderness of Beersheba.',	'ஆபிரகாம் அதிகாலையில் எழுந்து, அப்பத்தையும் ஒரு துருத்தி தண்ணீரையும் எடுத்து, ஆகாருடைய தோளின்மேல் வைத்துப் பிள்ளையையும் ஒப்புக்கொடுத்து, அவளை அனுப்பிவிட்டான்; அவள் புறப்பட்டுப்போய், பெயர்செபாவின் வனாந்தரத்திலே அலைந்து திரிந்தாள்.',	1,	21,	14),
(529,	'And the water was spent in the bottle, and she cast the child under one of the shrubs.',	'துருத்தியிலிருந்த தண்ணீர் செலவழிந்தபின்பு, அவள் பிள்ளையை ஒரு செடியின் கீழே விட்டு,',	1,	21,	15),
(530,	'And she went, and sat her down over against him a good way off, as it were a bow shot: for she said, Let me not see the death of the child. And she sat over against him, and lift up her voice, and wept.',	'பிள்ளை சாகிறதை நான் பார்க்கமாட்டேன் என்று, எதிராக அம்பு பாயும் தூரத்திலே போய் உட்கார்ந்து சத்தமிட்டு அழுதாள்.',	1,	21,	16),
(531,	'And God heard the voice of the lad; and the angel of God called to Hagar out of heaven, and said unto her, What aileth thee, Hagar? fear not; for God hath heard the voice of the lad where he is.',	'தேவன் பிள்ளையின் சத்தத்தைக் கேட்டார்; தேவதூதன் வானத்திலிருந்து ஆகாரைக் கூப்பிட்டு: ஆகாரே, உனக்கு என்ன சம்பவித்தது, பயப்படாதே, பிள்ளையிருக்கும் இடத்திலே தேவன் அவன் சத்தத்தைக் கேட்டார்.',	1,	21,	17),
(532,	'Arise, lift up the lad, and hold him in thine hand; for I will make him a great nation.',	'நீ எழுந்து பிள்ளையை எடுத்து அவனை உன் கையினால் பிடித்துக் கொண்டுபோ, அவனைப் பெரிய ஜாதியாக்குவேன் என்றார்.',	1,	21,	18),
(533,	'And God opened her eyes, and she saw a well of water; and she went, and filled the bottle with water, and gave the lad drink.',	'தேவன் அவளுடைய கண்களைத் திறந்தார்; அப்பொழுது அவள் ஒரு தண்ணீர்த் துரவைக் கண்டு, போய், துருத்தியிலே தண்ணீர் நிரப்பி, பிள்ளைக்குக் குடிக்கக் கொடுத்தாள்.',	1,	21,	19),
(534,	'And God was with the lad; and he grew, and dwelt in the wilderness, and became an archer.',	'தேவன் பிள்ளையுடனே இருந்தார்; அவன் வளர்ந்து வனாந்தரத்திலே குடியிருந்து வில்வித்தையிலே வல்லவனானான்.',	1,	21,	20),
(535,	'And he dwelt in the wilderness of Paran: and his mother took him a wife out of the land of Egypt.',	'அவன் பாரான் வனாந்தரத்திலே குடியிருக்கையில், அவனுடைய தாய் எகிப்து தேசத்தாளாகிய ஒரு பெண்ணை அவனுக்கு விவாகம்பண்ணுவித்தாள்.',	1,	21,	21),
(536,	'And it came to pass at that time, that Abimelech and Phichol the chief captain of his host spake unto Abraham, saying, God is with thee in all that thou doest:',	'அக்காலத்தில் அபிமெலேக்கும் அவன் சேனாதிபதியாகிய பிகோலும் ஆபிரகாமை நோக்கி: நீ செய்கிற காரியங்கள் எல்லாவற்றிலும் தேவன் உன்னுடனே இருக்கிறார்.',	1,	21,	22),
(537,	'Now therefore swear unto me here by God that thou wilt not deal falsely with me, nor with my son, nor with my son\'s son: but according to the kindness that I have done unto thee, thou shalt do unto me, and to the land wherein thou hast sojourned.',	'ஆகையால், நீ எனக்காவது, என் குமாரனுக்காவது, என் பேரனுக்காவது வஞ்சனை செய்யாமல், நான் உனக்குச் செய்த தயவின்படியே, நீ எனக்கும், நீ தங்கியிருக்கிற இந்தத் தேசத்திற்கும், தயவு செய்வேன் என்று இங்கே தேவன் பேரில் எனக்கு ஆணையிட்டுக்கொடு என்றான்.',	1,	21,	23),
(538,	'And Abraham said, I will swear.',	'அதற்கு ஆபிரகாம்: நான் ஆணையிட்டுக்கொடுக்கிறேன் என்றான்.',	1,	21,	24),
(539,	'And Abraham reproved Abimelech because of a well of water, which Abimelech\'s servants had violently taken away.',	'ஆனாலும், அபிமெலேக்குடைய வேலைக்காரர் கைவசப்படுத்திக்கொண்ட துரவின் நிமித்தம் ஆபிரகாம் அபிமெலேக்கைக் கடிந்துகொண்டான்.',	1,	21,	25),
(540,	'And Abimelech said, I wot not who hath done this thing; neither didst thou tell me, neither yet heard I of it, but to day.',	'அதற்கு அபிமெலேக்கு: இந்தக் காரியத்தைச் செய்தவன் இன்னான் என்று எனக்குத் தெரியாது, நீயும் எனக்கு அறிவிக்கவில்லை; இன்று நான் அதைக்கேட்டதேயன்றி, இதற்குமுன் அதை நான் கேள்விப்பட்டதே இல்லை என்றான்.',	1,	21,	26),
(541,	'And Abraham took sheep and oxen, and gave them unto Abimelech; and both of them made a covenant.',	'அப்பொழுது ஆபிரகாம் ஆடுமாடுகளைக் கொண்டுவந்து அபிமெலேக்குக்குக் கொடுத்தான்; அவர்கள் இருவரும் உடன்படிக்கை பண்ணிக்கொண்டார்கள்.',	1,	21,	27),
(542,	'And Abraham set seven ewe lambs of the flock by themselves.',	'ஆபிரகாம் ஏழு பெண்ணாட்டுக்குட்டிகளைத் தனியே நிறுத்தினான்.',	1,	21,	28),
(543,	'And Abimelech said unto Abraham, What mean these seven ewe lambs which thou hast set by themselves?',	'அப்பொழுது அபிமெலேக்கு ஆபிரகாமை நோக்கி: நீ தனியே நிறுத்தின இந்த ஏழு பெண்ணாட்டுக்குட்டிகள் என்னத்திற்கு என்று கேட்டான்.',	1,	21,	29),
(544,	'And he said, For these seven ewe lambs shalt thou take of my hand, that they may be a witness unto me, that I have digged this well.',	'அதற்கு அவன்: நான் இந்தத் துரவு தோண்டினதைக்குறித்து, நீர் சாட்சியாக இந்த ஏழு பெண்ணாட்டுக்குட்டிகளை என் கையில் வாங்கிக்கொள்ளவேண்டும் என்றான்.',	1,	21,	30),
(545,	'Wherefore he called that place Beersheba; because there they sware both of them.',	'அவர்கள் இருவரும் அவ்விடத்தில் ஆணையிட்டுக்கொண்டபடியால், அந்த இடம் பெயெர்செபா என்னப்பட்டது.',	1,	21,	31),
(546,	'Thus they made a covenant at Beersheba: then Abimelech rose up, and Phichol the chief captain of his host, and they returned into the land of the Philistines.',	'அவர்கள் பெயெர்செபாவிலே உடன்படிக்கை பண்ணிக்கொண்டபின் அபிமெலேக்கும், அவன் சேனாதிபதியாகிய பிகோலும் எழுந்து பெலிஸ்தருடைய தேசத்திற்குத் திரும்பிப்போனார்கள்.',	1,	21,	32),
(547,	'And Abraham planted a grove in Beersheba, and called there on the name of the LORD, the everlasting God.',	'ஆபிரகாம் பெயெர்செபாவிலே ஒரு தோப்பை உண்டாக்கி, சதாகாலமுமுள்ள தேவனாகிய கர்த்தருடைய நாமத்தை அவ்விடத்தில் தொழுதுகொண்டான்.',	1,	21,	33),
(548,	'And Abraham sojourned in the Philistines\' land many days.',	'ஆபிரகாம் பெலிஸ்தருடைய தேசத்தில் அநேகநாள் தங்கியிருந்தான்.  ',	1,	21,	34),
(549,	'And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am.',	'இந்தக் காரியங்கள் நடந்தபின்பு, தேவன் ஆபிரகாமைச் சோதித்தார்; எப்படியெனில், அவர் அவனை நோக்கி: ஆபிரகாமே என்றார்; அவன்: இதோ அடியேன் என்றான்.',	1,	22,	1),
(550,	'And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of.',	'அப்பொழுது அவர்: உன் புத்திரனும், உன் ஏகசுதனும், உன் நேசகுமாரனுமாகிய ஈசாக்கை நீ இப்பொழுது அழைத்துக்கொண்டு, மோரியா தேசத்துக்குப் போய், அங்கே நான் உனக்குக் குறிக்கும் மலைகள் ஒன்றின்மேல் அவனைத் தகனபலியாகப் பலியிடு என்றார்.',	1,	22,	2),
(551,	'And Abraham rose up early in the morning, and saddled his ass, and took two of his young men with him, and Isaac his son, and clave the wood for the burnt offering, and rose up, and went unto the place of which God had told him.',	'ஆபிரகாம் அதிகாலையில் எழுந்து, தன் கழுதையின்மேல் சேணங்கட்டி, தன் வேலைக்காரரில் இரண்டுபேரையும் தன் குமாரன் ஈசாக்கையும் கூட்டிக்கொண்டு, தகனபலிக்குக் கட்டைகளையும் பிளந்துகொண்டு, தேவன் தனக்குக் குறித்த இடத்திற்குப் புறப்பட்டுப்போனான்.',	1,	22,	3),
(552,	'Then on the third day Abraham lifted up his eyes, and saw the place afar off.',	'மூன்றாம் நாளில் ஆபிரகாம் தன் கண்களை ஏறெடுத்துப்பார்த்து, தூரத்திலே அந்த இடத்தைக் கண்டான்.',	1,	22,	4),
(553,	'And Abraham said unto his young men, Abide ye here with the ass; and I and the lad will go yonder and worship, and come again to you.',	'அப்பொழுது ஆபிரகாம் தன் வேலைக்காரரை நோக்கி: நீங்கள் கழுதையை நிறுத்தி இங்கே காத்திருங்கள், நானும் பிள்ளையாண்டானும் அவ்விடமட்டும் போய், தொழுதுகொண்டு, உங்களிடத்துக்குத் திரும்பி வருவோம் என்றான்.',	1,	22,	5),
(554,	'And Abraham took the wood of the burnt offering, and laid it upon Isaac his son; and he took the fire in his hand, and a knife; and they went both of them together.',	'ஆபிரகாம் தகனபலிக்குக் கட்டைகளை எடுத்து, தன் குமாரனாகிய ஈசாக்கின் மேல் வைத்து, தன் கையிலே நெருப்பையும் கத்தியையும் எடுத்துக்கொண்டான்; இருவரும் கூடிப்போனார்கள்.',	1,	22,	6),
(555,	'And Isaac spake unto Abraham his father, and said, My father: and he said, Here am I, my son. And he said, Behold the fire and the wood: but where is the lamb for a burnt offering?',	'அப்பொழுது ஈசாக்கு தன் தகப்பனாகிய ஆபிரகாமை நோக்கி: என் தகப்பனே என்றான்; அதற்கு அவன்: என் மகனே, இதோ, இருக்கிறேன் என்றான்; அப்பொழுது அவன்: இதோ, நெருப்பும் கட்டையும் இருக்கிறது, தகனபலிக்கு ஆட்டுக்குட்டி எங்கே என்றான்.',	1,	22,	7),
(556,	'And Abraham said, My son, God will provide himself a lamb for a burnt offering: so they went both of them together.',	'அதற்கு ஆபிரகாம்: என் மகனே, தேவன் தமக்குத் தகனபலிக்கான ஆட்டுக்குட்டியைப் பார்த்துக்கொள்வார் என்றான்; அப்புறம் இருவரும் கூடிப்போய்,',	1,	22,	8),
(557,	'And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood.',	'தேவன் அவனுக்குச் சொல்லியிருந்த இடத்துக்கு வந்தார்கள்; அங்கே ஆபிரகாம் ஒரு பலிபீடத்தை உண்டாக்கி, கட்டைகளை அடுக்கி, தன் குமாரனாகிய ஈசாக்கைக் கட்டி, அந்தப் பலிபீடத்தில் அடுக்கிய கட்டைகளின்மேல் அவனைக் கிடத்தினான்.',	1,	22,	9),
(558,	'And Abraham stretched forth his hand, and took the knife to slay his son.',	'பின்பு ஆபிரகாம் தன் குமாரனை வெட்டும்படிக்குத் தன் கையை நீட்டிக் கத்தியை எடுத்தான்.',	1,	22,	10),
(559,	'And the angel of the LORD called unto him out of heaven, and said, Abraham, Abraham: and he said, Here am I.',	'அப்பொழுது கர்த்தருடைய தூதனானவர் வானத்திலிருந்து, ஆபிரகாமே, ஆபிரகாமே என்று கூப்பிட்டார்; அவன்: இதோ, அடியேன் என்றான்.',	1,	22,	11),
(560,	'And he said, Lay not thine hand upon the lad, neither do thou any thing unto him: for now I know that thou fearest God, seeing thou hast not withheld thy son, thine only son from me.',	'அப்பொழுது அவர்: பிள்ளையாண்டான்மேல் உன் கையைப் போடாதே, அவனுக்கு ஒன்றும் செய்யாதே; நீ அவனை உன் புத்திரன் என்றும், உன் ஏகசுதன் என்றும் பாராமல் எனக்காக ஒப்புக்கொடுத்தபடியினால் நீ தேவனுக்குப் பயப்படுகிறவன் என்று இப்பொழுது அறிந்திருக்கிறேன் என்றார்.',	1,	22,	12),
(561,	'And Abraham lifted up his eyes, and looked, and behold behind him a ram caught in a thicket by his horns: and Abraham went and took the ram, and offered him up for a burnt offering in the stead of his son.',	'ஆபிரகாம் தன் கண்களை ஏறெடுத்துப் பார்க்கும்போது, இதோ, பின்னாகப் புதரிலே தன் கொம்புகள் சிக்கிக்கொண்டிருந்த ஒரு ஆட்டுக்கடாவைக் கண்டான்; அப்பொழுது ஆபிரகாம் போய், கடாவைப் பிடித்து, அதைத் தன் குமாரனுக்குப் பதிலாகத் தகனபலியிட்டான்.',	1,	22,	13),
(562,	'And Abraham called the name of that place Jehovahjireh: as it is said to this day, In the mount of the LORD it shall be seen.',	'ஆபிரகாம் அந்த இடத்துக்கு யேகோவாயீரே என்று பேரிட்டான்; அதினாலே கர்த்தருடைய பர்வதத்திலே பார்த்துக்கொள்ளப்படும் என்று இந்நாள்வரைக்கும் சொல்லப்பட்டு வருகிறது.',	1,	22,	14),
(563,	'And the angel of the LORD called unto Abraham out of heaven the second time,',	'கர்த்தருடைய தூதனானவர் இரண்டாந்தரம் வானத்திலிருந்து ஆபிரகாமைக் கூப்பிட்டு:',	1,	22,	15),
(564,	'And said, By myself have I sworn, saith the LORD, for because thou hast done this thing, and hast not withheld thy son, thine only son:',	'நீ உன் புத்திரன் என்றும், உன் ஏகசுதன் என்றும் பாராமல் அவனை ஒப்புக்கொடுத்து இந்தக் காரியத்தைச் செய்தபடியால்;',	1,	22,	16),
(565,	'That in blessing I will bless thee, and in multiplying I will multiply thy seed as the stars of the heaven, and as the sand which is upon the sea shore; and thy seed shall possess the gate of his enemies;',	'நான் உன்னை ஆசீர்வதிக்கவே ஆசீர்வதித்து, உன் சந்ததியை வானத்து நட்சத்திரங்களைப்போலவும், கடற்கரை மணலைப்போலவும் பெருகவே பெருகப்பண்ணுவேன் என்றும், உன் சந்ததியார் தங்கள் சத்துருக்களின் வாசல்களைச் சுதந்தரித்துக்கொள்ளுவார்கள் என்றும்,',	1,	22,	17),
(566,	'And in thy seed shall all the nations of the earth be blessed; because thou hast obeyed my voice.',	'நீ என் சொல்லுக்குக் கீழ்ப்படிந்தபடியினால், உன் சந்ததிக்குள் பூமியிலுள்ள சகல ஜாதிகளும் ஆசீர்வதிக்கப்படும் என்றும் என்பேரில் ஆணையிட்டேன் என்று கர்த்தர் சொல்லுகிறார் என்றார்.',	1,	22,	18),
(567,	'So Abraham returned unto his young men, and they rose up and went together to Beersheba; and Abraham dwelt at Beersheba.',	'ஆபிரகாம் தன் வேலைக்காரரிடத்துக்குத் திரும்பிவந்தான்; அவர்கள் எழுந்து புறப்பட்டு, ஏகமாய்ப் பெயெர்செபாவுக்குப் போனார்கள்; ஆபிரகாம் பெயெர்செபாவிலே குடியிருந்தான்.',	1,	22,	19),
(568,	'And it came to pass after these things, that it was told Abraham, saying, Behold, Milcah, she hath also born children unto thy brother Nahor;',	'இந்தக் காரியங்கள் நடந்தபின்பு, ஒருவன் ஆபிரகாமிடத்தில் வந்து: மில்க்காளும் உன் சகோதரனாகிய நாகோருக்குப் பிள்ளைகளைப் பெற்றாள்;',	1,	22,	20),
(569,	'Huz his firstborn, and Buz his brother, and Kemuel the father of Aram,',	'அவர்கள் யாரென்றால், முதற்பேறான ஊத்ஸ், அவன் தம்பியாகிய பூஸ், ஆராமுக்குத் தகப்பனாகிய கேமுவேல்,',	1,	22,	21),
(570,	'And Chesed, and Hazo, and Pildash, and Jidlaph, and Bethuel.',	'கேசேத், ஆசோ, பில்தாஸ், இத்லாப், பெத்துவேல் என்பவர்கள்; பெத்துவேல் ரெபெக்காளைப் பெற்றான் என்று அறிவித்தான்.',	1,	22,	22),
(571,	'And Bethuel begat Rebekah: these eight Milcah did bear to Nahor, Abraham\'s brother.',	'அந்த எட்டுப்பேரை மில்க்காள் ஆபிரகாமுடைய சகோதரனாகிய நாகோருக்குப் பெற்றாள்.',	1,	22,	23),
(572,	'And his concubine, whose name was Reumah, she bare also Tebah, and Gaham, and Thahash, and Maachah.',	'ரேயுமாள் என்று பேர்கொண்ட அவனுடைய மறுமனையாட்டியும், தேபா, காகாம், தாகாஸ், மாகா என்பவர்களைப் பெற்றாள்.  ',	1,	22,	24),
(573,	'And Sarah was an hundred and seven and twenty years old: these were the years of the life of Sarah.',	'சாராள் நூற்று இருபத்தேழு வருஷம் உயிரோடிருந்தாள்; இவ்வளவே சாராளுடைய வயது.',	1,	23,	1),
(574,	'And Sarah died in Kirjatharba; the same is Hebron in the land of Canaan: and Abraham came to mourn for Sarah, and to weep for her.',	'கானான் தேசத்திலுள்ள எபிரோன் என்னும் கீரியாத்அர்பாவிலே சாராள் மரித்தாள்; அப்பொழுது ஆபிரகாம் வந்து, சாராளுக்காகப் புலம்பி அழுதான்.',	1,	23,	2),
(575,	'And Abraham stood up from before his dead, and spake unto the sons of Heth, saying,',	'பின்பு ஆபிரகாம் பிரேதம் இருந்த இடத்திலிருந்து எழுந்துபோய், ஏத்தின் புத்திரரோடே பேசி:',	1,	23,	3),
(576,	'I am a stranger and a sojourner with you: give me a possession of a buryingplace with you, that I may bury my dead out of my sight.',	'நான் உங்களிடத்தில் அந்நியனும் பரதேசியுமாய் இருக்கிறேன்; என்னிடத்திலிருக்கிற இந்தப் பிரேதம் என் கண்முன் இராதபடிக்கு நான் அதை அடக்கம்பண்ணுவதற்கு, உங்களிடத்தில் எனக்குச் சொந்தமாக ஒரு கல்லறைப் பூமியைத் தரவேண்டும் என்றான்.',	1,	23,	4),
(577,	'And the children of Heth answered Abraham, saying unto him,',	'அதற்கு ஏத்தின் புத்திரர் ஆபிரகாமுக்குப் பிரதியுத்தரமாக:',	1,	23,	5),
(578,	'Hear us, my lord: thou art a mighty prince among us: in the choice of our sepulchres bury thy dead; none of us shall withhold from thee his sepulchre, but that thou mayest bury thy dead.',	'எங்கள் ஆண்டவனே, நாங்கள் சொல்லுகிறதைக் கேளும்; எங்களுக்குள்ளே நீர் மகா பிரபு; எங்கள் கல்லறைகளில் முக்கியமானதிலே பிரேதத்தை அடக்கம்பண்ணும்; நீர் பிரேதத்தை அடக்கம்பண்ண எங்களில் ஒருவனும் தன் கல்லறையை உமக்குத் தடைசெய்வதில்லை என்றார்கள்.',	1,	23,	6),
(579,	'And Abraham stood up, and bowed himself to the people of the land, even to the children of Heth.',	'அப்பொழுது ஆபிரகாம் எழுந்திருந்து, ஏத்தின் புத்திரராகிய அத்தேசத்தாருக்கு வந்தனம் செய்து,',	1,	23,	7),
(580,	'And he communed with them, saying, If it be your mind that I should bury my dead out of my sight; hear me, and intreat for me to Ephron the son of Zohar,',	'அவர்களோடே பேசி: என்னிடத்திலிருக்கிற பிரேதம் என் கண்முன் இராதபடிக்கு, நான் அதை அடக்கம்பண்ண உங்களுக்குச் சம்மதியானால், நீங்கள் என் வார்த்தையைக் கேட்டு, சோகாருடைய குமாரனாகிய எப்பெரோன்,',	1,	23,	8),
(581,	'That he may give me the cave of Machpelah, which he hath, which is in the end of his field; for as much money as it is worth he shall give it me for a possession of a buryingplace amongst you.',	'தன் நிலத்தின் கடைசியிலே இருக்கிற மக்பேலா என்னப்பட்ட குகையை எனக்குச் சொந்தமான கல்லறைப் பூமியாயிருக்கும்படி தரவேண்டும் என்று, அவரிடத்தில் எனக்காக வேண்டிக்கொள்ளுங்கள்; அது பெறுமான விலைக்கு அவர் அதைத் தருவாராக என்றான்.',	1,	23,	9),
(582,	'And Ephron dwelt among the children of Heth: and Ephron the Hittite answered Abraham in the audience of the children of Heth, even of all that went in at the gate of his city, saying,',	'எப்பெரோன் ஏத்தின் புத்திரர் நடுவிலே உட்கார்ந்திருந்தான்; அப்பொழுது ஏத்தியனாகிய எப்பெரோன் தன் ஊர் வாசலுக்குள் பிரவேசிக்கிற ஏத்தின் புத்திரர் அனைவரும் கேட்க ஆபிரகாமுக்குப் பிரதியுத்தரமாக:',	1,	23,	10),
(583,	'Nay, my lord, hear me: the field give I thee, and the cave that is therein, I give it thee; in the presence of the sons of my people give I it thee: bury thy dead.',	'அப்படியல்ல, என் ஆண்டவனே, என் வார்த்தையைக் கேளும்; அந்த நிலத்தை உமக்குத் தருகிறேன், அதிலிருக்கும் குகையையும் உமக்குத் தருகிறேன், என் ஜனப்புத்திரருடைய கண்களுக்கு முன்பாக அதை உமக்குத் தருகிறேன், உம்மிடத்திலிருக்கிற பிரேதத்தை அடக்கம்பண்ணும் என்றான்.',	1,	23,	11),
(584,	'And Abraham bowed down himself before the people of the land.',	'அப்பொழுது ஆபிரகாம் அத்தேசத்தாருக்கு வந்தனம் செய்து,',	1,	23,	12),
(585,	'And he spake unto Ephron in the audience of the people of the land, saying, But if thou wilt give it, I pray thee, hear me: I will give thee money for the field; take it of me, and I will bury my dead there.',	'தேசத்து ஜனங்கள் கேட்க, எப்பெரோனை நோக்கி: கொடுக்க உமக்கு மனதானால் என் வார்த்தையைக் கேளும்; நிலத்தின் விலையைத் தருகிறேன்; என் கையில் அதை வாங்கிக்கொள்ளும்; அப்பொழுது என்னிடத்திலிருக்கிற பிரேதத்தை அவ்விடத்தில் அடக்கம்பண்ணுவேன் என்றான்.',	1,	23,	13),
(586,	'And Ephron answered Abraham, saying unto him,',	'அதற்கு எப்பெரோன் ஆபிரகாமுக்குப் பிரதியுத்தரமாக:',	1,	23,	14),
(587,	'My lord, hearken unto me: the land is worth four hundred shekels of silver; what is that betwixt me and thee? bury therefore thy dead.',	'என் ஆண்டவனே, நான் சொல்லுகிறதைக் கேளும்; அந்த நிலம் நானூறு சேக்கல் நிறை வெள்ளி பெறும்; எனக்கும் உமக்கும் அது எவ்வளவு காரியம்; நீர் உம்மிடத்திலிருக்கிற பிரேதத்தை அடக்கம் பண்ணும் என்றான்.',	1,	23,	15),
(588,	'And Abraham hearkened unto Ephron; and Abraham weighed to Ephron the silver, which he had named in the audience of the sons of Heth, four hundred shekels of silver, current money with the merchant.',	'அப்பொழுது ஆபிரகாம் எப்பெரோனின் சொல்லைக் கேட்டு, ஏத்தின் புத்திரருக்கு முன்பாக எப்பெரோன் சொன்னபடியே, வர்த்தகரிடத்தில் செல்லும்படியான நானூறு சேக்கல் நிறை வெள்ளியை அவனுக்கு நிறுத்துக் கொடுத்தான்.',	1,	23,	16),
(589,	'And the field of Ephron which was in Machpelah, which was before Mamre, the field, and the cave which was therein, and all the trees that were in the field, that were in all the borders round about, were made sure',	'இந்தப்பிரகாரம் மம்ரேக்கு எதிரே மக்பேலாவிலுள்ள எப்பெரோனுடைய நிலமாகிய அந்தப் பூமியும், அதிலுள்ள குகையும், நிலத்தின் எல்லையெங்கும் சூழ்ந்திருக்கிற மரங்கள் அடங்கலும்,',	1,	23,	17),
(590,	'Unto Abraham for a possession in the presence of the children of Heth, before all that went in at the gate of his city.',	'அவனுடைய ஊர்வாசலுக்குள் பிரவேசிக்கும் ஏத்தின் புத்திரர் எல்லாரும் அறிய ஆபிரகாமுக்குச் சொந்தமாக உறுதிப்படுத்தப்பட்டது.',	1,	23,	18),
(591,	'And after this, Abraham buried Sarah his wife in the cave of the field of Machpelah before Mamre: the same is Hebron in the land of Canaan.',	'அதற்குப்பின் ஆபிரகாம் தன் மனைவியாகிய சாராளைக் கானான் தேசத்தில் எப்பெரோன் ஊர் பூமியான மம்ரேக்கு எதிரே இருக்கிற மக்பேலா என்னும் நிலத்தின் குகையிலே அடக்கம்பண்ணினான்.',	1,	23,	19),
(592,	'And the field, and the cave that is therein, were made sure unto Abraham for a possession of a buryingplace by the sons of Heth.',	'இப்படி ஏத்தின் புத்திரர் கையில் கொள்ளப்பட்ட அந்த நிலமும், அதிலுள்ள குகையும், ஆபிரகாமுக்குச் சொந்த கல்லறைப் பூமியாக உறுதிப்படுத்தப்பட்டது.  ',	1,	23,	20),
(593,	'And Abraham was old, and well stricken in age: and the LORD had blessed Abraham in all things.',	'ஆபிரகாம் வயதுசென்று முதிர்ந்தவனானான். கர்த்தர் ஆபிரகாமைச் சகல காரியங்களிலும் ஆசீர்வதித்து வந்தார்.',	1,	24,	1),
(594,	'And Abraham said unto his eldest servant of his house, that ruled over all that he had, Put, I pray thee, thy hand under my thigh:',	'அப்பொழுது ஆபிரகாம் தன் வீட்டிலுள்ளவர்களில் வயதில் மூத்தவனும், தனக்கு உண்டான எல்லாவற்றிற்கும் அதிகாரியுமாகிய தன் ஊழியக்காரனை நோக்கி:',	1,	24,	2),
(595,	'And I will make thee swear by the LORD, the God of heaven, and the God of the earth, that thou shalt not take a wife unto my son of the daughters of the Canaanites, among whom I dwell:',	'நான் குடியிருக்கிற கானானியருடைய குமாரத்திகளில் நீ என் குமாரனுக்குப் பெண்கொள்ளாமல்;',	1,	24,	3),
(596,	'But thou shalt go unto my country, and to my kindred, and take a wife unto my son Isaac.',	'நீ என் தேசத்துக்கும் என் இனத்தாரிடத்துக்கும் போய், என் குமாரனாகிய ஈசாக்குக்குப் பெண்கொள்வேன் என்று, வானத்துக்குத் தேவனும் பூமிக்குத் தேவனுமாகிய கர்த்தர் பேரில் எனக்கு ஆணையிட்டுக்கொடுக்கும்படிக்கு, நீ உன் கையை என் தொடையின்கீழ் வை என்றான்.',	1,	24,	4),
(597,	'And the servant said unto him, Peradventure the woman will not be willing to follow me unto this land: must I needs bring thy son again unto the land from whence thou camest?',	'அதற்கு அந்த ஊழியக்காரன்: அவ்விடத்துப் பெண் என் பின்னே இந்தத் தேசத்துக்கு வர மனதில்லாதிருந்தால், நீர் விட்டுவந்த தேசத்திற்குத்தானே உம்முடைய குமாரனை மறுபடியும் அழைத்துப்போகவேண்டுமோ என்று கேட்டான்.',	1,	24,	5),
(598,	'And Abraham said unto him, Beware thou that thou bring not my son thither again.',	'அதற்கு ஆபிரகாம்: நீ என் குமாரனை மறுபடியும் அங்கே அழைத்துக்கொண்டு போகாதபடிக்கு எச்சரிக்கையாயிரு.',	1,	24,	6),
(599,	'The LORD God of heaven, which took me from my father\'s house, and from the land of my kindred, and which spake unto me, and that sware unto me, saying, Unto thy seed will I give this land; he shall send his angel before thee, and thou shalt take a wife unto my son from thence.',	'என்னை என் தகப்பனுடைய வீட்டிலும் என் இனத்தார் இருக்கிற தேசத்திலுமிருந்து அழைத்துவந்தவரும், உன் சந்ததிக்கு இந்த தேசத்தைத் தருவேன் என்று எனக்குச் சொல்லி ஆணையிட்டவருமான வானத்துக்குத் தேவனாகிய கர்த்தர், நீ அங்கேயிருந்து என் குமாரனுக்கு ஒரு பெண்ணைக் கொண்டுவரும்படிக்கு, தம்முடைய தூதனை உனக்கு முன்பாக அனுப்புவார்.',	1,	24,	7),
(600,	'And if the woman will not be willing to follow thee, then thou shalt be clear from this my oath: only bring not my son thither again.',	'பெண் உன் பின்னே வர மனதில்லாதிருந்தாளேயாகில், அப்பொழுது நீ இந்த என் ஆணைக்கு நீங்கலாயிருப்பாய்; அங்கே மாத்திரம் என் குமாரனை மறுபடியும் அழைத்துக்கொண்டு போகவேண்டாம் என்றான்.',	1,	24,	8),
(601,	'And the servant put his hand under the thigh of Abraham his master, and sware to him concerning that matter.',	'அப்பொழுது அந்த ஊழியக்காரன் தன் கையைத் தன் எஜமானாகிய ஆபிரகாமுடைய தொடையின்கீழ் வைத்து, இந்தக் காரியத்தைக்குறித்து அவனுக்கு ஆணையிட்டுக்கொடுத்தான்.',	1,	24,	9),
(602,	'And the servant took ten camels of the camels of his master, and departed; for all the goods of his master were in his hand: and he arose, and went to Mesopotamia, unto the city of Nahor.',	'பின்பு அந்த ஊழியக்காரன் தன் எஜமானுடைய ஒட்டகங்களில் பத்து ஒட்டகங்களைத் தன்னுடனே கொண்டுபோனான்; தன் எஜமானுடைய சகலவித உச்சிதமான பொருள்களும் அவன் கையில் இருந்தன; அவன் எழுந்து புறப்பட்டுப்போய், மெசொப்பொத்தாமியாவிலே நாகோருடைய ஊரில் சேர்ந்து,',	1,	24,	10),
(603,	'And he made his camels to kneel down without the city by a well of water at the time of the evening, even the time that women go out to draw water.',	'ஊருக்குப் புறம்பே ஒரு தண்ணீர்த் துரவண்டையிலே, தண்ணீர் மொள்ள ஸ்திரீகள் புறப்படுகிற சாயங்கால வேளையிலே, ஒட்டகங்களை மடக்கி, தனக்குள்ளே சொல்லிக்கொண்டது என்னவென்றால்:',	1,	24,	11),
(604,	'And he said O LORD God of my master Abraham, I pray thee, send me good speed this day, and shew kindness unto my master Abraham.',	'என் எஜமானாகிய ஆபிரகாமுக்கு தேவனாயிருக்கிற கர்த்தாவே, இன்றைக்கு நீர் எனக்குக் காரியம் சித்திக்கப்பண்ணி, என் எஜமானாகிய ஆபிரகாமுக்குத் தயவு செய்தருளும்.',	1,	24,	12),
(605,	'Behold, I stand here by the well of water; and the daughters of the men of the city come out to draw water:',	'இதோ, நான் இந்தத் தண்ணீர்த்துரவண்டையிலே நிற்கிறேன், இந்த ஊராருடைய பெண்கள் தண்ணீர் மொள்ளப்புறப்பட்டு வருவார்களே.',	1,	24,	13),
(606,	'And let it come to pass, that the damsel to whom I shall say, Let down thy pitcher, I pray thee, that I may drink; and she shall say, Drink, and I will give thy camels drink also: let the same be she that thou hast appointed for thy servant Isaac; and thereby shall I know that thou hast shewed kindness unto my master.',	'நான் குடிக்க உன் குடத்தைச் சாய்க்கவேண்டும் என்று நான் சொல்லும்போது: குடி என்றும், உன் ஒட்டகங்களும் குடிக்கும்படி வார்ப்பேன் என்றும் சொல்லும் பெண் எவளோ, அவளே நீர் உம்முடைய ஊழியக்காரனாகிய ஈசாக்குக்கு நியமித்தவளாயிருக்கவும், என் எஜமானுக்கு அநுக்கிரகம் செய்தீர் என்று நான் அதினாலே அறியவும் செய்தருளும் என்றான்.',	1,	24,	14),
(607,	'And it came to pass, before he had done speaking, that, behold, Rebekah came out, who was born to Bethuel, son of Milcah, the wife of Nahor, Abraham\'s brother, with her pitcher upon her shoulder.',	'அவன் இப்படிச் சொல்லி முடிக்கும் முன்னே, இதோ, ஆபிரகாமுடைய சகோதரனாகிய நாகோரின் மனைவி மில்க்காளுடைய குமாரனாகிய பெத்துவேலுக்குப் பிறந்த ரெபெக்காள் குடத்தைத் தோள்மேல் வைத்துக்கொண்டு புறப்பட்டுவந்தாள்.',	1,	24,	15),
(608,	'And the damsel was very fair to look upon, a virgin, neither had any man known her: and she went down to the well, and filled her pitcher, and came up.',	'அந்தப் பெண் மகா ரூபவதியும், புருஷனை அறியாத கன்னிகையுமாய் இருந்தாள்; அவள் துரவில் இறங்கி, தன் குடத்தை நிரப்பிக்கொண்டு ஏறிவந்தாள்.',	1,	24,	16),
(609,	'And the servant ran to meet her, and said, Let me, I pray thee, drink a little water of thy pitcher.',	'அப்பொழுது அந்த ஊழியக்காரன், அவளுக்கு எதிர்கொண்டோடி: உன் குடத்திலிருக்கிற தண்ணீரில் கொஞ்சம் குடிக்கத் தரவேண்டும் என்றான்.',	1,	24,	17),
(610,	'And she said, Drink, my lord: and she hasted, and let down her pitcher upon her hand, and gave him drink.',	'அதற்கு அவள்: குடியும் என் ஆண்டவனே என்று சீக்கிரமாய்க் குடத்தைத் தன் கையில் இறக்கிக்கொண்டு, அவனுக்குக் குடிக்கக் கொடுத்தாள்.',	1,	24,	18),
(611,	'And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking.',	'கொடுத்தபின், உம்முடைய ஒட்டகங்களும் குடித்துத் தீருமட்டும் அவைகளுக்கும் மொண்டு வார்ப்பேன் என்றுசொல்லி;',	1,	24,	19),
(612,	'And she hasted, and emptied her pitcher into the trough, and ran again unto the well to draw water, and drew for all his camels.',	'சீக்கிரமாய்த் தன் குடத்துத் தண்ணீரைத் தொட்டியிலே ஊற்றிவிட்டு, இன்னும் மொண்டுவரத் துரவண்டையில் ஓடி, அவனுடைய ஒட்டகங்களுக்கெல்லாம் மொண்டு வார்த்தாள்.',	1,	24,	20),
(613,	'And the man wondering at her held his peace, to wit whether the LORD had made his journey prosperous or not.',	'அந்த மனிதன் அவளைக்குறித்து ஆச்சரியப்பட்டு, கர்த்தர் தன் பிரயாணத்தை வாய்க்கப்பண்ணினாரோ இல்லையோ என்று அறியும்பொருட்டு மவுனமாயிருந்தான்.',	1,	24,	21),
(614,	'And it came to pass, as the camels had done drinking, that the man took a golden earring of half a shekel weight, and two bracelets for her hands of ten shekels weight of gold;',	'ஒட்டகங்கள் குடித்துத் தீர்ந்தபின், அந்த மனிதன் அரைச்சேக்கல் எடையுள்ள பொற்காதணியையும், அவள் கைகளுக்குப் பத்துச் சேக்கல் எடைப் பொன்னுள்ள இரண்டு கடகங்களையும் எடுத்துக்கொடுத்து,',	1,	24,	22),
(615,	'And said, Whose daughter art thou? tell me, I pray thee: is there room in thy father\'s house for us to lodge in?',	'நீ யாருடைய மகள், எனக்குச் சொல்லவேண்டும்; நாங்கள் உன் தகப்பன் வீட்டில் இராத்தங்க இடம் உண்டா என்றான்.',	1,	24,	23),
(616,	'And she said unto him, I am the daughter of Bethuel the son of Milcah, which she bare unto Nahor.',	'அதற்கு அவள்: நான் நாகோருக்கு மில்க்காள் பெற்ற குமாரனாகிய பெத்துவேலின் மகள் என்று சொன்னதுமன்றி,',	1,	24,	24),
(617,	'She said moreover unto him, We have both straw and provender enough, and room to lodge in.',	'எங்களிடத்தில் வைக்கோலும் தீவனமும் வேண்டியமட்டும் இருக்கிறது; இராத்தங்க இடமும் உண்டு என்றாள்.',	1,	24,	25),
(618,	'And the man bowed down his head, and worshipped the LORD.',	'அப்பொழுது அந்த மனிதன் தலைகுனிந்து, கர்த்தரைப்பணிந்துகொண்டு,',	1,	24,	26),
(619,	'And he said, Blessed be the LORD God of my master Abraham, who hath not left destitute my master of his mercy and his truth: I being in the way, the LORD led me to the house of my master\'s brethren.',	'என் எஜமானாகிய ஆபிரகாமின் தேவனாயிருக்கிற கர்த்தருக்கு ஸ்தோத்திரம்; அவர் தம்முடைய கிருபையையும், தம்முடைய உண்மையையும் என் எஜமானை விட்டு நீக்கவில்லை; நான் பிரயாணம் பண்ணிவருகையில், கர்த்தர் என் எஜமானுடைய சகோதரர் வீட்டுக்கு என்னை அழைத்துக்கொண்டு வந்தார் என்றான்.',	1,	24,	27),
(620,	'And the damsel ran, and told them of her mother\'s house these things.',	'அந்தப் பெண் ஓடி, இந்தக் காரியங்களைத் தன் தாயின் வீட்டிலுள்ளவர்களுக்கு அறிவித்தாள்.',	1,	24,	28),
(621,	'And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well.',	'ரெபெக்காளுக்கு ஒரு சகோதரன் இருந்தான்; அவனுக்கு லாபான் என்று பேர்; அந்த லாபான் வெளியே துரவண்டையிலே இருந்த அந்த மனிதனிடத்துக்கு ஓடினான்.',	1,	24,	29),
(622,	'And it came to pass, when he saw the earring and bracelets upon his sister\'s hands, and when he heard the words of Rebekah his sister, saying, Thus spake the man unto me; that he came unto the man; and, behold, he stood by the camels at the well.',	'அவன் தன் சகோதரி தரித்திருந்த அந்தக் காதணியையும், அவள் கைகளில் போட்டிருந்த கடகங்களையும் பார்த்து, இன்ன இன்னபடி அந்த மனிதன் என்னோடே பேசினானென்று தன் சகோதரி ரெபெக்காள் சொன்ன வார்த்தைகளைக் கேட்டமாத்திரத்தில், அந்த மனிதனிடத்தில் வந்தான்; அவன் துரவு அருகே ஒட்டகங்கள் அண்டையில் நின்றுகொண்டிருந்தான்.',	1,	24,	30),
(623,	'And he said, Come in, thou blessed of the LORD; wherefore standest thou without? for I have prepared the house, and room for the camels.',	'அப்பொழுது அவன்: கர்த்தரால் ஆசீர்வதிக்கப்பட்டவரே, உள்ளே வாரும்; நீர் வெளியே நிற்பானேன்? உமக்கு வீடும், ஒட்டகங்களுக்கு இடமும் ஆயத்தம்பண்ணியிருக்கிறேன் என்றான்.',	1,	24,	31),
(624,	'And the man came into the house: and he ungirded his camels, and gave straw and provender for the camels, and water to wash his feet, and the men\'s feet that were with him.',	'அப்பொழுது அந்த மனிதன் வீட்டுக்குப் போனான். லாபான் ஒட்டகங்களின் கட்டவிழ்த்து, ஒட்டகங்களுக்கு வைக்கோலும் தீவனமும் போட்டு, அவனும், அவனோடே வந்தவர்களும் தங்கள் கால்களைக் கழுவிக்கொள்ளத் தண்ணீர் கொடுத்தான்.',	1,	24,	32),
(625,	'And there was set meat before him to eat: but he said, I will not eat, until I have told mine errand. And he said, Speak on.',	'பின்பு, அவனுக்கு முன்பாக போஜனம் வைக்கப்பட்டது. அப்பொழுது அவன்: நான் வந்த காரியத்தைச் சொல்லுமுன்னே புசிக்கமாட்டேன் என்றான். அதற்கு அவன், சொல்லும் என்றான்.',	1,	24,	33),
(626,	'And he said, I am Abraham\'s servant.',	'அப்பொழுது அவன்: நான் ஆபிரகாமுடைய ஊழியக்காரன்.',	1,	24,	34),
(627,	'And the LORD hath blessed my master greatly; and he is become great: and he hath given him flocks, and herds, and silver, and gold, and menservants, and maidservants, and camels, and asses.',	'கர்த்தர் என் எஜமானை மிகவும் ஆசீர்வதித்திருக்கிறார், அவர் சீமானாயிருக்கிறார்; கர்த்தர் அவருக்கு ஆடுமாடுகளையும், வெள்ளியையும், பொன்னையும், வேலைக்காரரையும், வேலைக்காரிகளையும், ஒட்டகங்களையும், கழுதைகளையும் கொடுத்திருக்கிறார்.',	1,	24,	35),
(628,	'And Sarah my master\'s wife bare a son to my master when she was old: and unto him hath he given all that he hath.',	'என் எஜமானுடைய மனைவியாகிய சாராள் முதிர்வயதானபோது, என் எஜமானுக்கு ஒரு குமாரனைப் பெற்றாள்; அவர் தமக்கு உண்டான யாவையும் அவனுக்குக் கொடுத்திருக்கிறார்.',	1,	24,	36),
(629,	'And my master made me swear, saying, Thou shalt not take a wife to my son of the daughters of the Canaanites, in whose land I dwell:',	'என் எஜமான் என்னை நோக்கி: நான் குடியிருக்கிற கானான் தேசத்தாருடைய குமாரத்திகளில் நீ என் குமாரனுக்குப் பெண்கொள்ளாமல்,',	1,	24,	37),
(630,	'But thou shalt go unto my father\'s house, and to my kindred, and take a wife unto my son.',	'நீ என் தகப்பன் வீட்டுக்கும், என் இனத்தாரிடத்துக்கும் போய், என் குமாரனுக்குப் பெண்கொள்ளவேண்டும் என்று ஆணையிட்டுக்கொடுக்கும்படி சொன்னார்.',	1,	24,	38),
(631,	'And I said unto my master, Peradventure the woman will not follow me.',	'அப்பொழுது நான் என் எஜமானை நோக்கி: ஒருவேளை அந்தப் பெண் என்பின்னே வராதேபோனாலோ என்று கேட்டதற்கு,',	1,	24,	39),
(632,	'And he said unto me, The LORD, before whom I walk, will send his angel with thee, and prosper thy way; and thou shalt take a wife for my son of my kindred, and of my father\'s house:',	'அவர்: நான் வழிபடும் கர்த்தர் உன்னோடே தம்முடைய தூதனை அனுப்பி, உன் பிரயாணத்தை வாய்க்கப்பண்ணுவார்; என் இனத்தாரிடத்திலும், என் தகப்பன் வீட்டிலும் நீ என் குமாரனுக்குப் பெண்கொள்வாய்.',	1,	24,	40),
(633,	'Then shalt thou be clear from this my oath, when thou comest to my kindred; and if they give not thee one, thou shalt be clear from my oath.',	'நீ என் இனத்தாரிடத்துக்குப்போனால், என் ஆணைக்கு நீங்கலாயிருப்பாய்; அவர்கள் உனக்குப் பெண்கொடாமற்போனாலும், நீ என் ஆணைக்கு நீங்கலாயிருப்பாய் என்றார்.',	1,	24,	41),
(634,	'And I came this day unto the well, and said, O LORD God of my master Abraham, if now thou do prosper my way which I go:',	'அப்படியே நான் இன்று துரவண்டையிலே வந்து: என் எஜமானாகிய ஆபிரகாமின் தேவனாகிய கர்த்தரே, என் பிரயாணத்தை நீர் இப்பொழுது வாய்க்கப்பண்ணுவீரானால்,',	1,	24,	42),
(635,	'Behold, I stand by the well of water; and it shall come to pass, that when the virgin cometh forth to draw water, and I say to her, Give me, I pray thee, a little water of thy pitcher to drink;',	'இதோ, நான் தண்ணீர்த் துரவண்டையிலே நிற்கிறேன், தண்ணீர் மொள்ள வரப்போகிற கன்னிகையை நான் நோக்கி: உன் குடத்திலிருக்கிற தண்ணீரில் கொஞ்சம் எனக்குக் குடிக்கத்தரவேண்டும் என்று கேட்கும்போது:',	1,	24,	43),
(636,	'And she say to me, Both drink thou, and I will also draw for thy camels: let the same be the woman whom the LORD hath appointed out for my master\'s son.',	'நீ குடி என்றும், உன் ஒட்டகங்களுக்கும் மொண்டு வார்ப்பேன் என்றும் சொல்லும் பெண்ணே கர்த்தர் என் எஜமானுடைய குமாரனுக்கு நியமித்த ஸ்திரீயாகவேண்டும் என்றேன்.',	1,	24,	44),
(637,	'And before I had done speaking in mine heart, behold, Rebekah came forth with her pitcher on her shoulder; and she went down unto the well, and drew water: and I said unto her, Let me drink, I pray thee.',	'நான் இதை என் இருதயத்தில் சொல்லி முடிக்குமுன்னே, இதோ, ரெபெக்காள் தன் குடத்தைத் தோள்மேல் வைத்துக்கொண்டு புறப்பட்டுவந்து, துரவில் இறங்கிப்போய்த் தண்ணீர் மொண்டாள். அப்பொழுது நான்: எனக்குக் குடிக்கத்தரவேண்டும் என்றேன்.',	1,	24,	45),
(638,	'And she made haste, and let down her pitcher from her shoulder, and said, Drink, and I will give thy camels drink also: so I drank, and she made the camels drink also.',	'அவள் சீக்கிரமாய்த் தன் தோள்மேலிருந்த குடத்தை இறக்கி, குடியும், உம்முடைய ஒட்டகங்களுக்கும் வார்ப்பேன் என்றாள். நான் குடித்தேன்; ஒட்டகங்களுக்கும் வார்த்தாள்.',	1,	24,	46),
(639,	'And I asked her, and said, Whose daughter art thou? And she said, the daughter of Bethuel, Nahor\'s son, whom Milcah bare unto him: and I put the earring upon her face, and the bracelets upon her hands.',	'அப்பொழுது: நீ யாருடைய மகள் என்று அவளைக் கேட்டேன்; அதற்கு அவள்: நான் மில்க்காள் நாகோருக்குப் பெற்ற குமாரனாகிய பெத்துவேலின் மகள் என்றாள்; அப்பொழுது அவளுக்குக் காதணியையும், அவள் கைகளிலே கடகங்களையும் போட்டு;',	1,	24,	47),
(640,	'And I bowed down my head, and worshipped the LORD, and blessed the LORD God of my master Abraham, which had led me in the right way to take my master\'s brother\'s daughter unto his son.',	'தலைகுனிந்து, கர்த்தரைப் பணிந்துகொண்டு, நான் என் எஜமானுடைய சகோதரன் குமாரத்தியை அவர் குமாரனுக்குக் கொள்ள என்னை நேர்வழியாய் நடத்திவந்த என் எஜமானாகிய ஆபிரகாமின் தேவனாயிருக்கிற கர்த்தரை ஸ்தோத்திரித்தேன்.',	1,	24,	48),
(641,	'And now if ye will deal kindly and truly with my master, tell me: and if not, tell me; that I may turn to the right hand, or to the left.',	'இப்பொழுதும் நீங்களும் என் எஜமானுக்குத் தயையும் உண்மையும் உடையவர்களாய் நடக்க மனதுள்ளவர்களானால், எனக்குச் சொல்லுங்கள்; இல்லையென்றால் அதையும் எனக்குச் சொல்லுங்கள், அப்பொழுது நான் வலதுபுறத்தையாகிலும் இடதுபுறத்தையாகிலும் நோக்கிப்போவேன் என்றான்.',	1,	24,	49),
(642,	'Then Laban and Bethuel answered and said, The thing proceedeth from the LORD: we cannot speak unto thee bad or good.',	'அப்பொழுது லாபானும் பெத்துவேலும் பிரதியுத்தரமாக: இந்தக் காரியம் கர்த்தரால் வந்தது, உமக்கு நாங்கள் நலம் பொலம் ஒன்றும் சொல்லக்கூடாது.',	1,	24,	50),
(643,	'Behold, Rebekah is before thee, take her, and go, and let her be thy master\'s son\'s wife, as the LORD hath spoken.',	'இதோ, ரெபெக்காள் உமக்கு முன்பாக இருக்கிறாள்; கர்த்தர் சொன்னபடியே அவள் உமது எஜமானுடைய குமாரனுக்கு மனைவியாகும்படிக்கு, அவளை அழைத்துக்கொண்டுபோம் என்றார்கள்.',	1,	24,	51),
(644,	'And it came to pass, that, when Abraham\'s servant heard their words, he worshipped the LORD, bowing himself to the earth.',	'ஆபிரகாமின் ஊழியக்காரன் அவர்கள் வார்த்தைகளைக் கேட்டபோது, தரை மட்டும் குனிந்து, கர்த்தரைப் பணிந்துகொண்டான்.',	1,	24,	52),
(645,	'And the servant brought forth jewels of silver, and jewels of gold, and raiment, and gave them to Rebekah: he gave also to her brother and to her mother precious things.',	'பின்பு அந்த ஊழியக்காரன் வெள்ளியுடைமைகளையும், பொன்னுடைமைகளையும், வஸ்திரங்களையும் எடுத்து, ரெபெக்காளுக்குக் கொடுத்ததுமன்றி, அவளுடைய சகோதரனுக்கும் தாய்க்கும் சில உச்சிதங்களையும் கொடுத்தான்.',	1,	24,	53),
(646,	'And they did eat and drink, he and the men that were with him, and tarried all night; and they rose up in the morning, and he said, Send me away unto my master.',	'பின்பு அவனும் அவனோடிருந்த மனிதரும் புசித்துக் குடித்து, இராத்தங்கினார்கள்; காலையிலே எழுந்திருந்து, அவன்: என் எஜமானிடத்துக்கு என்னை அனுப்பிவிடுங்கள் என்றான்.',	1,	24,	54),
(647,	'And her brother and her mother said, Let the damsel abide with us a few days, at the least ten; after that she shall go.',	'அப்பொழுது அவள் சகோதரனும் அவள் தாயும், பத்து நாளாகிலும் பெண் எங்களோடிருக்கட்டும், பிற்பாடு போகலாம் என்றார்கள்.',	1,	24,	55),
(648,	'And he said unto them, Hinder me not, seeing the LORD hath prospered my way; send me away that I may go to my master.',	'அதற்கு அவன்: கர்த்தர் என் பிரயாணத்தை வாய்க்கப்பண்ணியிருக்க, நீங்கள் எனக்குத் தடைசெய்யாதிருங்கள்; நான் என் எஜமானிடத்துக்குப்போக என்னை அனுப்பிவிடவேண்டும் என்றான்.',	1,	24,	56),
(649,	'And they said, We will call the damsel, and enquire at her mouth.',	'அப்பொழுது அவர்கள்: பெண்ணை அழைத்து, அவள் வாய்ப்பிறப்பைக் கேட்போம் என்று சொல்லி,',	1,	24,	57),
(650,	'And they called Rebekah, and said unto her, Wilt thou go with this man? And she said, I will go.',	'ரெபெக்காளை அழைத்து: நீ இந்த மனிதனோடேகூடப் போகிறாயா என்று கேட்டார்கள். அவள்: போகிறேன் என்றாள்.',	1,	24,	58),
(651,	'And they sent away Rebekah their sister, and her nurse, and Abraham\'s servant, and his men.',	'அப்படியே அவர்கள் தங்கள் சகோதரியாகிய ரெபெக்காளையும், அவள் தாதியையும், ஆபிரகாமின் ஊழியக்காரனையும், அவன் மனிதரையும் அனுப்புவித்து,',	1,	24,	59),
(652,	'And they blessed Rebekah, and said unto her, Thou art our sister, be thou the mother of thousands of millions, and let thy seed possess the gate of those which hate them.',	'ரெபெக்காளை வாழ்த்தி: எங்கள் சகோதரியே, நீ கோடாகோடியாய்ப் பெருகுவாயாக; உன் சந்ததியார் தங்கள் பகைஞருடைய வாசல்களைச் சுதந்தரித்துக்கொள்வார்களாக என்று ஆசீர்வதித்தார்கள்.',	1,	24,	60),
(653,	'And Rebekah arose, and her damsels, and they rode upon the camels, and followed the man: and the servant took Rebekah, and went his way.',	'அப்பொழுது ரெபெக்காளும் அவள் வேலைக்காரிகளும் எழுந்து ஒட்டகங்கள் மேல் ஏறி, அந்த மனிதனோடேகூடப் போனார்கள். ஊழியக்காரன் ரெபெக்காளை அழைத்துக்கொண்டுபோனான்.',	1,	24,	61),
(654,	'And Isaac came from the way of the well Lahairoi; for he dwelt in the south country.',	'ஈசாக்கு தென்தேசத்தில் குடியிருந்தான். அப்பொழுது அவன்: லகாய்ரோயீ என்னப்பட்ட துரவின் வழியாய்ப் புறப்பட்டு வந்தான்.',	1,	24,	62),
(655,	'And Isaac went out to meditate in the field at the eventide: and he lifted up his eyes, and saw, and, behold, the camels were coming.',	'ஈசாக்கு சாயங்காலவேளையிலே தியானம்பண்ண வெளியிலே போயிருந்து, தன் கண்களை ஏறெடுத்துப்பார்த்தபோது, ஒட்டகங்கள் வரக்கண்டான்.',	1,	24,	63),
(656,	'And Rebekah lifted up her eyes, and when she saw Isaac, she lighted off the camel.',	'ரெபெக்காளும் தன் கண்களை ஏறெடுத்து ஈசாக்கைக் கண்டபோது,',	1,	24,	64),
(657,	'For she had said unto the servant, What man is this that walketh in the field to meet us? And the servant had said, It is my master: therefore she took a vail, and covered herself.',	'ஊழியக்காரனை நோக்கி: அங்கே வெளியிலே நமக்கு எதிராக நடந்துவருகிற அந்த மனிதன் யார் என்று கேட்டாள். அவர்தான் என் எஜமான் என்று ஊழியக்காரன் சொன்னான். அப்பொழுது அவள் ஒட்டகத்தை விட்டிறங்கி முக்காடிட்டுக்கொண்டாள்.',	1,	24,	65),
(658,	'And the servant told Isaac all things that he had done.',	'ஊழியக்காரன் தான் செய்த சகல காரியங்களையும் ஈசாக்குக்கு விவரித்துச் சொன்னான்.',	1,	24,	66),
(659,	'And Isaac brought her into his mother Sarah\'s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother\'s death.',	'அப்பொழுது ஈசாக்கு ரெபெக்காளைத் தன் தாய் சாராளுடைய கூடாரத்துக்கு அழைத்துக்கொண்டுபோய், அவளைத் தனக்கு மனைவியாக்கிக்கொண்டு, அவளை நேசித்தான். ஈசாக்கு தன் தாய்க்காகக் கொண்டிருந்த துக்கம் நீங்கி ஆறுதல் அடைந்தான்.  ',	1,	24,	67),
(660,	'Then again Abraham took a wife, and her name was Keturah.',	'ஆபிரகாம் கேத்தூராள் என்னும் பேர்கொண்ட ஒரு ஸ்திரீயையும் விவாகம்பண்ணியிருந்தான்.',	1,	25,	1),
(661,	'And she bare him Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah.',	'அவள் அவனுக்குச் சிம்ரானையும், யக்க்ஷானையும், மேதானையும், மீதியானையும், இஸ்பாக்கையும், சூவாகையும் பெற்றாள்.',	1,	25,	2),
(662,	'And Jokshan begat Sheba, and Dedan. And the sons of Dedan were Asshurim, and Letushim, and Leummim.',	'யக்க்ஷான் சேபாவையும், தேதானையும் பெற்றான்; தேதானுடைய குமாரர் அசூரீம், லெத்தூசீம், லெயூமீம் என்பவர்கள்.',	1,	25,	3),
(663,	'And the sons of Midian; Ephah, and Epher, and Hanoch, and Abidah, and Eldaah. All these were the children of Keturah.',	'மீதியானுடைய குமாரர் ஏப்பா, ஏப்பேர், ஆனோக்கு, அபீதா, எல்தாகா என்பவர்கள்; இவர்கள் எல்லாரும் கேத்தூராளின் பிள்ளைகள்.',	1,	25,	4),
(664,	'And Abraham gave all that he had unto Isaac.',	'ஆபிரகாம் தனக்கு உண்டான யாவையும் ஈசாக்குக்குக் கொடுத்தான்.',	1,	25,	5),
(665,	'But unto the sons of the concubines, which Abraham had, Abraham gave gifts, and sent them away from Isaac his son, while he yet lived, eastward, unto the east country.',	'ஆபிரகாமுக்கு இருந்த மறுமனையாட்டிகளின் பிள்ளைகளுக்கோ ஆபிரகாம் நன்கொடைகளைக் கொடுத்து, தான் உயிரோடிருக்கும்போதே அவர்களைத் தன் குமாரனாகிய ஈசாக்கைவிட்டுக் கிழக்கே போகக் கீழ்தேசத்துக்கு அனுப்பிவிட்டான்.',	1,	25,	6),
(666,	'And these are the days of the years of Abraham\'s life which he lived, an hundred threescore and fifteen years.',	'ஆபிரகாம் உயிரோடிருந்த ஆயுசு நாட்கள் நூற்று எழுபத்தைந்து வருஷம்.',	1,	25,	7),
(667,	'Then Abraham gave up the ghost, and died in a good old age, an old man, and full of years; and was gathered to his people.',	'பிற்பாடு ஆபிரகாம் நல்ல நரைவயதிலும், முதிர்ந்த பூரண ஆயுசிலும் பிராணன்போய் மரித்து, தன் ஜனத்தாரோடே சேர்க்கப்பட்டான்.',	1,	25,	8),
(668,	'And his sons Isaac and Ishmael buried him in the cave of Machpelah, in the field of Ephron the son of Zohar the Hittite, which is before Mamre;',	'அவன் குமாரராகிய ஈசாக்கும் இஸ்மவேலும் மம்ரேக்கு எதிரே ஏத்தியனான சோகாரின் குமாரனாகிய எப்பெரோனின் நிலத்திலுள்ள மக்பேலா என்னப்பட்ட குகையிலே அவனை அடக்கம்பண்ணினார்கள்.',	1,	25,	9),
(669,	'The field which Abraham purchased of the sons of Heth: there was Abraham buried, and Sarah his wife.',	'அந்த நிலத்தை ஏத்தின் புத்திரர் கையிலே ஆபிரகாம் வாங்கியிருந்தான்; அங்கே ஆபிரகாமும் அவன் மனைவியாகிய சாராளும் அடக்கம்பண்ணப்பட்டார்கள்.',	1,	25,	10),
(670,	'And it came to pass after the death of Abraham, that God blessed his son Isaac; and Isaac dwelt by the well Lahairoi.',	'ஆபிரகாம் மரித்தபின் தேவன் அவன் குமாரனாகிய ஈசாக்கை ஆசீர்வதித்தார். லகாய்ரோயீ என்னும் துரவுக்குச் சமீபமாய் ஈசாக்கு குடியிருந்தான்.',	1,	25,	11),
(671,	'Now these are the generations of Ishmael, Abraham\'s son, whom Hagar the Egyptian, Sarah\'s handmaid, bare unto Abraham:',	'சாராளுடைய அடிமைப்பெண்ணாகிய எகிப்து தேசத்தாளான ஆகார் ஆபிரகாமுக்குப் பெற்ற குமாரனாகிய இஸ்மவேலின் வம்சவரலாறு:',	1,	25,	12),
(672,	'And these are the names of the sons of Ishmael, by their names, according to their generations: the firstborn of Ishmael, Nebajoth; and Kedar, and Adbeel, and Mibsam,',	'பற்பல சந்ததிகளாய்ப் பிரிந்த இஸ்மவேலின் புத்திரருடைய நாமங்களாவன; இஸ்மவேலுடைய மூத்த மகன் நெபாயோத், பின்பு கேதார், அத்பியேல், மிப்சாம்,',	1,	25,	13),
(673,	'And Mishma, and Dumah, and Massa,',	'மிஷ்மா, தூமா, மாசா,',	1,	25,	14),
(674,	'Hadar, and Tema, Jetur, Naphish, and Kedemah:',	'ஆதார், தேமா, யெத்தூர், நாபீஸ், கேத்மா என்பவைகளே.',	1,	25,	15),
(675,	'These are the sons of Ishmael, and these are their names, by their towns, and by their castles; twelve princes according to their nations.',	'தங்கள் கிராமங்களிலும் அரண்களிலும் குடியிருந்த தங்கள் ஜனத்தாருக்குப் பன்னிரண்டு பிரபுக்களாகிய இஸ்மவேலின் குமாரர்கள் இவர்களே, இவர்களுடைய நாமங்களும் இவைகளே.',	1,	25,	16),
(676,	'And these are the years of the life of Ishmael, an hundred and thirty and seven years: and he gave up the ghost and died; and was gathered unto his people.',	'இஸ்மவேலின் வயது நூற்று முப்பத்தேழு. பின்பு அவன் பிராணன் போய் மரித்து, தன் ஜனத்தாரோடே சேர்க்கப்பட்டான்.',	1,	25,	17),
(677,	'And they dwelt from Havilah unto Shur, that is before Egypt, as thou goest toward Assyria: and he died in the presence of all his brethren.',	'அவர்கள் ஆவிலா துவக்கி எகிப்துக்கு எதிராக அசீரியாவுக்கு போகிற வழியிலிருக்கும் சூர்மட்டும் வாசம்பண்ணினார்கள். இது அவன் சகோதரர் எல்லாருக்கும் முன்பாக அவன் குடியேறின பூமி.',	1,	25,	18),
(678,	'And these are the generations of Isaac, Abraham\'s son: Abraham begat Isaac:',	'ஆபிரகாமின் குமாரனாகிய ஈசாக்குடைய வம்சவரலாறு; ஆபிரகாம் ஈசாக்கைப் பெற்றான்.',	1,	25,	19),
(679,	'And Isaac was forty years old when he took Rebekah to wife, the daughter of Bethuel the Syrian of Padanaram, the sister to Laban the Syrian.',	'ஈசாக்கு ரெபெக்காளை விவாகம்பண்ணுகிறபோது நாற்பது வயதாயிருந்தான்; இவள் பதான்அராம் என்னும் சீரியா தேசத்தானாகிய பெத்துவேலுக்குக் குமாரத்தியும், சீரியா தேசத்தானாகிய லாபானுக்குச் சகோதரியுமானவள்.',	1,	25,	20),
(680,	'And Isaac intreated the LORD for his wife, because she was barren: and the LORD was intreated of him, and Rebekah his wife conceived.',	'மலடியாயிருந்த தன் மனைவிக்காக ஈசாக்கு கர்த்தரை நோக்கி வேண்டுதல் செய்தான்; கர்த்தர் அவன் வேண்டுதலைக் கேட்டருளினார்; அவன் மனைவி ரெபெக்காள் கர்ப்பந்தரித்தாள்.',	1,	25,	21),
(681,	'And the children struggled together within her; and she said, If it be so, why am I thus? And she went to enquire of the LORD.',	'அவள் கர்ப்பத்திலே பிள்ளைகள் ஒன்றோடொன்று மோதிக்கொண்டிருந்தன; அப்பொழுது அவள்: இப்படியானால் எனக்கு எப்படியோ என்று சொல்லி, கர்த்தரிடத்தில் விசாரிக்கும்படி போனாள்.',	1,	25,	22),
(682,	'And the LORD said unto her, Two nations are in thy womb, and two manner of people shall be separated from thy bowels; and the one people shall be stronger than the other people; and the elder shall serve the younger.',	'அதற்குக் கர்த்தர்: இரண்டு ஜாதிகள் உன் கர்ப்பத்தில் உண்டாயிருக்கிறது; இரண்டுவித ஜனங்கள் உன் வயிற்றிலிருந்து பிரியும், அவர்களில் ஒரு ஜனத்தார் மற்ற ஜனத்தாரைப்பார்க்கிலும் பலத்திருப்பார்கள், மூத்தவன் இளையவனைச் சேவிப்பான் என்றார்.',	1,	25,	23),
(683,	'And when her days to be delivered were fulfilled, behold, there were twins in her womb.',	'பிரசவகாலம் பூரணமானபோது, அவள் கர்ப்பத்தில் இரட்டைப் பிள்ளைகள் இருந்தது.',	1,	25,	24),
(684,	'And the first came out red, all over like an hairy garment; and they called his name Esau.',	'மூத்தவன் சிவந்த நிறமுள்ளவனாயும் சர்வாங்கமும் ரோம அங்கி போர்த்தவன் போலவும் வெளிப்பட்டான்; அவனுக்கு ஏசா என்று பேரிட்டார்கள்.',	1,	25,	25),
(685,	'And after that came his brother out, and his hand took hold on Esau\'s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them.',	'பின்பு, அவன் சகோதரன் தன் கையினாலே ஏசாவின் குதிங்காலைப் பிடித்துக்கொண்டு வெளிப்பட்டான்; அவனுக்கு யாக்கோபு என்று பேரிட்டார்கள்; இவர்களை அவள் பெற்றபோது ஈசாக்கு அறுபது வயதாயிருந்தான்.',	1,	25,	26),
(686,	'And the boys grew: and Esau was a cunning hunter, a man of the field; and Jacob was a plain man, dwelling in tents.',	'இந்தப் பிள்ளைகள் பெரியவர்களானபோது, ஏசா வேட்டையில் வல்லவனும் வனசஞ்சாரியுமாய் இருந்தான்; யாக்கோபு குணசாலியும் கூடாரவாசியுமாய் இருந்தான்.',	1,	25,	27),
(687,	'And Isaac loved Esau, because he did eat of his venison: but Rebekah loved Jacob.',	'ஏசா வேட்டையாடிக் கொண்டுவருகிறது ஈசாக்கினுடைய வாய்க்கு ருசிகரமாயிருந்ததினாலே ஏசாவின்மேல் பட்சமாயிருந்தான்; ரெபெக்காளோ யாக்கோபின்மேல் பட்சமாயிருந்தாள்.',	1,	25,	28),
(688,	'And Jacob sod pottage: and Esau came from the field, and he was faint:',	'ஒருநாள் ஏசா வெளியிலிருந்து களைத்து வந்தபோது, யாக்கோபு கூழ் சமைத்துக்கொண்டிருந்தான்.',	1,	25,	29),
(689,	'And Esau said to Jacob, Feed me, I pray thee, with that same red pottage; for I am faint: therefore was his name called Edom.',	'அப்பொழுது ஏசா யாக்கோபை நோக்கி: அந்தச் சிவப்பான கூழிலே நான் சாப்பிடக் கொஞ்சம் தா, இளைத்திருக்கிறேன் என்றான்; இதனாலே அவனுக்கு ஏதோம் என்கிற பேர் உண்டாயிற்று.',	1,	25,	30),
(690,	'And Jacob said, Sell me this day thy birthright.',	'அப்பொழுது யாக்கோபு: உன் சேஷ்ட புத்திரபாகத்தை இன்று எனக்கு விற்றுப்போடு என்றான்.',	1,	25,	31),
(691,	'And Esau said, Behold, I am at the point to die: and what profit shall this birthright do to me?',	'அதற்கு ஏசா: இதோ, நான் சாகப்போகிறேனே, இந்தச் சேஷ்ட புத்திரபாகம் எனக்கு என்னத்திற்கு என்றான்.',	1,	25,	32),
(692,	'And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob.',	'அப்பொழுது யாக்கோபு: இன்று எனக்கு ஆணையிட்டுக்கொடு என்றான்; அவன் யாக்கோபுக்கு ஆணையிட்டு, தன் சேஷ்ட புத்திரபாகத்தை அவனுக்கு விற்றுப்போட்டான்.',	1,	25,	33),
(693,	'Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright.',	'அப்பொழுது யாக்கோபு ஏசாவுக்கு அப்பத்தையும் பயற்றங்கூழையும் கொடுத்தான்; அவன் புசித்துக் குடித்து எழுந்திருந்து போய்விட்டான். இப்படி ஏசா தன் சேஷ்ட புத்திரபாகத்தை அலட்சியம் பண்ணினான்.  ',	1,	25,	34),
(694,	'And there was a famine in the land, beside the first famine that was in the days of Abraham. And Isaac went unto Abimelech king of the Philistines unto Gerar.',	'ஆபிரகாமின் நாட்களில் உண்டான பஞ்சத்தை அல்லாமல், பின்னும் ஒரு பஞ்சம் தேசத்தில் உண்டாயிற்று; அப்பொழுது ஈசாக்கு பெலிஸ்தருக்கு ராஜாவாகிய அபிமெலேக்கினிடத்தில் கேராருக்குப் போனான்.',	1,	26,	1),
(695,	'And the LORD appeared unto him, and said, Go not down into Egypt; dwell in the land which I shall tell thee of:',	'கர்த்தர் அவனுக்குத் தரிசனமாகி: நீ எகிப்துக்குப் போகாமல், நான் உனக்குச் சொல்லும் தேசத்திலே குடியிரு.',	1,	26,	2),
(696,	'Sojourn in this land, and I will be with thee, and will bless thee; for unto thee, and unto thy seed, I will give all these countries, and I will perform the oath which I sware unto Abraham thy father;',	'இந்தத் தேசத்திலே வாசம்பண்ணு; நான் உன்னோடேகூட இருந்து, உன்னை ஆசீர்வதிப்பேன்; நான் உனக்கும் உன் சந்ததிக்கும் இந்தத் தேசங்கள் யாவையும் தந்து, உன் தகப்பனாகிய ஆபிரகாமுக்கு நான் இட்ட ஆணையை நிறைவேற்றுவேன்.',	1,	26,	3),
(697,	'And I will make thy seed to multiply as the stars of heaven, and will give unto thy seed all these countries; and in thy seed shall all the nations of the earth be blessed;',	'ஆபிரகாம் என் சொல்லுக்குக் கீழ்ப்படிந்து, என் விதிகளையும், என் கற்பனைகளையும், என் நியமங்களையும், என் பிரமாணங்களையும் கைக்கொண்டபடியினால்,',	1,	26,	4),
(698,	'Because that Abraham obeyed my voice, and kept my charge, my commandments, my statutes, and my laws.',	'நான் உன் சந்ததியை வானத்தின் நட்சத்திரங்களைப்போலப் பெருகப்பண்ணி, உன் சந்ததிக்கு இந்தத் தேசங்கள் யாவையும் தருவேன்; உன் சந்ததிக்குள் பூமியிலுள்ள சகல ஜாதிகளும் ஆசீர்வதிக்கப்படும் என்றார்.',	1,	26,	5),
(699,	'And Isaac dwelt in Gerar:',	'ஈசாக்கு கேராரிலே குடியிருந்தான்.',	1,	26,	6),
(700,	'And the men of the place asked him of his wife; and he said, She is my sister: for he feared to say, She is my wife; lest, said he, the men of the place should kill me for Rebekah; because she was fair to look upon.',	'அவ்விடத்து மனிதர்கள் அவன் மனைவியைக்குறித்து விசாரித்தபோது: இவள் என் சகோதரி என்றான். ரெபெக்காள் பார்வைக்கு அழகுள்ளவளானபடியால், அவ்விடத்து மனிதர்கள் அவள்நிமித்தம் தன்னைக் கொல்லுவார்கள் என்று எண்ணி, அவளைத் தன் மனைவி என்று சொல்லப் பயந்தான்.',	1,	26,	7),
(701,	'And it came to pass, when he had been there a long time, that Abimelech king of the Philistines looked out at a window, and saw, and, behold, Isaac was sporting with Rebekah his wife.',	'அவன் அங்கே நெடுநாள் தங்கியிருக்கையில், பெலிஸ்தருக்கு ராஜாவாகிய அபிமெலேக்கு ஜன்னல் வழியாய்ப் பார்க்கும்போது, ஈசாக்கு தன் மனைவியாகிய ரெபெக்காளோடே விளையாடிக்கொண்டிருக்கிறதைக் கண்டான்.',	1,	26,	8),
(702,	'And Abimelech called Isaac, and said, Behold, of a surety she is thy wife; and how saidst thou, She is my sister? And Isaac said unto him, Because I said, Lest I die for her.',	'அபிமெலேக்கு ஈசாக்கை அழைத்து: அவள் உன் மனைவியாயிருக்கிறாளே! பின்னை ஏன் அவளை உன் சகோதரி என்று சொன்னாய் என்றான். அதற்கு ஈசாக்கு: அவள் நிமித்தம் நான் சாகாதபடிக்கு, இப்படிச் சொன்னேன் என்றான்.',	1,	26,	9),
(703,	'And Abimelech said, What is this thou hast done unto us? one of the people might lightly have lien with thy wife, and thou shouldest have brought guiltiness upon us.',	'அதற்கு அபிமெலேக்கு: எங்களிடத்தில் ஏன் இப்படிச் செய்தாய்? ஜனங்களுக்குள் யாராகிலும் உன் மனைவியோடே சயனிக்கவும், எங்கள்மேல் பழி சுமரவும் நீ இடமுண்டாக்கினாயே என்றான்.',	1,	26,	10),
(704,	'And Abimelech charged all his people, saying, He that toucheth this man or his wife shall surely be put to death.',	'பின்பு, அபிமெலேக்கு: இந்தப் புருஷனையாகிலும் இவன் மனைவியையாகிலும் தொடுகிறவன் நிச்சயமாய்க் கொலைசெய்யப்படுவான் என்று எல்லா ஜனங்களும் அறியச் சொன்னான்.',	1,	26,	11),
(705,	'Then Isaac sowed in that land, and received in the same year an hundredfold: and the LORD blessed him.',	'ஈசாக்கு அந்தத் தேசத்தில் விதைவிதைத்தான்; கர்த்தர் அவனை ஆசீர்வதித்ததினால் அந்த வருஷத்தில் நூறுமடங்கு பலன் அடைந்தான்;',	1,	26,	12),
(706,	'And the man waxed great, and went forward, and grew until he became very great:',	'அவன் ஐசுவரியவானாகி, வரவர விருத்தியடைந்து, மகா பெரியவனானான்.',	1,	26,	13),
(707,	'For he had possession of flocks, and possession of herds, and great store of servants: and the Philistines envied him.',	'அவனுக்கு ஆட்டு மந்தையும், மாட்டு மந்தையும், அநேக பணிவிடைக்காரரும் இருந்தபடியினாலே பெலிஸ்தர் அவன் பேரில் பொறாமைகொண்டு,',	1,	26,	14),
(708,	'For all the wells which his father\'s servants had digged in the days of Abraham his father, the Philistines had stopped them, and filled them with earth.',	'அவன் தகப்பனாகிய ஆபிரகாமின் நாட்களில் அவனுடைய வேலைக்காரர் வெட்டின துரவுகளையெல்லாம் தூர்த்து மண்ணினால் நிரப்பிப்போட்டார்கள்.',	1,	26,	15),
(709,	'And Abimelech said unto Isaac, Go from us; for thou art much mightier than we.',	'அபிமெலேக்கு ஈசாக்கை நோக்கி: நீ எங்களை விட்டுப் போய்விடு; எங்களைப் பார்க்கிலும் மிகவும் பலத்தவனானாய் என்றான்.',	1,	26,	16),
(710,	'And Isaac departed thence, and pitched his tent in the valley of Gerar, and dwelt there.',	'அப்பொழுது ஈசாக்கு அவ்விடம் விட்டுப் புறப்பட்டு, கேராரின் பள்ளத்தாக்கிலே கூடாரம் போட்டு, அங்கே குடியிருந்து,',	1,	26,	17),
(711,	'And Isaac digged again the wells of water, which they had digged in the days of Abraham his father; for the Philistines had stopped them after the death of Abraham: and he called their names after the names by which his father had called them.',	'தன் தகப்பனாகிய ஆபிரகாமின் நாட்களில் வெட்டினவைகளும், ஆபிரகாம் மரித்தபின் பெலிஸ்தர் தூர்த்துப்போட்டவைகளுமான துரவுகளை மறுபடியும் தோண்டி, தன் தகப்பன் அவைகளுக்கு இட்டிருந்த பேர்களின்படியே அவைகளுக்குப் பேரிட்டான்.',	1,	26,	18),
(712,	'And Isaac\'s servants digged in the valley, and found there a well of springing water.',	'ஈசாக்குடைய வேலைக்காரர் பள்ளத்தாக்கிலே வெட்டி, அங்கே சுரக்கும் நீரூற்றைக் கண்டார்கள்.',	1,	26,	19),
(713,	'And the herdmen of Gerar did strive with Isaac\'s herdmen, saying, The water is ours: and he called the name of the well Esek; because they strove with him.',	'கேராரூர் மேய்ப்பர் இந்தத் தண்ணீர் தங்களுடையது என்று சொல்லி, ஈசாக்குடைய மேய்ப்பருடனே வாக்குவாதம்பண்ணினார்கள்; அவர்கள் தன்னோடே வாக்குவாதம் பண்ணினபடியால், அந்தத் துரவுக்கு ஏசேக்கு என்று பேரிட்டான்.',	1,	26,	20),
(714,	'And they digged another well, and strove for that also: and he called the name of it Sitnah.',	'வேறொரு துரவை வெட்டினார்கள்; அதைக்குறித்தும் வாக்குவாதம்பண்ணினார்கள்; ஆகையால் அதற்கு சித்னா என்று பேரிட்டான்.',	1,	26,	21),
(715,	'And he removed from thence, and digged another well; and for that they strove not: and he called the name of it Rehoboth; and he said, For now the LORD hath made room for us, and we shall be fruitful in the land.',	'பின்பு அவ்விடம்விட்டுப் பெயர்ந்துபோய், வேறொரு துரவை வெட்டினான்; அதைக்குறித்து அவர்கள் வாக்குவாதம்பண்ணவில்லை; அப்பொழுது அவன்: நாம் தேசத்தில் பலுகும்படிக்கு, இப்பொழுது கர்த்தர் நமக்கு இடம் உண்டாக்கினார் என்று சொல்லி, அதற்கு ரெகொபோத் என்று பேரிட்டான்.',	1,	26,	22),
(716,	'And he went up from thence to Beersheba.',	'அங்கேயிருந்து பெயெர்செபாவுக்குப் போனான்.',	1,	26,	23),
(717,	'And the LORD appeared unto him the same night, and said, I am the God of Abraham thy father: fear not, for I am with thee, and will bless thee, and multiply thy seed for my servant Abraham\'s sake.',	'அன்று ராத்திரியிலே கர்த்தர் அவனுக்குத் தரிசனமாகி: நான் உன் தகப்பனாகிய ஆபிரகாமுடைய தேவன், பயப்படாதே, நான் உன்னோடேகூட இருந்து, என் ஊழியக்காரனாகிய ஆபிரகாமினிமித்தம் உன்னை ஆசீர்வதித்து, உன் சந்ததியைப் பெருகப்பண்ணுவேன் என்றார்.',	1,	26,	24),
(718,	'And he builded an altar there, and called upon the name of the LORD, and pitched his tent there: and there Isaac\'s servants digged a well.',	'அங்கே அவன் ஒரு பலிபீடத்தைக் கட்டி, கர்த்தருடைய நாமத்தைத் தொழுதுகொண்டு, அங்கே தன் கூடாரத்தைப் போட்டான். அவ்விடத்தில் ஈசாக்கின் வேலைக்காரர் ஒரு துரவை வெட்டினார்கள்.',	1,	26,	25),
(719,	'Then Abimelech went to him from Gerar, and Ahuzzath one of his friends, and Phichol the chief captain of his army.',	'அபிமெலேக்கும் அவன் சிநேகிதனாகிய அகுசாத்தும் அவன் சேனாபதியாகிய பிகோலும், கேராரிலிருந்து அவனிடத்துக்கு வந்தார்கள்.',	1,	26,	26),
(720,	'And Isaac said unto them, Wherefore come ye to me, seeing ye hate me, and have sent me away from you?',	'அப்பொழுது ஈசாக்கு அவர்களை நோக்கி: ஏன் என்னிடத்தில் வந்தீர்கள்? நீங்கள் என்னைப் பகைத்து, என்னை உங்களிடத்தில் இராதபடிக்குத் துரத்திவிட்டீர்களே என்றான்.',	1,	26,	27),
(721,	'And they said, We saw certainly that the LORD was with thee: and we said, Let there be now an oath betwixt us, even betwixt us and thee, and let us make a covenant with thee;',	'அதற்கு அவர்கள்: நிச்சயமாய் கர்த்தர் உம்மோடேகூட இருக்கிறார் என்று கண்டோம்; ஆகையால் எங்களுக்கும் உமக்கும் ஒரு ஆணை ஏற்பாடு உண்டாகவேண்டும் என்று நாங்கள் நிர்ணயம் பண்ணினோம்.',	1,	26,	28),
(722,	'That thou wilt do us no hurt, as we have not touched thee, and as we have done unto thee nothing but good, and have sent thee away in peace: thou art now the blessed of the LORD.',	'நாங்கள் உம்மைத் தொடாமல், நன்மையையே உமக்குச் செய்து, உம்மைச் சமாதானத்தோடே அனுப்பிவிட்டதுபோல, நீரும் எங்களுக்குத் தீங்குசெய்யாதபடிக்கு உம்மோடே உடன்படிக்கை பண்ணிக்கொள்ள வந்தோம்; நீர் கர்த்தரால் ஆசீர்வதிக்கப்பட்டவராமே என்றார்கள்.',	1,	26,	29),
(723,	'And he made them a feast, and they did eat and drink.',	'அவன் அவர்களுக்கு விருந்துபண்ணினான், அவர்கள் புசித்துக் குடித்தார்கள்.',	1,	26,	30),
(724,	'And they rose up betimes in the morning, and sware one to another: and Isaac sent them away, and they departed from him in peace.',	'அதிகாலையில் எழுந்து ஒருவருக்கொருவர் ஆணையிட்டுக்கொண்டார்கள். பின்பு ஈசாக்கு அவர்களை அனுப்பிவிட்டான்; அவர்கள் அவனிடத்திலிருந்து சமாதானத்தோடே போய்விட்டார்கள்.',	1,	26,	31),
(725,	'And it came to pass the same day, that Isaac\'s servants came, and told him concerning the well which they had digged, and said unto him, We have found water.',	'அந்நாளில்தானே ஈசாக்கின் வேலைக்காரர் வந்து, தாங்கள் துரவு வெட்டின செய்தியை அவனுக்கு அறிவித்து, தண்ணீர் கண்டோம் என்றார்கள்.',	1,	26,	32),
(726,	'And he called it Shebah: therefore the name of the city is Beersheba unto this day.',	'அதற்கு சேபா என்று பேரிட்டான்; ஆகையால் அந்த ஊரின் பேர் இந்நாள் வரைக்கும் பெயெர்செபா என்னப்படுகிறது.',	1,	26,	33),
(727,	'And Esau was forty years old when he took to wife Judith the daughter of Beeri the Hittite, and Bashemath the daughter of Elon the Hittite:',	'ஏசா நாற்பது வயதானபோது, ஏத்தியனான பெயேரியினுடைய குமாரத்தியாகிய யூதீத்தையும், ஏத்தியனான ஏலோனுடைய குமாரத்தியாகிய பஸ்மாத்தையும் விவாகம்பண்ணினான்.',	1,	26,	34),
(728,	'Which were a grief of mind unto Isaac and to Rebekah.',	'அவர்கள் ஈசாக்குக்கும் ரெபெக்காளுக்கும் மனநோவாயிருந்தார்கள்.  ',	1,	26,	35),
(729,	'And it came to pass, that when Isaac was old, and his eyes were dim, so that he could not see, he called Esau his eldest son, and said unto him, My son: and he said unto him, Behold, here am I.',	'ஈசாக்கு முதிர்வயதானதினால் அவன் கண்கள் இருளடைந்து பார்வையற்றுப் போனபோது, அவன் தன் மூத்த குமாரனாகிய ஏசாவை அழைத்து, என் மகனே என்றான்; அவன், இதோ, இருக்கிறேன் என்றான்.',	1,	27,	1),
(730,	'And he said, Behold now, I am old, I know not the day of my death:',	'அப்பொழுது அவன்: நான் முதிர்வயதானேன், என் மரணம் இன்ன நாளில் என்று அறியேன்.',	1,	27,	2),
(731,	'Now therefore take, I pray thee, thy weapons, thy quiver and thy bow, and go out to the field, and take me some venison;',	'ஆகையால், நீ உன் ஆயுதங்களாகிய உன் அம்பறாத்தூணியையும் உன் வில்லையும் எடுத்துக்கொண்டு வனத்துக்குப்போய், எனக்காக வேட்டையாடி,',	1,	27,	3),
(732,	'And make me savoury meat, such as I love, and bring it to me, that I may eat; that my soul may bless thee before I die.',	'அதை எனக்குப் பிரியமாயிருக்கிற ருசியுள்ள பதார்த்தங்களாகச் சமைத்து, நான் புசிக்கவும், நான் மரணமடையுமுன்னே என் ஆத்துமா உன்னை ஆசீர்வதிக்கவும், என்னிடத்தில் கொண்டுவா என்றான்.',	1,	27,	4),
(733,	'And Rebekah heard when Isaac spake to Esau his son. And Esau went to the field to hunt for venison, and to bring it.',	'ஈசாக்கு தன் குமாரனாகிய ஏசாவோடே பேசுகையில், ரெபெக்காள் கேட்டுக்கொண்டிருந்தாள். ஏசா வேட்டையாடிக்கொண்டுவரும்படி வனத்துக்குப் போனான்.',	1,	27,	5),
(734,	'And Rebekah spake unto Jacob her son, saying, Behold, I heard thy father speak unto Esau thy brother, saying,',	'அப்பொழுது ரெபெக்காள் தன் குமாரனாகிய யாக்கோபை நோக்கி: உன் தகப்பன் உன் சகோதரனாகிய ஏசாவை அழைத்து:',	1,	27,	6),
(735,	'Bring me venison, and make me savoury meat, that I may eat, and bless thee before the LORD before my death.',	'நான் புசித்து, எனக்கு மரணம் வருமுன்னே, கர்த்தரை முன்னிட்டு உன்னை ஆசீர்வதிக்கும்படி, நீ எனக்காக வேட்டையாடி, அதை எனக்கு ருசியுள்ள பதார்த்தங்களாகச் சமைத்துக்கொண்டுவா என்று சொல்லக்கேட்டேன்.',	1,	27,	7),
(736,	'Now therefore, my son, obey my voice according to that which I command thee.',	'ஆகையால், என் மகனே, என் சொல்லைக் கேட்டு, நான் உனக்குக் கற்பிக்கிறபடி செய்.',	1,	27,	8),
(737,	'Go now to the flock, and fetch me from thence two good kids of the goats; and I will make them savoury meat for thy father, such as he loveth:',	'நீ ஆட்டுமந்தைக்குப் போய், இரண்டு நல்ல வெள்ளாட்டுக்குட்டிகளைக் கொண்டுவா; நான் அவைகளை உன் தகப்பனுக்குப் பிரியமானபடி ருசியுள்ள பதார்த்தங்களாகச் சமைப்பேன்.',	1,	27,	9),
(738,	'And thou shalt bring it to thy father, that he may eat, and that he may bless thee before his death.',	'உன் தகப்பன் தாம் மரணமடையுமுன்னே உன்னை ஆசீர்வதிக்குபடி அவர் புசிப்பதற்கு நீ அதை அவரிடத்தில் கொண்டுபோகவேண்டும் என்றாள்.',	1,	27,	10),
(739,	'And Jacob said to Rebekah his mother, Behold, Esau my brother is a hairy man, and I am a smooth man:',	'அதற்கு யாக்கோபு தன் தாயாகிய ரெபெக்காளை நோக்கி: என் சகோதரனாகிய ஏசா ரோமம் மிகுந்தவன், நான் ரோமமில்லாதவன்.',	1,	27,	11),
(740,	'My father peradventure will feel me, and I shall seem to him as a deceiver; and I shall bring a curse upon me, and not a blessing.',	'ஒருவேளை என் தகப்பன் என்னைத்தடவிப்பார்ப்பார்; அப்பொழுது நான் அவருக்கு எத்தனாய்க் காணப்பட்டு, என்மேல் ஆசீர்வாதத்தை அல்ல, சாபத்தை வரப்பண்ணிக்கொள்வேனே என்றான்.',	1,	27,	12),
(741,	'And his mother said unto him, Upon me be thy curse, my son: only obey my voice, and go fetch me them.',	'அதற்கு அவன் தாய்: என் மகனே, உன்மேல் வரும் சாபம் என்மேல் வரட்டும்; என் சொல்லைமாத்திரம் கேட்டு, நீ போய், அவைகளை என்னிடத்தில் கொண்டுவா என்றாள்.',	1,	27,	13),
(742,	'And he went, and fetched, and brought them to his mother: and his mother made savoury meat, such as his father loved.',	'அவன் போய் அவைகளைப் பிடித்து, தன் தாயினிடத்தில் கொண்டுவந்தான்; அவனுடைய தாய் அவன் தகப்பனுக்குப்பிரியமானபடி ருசியுள்ள பதார்த்தங்களைச் சமைத்தாள்.',	1,	27,	14),
(743,	'And Rebekah took goodly raiment of her eldest son Esau, which were with her in the house, and put them upon Jacob her younger son:',	'பின்பு, ரெபெக்காள் வீட்டிலே தன்னிடத்தில் இருந்த தன் மூத்த மகனாகிய ஏசாவின் நல்ல வஸ்திரங்களை எடுத்து, தன் இளைய மகனாகிய யாக்கோபுக்கு உடுத்தி,',	1,	27,	15),
(744,	'And she put the skins of the kids of the goats upon his hands, and upon the smooth of his neck:',	'வெள்ளாட்டுக்குட்டிகளின் தோலை அவன் கைகளிலேயும் ரோமமில்லாத அவன் கழுத்திலேயும் போட்டு;',	1,	27,	16),
(745,	'And she gave the savoury meat and the bread, which she had prepared, into the hand of her son Jacob.',	'தான் சமைத்த ருசியுள்ள பதார்த்தங்களையும் அப்பங்களையும் தன் குமாரனாகிய யாக்கோபின் கையிலே கொடுத்தாள்.',	1,	27,	17),
(746,	'And he came unto his father, and said, My father: and he said, Here am I; who art thou, my son?',	'அவன் தன் தகப்பனிடத்தில் வந்து, என் தகப்பனே என்றான்; அதற்கு அவன்: இதோ, இருக்கிறேன்; நீ யார், என் மகனே என்றான்.',	1,	27,	18),
(747,	'And Jacob said unto his father, I am Esau thy first born; I have done according as thou badest me: arise, I pray thee, sit and eat of my venison, that thy soul may bless me.',	'அப்பொழுது யாக்கோபு தன் தகப்பனை நோக்கி: நான் உமது மூத்த மகனாகிய ஏசா; நீர் எனக்குச் சொன்னபடியே செய்தேன்; உம்முடைய ஆத்துமா என்னை ஆசீர்வதிக்கும்படி, நீர் எழுந்து உட்கார்ந்து, நான் வேட்டையாடிக்கொண்டு வந்ததைப் புசியும் என்றான்.',	1,	27,	19),
(748,	'And Isaac said unto his son, How is it that thou hast found it so quickly, my son? And he said, Because the LORD thy God brought it to me.',	'அப்பொழுது ஈசாக்குத் தன் குமாரனை நோக்கி: என் மகனே, இது உனக்கு இத்தனை சீக்கிரமாய் எப்படி அகப்பட்டது என்றான். அவன்: உம்முடைய தேவனாகிய கர்த்தர் எனக்கு நேரிடப்பண்ணினார் என்றான்.',	1,	27,	20),
(749,	'And Isaac said unto Jacob, Come near, I pray thee, that I may feel thee, my son, whether thou be my very son Esau or not.',	'அப்பொழுது ஈசாக்கு யாக்கோபை நோக்கி: என் மகனே, நீ என் குமாரனாகிய ஏசாதானோ அல்லவோ என்று நான் உன்னைத் தடவிப்பார்க்கும்படி கிட்ட வா என்றான்.',	1,	27,	21),
(750,	'And Jacob went near unto Isaac his father; and he felt him, and said, The voice is Jacob\'s voice, but the hands are the hands of Esau.',	'யாக்கோபு தன் தகப்பனாகிய ஈசாக்கண்டையில் கிட்டப் போனான்; அவன் இவனைத் தடவிப்பார்த்து: சத்தம் யாக்கோபின் சத்தம், கைகளோ ஏசாவின் கைகள் என்று சொல்லி,',	1,	27,	22),
(751,	'And he discerned him not, because his hands were hairy, as his brother Esau\'s hands: so he blessed him.',	'அவனுடைய கைகள் அவன் சகோதரனாகிய ஏசாவின் கைகளைப்போல ரோமமுள்ளவைகளாயிருந்தபடியினாலே, இன்னான் என்று அறியாமல், அவனை ஆசீர்வதித்து,',	1,	27,	23),
(752,	'And he said, Art thou my very son Esau? And he said, I am.',	'நீ என் குமாரனாகிய ஏசாதானோ என்றான்; அவன்: நான்தான் என்றான்.',	1,	27,	24),
(753,	'And he said, Bring it near to me, and I will eat of my son\'s venison, that my soul may bless thee. And he brought it near to him, and he did eat: and he brought him wine and he drank.',	'அப்பொழுது அவன்: என் குமாரனே, நீ வேட்டையாடிக் கொண்டுவந்ததை நான் புசித்து, என் ஆத்துமா உன்னை ஆசீர்வதிக்கும்படி அதை என்கிட்டக் கொண்டுவா என்றான்; அவன் அதைக் கிட்டக் கொண்டுபோனான்; அப்பொழுது அவன் புசித்தான்; பிற்பாடு, திராட்சரசம் அவனுக்குக் கொண்டுவந்து கொடுத்தான், அவன் குடித்தான்.',	1,	27,	25),
(754,	'And his father Isaac said unto him, Come near now, and kiss me, my son.',	'அப்பொழுது அவன் தகப்பானாகிய ஈசாக்கு அவனை நோக்கி: என் மகனே, நீ கிட்ட வந்து என்னை முத்தஞ்செய் என்றான்.',	1,	27,	26),
(755,	'And he came near, and kissed him: and he smelled the smell of his raiment, and blessed him, and said, See, the smell of my son is as the smell of a field which the LORD hath blessed:',	'அவன் கிட்டப் போய், அவனை முத்தஞ்செய்தான்; அப்பொழுது அவனுடைய வஸ்திரங்களின் வாசனையை மோந்து: இதோ, என் குமாரனுடைய வாசனை கர்த்தர் ஆசீர்வதித்த வயல்வெளியின் வாசனையைப்போல் இருக்கிறது.',	1,	27,	27),
(756,	'Therefore God give thee of the dew of heaven, and the fatness of the earth, and plenty of corn and wine:',	'தேவன் உனக்கு வானத்துப் பனியையும் பூமியின் கொழுமையையும் கொடுத்து, மிகுந்த தானியத்தையும் திராட்சரசத்தையும் தந்தருளுவாராக.',	1,	27,	28),
(757,	'Let people serve thee, and nations bow down to thee: be lord over thy brethren, and let thy mother\'s sons bow down to thee: cursed be every one that curseth thee, and blessed be he that blesseth thee.',	'ஜனங்கள் உன்னைச் சேவிக்கவும் ஜாதிகள் உன்னை வணங்கவும்கடவர்கள்; உன் சகோதரருக்கு எஜமானாயிருப்பாய்; உன் தாயின் பிள்ளைகள் உன்னை வணங்குவார்கள்; உன்னைச் சபிக்கிறவர்கள் சபிக்கப்பட்டவர்களும், உன்னை ஆசீர்வதிக்கிறவர்கள் ஆசீர்வதிக்கப்பட்டவர்களுமாய் இருப்பார்கள் என்று சொல்லி அவனை ஆசீர்வதித்தான்.',	1,	27,	29),
(758,	'And it came to pass, as soon as Isaac had made an end of blessing Jacob, and Jacob was yet scarce gone out from the presence of Isaac his father, that Esau his brother came in from his hunting.',	'ஈசாக்கு யாக்கோபை ஆசீர்வதித்து முடிந்தபோது, யாக்கோபு தன் தகப்பனாகிய ஈசாக்கின் சமுகத்தைவிட்டுப் புறப்பட்டவுடனே, அவன் சகோதரனாகிய ஏசா வேட்டையாடி வந்து சேர்ந்தான்.',	1,	27,	30),
(759,	'And he also had made savoury meat, and brought it unto his father, and said unto his father, Let my father arise, and eat of his son\'s venison, that thy soul may bless me.',	'அவனும் ருசியுள்ள பதார்த்தங்களைச் சமைத்து, தன் தகப்பனண்டைக்குக் கொண்டுவந்து, தகப்பனை நோக்கி: உம்முடைய ஆத்துமா என்னை ஆசீர்வதிக்கும்படி, என் தகப்பனார் எழுந்திருந்து, உம்முடைய குமாரனாகிய நான் வேட்டையாடிக் கொண்டுவந்ததைப் புசிப்பாராக என்றான்.',	1,	27,	31),
(760,	'And Isaac his father said unto him, Who art thou? And he said, I am thy son, thy firstborn Esau.',	'அப்பொழுது அவன் தகப்பனாகிய ஈசாக்கு: நீ யார் என்றான்; அதற்கு அவன்: நான் உமது மூத்த மகனாகிய ஏசா என்றான்.',	1,	27,	32),
(761,	'And Isaac trembled very exceedingly, and said, Who? where is he that hath taken venison, and brought it me, and I have eaten of all before thou camest, and have blessed him? yea, and he shall be blessed.',	'அப்பொழுது ஈசாக்கு மிகவும் பிரமித்து நடுங்கி: வேட்டையாடி எனக்குக் கொண்டுவந்தானே, அவன் யார்? நீ வருமுன்னே அவையெல்லாவற்றிலும் நான் புசித்து அவனை ஆசீர்வதித்தேனே, அவன் ஆசீர்வதிக்கப்பட்டவனாகவும் இருப்பான் என்றான்.',	1,	27,	33),
(762,	'And when Esau heard the words of his father, he cried with a great and exceeding bitter cry, and said unto his father, Bless me, even me also, O my father.',	'ஏசா தன் தகப்பனுடைய வார்த்தைகளைக் கேட்டவுடனே, மிகவும் மனங்கசந்து உரத்த சத்தமிட்டு அலறி, தன் தகப்பனை நோக்கி: என் தகப்பனே, என்னையும் ஆசீர்வதியும் என்றான்.',	1,	27,	34),
(763,	'And he said, Thy brother came with subtilty, and hath taken away thy blessing.',	'அதற்கு அவன்: உன் சகோதரன் தந்திரமாய் வந்து, உன்னுடைய ஆசீர்வாதத்தைப் பெற்றுக்கொண்டான் என்றான்.',	1,	27,	35),
(764,	'And he said, Is not he rightly named Jacob? for he hath supplanted me these two times: he took away my birthright; and, behold, now he hath taken away my blessing. And he said, Hast thou not reserved a blessing for me?',	'அப்பொழுது அவன்: அவன் பெயர் யாக்கோபு என்னப்படுவது சரியல்லவா? இதோடே இரண்டுதரம் என்னை மோசம் போக்கினான்; என் சேஷ்ட புத்திரபாகத்தை எடுத்துக்கொண்டான்; இதோ, இப்பொழுது என் ஆசீர்வாதத்தையும் வாங்கிக்கொண்டான் என்று சொல்லி, நீர் எனக்கு ஒரு ஆசீர்வாதத்தையாகிலும் வைத்துவைக்கவில்லையா என்றான்.',	1,	27,	36),
(765,	'And Isaac answered and said unto Esau, Behold, I have made him thy lord, and all his brethren have I given to him for servants; and with corn and wine have I sustained him: and what shall I do now unto thee, my son?',	'ஈசாக்கு ஏசாவுக்குப் பிரதியுத்தரமாக: இதோ, நான் அவனை உனக்கு எஜமானாக வைத்தேன்; அவன் சகோதரர் எல்லாரையும் அவனுக்கு ஊழியக்காரராகக் கொடுத்து, அவனைத் தானியத்தினாலும் திராட்சரசத்தினாலும் ஆதரித்தேன்; இப்பொழுதும் என் மகனே, நான் உனக்கு என்னசெய்வேன் என்றான்.',	1,	27,	37),
(766,	'And Esau said unto his father, Hast thou but one blessing, my father? bless me, even me also, O my father. And Esau lifted up his voice, and wept.',	'ஏசா தன் தகப்பனை நோக்கி: என் தகப்பனே, இந்த ஒரே ஆசீர்வாதம் மாத்திரமா உம்மிடத்தில் உண்டு? என் தகப்பனே, என்னையும் ஆசீர்வதியும் என்று சொல்லி, ஏசா சத்தமிட்டு அழுதான்.',	1,	27,	38),
(767,	'And Isaac his father answered and said unto him, Behold, thy dwelling shall be the fatness of the earth, and of the dew of heaven from above;',	'அப்பொழுது அவன் தகப்பனாகிய ஈசாக்கு அவனுக்குப் பிரதியுத்தரமாக: உன் வாசஸ்தலம் பூமியின் சாரத்தோடும் உயர வானத்திலிருந்து இறங்கும் பனியோடும் இருக்கும்.',	1,	27,	39),
(768,	'And by thy sword shalt thou live, and shalt serve thy brother; and it shall come to pass when thou shalt have the dominion, that thou shalt break his yoke from off thy neck.',	'உன் பட்டயத்தினாலே நீ பிழைத்து, உன் சகோதரனைச் சேவிப்பாய்; நீ மேற்கொள்ளும் காலம் வரும்போதோ, உன் கழுத்தில் இருக்கிற அவனுடைய நுகத்தடியை முறித்துப்போடுவாய் என்றான்.',	1,	27,	40),
(769,	'And Esau hated Jacob because of the blessing wherewith his father blessed him: and Esau said in his heart, The days of mourning for my father are at hand; then will I slay my brother Jacob.',	'யாக்கோபைத் தன் தகப்பன் ஆசீர்வதித்ததினிமித்தம் ஏசா யாக்கோபைப் பகைத்து: என் தகப்பனுக்காகத் துக்கிக்கும் நாட்கள் சீக்கிரமாய் வரும், அப்பொழுது என் சகோதரனாகிய யாக்கோபைக் கொன்றுபோடுவேன் என்று ஏசா தன் இருதயத்திலே சொல்லிக்கொண்டான்.',	1,	27,	41),
(770,	'And these words of Esau her elder son were told to Rebekah: and she sent and called Jacob her younger son, and said unto him, Behold, thy brother Esau, as touching thee, doth comfort himself, purposing to kill thee.',	'மூத்த மகனாகிய ஏசாவின் வார்த்தைகள் ரெபெக்காளுக்கு அறிவிக்கப்பட்டது; அப்பொழுது அவள் தன் இளைய மகனாகிய யாக்கோபை அழைத்து: உன் சகோதரனாகிய ஏசா உன்னைக் கொன்றுபோட நினைத்து, தன்னைத் தேற்றிக்கொள்ளுகிறான்.',	1,	27,	42),
(771,	'Now therefore, my son, obey my voice; arise, flee thou to Laban my brother to Haran;',	'ஆகையால், என் மகனே, நான் சொல்வதைக் கேட்டு, எழுந்து புறப்பட்டு, ஆரானில் இருக்கிற என் சகோதரனாகிய லாபானிடத்துக்கு ஓடிப்போய்,',	1,	27,	43),
(772,	'And tarry with him a few days, until thy brother\'s fury turn away;',	'உன் சகோதரன் உன்மேல் வைத்த கோபம் தணியுமட்டும் சிலநாள் அவனிடத்திலே இரு.',	1,	27,	44),
(773,	'Until thy brother\'s anger turn away from thee, and he forget that which thou hast done to him: then I will send, and fetch thee from thence: why should I be deprived also of you both in one day?',	'உன் சகோதரன் உன்மேல் வைத்த கோபம் தணிந்து, நீ அவனுக்குச் செய்ததை அவன் மறந்தபின், நான் ஆள் அனுப்பி, அவ்விடத்திலிருந்து உன்னை அழைப்பிப்பேன்; நான் ஒரே நாளில் உங்கள் இருவரையும் ஏன் இழந்துபோகவேண்டும் என்றாள்.',	1,	27,	45),
(774,	'And Rebekah said to Isaac, I am weary of my life because of the daughters of Heth: if Jacob take a wife of the daughters of Heth, such as these which are of the daughters of the land, what good shall my life do me?',	'பின்பு, ரெபெக்காள் ஈசாக்கை நோக்கி: ஏத்தின் குமாரத்திகளினிமித்தம் என் உயிர் எனக்கு வெறுப்பாயிருக்கிறது; இந்தத் தேசத்துப் பெண்களாகிய ஏத்தின் குமாரத்திகளில் யாக்கோபு ஒரு பெண்ணைக் கொள்வானானால் என் உயிர் இருந்து ஆவதென்ன என்றாள்.  ',	1,	27,	46),
(775,	'And Isaac called Jacob, and blessed him, and charged him, and said unto him, Thou shalt not take a wife of the daughters of Canaan.',	'ஈசாக்கு யாக்கோபை அழைத்து, அவனை ஆசீர்வதித்து, நீ கானானியருடைய குமாரத்திகளில் பெண்கொள்ளாமல்,',	1,	28,	1),
(776,	'Arise, go to Padanaram, to the house of Bethuel thy mother\'s father; and take thee a wife from thence of the daughers of Laban thy mother\'s brother.',	'எழுந்து புறப்பட்டு, பதான் அராமிலிருக்கிற உன் தாயினுடைய தகப்பனாகிய பெத்துவேலுடைய வீட்டுக்குப் போய், அவ்விடத்தில் உன் தாயின் சகோதரனாகிய லாபானின் குமாரத்திகளுக்குள் பெண்கொள் என்று அவனுக்குக் கட்டளையிட்டான்.',	1,	28,	2),
(777,	'And God Almighty bless thee, and make thee fruitful, and multiply thee, that thou mayest be a multitude of people;',	'சர்வவல்லமையுள்ள தேவன் உன்னை ஆசீர்வதித்து, நீ பல ஜனக்கூட்டமாகும்படி உன்னைப் பலுகவும் பெருகவும்பண்ணி;',	1,	28,	3),
(778,	'And give thee the blessing of Abraham, to thee, and to thy seed with thee; that thou mayest inherit the land wherein thou art a stranger, which God gave unto Abraham.',	'தேவன் ஆபிரகாமுக்குக் கொடுத்ததும் நீ பரதேசியாய்த் தங்குகிறதுமான தேசத்தை நீ சுதந்தரித்துக்கொள்ளும்படி ஆபிரகாமுக்கு அருளிய ஆசீர்வாதத்தை உனக்கும் உன் சந்ததிக்கும் அருளுவாராக என்று சொல்லி;',	1,	28,	4),
(779,	'And Isaac sent away Jacob: and he went to Padanaram unto Laban, son of Bethuel the Syrian, the brother of Rebekah, Jacob\'s and Esau\'s mother.',	'ஈசாக்கு யாக்கோபை அனுப்பிவிட்டான். அப்பொழுது அவன் பதான் அராமிலிருக்கும் சீரியா தேசத்தானாகிய பெத்துவேலுடைய குமாரனும், தனக்கும் ஏசாவுக்கும் தாயாகிய ரெபெக்காளின் சகோதரனுமான லாபானிடத்துக்குப் போகப் புறப்பட்டான்.',	1,	28,	5),
(780,	'When Esau saw that Isaac had blessed Jacob, and sent him away to Padanaram, to take him a wife from thence; and that as he blessed him he gave him a charge, saying, Thou shalt not take a wife of the daughers of Canaan;',	'ஈசாக்கு யாக்கோபை ஆசீர்வதித்து, ஒரு பெண்ணைக் கொள்ளும்படி அவனைப் பதான் அராமுக்கு அனுப்பினதையும், அவனை ஆசீர்வதிக்கையில்: நீ கானானியருடைய குமாரத்திகளில் பெண்கொள்ளவேண்டாம் என்று அவனுக்குக் கட்டளையிட்டதையும்,',	1,	28,	6),
(781,	'And that Jacob obeyed his father and his mother, and was gone to Padanaram;',	'யாக்கோபு தன் தகப்பனுக்கும் தன் தாய்க்கும் கீழ்ப்படிந்து, பதான் அராமுக்குப் புறப்பட்டுப்போனதையும் ஏசா கண்டதினாலும்,',	1,	28,	7),
(782,	'And Esau seeing that the daughters of Canaan pleased not Isaac his father;',	'கானானியருடைய குமாரத்திகள் தன் தகப்பனாகிய ஈசாக்கின் பார்வைக்கு ஆகாதவர்கள் என்பதை ஏசா அறிந்ததினாலும்,',	1,	28,	8),
(783,	'Then went Esau unto Ishmael, and took unto the wives which he had Mahalath the daughter of Ishmael Abraham\'s son, the sister of Nebajoth, to be his wife.',	'ஏசா இஸ்மவேலிடத்துக்குப் போய், தனக்கு முன்னிருந்த மனைவிகளுமன்றி, ஆபிரகாமுடைய குமாரனாகிய இஸ்மவேலின் குமாரத்தியும் நெபாயோத்தின் சகோதரியுமாகிய மகலாத்தையும் விவாகம் பண்ணினான்.',	1,	28,	9),
(784,	'And Jacob went out from Beersheba, and went toward Haran.',	'யாக்கோபு பெயெர்செபாவை விட்டுப் புறப்பட்டு ஆரானுக்குப் போகப் பிரயாணம்பண்ணி,',	1,	28,	10),
(785,	'And he lighted upon a certain place, and tarried there all night, because the sun was set; and he took of the stones of that place, and put them for his pillows, and lay down in that place to sleep.',	'ஒரு இடத்திலே வந்து, சூரியன் அஸ்தமித்தபடியினால், அங்கே ராத்தங்கி, அவ்விடத்துக் கற்களில் ஒன்றை எடுத்து, தன் தலையின்கீழ் வைத்து, அங்கே நித்திரை செய்யும்படி படுத்துக்கொண்டான்.',	1,	28,	11),
(786,	'And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it.',	'அங்கே அவன் ஒரு சொப்பனங்கண்டான்; இதோ, ஒரு ஏணி பூமியிலே வைக்கப்பட்டிருந்தது, அதின் நுனி வானத்தை எட்டியிருந்தது, அதிலே தேவதூதர் ஏறுகிறவர்களும் இறங்குகிறவர்களுமாய் இருந்தார்கள்.',	1,	28,	12),
(787,	'And, behold, the LORD stood above it, and said, I am the LORD God of Abraham thy father, and the God of Isaac: the land whereon thou liest, to thee will I give it, and to thy seed;',	'அதற்கு மேலாகக் கர்த்தர் நின்று: நான் உன் தகப்பனாகிய ஆபிரகாமின் தேவனும் ஈசாக்கின் தேவனுமாகிய கர்த்தர்; நீ படுத்திருக்கிற பூமியை உனக்கும் உன் சந்ததிக்கும் தருவேன்.',	1,	28,	13),
(788,	'And thy seed shall be as the dust of the earth, and thou shalt spread abroad to the west, and to the east, and to the north, and to the south: and in thee and in thy seed shall all the families of the earth be blessed.',	'உன் சந்ததி பூமியின் தூளைப்போலிருக்கும்; நீ மேற்கேயும், கிழக்கேயும், வடக்கேயும், தெற்கேயும் பரம்புவாய்; உனக்குள்ளும் உன் சந்ததிக்குள்ளும் பூமியின் வம்சங்களெல்லாம் ஆசீர்வதிக்கப்படும்.',	1,	28,	14),
(789,	'And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of.',	'நான் உன்னோடே இருந்து, நீ போகிற இடத்திலெல்லாம் உன்னைக் காத்து, இந்தத் தேசத்துக்கு உன்னைத்திரும்பி வரப்பண்ணுவேன்; நான் உனக்குச் சொன்னதைச் செய்யுமளவும் உன்னைக் கைவிடுவதில்லை என்றார்.',	1,	28,	15),
(790,	'And Jacob awaked out of his sleep, and he said, Surely the LORD is in this place; and I knew it not.',	'யாக்கோபு நித்திரை தெளிந்து விழித்தபோது: மெய்யாகவே கர்த்தர் இந்த ஸ்தலத்தில் இருக்கிறார்; இதை நான் அறியாதிருந்தேன் என்றான்.',	1,	28,	16),
(791,	'And he was afraid, and said, How dreadful is this place! this is none other but the house of God, and this is the gate of heaven.',	'அவன் பயந்து, இந்த ஸ்தலம் எவ்வளவு பயங்கரமாயிருக்கிறது! இது தேவனுடைய வீடேயல்லாமல் வேறல்ல, இது வானத்தின் வாசல் என்றான்.',	1,	28,	17),
(792,	'And Jacob rose up early in the morning, and took the stone that he had put for his pillows, and set it up for a pillar, and poured oil upon the top of it.',	'அதிகாலையிலே யாக்கோபு எழுந்து, தன் தலையின்கீழ் வைத்திருந்த கல்லை எடுத்து, அதைத் தூணாக நிறுத்தி, அதின்மேல் எண்ணெய் வார்த்து,',	1,	28,	18),
(793,	'And he called the name of that place Bethel: but the name of that city was called Luz at the first.',	'அந்த ஸ்தலத்திற்குப் பெத்தேல் என்று பேரிட்டான்; அதற்கு முன்னே அவ்வூருக்கு லூஸ் என்னும் பேர் இருந்தது.',	1,	28,	19),
(794,	'And Jacob vowed a vow, saying, If God will be with me, and will keep me in this way that I go, and will give me bread to eat, and raiment to put on,',	'அப்பொழுது யாக்கோபு: தேவன் என்னோடே இருந்து, நான் போகிற இந்த வழியிலே என்னைக் காப்பாற்றி, உண்ண ஆகாரமும், உடுக்க வஸ்திரமும் எனக்குத் தந்து,',	1,	28,	20),
(795,	'So that I come again to my father\'s house in peace; then shall the LORD be my God:',	'என்னை என் தகப்பன் வீட்டுக்குச் சமாதானத்தோடே திரும்பிவரப்பண்ணுவாரானால், கர்த்தர் எனக்குத் தேவனாயிருப்பார்;',	1,	28,	21),
(796,	'And this stone, which I have set for a pillar, shall be God\'s house: and of all that thou shalt give me I will surely give the tenth unto thee.',	'நான் தூணாக நிறுத்தின இந்தக் கல் தேவனுக்கு வீடாகும்; தேவரீர் எனக்குத் தரும் எல்லாவற்றிலும் உமக்குத் தசமபாகம் செலுத்துவேன் என்று சொல்லிப் பொருத்தனைபண்ணிக்கொண்டான்.  ',	1,	28,	22),
(797,	'Then Jacob went on his journey, and came into the land of the people of the east.',	'யாக்கோபு பிரயாணம்பண்ணி, கீழ்த்திசையாரின் தேசத்தில் போய்ச் சேர்ந்தான்.',	1,	29,	1),
(798,	'And he looked, and behold a well in the field, and, lo, there were three flocks of sheep lying by it; for out of that well they watered the flocks: and a great stone was upon the well\'s mouth.',	'அங்கே வயல்வெளியிலே ஒரு கிணற்றையும், அதின் அருகே மடக்கியிருக்கிற மூன்று ஆட்டுமந்தைகளையும் கண்டான்; அந்தக் கிணற்றிலே மந்தைகளுக்குத் தண்ணீர் காட்டுவார்கள்; அந்தக் கிணற்றின் வாய் ஒரு பெரிய கல்லினால் அடைக்கப்பட்டிருந்தது.',	1,	29,	2),
(799,	'And thither were all the flocks gathered: and they rolled the stone from the well\'s mouth, and watered the sheep, and put the stone again upon the well\'s mouth in his place.',	'அவ்விடத்தில் மந்தைகள் எல்லாம் சேர்ந்தபின் கிணற்றின் வாயிலிருக்கும் கல்லை மேய்ப்பர் புரட்டி, ஆடுகளுக்குத் தண்ணீர் காட்டி, மறுபடியும் கல்லை முன்னிருந்தபடி கிணற்றின் வாயில் வைப்பார்கள்.',	1,	29,	3),
(800,	'And Jacob said unto them, My brethren, whence be ye? And they said, Of Haran are we.',	'யாக்கோபு அவர்களைப் பார்த்து: சகோதரரே, நீங்கள் எவ்விடத்தார் என்றான்; அவர்கள், நாங்கள் ஆரான் ஊரார் என்றார்கள்.',	1,	29,	4),
(801,	'And he said unto them, Know ye Laban the son of Nahor? And they said, We know him.',	'அப்பொழுது அவன்: நாகோரின் குமாரனாகிய லாபானை அறிவீர்களா என்று கேட்டான்; அறிவோம் என்றார்கள்.',	1,	29,	5),
(802,	'And he said unto them, Is he well? And they said, He is well: and, behold, Rachel his daughter cometh with the sheep.',	'அவன் சுகமாயிருக்கிறானா என்று விசாரித்தான்; அதற்கு அவர்கள்: சுகமாயிருக்கிறான்; அவன் குமாரத்தியாகிய ராகேல், அதோ, ஆடுகளை ஓட்டிக்கொண்டு வருகிறாள் என்று சொன்னார்கள்.',	1,	29,	6),
(803,	'And he said, Lo, it is yet high day, neither is it time that the cattle should be gathered together: water ye the sheep, and go and feed them.',	'அப்பொழுது அவன்: இன்னும் வெகு பொழுதிருக்கிறதே; இது மந்தைகளைச் சேர்க்கிற வேளை அல்லவே, ஆடுகளுக்குத் தண்ணீர் காட்டி, இன்னும் மேயவிடலாம் என்றான்.',	1,	29,	7),
(804,	'And they said, We cannot, until all the flocks be gathered together, and till they roll the stone from the well\'s mouth; then we water the sheep.',	'அதற்கு அவர்கள்: எல்லா மந்தைகளும் சேருமுன்னே அப்படிச் செய்யக்கூடாது; சேர்ந்தபின் கிணற்றின் வாயிலுள்ள கல்லைப் புரட்டுவார்கள்; அப்பொழுது ஆடுகளுக்குத் தண்ணீர் காட்டுவோம் என்றார்கள்.',	1,	29,	8),
(805,	'And while he yet spake with them, Rachel came with her father\'s sheep; for she kept them.',	'அவர்களோடே அவன் பேசிக்கொண்டிருக்கும்போதே, தன் தகப்பனுடைய ஆடுகளை மேய்த்துக்கொண்டுருந்த ராகேல் அந்த ஆடுகளை ஓட்டிக்கொண்டு வந்தாள்.',	1,	29,	9),
(806,	'And it came to pass, when Jacob saw Rachel the daughter of Laban his mother\'s brother, and the sheep of Laban his mother\'s brother, that Jacob went near, and rolled the stone from the well\'s mouth, and watered the flock of Laban his mother\'s brother.',	'யாக்கோபு தன் தாயின் சகோதரனான லாபானுடைய குமாரத்தியாகிய ராகேலையும், தன் தாயின் சகோதரனாகிய லாபானின் ஆடுகளையும் கண்டபோது, யாக்கோபு போய், கிணற்றின் வாயிலிருந்த கல்லைப் புரட்டி, தன் தாயின் சகோதரனாகிய லாபானின் ஆடுகளுக்குத் தண்ணீர் காட்டினான்.',	1,	29,	10),
(807,	'And Jacob kissed Rachel, and lifted up his voice, and wept.',	'பின்பு யாக்கோபு ராகேலை முத்தஞ்செய்து, சத்தமிட்டு அழுது,',	1,	29,	11),
(808,	'And Jacob told Rachel that he was her father\'s brother, and that he was Rebekah\'s son: and she ran and told her father.',	'தான் அவள் தகப்பனுடைய மருமகனென்றும், ரெபெக்காளின் குமாரனென்றும் ராகேலுக்கு அறிவித்தான். அவள் ஓடிப்போய்த் தன் தகப்பனுக்கு அறிவித்தாள்.',	1,	29,	12),
(809,	'And it came to pass, when Laban heard the tidings of Jacob his sister\'s son, that he ran to meet him, and embraced him, and kissed him, and brought him to his house. And he told Laban all these things.',	'லாபான் தன் சகோதரியின் குமாரனாகிய யாக்கோபுடைய செய்தியைக் கேட்டபோது, அவனுக்கு எதிர்கொண்டோடி, அவனைக் கட்டிக்கொண்டு முத்தஞ்செய்து, தன் வீட்டுக்கு அழைத்துக்கொண்டுபோனான்; அவன் தன் காரியங்களையெல்லாம் விவரமாய் லாபானுக்குச் சொன்னான்.',	1,	29,	13),
(810,	'And Laban said to him, Surely thou art my bone and my flesh. And he abode with him the space of a month.',	'அப்பொழுது லாபான்: நீ என் எலும்பும் என் மாம்சமுமானவன் என்றான். ஒரு மாதம்வரைக்கும் யாக்கோபு அவனிடத்தில் தங்கினான்.',	1,	29,	14),
(811,	'And Laban said unto Jacob, Because thou art my brother, shouldest thou therefore serve me for nought? tell me, what shall thy wages be?',	'பின்பு லாபான் யாக்கோபை நோக்கி: நீ என் மருமகனாயிருப்பதினால், சும்மா எனக்கு வேலைசெய்யலாமா? சம்பளம் எவ்வளவு கேட்கிறாய், சொல் என்றான்.',	1,	29,	15),
(812,	'And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel.',	'லாபானுக்கு இரண்டு குமாரத்திகள் இருந்தார்கள்; மூத்தவள் பேர் லேயாள், இளையவள் பேர் ராகேல்.',	1,	29,	16),
(813,	'Leah was tender eyed; but Rachel was beautiful and well favoured.',	'லேயாளுடைய கண்கள் கூச்சப்பார்வையாயிருந்தது; ராகேலோ ரூபவதியும் பார்வைக்கு அழகானவளுமாயிருந்தாள்.',	1,	29,	17),
(814,	'And Jacob loved Rachel; and said, I will serve thee seven years for Rachel thy younger daughter.',	'யாக்கோபு ராகேல் பேரில் பிரியப்பட்டு: உம்முடைய இளைய குமாரத்தியாகிய ராகேலுக்காக உம்மிடத்தில் ஏழு வருஷம் வேலை செய்கிறேன் என்றான்.',	1,	29,	18),
(815,	'And Laban said, It is better that I give her to thee, than that I should give her to another man: abide with me.',	'அதற்கு லாபான்: நான் அவளை அந்நிய புருஷனுக்குக் கொடுக்கிறதைப்பார்க்கிலும், அவளை உனக்குக் கொடுக்கிறது உத்தமம், என்னிடத்தில் தரித்திரு என்றான்.',	1,	29,	19),
(816,	'And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her.',	'அந்தப்படியே யாக்கோபு ராகேலுக்காக ஏழு வருஷம் வேலை செய்தான்; அவள் பேரில் இருந்த பிரியத்தினாலே அந்த வருஷங்கள் அவனுக்குக் கொஞ்ச நாளாகத் தோன்றினது.',	1,	29,	20),
(817,	'And Jacob said unto Laban, Give me my wife, for my days are fulfilled, that I may go in unto her.',	'பின்பு யாக்கோபு லாபானை நோக்கி: என் நாட்கள் நிறைவேறினபடியால், என் மனைவியிடத்தில் நான் சேரும்படி அவளை எனக்குத் தரவேண்டும் என்றான்.',	1,	29,	21),
(818,	'And Laban gathered together all the men of the place, and made a feast.',	'அப்பொழுது லாபான் அவ்விடத்து மனிதர் எல்லாரையும் கூடிவரச்செய்து விருந்துபண்ணினான்.',	1,	29,	22),
(819,	'And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her.',	'அன்று இரவிலே அவன் தன் குமாரத்தியாகிய லேயாளை அழைத்துக்கொண்டுபோய், அவனிடத்தில் விட்டான்; அவளை அவன் சேர்ந்தான்.',	1,	29,	23),
(820,	'And Laban gave unto his daughter Leah Zilpah his maid for an handmaid.',	'லாபான் தன் வேலைக்காரியாகிய சில்பாளைத் தன் குமாரத்தியாகிய லேயாளுக்கு வேலைக்காரியாகக் கொடுத்தான்.',	1,	29,	24),
(821,	'And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me?',	'காலையிலே, இதோ, அவள் லேயாள் என்று யாக்கோபு கண்டு, லாபானை நோக்கி: ஏன் எனக்கு இப்படிச் செய்தீர்? ராகேலுக்காக அல்லவா உம்மிடத்தில் வேலைசெய்தேன்; பின்னை ஏன் எனக்கு வஞ்சகம்பண்ணினீர் என்றான்.',	1,	29,	25),
(822,	'And Laban said, It must not be so done in our country, to give the younger before the firstborn.',	'அதற்கு லாபான்: மூத்தவள் இருக்க இளையவளைக் கொடுப்பது இவ்விடத்து வழக்கம் அல்ல.',	1,	29,	26),
(823,	'Fulfil her week, and we will give thee this also for the service which thou shalt serve with me yet seven other years.',	'இவளுடைய ஏழு நாளை நிறைவேற்று; அவளையும் உனக்குத் தருவேன்; அவளுக்காகவும் நீ இன்னும் ஏழு வருஷம் என்னிடத்திலே வேலைசெய் என்றான்.',	1,	29,	27),
(824,	'And Jacob did so, and fulfilled her week: and he gave him Rachel his daughter to wife also.',	'அந்தபடியே யாக்கோபு, இவளுடைய ஏழு நாளை நிறைவேற்றினான். அப்பொழுது தன் குமாரத்தியாகிய ராகேலையும் அவனுக்கு மனைவியாகக் கொடுத்தான்.',	1,	29,	28),
(825,	'And Laban gave to Rachel his daughter Bilhah his handmaid to be her maid.',	'மேலும் லாபான் தன் வேலைக்காரியாகிய பில்காளைத் தன் குமாரத்தியாகிய ராகேலுக்கு வேலைக்காரியாகக் கொடுத்தான்.',	1,	29,	29),
(826,	'And he went in also unto Rachel, and he loved also Rachel more than Leah, and served with him yet seven other years.',	'யாக்கோபு ராகேலையும் சேர்ந்தான்; லேயாளைப்பார்க்கிலும் ராகேலை அவன் அதிகமாய் நேசித்து, பின்னும் ஏழு வருஷம் அவனிடத்தில் சேவித்தான்.',	1,	29,	30),
(827,	'And when the LORD saw that Leah was hated, he opened her womb: but Rachel was barren.',	'லேயாள் அற்பமாய் எண்ணப்பட்டாள் என்று கர்த்தர் கண்டு, அவள் கர்ப்பந்தரிக்கும்படி செய்தார்; ராகேலோ மலடியாயிருந்தாள்.',	1,	29,	31),
(828,	'And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the LORD hath looked upon my affliction; now therefore my husband will love me.',	'லேயாள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று: கர்த்தர் என் சிறுமையைப் பார்த்தருளினார்; இப்பொழுது என் புருஷன் என்னை நேசிப்பார் என்று சொல்லி, அவனுக்கு ரூபன் என்று பேரிட்டாள்.',	1,	29,	32),
(829,	'And she conceived again, and bare a son; and said, Because the LORD hath heard I was hated, he hath therefore given me this son also: and she called his name Simeon.',	'மறுபடியும் அவள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று: நான் அற்பமாய் எண்ணப்பட்டதைக் கர்த்தர் கேட்டருளி, இவனையும் எனக்குத் தந்தார் என்று சொல்லி, அவனுக்குச் சிமியோன் என்று பேரிட்டாள்.',	1,	29,	33),
(830,	'And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi.',	'பின்னும் அவள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று: என் புருஷனுக்கு மூன்று குமாரரைப் பெற்றபடியால் அவர் இப்பொழுது என்னோடே சேர்ந்திருப்பார் என்று சொல்லி, அவனுக்கு லேவி என்று பேரிட்டாள்.',	1,	29,	34),
(831,	'And she conceived again, and bare a son: and she said, Now will I praise the LORD: therefore she called his name Judah; and left bearing.',	'மறுபடியும் அவள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று: இப்பொழுது கர்த்தரைத் துதிப்பேன் என்று சொல்லி, அவனுக்கு யூதா என்று பேரிட்டாள்; பிற்பாடு அவளுக்குப் பிள்ளைப்பேறு நின்று போயிற்று.  ',	1,	29,	35),
(832,	'And when Rachel saw that she bare Jacob no children, Rachel envied her sister; and said unto Jacob, Give me children, or else I die.',	'ராகேல் தான் யாக்கோபுக்குப் பிள்ளைகளைப் பெறாததைக்கண்டு, தன் சகோதரியின்மேல் பொறாமைகொண்டு, யாக்கோபை நோக்கி: எனக்குப் பிள்ளைகொடும், இல்லாவிட்டால் நான் சாகிறேன் என்றாள்.',	1,	30,	1),
(833,	'And Jacob\'s anger was kindled against Rachel: and he said, Am I in God\'s stead, who hath withheld from thee the fruit of the womb?',	'அப்பொழுது யாக்கோபு ராகேலின் மேல் கோபங்கொண்டு: தேவனல்லோ உன் கர்ப்பத்தை அடைத்திருக்கிறார், நான் தேவனா? என்றான்.',	1,	30,	2),
(834,	'And she said, Behold my maid Bilhah, go in unto her; and she shall bear upon my knees, that I may also have children by her.',	'அப்பொழுது அவள்: இதோ, என் வேலைக்காரியாகிய பில்காள் இருக்கிறாளே; அவள் என் மடிக்குப் பிள்ளைகளைப் பெறவும், அவளாலாகிலும் என் வீடு கட்டப்படவும் அவளிடத்தில் சேரும் என்று சொல்லி,',	1,	30,	3),
(835,	'And she gave him Bilhah her handmaid to wife: and Jacob went in unto her.',	'அவனுக்குத் தன் வேலைக்காரியாகிய பில்காளை மனைவியாகக் கொடுத்தாள்; அப்படியே யாக்கோபு அவளைச் சேர்ந்தான்.',	1,	30,	4),
(836,	'And Bilhah conceived, and bare Jacob a son.',	'பில்காள் கர்ப்பவதியாகி, யாக்கோபுக்கு ஒரு குமாரனைப் பெற்றாள்.',	1,	30,	5),
(837,	'And Rachel said, God hath judged me, and hath also heard my voice, and hath given me a son: therefore called she his name Dan.',	'அப்பொழுது ராகேல்: தேவன் என் வழக்கைத் தீர்த்து, என் சத்தத்தையும் கேட்டு, எனக்கு ஒரு குமாரனைக் கொடுத்தார் என்று சொல்லி, அவனுக்குத் தாண் என்று பேரிட்டாள்.',	1,	30,	6),
(838,	'And Bilhah Rachel\'s maid conceived again, and bare Jacob a second son.',	'மறுபடியும் ராகேலின் வேலைக்காரியாகிய பில்காள் கர்ப்பவதியாகி, யாக்கோபுக்கு இரண்டாம் குமாரனைப் பெற்றாள்.',	1,	30,	7),
(839,	'And Rachel said, With great wrestlings have I wrestled with my sister, and I have prevailed: and she called his name Naphtali.',	'அப்பொழுது ராகேல்: நான் மகா போராட்டமாய் என் சகோதரியோடே போராடி மேற்கொண்டேன் என்று சொல்லி, அவனுக்கு நப்தலி என்று பேரிட்டாள்.',	1,	30,	8),
(840,	'When Leah saw that she had left bearing, she took Zilpah her maid, and gave her Jacob to wife.',	'லேயாள் தான் பிள்ளைபெறுகிறது நின்றுபோனதைக் கண்டு, தன் வேலைக்காரியாகிய சில்பாளை அழைத்து, அவளை யாக்கோபுக்கு மனைவியாகக் கொடுத்தாள்.',	1,	30,	9),
(841,	'And Zilpah Leah\'s maid bare Jacob a son.',	'லேயாளின் வேலைக்காரியாகிய சில்பாள் யாக்கோபுக்கு ஒரு குமாரனைப் பெற்றாள்.',	1,	30,	10),
(842,	'And Leah said, A troop cometh: and she called his name Gad.',	'அப்பொழுது லேயாள்: ஏராளமாகிறதென்று சொல்லி, அவனுக்குக் காத் என்று பேரிட்டாள்.',	1,	30,	11),
(843,	'And Zilpah Leah\'s maid bare Jacob a second son.',	'பின்பு லேயாளின் வேலைக்காரியாகிய சில்பாள் யாக்கோபுக்கு இரண்டாம் குமாரனைப் பெற்றாள்.',	1,	30,	12),
(844,	'And Leah said, Happy am I, for the daughters will call me blessed: and she called his name Asher.',	'அப்பொழுது லேயாள்: நான் பாக்கியவதி, ஸ்திரீகள் என்னைப் பாக்கியவதி என்பார்கள் என்று சொல்லி, அவனுக்கு ஆசேர் என்று பேரிட்டாள்.',	1,	30,	13),
(845,	'And Reuben went in the days of wheat harvest, and found mandrakes in the field, and brought them unto his mother Leah. Then Rachel said to Leah, Give me, I pray thee, of thy son\'s mandrakes.',	'கோதுமை அறுப்பு நாட்களிலே ரூபன் வயல்வெளியிலே போய், தூதாயீம் கனிகளைக் கண்டெடுத்து, அவைகளைக் கொண்டுவந்து தன் தாயாகிய லேயாளிடத்தில் கொடுத்தான். அப்பொழுது ராகேல் லேயாளை நோக்கி: உன் குமாரனுடைய தூதாயீம் கனியில் எனக்குக் கொஞ்சம் தா என்றாள்.',	1,	30,	14),
(846,	'And she said unto her, Is it a small matter that thou hast taken my husband? and wouldest thou take away my son\'s mandrakes also? And Rachel said, Therefore he shall lie with thee to night for thy son\'s mandrakes.',	'அதற்கு அவள்: நீ என் புருஷனை எடுத்துக்கொண்டது அற்பகாரியமா? என் குமாரனுடைய தூதாயீம் கனிகளையும் எடுத்துக்கொள்ளவேண்டுமோ என்றாள்; அதற்கு ராகேல்: உன் குமாரனுடைய தூதாயீம் கனிகளுக்கு ஈடாக இன்று இரவு அவர் உன்னோடே சயனிக்கட்டும் என்றாள்.',	1,	30,	15),
(847,	'And Jacob came out of the field in the evening, and Leah went out to meet him, and said, Thou must come in unto me; for surely I have hired thee with my son\'s mandrakes. And he lay with her that night.',	'சாயங்காலத்தில் யாக்கோபு வெளியிலிருந்து வருகையில் லேயாள் புறப்பட்டு அவனுக்கு எதிர்கொண்டுபோய்: என் குமாரனுடைய தூதாயீம் கனிகளால் உம்மைக் கொண்டேன்; ஆகையால், நீர் என்னிடத்தில் வரவேண்டும் என்றாள்; அவன் அன்று இரவு அவளோடே சயனித்தான்.',	1,	30,	16),
(848,	'And God hearkened unto Leah, and she conceived, and bare Jacob the fifth son.',	'தேவன் லேயாளுக்குச் செவிகொடுத்தார். அவள் கர்ப்பவதியாகி யாக்கோபுக்கு ஐந்தாம் குமாரனைப் பெற்றாள்.',	1,	30,	17),
(849,	'And Leah said, God hath given me my hire, because I have given my maiden to my husband: and she called his name Issachar.',	'அப்பொழுது லேயாள்: நான் என் வேலைக்காரியை என் புருஷனுக்குக் கொடுத்த பலனைத் தேவன் எனக்குத் தந்தார் என்று சொல்லி, அவனுக்கு இசக்கார் என்று பேரிட்டாள்.',	1,	30,	18),
(850,	'And Leah conceived again, and bare Jacob the sixth son.',	'அப்புறம் லேயாள் கர்ப்பவதியாகி யாக்கோபுக்கு ஆறாம் குமாரனைப் பெற்றாள்.',	1,	30,	19),
(851,	'And Leah said, God hath endued me with a good dowry; now will my husband dwell with me, because I have born him six sons: and she called his name Zebulun.',	'அப்பொழுது லேயாள்: தேவன் எனக்கு நல்ல ஈவைத் தந்தார்; என் புருஷனுக்கு நான் ஆறு குமாரரைப் பெற்றபடியால், இப்பொழுது அவர் என்னுடனே வாசம்பண்ணுவார் என்று சொல்லி, அவனுக்குச் செபுலோன் என்று பேரிட்டாள்.',	1,	30,	20),
(852,	'And afterwards she bare a daughter, and called her name Dinah.',	'பின்பு அவள் ஒரு குமாரத்தியையும் பெற்று, அவளுக்குத் தீனாள் என்று பேரிட்டாள்.',	1,	30,	21),
(853,	'And God remembered Rachel, and God hearkened to her, and opened her womb.',	'தேவன் ராகேலை நினைத்தருளினார்; அவளுக்குத் தேவன் செவிகொடுத்து, அவள் கர்ப்பந்தரிக்கும்படி செய்தார்.',	1,	30,	22),
(854,	'And she conceived, and bare a son; and said, God hath taken away my reproach:',	'அவள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று: தேவன் என் நிந்தையை நீக்கிவிட்டார் என்றும்,',	1,	30,	23),
(855,	'And she called his name Joseph; and said, The LORD shall add to me another son.',	'இன்னும் ஒரு குமாரனைக் கர்த்தர் எனக்குத் தருவார் என்றும் சொல்லி, அவனுக்கு யோசேப்பு என்று பேரிட்டாள்.',	1,	30,	24),
(856,	'And it came to pass, when Rachel had born Joseph, that Jacob said unto Laban, Send me away, that I may go unto mine own place, and to my country.',	'ராகேல் யோசேப்பைப் பெற்றபின், யாக்கோபு லாபானை நோக்கி: நான் என் ஸ்தானத்திற்கும் என் தேசத்திற்கும் போக என்னை அனுப்பிவிடும்.',	1,	30,	25),
(857,	'Give me my wives and my children, for whom I have served thee, and let me go: for thou knowest my service which I have done thee.',	'நான் உமக்கு ஊழியஞ்செய்து சம்பாதித்த என் மனைவிகளையும் என் பிள்ளைகளையும் எனக்குத் தாரும்; நான் போவேன், நான் உம்மிடத்தில் சேவித்த சேவகத்தை நீர் அறிந்திருக்கிறீர் என்றான்.',	1,	30,	26),
(858,	'And Laban said unto him, I pray thee, if I have found favour in thine eyes, tarry: for I have learned by experience that the LORD hath blessed me for thy sake.',	'அப்பொழுது லாபான்: உன் கண்களில் எனக்குத் தயவு கிடைத்ததேயானால் நீ இரு; உன் நிமித்தம் கர்த்தர் என்னை ஆசீர்வதித்தார் என்று குறிப்பினால் அறிந்தேன்.',	1,	30,	27),
(859,	'And he said, Appoint me thy wages, and I will give it.',	'உன் சம்பளம் இன்னதென்று எனக்குச் சொல், நான் அதைத் தருவேன் என்றான்.',	1,	30,	28),
(860,	'And he said unto him, Thou knowest how I have served thee, and how thy cattle was with me.',	'அதற்கு அவன்: நான் உம்மைச் சேவித்த விதமும், உம்முடைய மந்தை என்னிடத்தில் இருந்த விதமும் அறிந்திருக்கிறீர்.',	1,	30,	29),
(861,	'For it was little which thou hadst before I came, and it is now increased unto a multitude; and the LORD hath blessed thee since my coming: and now when shall I provide for mine own house also?',	'நான் வருமுன்னே உமக்கு இருந்தது கொஞ்சம்; நான் வந்தபின் கர்த்தர் உம்மை ஆசீர்வதித்ததினால் அது மிகவும் பெருகியிருக்கிறது; இனி நான் என் குடும்பத்துக்குச் சம்பாத்தியம்பண்ணுவது எப்பொழுது என்றான்.',	1,	30,	30),
(862,	'And he said, What shall I give thee? And Jacob said, Thou shalt not give me any thing: if thou wilt do this thing for me, I will again feed and keep thy flock.',	'அதற்கு அவன்: நான் உனக்கு என்ன தரவேண்டும் என்றான்; யாக்கோபு: நீர் எனக்கு ஒன்றும் தரவேண்டியதில்லை; நான் சொல்லுகிறபடி நீர் எனக்குச் செய்தால், உம்முடைய மந்தையைத் திரும்ப மேய்த்துக் காப்பேன்.',	1,	30,	31),
(863,	'I will pass through all thy flock to day, removing from thence all the speckled and spotted cattle, and all the brown cattle among the sheep, and the spotted and speckled among the goats: and of such shall be my hire.',	'நான் இன்றைக்குப்போய், உம்முடைய மந்தைகளையெல்லாம் பார்வையிட்டு, அவைகளில் புள்ளியும் வரியும் கறுப்புமுள்ள செம்மறியாடுகளையும், வரியும் புள்ளியுமுள்ள வெள்ளாடுகளையும் பிரித்துவிடுகிறேன்; அப்படிப்பட்டவை இனி எனக்குச் சம்பளமாயிருக்கட்டும்.',	1,	30,	32),
(864,	'So shall my righteousness answer for me in time to come, when it shall come for my hire before thy face: every one that is not speckled and spotted among the goats, and brown among the sheep, that shall be counted stolen with me.',	'அப்படியே இனிமேல் என் சம்பளமாகிய இவற்றை நீர் பார்வையிடும்போது, என் நீதி விளங்கும்; புள்ளியும் வரியுமில்லாத வெள்ளாடுகளும், கறுப்பான செம்மறியாடுகளும் என் வசத்தில் இருந்தால், அவையெல்லாம் என்னால் திருடிக்கொள்ளப்பட்டவைகளாய் எண்ணப்படட்டும் என்றான்.',	1,	30,	33),
(865,	'And Laban said, Behold, I would it might be according to thy word.',	'அதற்கு லாபான்: நீ சொன்னபடியே ஆகட்டும் என்று சொல்லி,',	1,	30,	34),
(866,	'And he removed that day the he goats that were ringstraked and spotted, and all the she goats that were speckled and spotted, and every one that had some white in it, and all the brown among the sheep, and gave them into the hand of his sons.',	'அந்நாளிலே கலப்பு நிறமும் வரியுமுள்ள வெள்ளாட்டுக் கடாக்களையும், புள்ளியும் வரியுமுள்ள வெள்ளாடுகள் யாவையும், சற்று வெண்மையும் கருமையுமுள்ள செம்மறியாடுகள் யாவையும் பிரித்து, தன் குமாரரிடத்தில் ஒப்புவித்து,',	1,	30,	35),
(867,	'And he set three days\' journey betwixt himself and Jacob: and Jacob fed the rest of Laban\'s flocks.',	'தனக்கும் யாக்கோபுக்கும் இடையிலே மூன்றுநாள் பிரயாணதூரத்தில் இருக்கும்படி வைத்தான். லாபானுடைய மற்ற ஆடுகளை யாக்கோபு மேய்த்தான்.',	1,	30,	36),
(868,	'And Jacob took him rods of green poplar, and of the hazel and chesnut tree; and pilled white strakes in them, and made the white appear which was in the rods.',	'பின்பு யாக்கோபு பச்சையாயிருக்கிற புன்னை, வாதுமை, அர்மோன் என்னும் மரங்களின் கொப்புகளை வெட்டி, இடையிடையே வெண்மை தோன்றும்படி, பட்டையை உரித்து,',	1,	30,	37),
(869,	'And he set the rods which he had pilled before the flocks in the gutters in the watering troughs when the flocks came to drink, that they should conceive when they came to drink.',	'தான் உரித்த கொப்புகளை ஆடுகள் தண்ணீர் குடிக்க வரும் கால்வாய்களிலும் தொட்டிகளிலும் ஆடுகளுக்கு எதிராகப் போட்டுவைப்பான்; ஆடுகள் தண்ணீர் குடிக்க வரும்போது பொலிவதுண்டு.',	1,	30,	38),
(870,	'And the flocks conceived before the rods, and brought forth cattle ringstraked, speckled, and spotted.',	'ஆடுகள் அந்தக் கொப்புகளுக்கு முன்பாகப் பொலிந்தபடியால், அவைகள் கலப்பு நிறமுள்ளதும் புள்ளியுள்ளதும் வரியுள்ளதுமான குட்டிகளைப் போட்டது.',	1,	30,	39),
(871,	'And Jacob did separate the lambs, and set the faces of the flocks toward the ringstraked, and all the brown in the flock of Laban; and he put his own flocks by themselves, and put them not unto Laban\'s cattle.',	'அந்த ஆட்டுக்குட்டிகளை யாக்கோபு பிரித்துக்கொண்டு, ஆடுகளை லாபானுடைய மந்தையிலிருக்கும் கலப்பு நிறமானவைகளுக்கும் கறுப்பானவைகளெல்லாவற்றிற்கும் எதிராக நிறுத்தி, தன் ஆடுகளை லாபானுடைய மந்தையோடே சேர்க்காமல், தனிப்புறமாக வைத்துக்கொள்வான்.',	1,	30,	40),
(872,	'And it came to pass, whensoever the stronger cattle did conceive, that Jacob laid the rods before the eyes of the cattle in the gutters, that they might conceive among the rods.',	'பலத்த ஆடுகள் பொலியும்போது, அந்தக் கொப்புகளுக்கு எதிரே பொலியும்படி யாக்கோபு அவைகளை அந்த ஆடுகளின் கண்களுக்கு முன்பாகக் கால்வாய்களிலே போட்டுவைப்பான்.',	1,	30,	41),
(873,	'But when the cattle were feeble, he put them not in: so the feebler were Laban\'s, and the stronger Jacob\'s.',	'பலவீனமான ஆடுகள் பொலியும்போது, அவைகளைப் போடாமலிருப்பான்; இதனால் பலவீனமானவைகள் லாபானையும், பலமுள்ளவைகள் யாக்கோபையும் சேர்ந்தன.',	1,	30,	42),
(874,	'And the man increased exceedingly, and had much cattle, and maidservants, and menservants, and camels, and asses.',	'இவ்விதமாய் அந்தப் புருஷன் மிகவும் விருத்தியடைந்து, திரளான ஆடுகளும், வேலைக்காரிகளும், வேலைக்காரரும், ஒட்டகங்களும், கழுதைகளும் உடையவனானான்.  ',	1,	30,	43),
(875,	'And he heard the words of Laban\'s sons, saying, Jacob hath taken away all that was our father\'s; and of that which was our father\'s hath he gotten all this glory.',	'பின்பு, லாபானுடைய குமாரர்: எங்கள் தகப்பனுக்கு உண்டானவைகள் யாவையும் யாக்கோபு எடுத்துக்கொண்டான் என்றும், எங்கள் தகப்பனுடைய பொருளினாலே இந்தச் செல்வத்தையெல்லாம் அடைந்தான் என்றும் சொன்ன வார்த்தைகளை யாக்கோபு கேட்டான்.',	1,	31,	1),
(876,	'And Jacob beheld the countenance of Laban, and, behold, it was not toward him as before.',	'லாபானின் முகத்தை யாக்கோபு பார்த்தபோது, அது நேற்று முந்தைநாள் இருந்ததுபோல் இராமல் வேறுபட்டிருக்கக் கண்டான்.',	1,	31,	2),
(877,	'And the LORD said unto Jacob, Return unto the land of thy fathers, and to thy kindred; and I will be with thee.',	'கர்த்தர் யாக்கோபை நோக்கி: உன் பிதாக்களுடைய தேசத்திற்கும் உன் இனத்தாரிடத்திற்கும் நீ திரும்பிப்போ; நான் உன்னோடேகூட இருப்பேன் என்றார்.',	1,	31,	3),
(878,	'And Jacob sent and called Rachel and Leah to the field unto his flock,',	'அப்பொழுது யாக்கோபு, ராகேலையும் லேயாளையும் வெளியிலே தன் மந்தையிடத்தில் அழைப்பித்து,',	1,	31,	4),
(879,	'And said unto them, I see your father\'s countenance, that it is not toward me as before; but the God of my father hath been with me.',	'அவர்களை நோக்கி உங்கள் தகப்பனுடைய முகம் நேற்று முந்தைநாள் இருந்ததுபோல இருக்கவில்லை என்று எனக்குத் தோன்றுகிறது; ஆனாலும் என் தகப்பனுடைய தேவன் என்னோடேகூட இருக்கிறார்.',	1,	31,	5),
(880,	'And ye know that with all my power I have served your father.',	'என்னால் இயன்றமட்டும் நான் உங்கள் தகப்பனுக்கு ஊழியஞ்செய்தேன் என்று நீங்கள் அறிந்திருக்கிறீர்கள்.',	1,	31,	6),
(881,	'And your father hath deceived me, and changed my wages ten times; but God suffered him not to hurt me.',	'உங்கள் தகப்பனோ, என்னை வஞ்சித்து, என் சம்பளத்தைப் பத்துமுறை மாற்றினான்; ஆனாலும் அவன் எனக்குத் தீங்குசெய்ய தேவன் அவனுக்கு இடங்கொடுக்கவில்லை.',	1,	31,	7),
(882,	'If he said thus, The speckled shall be thy wages; then all the cattle bare speckled: and if he said thus, The ringstraked shall be thy hire; then bare all the cattle ringstraked.',	'புள்ளியுள்ளவைகள் உன் சம்பளமாயிருக்கும் என்று அவன் சொன்னபோது, ஆடுகளெல்லாம் புள்ளியுள்ள குட்டிகளைப் போட்டது; கலப்புநிறமானவைகள் உன் சம்பளமாயிருக்கும் என்று அவன் சொன்னபோது, ஆடுகளெல்லாம் கலப்பு நிறக் குட்டிகளைப் போட்டது.',	1,	31,	8),
(883,	'Thus God hath taken away the cattle of your father, and given them to me.',	'இவ்விதமாய் தேவன் உங்கள் தகப்பனுடைய ஆடுகளை எடுத்து, எனக்குத் தந்தார்.',	1,	31,	9),
(884,	'And it came to pass at the time that the cattle conceived, that I lifted up mine eyes, and saw in a dream, and, behold, the rams which leaped upon the cattle were ringstraked, speckled, and grisled.',	'ஆடுகள் பொலியும் காலத்திலே நான் கண்ட சொப்பனத்தில் என் கண்களை ஏறெடுத்துப் பார்க்கும்போது, ஆடுகளோடே பொலியும் கடாக்கள் கலப்புநிறமும் புள்ளியும் வரியும் உள்ளவைகளாயிருக்கக் கண்டேன்.',	1,	31,	10),
(885,	'And the angel of God spake unto me in a dream, saying, Jacob: And I said, Here am I.',	'அன்றியும் தேவதூதன் ஒருவர் சொப்பனத்தில்: யாக்கோபே என்றார்; இதோ, இருக்கிறேன் என்றேன்.',	1,	31,	11),
(886,	'And he said, Lift up now thine eyes, and see, all the rams which leap upon the cattle are ringstraked, speckled, and grisled: for I have seen all that Laban doeth unto thee.',	'அப்பொழுது அவர்: உன் கண்களை ஏறெடுத்துப்பார்; ஆடுகளோடே பொலியும் கடாக்களெல்லாம் கலப்புநிறமும் புள்ளியும் வரியுமுள்ளவைகளாய் இருக்கிறது; லாபான் உனக்குச் செய்கிற யாவையும் கண்டேன்.',	1,	31,	12),
(887,	'I am the God of Bethel, where thou anointedst the pillar, and where thou vowedst a vow unto me: now arise, get thee out from this land, and return unto the land of thy kindred.',	'நீ தூணுக்கு அபிஷேகஞ்செய்து, எனக்கு ஒரு பொருத்தனையைப் பண்ணின பெத்தேலிலே உனக்குத் தரிசனமான தேவன் நானே; இப்பொழுது நீ எழுந்து, இந்தத் தேசத்தைவிட்டுப் புறப்பட்டு, உன் இனத்தாரிருக்கிற தேசத்திற்குத் திரும்பிப்போ என்று சொன்னார் என்றான்.',	1,	31,	13),
(888,	'And Rachel and Leah answered and said unto him, Is there yet any portion or inheritance for us in our father\'s house?',	'அதற்கு ராகேலும் லேயாளும்: எங்கள் தகப்பன் வீட்டிலே இனி எங்களுக்குப் பங்கும் சுதந்தரமும் உண்டோ?',	1,	31,	14),
(889,	'Are we not counted of him strangers? for he hath sold us, and hath quite devoured also our money.',	'அவரால் நாங்கள் அந்நியராய் எண்ணப்படவில்லையா? அவர் எங்களை விற்று, எங்கள் பணத்தையும் வாயிலே போட்டுக்கொண்டார்.',	1,	31,	15),
(890,	'For all the riches which God hath taken from our father, that is ours, and our children\'s: now then, whatsoever God hath said unto thee, do.',	'ஆகையால் தேவன் எங்கள் தகப்பனிடத்திலிருந்து எடுத்த ஐசுவரியம் எல்லாம் நமக்கும் நம்முடைய பிள்ளைகளுக்கும் உரியது; இப்படியிருக்க, தேவன் உமக்குச் சொன்னபடியெல்லாம் செய்யும் என்றார்கள்.',	1,	31,	16),
(891,	'Then Jacob rose up, and set his sons and his wives upon camels;',	'அப்பொழுது யாக்கோபு எழுந்து, தன் பிள்ளைகளையும் தன் மனைவிகளையும் ஒட்டகங்கள்மேல் ஏற்றி,',	1,	31,	17),
(892,	'And he carried away all his cattle, and all his goods which he had gotten, the cattle of his getting, which he had gotten in Padanaram, for to go to Isaac his father in the land of Canaan.',	'தான் பதான் அராமிலே சம்பாதித்த மிருகஜீவன்களாகிய மந்தைகள் அனைத்தையும் தன் பொருள்கள் எல்லாவற்றையும் எடுத்துக்கொண்டு, கானான் தேசத்தில் இருக்கிற தன் தகப்பனாகிய ஈசாக்கினிடத்துக்குப் போகப் புறப்பட்டான்.',	1,	31,	18),
(893,	'And Laban went to shear his sheep: and Rachel had stolen the images that were her father\'s.',	'லாபான், தன் ஆடுகளை மயிர்கத்தரிக்கப் போயிருந்தான்; அந்தச் சமயத்திலே ராகேல் தன் தகப்பனுடைய சுரூபங்களைத் திருடிக்கொண்டாள்.',	1,	31,	19),
(894,	'And Jacob stole away unawares to Laban the Syrian, in that he told him not that he fled.',	'யாக்கோபு தான் ஓடிப்போகிறதைச் சீரியனாகிய லாபானுக்கு அறிவியாமல், திருட்டளவாய்ப் போய்விட்டான்.',	1,	31,	20),
(895,	'So he fled with all that he had; and he rose up, and passed over the river, and set his face toward the mount Gilead.',	'இப்படியே அவன் தனக்கு உண்டானவைகளையெல்லாம் எடுத்துக்கொண்டு, ஆற்றைக் கடந்து, கீலேயாத் மலையை நோக்கி ஓடிப்போனான்.',	1,	31,	21),
(896,	'And it was told Laban on the third day that Jacob was fled.',	'யாக்கோபு ஓடிப்போனது மூன்றாம் நாளிலே லாபானுக்கு அறிவிக்கப்பட்டது.',	1,	31,	22),
(897,	'And he took his brethren with him, and pursued after him seven days\' journey; and they overtook him in the mount Gilead.',	'அப்பொழுது அவன், தன் சகோதரரைக் கூட்டிக்கொண்டு, ஏழுநாள் பிரயாணபரியந்தம் அவனைத் தொடர்ந்து போய், கீலேயாத் மலையிலே அவனைக் கண்டுபிடித்தான்.',	1,	31,	23),
(898,	'And God came to Laban the Syrian in a dream by night, and said unto him, Take heed that thou speak not to Jacob either good or bad.',	'அன்று ராத்திரி தேவன் சீரியா தேசத்தானாகிய லாபானுக்குச் சொப்பனத்தில் தோன்றி: நீ யாக்கோபோடே நன்மையே அன்றித் தீமை ஒன்றும் பேசாதபடிக்கு எச்சரிக்கையாயிரு என்றார்.',	1,	31,	24),
(899,	'Then Laban overtook Jacob. Now Jacob had pitched his tent in the mount: and Laban with his brethren pitched in the mount of Gilead.',	'லாபான் யாக்கோபினிடத்தில் வந்தான்; யாக்கோபு மலையிலே தன் கூடாரத்தைப் போட்டிருந்தான்; லாபானும் தன் சகோதரரோடேகூடக் கீலேயாத் மலையிலே கூடாரம் போட்டான்.',	1,	31,	25),
(900,	'And Laban said to Jacob, What hast thou done, that thou hast stolen away unawares to me, and carried away my daughters, as captives taken with the sword?',	'அப்பொழுது லாபான் யாக்கோபை நோக்கி: நீ திருட்டளவாய்ப் புறப்பட்டு, என் குமாரத்திகளை யுத்தத்தில் பிடித்த சிறைகளைப்போலக் கொண்டுவந்தது என்ன செய்கை?',	1,	31,	26),
(901,	'Wherefore didst thou flee away secretly, and steal away from me; and didst not tell me, that I might have sent thee away with mirth, and with songs, with tabret, and with harp?',	'நீ ஓடிப்போவதை மறைத்து, எனக்கு அறிவியாமல், திருட்டளவாய் என்னிடத்திலிருந்து வந்துவிட்டது என்ன? நான் உன்னைச் சந்தோஷமாய், சங்கீதம் மேளதாளம் கின்னரமுழக்கத்துடனே அனுப்புவேனே.',	1,	31,	27),
(902,	'And hast not suffered me to kiss my sons and my daughters? thou hast now done foolishly in so doing.',	'என் பிள்ளைகளையும் என் குமாரத்திகளையும் நான் முத்தஞ்செய்ய விடாமல் போனதென்ன? இந்தச் செய்கையை நீ மதியில்லாமல் செய்தாய்.',	1,	31,	28),
(903,	'It is in the power of my hand to do you hurt: but the God of your father spake unto me yesternight, saying, Take thou heed that thou speak not to Jacob either good or bad.',	'உங்களுக்குப் பொல்லாப்புச்செய்ய எனக்கு வல்லமை உண்டு; ஆகிலும், உங்கள் தகப்பனுடைய தேவன்: நீ யாக்கோபோடே நன்மையே அன்றித் தீமை ஒன்றும் பேசாதபடிக்கு எச்சரிக்கையாயிரு என்று நேற்று இராத்திரி என்னோடே சொன்னார்.',	1,	31,	29),
(904,	'And now, though thou wouldest needs be gone, because thou sore longedst after thy father\'s house, yet wherefore hast thou stolen my gods?',	'இப்பொழுதும் உன் தகப்பனுடைய வீட்டின்மேலுள்ள வாஞ்சையினால் நீ புறப்பட்டுப்போகிறதானால் போகலாம், என் தெய்வங்களை ஏன் திருடிக்கொண்டு போகிறாய் என்று கேட்டான்.',	1,	31,	30),
(905,	'And Jacob answered and said to Laban, Because I was afraid: for I said, Peradventure thou wouldest take by force thy daughters from me.',	'யாக்கோபு லாபானுக்குப் பிரதியுத்தரமாக: உம்முடைய குமாரத்திகளைப் பலாத்காரமாய்ப் பிடித்து வைத்துக்கொள்வீர் என்று நான் அஞ்சினதினாலே இப்படி வந்துவிட்டேன்.',	1,	31,	31),
(906,	'With whomsoever thou findest thy gods, let him not live: before our brethren discern thou what is thine with me, and take it to thee. For Jacob knew not that Rachel had stolen them.',	'ஆனாலும் யாரிடத்தில் உம்முடைய தெய்வங்களைக் கண்டுபிடிக்கிறீரோ, அவனை உயிரோடே விடவேண்டாம்; உம்முடைய பொருள்கள் ஏதாவது என் வசத்தில் உண்டானால் நீர் அதை நம்முடைய சகோதரருக்கு முன்பாகப் பரிசோதித்தறிந்து, அதை எடுத்துக்கொள்ளும் என்றான். ராகேல் அவைகளைத் திருடிக்கொண்டு வந்ததை யாக்கோபு அறியாதிருந்தான்.',	1,	31,	32),
(907,	'And Laban went into Jacob\'s tent, and into Leah\'s tent, and into the two maidservants\' tents; but he found them not. Then went he out of Leah\'s tent, and entered into Rachel\'s tent.',	'அப்பொழுது லாபான் யாக்கோபின் கூடாரத்திலும், லேயாளின் கூடாரத்திலும், இரண்டு வேலைக்காரிகளின் கூடாரத்திலும் பிரவேசித்துப் பார்த்தும் ஒன்றும் கண்டுபிடிக்கவில்லை; பின்பு, லேயாளின் கூடாரத்தைவிட்டு ராகேலின் கூடாரத்துக்குப் போனான்.',	1,	31,	33),
(908,	'Now Rachel had taken the images, and put them in the camel\'s furniture, and sat upon them. And Laban searched all the tent, but found them not.',	'ராகேல் அந்தச் சுரூபங்களை எடுத்து, ஒட்டகச் சேணத்தின்கீழ் வைத்து, அதின்மேல் உட்கார்ந்திருந்தாள். லாபான் கூடாரம் எங்கும் தடவிப்பார்த்தும், அவைகளைக் கண்டுபிடிக்கவில்லை.',	1,	31,	34),
(909,	'And she said to her father, Let it not displease my lord that I cannot rise up before thee; for the custom of women is upon me. And he searched but found not the images.',	'அவள் தன் தகப்பனை நோக்கி: என் ஆண்டவனாகிய உமக்கு முன்பாக நான் எழுந்திராததைக்குறித்துக் கோபங்கொள்ளவேண்டாம்; ஸ்திரீகளுக்குள்ள வழிபாடு எனக்கு உண்டாயிருக்கிறது என்றாள்; அப்படியே அவன் அந்தச் சுரூபங்களைத் தேடியும் கண்டுபிடிக்கவில்லை.',	1,	31,	35),
(910,	'And Jacob was wroth, and chode with Laban: and Jacob answered and said to Laban, What is my trespass? what is my sin, that thou hast so hotly pursued after me?',	'அப்பொழுது யாக்கோபுக்குக் கோபம் எழும்பி, லாபானோடே வாக்குவாதம்பண்ணி: நீர் என்னை இவ்வளவு உக்கிரமாய்த் தொடர்ந்துவரும்படிக்கு நான் செய்த தப்பிதம் என்ன? நான் செய்த துரோகம் என்ன?',	1,	31,	36),
(911,	'Whereas thou hast searched all my stuff, what hast thou found of all thy household stuff? set it here before my brethren and thy brethren, that they may judge betwixt us both.',	'என் தட்டுமுட்டுகளையெல்லாம் தடவிப்பார்த்தீரே; உம்முடைய வீட்டுத் தட்டுமுட்டுகளில் என்னத்தைக் கண்டுபிடித்தீர்? அதை என்னுடைய சகோதரருக்கும் உம்முடைய சகோதரருக்கும் முன்பாக இங்கே வையும்; அவர்கள் எனக்கும் உமக்கும் நடுத்தீர்க்கட்டும்.',	1,	31,	37),
(912,	'This twenty years have I been with thee; thy ewes and thy she goats have not cast their young, and the rams of thy flock have I not eaten.',	'இந்த இருபது வருஷகாலமாய் நான் உம்மிடத்தில் இருந்தேன்; உம்முடைய செம்மறியாடுகளும் வெள்ளாடுகளும் சினையழியவில்லை; உம்முடைய மந்தையின் கடாக்களை நான் தின்னவில்லை.',	1,	31,	38),
(913,	'That which was torn of beasts I brought not unto thee; I bare the loss of it; of my hand didst thou require it, whether stolen by day, or stolen by night.',	'பீறுண்டதை நான் உம்மிடத்துக்குக் கொண்டுவராமல், அதற்காக நான் உத்தரவாதம்பண்ணினேன்; பகலில் களவுபோனதையும், இரவில் களவுபோனதையும் என் கையில் கேட்டு வாங்கினீர்.',	1,	31,	39),
(914,	'Thus I was; in the day the drought consumed me, and the frost by night; and my sleep departed from mine eyes.',	'பகலிலே வெயிலும் இரவிலே குளிரும் என்னைப் பட்சித்தது; நித்திரை என் கண்களுக்குத் தூரமாயிருந்தது; இவ்விதமாய்ப் பாடுபட்டேன்.',	1,	31,	40),
(915,	'Thus have I been twenty years in thy house; I served thee fourteen years for thy two daughters, and six years for thy cattle: and thou hast changed my wages ten times.',	'இந்த இருபது வருஷகாலம் உம்முடைய வீட்டிலே இருந்தேன்; பதினாலு வருஷம் உம்முடைய இரண்டு குமாரத்திகளுக்காகவும், ஆறு வருஷம் உம்முடைய மந்தைக்காகவும் உம்மிடத்தில் சேவித்தேன்; பத்துமுறை என் சம்பளத்தை மாற்றினீர்.',	1,	31,	41),
(916,	'Except the God of my father, the God of Abraham, and the fear of Isaac, had been with me, surely thou hadst sent me away now empty. God hath seen mine affliction and the labour of my hands, and rebuked thee yesternight.',	'என் பிதாவின் தேவனாகிய ஆபிரகாமின் தேவனும் ஈசாக்கின் பயபக்திக்குரியவரும் என்னோடிராமற்போனால், நீர் இப்பொழுது என்னை வெறுமையாய் அனுப்பிவிட்டிருப்பீர்; தேவன் என் சிறுமையையும் என் கைப்பிரயாசத்தையும் பார்த்து, நேற்று இராத்திரி உம்மைக் கடிந்துகொண்டார் என்று சொன்னான்.',	1,	31,	42),
(917,	'And Laban answered and said unto Jacob, These daughters are my daughters, and these children are my children, and these cattle are my cattle, and all that thou seest is mine: and what can I do this day unto these my daughters, or unto their children which they have born?',	'அப்பொழுது லாபான் யாக்கோபுக்குப் பிரதியுத்தரமாக: இந்தக் குமாரத்திகள் என் குமாரத்திகள், இந்தப் பிள்ளைகள் என் பிள்ளைகள், இந்த மந்தை என் மந்தை; நீ காண்கிற யாவும் என்னுடையவைகள்; என் குமாரத்திகளாகிய இவர்களையும், இவர்கள் பெற்ற பிள்ளைகளையும் இன்று நான் என்ன செய்யக்கூடும்?',	1,	31,	43),
(918,	'Now therefore come thou, let us make a covenant, I and thou; and let it be for a witness between me and thee.',	'இப்பொழுதும் எனக்கும் உனக்கும் சாட்சியாயிருக்கும்பொருட்டு, நீயும் நானும் உடன்படிக்கைபண்ணிக்கொள்ளக்கடவோம் என்றான்.',	1,	31,	44),
(919,	'And Jacob took a stone, and set it up for a pillar.',	'அப்பொழுது யாக்கோபு ஒரு கல்லை எடுத்து, அதைத் தூணாக நிறுத்தினான்.',	1,	31,	45),
(920,	'And Jacob said unto his brethren, Gather stones; and they took stones, and made an heap: and they did eat there upon the heap.',	'பின்னும் யாக்கோபு தன் சகோதரரைப் பார்த்து, கற்களைக் குவியலாகச் சேருங்கள் என்றான்; அவர்கள் கற்களை எடுத்துக்கொண்டுவந்து, ஒரு குவியலாக்கி, அந்தக் குவியலின்மேல் போஜனம் பண்ணினார்கள்.',	1,	31,	46),
(921,	'And Laban called it Jegarsahadutha: but Jacob called it Galeed.',	'லாபான் அதற்கு ஜெகர்சகதூதா என்று பேரிட்டான்; யாக்கோபு அதற்குக் கலயெத் என்று பேரிட்டான்.',	1,	31,	47),
(922,	'And Laban said, This heap is a witness between me and thee this day. Therefore was the name of it called Galeed;',	'இந்தக் குவியல் இன்று எனக்கும் உனக்கும் சாட்சி என்று லாபான் சொன்னபடியினாலே, அதின் பேர் கலயெத் என்னப்பட்டது.',	1,	31,	48),
(923,	'And Mizpah; for he said, The LORD watch between me and thee, when we are absent one from another.',	'அல்லாமலும் அவன்: நாம் ஒருவரை ஒருவர் விட்டு மறைந்தபின், நீ என் குமாரத்திகளைத் துயரப்படுத்தி, அவர்களையல்லாமல் வேறே ஸ்திரீகளை விவாகம்பண்ணினாயானால், கர்த்தர் எனக்கும் உனக்கும் நடுநின்று கண்காணிக்கக்கடவர்;',	1,	31,	49),
(924,	'If thou shalt afflict my daughters, or if thou shalt take other wives beside my daughters, no man is with us; see, God is witness betwixt me and thee.',	'நம்முடனே ஒருவரும் இல்லை; பார், தேவனே எனக்கும் உனக்கும் சாட்சி என்று சொன்னபடியால், அது மிஸ்பா என்னும் பேர்பெற்றது.',	1,	31,	50),
(925,	'And Laban said to Jacob, Behold this heap, and behold this pillar, which I have cast betwixt me and thee:',	'பின்னும் லாபான் யாக்கோபை நோக்கி: இதோ, இந்தக் குவியலையும் எனக்கும் உனக்கும் நடுவாக நான் நிறுத்தின தூணையும் பார்.',	1,	31,	51),
(926,	'This heap be witness, and this pillar be witness, that I will not pass over this heap to thee, and that thou shalt not pass over this heap and this pillar unto me, for harm.',	'தீங்குசெய்ய நான் இந்தக் குவியலைக் கடந்து உன்னிடத்துக்கு வராதபடிக்கும், நீ இந்தக் குவியலையும் இந்தத் தூணையும் கடந்து என்னிடத்துக்கு வராதபடிக்கும் இந்தக் குவியலும் சாட்சி, இந்தத் தூணும் சாட்சி.',	1,	31,	52),
(927,	'The God of Abraham, and the God of Nahor, the God of their father, judge betwixt us. And Jacob sware by the fear of his father Isaac.',	'ஆபிரகாமின் தேவனும் நாகோரின் தேவனும் அவர்கள் பிதாக்களின் தேவனுமாயிருக்கிறவர் நமக்குள்ளே நடுநின்று நியாயந்தீர்ப்பாராக என்றான். அப்பொழுது யாக்கோபு தன் தகப்பனாகிய ஈசாக்கின் பயபக்திக்குரியவர்மேல் ஆணையிட்டான்.',	1,	31,	53),
(928,	'Then Jacob offered sacrifice upon the mount, and called his brethren to eat bread: and they did eat bread, and tarried all night in the mount.',	'பின்பு, யாக்கோபு மலையின்மேல் பலியிட்டு, போஜனம்பண்ணும்படி தன் சகோதரரை அழைத்தான்; அப்படியே அவர்கள் போஜனம்பண்ணி மலையிலே இராத்தங்கினார்கள்.',	1,	31,	54),
(929,	'And early in the morning Laban rose up, and kissed his sons and his daughters, and blessed them: and Laban departed, and returned unto his place.',	'லாபான் அதிகாலமே எழுந்திருந்து, தன் குமாரரையும் தன் குமாரத்திகளையும் முத்தஞ்செய்து, அவர்களை ஆசீர்வதித்தான். பின்பு லாபான் புறப்பட்டு, தன் இடத்துக்குத் திரும்பிப்போனான்.  ',	1,	31,	55),
(930,	'And Jacob went on his way, and the angels of God met him.',	'யாக்கோபு பிரயாணம் பண்ணுகையில், தேவதூதர்கள் அவனைச் சந்தித்தார்கள்.',	1,	32,	1),
(931,	'And when Jacob saw them, he said, This is God\'s host: and he called the name of that place Mahanaim.',	'யாக்கோபு அவர்களைக் கண்டபோது: இது தேவனுடைய சேனை என்று சொல்லி, அந்த ஸ்தலத்திற்கு மக்னாயீம் என்று பேரிட்டான்.',	1,	32,	2),
(932,	'And Jacob sent messengers before him to Esau his brother unto the land of Seir, the country of Edom.',	'பின்பு, யாக்கோபு ஏதோம் சீமையாகிய சேயீர் தேசத்திலிருக்கிற தன் சகோதரனாகிய ஏசாவினிடத்துக்குப் போகும்படி ஆட்களை அழைப்பித்து:',	1,	32,	3),
(933,	'And he commanded them, saying, Thus shall ye speak unto my lord Esau; Thy servant Jacob saith thus, I have sojourned with Laban, and stayed there until now:',	'நீங்கள் என் ஆண்டவனாகிய ஏசாவினிடத்தில் போய், நான் இதுவரைக்கும் லாபானிடத்தில் தங்கியிருந்தேன் என்றும்,',	1,	32,	4),
(934,	'And I have oxen, and asses, flocks, and menservants, and womenservants: and I have sent to tell my lord, that I may find grace in thy sight.',	'எனக்கு எருதுகளும், கழுதைகளும், ஆடுகளும், வேலைக்காரரும், வேலைக்காரிகளும் உண்டென்றும், உம்முடைய கண்களில் எனக்குத் தயவு கிடைக்கத்தக்கதாக ஆண்டவனாகிய உமக்கு இதை அறிவிக்கும்படி ஆட்களை அனுப்பினேன் என்றும் உம்முடைய தாசனாகிய யாக்கோபு சொல்லச்சொன்னான் என்று சொல்லும்படி கட்டளைகொடுத்துத் தனக்கு முன்னாக அவர்களை அனுப்பினான்.',	1,	32,	5),
(935,	'And the messengers returned to Jacob, saying, We came to thy brother Esau, and also he cometh to meet thee, and four hundred men with him.',	'அந்த ஆட்கள் யாக்கோபினிடத்துக்குத் திரும்பிவந்து: நாங்கள் உம்முடைய சகோதரனாகிய ஏசாவினிடத்துக்குப் போய்வந்தோம்; அவரும் நானூறு பேரோடே உம்மை எதிர்கொள்ள வருகிறார் என்றார்கள்.',	1,	32,	6),
(936,	'Then Jacob was greatly afraid and distressed: and he divided the people that was with him, and the flocks, and herds, and the camels, into two bands;',	'அப்பொழுது யாக்கோபு மிகவும் பயந்து, வியாகுலப்பட்டு, தன்னிடத்திலிருந்த ஜனங்களையும் ஆடுமாடுகளையும் ஒட்டகங்களையும் இரண்டு பகுதியாகப்பிரித்து:',	1,	32,	7),
(937,	'And said, If Esau come to the one company, and smite it, then the other company which is left shall escape.',	'ஏசா ஒரு பகுதியின்மேல் விழுந்து அதை முறிய அடித்தாலும், மற்றப் பகுதி தப்பித்துக்கொள்ள இடம் உண்டு என்றான்.',	1,	32,	8),
(938,	'And Jacob said, O God of my father Abraham, and God of my father Isaac, the LORD which saidst unto me, Return unto thy country, and to thy kindred, and I will deal well with thee:',	'பின்பு யாக்கோபு: என் தகப்பனாகிய ஆபிரகாமின் தேவனும், என் தகப்பனாகிய ஈசாக்கின் தேவனுமாய் இருக்கிறவரே: உன் தேசத்துக்கும் உன் இனத்தாரிடத்துக்கும் திரும்பிப்போ, உனக்கு நன்மை செய்வேன் என்று என்னுடனே சொல்லியிருக்கிற கர்த்தாவே,',	1,	32,	9),
(939,	'I am not worthy of the least of all the mercies, and of all the truth, which thou hast shewed unto thy servant; for with my staff I passed over this Jordan; and now I am become two bands.',	'அடியேனுக்கு தேவரீர் காண்பித்த எல்லா தயவுக்கும் எல்லா சத்தியத்துக்கும் நான் எவ்வளவேனும் பாத்திரன் அல்ல, நான் கோலும் கையுமாய் இந்த யோர்தானைக் கடந்துபோனேன்; இப்பொழுது இவ்விரண்டு பரிவாரங்களையும் உடையவனானேன்.',	1,	32,	10),
(940,	'Deliver me, I pray thee, from the hand of my brother, from the hand of Esau: for I fear him, lest he will come and smite me, and the mother with the children.',	'என் சகோதரனாகிய ஏசாவின் கைக்கு என்னைத் தப்புவியும், அவன் வந்து என்னையும் பிள்ளைகளையும் தாய்மார்களையும் முறிய அடிப்பான் என்று அவனுக்கு நான் பயந்திருக்கிறேன்.',	1,	32,	11),
(941,	'And thou saidst, I will surely do thee good, and make thy seed as the sand of the sea, which cannot be numbered for multitude.',	'தேவரீரோ: நான் உனக்கு மெய்யாகவே நன்மைசெய்து, உன் சந்ததியை எண்ணிமுடியாத கடற்கரை மணலைப்போல மிகவும் பெருகப்பண்ணுவேன் என்று சொன்னீரே என்றான்.',	1,	32,	12),
(942,	'And he lodged there that same night; and took of that which came to his hand a present for Esau his brother;',	'அன்று இராத்திரி அவன் அங்கே தங்கி, தன் கைக்கு உதவினவைகளிலே தன் சகோதரனாகிய ஏசாவுக்கு வெகுமானமாக,',	1,	32,	13),
(943,	'Two hundred she goats, and twenty he goats, two hundred ewes, and twenty rams,',	'இருநூறு வெள்ளாடுகளையும், இருபது வெள்ளாட்டுக் கடாக்களையும், இருநூறு செம்மறியாடுகளையும், இருபது ஆட்டுக்கடாக்களையும்,',	1,	32,	14),
(944,	'Thirty milch camels with their colts, forty kine, and ten bulls, twenty she asses, and ten foals.',	'பால் கொடுக்கிற முப்பது ஒட்டகங்களையும், அவைகளின் குட்டிகளையும், நாற்பது கடாரிகளையும், பத்துக் காளைகளையும் இருபது கோளிகைக் கழுதைகளையும், பத்துக் கழுதைக்குட்டிகளையும் பிரித்தெடுத்து,',	1,	32,	15),
(945,	'And he delivered them into the hand of his servants, every drove by themselves; and said unto his servants, Pass over before me, and put a space betwixt drove and drove.',	'வேலைக்காரர் கையில் ஒவ்வொரு மந்தையை தனித்தனியாக ஒப்புவித்து, நீங்கள் மந்தை மந்தைக்கு முன்னும் பின்னுமாக இடம் விட்டு எனக்கு முன்னாக ஓட்டிக்கொண்டுபோங்கள் என்று தன் வேலைக்காரருக்குச் சொல்லி,',	1,	32,	16),
(946,	'And he commanded the foremost, saying, When Esau my brother meeteth thee, and asketh thee, saying, Whose art thou? and whither goest thou? and whose are these before thee?',	'முன்னே போகிறவனை நோக்கி: என் சகோதரனாகிய ஏசா உனக்கு எதிர்ப்பட்டு: நீ யாருடையவன்? எங்கே போகிறாய்? உனக்குமுன் போகிற மந்தை யாருடையது? என்று உன்னைக் கேட்டால்,',	1,	32,	17),
(947,	'Then thou shalt say, They be thy servant Jacob\'s; it is a present sent unto my lord Esau: and, behold, also he is behind us.',	'நீ: இது உமது அடியானாகிய யாக்கோபுடையது; இது என் ஆண்டவனாகிய ஏசாவுக்கு அனுப்பப்படுகிற வெகுமதி; இதோ, அவனும் எங்கள் பின்னே வருகிறான் என்று சொல் என்றான்.',	1,	32,	18),
(948,	'And so commanded he the second, and the third, and all that followed the droves, saying, On this manner shall ye speak unto Esau, when ye find him.',	'இரண்டாம் மூன்றாம் வேலைக்காரனையும், மந்தைகளின் பின்னாலே போகிற அனைவரையும் நோக்கி: நீங்களும் ஏசாவைக் காணும்போது, இந்தப்பிரகாரமாக அவனோடே சொல்லி,',	1,	32,	19),
(949,	'And say ye moreover, Behold, thy servant Jacob is behind us. For he said, I will appease him with the present that goeth before me, and afterward I will see his face; peradventure he will accept of me.',	'இதோ, உமது அடியானாகிய யாக்கோபு எங்கள் பின்னாலே வருகிறான் என்றும் சொல்லுங்கள் என்று கட்டளையிட்டான்; முன்னே வெகுமதியை அனுப்பி, அவனைச் சாந்தப்படுத்திக்கொண்டு, பின்பு அவன் முகத்தைப் பார்ப்பேன், அப்பொழுது ஒருவேளை என்பேரில் தயவாயிருப்பான் என்றான்.',	1,	32,	20),
(950,	'So went the present over before him: and himself lodged that night in the company.',	'அந்தப்படியே வெகுமதி அவனுக்குமுன் போயிற்று; அவனோ அன்று இராத்திரி பாளயத்திலே தங்கி,',	1,	32,	21),
(951,	'And he rose up that night, and took his two wives, and his two womenservants, and his eleven sons, and passed over the ford Jabbok.',	'இராத்திரியில் எழுந்திருந்து, தன் இரண்டு மனைவிகளையும், தன் இரண்டு பணிவிடைக்காரிகளையும், தன்னுடைய பதினொரு குமாரரையும் கூட்டிக்கொண்டு, யாப்போக்கு என்கிற ஆற்றின் துறையைக் கடந்தான்.',	1,	32,	22),
(952,	'And he took them, and sent them over the brook, and sent over that he had.',	'அவர்களையும் சேர்த்து, ஆற்றைக்கடக்கப்பண்ணி, தனக்கு உண்டான யாவையும் அக்கரைப்படுத்தினான்.',	1,	32,	23),
(953,	'And Jacob was left alone; and there wrestled a man with him until the breaking of the day.',	'யாக்கோபு பிந்தித் தனித்திருந்தான்; அப்பொழுது ஒரு புருஷன் பொழுது விடியுமளவும் அவனுடனே போராடி,',	1,	32,	24),
(954,	'And when he saw that he prevailed not against him, he touched the hollow of his thigh; and the hollow of Jacob\'s thigh was out of joint, as he wrestled with him.',	'அவனை மேற்கொள்ளாததைக்கண்டு, அவனுடைய தொடைச்சந்தைத் தொட்டார்; அதினால் அவருடனே போராடுகையில் யாக்கோபின் தொடைச்சந்து சுளுக்கிற்று.',	1,	32,	25),
(955,	'And he said, Let me go, for the day breaketh. And he said, I will not let thee go, except thou bless me.',	'அவர்: நான் போகட்டும், பொழுது விடிகிறது என்றார். அதற்கு அவன்: நீர் என்னை ஆசீர்வதித்தாலொழிய உம்மைப் போகவிடேன் என்றான்.',	1,	32,	26),
(956,	'And he said unto him, What is thy name? And he said, Jacob.',	'அவர்: உன் பேர் என்ன என்று கேட்டார்; யாக்கோபு என்றான்.',	1,	32,	27),
(957,	'And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed.',	'அப்பொழுது அவர்: உன் பேர் இனி யாக்கோபு என்னப்படாமல் இஸ்ரவேல் என்னப்படும்; தேவனோடும் மனிதரோடும் போராடி மேற்கொண்டாயே என்றார்.',	1,	32,	28),
(958,	'And Jacob asked him, and said, Tell me, I pray thee, thy name. And he said, Wherefore is it that thou dost ask after my name? And he blessed him there.',	'அப்பொழுது யாக்கோபு: உம்முடைய நாமத்தை எனக்கு அறிவிக்கவேண்டும் என்று கேட்டான்; அதற்கு அவர்: நீ என் நாமத்தைக் கேட்பானேன் என்று சொல்லி, அங்கே அவனை ஆசீர்வதித்தார்.',	1,	32,	29),
(959,	'And Jacob called the name of the place Peniel: for I have seen God face to face, and my life is preserved.',	'அப்பொழுது யாக்கோபு: நான் தேவனை முகமுகமாய்க் கண்டேன், உயிர் தப்பிப் பிழைத்தேன் என்று சொல்லி, அந்த ஸ்தலத்துக்கு பெனியேல் என்று பேரிட்டான்.',	1,	32,	30),
(960,	'And as he passed over Penuel the sun rose upon him, and he halted upon his thigh.',	'அவன் பெனியேலைக் கடந்துபோகையில், சூரியன் உதயமாயிற்று; அவன் தொடைச்சுளுக்கினாலே நொண்டி நொண்டி நடந்தான்.',	1,	32,	31),
(961,	'Therefore the children of Israel eat not of the sinew which shrank, which is upon the hollow of the thigh, unto this day: because he touched the hollow of Jacob\'s thigh in the sinew that shrank.',	'அவர் யாக்கோபுடைய தொடைச்சந்து நரம்பைத் தொட்டபடியால், இஸ்ரவேல் புத்திரர் இந்நாள்வரைக்கும் தொடைச்சந்து நரம்பைப் புசிக்கிறதில்லை.  ',	1,	32,	32),
(962,	'And Jacob lifted up his eyes, and looked, and, behold, Esau came, and with him four hundred men. And he divided the children unto Leah, and unto Rachel, and unto the two handmaids.',	'யாக்கோபு தன் கண்களை ஏறெடுத்து, இதோ, ஏசாவும் அவனோடேகூட நானூறு மனிதரும் வருகிறதைக் கண்டு, பிள்ளைகளை லேயாளிடத்திலும் ராகேலிடத்திலும் இரண்டு பணிவிடைக்காரிகளிடத்திலும் வெவ்வேறாகப் பிரித்துவைத்து,',	1,	33,	1),
(963,	'And he put the handmaids and their children foremost, and Leah and her children after, and Rachel and Joseph hindermost.',	'பணிவிடைக்காரிகளையும் அவர்கள் பிள்ளைகளையும் முதலிலும், லேயாளையும் அவள் பிள்ளைகளையும் இடையிலும், ராகேலையும் யோசேப்பையும் கடையிலும் நிறுத்தி:',	1,	33,	2),
(964,	'And he passed over before them, and bowed himself to the ground seven times, until he came near to his brother.',	'தான் அவர்களுக்கு முன்னாக நடந்து போய், ஏழுவிசை தரைமட்டும் குனிந்து வணங்கி, தன் சகோதரன் கிட்டச் சேர்ந்தான்.',	1,	33,	3),
(965,	'And Esau ran to meet him, and embraced him, and fell on his neck, and kissed him: and they wept.',	'அப்பொழுது ஏசா எதிர்கொண்டு ஓடிவந்து, அவனைத் தழுவி, அவன் கழுத்தைக் கட்டிக்கொண்டு, அவனை முத்தஞ்செய்தான்; இருவரும் அழுதார்கள்.',	1,	33,	4),
(966,	'And he lifted up his eyes, and saw the women and the children; and said, Who are those with thee? And he said, The children which God hath graciously given thy servant.',	'அவன் தன் கண்களை ஏறெடுத்து, ஸ்திரீகளையும் பிள்ளைகளையும் கண்டு: உன்னோடிருக்கிற இவர்கள் யார்? என்றான். அதற்கு அவன்: தேவன் உமது அடியானுக்கு அருளின பிள்ளைகள் என்றான்.',	1,	33,	5),
(967,	'Then the handmaidens came near, they and their children, and they bowed themselves.',	'அப்பொழுது பணிவிடைக்காரிகளும் அவர்கள் பிள்ளைகளும் சேர்ந்துவந்து வணங்கினார்கள்.',	1,	33,	6),
(968,	'And Leah also with her children came near, and bowed themselves: and after came Joseph near and Rachel, and they bowed themselves.',	'லேயாளும் அவள் பிள்ளைகளும் சேர்ந்துவந்து வணங்கினார்கள்; பின்பு யோசேப்பும் ராகேலும் சேர்ந்துவந்து வணங்கினார்கள்.',	1,	33,	7),
(969,	'And he said, What meanest thou by all this drove which I met? And he said, These are to find grace in the sight of my lord.',	'அப்பொழுது அவன்: எனக்கு எதிர்கொண்டுவந்த அந்த மந்தையெல்லாம் என்னத்துக்கு என்றான். அதற்கு அவன்: என் ஆண்டவனுடைய கண்களில் எனக்குத் தயவு கிடைக்கிறதற்கு என்றான்.',	1,	33,	8),
(970,	'And Esau said, I have enough, my brother; keep that thou hast unto thyself.',	'அதற்கு ஏசா: என் சகோதரனே, எனக்குப் போதுமானது உண்டு; உன்னுடையது உனக்கு இருக்கட்டும் என்றான்.',	1,	33,	9),
(971,	'And Jacob said, Nay, I pray thee, if now I have found grace in thy sight, then receive my present at my hand: for therefore I have seen thy face, as though I had seen the face of God, and thou wast pleased with me.',	'அதற்கு யாக்கோபு: அப்படி அல்ல, உம்முடைய கண்களில் எனக்குத் தயவு கிடைத்ததேயானால், என் வெகுமதியை என் கையிலிருந்து ஏற்றுக்கொள்ளும்; நீர் என்மேல் பிரியமானீர், நான் உம்முடைய முகத்தைக் கண்டது தேவனுடைய முகத்தைக் கண்டதுபோல இருக்கிறது.',	1,	33,	10),
(972,	'Take, I pray thee, my blessing that is brought to thee; because God hath dealt graciously with me, and because I have enough. And he urged him, and he took it.',	'தேவன் எனக்கு அநுக்கிரகம் செய்திருக்கிறார்; வேண்டியதெல்லாம் எனக்கு உண்டு; ஆகையால் உமக்குக் கொண்டுவரப்பட்ட என் காணிக்கையை ஏற்றுக்கொள்ளும் என்று சொல்லி, அவனை வருந்திக் கேட்டுக்கொண்டான்; அப்பொழுது அவன் அதை ஏற்றுக்கொண்டான்.',	1,	33,	11),
(973,	'And he said, Let us take our journey, and let us go, and I will go before thee.',	'பின்பு அவன்: நாம் புறப்பட்டுப்போவோம் வா, நான் உனக்கு முன் நடப்பேன் என்றான்.',	1,	33,	12),
(974,	'And he said unto him, My lord knoweth that the children are tender, and the flocks and herds with young are with me: and if men should overdrive them one day, all the flock will die.',	'அதற்கு அவன்: பிள்ளைகள் இளம்பிள்ளைகள் என்றும், கறவையான ஆடுமாடுகள் என்னிடத்தில் இருக்கிறது என்றும் என் ஆண்டவனுக்குத் தெரியும்; அவைகள் ஒரு நாளாவது துரிதமாய் ஓட்டினால், மந்தையெல்லாம் மாண்டுபோம்.',	1,	33,	13),
(975,	'Let my lord, I pray thee, pass over before his servant: and I will lead on softly, according as the cattle that goeth before me and the children be able to endure, until I come unto my lord unto Seir.',	'என் ஆண்டவனாகிய நீர் உமது அடியானுக்கு முன்னே போம்; நான் சேயீருக்கு என் ஆண்டவனிடத்தில் வருமளவும், எனக்குமுன் நடக்கிற மந்தைகளின் கால்நடைக்கும் பிள்ளைகளின் கால்நடைக்கும் தக்கதாக, மெதுவாய் அவைகளை நடத்திக்கொண்டு வருகிறேன் என்றான்.',	1,	33,	14),
(976,	'And Esau said, Let me now leave with thee some of the folk that are with me. And he said, What needeth it? let me find grace in the sight of my lord.',	'அப்பொழுது ஏசா: என்னிடத்திலிருக்கிற ஜனங்களில் சிலரை நான் உன்னிடத்தில் நிறுத்திவிட்டுப் போகட்டுமா என்றான். அதற்கு அவன்: அது என்னத்திற்கு, என் ஆண்டவனுடைய கண்களில் எனக்குத் தயவுகிடைத்தால் மாத்திரம் போதும் என்றான்.',	1,	33,	15),
(977,	'So Esau returned that day on his way unto Seir.',	'அன்றைத்தினம் ஏசா திரும்பித் தான் வந்த வழியே சேயீருக்குப்போனான்.',	1,	33,	16),
(978,	'And Jacob journeyed to Succoth, and built him an house, and made booths for his cattle: therefore the name of the place is called Succoth.',	'யாக்கோபு சுக்கோத்திற்குப் பிரயாணம்பண்ணி, தனக்கு ஒரு வீடு கட்டி, தன் மிருகஜீவன்களுக்குக் கொட்டாரங்களைப் போட்டான்; அதினாலே அந்த ஸ்தலத்துக்குச் சுக்கோத் என்று பேரிட்டான்.',	1,	33,	17),
(979,	'And Jacob came to Shalem, a city of Shechem, which is in the land of Canaan, when he came from Padanaram; and pitched his tent before the city.',	'யாக்கோபு பதான்அராமிலிருந்து வந்தபின் கானான்தேசத்திலிருக்கிற சாலேம் என்னும் சீகேமுடைய பட்டணத்திற்கு அருகே சென்று பட்டணத்திற்கு எதிரே கூடாரம்போட்டான்.',	1,	33,	18),
(980,	'And he bought a parcel of a field, where he had spread his tent, at the hand of the children of Hamor, Shechem\'s father, for an hundred pieces of money.',	'தான் கூடாரம்போட்ட வெளியின் நிலத்தைச் சீகேமின் தகப்பனாகிய ஏமோரின் புத்திரர் கையிலே நூறு வெள்ளிக்காசுக்குக் கொண்டு,',	1,	33,	19),
(981,	'And he erected there an altar, and called it EleloheIsrael.',	'அங்கே ஒரு பலிபீடத்தைக் கட்டி, அதற்கு ஏல்எல்லோகே இஸ்ரவேல் என்று பேரிட்டான்.  ',	1,	33,	20),
(982,	'And Dinah the daughter of Leah, which she bare unto Jacob, went out to see the daughters of the land.',	'லேயாள் யாக்கோபுக்குப் பெற்ற குமாரத்தியாகிய தீனாள் தேசத்துப் பெண்களைப் பார்க்கப் புறப்பட்டாள்.',	1,	34,	1),
(983,	'And when Shechem the son of Hamor the Hivite, prince of the country, saw her, he took her, and lay with her, and defiled her.',	'அவளை ஏவியனான ஏமோரின் குமாரனும் அத்தேசத்தின் பிரபுவுமாகிய சீகேம் என்பவன் கண்டு, அவளைக் கொண்டுபோய், அவளோடே சயனித்து, அவளைத் தீட்டுப்படுத்தினான்.',	1,	34,	2),
(984,	'And his soul clave unto Dinah the daughter of Jacob, and he loved the damsel, and spake kindly unto the damsel.',	'அவனுடைய மனம் யாக்கோபின் குமாரத்தி.யாகிய தீனாள்மேல் பற்றுதலாயிருந்தது; அவன் அந்தப் பெண்ணை நேசித்து, அந்தப் பெண்ணின் மனதுக்கு இன்பமாய்ப் பேசினான்.',	1,	34,	3),
(985,	'And Shechem spake unto his father Hamor, saying, Get me this damsel to wife.',	'சீகேம் தன் தகப்பனாகிய ஏமோரை நோக்கி: இந்தப் பெண்ணை எனக்குக் கொள்ளவேண்டும் என்று சொன்னான்.',	1,	34,	4),
(986,	'And Jacob heard that he had defiled Dinah his daughter: now his sons were with his cattle in the field: and Jacob held his peace until they were come.',	'தன் குமாரத்தியாகிய தீனாளை அவன் தீட்டுப்படுத்தினதை யாக்கோபு கேள்விப்பட்டபோது, அவன் குமாரர் அவனுடைய மந்தையினிடத்தில் வெளியிலே இருந்தார்கள்; அவர்கள் வருமளவும் யாக்கோபு பேசாமலிருந்தான்.',	1,	34,	5),
(987,	'And Hamor the father of Shechem went out unto Jacob to commune with him.',	'அத்தருணத்தில் சீகேமின் தகப்பனாகிய ஏமோர் புறப்பட்டு, யாக்கோபோடே பேசும்படி அவனிடத்தில் வந்தான்.',	1,	34,	6),
(988,	'And the sons of Jacob came out of the field when they heard it: and the men were grieved, and they were very wroth, because he had wrought folly in Israel in lying with Jacob\'s daughter: which thing ought not to be done.',	'யாக்கோபின் குமாரர் இந்தச் செய்தியைக் கேட்டவுடனே, வெளியிலிருந்து வந்தார்கள். அவன் யாக்கோபின் குமாரத்தியோடே சயனித்து, செய்யத்தகாத மதிகெட்ட காரியத்தை இஸ்ரவேலில் செய்ததினாலே, அந்த மனிதர் மனங்கொதித்து மிகவும் கோபங்கொண்டார்கள்.',	1,	34,	7),
(989,	'And Hamor communed with them, saying, The soul of my son Shechem longeth for your daughter: I pray you give her him to wife.',	'ஏமோர் அவர்களோடே பேசி: என் குமாரனாகிய சீகேமின் மனது உங்கள் குமாரத்தியின்மேல் பற்றுதலாயிருக்கிறது; அவளை அவனுக்கு மனைவியாகக் கொடுங்கள்.',	1,	34,	8),
(990,	'And make ye marriages with us, and give your daughters unto us, and take our daughters unto you.',	'நீங்கள் எங்களோடே சம்பந்தங்கலந்து, உங்கள் குமாரத்திகளை எங்களுக்குக் கொடுத்து, எங்கள் குமாரத்திகளை உங்களுக்குக் கொண்டு,',	1,	34,	9),
(991,	'And ye shall dwell with us: and the land shall be before you; dwell and trade ye therein, and get you possessions therein.',	'எங்களோடே வாசம்பண்ணுங்கள்; தேசம் உங்கள் முன்பாக இருக்கிறது; இதிலே குடியிருந்து, வியாபாரம்பண்ணி, பொருள் சம்பாதித்து, அதைக் கையாண்டுகொண்டிருங்கள் என்றான்.',	1,	34,	10),
(992,	'And Shechem said unto her father and unto her brethren, Let me find grace in your eyes, and what ye shall say unto me I will give.',	'சீகேமும் அவள் தகப்பனையும் அவள் சகோதரனையும் நோக்கி: உங்கள் கண்களில் எனக்குத் தயவு கிடைக்கவேண்டும்; நீங்கள் என்னிடத்தில் எதைக் கேட்டாலும் தருகிறேன்;',	1,	34,	11),
(993,	'Ask me never so much dowry and gift, and I will give according as ye shall say unto me: but give me the damsel to wife.',	'பரிசமும் வெகுமதியும் நீங்கள் எவ்வளவு கேட்டாலும், உங்கள் சொற்படி தருகிறேன்; அந்தப் பெண்ணைமாத்திரம் எனக்கு மனைவியாகக் கொடுக்கவேண்டும் என்றான்.',	1,	34,	12),
(994,	'And the sons of Jacob answered Shechem and Hamor his father deceitfully, and said, because he had defiled Dinah their sister:',	'அப்பொழுது யாக்கோபின் குமாரர் தங்கள் சகோதரியாகிய தீனாளைச் சீகேம் என்பவன் தீட்டுப்படுத்தினபடியால், அவனுக்கும் அவன் தகப்பனாகிய ஏமோருக்கும் வஞ்சகமான மறுமொழியாக:',	1,	34,	13),
(995,	'And they said unto them, We cannot do this thing, to give our sister to one that is uncircumcised; for that were a reproach unto us:',	'விருத்தசேதனமில்லாத புருஷனுக்கு நாங்கள் எங்கள் சகோதரியைக் கொடுக்கலாகாது; அது எங்களுக்கு நிந்தையாயிருக்கும்.',	1,	34,	14),
(996,	'But in this will we consent unto you: If ye will be as we be, that every male of you be circumcised;',	'நீங்களும், உங்களுக்குள்ளிருக்கும் ஆண்மக்கள் யாவரும் விருத்தசேதனம்பண்ணப்பட்டு எங்களைப்போலாவீர்களானால், நாங்கள் சம்மதித்து,',	1,	34,	15),
(997,	'Then will we give our daughters unto you, and we will take your daughters to us, and we will dwell with you, and we will become one people.',	'உங்களுக்கு எங்கள் குமாரத்திகளைக் கொடுத்து, உங்கள் குமாரத்திகளை எங்களுக்குக் கொண்டு, உங்களோடே குடியிருந்து, ஏகஜனமாயிருப்போம்.',	1,	34,	16),
(998,	'But if ye will not hearken unto us, to be circumcised; then will we take our daughter, and we will be gone.',	'விருத்தசேதனம்பண்ணிக்கொள்வதற்கு எங்கள் சொல் கேளாமற்போவீர்களானால், நாங்கள் எங்கள் குமாரத்தியை அழைத்துக்கொண்டு போய்விடுவோம் என்று சொன்னார்கள்.',	1,	34,	17),
(999,	'And their words pleased Hamor, and Shechem Hamor\'s son.',	'அவர்களுடைய வார்த்தைகள் ஏமோருக்கும் ஏமோரின் குமாரனாகிய சீகேமுக்கும் நலமாய்த் தோன்றினது.',	1,	34,	18),
(1000,	'And the young man deferred not to do the thing, because he had delight in Jacob\'s daughter: and he was more honourable than all the house of his father.',	'அந்த வாலிபன் யாக்கோபுடைய குமாரத்தியின்மேல் பிரியம் வைத்திருந்தபடியால், அந்தக் காரியத்தைச் செய்ய அவன் தாமதம்பண்ணவில்லை. அவன் தன் தகப்பன் வீட்டார் அனைவருக்குள்ளும் மேன்மையுள்ளவனாயிருந்தான்.',	1,	34,	19),
(1001,	'And Hamor and Shechem his son came unto the gate of their city, and communed with the men of their city, saying,',	'ஏமோரும் அவன் குமாரன் சீகேமும் தங்கள் பட்டணத்து வாசலில் வந்து, தங்கள் பட்டணத்து மனிதரோடே பேசி:',	1,	34,	20),
(1002,	'These men are peaceable with us; therefore let them dwell in the land, and trade therein; for the land, behold, it is large enough for them; let us take their daughters to us for wives, and let us give them our daughters.',	'இந்த மனிதர் நம்மோடே சமாதானமாயிருக்கிறார்கள்; ஆகையால், அவர்கள் இந்தத் தேசத்தில் வாசம்பண்ணி, இதிலே வியாபாரம்பண்ணட்டும்; அவர்களும் வாசம்பண்ணுகிறதற்கு தேசம் விஸ்தாரமாயிருக்கிறது; அவர்களுடைய குமாரத்திகளை நமக்கு மனைவிகளாகக் கொண்டு, நம்முடைய குமாரத்திகளை அவர்களுக்குக் கொடுப்போம்.',	1,	34,	21),
(1003,	'Only herein will the men consent unto us for to dwell with us, to be one people, if every male among us be circumcised, as they are circumcised.',	'அந்த மனிதர் விருத்தசேதனம்பண்ணப்பட்டவர்களாயிருக்கிறது போல, நம்மிலுள்ள ஆண்மக்கள் யாவரும் விருத்தசேதனம்பண்ணப்பட்டால், அவர்கள் ஏகஜனமாக நம்மோடே வாசம்பண்ணச் சம்மதிப்பார்கள்.',	1,	34,	22),
(1004,	'Shall not their cattle and their substance and every beast of their\'s be our\'s? only let us consent unto them, and they will dwell with us.',	'அவர்களுடைய ஆடுமாடுகள் ஆஸ்திகள் மிருகஜீவன்கள் எல்லாம் நம்மைச் சேருமல்லவா? அவர்களுக்குச் சம்மதிப்போமானால், அவர்கள் நம்முடனே வாசம்பண்ணுவார்கள் என்று சொன்னார்கள்.',	1,	34,	23),
(1005,	'And unto Hamor and unto Shechem his son hearkened all that went out of the gate of his city; and every male was circumcised, all that went out of the gate of his city.',	'அப்பொழுது ஏமோரின் பட்டணத்து வாசலில் புறப்பட்டுவரும் அனைவரும் அவன் சொல்லையும், அவன் குமாரனாகிய சீகேமின் சொல்லையும் கேட்டு, அவனுடைய பட்டணத்து வாசலில் புறப்பட்டுவரும் ஆண்மக்கள் யாவரும் விருத்தசேதனம்பண்ணப்பட்டார்கள்.',	1,	34,	24),
(1006,	'And it came to pass on the third day, when they were sore, that two of the sons of Jacob, Simeon and Levi, Dinah\'s brethren, took each man his sword, and came upon the city boldly, and slew all the males.',	'மூன்றாம் நாளில் அவர்களுக்கு நோவெடுத்துக்கொண்டபோது, யாக்கோபின் குமாரரும் தீனாளின் சகோதரருமான சிமியோன் லேவி என்னும் இவ்விரண்டு பேரும் தன்தன் பட்டயத்தை எடுத்துக்கொண்டு, துணிகரமாய்ப் பட்டணத்தின் மேல் பாய்ந்து, ஆண்மக்கள் யாவரையும் கொன்றுபோட்டார்கள்.',	1,	34,	25),
(1007,	'And they slew Hamor and Shechem his son with the edge of the sword, and took Dinah out of Shechem\'s house, and went out.',	'ஏமோரையும், அவன் குமாரன் சீகேமையும் பட்டயக்கருக்காலே கொன்று, சீகேமின் வீட்டிலிருந்த தீனாளை அழைத்துக்கொண்டு போய்விட்டார்கள்.',	1,	34,	26),
(1008,	'The sons of Jacob came upon the slain, and spoiled the city, because they had defiled their sister.',	'மேலும், யாக்கோபின் குமாரர் வெட்டுண்டவர்களிடத்தில் வந்து, தங்கள் சகோதரியை அவர்கள் தீட்டுப்படுத்தினதற்காகப் பட்டணத்தைக் கொள்ளையிட்டு,',	1,	34,	27),
(1009,	'They took their sheep, and their oxen, and their asses, and that which was in the city, and that which was in the field,',	'அவர்களுடைய ஆடுமாடுகளையும், கழுதைகளையும், பட்டணத்திலும் வயல்வெளியிலும் இருந்தவைகள் யாவையும்,',	1,	34,	28),
(1010,	'And all their wealth, and all their little ones, and their wives took they captive, and spoiled even all that was in the house.',	'அவர்களுடைய எல்லாத் தட்டுமுட்டுகளையும் எடுத்துக்கொண்டு, அவர்களுடைய எல்லாக் குழந்தைகளையும் ஸ்திரீகளையும் சிறைபிடித்து, வீட்டிலிருந்த எல்லாவற்றையும் கொள்ளையிட்டார்கள்.',	1,	34,	29),
(1011,	'And Jacob said to Simeon and Levi, Ye have troubled me to make me to stink among the inhabitants of the land, among the Canaanites and the Perizzites: and I being few in number, they shall gather themselves together against me, and slay me; and I shall be destroyed, I and my house.',	'அப்பொழுது யாக்கோபு சிமியோனையும் லேவியையும் பார்த்து: இந்தத் தேசத்தில் குடியிருக்கிற கானானியரிடத்திலும் பெரிசியரிடத்திலும் என் வாசனையை நீங்கள் கெடுத்ததினாலே என்னைக் கலங்கப்பண்ணினீர்கள்; நான் கொஞ்ச ஜனமுள்ளவன்; அவர்கள் எனக்கு விரோதமாய்க் கூட்டங்கூடி, நானும் என் குடும்பமும் அழியும்படி என்னை வெட்டிப்போடுவார்களே என்றான்.',	1,	34,	30),
(1012,	'And they said, Should he deal with our sister as with an harlot?',	'அதற்கு அவர்கள்: எங்கள் சகோதரியை அவர்கள் ஒரு வேசியைப்போல நடத்தலாமோ என்றார்கள்.  ',	1,	34,	31),
(1013,	'And God said unto Jacob, Arise, go up to Bethel, and dwell there: and make there an altar unto God, that appeared unto thee when thou fleddest from the face of Esau thy brother.',	'தேவன் யாக்கோபை நோக்கி: நீ எழுந்து பெத்தேலுக்குப் போய், அங்கே குடியிருந்து, நீ உன் சகோதரனாகிய ஏசாவின் முகத்திற்கு விலகி ஓடிப்போகிறபோது, உனக்குத் தரிசனமான தேவனுக்கு அங்கே ஒரு பலிபீடத்தை உண்டாக்கு என்றார்.',	1,	35,	1),
(1014,	'Then Jacob said unto his household, and to all that were with him, Put away the strange gods that are among you, and be clean, and change your garments:',	'அப்பொழுது யாக்கோபு தன் வீட்டாரையும் தன்னோடேகூட இருந்த மற்ற அனைவரையும் நோக்கி: உங்களிடத்தில் இருக்கிற அந்நிய தெய்வங்களை விலக்கிப்போட்டு, உங்களைச் சுத்தம்பண்ணிக்கொண்டு, உங்கள் வஸ்திரங்களை மாற்றுங்கள்.',	1,	35,	2),
(1015,	'And let us arise, and go up to Bethel; and I will make there an altar unto God, who answered me in the day of my distress, and was with me in the way which I went.',	'நாம் எழுந்து பெத்தேலுக்குப் போவோம் வாருங்கள்; எனக்கு ஆபத்து நேரிட்ட நாளில் என் விண்ணப்பத்துக்கு உத்தரவு அருளிச்செய்து, நான் நடந்த வழியிலே என்னோடேகூட இருந்த தேவனுக்கு அங்கே ஒரு பலிபீடத்தை உண்டாக்குவேன் என்றான்.',	1,	35,	3),
(1016,	'And they gave unto Jacob all the strange gods which were in their hand, and all their earrings which were in their ears; and Jacob hid them under the oak which was by Shechem.',	'அப்பொழுது அவர்கள் தங்கள் கையில் இருந்த எல்லா அந்நிய தெய்வங்களையும், தங்கள் காதணிகளையும் யாக்கோபிடத்தில் கொடுத்தார்கள்; யாக்கோபு அவைகளைச் சீகேம் ஊர் அருகே இருந்த ஒரு கர்வாலி மரத்தின்கீழே புதைத்துப்போட்டான்.',	1,	35,	4),
(1017,	'And they journeyed: and the terror of God was upon the cities that were round about them, and they did not pursue after the sons of Jacob.',	'பின்பு பிரயாணம் புறப்பட்டார்கள்; அவர்களைச் சுற்றிலும் இருந்த பட்டணத்தாருக்குத் தேவனாலே பயங்கரம் உண்டானதினால், அவர்கள் யாக்கோபின் குமாரரைப் பின்தொடராதிருந்தார்கள்.',	1,	35,	5),
(1018,	'So Jacob came to Luz, which is in the land of Canaan, that is, Bethel, he and all the people that were with him.',	'யாக்கோபும் அவனோடேகூட இருந்த எல்லா ஜனங்களும் கானான் தேசத்திலுள்ள பெத்தேல் என்னும் லூசுக்கு வந்தார்கள்.',	1,	35,	6),
(1019,	'And he built there an altar, and called the place Elbethel: because there God appeared unto him, when he fled from the face of his brother.',	'அங்கே அவன் ஒரு பலிபீடத்தைக்கட்டி, தன் சகோதரனுடைய முகத்துக்குத் தப்பி ஓடினபோது, அங்கே தனக்கு தேவன் தரிசனமானபடியால், அந்த ஸ்தலத்திற்கு ஏல்பெத்தேல் என்று பேரிட்டான்.',	1,	35,	7),
(1020,	'But Deborah, Rebekah\'s nurse died, and she was buried beneath Bethel under an oak: and the name of it was called Allonbachuth.',	'ரெபெக்காளின் தாதியாகிய தெபொராள் மரித்து, பெத்தேலுக்குச் சமீபமாயிருந்த ஒரு கர்வாலி மரத்தின்கீழ் அடக்கம்பண்ணப்பட்டாள்; அதற்கு அல்லோன்பாகூத் என்னும் பேர் உண்டாயிற்று.',	1,	35,	8),
(1021,	'And God appeared unto Jacob again, when he came out of Padanaram, and blessed him.',	'யாக்கோபு பதான் அராமிலிருந்து வந்தபின்பு தேவன் அவனுக்கு மறுபடியும் தரிசனமாகி, அவனை ஆசீர்வதித்து:',	1,	35,	9),
(1022,	'And God said unto him, Thy name is Jacob: thy name shall not be called any more Jacob, but Israel shall be thy name: and he called his name Israel.',	'இப்பொழுது உன் பேர் யாக்கோபு, இனி உன் பேர் யாக்கோபு என்னப்படாமல், இஸ்ரவேல் என்று உனக்குப் பேர் வழங்கும் என்று சொல்லி, அவனுக்கு இஸ்ரவேல் என்று பேரிட்டார்.',	1,	35,	10),
(1023,	'And God said unto him, I am God Almighty: be fruitful and multiply; a nation and a company of nations shall be of thee, and kings shall come out of thy loins;',	'பின்னும் தேவன் அவனை நோக்கி: நான் சர்வவல்லமையுள்ள தேவன், நீ பலுகிப் பெருகுவாயாக; ஒரு ஜாதியும் பற்பல ஜாதிகளின் கூட்டங்களும் உன்னிலிருந்து உண்டாகும்; ராஜாக்களும் உன் சந்ததியில் பிறப்பார்கள்.',	1,	35,	11),
(1024,	'And the land which I gave Abraham and Isaac, to thee I will give it, and to thy seed after thee will I give the land.',	'நான் ஆபிரகாமுக்கும் ஈசாக்குக்கும் கொடுத்த தேசத்தை உனக்குக் கொடுப்பேன்; உனக்குப்பின் உன் சந்ததிக்கும் இந்த தேசத்தைக் கொடுப்பேன் என்று சொல்லி,',	1,	35,	12),
(1025,	'And God went up from him in the place where he talked with him.',	'தேவன் அவனோடே பேசின ஸ்தலத்திலிருந்து அவனைவிட்டு எழுந்தருளிப்போனார்.',	1,	35,	13),
(1026,	'And Jacob set up a pillar in the place where he talked with him, even a pillar of stone: and he poured a drink offering thereon, and he poured oil thereon.',	'அப்பொழுது யாக்கோபு தன்னோடே அவர் பேசின ஸ்தலத்திலே ஒரு கற்றூணை நிறுத்தி, அதின்மேல் பானபலியை ஊற்றி, எண்ணையையும் வார்த்தான்.',	1,	35,	14),
(1027,	'And Jacob called the name of the place where God spake with him, Bethel.',	'தேவன் தன்னோடே பேசின அந்த ஸ்தலத்திற்கு யாக்கோபு பெத்தேல் என்று பேரிட்டான்.',	1,	35,	15),
(1028,	'And they journeyed from Bethel; and there was but a little way to come to Ephrath: and Rachel travailed, and she had hard labour.',	'பின்பு, பெத்தேலை விட்டுப் பிரயாணம் புறப்பட்டார்கள். எப்பிராத்தாவுக்கு வர இன்னும் கொஞ்சம் தூரமிருக்கும்போது, ராகேல் பிள்ளைபெற்றாள்; பிரசவத்தில் அவளுக்குக் கடும்வேதனை உண்டாயிற்று.',	1,	35,	16),
(1029,	'And it came to pass, when she was in hard labour, that the midwife said unto her, Fear not; thou shalt have this son also.',	'பிரசவிக்கும்போது, அவளுக்குக் கடும் வேதனையாயிருக்கையில், மருத்துவச்சி அவளைப் பார்த்து: பயப்படாதே, இந்த முறையும் புத்திரனைப் பெறுவாய் என்றாள்.',	1,	35,	17),
(1030,	'And it came to pass, as her soul was in departing, (for she died) that she called his name Benoni: but his father called him Benjamin.',	'மரணகாலத்தில் அவள் ஆத்துமா பிரியும்போது, அவள் அவனுக்கு பெனொனி என்று பேரிட்டாள்; அவன் தகப்பனோ, அவனுக்கு பென்யமீன் என்று பேரிட்டான்.',	1,	35,	18),
(1031,	'And Rachel died, and was buried in the way to Ephrath, which is Bethlehem.',	'ராகேல் மரித்து, பெத்லகேம் என்னும் எப்பிராத்தா ஊருக்குப் போகிற வழியிலே அடக்கம் பண்ணப்பட்டாள்.',	1,	35,	19),
(1032,	'And Jacob set a pillar upon her grave: that is the pillar of Rachel\'s grave unto this day.',	'அவள் கல்லறையின்மேல் யாக்கோபு ஒரு தூணை நிறுத்தினான்; அதுவே இந்நாள் வரைக்கும் இருக்கிற ராகேலுடைய கல்லறையின் தூண்.',	1,	35,	20),
(1033,	'And Israel journeyed, and spread his tent beyond the tower of Edar.',	'இஸ்ரவேல் பிரயாணம்பண்ணி, ஏதேர் என்கிற கோபுரத்திற்கு அப்புறத்தில் கூடாரம் போட்டான்.',	1,	35,	21),
(1034,	'And it came to pass, when Israel dwelt in that land, that Reuben went and lay with Bilhah his father\'s concubine: and Israel heard it. Now the sons of Jacob were twelve:',	'இஸ்ரவேல் அந்தத் தேசத்தில் தங்கிக் குடியிருக்கும்போது, ரூபன் போய், தன் தகப்பனுடைய மறுமனையாட்டியாகிய பில்காளோடே சயனித்தான்; அதை இஸ்ரவேல் கேள்விப்பட்டான்.',	1,	35,	22),
(1035,	'The sons of Leah; Reuben, Jacob\'s firstborn, and Simeon, and Levi, and Judah, and Issachar, and Zebulun:',	'யாக்கோபின் குமாரர் பன்னிரண்டு பேர். யாக்கோபின் மூத்தமகனாகிய ரூபன், சிமியோன், லேவி, யூதா, இசக்கார், செபுலோன் என்பவர்கள் லேயாள் பெற்ற குமாரர்.',	1,	35,	23),
(1036,	'The sons of Rachel; Joseph, and Benjamin:',	'யோசேப்பு, பென்யமீன் என்பவர்கள் ராகேல் பெற்ற குமாரர்.',	1,	35,	24),
(1037,	'And the sons of Bilhah, Rachel\'s handmaid; Dan, and Naphtali:',	'தாண், நப்தலி என்பவர்கள் ராகேலுடைய பணிவிடைக்காரியாகிய பில்காள் பெற்ற குமாரர்.',	1,	35,	25),
(1038,	'And the sons of Zilpah, Leah\'s handmaid: Gad, and Asher: these are the sons of Jacob, which were born to him in Padanaram.',	'காத், ஆசேர் என்பவர்கள் லேயாளின் பணிவிடைக்காரியாகிய சில்பாள் பெற்ற குமாரர்; இவர்களே யாக்கோபுக்குப் பதான் அராமிலே பிறந்த குமாரர்.',	1,	35,	26),
(1039,	'And Jacob came unto Isaac his father unto Mamre, unto the city of Arbah, which is Hebron, where Abraham and Isaac sojourned.',	'பின்பு, யாக்கோபு அர்பாவின் ஊராகிய மம்ரேக்கு தன் தகப்பனாகிய ஈசாக்கினிடத்தில் வந்தான்; அது ஆபிரகாமும் ஈசாக்கும் தங்கியிருந்த எபிரோன் என்னும் ஊர்.',	1,	35,	27),
(1040,	'And the days of Isaac were an hundred and fourscore years.',	'ஈசாக்கு விருத்தாப்பியமும் பூரண ஆயுசுமுள்ளவனாகி, நூற்றெண்பது வருஷம் ஜீவித்திருந்து,',	1,	35,	28),
(1041,	'And Isaac gave up the ghost, and died, and was gathered unto his people, being old and full of days: and his sons Esau and Jacob buried him.',	'பிராணன்போய் மரித்து, தன் ஜனத்தாரோடே சேர்க்கப்பட்டான். அவன் குமாரராகிய ஏசாவும் யாக்கோபும் அவனை அடக்கம்பண்ணினார்கள்.  ',	1,	35,	29),
(1042,	'Now these are the generations of Esau, who is Edom.',	'ஏதோமியரின் தகப்பனாகிய ஏசாவின் வம்ச வரலாறு:',	1,	36,	1),
(1043,	'Esau took his wives of the daughters of Canaan; Adah the daughter of Elon the Hittite, and Aholibamah the daughter of Anah the daughter of Zibeon the Hivite;',	'ஏசா கானான் தேசத்துப் பெண்களில் ஏத்தியனான ஏலோனின் குமாரத்தியாகிய ஆதாளையும், ஏவியனாகிய சிபியோனின் குமாரத்தியும் ஆனாகின் குமாரத்தியுமாகிய அகோலிபாமாளையும்,',	1,	36,	2),
(1044,	'And Bashemath Ishmael\'s daughter, sister of Nebajoth.',	'இஸ்மவேலின் குமாரத்தியும் நெபாயோத்தின் சகோதரியுமாகிய பஸ்மாத்தையும் விவாகம் பண்ணியிருந்தான்.',	1,	36,	3),
(1045,	'And Adah bare to Esau Eliphaz; and Bashemath bare Reuel;',	'ஆதாள் ஏசாவுக்கு எலீப்பாசைப் பெற்றாள்; பஸ்மாத்து ரெகுவேலைப் பெற்றாள்.',	1,	36,	4),
(1046,	'And Aholibamah bare Jeush, and Jaalam, and Korah: these are the sons of Esau, which were born unto him in the land of Canaan.',	'அகோலிபாமாள் எயூஷையும், யாலாமையும், கோராகையும் பெற்றாள்; இவர்களே ஏசாவுக்குக் கானான் தேசத்திலே பிறந்த குமாரர்.',	1,	36,	5),
(1047,	'And Esau took his wives, and his sons, and his daughters, and all the persons of his house, and his cattle, and all his beasts, and all his substance, which he had got in the land of Canaan; and went into the country from the face of his brother Jacob.',	'ஏசா தன் மனைவிகளையும், தன் குமாரரையும், தன் குமாரத்திகளையும், தன் வீட்டிலுள்ள யாவரையும், தன் ஆடுமாடுகளையும், மற்ற ஜீவஜந்துக்கள் யாவையும், தான் கானான் தேசத்திலே சம்பாதித்த ஆஸ்தி முழுவதையும் சேர்த்துக்கொண்டு, தன் சகோதரனாகிய யாக்கோபை விட்டுப் பிரிந்து வேறே தேசத்துக்குப்போனான்.',	1,	36,	6),
(1048,	'For their riches were more than that they might dwell together; and the land wherein they were strangers could not bear them because of their cattle.',	'அவர்களுடைய சம்பத்து மிகுதியாயிருந்தபடியினால் அவர்கள் ஒருமித்துக் குடியிருக்கக் கூடாமற்போயிற்று; அவர்களுடைய மந்தைகளினிமித்தமாய் அவர்கள் தங்கியிருந்த பூமி அவர்களைத் தாங்கக்கூடாததாயிருந்தது.',	1,	36,	7),
(1049,	'Thus dwelt Esau in mount Seir: Esau is Edom.',	'ஆதலால் ஏசா சேயீர்மலையில் குடியேறினான்; ஏசாவுக்கு ஏதோம் என்றும் பேர்.',	1,	36,	8),
(1050,	'And these are the generations of Esau the father of the Edomites in mount Seir:',	'சேயீர்மலையில் இருக்கிற ஏதோமியருடைய தகப்பனாகிய ஏசாவின் சந்ததிகளும்,',	1,	36,	9),
(1051,	'These are the names of Esau\'s sons; Eliphaz the son of Adah the wife of Esau, Reuel the son of Bashemath the wife of Esau.',	'ஏசாவின் குமாரருடைய நாமங்களுமாவன: ஏசாவின் மனைவியாகிய ஆதாளுடைய குமாரனுக்கு எலீப்பாஸ் என்று பேர்; ஏசாவின் மனைவியாகிய பஸ்மாத்துடைய குமாரனுக்கு ரெகுவேல் என்று பேர்.',	1,	36,	10),
(1052,	'And the sons of Eliphaz were Teman, Omar, Zepho, and Gatam, and Kenaz.',	'எலீப்பாசின் குமாரர், தேமான், ஓமார், செப்போ, கத்தாம், கேனாஸ் என்பவர்கள்.',	1,	36,	11),
(1053,	'And Timna was concubine to Eliphaz Esau\'s son; and she bare to Eliphaz Amalek: these were the sons of Adah Esau\'s wife.',	'திம்னாள் ஏசாவின் குமாரனாகிய எலீப்பாசுக்கு மறுமனையாட்டியாயிருந்து, எலீப்பாசுக்கு அமலேக்கைப் பெற்றாள்; இவர்களே ஏசாவின் மனைவியாகிய ஆதாளுடைய புத்திரர்.',	1,	36,	12),
(1054,	'And these are the sons of Reuel; Nahath, and Zerah, Shammah, and Mizzah: these were the sons of Bashemath Esau\'s wife.',	'ரெகுவேலுடைய குமாரர், நகாத், செராகு, சம்மா, மீசா என்பவர்கள்; இவர்களே ஏசாவின் மனைவியாகிய பஸ்மாத்தின் புத்திரர்.',	1,	36,	13),
(1055,	'And these were the sons of Aholibamah, the daughter of Anah the daughter of Zibeon, Esau\'s wife: and she bare to Esau Jeush, and Jaalam, and Korah.',	'சிபியோனின் குமாரத்தியும் ஆனாகின் குமாரத்தியுமான அகோலிபாமாள் என்கிற ஏசாவின் மனைவி எயூஷ், யாலாம், கோராகு என்னும் புத்திரரை ஏசாவுக்குப் பெற்றாள்.',	1,	36,	14),
(1056,	'These were dukes of the sons of Esau: the sons of Eliphaz the firstborn son of Esau; duke Teman, duke Omar, duke Zepho, duke Kenaz,',	'ஏசாவின் குமாரரில் தோன்றிய பிரபுக்களாவன: ஏசாவுக்கு மூத்த மகனாகிய எலீப்பாசுடைய குமாரரில் தேமான் பிரபு, ஓமார் பிரபு, செப்போ, பிரபு, கேனாஸ் பிரபு,',	1,	36,	15),
(1057,	'Duke Korah, duke Gatam, and duke Amalek: these are the dukes that came of Eliphaz in the land of Edom; these were the sons of Adah.',	'கோராகு பிரபு, கத்தாம் பிரபு, அமலேக்கு பிரபு என்பவர்கள்; இவர்கள் ஏதோம் தேசத்தில் எலீப்பாசின் சந்ததியும் ஆதாளின் குமாரருமாயிருந்த பிரபுக்கள்.',	1,	36,	16),
(1058,	'And these are the sons of Reuel Esau\'s son; duke Nahath, duke Zerah, duke Shammah, duke Mizzah: these are the dukes that came of Reuel in the land of Edom; these are the sons of Bashemath Esau\'s wife.',	'ஏசாவின் குமாரனாகிய ரெகுவேலின் புத்திரரில் நகாத் பிரபு, செராகு பிரபு, சம்மா பிரபு, மீசா பிரபு என்பவர்கள்; இவர்கள் ஏதோம் தேசத்தில் ரெகுவேலின் சந்ததியும் ஏசாவின் மனைவியாகிய பஸ்மாத்தின் குமாரருமாயிருந்த பிரபுக்கள்.',	1,	36,	17),
(1059,	'And these are the sons of Aholibamah Esau\'s wife; duke Jeush, duke Jaalam, duke Korah: these were the dukes that came of Aholibamah the daughter of Anah, Esau\'s wife.',	'ஏசாவின் மனைவியாகிய அகோலிபாமாளின் குமாரர், எயூஷ் பிரபு, யாலாம் பிரபு, கோராகு பிரபு என்பவர்கள்; இவர்கள் ஆனாகின் குமாரத்தியும் ஏசாவுடைய மனைவியுமாகிய அகோலிபாமாளின் சந்ததியாயிருந்த பிரபுக்கள்.',	1,	36,	18),
(1060,	'These are the sons of Esau, who is Edom, and these are their dukes.',	'இவர்களே ஏதோம் என்னும் ஏசாவின் சந்ததி; இவர்களே அவர்களிலிருந்த பிரபுக்கள்.',	1,	36,	19),
(1061,	'These are the sons of Seir the Horite, who inhabited the land; Lotan, and Shobal, and Zibeon, and Anah,',	'அந்தத் தேசத்தின் குடிகளாகிய ஓரியனான சேயீரின் குமாரர், லோத்தான், சோபால், சிபியோன், ஆனாகு,',	1,	36,	20),
(1062,	'And Dishon, and Ezer, and Dishan: these are the dukes of the Horites, the children of Seir in the land of Edom.',	'திஷோன், ஏத்சேர், திஷான் என்பவர்கள்; இவர்களே ஏதோம் தேசத்தில் சேயீரின் புத்திரராகிய ஓரியருடைய சந்ததியாயிருந்த பிரபுக்கள்.',	1,	36,	21),
(1063,	'And the children of Lotan were Hori and Hemam; and Lotan\'s sister was Timna.',	'லோத்தானுடைய குமாரர், ஓரி, ஏமாம் என்பவர்கள்; லோத்தானின் சகோதரி திம்னாள் என்பவள்.',	1,	36,	22),
(1064,	'And the children of Shobal were these; Alvan, and Manahath, and Ebal, Shepho, and Onam.',	'சோபாலின் குமாரர், அல்வான், மானகாத், ஏபால், செப்போ, ஓனாம் என்பவர்கள்.',	1,	36,	23),
(1065,	'And these are the children of Zibeon; both Ajah, and Anah: this was that Anah that found the mules in the wilderness, as he fed the asses of Zibeon his father.',	'சிபியோனின் குமாரர், அயா, ஆனாகு என்பவர்கள்; வனாந்தரத்திலே தன் தகப்பனாகிய சீபெயோனின் கழுதைகளை மேய்க்கையில், கோவேறு கழுதைகளைக் கண்டுபிடித்த ஆனாகு இவன்தான்.',	1,	36,	24),
(1066,	'And the children of Anah were these; Dishon, and Aholibamah the daughter of Anah.',	'ஆனாகின் பிள்ளைகள், திஷோன், அகோலிபாமாள் என்பவர்கள்; இந்த அகோலிபாமாள் ஆனாகின் குமாரத்தி.',	1,	36,	25),
(1067,	'And these are the children of Dishon; Hemdan, and Eshban, and Ithran, and Cheran.',	'திஷோனுடைய குமாரர், எம்தான், எஸ்பான், இத்தரான், கெரான் என்பவர்கள்.',	1,	36,	26),
(1068,	'The children of Ezer are these; Bilhan, and Zaavan, and Akan.',	'ஏத்சேருடைய குமாரர், பில்கான், சகவான், அக்கான் என்பவர்கள்.',	1,	36,	27),
(1069,	'The children of Dishan are these; Uz, and Aran.',	'திஷானுடைய குமாரர், ஊத்ஸ், அரான் என்பவர்கள்.',	1,	36,	28),
(1070,	'These are the dukes that came of the Horites; duke Lotan, duke Shobal, duke Zibeon, duke Anah,',	'ஓரியரின் சந்ததியில் தோன்றிய பிரபுக்கள், லோத்தான் பிரபு, சோபால் பிரபு, சிபியோன் பிரபு, ஆனாகு பிரபு,',	1,	36,	29),
(1071,	'Duke Dishon, duke Ezer, duke Dishan: these are the dukes that came of Hori, among their dukes in the land of Seir.',	'திஷோன் பிரபு, ஏத்சேர் பிரபு, திஷான் பிரபு என்பவர்கள்; இவர்களே சேயீர் தேசத்திலே தங்கள் தங்கள் இடங்களில் இருந்த ஓரியர் சந்ததியான பிரபுக்கள்.',	1,	36,	30),
(1072,	'And these are the kings that reigned in the land of Edom, before there reigned any king over the children of Israel.',	'இஸ்ரவேல் புத்திரர்மேல் ராஜாக்கள் அரசாளுகிறதற்கு முன்னே, ஏதோம் தேசத்திலே ஆண்ட ராஜாக்களாவன:',	1,	36,	31),
(1073,	'And Bela the son of Beor reigned in Edom: and the name of his city was Dinhabah.',	'பேயோருடைய குமாரனாகிய பேலா ஏதோமிலே அரசாண்டான்; அவனுடைய பட்டணத்துக்குத் தின்காபா என்று பேர்.',	1,	36,	32),
(1074,	'And Bela died, and Jobab the son of Zerah of Bozrah reigned in his stead.',	'பேலா மரித்தபின், போஸ்றா பட்டணத்தானாகிய சேராகுடைய குமாரனாகிய யோபாப் அவன் பட்டத்திற்கு வந்தான்.',	1,	36,	33),
(1075,	'And Jobab died, and Husham of the land of Temani reigned in his stead.',	'யோபாப் மரித்தபின், தேமானிய தேசத்தானாகிய உஷாம் அவன் பட்டத்திற்கு வந்தான்.',	1,	36,	34),
(1076,	'And Husham died, and Hadad the son of Bedad, who smote Midian in the field of Moab, reigned in his stead: and the name of his city was Avith.',	'உஷாம் மரித்தபின், மோவாபின் நாட்டிலே மீதியானியரை முறிய அடித்த பேதாதின் குமாரனாகிய ஆதாத் அவன் பட்டத்திற்கு வந்தான்; அவனுடைய பட்டணத்துக்கு ஆவீத் என்று பேர்.',	1,	36,	35),
(1077,	'And Hadad died, and Samlah of Masrekah reigned in his stead.',	'ஆதாத் மரித்தபின், மஸ்ரேக்கா ஊரானாகிய சம்லா அவனுடைய பட்டத்திற்கு வந்தான்.',	1,	36,	36),
(1078,	'And Samlah died, and Saul of Rehoboth by the river reigned in his stead.',	'சம்லா மரித்தபின், அங்கே இருக்கிற நதிக்குச் சமீபமான ரெகொபோத் என்னும் ஊரானாகிய சவுல் அவனுடைய பட்டத்திற்கு வந்தான்.',	1,	36,	37),
(1079,	'And Saul died, and Baalhanan the son of Achbor reigned in his stead.',	'சவுல் மரித்தபின், அக்போருடைய குமாரனாகிய பாகால்கானான் அவனுடைய பட்டத்திற்கு வந்தான்.',	1,	36,	38),
(1080,	'And Baalhanan the son of Achbor died, and Hadar reigned in his stead: and the name of his city was Pau; and his wife\'s name was Mehetabel, the daughter of Matred, the daughter of Mezahab.',	'அக்போருடைய குமாரனாகிய பாகால்கானான் மரித்தபின், ஆதார் அவனுடைய பட்டத்திற்கு வந்தான். அவனுடைய பட்டணத்துக்குப் பாகு என்று பேர்; அவன் மனைவியின் பேர் மெகேதபேல்; அவள் மத்ரேத்துடைய குமாரத்தியும் மேசகாவின் குமாரத்தியுமாய் இருந்தாள்.',	1,	36,	39),
(1081,	'And these are the names of the dukes that came of Esau, according to their families, after their places, by their names; duke Timnah, duke Alvah, duke Jetheth,',	'தங்கள் பற்பல வம்சங்களின்படியேயும் வாசஸ்தலங்களின்படியேயும் நாமதேயங்களின்படியேயும் ஏசாவின் சந்ததியில் தோன்றிய பிரபுக்களுடைய நாமங்களாவன: திம்னா பிரபு, அல்வா பிரபு, ஏதேத் பிரபு,',	1,	36,	40),
(1082,	'Duke Aholibamah, duke Elah, duke Pinon,',	'அகோலிபாமா பிரபு, ஏலா பிரபு, பினோன் பிரபு,',	1,	36,	41),
(1083,	'Duke Kenaz, duke Teman, duke Mibzar,',	'கேனாஸ் பிரபு, தேமான் பிரபு, மிப்சார் பிரபு,',	1,	36,	42),
(1084,	'Duke Magdiel, duke Iram: these be the dukes of Edom, according to their habitations in the land of their possession: he is Esau the father of the Edomites.',	'மக்தியேல் பிரபு, ஈராம் பிரபு; இவர்களே தங்கள் சொந்தமான தேசத்திலே பற்பல இடங்களில் குடியிருந்த ஏதோம் சந்ததிப் பிரபுக்கள்; இந்த ஏதோமியருக்குத் தகப்பன் ஏசா.  ',	1,	36,	43),
(1085,	'And Jacob dwelt in the land wherein his father was a stranger, in the land of Canaan.',	'யாக்கோபு தன் தகப்பன் தங்கியிருந்த கானான் தேசத்திலே குடியிருந்தான்.',	1,	37,	1),
(1086,	'These are the generations of Jacob. Joseph, being seventeen years old, was feeding the flock with his brethren; and the lad was with the sons of Bilhah, and with the sons of Zilpah, his father\'s wives: and Joseph brought unto his father their evil report.',	'யாக்கோபுடைய சந்ததியின் வரலாறு: யோசேப்பு பதினேழு வயதிலே தன் சகோதரருடனே ஆடுகளை மேய்த்துக்கொண்டிருந்தான்; அந்த இளைஞன் பில்காள் சில்பாள் என்னும் தன் தகப்பனுடைய மறுமனையாட்டிகளின் குமாரரோடே இருந்து, அவர்களுடைய துன்மார்க்கத்தைத் தன் தகப்பனுக்குச் சொல்லிவருவான்.',	1,	37,	2),
(1087,	'Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours.',	'இஸ்ரவேலின் முதிர்வயதிலே யோசேப்பு தனக்குப் பிறந்ததினால், இஸ்ரவேல் தன் குமாரர் எல்லாரிலும் அவனை அதிகமாய் நேசித்து, அவனுக்குப் பலவருணமான அங்கியைச் செய்வித்தான்.',	1,	37,	3),
(1088,	'And when his brethren saw that their father loved him more than all his brethren, they hated him, and could not speak peaceably unto him.',	'அவனுடைய சகோதரர் எல்லாரிலும் அவனைத் தங்கள் தகப்பன் அதிகமாய் நேசிக்கிறதை அவன் சகோதரர் கண்டபோது, அவனோடே பட்சமாய்ப் பேசாமல் அவனைப் பகைத்தார்கள்.',	1,	37,	4),
(1089,	'And Joseph dreamed a dream, and he told it his brethren: and they hated him yet the more.',	'யோசேப்பு ஒரு சொப்பனம் கண்டு, அதைத் தன் சகோதரருக்கு அறிவித்தான்; அதினிமித்தம் அவனை இன்னும் அதிகமாய்ப் பகைத்தார்கள்.',	1,	37,	5),
(1090,	'And he said unto them, Hear, I pray you, this dream which I have dreamed:',	'அவன் அவர்களை நோக்கி: நான் கண்ட சொப்பனத்தைக் கேளுங்கள்:',	1,	37,	6),
(1091,	'For, behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf.',	'நாம் வயலில் அறுத்த அரிகளைக் கட்டிக்கொண்டிருந்தோம்; அப்பொழுது என்னுடைய அரிக்கட்டு நிமிர்ந்திருந்தது; உங்கள் அரிக்கட்டுகள் என் அரிக்கட்டைச் சுற்றி வணங்கி நின்றது என்றான்.',	1,	37,	7),
(1092,	'And his brethren said to him, Shalt thou indeed reign over us? or shalt thou indeed have dominion over us? And they hated him yet the more for his dreams, and for his words.',	'அப்பொழுது அவன் சகோதரர் அவனைப் பார்த்து: நீ எங்கள்மேல் துரைத்தனம் பண்ணுவாயோ? நீ எங்களை ஆளப்போகிறாயோ? என்று சொல்லி, அவனை அவன் சொப்பனங்களின் நிமித்தமும், அவன் வார்த்தைகளின் நிமித்தமும் இன்னும் அதிகமாய்ப் பகைத்தார்கள்.',	1,	37,	8),
(1093,	'And he dreamed yet another dream, and told it his brethren, and said, Behold, I have dreamed a dream more; and, behold, the sun and the moon and the eleven stars made obeisance to me.',	'அவன் வேறொரு சொப்பனம் கண்டு, தன் சகோதரரை நோக்கி: நான் இன்னும் ஒரு சொப்பனத்தைக் கண்டேன்; சூரியனும் சந்திரனும் பதினொரு நட்சத்திரங்களும் என்னை வணங்கினது என்றான்.',	1,	37,	9),
(1094,	'And he told it to his father, and to his brethren: and his father rebuked him, and said unto him, What is this dream that thou hast dreamed? Shall I and thy mother and thy brethren indeed come to bow down ourselves to thee to the earth?',	'இதை அவன் தன் தகப்பனுக்கும் தன் சகோதரருக்கும் சொன்னபோது, அவன் தகப்பன் அவனைப் பார்த்து: நீ கண்ட இந்தச் சொப்பனம் என்ன? நானும் உன் தாயாரும் உன் சகோதரரும் தரைமட்டும் குனிந்து உன்னை வணங்கவருவோமோ? என்று அவனைக் கடிந்து கொண்டான்.',	1,	37,	10),
(1095,	'And his brethren envied him; but his father observed the saying.',	'அவன் சகோதரர் அவன் மேல் பொறாமைகொண்டார்கள்; அவன் தகப்பனோ அவன் சொன்னதை மனதிலே வைத்துக்கொண்டான்.',	1,	37,	11),
(1096,	'And his brethren went to feed their father\'s flock in Shechem.',	'பின்பு, அவன் சகோதரர் சீகேமிலே தங்கள் தகப்பனுடைய ஆடுகளை மேய்க்கப் போனார்கள்.',	1,	37,	12),
(1097,	'And Israel said unto Joseph, Do not thy brethren feed the flock in Shechem? come, and I will send thee unto them. And he said to him, Here am I.',	'அப்பொழுது இஸ்ரவேல் யோசேப்பை நோக்கி: உன் சகோதரர் சீகேமிலே ஆடுகளை மேய்க்கிறார்கள் அல்லவா? உன்னை அவர்களிடத்துக்கு அனுப்பப் போகிறேன், வா என்றான். அவன்: இதோ, போகிறேன் என்றான்.',	1,	37,	13),
(1098,	'And he said to him, Go, I pray thee, see whether it be well with thy brethren, and well with the flocks; and bring me word again. So he sent him out of the vale of Hebron, and he came to Shechem.',	'அப்பொழுது அவன்: நீ போய், உன் சகோதரருடைய ஷேமம் எப்படி என்றும், ஆடுகள் எப்படி இருக்கிறது என்றும் பார்த்து, எனக்கு மறுசெய்தி கொண்டுவா என்று அவனுக்குச் சொல்லி, எபிரோன் பள்ளத்தாக்கிலே இருந்து அவனை அனுப்பினான்; அந்தப்படியே அவன் சீகேமுக்குப் போனான்.',	1,	37,	14),
(1099,	'And a certain man found him, and, behold, he was wandering in the field: and the man asked him, saying, What seekest thou?',	'அப்பொழுது ஒரு மனிதன் அவன் வெளியிலே வழிதப்பித் திரிகிறதைக் கண்டு, என்ன தேடுகிறாய்? என்று அவனைக் கேட்டான்.',	1,	37,	15),
(1100,	'And he said, I seek my brethren: tell me, I pray thee, where they feed their flocks.',	'அதற்கு அவன்: என் சகோதரரைத் தேடுகிறேன், அவர்கள் எங்கே ஆடு மேய்க்கிறார்கள், சொல்லும் என்றான்.',	1,	37,	16),
(1101,	'And the man said, They are departed hence; for I heard them say, Let us go to Dothan. And Joseph went after his brethren, and found them in Dothan.',	'அந்த மனிதன்: அவர்கள் இவ்விடத்திலிருந்து போய்விட்டார்கள், தோத்தானுக்குப் போவோம் என்று அவர்கள் சொல்லக்கேட்டேன் என்றான்; அப்பொழுது யோசேப்பு தன் சகோதரரைத் தொடர்ந்துபோய், அவர்களைத் தோத்தானிலே கண்டுபிடித்தான்.',	1,	37,	17),
(1102,	'And when they saw him afar off, even before he came near unto them, they conspired against him to slay him.',	'அவர்கள் அவனைத் தூரத்தில் வரக்கண்டு, அவன் தங்களுக்குச் சமீபமாய் வருமுன்னே, அவனைக் கொலைசெய்யும்படி சதியோசனைபண்ணி,',	1,	37,	18),
(1103,	'And they said one to another, Behold, this dreamer cometh.',	'ஒருவரை ஒருவர் நோக்கி: இதோ, சொப்பனக்காரன் வருகிறான்,',	1,	37,	19),
(1104,	'Come now therefore, and let us slay him, and cast him into some pit, and we will say, Some evil beast hath devoured him: and we shall see what will become of his dreams.',	'நாம் அவனைக் கொன்று, இந்தக் குழிகள் ஒன்றிலே அவனைப் போட்டு, ஒரு துஷ்டமிருகம் அவனைப் பட்சித்தது என்று சொல்லுவோம் வாருங்கள்; அவனுடைய சொப்பனங்கள் எப்படி முடியும் பார்ப்போம் என்றார்கள்.',	1,	37,	20),
(1105,	'And Reuben heard it, and he delivered him out of their hands; and said, Let us not kill him.',	'ரூபன் அதைக்கேட்டு, அவனை அவர்கள் கைக்குத் தப்புவித்து, அவனை அவன் தகப்பனிடத்துக்குத் திரும்பவும் கொண்டுபோக மனதுள்ளவனாய்,',	1,	37,	21),
(1106,	'And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again.',	'அவர்களை நோக்கி: அவனைக் கொல்ல வேண்டாம், நீங்கள் இரத்தம் சிந்தலாகாது; நீங்கள் அவன்மேல் கை வையாமல், அவனை வனாந்திரத்திலுள்ள இந்தக் குழியிலே போட்டுவிடுங்கள் என்று சொல்லி, இவ்விதமாய் ரூபன் அவனை அவர்கள் கைக்குத் தப்புவித்தான்.',	1,	37,	22),
(1107,	'And it came to pass, when Joseph was come unto his brethren, that they stript Joseph out of his coat, his coat of many colours that was on him;',	'யோசேப்பு தன் சகோதரரிடத்தில் சேர்ந்தபோது யோசேப்பு உடுத்திக்கொண்டிருந்த பலவருண அங்கியை அவர்கள் கழற்றி,',	1,	37,	23),
(1108,	'And they took him, and cast him into a pit: and the pit was empty, there was no water in it.',	'அவனை எடுத்து, அந்தக் குழியிலே போட்டார்கள்; அது தண்ணீரில்லாத வெறுங்குழியாயிருந்தது.',	1,	37,	24),
(1109,	'And they sat down to eat bread: and they lifted up their eyes and looked, and, behold, a company of Ishmeelites came from Gilead with their camels bearing spicery and balm and myrrh, going to carry it down to Egypt.',	'பின்பு, அவர்கள் போஜனஞ்செய்யும்படி உட்கார்ந்தார்கள்; அவர்கள் தங்கள் கண்களை ஏறெடுக்கும்போது, இதோ, கீலேயாத்திலிருந்து வருகிற இஸ்மவேலருடைய கூட்டத்தைக் கண்டார்கள்; அவர்கள் எகிப்துக்குக் கொண்டுபோகும்படி கந்தவர்க்கங்களையும் பிசின்தைலத்தையும் வெள்ளைப்போளத்தையும் ஒட்டகங்கள்மேல் ஏற்றிக்கொண்டுவந்தார்கள்.',	1,	37,	25),
(1110,	'And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood?',	'அப்பொழுது யூதா தன் சகோதரரை நோக்கி: நாம் நம்முடைய சகோதரனைக் கொன்று, அவன் இரத்தத்தை மறைப்பதினால் லாபம் என்ன?',	1,	37,	26),
(1111,	'Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content.',	'அவனை இந்த இஸ்மவேலருக்கு விற்றுப்போடுவோம் வாருங்கள்; நமது கை அவன்மேல் படாதிருப்பதாக; அவன் நம்முடைய சகோதரனும் நம்முடைய மாம்சமுமாய் இருக்கிறானே என்றான். அவன் சகோதரர் அவன் சொல்லுக்கு இணங்கினார்கள்.',	1,	37,	27),
(1112,	'Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt.',	'அந்த வர்த்தகரான மீதியானியர் கடந்துபோகிறபோது, அவர்கள் யோசேப்பை அந்தக் குழியிலிருந்து தூக்கியெடுத்து, அவனை இஸ்மவேலர் கையில் இருபது வெள்ளிக்காசுக்கு விற்றுப்போட்டார்கள். அவர்கள் யோசேப்பை எகிப்திற்குக் கொண்டுபோனார்கள்.',	1,	37,	28),
(1113,	'And Reuben returned unto the pit; and, behold, Joseph was not in the pit; and he rent his clothes.',	'பின்பு, ரூபன் அந்தக் குழியினிடத்துக்குத் திரும்பிப்போனபோது, யோசேப்பு குழியில் இல்லையென்று கண்டு, தன் வஸ்திரங்களைக் கிழித்துக்கொண்டு,',	1,	37,	29),
(1114,	'And he returned unto his brethren, and said, The child is not; and I, whither shall I go?',	'தன் சகோதரரிடத்துக்குத் திரும்பி வந்து: இளைஞன் இல்லையே, ஐயோ! நான் எங்கே போவேன் என்றான்.',	1,	37,	30),
(1115,	'And they took Joseph\'s coat, and killed a kid of the goats, and dipped the coat in the blood;',	'அவர்கள் யோசேப்பின் அங்கியை எடுத்து, ஒரு வெள்ளாட்டுக்கடாவை அடித்து, அந்த அங்கியை இரத்தத்திலே தோய்த்து,',	1,	37,	31),
(1116,	'And they sent the coat of many colours, and they brought it to their father; and said, This have we found: know now whether it be thy son\'s coat or no.',	'பல வருணமான அந்த அங்கியைத் தங்கள் தகப்பனிடத்துக்கு அனுப்பி: இதை நாங்கள் கண்டெடுத்தோம், இது உம்முடைய குமாரன் அங்கியோ, அல்லவோ, பாரும் என்று சொல்லச்சொன்னார்கள்.',	1,	37,	32),
(1117,	'And he knew it, and said, It is my son\'s coat; an evil beast hath devoured him; Joseph is without doubt rent in pieces.',	'யாக்கோபு அதைக் கண்டு, இது என் குமாரனுடைய அங்கிதான், ஒரு துஷ்டமிருகம் அவனைப் பட்சித்துப்போட்டது, யோசேப்பு பீறுண்டு போனான் என்று புலம்பி,',	1,	37,	33),
(1118,	'And Jacob rent his clothes, and put sackcloth upon his loins, and mourned for his son many days.',	'தன் வஸ்திரங்களைக் கிழித்து, தன் அரையில் இரட்டுக் கட்டிக்கொண்டு, அநேகநாள் தன் குமாரனுக்காகத் துக்கித்துக்கொண்டிருந்தான்.',	1,	37,	34),
(1119,	'And all his sons and all his daughters rose up to comfort him; but he refused to be comforted; and he said, For I will go down into the grave unto my son mourning. Thus his father wept for him.',	'அவனுடைய குமாரர் குமாரத்திகள் எல்லாரும் அவனுக்கு ஆறுதல் சொல்ல வந்து நின்றார்கள்; ஆனாலும் அவன் ஆறுதலுக்கு இடங்கொடாமல், நான் துக்கத்தோடே என் குமாரனிடத்தில் பாதாளத்தில் இறங்குவேன் என்றான். இவ்விதமாய் அவனுடைய தகப்பன் அவனுக்காக அழுதுகொண்டிருந்தான்.',	1,	37,	35),
(1120,	'And the Midianites sold him into Egypt unto Potiphar, an officer of Pharaoh\'s, and captain of the guard.',	'அந்த மீதியானியர் யோசேப்பை எகிப்திலே பார்வோனின் பிரதானியும் தலையாரிகளுக்கு அதிபதியுமாகிய போத்திபார் என்பவனிடத்தில் விற்றார்கள்.  ',	1,	37,	36),
(1121,	'And it came to pass at that time, that Judah went down from his brethren, and turned in to a certain Adullamite, whose name was Hirah.',	'அக்காலத்திலே யூதா தன் சகோதரரை விட்டு, அதுல்லாம் ஊரானாகிய ஈரா என்னும் ஒரு மனிதனிடத்தில் போய்ச் சேர்ந்தான்.',	1,	38,	1),
(1122,	'And Judah saw there a daughter of a certain Canaanite, whose name was Shuah; and he took her, and went in unto her.',	'அங்கே யூதா, சூவா என்னும் பேருள்ள ஒரு கானானியனுடைய குமாரத்தியைக் கண்டு, அவளை விவாகம்பண்ணி, அவளோடே சேர்ந்தான்.',	1,	38,	2),
(1123,	'And she conceived, and bare a son; and he called his name Er.',	'அவள் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்றாள்; அவனுக்கு ஏர் என்று பேரிட்டான்.',	1,	38,	3),
(1124,	'And she conceived again, and bare a son; and she called his name Onan.',	'அவள் மறுபடியும் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று, அவனுக்கு ஓனான் என்று பேரிட்டாள்.',	1,	38,	4),
(1125,	'And she yet again conceived, and bare a son; and called his name Shelah: and he was at Chezib, when she bare him.',	'அவள் மறுபடியும் கர்ப்பவதியாகி ஒரு குமாரனைப் பெற்று, அவனுக்குச் சேலா என்று பேரிட்டாள்; அவள் இவனைப் பெறுகிறபோது, அவன் கெசீபிலே இருந்தான்.',	1,	38,	5),
(1126,	'And Judah took a wife for Er his firstborn, whose name was Tamar.',	'யூதா தன் மூத்த மகனாகிய ஏர் என்பவனுக்குத் தாமார் என்னும் பேருள்ள ஒரு பெண்ணைக் கொண்டான்.',	1,	38,	6),
(1127,	'And Er, Judah\'s firstborn, was wicked in the sight of the LORD; and the LORD slew him.',	'யூதாவின் மூத்த மகனாகிய ஏர் என்பவன் கர்த்தரின் பார்வைக்குப் பொல்லாதவனாயிருந்ததினால், கர்த்தர் அவனை அழித்துப்போட்டார்.',	1,	38,	7),
(1128,	'And Judah said unto Onan, Go in unto thy brother\'s wife, and marry her, and raise up seed to thy brother.',	'அப்பொழுது யூதா ஓனானை நோக்கி: நீ உன் தமையன் மனைவியைச் சேர்ந்து, அவளை மைத்துனச் சுதந்தரமாய்ப்படைத்து, உன் தமையனுக்குச் சந்ததியை உண்டாக்கு என்றான்.',	1,	38,	8),
(1129,	'And Onan knew that the seed should not be his; and it came to pass, when he went in unto his brother\'s wife, that he spilled it on the ground, lest that he should give seed to his brother.',	'அந்தச் சந்ததி தன் சந்ததியாயிராதென்று ஓனான் அறிந்தபடியினாலே, அவன் தன் தமையனுடைய மனைவியைச் சேரும்போது, தன் தமையனுக்குச் சந்ததி உண்டாகாதபடிக்குத் தன் வித்தைத் தரையிலே விழவிட்டுக் கெடுத்தான்.',	1,	38,	9),
(1130,	'And the thing which he did displeased the LORD: wherefore he slew him also.',	'அவன் செய்தது கர்த்தரின் பார்வைக்குப் பொல்லாததாயிருந்ததினால், அவனையும் அவர் அழித்துப்போட்டார்.',	1,	38,	10),
(1131,	'Then said Judah to Tamar his daughter in law, Remain a widow at thy father\'s house, till Shelah my son be grown: for he said, Lest peradventure he die also, as his brethren did. And Tamar went and dwelt in her father\'s house.',	'அப்பொழுது யூதா, தன் குமாரனாகிய சேலாவும் அவன் சகோதரர் செத்தது போலச் சாவான் என்று அஞ்சி, தன் மருமகளாகிய தாமாரை நோக்கி: என் குமாரனாகிய சேலா பெரியவனாகுமட்டும், நீ உன் தகப்பன் வீட்டிலே கைம்பெண்ணாய்த் தங்கியிரு என்று சொன்னான்; அந்தப்படியே தாமார் போய்த் தன் தகப்பன் வீட்டிலே தங்கியிருந்தாள்.',	1,	38,	11),
(1132,	'And in process of time the daughter of Shuah Judah\'s wife died; and Judah was comforted, and went up unto his sheepshearers to Timnath, he and his friend Hirah the Adullamite.',	'அநேகநாள் சென்றபின், சூவாவின் குமாரத்தியாகிய யூதாவின் மனைவி மரித்தாள். யூதாவினுடைய துக்கம் ஆறினபின், அவன் அதுல்லாம் ஊரானாகிய தன் சிநேகிதன் ஈராவுடனே திம்னாவிலே தன் ஆடுகளை மயிர்க் கத்தரிக்கிறவர்களிடத்திற்குப் போனான்.',	1,	38,	12),
(1133,	'And it was told Tamar, saying, Behold thy father in law goeth up to Timnath to shear his sheep.',	'அப்பொழுது: உன் மாமனார் தம்முடைய ஆடுகளை மயிர்க்கத்தரிக்கத் திம்னாவுக்குப் போகிறார் என்று தாமாருக்கு அறிவிக்கப்பட்டது.',	1,	38,	13),
(1134,	'And she put her widow\'s garments off from her, and covered her with a vail, and wrapped herself, and sat in an open place, which is by the way to Timnath; for she saw that Shelah was grown, and she was not given unto him to wife.',	'சேலா பெரியவனாகியும் தான் அவனுக்கு மனைவியாகக் கொடுக்கப்படவில்லை என்று அவள் கண்டபடியால், தன் கைம்பெண்மைக்குரிய வஸ்திரங்களைக் களைந்துபோட்டு, முக்காடிட்டுத் தன்னை மூடிக்கொண்டு, திம்னாவுக்குப் போகிற வழியிலிருக்கிற நீரூற்றுகளுக்கு முன்பாக உட்கார்ந்தாள்.',	1,	38,	14),
(1135,	'When Judah saw her, he thought her to be an harlot; because she had covered her face.',	'யூதா அவளைக் கண்டு, அவள் தன் முகத்தை மூடியிருந்தபடியால், அவள் ஒரு வேசி என்று நினைத்து,',	1,	38,	15),
(1136,	'And he turned unto her by the way, and said, Go to, I pray thee, let me come in unto thee; (for he knew not that she was his daughter in law.) And she said, What wilt thou give me, that thou mayest come in unto me?',	'அந்த வழியாய் அவளிடத்தில் போய், அவள் தன் மருமகள் என்று அறியாமல்: நான் உன்னிடத்தில் சேரும்படி வருவாயா என்றான்; அதற்கு அவள்: நீர் என்னிடத்தில் சேரும்படி, எனக்கு என்ன தருவீர் என்றாள்.',	1,	38,	16),
(1137,	'And he said, I will send thee a kid from the flock. And she said, Wilt thou give me a pledge, till thou send it?',	'அதற்கு அவன்: நான் மந்தையிலிருந்து ஒரு வெள்ளாட்டுக்குட்டியை அனுப்புகிறேன் என்றான். அதற்கு அவள்: நீர் அதை அனுப்புமளவும் ஒரு அடைமானம் கொடுப்பீரா என்றாள்.',	1,	38,	17),
(1138,	'And he said, What pledge shall I give thee? And she said, Thy signet, and thy bracelets, and thy staff that is in thine hand. And he gave it her, and came in unto her, and she conceived by him.',	'அப்பொழுது அவன்: நான் உனக்கு அடைமானமாக என்ன கொடுக்கவேண்டும் என்று கேட்டான். அதற்கு அவள்: உம்முடைய முத்திரை மோதிரமும் உம்முடைய ஆரமும் உம்முடைய கைக்கோலும் கொடுக்கவேண்டும் என்றாள். அவன் அவைகளை அவளுக்குக் கொடுத்து, அவளிடத்தில் சேர்ந்தான்; அவள் அவனாலே கர்ப்பவதியாகி,',	1,	38,	18),
(1139,	'And she arose, and went away, and laid by her vail from her, and put on the garments of her widowhood.',	'எழுந்துபோய், தன் முக்காட்டைக் களைந்து, தன் கைம்பெண்மைக்குரிய வஸ்திரங்களை உடுத்திக்கொண்டாள்.',	1,	38,	19),
(1140,	'And Judah sent the kid by the hand of his friend the Adullamite, to receive his pledge from the woman\'s hand: but he found her not.',	'யூதா அந்த ஸ்திரீயினிடத்தில் இருந்த அடைமானத்தை வாங்கிக்கொண்டு வரும்படி அதுல்லாம் ஊரானாகிய தன் சிநேகிதன் கையிலே ஒரு வெள்ளாட்டுக்குட்டியைக் கொடுத்தனுப்பினான்; அவன் அவளைக் காணாமல்,',	1,	38,	20),
(1141,	'Then he asked the men of that place, saying, Where is the harlot, that was openly by the way side? And they said, There was no harlot in this place.',	'அவ்விடத்து மனிதரை நோக்கி: வழியண்டை நீரூற்றுகள் அருகே இருந்த தாசி எங்கே என்று கேட்டான்; அதற்கு அவர்கள்: இங்கே தாசி இல்லை என்றார்கள்.',	1,	38,	21),
(1142,	'And he returned to Judah, and said, I cannot find her; and also the men of the place said, that there was no harlot in this place.',	'அவன் யூதாவினிடத்தில் திரும்பி வந்து: அவளைக் காணோம், அங்கே தாசி இல்லையென்று அவ்விடத்து மனிதரும் சொல்லுகிறார்கள் என்றான்.',	1,	38,	22),
(1143,	'And Judah said, Let her take it to her, lest we be shamed: behold, I sent this kid, and thou hast not found her.',	'அப்பொழுது யூதா: இதோ, இந்த ஆட்டுக்குட்டியை அனுப்பினேன், நீ அவளைக் காணவில்லை; நமக்கு அவகீர்த்திவராதபடிக்கு, அவள் அதைக் கொண்டுபோனால் போகட்டும் என்றான்.',	1,	38,	23),
(1144,	'And it came to pass about three months after, that it was told Judah, saying, Tamar thy daughter in law hath played the harlot; and also, behold, she is with child by whoredom. And Judah said, Bring her forth, and let her be burnt.',	'ஏறக்குறைய மூன்றுமாதம் சென்றபின்பு உன் மருகளாகிய தாமார் வேசித்தனம்பண்ணினாள், அந்த வேசித்தனத்தினால் கர்ப்பவதியுமானாள் என்று யூதாவுக்கு அறிவிக்கப்பட்டது. அப்பொழுது யூதா: அவளை வெளியே கொண்டுவாருங்கள், அவள் சுட்டெரிக்கப்படவேண்டும் என்றான்.',	1,	38,	24),
(1145,	'When she was brought forth, she sent to her father in law, saying, By the man, whose these are, am I with child: and she said, Discern, I pray thee, whose are these, the signet, and bracelets, and staff.',	'அவள் வெளியே கொண்டுவரப்பட்டபோது, அவள் தன் மாமனிடத்துக்கு அந்த அடைமானத்தை அனுப்பி, இந்தப் பொருட்களை உடையவன் எவனோ அவனாலே நான் கர்ப்பவதியானேன்; இந்த முத்திரை மோதிரமும் இந்த ஆரமும் இந்தக் கோலும் யாருடையவைகள் பாரும் என்று சொல்லி அனுப்பினாள்.',	1,	38,	25),
(1146,	'And Judah acknowledged them, and said, She hath been more righteous than I; because that I gave her not to Shelah my son. And he knew her again no more.',	'யூதா அவைகளைப் பார்த்தறிந்து: என்னிலும் அவள் நீதியுள்ளவள்; அவளை என் குமாரனாகிய சேலாவுக்குக் கொடாமற்போனேனே என்றான். அப்புறம் அவன் அவளைச் சேரவில்லை.',	1,	38,	26),
(1147,	'And it came to pass in the time of her travail, that, behold, twins were in her womb.',	'அவளுக்குப் பிரசவகாலம் வந்தபோது, அவள் கர்ப்பத்தில் இரட்டைப்பிள்ளைகள் இருந்தன.',	1,	38,	27),
(1148,	'And it came to pass, when she travailed, that the one put out his hand: and the midwife took and bound upon his hand a scarlet thread, saying, This came out first.',	'அவள் பெறுகிறபேது, ஒரு பிள்ளை கையை நீட்டினது; அப்பொழுது மருத்துவச்சி அதின் கையைப் பிடித்து, அதில் சிவப்புநூலைக் கட்டி, இது முதலாவது வெளிப்பட்டது என்றாள்.',	1,	38,	28),
(1149,	'And it came to pass, as he drew back his hand, that, behold, his brother came out: and she said, How hast thou broken forth? this breach be upon thee: therefore his name was called Pharez.',	'அது தன் கையைத் திரும்ப உள்ளே வாங்கிக்கொண்டபோது, அதின் சகோதரன் வெளிப்பட்டான். அப்பொழுது அவள்: நீ மீறிவந்ததென்ன, இந்த மீறுதல் உன்மேல் நிற்கும் என்றாள்; அதினாலே அவனுக்குப் பாரேஸ் என்று பேரிடப்பட்டது.',	1,	38,	29),
(1150,	'And afterward came out his brother, that had the scarlet thread upon his hand: and his name was called Zarah.',	'பிற்பாடு கையில் சிவப்புநூல் கட்டியிருந்த அவனுடைய தம்பி வெளிப்பட்டான்; அவனுக்கு சேரா என்று பேரிடப்பட்டது.  ',	1,	38,	30),
(1151,	'And Joseph was brought down to Egypt; and Potiphar, an officer of Pharaoh, captain of the guard, an Egyptian, bought him of the hands of the Ishmeelites, which had brought him down thither.',	'யோசேப்பு எகிப்துக்குக் கொண்டு போகப்பட்டான். பார்வோனுடைய பிரதானியும் தலையாரிகளுக்கு அதிபதியுமாகிய போத்திபார் என்னும் எகிப்து தேசத்தான் அவனை அவ்விடத்திற்குக் கொண்டுவந்த இஸ்மவேலரிடத்தில் விலைக்கு வாங்கினான்.',	1,	39,	1),
(1152,	'And the LORD was with Joseph, and he was a prosperous man; and he was in the house of his master the Egyptian.',	'கர்த்தர் யோசேப்போடே இருந்தார், அவன் காரியசித்தியுள்ளவனானான்; அவன் எகிப்தியனாகிய தன் எஜமானுடைய வீட்டிலே இருந்தான்.',	1,	39,	2),
(1153,	'And his master saw that the LORD was with him, and that the LORD made all that he did to prosper in his hand.',	'கர்த்தர் அவனோடே இருக்கிறார் என்றும், அவன் செய்கிற யாவையும் கர்த்தர் வாய்க்கப்பண்ணுகிறார் என்றும், அவன் எஜமான் கண்டு;',	1,	39,	3),
(1154,	'And Joseph found grace in his sight, and he served him: and he made him overseer over his house, and all that he had he put into his hand.',	'யோசேப்பினிடத்தில் தயவுவைத்து, அவனைத் தனக்கு ஊழியக்காரனும் தன் வீட்டுக்கு விசாரணைக்காரனுமாக்கி, தனக்கு உண்டான யாவற்றையும் அவன் கையில் ஒப்புவித்தான்.',	1,	39,	4),
(1155,	'And it came to pass from the time that he had made him overseer in his house, and over all that he had, that the LORD blessed the Egyptian\'s house for Joseph\'s sake; and the blessing of the LORD was upon all that he had in the house, and in the field.',	'அவனைத் தன் வீட்டுக்கும் தனக்கு உண்டான எல்லாவற்றிற்கும் விசாரணைக்காரனாக்கினது முதற்கொண்டு, கர்த்தர் யோசேப்பினிமித்தம் அந்த எகிப்தியன் வீட்டை ஆசீர்வதித்தார்; வீட்டிலும் வெளியிலும் அவனுக்கு உண்டானவைகள் எல்லாவற்றிலும் கர்த்தருடைய ஆசீர்வாதம் இருந்தது.',	1,	39,	5),
(1156,	'And he left all that he had in Joseph\'s hand; and he knew not ought he had, save the bread which he did eat. And Joseph was a goodly person, and well favoured.',	'ஆகையால், அவன் தனக்கு உண்டானதையெல்லாம் யோசேப்பின் கையிலே ஒப்புக்கொடுத்துவிட்டு, தான் புசிக்கிற போஜனம் தவிர தன்னிடத்திலிருந்த மற்றொன்றைக்குறித்தும் விசாரியாதிருந்தான். யோசேப்பு அழகான ரூபமும் சௌந்தரிய முகமும் உள்ளவனாயிருந்தான்.',	1,	39,	6),
(1157,	'And it came to pass after these things, that his master\'s wife cast her eyes upon Joseph; and she said, Lie with me.',	'சிலநாள் சென்றபின், அவனுடைய எஜமானின் மனைவி யோசேப்பின்மேல் கண்போட்டு, என்னோடே சயனி என்றாள்.',	1,	39,	7),
(1158,	'But he refused, and said unto his master\'s wife, Behold, my master wotteth not what is with me in the house, and he hath committed all that he hath to my hand;',	'அவனோ தன் எஜமானுடைய மனைவியின் சொல்லுக்கு இணங்காமல், அவளை நோக்கி: இதோ, வீட்டிலே என்னிடத்தில் இருக்கிறவைகளில் யாதொன்றைக்குறித்தும் என் ஆண்டவன் விசாரியாமல், தமக்கு உண்டான எல்லாவற்றையும் என்கையில் ஒப்பித்திருக்கிறார்.',	1,	39,	8),
(1159,	'There is none greater in this house than I; neither hath he kept back any thing from me but thee, because thou art his wife: how then can I do this great wickedness, and sin against God?',	'இந்த வீட்டிலே என்னிலும் பெரியவன் இல்லை; நீ அவருடைய மனைவியாயிருக்கிறபடியால் உன்னைத்தவிர வேறோன்றையும் அவர் எனக்கு விலக்கி வைக்கவில்லை; இப்படியிருக்க, நான் இத்தனை பெரிய பொல்லாங்குக்கு உடன்பட்டு, தேவனுக்கு விரோதமாய்ப் பாவம் செய்வது எப்படி என்றான்.',	1,	39,	9),
(1160,	'And it came to pass, as she spake to Joseph day by day, that he hearkened not unto her, to lie by her, or to be with her.',	'அவள் நித்தம் நித்தம் யோசேப்போடே இப்படிப் பேசிக்கொண்டு வந்தும், அவன் அவளுடனே சயனிக்கவும் அவளுடனே இருக்கவும் சம்மதிக்கவில்லை.',	1,	39,	10),
(1161,	'And it came to pass about this time, that Joseph went into the house to do his business; and there was none of the men of the house there within.',	'இப்படியிருக்கும்போது, ஒருநாள் அவன் தன் வேலையைச் செய்கிறதற்கு வீட்டுக்குள் போனான்; வீட்டு மனிதரில் ஒருவரும் வீட்டில் இல்லை.',	1,	39,	11),
(1162,	'And she caught him by his garment, saying, Lie with me: and he left his garment in her hand, and fled, and got him out.',	'அப்பொழுது அவள் அவனுடைய வஸ்திரத்தைப் பற்றிப் பிடித்து, என்னோடே சயனி என்றாள். அவனோ தன் வஸ்திரத்தை அவள் கையிலே விட்டு வெளியே ஓடிப்போனான்.',	1,	39,	12),
(1163,	'And it came to pass, when she saw that he had left his garment in her hand, and was fled forth,',	'அவன் தன் வஸ்திரத்தை அவள் கையிலே விட்டு வெளியே ஓடிப்போனதை அவள் கண்டபோது,',	1,	39,	13),
(1164,	'That she called unto the men of her house, and spake unto them, saying, See, he hath brought in an Hebrew unto us to mock us; he came in unto me to lie with me, and I cried with a loud voice:',	'அவள் தன் வீட்டு மனிதரைக் கூப்பிட்டு: பாருங்கள், எபிரெய மனுஷன் நம்மிடத்தில் சரசம்பண்ணும்படிக்கு அவனை நமக்குள் கொண்டுவந்தார், அவன் என்னோடே சயனிக்கும்படிக்கு என்னிடத்தில் வந்தான்; நான் மிகுந்த சத்தமிட்டுக் கூப்பிட்டேன்.',	1,	39,	14),
(1165,	'And it came to pass, when he heard that I lifted up my voice and cried, that he left his garment with me, and fled, and got him out.',	'நான் சத்தமிட்டுக் கூப்பிடுகிறதை அவன் கேட்டு, தன் வஸ்திரத்தை என்னிடத்தில் விட்டு, வெளியே ஓடிப்போய்விட்டான் என்று சொன்னாள்.',	1,	39,	15),
(1166,	'And she laid up his garment by her, until his lord came home.',	'அவனுடைய எஜமான் வீட்டுக்கு வருமளவும் அவனுடைய வஸ்திரத்தைத் தன்னிடத்தில் வைத்திருந்து,',	1,	39,	16),
(1167,	'And she spake unto him according to these words, saying, The Hebrew servant, which thou hast brought unto us, came in unto me to mock me:',	'அவனை நோக்கி: நீர் நம்மிடத்தில் கொண்டுவந்த அந்த எபிரெய வேலைக்காரன் சரசம்பண்ணும்படிக்கு என்னிடத்தில் வந்தான்.',	1,	39,	17),
(1168,	'And it came to pass, as I lifted up my voice and cried, that he left his garment with me, and fled out.',	'அப்பொழுது நான் சத்தமிட்டுக்கூப்பிட்டேன், அவன் தன் வஸ்திரத்தை என்னிடத்தில் விட்டு வெளியே ஓடிப்போனான் என்றாள்.',	1,	39,	18),
(1169,	'And it came to pass, when his master heard the words of his wife, which she spake unto him, saying, After this manner did thy servant to me; that his wrath was kindled.',	'உம்முடைய வேலைக்காரன் எனக்கு இப்படிச் செய்தான் என்று தன் மனைவி தன்னோடே சொன்ன வார்த்தைகளை அவனுடைய எஜமான் கேட்டபோது, அவனுக்குக் கோபம் மூண்டது.',	1,	39,	19),
(1170,	'And Joseph\'s master took him, and put him into the prison, a place where the king\'s prisoners were bound: and he was there in the prison.',	'யோசேப்பின் எஜமான் அவனைப்பிடித்து, ராஜாவின் கட்டளையால் காவலில் வைக்கப்பட்டவர்கள் இருக்கும் சிறைச்சாலையிலே அவனை ஒப்புவித்தான். அந்தச் சிறைச்சாலையில் அவன் இருந்தான்.',	1,	39,	20),
(1171,	'But the LORD was with Joseph, and shewed him mercy, and gave him favour in the sight of the keeper of the prison.',	'கர்த்தரோ யோசேப்போடே இருந்து, அவன்மேல் கிருபைவைத்து, சிறைச்சாலைத் தலைவனுடைய தயவு அவனுக்குக் கிடைக்கும்படி செய்தார்.',	1,	39,	21),
(1172,	'And the keeper of the prison committed to Joseph\'s hand all the prisoners that were in the prison; and whatsoever they did there, he was the doer of it.',	'சிறைச்சாலைத் தலைவன் சிறைச்சாலையில் வைக்கப்பட்ட யாவரையும் யோசேப்பின் கையிலே ஒப்புவித்தான்; அங்கே அவர்கள் செய்வதெல்லாவற்றையும் யோசேப்பு செய்வித்தான்.',	1,	39,	22),
(1173,	'The keeper of the prison looked not to any thing that was under his hand; because the LORD was with him, and that which he did, the LORD made it to prosper.',	'கர்த்தர் அவனோடே இருந்தபடியினாலும், அவன் எதைச் செய்தானோ அதைக் கர்த்தர் வாய்க்கப்பண்ணினபடியினாலும், அவன் வசமாயிருந்த யாதொன்றையும் குறித்துச் சிறைச்சாலைத் தலைவன் விசாரிக்கவில்லை.  ',	1,	39,	23),
(1174,	'And it came to pass after these things, that the butler of the king of Egypt and his baker had offended their lord the king of Egypt.',	'இந்த நடபடிகளுக்குப்பின்பு, எகிப்து ராஜாவுக்குப் பானபாத்திரக்காரனும் சுயம்பாகியும் எகிப்து ராஜாவாகிய தங்கள் ஆண்டவனுக்குக் குற்றம் செய்தார்கள்.',	1,	40,	1),
(1175,	'And Pharaoh was wroth against two of his officers, against the chief of the butlers, and against the chief of the bakers.',	'பார்வோன் தன் பானபாத்திரக்காரரின் தலைவனும் சுயம்பாகிகளின் தலைவனும் ஆகிய இவ்விரண்டு பிரதானிகள் மேலும் கடுங்கோபங்கொண்டு,',	1,	40,	2),
(1176,	'And he put them in ward in the house of the captain of the guard, into the prison, the place where Joseph was bound.',	'அவர்களை யோசேப்பு வைக்கப்பட்டிருந்த இடமும் தலையாரிகளின் அதிபதியின் வீடுமாகிய சிறைச்சாலையிலே காவல்பண்ணுவித்தான்.',	1,	40,	3),
(1177,	'And the captain of the guard charged Joseph with them, and he served them: and they continued a season in ward.',	'தலையாரிகளின் அதிபதி அவர்களை விசாரிக்கும்படி யோசேப்பின் வசத்தில் ஒப்புவித்தான்; அவன் அவர்களை விசாரித்து வந்தான்; அவர்கள் அநேகநாள் காவலில் இருந்தார்கள்.',	1,	40,	4),
(1178,	'And they dreamed a dream both of them, each man his dream in one night, each man according to the interpretation of his dream, the butler and the baker of the king of Egypt, which were bound in the prison.',	'எகிப்து ராஜாவுக்குப் பானபாத்திரக்காரனும் சுயம்பாகியுமாகிய அவ்விரண்டுபேரும் சிறைச்சாலையில் இருக்கும்போது, ஒரே ராத்திரியிலே வெவ்வேறு பொருள்கொண்ட சொப்பனம் கண்டார்கள்.',	1,	40,	5),
(1179,	'And Joseph came in unto them in the morning, and looked upon them, and, behold, they were sad.',	'காலமே யோசேப்பு அவர்களிடத்தில் போய், அவர்களைப் பார்க்கும்போது, அவர்கள் கலங்கியிருந்தார்கள்.',	1,	40,	6),
(1180,	'And he asked Pharaoh\'s officers that were with him in the ward of his lord\'s house, saying, Wherefore look ye so sadly to day?',	'அப்பொழுது அவன் தன் எஜமானுடைய வீட்டில் தன்னோடே காவல்பண்ணப்பட்டிருந்த பார்வோனுடைய பிரதானிகளை நோக்கி: உங்கள் முகங்கள் இன்று துக்கமாயிருக்கிறது என்ன என்று கேட்டான்.',	1,	40,	7),
(1181,	'And they said unto him, We have dreamed a dream, and there is no interpreter of it. And Joseph said unto them, Do not interpretations belong to God? tell me them, I pray you.',	'அதற்கு அவர்கள்: சொப்பனம் கண்டோம், அதற்கு அர்த்தம் சொல்லுகிறவன் ஒருவனும் இல்லை என்றார்கள். அதற்கு யோசேப்பு: சொப்பனத்துக்கு அர்த்தம் சொல்லுதல் தேவனுக்குரியதல்லவா? அவைகளை என்னிடத்தில் சொல்லுங்கள் என்றான்.',	1,	40,	8),
(1182,	'And the chief butler told his dream to Joseph, and said to him, In my dream, behold, a vine was before me;',	'அப்பொழுது பானபாத்திரக்காரரின் தலைவன் யோசேப்பை நோக்கி: என் சொப்பனத்திலே ஒரு திராட்சச்செடி எனக்கு முன்பாக இருக்கக்கண்டேன்.',	1,	40,	9),
(1183,	'And in the vine were three branches: and it was as though it budded, and her blossoms shot forth; and the clusters thereof brought forth ripe grapes:',	'அந்தத் திராட்சச்செடியிலே மூன்று கொடிகள் இருந்தது; அது துளிர்க்கிறதாயிருந்தது; அதில் பூக்கள் மலர்ந்திருந்தது; அதின் குலைகள் பழுத்த பழங்களாயிருந்தது.',	1,	40,	10),
(1184,	'And Pharaoh\'s cup was in my hand: and I took the grapes, and pressed them into Pharaoh\'s cup, and I gave the cup into Pharaoh\'s hand.',	'பார்வோனுடைய பாத்திரம் என்கையிலே இருந்தது; நான் அந்தப் பழங்களைப் பறித்து, அவைகளைப் பார்வோனுடைய பாத்திரத்தில் பிழிந்து, அந்தப் பாத்திரத்தைப் பார்வோனுடைய கையிலே கொடுத்தேன் என்று, தன் சொப்பனத்தைச் சொன்னான்.',	1,	40,	11),
(1185,	'And Joseph said unto him, This is the interpretation of it: The three branches are three days:',	'அதற்கு யோசேப்பு: அந்த மூன்று கொடிகளும் மூன்று நாளாம்.',	1,	40,	12),
(1186,	'Yet within three days shall Pharaoh lift up thine head, and restore thee unto thy place: and thou shalt deliver Pharaoh\'s cup into his hand, after the former manner when thou wast his butler.',	'மூன்று நாளைக்குள்ளே பார்வோன் உன் தலையை உயர்த்தி, உன்னை மறுபடியும் உன் நிலையிலே நிறுத்துவார்; முன்னே அவருக்குப் பானம் கொடுத்துவந்த வழக்கத்தின்படி பார்வோனின் பாத்திரத்தை அவர் கையிலே கொடுப்பாய்;',	1,	40,	13),
(1187,	'But think on me when it shall be well with thee, and shew kindness, I pray thee, unto me, and make mention of me unto Pharaoh, and bring me out of this house:',	'இதுதான் அதின் அர்த்தம் என்று சொன்னதும் அன்றி நீ வாழ்வடைந்திருக்கும்போது, என்னை நினைத்து, என்மேல் தயவுவைத்து, என் காரியத்தைப் பார்வோனுக்கு அறிவித்து, இந்த இடத்திலிருந்து என்னை விடுதலையாக்கவேண்டும்.',	1,	40,	14),
(1188,	'For indeed I was stolen away out of the land of the Hebrews: and here also have I done nothing that they should put me into the dungeon.',	'நான் எபிரெயருடைய தேசத்திலிருந்து களவாய்க் கொண்டுவரப்பட்டேன்; என்னை இந்தக் காவல்கிடங்கில் வைக்கும்படிக்கும் நான் இவ்விடத்தில் ஒன்றும் செய்யவில்லை என்றும் சொன்னான்.',	1,	40,	15),
(1189,	'When the chief baker saw that the interpretation was good, he said unto Joseph, I also was in my dream, and, behold, I had three white baskets on my head:',	'அர்த்தம் நன்றாயிருக்கிறது என்று சுயம்பாகிகளின் தலைவன் கண்டு, யோசேப்பை நோக்கி: நானும் என் சொப்பனத்தில் மூன்று வெள்ளைக் கூடைகள் என் தலையின்மேல் இருக்கக்கண்டேன்;',	1,	40,	16),
(1190,	'And in the uppermost basket there was of all manner of bakemeats for Pharaoh; and the birds did eat them out of the basket upon my head.',	'மேற்கூடையிலே பார்வோனுக்காக சமைக்கப்பட்ட சகலவித பலகாரங்களிலும் கொஞ்சம் கொஞ்சம் இருந்தது; என் தலையின் மேல் கூடையில் இருந்தவைகளைப் பறவைகள் வந்து பட்சித்தது என்றான்.',	1,	40,	17),
(1191,	'And Joseph answered and said, This is the interpretation thereof: The three baskets are three days:',	'அதற்கு யோசேப்பு: அந்த மூன்று கூடைகளும் மூன்று நாளாம்.',	1,	40,	18),
(1192,	'Yet within three days shall Pharaoh lift up thy head from off thee, and shall hang thee on a tree; and the birds shall eat thy flesh from off thee.',	'இன்னும் மூன்று நாளைக்குள்ளே பார்வோன் உன் தலையை உயர்த்தி, உன்னை மரத்திலே தூக்கிப்போடுவார்; அப்பொழுது பறவைகள் உன் மாம்சத்தைத் தின்னும், இதுதான் அதின் அர்த்தம் என்று சொன்னான்.',	1,	40,	19),
(1193,	'And it came to pass the third day, which was Pharaoh\'s birthday, that he made a feast unto all his servants: and he lifted up the head of the chief butler and of the chief baker among his servants.',	'மூன்றாம் நாள் பார்வோனுடைய ஜன்ம நாளாயிருந்தது; அவன் தன் ஊழியக்காரர் எல்லாருக்கும் விருந்துபண்ணி, பானபாத்திரக்காரருடைய தலைவன் தலையையும் சுயம்பாகிகளுடைய தலைவன் தலையையும் தன் உத்தியோகஸ்தரின் நடுவே உயர்த்தி,',	1,	40,	20),
(1194,	'And he restored the chief butler unto his butlership again; and he gave the cup into Pharaoh\'s hand:',	'பானபாத்திரக்காரரின் தலைவனைப் பானங்கொடுக்கிற தன் உத்தியோகத்திலே மறுபடியும் வைத்தான்; அந்தப்படியே அவன் பார்வோனுடைய கையிலே பாத்திரத்தைக் கொடுத்தான்.',	1,	40,	21),
(1195,	'But he hanged the chief baker: as Joseph had interpreted to them.',	'சுயம்பாகிகளின் தலைவனையோ தூக்கிப்போட்டான். யோசேப்பு அவர்களுக்குச் சொன்ன அர்த்தத்தின்படியே சம்பவித்தது.',	1,	40,	22),
(1196,	'Yet did not the chief butler remember Joseph, but forgat him.',	'ஆனாலும் பானபாத்திரக்காரனின் தலைவன் யோசேப்பை நினையாமல் அவனை மறந்துவிட்டான்.  ',	1,	40,	23),
(1197,	'And it came to pass at the end of two full years, that Pharaoh dreamed: and, behold, he stood by the river.',	'இரண்டு வருஷம் சென்றபின்பு, பார்வோன் ஒரு சொப்பனம் கண்டான்; அது என்னவென்றால், அவன் நதியண்டையிலே நின்றுகொண்டிருந்தான்.',	1,	41,	1),
(1198,	'And, behold, there came up out of the river seven well favoured kine and fatfleshed; and they fed in a meadow.',	'அப்பொழுது அழகும் புஷ்டியுமான ஏழு பசுக்கள் நதியிலிருந்து ஏறிவந்து புல் மேய்ந்தது.',	1,	41,	2),
(1199,	'And, behold, seven other kine came up after them out of the river, ill favoured and leanfleshed; and stood by the other kine upon the brink of the river.',	'அவைகளின்பின் அவலட்சணமும் கேவலமுமான வேறே ஏழு பசுக்கள் நதியிலிருந்து ஏறிவந்து, நதி ஓரத்தில் மற்றப் பசுக்களண்டையிலே நின்றது.',	1,	41,	3),
(1200,	'And the ill favoured and leanfleshed kine did eat up the seven well favoured and fat kine. So Pharaoh awoke.',	'அவலட்சணமும் கேவலமுமான பசுக்கள் அழகும் புஷ்டியுமான ஏழு பசுக்களையும் பட்சித்துப்போட்டது; இப்படிப் பார்வோன் கண்டு விழித்துக்கொண்டான்.',	1,	41,	4),
(1201,	'And he slept and dreamed the second time: and, behold, seven ears of corn came up upon one stalk, rank and good.',	'மறுபடியும் அவன் நித்திரைசெய்து, இரண்டாம் விசை ஒரு சொப்பனம் கண்டான்; நல்ல செழுமையான ஏழு கதிர்கள் ஒரே தாளிலிருந்து ஓங்கி வளர்ந்தது.',	1,	41,	5),
(1202,	'And, behold, seven thin ears and blasted with the east wind sprung up after them.',	'பின்பு, சாவியானதும் கீழ்காற்றினால் தீய்ந்ததுமான ஏழு கதிர்கள் முளைத்தது.',	1,	41,	6),
(1203,	'And the seven thin ears devoured the seven rank and full ears. And Pharaoh awoke, and, behold, it was a dream.',	'சாவியான கதிர்கள் செழுமையும் நிறைமேனியுமான அந்த ஏழு கதிர்களையும் விழுங்கிப்போட்டது; அப்பொழுது பார்வோன் விழித்துக்கொண்டு, அது சொப்பனம் என்று அறிந்தான்.',	1,	41,	7),
(1204,	'And it came to pass in the morning that his spirit was troubled; and he sent and called for all the magicians of Egypt, and all the wise men thereof: and Pharaoh told them his dream; but there was none that could interpret them unto Pharaoh.',	'காலமே பார்வோனுடைய மனம் கலக்கங்கொண்டிருந்தது; அப்பொழுது அவன் எகிப்திலுள்ள சகல மந்திரவாதிகளையும் சகல சாஸ்திரிகளையும் அழைப்பித்து, அவர்களுக்குத் தன் சொப்பனத்தைச் சொன்னான்; ஒருவராலும் அதின் அர்த்தத்தைப் பார்வோனுக்குச் சொல்லக் கூடாமற்போயிற்று.',	1,	41,	8),
(1205,	'Then spake the chief butler unto Pharaoh, saying, I do remember my faults this day:',	'அப்பொழுது பானபாத்திரக்காரரின் தலைவன் பார்வோனை நோக்கி: நான் செய்த குற்றம் இன்றுதான் என் நினைவில் வந்தது.',	1,	41,	9),
(1206,	'Pharaoh was wroth with his servants, and put me in ward in the captain of the guard\'s house, both me and the chief baker:',	'பார்வோன் தம்முடைய ஊழியக்காரர்மேல் கடுங்கோபங்கொண்டு, என்னையும் சுயம்பாகிகளின் தலைவனையும் தலையாரிகளின் அதிபதி வீடாகிய சிறைச்சாலையிலே வைத்திருந்த காலத்தில்,',	1,	41,	10),
(1207,	'And we dreamed a dream in one night, I and he; we dreamed each man according to the interpretation of his dream.',	'நானும் அவனும் ஒரே இராத்திரியிலே வெவ்வேறு பொருள்கொண்ட சொப்பனம் கண்டோம்.',	1,	41,	11),
(1208,	'And there was there with us a young man, an Hebrew, servant to the captain of the guard; and we told him, and he interpreted to us our dreams; to each man according to his dream he did interpret.',	'அப்பொழுது தலையாரிகளின் அதிபதிக்கு வேலைக்காரனாகிய எபிரெய பிள்ளையாண்டான் ஒருவன் அங்கே எங்களோடே இருந்தான்; அவனிடத்தில் அவைகளைச் சொன்னோம், அவன் நாங்கள் கண்ட சொப்பனங்களுக்குரிய வெவ்வேறு அர்த்தத்தின்படியே எங்கள் சொப்பனத்தின் பயனைச் சொன்னான்.',	1,	41,	12),
(1209,	'And it came to pass, as he interpreted to us, so it was; me he restored unto mine office, and him he hanged.',	'அவன் எங்களுக்குச் சொல்லிய அர்த்தத்தின்படியே நடந்தது; என்னைத் திரும்ப என் நிலையிலே நிறுத்தி, அவனைத் தூக்கிப்போடுவித்தார் என்றான்.',	1,	41,	13),
(1210,	'Then Pharaoh sent and called Joseph, and they brought him hastily out of the dungeon: and he shaved himself, and changed his raiment, and came in unto Pharaoh.',	'அப்பொழுது பார்வோன் யோசேப்பை அழைப்பித்தான்; அவனைத் தீவிரமாய்க் காவல்கிடங்கிலிருந்து கொண்டுவந்தார்கள். அவன் சவரம் பண்ணிக்கொண்டு, வேறு வஸ்திரம் தரித்து, பார்வோனிடத்தில் வந்தான்.',	1,	41,	14),
(1211,	'And Pharaoh said unto Joseph, I have dreamed a dream, and there is none that can interpret it: and I have heard say of thee, that thou canst understand a dream to interpret it.',	'பார்வோன் யோசேப்பை நோக்கி: ஒரு சொப்பனம் கண்டேன்; அதின் அர்த்தத்தைச் சொல்ல ஒருவரும் இல்லை; நீ ஒரு சொப்பனத்தைக் கேட்டால், அதின் அர்த்தத்தைச் சொல்லுவாய் என்று உன்னைக்குறித்து நான் கேள்விப்பட்டேன் என்றான்.',	1,	41,	15),
(1212,	'And Joseph answered Pharaoh, saying, It is not in me: God shall give Pharaoh an answer of peace.',	'அப்பொழுது யோசேப்பு பார்வோனுக்குப் பிரதியுத்தரமாக: நான் அல்ல, தேவனே பார்வோனுக்கு மங்களமான உத்தரவு அருளிச்செய்வார் என்றான்.',	1,	41,	16),
(1213,	'And Pharaoh said unto Joseph, In my dream, behold, I stood upon the bank of the river:',	'பார்வோன் யோசேப்பை நோக்கி: என் சொப்பனத்திலே, நான் நதி ஓரத்தில் நின்றுகொண்டிருந்தேன்.',	1,	41,	17),
(1214,	'And, behold, there came up out of the river seven kine, fatfleshed and well favoured; and they fed in a meadow:',	'அழகும் புஷ்டியுமான ஏழு பசுக்கள் நதியிலிருந்து ஏறிவந்து புல்மேய்ந்தது.',	1,	41,	18),
(1215,	'And, behold, seven other kine came up after them, poor and very ill favoured and leanfleshed, such as I never saw in all the land of Egypt for badness:',	'அவைகளின்பின் இளைத்ததும் மகா அவலட்சணமும் கேவலமுமான வேறே ஏழு பசுக்கள் ஏறிவந்தது; இவைகளைப்போல அவலட்சணமான பசுக்களை எகிப்து தேசமெங்கும் நான் கண்டதில்லை.',	1,	41,	19),
(1216,	'And the lean and the ill favoured kine did eat up the first seven fat kine:',	'கேவலமும் அவலட்சணமுமான பசுக்கள் கொழுமையான முந்தின ஏழு பசுக்களையும் பட்சித்துப்போட்டது.',	1,	41,	20),
(1217,	'And when they had eaten them up, it could not be known that they had eaten them; but they were still ill favoured, as at the beginning. So I awoke.',	'அவைகள் இவைகளின் வயிற்றுக்குள் போயும், வயிற்றுக்குள் போயிற்றென்று தோன்றாமல், முன் இருந்தது போலவே அவலட்சணமாயிருந்தது; இப்படிக் கண்டு விழித்துக்கொண்டேன்.',	1,	41,	21),
(1218,	'And I saw in my dream, and, behold, seven ears came up in one stalk, full and good:',	'பின்னும் நான் என் சொப்பனத்திலே, நிறைமேனியுள்ள ஏழு நல்ல கதிர்கள் ஒரே தாளிலிருந்து ஓங்கி வளரக்கண்டேன்.',	1,	41,	22),
(1219,	'And, behold, seven ears, withered, thin, and blasted with the east wind, sprung up after them:',	'பின்பு சாவியானவைகளும் கீழ்காற்றினால் தீய்ந்து பதரானவைகளுமான ஏழு கதிர்கள் முளைத்தது.',	1,	41,	23),
(1220,	'And the thin ears devoured the seven good ears: and I told this unto the magicians; but there was none that could declare it to me.',	'சாவியான கதிர்கள் அந்த ஏழு நல்ல கதிர்களையும் விழுங்கிப்போட்டது. இதை மந்திரவாதிகளிடத்தில் சொன்னேன்; இதின் பொருளை எனக்கு விடுவிக்கிறவன் ஒருவனும் இல்லை என்றான்.',	1,	41,	24),
(1221,	'And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do.',	'அப்பொழுது யோசேப்பு பார்வோனை நோக்கி: பார்வோனின் சொப்பனம் ஒன்று தான்; தேவன் தாம் செய்யப்போகிறது இன்னதென்று பார்வோனுக்கு அறிவித்திருக்கிறார்.',	1,	41,	25),
(1222,	'The seven good kine are seven years; and the seven good ears are seven years: the dream is one.',	'அந்த ஏழு நல்ல பசுக்களும் ஏழு வருஷமாம்; அந்த ஏழு நல்ல கதிர்களும் ஏழு வருஷமாம்; சொப்பனம் ஒன்றே.',	1,	41,	26),
(1223,	'And the seven thin and ill favoured kine that came up after them are seven years; and the seven empty ears blasted with the east wind shall be seven years of famine.',	'அவைகளின்பின் ஏறிவந்த கேவலமும் அவலட்சணமுமான ஏழு பசுக்களும் ஏழு வருஷமாம்; கீழ்காற்றினால் தீய்ந்து சாவியான ஏழு கதிர்களும் ஏழு வருஷமாம்; இவைகள் பஞ்சமுள்ள ஏழு வருஷமாம்.',	1,	41,	27),
(1224,	'This is the thing which I have spoken unto Pharaoh: What God is about to do he sheweth unto Pharaoh.',	'பார்வோனுக்கு நான் சொல்லவேண்டிய காரியம் இதுவே; தேவன் தாம் செய்யப்போகிறதைப் பார்வோனுக்குக் காண்பித்திருக்கிறார்.',	1,	41,	28),
(1225,	'Behold, there come seven years of great plenty throughout all the land of Egypt:',	'எகிப்து தேசமெங்கும் பரிபூரணமான விளைவு உண்டாயிருக்கும் ஏழு வருஷம் வரும்.',	1,	41,	29),
(1226,	'And there shall arise after them seven years of famine; and all the plenty shall be forgotten in the land of Egypt; and the famine shall consume the land;',	'அதன்பின் பஞ்சமுண்டாயிருக்கும் ஏழு வருஷம் வரும்; அப்பொழுது எகிப்துதேசத்தில் அந்தப் பரிபூரணமெல்லாம் மறக்கப்பட்டுப்போகும்; அந்தப் பஞ்சம் தேசத்தைப் பாழாக்கும்.',	1,	41,	30),
(1227,	'And the plenty shall not be known in the land by reason of that famine following; for it shall be very grievous.',	'வரப்போகிற மகா கொடுமையான பஞ்சத்தால் தேசத்தில் முன்னிருந்த பரிபூரணமெல்லாம் ஒழிந்துபோம்.',	1,	41,	31),
(1228,	'And for that the dream was doubled unto Pharaoh twice; it is because the thing is established by God, and God will shortly bring it to pass.',	'இந்தக் காரியம் தேவனால் நிச்சயிக்கப்பட்டிருக்கிறது என்பதையும், தேவன் இதைச் சீக்கிரத்தில் செய்வார் என்பதையும் குறிக்கும்பொருட்டு, இந்தச் சொப்பனம் பார்வோனுக்கு இரட்டித்தது.',	1,	41,	32),
(1229,	'Now therefore let Pharaoh look out a man discreet and wise, and set him over the land of Egypt.',	'ஆகையால், விவேகமும் ஞானமுமுள்ள ஒரு மனுஷனைத் தேடி, அவனை எகிப்துதேசத்துக்கு அதிகாரியாகப் பார்வோன் ஏற்படுத்துவாராக.',	1,	41,	33),
(1230,	'Let Pharaoh do this, and let him appoint officers over the land, and take up the fifth part of the land of Egypt in the seven plenteous years.',	'இப்படிப் பார்வோன் செய்து, தேசத்தின்மேல் விசாரணைக்காரரை வைத்து, பரிபூரணமுள்ள ஏழு வருஷங்களில் எகிப்துதேசத்திலே விளையும் விளைச்சலில் ஐந்தில் ஒரு பங்கை வாங்கும்படி செய்வாராக.',	1,	41,	34),
(1231,	'And let them gather all the food of those good years that come, and lay up corn under the hand of Pharaoh, and let them keep food in the cities.',	'அவர்கள் வரப்போகிற நல்ல வருஷங்களில் விளையும் தானியங்களையெல்லாம் சேர்த்து, பட்டணங்களில் ஆகாரம் உண்டாயிருக்கும்படிக்கு, பார்வோனுடைய அதிகாரத்துக்குள்ளாகத் தானியங்களைப் பத்திரப்படுத்தி வைத்துவைப்பார்களாக.',	1,	41,	35),
(1232,	'And that food shall be for store to the land against the seven years of famine, which shall be in the land of Egypt; that the land perish not through the famine.',	'தேசம் பஞ்சத்தினால் அழிந்துபோகாதபடிக்கு, அந்தத் தானியம் இனி எகிப்துதேசத்தில் உண்டாகும் பஞ்சமுள்ள ஏழு வருஷங்களுக்காக தேசத்திற்கு ஒரு வைப்பாயிருப்பதாக என்றான்.',	1,	41,	36),
(1233,	'And the thing was good in the eyes of Pharaoh, and in the eyes of all his servants.',	'இந்த வார்த்தை பார்வோனுடைய பார்வைக்கும் அவன் ஊழியக்காரர் எல்லாருடைய பார்வைக்கும் நன்றாய்க் கண்டது.',	1,	41,	37),
(1234,	'And Pharaoh said unto his servants, Can we find such a one as this is, a man in whom the Spirit of God is?',	'அப்பொழுது பார்வோன் தன் ஊழியக்காரரை நோக்கி: தேவ ஆவியைப் பெற்ற இந்த மனுஷனைப்போல வேறொருவன் உண்டோ என்றான்.',	1,	41,	38),
(1235,	'And Pharaoh said unto Joseph, Forasmuch as God hath shewed thee all this, there is none so discreet and wise as thou art:',	'பின்பு, பார்வோன் யோசேப்பை நோக்கி: தேவன் இவையெல்லாவற்றையும் உனக்கு வெளிப்படுத்தியிருக்கிறபடியால், உன்னைப்போல விவேகமும் ஞானமுமுள்ளவன் வேறொருவனும் இல்லை.',	1,	41,	39),
(1236,	'Thou shalt be over my house, and according unto thy word shall all my people be ruled: only in the throne will I be greater than thou.',	'நீ என் அரமனைக்கு அதிகாரியாயிருப்பாய்; உன் வாக்கின்படியே என் ஜனங்கள் எல்லாரும் அடங்கி நடக்கக்கடவர்கள்; சிங்காசனத்தில் மாத்திரம் உன்னிலும் நான் பெரியவனாய் இருப்பேன் என்றான்.',	1,	41,	40),
(1237,	'And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt.',	'பின்னும் பார்வோன் யோசேப்பை நோக்கி: பார், எகிப்துதேசம் முழுமைக்கும் உன்னை அதிகாரியாக்கினேன் என்று சொல்லி,',	1,	41,	41),
(1238,	'And Pharaoh took off his ring from his hand, and put it upon Joseph\'s hand, and arrayed him in vestures of fine linen, and put a gold chain about his neck;',	'பார்வோன் தன் கையில் போட்டிருந்த தன் முத்திரை மோதிரத்தைக் கழற்றி, அதை யோசேப்பின் கையிலே போட்டு, மெல்லிய வஸ்திரங்களை அவனுக்கு உடுத்தி, பொன் சரப்பணியை அவன் கழுத்திலே தரித்து,',	1,	41,	42),
(1239,	'And he made him to ride in the second chariot which he had; and they cried before him, Bow the knee: and he made him ruler over all the land of Egypt.',	'தன்னுடைய இரண்டாம் இரதத்தின்மேல் அவனை ஏற்றி, தெண்டனிட்டுப் பணியுங்கள் என்று அவனுக்கு முன்பாகக் கூறுவித்து, எகிப்துதேசம் முழுமைக்கும் அவனை அதிகாரியாக்கினான்;',	1,	41,	43),
(1240,	'And Pharaoh said unto Joseph, I am Pharaoh, and without thee shall no man lift up his hand or foot in all the land of Egypt.',	'பின்னும் பார்வோன் யோசேப்பை நோக்கி: நான் பார்வோன்; ஆனாலும் எகிப்துதேசத்திலுள்ளவர்களில் ஒருவனும் உன் உத்தரவில்லாமல் தன் கையையாவது தன் காலையாவது அசைக்கக்கூடாது என்றான்.',	1,	41,	44),
(1241,	'And Pharaoh called Joseph\'s name Zaphnathpaaneah; and he gave him to wife Asenath the daughter of Potipherah priest of On. And Joseph went out over all the land of Egypt.',	'மேலும், பார்வோன் யோசேப்புக்கு சாப்நாத்பன்னேயா என்கிற பெயரையிட்டு; ஓன் பட்டணத்து ஆசாரியனாகிய போத்திபிராவின் குமாரத்தியாகிய ஆஸ்நாத்தை அவனுக்கு மனைவியாகக் கொடுத்தான். யோசேப்பு எகிப்துதேசத்தைச் சுற்றிப்பார்க்கும்படி புறப்பட்டான்.',	1,	41,	45),
(1242,	'And Joseph was thirty years old when he stood before Pharaoh king of Egypt. And Joseph went out from the presence of Pharaoh, and went throughout all the land of Egypt.',	'யோசேப்பு எகிப்தின் ராஜாவாகிய பார்வோனுக்கு முன்பாக நிற்கும்போது முப்பது வயதாயிருந்தான்; யோசேப்பு பார்வோனுடைய சந்நிதியிலிருந்து புறப்பட்டு, எகிப்துதேசம் எங்கும் போய்ச் சுற்றிப்பார்த்தான்.',	1,	41,	46),
(1243,	'And in the seven plenteous years the earth brought forth by handfuls.',	'பரிபூரணமுள்ள ஏழு வருஷங்களிலும் பூமி மிகுதியான பலனைக் கொடுத்தது.',	1,	41,	47),
(1244,	'And he gathered up all the food of the seven years, which were in the land of Egypt, and laid up the food in the cities: the food of the field, which was round about every city, laid he up in the same.',	'அவ்வேழு வருஷங்களில் எகிப்துதேசத்தில் விளைந்த தானியங்களையெல்லாம் அவன் சேர்த்து, அந்தத் தானியங்களைப் பட்டணங்களில் கட்டிவைத்தான்; அந்தந்தப் பட்டணத்தில் அதினதின் சுற்றுப்புறத்துத் தானியங்களைக் கட்டிவைத்தான்.',	1,	41,	48),
(1245,	'And Joseph gathered corn as the sand of the sea, very much, until he left numbering; for it was without number.',	'இப்படி யோசேப்பு அளவிறந்ததாய்க் கடற்கரை மணலைப்போல மிகுதியாக தானியத்தைச் சேர்த்துவைத்தான்; அது அளவுக்கு அடங்காததாயிருந்தது.',	1,	41,	49),
(1246,	'And unto Joseph were born two sons before the years of famine came, which Asenath the daughter of Potipherah priest of On bare unto him.',	'பஞ்சமுள்ள வருஷங்கள் வருவதற்கு முன்னே யோசேப்புக்கு இரண்டு குமாரர் பிறந்தார்கள்; அவர்களை ஓன் பட்டணத்து ஆசாரியனாகிய போத்திபிராவின் குமாரத்தியாகிய ஆஸ்நாத்து அவனுக்குப் பெற்றாள்.',	1,	41,	50),
(1247,	'And Joseph called the name of the firstborn Manasseh: For God, said he, hath made me forget all my toil, and all my father\'s house.',	'யோசேப்பு: என் வருத்தம் யாவையும் என் தகப்பனுடைய குடும்பம் அனைத்தையும் நான் மறக்கும்படி தேவன் பண்ணினார் என்று சொல்லி, மூத்தவனுக்கு மனாசே என்று பேரிட்டான்.',	1,	41,	51),
(1248,	'And the name of the second called he Ephraim: For God hath caused me to be fruitful in the land of my affliction.',	'நான் சிறுமைப்பட்டிருந்த தேசத்தில் தேவன் என்னைப் பலுகப்பண்ணினார் என்று சொல்லி, இளையவனுக்கு எப்பிராயீம் என்று பேரிட்டான்.',	1,	41,	52),
(1249,	'And the seven years of plenteousness, that was in the land of Egypt, were ended.',	'எகிப்துதேசத்தில் வந்த பரிபூரணமுள்ள ஏழு வருஷங்களும் முடிந்தபின்,',	1,	41,	53),
(1250,	'And the seven years of dearth began to come, according as Joseph had said: and the dearth was in all lands; but in all the land of Egypt there was bread.',	'யோசேப்பு சொல்லியபடி ஏழுவருஷ பஞ்சம் தொடங்கினது; சகலதேசங்களிலும் பஞ்சம் உண்டாயிற்று; ஆனாலும் எகிப்துதேசமெங்கும் ஆகாரம் இருந்தது.',	1,	41,	54),
(1251,	'And when all the land of Egypt was famished, the people cried to Pharaoh for bread: and Pharaoh said unto all the Egyptians, Go unto Joseph; what he saith to you, do.',	'எகிப்துதேசமெங்கும் பஞ்சம் உண்டானபோது, ஜனங்கள் உணவுக்காகப் பார்வோனை நோக்கி ஓலமிட்டார்கள்; அதற்குப் பார்வோன்: நீங்கள் யோசேப்பினிடத்துக்குப் போய், அவன் உங்களுக்குச் சொல்லுகிறபடி செய்யுங்கள் என்று எகிப்தியர் எல்லாருக்கும் சொன்னான்.',	1,	41,	55),
(1252,	'And the famine was over all the face of the earth: and Joseph opened all the storehouses, and sold unto the Egyptians; and the famine waxed sore in the land of Egypt.',	'தேசமெங்கும் பஞ்சம் உண்டானபடியால், யோசேப்பு களஞ்சியங்களையெல்லாம் திறந்து, எகிப்தியருக்கு விற்றான்; பஞ்சம் எகிப்துதேசத்தில் வரவரக்கொடிதாயிற்று.',	1,	41,	56),
(1253,	'And all countries came into Egypt to Joseph for to buy corn; because that the famine was so sore in all lands.',	'சகல தேசங்களிலும் பஞ்சம் கொடிதாயிருந்தபடியால், சகல தேசத்தார்களும் யோசேப்பினிடத்தில் தானியம் கொள்ளும்படி எகிப்துக்கு வந்தார்கள்.  ',	1,	41,	57),
(1254,	'Now when Jacob saw that there was corn in Egypt, Jacob said unto his sons, Why do ye look one upon another?',	'எகிப்திலே தானியம் உண்டென்று யாக்கோபு அறிந்து, தன் குமாரரை நோக்கி: நீங்கள் ஒருவர் முகத்தை ஒருவர் பார்த்துக்கொண்டிருக்கிறது என்ன?',	1,	42,	1),
(1255,	'And he said, Behold, I have heard that there is corn in Egypt: get you down thither, and buy for us from thence; that we may live, and not die.',	'எகிப்திலே தானியம் உண்டென்று கேள்விப்படுகிறேன்; நாம் சாகாமல் உயிரோடிருக்கும்படி நீங்கள் அவ்விடத்துக்குப் போய், நமக்காகத் தானியம் கொள்ளுங்கள் என்றான்.',	1,	42,	2),
(1256,	'And Joseph\'s ten brethren went down to buy corn in Egypt.',	'யோசேப்பின் சகோதரர் பத்துப்பேர் தானியங்கொள்ள எகிப்துக்குப் போனார்கள்.',	1,	42,	3),
(1257,	'But Benjamin, Joseph\'s brother, Jacob sent not with his brethren; for he said, Lest peradventure mischief befall him.',	'யோசேப்பின் தம்பியாகிய பென்யமீனுக்கு ஏதோ மோசம் வரும் என்று சொல்லி, யாக்கோபு அவனை அவன் சகோதரரோடே அனுப்பவில்லை.',	1,	42,	4),
(1258,	'And the sons of Israel came to buy corn among those that came: for the famine was in the land of Canaan.',	'கானான் தேசத்திலே பஞ்சம் உண்டாயிருந்தபடியால், தானியம் கொள்ளப்போகிறவர்களுடனேகூட இஸ்ரவேலின் குமாரரும் போனார்கள்.',	1,	42,	5),
(1259,	'And Joseph was the governor over the land, and he it was that sold to all the people of the land: and Joseph\'s brethren came, and bowed down themselves before him with their faces to the earth.',	'யோசேப்பு அத்தேசத்துக்கு அதிபதியாயிருந்து, தேசத்தின் ஜனங்கள் யாவருக்கும் விற்றான். யோசேப்பின் சகோதரர் வந்து, முகங்குப்புறத் தரையிலே விழுந்து அவனை வணங்கினார்கள்.',	1,	42,	6),
(1260,	'And Joseph saw his brethren, and he knew them, but made himself strange unto them, and spake roughly unto them; and he said unto them, Whence come ye? And they said, From the land of Canaan to buy food.',	'யோசேப்பு அவர்களைப் பார்த்து, தன் சகோதரர் என்று அறிந்துகொண்டான்; அறிந்தும் அறியாதவன்போலக் கடினமாய் அவர்களோடே பேசி: நீங்கள் எங்கேயிருந்து வந்தீர்கள் என்று கேட்டான்; அதற்கு அவர்கள்: கானான் தேசத்திலிருந்து தானியம் கொள்ளவந்தோம் என்றார்கள்.',	1,	42,	7),
(1261,	'And Joseph knew his brethren, but they knew not him.',	'யோசேப்பு அவர்களைத் தன் சகோதரர் என்று அறிந்தும், அவர்கள் அவனை அறியவில்லை.',	1,	42,	8),
(1262,	'And Joseph remembered the dreams which he dreamed of them, and said unto them, Ye are spies; to see the nakedness of the land ye are come.',	'யோசேப்பு அவர்களைக்குறித்துத் தான் கண்ட சொப்பனங்களை நினைத்து, அவர்களை நோக்கி: நீங்கள் வேவுகாரர், தேசம் எங்கே திறந்துகிடக்கிறது என்று பார்க்க வந்தீர்கள் என்றான்.',	1,	42,	9),
(1263,	'And they said unto him, Nay, my lord, but to buy food are thy servants come.',	'அதற்கு அவர்கள்: அப்படியல்ல, ஆண்டவனே, உமது அடியாராகிய நாங்கள் தானியம் கொள்ள வந்தோம்.',	1,	42,	10),
(1264,	'We are all one man\'s sons; we are true men, thy servants are no spies.',	'நாங்கள் எல்லாரும் ஒரு தகப்பனுடைய பிள்ளைகள்; நாங்கள் நிஜஸ்தர்; உமது அடியார் வேவுகாரர் அல்ல என்றார்கள்.',	1,	42,	11),
(1265,	'And he said unto them, Nay, but to see the nakedness of the land ye are come.',	'அதற்கு அவன்: அப்படியல்ல, தேசம் எங்கே திறந்துகிடக்கிறது என்று பார்க்கவே வந்தீர்கள் என்றான்.',	1,	42,	12),
(1266,	'And they said, Thy servants are twelve brethren, the sons of one man in the land of Canaan; and, behold, the youngest is this day with our father, and one is not.',	'அப்பொழுது அவர்கள்: உமது அடியாராகிய நாங்கள் பன்னிரண்டு சகோதரர்; கானான் தேசத்தில் இருக்கிற ஒரு தகப்பன் புத்திரர்; இளையவன் இப்பொழுது எங்கள் தகப்பனிடத்தில் இருக்கிறான்; ஒருவன் காணாமற்போனான் என்றார்கள்.',	1,	42,	13),
(1267,	'And Joseph said unto them, That is it that I spake unto you, saying, Ye are spies:',	'யோசேப்பு அவர்களை நோக்கி: உங்களை வேவுகாரர் என்று நான் சொன்னது சரி.',	1,	42,	14),
(1268,	'Hereby ye shall be proved: By the life of Pharaoh ye shall not go forth hence, except your youngest brother come hither.',	'உங்கள் இளைய சகோதரன் இங்கே வந்தாலொழிய நீங்கள் இங்கேயிருந்து புறப்படுவது இல்லை என்று பார்வோனின் ஜீவனைக்கொண்டு ஆணையிட்டுச் சொல்லுகிறேன்.',	1,	42,	15),
(1269,	'Send one of you, and let him fetch your brother, and ye shall be kept in prison, that your words may be proved, whether there be any truth in you: or else by the life of Pharaoh surely ye are spies.',	'இதினாலே நீங்கள் சோதிக்கப்படுவீர்கள்; உங்கள் சகோதரனை அழைத்து வரும்படி உங்களில் ஒருவனை அனுப்புங்கள்; உங்களிடத்தில் உண்மை உண்டோ இல்லையோ என்று உங்கள் வார்த்தைகள் சோதிக்கப்படுமளவும், நீங்கள் காவலில் இருக்கவேண்டும்; இல்லாவிட்டால், நீங்கள் வேவுகாரர்தான் என்று பார்வோனின் ஜீவனைக்கொண்டு ஆணையிட்டுச் சொல்லுகிறேன் என்று சொல்லி,',	1,	42,	16),
(1270,	'And he put them all together into ward three days.',	'அவர்கள் எல்லாரையும் மூன்றுநாள் காவலிலே வைத்தான்.',	1,	42,	17),
(1271,	'And Joseph said unto them the third day, This do, and live; for I fear God:',	'மூன்றாம் நாளிலே யோசேப்பு அவர்களை நோக்கி: நான் தேவனுக்குப் பயப்படுகிறவன்; நீங்கள் உயிரோடே இருக்கும்படிக்கு ஒன்று செய்யுங்கள்.',	1,	42,	18),
(1272,	'If ye be true men, let one of your brethren be bound in the house of your prison: go ye, carry corn for the famine of your houses:',	'நீங்கள் நிஜஸ்தரானால், சகோதரராகிய உங்களில் ஒருவன் காவற்கூடத்தில் கட்டுண்டிருக்கட்டும்; மற்றவர்கள் புறப்பட்டு, பஞ்சத்தினால் வருந்துகிற உங்கள் குடும்பத்துக்குத் தானியம் கொண்டுபோய்க் கொடுத்து,',	1,	42,	19),
(1273,	'But bring your youngest brother unto me; so shall your words be verified, and ye shall not die. And they did so.',	'உங்கள் இளைய சகோதரனை என்னிடத்துக்கு அழைத்துக்கொண்டுவாருங்கள்; அப்பொழுது உங்கள் வார்த்தைகள் மெய்யென்று விளங்கும்; நீங்கள் சாவதில்லை என்றான். அவர்கள் அப்படிச்செய்கிறதற்கு இசைந்து:',	1,	42,	20),
(1274,	'And they said one to another, We are verily guilty concerning our brother, in that we saw the anguish of his soul, when he besought us, and we would not hear; therefore is this distress come upon us.',	'நம்முடைய சகோதரனுக்கு நாம் செய்த துரோகம் நம்மேல் சுமந்தது; அவன் நம்மைக் கெஞ்சி வேண்டிக்கொண்டபோது, அவனுடைய மனவியாகுலத்தை நாம் கண்டும், அவனுக்குச் செவிகொடாமற்போனோமே; ஆகையால் இந்த ஆபத்து நமக்கு நேரிட்டது என்று ஒருவரை ஒருவர் பார்த்துச் சொல்லிக்கொண்டார்கள்.',	1,	42,	21),
(1275,	'And Reuben answered them, saying, Spake I not unto you, saying, Do not sin against the child; and ye would not hear? therefore, behold, also his blood is required.',	'அப்பொழுது ரூபன் அவர்களைப் பார்த்து: இளைஞனுக்கு விரோதமாகப் பாவஞ்செய்யாதிருங்கள் என்று நான் உங்களுக்குச் சொல்லவில்லையா? நீங்கள் கேளாமற்போனீர்கள்; இப்பொழுது, இதோ, அவன் இரத்தப்பழி நம்மிடத்தில் வாங்கப்படுகிறது என்றான்.',	1,	42,	22),
(1276,	'And they knew not that Joseph understood them; for he spake unto them by an interpreter.',	'யோசேப்பு துபாசியைக்கொண்டு அவர்களிடத்தில் பேசினபடியால், தாங்கள் சொன்னது அவனுக்குத் தெரியும் என்று அறியாதிருந்தார்கள்.',	1,	42,	23),
(1277,	'And he turned himself about from them, and wept; and returned to them again, and communed with them, and took from them Simeon, and bound him before their eyes.',	'அவன் அவர்களை விட்டு அப்புறம் போய் அழுது, திரும்ப அவர்களிடத்தில் வந்து, அவர்களோடே பேசி, அவர்களில் சிமியோனைப் பிடித்து, அவர்கள் கண்களுக்கு முன்பாகக் கட்டுவித்தான்.',	1,	42,	24),
(1278,	'Then Joseph commanded to fill their sacks with corn, and to restore every man\'s money into his sack, and to give them provision for the way: and thus did he unto them.',	'பின்பு, அவர்கள் சாக்குகளைத் தானியத்தால் நிரப்பவும், அவர்கள் பணத்தைத் திரும்ப அவனவன் சாக்கிலே போடவும், வழிக்கு வேண்டிய ஆகாரத்தைக் கொடுக்கவும் யோசேப்பு கட்டளையிட்டான்; அப்படியே அவர்களுக்குச் செய்யப்பட்டது.',	1,	42,	25),
(1279,	'And they laded their asses with the corn, and departed thence.',	'அவர்கள் அந்தத் தானியத்தைத் தங்கள் கழுதைகள்மேல் ஏற்றிக்கொண்டு, அவ்விடம்விட்டுப் புறப்பட்டுப்போனார்கள்.',	1,	42,	26),
(1280,	'And as one of them opened his sack to give his ass provender in the inn, he espied his money; for, behold, it was in his sack\'s mouth.',	'தங்குகிற இடத்திலே அவர்களில் ஒருவன் தன் கழுதைக்குத் தீவனம் போடத் தன் சாக்கைத் திறந்தபோது, சாக்கின் வாயிலே தன் பணம் இருக்கிறதைக் கண்டு,',	1,	42,	27),
(1281,	'And he said unto his brethren, My money is restored; and, lo, it is even in my sack: and their heart failed them, and they were afraid, saying one to another, What is this that God hath done unto us?',	'தன் சகோதரரைப் பார்த்து, என் பணம் திரும்ப வந்திருக்கிறது; இதோ, அது என் சாக்கிலே இருக்கிறது என்றான். அப்பொழுது அவர்களுடைய இருதயம் சோர்ந்துபோய், அவர்கள் பயந்து, ஒருவரை ஒருவர் பார்த்து, தேவன் நமக்கு இப்படிச் செய்தது என்ன என்றார்கள்.',	1,	42,	28),
(1282,	'And they came unto Jacob their father unto the land of Canaan, and told him all that befell unto them; saying,',	'அவர்கள் கானான் தேசத்திலுள்ள தங்கள் தகப்பனாகிய யாக்கோபினிடத்தில் வந்து, தங்களுக்குச் சம்பவித்தவைகளையெல்லாம் அவனுக்கு அறிவித்து:',	1,	42,	29),
(1283,	'The man, who is the lord of the land, spake roughly to us, and took us for spies of the country.',	'தேசத்துக்கு அதிபதியாயிருக்கிறவன் எங்களை தேசத்தை வேவுபார்க்க வந்தவர்கள் என்று எண்ணி எங்களோடே கடினமாய்ப் பேசினான்.',	1,	42,	30),
(1284,	'And we said unto him, We are true men; we are no spies:',	'நாங்களோ அவனை நோக்கி: நாங்கள் நிஜஸ்தர், வேவுகாரர் அல்ல.',	1,	42,	31),
(1285,	'We be twelve brethren, sons of our father; one is not, and the youngest is this day with our father in the land of Canaan.',	'நாங்கள் பன்னிரண்டு சகோதரர், ஒரு தகப்பன் புத்திரர், ஒருவன் காணாமற்போனான், இளையவன் இப்பொழுது கானான்தேசத்தில் எங்கள் தகப்பனிடத்தில் இருக்கிறான் என்றோம்.',	1,	42,	32),
(1286,	'And the man, the lord of the country, said unto us, Hereby shall I know that ye are true men; leave one of your brethren here with me, and take food for the famine of your households, and be gone:',	'அப்பொழுது தேசத்தின் அதிபதியானவன்: நீங்கள் நிஜஸ்தர் என்பதை நான் அறியும்படி உங்கள் சகோதரரில் ஒருவனை நீங்கள் என்னிடத்தில் விட்டு, பஞ்சத்தினால் வருந்துகிற உங்கள் குடும்பத்துக்குத் தானியம் வாங்கிக்கொண்டுபோய்க் கொடுத்து,',	1,	42,	33),
(1287,	'And bring your youngest brother unto me: then shall I know that ye are no spies, but that ye are true men: so will I deliver you your brother, and ye shall traffick in the land.',	'உங்கள் இளைய சகோதரனை என்னிடத்தில் அழைத்துக்கொண்டுவாருங்கள்; அதினாலே நீங்கள் வேவுகாரர் அல்ல, நிஜஸ்தர் என்பதை நான் அறிந்துகொண்டு, உங்கள் சகோதரனை விடுதலை செய்வேன்; நீங்கள் இந்தத் தேசத்திலே வியாபாரமும் பண்ணலாம் என்றான் என்று சொன்னார்கள்.',	1,	42,	34),
(1288,	'And it came to pass as they emptied their sacks, that, behold, every man\'s bundle of money was in his sack: and when both they and their father saw the bundles of money, they were afraid.',	'அவர்கள் தங்கள் சாக்குகளிலுள்ள தானியத்தைக் கொட்டுகையில், இதோ, அவனவன் சாக்கிலே அவனவன் பணமுடிப்பு இருந்தது; அந்தப் பணமுடிப்புகளை அவர்களும் அவர்கள் தகப்பனும் கண்டு பயந்தார்கள்.',	1,	42,	35),
(1289,	'And Jacob their father said unto them, Me have ye bereaved of my children: Joseph is not, and Simeon is not, and ye will take Benjamin away: all these things are against me.',	'அவர்கள் தகப்பனாகிய யாக்கோபு அவர்களை நோக்கி: என்னைப் பிள்ளையற்றவனாக்குகிறீர்கள்; யோசேப்பும் இல்லை, சிமியோனும் இல்லை; பென்யமீனையும் கொண்டுபோகப் பார்க்கிறீர்கள்; இதெல்லாம் எனக்கு விரோதமாய் நேரிடுகிறது என்றான்.',	1,	42,	36),
(1290,	'And Reuben spake unto his father, saying, Slay my two sons, if I bring him not to thee: deliver him into my hand, and I will bring him to thee again.',	'அப்பொழுது ரூபன் தன் தகப்பனைப் பார்த்து, அவனை என் கையில் ஒப்புவியும், நான் அவனைத் திரும்ப உம்மிடத்தில் கொண்டுவருவேன்; அவனைக் கொண்டுவராவிட்டால், என் இரண்டு குமாரரையும் கொன்றுபோடும் என்று சொன்னான்.',	1,	42,	37),
(1291,	'And he said, My son shall not go down with you; for his brother is dead, and he is left alone: if mischief befall him by the way in the which ye go, then shall ye bring down my gray hairs with sorrow to the grave.',	'அதற்கு அவன்: என் மகன் உங்களோடேகூடப் போவதில்லை; அவன் தமையன் இறந்துபோனான், இவன் ஒருவன் மீதியாயிருக்கிறான்; நீங்கள் போகும் வழியில் இவனுக்கு மோசம் நேரிட்டால், நீங்கள் என் நரைமயிரைச் சஞ்சலத்தோடே பாதாளத்தில் இறங்கப்பண்ணுவீர்கள் என்றான்.  ',	1,	42,	38),
(1292,	'And the famine was sore in the land.',	'தேசத்திலே பஞ்சம் கொடிதாயிருந்தது.',	1,	43,	1),
(1293,	'And it came to pass, when they had eaten up the corn which they had brought out of Egypt, their father said unto them, Go again, buy us a little food.',	'எகிப்திலிருந்து அவர்கள் கொண்டுவந்த தானியம் செலவழிந்தபோது, அவர்கள் தகப்பன் அவர்களை நோக்கி: நீங்கள் திரும்பப் போய், நமக்குக் கொஞ்சம் தானியம் வாங்கிக்கொண்டு வாருங்கள் என்றான்.',	1,	43,	2),
(1294,	'And Judah spake unto him, saying, The man did solemnly protest unto us, saying, Ye shall not see my face, except your brother be with you.',	'அதற்கு யூதா: உங்கள் சகோதரன் உங்களோடேகூட வராவிட்டால், நீங்கள் என் முகத்தைக் காண்பதில்லை என்று அந்த மனிதன் எங்களுக்குச் சத்தியமாய்ச் சொன்னான்.',	1,	43,	3),
(1295,	'If thou wilt send our brother with us, we will go down and buy thee food:',	'எங்கள் சகோதரனை நீர் எங்களோடேகூட அனுப்பினால், நாங்கள் போய், உமக்குத் தானியம் வாங்கிக்கொண்டு வருவோம்.',	1,	43,	4),
(1296,	'But if thou wilt not send him, we will not go down: for the man said unto us, Ye shall not see my face, except your brother be with you.',	'அனுப்பாவிட்டால். நாங்கள் போகமாட்டோம்; உங்கள் சகோதரன் உங்களோடேகூட வராவிட்டால், நீங்கள் என் முகத்தைக் காண்பதில்லை என்று அந்த மனிதன் எங்களோடே சொல்லியிருக்கிறான் என்றான்.',	1,	43,	5),
(1297,	'And Israel said, Wherefore dealt ye so ill with me, as to tell the man whether ye had yet a brother?',	'அதற்கு இஸ்ரவேல்: உங்களுக்கு இன்னும் ஒரு சகோதரன் உண்டென்று நீங்கள் அந்த மனிதனுக்குச் சொல்லி, ஏன் எனக்கு இந்தத் துன்பத்தை வருவித்தீர்கள் என்றான்.',	1,	43,	6),
(1298,	'And they said, The man asked us straitly of our state, and of our kindred, saying, Is your father yet alive? have ye another brother? and we told him according to the tenor of these words: could we certainly know that he would say, Bring your brother down?',	'அதற்கு அவர்கள்: அந்த மனிதன், உங்கள் தகப்பன் இன்னும் உயிரோடிருக்கிறாரா? உங்களுக்கு இன்னும் ஒரு சகோதரன் உண்டா? என்று எங்களையும் எங்கள் வம்சத்தையும் குறித்து விபரமாய் விசாரித்தான்; அந்தக் கேள்விகளுக்குத் தக்கதாக உள்ளபடி அவனுக்குச் சொன்னோம்; உங்கள் சகோதரனை உங்களோடேகூட இங்கே கொண்டுவாருங்கள் என்று அவன் சொல்லுவான் என்பதை நாங்கள் அறிந்திருந்தோமா என்றார்கள்.',	1,	43,	7),
(1299,	'And Judah said unto Israel his father, Send the lad with me, and we will arise and go; that we may live, and not die, both we, and thou, and also our little ones.',	'பின்னும், யூதா தன் தகப்பனாகிய இஸ்ரவேலை நோக்கி: நீரும் நாங்களும் எங்கள் குழந்தைகளும் சாகாமல் உயிரோடிருக்கும்படி, நாங்கள் புறப்பட்டுப்போகிறோம், பிள்ளையாண்டானை என்னோடே அனுப்பும்.',	1,	43,	8),
(1300,	'I will be surety for him; of my hand shalt thou require him: if I bring him not unto thee, and set him before thee, then let me bear the blame for ever:',	'அவனுக்காக நான் உத்தரவாதம்பண்ணுவேன்; அவனை என்னிடத்திலே கேளும், நான் அவனை உம்மிடத்தில் கொண்டுவந்து, உமக்கு முன்பாக நிறுத்தாமற்போனால், எந்நாளும் அந்தக் குற்றம் என்மேல் இருப்பதாக.',	1,	43,	9),
(1301,	'For except we had lingered, surely now we had returned this second time.',	'நாங்கள் தாமதியாதிருந்தோமானால், இதற்குள்ளே இரண்டாந்தரம் போய்த் திரும்பி வந்திருப்போமே என்றான்.',	1,	43,	10),
(1302,	'And their father Israel said unto them, If it must be so now, do this; take of the best fruits in the land in your vessels, and carry down the man a present, a little balm, and a little honey, spices, and myrrh, nuts, and almonds:',	'அதற்கு அவர்கள் தகப்பனாகிய இஸ்ரவேல்: அப்படியானால், ஒன்று செய்யுங்கள்; இந்த தேசத்தின் உச்சிதமான வஸ்துக்களில் கொஞ்சம் பிசின் தைலமும், கொஞ்சம் தேனும், கந்தவர்க்கங்களும், வெள்ளைப்போளமும், தெரபிந்து கொட்டைகளும், வாதுமைக்கொட்டைகளும் உங்கள் சாக்குகளில் போட்டு, அந்த மனிதனுக்குக் காணிக்கையாகக் கொண்டுபோய்க் கொடுங்கள்.',	1,	43,	11),
(1303,	'And take double money in your hand; and the money that was brought again in the mouth of your sacks, carry it again in your hand; peradventure it was an oversight:',	'பணத்தை இரட்டிப்பாய் உங்கள் கைகளில் கொண்டுபோங்கள், சாக்குகளின் வாயிலே திரும்பக் கொண்டுவந்த பணத்தையும் கொண்டுபோங்கள்; அது கைப்பிசகாய் வந்திருக்கும்.',	1,	43,	12),
(1304,	'Take also your brother, and arise, go again unto the man:',	'உங்கள் சகோதரனையும் கூட்டிக்கொண்டு, அந்த மனிதனிடத்துக்கு மறுபடியும் போங்கள்.',	1,	43,	13),
(1305,	'And God Almighty give you mercy before the man, that he may send away your other brother, and Benjamin. If I be bereaved of my children, I am bereaved.',	'அந்த மனிதன், அங்கிருக்கிற உங்கள் மற்ற சகோதரனையும் பென்யமீனையும் உங்களுடனே அனுப்பிவிடும்படிக்கு, சர்வவல்லமையுள்ள தேவன் அவன் சமுகத்தில் உங்களுக்கு இரக்கங்கிடைக்கப்பண்ணுவாராக; நானோ பிள்ளையற்றுப் போனவனைப்போல் இருப்பேன் என்றான்.',	1,	43,	14),
(1306,	'And the men took that present, and they took double money in their hand and Benjamin; and rose up, and went down to Egypt, and stood before Joseph.',	'அப்பொழுது அவர்கள் காணிக்கையையும் தங்கள் கைகளில் இரட்டிப்பான பணத்தையும் எடுத்துக்கொண்டு, பென்யமீனையும் கூட்டிக்கொண்டு, பிரயாணப்பட்டு, எகிப்துக்குப்போய், யோசேப்பின் சமுகத்தில் வந்து நின்றார்கள்.',	1,	43,	15),
(1307,	'And when Joseph saw Benjamin with them, he said to the ruler of his house, Bring these men home, and slay, and make ready; for these men shall dine with me at noon.',	'பென்யமீன் அவர்களோடேகூட வந்திருக்கிறதை யோசேப்பு கண்டு, தன் வீட்டு விசாரணைக்காரனை நோக்கி: நீ இந்த மனிதரை வீட்டுக்கு அழைத்துப்போய், சாப்பாட்டுக்கு வேண்டியவைகளை அடித்து, ஆயத்தம்பண்ணு, மத்தியானத்திலே இந்த மனிதர் என்னோடே சாப்பிடுவார்கள் என்றான்.',	1,	43,	16),
(1308,	'And the man did as Joseph bade; and the man brought the men into Joseph\'s house.',	'அவன் தனக்கு யோசேப்பு சொன்னபடியே செய்து, அந்த மனிதரை யோசேப்பின் வீட்டுக்கு அழைத்துக்கொண்டு போனான்.',	1,	43,	17),
(1309,	'And the men were afraid, because they were brought into Joseph\'s house; and they said, Because of the money that was returned in our sacks at the first time are we brought in; that he may seek occasion against us, and fall upon us, and take us for bondmen, and our asses.',	'தாங்கள் யோசேப்பின் வீட்டுக்குக் கொண்டுபோகப்படுகிறதை அவர்கள் கண்டு பயந்து, முன்னே நம்முடைய சாக்குகளில் இருந்த பணத்தினிமித்தம் நம்மேல் குற்றம் சுமத்தி, நம்மைப் பிடித்துச் சிறைகளாக்கி, நம்முடைய கழுதைகளை எடுத்துக்கொள்ளும்படி நம்மைக்கொண்டுபோகிறார்கள் என்று சொல்லி,',	1,	43,	18),
(1310,	'And they came near to the steward of Joseph\'s house, and they communed with him at the door of the house,',	'யோசேப்பின் வீட்டு விசாரணைக்காரனண்டையிலே சேர்ந்து, வீட்டு வாசற்படியிலே அவனோடே பேசி:',	1,	43,	19),
(1311,	'And said, O sir, we came indeed down at the first time to buy food:',	'ஆண்டவனே, நாங்கள் தானியம் கொள்ளும்படி முன்னே வந்துபோனோமே;',	1,	43,	20),
(1312,	'And it came to pass, when we came to the inn, that we opened our sacks, and, behold, every man\'s money was in the mouth of his sack, our money in full weight: and we have brought it again in our hand.',	'நாங்கள் தங்கும் இடத்தில் போய் எங்கள் சாக்குகளைத் திறந்தபோது, நாங்கள் நிறுத்துக்கொடுத்த நிறையின்படியே அவனவன் பணம் அவனவன் சாக்கின் வாயிலே இருக்கக் கண்டோம்; அதை நாங்கள் திரும்பவும் எங்கள் கையிலே கொண்டுவந்திருக்கிறோம்.',	1,	43,	21),
(1313,	'And other money have we brought down in our hands to buy food: we cannot tell who put our money in our sacks.',	'மேலும், தானியம் கொள்ளும்படி வேறே பணமும் எங்கள் கையில் கொண்டு வந்திருக்கிறோம்; நாங்கள் முன் கொடுத்த பணத்தை எங்கள் சாக்குகளில் போட்டது இன்னார் என்று அறியோம் என்றார்கள்.',	1,	43,	22),
(1314,	'And he said, Peace be to you, fear not: your God, and the God of your father, hath given you treasure in your sacks: I had your money. And he brought Simeon out unto them.',	'அதற்கு அவன்: உங்களுக்குச் சமாதானம்; பயப்படவேண்டாம்; உங்கள் தேவனும் உங்கள் தகப்பனுடைய தேவனுமாயிருக்கிறவர் உங்கள் சாக்குகளில் அதை உங்களுக்குப் புதையலாகக் கட்டளையிட்டார்; நீங்கள் கொடுத்த பணம் என்னிடத்தில் வந்து சேர்ந்தது என்று சொல்லி, சிமியோனை வெளியே அழைத்து வந்து, அவர்களிடத்தில் விட்டான்.',	1,	43,	23),
(1315,	'And the man brought the men into Joseph\'s house, and gave them water, and they washed their feet; and he gave their asses provender.',	'மேலும், அந்த மனிதன் அவர்களை யோசேப்பின் வீட்டுக்குள்ளே கூட்டிக்கொண்டுபோய், அவர்கள் தங்கள் கால்களைக் கழுவும்படி தண்ணீர் கொடுத்து, அவர்களுடைய கழுதைகளுக்குத் தீவனம் போட்டான்.',	1,	43,	24),
(1316,	'And they made ready the present against Joseph came at noon: for they heard that they should eat bread there.',	'தாங்கள் அங்கே போஜனம் செய்யப்போகிறதை அவர்கள் கேள்விப்பட்டபடியால், மத்தியானத்தில் யோசேப்பு வருமளவும் காணிக்கையை ஆயத்தமாய் வைத்துக் காத்துக்கொண்டிருந்தார்கள்.',	1,	43,	25),
(1317,	'And when Joseph came home, they brought him the present which was in their hand into the house, and bowed themselves to him to the earth.',	'யோசேப்பு வீட்டுக்கு வந்தபோது, அவர்கள் தங்கள் கையில் இருந்த காணிக்கையை வீட்டுக்குள் அவனிடத்தில் கொண்டுபோய் வைத்து, தரைமட்டும் குனிந்து, அவனை வணங்கினார்கள்.',	1,	43,	26),
(1318,	'And he asked them of their welfare, and said, Is your father well, the old man of whom ye spake? Is he yet alive?',	'அப்பொழுது அவன்: அவர்கள் சுகசெய்தியை விசாரித்து, நீங்கள் சொன்ன முதிர்வயதான உங்கள் தகப்பன் சுகமாயிருக்கிறாரா? அவர் இன்னும் உயிரோடிருக்கிறாரா? என்று அவர்களிடத்தில் விசாரித்தான்.',	1,	43,	27),
(1319,	'And they answered, Thy servant our father is in good health, he is yet alive. And they bowed down their heads, and made obeisance.',	'அதற்கு அவர்கள்: எங்கள் தகப்பனாராகிய உமது அடியான் சுகமாயிருக்கிறார், இன்னும் உயிரோடிருக்கிறார் என்று சொல்லி, குனிந்து வணங்கினார்கள்.',	1,	43,	28),
(1320,	'And he lifted up his eyes, and saw his brother Benjamin, his mother\'s son, and said, Is this your younger brother, of whom ye spake unto me? And he said, God be gracious unto thee, my son.',	'அவன் தன் கண்களை ஏறெடுத்து, தன் தாய் பெற்ற குமாரனாகிய தன் சகோதரன் பென்யமீனைக் கண்டு, நீங்கள் எனக்குச் சொன்ன உங்கள் இளைய சகோதரன் இவன்தானா என்று கேட்டு, மகனே, தேவன் உனக்குக் கிருபைசெய்யக்கடவர் என்றான்.',	1,	43,	29),
(1321,	'And Joseph made haste; for his bowels did yearn upon his brother: and he sought where to weep; and he entered into his chamber, and wept there.',	'யோசேப்பின் உள்ளம் தன் சகோதரனுக்காகப் பொங்கினபடியால், அவன் அழுகிறதற்கு இடம் தேடி, துரிதமாய் அறைக்குள்ளே போய், அங்கே அழுதான்.',	1,	43,	30),
(1322,	'And he washed his face, and went out, and refrained himself, and said, Set on bread.',	'பின்பு, அவன் தன் முகத்தைக் கழுவி வெளியே வந்து, தன்னை அடக்கிக்கொண்டு, போஜனம் வையுங்கள் என்றான்.',	1,	43,	31),
(1323,	'And they set on for him by himself, and for them by themselves, and for the Egyptians, which did eat with him, by themselves: because the Egyptians might not eat bread with the Hebrews; for that is an abomination unto the Egyptians.',	'எகிப்தியர் எபிரெயரோடே சாப்பிடமாட்டார்கள்; அப்படிச் செய்வது எகிப்தியருக்கு அருவருப்பாயிருக்கும்; ஆகையால், அவனுக்குத் தனிப்படவும், அவர்களுக்குத் தனிப்படவும், அவனோடே சாப்பிடுகிற எகிப்தியருக்குத் தனிப்படவும் வைத்தார்கள்.',	1,	43,	32),
(1324,	'And they sat before him, the firstborn according to his birthright, and the youngest according to his youth: and the men marvelled one at another.',	'அவனுக்கு முன்பாக, மூத்தவன் முதல் இளையவன்வரைக்கும் அவனவன் வயதின்படியே அவர்களை உட்காரவைத்தார்கள்; அதற்காக அவர்கள், ஒருவரை ஒருவர் பார்த்து ஆச்சரியப்பட்டார்கள்.',	1,	43,	33),
(1325,	'And he took and sent messes unto them from before him: but Benjamin\'s mess was five times so much as any of their\'s. And they drank, and were merry with him.',	'அவன் தனக்குமுன் வைக்கப்பட்டிருந்த போஜனத்தில் அவர்களுக்குப் பங்கிட்டு அனுப்பினான்; அவர்கள் எல்லாருடைய பங்குகளைப்பார்க்கிலும் பென்யமீனுடைய பங்கு ஐந்துமடங்கு அதிகமாயிருந்தது; அவர்கள் பானம்பண்ணி, அவனுடனே சந்தோஷமாயிருந்தார்கள்.  ',	1,	43,	34),
(1326,	'And he commanded the steward of his house, saying, Fill the men\'s sacks with food, as much as they can carry, and put every man\'s money in his sack\'s mouth.',	'பின்பு, அவன் தன் வீட்டு விசாரணைக்காரனை நோக்கி: நீ இந்த மனிதருடைய சாக்குகளை அவர்கள் ஏற்றிக்கொண்டுபோகத்தக்க பாரமாய்த் தானியத்தினாலே நிரப்பி, அவனவன் பணத்தை அவனவன் சாக்கின் வாயிலே போட்டு,',	1,	44,	1),
(1327,	'And put my cup, the silver cup, in the sack\'s mouth of the youngest, and his corn money. And he did according to the word that Joseph had spoken.',	'இளையவனுடைய சாக்கின் வாயிலே வெள்ளிப்பாத்திரமாகிய என் பானபாத்திரத்தையும் தானியத்துக்கு அவன் கொடுத்த பணத்தையும் போடு என்று கட்டளையிட்டான்; யோசேப்பு சொன்னபடியே அவன் செய்தான்.',	1,	44,	2),
(1328,	'As soon as the morning was light, the men were sent away, they and their asses.',	'அதிகாலையிலே அந்த மனிதர்கள் தங்கள் கழுதைகளை ஓட்டிக்கொண்டுபோகும்படி அனுப்பிவிடப்பட்டார்கள்.',	1,	44,	3),
(1329,	'And when they were gone out of the city, and not yet far off, Joseph said unto his steward, Up, follow after the men; and when thou dost overtake them, say unto them, Wherefore have ye rewarded evil for good?',	'அவர்கள் பட்டணத்தை விட்டுப்புறப்பட்டு, வெகுதூரம் போவதற்கு முன்னே, யோசேப்பு தன் வீட்டு விசாரணைக்காரனை நோக்கி: நீ புறப்பட்டுப்போய், அந்த மனிதரைப் பின்தொடர்ந்து, அவர்களைப் பிடித்து: நீங்கள் நன்மைக்குத் தீமை செய்தது என்ன?',	1,	44,	4),
(1330,	'Is not this it in which my lord drinketh, and whereby indeed he divineth? ye have done evil in so doing.',	'அது என் எஜமான் பானம்பண்ணுகிற பாத்திரம் அல்லவா? அது போனவகை ஞானதிருஷ்டியால் அவருக்குத் தெரியாதா? நீங்கள் செய்தது தகாதகாரியம் என்று அவர்களோடே சொல் என்றான்.',	1,	44,	5),
(1331,	'And he overtook them, and he spake unto them these same words.',	'அவன் அவர்களைத் தொடர்ந்து பிடித்து, தன்னிடத்தில் சொல்லியிருந்த வார்த்தைகளை அவர்களுக்குச் சொன்னான்.',	1,	44,	6),
(1332,	'And they said unto him, Wherefore saith my lord these words? God forbid that thy servants should do according to this thing:',	'அதற்கு அவர்கள்: எங்கள் ஆண்டவன் இப்படிப்பட்ட வார்த்தைகளைச் சொல்லுகிறது என்ன? இப்படிப்பட்ட காரியத்துக்கும் உம்முடைய அடியாராகிய எங்களுக்கும் வெகுதூரம்.',	1,	44,	7),
(1333,	'Behold, the money, which we found in our sacks\' mouths, we brought again unto thee out of the land of Canaan: how then should we steal out of thy lord\'s house silver or gold?',	'எங்கள் சாக்குகளின் வாயிலே நாங்கள் கண்ட பணத்தைக் கானான்தேசத்திலிருந்து திரும்ப உம்மிடத்துக்குக் கொண்டுவந்தோமே; நாங்கள் உம்முடைய எஜமானின் வீட்டிலிருந்து வெள்ளியையாகிலும், பொன்னையாகிலும் திருடிக்கொண்டு போவோமா?',	1,	44,	8),
(1334,	'With whomsoever of thy servants it be found, both let him die, and we also will be my lord\'s bondmen.',	'உம்முடைய அடியாருக்குள்ளே அது எவனிடத்தில் காணப்படுமோ அவன் கொலையுண்ணக்கடவன்; நாங்களும் எங்கள் ஆண்டவனுக்கு அடிமைகளாவோம் என்றார்கள்.',	1,	44,	9),
(1335,	'And he said, Now also let it be according unto your words: he with whom it is found shall be my servant; and ye shall be blameless.',	'அதற்கு அவன்: நீங்கள் சொன்னபடியே ஆகட்டும்; எவனிடத்தில் அது காணப்படுமோ, அவன் எனக்கு அடிமையாவான்; நீங்கள் குற்றமற்றிருப்பீர்கள் என்றான்.',	1,	44,	10),
(1336,	'Then they speedily took down every man his sack to the ground, and opened every man his sack.',	'அப்பொழுது அவர்கள் துரிதமாய் அவனவன் தன்தன் சாக்கைத் தரையிலே இறக்கி, தங்கள் சாக்குகளைத் திறந்து வைத்தார்கள்.',	1,	44,	11),
(1337,	'And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin\'s sack.',	'மூத்தவன் சாக்குமுதல் இளையவன் சாக்குமட்டும் அவன் சோதிக்கும்போது, அந்தப் பாத்திரம் பென்யமீனுடைய சாக்கிலே கண்டுபிடிக்கப்பட்டது.',	1,	44,	12),
(1338,	'Then they rent their clothes, and laded every man his ass, and returned to the city.',	'அப்பொழுது அவர்கள் தங்கள் வஸ்திரங்களைக் கிழித்துக்கொண்டு, அவனவன் கழுதையின்மேல் பொதியை ஏற்றிக்கொண்டு, பட்டணத்திற்குத் திரும்பினார்கள்.',	1,	44,	13),
(1339,	'And Judah and his brethren came to Joseph\'s house; for he was yet there: and they fell before him on the ground.',	'யூதாவும் அவன் சகோதரரும் யோசேப்பின் வீட்டுக்குப் போனார்கள். யோசேப்பு அதுவரையும் அங்கே இருந்தான்; அவனுக்கு முன்பாகத் தரையிலே விழுந்தார்கள்.',	1,	44,	14),
(1340,	'And Joseph said unto them, What deed is this that ye have done? wot ye not that such a man as I can certainly divine?',	'யோசேப்பு அவர்களை நோக்கி: நீங்கள் என்ன காரியம் செய்தீர்கள்? என்னைப் போலொத்த மனிதனுக்கு ஞானதிருஷ்டியினால் காரியம் தெரியவரும் என்று அறியாமற்போனீர்களா என்றான்.',	1,	44,	15),
(1341,	'And Judah said, What shall we say unto my lord? what shall we speak? or how shall we clear ourselves? God hath found out the iniquity of thy servants: behold, we are my lord\'s servants, both we, and he also with whom the cup is found.',	'அதற்கு யூதா: என் ஆண்டவனாகிய உம்மிடத்தில் நாங்கள் என்ன சொல்லுவோம்? என்னத்தைப் பேசுவோம்? எதினாலே எங்கள் நீதியை விளங்கப்பண்ணுவோம்? உம்முடைய அடியாரின் அக்கிரமத்தை தேவன் விளங்கப்பண்ணினார்; பாத்திரத்தை வைத்திருக்கிறவனும் நாங்களும் என் ஆண்டவனுக்கு அடிமைகள் என்றான்.',	1,	44,	16),
(1342,	'And he said, God forbid that I should do so: but the man in whose hand the cup is found, he shall be my servant; and as for you, get you up in peace unto your father.',	'அதற்கு அவன்: அப்படிப்பட்ட செய்கை எனக்குத் தூரமாயிருப்பதாக; எவன் வசத்தில் பாத்திரம் கண்டுபிடிக்கப்பட்டதோ, அவனே எனக்கு அடிமையாயிருப்பான்; நீங்களோ சமாதானத்தோடே உங்கள் தகப்பனிடத்துக்குப் போங்கள் என்றான்.',	1,	44,	17),
(1343,	'Then Judah came near unto him, and said, Oh my lord, let thy servant, I pray thee, speak a word in my lord\'s ears, and let not thine anger burn against thy servant: for thou art even as Pharaoh.',	'அப்பொழுது யூதா அவனண்டையிலே சேர்ந்து: ஆ, என் ஆண்டவனே, உமது அடியேன் உம்முடைய செவிகள் கேட்க ஒரு வார்த்தை சொல்லுகிறேன் கேட்பீராக; அடியேன்மேல் உமது கோபம் மூளாதிருப்பதாக; நீர் பார்வோனுக்கு ஒப்பாயிருக்கிறீர்.',	1,	44,	18),
(1344,	'My lord asked his servants, saying, Have ye a father, or a brother?',	'உங்களுக்குத் தகப்பனாவது சகோதரனாவது உண்டா என்று என் ஆண்டவன் உம்முடைய அடியாரிடத்தில் கேட்டீர்.',	1,	44,	19),
(1345,	'And we said unto my lord, We have a father, an old man, and a child of his old age, a little one; and his brother is dead, and he alone is left of his mother, and his father loveth him.',	'அதற்கு நாங்கள்: எங்களுக்கு முதிர்வயதுள்ள தகப்பனாரும், அவருக்கு முதிர்வயதிலே பிறந்த ஒரு இளைஞனும் உண்டு என்றும், அவனுடைய தமையன் இறந்துபோனான் என்றும், அவன் ஒருவன்மாத்திரமே அவனைப்பெற்ற தாயாருக்கு இருப்பதினால் தகப்பனார் அவன்மேல் பட்சமாயிருக்கிறார் என்றும் என் ஆண்டவனுக்குச் சொன்னோம்.',	1,	44,	20),
(1346,	'And thou saidst unto thy servants, Bring him down unto me, that I may set mine eyes upon him.',	'அப்பொழுது நீர்: அவனை என்னிடத்துக்குக் கொண்டுவாருங்கள்; என் கண்களினால் அவனைப் பார்க்கவேண்டும் என்று உமது அடியாருக்குச் சொன்னீர்.',	1,	44,	21),
(1347,	'And we said unto my lord, The lad cannot leave his father: for if he should leave his father, his father would die.',	'நாங்கள் ஆண்டவனை நோக்கி: அந்த இளைஞன் தன் தகப்பனைவிட்டுப் பிரியக்கூடாது, பிரிந்தால் அவர் இறந்துபோவார் என்று சொன்னோம்.',	1,	44,	22),
(1348,	'And thou saidst unto thy servants, Except your youngest brother come down with you, ye shall see my face no more.',	'அதற்கு நீர்: உங்கள் இளைய சகோதரனைக் கொண்டுவராவிட்டால், நீங்கள் இனி என் முகத்தைக் காண்பதில்லை என்று உமது அடியாருக்குச் சொன்னீர்.',	1,	44,	23),
(1349,	'And it came to pass when we came up unto thy servant my father, we told him the words of my lord.',	'நாங்கள் உமது அடியானாகிய என் தகப்பனாரிடத்துக்குப் போனபோது, என் ஆண்டவனுடைய வார்த்தைகளை அவருக்கு அறிவித்தோம்.',	1,	44,	24),
(1350,	'And our father said, Go again, and buy us a little food.',	'எங்கள் தகப்பனார் எங்களை நோக்கி: நீங்கள் திரும்பப்போய், நமக்குக் கொஞ்சம் தானியம் கொள்ளுங்கள் என்று சொன்னார்.',	1,	44,	25),
(1351,	'And we said, We cannot go down: if our youngest brother be with us, then will we go down: for we may not see the man\'s face, except our youngest brother be with us.',	'அதற்கு: நாங்கள் போகக்கூடாது; எங்கள் இளைய சகோதரன் எங்களோடே வந்தால் போவோம்; எங்கள் இளைய சகோதரன் எங்களோடே வராவிட்டால், நாங்கள் அந்தப் புருஷனுடைய முகத்தைக்காணக்கூடாது என்றோம்.',	1,	44,	26),
(1352,	'And thy servant my father said unto us, Ye know that my wife bare me two sons:',	'அப்பொழுது உம்முடைய அடியானாகிய என் தகப்பனார்: என் மனைவி எனக்கு இரண்டு பிள்ளைகளைப் பெற்றாள்;',	1,	44,	27),
(1353,	'And the one went out from me, and I said, Surely he is torn in pieces; and I saw him not since:',	'அவர்களில் ஒருவன் என்னிடத்திலிருந்து போய்விட்டான், அவன் பீறுண்டுபோயிருப்பான் என்றிருந்தேன், இதுவரைக்கும் அவனைக் காணாதிருக்கிறேன், இதெல்லாம் நீங்கள் அறிந்திருக்கிறீர்கள்.',	1,	44,	28),
(1354,	'And if ye take this also from me, and mischief befall him, ye shall bring down my gray hairs with sorrow to the grave.',	'நீங்கள் இவனையும் என்னை விட்டுப்பிரித்து அழைத்துப்போகுமிடத்தில் இவனுக்கு மோசம் நேரிட்டால், என் நரைமயிரை வியாகுலத்தோடே பாதாளத்தில் இறங்கப்பண்ணுவீர்கள் என்றார்.',	1,	44,	29),
(1355,	'Now therefore when I come to thy servant my father, and the lad be not with us; seeing that his life is bound up in the lad\'s life;',	'ஆகையால் இளையவனை விட்டு, நான் என் தகப்பனாகிய உமது அடியானிடத்துக்குப் போனால், அவருடைய ஜீவன் இவனுடைய ஜீவனோடே ஒன்றாய் இணைக்கப்பட்டிருக்கிறபடியினால்,',	1,	44,	30),
(1356,	'It shall come to pass, when he seeth that the lad is not with us, that he will die: and thy servants shall bring down the gray hairs of thy servant our father with sorrow to the grave.',	'அவர் இளையவன் வரவில்லை என்று அறிந்தமாத்திரத்தில் இறந்துபோவார்; இப்படி உமது அடியாராகிய நாங்கள் உமது அடியானாகிய எங்கள் தகப்பனுடைய நரைமயிரை வியாகுலத்துடனே பாதாளத்தில் இறங்கப்பண்ணுவோம்.',	1,	44,	31),
(1357,	'For thy servant became surety for the lad unto my father, saying, If I bring him not unto thee, then I shall bear the blame to my father for ever.',	'இந்த இளையவனுக்காக உமது அடியானாகிய நான் என் தகப்பனுக்கு உத்தரவாதி; அன்றியும், நான் இவனை உம்மிடத்துக்குக் கொண்டுவராவிட்டால், நான் எந்நாளும் உமக்கு முன்பாகக் குற்றவாளியாயிருப்பேன் என்று அவருக்குச் சொல்லியிருக்கிறேன்.',	1,	44,	32),
(1358,	'Now therefore, I pray thee, let thy servant abide instead of the lad a bondman to my lord; and let the lad go up with his brethren.',	'இப்படியிருக்க, இளையவன் தன் சகோதரரோடேகூடப் போகவிடும்படி மன்றாடுகிறேன்; உம்முடைய அடியானாகிய நான் இளையவனுக்குப் பதிலாக இங்கே என் ஆண்டவனுக்கு அடிமையாயிருக்கிறேன்.',	1,	44,	33),
(1359,	'For how shall I go up to my father, and the lad be not with me? lest peradventure I see the evil that shall come on my father.',	'இளையவனை விட்டு, எப்படி என் தகப்பனிடத்துக்குப் போவேன்? போனால் என் தகப்பனுக்கு நேரிடும் தீங்கை நான் எப்படிக் காண்பேன் என்றான்.  ',	1,	44,	34),
(1360,	'Then Joseph could not refrain himself before all them that stood by him; and he cried, Cause every man to go out from me. And there stood no man with him, while Joseph made himself known unto his brethren.',	'அப்பொழுது யோசேப்பு தன் அருகே நின்ற எல்லாருக்கும் முன்பாகத் தன்னை அடக்கிக்கொண்டிருக்கக்கூடாமல்: யாவரையும் என்னைவிட்டு வெளியே போகப்பண்ணுங்கள் என்று கட்டளையிட்டான். யோசேப்பு தன் சகோதரருக்குத் தன்னை வெளிப்படுத்துகையில், ஒருவரும் அவன் அருகில் நிற்கவில்லை.',	1,	45,	1),
(1361,	'And he wept aloud: and the Egyptians and the house of Pharaoh heard.',	'அவன் சத்தமிட்டு அழுதான்; அதை எகிப்தியர் கேட்டார்கள், பார்வோனின் வீட்டாரும் கேட்டார்கள்.',	1,	45,	2),
(1362,	'And Joseph said unto his brethren, I am Joseph; doth my father yet live? And his brethren could not answer him; for they were troubled at his presence.',	'யோசேப்பு தன் சகோதரரைப்பார்த்து: நான் யோசேப்பு; என் தகப்பனார் இன்னும் உயிரோடே இருக்கிறாரா என்றான். அவனுடைய சகோதரர் அவனுக்கு முன்பாகக் கலக்கமுற்றிருந்ததினாலே, அவனுக்கு உத்தரம் சொல்லக்கூடாமல் இருந்தார்கள்.',	1,	45,	3),
(1363,	'And Joseph said unto his brethren, Come near to me, I pray you. And they came near. And he said, I am Joseph your brother, whom ye sold into Egypt.',	'அப்பொழுது யோசேப்பு தன் சகோதரரை நோக்கி: என் கிட்ட வாருங்கள் என்றான். அவர்கள் கிட்டப்போனார்கள்; அப்பொழுது அவன்: நீங்கள் எகிப்துக்குப் போகிறவர்களிடத்தில் விற்றுப்போட்ட உங்கள் சகோதரனாகிய யோசேப்பு நான்தான்.',	1,	45,	4),
(1364,	'Now therefore be not grieved, nor angry with yourselves, that ye sold me hither: for God did send me before you to preserve life.',	'என்னை இவ்விடத்தில் வரும்படி விற்றுப்போட்டதினால், நீங்கள் சஞ்சலப்படவேண்டாம்; அது உங்களுக்கு விசனமாயிருக்கவும் வேண்டாம்; ஜீவரட்சணை செய்யும்படிக்குத் தேவன் என்னை உங்களுக்கு முன்னே அனுப்பினார்.',	1,	45,	5),
(1365,	'For these two years hath the famine been in the land: and yet there are five years, in the which there shall neither be earing nor harvest.',	'தேசத்தில் இப்பொழுது இரண்டு வருஷமாகப் பஞ்சம் உண்டாயிருக்கிறது; இன்னும் ஐந்து வருஷம் உழவும் அறுப்பும் இல்லாமல் பஞ்சம் இருக்கும்.',	1,	45,	6),
(1366,	'And God sent me before you to preserve you a posterity in the earth, and to save your lives by a great deliverance.',	'பூமியிலே உங்கள் வம்சம் ஒழியாமலிருக்க உங்களை ஆதரிக்கிறதற்காகவும், பெரிய ரட்சிப்பினால் உங்களை உயிரோடே காப்பதற்காகவும் தேவன் என்னை உங்களுக்கு முன்னமே அனுப்பினார்.',	1,	45,	7),
(1367,	'So now it was not you that sent me hither, but God: and he hath made me a father to Pharaoh, and lord of all his house, and a ruler throughout all the land of Egypt.',	'ஆதலால் நீங்கள் அல்ல, தேவனே என்னை இவ்விடத்துக்கு அனுப்பி, என்னைப் பார்வோனுக்குத் தகப்பனாகவும், அவர் குடும்பம் அனைத்திற்கும் கர்த்தனாகவும், எகிப்துதேசம் முழுதுக்கும் அதிபதியாகவும் வைத்தார்.',	1,	45,	8),
(1368,	'Haste ye, and go up to my father, and say unto him, Thus saith thy son Joseph, God hath made me lord of all Egypt: come down unto me, tarry not:',	'நீங்கள் சீக்கிரமாய் என் தகப்பனிடத்தில் போய்: தேவன் என்னை எகிப்துதேசம் முழுவதுக்கும் அதிபதியாக வைத்தார்; என்னிடத்தில் வாரும், தாமதிக்க வேண்டாம்.',	1,	45,	9),
(1369,	'And thou shalt dwell in the land of Goshen, and thou shalt be near unto me, thou, and thy children, and thy children\'s children, and thy flocks, and thy herds, and all that thou hast:',	'நீரும், உம்முடைய பிள்ளைகளும், அவர்களுடைய பிள்ளைகளும், உம்முடைய ஆடுமாடுகளோடும் உமக்கு உண்டாயிருக்கிற யாவற்றோடும் கோசேன் நாட்டில் வாசம்பண்ணி என் சமீபத்தில் இருக்கலாம்.',	1,	45,	10),
(1370,	'And there will I nourish thee; for yet there are five years of famine; lest thou, and thy household, and all that thou hast, come to poverty.',	'உமக்கும் உம்முடைய குடும்பத்தாருக்கும் உமக்கு இருக்கிற யாவற்றிற்கும் வறுமை வராதபடிக்கு, அங்கே உம்மைப் பராமரிப்பேன்; இன்னும் ஐந்து வருஷம் பஞ்சம் இருக்கும் என்று, உம்முடைய குமாரனாகிய யோசேப்பு சொல்லச்சொன்னான் என்று சொல்லுங்கள்.',	1,	45,	11),
(1371,	'And, behold, your eyes see, and the eyes of my brother Benjamin, that it is my mouth that speaketh unto you.',	'இதோ, உங்களோடே பேசுகிற வாய் என் வாய்தான் என்பதை உங்கள் கண்களும் என் தம்பியாகிய பென்யமீனின் கண்களும் காண்கிறதே.',	1,	45,	12),
(1372,	'And ye shall tell my father of all my glory in Egypt, and of all that ye have seen; and ye shall haste and bring down my father hither.',	'எகிப்திலே எனக்கு உண்டாயிருக்கிற சகல மகிமையையும், நீங்கள் கண்ட யாவையும் என் தகப்பனுக்கு அறிவித்து, அவர் சீக்கிரமாய் இவ்விடத்துக்கு வரும்படி செய்யுங்கள் என்று சொல்லி;',	1,	45,	13),
(1373,	'And he fell upon his brother Benjamin\'s neck, and wept; and Benjamin wept upon his neck.',	'தன் தம்பியாகிய பென்யமீனின் கழுத்தைக் கட்டிக்கொண்டு அழுதான்; பென்யமீனும் அவன் கழுத்தைக் கட்டிக்கொண்டு அழுதான்.',	1,	45,	14),
(1374,	'Moreover he kissed all his brethren, and wept upon them: and after that his brethren talked with him.',	'பின்பு தன் சகோதரர் யாவரையும் முத்தஞ்செய்து, அவர்களையும் கட்டிக்கொண்டு அழுதான். அதற்குப்பின் அவன் சகோதரர் அவனோடே சம்பாஷித்தார்கள்.',	1,	45,	15),
(1375,	'And the fame thereof was heard in Pharaoh\'s house, saying, Joseph\'s brethren are come: and it pleased Pharaoh well, and his servants.',	'யோசேப்பின் சகோதரர் வந்தார்கள் என்கிற சமாசாரம் பார்வோன் அரமனையில் பிரசித்தமானபோது, பார்வோனும் அவனுடைய ஊழியக்காரரும் சந்தோஷம் அடைந்தார்கள்.',	1,	45,	16),
(1376,	'And Pharaoh said unto Joseph, Say unto thy brethren, This do ye; lade your beasts, and go, get you unto the land of Canaan;',	'பார்வோன் யோசேப்பை நோக்கி: நீ உன் சகோதரரோடே சொல்லவேண்டியது என்னவென்றால்: உங்கள் கழுதைகளின்மேல் பொதியேற்றிக்கொண்டு புறப்பட்டு, கானான்தேசத்துக்குப் போய்,',	1,	45,	17),
(1377,	'And take your father and your households, and come unto me: and I will give you the good of the land of Egypt, and ye shall eat the fat of the land.',	'உங்கள் தகப்பனையும் உங்கள் குடும்பத்தாரையும் கூட்டிக்கொண்டு, என்னிடத்தில் வாருங்கள், நான் உங்களுக்கு எகிப்துதேசத்தின் நன்மையைத் தருவேன்; தேசத்தின் கொழுமையைச் சாப்பிடுவீர்கள்.',	1,	45,	18),
(1378,	'Now thou art commanded, this do ye; take you wagons out of the land of Egypt for your little ones, and for your wives, and bring your father, and come.',	'நீங்கள் உங்கள் குழந்தைகளுக்காகவும் உங்கள் மனைவிகளுக்காகவும் வண்டிகளை எகிப்துதேசத்திலிருந்து கொண்டுபோய், அவர்களையும் உங்கள் தகப்பனுடனே ஏற்றிக்கொண்டு வாருங்கள்.',	1,	45,	19),
(1379,	'Also regard not your stuff; for the good of all the land of Egypt is your\'s.',	'உங்கள் தட்டுமுட்டுகளைக் குறித்துக் கவலைப்படவேண்டாம்; எகிப்துதேசமெங்குமுள்ள நன்மை உங்களுடையாதாயிருக்கும் என்று சொல்லச் சொல்லி, உனக்கு நான் இட்ட கட்டளைப்படியே செய் என்றான்.',	1,	45,	20),
(1380,	'And the children of Israel did so: and Joseph gave them wagons, according to the commandment of Pharaoh, and gave them provision for the way.',	'இஸ்ரவேலின் குமாரர் அப்படியே செய்தார்கள், யோசேப்பு பார்வோனுடைய கட்டளையின்படியே அவர்களுக்கு வண்டிகளைக் கொடுத்ததுமன்றி, வழிக்கு ஆகாரத்தையும்,',	1,	45,	21),
(1381,	'To all of them he gave each man changes of raiment; but to Benjamin he gave three hundred pieces of silver, and five changes of raiment.',	'அவர்களில் ஒவ்வொருவனுக்கும் மாற்று வஸ்திரங்களையும் கொடுத்தான்; பென்யமீனுக்கோ முந்நூறு வெள்ளிக்காசையும் ஐந்து மாற்று வஸ்திரங்களையும் கொடுத்தான்.',	1,	45,	22),
(1382,	'And to his father he sent after this manner; ten asses laden with the good things of Egypt, and ten she asses laden with corn and bread and meat for his father by the way.',	'அப்படியே தன் தகப்பனுக்குப் பத்துக் கழுதைகளின்மேல் எகிப்தின் உச்சிதமான பதார்த்தங்களும், பத்துக் கோளிகைக் கழுதைகளின்மேல் தன் தகப்பனுக்காக வழிக்குத் தானியமும் அப்பமும் மற்றத் தின்பண்டங்களும் ஏற்றி அனுப்பினான்.',	1,	45,	23),
(1383,	'So he sent his brethren away, and they departed: and he said unto them, See that ye fall not out by the way.',	'மேலும், நீங்கள் போகும் வழியிலே சண்டைபண்ணிக்கொள்ளாதிருங்கள் என்று அவன் தன் சகோதரருக்குச் சொல்லி அனுப்பினான்; அவர்கள் புறப்பட்டுப்போனார்கள்.',	1,	45,	24),
(1384,	'And they went up out of Egypt, and came into the land of Canaan unto Jacob their father,',	'அவர்கள் எகிப்திலிருந்து போய், கானான்தேசத்திலே தங்கள் தகப்பனாகிய யாக்கோபினிடத்தில் வந்து:',	1,	45,	25),
(1385,	'And told him, saying, Joseph is yet alive, and he is governor over all the land of Egypt. And Jacob\'s heart fainted, for he believed them not.',	'யோசேப்பு உயிரோடிருக்கிறான், அவன் எகிப்துதேசத்துக்கெல்லாம் அதிபதியாயிருக்கிறான் என்று அவனுக்கு அறிவித்தார்கள். அவன் இருதயம் மூர்ச்சை அடைந்தது; அவன் அவர்களை நம்பவில்லை.',	1,	45,	26),
(1386,	'And they told him all the words of Joseph, which he had said unto them: and when he saw the wagons which Joseph had sent to carry him, the spirit of Jacob their father revived:',	'அவர்கள் யோசேப்பு தங்களுடனே சொன்ன வார்த்தைகள் யாவையும் அவனுக்குச் சொன்னபோதும், தன்னை ஏற்றிக்கொண்டு போகும்படி யோசேப்பு அனுப்பின வண்டிகளை அவன் கண்டபோதும், அவர்களுடைய தகப்பனாகிய யாக்கோபின் ஆவி உயிர்த்தது.',	1,	45,	27),
(1387,	'And Israel said, It is enough; Joseph my son is yet alive: I will go and see him before I die.',	'அப்பொழுது இஸ்ரவேல்: என் குமாரனாகிய யோசேப்பு இன்னும் உயிரோடிருக்கிறானே, இது போதும்; நான் மரணமடையுமுன்னே போய் அவனைப் பார்ப்பேன் என்றான்.  ',	1,	45,	28),
(1388,	'And Israel took his journey with all that he had, and came to Beersheba, and offered sacrifices unto the God of his father Isaac.',	'இஸ்ரவேல் தனக்கு உண்டான யாவையும் சேர்த்துக்கொண்டு புறப்பட்டுப் பெயெர்செபாவுக்குப் போய், தன் தகப்பனாகிய ஈசாக்குடைய தேவனுக்குப் பலியிட்டான்.',	1,	46,	1),
(1389,	'And God spake unto Israel in the visions of the night, and said, Jacob, Jacob. And he said, Here am I.',	'அன்று இரவிலே தேவன் இஸ்ரவேலுக்குத் தரிசனமாகி: யாக்கோபே, யாக்கோபே என்று கூப்பிட்டார்; அவன் இதோ, அடியேன் என்றான்.',	1,	46,	2),
(1390,	'And he said, I am God, the God of thy father: fear not to go down into Egypt; for I will there make of thee a great nation:',	'அப்பொழுது அவர்: நான் தேவன், நான் உன் தகப்பனுடைய தேவன்; நீ எகிப்துதேசத்துக்குப்போகப் பயப்படவேண்டாம்; அங்கே உன்னைப் பெரிய ஜாதியாக்குவேன்.',	1,	46,	3),
(1391,	'I will go down with thee into Egypt; and I will also surely bring thee up again: and Joseph shall put his hand upon thine eyes.',	'நான் உன்னுடனே எகிப்துக்கு வருவேன்; நான் உன்னைத் திரும்பவும் வரப்பண்ணுவேன்; யோசேப்பு தன் கையால் உன் கண்களை மூடுவான் என்று சொன்னார்.',	1,	46,	4),
(1392,	'And Jacob rose up from Beersheba: and the sons of Israel carried Jacob their father, and their little ones, and their wives, in the wagons which Pharaoh had sent to carry him.',	'அதற்குப்பின்பு, யாக்கோபு பெயெர்செபாவிலிருந்து பிரயாணம் புறப்பட்டான். இஸ்ரவேலின் குமாரர் தங்கள் தகப்பனாகிய யாக்கோபையும் தங்கள் குழந்தைகளையும் தங்கள் மனைவிகளையும் பார்வோன் அனுப்பின வண்டிகளின்மேல் ஏற்றிக்கொண்டு,',	1,	46,	5),
(1393,	'And they took their cattle, and their goods, which they had gotten in the land of Canaan, and came into Egypt, Jacob, and all his seed with him:',	'தங்கள் ஆடுமாடுகளையும் தாங்கள் கானான் தேசத்தில் சம்பாதித்த தங்கள் பொருட்களையும் சேர்த்துக்கொண்டு, யாக்கோபும் அவன் சந்ததியார் யாவரும் எகிப்துக்குப் போனார்கள்.',	1,	46,	6),
(1394,	'His sons, and his sons\' sons with him, his daughters, and his sons\' daughters, and all his seed brought he with him into Egypt.',	'அவன் தன் குமாரரையும் தன் குமாரரின் குமாரரையும் தன் குமாரத்திகளையும் தன் குமாரரின் குமாரத்திகளையும் தன் சந்ததியார் அனைவரையும் எகிப்துக்குத் தன்னோடே அழைத்துக்கொண்டுபோனான்.',	1,	46,	7),
(1395,	'And these are the names of the children of Israel, which came into Egypt, Jacob and his sons: Reuben, Jacob\'s firstborn.',	'எகிப்துக்கு வந்த இஸ்ரவேலரின் நாமங்களாவன: யாக்கோபும் அவனுடைய குமாரரும்; யாக்கோபுடைய மூத்தகுமாரனான ரூபன்.',	1,	46,	8),
(1396,	'And the sons of Reuben; Hanoch, and Phallu, and Hezron, and Carmi.',	'ரூபனுடைய குமாரர் ஆனோக்கு, பல்லூ, எஸ்ரோன், கர்மீ என்பவர்கள்.',	1,	46,	9),
(1397,	'And the sons of Simeon; Jemuel, and Jamin, and Ohad, and Jachin, and Zohar, and Shaul the son of a Canaanitish woman.',	'சிமியோனுடைய குமாரர் எமுவேல், யாமின், ஓகாத், யாகீன், சொகார், கானானிய ஸ்திரீயின் குமாரனாகிய சவுல் என்பவர்கள்.',	1,	46,	10),
(1398,	'And the sons of Levi; Gershon, Kohath, and Merari.',	'லேவியினுடைய குமாரர் கெர்சோன், கோகாத், மெராரி என்பவர்கள்.',	1,	46,	11),
(1399,	'And the sons of Judah; Er, and Onan, and Shelah, and Pharez, and Zarah: but Er and Onan died in the land of Canaan. And the sons of Pharez were Hezron and Hamul.',	'யூதாவினுடைய குமாரர் ஏர், ஓனான், சேலா, பாரேஸ், சேரா என்பவர்கள்; அவர்களில் ஏரும் ஓனானும் கானான்தேசத்தில் இறந்துபோனார்கள்; பாரேசுடைய குமாரர் எஸ்ரோன், ஆமூல் என்பவர்கள்.',	1,	46,	12),
(1400,	'And the sons of Issachar; Tola, and Phuvah, and Job, and Shimron.',	'இசக்காருடைய குமாரர் தோலா, பூவா, யோபு, சிம்ரோன் என்பவர்கள்.',	1,	46,	13),
(1401,	'And the sons of Zebulun; Sered, and Elon, and Jahleel.',	'செபுலோனுடைய குமாரர் செரேத், ஏலோன், யக்லேல் என்பவர்கள்.',	1,	46,	14),
(1402,	'These be the sons of Leah, which she bare unto Jacob in Padanaram, with his daughter Dinah: all the souls of his sons and his daughters were thirty and three.',	'இவர்கள் லேயாளின் சந்ததியார்; அவள் இவர்களையும் தீனாள் என்னும் ஒரு குமாரத்தியையும் பதான் அராமிலே யாக்கோபுக்குப் பெற்றாள்; அவன் குமாரரும் அவன் குமாரத்திகளுமாகிய எல்லாரும் முப்பத்துமூன்றுபேர்.',	1,	46,	15),
(1403,	'And the sons of Gad; Ziphion, and Haggi, Shuni, and Ezbon, Eri, and Arodi, and Areli.',	'காத்துடைய குமாரர், சிப்பியோன், அகி, சூனி, எஸ்போன், ஏரி, அரோதி, அரேலி என்பவர்கள்.',	1,	46,	16),
(1404,	'And the sons of Asher; Jimnah, and Ishuah, and Isui, and Beriah, and Serah their sister: and the sons of Beriah; Heber, and Malchiel.',	'ஆசேருடைய குமாரர் இம்னா, இஸ்வா, இஸ்வி, பெரீயா என்பவர்கள்; இவர்களுடைய சகோதரி செராக்கு என்பவள்; பெரீயாவின் குமாரர் ஏபேர், மல்கியேல் என்பவர்கள்.',	1,	46,	17),
(1405,	'These are the sons of Zilpah, whom Laban gave to Leah his daughter, and these she bare unto Jacob, even sixteen souls.',	'இவர்கள் லாபான் தன் குமாரத்தியாகிய வேயாளுக்குக் கொடுத்த சில்பாளுடைய பிள்ளைகள்; அவள் இந்தப் பதினாறுபேரையும் யாக்கோபுக்குப் பெற்றாள்.',	1,	46,	18),
(1406,	'The sons of Rachel Jacob\'s wife; Joseph, and Benjamin.',	'யாக்கோபின் மனைவியாகிய ராகேலுடைய குமாரர் யோசேப்பு, பென்யமீன் என்பவர்கள்.',	1,	46,	19),
(1407,	'And unto Joseph in the land of Egypt were born Manasseh and Ephraim, which Asenath the daughter of Potipherah priest of On bare unto him.',	'யோசேப்புக்கு எகிப்துதேசத்திலே மனாசேயும் எப்பிராயீமும் பிறந்தார்கள்; அவர்களை ஓன்பட்டணத்து ஆசாரியனாகிய போத்திபிராவின் குமாரத்தியாகிய ஆஸ்நாத் அவனுக்குப் பெற்றாள்.',	1,	46,	20),
(1408,	'And the sons of Benjamin were Belah, and Becher, and Ashbel, Gera, and Naaman, Ehi, and Rosh, Muppim, and Huppim, and Ard.',	'பென்யமீனுடைய குமாரர் பேலா, பெகேர், அஸ்பேல், கேரா, நாகமான், ஏகி, ரோஷ், முப்பிம், உப்பிம், ஆர்து என்பவர்கள்.',	1,	46,	21),
(1409,	'These are the sons of Rachel, which were born to Jacob: all the souls were fourteen.',	'ராகேல் யாக்கோபுக்குப் பெற்ற குமாரராகிய இவர்கள் எல்லாரும் பதினாலுபேர்.',	1,	46,	22),
(1410,	'And the sons of Dan; Hushim.',	'தாணுடைய குமாரன் உசீம் என்பவன்.',	1,	46,	23),
(1411,	'And the sons of Naphtali; Jahzeel, and Guni, and Jezer, and Shillem.',	'நப்தலியின் குமாரர் யாத்சியேல், கூனி, எத்செர், சில்லேம் என்பவர்கள்.',	1,	46,	24),
(1412,	'These are the sons of Bilhah, which Laban gave unto Rachel his daughter, and she bare these unto Jacob: all the souls were seven.',	'இவர்கள் லாபான் தன் குமாரத்தியாகிய ராகேலுக்குக் கொடுத்த பில்காள் யாக்கோபுக்குப் பெற்றவர்கள்; இவர்கள் எல்லாரும் ஏழுபேர்.',	1,	46,	25),
(1413,	'All the souls that came with Jacob into Egypt, which came out of his loins, besides Jacob\'s sons\' wives, all the souls were threescore and six;',	'யாக்கோபுடைய குமாரரின் மனைவிகளைத் தவிர, அவனுடைய கர்ப்பப்பிறப்பாயிருந்து அவன் மூலமாய் எகிப்திலே வந்தவர்கள் எல்லாரும் அறுபத்தாறுபேர்.',	1,	46,	26),
(1414,	'And the sons of Joseph, which were born him in Egypt, were two souls: all the souls of the house of Jacob, which came into Egypt, were threescore and ten.',	'யோசேப்புக்கு எகிப்திலே பிறந்த குமாரர் இரண்டுபேர்; ஆக எகிப்துக்குப் போன யாக்கோபின் குடும்பத்தார் எழுபதுபேர்.',	1,	46,	27),
(1415,	'And he sent Judah before him unto Joseph, to direct his face unto Goshen; and they came into the land of Goshen.',	'கோசேன் நாட்டிலே தன்னை யோசேப்பு சந்திக்க வரும்படி சொல்ல, யூதாவைத் தனக்கு முன்னாக அவனிடத்தில் யாக்கோபு அனுப்பினான்; அவர்கள் கோசேனிலே சேர்ந்தார்கள்.',	1,	46,	28),
(1416,	'And Joseph made ready his chariot, and went up to meet Israel his father, to Goshen, and presented himself unto him; and he fell on his neck, and wept on his neck a good while.',	'யோசேப்பு தன் இரதத்தை ஆயத்தப்படுத்தி, அதின்மேல் ஏறி, தன் தகப்பனாகிய இஸ்ரவேலைச் சந்திக்கும்படி போய், அவனைக் கண்டு, அவனுடைய கழுத்தைக் கட்டிக்கொண்டு, வெகுநேரம் அவன் கழுத்தை விடாமல் அழுதான்.',	1,	46,	29),
(1417,	'And Israel said unto Joseph, Now let me die, since I have seen thy face, because thou art yet alive.',	'அப்பொழுது இஸ்ரவேல் யோசேப்பைப் பார்த்து: நீ இன்னும் உயிரோடிருக்கிறாயே, நான் உன் முகத்தைக் கண்டேன், எனக்கு இப்போது மரணம் வந்தாலும் வரட்டும் என்றான்.',	1,	46,	30),
(1418,	'And Joseph said unto his brethren, and unto his father\'s house, I will go up, and shew Pharaoh, and say unto him, My brethren, and my father\'s house, which were in the land of Canaan, are come unto me;',	'பின்பு, யோசேப்பு தன் சகோதரரையும் தன் தகப்பனுடைய குடும்பத்தாரையும் நோக்கி: நான் பார்வோனிடத்துக்குப் போய், கானான்தேசத்திலிருந்து என் சகோதரரும் என் தகப்பன் குடும்பத்தாரும் என்னிடத்தில் வந்திருக்கிறார்கள்.',	1,	46,	31),
(1419,	'And the men are shepherds, for their trade hath been to feed cattle; and they have brought their flocks, and their herds, and all that they have.',	'அவர்கள் மேய்ப்பர்கள், ஆடுமாடுகளை மேய்க்கிறது அவர்கள் தொழில்; அவர்கள் தங்கள் ஆடுமாடுகளையும் தங்களுக்கு உண்டான எல்லாவற்றையும் கொண்டுவந்தார்கள் என்று அவருக்குச் சொல்லுகிறேன்.',	1,	46,	32),
(1420,	'And it shall come to pass, when Pharaoh shall call you, and shall say, What is your occupation?',	'பார்வோன் உங்களை அழைத்து, உங்கள் தொழில் என்ன என்று கேட்டால்,',	1,	46,	33),
(1421,	'That ye shall say, Thy servants\' trade hath been about cattle from our youth even until now, both we, and also our fathers: that ye may dwell in the land of Goshen; for every shepherd is an abomination unto the Egyptians.',	'நீங்கள், கோசேன் நாட்டிலே குடியிருக்கும்படி, அவனை நோக்கி: எங்கள் பிதாக்களைப்போல, உமது அடியாராகிய நாங்களும் எங்கள் சிறுவயதுமுதல் இதுவரைக்கும் மேய்ப்பர்களாயிருக்கிறோம் என்று சொல்லுங்கள்; மேய்ப்பர்கள் எல்லாரும் எகிப்தியருக்கு அருவருப்பாயிருக்கிறார்கள் என்றான்.  ',	1,	46,	34),
(1422,	'Then Joseph came and told Pharaoh, and said, My father and my brethren, and their flocks, and their herds, and all that they have, are come out of the land of Canaan; and, behold, they are in the land of Goshen.',	'யோசேப்பு பார்வோனிடத்தில் போய்: என் தகப்பனும் என் சகோதரரும், தங்கள் ஆடுமாடுகளோடும் தங்களுக்கு உண்டான எல்லாவற்றோடுங்கூடக் கானான்தேசத்திலிருந்து வந்தார்கள்; இப்பொழுது கோசேன் நாட்டில் இருக்கிறார்கள் என்று சொல்லி;',	1,	47,	1),
(1423,	'And he took some of his brethren, even five men, and presented them unto Pharaoh.',	'தன் சகோதரரில் ஐந்துபேரைப் பார்வோனுக்கு முன்பாகக் கொண்டுபோய் நிறுத்தினான்.',	1,	47,	2),
(1424,	'And Pharaoh said unto his brethren, What is your occupation? And they said unto Pharaoh, Thy servants are shepherds, both we, and also our fathers.',	'பார்வோன் அவனுடைய சகோதரரை நோக்கி: உங்கள் தொழில் என்ன என்று கேட்டான்; அதற்கு அவர்கள்: உமது அடியாராகிய நாங்களும் எங்கள் பிதாக்களும் மந்தை மேய்க்கிறவர்கள் என்று பார்வோனிடத்தில் சொன்னதுமன்றி,',	1,	47,	3),
(1425,	'They said morever unto Pharaoh, For to sojourn in the land are we come; for thy servants have no pasture for their flocks; for the famine is sore in the land of Canaan: now therefore, we pray thee, let thy servants dwell in the land of Goshen.',	'கானான் தேசத்திலே பஞ்சம் கொடிதாயிருக்கிறது; உமது அடியாரின் மந்தைகளுக்கு மேய்ச்சல் இல்லாமையால், இத்தேசத்திலே தங்கவந்தோம்; உமது அடியாராகிய நாங்கள் கோசேன் நாட்டிலே குடியிருக்கும்படி தயவுசெய்யவேண்டும் என்று வேண்டிக்கொண்டார்கள்.',	1,	47,	4),
(1426,	'And Pharaoh spake unto Joseph, saying, Thy father and thy brethren are come unto thee:',	'அப்பொழுது பார்வோன் யோசேப்பை நோக்கி: உன் தகப்பனும் உன் சகோதரரும் உன்னிடத்தில் வந்திருக்கிறார்களே.',	1,	47,	5),
(1427,	'The land of Egypt is before thee; in the best of the land make thy father and brethren to dwell; in the land of Goshen let them dwell: and if thou knowest any men of activity among them, then make them rulers over my cattle.',	'எகிப்துதேசம் உனக்கு முன்பாக இருக்கிறது; தேசத்திலுள்ள நல்ல இடத்திலே உன் தகப்பனையும் உன் சகோதரரையும் குடியேறும்படி செய்; அவர்கள் கோசேன் நாட்டிலே குடியிருக்கலாம்; அவர்களுக்குள்ளே திறமையுள்ளவர்கள் உண்டென்று உனக்குத் தெரிந்திருந்தால், அவர்களை என் ஆடுமாடுகளை விசாரிக்கிறதற்குத் தலைவராக வைக்கலாம் என்றான்.',	1,	47,	6),
(1428,	'And Joseph brought in Jacob his father, and set him before Pharaoh: and Jacob blessed Pharaoh.',	'பின்பு, யோசேப்பு தன் தகப்பனாகிய யாக்கோபை அழைத்துக்கொண்டுவந்து, அவனைப் பார்வோனுக்கு முன்பாக நிறுத்தினான். யாக்கோபு பார்வோனை ஆசீர்வதித்தான்.',	1,	47,	7),
(1429,	'And Pharaoh said unto Jacob, How old art thou?',	'பார்வோன் யாக்கோபை நோக்கி: உமக்கு வயது என்ன என்று கேட்டான்.',	1,	47,	8),
(1430,	'And Jacob said unto Pharaoh, The days of the years of my pilgrimage are an hundred and thirty years: few and evil have the days of the years of my life been, and have not attained unto the days of the years of the life of my fathers in the days of their pilgrimage.',	'அதற்கு யாக்கோபு: நான் பரதேசியாய்ச் சஞ்சரித்த நாட்கள் நூற்றுமுப்பது வருஷம்; என் ஆயுசு நாட்கள் கொஞ்சமும் சஞ்சலமுள்ளதுமாயிருக்கிறது; அவைகள் பரதேசிகளாய்ச் சஞ்சரித்த என் பிதாக்களுடைய ஆயுசு நாட்களுக்கு வந்து எட்டவில்லை என்று பார்வோனுடனே சொன்னான்.',	1,	47,	9),
(1431,	'And Jacob blessed Pharaoh, and went out from before Pharaoh.',	'பின்னும் யாக்கோபு பார்வோனை ஆசீர்வதித்து, அவன் சமுகத்தினின்று புறப்பட்டுப்போனான்.',	1,	47,	10),
(1432,	'And Joseph placed his father and his brethren, and gave them a possession in the land of Egypt, in the best of the land, in the land of Rameses, as Pharaoh had commanded.',	'பார்வோன் கட்டளையிட்டபடியே, யோசேப்பு தன் தகப்பனுக்கும் தன் சகோதரருக்கும் எகிப்துதேசத்திலே நல்ல நாடாகிய ராமசேஸ் என்னும் நாட்டிலே சுதந்திரம் கொடுத்து, அவர்களைக் குடியேற்றினான்.',	1,	47,	11),
(1433,	'And Joseph nourished his father, and his brethren, and all his father\'s household, with bread, according to their families.',	'யோசேப்பு தன் தகப்பனையும் தன் சகோதரரையும் தன் தகப்பனுடைய குடும்பத்தார் அனைவரையும், அவரவர்கள் குடும்பத்திற்குத்தக்கதாய் ஆகாரம் கொடுத்து ஆதரித்துவந்தான்.',	1,	47,	12),
(1434,	'And there was no bread in all the land; for the famine was very sore, so that the land of Egypt and all the land of Canaan fainted by reason of the famine.',	'பஞ்சம் மிகவும் கொடிதாயிருந்தது; தேசமெங்கும் ஆகாரம் கிடையாமற்போயிற்று; எகிப்துதேசமும் கானான்தேசமும் பஞ்சத்தினாலே மெலிந்துபோயிற்று.',	1,	47,	13),
(1435,	'And Joseph gathered up all the money that was found in the land of Egypt, and in the land of Canaan, for the corn which they bought: and Joseph brought the money into Pharaoh\'s house.',	'யோசேப்பு எகிப்துதேசத்திலும் கானான்தேசத்திலுமுள்ள பணத்தையெல்லாம் தானியம் கொண்டவர்களிடத்தில் வாங்கி, அதைப் பார்வோன் அரமனையிலே கொண்டுபோய்ச் சேர்த்தான்.',	1,	47,	14),
(1436,	'And when money failed in the land of Egypt, and in the land of Canaan, all the Egyptians came unto Joseph, and said, Give us bread: for why should we die in thy presence? for the money faileth.',	'எகிப்துதேசத்திலும் கானான்தேசத்திலுமுள்ள பணம் செலவழிந்தபோது, எகிப்தியர் எல்லாரும் யோசேப்பினிடத்தில் வந்து: எங்களுக்கு ஆகாரம் தாரும்; பணம் இல்லை, அதினால் நாங்கள் உமது சமுகத்தில் சாகவேண்டுமோ என்றார்கள்.',	1,	47,	15),
(1437,	'And Joseph said, Give your cattle; and I will give you for your cattle, if money fail.',	'அதற்கு யோசேப்பு: உங்களிடத்தில் பணம் இல்லாமற்போனால், உங்கள் ஆடுமாடுகளைக் கொடுங்கள்; அவைகளுக்குப் பதிலாக உங்களுக்குத் தானியம் கொடுக்கிறேன் என்றான்.',	1,	47,	16),
(1438,	'And they brought their cattle unto Joseph: and Joseph gave them bread in exchange for horses, and for the flocks, and for the cattle of the herds, and for the asses: and he fed them with bread for all their cattle for that year.',	'அவர்கள் தங்கள் ஆடுமாடு முதலானவைகளை யோசேப்பினிடத்தில் கொண்டுவந்தார்கள்; யோசேப்பு குதிரைகளையும் ஆடுகளையும் மாடுகளையும் கழுதைகளையும் வாங்கிக்கொண்டு, அந்த வருஷம் அவர்களுடைய ஆடுமாடு முதலான எல்லாவற்றிற்கும் பதிலாக அவர்களுக்கு ஆகாரம் கொடுத்து, அவர்களை ஆதரித்தான்.',	1,	47,	17),
(1439,	'When that year was ended, they came unto him the second year, and said unto him, We will not hide it from my lord, how that our money is spent; my lord also hath our herds of cattle; there is not ought left in the sight of my lord, but our bodies, and our lands:',	'அந்த வருஷம் முடிந்தபின், மறுவருஷத்திலே அவர்கள் அவனிடத்தில் வந்து: பணமும் செலவழிந்துபோயிற்று; எங்கள் ஆடுமாடு முதலானவைகளும் எங்கள் ஆண்டவனைச் சேர்ந்தது; எங்கள் சரீரமும் எங்கள் நிலமுமே ஒழிய, எங்கள் ஆண்டவனுக்கு முன்பாக மீதியானது ஒன்றும் இல்லை; இது எங்கள் ஆண்டவனுக்குத் தெரியாத காரியம் அல்ல.',	1,	47,	18),
(1440,	'Wherefore shall we die before thine eyes, both we and our land? buy us and our land for bread, and we and our land will be servants unto Pharaoh: and give us seed, that we may live, and not die, that the land be not desolate.',	'நாங்களும் எங்கள் நிலங்களும் உம்முடைய கண்களுக்கு முன்பாக அழிந்து போகலாமா? நீர் எங்களையும் எங்கள் நிலங்களையும் வாங்கிக்கொண்டு, ஆகாரம் கொடுக்கவேண்டும்; நாங்களும் எங்கள் நிலங்களும் பார்வோனுக்கு ஆதீனமாயிருப்போம்; நாங்கள் சாகாமல் உயிரோடிருக்கவும், நிலங்கள் பாழாய்ப் போகாமலிருக்கவும், எங்களுக்கு விதைத்தானியத்தைத் தாரும் என்றார்கள்.',	1,	47,	19),
(1441,	'And Joseph bought all the land of Egypt for Pharaoh; for the Egyptians sold every man his field, because the famine prevailed over them: so the land became Pharaoh\'s.',	'அப்படியே எகிப்தியர் தங்களுக்குப் பஞ்சம் மேலிட்டபடியால் அவரவர் தங்கள் தங்கள் வயல் நிலங்களை விற்றார்கள்; யோசேப்பு எகிப்தின் நிலங்கள் யாவையும் பார்வோனுக்காகக் கொண்டான்; இவ்விதமாய் அந்தப் பூமி பார்வோனுடையதாயிற்று.',	1,	47,	20),
(1442,	'And as for the people, he removed them to cities from one end of the borders of Egypt even to the other end thereof.',	'மேலும் அவன் எகிப்தின் ஒரு எல்லைமுதல் மறு எல்லைவரைக்குமுள்ள ஜனங்களை அந்தந்தப் பட்டணங்களில் குடிமாறிப்போகப்பண்ணினான்.',	1,	47,	21),
(1443,	'Only the land of the priests bought he not; for the priests had a portion assigned them of Pharaoh, and did eat their portion which Pharaoh gave them: wherefore they sold not their lands.',	'ஆசாரியருடைய நிலத்தை மாத்திரம் அவன் கொள்ளவில்லை; அது பார்வோனாலே ஆசாரியருக்கு மானியமாகக் கொடுக்கப்பட்டிருந்ததினாலும், பார்வோன் அவர்களுக்குக் கொடுத்த மானியத்தினாலே அவர்கள் ஜீவனம் பண்ணிவந்ததினாலும், அவர்கள் தங்கள் நிலத்தை விற்கவில்லை.',	1,	47,	22),
(1444,	'Then Joseph said unto the people, Behold, I have bought you this day and your land for Pharaoh: lo, here is seed for you, and ye shall sow the land.',	'பின்னும் யோசேப்பு ஜனங்களை நோக்கி: இதோ, இன்று உங்களையும் உங்கள் நிலங்களையும் பார்வோனுக்காக வாங்கிக்கொண்டேன்; இதோ, உங்களுக்குக் கொடுக்கப்படுகிற விதைத் தானியம், இதை நிலத்தில் விதையுங்கள்.',	1,	47,	23),
(1445,	'And it shall come to pass in the increase, that ye shall give the fifth part unto Pharaoh, and four parts shall be your own, for seed of the field, and for your food, and for them of your households, and for food for your little ones.',	'விளைவில் ஐந்தில் ஒரு பங்கைப் பார்வோனுக்குக் கொடுக்கவேண்டும்; மற்ற நாலு பங்கும் வயலுக்கு விதையாகவும் உங்களுக்கும் உங்கள் குடும்பத்தாருக்கும் உங்கள் குழந்தைகளுக்கும் ஆகாரமாகவும் உங்களுடையதாயிருக்கட்டும் என்றான்.',	1,	47,	24),
(1446,	'And they said, Thou hast saved our lives: let us find grace in the sight of my lord, and we will be Pharaoh\'s servants.',	'அப்பொழுது அவர்கள்: நீர் எங்கள் பிராணனைக் காப்பாற்றினீர்; எங்கள் ஆண்டவனுடைய கண்களில் எங்களுக்குத் தயவு கிடைக்கவேண்டும்; நாங்கள் பார்வோனுக்கு அடிமைகளாயிருக்கிறோம் என்றார்கள்.',	1,	47,	25),
(1447,	'And Joseph made it a law over the land of Egypt unto this day, that Pharaoh should have the fifth part, except the land of the priests only, which became not Pharaoh\'s.',	'ஐந்தில் ஒன்று பார்வோனுக்குச் சேரும் வாரம் என்று யோசேப்பு இட்ட கட்டளைப்படி எகிப்து தேசத்திலே இந்நாள்வரைக்கும் நடந்துவருகிறது; ஆசாரியரின் நிலம் மாத்திரம் பார்வோனைச் சேராமல் நீங்கலாயிருந்தது.',	1,	47,	26),
(1448,	'And Israel dwelt in the land of Egypt, in the country of Goshen; and they had possessions therein, and grew, and multiplied exceedingly.',	'இஸ்ரவேலர் எகிப்து தேசத்திலுள்ள கோசேன் நாட்டிலே குடியிருந்தார்கள்; அங்கே நிலங்களைக் கையாட்சி செய்து, மிகவும் பலுகிப் பெருகினார்கள்.',	1,	47,	27),
(1449,	'And Jacob lived in the land of Egypt seventeen years: so the whole age of Jacob was an hundred forty and seven years.',	'யாக்கோபு எகிப்து தேசத்திலே பதினேழு வருஷம் இருந்தான்; யாக்கோபுடைய ஆயுசு நாட்கள் நூற்றுநாற்பத்தேழு வருஷம்.',	1,	47,	28),
(1450,	'And the time drew nigh that Israel must die: and he called his son Joseph, and said unto him, If now I have found grace in thy sight, put, I pray thee, thy hand under my thigh, and deal kindly and truly with me; bury me not, I pray thee, in Egypt:',	'இஸ்ரவேல் மரணமடையும் காலம் சமீபித்தது. அப்பொழுது அவன் தன் குமாரனாகிய யோசேப்பை வரவழைத்து, அவனை நோக்கி: என்மேல் உனக்குத் தயவுண்டானால், உன் கையை என் தொடையின்கீழ் வைத்து என்மேல் பட்சமும் உண்மையுமுள்ளவனாயிரு; என்னை எகிப்திலே அடக்கம் பண்ணாதிருப்பாயாக.',	1,	47,	29),
(1451,	'But I will lie with my fathers, and thou shalt carry me out of Egypt, and bury me in their buryingplace. And he said, I will do as thou hast said.',	'நான் என் பிதாக்களோடே படுத்துக்கொள்ளவேண்டும்; ஆகையால், நீ என்னை எகிப்திலிருந்து எடுத்துக்கொண்டுபோய், அவர்களை அடக்கம்பண்ணியிருக்கிற நிலத்திலே என்னையும் அடக்கம்பண்ணு என்றான். அதற்கு அவன்: உமது சொற்படி செய்வேன் என்றான்.',	1,	47,	30),
(1452,	'And he said, Swear unto me. And he sware unto him. And Israel bowed himself upon the bed\'s head.',	'அப்பொழுது அவன்: எனக்கு ஆணையிட்டுக்கொடு என்றான்; அவனுக்கு ஆணையிட்டுக்கொடுத்தான். அப்பொழுது இஸ்ரவேல் கட்டிலின் தலைமாட்டிலே சாய்ந்து தொழுதுகொண்டான்.  ',	1,	47,	31),
(1453,	'And it came to pass after these things, that one told Joseph, Behold, thy father is sick: and he took with him his two sons, Manasseh and Ephraim.',	'அதற்குப்பின்பு, உம்முடைய தகப்பனாருக்கு வருத்தமாயிருக்கிறது என்று யோசேப்புக்குச் சொல்லப்பட்டது. அப்பொழுது அவன் தன் இரண்டு குமாரராகிய மனாசேயையும் எப்பிராயீமையும் தன்னோடேகூடக் கொண்டுபோனான்.',	1,	48,	1),
(1454,	'And one told Jacob, and said, Behold, thy son Joseph cometh unto thee: and Israel strengthened himself, and sat upon the bed.',	'இதோ, உம்முடைய குமாரனாகிய யோசேப்பு உம்மிடத்தில் வந்திருக்கிறார் என்று யாக்கோபுக்கு அறிவிக்கப்பட்டது; அப்பொழுது இஸ்ரவேல் தன்னைத்திடப்படுத்திக்கொண்டு, கட்டிலின்மேல் உட்கார்ந்தான்.',	1,	48,	2),
(1455,	'And Jacob said unto Joseph, God Almighty appeared unto me at Luz in the land of Canaan, and blessed me,',	'யாக்கோபு யோசேப்பை நோக்கி: சர்வவல்லமையுள்ள தேவன் கானான் தேசத்திலுள்ள லூஸ் என்னும் இடத்தில் எனக்குத் தரிசனமாகி, என்னை ஆசீர்வதித்து:',	1,	48,	3),
(1456,	'And said unto me, Behold, I will make thee fruitful, and multiply thee, and I will make of thee a multitude of people; and will give this land to thy seed after thee for an everlasting possession.',	'நான் உன்னைப் பலுகவும் பெருகவும் பண்ணி, உன்னைப் பல ஜனக்கூட்டமாக்கி, உனக்குப் பின்வரும் உன் சந்ததிக்கு இந்தத் தேசத்தை நித்திய சுதந்தரமாகக் கொடுப்பேன் என்று என்னோடே சொன்னார்.',	1,	48,	4),
(1457,	'And now thy two sons, Ephraim and Manasseh, which were born unto thee in the land of Egypt before I came unto thee into Egypt, are mine; as Reuben and Simeon, they shall be mine.',	'நான் உன்னிடத்தில் எகிப்துக்கு வருமுன்னே உனக்கு எகிப்துதேசத்தில் பிறந்த உன் இரண்டு குமாரரும் என்னுடைய குமாரர்; ரூபன் சிமியோன் என்பவர்களைப்போல, எப்பிராயீமும் மனாசேயும் என்னுடையவர்கள்.',	1,	48,	5),
(1458,	'And thy issue, which thou begettest after them, shall be thine, and shall be called after the name of their brethren in their inheritance.',	'இவர்களுக்குப்பின், நீ பெறும் பிள்ளைகள் உன்னுடையவர்கள்; அவர்கள் தங்கள் தங்கள் சகோதரருடைய பேரால் அழைக்கப்பட்டு அவர்களுக்குரிய சுதந்தரத்தில் பங்குபெறுவார்கள்.',	1,	48,	6),
(1459,	'And as for me, when I came from Padan, Rachel died by me in the land of Canaan in the way, when yet there was but a little way to come unto Ephrath: and I buried her there in the way of Ephrath; the same is Bethlehem.',	'நான் பதானை விட்டு வருகையில், கானான்தேசத்தில் எப்பிராத்தாவுக்குக் கொஞ்சம் தூரம் இருக்கும்போது, வழியிலே ராகேல் என்னண்டையில் மரணமடைந்தாள்; அவளை அங்கே பெத்லகேம் என்னும் எப்பிராத்தா ஊருக்குப் போகிற வழியிலே அடக்கம்பண்ணினேன் என்றான்.',	1,	48,	7),
(1460,	'And Israel beheld Joseph\'s sons, and said, Who are these?',	'இஸ்ரவேல் யோசேப்பின் குமாரரைப் பார்த்து: இவர்கள் யார் என்று கேட்டான்.',	1,	48,	8),
(1461,	'And Joseph said unto his father, They are my sons, whom God hath given me in this place. And he said, Bring them, I pray thee, unto me, and I will bless them.',	'யோசேப்பு தன் தகப்பனை நோக்கி: இவர்கள் இவ்விடத்தில் தேவன் எனக்கு அருளின குமாரர் என்றான். அப்பொழுது அவன்: நான் அவர்களை ஆசீர்வதிக்கும்படி அவர்களை என் கிட்டக்கொண்டுவா என்றான்.',	1,	48,	9),
(1462,	'Now the eyes of Israel were dim for age, so that he could not see. And he brought them near unto him; and he kissed them, and embraced them.',	'முதிர்வயதினால் இஸ்ரவேலின் கண்கள் மங்கலாயிருந்தபடியால், அவன் நன்றாய்ப் பார்க்கக்கூடாதிருந்தது. அவர்களை அவனண்டையிலே சேரப்பண்ணினான்; அப்பொழுது அவன் அவர்களை முத்தஞ்செய்து அணைத்துக்கொண்டான்.',	1,	48,	10),
(1463,	'And Israel said unto Joseph, I had not thought to see thy face: and, lo, God hath shewed me also thy seed.',	'இஸ்ரவேல் யோசேப்பை நோக்கி: உன் முகத்தைக் காண்பேன் என்று நான் நினைக்கவில்லை; ஆனாலும், இதோ, உன் சந்ததியையும் காணும்படி தேவன் எனக்கு அருள்செய்தார் என்றான்.',	1,	48,	11),
(1464,	'And Joseph brought them out from between his knees, and he bowed himself with his face to the earth.',	'அப்பொழுது அவனுடைய முழங்கால்கள் நடுவே இருந்த பிள்ளைகளை யோசேப்பு பின்னிடப்பண்ணி, அவனுடைய முகத்துக்கு முன்பாகத் தரைமட்டும் குனிந்து வணங்கினான்.',	1,	48,	12),
(1465,	'And Joseph took them both, Ephraim in his right hand toward Israel\'s left hand, and Manasseh in his left hand toward Israel\'s right hand, and brought them near unto him.',	'பின்பு, யோசேப்பு அவ்விருவரையும் கொண்டுவந்து, எப்பிராயீமைத் தன் வலது கையினாலே இஸ்ரவேலின் இடது கைக்கு நேராகவும், மனாசேயைத் தன் இடது கையினாலே இஸ்ரவேலின் வலது கைக்கு நேராகவும் விட்டான்.',	1,	48,	13),
(1466,	'And Israel stretched out his right hand, and laid it upon Ephraim\'s head, who was the younger, and his left hand upon Manasseh\'s head, guiding his hands wittingly; for Manasseh was the firstborn.',	'அப்பொழுது இஸ்ரவேல், மனமறிய, தன் வலது கையை நீட்டி, இளையவனாகிய எப்பிராயீமுடைய தலையின்மேலும், மனாசே மூத்தவனாயிருந்தும், தன் இடது கையை மனாசேயுடைய தலையின்மேலும் வைத்தான்.',	1,	48,	14),
(1467,	'And he blessed Joseph, and said, God, before whom my fathers Abraham and Isaac did walk, the God which fed me all my life long unto this day,',	'அவன் யோசேப்பை ஆசீர்வதித்து: என் பிதாக்களாகிய ஆபிரகாமும் ஈசாக்கும் வழிபட்டு வணங்கிய தேவனும், நான் பிறந்த நாள்முதல் இந்நாள்வரைக்கும் என்னை ஆதரித்துவந்த தேவனும்,',	1,	48,	15),
(1468,	'The Angel which redeemed me from all evil, bless the lads; and let my name be named on them, and the name of my fathers Abraham and Isaac; and let them grow into a multitude in the midst of the earth.',	'எல்லாத் தீமைக்கும் நீங்கலாக்கி என்னை மீட்ட தூதனுமானவர் இந்தப் பிள்ளைகளை ஆசீர்வதிப்பாராக, என் பேரும் என் பிதாக்களாகிய ஆபிரகாம் ஈசாக்கு என்பவர்களின் பேரும் இவர்களுக்கு இடப்படக்கடவது; பூமியில் இவர்கள் மிகுதியாய்ப் பெருகக்கடவர்கள் என்றான்.',	1,	48,	16),
(1469,	'And when Joseph saw that his father laid his right hand upon the head of Ephraim, it displeased him: and he held up his father\'s hand, to remove it from Ephraim\'s head unto Manasseh\'s head.',	'தகப்பன் தன் வலதுகையை எப்பிராயீமுடைய தலையின்மேல் வைத்ததை யோசேப்பு கண்டு, அது தனக்குப் பிரியமில்லாதபடியால், எப்பிராயீமுடைய தலையின்மேல் இருந்த தன் தகப்பனுடைய கையை மனாசேயினுடைய தலையின்மேல் வைக்கும்படிக்கு எடுத்து:',	1,	48,	17),
(1470,	'And Joseph said unto his father, Not so, my father: for this is the firstborn; put thy right hand upon his head.',	'என் தகப்பனே, அப்படியல்ல, இவன் மூத்தவன், இவனுடைய தலையின் மேல் உம்முடைய வலதுகையை வைக்கவேண்டும் என்றான்.',	1,	48,	18),
(1471,	'And his father refused, and said, I know it, my son, I know it: he also shall become a people, and he also shall be great: but truly his younger brother shall be greater than he, and his seed shall become a multitude of nations.',	'அவன் தகப்பனோ தடுத்து: அது எனக்குத் தெரியும், என் மகனே, எனக்குத் தெரியும்; இவனும் ஒரு ஜனக்கூட்டமாவான், இவனும் பெருகுவான்; இவனுடைய தம்பியோ இவனிலும் அதிகமாய்ப் பெருகுவான்; அவனுடைய சந்ததியார் திரளான ஜனங்களாவார்கள் என்றான்.',	1,	48,	19),
(1472,	'And he blessed them that day, saying, In thee shall Israel bless, saying, God make thee as Ephraim and as Manasseh: and he set Ephraim before Manasseh.',	'இவ்விதமாக அவன் அன்றைத்தினம் அவர்களை ஆசீர்வதித்து: தேவன் உன்னை எப்பிராயீமைப்போலவும் மனாசேயைப்போலவும் ஆக்குவாராக என்று இஸ்ரவேலர் உன்னை முன்னிட்டு வாழ்த்துவார்கள் என்று சொல்லி, எப்பிராயீமை மனாசேக்கு முன்னே வைத்தான்.',	1,	48,	20),
(1473,	'And Israel said unto Joseph, Behold, I die: but God shall be with you, and bring you again unto the land of your fathers.',	'பின்பு, இஸ்ரவேல் யோசேப்பை நோக்கி: இதோ, நான் மரணமடையப்போகிறேன்; தேவன் உங்களோடே இருப்பார்; அவர் உங்கள் பிதாக்களின் தேசத்துக்கு உங்களைத் திரும்பவும் போகப்பண்ணுவார் என்றும்,',	1,	48,	21),
(1474,	'Moreover I have given to thee one portion above thy brethren, which I took out of the hand of the Amorite with my sword and with my bow.',	'உன் சகோதரருக்கு கொடுத்ததைப்பார்க்கிலும், நான் என் பட்டயத்தாலும், என் வில்லினாலும், எமோரியர் கையிலிருந்து சம்பாதித்த ஒரு நிலத்தை உனக்கு அதிகமான பங்காகக் கொடுத்தேன் என்றும் சொன்னான்.  ',	1,	48,	22),
(1475,	'And Jacob called unto his sons, and said, Gather yourselves together, that I may tell you that which shall befall you in the last days.',	'யாக்கோபு தன் குமாரரை அழைத்து: நீங்கள் கூடிவாருங்கள், கடைசி நாட்களில் உங்களுக்கு நேரிடும் காரியங்களை அறிவிப்பேன்.',	1,	49,	1),
(1476,	'Gather yourselves together, and hear, ye sons of Jacob; and hearken unto Israel your father.',	'யாக்கோபின் குமாரரே, கூடிவந்து கேளுங்கள்; உங்கள் தகப்பனாகிய இஸ்ரவேலுக்குச் செவிகொடுங்கள்.',	1,	49,	2),
(1477,	'Reuben, thou art my firstborn, my might, and the beginning of my strength, the excellency of dignity, and the excellency of power:',	'ரூபனே, நீ என் சேஷ்டபுத்திரன்; நீ என் சத்துவமும், என் முதற்பெலனுமானவன்; நீ மேன்மையில் பிரதானமும் வல்லமையில் விசேஷமுமானவன்.',	1,	49,	3),
(1478,	'Unstable as water, thou shalt not excel; because thou wentest up to thy father\'s bed; then defiledst thou it: he went up to my couch.',	'தண்ணீரைப்போல தளம்பினவனே, நீ மேன்மை அடையமாட்டாய்; உன் தகப்பனுடைய மஞ்சத்தின்மேல் ஏறினாய்; நீ அதைத் தீட்டுப்படுத்தினாய்; என் படுக்கையின்மேல் ஏறினானே.',	1,	49,	4),
(1479,	'Simeon and Levi are brethren; instruments of cruelty are in their habitations.',	'சிமியோனும், லேவியும் ஏகசகோதரர்; அவர்களுடைய பட்டயங்கள் கொடுமையின் கருவிகள்.',	1,	49,	5),
(1480,	'O my soul, come not thou into their secret; unto their assembly, mine honour, be not thou united: for in their anger they slew a man, and in their selfwill they digged down a wall.',	'என் ஆத்துமாவே, அவர்களுடைய இரகசிய ஆலோசனைக்கு உடன்படாதே; என் மேன்மையே, அவர்கள் கூட்டத்தில் நீ சேராதே; அவர்கள் தங்கள் கோபத்தினாலே ஒரு புருஷனைக் கொன்று, தங்கள் அகங்காரத்தினாலே அரண்களை நிர்மூலமாக்கினார்களே.',	1,	49,	6),
(1481,	'Cursed be their anger, for it was fierce; and their wrath, for it was cruel: I will divide them in Jacob, and scatter them in Israel.',	'உக்கிரமான அவர்கள் கோபமும் கொடுமையான அவர்கள் மூர்க்கமும் சபிக்கப்படக்கடவது; யாக்கோபிலே அவர்களைப் பிரியவும், இஸ்ரவேலிலே அவர்களைச் சிதறவும்பண்ணுவேன்.',	1,	49,	7),
(1482,	'Judah, thou art he whom thy brethren shall praise: thy hand shall be in the neck of thine enemies; thy father\'s children shall bow down before thee.',	'யூதாவே, சகோதரரால் புகழப்படுபவன் நீயே; உன் கரம் உன் சத்துருக்களுடைய பிடரியின்மேல் இருக்கும்; உன் தகப்பனுடைய புத்திரர் உன்முன் பணிவார்கள்.',	1,	49,	8),
(1483,	'Judah is a lion\'s whelp: from the prey, my son, thou art gone up: he stooped down, he couched as a lion, and as an old lion; who shall rouse him up?',	'யூதா பாலசிங்கம், நீ இரை கவர்ந்துகொண்டு ஏறிப்போனாய்; என் மகனே, சிங்கம்போலும் கிழச்சிங்கம்போலும் மடங்கிப் படுத்தான்; அவனை எழுப்புகிறவன் யார்?',	1,	49,	9),
(1484,	'The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be.',	'சமாதான கர்த்தர் வருமளவும் செங்கோல் யூதாவைவிட்டு நீங்குவதும் இல்லை, நியாயப்பிரமாணிக்கன் அவன் பாதங்களை விட்டு ஒழிவதும் இல்லை; ஜனங்கள் அவரிடத்தில் சேருவார்கள்.',	1,	49,	10),
(1485,	'Binding his foal unto the vine, and his ass\'s colt unto the choice vine; he washed his garments in wine, and his clothes in the blood of grapes:',	'அவன் தன் கழுதைக்குட்டியைத் திராட்சச்செடியிலும், தன் கோளிகைக்கழுதையின் குட்டியை நற்குல திராட்சச்செடியிலும் கட்டுவான்; திராட்சரசத்திலே தன் வஸ்திரத்தையும், திராட்சப்பழங்களின் இரத்தத்திலே தன் அங்கியையும் தோய்ப்பான்.',	1,	49,	11),
(1486,	'His eyes shall be red with wine, and his teeth white with milk.',	'அவன் கண்கள் திராட்சரசத்தினால் சிவப்பாயும், அவன் பற்கள் பாலினால் வெண்மையாயும் இருக்கும்.',	1,	49,	12),
(1487,	'Zebulun shall dwell at the haven of the sea; and he shall be for an haven of ships; and his border shall be unto Zidon.',	'செபுலோன் கடல்துறை அருகே குடியிருப்பான்; அவன் கப்பல் துறைமுகமாய் இருப்பான்; அவன் எல்லை சீதோன்வரைக்கும் இருக்கும்.',	1,	49,	13),
(1488,	'Issachar is a strong ass couching down between two burdens:',	'இசக்கார் இரண்டு பொதியின் நடுவே படுத்துக்கொண்டிருக்கிற பலத்த கழுதை.',	1,	49,	14),
(1489,	'And he saw that rest was good, and the land that it was pleasant; and bowed his shoulder to bear, and became a servant unto tribute.',	'அவன், இளைப்பாறுதல் நல்லது என்றும், நாடு வசதியானது என்றும் கண்டு, சுமக்கிறதற்குத் தன் தோளைச் சாய்த்து, பகுதிகட்டுகிறவனானான்.',	1,	49,	15),
(1490,	'Dan shall judge his people, as one of the tribes of Israel.',	'தாண் இஸ்ரவேல் கோத்திரங்களில் ஒரு கோத்திரமாகி, தன் ஜனத்தை நியாயம் விசாரிப்பான்.',	1,	49,	16),
(1491,	'Dan shall be a serpent by the way, an adder in the path, that biteth the horse heels, so that his rider shall fall backward.',	'தாண், குதிரையின்மேல் ஏறியிருக்கிறவன் மல்லாந்து விழும்படியாய் அதின் குதிகாலைக் கடிக்கிறதற்கு வழியில் கிடக்கிற சர்ப்பத்தைப்போலவும், பாதையில் இருக்கிற விரியனைப்போலவும் இருப்பான்.',	1,	49,	17),
(1492,	'I have waited for thy salvation, O LORD.',	'கர்த்தாவே, உம்முடைய இரட்சிப்புக்குக் காத்திருக்கிறேன்.',	1,	49,	18),
(1493,	'Gad, a troop shall overcome him: but he shall overcome at the last.',	'காத் என்பவன்மேல் ராணுவக்கூட்டம் பாய்ந்துவிழும்; அவனோ முடிவிலே அதின்மேல் பாய்ந்துவிழுவான்.',	1,	49,	19),
(1494,	'Out of Asher his bread shall be fat, and he shall yield royal dainties.',	'ஆசேருடைய ஆகாரம் கொழுமையாயிருக்கும்; ராஜாக்களுக்கு வேண்டிய ருசிவர்க்கங்களை அவன் தருவான்.',	1,	49,	20),
(1495,	'Naphtali is a hind let loose: he giveth goodly words.',	'நப்தலி விடுதலைபெற்ற பெண்மான்; இன்பமான வசனங்களை வசனிப்பான்.',	1,	49,	21),
(1496,	'Joseph is a fruitful bough, even a fruitful bough by a well; whose branches run over the wall:',	'யோசேப்பு கனிதரும் செடி; அவன் நீர் ஊற்றண்டையிலுள்ள கனிதரும் செடி; அதின் கொடிகள் சுவரின்மேல் படரும்.',	1,	49,	22),
(1497,	'The archers have sorely grieved him, and shot at him, and hated him:',	'வில்வீரர் அவனை மனமடிவாக்கி, அவன்மேல் எய்து, அவனைப் பகைத்தார்கள்.',	1,	49,	23),
(1498,	'But his bow abode in strength, and the arms of his hands were made strong by the hands of the mighty God of Jacob; (from thence is the shepherd, the stone of Israel:)',	'ஆனாலும், அவனுடைய வில் உறுதியாய் நின்றது; அவன் புயங்கள் யாக்கோபுடைய வல்லவரின் கரங்களால் பலத்தன; இதினால் அவன் மேய்ப்பனும் இஸ்ரவேலின் கன்மலையும் ஆனான்.',	1,	49,	24),
(1499,	'Even by the God of thy father, who shall help thee; and by the Almighty, who shall bless thee with blessings of heaven above, blessings of the deep that lieth under, blessings of the breasts, and of the womb:',	'உன் தகப்பனுடைய தேவனாலே அப்படியாயிற்று, அவர் உனக்குத் துணையாயிருப்பார்; சர்வவல்லவராலே அப்படியாயிற்று, அவர் உயர வானத்திலிருந்து உண்டாகும் ஆசீர்வாதங்களினாலும், கீழே ஆழத்தில் உண்டாகும் ஆசீர்வாதங்களினாலும், ஸ்தனங்களுக்கும் கர்ப்பங்களுக்கும் உரிய ஆசீர்வாதங்களினாலும் உன்னை ஆசீர்வதிப்பார்.',	1,	49,	25),
(1500,	'The blessings of thy father have prevailed above the blessings of my progenitors unto the utmost bound of the everlasting hills: they shall be on the head of Joseph, and on the crown of the head of him that was separate from his brethren.',	'உன் தகப்பனுடைய ஆசீர்வாதங்கள் என் பிதாக்களுடைய ஆசீர்வாதங்களுக்கு மேற்பட்டதாயிருந்து, நித்திய பர்வதங்களின் முடிவுமட்டும் எட்டுகின்றன; அவைகள் யோசேப்புடைய சிரசின் மேலும், தன் சகோதரரில் விசேஷித்தவனுடைய உச்சந்தலையின்மேலும் வருவதாக.',	1,	49,	26),
(1501,	'Benjamin shall ravin as a wolf: in the morning he shall devour the prey, and at night he shall divide the spoil.',	'பென்யமீன் பீறுகிற ஓநாய்; காலையில் தன் இரையைப் பட்சிப்பான், மாலையில் தான் கொள்ளையிட்டதைப் பங்கிடுவான் என்றான்.',	1,	49,	27),
(1502,	'All these are the twelve tribes of Israel: and this is it that their father spake unto them, and blessed them; every one according to his blessing he blessed them.',	'இவர்கள் எல்லாரும் இஸ்ரவேலின் பன்னிரண்டு கோத்திரத்தார்; அவர்களுடைய தகப்பன் அவர்களை ஆசீர்வதிக்கையில், அவர்களுக்குச் சொன்னது இதுதான்; அவனவனுக்குரிய ஆசீர்வாதம் சொல்லி அவனவனை ஆசீர்வதித்தான்.',	1,	49,	28),
(1503,	'And he charged them, and said unto them, I am to be gathered unto my people: bury me with my fathers in the cave that is in the field of Ephron the Hittite,',	'பின்னும் அவன் அவர்களை நோக்கி: நான் என் ஜனத்தாரோடே சேர்க்கப்படப்போகிறேன்; ஏத்தியனான எப்பெரோனின் நிலத்திலுள்ள குகையிலே என்னை என் பிதாக்களண்டையிலே அடக்கம் பண்ணுங்கள் என்று கட்டளையிட்டு;',	1,	49,	29),
(1504,	'In the cave that is in the field of Machpelah, which is before Mamre, in the land of Canaan, which Abraham bought with the field of Ephron the Hittite for a possession of a buryingplace.',	'அந்தக் குகை கானான் தேசத்திலே மம்ரேக்கு எதிராக மக்பேலா என்னப்பட்ட நிலத்தில் இருக்கிறது; அதை நமக்குச் சொந்தக் கல்லறைப் பூமியாயிருக்கும்படி, ஆபிரகாம் ஏத்தியனாகிய எப்பெரோன் கையில் அதற்குரிய நிலத்துடனே வாங்கினார்.',	1,	49,	30),
(1505,	'There they buried Abraham and Sarah his wife; there they buried Isaac and Rebekah his wife; and there I buried Leah.',	'அங்கே ஆபிரகாமையும் அவர் மனைவியாகிய சாராளையும் அடக்கம்பண்ணினார்கள்; அங்கே ஈசாக்கையும் அவர் மனைவியாகிய ரெபெக்காளையும் அடக்கம்பண்ணினார்கள்; அங்கே லேயாளையும் அடக்கம்பண்ணினேன்.',	1,	49,	31),
(1506,	'The purchase of the field and of the cave that is therein was from the children of Heth.',	'அந்த நிலமும் அதில் இருக்கிற குகையும் ஏத்தின் புத்திரர் கையில் கொள்ளப்பட்டது என்றான்.',	1,	49,	32),
(1507,	'And when Jacob had made an end of commanding his sons, he gathered up his feet into the bed, and yielded up the ghost, and was gathered unto his people.',	'யாக்கோபு தன் குமாரருக்குக் கட்டளையிட்டு முடிந்தபின்பு, அவன் தன் கால்களைக் கட்டிலின்மேல் மடக்கிக் கொண்டு ஜீவித்துப்போய், தன் ஜனத்தாரோடே சேர்க்கப்பட்டான்.  ',	1,	49,	33),
(1508,	'And Joseph fell upon his father\'s face, and wept upon him, and kissed him.',	'அப்பொழுது யோசேப்பு தன் தகப்பனுடைய முகத்தின்மேல் விழுந்து, அழுது, அவனை முத்தஞ்செய்தான்.',	1,	50,	1),
(1509,	'And Joseph commanded his servants the physicians to embalm his father: and the physicians embalmed Israel.',	'பின்பு, தன் தகப்பனுக்குச் சுகந்தவர்க்கமிடும்படி யோசேப்பு தன் ஊழியக்காரராகிய வைத்தியருக்குக் கட்டளையிட்டான்; அப்படியே வைத்தியர் இஸ்ரவேலுக்குச் சுகந்தவர்க்கமிட்டார்கள்.',	1,	50,	2),
(1510,	'And forty days were fulfilled for him; for so are fulfilled the days of those which are embalmed: and the Egyptians mourned for him threescore and ten days.',	'சுகந்தவர்க்கமிட நாற்பதுநாள் செல்லும்; அப்படியே அந்த நாட்கள் நிறைவேறின. எகிப்தியர் அவனுக்காக எழுபதுநாள் துக்கங்கொண்டாடினார்கள்.',	1,	50,	3),
(1511,	'And when the days of his mourning were past, Joseph spake unto the house of Pharaoh, saying, If now I have found grace in your eyes, speak, I pray you, in the ears of Pharaoh, saying,',	'துக்கங்கொண்டாடும் நாட்கள் முடிந்தபின், யோசேப்பு பார்வோனின் குடும்பத்தாரை நோக்கி: உங்கள் கண்களில் எனக்குத் தயவுகிடைத்ததானால், நீங்கள் பார்வோனுடைய காது கேட்க அவருக்கு அறிவிக்கவேண்டியது என்னவென்றால்,',	1,	50,	4),
(1512,	'My father made me swear, saying, Lo, I die: in my grave which I have digged for me in the land of Canaan, there shalt thou bury me. Now therefore let me go up, I pray thee, and bury my father, and I will come again.',	'என் தகப்பனார் என்னை நோக்கி: இதோ, நான் மரணமடையப்போகிறேன்; கானான் தேசத்திலே நான் எனக்காக வெட்டிவைத்திருக்கிற கல்லறையிலே என்னை அடக்கபண்ணுவாயாக என்று என்னிடத்தில் சொல்லி, ஆணையிடுவித்துக்கொண்டார்; நான் அங்கே போய், என் தகப்பனை அடக்கம்பண்ணி வருவதற்கு உத்தரவுகொடுக்க வேண்டிக்கொள்ளுகிறேன் என்று சொல்லுங்கள் என்றான்.',	1,	50,	5),
(1513,	'And Pharaoh said, Go up, and bury thy father, according as he made thee swear.',	'அதற்குப் பார்வோன்: உன் தகப்பன் உன்னிடத்தில் ஆணையிடுவித்தபடியே, நீ போய், அவரை அடக்கம்பண்ணி வா என்றான்.',	1,	50,	6),
(1514,	'And Joseph went up to bury his father: and with him went up all the servants of Pharaoh, the elders of his house, and all the elders of the land of Egypt,',	'அப்படியே யோசேப்பு தன் தகப்பனை அடக்கம்பண்ணப் போனான். பார்வோனுடைய அரமனையிலிருந்த பெரியவர்களாகிய அவனுடைய சகல உத்தியோகஸ்தரும் எகிப்துதேசத்திலுள்ள சகல பெரியோரும்,',	1,	50,	7),
(1515,	'And all the house of Joseph, and his brethren, and his father\'s house: only their little ones, and their flocks, and their herds, they left in the land of Goshen.',	'யோசேப்பின் வீட்டார் யாவரும், அவன் சகோதரரும், அவன் தகப்பன் வீட்டாரும் அவனோடேகூடப் போனார்கள். தங்கள் குழந்தைகளையும், தங்கள் ஆடுமாடுகளையும் மாத்திரம் கோசேன் நாட்டிலே விட்டுப் போனார்கள்.',	1,	50,	8),
(1516,	'And there went up with him both chariots and horsemen: and it was a very great company.',	'இரதங்களும் குதிரைவீரரும் அவனோடே போனதினால், பரிவாரக்கூட்டம் மிகவும் அதிகமாயிருந்தது.',	1,	50,	9),
(1517,	'And they came to the threshingfloor of Atad, which is beyond Jordan, and there they mourned with a great and very sore lamentation: and he made a mourning for his father seven days.',	'அவர்கள் யோர்தானுக்கு அக்கரையில் இருக்கிற ஆத்தாத்தின் போர்க்களத்தில் வந்தபோது, அவ்விடத்திலே பெரும் புலம்பலாகப் புலம்பினார்கள். அங்கே தன் தகப்பனுக்காக ஏழுநாள் துக்கங்கொண்டாடினான்.',	1,	50,	10),
(1518,	'And when the inhabitants of the land, the Canaanites, saw the mourning in the floor of Atad, they said, This is a grievous mourning to the Egyptians: wherefore the name of it was called Abelmizraim, which is beyond Jordan.',	'ஆத்தாத்தின் களத்திலே துக்கங்கொண்டாடுகிறதை அத்தேசத்தின் குடிகளாகிய கானானியர் கண்டு: இது எகிப்தியருக்குப் பெரிய துக்கங்கொண்டாடல் என்றார்கள். அதினால் யோர்தானுக்கு அப்பால் இருக்கிற அந்த ஸ்தலத்திற்கு ஆபேல்மிஸ்ராயீம் என்னும் பேர் உண்டாயிற்று.',	1,	50,	11),
(1519,	'And his sons did unto him according as he commanded them:',	'யாக்கோபின் குமாரர், தங்களுக்குக் கட்டளையிட்டிருந்தபடியே,',	1,	50,	12),
(1520,	'For his sons carried him into the land of Canaan, and buried him in the cave of the field of Machpelah, which Abraham bought with the field for a possession of a buryingplace of Ephron the Hittite, before Mamre.',	'அவனைக் கானான் தேசத்துக்குக் கொண்டுபோய், ஆபிரகாம் மம்ரேக்கு எதிரே இருக்கிற மக்பேலா என்னும் நிலத்திலே தனக்குச் சொந்தக் கல்லறை பூமியாக ஏத்தியனாகிய எப்பெரோனிடத்தில் வாங்கின நிலத்திலுள்ள குகையிலே அவனை அடக்கம்பண்ணினார்கள்.',	1,	50,	13),
(1521,	'And Joseph returned into Egypt, he, and his brethren, and all that went up with him to bury his father, after he had buried his father.',	'யோசேப்பு தன் தகப்பனை அடக்கம்பண்ணினபின்பு, அவனும் அவன் சகோதரரும், அவனுடைய தகப்பனை அடக்கம்பண்ணுவதற்கு அவனோடேகூடப் போனவர்கள் யாவரும் எகிப்துக்குத் திரும்பினார்கள்.',	1,	50,	14),
(1522,	'And when Joseph\'s brethren saw that their father was dead, they said, Joseph will peradventure hate us, and will certainly requite us all the evil which we did unto him.',	'தங்கள் தகப்பன் மரணமடைந்ததை யோசேப்பின் சகோதரர் கண்டு: ஒரு வேளை யோசேப்பு நம்மைப் பகைத்து, நாம் அவனுக்குச் செய்த எல்லாப் பொல்லாங்குக்காகவும் நமக்குச் சரிக்குச் சரிக்கட்டுவான் என்று சொல்லி, யோசேப்பினிடத்தில் ஆள் அனுப்பி,',	1,	50,	15),
(1523,	'And they sent a messenger unto Joseph, saying, Thy father did command before he died, saying,',	'உம்முடைய சகோதரர் உமக்குப் பொல்லாங்கு செய்திருந்தாலும், அவர்கள் செய்த துரோகத்தையும் பாதகத்தையும் நீர் தயவுசெய்து மன்னிக்கவேண்டும் என்று உம்முடைய தகப்பனார் மரணமடையுமுன்னே, உமக்குச் சொல்லும்படி கட்டளையிட்டார்.',	1,	50,	16),
(1524,	'So shall ye say unto Joseph, Forgive, I pray thee now, the trespass of thy brethren, and their sin; for they did unto thee evil: and now, we pray thee, forgive the trespass of the servants of the God of thy father. And Joseph wept when they spake unto him.',	'ஆகையால், உம்முடைய தகப்பனாருடைய தேவனுக்கு ஊழியக்காரராகிய நாங்கள் செய்த துரோகத்தை மன்னிக்கவேண்டும் என்று அவனுக்குச் சொல்லச் சொன்னார்கள். அவர்கள் அதை யோசேப்புக்குச் சொன்னபோது, அவன் அழுதான்.',	1,	50,	17),
(1525,	'And his brethren also went and fell down before his face; and they said, Behold, we be thy servants.',	'பின்பு, அவனுடைய சகோதரரும் போய், அவனுக்கு முன்பாகத் தாழவிழுந்து: இதோ, நாங்கள் உமக்கு அடிமைகள் என்றார்கள்.',	1,	50,	18),
(1526,	'And Joseph said unto them, Fear not: for am I in the place of God?',	'யோசேப்பு அவர்களை நோக்கி: பயப்படாதிருங்கள்; நான் தேவனா;',	1,	50,	19),
(1527,	'But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.',	'நீங்கள் எனக்குத் தீமைசெய்ய நினைத்தீர்கள்; தேவனோ, இப்பொழுது நடந்துவருகிறபடியே, வெகு ஜனங்களை உயிரோடே காக்கும்படிக்கு, அதை நன்மையாக முடியப்பண்ணினார்.',	1,	50,	20),
(1528,	'Now therefore fear ye not: I will nourish you, and your little ones. And he comforted them, and spake kindly unto them.',	'ஆதலால், பயப்படாதிருங்கள்; நான் உங்களையும் உங்கள் குழந்தைகளையும் பராமரிப்பேன் என்று, அவர்களுக்கு ஆறுதல் சொல்லி, அவர்களோடே பட்சமாய்ப் பேசினான்.',	1,	50,	21),
(1529,	'And Joseph dwelt in Egypt, he, and his father\'s house: and Joseph lived an hundred and ten years.',	'யோசேப்பும் அவன் தகப்பன் குடும்பத்தாரும் எகிப்திலே குடியிருந்தார்கள். யோசேப்பு நூற்றுப்பத்து வருஷம் உயிரோடிருந்தான்.',	1,	50,	22),
(1530,	'And Joseph saw Ephraim\'s children of the third generation: the children also of Machir the son of Manasseh were brought up upon Joseph\'s knees.',	'யோசேப்பு எப்பிராயீமுக்குப் பிறந்த மூன்றாம் தலைமுறைப் பிள்ளைகளையும் கண்டான்; மனாசேயின் குமாரனாகிய மாகீரின் பிள்ளைகளும் யோசேப்பின் மடியில் வளர்க்கப்பட்டார்கள்.',	1,	50,	23),
(1531,	'And Joseph said unto his brethren, I die: and God will surely visit you, and bring you out of this land unto the land which he sware to Abraham, to Isaac, and to Jacob.',	'யோசேப்பு தன் சகோதரரை நோக்கி: நான் மரணமடையப்போகிறேன்; ஆனாலும் தேவன் உங்களை நிச்சயமாய்ச் சந்தித்து, நீங்கள் இந்தத் தேசத்தை விட்டு, தாம் ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் ஆணையிட்டுக் கொடுத்திருக்கிற தேசத்துக்குப் போகப்பண்ணுவார் என்று சொன்னதுமன்றி;',	1,	50,	24),
(1532,	'And Joseph took an oath of the children of Israel, saying, God will surely visit you, and ye shall carry up my bones from hence.',	'தேவன் உங்களைச் சந்திக்கும்போது, என் எலும்புகளை இவ்விடத்திலிருந்து கொண்டுபோவீர்களாக என்றும் சொல்லி; யோசேப்பு இஸ்ரவேல் புத்திரரிடத்தில் ஆணையிடுவித்துக்கொண்டான்.',	1,	50,	25),
(1533,	'So Joseph died, being an hundred and ten years old: and they embalmed him, and he was put in a coffin in Egypt.',	'யோசேப்பு நூற்றுப்பத்து வயதுள்ளவனாய் மரித்தான். அவனுக்குச் சுகந்தவர்க்கமிட்டு, எகிப்து தேசத்தில் அவனை ஒரு பெட்டியிலே வைத்துவைத்தார்கள்.    ',	1,	50,	26),
(1534,	'Now these are the names of the children of Israel, which came into Egypt; every man and his household came with Jacob.',	'எகிப்துக்குப் போன இஸ்ரவேலுடைய குமாரரின் நாமங்களாவன: ரூபன், சிமியோன், லேவி, யூதா,',	2,	1,	1),
(1535,	'Reuben, Simeon, Levi, and Judah,',	'இசக்கார், செபுலோன், பென்யமீன்,',	2,	1,	2),
(1536,	'Issachar, Zebulun, and Benjamin,',	'தாண், நப்தலி, காத், ஆசேர் என்பவைகளே.',	2,	1,	3),
(1537,	'Dan, and Naphtali, Gad, and Asher.',	'இவர்கள் யாக்கோபுடனே தங்கள்தங்கள் குடும்பத்தோடுங்கூடப் போனார்கள்.',	2,	1,	4),
(1538,	'And all the souls that came out of the loins of Jacob were seventy souls: for Joseph was in Egypt already.',	'யோசேப்போ அதற்கு முன்னமே எகிப்தில் போயிருந்தான். யாக்கோபின் கர்ப்பப்பிறப்பாகிய யாவரும் எழுபது பேர்.',	2,	1,	5),
(1539,	'And Joseph died, and all his brethren, and all that generation.',	'யோசேப்பும் அவனுடைய சகோதரர் யாவரும், அந்தத் தலைமுறையார் எல்லாரும் மரணமடைந்தார்கள்.',	2,	1,	6),
(1540,	'And the children of Israel were fruitful, and increased abundantly, and multiplied, and waxed exceeding mighty; and the land was filled with them.',	'இஸ்ரவேல் புத்திரர் மிகுதியும் பலுகி, ஏராளமாய்ப் பெருகிப் பலத்திருந்தார்கள்; தேசம் அவர்களால் நிறைந்தது.',	2,	1,	7),
(1541,	'Now there arose up a new king over Egypt, which knew not Joseph.',	'யோசேப்பை அறியாத புதிய ராஜன் ஒருவன் எகிப்தில் தோன்றினான்.',	2,	1,	8),
(1542,	'And he said unto his people, Behold, the people of the children of Israel are more and mightier than we:',	'அவன் தன் ஜனங்களை நோக்கி: இதோ, இஸ்ரவேல் புத்திரராகிய ஜனங்கள் நம்மிலும் ஏராளமானவர்களும், பலத்தவர்களுமாய் இருக்கிறார்கள்.',	2,	1,	9),
(1543,	'Come on, let us deal wisely with them; lest they multiply, and it come to pass, that, when there falleth out any war, they join also unto our enemies, and fight against us, and so get them up out of the land.',	'அவர்கள் பெருகாதபடிக்கும், ஒரு யுத்தம் உண்டானால், அவர்களும் நம்முடைய பகைஞரோடே கூடி, நமக்கு விரோதமாக யுத்தம்பண்ணி, தேசத்தைவிட்டுப் புறப்பட்டுப்போகாதபடிக்கும், நாம் அவர்களைக்குறித்து ஒரு உபாயம்பண்ணவேண்டும் என்றான்.',	2,	1,	10),
(1544,	'Therefore they did set over them taskmasters to afflict them with their burdens. And they built for Pharaoh treasure cities, Pithom and Raamses.',	'அப்படியே அவர்களைச் சுமைசுமக்கிற வேலையினால் ஒடுக்கும்படிக்கு, அவர்கள்மேல் விசாரணைக்காரரை வைத்தார்கள்; அப்பொழுது அவர்கள் பார்வோனுக்காகப் பித்தோம், ராமசேஸ் என்னும் பண்டசாலைப் பட்டணங்களைக் கட்டினார்கள்.',	2,	1,	11),
(1545,	'But the more they afflicted them, the more they multiplied and grew. And they were grieved because of the children of Israel.',	'ஆனாலும் அவர்களை எவ்வளவு ஒடுக்கினார்களோ அவ்வளவாய் அவர்கள் பலுகிப் பெருகினார்கள். ஆகையால் அவர்கள் இஸ்ரவேல் புத்திரரைக்குறித்து எரிச்சல் அடைந்தார்கள்.',	2,	1,	12),
(1546,	'And the Egyptians made the children of Israel to serve with rigour:',	'எகிப்தியர் இஸ்ரவேல் புத்திரரைக் கொடுமையாய் வேலைவாங்கினார்கள்.',	2,	1,	13),
(1547,	'And they made their lives bitter with hard bondage, in morter, and in brick, and in all manner of service in the field: all their service, wherein they made them serve, was with rigour.',	'சாந்தும் செங்கலுமாகிய இவைகளைச் செய்யும் வேலையினாலும், வயலில் செய்யும் சகலவித வேலையினாலும், அவர்களுக்கு அவர்கள் ஜீவனையும் கசப்பாக்கினார்கள்; அவர்களைக்கொண்டு செய்வித்த மற்ற எல்லா வேலைகளிலும், அவர்களைக் கொடுமையாய் நடத்தினார்கள்.',	2,	1,	14),
(1548,	'And the king of Egypt spake to the Hebrew midwives, of which the name of the one was Shiphrah, and the name of the other Puah:',	'அதுவுமன்றி, எகிப்தின் ராஜா, சிப்பிராள் பூவாள் என்னும் பேருடைய எபிரெய மருத்துவச்சிகளோடே பேசி:',	2,	1,	15),
(1549,	'And he said, When ye do the office of a midwife to the Hebrew women, and see them upon the stools; if it be a son, then ye shall kill him: but if it be a daughter, then she shall live.',	'நீங்கள் எபிரெய ஸ்திரீகளுக்கு மருத்துவம் செய்யும்போது, அவர்கள் மணையின்மேல் உட்கார்ந்திருக்கையில் பார்த்து, ஆண்பிள்ளையானால் கொன்றுபோடுங்கள், பெண்பிள்ளையானால் உயிரோடிருக்கட்டும் என்றான்.',	2,	1,	16),
(1550,	'But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive.',	'மருத்துவச்சிகளோ, தேவனுக்குப் பயந்ததினால், எகிப்தின் ராஜா தங்களுக்கு இட்ட கட்டளைப்படி செய்யாமல், ஆண்பிள்ளைகளையும் உயிரோடே காப்பாற்றினார்கள்.',	2,	1,	17),
(1551,	'And the king of Egypt called for the midwives, and said unto them, Why have ye done this thing, and have saved the men children alive?',	'அதினால் எகிப்தின் ராஜா மருத்துவச்சிகளை அழைப்பித்து: நீங்கள் ஆண்பிள்ளைகளை உயிரோடே காப்பாற்றுகிற காரியம் என்ன என்று கேட்டான்.',	2,	1,	18),
(1552,	'And the midwives said unto Pharaoh, Because the Hebrew women are not as the Egyptian women; for they are lively, and are delivered ere the midwives come in unto them.',	'அதற்கு மருத்துவச்சிகள் பார்வோனை நோக்கி: எபிரெய ஸ்திரீகள் எகிப்திய ஸ்திரீகளைப்போல் அல்ல, அவர்கள் நல்ல பலமுள்ளவர்கள்; மருத்துவச்சி அவர்களிடத்துக்குப் போகுமுன்னமே அவர்கள் பிரசவித்தாகும் என்றார்கள்.',	2,	1,	19),
(1553,	'Therefore God dealt well with the midwives: and the people multiplied, and waxed very mighty.',	'இதினிமித்தம் தேவன் மருத்துவச்சிகளுக்கு நன்மைசெய்தார். ஜனங்கள் பெருகி மிகுதியும் பலத்துப்போனார்கள்.',	2,	1,	20),
(1554,	'And it came to pass, because the midwives feared God, that he made them houses.',	'மருத்துவச்சிகள் தேவனுக்குப் பயந்ததினால், அவர்களுடைய குடும்பங்கள் தழைக்கும்படி செய்தார்.',	2,	1,	21),
(1555,	'And Pharaoh charged all his people, saying, Every son that is born ye shall cast into the river, and every daughter ye shall save alive.',	'அப்பொழுது பார்வோன், பிறக்கும் ஆண்பிள்ளைகளையெல்லாம் நதியிலே போட்டுவிடவும், பெண்பிள்ளைகளையெல்லாம் உயிரோடே வைக்கவும் தன் ஜனங்கள் எல்லாருக்கும் கட்டளையிட்டான்.  ',	2,	1,	22),
(1556,	'And there went a man of the house of Levi, and took to wife a daughter of Levi.',	'லேவியின் குடும்பத்தாரில் ஒருவன் லேவியின் குமாரத்திகளில் ஒருத்தியை விவாகம்பண்ணினான்.',	2,	2,	1),
(1557,	'And the woman conceived, and bare a son: and when she saw him that he was a goodly child, she hid him three months.',	'அந்த ஸ்திரீ கர்ப்பவதியாகி, ஒரு ஆண்பிள்ளையைப் பெற்று, அது அழகுள்ளது என்று கண்டு, அதை மூன்று மாதம் ஒளித்துவைத்தாள்.',	2,	2,	2),
(1558,	'And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river\'s brink.',	'அவள் அதை அப்புறம் ஒளித்துவைக்கக்கூடாமல், ஒரு நாணற்பெட்டியை எடுத்து, அதற்குப் பிசினும் கீலும் பூசி, அதிலே பிள்ளையை வளர்த்தி, நதியோரமாய் நாணலுக்குள்ளே வைத்தாள்.',	2,	2,	3),
(1559,	'And his sister stood afar off, to wit what would be done to him.',	'அதற்கு என்ன சம்பவிக்கும் என்பதை அறியும்படி அதின் தமக்கை தூரத்திலே நின்றுகொண்டிருந்தாள்.',	2,	2,	4),
(1560,	'And the daughter of Pharaoh came down to wash herself at the river; and her maidens walked along by the river\'s side; and when she saw the ark among the flags, she sent her maid to fetch it.',	'அப்பொழுது பார்வோனுடைய குமாரத்தி நதியில் ஸ்நானம்பண்ண வந்தாள்; அவளுடைய தாதிகள் நதியோரத்தில் உலாவினார்கள்; அவள் நாணலுக்குள்ளே இருக்கிற பெட்டியைக் கண்டு, தன் தாதியை அனுப்பி அதைக் கொண்டுவரும்படி செய்தாள்.',	2,	2,	5),
(1561,	'And when she had opened it, she saw the child: and, behold, the babe wept. And she had compassion on him, and said, This is one of the Hebrews\' children.',	'அதைத் திறந்தபோது பிள்ளையைக்கண்டாள்; பிள்ளை அழுதது; அவள் அதின்மேல் இரக்கமுற்று, இது எபிரெயர் பிள்ளைகளில் ஒன்று என்றாள்.',	2,	2,	6),
(1562,	'Then said his sister to Pharaoh\'s daughter, Shall I go and call to thee a nurse of the Hebrew women, that she may nurse the child for thee?',	'அப்பொழுது அதின் தமக்கை பார்வோனின் குமாரத்தியை நோக்கி: உமக்கு இந்தப் பிள்ளையை வளர்க்கும்படி எபிரெய ஸ்திரீகளில் பால்கொடுக்கிற ஒருத்தியை நான் போய் உம்மிடத்தில் அழைத்துக்கொண்டு வரட்டுமா என்றாள்.',	2,	2,	7),
(1563,	'And Pharaoh\'s daughter said to her, Go. And the maid went and called the child\'s mother.',	'அதற்குப் பார்வோனுடைய குமாரத்தி: அழைத்துக்கொண்டுவா என்றாள். இந்தப் பெண் போய்ப் பிள்ளையின் தாயையே அழைத்துக்கொண்டு வந்தாள்.',	2,	2,	8),
(1564,	'And Pharaoh\'s daughter said unto her, Take this child away, and nurse it for me, and I will give thee thy wages. And the women took the child, and nursed it.',	'பார்வோனுடைய குமாரத்தி அவளை நோக்கி: நீ இந்தப் பிள்ளையை எடுத்துக்கொண்டுபோய், அதை எனக்கு வளர்த்திடு, நான் உனக்குச் சம்பளம் கொடுக்கிறேன் என்றாள். அந்த ஸ்திரீ பிள்ளையை எடுத்துக்கொண்டுபோய், அதை வளர்த்தாள்.',	2,	2,	9),
(1565,	'And the child grew, and she brought him unto Pharaoh\'s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water.',	'பிள்ளை பெரிதானபோது, அவள் அதைப் பார்வோனுடைய குமாரத்தியினிடத்தில் கொண்டுபோய் விட்டாள். அவளுக்கு அவன் குமாரனானான். அவள்: அவனை ஜலத்தினின்று எடுத்தேன் என்று சொல்லி, அவனுக்கு மோசே என்று பேரிட்டாள்.',	2,	2,	10),
(1566,	'And it came to pass in those days, when Moses was grown, that he went out unto his brethren, and looked on their burdens: and he spied an Egyptian smiting an Hebrew, one of his brethren.',	'மோசே பெரியவனான காலத்தில், அவன் தன் சகோதரரிடத்தில் போய், அவர்கள் சுமைசுமக்கிறதைப் பார்த்து, தன் சகோதரராகிய எபிரெயரில் ஒருவனை ஒரு எகிப்தியன் அடிக்கிறதைக் கண்டு,',	2,	2,	11),
(1567,	'And he looked this way and that way, and when he saw that there was no man, he slew the Egyptian, and hid him in the sand.',	'அங்கும் இங்கும் பார்த்து, ஒருவரும் இல்லை என்று அறிந்து, எகிப்தியனை வெட்டி, அவனை மணலிலே புதைத்துப்போட்டான்.',	2,	2,	12),
(1568,	'And when he went out the second day, behold, two men of the Hebrews strove together: and he said to him that did the wrong, Wherefore smitest thou thy fellow?',	'அவன் மறுநாளிலும் வெளியே போனபோது, எபிரெய மனுஷர் இருவர் சண்டைபண்ணிக்கொண்டிருந்தார்கள். அப்பொழுது அவன் அநியாயஞ்செய்கிறவனை நோக்கி: நீ உன் தோழனை அடிக்கிறது என்ன என்று கேட்டான்.',	2,	2,	13),
(1569,	'And he said, Who made thee a prince and a judge over us? intendest thou to kill me, as thou killedst the Egyptian? And Moses feared, and said, Surely this thing is known.',	'அதற்கு அவன்: எங்கள்மேல் உன்னை அதிகாரியாகவும் நியாயாதிபதியாகவும் ஏற்படுத்தினவன் யார்? நீ எகிப்தியனைக் கொன்றுபோட்டதுபோல, என்னையும் கொன்றுபோட நினைக்கிறாயோ என்றான். அப்பொழுது மோசே காரியம் நிச்சயமாக வெளிப்பட்டது என்று பயந்தான்.',	2,	2,	14),
(1570,	'Now when Pharaoh heard this thing, he sought to slay Moses. But Moses fled from the face of Pharaoh, and dwelt in the land of Midian: and he sat down by a well.',	'பார்வோன் அந்தக் காரியத்தைக் கேள்விப்பட்டபோது, மோசேயைக் கொலைசெய்ய வகைதேடினான். மோசே பார்வோனிடத்தினின்று தப்பியோடி, மீதியான் தேசத்தில் போய்த் தங்கி, ஒரு துரவண்டையிலே உட்கார்ந்திருந்தான்.',	2,	2,	15),
(1571,	'Now the priest of Midian had seven daughters: and they came and drew water, and filled the troughs to water their father\'s flock.',	'மீதியான் தேசத்து ஆசாரியனுக்கு ஏழு குமாரத்திகள் இருந்தார்கள்; அவர்கள் தங்கள் தகப்பனுடைய ஆடுகளுக்குத் தண்ணீர் காட்டும்படிக்கு அங்கே வந்து, தண்ணீர் மொண்டு, தொட்டிகளை நிரப்பினார்கள்.',	2,	2,	16),
(1572,	'And the shepherds came and drove them away: but Moses stood up and helped them, and watered their flock.',	'அப்பொழுது மேய்ப்பர்கள் வந்து, அவர்களைத் துரத்தினார்கள்; மோசே எழுந்திருந்து, அவர்களுக்குத் துணை நின்று, அவர்களுடைய ஆடுகளுக்குத் தண்ணீர் காட்டினான்.',	2,	2,	17),
(1573,	'And when they came to Reuel their father, he said, How is it that ye are come so soon to day?',	'அவர்கள் தங்கள் தகப்பனாகிய ரெகுவேலிடத்தில் வந்தபோது, அவன்: நீங்கள் இன்று இத்தனை சீக்கிரமாய் வந்தது என்ன என்று கேட்டான்.',	2,	2,	18),
(1574,	'And they said, An Egyptian delivered us out of the hand of the shepherds, and also drew water enough for us, and watered the flock.',	'அதற்கு அவர்கள்: எகிப்தியன் ஒருவன் மேய்ப்பரின் கைகளுக்கு எங்களைத் தப்புவித்து, எங்களுக்குத் தண்ணீர் மொண்டு கொடுத்து, ஆடுகளுக்கும் தண்ணீர் காட்டினான் என்றார்கள்.',	2,	2,	19),
(1575,	'And he said unto his daughters, And where is he? why is it that ye have left the man? call him, that he may eat bread.',	'அப்பொழுது அவன் தன் குமாரத்திகளைப் பார்த்து, அவன் எங்கே? அந்த மனிதனை நீங்கள் விட்டுவந்தது என்ன? போஜனம்பண்ணும்படிக்கு அவனை அழைத்துக்கொண்டுவாருங்கள் என்றான்.',	2,	2,	20),
(1576,	'And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter.',	'மோசே அந்த மனிதனிடத்தில் தங்கியிருக்கச் சம்மதித்தான். அவன் சிப்போராள் என்னும் தன் குமாரத்தியை மோசேக்குக் கொடுத்தான்.',	2,	2,	21),
(1577,	'And she bare him a son, and he called his name Gershom: for he said, I have been a stranger in a strange land.',	'அவள் ஒரு குமாரனைப் பெற்றாள். நான் அந்நிய தேசத்தில் பரதேசியாய் இருக்கிறேன் என்று சொல்லி, அவனுக்கு கெர்சோம் என்று பேரிட்டான்.',	2,	2,	22),
(1578,	'And it came to pass in process of time, that the king of Egypt died: and the children of Israel sighed by reason of the bondage, and they cried, and their cry came up unto God by reason of the bondage.',	'சிலகாலம் சென்றபின், எகிப்தின் ராஜா மரித்தான். இஸ்ரவேல் புத்திரர் அடிமைத்தனத்தினால் தவித்து, முறையிட்டுக்கொண்டிருந்தார்கள்; அவர்கள் அடிமைத்தனத்திலிருந்து முறையிடும் சத்தம் தேவசந்நிதியில் எட்டினது.',	2,	2,	23),
(1579,	'And God heard their groaning, and God remembered his covenant with Abraham, with Isaac, and with Jacob.',	'தேவன் அவர்கள் பெருமூச்சைக்கேட்டு, தாம் ஆபிரகாமோடும் ஈசாக்கோடும் யாக்கோபோடும் செய்த உடன்படிக்கையை நினைவுகூர்ந்தார்.',	2,	2,	24),
(1580,	'And God looked upon the children of Israel, and God had respect unto them.',	'தேவன் இஸ்ரவேல் புத்திரரைக் கண்ணோக்கினார்; தேவன் அவர்களை நினைத்தருளினார்.  ',	2,	2,	25),
(1581,	'Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb.',	'மோசே மீதியான் தேசத்து ஆசாரியனாயிருந்த தன் மாமனாகிய எத்திரோவின் ஆடுகளை மேய்த்துவந்தான். அவன் ஆடுகளை வனாந்தரத்தின் பின்புறத்திலே ஓட்டி, தேவபர்வதமாகிய ஓரேப் மட்டும் வந்தான்.',	2,	3,	1),
(1582,	'And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed.',	'அங்கே கர்த்தருடைய தூதனானவர் ஒரு முட்செடியின் நடுவிலிருந்து உண்டான அக்கினிஜூவாலையிலே நின்று அவனுக்குத் தரிசனமானார். அப்பொழுது அவன் உற்றுப்பார்த்தான்; முட்செடி அக்கினியால் ஜூவாலித்து எரிந்தும், அது வெந்துபோகாமல் இருந்தது.',	2,	3,	2),
(1583,	'And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt.',	'அப்பொழுது மோசே: இந்த முட்செடி வெந்துபோகாதிருக்கிறது என்ன, நான் கிட்டப்போய் இந்த அற்புதக்காட்சியைப் பார்ப்பேன் என்றான்.',	2,	3,	3),
(1584,	'And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I.',	'அவன் பார்க்கும்படி கிட்ட வருகிறதைக் கர்த்தர் கண்டார். முட்செடியின் நடுவிலிருந்து தேவன் அவனை நோக்கி: மோசே, மோசே என்று கூப்பிட்டார். அவன்: இதோ, அடியேன் என்றான்.',	2,	3,	4),
(1585,	'And he said, Draw not nigh hither: put off thy shoes from off thy feet, for the place whereon thou standest is holy ground.',	'அப்பொழுது அவர்: இங்கே கிட்டிச்சேராயாக; உன் கால்களில் இருக்கிற பாதரட்சையைக் கழற்றிப்போடு; நீ நிற்கிற இடம் பரிசுத்த பூமி என்றார்.',	2,	3,	5),
(1586,	'Moreover he said, I am the God of thy father, the God of Abraham, the God of Isaac, and the God of Jacob. And Moses hid his face; for he was afraid to look upon God.',	'பின்னும் அவர்: நான் ஆபிரகாமின் தேவனும் ஈசாக்கின் தேவனும் யாக்கோபின் தேவனுமாகிய உன் பிதாக்களுடைய தேவனாயிருக்கிறேன் என்றார். மோசே தேவனை நோக்கிப்பார்க்கப் பயந்ததினால், தன் முகத்தை மூடிக்கொண்டான்.',	2,	3,	6),
(1587,	'And the LORD said, I have surely seen the affliction of my people which are in Egypt, and have heard their cry by reason of their taskmasters; for I know their sorrows;',	'அப்பொழுது கர்த்தர்: எகிப்திலிருக்கிற என் ஜனத்தின் உபத்திரவத்தை நான் பார்க்கவே பார்த்து, ஆளோட்டிகளினிமித்தம் அவர்கள் இடுகிற கூக்குரலைக் கேட்டேன், அவர்கள் படுகிற வேதனைகளையும் அறிந்திருக்கிறேன்.',	2,	3,	7),
(1588,	'And I am come down to deliver them out of the hand of the Egyptians, and to bring them up out of that land unto a good land and a large, unto a land flowing with milk and honey; unto the place of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites.',	'அவர்களை எகிப்தியரின் கைக்கு விடுதலையாக்கவும், அவர்களை அந்தத் தேசத்திலிருந்து நீக்கி, கானானியரும் ஏத்தியரும் எமோரியரும் பெரிசியரும் ஏவியரும் எபூசியரும் இருக்கிற இடமாகிய பாலும் தேனும் ஓடுகிற நலமும் விசாலமுமான தேசத்தில் கொண்டுபோய்ச் சேர்க்கவும் இறங்கினேன்.',	2,	3,	8),
(1589,	'Now therefore, behold, the cry of the children of Israel is come unto me: and I have also seen the oppression wherewith the Egyptians oppress them.',	'இப்பொழுதும் இஸ்ரவேல் புத்திரரின் கூக்குரல் என் சந்நிதியில் வந்து எட்டினது; எகிப்தியர் அவர்களை ஒடுக்குகிற ஒடுக்குதலையும் கண்டேன்.',	2,	3,	9),
(1590,	'Come now therefore, and I will send thee unto Pharaoh, that thou mayest bring forth my people the children of Israel out of Egypt.',	'நீ இஸ்ரவேல் புத்திரராகிய என் ஜனத்தை எகிப்திலிருந்து அழைத்து வரும்படி உன்னைப் பார்வோனிடத்துக்கு அனுப்புவேன் வா என்றார்.',	2,	3,	10),
(1591,	'And Moses said unto God, Who am I, that I should go unto Pharaoh, and that I should bring forth the children of Israel out of Egypt?',	'அப்பொழுது மோசே தேவனை நோக்கி: பார்வோனிடத்துக்குப் போகவும், இஸ்ரவேல் புத்திரரை எகிப்திலிருந்து அழைத்துவரவும், நான் எம்மாத்திரம் என்றான்.',	2,	3,	11),
(1592,	'And he said, Certainly I will be with thee; and this shall be a token unto thee, that I have sent thee: When thou hast brought forth the people out of Egypt, ye shall serve God upon this mountain.',	'அதற்கு அவர்: நான் உன்னோடே இருப்பேன்; நீ ஜனத்தை எகிப்திலிருந்து அழைத்துவந்தபின், நீங்கள் இந்த மலையில் தேவனுக்கு ஆராதனை செய்வீர்கள்; நான் உன்னை அனுப்பினேன் என்பதற்கு இதுவே அடையாளம் என்றார்.',	2,	3,	12),
(1593,	'And Moses said unto God, Behold, when I come unto the children of Israel, and shall say unto them, The God of your fathers hath sent me unto you; and they shall say to me, What is his name? what shall I say unto them?',	'அப்பொழுது மோசே தேவனை நோக்கி: நான் இஸ்ரவேல் புத்திரரிடத்தில் போய், உங்கள் பிதாக்களுடைய தேவன் உங்களிடத்தில் என்னை அனுப்பினார் என்று அவர்களுக்குச் சொல்லும்போது, அவருடைய நாமம் என்ன என்று அவர்கள் என்னிடத்தில் கேட்டால், நான் அவர்களுக்கு என்ன சொல்லுவேன் என்றான்.',	2,	3,	13),
(1594,	'And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.',	'அதற்குத் தேவன்: இருக்கிறவராக இருக்கிறேன் என்று மோசேயுடனே சொல்லி, இருக்கிறேன் என்பவர் என்னை உங்களிடத்துக்கு அனுப்பினார் என்று இஸ்ரவேல் புத்திரரோடே சொல்வாயாக என்றார்.',	2,	3,	14),
(1595,	'And God said moreover unto Moses, Thus shalt thou say unto the children of Israel, the LORD God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath sent me unto you: this is my name for ever, and this is my memorial unto all generations.',	'மேலும், தேவன் மோசேயை நோக்கி: ஆபிரகாமின் தேவனும் ஈசாக்கின் தேவனும் யாக்கோபின் தேவனுமாயிருக்கிற உங்கள் பிதாக்களுடைய தேவனாகிய கர்த்தர் என்னை உங்களிடத்துக்கு அனுப்பினார் என்று நீ இஸ்ரவேல் புத்திரருக்குச் சொல்வாயாக; என்றைக்கும் இதுவே என் நாமம், தலைமுறை தலைமுறைதோறும் இதுவே என் பேர்ப்பிரஸ்தாபம்.',	2,	3,	15),
(1596,	'Go, and gather the elders of Israel together, and say unto them, The LORD God of your fathers, the God of Abraham, of Isaac, and of Jacob, appeared unto me, saying, I have surely visited you, and seen that which is done to you in Egypt:',	'நீ போய், இஸ்ரவேலின் மூப்பரைக்கூட்டி, அவர்களிடத்தில்: ஆபிரகாம் ஈசாக்கு யாக்கோபு என்பவர்களுடைய தேவனாயிருக்கிற உங்கள் பிதாக்களுடைய தேவனாகிய கர்த்தர் எனக்குத் தரிசனமாகி, உங்களை நிச்சயமாய்ச் சந்தித்து, எகிப்தில் உங்களுக்குச் செய்யப்பட்டதைக் கண்டேன் என்றும்,',	2,	3,	16),
(1597,	'And I have said, I will bring you up out of the affliction of Egypt unto the land of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, unto a land flowing with milk and honey.',	'நான் உங்களை எகிப்தின் சிறுமையிலிருந்து நீக்கி, பாலும் தேனும் ஓடுகிற தேசமாகிய கானானியர் ஏத்தியர் எமோரியர் பெரிசியர் ஏவியர் எபூசியருடைய தேசத்துக்குக் கொண்டுபோவேன் என்றும் சொன்னேன் என்றார் என்று சொல்லு.',	2,	3,	17),
(1598,	'And they shall hearken to thy voice: and thou shalt come, thou and the elders of Israel, unto the king of Egypt, and ye shall say unto him, The LORD God of the Hebrews hath met with us: and now let us go, we beseech thee, three days\' journey into the wilderness, that we may sacrifice to the LORD our God.',	'அவர்கள் உன் வாக்குக்குச் செவிகொடுப்பார்கள்; அப்பொழுது நீயும் இஸ்ரவேலின் மூப்பரும் எகிப்தின் ராஜாவினிடத்தில் போய்: எபிரெயருடைய தேவனாகிய கர்த்தர் எங்களைச் சந்தித்தார்; இப்பொழுதும் நாங்கள் வனாந்தரத்தில் மூன்று நாள் பிரயாணம்போய், எங்கள் தேவனாகிய கர்த்தருக்குப் பலியிடும்படி எங்களைப் போகவிடவேண்டுமென்று சொல்லுங்கள்.',	2,	3,	18),
(1599,	'And I am sure that the king of Egypt will not let you go, no, not by a mighty hand.',	'ஆனாலும், எகிப்தின் ராஜா கைவல்லமை கண்டாலொழிய, உங்களைப் போகவிடான் என்று நான் அறிவேன்.',	2,	3,	19),
(1600,	'And I will stretch out my hand, and smite Egypt with all my wonders which I will do in the midst thereof: and after that he will let you go.',	'ஆகையால், நான் என் கையை நீட்டி, எகிப்தின் நடுவிலே நான் செய்யும் சகலவித அற்புதங்களாலும் அதை வாதிப்பேன்; அதற்குப்பின் அவன் உங்களைப் போகவிடுவான்.',	2,	3,	20),
(1601,	'And I will give this people favour in the sight of the Egyptians: and it shall come to pass, that, when ye go, ye shall not go empty.',	'அப்பொழுது இந்த ஜனங்களுக்கு எகிப்தியரின் கண்களில் தயவு கிடைக்கப்பண்ணுவேன்; நீங்கள் போகும்போது வெறுமையாய்ப் போவதில்லை.',	2,	3,	21),
(1602,	'But every woman shall borrow of her neighbour, and of her that sojourneth in her house, jewels of silver, and jewels of gold, and raiment: and ye shall put them upon your sons, and upon your daughters; and ye shall spoil the Egyptians.',	'ஒவ்வொரு ஸ்திரீயும், தன்தன் அயலகத்தாளிடத்திலும் தன்தன் வீட்டில் தங்குகிறவளிடத்திலும், வெள்ளியுடைமைகளையும் பொன்னுடைமைகளையும் வஸ்திரங்களையும் கேட்டு வாங்குவாள்; அவைகளை உங்கள் குமாரருக்கும் உங்கள் குமாரத்திகளுக்கும் தரிப்பித்து, எகிப்தியரைக் கொள்ளையிடுவீர்கள் என்றார்.  ',	2,	3,	22),
(1603,	'And Moses answered and said, But, behold, they will not believe me, nor hearken unto my voice: for they will say, The LORD hath not appeared unto thee.',	'அப்பொழுது மோசே: அவர்கள் என்னை நம்பார்கள்; என் வாக்குக்குச் செவிகொடார்கள்; கர்த்தர் உனக்குத் தரிசனமாகவில்லை என்று சொல்லுவார்கள் என்றான்.',	2,	4,	1),
(1604,	'And the LORD said unto him, What is that in thine hand? And he said, A rod.',	'கர்த்தர் அவனை நோக்கி: உன் கையிலிருக்கிறது என்ன என்றார். ஒரு கோல் என்றான்.',	2,	4,	2),
(1605,	'And he said, Cast it on the ground. And he cast it on the ground, and it became a serpent; and Moses fled from before it.',	'அதைத் தரையிலே போடு என்றார்; அவன் அதைத் தரையிலே போட்டபோது, அது சர்ப்பமாயிற்று; மோசே அதற்கு விலகியோடினான்.',	2,	4,	3),
(1606,	'And the LORD said unto Moses, Put forth thine hand, and take it by the tail. And he put forth his hand, and caught it, and it became a rod in his hand:',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: உன் கையை நீட்டி, அதின் வாலைப் பிடி என்றார்; அவன் தன் கையை நீட்டி, அதைப் பிடித்தபோது, அது அவன் கையிலே கோலாயிற்று.',	2,	4,	4),
(1607,	'That they may believe that the LORD God of their fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath appeared unto thee.',	'ஆபிரகாமின் தேவனும் ஈசாக்கின் தேவனும் யாக்கோபின் தேவனுமாயிருக்கிற தங்கள் பிதாக்களுடைய தேவனாகிய கர்த்தர் உனக்குத் தரிசனமானதை அவர்கள் நம்புவதற்கு இதுவே அடையாளம் என்றார்.',	2,	4,	5),
(1608,	'And the LORD said furthermore unto him, Put now thine hand into thy bosom. And he put his hand into his bosom: and when he took it out, behold, his hand was leprous as snow.',	'மேலும், கர்த்தர் அவனை நோக்கி: உன் கையை உன் மடியிலே போடு என்றார்; அவன் தன் கையைத் தன் மடியிலே போட்டு, அதை வெளியே எடுக்கும்போது, இதோ, அவன் கை உறைந்த மழையைப்போல வெண்குஷ்டம் பிடித்திருந்தது.',	2,	4,	6),
(1609,	'And he said, Put thine hand into thy bosom again. And he put his hand into his bosom again; and plucked it out of his bosom, and, behold, it was turned again as his other flesh.',	'அவர்: உன் கையைத் திரும்பவும் உன் மடியிலே போடு என்றார். அவன் தன் கையைத் திரும்பத் தன் மடியிலே போட்டு, தன் மடியிலிருந்து அதை வெளியே எடுத்தபோது, அது திரும்ப அவனுடைய மற்றச் சதையைப்போலாயிற்று.',	2,	4,	7),
(1610,	'And it shall come to pass, if they will not believe thee, neither hearken to the voice of the first sign, that they will believe the voice of the latter sign.',	'அப்பொழுது அவர்: முந்தின அடையாளத்தை அவர்கள் கண்டு, உன்னை நம்பாமலும் உனக்குச் செவிகொடாமலும் போனால், பிந்தின அடையாளத்தைக் கண்டு நம்புவார்கள்.',	2,	4,	8),
(1611,	'And it shall come to pass, if they will not believe also these two signs, neither hearken unto thy voice, that thou shalt take of the water of the river, and pour it upon the dry land: and the water which thou takest out of the river shall become blood upon the dry land.',	'இவ்விரண்டு அடையாளங்களையும் அவர்கள் நம்பாமலும், உன் வாக்குக்குச் செவிகொடமலும் இருப்பார்களானால், அப்பொழுது நீ நதியின் தண்ணீரை மொண்டு நிலத்தில் ஊற்றுவாயாக; நதியில் மொண்ட தண்ணீர் வெட்டாந்தரையிலே இரத்தமாகும் என்றார்.',	2,	4,	9),
(1612,	'And Moses said unto the LORD, O my LORD, I am not eloquent, neither heretofore, nor since thou hast spoken unto thy servant: but I am slow of speech, and of a slow tongue.',	'அப்பொழுது மோசே கர்த்தரை நோக்கி: ஆண்டவரே, இதற்கு முன்னாவது, தேவரீர் உமது அடியேனோடே பேசினதற்குப் பின்னாவது நான் வாக்குவல்லவன் அல்ல; நான் திக்குவாயும் மந்த நாவும் உள்ளவன் என்றான்.',	2,	4,	10),
(1613,	'And the LORD said unto him, Who hath made man\'s mouth? or who maketh the dumb, or deaf, or the seeing, or the blind? have not I the LORD?',	'அப்பொழுது கர்த்தர் அவனை நோக்கி: மனுஷனுக்கு வாயை உண்டாக்கினவர் யார்? ஊமையனையும் செவிடனையும் பார்வையுள்ளவனையும் குருடனையும் உண்டாக்கினவர் யார்? கர்த்தராகிய நான் அல்லவா?',	2,	4,	11),
(1614,	'Now therefore go, and I will be with thy mouth, and teach thee what thou shalt say.',	'ஆதலால், நீ போ; நான் உன் வாயோடே இருந்து, நீ பேசவேண்டியதை உனக்குப் போதிப்பேன் என்றார்.',	2,	4,	12),
(1615,	'And he said, O my LORD, send, I pray thee, by the hand of him whom thou wilt send.',	'அதற்கு அவன்: ஆண்டவரே. நீர் அனுப்பச் சித்தமாயிருக்கிற யாரையாகிலும் அனுப்பும் என்றான்.',	2,	4,	13),
(1616,	'And the anger of the LORD was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart.',	'அப்பொழுது கர்த்தர் மோசேயின் மேல் கோபம்மூண்டவராகி: லேவியனாகிய ஆரோன் உன் சகோதரன் அல்லவா? அவன் நன்றாய்ப் பேசுகிறவன் என்று அறிவேன்; அவன் உன்னைச் சந்திக்கப் புறப்பட்டு வருகிறான்; உன்னைக் காணும்போது அவன் இருதயம் மகிழும்.',	2,	4,	14),
(1617,	'And thou shalt speak unto him, and put words in his mouth: and I will be with thy mouth, and with his mouth, and will teach you what ye shall do.',	'நீ அவனோடே பேசி, அவன் வாயில் வார்த்தைகளைப் போடு; நான் உன் வாயிலும் அவன் வாயிலும் இருந்து, நீங்கள் செய்யவேண்டியதை உங்களுக்கு உணர்த்துவேன்.',	2,	4,	15),
(1618,	'And he shall be thy spokesman unto the people: and he shall be, even he shall be to thee instead of a mouth, and thou shalt be to him instead of God.',	'அவன் உனக்குப் பதிலாக ஜனங்களோடே பேசுவான்; இவ்விதமாய் அவன் உனக்கு வாயாக இருப்பான்; நீ அவனுக்குத் தேவனாக இருப்பாய்.',	2,	4,	16),
(1619,	'And thou shalt take this rod in thine hand, wherewith thou shalt do signs.',	'இந்தக் கோலையும் உன் கையிலே பிடித்துக்கொண்டுபோ, இதனால் நீ அடையாளங்களைச் செய்வாய் என்றார்.',	2,	4,	17),
(1620,	'And Moses went and returned to Jethro his father in law, and said unto him, Let me go, I pray thee, and return unto my brethren which are in Egypt, and see whether they be yet alive. And Jethro said to Moses, Go in peace.',	'மோசே தன் மாமனாகிய எத்திரோவினிடத்துக்கு வந்து: நான் எகிப்திலிருக்கிற என் சகோதரரிடத்துக்குத் திரும்பிப்போய், அவர்கள் இன்னும் உயிரோடே இருக்கிறார்களா என்று பார்க்கும்படிப் புறப்பட்டுப்போக உத்தரவு தரவேண்டும் என்றான். அப்பொழுது எத்திரோ மோசேயை நோக்கி: சுகமாய்ப் போய்வாரும் என்றான்.',	2,	4,	18),
(1621,	'And the LORD said unto Moses in Midian, Go, return into Egypt: for all the men are dead which sought thy life.',	'பின்னும் கர்த்தர் மீதியானிலே மோசேயை நோக்கி: நீ எகிப்துக்குத் திரும்பிப் போ, உன் பிராணனை வாங்கத்தேடின மனிதர் எல்லாரும் இறந்துபோனார்கள் என்றார்.',	2,	4,	19),
(1622,	'And Moses took his wife and his sons, and set them upon an ass, and he returned to the land of Egypt: and Moses took the rod of God in his hand.',	'அப்பொழுது மோசே தன் மனைவியையும் தன் பிள்ளைகளையும் கழுதையின் மேல் ஏற்றிக்கொண்டு, எகிப்து தேசத்துக்குத் திரும்பினான்; தேவனுடைய கோலையும் மோசே தன் கையிலே பிடித்துக்கொண்டு போனான்.',	2,	4,	20),
(1623,	'And the LORD said unto Moses, When thou goest to return into Egypt, see that thou do all those wonders before Pharaoh, which I have put in thine hand: but I will harden his heart, that he shall not let the people go.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ எகிப்திலே திரும்பிப்போய்ச் சேர்ந்தபின், நான் உன் கையில் அளித்திருக்கிற அற்புதங்கள் யாவையும் பார்வோனுக்கு முன்பாகச் செய்யும்படி எச்சரிக்கையாயிரு; ஆகிலும், நான் அவன் இருதயத்தைக் கடினப்படுத்துவேன்; அவன் ஜனத்தைப் போகவிடான்.',	2,	4,	21),
(1624,	'And thou shalt say unto Pharaoh, Thus saith the LORD, Israel is my son, even my firstborn:',	'அப்பொழுது நீ பார்வோனோடே சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேல் என்னுடைய குமாரன், என் சேஷ்டபுத்திரன்.',	2,	4,	22),
(1625,	'And I say unto thee, Let my son go, that he may serve me: and if thou refuse to let him go, behold, I will slay thy son, even thy firstborn.',	'எனக்கு ஆராதனை செய்யும்படி என் குமாரனை அனுப்பிவிடு என்று கட்டளையிடுகிறேன்; அவனை விடமாட்டேன் என்பாயாகில் நான் உன்னுடைய குமாரனை, உன் சேஷ்டபுத்திரனைச் சங்கரிப்பேன் என்று கர்த்தர் சொன்னார் என்று சொல் என்றார்.',	2,	4,	23),
(1626,	'And it came to pass by the way in the inn, that the LORD met him, and sought to kill him.',	'வழியிலே தங்கும் இடத்தில் கர்த்தர் அவனுக்கு எதிர்ப்பட்டு, அவனைக் கொல்லப்பார்த்தார்.',	2,	4,	24),
(1627,	'Then Zipporah took a sharp stone, and cut off the foreskin of her son, and cast it at his feet, and said, Surely a bloody husband art thou to me.',	'அப்பொழுது சிப்போராள் கருக்கான ஒரு கல்லை எடுத்து, தன் புத்திரனுடைய நுனித்தோலை அறுத்து, அதை அவன் கால்களுக்கு முன்பாக எறிந்து: நீர் எனக்கு இரத்தசம்பந்தமான புருஷன் என்றாள்.',	2,	4,	25),
(1628,	'So he let him go: then she said, A bloody husband thou art, because of the circumcision.',	'பின்பு அவர் அவனைவிட்டு விலகினார். அப்பொழுது அவள்: விருத்தசேதனத்தினிமித்தம் நீர் எனக்கு இரத்தசம்பந்தமான புருஷன் என்றாள்.',	2,	4,	26),
(1629,	'And the LORD said to Aaron, Go into the wilderness to meet Moses. And he went, and met him in the mount of God, and kissed him.',	'கர்த்தர் ஆரோனை நோக்கி: நீ வனாந்தரத்தில் மோசேக்கு எதிர்கொண்டுபோ என்றார். அவன் போய், தேவபர்வதத்தில் அவனைச் சந்தித்து, அவனை முத்தஞ்செய்தான்.',	2,	4,	27),
(1630,	'And Moses told Aaron all the words of the LORD who had sent him, and all the signs which he had commanded him.',	'அப்பொழுது மோசே தன்னை அனுப்பின கர்த்தருடைய சகல வார்த்தைகளையும் அவர் தனக்குக் கட்டளையிட்ட சகல அடையாளங்களையும் ஆரோனுக்குத் தெரிவித்தான்.',	2,	4,	28),
(1631,	'And Moses and Aaron went and gathered together all the elders of the children of Israel:',	'மோசேயும் ஆரோனும் போய், இஸ்ரவேல் புத்திரரின் மூப்பர் எல்லாரையும் கூடிவரச் செய்தார்கள்.',	2,	4,	29),
(1632,	'And Aaron spake all the words which the LORD had spoken unto Moses, and did the signs in the sight of the people.',	'கர்த்தர் மோசேக்குச் சொல்லிய சகல வார்த்தைகளையும் ஆரோன் சொல்லி, ஜனங்களின் கண்களுக்கு முன்பாக அந்த அடையாளங்களையும் செய்தான்.',	2,	4,	30),
(1633,	'And the people believed: and when they heard that the LORD had visited the children of Israel, and that he had looked upon their affliction, then they bowed their heads and worshipped.',	'ஜனங்கள் விசுவாசித்தார்கள்; கர்த்தர் இஸ்ரவேல் புத்திரரைச் சந்தித்தார் என்றும், அவர்கள் படும் உபத்திரவங்களைக் கண்ணோக்கிப்பார்த்தார் என்றும், அவர்கள் கேட்டபோது, தலைகுனிந்துத் தொழுதுகொண்டார்கள்.  ',	2,	4,	31),
(1634,	'And afterward Moses and Aaron went in, and told Pharaoh, Thus saith the LORD God of Israel, Let my people go, that they may hold a feast unto me in the wilderness.',	'பின்பு, மோசேயும் ஆரோனும் பார்வோனிடத்தில் போய்: இஸ்ரவேலின் தேவனாகிய கர்த்தர் வனாந்திரத்திலே எனக்குப் பண்டிகை கொண்டாடும்படி என் ஜனங்களைப் போகவிடவேண்டும் என்று சொல்லுகிறார் என்றார்கள்.',	2,	5,	1),
(1635,	'And Pharaoh said, Who is the LORD, that I should obey his voice to let Israel go? I know not the LORD, neither will I let Israel go.',	'அதற்குப் பார்வோன்: நான் இஸ்ரவேலைப் போகவிடக் கர்த்தரின் வார்த்தையைக் கேட்கிறதற்கு அவர் யார்? நான் கர்த்தரை அறியேன்; நான் இஸ்ரவேலைப் போகவிடுவதில்லை என்றான்.',	2,	5,	2),
(1636,	'And they said, The God of the Hebrews hath met with us: let us go, we pray thee, three days\' journey into the desert, and sacrifice unto the LORD our God; lest he fall upon us with pestilence, or with the sword.',	'அப்பொழுது அவர்கள்: எபிரெயருடைய தேவன் எங்களைச் சந்தித்தார்; நாங்கள் வனாந்தரத்தில் மூன்றுநாள் பிரயாணம் போய், எங்கள் தேவனாகிய கர்த்தருக்குப் பலியிடும்படி போகவிடவேண்டும்; போகாதிருந்தால், அவர் கொள்ளைநோயும் பட்டயமும் எங்கள் மேல் வரப்பண்ணுவார் என்றார்கள்.',	2,	5,	3),
(1637,	'And the king of Egypt said unto them, Wherefore do ye, Moses and Aaron, let the people from their works? get you unto your burdens.',	'எகிப்தின் ராஜா அவர்களை நோக்கி: மோசேயும் ஆரோனுமாகிய நீங்கள் ஜனங்களைத் தங்கள் வேலைகளை விட்டுக் கலையப்பண்ணுகிறது என்ன? உங்கள் சுமைகளைச் சுமக்கப்போங்கள் என்றான்.',	2,	5,	4),
(1638,	'And Pharaoh said, Behold, the people of the land now are many, and ye make them rest from their burdens.',	'பின்னும் பார்வோன்: இதோ, தேசத்தில் ஜனங்கள் மிகுதியாயிருக்கிறார்கள்; அவர்கள் சுமை சுமக்கிறதை விட்டு ஓய்ந்திருக்கும்படி செய்கிறீர்களே என்றான்.',	2,	5,	5),
(1639,	'And Pharaoh commanded the same day the taskmasters of the people, and their officers, saying,',	'அன்றியும், அந்நாளிலே பார்வோன் ஜனங்களின் ஆளோட்டிகளையும் அவர்கள் தலைவரையும் நோக்கி:',	2,	5,	6),
(1640,	'Ye shall no more give the people straw to make brick, as heretofore: let them go and gather straw for themselves.',	'செங்கல் வேலைக்கு நீங்கள் முன்போல இனி ஜனங்களுக்கு வைக்கோல் கொடுக்கவேண்டாம்; அவர்கள் தாங்களே போய்த் தங்களுக்கு வைக்கோல் சேர்க்கட்டும்.',	2,	5,	7),
(1641,	'And the tale of the bricks, which they did make heretofore, ye shall lay upon them; ye shall not diminish ought thereof: for they be idle; therefore they cry, saying, Let us go and sacrifice to our God.',	'அவர்கள் முன் செய்துகொடுத்த கணக்கின்படியே செங்கல் செய்யும்படி சொல்லுங்கள்; அதிலே நீங்கள் ஒன்றும் குறைக்கவேண்டாம், அவர்கள் சோம்பலாயிருக்கிறார்கள்; அதினால் நாங்கள் போய் எங்கள் தேவனுக்குப் பலியிடுவோம் என்று கூக்குரலிடுகிறார்கள்.',	2,	5,	8),
(1642,	'Let there more work be laid upon the men, that they may labour therein; and let them not regard vain words.',	'அந்த மனிதர்மேல் முன்னிலும் அதிக வேலையைச் சுமத்துங்கள், அதில் அவர்கள் கஷ்டப்படட்டும்; வீண்வார்த்தைகளுக்கு அவர்கள் செவிகொடுக்கவிடாதிருங்கள் என்று கட்டளையிட்டான்.',	2,	5,	9),
(1643,	'And the taskmasters of the people went out, and their officers, and they spake to the people, saying, Thus saith Pharaoh, I will not give you straw.',	'அப்பொழுது ஜனங்களின் ஆளோட்டிகளும் அவர்கள் தலைவர்களும் புறப்பட்டுப்போய் ஜனங்களை நோக்கி: உங்களுக்கு வைக்கோல் கொடுப்பதில்லை;',	2,	5,	10),
(1644,	'Go ye, get you straw where ye can find it: yet not ought of your work shall be diminished.',	'நீங்களே போய் உங்களுக்கு அகப்படுகிற இடங்களில் வைக்கோல் சம்பாதியுங்கள்; ஆனாலும் உங்கள் வேலையில் ஒன்றும் குறைக்கப்படுவதில்லை என்று பார்வோன் சொல்லுகிறார் என்றார்கள்.',	2,	5,	11),
(1645,	'So the people were scattered abroad throughout all the land of Egypt to gather stubble instead of straw.',	'அப்பொழுது வைக்கோலுக்குப் பதிலாகத் தாளடிகளைச் சேர்க்கும்படி ஜனங்கள் எகிப்துதேசம் எங்கும் சிதறிப்போனார்கள்.',	2,	5,	12),
(1646,	'And the taskmasters hasted them, saying, Fulfil your works, your daily tasks, as when there was straw.',	'ஆளோட்டிகள் அவர்களை நோக்கி: வைக்கோலிருந்த நாளில் செய்தபடியே உங்கள் வேலைகளை ஒவ்வொரு நாளிலும் செய்து முடியுங்கள் என்று சொல்லி, அவர்களைத் துரிதப்படுத்தினார்கள்.',	2,	5,	13),
(1647,	'And the officers of the children of Israel, which Pharaoh\'s taskmasters had set over them, were beaten, and demanded, Wherefore have ye not fulfilled your task in making brick both yesterday and to day, as heretofore?',	'பார்வோனுடைய ஆளோட்டிகள் இஸ்ரவேல் புத்திரர்மேல் வைத்த அவர்களுடைய தலைவர்களை நோக்கி: செங்கல் வேலையில் நீங்கள் முன்செய்ததுபோல நேற்றும் இன்றும் ஏன் செய்யவில்லை என்று கேட்டு, அவர்களை அடித்தார்கள்.',	2,	5,	14),
(1648,	'Then the officers of the children of Israel came and cried unto Pharaoh, saying, Wherefore dealest thou thus with thy servants?',	'அப்பொழுது இஸ்ரவேல் புத்திரரின் தலைவர் பார்வோனிடத்தில் போய்ச் சத்தமிட்டு: உமது அடியாருக்கு நீர் இப்படிச் செய்கிறது என்ன?',	2,	5,	15),
(1649,	'There is no straw given unto thy servants, and they say to us, Make brick: and, behold, thy servants are beaten; but the fault is in thine own people.',	'உமது அடியாருக்கு வைக்கோல் கொடாதிருந்தும், செங்கல் அறுத்துத் தீரவேண்டும் என்று எங்களுக்குச் சொல்லுகிறார்கள்; உம்முடைய ஜனங்களிடத்தில் குற்றம் இருக்க, உமது அடியாராகிய நாங்கள் அடிக்கப்படுகிறோம் என்றார்கள்.',	2,	5,	16),
(1650,	'But he said, Ye are idle, ye are idle: therefore ye say, Let us go and do sacrifice to the LORD.',	'அதற்கு அவன்: நீங்கள் சோம்பலாயிருக்கிறீர்கள், சோம்பலாயிருக்கிறீர்கள்; அதினால்தான் போகவேண்டும், கர்த்தருக்குப் பலியிடவேண்டும் என்கிறீர்கள்.',	2,	5,	17),
(1651,	'Go therefore now, and work; for there shall no straw be given you, yet shall ye deliver the tale of bricks.',	'போய், வேலை செய்யுங்கள், உங்களுக்கு வைக்கோல் கொடுக்கப்படுவதில்லை; ஆனாலும் கணக்கின்படியே நீங்கள் செங்கலை ஒப்புவிக்கவேண்டும் என்றான்.',	2,	5,	18),
(1652,	'And the officers of the children of Israel did see that they were in evil case, after it was said, Ye shall not minish ought from your bricks of your daily task.',	'நீங்கள் ஒவ்வொரு நாளிலும் அறுத்துத் தீரவேண்டிய செங்கலிலே ஒன்றும் குறைக்கப்படாது என்று சொல்லப்பட்டதினாலே, இஸ்ரவேல் புத்திரரின் தலைவர் தங்களுக்கு இக்கட்டு வந்தது என்று கண்டார்கள்.',	2,	5,	19),
(1653,	'And they met Moses and Aaron, who stood in the way, as they came forth from Pharaoh:',	'அவர்கள் பார்வோனுடைய சமுகத்தை விட்டுப் புறப்படுகையில், வழியில் நின்ற மோசேக்கும் ஆரோனுக்கும் எதிர்ப்பட்டு,',	2,	5,	20),
(1654,	'And they said unto them, The LORD look upon you, and judge; because ye have made our savour to be abhorred in the eyes of Pharaoh, and in the eyes of his servants, to put a sword in their hand to slay us.',	'அவர்களை நோக்கி: நீங்கள் பார்வோனின் கண்களுக்கு முன்பாகவும் அவருடைய ஊழியக்காரரின் கண்களுக்கு முன்பாகவும் எங்கள் வாசனையைக்கெடுத்து, எங்களைக் கொல்லும்படி அவர்கள் கையிலே பட்டயத்தைக் கொடுத்ததினிமித்தம், கர்த்தர் உங்களைப் பார்த்து நியாயந்தீர்க்கக்கடவர் என்றார்கள்.',	2,	5,	21),
(1655,	'And Moses returned unto the LORD, and said, LORD, wherefore hast thou so evil entreated this people? why is it that thou hast sent me?',	'அப்பொழுது மோசே கர்த்தரிடத்தில் திரும்பிப்போய்: ஆண்டவரே, இந்த ஜனங்களுக்குத் தீங்குவரப்பண்ணினதென்ன? ஏன் என்னை அனுப்பினீர்?',	2,	5,	22),
(1656,	'For since I came to Pharaoh to speak in thy name, he hath done evil to this people; neither hast thou delivered thy people at all.',	'நான் உமது நாமத்தைக்கொண்டு பேசும்படி பார்வோனிடத்தில் பிரவேசித்தது முதல் அவன் இந்த ஜனங்களை உபத்திரவப்படுத்துகிறான்; நீர் உம்முடைய ஜனங்களை விடுதலையாக்கவில்லையே என்றான்.  ',	2,	5,	23),
(1657,	'Then the LORD said unto Moses, Now shalt thou see what I will do to Pharaoh: for with a strong hand shall he let them go, and with a strong hand shall he drive them out of his land.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நான் பார்வோனுக்குச் செய்வதை இப்பொழுது காண்பாய்; பலத்த கையைக் கண்டு அவர்களைப் போகவிட்டு, பலத்த கையைக் கண்டு அவர்களைத் தன் தேசத்திலிருந்து துரத்திவிடுவான் என்றார்.',	2,	6,	1),
(1658,	'And God spake unto Moses, and said unto him, I am the LORD:',	'மேலும், தேவன் மோசேயை நோக்கி: நான் யேகோவா,',	2,	6,	2),
(1659,	'And I appeared unto Abraham, unto Isaac, and unto Jacob, by the name of God Almighty, but by my name JEHOVAH was I not known to them.',	'சர்வல்லமையுள்ள தேவன் என்னும் நாமத்தினால் நான் ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் தரிசனமானேன்; ஆனாலும் யேகோவா என்னும் என் நாமத்தினால் நான் அவர்களுக்கு அறியப்படவில்லை.',	2,	6,	3),
(1660,	'And I have also established my covenant with them, to give them the land of Canaan, the land of their pilgrimage, wherein they were strangers.',	'அவர்கள் பரதேசிகளாய்த் தங்கின தேசமாகிய கானான்தேசத்தை அவர்களுக்குக் கொடுப்பேன் என்று நான் அவர்களோடே என் உடன்படிக்கையையும் ஏற்படுத்தியிருக்கிறேன்.',	2,	6,	4),
(1661,	'And I have also heard the groaning of the children of Israel, whom the Egyptians keep in bondage; and I have remembered my covenant.',	'எகிப்தியர் அடிமைகொள்ளுகிற இஸ்ரவேல் புத்திரரின் பெருமூச்சையும் நான் கேட்டு, என் உடன்படிக்கையை நினைத்தேன்.',	2,	6,	5),
(1662,	'Wherefore say unto the children of Israel, I am the LORD, and I will bring you out from under the burdens of the Egyptians, and I will rid you out of their bondage, and I will redeem you with a stretched out arm, and with great judgments:',	'ஆதலால், இஸ்ரவேல் புத்திரரை நோக்கி: நானே கர்த்தர்; உங்கள்மேல் எகிப்தியர் சுமத்தின சுமைகளை நீக்கி நான் உங்களை விடுவித்து, உங்களை அவர்கள் அடிமைத்தனத்திற்கு, நீங்கலாக்கி, ஓங்கிய கையினாலும், மகா தண்டனைகளினாலும் உங்களை மீட்டு,',	2,	6,	6),
(1663,	'And I will take you to me for a people, and I will be to you a God: and ye shall know that I am the LORD your God, which bringeth you out from under the burdens of the Egyptians.',	'உங்களை எனக்கு ஜனங்களாகச் சேர்த்துக்கொண்டு, உங்களுக்கு தேவனாயிருப்பேன்; உங்கள்மேல் எகிப்தியர் சுமத்தின சுமைகளை நீக்கி உங்களை விடுவிக்கிற உங்கள் தேவனாகிய கர்த்தர் நான் என்று அறிவீர்கள்.',	2,	6,	7),
(1664,	'And I will bring you in unto the land, concerning the which I did swear to give it to Abraham, to Isaac, and to Jacob; and I will give it you for an heritage: I am the LORD.',	'ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் கொடுப்பேன் என்று நான் ஆணையிட்ட தேசத்தில் உங்களைக் கொண்டுபோய், அதை உங்களுக்குச் சுதந்தரமாகக் கொடுப்பேன்; நான் கர்த்தர் என்று அவர்களுக்குச் சொல் என்றார்.',	2,	6,	8),
(1665,	'And Moses spake so unto the children of Israel: but they hearkened not unto Moses for anguish of spirit, and for cruel bondage.',	'இந்தப்பிரகாரமாக மோசே இஸ்ரவேல் புத்திரருக்குச் சொன்னான்; அவர்களோ மனமடிவினாலும் கொடுமையான வேலையினாலும் மோசேக்குச் செவிகொடாமற்போனார்கள்.',	2,	6,	9),
(1666,	'And the LORD spake unto Moses, saying,',	'பின்பு, கர்த்தர் மோசேயை நோக்கி:',	2,	6,	10),
(1667,	'Go in, speak unto Pharaoh king of Egypt, that he let the children of Israel go out of his land.',	'நீ எகிப்தின் ராஜாவாகிய பார்வோனிடத்தில் போய், அவன் தன் தேசத்திலிருந்து இஸ்ரவேல் புத்திரரைப் போகவிடும்படி அவனோடே பேசு என்றார்.',	2,	6,	11),
(1668,	'And Moses spake before the LORD, saying, Behold, the children of Israel have not hearkened unto me; how then shall Pharaoh hear me, who am of uncircumcised lips?',	'மோசே கர்த்தருடைய சந்நிதானத்தில் நின்று, இஸ்ரவேல் புத்திரரே எனக்குச் செவிகொடுக்கவில்லை; பார்வோன் எனக்கு எப்படிச் செவிகொடுப்பான்? நான் விருத்தசேதனமில்லாத உதடுகளுள்ளவன் என்றான்.',	2,	6,	12),
(1669,	'And the LORD spake unto Moses and unto Aaron, and gave them a charge unto the children of Israel, and unto Pharaoh king of Egypt, to bring the children of Israel out of the land of Egypt.',	'கர்த்தர் மோசேயோடும் ஆரோனோடும் பேசி, இஸ்ரவேல் புத்திரரை எகிப்துதேசத்திலிருந்து அழைத்துக்கொண்டு போகும்படிக்கு, அவர்களை இஸ்ரவேல் புத்திரரிடத்துக்கும் எகிப்தின் ராஜாவாகிய பார்வோனிடத்துக்கும் கட்டளை கொடுத்து அனுப்பினார்.',	2,	6,	13),
(1670,	'These be the heads of their fathers\' houses: The sons of Reuben the firstborn of Israel; Hanoch, and Pallu, Hezron, and Carmi: these be the families of Reuben.',	'அவர்களுடைய பிதாக்கள் வீட்டாரின் தலைவர் யாரென்றால், இஸ்ரவேலுக்கு முதல் பிறந்தவனாகிய ரூபனுடைய குமாரர் ஆனோக்கு, பல்லூ, எஸ்ரோன், கர்மீ; இவர்கள் ரூபனுடைய வம்சங்களின் தலைவர்.',	2,	6,	14),
(1671,	'And the sons of Simeon; Jemuel, and Jamin, and Ohad, and Jachin, and Zohar, and Shaul the son of a Canaanitish woman: these are the families of Simeon.',	'சிமியோனின் குமாரர் எமுவேல், யாமின், ஓகாத், யாகீன், சோகார், கானானிய ஸ்திரீயின் குமாரனாகிய சவுல்; சிமியோனுடைய வம்சங்களின் தலைவர் இவர்களே.',	2,	6,	15),
(1672,	'And these are the names of the sons of Levi according to their generations; Gershon, and Kohath, and Merari: and the years of the life of Levi were an hundred thirty and seven years.',	'உற்பத்திக்கிரமப்படி பிறந்த லேவியின் குமாரருடைய நாமங்களாவன, கெர்சோன், கோகாத், மெராரி என்பவைகள். லேவி நூற்றுமுப்பத்தேழு வருஷம் உயிரோடிருந்தான்.',	2,	6,	16),
(1673,	'The sons of Gershon; Libni, and Shimi, according to their families.',	'அவரவர் வம்சங்களின்படி பிறந்த கெர்சோனின் குமாரர் லிப்னீ, சிமேயீ என்பவர்கள்.',	2,	6,	17),
(1674,	'And the sons of Kohath; Amram, and Izhar, and Hebron, and Uzziel: and the years of the life of Kohath were an hundred thirty and three years.',	'கோகாத்தின் குமாரர் அம்ராம், இத்சேயார், எப்ரோன், ஊசியேல் என்பவர்கள்; கோகாத் நூற்றுமுப்பத்துமூன்று வருஷம் உயிரோடிருந்தான்.',	2,	6,	18),
(1675,	'And the sons of Merari; Mahali and Mushi: these are the families of Levi according to their generations.',	'மெராரியின் குமாரர் மகேலி, மூசி என்பவர்கள்; அவரவர் சந்ததியின்படி லேவியினுடைய வம்சங்களின் தலைவர் இவர்களே.',	2,	6,	19),
(1676,	'And Amram took him Jochebed his father\'s sister to wife; and she bare him Aaron and Moses: and the years of the life of Amram were an hundred and thirty and seven years.',	'அம்ராம் தன் அத்தையாகிய யோகெபேத்தை விவாகம்பண்ணினான்; அவள் அவனுக்கு ஆரோனையும் மோசேயையும் பெற்றாள்; அம்ராம் நூற்றுமுப்பத்தேழு வருஷம் உயிரோடிருந்தான்.',	2,	6,	20),
(1677,	'And the sons of Izhar; Korah, and Nepheg, and Zichri.',	'இத்சேயாரின் குமாரர் கோராகு, நெப்பேக், சித்ரி என்பவர்கள்.',	2,	6,	21),
(1678,	'And the sons of Uzziel; Mishael, and Elzaphan, and Zithri.',	'ஊசியேலின் குமாரர் மீசவேல், எல்சாபான், சித்ரி என்பவர்கள்.',	2,	6,	22),
(1679,	'And Aaron took him Elisheba, daughter of Amminadab, sister of Naashon, to wife; and she bare him Nadab, and Abihu, Eleazar, and Ithamar.',	'ஆரோன் அம்மினதாபின் குமாரத்தியும் நகசோனின் சகோதரியுமாகிய எலிசபாளை விவாகம் பண்ணினான்; இவள் அவனுக்கு நாதாபையும், அபியூவையும், எலேயாசாரையும், இத்தாமாரையும் பெற்றாள்.',	2,	6,	23),
(1680,	'And the sons of Korah; Assir, and Elkanah, and Abiasaph: these are the families of the Korhites.',	'கோராகின் குமாரர் ஆசீர், எல்க்கானா, அபியாசாப் என்பவர்கள்; கோராகியரின் வம்சத்தலைவர் இவர்களே.',	2,	6,	24),
(1681,	'And Eleazar Aaron\'s son took him one of the daughters of Putiel to wife; and she bare him Phinehas: these are the heads of the fathers of the Levites according to their families.',	'ஆரோனின் குமாரனாகிய எலெயாசார் பூத்தியேலுடைய குமாரத்திகளில் ஒருத்தியை விவாகம் பண்ணினான், அவள் அவனுக்குப் பினெகாசைப் பெற்றாள்; அவரவர் வம்சங்களின்படி லேவியருடைய பிதாக்களாகிய தலைவர் இவர்களே.',	2,	6,	25),
(1682,	'These are that Aaron and Moses, to whom the LORD said, Bring out the children of Israel from the land of Egypt according to their armies.',	'இஸ்ரவேல் புத்திரரை அணியணியாய் எகிப்துதேசத்திலிருந்து நடத்திக்கொண்டு போவதற்குக் கர்த்தரால் கட்டளைபெற்ற ஆரோனும் மோசேயும் இவர்களே.',	2,	6,	26),
(1683,	'These are they which spake to Pharaoh king of Egypt, to bring out the children of Israel from Egypt: these are that Moses and Aaron.',	'இஸ்ரவேல் புத்திரரை எகிப்திலிருந்து நடத்திக்கொண்டுபோவதற்கு, எகிப்தின் ராஜாவாகிய பார்வோனோடே பேசின மோசேயும் ஆரோனும் இவர்களே.',	2,	6,	27),
(1684,	'And it came to pass on the day when the LORD spake unto Moses in the land of Egypt,',	'கர்த்தர் எகிப்துதேசத்திலே மோசேயோடே பேசின நாளில்;',	2,	6,	28),
(1685,	'That the LORD spake unto Moses, saying, I am the LORD: speak thou unto Pharaoh king of Egypt all that I say unto thee.',	'கர்த்தர் மோசேயை நோக்கி: நானே கர்த்தர்; நான் உன்னோடே சொல்லுகிறவைகளையெல்லாம் நீ எகிப்து ராஜாவாகிய பார்வோனுக்குச் சொல் என்று சொன்னபோது,',	2,	6,	29),
(1686,	'And Moses said before the LORD, Behold, I am of uncircumcised lips, and how shall Pharaoh hearken unto me?',	'மோசே கர்த்தருடைய சந்நிதானத்தில்: நான் விருத்தசேதனமில்லாத உதடுகளுள்ளவன்; பார்வோன் எனக்கு எப்படிச் செவிகொடுப்பான் என்றான்.  ',	2,	6,	30),
(1687,	'And the LORD said unto Moses, See, I have made thee a god to Pharaoh: and Aaron thy brother shall be thy prophet.',	'கர்த்தர் மோசேயை நோக்கி: பார், உன்னை நான் பார்வோனுக்கு தேவனாக்கினேன்; உன் சகோதரனாகிய ஆரோன் உன் தீர்க்கதரிசியாயிருப்பான்.',	2,	7,	1),
(1688,	'Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land.',	'நான் உனக்குக் கட்டளையிடும் யாவையும் நீ சொல்லவேண்டும்; பார்வோன் இஸ்ரவேல் புத்திரரைத் தன் தேசத்திலிருந்து அனுப்பிவிடும்படி உன் சகோதரனாகிய ஆரோன் அவனிடத்தில் பேசவேண்டும்.',	2,	7,	2),
(1689,	'And I will harden Pharaoh\'s heart, and multiply my signs and my wonders in the land of Egypt.',	'நான் பார்வோனின் இருதயத்தைக் கடினப்படுத்தி, எகிப்துதேசத்தில் என் அடையாளங்களையும் அற்புதங்களையும் மிகுதியாய் நடப்பிப்பேன்.',	2,	7,	3),
(1690,	'But Pharaoh shall not hearken unto you, that I may lay my hand upon Egypt, and bring forth mine armies, and my people the children of Israel, out of the land of Egypt by great judgments.',	'பார்வோன் உங்களுக்குச் செவிகொடுக்கமாட்டான்; ஆகையால் எகிப்துக்கு விரோதமாக நான் என் கையை நீட்டி, மகா தண்டனையினால் என் சேனைகளும் என் ஜனங்களுமாகிய இஸ்ரவேல் புத்திரரை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணுவேன்.',	2,	7,	4),
(1691,	'And the Egyptians shall know that I am the LORD, when I stretch forth mine hand upon Egypt, and bring out the children of Israel from among them.',	'நான் எகிப்தின்மேல் என் கையை நீட்டி, இஸ்ரவேல் புத்திரரை அவர்கள் நடுவிலிருந்து புறப்படப்பண்ணும்போது, நானே கர்த்தர் என்று எகிப்தியர் அறிவார்கள் என்றார்.',	2,	7,	5),
(1692,	'And Moses and Aaron did as the LORD commanded them, so did they.',	'மோசேயும் ஆரோனும் கர்த்தர் தங்களுக்குக் கட்டளையிட்டபடியே செய்தார்கள்.',	2,	7,	6),
(1693,	'And Moses was fourscore years old, and Aaron fourscore and three years old, when they spake unto Pharaoh.',	'அவர்கள் பார்வோனோடே பேசும்போது, மோசேக்கு எண்பது வயதும், ஆரோனுக்கு எண்பத்துமூன்று வயதுமாயிருந்தது.',	2,	7,	7),
(1694,	'And the LORD spake unto Moses and unto Aaron, saying,',	'கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	2,	7,	8),
(1695,	'When Pharaoh shall speak unto you, saying, Shew a miracle for you: then thou shalt say unto Aaron, Take thy rod, and cast it before Pharaoh, and it shall become a serpent.',	'உங்கள் பட்சத்திற்கு ஒரு அற்புதம் காட்டுங்கள் என்று பார்வோன் உங்களோடே சொன்னால்; அப்பொழுது நீ ஆரோனை நோக்கி: உன் கோலை எடுத்து அதைப் பார்வோனுக்கு முன்பாகப்போடு என்பாயாக; அது சர்ப்பமாகும் என்றார்.',	2,	7,	9),
(1696,	'And Moses and Aaron went in unto Pharaoh, and they did so as the LORD had commanded: and Aaron cast down his rod before Pharaoh, and before his servants, and it became a serpent.',	'மோசேயும் ஆரோனும் பார்வோனிடத்தில் போய், கர்த்தர் தங்களுக்குக் கட்டளையிட்டபடி செய்தார்கள். ஆரோன் பார்வோனுக்கு முன்பாகவும், அவன் ஊழியக்காரருக்கு முன்பாகவும் தன் கோலைப் போட்டான், அது சர்ப்பமாயிற்று.',	2,	7,	10),
(1697,	'Then Pharaoh also called the wise men and the sorcerers: now the magicians of Egypt, they also did in like manner with their enchantments.',	'அப்பொழுது பார்வோன் சாஸ்திரிகளையும் சூனியக்காரரையும் அழைப்பித்தான். எகிப்தின் மந்திரவாதிகளும் தங்கள் மந்திரவித்தையினால் அப்படிச் செய்தார்கள்.',	2,	7,	11),
(1698,	'For they cast down every man his rod, and they became serpents: but Aaron\'s rod swallowed up their rods.',	'அவர்கள் ஒவ்வொருவனாகத் தன்தன் கோலைப் போட்டபோது, அவைகள் சர்ப்பங்களாயின; ஆரோனுடைய கோலோ அவர்களுடைய கோல்களை விழுங்கிற்று.',	2,	7,	12),
(1699,	'And he hardened Pharaoh\'s heart, that he hearkened not unto them; as the LORD had said.',	'கர்த்தர் சொல்லியிருந்தபடி பார்வோனின் இருதயம் கடினப்பட்டது, அவர்களுக்குச் செவிகொடாமற் போனான்.',	2,	7,	13),
(1700,	'And the LORD said unto Moses, Pharaoh\'s heart is hardened, he refuseth to let the people go.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: பார்வோனின் இருதயம் கடினமாயிற்று; ஜனங்களை விடமாட்டேன் என்கிறான்.',	2,	7,	14),
(1701,	'Get thee unto Pharaoh in the morning; lo, he goeth out unto the water; and thou shalt stand by the river\'s brink against he come; and the rod which was turned to a serpent shalt thou take in thine hand.',	'காலமே நீ பார்வோனிடத்துக்குப் போ, அவன் நதிக்குப் புறப்பட்டு வருவான்; நீ அவனுக்கு எதிராக நதியோரத்திலே நின்று, சர்ப்பமாக மாறின கோலை உன் கையிலே பிடித்துக்கொண்டு,',	2,	7,	15),
(1702,	'And thou shalt say unto him, The LORD God of the Hebrews hath sent me unto thee, saying, Let my people go, that they may serve me in the wilderness: and, behold, hitherto thou wouldest not hear.',	'அவனை நோக்கி: வனாந்தரத்தில் எனக்கு ஆராதனைசெய்ய என் ஜனங்களை அனுப்பிவிடவேண்டும் என்று சொல்லும்படி எபிரெயருடைய தேவனாகிய கர்த்தர் என்னை உம்மிடத்துக்கு அனுப்பியும், இது வரைக்கும் நீர் கேளாமற்போனீர்.',	2,	7,	16),
(1703,	'Thus saith the LORD, In this thou shalt know that I am the LORD: behold, I will smite with the rod that is in mine hand upon the waters which are in the river, and they shall be turned to blood.',	'இதோ, என் கையில் இருக்கிற கோலினால் நதியில் இருக்கிற தண்ணீர்மேல் அடிப்பேன்; அப்பொழுது அது இரத்தமாய் மாறி,',	2,	7,	17),
(1704,	'And the fish that is in the river shall die, and the river shall stink; and the Egyptians shall lothe to drink of the water of the river.',	'நதியில் இருக்கிற மீன்கள் செத்து, நதி நாறிப்போம்; அப்பொழுது நதியில் இருக்கிற தண்ணீரை எகிப்தியர் குடிக்கக்கூடாமல் அரோசிப்பார்கள்; இதினால் நானே கர்த்தர் என்பதை அறிந்துகொள்வாய் என்று கர்த்தர் சொல்லுகிறார் என்று சொல் என்றார்.',	2,	7,	18),
(1705,	'And the LORD spake unto Moses, Say unto Aaron, Take thy rod, and stretch out thine hand upon the waters of Egypt, upon their streams, upon their rivers, and upon their ponds, and upon all their pools of water, that they may become blood; and that there may be blood throughout all the land of Egypt, both in vessels of wood, and in vessels of stone.',	'மேலும், கர்த்தர் மோசேயை நோக்கி: நீ ஆரோனிடத்தில் உன் கோலை எடுத்துக்கொண்டு எகிப்தின் நீர்நிலைகளாகிய அவர்கள் வாய்க்கால்கள்மேலும், நதிகள்மேலும், குளங்கள்மேலும், தண்ணீர் நிற்கிற எல்லா இடங்கள்மேலும், அவைகள் இரத்தமாகும்படிக்கு, உன் கையை நீட்டு; அப்பொழுது எகிப்து தேசம் எங்கும் மரப்பாத்திரங்களிலும், கற்பாத்திரங்களிலும் இரத்தம் உண்டாயிருக்கும் என்று சொல் என்றார்.',	2,	7,	19),
(1706,	'And Moses and Aaron did so, as the LORD commanded; and he lifted up the rod, and smote the waters that were in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that were in the river were turned to blood.',	'கர்த்தர் கட்டளையிட்டபடி மோசேயும் ஆரோனும் செய்தார்கள்; பார்வோனுடைய கண்களுக்கு முன்பாகவும், அவன் ஊழியக்காரரின் கண்களுக்கு முன்பாகவும் கோலை ஓங்கி, நதியிலுள்ள தண்ணீரை அடிக்க, நதியிலுள்ள தண்ணீரெல்லாம் இரத்தமாய் மாறிப்போயிற்று.',	2,	7,	20),
(1707,	'And the fish that was in the river died; and the river stank, and the Egyptians could not drink of the water of the river; and there was blood throughout all the land of Egypt.',	'நதியின் மீன்கள் செத்து, நதி நாறிப்போயிற்று; நதியின் தண்ணீரைக் குடிக்க எகிப்தியருக்குக் கூடாமற்போயிற்று; எகிப்து தேசம் எங்கும் இரத்தமாயிருந்தது.',	2,	7,	21),
(1708,	'And the magicians of Egypt did so with their enchantments: and Pharaoh\'s heart was hardened, neither did he hearken unto them; as the LORD had said.',	'எகிப்தின் மந்திரவாதிகளும் தங்கள் மந்திரவித்தையினால் அப்படிச் செய்தார்கள்; கர்த்தர் சொல்லியிருந்தபடி பார்வோனின் இருதயம் கடினப்பட்டது; அவர்களுக்குச் செவிகொடாமற்போனான்.',	2,	7,	22),
(1709,	'And Pharaoh turned and went into his house, neither did he set his heart to this also.',	'பார்வோன் இதையும் சிந்தியாமல், தன் வீட்டிற்குத் திரும்பிப்போனான்.',	2,	7,	23),
(1710,	'And all the Egyptians digged round about the river for water to drink; for they could not drink of the water of the river.',	'நதியின் தண்ணீர் குடிக்க உதவாதபடியால், குடிக்கத்தக்க தண்ணீருக்காக எகிப்தியர் எல்லாரும் நதியோரத்தில் ஊற்றுத் தோண்டினார்கள்.',	2,	7,	24),
(1711,	'And seven days were fulfilled, after that the LORD had smitten the river.',	'கர்த்தர் நதியை அடித்து ஏழுநாள் ஆயிற்று.  ',	2,	7,	25),
(1712,	'And the LORD spake unto Moses, Go unto Pharaoh, and say unto him, Thus saith the LORD, Let my people go, that they may serve me.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ பார்வோனிடத்தில் போய்: எனக்கு ஆராதனைசெய்ய என் ஜனங்களை அனுப்பிவிடு.',	2,	8,	1),
(1713,	'And if thou refuse to let them go, behold, I will smite all thy borders with frogs:',	'நீ அவர்களை அனுப்பிவிடமாட்டேன் என்பாயாகில், உன் எல்லை அடங்கலையும் தவளைகளால் வாதிப்பேன்.',	2,	8,	2),
(1714,	'And the river shall bring forth frogs abundantly, which shall go up and come into thine house, and into thy bedchamber, and upon thy bed, and into the house of thy servants, and upon thy people, and into thine ovens, and into thy kneadingtroughs:',	'நதி தவளைகளைத் திரளாய்ப் பிறப்பிக்கும்; அவைகள் உன் வீட்டிலும் உன் படுக்கை அறையிலும், உன் மஞ்சத்தின் மேலும், உன் ஊழியக்காரர் வீடுகளிலும், உன் ஜனங்களிடத்திலும், உன் அடுப்புகளிலும், மாப்பிசைகிற உன் தொட்டிகளிலும் வந்து ஏறும்.',	2,	8,	3),
(1715,	'And the frogs shall come up both on thee, and upon thy people, and upon all thy servants.',	'அந்தத் தவளைகள் உன்மேலும், உன் ஜனங்கள்மேலும், உன் ஊழியக்காரர் எல்லார்மேலும் வந்து ஏறும் என்று கர்த்தர் சொல்லுகிறார் என்று சொல் என்றார்.',	2,	8,	4),
(1716,	'And the LORD spake unto Moses, Say unto Aaron, Stretch forth thine hand with thy rod over the streams, over the rivers, and over the ponds, and cause frogs to come up upon the land of Egypt.',	'மேலும் கர்த்தர் மோசேயினிடத்தில் நீ ஆரோனை நோக்கி: நீ உன் கையில் இருக்கிற கோலை நதிகள்மேலும், வாய்க்கால்கள்மேலும், குளங்கள்மேலும் நீட்டி, எகிப்துதேசத்தின்மேல் தவளைகளை வரும்படி செய் என்று சொல் என்றார்.',	2,	8,	5),
(1717,	'And Aaron stretched out his hand over the waters of Egypt; and the frogs came up, and covered the land of Egypt.',	'அப்படியே ஆரோன் தன் கையை எகிப்திலுள்ள தண்ணீர்கள்மேல் நீட்டினான்; அப்பொழுது தவளைகள் வந்து, எகிப்து தேசத்தை மூடிக்கொண்டது.',	2,	8,	6),
(1718,	'And the magicians did so with their enchantments, and brought up frogs upon the land of Egypt.',	'மந்திரவாதிகளும் தங்கள் மந்திரவித்தையினால் அப்படிச் செய்து, எகிப்து தேசத்தின்மேல் தவளைகளை வரப்பண்ணினார்கள்.',	2,	8,	7),
(1719,	'Then Pharaoh called for Moses and Aaron, and said, Intreat the LORD, that he may take away the frogs from me, and from my people; and I will let the people go, that they may do sacrifice unto the LORD.',	'பார்வோன் மோசேயையும் ஆரோனையும் அழைப்பித்து: அந்தத் தவளைகள் என்னையும் என் ஜனங்களையும் விட்டு நீங்கும்படி கர்த்தரை நோக்கி வேண்டிக்கொள்ளுங்கள்; கர்த்தருக்குப் பலியிடும்படி ஜனங்களைப் போகவிடுவேன் என்றான்.',	2,	8,	8),
(1720,	'And Moses said unto Pharaoh, Glory over me: when shall I intreat for thee, and for thy servants, and for thy people, to destroy the frogs from thee and thy houses, that they may remain in the river only?',	'அப்பொழுது மோசே பார்வோனை நோக்கி: தவளைகள் நதியிலே மாத்திரம் இருக்கத்தக்கதாய் அவைகளை உம்மிடத்திலும் உம்முடைய வீட்டிலும் இல்லாமல் ஒழிந்துபோகும்படி செய்ய, உமக்காகவும் உம்முடைய ஊழியக்காரருக்காகவும் உம்முடைய ஜனங்களுக்காகவும் நான் விண்ணப்பம் பண்ணவேண்டிய காலத்தைக் குறிக்கும் மேன்மை உமக்கே இருப்பதாக என்றான்.',	2,	8,	9),
(1721,	'And he said, To morrow. And he said, Be it according to thy word: that thou mayest know that there is none like unto the LORD our God.',	'அதற்கு அவன்: நாளைக்கு என்றான். அப்பொழுது இவன்: எங்கள் தேவனாகிய கர்த்தருக்கு ஒப்பானவர் இல்லை என்பதை நீர் அறியும்படிக்கு உம்முடைய வார்த்தையின்படி ஆகக்கடவது.',	2,	8,	10),
(1722,	'And the frogs shall depart from thee, and from thy houses, and from thy servants, and from thy people; they shall remain in the river only.',	'தவளைகள் உம்மையும், உம்முடைய வீட்டையும், உம்முடைய ஊழியக்காரரையும், உம்முடைய ஜனங்களையும் விட்டு நீங்கி, நதியிலே மாத்திரம் இருக்கும் என்றான்.',	2,	8,	11),
(1723,	'And Moses and Aaron went out from Pharaoh: and Moses cried unto the LORD because of the frogs which he had brought against Pharaoh.',	'மோசேயும் ஆரோனும் பார்வோனை விட்டுப் புறப்பட்டார்கள். பார்வோனுக்கு விரோதமாக வரப்பண்ணின தவளைகள் நிமித்தம் மோசே கர்த்தரை நோக்கிக் கூப்பிட்டான்.',	2,	8,	12),
(1724,	'And the LORD did according to the word of Moses; and the frogs died out of the houses, out of the villages, and out of the fields.',	'கர்த்தர் மோசேயின் சொற்படி செய்தார்; வீடுகளிலும் முற்றங்களிலும் வயல்களிலும் இருந்த தவளைகள் செத்துப்போயிற்று.',	2,	8,	13),
(1725,	'And they gathered them together upon heaps: and the land stank.',	'அவைகளைக் குவியல் குவியலாகச் சேர்த்தார்கள்; அதினால் பூமியெங்கும் நாற்றம் எடுத்தது.',	2,	8,	14),
(1726,	'But when Pharaoh saw that there was respite, he hardened his heart, and hearkened not unto them; as the LORD had said.',	'இலகுவுண்டாயிற்றென்று பார்வோன் கண்டபோதோ, தன் இருதயத்தைக் கடினப்படுத்தி, அவர்களுக்குச் செவிகொடாமற்போனான்; கர்த்தர் சொல்லியிருந்தபடி ஆயிற்று.',	2,	8,	15),
(1727,	'And the LORD said unto Moses, Say unto Aaron, Stretch out thy rod, and smite the dust of the land, that it may become lice throughout all the land of Egypt.',	'அப்பொழுது கர்த்தர் மோசேயினிடத்தில்: நீ ஆரோனை நோக்கி: உன் கோலை நீட்டி, பூமியின் புழுதியின்மேல் அடி; அப்பொழுது அது எகிப்து தேசம் எங்கும் பேன்களாய்ப்போம் என்று சொல் என்றார்.',	2,	8,	16),
(1728,	'And they did so; for Aaron stretched out his hand with his rod, and smote the dust of the earth, and it became lice in man, and in beast; all the dust of the land became lice throughout all the land of Egypt.',	'அப்படியே செய்தார்கள்; ஆரோன் தன் கையில் இருந்த தன் கோலை நீட்டி, பூமியின் புழுதியின்மேல் அடித்தான்; அப்பொழுது அது மனிதர்மேலும் மிருகஜீவன்கள்மேலும் பேன்களாய் எகிப்து தேசம் எங்கும் பூமியின் புழுதியெல்லாம் பேன்களாயிற்று.',	2,	8,	17),
(1729,	'And the magicians did so with their enchantments to bring forth lice, but they could not: so there were lice upon man, and upon beast.',	'மந்திரவாதிகளும் தங்கள் மந்திரவித்தையினால் பேன்களைப் பிறப்பிக்கும்படிப் பிரயத்தனஞ்செய்தார்கள்; செய்தும், அவர்களால் கூடாமற்போயிற்று; பேன்கள் மனிதர்மேலும் மிருகஜீவன்கள்மேலும் இருந்தது.',	2,	8,	18),
(1730,	'Then the magicians said unto Pharaoh, This is the finger of God: and Pharaoh\'s heart was hardened, and he hearkened not unto them; as the LORD had said.',	'அப்பொழுது மந்திரவாதிகள் பார்வோனை நோக்கி: இது தேவனுடைய விரல் என்றார்கள். ஆனாலும், கர்த்தர் சொல்லிருந்தபடி பார்வோனுடைய இருதயம் கடினப்பட்டது; அவர்களுக்குச் செவிகொடாமற்போனான்.',	2,	8,	19),
(1731,	'And the LORD said unto Moses, Rise up early in the morning, and stand before Pharaoh; lo, he cometh forth to the water; and say unto him, Thus saith the LORD, Let my people go, that they may serve me.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நாளை அதிகாலமே நீ எழுந்து போய், பார்வோன் நதிக்குப் புறப்பட்டு வரும்போது, அவனுக்கு முன்பாக நின்று: எனக்கு ஆராதனை செய்யும்படி என் ஜனங்களைப் போகவிடு.',	2,	8,	20),
(1732,	'Else, if thou wilt not let my people go, behold, I will send swarms of flies upon thee, and upon thy servants, and upon thy people, and into thy houses: and the houses of the Egyptians shall be full of swarms of flies, and also the ground whereon they are.',	'என் ஜனங்களைப் போகவிடாயாகில், நான் உன்மேலும், உன் ஊழியக்காரர்மேலும், உன் ஜனங்கள்மேலும், உன் வீடுகள்மேலும் பலவித வண்டுகளை அனுப்புவேன்; எகிப்தியர் வீடுகளும் அவர்கள் இருக்கிற தேசமும் அந்த வண்டுகளால் நிறையும்.',	2,	8,	21),
(1733,	'And I will sever in that day the land of Goshen, in which my people dwell, that no swarms of flies shall be there; to the end thou mayest know that I am the LORD in the midst of the earth.',	'பூமியின் நடுவில் நானே கர்த்தர் என்பதை நீ அறியும்படி என் ஜனங்கள் இருக்கிற கோசேன் நாட்டில் அந்நாளிலே வண்டுகள் வராதபடிக்கு, அந்த நாட்டை விசேஷப்படுத்தி,',	2,	8,	22),
(1734,	'And I will put a division between my people and thy people: to morrow shall this sign be.',	'என் ஜனங்களுக்கும் உன் ஜனங்களுக்கும் வித்தியாசம் உண்டாகும்படி செய்வேன்; இந்த அடையாளம் நாளைக்கு உண்டாகும் என்று கர்த்தர் சொல்லுகிறார் என்று சொல் என்றார்.',	2,	8,	23),
(1735,	'And the LORD did so; and there came a grievous swarm of flies into the house of Pharaoh, and into his servants\' houses, and into all the land of Egypt: the land was corrupted by reason of the swarm of flies.',	'அப்படியே கர்த்தர் செய்தார்; மகா திரளான வண்டுஜாதிகள் பார்வோன் வீட்டிலும், அவன் ஊழியக்காரர் வீடுகளிலும், எகிப்து தேசம் முழுவதிலும் வந்தது; வண்டுகளினாலே தேசம் கெட்டுப்போயிற்று.',	2,	8,	24),
(1736,	'And Pharaoh called for Moses and for Aaron, and said, Go ye, sacrifice to your God in the land.',	'அப்பொழுது பார்வோன் மோசேயையும் ஆரோனையும் அழைப்பித்து: நீங்கள் போய், உங்கள் தேவனுக்கு தேசத்திலேதானே பலியிடுங்கள் என்றான்.',	2,	8,	25),
(1737,	'And Moses said, It is not meet so to do; for we shall sacrifice the abomination of the Egyptians to the LORD our God: lo, shall we sacrifice the abomination of the Egyptians before their eyes, and will they not stone us?',	'அதற்கு மோசே: அப்படிச் செய்யத்தகாது; எங்கள் தேவனாகிய கர்த்தருக்கு நாங்கள் எகிப்தியருடைய அருவருப்பைப் பலியிடுகிறதாயிருக்குமே, எகிப்தியருடைய அருவருப்பை நாங்கள் அவர்கள் கண்களுக்கு முன்பாகப் பலியிட்டால், எங்களைக் கல்லெறிவார்கள் அல்லவா?',	2,	8,	26),
(1738,	'We will go three days\' journey into the wilderness, and sacrifice to the LORD our God, as he shall command us.',	'நாங்கள் வனாந்தரத்தில் மூன்று நாள் பிரயாணம்போய், எங்கள் தேவனாகிய கர்த்தர் எங்களுக்கு விதிக்கிறபடியே அவருக்குப் பலியிடுவோம் என்றான்.',	2,	8,	27),
(1739,	'And Pharaoh said, I will let you go, that ye may sacrifice to the LORD your God in the wilderness; only ye shall not go very far away: intreat for me.',	'அப்பொழுது பார்வோன்: நீங்கள் உங்கள் தேவனாகிய கர்த்தருக்கு வனாந்தரத்தில் பலியிடும்படிக்கு, நான் உங்களைப் போகவிடுவேன்; ஆனாலும், நீங்கள் அதிக தூரமாய்ப் போகவேண்டாம்; எனக்காக வேண்டுதல் செய்யுங்கள் என்றான்.',	2,	8,	28),
(1740,	'And Moses said, Behold, I go out from thee, and I will intreat the LORD that the swarms of flies may depart from Pharaoh, from his servants, and from his people, to morrow: but let not Pharaoh deal deceitfully any more in not letting the people go to sacrifice to the LORD.',	'அதற்கு மோசே: நான் உம்மைவிட்டுப் புறப்பட்டபின், நாளைக்கு வண்டுகள் பார்வோனையும் அவர் ஊழியக்காரரையும் அவர் ஜனங்களையும் விட்டு நீங்கும்படி, நான் கர்த்தரை நோக்கி வேண்டுதல் செய்வேன்; ஆனாலும், கர்த்தருக்குப் பலியிடுகிறதற்கு ஜனங்களைப் போகவிடாதபடிப் பார்வோன் இனி வஞ்சனை செய்யாதிருப்பாராக என்றான்.',	2,	8,	29),
(1741,	'And Moses went out from Pharaoh, and intreated the LORD.',	'மோசே பார்வோனை விட்டுப் புறப்பட்டுப்போய், கர்த்தரை நோக்கி வேண்டுதல் செய்தான்.',	2,	8,	30),
(1742,	'And the LORD did according to the word of Moses; and he removed the swarms of flies from Pharaoh, from his servants, and from his people; there remained not one.',	'அப்பொழுது கர்த்தர் மோசேயின் சொற்படி, வண்டுஜாதிகள் பார்வோனையும் அவன் ஊழியக்காரரையும் அவன் ஜனங்களையும் விட்டு நீங்கும்படி செய்தார்; ஒன்றாகிலும் மீந்திருக்கவில்லை.',	2,	8,	31),
(1743,	'And Pharaoh hardened his heart at this time also, neither would he let the people go.',	'பார்வோனோ, இந்த முறையும் தன் இருதயத்தைக் கடினப்படுத்தி, ஜனங்களைப் போகவிடாதிருந்தான்.  ',	2,	8,	32),
(1744,	'Then the LORD said unto Moses, Go in unto Pharaoh, and tell him, Thus saith the LORD God of the Hebrews, Let my people go, that they may serve me.',	'பின்பு, கர்த்தர் மோசேயை நோக்கி: நீ பார்வோனிடத்தில் போய்: எனக்கு ஆராதனைசெய்ய என் ஜனங்களைப் போகவிடு.',	2,	9,	1),
(1745,	'For if thou refuse to let them go, and wilt hold them still,',	'நீ அவர்களை விடமாட்டேன் என்று இன்னும் நிறுத்திவைத்தாயாகில்,',	2,	9,	2),
(1746,	'Behold, the hand of the LORD is upon thy cattle which is in the field, upon the horses, upon the asses, upon the camels, upon the oxen, and upon the sheep: there shall be a very grievous murrain.',	'கர்த்தருடைய கரம் வெளியிலிருக்கிற உன் மிருகஜீவன்களாகிய குதிரைகளின்மேலும் கழுதைகளின்மேலும் ஒட்டகங்களின்மேலும் ஆடுமாடுகளின் மேலும் இருக்கும்; மகா கொடிதான கொள்ளை நோய் உண்டாகும்.',	2,	9,	3),
(1747,	'And the LORD shall sever between the cattle of Israel and the cattle of Egypt: and there shall nothing die of all that is the children\'s of Israel.',	'கர்த்தர் இஸ்ரவேலின் மிருகஜீவன்களுக்கும் எகிப்தியரின் மிருகஜீவன்களுக்கும் வித்தியாசம் பண்ணுவார்; இஸ்ரவேல் புத்திரருக்கு உரியவைகள் எல்லாவற்றிலும் ஒன்றும் சாவதில்லை என்றார்.',	2,	9,	4),
(1748,	'And the LORD appointed a set time, saying, To morrow the LORD shall do this thing in the land.',	'மேலும், நாளைக்குக் கர்த்தர் இந்தக் காரியத்தை தேசத்தில் செய்வார் என்று சொல்லி, கர்த்தர் ஒரு காலத்தைக் குறித்தார் என்றும், எபிரெயருடைய தேவனாகிய கர்த்தர் சொல்லுகிறார் என்றும் அவனிடத்தில் சொல் என்றார்.',	2,	9,	5),
(1749,	'And the LORD did that thing on the morrow, and all the cattle of Egypt died: but of the cattle of the children of Israel died not one.',	'மறுநாளில் கர்த்தர் அந்தக் காரியத்தைச் செய்தார்; எகிப்தியருடைய மிருகஜீவன்கள் எல்லாம் செத்துப்போயிற்று; இஸ்ரவேல் புத்திரரின் மிருகஜீவன்களில் ஒன்றாகிலும் சாகவில்லை.',	2,	9,	6),
(1750,	'And Pharaoh sent, and, behold, there was not one of the cattle of the Israelites dead. And the heart of Pharaoh was hardened, and he did not let the people go.',	'பார்வோன் விசாரித்து, இஸ்ரவேலரின் மிருகஜீவன்களில் ஒன்றாகிலும் சாகவில்லை என்று அறிந்தான். பார்வோனுடைய இருதயமோ கடினப்பட்டது; அவன் ஜனங்களைப் போகவிடவில்லை.',	2,	9,	7),
(1751,	'And the LORD said unto Moses and unto Aaron, Take to you handfuls of ashes of the furnace, and let Moses sprinkle it toward the heaven in the sight of Pharaoh.',	'அப்பொழுது கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி: உங்கள் கைப்பிடி நிறைய சூளையின் சாம்பலை அள்ளிக்கொள்ளுங்கள்; மோசே அதைப் பார்வோனுடைய கண்களுக்குமுன் வானத்திற்கு நேராக இறைக்கக்கடவன்.',	2,	9,	8),
(1752,	'And it shall become small dust in all the land of Egypt, and shall be a boil breaking forth with blains upon man, and upon beast, throughout all the land of Egypt.',	'அது எகிப்து தேசம் மீதெங்கும் தூசியாகி, எகிப்து தேசமெங்கும் மனிதர்மேலும் மிருகஜீவன்கள்மேலும் எரிபந்தமான கொப்புளங்களை எழும்பப்பண்ணும் என்றார்.',	2,	9,	9),
(1753,	'And they took ashes of the furnace, and stood before Pharaoh; and Moses sprinkled it up toward heaven; and it became a boil breaking forth with blains upon man, and upon beast.',	'அப்படியே அவர்கள் சூளையின் சாம்பலை அள்ளிக்கொண்டு, பார்வோனுக்கு முன்பாக வந்து நின்றார்கள். மோசே அதை வானத்துக்கு நேராக இறைத்தான்; அப்பொழுது மனிதர்மேலும் மிருகஜீவன்கள்மேலும் எரிபந்தமான கொப்புளங்கள் எழும்பிற்று.',	2,	9,	10),
(1754,	'And the magicians could not stand before Moses because of the boils; for the boil was upon the magicians, and upon all the Egyptians.',	'அந்தக் கொப்புளங்கள் மந்திரவாதிகள்மேலும் எகிப்தியர் எல்லார்மேலும் உண்டானதினால், அந்தக் கொப்புளங்களின் நிமித்தம் மந்திரவாதிகளும் மோசேக்கு முன்பாக நிற்கக்கூடாதிருந்தது.',	2,	9,	11),
(1755,	'And the LORD hardened the heart of Pharaoh, and he hearkened not unto them; as the LORD had spoken unto Moses.',	'ஆனாலும், கர்த்தர் மோசேயோடே சொல்லியிருந்தபடியே, கர்த்தர் பார்வோனின் இருதயத்தைக் கடினப்படுத்தினார்; அவன் அவர்களுக்குச் செவிகொடுக்கவில்லை.',	2,	9,	12),
(1756,	'And the LORD said unto Moses, Rise up early in the morning, and stand before Pharaoh, and say unto him, Thus saith the LORD God of the Hebrews, Let my people go, that they may serve me.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ அதிகாலமே எழுந்திருந்து போய், பார்வோனுக்கு முன்பாக நின்று: எனக்கு ஆராதனைசெய்ய என் ஜனங்களை அனுப்பிவிடு.',	2,	9,	13),
(1757,	'For I will at this time send all my plagues upon thine heart, and upon thy servants, and upon thy people; that thou mayest know that there is none like me in all the earth.',	'விடாதிருந்தால், பூமியெங்கும் என்னைப்போல் வேறொருவரும் இல்லை என்பதை நீ அறியும்படிக்கு, இந்தமுறை நான் சகலவித வாதைகளையும் உன் இருதயத்திலும், உன் ஊழியக்காரர்மேலும் உன் ஜனங்கள்மேலும் அனுப்புவேன்.',	2,	9,	14),
(1758,	'For now I will stretch out my hand, that I may smite thee and thy people with pestilence; and thou shalt be cut off from the earth.',	'நீ பூமியில் இராமல் நாசமாய்ப்போகும்படி நான் என் கையை நீட்டி, உன்னையும் உன் ஜனங்களையும் கொள்ளை நோயினால் வாதிப்பேன்.',	2,	9,	15),
(1759,	'And in very deed for this cause have I raised thee up, for to shew in thee my power; and that my name may be declared throughout all the earth.',	'என்னுடைய வல்லமையை உன்னிடத்தில் காண்பிக்கும்படியாகவும், என் நாமம் பூமியிலெங்கும் பிரஸ்தாபமாகும்படியாகவும் உன்னை நிலைநிறுத்தினேன்.',	2,	9,	16),
(1760,	'As yet exaltest thou thyself against my people, that thou wilt not let them go?',	'நீ என் ஜனங்களைப் போகவிடாமல், இன்னும் அவர்களுக்கு விரோதமாய் உன்னை உயர்த்துகிறாயா?',	2,	9,	17),
(1761,	'Behold, to morrow about this time I will cause it to rain a very grievous hail, such as hath not been in Egypt since the foundation thereof even until now.',	'எகிப்து தோன்றிய நாள்முதல் இதுவரைக்கும் அதில் பெய்யாத மிகவும் கொடிய கல்மழையை நாளை இந்நேரம் பெய்யப்பண்ணுவேன்.',	2,	9,	18),
(1762,	'Send therefore now, and gather thy cattle, and all that thou hast in the field; for upon every man and beast which shall be found in the field, and shall not be brought home, the hail shall come down upon them, and they shall die.',	'இப்பொழுதே ஆள் அனுப்பி, உன் மிருகஜீவன்களையும் வெளியில் உனக்கு இருக்கிற யாவையும் சேர்த்துக்கொள்; வீட்டிலே சேர்க்கப்படாமல் வெளியிலிருக்கும் ஒவ்வொரு மனிதனும் மிருகமும் செத்துப்போகத்தக்கதாய் அந்தக் கல்மழை பெய்யும் என்று எபிரெயரின் தேவனாகிய கர்த்தர் சொல்லுகிறார் என்று அவனுக்குச் சொல் என்றார்.',	2,	9,	19),
(1763,	'He that feared the word of the LORD among the servants of Pharaoh made his servants and his cattle flee into the houses:',	'பார்வோனுடைய ஊழியக்காரரில் எவன் கர்த்தருடைய வார்த்தைக்குப் பயப்பட்டானோ, அவன் தன் வேலைக்காரரையும் தன் மிருகஜீவன்களையும் வீடுகளுக்கு ஓடிவரப்பண்ணினான்.',	2,	9,	20),
(1764,	'And he that regarded not the word of the LORD left his servants and his cattle in the field.',	'எவன் கர்த்தருடைய வார்த்தையை மதியாமற்போனானோ, அவன் தன் வேலைக்காரரையும் தன் மிருகஜீவன்களையும் வெளியிலே விட்டுவிட்டான்.',	2,	9,	21),
(1765,	'And the LORD said unto Moses, Stretch forth thine hand toward heaven, that there may be hail in all the land of Egypt, upon man, and upon beast, and upon every herb of the field, throughout the land of Egypt.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: எகிப்து தேசம் எங்கும் மனிதர்மேலும் மிருகஜீவன்கள்மேலும் எகிப்து தேசத்திலிருக்கிற சகலவிதமான பயிர் வகைகள்மேலும் கல்மழை பெய்ய, உன் கையை வானத்திற்கு நேராக நீட்டு என்றார்.',	2,	9,	22),
(1766,	'And Moses stretched forth his rod toward heaven: and the LORD sent thunder and hail, and the fire ran along upon the ground; and the LORD rained hail upon the land of Egypt.',	'அப்படியே மோசே தன் கோலை வானத்திற்கு நேராக நீட்டினான். அப்பொழுது கர்த்தர் இடிமுழக்கங்களையும் கல்மழையையும் அனுப்பினார்; அக்கினி தரையின்மேல் வேகமாய் ஓடிற்று; எகிப்து தேசத்தின்மேல் கர்த்தர் கல்மழையைப் பெய்யப்பண்ணினார்;',	2,	9,	23),
(1767,	'So there was hail, and fire mingled with the hail, very grievous, such as there was none like it in all the land of Egypt since it became a nation.',	'கல்மழையும் கல்மழையோடே கலந்த அக்கினியும் மிகவும் கொடிதாயிருந்தது; எகிப்து தேசம் குடியேற்றப்பட்ட நாள்முதல் அதில் அப்படி ஒருபோதும் உண்டானதில்லை.',	2,	9,	24),
(1768,	'And the hail smote throughout all the land of Egypt all that was in the field, both man and beast; and the hail smote every herb of the field, and brake every tree of the field.',	'எகிப்து தேசம் எங்கும் மனிதரையும் மிருகஜீவன்களையும், வெளியிலே இருந்தவைகள் எவைகளோ அவைகள் எல்லாவற்றையும் அந்தக் கல்மழை அழித்துப்போட்டது; அது வெளியின் பயிர்வகைகளையெல்லாம் அழித்து, வெளியின் மரங்களையெல்லாம் முறித்துப்போட்டது.',	2,	9,	25),
(1769,	'Only in the land of Goshen, where the children of Israel were, was there no hail.',	'இஸ்ரவேல் புத்திரர் இருந்த கோசேன் நாட்டிலே மாத்திரம் கல்மழை இல்லாதிருந்தது.',	2,	9,	26),
(1770,	'And Pharaoh sent, and called for Moses and Aaron, and said unto them, I have sinned this time: the LORD is righteous, and I and my people are wicked.',	'அப்பொழுது பார்வோன் மோசேயையும் ஆரோனையும் அழைப்பித்து: நான் இந்த முறை பாவம் செய்தேன்; கர்த்தர் நீதியுள்ளவர்; நானும் என் ஜனமும் துன்மார்க்கர்.',	2,	9,	27),
(1771,	'Intreat the LORD (for it is enough) that there be no more mighty thunderings and hail; and I will let you go, and ye shall stay no longer.',	'இது போதும்; இந்த மகா இடிமுழக்கங்களும் கல்மழையும் ஒழியும்படிக்கு, கர்த்தரை நோக்கி விண்ணப்பம்பண்ணுங்கள்; நான் உங்களைப் போகவிடுவேன், இனி உங்களுக்குத் தடையில்லை என்றான்.',	2,	9,	28),
(1772,	'And Moses said unto him, As soon as I am gone out of the city, I will spread abroad my hands unto the LORD; and the thunder shall cease, neither shall there be any more hail; that thou mayest know how that the earth is the LORD\'s.',	'மோசே அவனை நோக்கி: நான் பட்டணத்திலிருந்து புறப்பட்டவுடனே, என் கைகளைக் கர்த்தருக்கு நேராக விரிப்பேன்; அப்பொழுது இடிமுழக்கங்கள் ஓய்ந்து கல்மழை நின்றுபோகும்; அதினால் பூமி கர்த்தருடையது என்பதை நீர் அறிவீர்.',	2,	9,	29),
(1773,	'But as for thee and thy servants, I know that ye will not yet fear the LORD God.',	'ஆகிலும் நீரும் உம்முடைய ஊழியக்காரரும் இன்னும் தேவனாகிய கர்த்தருக்குப் பயப்படமாட்டீர்கள் என்பதை அறிவேன் என்றான்.',	2,	9,	30),
(1774,	'And the flax and the barley was smitten: for the barley was in the ear, and the flax was bolled.',	'அப்பொழுது வாற்கோதுமை கதிர்ப்பயிரும் சணல் தாள்ப்பயிருமாயிருந்தது; அதினால் சணலும் வாற்கோதுமையும் அழிக்கப்பட்டுப்போயிற்று.',	2,	9,	31),
(1775,	'But the wheat and the rie were not smitten: for they were not grown up.',	'கோதுமையும் கம்பும் கதிர்விடாதிருந்ததால், அவைகள் அழிக்கப்படவில்லை.',	2,	9,	32),
(1776,	'And Moses went out of the city from Pharaoh, and spread abroad his hands unto the LORD: and the thunders and hail ceased, and the rain was not poured upon the earth.',	'மோசே பார்வோனைவிட்டுப் பட்டணத்திலிருந்து புறப்பட்டு, தன் கைகளைக் கர்த்தருக்கு நேராக விரித்தான்; அப்பொழுது இடிமுழக்கமும் கல்மழையும் நின்றது; மழையும் பூமியில் பெய்யாமலிருந்தது.',	2,	9,	33),
(1777,	'And when Pharaoh saw that the rain and the hail and the thunders were ceased, he sinned yet more, and hardened his heart, he and his servants.',	'மழையும் கல்மழையும் இடிமுழக்கமும் நின்றுபோனதைப் பார்வோன் கண்டபோது, அவனும் அவன் ஊழியக்காரரும் பின்னும் பாவம்செய்து, தங்கள் இருதயத்தைக் கடினப்படுத்தினார்கள்.',	2,	9,	34),
(1778,	'And the heart of Pharaoh was hardened, neither would he let the children of Israel go; as the LORD had spoken by Moses.',	'கர்த்தர் மோசேயைக்கொண்டு சொல்லியிருந்தபடியே, பார்வோனின் இருதயம் கடினப்பட்டது; அவன் இஸ்ரவேல் புத்திரரைப் போகவிடவில்லை.  ',	2,	9,	35),
(1779,	'And the LORD said unto Moses, Go in unto Pharaoh: for I have hardened his heart, and the heart of his servants, that I might shew these my signs before him:',	'பின்பு கர்த்தர் மோசேயை நோக்கி: நீ பார்வோனிடத்தில் போ, அவர்கள் நடுவே நான் இந்த என் அடையாளங்களைச் செய்யும்படிக்கும்,',	2,	10,	1),
(1780,	'And that thou mayest tell in the ears of thy son, and of thy son\'s son, what things I have wrought in Egypt, and my signs which I have done among them; that ye may know how that I am the LORD.',	'நான் எகிப்திலே நடப்பித்ததையும் நான் அவர்களுக்குள் செய்த என் அடையாளங்களையும், நீ உன் பிள்ளைகளின் செவிகள் கேட்கவும், உன் பிள்ளைகளுடைய பிள்ளைகளின் செவிகள் கேட்கவும் விவரித்துச் சொல்லும்படிக்கும், நானே கர்த்தர் என்பதை நீங்கள் அறியும்படிக்கும், நான் அவன் இருதயத்தையும் அவன் ஊழியக்காரரின் இருதயத்தையும் கடினப்படுத்தினேன் என்றார்.',	2,	10,	2),
(1781,	'And Moses and Aaron came in unto Pharaoh, and said unto him, Thus saith the LORD God of the Hebrews, How long wilt thou refuse to humble thyself before me? let my people go, that they may serve me.',	'அப்படியே மோசேயும் ஆரோனும் பார்வோனிடத்தில் வந்து: உன்னைத் தாழ்த்த நீ எதுவரைக்கும் மனதில்லாதிருப்பாய்? என் சமுகத்தில் எனக்கு ஆராதனைசெய்ய என் ஜனங்களைப் போகவிடு.',	2,	10,	3),
(1782,	'Else, if thou refuse to let my people go, behold, to morrow will I bring the locusts into thy coast:',	'நீ என் ஜனங்களைப் போகவிடமாட்டேன் என்பாயாகில், நான் நாளைக்கு உன் எல்லைகளுக்குள்ளே வெட்டுக்கிளிகளை வரப்பண்ணுவேன்.',	2,	10,	4),
(1783,	'And they shall cover the face of the earth, that one cannot be able to see the earth: and they shall eat the residue of that which is escaped, which remaineth unto you from the hail, and shall eat every tree which groweth for you out of the field:',	'தரை காணாதபடிக்கு அவைகள் பூமியின் முகத்தை மூடி, கல்மழைக்குத் தப்பி மீதியாக வைக்கப்பட்டதைப் பட்சித்து, வெளியிலே துளிர்க்கிற செடிகளையெல்லாம் தின்றுபோடும்.',	2,	10,	5),
(1784,	'And they shall fill thy houses, and the houses of all thy servants, and the houses of all the Egyptians; which neither thy fathers, nor thy fathers\' fathers have seen, since the day that they were upon the earth unto this day. And he turned himself, and went out from Pharaoh.',	'உன் வீடுகளும் உன் ஊழியக்காரருடைய வீடுகளும் எகிப்தியரின் வீடுகளும் எல்லாம் அவைகளால் நிரம்பும்; உன் பிதாக்களும் உன் பிதாக்களின் பிதாக்களும் தாங்கள் பூமியில் தோன்றின நாள்முதல் இந்நாள்வரைக்கும் அப்படிப் பட்டவைகளைக் கண்டதில்லை என்று எபிரெயரின் தேவனாகிய கர்த்தர் சொல்லுகிறார் என்று சொல்லி, திரும்பிக்கொண்டு பார்வோனை விட்டுப் புறப்பட்டான்.',	2,	10,	6),
(1785,	'And Pharaoh\'s servants said unto him, How long shall this man be a snare unto us? let the men go, that they may serve the LORD their God: knowest thou not yet that Egypt is destroyed?',	'அப்பொழுது பார்வோனுடைய ஊழியக்காரர் அவனை நோக்கி: எந்தமட்டும் இந்த மனிதன் நமக்குக் கண்ணியாயிருப்பான்? தங்கள் தேவனாகிய கர்த்தருக்கு ஆராதனைசெய்ய அந்த மனிதரைப் போகவிடும்; எகிப்து அழிந்துபோனதை நீர் இன்னும் அறியவில்லையா என்றார்கள்.',	2,	10,	7),
(1786,	'And Moses and Aaron were brought again unto Pharaoh: and he said unto them, Go, serve the LORD your God: but who are they that shall go?',	'அப்பொழுது மோசேயும் ஆரோனும் பார்வோனிடத்துக்குத் திரும்ப அழைக்கப்பட்டார்கள். அவன் அவர்களை நோக்கி: நீங்கள் போய் உங்கள் தேவனாகிய கர்த்தருக்கு ஆராதனை செய்யுங்கள் என்று சொல்லி, யாரார் போகிறார்கள் என்று கேட்டான்.',	2,	10,	8),
(1787,	'And Moses said, We will go with our young and with our old, with our sons and with our daughters, with our flocks and with our herds will we go; for we must hold a feast unto the LORD.',	'அதற்கு மோசே: எங்கள் இளைஞரோடும், எங்கள் முதியோரோடும், எங்கள் குமாரரோடும், எங்கள் குமாரத்திகளோடும், எங்கள் ஆடுகளையும் எங்கள் மாடுகளையும் கூட்டிக்கொண்டுபோவோம்; நாங்கள் கர்த்தருக்குப் பண்டிகை கொண்டாடவேண்டும் என்றான்.',	2,	10,	9),
(1788,	'And he said unto them, Let the LORD be so with you, as I will let you go, and your little ones: look to it; for evil is before you.',	'அப்பொழுது அவன்: நான் உங்களையும் உங்கள் குழந்தைகளையும் எப்படி விடுவேனோ, அப்படியே கர்த்தர் உங்களோடிருப்பாராக; எச்சரிக்கையாயிருங்கள், உங்களுக்குப் பொல்லாப்பு நேரிடும்;',	2,	10,	10),
(1789,	'Not so: go now ye that are men, and serve the LORD; for that ye did desire. And they were driven out from Pharaoh\'s presence.',	'அப்படி வேண்டாம்; புருஷராகிய நீங்கள் போய், கர்த்தருக்கு ஆராதனை செய்யுங்கள்; இதுதானே நீங்கள் விரும்பிக் கேட்டது என்று சொன்னான். அவர்கள் பார்வோன் சமுகத்தினின்று துரத்தி விடப்பட்டார்கள்.',	2,	10,	11),
(1790,	'And the LORD said unto Moses, Stretch out thine hand over the land of Egypt for the locusts, that they may come up upon the land of Egypt, and eat every herb of the land, even all that the hail hath left.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: வெட்டுக்கிளிகள் எகிப்து தேசத்தின்மேல் வந்து கல்மழையினால் அழியாத பூமியின் பயிர்வகைகளையெல்லாம் பட்சிக்கும்படிக்கு, எகிப்து தேசத்தின்மேல் உன் கையை நீட்டு என்றார்.',	2,	10,	12),
(1791,	'And Moses stretched forth his rod over the land of Egypt, and the LORD brought an east wind upon the land all that day, and all that night; and when it was morning, the east wind brought the locusts.',	'அப்படியே மோசே தன் கோலை எகிப்து தேசத்தின்மேல் நீட்டினான்; அப்பொழுது கர்த்தர் அன்று பகல் முழுவதும் அன்று இராமுழுவதும் கீழ்காற்றைத் தேசத்தின்மேல் வீசப்பண்ணினார்; விடியற்காலத்திலே கீழ்காற்று வெட்டுக்கிளிகளைக் கொண்டுவந்தது.',	2,	10,	13),
(1792,	'And the locust went up over all the land of Egypt, and rested in all the coasts of Egypt: very grievous were they; before them there were no such locusts as they, neither after them shall be such.',	'வெட்டுக்கிளிகள் எகிப்து தேசம் எங்கும் பரம்பி, எகிப்தின் எல்லையில் எங்கும் மிகவும் ஏராளமாய் இறங்கிற்று; அப்படிப்பட்ட வெட்டுக்கிளிகள் அதற்குமுன் இருந்ததும் இல்லை, அதற்குப்பின் இருப்பதும் இல்லை.',	2,	10,	14),
(1793,	'For they covered the face of the whole earth, so that the land was darkened; and they did eat every herb of the land, and all the fruit of the trees which the hail had left: and there remained not any green thing in the trees, or in the herbs of the field, through all the land of Egypt.',	'அவைகள் பூமியின் முகம் முழுவதையும் மூடிற்று; தேசம் அவைகளால் அந்தகாரப்பட்டது; கல்மழைக்குத் தப்பியிருந்த நிலத்தின் பயிர்வகைகள் யாவையும் மரங்களின் கனிகள் யாவையும் அவைகள் பட்சித்துப்போட்டது; எகிப்து தேசம் எங்குமுள்ள மரங்களிலும் வயல்வெளியின் பயிர்வகைகளிலும் ஒரு பச்சிலையும் மீதியாயிருக்கவில்லை.',	2,	10,	15),
(1794,	'Then Pharaoh called for Moses and Aaron in haste; and he said, I have sinned against the LORD your God, and against you.',	'அப்பொழுது பார்வோன் மோசேயையும் ஆரோனையும் தீவிரமாய் அழைப்பித்து: உங்கள் தேவனாகிய கர்த்தருக்கும் உங்களுக்கும் விரோதமாகப் பாவம் செய்தேன்.',	2,	10,	16),
(1795,	'Now therefore forgive, I pray thee, my sin only this once, and intreat the LORD your God, that he may take away from me this death only.',	'இந்த ஒரு முறைமாத்திரம் நீ என் பாவத்தை மன்னிக்கவேண்டும்; உங்கள் தேவனாகிய கர்த்தர் இந்தச் சாவைமாத்திரம் என்னைவிட்டு விலக்க அவரை நோக்கி விண்ணப்பம்பண்ணுங்கள் என்றான்.',	2,	10,	17),
(1796,	'And he went out from Pharaoh, and intreated the LORD.',	'அவன் பார்வோனை விட்டுப் புறப்பட்டுப்போய், கர்த்தரை நோக்கி விண்ணப்பம்பண்ணினான்.',	2,	10,	18),
(1797,	'And the LORD turned a mighty strong west wind, which took away the locusts, and cast them into the Red sea; there remained not one locust in all the coasts of Egypt.',	'அப்பொழுது கர்த்தர் மகா பலத்த மேல்காற்றை வீசும்படி செய்தார்; அது வெட்டுக்கிளிகளை அடித்துக்கொண்டுபோய் செங்கடலிலே போட்டது; எகிப்தின் எல்லையில் எங்கும் ஒரு வெட்டுகிளியாகிலும் மீதியாயிருந்ததில்லை.',	2,	10,	19),
(1798,	'But the LORD hardened Pharaoh\'s heart, so that he would not let the children of Israel go.',	'கர்த்தரோ பார்வோனின் இருதயத்தைக் கடினப்படுத்தினார்; அவன் இஸ்ரவேல் புத்திரரைப் போகவிடவில்லை.',	2,	10,	20),
(1799,	'And the LORD said unto Moses, Stretch out thine hand toward heaven, that there may be darkness over the land of Egypt, even darkness which may be felt.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: தடவிக்கொண்டிருக்கத்தக்கதான இருள் எகிப்து தேசத்தின்மேல் உண்டாகும்படிக்கு, உன் கையை வானத்திற்கு நேராக நீட்டு என்றார்.',	2,	10,	21),
(1800,	'And Moses stretched forth his hand toward heaven; and there was a thick darkness in all the land of Egypt three days:',	'மோசே தன் கையை வானத்திற்கு நேராக நீட்டினான்; அப்பொழுது எகிப்து தேசம் எங்கும் மூன்றுநாள் மட்டும் காரிருள் உண்டாயிற்று.',	2,	10,	22),
(1801,	'They saw not one another, neither rose any from his place for three days: but all the children of Israel had light in their dwellings.',	'மூன்றுநாள் மட்டும் ஒருவரை ஒருவர் காணவும் இல்லை, ஒருவரும் தம்மிடத்தைவிட்டு எழுந்திருக்கவும் இல்லை; இஸ்ரவேல் புத்திரர் யாவருக்குமோவெனில் அவர்கள் வாசஸ்தலங்களிலே வெளிச்சம் இருந்தது.',	2,	10,	23),
(1802,	'And Pharaoh called unto Moses, and said, Go ye, serve the LORD; only let your flocks and your herds be stayed: let your little ones also go with you.',	'அப்பொழுது பார்வோன் மோசேயை அழைப்பித்து; நீங்கள் போய்க் கர்த்தருக்கு ஆராதனை செய்யுங்கள்; உங்கள் ஆடுகளும் உங்கள் மாடுகளும்மாத்திரம் நிறுத்தப்படவேண்டும்; உங்கள் குழந்தைகள் உங்களுடன் போகலாம் என்றான்.',	2,	10,	24),
(1803,	'And Moses said, Thou must give us also sacrifices and burnt offerings, that we may sacrifice unto the LORD our God.',	'அதற்கு மோசே: நாங்கள் எங்கள் தேவனாகிய கர்த்தருக்குப் படைக்கும் பலிகளையும் சர்வாங்க தகனபலிகளையும் நீர் எங்கள் கையிலே கொடுக்கவேண்டும்.',	2,	10,	25),
(1804,	'Our cattle also shall go with us; there shall not an hoof be left behind; for thereof must we take to serve the LORD our God; and we know not with what we must serve the LORD, until we come thither.',	'எங்கள் மிருகஜீவன்களும் எங்களோடேகூட வரவேண்டும்; ஒரு குளம்பும் பின்வைக்கப்படுவதில்லை; எங்கள் தேவனாகிய கர்த்தருக்கு ஆராதனை செய்கிறதற்கு அவைகளிலிருந்து எடுக்கவேண்டும்; இன்னதைக்கொண்டு கர்த்தருக்கு ஆராதனை செய்வோம் என்பது நாங்கள் அங்கே போய்ச் சேருமளவும் எங்களுக்குத் தெரியாது என்றான்.',	2,	10,	26),
(1805,	'But the LORD hardened Pharaoh\'s heart, and he would not let them go.',	'கர்த்தர் பார்வோனுடைய இருதயத்தைக் கடினப்படுத்தினார்; அவன் அவர்களைப் போகவிட மனதில்லாதிருந்தான்.',	2,	10,	27),
(1806,	'And Pharaoh said unto him, Get thee from me, take heed to thyself, see my face no more; for in that day thou seest my face thou shalt die.',	'பார்வோன் அவனை நோக்கி: என்னை விட்டு அப்பாலே போ; நீ இனி என் முகத்தைக் காணாதபடி எச்சரிக்கையாயிரு; நீ இனி என் முகத்தைக் காணும் நாளில் சாவாய் என்றான்.',	2,	10,	28),
(1807,	'And Moses said, Thou hast spoken well, I will see thy face again no more.',	'அப்பொழுது மோசே: நீர் சொன்னது சரி; இனி நான் உம்முடைய முகத்தைக் காண்பதில்லை என்றான்.  ',	2,	10,	29),
(1808,	'And the LORD said unto Moses, Yet will I bring one plague more upon Pharaoh, and upon Egypt; afterwards he will let you go hence: when he shall let you go, he shall surely thrust you out hence altogether.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: இன்னும் ஒரு வாதையைப் பார்வோன்மேலும் எகிப்தின்மேலும் வரப்பண்ணுவேன்; அதற்குப்பின் அவன் உங்களை இவ்விடத்திலிருந்து போகவிடுவான்; சமூலமாய் உங்களைப் போகவிடுவதும் அல்லாமல், உங்களை இவ்விடத்திலிருந்து துரத்தியும் விடுவான்.',	2,	11,	1),
(1809,	'Speak now in the ears of the people, and let every man borrow of his neighbour, and every woman of her neighbour, jewels of silver and jewels of gold.',	'இப்பொழுது ஒவ்வொருவனும் அவனவன் அயலானிடத்திலும், ஒவ்வொருத்தியும் அவளவள் அயலாளிடத்திலும் வெள்ளியுடைமைகளையும் பொன்னுடைமைகளையும் கேட்கும்படி ஜனங்களுக்குச் சொல் என்றார்.',	2,	11,	2),
(1810,	'And the LORD gave the people favour in the sight of the Egyptians. Moreover the man Moses was very great in the land of Egypt, in the sight of Pharaoh\'s servants, and in the sight of the people.',	'அப்படியே கர்த்தர் ஜனங்களுக்கு எகிப்தியரின் கண்களில் தயவுகிடைக்கும்படி செய்தார். மோசே என்பவன் எகிப்து தேசத்தில் பார்வோனுடைய ஊழியக்காரரின் பார்வைக்கும் ஜனங்களின் பார்வைக்கும் மிகவும் பெரியவனாயிருந்தான்.',	2,	11,	3),
(1811,	'And Moses said, Thus saith the LORD, About midnight will I go out into the midst of Egypt:',	'அப்பொழுது மோசே: கர்த்தர் நடுராத்திரியிலே நான் எகிப்தின் மத்தியில் புறப்பட்டுப்போவேன்.',	2,	11,	4),
(1812,	'And all the firstborn in the land of Egypt shall die, from the first born of Pharaoh that sitteth upon his throne, even unto the firstborn of the maidservant that is behind the mill; and all the firstborn of beasts.',	'அப்பொழுது சிங்காசனத்தின்மேல் வீற்றிருக்கும் பார்வோனுடைய தலைப்பிள்ளைமுதல் எந்திரம் அரைக்கும் அடிமைப்பெண்ணுடைய தலைப்பிள்ளைவரைக்கும், எகிப்து தேசத்திலிருக்கிற முதற்பேறனைத்தும் மிருகஜீவன்களின் தலையீற்றனைத்தும் சாகும் என்று உரைக்கிறார் என்று சொன்னதுமன்றி,',	2,	11,	5),
(1813,	'And there shall be a great cry throughout all the land of Egypt, such as there was none like it, nor shall be like it any more.',	'அதினால் எகிப்து தேசம் எங்கும் முன்னும் பின்னும் ஒருக்காலும் உண்டாகாத பெரிய கூக்குரல் உண்டாகும்.',	2,	11,	6),
(1814,	'But against any of the children of Israel shall not a dog move his tongue, against man or beast: that ye may know how that the LORD doth put a difference between the Egyptians and Israel.',	'ஆனாலும் கர்த்தர் எகிப்தியருக்கும் இஸ்ரவேலருக்கும் பண்ணுகிற வித்தியாசத்தை நீங்கள் அறியும்படிக்கு, இஸ்ரவேல் புத்திரர் அனைவருக்குள்ளும் மனிதர்முதல் மிருகஜீவன்கள் வரைக்கும் ஒரு நாயாகிலும் தன் நாவை அசைப்பதில்லை.',	2,	11,	7),
(1815,	'And all these thy servants shall come down unto me, and bow down themselves unto me, saying, Get thee out, and all the people that follow thee: and after that I will go out. And he went out from Pharaoh in a great anger.',	'அப்பொழுது உம்முடைய ஊழியக்காரராகிய இவர்கள் எல்லாரும் என்னிடத்தில் வந்து, பணிந்து. நீயும் உன்னைப் பின்பற்றுகிறவர்கள் யாவரும் புறப்பட்டுப்போங்கள் என்று சொல்லுவார்கள்; அதின்பின் புறப்படுவேன் என்று சொல்லி, உக்கிரமான கோபத்தோடே பார்வோனை விட்டுப் புறப்பட்டான்.',	2,	11,	8),
(1816,	'And the LORD said unto Moses, Pharaoh shall not hearken unto you; that my wonders may be multiplied in the land of Egypt.',	'கர்த்தர் மோசேயை நோக்கி: எகிப்து தேசத்தில் என் அற்புதங்கள் அநேகமாகும்படிக்கு, பார்வோன் உங்களுக்குச் செவிகொடுக்கமாட்டான் என்று சொல்லியிருந்தார்.',	2,	11,	9),
(1817,	'And Moses and Aaron did all these wonders before Pharaoh: and the LORD hardened Pharaoh\'s heart, so that he would not let the children of Israel go out of his land.',	'மோசேயும் ஆரோனும் இந்த அற்புதங்களையெல்லாம் பார்வோனுக்கு முன்பாகச் செய்தார்கள். கர்த்தர் பார்வோனின் இருதயத்தைக் கடினப்படுத்தினதினால், அவன் இஸ்ரவேல் புத்திரரைத் தன் தேசத்திலிருந்து போகவிடவில்லை.  ',	2,	11,	10),
(1818,	'And the LORD spake unto Moses and Aaron in the land of Egypt saying,',	'கர்த்தர் எகிப்து தேசத்தில் மோசேயையும் ஆரோனையும் நோக்கி:',	2,	12,	1),
(1819,	'This month shall be unto you the beginning of months: it shall be the first month of the year to you.',	'இந்த மாதம் உங்களுக்குப் பிரதான மாதம்; இது உங்களுக்கு வருஷத்தின் முதலாம் மாதமாயிருப்பதாக.',	2,	12,	2),
(1820,	'Speak ye unto all the congregation of Israel, saying, In the tenth day of this month they shall take to them every man a lamb, according to the house of their fathers, a lamb for an house:',	'நீங்கள் இஸ்ரவேல் சபையார் யாவரையும் நோக்கி: இந்த மாதம் பத்தாம் தேதியில் வீட்டுத்தலைவர்கள், வீட்டுக்கு ஒரு ஆட்டுக்குட்டியாக, ஒவ்வொருவரும் ஒவ்வொரு ஆட்டுக்குட்டியைத் தெரிந்து கொள்ளக்கடவர்கள்.',	2,	12,	3),
(1821,	'And if the household be too little for the lamb, let him and his neighbour next unto his house take it according to the number of the souls; every man according to his eating shall make your count for the lamb.',	'ஒரு வீட்டில் இருக்கிறவர்கள் ஒரு ஆட்டுக்குட்டியைப் புசிக்கிறதற்குப் போதுமான பேர்களாயிராமற்போனால், அவனும் அவன் சமீபத்திலிருக்கிற அவனுடைய அயல்வீட்டுக்காரனும், தங்களிடத்திலுள்ள ஆத்துமாக்களின் இலக்கத்திற்குத்தக்கதாக ஒரு ஆட்டுக்குட்டியைத் தெரிந்துகொள்ளவேண்டும்; அவனவன் புசிப்புக்குத்தக்கதாக இலக்கம் பார்த்து, ஆட்டுக்குட்டியைத் தெரிந்து கொள்ளவேண்டும்.',	2,	12,	4),
(1822,	'Your lamb shall be without blemish, a male of the first year: ye shall take it out from the sheep, or from the goats:',	'அந்த ஆட்டுக்குட்டி பழுதற்றதும் ஆணும் ஒருவயதுள்ளதுமாய் இருக்கவேண்டும்; செம்மறியாடுகளிலாவது வெள்ளாடுகளிலாவது அதைத் தெரிந்து கொள்ளலாம்.',	2,	12,	5),
(1823,	'And ye shall keep it up until the fourteenth day of the same month: and the whole assembly of the congregation of Israel shall kill it in the evening.',	'அதை இந்த மாதம் பதினாலாம் தேதிவரைக்கும் வைத்திருந்து, இஸ்ரவேல் சபையின் ஒவ்வொரு கூட்டத்தாரும் சாயங்காலத்தில் அதை அடித்து,',	2,	12,	6),
(1824,	'And they shall take of the blood, and strike it on the two side posts and on the upper door post of the houses, wherein they shall eat it.',	'அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, தாங்கள் அதைப் புசிக்கும் வீட்டுவாசல் நிலைக்கால்கள் இரண்டிலும் நிலையின் மேற்சட்டத்திலும் தெளித்து,',	2,	12,	7),
(1825,	'And they shall eat the flesh in that night, roast with fire, and unleavened bread; and with bitter herbs they shall eat it.',	'அன்று ராத்திரியிலே அதின் மாம்சத்தை நெருப்பினால் சுட்டு, புளிப்பில்லா அப்பத்தோடும் கசப்பான கீரையோடும் அதைப் புசிக்கக்கடவர்கள்.',	2,	12,	8),
(1826,	'Eat not of it raw, nor sodden at all with water, but roast with fire; his head with his legs, and with the purtenance thereof.',	'பச்சையாயும் தண்ணீரில் அவிக்கப்பட்டதாயும் அல்ல; அதின் தலையையும் அதின் தொடைகளையும் அதற்குள்ள யாவையும் ஏகமாய் நெருப்பினால் சுட்டதாய் அதைப் புசிப்பீர்களாக.',	2,	12,	9),
(1827,	'And ye shall let nothing of it remain until the morning; and that which remaineth of it until the morning ye shall burn with fire.',	'அதிலே ஒன்றையும் விடியற்காலம் மட்டும் மீதியாக வைக்காமல், விடியற்காலம் மட்டும் அதிலே மீதியாய் இருக்கிறதை அக்கினியால் சுட்டெரிப்பீர்களாக.',	2,	12,	10),
(1828,	'And thus shall ye eat it; with your loins girded, your shoes on your feet, and your staff in your hand; and ye shall eat it in haste: it is the LORD\'s passover.',	'அதைப் புசிக்கவேண்டிய விதமாவது, நீங்கள் உங்கள் அரைகளில் கச்சை கட்டிக்கொண்டும், உங்கள் கால்களில் பாதரட்சை தொடுத்துக்கொண்டும், உங்கள் கையில் தடி பிடித்துக்கொண்டும் அதைத் தீவிரமாய்ப் புசிக்கக்கடவீர்கள்; அது கர்த்தருடைய பஸ்கா.',	2,	12,	11),
(1829,	'For I will pass through the land of Egypt this night, and will smite all the firstborn in the land of Egypt, both man and beast; and against all the gods of Egypt I will execute judgment: I am the LORD.',	'அந்த ராத்திரியிலே நான் எகிப்து தேசம் எங்கும் கடந்துபோய், எகிப்துதேசத்திலுள்ள மனிதர்முதல் மிருகஜீவன்கள்மட்டும், முதற்பேறாயிருக்கிறவைகளையெல்லாம் அதம்பண்ணி, எகிப்து தேவர்களின்மேல் நீதியைச் செலுத்துவேன்; நானே கர்த்தர்.',	2,	12,	12),
(1830,	'And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you, and the plague shall not be upon you to destroy you, when I smite the land of Egypt.',	'நீங்கள் இருக்கும் வீடுகளில் அந்த இரத்தம் உங்களுக்காக அடையாளமாய் இருக்கும்; அந்த இரத்தத்தை நான் கண்டு, உங்களைக் கடந்துபோவேன்; நான் எகிப்து தேசத்தை அழிக்கும்போது, அழிக்கும் வாதை உங்களுக்குள்ளே வராதிருக்கும்.',	2,	12,	13),
(1831,	'And this day shall be unto you for a memorial; and ye shall keep it a feast to the LORD throughout your generations; ye shall keep it a feast by an ordinance for ever.',	'அந்த நாள் உங்களுக்கு நினைவுகூருதலான நாளாய் இருக்கக்கடவது; அதைக் கர்த்தருக்குப் பண்டிகையாக ஆசரிப்பீர்களாக; அதை உங்கள் தலைமுறைதோறும் நித்திய நியமமாக ஆசரிக்கக்கடவீர்கள்.',	2,	12,	14),
(1832,	'Seven days shall ye eat unleavened bread; even the first day ye shall put away leaven out of your houses: for whosoever eateth leavened bread from the first day until the seventh day, that soul shall be cut off from Israel.',	'புளிப்பில்லா அப்பத்தை ஏழுநாளளவும் புசிக்கக்கடவீர்கள்; முதலாம் நாளில்தானே புளித்தமாவை உங்கள் வீடுகளிலிருந்து நீக்கவேண்டும்; முதலாம் நாள் தொடங்கி ஏழாம் நாள்வரைக்கும் புளித்த அப்பம். புசிக்கிறவன் எவனோ அந்த ஆத்துமா இஸ்ரவேலரிலிருந்து அறுப்புண்டுபோவான்.',	2,	12,	15),
(1833,	'And in the first day there shall be an holy convocation, and in the seventh day there shall be an holy convocation to you; no manner of work shall be done in them, save that which every man must eat, that only may be done of you.',	'முதலாம் நாளில் பரிசுத்த சபைகூடுதலும், ஏழாம் நாளிலும் பரிசுத்த சபைகூடுதலும் இருக்கவேண்டும்; அவைகளில் ஒரு வேலையும் செய்யப்படலாகாது; அவரவர் சாப்பிடுகிறதற்குத் தேவையானதுமாத்திரம் உங்களால் செய்யப்படலாம்.',	2,	12,	16),
(1834,	'And ye shall observe the feast of unleavened bread; for in this selfsame day have I brought your armies out of the land of Egypt: therefore shall ye observe this day in your generations by an ordinance for ever.',	'புளிப்பில்லா அப்பப்பண்டிகையை ஆசரிப்பீர்களாக; இந்த நாளில்தான் நான் உங்கள் சேனைகளை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினேன்; ஆகையால், உங்கள் தலைமுறைதோறும் நித்திய நியமமாக இந்த நாளை ஆசரிக்கக்கடவீர்கள்.',	2,	12,	17),
(1835,	'In the first month, on the fourteenth day of the month at even, ye shall eat unleavened bread, until the one and twentieth day of the month at even.',	'முதலாம் மாதம் பதினாலாம் தேதி சாயங்காலந்தொடங்கி மாதத்தின் இருபத்தோராம் தேதி சாயங்காலம்வரைக்கும் புளிப்பில்லா அப்பம் புசிக்கக்கடவீர்கள்.',	2,	12,	18),
(1836,	'Seven days shall there be no leaven found in your houses: for whosoever eateth that which is leavened, even that soul shall be cut off from the congregation of Israel, whether he be a stranger, or born in the land.',	'ஏழுநாளளவும் உங்கள் வீடுகளில் புளித்த மா காணப்படலாகாது; எவனாகிலும் புளிப்பிடப்பட்டதைப் புசித்தால், அவன் பரதேசியானாலும் சுதேசியானாலும், அந்த ஆத்துமா இஸ்ரவேல் சபையில் இராமல் அறுப்புண்டுபோவான்.',	2,	12,	19),
(1837,	'Ye shall eat nothing leavened; in all your habitations shall ye eat unleavened bread.',	'புளிப்பிடப்பட்ட யாதொன்றையும் நீங்கள் புசிக்கவேண்டாம்; உங்கள் வாசஸ்தலங்களிலெல்லாம் புளிப்பில்லா அப்பம் புசிக்கக்கடவீர்கள் என்று சொல் என்றார்.',	2,	12,	20),
(1838,	'Then Moses called for all the elders of Israel, and said unto them, Draw out and take you a lamb according to your families, and kill the passover.',	'அப்பொழுது மோசே இஸ்ரவேல் மூப்பர் யாவரையும் அழைப்பித்து: நீங்கள் உங்கள் குடும்பங்களுக்குத் தக்கதாக உங்களுக்கு ஆட்டுக்குட்டியைத் தெரிந்தெடுத்துக்கொண்டு, பஸ்காவை அடித்து,',	2,	12,	21),
(1839,	'And ye shall take a bunch of hyssop, and dip it in the blood that is in the bason, and strike the lintel and the two side posts with the blood that is in the bason; and none of you shall go out at the door of his house until the morning.',	'ஈசோப்புக் கொழுந்துகளின் கொத்தை எடுத்து கிண்ணியில் இருக்கும் இரத்தத்தில் தோய்த்து, அதில் இருக்கும் அந்த இரத்தத்தை வாசல் நிலைக்கால்களின் மேற்சட்டத்திலும் வாசலின் நிலைக்கால்கள் இரண்டிலும் தெளியுங்கள்; விடியற்காலம் வரைக்கும் உங்களில் ஒருவரும் வீட்டு வாசலைவிட்டுப் புறப்படவேண்டாம்.',	2,	12,	22),
(1840,	'For the LORD will pass through to smite the Egyptians; and when he seeth the blood upon the lintel, and on the two side posts, the LORD will pass over the door, and will not suffer the destroyer to come in unto your houses to smite you.',	'கர்த்தர் எகிப்தியரை அதம்பண்ணுகிறதற்குக் கடந்துவருவார்; நிலையின் மேற்சட்டத்திலும் வாசலின் நிலைக்கால்கள் இரண்டிலும் அந்த இரத்தத்தைக் காணும்போது, கர்த்தர் சங்காரக்காரனை உங்கள் வீடுகளில் உங்களை அதம்பண்ணுகிறதற்கு வரவொட்டாமல், வாசற்படியை விலகிக் கடந்துபோவார்.',	2,	12,	23),
(1841,	'And ye shall observe this thing for an ordinance to thee and to thy sons for ever.',	'இந்தக் காரியத்தை உங்களுக்கும் உங்கள் பிள்ளைகளுக்கும் நித்திய நியமமாகக் கைக்கொள்ளக்கடவீர்கள்.',	2,	12,	24),
(1842,	'And it shall come to pass, when ye be come to the land which the LORD will give you, according as he hath promised, that ye shall keep this service.',	'கர்த்தர் உங்களுக்குத் தாம் சொன்னபடி கொடுக்கப்போகிற தேசத்திலே நீங்கள் போய்ச் சேரும்போது, இந்த ஆராதனையைக் கைக்கொள்ளக்கடவீர்கள்.',	2,	12,	25),
(1843,	'And it shall come to pass, when your children shall say unto you, What mean ye by this service?',	'அப்பொழுது உங்கள் பிள்ளைகள்: இந்த ஆராதனையின் கருத்து என்ன என்று உங்களைக் கேட்டால்,',	2,	12,	26),
(1844,	'That ye shall say, It is the sacrifice of the LORD\'s passover, who passed over the houses of the children of Israel in Egypt, when he smote the Egyptians, and delivered our houses. And the people bowed the head and worshipped.',	'இது கர்த்தருடைய பஸ்காவாகிய பலி; அவர் எகிப்தியரை அதம்பண்ணி, நம்முடைய வீடுகளைத் தப்பப்பண்ணினபோது, எகிப்திலிருந்த இஸ்ரவேல் புத்திரருடைய வீடுகளைக் கடந்துபோனார் என்று நீங்கள் சொல்லவேண்டும் என்றான். அப்பொழுது ஜனங்கள் தலை வணங்கிப் பணிந்துகொண்டார்கள்.',	2,	12,	27),
(1845,	'And the children of Israel went away, and did as the LORD had commanded Moses and Aaron, so did they.',	'இஸ்ரவேல் புத்திரர் போய் அப்படியே செய்தார்கள்; கர்த்தர் மோசேக்கும் ஆரோனுக்கும் கட்டளையிட்டபடியே செய்தார்கள்.',	2,	12,	28),
(1846,	'And it came to pass, that at midnight the LORD smote all the firstborn in the land of Egypt, from the firstborn of Pharaoh that sat on his throne unto the firstborn of the captive that was in the dungeon; and all the firstborn of cattle.',	'நடுராத்திரியிலே சிங்காசனத்தின்மேல் வீற்றிருக்கும் பார்வோனுடைய தலைப்பிள்ளைமுதல் காவல் கிடங்கிலிருக்கும் சிறைப்பட்டவனின் தலைப்பிள்ளைவரைக்கும், எகிப்து தேசத்தில் இருந்த முதற்பேறனைத்தையும், மிருகஜீவன்களின் தலையீற்றனைத்தையும் கர்த்தர் அழித்தார்.',	2,	12,	29),
(1847,	'And Pharaoh rose up in the night, he, and all his servants, and all the Egyptians; and there was a great cry in Egypt; for there was not a house where there was not one dead.',	'அப்பொழுது பார்வோனும் அவனுடைய சகல ஊழியக்காரரும் எகிப்தியர் யாவரும் இராத்திரியிலே எழுந்திருந்தார்கள்; மகா கூக்குரல் எகிப்திலே உண்டாயிற்று; சாவில்லாத ஒரு வீடும் இருந்ததில்லை.',	2,	12,	30),
(1848,	'And he called for Moses and Aaron by night, and said, Rise up, and get you forth from among my people, both ye and the children of Israel; and go, serve the LORD, as ye have said.',	'இராத்திரியிலே அவன் மோசேயையும் ஆரோனையும் அழைப்பித்து: நீங்களும் இஸ்ரவேல் புத்திரரும் எழுந்து, என் ஜனங்களைவிட்டுப் புறப்பட்டுப் போய், நீங்கள் சொன்னபடியே கர்த்தருக்கு ஆராதனை செய்யுங்கள்.',	2,	12,	31),
(1849,	'Also take your flocks and your herds, as ye have said, and be gone; and bless me also.',	'நீங்கள் சொன்னபடியே உங்கள் ஆடுமாடுகளையும் ஓட்டிக்கொண்டுபோங்கள்; என்னையும் ஆசீர்வதியுங்கள் என்றான்.',	2,	12,	32),
(1850,	'And the Egyptians were urgent upon the people, that they might send them out of the land in haste; for they said, We be all dead men.',	'எகிப்தியர்: நாங்கள் எல்லாரும் சாகிறோமே என்று சொல்லி, தீவிரமாய் அந்த ஜனங்களைத் தேசத்திலிருந்து அனுப்பிவிட அவர்களை மிகவும் துரிதப்படுத்தினார்கள்.',	2,	12,	33),
(1851,	'And the people took their dough before it was leavened, their kneadingtroughs being bound up in their clothes upon their shoulders.',	'பிசைந்தமா புளிக்குமுன் ஜனங்கள் அதைப் பாத்திரத்துடனே தங்கள் வஸ்திரங்களில் கட்டி, தங்கள் தோள்மேல் எடுத்துக்கொண்டு போனார்கள்.',	2,	12,	34),
(1852,	'And the children of Israel did according to the word of Moses; and they borrowed of the Egyptians jewels of silver, and jewels of gold, and raiment:',	'மோசே சொல்லியிருந்தபடி இஸ்ரவேல் ஜனங்கள் எகிப்தியரிடத்தில் வெள்ளியுடைமைகளையும் பொன்னுடைமைகளையும் வஸ்திரங்களையும் கேட்டார்கள்.',	2,	12,	35),
(1853,	'And the LORD gave the people favour in the sight of the Egyptians, so that they lent unto them such things as they required. And they spoiled the Egyptians.',	'கர்த்தர் ஜனங்களுக்கு எகிப்தியரின் கண்களில் தயவு கிடைக்கும்படி செய்ததினால், கேட்டதை அவர்களுக்குக் கொடுத்தார்கள்; இவ்விதமாய் அவர்கள் எகிப்தியரைக் கொள்ளையிட்டார்கள்.',	2,	12,	36),
(1854,	'And the children of Israel journeyed from Rameses to Succoth, about six hundred thousand on foot that were men, beside children.',	'இஸ்ரவேல் புத்திரர் ராமசேசை விட்டுக் கால்நடையாகப் பிரயாணம்பண்ணி, சுக்கோத்துக்குப் போனார்கள்; அவர்கள், பிள்ளைகள் தவிர ஆறுலட்சம் புருஷராயிருந்தார்கள்.',	2,	12,	37),
(1855,	'And a mixed multitude went up also with them; and flocks, and herds, even very much cattle.',	'அவர்களோடே கூடப் பல ஜாதியான ஜனங்கள் அநேகர் போனதுமன்றி, மிகுதியான ஆடுமாடுகள் முதலான மிருகஜீவன்களும் போயிற்று.',	2,	12,	38),
(1856,	'And they baked unleavened cakes of the dough which they brought forth out of Egypt, for it was not leavened; because they were thrust out of Egypt, and could not tarry, neither had they prepared for themselves any victual.',	'எகிப்திலிருந்து அவர்கள் கொண்டு வந்த பிசைந்தமாவைப் புளிப்பில்லா அப்பங்களாகச் சுட்டார்கள்; அவர்கள் எகிப்தில் தரிக்கக்கூடாமல் துரத்திவிடப்பட்டதினால், அது புளியாதிருந்தது; அவர்கள் தங்களுக்கு வழிக்கென்று ஒன்றும் ஆயத்தம்பண்ணவில்லை.',	2,	12,	39),
(1857,	'Now the sojourning of the children of Israel, who dwelt in Egypt, was four hundred and thirty years.',	'இஸ்ரவேல் புத்திரர் எகிப்திலே குடியிருந்த காலம் நானூற்றுமுப்பது வருஷம்.',	2,	12,	40),
(1858,	'And it came to pass at the end of the four hundred and thirty years, even the selfsame day it came to pass, that all the hosts of the LORD went out from the land of Egypt.',	'நானூற்றுமுப்பது வருஷம் முடிந்த அன்றைத்தினமே கர்த்தருடைய சேனைகள் எல்லாம் எகிப்து தேசத்திலிருந்து புறப்பட்டது.',	2,	12,	41),
(1859,	'It is a night to be much observed unto the LORD for bringing them out from the land of Egypt: this is that night of the LORD to be observed of all the children of Israel in their generations.',	'கர்த்தர் அவர்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினதினால், இது அவருக்கென்று முக்கியமாய் ஆசரிக்கத்தக்க இராத்திரியாயிற்று; இஸ்ரவேல் சந்ததியார் எல்லாரும் தங்கள் தலைமுறைதோறும் கர்த்தருக்கு முக்கியமாய் ஆசரிக்கவேண்டிய இராத்திரி இதுவே.',	2,	12,	42),
(1860,	'And the LORD said unto Moses and Aaron, This is the ordinance of the passover: There shall no stranger eat thereof:',	'மேலும், கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி: பஸ்காவின் நியமமாவது, அந்நிய புத்திரன் ஒருவனும் அதைப் புசிக்கவேண்டாம்.',	2,	12,	43),
(1861,	'But every man\'s servant that is bought for money, when thou hast circumcised him, then shall he eat thereof.',	'பணத்தினால் கொள்ளப்பட்ட அடிமையானவன் எவனும், நீ அவனுக்கு விருத்தசேதனம் பண்ணினபின், அவன் அதைப் புசிக்கலாம்.',	2,	12,	44),
(1862,	'A foreigner and an hired servant shall not eat thereof.',	'அந்நியனும் கூலியாளும் அதிலே புசிக்கவேண்டாம்.',	2,	12,	45),
(1863,	'In one house shall it be eaten; thou shalt not carry forth ought of the flesh abroad out of the house; neither shall ye break a bone thereof.',	'அதை ஒவ்வொரு வீட்டிற்குள்ளும் புசிக்கவேண்டும்; அந்த மாம்சத்தில் கொஞ்சமாகிலும் வீட்டிலிருந்து வெளியே கொண்டுபோகக்கூடாது; அதில் ஒரு எலும்பையும் முறிக்கக்கூடாது.',	2,	12,	46),
(1864,	'All the congregation of Israel shall keep it.',	'இஸ்ரவேல் சபையார் எல்லாரும் அதை ஆசரிக்கக்கடவர்கள்.',	2,	12,	47),
(1865,	'And when a stranger shall sojourn with thee, and will keep the passover to the LORD, let all his males be circumcised, and then let him come near and keep it; and he shall be as one that is born in the land: for no uncircumcised person shall eat thereof.',	'அந்நியன் ஒருவன் உன்னிடத்திலே தங்கி, கர்த்தருக்குப் பஸ்காவை ஆசரிக்கவேண்டுமென்று இருந்தால், அவனைச் சேர்ந்த ஆண்பிள்ளைகள் யாவரும் விருத்தசேதனம்பண்ணப்படவேண்டும்; பின்பு அவன் சேர்ந்து அதை ஆசரிக்கவேண்டும்; அவன் சுதேசியைப்போல் இருப்பான்; விருத்தசேதனம் இல்லாத ஒருவரும் அதில் புசிக்கவேண்டாம்.',	2,	12,	48),
(1866,	'One law shall be to him that is homeborn, and unto the stranger that sojourneth among you.',	'சுதேசிக்கும் உங்களிடத்தில் தங்கும் பரதேசிக்கும் ஒரே பிரமாணம் இருக்கக்கடவது என்றார்.',	2,	12,	49),
(1867,	'Thus did all the children of Israel; as the LORD commanded Moses and Aaron, so did they.',	'இப்படியே இஸ்ரவேல் புத்திரர் எல்லாரும் செய்தார்கள்; கர்த்தர் மோசேக்கும் ஆரோனுக்கும் கட்டளையிட்டபடியே செய்தார்கள்.',	2,	12,	50),
(1868,	'And it came to pass the selfsame day, that the LORD did bring the children of Israel out of the land of Egypt by their armies.',	'அன்றைத்தினமே கர்த்தர் இஸ்ரவேல் புத்திரரை அணியணியாய் எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினார்.  ',	2,	12,	51),
(1869,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	2,	13,	1),
(1870,	'Sanctify unto me all the firstborn, whatsoever openeth the womb among the children of Israel, both of man and of beast: it is mine.',	'இஸ்ரவேல் புத்திரருக்குள் மனிதரிலும் மிருகஜீவன்களிலும் கர்ப்பந்திறந்து பிறக்கிற முதற்பேறனைத்தையும் எனக்குப் பரிசுத்தப்படுத்து; அது என்னுடையது என்றார்.',	2,	13,	2),
(1871,	'And Moses said unto the people, Remember this day, in which ye came out from Egypt, out of the house of bondage; for by strength of hand the LORD brought you out from this place: there shall no leavened bread be eaten.',	'அப்பொழுது மோசே ஜனங்களை நோக்கி: நீங்கள் அடிமைத்தன வீடாகிய எகிப்திலிருந்து புறப்பட்ட இந்த நாளை நினையுங்கள்; கர்த்தர் பலத்த கையினால் உங்களை அவ்விடத்திலிருந்து புறப்படப்பண்ணினார்; ஆகையால், நீங்கள் புளித்த அப்பம் புசிக்கவேண்டாம்.',	2,	13,	3),
(1872,	'This day came ye out in the month Abib.',	'ஆபிப் மாதத்தின் இந்த நாளிலே நீங்கள் புறப்பட்டீர்கள்.',	2,	13,	4),
(1873,	'And it shall be when the LORD shall bring thee into the land of the Canaanites, and the Hittites, and the Amorites, and the Hivites, and the Jebusites, which he sware unto thy fathers to give thee, a land flowing with milk and honey, that thou shalt keep this service in this month.',	'ஆகையால், கர்த்தர் உனக்குக் கொடுப்பேன் என்று உன் பிதாக்களுக்கு ஆணையிட்டதும், பாலும் தேனும் ஓடுகிறதுமான தேசமாகிய கானானியர், ஏத்தியர், எமோரியர், ஏவியர், எபூசியர் என்பவர்களுடைய தேசத்துக்கு உன்னை வரப்பண்ணும் காலத்தில், நீ இந்த மாதத்திலே இந்த ஆராதனையைச் செய்வாயாக.',	2,	13,	5),
(1874,	'Seven days thou shalt eat unleavened bread, and in the seventh day shall be a feast to the LORD.',	'புளிப்பில்லா அப்பத்தை ஏழுநாளளவும் புசிக்கக்கடவாய்; ஏழாம்நாளிலே கர்த்தருக்குப் பண்டிகை ஆசரிக்கப்படுவதாக.',	2,	13,	6),
(1875,	'Unleavened bread shall be eaten seven days; and there shall no leavened bread be seen with thee, neither shall there be leaven seen with thee in all thy quarters.',	'அந்த ஏழுநாளும் புளிப்பில்லா அப்பம் புசிக்கவேண்டும்; புளிப்புள்ள அப்பம் உன்னிடத்திலே காணப்படவேண்டாம்; உன் எல்லைக்குள் எங்கும் புளித்தமாவும் உன்னிடத்தில் காணப்படவேண்டாம்.',	2,	13,	7),
(1876,	'And thou shalt shew thy son in that day, saying, This is done because of that which the LORD did unto me when I came forth out of Egypt.',	'அந்நாளில் நீ உன் புத்திரனை நோக்கி: நான் எகிப்திலிருந்து புறப்படுகையில், கர்த்தர் எனக்குச் செய்ததற்காக இப்படி நடப்பிக்கப்படுகிறது என்று சொல்.',	2,	13,	8),
(1877,	'And it shall be for a sign unto thee upon thine hand, and for a memorial between thine eyes, that the LORD\'s law may be in thy mouth: for with a strong hand hath the LORD brought thee out of Egypt.',	'கர்த்தரின் நியாயப்பிரமாணம் உன் வாயிலிருக்கும்படிக்கு, இது உன் கையிலே ஒரு அடையாளமாகவும் உன் கண்களின் நடுவே நினைப்பூட்டுதலாகவும் இருக்கக்கடவது; பலத்த கையினால் கர்த்தர் உன்னை எகிப்திலிருந்து புறப்படப்பண்ணினார்;',	2,	13,	9),
(1878,	'Thou shalt therefore keep this ordinance in his season from year to year.',	'ஆகையால், நீ வருஷந்தோறும் குறித்த காலத்தில் இந்த நியாயத்தை ஆசரித்து வருவாயாக.',	2,	13,	10),
(1879,	'And it shall be when the LORD shall bring thee into the land of the Canaanites, as he sware unto thee and to thy fathers, and shall give it thee,',	'மேலும், கர்த்தர் உனக்கும் உன் பிதாக்களுக்கும் ஆணையிட்டபடியே, உன்னைக் கானானியரின் தேசத்திலே வரப்பண்ணி, அதை உனக்குக் கொடுக்கும்போது,',	2,	13,	11),
(1880,	'That thou shalt set apart unto the LORD all that openeth the matrix, and every firstling that cometh of a beast which thou hast; the males shall be the LORD\'s.',	'கர்ப்பந்திறந்து பிறக்கும் அனைத்தையும், உனக்கு இருக்கும் மிருகஜீவன்களின் தலையீற்றனைத்தையும், கர்த்தருக்கு ஒப்புக்கொடுப்பாயாக; அவைகளிலுள்ள ஆண்கள் கர்த்தருடையவைகள்.',	2,	13,	12),
(1881,	'And every firstling of an ass thou shalt redeem with a lamb; and if thou wilt not redeem it, then thou shalt break his neck: and all the firstborn of man among thy children shalt thou redeem.',	'கழுதையின் தலையீற்றையெல்லாம் ஒரு ஆட்டுக்குட்டியால் மீட்டுக்கொள்வாயாக; மீட்காவிட்டால், அதின் கழுத்தை முறித்துப்போடு. உன் பிள்ளைகளில் முதற்பேறான சகல நரஜீவனையும் மீட்டுக்கொள்வாயாக.',	2,	13,	13),
(1882,	'And it shall be when thy son asketh thee in time to come, saying, What is this? that thou shalt say unto him, By strength of hand the LORD brought us out from Egypt, from the house of bondage:',	'பிற்காலத்தில் உன் குமாரன்: இது என்ன என்று உன்னைக் கேட்டால்; நீ அவனை நோக்கி: கர்த்தர் எங்களைப் பலத்த கையினால் அடிமைத்தன வீடாகிய எகிப்திலிருந்து புறப்படப்பண்ணினார்.',	2,	13,	14),
(1883,	'And it came to pass, when Pharaoh would hardly let us go, that the LORD slew all the firstborn in the land of Egypt, both the firstborn of man, and the firstborn of beast: therefore I sacrifice to the LORD all that openeth the matrix, being males; but all the firstborn of my children I redeem.',	'எங்களை விடாதபடிக்கு, பார்வோன் கடினப்பட்டிருக்கும்போது, கர்த்தர் எகிப்து தேசத்தில் மனிதரின் தலைப்பிள்ளைகள்முதல் மிருகஜீவன்களின் தலையீற்றுகள்வரைக்கும் உண்டாயிருந்த முதற்பேறுகள் யாவையும் கொன்றுபோட்டார்; ஆகையால், கர்ப்பந்திறந்து பிறக்கும் ஆணையெல்லாம் நான் கர்த்தருக்குப் பலியிட்டு, என் பிள்ளைகளில் முதற்பேறனைத்தையும் மீட்டுக்கொள்ளுகிறேன்.',	2,	13,	15),
(1884,	'And it shall be for a token upon thine hand, and for frontlets between thine eyes: for by strength of hand the LORD brought us forth out of Egypt.',	'கர்த்தர் எங்களைப் பலத்த கையினால் எகிப்திலிருந்து புறப்படப்பண்ணினதற்கு, இது உன் கையில் அடையாளமாகவும், உன் கண்களின் நடுவே ஞாபகக்குறியாகவும் இருக்கக்கடவது என்று சொல்வாயாக என்றான்.',	2,	13,	16),
(1885,	'And it came to pass, when Pharaoh had let the people go, that God led them not through the way of the land of the Philistines, although that was near; for God said, Lest peradventure the people repent when they see war, and they return to Egypt:',	'பார்வோன் ஜனங்களைப் போகவிட்டபின்: ஜனங்கள் யுத்தத்தைக் கண்டால் மனமடிந்து, எகிப்துக்குத் திரும்புவார்கள் என்று சொல்லி; பெலிஸ்தரின் தேசவழியாய்ப் போவது சமீபமானாலும், தேவன் அவர்களை அந்த வழியாய் நடத்தாமல்,',	2,	13,	17),
(1886,	'But God led the people about, through the way of the wilderness of the Red sea: and the children of Israel went up harnessed out of the land of Egypt.',	'சிவந்த சமுத்திரத்தின் வனாந்தர வழியாய் ஜனங்களைச் சுற்றிப் போகப்பண்ணினார். இஸ்ரவேல் புத்திரர் எகிப்து தேசத்திலிருந்து அணியணியாய்ப் புறப்பட்டுப்போனார்கள்.',	2,	13,	18),
(1887,	'And Moses took the bones of Joseph with him: for he had straitly sworn the children of Israel, saying, God will surely visit you; and ye shall carry up my bones away hence with you.',	'மோசே தன்னோடேகூட யோசேப்பின் எலும்புகளை எடுத்துக்கொண்டு போனான். தேவன் நிச்சயமாய் உங்களைச் சந்திப்பார்; அப்பொழுது உங்களோடேகூட என் எலும்புகளை இவ்விடத்திலிருந்து கொண்டுபோங்கள் என்று யோசேப்பு சொல்லி, இஸ்ரவேல் புத்திரரை உறுதியாய் ஆணையிடும்படி செய்திருந்தான்.',	2,	13,	19),
(1888,	'And they took their journey from Succoth, and encamped in Etham, in the edge of the wilderness.',	'அவர்கள் சுக்கோத்திலிருந்து பிரயாணப்பட்டு, வனாந்தரத்தின் ஓரமாய் ஏத்தாமிலே பாளயமிறங்கினார்கள்.',	2,	13,	20),
(1889,	'And the LORD went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light; to go by day and night:',	'அவர்கள் இரவும் பகலும் வழிநடக்கக்கூடும்படிக்கு, கர்த்தர் பகலில் அவர்களை வழிநடத்த மேகஸ்தம்பத்திலும், இரவில் அவர்களுக்கு வெளிச்சங்காட்ட அக்கினிஸ்தம்பத்திலும் அவர்களுக்கு முன் சென்றார்.',	2,	13,	21),
(1890,	'He took not away the pillar of the cloud by day, nor the pillar of fire by night, from before the people.',	'பகலிலே மேகஸ்தம்பமும், இரவிலே அக்கினிஸ்தம்பமும் ஜனங்களிடத்திலிருந்து விலகிப்போகவில்லை.  ',	2,	13,	22),
(1891,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	2,	14,	1),
(1892,	'Speak unto the children of Israel, that they turn and encamp before Pihahiroth, between Migdol and the sea, over against Baalzephon: before it shall ye encamp by the sea.',	'நீங்கள் திரும்பி மிக்தோலுக்கும் சமுத்திரத்துக்கும் நடுவே பாகால்செபோனுக்கு முன்பாக இருக்கிற ஈரோத் பள்ளத்தாக்கின் முன்னடியிலே பாளயமிறங்கவேண்டும் என்று இஸ்ரவேல் புத்திரருக்குச் சொல்லு; அதற்கு எதிராகச் சமுத்திரக்கரையிலே பாளயமிறங்குவீர்களாக.',	2,	14,	2),
(1893,	'For Pharaoh will say of the children of Israel, They are entangled in the land, the wilderness hath shut them in.',	'அப்பொழுது பார்வோன் இஸ்ரவேல் புத்திரரைக்குறித்து: அவர்கள் தேசத்திலே திகைத்துத் திரிகிறார்கள்; வனாந்தரம் அவர்களை அடைத்துப்போட்டது என்று சொல்லுவான்.',	2,	14,	3),
(1894,	'And I will harden Pharaoh\'s heart, that he shall follow after them; and I will be honoured upon Pharaoh, and upon all his host; that the Egyptians may know that I am the LORD. And they did so.',	'ஆகையால், பார்வோன் அவர்களைப் பின்தொடரும்படிக்கு, நான் அவன் இருதயத்தைக் கடினப்படுத்தி, நானே கர்த்தர் என்பதை எகிப்தியர் அறியும்படி, பார்வோனாலும் அவனுடைய எல்லா ராணுவத்தாலும் மகிமைப்படுவேன் என்றார்; அவர்கள் அப்படியே செய்தார்கள்.',	2,	14,	4),
(1895,	'And it was told the king of Egypt that the people fled: and the heart of Pharaoh and of his servants was turned against the people, and they said, Why have we done this, that we have let Israel go from serving us?',	'ஜனங்கள் ஓடிப்போய்விட்டார்கள் என்று எகிப்தின் ராஜாவுக்கு அறிவிக்கப்பட்டபோது, ஜனங்களுக்கு விரோதமாகப் பார்வோனும் அவன் ஊழியக்காரரும் மனம் வேறுபட்டு: நமக்கு வேலை செய்யாதபடிக்கு நாம் இஸ்ரவேலரைப் போகவிட்டது என்ன காரியம் என்றார்கள்.',	2,	14,	5),
(1896,	'And he made ready his chariot, and took his people with him:',	'அவன் தன் இரதத்தைப் பூட்டி, தன் ஜனங்களைக் கூட்டிக்கொண்டு,',	2,	14,	6),
(1897,	'And he took six hundred chosen chariots, and all the chariots of Egypt, and captains over every one of them.',	'பிரதானமான அறுநூறு இரதங்களையும், எகிப்திலுள்ள மற்ற சகல இரதங்களையும், அவைகள் எல்லாவற்றிற்கும் அதிபதிகளான வீரரையும் கூட்டிக்கொண்டு போனான்.',	2,	14,	7),
(1898,	'And the LORD hardened the heart of Pharaoh king of Egypt, and he pursued after the children of Israel: and the children of Israel went out with an high hand.',	'கர்த்தர் எகிப்தின் ராஜாவாகிய பார்வோனின் இருதயத்தைக் கடினப்படுத்தினார்; அவன் இஸ்ரவேல் புத்திரரைப் பின்தொடர்ந்தான், இஸ்ரவேல் புத்திரர் பலத்த கையுடன் புறப்பட்டுப் போனார்கள்.',	2,	14,	8),
(1899,	'But the Egyptians pursued after them, all the horses and chariots of Pharaoh, and his horsemen, and his army, and overtook them encamping by the sea, beside Pihahiroth, before Baalzephon.',	'எகிப்தியர் பார்வோனுடைய சகல குதிரைகளோடும் இரதங்களோடும் அவனுடைய குதிரைவீரரோடும் சேனைகளோடும் அவர்களைத் தொடர்ந்துபோய், சமுத்திரத்தண்டையிலே பாகால்செபோனுக்கு எதிரே இருக்கிற ஈரோத் பள்ளத்தாக்கின் முன்னடியிலே பாளயமிறங்கியிருக்கிற அவர்களைக் கிட்டினார்கள்.',	2,	14,	9),
(1900,	'And when Pharaoh drew nigh, the children of Israel lifted up their eyes, and, behold, the Egyptians marched after them; and they were sore afraid: and the children of Israel cried out unto the LORD.',	'பார்வோன் சமீபித்து வருகிறபோது, இஸ்ரவேல் புத்திரர் தங்கள் கண்களை ஏறெடுத்துப்பார்த்து, எகிப்தியர் தங்களுக்குப் பின்னே வருகிறதைக் கண்டு, மிகவும் பயந்தார்கள்; அப்பொழுது இஸ்ரவேல் புத்திரர் கர்த்தரை நோக்கிக் கூப்பிட்டார்கள்.',	2,	14,	10),
(1901,	'And they said unto Moses, Because there were no graves in Egypt, hast thou taken us away to die in the wilderness? wherefore hast thou dealt thus with us, to carry us forth out of Egypt?',	'அன்றியும் அவர்கள் மோசேயை நோக்கி: எகிப்திலே பிரேதக்குழிகள் இல்லையென்றா வனாந்தரத்திலே சாகும்படிக்கு எங்களைக் கொண்டுவந்தீர்? நீர் எங்களை எகிப்திலிருந்து புறப்படப்பண்ணினதினால், எங்களுக்கு இப்படிச் செய்தது என்ன?',	2,	14,	11),
(1902,	'Is not this the word that we did tell thee in Egypt, saying, Let us alone, that we may serve the Egyptians? For it had been better for us to serve the Egyptians, than that we should die in the wilderness.',	'நாங்கள் எகிப்திலே இருக்கும்போது, நாங்கள் எகிப்தியருக்கு வேலை செய்ய எங்களைச் சும்மா விட்டுவிடும் என்று சொன்னோம் அல்லவா? நாங்கள் வனாந்தரத்திலே சாகிறதைப்பார்க்கிலும் எகிப்தியருக்கு வேலைசெய்கிறது எங்களுக்கு நலமாயிருக்குமே என்றார்கள்.',	2,	14,	12),
(1903,	'And Moses said unto the people, Fear ye not, stand still, and see the salvation of the LORD, which he will shew to you to day: for the Egyptians whom ye have seen to day, ye shall see them again no more for ever.',	'அப்பொழுது மோசே ஜனங்களை நோக்கி: பயப்படாதிருங்கள்; நீங்கள் நின்றுகொண்டு இன்றைக்குக் கர்த்தர் உங்களுக்குச் செய்யும் இரட்சிப்பைப் பாருங்கள்; இன்றைக்கு நீங்கள் காண்கிற எகிப்தியரை இனி என்றைக்கும் காணமாட்டீர்கள்.',	2,	14,	13),
(1904,	'The LORD shall fight for you, and ye shall hold your peace.',	'கர்த்தர் உங்களுக்காக யுத்தம்பண்ணுவார்; நீங்கள் சும்மாயிருப்பீர்கள் என்றான்.',	2,	14,	14),
(1905,	'And the LORD said unto Moses, Wherefore criest thou unto me? speak unto the children of Israel, that they go forward:',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ என்னிடத்தில் முறையிடுகிறது என்ன? புறப்பட்டுப் போங்கள் என்று இஸ்ரவேல் புத்திரருக்குச் சொல்லு.',	2,	14,	15),
(1906,	'But lift thou up thy rod, and stretch out thine hand over the sea, and divide it: and the children of Israel shall go on dry ground through the midst of the sea.',	'நீ உன் கோலை ஓங்கி, உன் கையைச் சமுத்திரத்தின்மேல் நீட்டி, சமுத்திரத்தைப் பிளந்துவிடு; அப்பொழுது இஸ்ரவேல் புத்திரர் சமுத்திரத்தின் நடுவாக வெட்டாந்தரையிலே நடந்துபோவார்கள்.',	2,	14,	16);
INSERT INTO `bible_verses` (`id`, `english_verse`, `tamil_verse`, `book_id`, `chapter_id`, `verse_id`) VALUES
(1907,	'And I, behold, I will harden the hearts of the Egyptians, and they shall follow them: and I will get me honour upon Pharaoh, and upon all his host, upon his chariots, and upon his horsemen.',	'எகிப்தியர் உங்களைப் பின்தொடர்ந்து வரும்படி நான் அவர்கள் இருதயத்தைக் கடினப்படுத்தி பார்வோனாலும் அவன் இரதங்கள் குதிரைவீரர் முதலாகிய அவனுடைய எல்லா இராணுவத்தாலும் மகிமைப்படுவேன்.',	2,	14,	17),
(1908,	'And the Egyptians shall know that I am the LORD, when I have gotten me honour upon Pharaoh, upon his chariots, and upon his horsemen.',	'இப்படி நான் பார்வோனாலும் அவன் இரதங்களாலும் அவன் குதிரைவீரராலும் மகிமைப்படும்போது, நானே கர்த்தர் என்பதை எகிப்தியர் அறிவார்கள் என்றார்.',	2,	14,	18),
(1909,	'And the angel of God, which went before the camp of Israel, removed and went behind them; and the pillar of the cloud went from before their face, and stood behind them:',	'அப்பொழுது இஸ்ரவேலரின் சேனைக்கு முன்னாக நடந்த தேவதூதனானவர் விலகி, அவர்களுக்குப் பின்னாக நடந்தார்; அவர்களுக்கு முன் இருந்த மேகஸ்தம்பமும் விலகி, அவர்கள் பின்னே நின்றது.',	2,	14,	19),
(1910,	'And it came between the camp of the Egyptians and the camp of Israel; and it was a cloud and darkness to them, but it gave light by night to these: so that the one came not near the other all the night.',	'அது எகிப்தியரின் சேனையும் இஸ்ரவேலரின் சேனையும் இராமுழுவதும் ஒன்றோடொன்று சேராதபடி அவைகள் நடுவில் வந்தது; எகிப்தியருக்கு அது மேகமும் அந்தகாரமுமாய் இருந்தது, இஸ்ரவேலருக்கோ அது இரவை வெளிச்சமாக்கிற்று.',	2,	14,	20),
(1911,	'And Moses stretched out his hand over the sea; and the LORD caused the sea to go back by a strong east wind all that night, and made the sea dry land, and the waters were divided.',	'மோசே தன் கையைச் சமுத்திரத்தின்மேல் நீட்டினான்; அப்பொழுது கர்த்தர் இராமுழுவதும் பலத்த கீழ்காற்றினால் சமுத்திரம் ஒதுங்கும்படி செய்து, அதை வறண்டுபோகப்பண்ணினார்; ஜலம் பிளந்து பிரிந்துபோயிற்று.',	2,	14,	21),
(1912,	'And the children of Israel went into the midst of the sea upon the dry ground: and the waters were a wall unto them on their right hand, and on their left.',	'இஸ்ரவேல் புத்திரர் சமுத்திரத்தின் நடுவாக வெட்டாந்தரையிலே நடந்துபோனார்கள்; அவர்கள் வலதுபுறத்திலும் அவர்கள் இடதுபுறத்திலும் ஜலம் அவர்களுக்கு மதிலாக நின்றது.',	2,	14,	22),
(1913,	'And the Egyptians pursued, and went in after them to the midst of the sea, even all Pharaoh\'s horses, his chariots, and his horsemen.',	'அப்பொழுது எகிப்தியர் அவர்களைத் தொடர்ந்து, பார்வோனுடைய சகல குதிரைகளோடும் இரதங்களோடும் குதிரைவீரரோடும் அவர்கள் பிறகாலே சமுத்திரத்தின் நடுவே பிரவேசித்தார்கள்.',	2,	14,	23),
(1914,	'And it came to pass, that in the morning watch the LORD looked unto the host of the Egyptians through the pillar of fire and of the cloud, and troubled the host of the Egyptians,',	'கிழக்கு வெளுத்துவரும் ஜாமத்தில் கர்த்தர் அக்கினியும் மேகமுமான ஸ்தம்பத்திலிருந்து எகிப்தியரின் சேனையைப் பார்த்து, அவர்கள் சேனையைக் கலங்கடித்து,',	2,	14,	24),
(1915,	'And took off their chariot wheels, that they drave them heavily: so that the Egyptians said, Let us flee from the face of Israel; for the LORD fighteth for them against the Egyptians.',	'அவர்களுடைய இரதங்களிலிருந்து உருளைகள் கழலவும், அவர்கள் தங்கள் இரதங்களை வருத்தத்தோடே நடத்தவும் பண்ணினார்; அப்பொழுது எகிப்தியர்: இஸ்ரவேலரைவிட்டு ஓடிப்போவோம், கர்த்தர் அவர்களுக்குத் துணைநின்று எகிப்தியருக்கு விரோதமாய் யுத்தம்பண்ணுகிறார் என்றார்கள்.',	2,	14,	25),
(1916,	'And the LORD said unto Moses, Stretch out thine hand over the sea, that the waters may come again upon the Egyptians, upon their chariots, and upon their horsemen.',	'கர்த்தர் மோசேயை நோக்கி: ஜலம் எகிப்தியர்மேலும் அவர்களுடைய இரதங்கள்மேலும் அவர்களுடைய குதிரைவீரர்மேலும் திரும்பும்படிக்கு, உன் கையைச் சமுத்திரத்தின்மேல் நீட்டு என்றார்.',	2,	14,	26),
(1917,	'And Moses stretched forth his hand over the sea, and the sea returned to his strength when the morning appeared; and the Egyptians fled against it; and the LORD overthrew the Egyptians in the midst of the sea.',	'அப்படியே மோசே தன் கையைச் சமுத்திரத்தின்மேல் நீட்டினான்; விடியற்காலத்தில் சமுத்திரம் பலமாய்த் திரும்பி வந்தது; எகிப்தியர் அதற்கு எதிராக ஓடும்போது, கர்த்தர் அவர்களைக் கடலின் நடுவே கவிழ்த்துப்போட்டார்.',	2,	14,	27),
(1918,	'And the waters returned, and covered the chariots, and the horsemen, and all the host of Pharaoh that came into the sea after them; there remained not so much as one of them.',	'ஜலம் திரும்பிவந்து, இரதங்களையும் குதிரைவீரரையும், அவர்கள் பின்னாக சமுத்திரத்தில் பிரவேசித்திருந்த பார்வோனுடைய இராணுவம் அனைத்தையும் மூடிக்கொண்டது; அவர்களில் ஒருவனாகிலும் தப்பவில்லை.',	2,	14,	28),
(1919,	'But the children of Israel walked upon dry land in the midst of the sea; and the waters were a wall unto them on their right hand, and on their left.',	'இஸ்ரவேல் புத்திரரோ சமுத்திரத்தின் நடுவாக வெட்டாந்தரையின் வழியாய் நடந்துபோனார்கள்; அவர்கள் வலதுபுறத்திலும் அவர்கள் இடதுபுறத்திலும் ஜலம் அவர்களுக்கு மதிலாக நின்றது.',	2,	14,	29),
(1920,	'Thus the LORD saved Israel that day out of the hand of the Egyptians; and Israel saw the Egyptians dead upon the sea shore.',	'இவ்விதமாய்க் கர்த்தர் அந்நாளிலே இஸ்ரவேலரை எகிப்தியரின் கைக்குத் தப்புவித்து ரட்சித்தார்; கடற்கரையிலே எகிப்தியர் செத்துக்கிடக்கிறதை இஸ்ரவேலர் கண்டார்கள்.',	2,	14,	30),
(1921,	'And Israel saw that great work which the LORD did upon the Egyptians: and the people feared the LORD, and believed the LORD, and his servant Moses.',	'கர்த்தர் எகிப்தியரில் செய்த அந்த மகத்தான கிரியையை இஸ்ரவேலர் கண்டார்கள்; அப்பொழுது ஜனங்கள் கர்த்தருக்குப் பயந்து, கர்த்தரிடத்திலும் அவருடைய ஊழியக்காரனாகிய மோசேயினிடத்திலும் விசுவாசம் வைத்தார்கள்.  ',	2,	14,	31),
(1922,	'Then sang Moses and the children of Israel this song unto the LORD, and spake, saying, I will sing unto the LORD, for he hath triumphed gloriously: the horse and his rider hath he thrown into the sea.',	'அப்பொழுது மோசேயும் இஸ்ரவேல் புத்திரரும் கர்த்தரைப் புகழ்ந்துபாடின பாட்டு: கர்த்தரைப் பாடுவேன்; அவர் மகிமையாய் வெற்றி சிறந்தார்; குதிரையையும் குதிரைவீரனையும் கடலிலே தள்ளினார்.',	2,	15,	1),
(1923,	'The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father\'s God, and I will exalt him.',	'கர்த்தர் என் பெலனும் என் கீதமுமானவர்; அவர் எனக்கு இரட்சிப்புமானவர்; அவரே என் தேவன், அவருக்கு வாசஸ்தலத்தை ஆயத்தம்பண்ணுவேன்; அவரே என் தகப்பனுடைய தேவன், அவரை உயர்த்துவேன்;',	2,	15,	2),
(1924,	'The LORD is a man of war: the LORD is his name.',	'கர்த்தரே யுத்தத்தில் வல்லவர்; கர்த்தர் என்பது அவருடைய நாமம்.',	2,	15,	3),
(1925,	'Pharaoh\'s chariots and his host hath he cast into the sea: his chosen captains also are drowned in the Red sea.',	'பார்வோனின் இரதங்களையும் அவன் சேனைகளையும் சமுத்திரத்திலே தள்ளிவிட்டார்; அவனுடைய பிரதான அதிபதிகள் சிவந்த சமுத்திரத்தில் அமிழ்ந்துபோனார்கள்.',	2,	15,	4),
(1926,	'The depths have covered them: they sank into the bottom as a stone.',	'ஆழி அவர்களை மூடிக்கொண்டது; கல்லைப்போல ஆழங்களில் அமிழ்ந்துபோனார்கள்.',	2,	15,	5),
(1927,	'Thy right hand, O LORD, is become glorious in power: thy right hand, O LORD, hath dashed in pieces the enemy.',	'கர்த்தாவே, உம்முடைய வலதுகரம் பலத்தினால் மகத்துவம் சிறந்திருக்கிறது; கர்த்தாவே, உம்முடைய வலதுகரம் பகைஞனை நொறுக்கிவிட்டது.',	2,	15,	6),
(1928,	'And in the greatness of thine excellency thou hast overthrown them that rose up against thee: thou sentest forth thy wrath, which consumed them as stubble.',	'உமக்கு விரோதமாய் எழும்பினவர்களை உமது முக்கியத்தின் மகத்துவத்தினாலே நிர்மூலமாக்கினீர்; உம்முடைய கோபாக்கினியை அனுப்பினீர், அது அவர்களைத் தாளடியைப்போலப் பட்சித்தது.',	2,	15,	7),
(1929,	'And with the blast of thy nostrils the waters were gathered together, the floods stood upright as an heap, and the depths were congealed in the heart of the sea.',	'உமது நாசியின் சுவாசத்தினால் ஜலம் குவிந்து நின்றது; வெள்ளம் குவியலாக நிமிர்ந்து நின்றது; ஆழமான ஜலம் நடுக்கடலிலே உறைந்துபோயிற்று.',	2,	15,	8),
(1930,	'The enemy said, I will pursue, I will overtake, I will divide the spoil; my lust shall be satisfied upon them; I will draw my sword, my hand shall destroy them.',	'தொடருவேன், பிடிப்பேன், கொள்ளையாடிப் பங்கிடுவேன், என் ஆசை அவர்களிடத்தில் திருப்தியாகும், என் பட்டயத்தை உருவுவேன், என் கை அவர்களைச் சங்கரிக்கும் என்று பகைஞன் சொன்னான்.',	2,	15,	9),
(1931,	'Thou didst blow with thy wind, the sea covered them: they sank as lead in the mighty waters.',	'உம்முடைய காற்றை வீசப்பண்ணினீர், கடல் அவர்களை மூடிக்கொண்டது; திரளான தண்ணீர்களில் ஈயம்போல அமிழ்ந்துபோனார்கள்.',	2,	15,	10),
(1932,	'Who is like unto thee, O LORD, among the gods? who is like thee, glorious in holiness, fearful in praises, doing wonders?',	'கர்த்தாவே, தேவர்களில் உமக்கு ஒப்பானவர் யார்? பரிசுத்தத்தில் மகத்துவமுள்ளவரும், துதிகளில் பயப்படத்தக்கவரும், அற்புதங்களைச் செய்கிறவருமாகிய உமக்கு ஒப்பானவர் யார்?',	2,	15,	11),
(1933,	'Thou stretchedst out thy right hand, the earth swallowed them.',	'நீர் உமது வலதுகரத்தை நீட்டினீர்; பூமி அவர்களை விழுங்கிப்போட்டது.',	2,	15,	12),
(1934,	'Thou in thy mercy hast led forth the people which thou hast redeemed: thou hast guided them in thy strength unto thy holy habitation.',	'நீர் மீட்டுக்கொண்ட இந்த ஜனங்களை உமது கிருபையினாலே அழைத்து வந்தீர்; உம்முடைய பரிசுத்த வாசஸ்தலத்துக்கு நேராக அவர்களை உமது பலத்தினால் வழி நடத்தினீர்.',	2,	15,	13),
(1935,	'The people shall hear, and be afraid: sorrow shall take hold on the inhabitants of Palestina.',	'ஜனங்கள் அதைக் கேட்டுத் தத்தளிப்பார்கள்; பெலிஸ்தியாவின் குடிகளைத் திகில் பிடிக்கும்.',	2,	15,	14),
(1936,	'Then the dukes of Edom shall be amazed; the mighty men of Moab, trembling shall take hold upon them; all the inhabitants of Canaan shall melt away.',	'ஏதோமின் பிரபுக்கள் கலங்குவார்கள்; மோவாபின் பராக்கிரமசாலிகளை நடுக்கம் பிடிக்கும்; கானானின் குடிகள் யாவரும் கரைந்துபோவார்கள்.',	2,	15,	15),
(1937,	'Fear and dread shall fall upon them; by the greatness of thine arm they shall be as still as a stone; till thy people pass over, O LORD, till the people pass over, which thou hast purchased.',	'பயமும் திகிலும் அவர்கள்மேல் விழும். கர்த்தாவே, உமது ஜனங்கள் கடந்துபோகும்வரையும், நீர் மீட்ட ஜனங்களே கடந்துபோகும்வரையும், அவர்கள் உம்முடைய புயத்தின் மகத்துவத்தினால் கல்லைப்போல அசைவற்றிருப்பார்கள்.',	2,	15,	16),
(1938,	'Thou shalt bring them in, and plant them in the mountain of thine inheritance, in the place, O LORD, which thou hast made for thee to dwell in, in the Sanctuary, O LORD, which thy hands have established.',	'நீர் அவர்களைக் கொண்டுபோய், கர்த்தராகிய தேவரீர் வாசம்பண்ணுகிறதற்கு நியமித்த ஸ்தானமாகிய உம்முடைய சுதந்தரத்தின் பர்வதத்திலும், ஆண்டவராகிய தேவரீருடைய கரங்கள் ஸ்தாபித்த பரிசுத்த ஸ்தலத்திலும் அவர்களை நாட்டுவீர்.',	2,	15,	17),
(1939,	'The LORD shall reign for ever and ever.',	'கர்த்தர் சதாகாலங்களாகிய என்றென்றைக்கும் ராஜரிகம்பண்ணுவார்.',	2,	15,	18),
(1940,	'For the horse of Pharaoh went in with his chariots and with his horsemen into the sea, and the LORD brought again the waters of the sea upon them; but the children of Israel went on dry land in the midst of the sea.',	'பார்வோனின் குதிரைகள் அவனுடைய இரதங்களோடும் குதிரைவீரரோடும் சமுத்திரத்தில் பிரவேசித்தது; கர்த்தர் சமுத்திரத்தின் ஜலத்தை அவர்கள்மேல் திரும்பப்பண்ணினார்; இஸ்ரவேல் புத்திரரோ சமுத்திரத்தின் நடுவே வெட்டாந்தரையிலே நடந்துபோனார்கள் என்று பாடினார்கள்.',	2,	15,	19),
(1941,	'And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances.',	'ஆரோனின் சகோதரியாகிய மிரியாம் என்னும் தீர்க்கதரிசியானவளும் தன் கையிலே தம்புரை எடுத்துக்கொண்டாள்; சகல ஸ்திரீகளும் தம்புருகளோடும் நடனத்தோடும் அவளுக்குப் பின்னே புறப்பட்டுப்போனார்கள்.',	2,	15,	20),
(1942,	'And Miriam answered them, Sing ye to the LORD, for he hath triumphed gloriously; the horse and his rider hath he thrown into the sea.',	'மிரியாம் அவர்களுக்குப் பிரதிவசனமாக: கர்த்தரைப் பாடுங்கள், அவர் மகிமையாய் வெற்றிசிறந்தார்; குதிரையையும் குதிரைவீரனையும் கடலிலே தள்ளினார் என்று பாடினாள்.',	2,	15,	21),
(1943,	'So Moses brought Israel from the Red sea, and they went out into the wilderness of Shur; and they went three days in the wilderness, and found no water.',	'பின்பு மோசே இஸ்ரவேல் ஜனங்களைச் சிவந்த சமுத்திரத்திலிருந்து பிரயாணப்படுத்தினான். அவர்கள் சூர்வனாந்தரத்துக்குப் புறப்பட்டுப்போய், மூன்று நாள் வனாந்தரத்தில் தண்ணீர் கிடையாமல் நடந்தார்கள்.',	2,	15,	22),
(1944,	'And when they came to Marah, they could not drink of the waters of Marah, for they were bitter: therefore the name of it was called Marah.',	'அவர்கள் மாராவிலே வந்தபோது, மாராவின் தண்ணீர் கசப்பாயிருந்ததினால் அதைக் குடிக்க அவர்களுக்குக் கூடாதிருந்தது; அதினால் அவ்விடத்துக்கு மாரா என்று பேரிடப்பட்டது.',	2,	15,	23),
(1945,	'And the people murmured against Moses, saying, What shall we drink?',	'அப்பொழுது ஜனங்கள் மோசேக்கு விரோதமாய் முறுமுறுத்து: என்னத்தைக் குடிப்போம் என்றார்கள்.',	2,	15,	24),
(1946,	'And he cried unto the LORD; and the LORD shewed him a tree, which when he had cast into the waters, the waters were made sweet: there he made for them a statute and an ordinance, and there he proved them,',	'மோசே கர்த்தரை நோக்கிக் கூப்பிட்டான்; அப்பொழுது கர்த்தர் மோசேக்கு ஒரு மரத்தைக் காண்பித்தார்; அதை அவன் தண்ணீரில் போட்டவுடனே, அது மதுரமான தண்ணீராயிற்று. அவர் அங்கே அவர்களுக்கு ஒரு நியமத்தையும், ஒரு நியாயத்தையும் கட்டளையிட்டு, அங்கே அவர்களைச் சோதித்து:',	2,	15,	25),
(1947,	'And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee.',	'நீ உன் தேவனாகிய கர்த்தரின் சத்தத்தைக் கவனமாய்க் கேட்டு, அவர் பார்வைக்குச் செம்மையானவைகளைச் செய்து, அவர் கட்டளைகளுக்குச் செவிகொடுத்து, அவருடைய நியமங்கள் யாவையும் கைக்கொண்டால், நான் எகிப்தியருக்கு வரப்பண்ணின வியாதிகளில் ஒன்றையும் உனக்கு வரப்பண்ணேன்; நானே உன் பரிகாரியாகிய கர்த்தர் என்றார்.',	2,	15,	26),
(1948,	'And they came to Elim, where were twelve wells of water, and threescore and ten palm trees: and they encamped there by the waters.',	'பின்பு அவர்கள் ஏலிமுக்கு வந்தார்கள்; அங்கே பன்னிரண்டு நீரூற்றுகளும் எழுபது பேரீச்சமரங்களும் இருந்தது; அங்கே தண்ணீர் அருகே பாளயமிறங்கினார்கள்.  ',	2,	15,	27),
(1949,	'And they took their journey from Elim, and all the congregation of the children of Israel came unto the wilderness of Sin, which is between Elim and Sinai, on the fifteenth day of the second month after their departing out of the land of Egypt.',	'இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் ஏலிமைவிட்டுப் பிரயாணம்பண்ணி, எகிப்து தேசத்திலிருந்து புறப்பட்ட இரண்டாம் மாதம் பதினைந்தாம் தேதியிலே, ஏலிமுக்கும் சீனாய்க்கும் நடுவே இருக்கிற சீன்வனாந்தரத்தில் சேர்ந்தார்கள்.',	2,	16,	1),
(1950,	'And the whole congregation of the children of Israel murmured against Moses and Aaron in the wilderness:',	'அந்த வனாந்தரத்திலே இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் மோசேக்கும் ஆரோனுக்கும் விரோதமாக முறுமுறுத்து:',	2,	16,	2),
(1951,	'And the children of Israel said unto them, Would to God we had died by the hand of the LORD in the land of Egypt, when we sat by the flesh pots, and when we did eat bread to the full; for ye have brought us forth into this wilderness, to kill this whole assembly with hunger.',	'நாங்கள் இறைச்சிப் பாத்திரங்களண்டையிலே உட்கார்ந்து அப்பத்தைத் திருப்தியாகச் சாப்பிட்ட எகிப்து தேசத்திலே, கர்த்தரின் கையால் செத்துப்போனோமானால் தாவிளை; இந்தக் கூட்டம் முழுவதையும் பட்டினியினால் கொல்லும்படி நீங்கள் எங்களைப் புறப்படப்பண்ணி, இந்த வனாந்தரத்திலே அழைத்துவந்தீர்களே என்று அவர்களிடத்தில் சொன்னார்கள்.',	2,	16,	3),
(1952,	'Then said the LORD unto Moses, Behold, I will rain bread from heaven for you; and the people shall go out and gather a certain rate every day, that I may prove them, whether they will walk in my law, or no.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நான் உங்களுக்கு வானத்திலிருந்து அப்பம் வருஷிக்கப்பண்ணுவேன்; ஜனங்கள் போய், ஒவ்வொரு நாளுக்கு வேண்டியதை ஒவ்வொரு நாளிலும் சேர்த்துக்கொள்ளவேண்டும்; அதினால் அவர்கள் என் நியாயப்பிரமாணத்தின்படி நடப்பார்களோ நடக்கமாட்டார்களோ என்று அவர்களைச் சோதிப்பேன்.',	2,	16,	4),
(1953,	'And it shall come to pass, that on the sixth day they shall prepare that which they bring in; and it shall be twice as much as they gather daily.',	'ஆறாம் நாளிலோ, அவர்கள் நாள்தோறும் சேர்க்கிறதைப்பார்க்கிலும் இரண்டத்தனையாய்ச் சேர்த்து, அதை ஆயத்தம்பண்ணி வைக்கக்கடவர்கள் என்றார்.',	2,	16,	5),
(1954,	'And Moses and Aaron said unto all the children of Israel, At even, then ye shall know that the LORD hath brought you out from the land of Egypt:',	'அப்பொழுது மோசேயும் ஆரோனும் இஸ்ரவேல் புத்திரர் எல்லாரையும் நோக்கி: கர்த்தர் உங்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினவர் என்பதைச் சாயங்காலத்தில் அறிவீர்கள்;',	2,	16,	6),
(1955,	'And in the morning, then ye shall see the glory of the LORD; for that he heareth your murmurings against the LORD: and what are we, that ye murmur against us?',	'விடியற்காலத்தில் கர்த்தருடைய மகிமையையும் காண்பீர்கள்; கர்த்தருக்கு விரோதமான உங்கள் முறுமுறுப்புகளை அவர் கேட்டார்; நீங்கள் எங்களுக்கு விரோதமாய் முறுமுறுக்கிறதற்கு நாங்கள் எம்மாத்திரம் என்றார்கள்.',	2,	16,	7),
(1956,	'And Moses said, This shall be, when the LORD shall give you in the evening flesh to eat, and in the morning bread to the full; for that the LORD heareth your murmurings which ye murmur against him: and what are we? your murmurings are not against us, but against the LORD.',	'பின்னும் மோசே: சாயங்காலத்தில் நீங்கள் புசிக்கிறதற்குக் கர்த்தர் உங்களுக்கு இறைச்சியையும், விடியற்காலத்தில் நீங்கள் திருப்தியடைகிறதற்கு அப்பத்தையும் கொடுக்கையில் இது விளங்கும்; கர்த்தருக்கு விரோதமாக நீங்கள் முறுமுறுத்த உங்கள் முறுமுறுப்புகளை அவர் கேட்டார்; நாங்கள் எம்மாத்திரம்? உங்கள் முறுமுறுப்புகள் எங்களுக்கு அல்ல, கர்த்தருக்கே விரோதமாய் இருக்கிறது என்றான்.',	2,	16,	8),
(1957,	'And Moses spake unto Aaron, Say unto all the congregation of the children of Israel, Come near before the LORD: for he hath heard your murmurings.',	'அப்பொழுது மோசே ஆரோனைப் பார்த்து: நீ இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரையும் நோக்கி: கர்த்தருடைய சந்நிதியில் சேருங்கள், அவர் உங்கள் முறுமுறுப்புகளைக் கேட்டார் என்று சொல் என்றான்.',	2,	16,	9),
(1958,	'And it came to pass, as Aaron spake unto the whole congregation of the children of Israel, that they looked toward the wilderness, and, behold, the glory of the LORD appeared in the cloud.',	'ஆரோன் இஸ்ரவேல் புத்திரராகிய சபையாருக்கெல்லாம் இதைச் சொல்லுகிறபோது, அவர்கள் வனாந்தரதிசையாகத் திரும்பிப்பார்த்தார்கள்; அப்பொழுது கர்த்தருடைய மகிமை மேகத்திலே காணப்பட்டது.',	2,	16,	10),
(1959,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	2,	16,	11),
(1960,	'I have heard the murmurings of the children of Israel: speak unto them, saying, At even ye shall eat flesh, and in the morning ye shall be filled with bread; and ye shall know that I am the LORD your God.',	'இஸ்ரவேல் புத்திரரின் முறுமுறுப்புகளைக் கேட்டிருக்கிறேன்; நீ அவர்களோடே பேசி, நீங்கள் சாயங்காலத்தில் இறைச்சியைப் புசித்து, விடியற்காலத்தில் அப்பத்தால் திருப்தியாகி, நான் உங்கள் தேவனாகிய கர்த்தர் என்பதை அறிந்துகொள்வீர்கள் என்று சொல் என்றார்.',	2,	16,	12),
(1961,	'And it came to pass, that at even the quails came up, and covered the camp: and in the morning the dew lay round about the host.',	'சாயங்காலத்தில் காடைகள் வந்து விழுந்து பாளயத்தை மூடிக்கொண்டது. விடியற்காலத்தில் பாளயத்தைச் சுற்றி பனி பெய்திருந்தது.',	2,	16,	13),
(1962,	'And when the dew that lay was gone up, behold, upon the face of the wilderness there lay a small round thing, as small as the hoar frost on the ground.',	'பெய்திருந்த பனி நீங்கினபின், இதோ, வனாந்தரத்தின்மீதெங்கும் உருட்சியான ஒரு சிறிய வஸ்து உறைந்த பனிக்கட்டிப் பொடியத்தனையாய்த் தரையின்மேல் கிடந்தது.',	2,	16,	14),
(1963,	'And when the children of Israel saw it, they said one to another, It is manna: for they wist not what it was. And Moses said unto them, This is the bread which the LORD hath given you to eat.',	'இஸ்ரவேல் புத்திரர் அதைக் கண்டு, அது இன்னது என்று அறியாதிருந்து, ஒருவரை ஒருவர் பார்த்து, இது என்ன என்றார்கள்; அப்பொழுது மோசே அவர்களை நோக்கி: இது கர்த்தர் உங்களுக்குப் புசிக்கக்கொடுத்த அப்பம்.',	2,	16,	15),
(1964,	'This is the thing which the LORD hath commanded, Gather of it every man according to his eating, an omer for every man, according to the number of your persons; take ye every man for them which are in his tents.',	'கர்த்தர் கட்டளையிடுகிறது என்னவென்றால், அவரவர் புசிக்கும் அளவுக்குத் தக்கதாக அதில் எடுத்துச் சேர்க்கக்கடவீர்கள்; உங்களிலுள்ள ஆத்துமாக்களின் இலக்கத்தின்படி, அவனவன் தன் தன் கூடாரத்தில் இருக்கிறவர்களுக்காக தலைக்கு ஒரு ஓமர் அளவு எடுத்துக்கொள்ளக்கடவன் என்றான்.',	2,	16,	16),
(1965,	'And the children of Israel did so, and gathered, some more, some less.',	'இஸ்ரவேல் புத்திரர் அப்படியே செய்து, சிலர் மிகுதியாயும் சிலர் கொஞ்சமாயும் சேர்த்தார்கள்.',	2,	16,	17),
(1966,	'And when they did mete it with an omer, he that gathered much had nothing over, and he that gathered little had no lack; they gathered every man according to his eating.',	'பின்பு, அதை ஓமரால் அளந்தார்கள்: மிகுதியாய்ச் சேர்த்தவனுக்கு மீதியானதும் இல்லை, கொஞ்சமாய்ச் சேர்த்தவனுக்குக் குறைவானதும் இல்லை; அவரவர் தாங்கள் புசிக்கும் அளவுக்குத்தக்கதாகச் சேர்த்தார்கள்.',	2,	16,	18),
(1967,	'And Moses said, Let no man leave of it till the morning.',	'மோசே அவர்களை நோக்கி: ஒருவனும் விடியற்காலம்மட்டும் அதில் ஒன்றும் வைக்கக்கூடாது என்று அவர்களுக்குச் சொல்லியும்;',	2,	16,	19),
(1968,	'Notwithstanding they hearkened not unto Moses; but some of them left of it until the morning, and it bred worms, and stank: and Moses was wroth with them.',	'மோசேயின் சொல் கேளாமல், சிலர் அதில் விடியற்காலம்மட்டும் கொஞ்சம் மீதியாய் வைத்தார்கள்; அது பூச்சி பிடித்து நாற்றமெடுத்தது. அவர்கள்மேல் மோசே கோபங்கொண்டான்.',	2,	16,	20),
(1969,	'And they gathered it every morning, every man according to his eating: and when the sun waxed hot, it melted.',	'அதை விடியற்காலந்தோறும் அவரவர் புசிக்கும் அளவுக்குத்தக்கதாகச் சேர்த்தார்கள், வெயில் ஏறஏற அது உருகிப்போகும்.',	2,	16,	21),
(1970,	'And it came to pass, that on the sixth day they gathered twice as much bread, two omers for one man: and all the rulers of the congregation came and told Moses.',	'ஆறாம் நாளில் தலைக்கு இரண்டு ஓமர் வீதமாக இரண்டத்தனையாய் ஆகாரம் சேர்த்தார்கள்; அப்பொழுது சபையின் தலைவர் எல்லாரும் வந்து, அதை மோசேக்கு அறிவித்தார்கள்.',	2,	16,	22),
(1971,	'And he said unto them, This is that which the LORD hath said, To morrow is the rest of the holy sabbath unto the LORD: bake that which ye will bake to day, and seethe that ye will seethe; and that which remaineth over lay up for you to be kept until the morning.',	'அவன் அவர்களை நோக்கி: கர்த்தர் சொன்னது இதுதான்; நாளைக்குக் கர்த்தருக்குரிய பரிசுத்த ஓய்வுநாளாகிய ஓய்வு; நீங்கள் சுடவேண்டியதைச் சுட்டு, வேவிக்கவேண்டியதை வேவித்து, மீதியாயிருக்கிறதையெல்லாம் நாளைமட்டும் உங்களுக்காக வைத்துவையுங்கள் என்றான்.',	2,	16,	23),
(1972,	'And they laid it up till the morning, as Moses bade: and it did not stink, neither was there any worm therein.',	'மோசே கட்டளையிட்டபடியே, அதை மறுநாள்வரைக்கும் வைத்துவைத்தார்கள்; அப்பொழுது அது நாறவும் இல்லை, அதிலே பூச்சிபிடிக்கவும் இல்லை.',	2,	16,	24),
(1973,	'And Moses said, Eat that to day; for to day is a sabbath unto the LORD: to day ye shall not find it in the field.',	'அப்பொழுது மோசே; அதை இன்றைக்குப் புசியுங்கள்; இன்று கர்த்தருக்குரிய ஓய்வுநாள்; இன்று நீங்கள் அதை வெளியிலே காணமாட்டீர்கள்.',	2,	16,	25),
(1974,	'Six days ye shall gather it; but on the seventh day, which is the sabbath, in it there shall be none.',	'ஆறுநாளும் அதைச் சேர்ப்பீர்களாக; ஏழாம்நாள் ஓய்வுநாளாயிருக்கிறது; அதிலே அது உண்டாயிராது என்றான்.',	2,	16,	26),
(1975,	'And it came to pass, that there went out some of the people on the seventh day for to gather, and they found none.',	'ஏழாம்நாளில் ஜனங்களில் சிலர் அதைச் சேர்க்கப் புறப்பட்டார்கள்; அவர்கள் அதைக் காணவில்லை.',	2,	16,	27),
(1976,	'And the LORD said unto Moses, How long refuse ye to keep my commandments and my laws?',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: என் கட்டளைகளையும் என் பிரமாணங்களையும் கைக்கொள்ள எந்தமட்டும் மனதில்லாதிருப்பீர்கள்?',	2,	16,	28),
(1977,	'See, for that the LORD hath given you the sabbath, therefore he giveth you on the sixth day the bread of two days; abide ye every man in his place, let no man go out of his place on the seventh day.',	'பாருங்கள், கர்த்தர் உங்களுக்கு ஓய்வுநாளை அருளினபடியால், அவர் உங்களுக்கு ஆறாம்நாளில் இரண்டு நாளுக்கு வேண்டிய ஆகாரத்தைக் கொடுக்கிறார்; ஏழாம்நாளில் உங்களில் ஒருவனும் தன்தன் ஸ்தானத்திலிருந்து புறப்படாமல், அவனவன் தன்தன் ஸ்தானத்திலே இருக்கவேண்டும் என்றார்.',	2,	16,	29),
(1978,	'So the people rested on the seventh day.',	'அப்படியே ஜனங்கள் ஏழாம்நாளில் ஓய்ந்திருந்தார்கள்.',	2,	16,	30),
(1979,	'And the house of Israel called the name thereof Manna: and it was like coriander seed, white; and the taste of it was like wafers made with honey.',	'இஸ்ரவேல் வம்சத்தார் அதற்கு மன்னா என்று பேரிட்டார்கள்; அது கொத்துமல்லி அளவாயும் வெண்மைநிறமாயும் இருந்தது, அதின் ருசி தேனிட்ட பணிகாரத்திற்கு ஒப்பாயிருந்தது.',	2,	16,	31),
(1980,	'And Moses said, This is the thing which the LORD commandeth, Fill an omer of it to be kept for your generations; that they may see the bread wherewith I have fed you in the wilderness, when I brought you forth from the land of Egypt.',	'அப்பொழுது மோசே: கர்த்தர் கட்டளையிட்ட காரியம் என்னவென்றால், நான் உங்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினபோது, வனாந்தரத்தில் உங்களுக்குப் புசிக்கக்கொடுத்த அப்பத்தை உங்கள் சந்ததியார் பார்க்கும்படிக்கு, அவர்களுக்காக அதைப் காப்பதற்கு, அதிலே ஒரு ஓமர் நிறைய எடுத்து வைக்கவேண்டும் என்றான்.',	2,	16,	32),
(1981,	'And Moses said unto Aaron, Take a pot, and put an omer full of manna therein, and lay it up before the LORD, to be kept for your generations.',	'மேலும், மோசே ஆரோனை நோக்கி: நீ ஒரு கலசத்தை எடுத்து, அதிலே ஒரு ஓமர் அளவு மன்னாவைப் போட்டு, அதை உங்கள் சந்ததியாருக்காகக் காப்பதற்குக் கர்த்தருடைய சந்நிதியிலே வை என்றான்.',	2,	16,	33),
(1982,	'As the LORD commanded Moses, so Aaron laid it up before the Testimony, to be kept.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அது காக்கப்படும்படி ஆரோன் அதைச் சாட்சி சந்நிதியில் வைத்தான்.',	2,	16,	34),
(1983,	'And the children of Israel did eat manna forty years, until they came to a land inhabited; they did eat manna, until they came unto the borders of the land of Canaan.',	'இஸ்ரவேல் புத்திரர் குடியிருப்பான தேசத்துக்கு வருமட்டும் நாற்பது வருஷமளவும் மன்னாவைப் புசித்தார்கள்; அவர்கள் கானான் தேசத்தின் எல்லையில் சேரும்வரைக்கும் மன்னாவைப் புசித்தார்கள்.',	2,	16,	35),
(1984,	'Now an omer is the tenth part of an ephah.',	'ஒரு ஓமரானது எப்பாவிலே பத்தில் ஒரு பங்கு.  ',	2,	16,	36),
(1985,	'And all the congregation of the children of Israel journeyed from the wilderness of Sin, after their journeys, according to the commandment of the LORD, and pitched in Rephidim: and there was no water for the people to drink.',	'பின்பு இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் கர்த்தருடைய கட்டளையின்படியே சீன்வனாந்தரத்திலிருந்து புறப்பட்டு, பிரயாணம்பண்ணி, ரெவிதீமிலே வந்து பாளயமிறங்கினார்கள்; அங்கே ஜனங்களுக்குக் குடிக்கத் தண்ணீர் இல்லாதிருந்தது.',	2,	17,	1),
(1986,	'Wherefore the people did chide with Moses, and said, Give us water that we may drink. And Moses said unto them, Why chide ye with me? wherefore do ye tempt the LORD?',	'அப்பொழுது ஜனங்கள் மோசேயோடே வாதாடி: நாங்கள் குடிக்கிறதற்கு எங்களுக்குத் தண்ணீர் தரவேண்டும் என்றார்கள். அதற்கு மோசே: என்னோடே ஏன் வாதாடுகிறீர்கள், கர்த்தரை ஏன் பரீட்சை பார்க்கிறீர்கள் என்றான்.',	2,	17,	2),
(1987,	'And the people thirsted there for water; and the people murmured against Moses, and said, Wherefore is this that thou hast brought us up out of Egypt, to kill us and our children and our cattle with thirst?',	'ஜனங்கள் அவ்விடத்திலே தண்ணீர்த் தவனமாயிருந்தபடியால், அவர்கள் மோசேக்கு விரோதமாய் முறுமுறுத்து: நீர் எங்களையும் எங்கள் பிள்ளைகளையும் எங்கள் ஆடுமாடுகளையும் தண்ணீர்த் தவனத்தினால் கொன்றுபோட எங்களை எகிப்திலிருந்து ஏன் கொண்டுவந்தீர் என்றார்கள்.',	2,	17,	3),
(1988,	'And Moses cried unto the LORD, saying, What shall I do unto this people? they be almost ready to stone me.',	'மோசே கர்த்தரை நோக்கிக் கூப்பிட்டு: இந்த ஜனங்களுக்கு நான் என்ன செய்வேன், இவர்கள் என்மேல் கல்லெறியப் பார்க்கிறார்களே என்றான்.',	2,	17,	4),
(1989,	'And the LORD said unto Moses, Go on before the people, and take with thee of the elders of Israel; and thy rod, wherewith thou smotest the river, take in thine hand, and go.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ இஸ்ரவேல் மூப்பரில் சிலரை உன்னோடே கூட்டிக்கொண்டு, நீ நதியை அடித்த உன் கோலை உன் கையிலே பிடித்துக்கொண்டு, ஜனங்களுக்கு முன்னே நடந்துபோ.',	2,	17,	5),
(1990,	'Behold, I will stand before thee there upon the rock in Horeb; and thou shalt smite the rock, and there shall come water out of it, that the people may drink. And Moses did so in the sight of the elders of Israel.',	'அங்கே ஓரேபிலே நான் உனக்கு முன்பாகக் கன்மலையின்மேல் நிற்பேன்; நீ அந்தக் கன்மலையை அடி; அப்பொழுது ஜனங்கள் குடிக்க அதிலிருந்து தண்ணீர் புறப்படும் என்றார்; அப்படியே மோசே இஸ்ரவேல் மூப்பரின் கண்களுக்கு முன்பாகச் செய்தான்.',	2,	17,	6),
(1991,	'And he called the name of the place Massah, and Meribah, because of the chiding of the children of Israel, and because they tempted the LORD, saying, Is the LORD among us, or not?',	'இஸ்ரவேல் புத்திரர் வாதாடினதினிமித்தமும், கர்த்தர் எங்கள் நடுவில் இருக்கிறாரா இல்லையா என்று அவர்கள் கர்த்தரைப் பரீட்சை பார்த்ததினிமித்தமும், அவன் அந்த ஸ்தலத்திற்கு மாசா என்றும் மேரிபா என்றும் பேரிட்டான்.',	2,	17,	7),
(1992,	'Then came Amalek, and fought with Israel in Rephidim.',	'அமலேக்கியர் வந்து ரெவிதீமிலே இஸ்ரவேலரோடே யுத்தம்பண்ணினார்கள்.',	2,	17,	8),
(1993,	'And Moses said unto Joshua, Choose us out men, and go out, fight with Amalek: to morrow I will stand on the top of the hill with the rod of God in mine hand.',	'அப்பொழுது மோசே யோசுவாவை நோக்கி: நீ நமக்காக மனிதரைத் தெரிந்துகொண்டு, புறப்பட்டு, அமலேக்கோடே யுத்தம்பண்ணு; நாளைக்கு நான் மலையுச்சியில் தேவனுடைய கோலை என் கையில் பிடித்துக்கொண்டு நிற்பேன் என்றான்.',	2,	17,	9),
(1994,	'So Joshua did as Moses had said to him, and fought with Amalek: and Moses, Aaron, and Hur went up to the top of the hill.',	'யோசுவா தனக்கு மோசே சொன்னபடியே செய்து, அமலேக்கோடே யுத்தம்பண்ணினான். மோசேயும் ஆரோனும் ஊர் என்பவனும் மலையுச்சியில் ஏறினார்கள்.',	2,	17,	10),
(1995,	'And it came to pass, when Moses held up his hand, that Israel prevailed: and when he let down his hand, Amalek prevailed.',	'மோசே தன் கையை ஏறெடுத்திருக்கையில், இஸ்ரவேலர் மேற்கொண்டார்கள்; அவன் தன் கையைத் தாழவிடுகையில், அமலேக்கு மேற்கொண்டான்.',	2,	17,	11),
(1996,	'But Moses hands were heavy; and they took a stone, and put it under him, and he sat thereon; and Aaron and Hur stayed up his hands, the one on the one side, and the other on the other side; and his hands were steady until the going down of the sun.',	'மோசேயின் கைகள் அசந்துபோயிற்று, அப்பொழுது அவர்கள் ஒரு கல்லைக் கொண்டுவந்து அவன் கீழே வைத்தார்கள்; அதின்மேல் உட்கார்ந்தான்; ஆரோனும் ஊரும் ஒருவன் ஒரு பக்கத்திலும் ஒருவன் மறு பக்கத்திலும் இருந்து, அவன் கைகளைத் தாங்கினார்கள்; இவ்விதமாய் அவன் கைகள் சூரியன் அஸ்தமிக்கும்வரைக்கும் ஒரே நிலையாயிருந்தது.',	2,	17,	12),
(1997,	'And Joshua discomfited Amalek and his people with the edge of the sword.',	'யோசுவா அமலேக்கையும் அவன் ஜனங்களையும் பட்டயக்கருக்கினாலே முறிய அடித்தான்.',	2,	17,	13),
(1998,	'And the LORD said unto Moses, Write this for a memorial in a book, and rehearse it in the ears of Joshua: for I will utterly put out the remembrance of Amalek from under heaven.',	'பின்பு கர்த்தர் மோசேயை நோக்கி: இதை நினைவுகூரும்பொருட்டு, நீ ஒரு புஸ்தகத்தில் எழுதி, யோசுவாவின் செவி கேட்கும்படி வாசி. அமலேக்கை வானத்தின் கீழெங்கும் இராதபடிக்கு நாசம் பண்ணுவேன் என்றார்.',	2,	17,	14),
(1999,	'And Moses built an altar, and called the name of it Jehovahnissi:',	'மோசே ஒரு பலிபீடத்தைக் கட்டி, அதற்கு யேகோவாநிசி என்று பேரிட்டு,',	2,	17,	15),
(2000,	'For he said, Because the LORD hath sworn that the LORD will have war with Amalek from generation to generation.',	'அமலேக்கின் கை கர்த்தருடைய சிங்காசனத்துக்கு விரோதமாயிருந்தபடியால், தலைமுறை தலைமுறைதோறும் அவனுக்கு விரோதமாய் கர்த்தரின் யுத்தம் நடக்கும் என்றான்.  ',	2,	17,	16),
(2001,	'When Jethro, the priest of Midian, Moses\' father in law, heard of all that God had done for Moses, and for Israel his people, and that the LORD had brought Israel out of Egypt;',	'தேவன் மோசேக்கும் தமது ஜனமாகிய இஸ்ரவேலுக்கும் செய்த யாவையும், கர்த்தர் இஸ்ரவேலை எகிப்திலிருந்து புறப்படப்பண்ணினதையும், மீதியானில் ஆசாரியனாயிருந்த மோசேயின் மாமனாகிய எத்திரோ கேள்விப்பட்டபோது,',	2,	18,	1),
(2002,	'Then Jethro, Moses\' father in law, took Zipporah, Moses\' wife, after he had sent her back,',	'மோசேயின் மாமனாகிய எத்திரோ, மோசேயினாலே திரும்பி அனுப்பிவிடப்பட்டிருந்த அவன் மனைவியாகிய சிப்போராளையும்,',	2,	18,	2),
(2003,	'And her two sons; of which the name of the one was Gershom; for he said, I have been an alien in a strange land:',	'அவளுடைய இரண்டு குமாரரையும் கூட்டிக்கொண்டு பிரயாணப்பட்டான். நான் அந்நிய தேசத்திலே பரதேசியானேன் என்று மோசே சொல்லி, ஒரு மகனுக்குக் கெர்சோம் என்று பேரிட்டிருந்தான்.',	2,	18,	3),
(2004,	'And the name of the other was Eliezer; for the God of my father, said he, was mine help, and delivered me from the sword of Pharaoh:',	'என் பிதாவின் தேவன் எனக்குத் துணைநின்று பார்வோனின் பட்டயத்துக்கு என்னைத் தப்புவித்தார் என்று சொல்லி, மற்றவனுக்கு எலியேசர் என்று பேரிட்டிருந்தான்.',	2,	18,	4),
(2005,	'And Jethro, Moses\' father in law, came with his sons and his wife unto Moses into the wilderness, where he encamped at the mount of God:',	'மோசேயின் மாமனாகிய எத்திரோ மோசேயின் குமாரரோடும் அவன் மனைவியோடுங்கூட, அவன் பாளயமிறங்கியிருந்த தேவ பர்வதத்தினிடத்தில் வனாந்தரத்துக்கு வந்து:',	2,	18,	5),
(2006,	'And he said unto Moses, I thy father in law Jethro am come unto thee, and thy wife, and her two sons with her.',	'எத்திரோ என்னும் உம்முடைய மாமனாகிய நானும், உம்முடைய மனைவியும், அவளோடேகூட அவளுடைய இரண்டு குமாரரும் உம்மிடத்திற்கு வந்திருக்கிறோம் என்று மோசேக்குச் சொல்லியனுப்பினான்.',	2,	18,	6),
(2007,	'And Moses went out to meet his father in law, and did obeisance, and kissed him; and they asked each other of their welfare; and they came into the tent.',	'அப்பொழுது மோசே தன் மாமனுக்கு எதிர்கொண்டுபோய், அவனை வணங்கி, முத்தஞ்செய்தான்; ஒருவரை ஒருவர் சுகசெய்தி விசாரித்துக்கொண்டு, கூடாரத்துக்குள் பிரவேசித்தார்கள்.',	2,	18,	7),
(2008,	'And Moses told his father in law all that the LORD had done unto Pharaoh and to the Egyptians for Israel\'s sake, and all the travail that had come upon them by the way, and how the LORD delivered them.',	'பின்பு மோசே கர்த்தர் இஸ்ரவேலினிமித்தம் பார்வோனுக்கும் எகிப்தியருக்கும் செய்த எல்லாவற்றையும், வழியிலே தங்களுக்கு நேரிட்ட எல்லா வருத்தத்தையும், கர்த்தர் தங்களை விடுவித்து இரட்சித்ததையும் தன் மாமனுக்கு விவரித்துச் சொன்னான்.',	2,	18,	8),
(2009,	'And Jethro rejoiced for all the goodness which the LORD had done to Israel, whom he had delivered out of the hand of the Egyptians.',	'கர்த்தர் இஸ்ரவேலரை எகிப்தியரின் கைக்குத் தப்புவித்து, அவர்களுக்குச் செய்த சகல நன்மைகளையுங்குறித்து எத்திரோ சந்தோஷப்பட்டு:',	2,	18,	9),
(2010,	'And Jethro said, Blessed be the LORD, who hath delivered you out of the hand of the Egyptians, and out of the hand of Pharaoh, who hath delivered the people from under the hand of the Egyptians.',	'உங்களை எகிப்தியரின் கைக்கும் பார்வோனின் கைக்கும் தப்புவித்து, எகிப்தியருடைய கையின் கீழிருந்த ஜனத்தை விடுவித்த கர்த்தருக்கு ஸ்தோத்திரம்.',	2,	18,	10),
(2011,	'Now I know that the LORD is greater than all gods: for in the thing wherein they dealt proudly he was above them.',	'கர்த்தர் எல்லாத் தேவர்களைப்பார்க்கிலும் பெரியவர் என்பதை இப்பொழுது அறிந்திருக்கிறேன்; அவர்கள் இடும்பு செய்த காரியத்தில் அவர்களை மேற்கொண்டார் என்று சொல்லி;',	2,	18,	11),
(2012,	'And Jethro, Moses\' father in law, took a burnt offering and sacrifices for God: and Aaron came, and all the elders of Israel, to eat bread with Moses\' father in law before God.',	'மோசேயின் மாமனாகிய எத்திரோ சர்வாங்கதகனபலியையும் மற்றப் பலிகளையும் தேவனுக்குக் கொண்டுவந்து செலுத்தினான். பின்பு ஆரோனும் இஸ்ரவேல் மூப்பர் அனைவரும் வந்து, மோசேயின் மாமனுடனே தேவசமுகத்தில் போஜனம்பண்ணினார்கள்.',	2,	18,	12),
(2013,	'And it came to pass on the morrow, that Moses sat to judge the people: and the people stood by Moses from the morning unto the evening.',	'மறுநாள் மோசே ஜனங்களை நியாயம் விசாரிக்க உட்கார்ந்தான்; ஜனங்கள் காலமே துவக்கிச் சாயங்காலம்மட்டும் மோசேக்கு முன்பாக நின்றார்கள்.',	2,	18,	13),
(2014,	'And when Moses\' father in law saw all that he did to the people, he said, What is this thing that thou doest to the people? why sittest thou thyself alone, and all the people stand by thee from morning unto even?',	'ஜனங்களுக்கு அவன் செய்த யாவையும் மோசேயின் மாமன் கண்டு: நீர் ஜனங்களுக்குச் செய்கிற இந்தக் காரியம் என்ன? நீர் ஒன்றியாய் உட்கார்ந்திருக்கவும், ஜனங்கள் எல்லாரும் காலமே துவக்கிச் சாயங்காலம்மட்டும் உமக்கு முன்பாக நிற்கவும் வேண்டியது என்ன என்றான்.',	2,	18,	14),
(2015,	'And Moses said unto his father in law, Because the people come unto me to enquire of God:',	'அப்பொழுது மோசே தன் மாமனை நோக்கி: தேவனிடத்தில் விசாரிக்கும்படி ஜனங்கள் என்னிடத்தில் வருகிறார்கள்.',	2,	18,	15),
(2016,	'When they have a matter, they come unto me; and I judge between one and another, and I do make them know the statutes of God, and his laws.',	'அவர்களுக்கு யாதொரு காரியம் உண்டானால், என்னிடத்தில் வருகிறார்கள்; நான் அவர்களுக்குள்ள வழக்கைத் தீர்த்து, தேவகட்டளைகளையும் அவருடைய பிரமாணங்களையும் தெரிவிக்கிறேன் என்றான்.',	2,	18,	16),
(2017,	'And Moses\' father in law said unto him, The thing that thou doest is not good.',	'அதற்கு மோசேயின் மாமன்: நீர் செய்கிற காரியம் நல்லதல்ல;',	2,	18,	17),
(2018,	'Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone.',	'நீரும் உம்மோடே இருக்கிற ஜனங்களும் தொய்ந்துபோவீர்கள்; இது உமக்கு மிகவும் பாரமான காரியம்; நீர் ஒருவராய் அதைச் செய்ய உம்மாலே கூடாது.',	2,	18,	18),
(2019,	'Hearken now unto my voice, I will give thee counsel, and God shall be with thee: Be thou for the people to God-ward, that thou mayest bring the causes unto God:',	'இப்பொழுது என் சொல்லைக்கேளும், உமக்கு ஒரு ஆலோசனை சொல்லுகிறேன்; தேவனும் உம்மோடுகூட இருப்பார், நீர் தேவசந்நிதியிலே ஜனங்களுக்காக இரும்; விசேஷித்தவைகளைத் தேவனிடத்தில் கொண்டுபோய்;',	2,	18,	19),
(2020,	'And thou shalt teach them ordinances and laws, and shalt shew them the way wherein they must walk, and the work that they must do.',	'கட்டளைகளையும் பிரமாணங்களையும் அவர்களுக்கு வெளிப்படுத்தி; அவர்கள் நடக்கவேண்டிய வழியையும், அவர்கள் செய்யவேண்டிய காரியத்தையும் அவர்களுக்குத் தெரியப்படுத்தும்.',	2,	18,	20),
(2021,	'Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and rulers of hundreds, rulers of fifties, and rulers of tens:',	'ஜனங்கள் எல்லாருக்குள்ளும் தேவனுக்குப் பயந்தவர்களும் உண்மையுள்ளவர்களும் பொருளாசையை வெறுக்கிறவர்களுமான திறமையுள்ள மனிதரைத் தெரிந்துகொண்டு, அவர்களை ஆயிரம்பேருக்கு அதிபதிகளாகவும், நூறுபேருக்கு அதிபதிகளாகவும், ஐம்பதுபேருக்கு அதிபதிகளாகவும், பத்துப்பேருக்கு அதிபதிகளாகவும் ஏற்படுத்தும்.',	2,	18,	21),
(2022,	'And let them judge the people at all seasons: and it shall be, that every great matter they shall bring unto thee, but every small matter they shall judge: so shall it be easier for thyself, and they shall bear the burden with thee.',	'அவர்கள் எப்பொழுதும் ஜனங்களை நியாயம் விசாரித்து, பெரிய காரியங்கள் யாவையும் உம்மிடத்தில் கொண்டுவரட்டும், சிறிய காரியங்கள் யாவையும் தாங்களே தீர்க்கட்டும்; இப்படி அவர்கள் உம்மோடேகூட இந்தப் பாரத்தைச் சுமந்தால், உமக்கு இலகுவாயிருக்கும்.',	2,	18,	22),
(2023,	'If thou shalt do this thing, and God command thee so, then thou shalt be able to endure, and all this people shall also go to their place in peace.',	'இந்தப்பிரகாரம் நீர் செய்வதும், இப்படித் தேவன் உமக்குக் கட்டளையிடுவதும் உண்டானால், உம்மாலே தாங்கக்கூடும்; இந்த ஜனங்கள் எல்லாரும் தாங்கள் போகும் இடத்துக்குச் சுகமாய்ப் போய்ச் சேரலாம் என்றான்.',	2,	18,	23),
(2024,	'So Moses hearkened to the voice of his father in law, and did all that he had said.',	'மோசே தன் மாமன் சொல்கேட்டு, அவன் சொன்னபடியெல்லாம் செய்தான்.',	2,	18,	24),
(2025,	'And Moses chose able men out of all Israel, and made them heads over the people, rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.',	'மோசே இஸ்ரவேலர் எல்லாரிலும் திறமையுள்ள மனிதரைத் தெரிந்துகொண்டு, அவர்களை ஆயிரம்பேருக்கு அதிபதிகளாகவும், நூறுபேருக்கு அதிபதிகளாகவும், ஐம்பதுபேருக்கு அதிபதிகளாகவும், பத்துப்பேருக்கு அதிபதிகளாகவும் ஜனங்கள்மேல் தலைவராக்கினான்.',	2,	18,	25),
(2026,	'And they judged the people at all seasons: the hard causes they brought unto Moses, but every small matter they judged themselves.',	'அவர்கள் எப்பொழுதும் ஜனங்களை நியாயம் விசாரித்தார்கள்; வருத்தமான காரியங்களைமாத்திரம் மோசேயினிடத்தில் கொண்டுவந்தார்கள்; சிறிய காரியங்களையெல்லாம் தாங்களே தீர்த்தார்கள்.',	2,	18,	26),
(2027,	'And Moses let his father in law depart; and he went his way into his own land.',	'பின்பு மோசே தன் மாமனை அனுப்பிவிட்டான்; அவன் திரும்பத் தன் தேசத்துக்குப் போய்விட்டான்.  ',	2,	18,	27),
(2028,	'In the third month, when the children of Israel were gone forth out of the land of Egypt, the same day came they into the wilderness of Sinai.',	'இஸ்ரவேல் புத்திரர் எகிப்து தேசத்திலிருந்து புறப்பட்ட மூன்றாம் மாதம் முதலாம் நாளிலே, சீனாய் வனாந்தரத்தில் சேர்ந்தார்கள்.',	2,	19,	1),
(2029,	'For they were departed from Rephidim, and were come to the desert of Sinai, and had pitched in the wilderness; and there Israel camped before the mount.',	'அவர்கள் ரெவிதீமிலிருந்து பிரயாணம் புறப்பட்டு, சீனாய் வனாந்தரத்தில் சேர்ந்து, அந்த வனாந்தரத்தில் பாளயமிறங்கினார்கள்; இஸ்ரவேலர் அங்கே மலைக்கு எதிராகப் பாளயமிறங்கினார்கள்.',	2,	19,	2),
(2030,	'And Moses went up unto God, and the LORD called unto him out of the mountain, saying, Thus shalt thou say to the house of Jacob, and tell the children of Israel;',	'மோசே தேவனிடத்திற்கு ஏறிப்போனான்; கர்த்தர் மலையிலிருந்து அவனைக்கூப்பிட்டு: நீ யாக்கோபு வம்சத்தாருக்குச் சொல்லவும், இஸ்ரவேல் புத்திரருக்கு அறிவிக்கவும் வேண்டியது என்னவென்றால்,',	2,	19,	3),
(2031,	'Ye have seen what I did unto the Egyptians, and how I bare you on eagles\' wings, and brought you unto myself.',	'நான் எகிப்தியருக்குச் செய்ததையும், நான் உங்களைக் கழுகுகளுடைய செட்டைகளின்மேல் சுமந்து, உங்களை என்னண்டையிலே சேர்த்துக்கொண்டதையும், நீங்கள் கண்டிருக்கிறீர்கள்.',	2,	19,	4),
(2032,	'Now therefore, if ye will obey my voice indeed, and keep my covenant, then ye shall be a peculiar treasure unto me above all people: for all the earth is mine:',	'இப்பொழுது நீங்கள் என் வாக்கை உள்ளபடி கேட்டு, என் உடன்படிக்கையைக் கைகொள்வீர்களானால், சகல ஜனங்களிலும் நீங்களே எனக்குச் சொந்த சம்பத்தாயிருப்பீர்கள்; பூமியெல்லாம் என்னுடையது.',	2,	19,	5),
(2033,	'And ye shall be unto me a kingdom of priests, and an holy nation. These are the words which thou shalt speak unto the children of Israel.',	'நீங்கள் எனக்கு ஆசாரிய ராஜ்யமும் பரிசுத்த ஜாதியுமாய் இருப்பீர்கள் என்று நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டிய வார்த்தைகள் என்றார்.',	2,	19,	6),
(2034,	'And Moses came and called for the elders of the people, and laid before their faces all these words which the LORD commanded him.',	'மோசே வந்து ஜனங்களின் மூப்பரை அழைப்பித்து, கர்த்தர் தனக்குக் கற்பித்த வார்த்தைகளையெல்லாம் அவர்களுக்கு முன்பாகச் சொன்னான்.',	2,	19,	7),
(2035,	'And all the people answered together, and said, All that the LORD hath spoken we will do. And Moses returned the words of the people unto the LORD.',	'அதற்கு ஜனங்கள் எல்லாரும் ஏகமாய், கர்த்தர் சொன்னவைகளையெல்லாம் செய்வோம் என்று பிரதியுத்தரம் சொன்னார்கள். ஜனங்கள் சொன்ன வார்த்தைகளை மோசே கர்த்தரிடத்தில் தெரிவித்தான்.',	2,	19,	8),
(2036,	'And the LORD said unto Moses, Lo, I come unto thee in a thick cloud, that the people may hear when I speak with thee, and believe thee for ever. And Moses told the words of the people unto the LORD.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நான் உன்னோடே பேசும்போது ஜனங்கள் கேட்டு, உன்னை என்றைக்கும் விசுவாசிக்கும்படி, நான் கார்மேகத்தில் உன்னிடத்திற்கு வருவேன் என்றார். ஜனங்கள் சொன்ன வார்த்தைகளை மோசே கர்த்தருக்குச் சொன்னான்.',	2,	19,	9),
(2037,	'And the LORD said unto Moses, Go unto the people, and sanctify them to day and to morrow, and let them wash their clothes,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி: நீ ஜனங்களிடத்தில் போய், இன்றைக்கும் நாளைக்கும் அவர்களைப் பரிசுத்தப்படுத்து; அவர்கள் தங்கள் வஸ்திரங்களைத் தோய்த்து,',	2,	19,	10),
(2038,	'And be ready against the third day: for the third day the LORD will come down in the sight of all the people upon mount Sinai.',	'மூன்றாம் நாளைக்கு ஆயத்தப்பட்டிருக்கக்கடவர்கள்; மூன்றாம் நாளில் கர்த்தர் சகல ஜனங்களுக்கும் பிரத்தியட்சமாகச் சீனாய் மலையின்மேல் இறங்குவார்.',	2,	19,	11),
(2039,	'And thou shalt set bounds unto the people round about, saying, Take heed to yourselves, that ye go not up into the mount, or touch the border of it: whosoever toucheth the mount shall be surely put to death:',	'ஜனங்களுக்குச் சுற்றிலும் நீ ஒரு எல்லை குறித்து, அவர்கள் மலையில் ஏறாதபடிக்கும், அதின் அடிவாரத்தைத் தொடாதபடிக்கும் எச்சரிக்கையாய் இருங்கள் என்று அவர்களுக்குச் சொல்; மலையைத் தொடுகிறவன் எவனும் நிச்சயமாகவே கொல்லப்படுவான்.',	2,	19,	12),
(2040,	'There shall not an hand touch it, but he shall surely be stoned, or shot through; whether it be beast or man, it shall not live: when the trumpet soundeth long, they shall come up to the mount.',	'ஒரு கையும் அதைத்தொடலாகாது; தொட்டால், நிச்சயமாகக் கல்லெறியுண்டு, அல்லது ஊடுருவ எய்யுண்டு சாகவேண்டும்; மிருகமானாலும் சரி, மனிதனானாலும் சரி, உயிரோடே வைக்கப்படலாகாது; எக்காளம் நெடுந்தொனியாய்த் தொனிக்கையில், அவர்கள் மலையின் அடிவாரத்தில் வரக்கடவர்கள் என்றார்.',	2,	19,	13),
(2041,	'And Moses went down from the mount unto the people, and sanctified the people; and they washed their clothes.',	'மோசே மலையிலிருந்து இறங்கி, ஜனங்களிடத்தில் வந்து, அவர்களைப் பரிசுத்தப்படுத்தினான்; அவர்கள் தங்கள் வஸ்திரங்களைத் தோய்த்தார்கள்.',	2,	19,	14),
(2042,	'And he said unto the people, Be ready against the third day: come not at your wives.',	'அவன் ஜனங்களை நோக்கி: மூன்றாம் நாளுக்கு ஆயத்தப்பட்டிருங்கள், மனைவியினிடத்தில் சேராதிருங்கள் என்றான்.',	2,	19,	15),
(2043,	'And it came to pass on the third day in the morning, that there were thunders and lightnings, and a thick cloud upon the mount, and the voice of the trumpet exceeding loud; so that all the people that was in the camp trembled.',	'மூன்றாம் நாள் விடியற்காலத்தில் இடிமுழக்கங்களும் மின்னல்களும், மலையின்மேல் கார்மேகமும் மகா பலத்த எக்காளசத்தமும் உண்டாயிற்று; பாளயத்திலிருந்த ஜனங்கள் எல்லாரும் நடுங்கினார்கள்.',	2,	19,	16),
(2044,	'And Moses brought forth the people out of the camp to meet with God; and they stood at the nether part of the mount.',	'அப்பொழுது ஜனங்கள் தேவனுக்கு எதிர்கொண்டுபோக, மோசே அவர்களைப் பாளயத்திலிருந்து புறப்படப்பண்ணினான்; அவர்கள் மலையின் அடிவாரத்தில் நின்றார்கள்.',	2,	19,	17),
(2045,	'And mount Sinai was altogether on a smoke, because the LORD descended upon it in fire: and the smoke thereof ascended as the smoke of a furnace, and the whole mount quaked greatly.',	'கர்த்தர் சீனாய்மலையின்மேல் அக்கினியில் இறங்கினபடியால், அது முழுவதும் புகைக்காடாய் இருந்தது; அந்தப் புகை சூளையின் புகையைப்போல எழும்பிற்று; மலை முழுவதும் மிகவும் அதிர்ந்தது.',	2,	19,	18),
(2046,	'And when the voice of the trumpet sounded long, and waxed louder and louder, Moses spake, and God answered him by a voice.',	'எக்காளசத்தம் வரவர மிகவும் பலமாய்த் தொனித்தது; மோசே பேசினான்; தேவன் அவனுக்கு வாக்கினால் மறுமொழி கொடுத்தார்.',	2,	19,	19),
(2047,	'And the LORD came down upon mount Sinai, on the top of the mount: and the LORD called Moses up to the top of the mount; and Moses went up.',	'கர்த்தர் சீனாய்மலையிலுள்ள கொடுமுடியில் இறங்கினபோது, கர்த்தர் மோசேயை மலையின் கொடுமுடியிலே வரவழைத்தார்; மோசே ஏறிப்போனான்.',	2,	19,	20),
(2048,	'And the LORD said unto Moses, Go down, charge the people, lest they break through unto the LORD to gaze, and many of them perish.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: ஜனங்கள் பார்க்கிறதற்கு எல்லையைக் கடந்து கர்த்தரிடத்தில் வராதபடிக்கும், அவர்களில் அநேகர் அழிந்துபோகாதபடிக்கும், நீ இறங்கிப்போய், அவர்களை உறுதியாக எச்சரி.',	2,	19,	21),
(2049,	'And let the priests also, which come near to the LORD, sanctify themselves, lest the LORD break forth upon them.',	'கர்த்தரின் சமுகத்தில் வருகிற ஆசாரியர்களும், கர்த்தர் தங்களுக்குள்ளே சங்காரம்பண்ணாதபடி, தங்களைப் பரிசுத்தப்படுத்திக்கொள்ளவேண்டும் என்றார்.',	2,	19,	22),
(2050,	'And Moses said unto the LORD, The people cannot come up to mount Sinai: for thou chargedst us, saying, Set bounds about the mount, and sanctify it.',	'அப்பொழுது மோசே கர்த்தரை நோக்கி: மலையைச் சுற்றிலும் எல்லை குறித்து, அதைப் பரிசுத்தப்படுத்துங்கள் என்று தேவரீர் எங்களை உறுதியாக எச்சரித்திருக்கிறீர்; ஆகையால், ஜனங்கள் சீனாய்மலையின்மேல் ஏறிவரமாட்டார்கள் என்றான்.',	2,	19,	23),
(2051,	'And the LORD said unto him, Away, get thee down, and thou shalt come up, thou, and Aaron with thee: but let not the priests and the people break through to come up unto the LORD, lest he break forth upon them.',	'கர்த்தர் மோசேயை நோக்கி: நீ இறங்கிப்போ; பின்பு நீயும் ஆரோனும் கூடி ஏறிவாருங்கள்; ஆசாரியர்களும், ஜனங்களும், கர்த்தர் தங்களுக்குள்ளே சங்காரம்பண்ணாதபடிக்கு, எல்லையைக் கடந்து கர்த்தரிடத்தில் வராதிருக்கக்கடவர்கள் என்றார்.',	2,	19,	24),
(2052,	'So Moses went down unto the people, and spake unto them.',	'அப்படியே மோசே இறங்கி ஜனங்களிடத்தில் போய், அதை அவர்களுக்குச் சொன்னான்.  ',	2,	19,	25),
(2053,	'And God spake all these words, saying,',	'தேவன் பேசிச் சொல்லிய சகல வார்த்தைகளுமாவன:',	2,	20,	1),
(2054,	'I am the LORD thy God, which have brought thee out of the land of Egypt, out of the house of bondage.',	'உன்னை அடிமைத்தன வீடாகிய எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின உன் தேவனாகிய கர்த்தர் நானே.',	2,	20,	2),
(2055,	'Thou shalt have no other gods before me.',	'என்னையன்றி உனக்கு வேறே தேவர்கள் உண்டாயிருக்கவேண்டாம்.',	2,	20,	3),
(2056,	'Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth.',	'மேலே வானத்திலும், கீழே பூமியிலும், பூமியின் கீழ்த் தண்ணீரிலும் உண்டாயிருக்கிறவைகளுக்கு ஒப்பான ஒரு சொரூபத்தையாகிலும் யாதொரு விக்கிரகத்தையாகிலும் நீ உனக்கு உண்டாக்கவேண்டாம்;',	2,	20,	4),
(2057,	'Thou shalt not bow down thyself to them, nor serve them: for I the LORD thy God am a jealous God, visiting the iniquity of the fathers upon the children unto the third and fourth generation of them that hate me;',	'நீ அவைகளை நமஸ்கரிக்கவும் சேவிக்கவும் வேண்டாம்; உன் தேவனாகிய கர்த்தராயிருக்கிற நான் எரிச்சலுள்ள தேவனாயிருந்து, என்னைப் பகைக்கிறவர்களைக்குறித்துப் பிதாக்களுடைய அக்கிரமத்தைப் பிள்ளைகளிடத்தில் மூன்றாம் நான்காம் தலைமுறைமட்டும் விசாரிக்கிறவராயிருக்கிறேன்.',	2,	20,	5),
(2058,	'And shewing mercy unto thousands of them that love me, and keep my commandments.',	'என்னிடத்தில் அன்புகூர்ந்து, என் கற்பனைகளைக் கைக்கொள்ளுகிறவர்களுக்கோ ஆயிரம் தலைமுறைமட்டும் இரக்கஞ்செய்கிறவராயிருக்கிறேன்.',	2,	20,	6),
(2059,	'Thou shalt not take the name of the LORD thy God in vain; for the LORD will not hold him guiltless that taketh his name in vain.',	'உன் தேவனாகிய கர்த்தருடைய நாமத்தை வீணிலே வழங்காதிருப்பாயாக; கர்த்தர் தம்முடைய நாமத்தை வீணிலே வழங்குகிறவனைத் தண்டியாமல் விடார்.',	2,	20,	7),
(2060,	'Remember the sabbath day, to keep it holy.',	'ஓய்வுநாளைப் பரிசுத்தமாய் ஆசரிக்க நினைப்பாயாக;',	2,	20,	8),
(2061,	'Six days shalt thou labour, and do all thy work:',	'ஆறுநாளும் நீ வேலைசெய்து, உன் கிரியைகளையெல்லாம் நடப்பிப்பாயாக;',	2,	20,	9),
(2062,	'But the seventh day is the sabbath of the LORD thy God: in it thou shalt not do any work, thou, nor thy son, nor thy daughter, thy manservant, nor thy maidservant, nor thy cattle, nor thy stranger that is within thy gates:',	'ஏழாம்நாளோ உன் தேவனாகிய கர்த்தருடைய ஓய்வுநாள்; அதிலே நீயானாலும், உன் குமாரனானாலும், உன் குமாரத்தியானாலும், உன் வேலைக்காரனானாலும், உன் வேலைக்காரியானாலும், உன் மிருகஜீவனானாலும், உன் வாசல்களில் இருக்கிற அந்நியனானாலும், யாதொரு வேலையும் செய்யவேண்டாம்.',	2,	20,	10),
(2063,	'For in six days the LORD made heaven and earth, the sea, and all that in them is, and rested the seventh day: wherefore the LORD blessed the sabbath day, and hallowed it.',	'கர்த்தர் ஆறுநாளைக்குள்ளே வானத்தையும் பூமியையும் சமுத்திரத்தையும் அவைகளிலுள்ள எல்லாவற்றையும் உண்டாக்கி, ஏழாம்நாளிலே ஓய்ந்திருந்தார்; ஆகையால், கர்த்தர் ஓய்வுநாளை ஆசீர்வதித்து, அதைப் பரிசுத்தமாக்கினார்.',	2,	20,	11),
(2064,	'Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee.',	'உன் தேவனாகிய கர்த்தர் உனக்குக் கொடுக்கிற தேசத்திலே உன் நாட்கள் நீடித்திருப்பதற்கு, உன் தகப்பனையும் உன் தாயையும் கனம்பண்ணுவாயாக.',	2,	20,	12),
(2065,	'Thou shalt not kill.',	'கொலை செய்யாதிருப்பாயாக.',	2,	20,	13),
(2066,	'Thou shalt not commit adultery.',	'விபசாரம் செய்யாதிருப்பாயாக.',	2,	20,	14),
(2067,	'Thou shalt not steal.',	'களவு செய்யாதிருப்பாயாக.',	2,	20,	15),
(2068,	'Thou shalt not bear false witness against thy neighbour.',	'பிறனுக்கு விரோதமாய்ப் பொய்ச்சாட்சி சொல்லாதிருப்பாயாக.',	2,	20,	16),
(2069,	'Thou shalt not covet thy neighbour\'s house, thou shalt not covet thy neighbour\'s wife, nor his manservant, nor his maidservant, nor his ox, nor his ass, nor any thing that is thy neighbour\'s.',	'பிறனுடைய வீட்டை இச்சியாதிருப்பாயாக; பிறனுடைய மனைவியையும், அவனுடைய வேலைக்காரனையும், அவனுடைய வேலைக்காரியையும், அவனுடைய எருதையும், அவனுடைய கழுதையையும், பின்னும் பிறனுக்குள்ள யாதொன்றையும் இச்சியாதிருப்பாயாக என்றார்.',	2,	20,	17),
(2070,	'And all the people saw the thunderings, and the lightnings, and the noise of the trumpet, and the mountain smoking: and when the people saw it, they removed, and stood afar off.',	'ஜனங்கள் எல்லாரும் இடிமுழக்கங்களையும் மின்னல்களையும் எக்காளச் சத்தத்தையும் மலை புகைகிறதையும் கண்டார்கள்; அதைக் கண்டு, ஜனங்கள் பின்வாங்கி, தூரத்திலே நின்று,',	2,	20,	18),
(2071,	'And they said unto Moses, Speak thou with us, and we will hear: but let not God speak with us, lest we die.',	'மோசேயை நோக்கி: நீர் எங்களோடே பேசும், நாங்கள் கேட்போம்; தேவன் எங்களோடே பேசாதிருப்பாராக, பேசினால் நாங்கள் செத்துப்போவோம் என்றார்கள்.',	2,	20,	19),
(2072,	'And Moses said unto the people, Fear not: for God is come to prove you, and that his fear may be before your faces, that ye sin not.',	'மோசே ஜனங்களை நோக்கி; பயப்படாதிருங்கள்; உங்களைச் சோதிப்பதற்காகவும், நீங்கள் பாவஞ்செய்யாதபடிக்குத் தம்மைப் பற்றும் பயம் உங்கள் முகத்திற்கு முன்பாக இருப்பதற்காகவும், தேவன் எழுந்தருளினார் என்றான்.',	2,	20,	20),
(2073,	'And the people stood afar off, and Moses drew near unto the thick darkness where God was.',	'ஜனங்கள் தூரத்திலே நின்றார்கள்; மோசே, தேவன் இருந்த கார்மேகத்துக்குச் சமீபமாய்ச் சேர்ந்தான்.',	2,	20,	21),
(2074,	'And the LORD said unto Moses, Thus thou shalt say unto the children of Israel, Ye have seen that I have talked with you from heaven.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால், நான் வானத்திலிருந்து உங்களோடே பேசினேன் என்று கண்டீர்கள்.',	2,	20,	22),
(2075,	'Ye shall not make with me gods of silver, neither shall ye make unto you gods of gold.',	'நீங்கள் எனக்கு ஒப்பாக வெள்ளியினாலே தெய்வங்களையும் பொன்னினாலே தெய்வங்களையும் உங்களுக்கு உண்டாக்கவே வேண்டாம்.',	2,	20,	23),
(2076,	'An altar of earth thou shalt make unto me, and shalt sacrifice thereon thy burnt offerings, and thy peace offerings, thy sheep, and thine oxen: in all places where I record my name I will come unto thee, and I will bless thee.',	'மண்ணினாலே பலிபீடத்தை எனக்கு உண்டாக்கி, அதின்மேல் உன் ஆடுகளையும் உன் மாடுகளையும் சர்வாங்க தகனபலியாகவும் சமாதானபலியாகவும் செலுத்துவாயாக; நான் என் நாமத்தைப் பிரஸ்தாபப்படுத்தும் எந்த ஸ்தானத்திலும் உன்னிடத்தில் வந்து, உன்னை ஆசீர்வதிப்பேன்.',	2,	20,	24),
(2077,	'And if thou wilt make me an altar of stone, thou shalt not build it of hewn stone: for if thou lift up thy tool upon it, thou hast polluted it.',	'எனக்குக் கல்லினால் பலிபீடத்தை உண்டாக்கவேண்டுமாகில், அதை வெட்டின கல்லுகளால் கட்டவேண்டாம்; அதின்மேல் உளியிட்டவுடனே, அதை அசுசிப்படுத்துவாய்.',	2,	20,	25),
(2078,	'Neither shalt thou go up by steps unto mine altar, that thy nakedness be not discovered thereon.',	'என் பலிபீடத்தின்மேல் உன் நிர்வாணம் காணப்படாதபடிக்கு, படிகளால் அதின்மேல் ஏறவும் வேண்டாம்.  ',	2,	20,	26),
(2079,	'Now these are the judgments which thou shalt set before them.',	'மேலும், நீ அவர்களுக்கு அறிவிக்கவேண்டிய பிரமாணங்களாவன:',	2,	21,	1),
(2080,	'If thou buy an Hebrew servant, six years he shall serve: and in the seventh he shall go out free for nothing.',	'எபிரெயரில் ஒரு அடிமையைக் கொண்டாயானால், அவன் ஆறுவருஷம் சேவித்து, ஏழாம் வருஷத்திலே ஒன்றும் கொடாமல் விடுதலைப்பெற்றுப் போகக்கடவன்.',	2,	21,	2),
(2081,	'If he came in by himself, he shall go out by himself: if he were married, then his wife shall go out with him.',	'ஒன்றிக்காரனாய் வந்திருந்தானானால், ஒன்றிக்காரனாய்ப் போகக்கடவன்; விவாகம்பண்ணினவனாய் வந்திருந்தானானால், அவன் பெண்ஜாதி அவனோடேகூடப் போகக்கடவள்.',	2,	21,	3),
(2082,	'If his master have given him a wife, and she have born him sons or daughters; the wife and her children shall be her master\'s, and he shall go out by himself.',	'அவன் எஜமான் அவனுக்கு ஒரு பெண்ணை விவாகஞ்செய்துகொடுத்தும், அவள் அவனுக்கு ஆண்பிள்ளைகளையாவது பெண்பிள்ளைகளையாவது பெற்றும் இருந்தால், அந்தப் பெண்ணும் அவள் பிள்ளைகளும் அவள் எஜமானைச் சேரக்கடவர்கள்; அவன் மாத்திரம் ஒன்றியாய்ப் போகக்கடவன்.',	2,	21,	4),
(2083,	'And if the servant shall plainly say, I love my master, my wife, and my children; I will not go out free:',	'அந்த வேலைக்காரன்: என் எஜமானையும் என் பெண்ஜாதியையும் என் பிள்ளைகளையும் நேசிக்கிறேன்; நான் விடுதலை பெற்றுப்போக மனதில்லை என்று மனப்பூர்வமாய்ச் சொல்வானானால்,',	2,	21,	5),
(2084,	'Then his master shall bring him unto the judges; he shall also bring him to the door, or unto the door post; and his master shall bore his ear through with an aul; and he shall serve him for ever.',	'அவன் எஜமான் அவனை நியாயாதிபதிகளிடத்தில் அழைத்துக்கொண்டுபோய், அவனைக் கதவின் அருகேயாவது கதவுநிலையின் அருகேயாவது சேரப்பண்ணி, அங்கே அவன் எஜமான் அவன் காதைக் கம்பியினால் குத்தக்கடவன்; பின்பு அவன் என்றைக்கும் அவனிடத்திலே சேவித்துக்கொண்டிருக்கக்கடவன்.',	2,	21,	6),
(2085,	'And if a man sell his daughter to be a maidservant, she shall not go out as the menservants do.',	'ஒருவன் தன் மகளை வேலைக்காரியாக விற்றுப்போட்டானானால், வேலைக்காரன் விடுதலைபெற்றுப் போவதுபோல அவள் போகக்கூடாது.',	2,	21,	7),
(2086,	'If she please not her master, who hath betrothed her to himself, then shall he let her be redeemed: to sell her unto a strange nation he shall have no power, seeing he hath dealt deceitfully with her.',	'அவளைத் தனக்கு நியமித்துக்கொண்ட எஜமானின் பார்வைக்கு அவள் தகாதவளாய்ப் போனால், அவள் மீட்கப்படலாம்; அவன் அவளுக்குத் துரோகம்பண்ணி, அவளை அந்நியர் கையில் விற்றுப்போட அவனுக்கு அதிகாரம் இல்லை.',	2,	21,	8),
(2087,	'And if he have betrothed her unto his son, he shall deal with her after the manner of daughters.',	'அவன் தன் குமாரனுக்கு அவளை நியமித்திருந்தானானால், தன் குமாரத்திகளை நடத்துவதுபோல அவளையும் நடத்தக்கடவன்.',	2,	21,	9),
(2088,	'If he take him another wife; her food, her raiment, and her duty of marriage, shall he not diminish.',	'அவன் வேறொரு பெண்ணைக் கொண்டானாகில், இவளுக்குரிய அன்னவஸ்திர விவாகக்கடமை ஆகிய இவைகளில் குறைவுசெய்யாமல் இருப்பானாக.',	2,	21,	10),
(2089,	'And if he do not these three unto her, then shall she go out free without money.',	'இம்மூன்றும் அவன் அவளுக்குச் செய்யாமற்போனால், அவள் பணங்கொடாமல் விடுதலைபெற்றுப்போகக்கடவள்.',	2,	21,	11),
(2090,	'He that smiteth a man, so that he die, shall be surely put to death.',	'ஒரு மனிதனைச் சாகும்படி அடித்தவன், நிச்சயமாய்க் கொலைசெய்யப்படக்கடவன்.',	2,	21,	12),
(2091,	'And if a man lie not in wait, but God deliver him into his hand; then I will appoint thee a place whither he shall flee.',	'ஒருவன் பதிவிருந்து கொல்லாமல், தேவச்செயலாய்த் தன் கைக்கு நேரிட்டவனைக் கொன்றால், அவன் ஓடிப்போய்ச் சேரவேண்டிய ஸ்தலத்தை உனக்கு நியமிப்பேன்.',	2,	21,	13),
(2092,	'But if a man come presumptuously upon his neighbour, to slay him with guile; thou shalt take him from mine altar, that he may die.',	'ஒருவன் பிறனுக்கு விரோதமாகச் சதிமோசஞ்செய்து, அவனைத் துணிகரமாய்க் கொன்றுபோட்டால், அவனை என்பலிபீடத்திலிருந்தும் பிடித்துக்கொண்டுபோய்க் கொலைசெய்யவேண்டும்.',	2,	21,	14),
(2093,	'And he that smiteth his father, or his mother, shall be surely put to death.',	'தன் தகப்பனையாவது தன் தாயையாவது அடிக்கிறவன் நிச்சயமாய்க் கொலைசெய்யப்படக்கடவன்.',	2,	21,	15),
(2094,	'And he that stealeth a man, and selleth him, or if he be found in his hand, he shall surely be put to death.',	'ஒருவன் ஒரு மனிதனைத் திருடி விற்றுப்போட்டாலும், இவன் அவன் வசத்திலிருக்கக் கண்டுபிடிக்கப்பட்டாலும், அவன் நிச்சயமாய்க் கொலைசெய்யப்படக்கடவன்.',	2,	21,	16),
(2095,	'And he that curseth his father, or his mother, shall surely be put to death.',	'தன் தகப்பனையாவது தன் தாயையாவது சபிக்கிறவன் நிச்சயமாய்க் கொலைசெய்யப்படக்கடவன்.',	2,	21,	17),
(2096,	'And if men strive together, and one smite another with a stone, or with his fist, and he die not, but keepeth his bed:',	'மனிதர் சண்டைபண்ணி, ஒருவன் மற்றொருவனைக் கல்லால் எறிந்ததினாலாவது கையால் அடித்ததினாலாவது அவன் சாவாமல் கட்டில் கிடையாய்க்கிடந்து,',	2,	21,	18),
(2097,	'If he rise again, and walk abroad upon his staff, then shall he that smote him be quit: only he shall pay for the loss of his time, and shall cause him to be thoroughly healed.',	'திரும்ப எழுந்திருந்து வெளியிலே தன் ஊன்றுகோலைப் பிடித்துக்கொண்டு நடமாடினால், அடித்தவன் ஆக்கினைக்கு நீங்கலாயிருப்பான்; ஆனாலும் அவனுக்கு வேலை மினக்கெட்ட நஷ்டத்தைக் கொடுத்து, அவனை நன்றாய்க் குணமாக்குவிக்கக்கடவன்.',	2,	21,	19),
(2098,	'And if a man smite his servant, or his maid, with a rod, and he die under his hand; he shall be surely punished.',	'ஒருவன் தனக்கு அடிமையானவனையாவது தனக்கு அடிமையானவளையாவது, கோலால் அடித்ததினாலே, அவன் கையால் இறந்துபோனால், பழிக்குப்பழி வாங்கப்படவேண்டும்.',	2,	21,	20),
(2099,	'Notwithstanding, if he continue a day or two, he shall not be punished: for he is his money.',	'ஒரு நாளாவது இரண்டு நாளாவது உயிரோடிருந்தால், அவர்கள் அவனுடைய உடைமையாகையால், பழிவாங்கவேண்டியதில்லை.',	2,	21,	21),
(2100,	'If men strive, and hurt a woman with child, so that her fruit depart from her, and yet no mischief follow: he shall be surely punished, according as the woman\'s husband will lay upon him; and he shall pay as the judges determine.',	'மனிதர் சண்டைபண்ணி, கர்ப்பவதியான ஒரு ஸ்திரீயை அடித்ததினால், அவளுக்கு வேறே சேதமில்லாமல் கர்ப்பம் விழுந்துபோனால், அடிபட்ட ஸ்திரீயின் புருஷன் அடித்தவன்மேல் சுமத்துகிறதற்குத்தக்கதாயும் நியாயாதிபதிகள் செய்யும் தீர்ப்பின்படியும் தண்டம் கொடுக்கவேண்டும்.',	2,	21,	22),
(2101,	'And if any mischief follow, then thou shalt give life for life,',	'வேறே சேதமுண்டானால், ஜீவனுக்கு ஜீவன்,',	2,	21,	23),
(2102,	'Eye for eye, tooth for tooth, hand for hand, foot for foot,',	'கண்ணுக்குக் கண், பல்லுக்குப் பல், கைக்குக் கை, காலுக்குக் கால்,',	2,	21,	24),
(2103,	'Burning for burning, wound for wound, stripe for stripe.',	'சூட்டுக்குச் சூடு, காயத்துக்குக் காயம், தழும்புக்குத் தழும்பு பழி கொடுக்கவேண்டும்.',	2,	21,	25),
(2104,	'And if a man smite the eye of his servant, or the eye of his maid, that it perish; he shall let him go free for his eye\'s sake.',	'ஒருவன் தன் அடிமையானவன் கண்ணையாகிலும் தன் அடிமைப்பெண்ணின் கண்ணையாகிலும் அடித்ததினால் அதைக் கெடுத்தால், அவன் கண்ணுக்குப் பதிலாக அவனை விடுதலை பண்ணிவிடவேண்டும்.',	2,	21,	26),
(2105,	'And if he smite out his manservant\'s tooth, or his maidservant\'s tooth; he shall let him go free for his tooth\'s sake.',	'அவன் தன் அடிமையானவன் பல்லையாவது தன் அடிமைப்பெண்ணின் பல்லையாவது உதிர அடித்தால், அவன் பல்லுக்குப்பதிலாக அவனை விடுதலைபண்ணிவிடவேண்டும்.',	2,	21,	27),
(2106,	'If an ox gore a man or a woman, that they die: then the ox shall be surely stoned, and his flesh shall not be eaten; but the owner of the ox shall be quit.',	'ஒரு மாடு ஒரு புருஷனையாவது ஒரு ஸ்திரீயையாவது முட்டினதினால் சாவுண்டானால், அந்த மாடு கல்லெறியப்படவேண்டும், அதின் மாம்சம் புசிக்கப்படலாகாது; அப்பொழுது மாட்டின் எஜமான் ஆக்கினைக்கு நீங்கலாயிருப்பான்.',	2,	21,	28),
(2107,	'But if the ox were wont to push with his horn in time past, and it hath been testified to his owner, and he hath not kept him in, but that he hath killed a man or a woman; the ox shall be stoned, and his owner also shall be put to death.',	'தன் மாடு வழக்கமாய் முட்டுகிற மாடாயிருந்து, அது அதின் எஜமானுக்கு அறிவிக்கப்பட்டும், அவன் அதைக் கட்டிவைக்காததினால், அது ஒரு புருஷனையாவது ஒரு ஸ்திரீயையாவது கொன்று போட்டால், மாடும் கல்லெறியப்படவேண்டும், அதின் எஜமானும் கொலை செய்யப்படவேண்டும்.',	2,	21,	29),
(2108,	'If there be laid on him a sum of money, then he shall give for the ransom of his life whatsoever is laid upon him.',	'அபராதம் கொடுக்கும்படி தீர்க்கப்பட்டதானால், அவன் தன் ஜீவனை மீட்கும் பொருளாக விதிக்கப்பட்ட அபராதத்தைக் கொடுக்கக்கடவன்.',	2,	21,	30),
(2109,	'Whether he have gored a son, or have gored a daughter, according to this judgment shall it be done unto him.',	'அது ஒருவன் மகனை முட்டினாலும் சரி, ஒருவன் மகளை முட்டினாலும் சரி, இந்தத் தீர்ப்பின்படியே அவனுக்குச் செய்யப்படவேண்டும்.',	2,	21,	31),
(2110,	'If the ox shall push a manservant or a maidservant; he shall give unto their master thirty shekels of silver, and the ox shall be stoned.',	'அந்த மாடு ஒரு அடிமையானவனையாவது ஒரு அடிமைப்பெண்ணையாவது முட்டினால், அதற்கு உடையவன் அவர்களுடைய எஜமானுக்கு முப்பது சேக்கல் நிறையான வெள்ளியைக் கொடுக்கக்கடவன்; மாடு கல்லெறியப்படவேண்டும்.',	2,	21,	32),
(2111,	'And if a man shall open a pit, or if a man shall dig a pit, and not cover it, and an ox or an ass fall therein;',	'ஒருவன் ஒரு குழியைத் திறந்து வைத்ததினாலாவது, ஒரு குழியை வெட்டி அதை மூடாதேபோனதினாலாவது, அதிலே ஒரு மாடாவது ஒரு கழுதையாவது விழுந்தால்,',	2,	21,	33),
(2112,	'The owner of the pit shall make it good, and give money unto the owner of them; and the dead beast shall be his.',	'குழிக்கு உடையவன் அதற்கு ஈடாகப் பணத்தை மிருகத்தின் எஜமானுக்குக் கொடுக்கக்கடவன்; செத்ததோ அவனுடையதாகவேண்டும்.',	2,	21,	34),
(2113,	'And if one man\'s ox hurt another\'s, that he die; then they shall sell the live ox, and divide the money of it; and the dead ox also they shall divide.',	'ஒருவனுடைய மாடு மற்றவனுடைய மாட்டை முட்டினதினால் அது செத்தால், உயிரோடிருக்கிற மாட்டை அவர்கள் விற்று, அதின் கிரயத்தைப் பங்கிட்டு, செத்ததையும் பங்கிட்டுக்கொள்ளக்கடவர்கள்.',	2,	21,	35),
(2114,	'Or if it be known that the ox hath used to push in time past, and his owner hath not kept him in; he shall surely pay ox for ox; and the dead shall be his own.',	'அந்த மாடு முன்னமே முட்டுகிற மாடென்று அதின் எஜமான் அறிந்திருந்தும், அதைக் கட்டிவைக்காதிருந்தால், அவன் மாட்டுக்கு மாட்டைக் கொடுக்கக்கடவன்; செத்ததோ அவனுடையதாக வேண்டும்.  ',	2,	21,	36),
(2115,	'If a man shall steal an ox, or a sheep, and kill it, or sell it; he shall restore five oxen for an ox, and four sheep for a sheep.',	'ஒருவன் ஒரு மாட்டையாவது ஒரு ஆட்டையாவது திருடி, அதைக் கொன்றால், அல்லது அதை விற்றால், அவன் அந்த மாட்டுக்கு ஐந்து மாடுகளையும், அந்த ஆட்டுக்கு நாலு ஆடுகளையும் பதிலாகக் கொடுக்கக்கடவன்.',	2,	22,	1),
(2116,	'If a thief be found breaking up, and be smitten that he die, there shall no blood be shed for him.',	'திருடன் கன்னமிடுகையில் கண்டுபிடிக்கப்பட்டு, அடிக்கப்பட்டுச் செத்தால், அவன் நிமித்தம் இரத்தபழி சுமராது.',	2,	22,	2),
(2117,	'If the sun be risen upon him, there shall be blood shed for him; for he should make full restitution; if he have nothing, then he shall be sold for his theft.',	'சூரியன் அவன்மேல் உதித்திருந்ததானால், அவன் நிமித்தம் இரத்தப்பழி சுமரும்; திருடன் பதில் கொடுத்துத் தீர்க்கவேண்டும்; அவன் கையில் ஒன்றும் இல்லாதிருந்தால், தான் செய்த களவுக்காக விலைப்படக்கடவன்.',	2,	22,	3),
(2118,	'If the theft be certainly found in his hand alive, whether it be ox, or ass, or sheep; he shall restore double.',	'அவன் திருடின மாடாவது கழுதையாவது ஆடாவது உயிருடனே அவன் கையில் கண்டுபிடிக்கப்பட்டால், இரட்டிப்பாய் அவன் கொடுக்கவேண்டும்.',	2,	22,	4),
(2119,	'If a man shall cause a field or vineyard to be eaten, and shall put in his beast, and shall feed in another man\'s field; of the best of his own field, and of the best of his own vineyard, shall he make restitution.',	'ஒருவன் பிறனுடைய வயலிலாவது திராட்சத்தோட்டத்திலாவது தன் மிருகஜீவனை மேயவிட்டால், அவன் தன் சுயவயலிலும் திராட்சத்தோட்டத்திலுமுள்ள பலனில் உத்தமமானதை எடுத்து, பதில் செலுத்தக்கடவன்.',	2,	22,	5),
(2120,	'If fire break out, and catch in thorns, so that the stacks of corn, or the standing corn, or the field, be consumed therewith; he that kindled the fire shall surely make restitution.',	'அக்கினி எழும்பி, முள்ளுக்களில் பற்றி, தானியப்போரையாவது, விளைந்த பயிரையாவது, வயலிலுள்ள வேறே எதையாவது எரித்துப்போட்டதேயானால், அக்கினியைக் கொளுத்தினவன் அக்கினிச் சேதத்திற்கு உத்தரவாதம்பண்ணவேண்டும்.',	2,	22,	6),
(2121,	'If a man shall deliver unto his neighbour money or stuff to keep, and it be stolen out of the man\'s house; if the thief be found, let him pay double.',	'ஒருவன் பிறனுடைய வசத்தில் திரவியத்தையாவது, உடைமைகளையாவது அடைக்கலமாக வைத்திருக்கும்போது, அது அவன் வீட்டிலிருந்து திருடப்பட்டுப்போனால், திருடன் அகப்பட்டானாகில், அவன் அதற்கு இரட்டிப்பாகக் கொடுக்கவேண்டும்.',	2,	22,	7),
(2122,	'If the thief be not found, then the master of the house shall be brought unto the judges, to see whether he have put his hand unto his neighbour\'s goods.',	'திருடன் அகப்படாதேபோனால், அந்த வீட்டுக்காரன் தானே பிறனுடைய பொருளை அபகரித்தானோ இல்லையோ என்று அறியும்படி நியாயாதிபதிகளிடத்தில் அவனைக் கொண்டுபோகவேண்டும்.',	2,	22,	8),
(2123,	'For all manner of trespass, whether it be for ox, for ass, for sheep, for raiment, or for any manner of lost thing which another challengeth to be his, the cause of both parties shall come before the judges; and whom the judges shall condemn, he shall pay double unto his neighbour.',	'காணாமற்போன மாடு, கழுதை, ஆடு, வஸ்திரம் முதலியவைகளில் யாதொன்றைப் பிறனொருவன் தன்னுடையது என்று சொல்லி குற்றஞ்சாற்றினால், இருதிறத்தாருடைய வழக்கும் நியாயாதிபதிகளிடத்தில் வரக்கடவது; நியாயாதிபதிகள் எவனைக் குற்றவாளி என்று தீர்க்கிறார்களோ, அவன் மற்றவனுக்கு இரட்டிப்பாகக் கொடுக்கக்கடவன்.',	2,	22,	9),
(2124,	'If a man deliver unto his neighbour an ass, or an ox, or a sheep, or any beast, to keep; and it die, or be hurt, or driven away, no man seeing it:',	'ஒருவன் தன் கழுதையையாவது மாட்டையாவது ஆட்டையாவது மற்ற யாதொரு மிருகஜீவனையாவது பிறன் வசத்தில் விட்டிருக்கும்போது, அது செத்தாலும், சேதப்பட்டுப்போனாலும், ஒருவரும் காணாதபடி ஓட்டிக்கொண்டு போகப்பட்டாலும்,',	2,	22,	10),
(2125,	'Then shall an oath of the LORD be between them both, that he hath not put his hand unto his neighbour\'s goods; and the owner of it shall accept thereof, and he shall not make it good.',	'அவன் தான் பிறனுடைய பொருளை அபகரிக்கவில்லையென்று கர்த்தர் பேரில் இடும் ஆணை அவர்கள் இருவருக்கும் நடுத்தீர்க்கக்கடவது; உடையவன் அதை அங்கிகரிக்கவேண்டும்; மற்றவன் பதிலளிக்கவேண்டுவதில்லை.',	2,	22,	11),
(2126,	'And if it be stolen from him, he shall make restitution unto the owner thereof.',	'அது அவன் வசத்திலிருந்து திருடப்பட்டுப்போயிற்றானால், அவன் அதின் எஜமானுக்கு அதற்காக உத்தரவாதம்பண்ணக்கடவன்.',	2,	22,	12),
(2127,	'If it be torn in pieces, then let him bring it for witness, and he shall not make good that which was torn.',	'அது பீறுண்டுபோயிற்றானால், அதற்குச் சாட்சியை ஒப்புவிக்கவேண்டும். பீறுண்டதற்காக அவன் உத்தரவாதம்பண்ணவேண்டுவதில்லை.',	2,	22,	13),
(2128,	'And if a man borrow ought of his neighbour, and it be hurt, or die, the owner thereof being not with it, he shall surely make it good.',	'ஒருவன் பிறனிடத்தில் எதையாகிலும் இரவலாக வாங்கினதுண்டானால், அதற்கு உடையவன் கூட இராதபோது, அது சேதப்பட்டாலும், செத்துப்போனாலும், அவன் அதற்கு உத்தரவாதம்பண்ணவேண்டும்.',	2,	22,	14),
(2129,	'But if the owner thereof be with it, he shall not make it good: if it be an hired thing, it came for his hire.',	'அதற்கு உடையவன் கூட இருந்தானாகில், அவன் உத்தரவாதம்பண்ணவேண்டுவதில்லை; அது வாடகைக்கு வாங்கப்பட்டிருந்தால், அது அவன் வாடகைக்கு வந்த சேதம்.',	2,	22,	15),
(2130,	'And if a man entice a maid that is not betrothed, and lie with her, he shall surely endow her to be his wife.',	'நியமிக்கப்படாத ஒரு கன்னிகையை ஒருவன் மோசம்போக்கி அவளோடே சயனித்தால், அவன் அவளுக்காகப் பரிசம்கொடுத்து, அவளை விவாகம்பண்ணக்கடவன்.',	2,	22,	16),
(2131,	'If her father utterly refuse to give her unto him, he shall pay money according to the dowry of virgins.',	'அவள் தகப்பன் அவளை அவனுக்குக் கொடுக்கமாட்டேன் என்றானாகில், கன்னிகைகளுக்காகக் கொடுக்கப்படும் பரிச முறைமையின்படி அவன் பணத்தை நிறுத்துக் கொடுக்கவேண்டும்.',	2,	22,	17),
(2132,	'Thou shalt not suffer a witch to live.',	'சூனியக்காரியை உயிரோடே வைக்கவேண்டாம்.',	2,	22,	18),
(2133,	'Whosoever lieth with a beast shall surely be put to death.',	'மிருகத்தோடே புணருகிறவன் எவனும் கொல்லப்படவேண்டும்.',	2,	22,	19),
(2134,	'He that sacrificeth unto any god, save unto the LORD only, he shall be utterly destroyed.',	'கர்த்தர் ஒருவருக்கே ஒழிய வேறே தேவர்களுக்குப் பலியிடுகிறவன் சங்கரிக்கப்படக்கடவன்.',	2,	22,	20),
(2135,	'Thou shalt neither vex a stranger, nor oppress him: for ye were strangers in the land of Egypt.',	'அந்நியனைச் சிறுமைப்படுத்தாமலும் ஒடுக்காமலும் இருப்பீர்களாக; நீங்களும் எகிப்து தேசத்தில் அந்நியர்களாயிருந்தீர்களே.',	2,	22,	21),
(2136,	'Ye shall not afflict any widow, or fatherless child.',	'விதவையையும் திக்கற்ற பிள்ளையையும் ஒடுக்காமல் இருப்பீர்களாக;',	2,	22,	22),
(2137,	'If thou afflict them in any wise, and they cry at all unto me, I will surely hear their cry;',	'அவர்களை எவ்வளவாகிலும் ஒடுக்கும்போது, அவர்கள் என்னை நோக்கி முறையிட்டால், அவர்கள் முறையிடுதலை நான் நிச்சயமாய்க் கேட்டு,',	2,	22,	23),
(2138,	'And my wrath shall wax hot, and I will kill you with the sword; and your wives shall be widows, and your children fatherless.',	'கோபம்மூண்டவராகி, உங்களைப்பட்டயத்தினால் கொலைசெய்வேன்; உங்கள் மனைவிகள் விதவைகளும், உங்கள் பிள்ளைகள் திக்கற்ற பிள்ளைகளுமாவார்கள்.',	2,	22,	24),
(2139,	'If thou lend money to any of my people that is poor by thee, thou shalt not be to him as an usurer, neither shalt thou lay upon him usury.',	'உங்களுக்குள் சிறுமைப்பட்டிருக்கிற என் ஜனங்களில் ஒருவனுக்கு நீங்கள் பணம் கடனாகக் கொடுத்திருந்தால், வட்டிவாங்குகிறவர்கள்போல அவனிடத்தில் வட்டி வாங்கவேண்டாம்.',	2,	22,	25),
(2140,	'If thou at all take thy neighbour\'s raiment to pledge, thou shalt deliver it unto him by that the sun goeth down:',	'பிறனுடைய வஸ்திரத்தை ஈடாக வாங்கினால், பொழுதுபோகுமுன்னமே அதை அவனுக்குத் திரும்பக் கொடுத்துவிடுவாயாக.',	2,	22,	26),
(2141,	'For that is his covering only, it is his raiment for his skin: wherein shall he sleep? and it shall come to pass, when he crieth unto me, that I will hear; for I am gracious.',	'அவன் போர்வை அதுதானே, அதுவே அவன் தன் உடம்பை மூடிக்கொள்ளுகிற வஸ்திரம்; வேறு எதினாலே போர்த்துப் படுத்துக்கொள்ளுவான்? அவன் என்னை நோக்கி முறையிடும்போது, நான் அவனுக்குச் செவிகொடுப்பேன், நான் இரக்கமுள்ளவராயிருக்கிறேன்.',	2,	22,	27),
(2142,	'Thou shalt not revile the gods, nor curse the ruler of thy people.',	'நியாயாதிபதிகளைத் தூஷியாமலும், உன் ஜனத்தின் அதிபதியைச் சபியாமலும் இருப்பாயாக.',	2,	22,	28),
(2143,	'Thou shalt not delay to offer the first of thy ripe fruits, and of thy liquors: the firstborn of thy sons shalt thou give unto me.',	'முதல் முதல் பழுக்கும் உன் பழத்தையும், வடியும் உன் இரசத்தையும் காணிக்கையாகச் செலுத்தத் தாமதிக்கவேண்டாம். உன் குமாரரில் முதற்பேறானவனை எனக்குக் கொடுப்பாயாக.',	2,	22,	29),
(2144,	'Likewise shalt thou do with thine oxen, and with thy sheep: seven days it shall be with his dam; on the eighth day thou shalt give it me.',	'உன் மாடுகளிலும் உன் ஆடுகளிலும் அப்படியே செய்வாயாக; குட்டியானது ஏழுநாள் தன் தாயோடே இருக்கட்டும்; எட்டாம் நாளிலே அதை எனக்குச் செலுத்துவாயாக.',	2,	22,	30),
(2145,	'And ye shall be holy men unto me: neither shall ye eat any flesh that is torn of beasts in the field; ye shall cast it to the dogs.',	'நீங்கள் எனக்குப் பரிசுத்த மனுஷராயிருக்கக்கடவீர்கள்; வெளியிலே பீறுண்ட மாம்சத்தைப் புசியாமல், அதை நாய்களுக்குப் போட்டுவிடுங்கள்.  ',	2,	22,	31),
(2146,	'Thou shalt not raise a false report: put not thine hand with the wicked to be an unrighteous witness.',	'அபாண்டமான சொல்லை ஏற்றுக்கொள்ளாயாக; கொடுமையுள்ள சாட்சிக்காரனாயிருக்க ஆகாதவனோடே கலவாயாக.',	2,	23,	1),
(2147,	'Thou shalt not follow a multitude to do evil; neither shalt thou speak in a cause to decline after many to wrest judgment:',	'தீமைசெய்ய திரளானபேர்களைப் பின்பற்றாதிருப்பாயாக; வழக்கிலே நியாயத்தைப் புரட்ட மிகுதியானவர்களின் பட்சத்தில் சாய்ந்து, உத்தரவு சொல்லாதிருப்பாயாக.',	2,	23,	2),
(2148,	'Neither shalt thou countenance a poor man in his cause.',	'வியாச்சியத்திலே தரித்திரனுடைய முகத்தைப் பாராயாக.',	2,	23,	3),
(2149,	'If thou meet thine enemy\'s ox or his ass going astray, thou shalt surely bring it back to him again.',	'உன் சத்துருவின் மாடாவது அவனுடைய கழுதையாவது தப்பிப்போகக்கண்டால், அதைத் திரும்ப அவனிடத்தில் கொண்டுபோய் விடுவாயாக.',	2,	23,	4),
(2150,	'If thou see the ass of him that hateth thee lying under his burden, and wouldest forbear to help him, thou shalt surely help with him.',	'உன்னைப் பகைக்கிறவனுடைய கழுதை சுமையோடே விழுந்துகிடக்கக்கண்டாயானால், அதற்கு உதவிசெய்யாதிருக்கலாமா? அவசியமாய் அவனோடேகூட அதற்கு உதவிசெய்வாயாக.',	2,	23,	5),
(2151,	'Thou shalt not wrest the judgment of thy poor in his cause.',	'உன்னிடத்திலிருக்கிற எளியவனுடைய வியாச்சியத்தில் அவனுடைய நியாயத்தைப் புரட்டாயாக.',	2,	23,	6),
(2152,	'Keep thee far from a false matter; and the innocent and righteous slay thou not: for I will not justify the wicked.',	'கள்ளக்காரியத்துக்குத் தூரமாயிருப்பாயாக; குற்றமில்லாதவனையும் நீதிமானையும் கொலைசெய்யாயாக; நான் துன்மார்க்கனை நீதிமான் என்று தீர்க்கமாட்டேன்.',	2,	23,	7),
(2153,	'And thou shalt take no gift: for the gift blindeth the wise, and perverteth the words of the righteous.',	'பரிதானம் வாங்காதிருப்பாயாக; பரிதானம் பார்வையுள்ளவர்களைக் குருடாக்கி, நீதிமான்களின் வார்த்தைகளைப் புரட்டும்.',	2,	23,	8),
(2154,	'Also thou shalt not oppress a stranger: for ye know the heart of a stranger, seeing ye were strangers in the land of Egypt.',	'அந்நியனை ஒடுக்காயாக; எகிப்துதேசத்தில் அந்நியர்களாயிருந்த நீங்கள் அந்நியனுடைய இருதயத்தை அறிந்திருக்கிறீர்களே.',	2,	23,	9),
(2155,	'And six years thou shalt sow thy land, and shalt gather in the fruits thereof:',	'ஆறுவருஷம் நீ உன் நிலத்தில் பயிரிட்டு, அதின் பலனைச் சேர்த்துக்கொள்.',	2,	23,	10),
(2156,	'But the seventh year thou shalt let it rest and lie still; that the poor of thy people may eat: and what they leave the beasts of the field shall eat. In like manner thou shalt deal with thy vineyard, and with thy oliveyard.',	'ஏழாம் வருஷத்தில் உன் ஜனத்திலுள்ள எளியவர்கள் புசிக்கவும், மீதியானதை வெளியின் ஜெந்துக்கள் தின்னவும், அந்த நிலம் சும்மா கிடக்க விட்டுவிடுவாயாக; உன் திராட்சத்தோட்டத்தையும் உன் ஒலிவத்தோப்பையும் அப்படியே செய்வாயாக.',	2,	23,	11),
(2157,	'Six days thou shalt do thy work, and on the seventh day thou shalt rest: that thine ox and thine ass may rest, and the son of thy handmaid, and the stranger, may be refreshed.',	'ஆறுநாள் உன் வேலையைச் செய்து, ஏழாம்நாளிலே உன் மாடும் உன் கழுதையும் இளைப்பாறவும், உன் அடிமைப்பெண்ணின் பிள்ளையும் அந்நியனும் இளைப்பாறவும் ஓய்ந்திருப்பாயாக.',	2,	23,	12),
(2158,	'And in all things that I have said unto you be circumspect: and make no mention of the name of other gods, neither let it be heard out of thy mouth.',	'நான் உங்களுக்குச் சொன்னவைகள் யாவற்றிலும் சாவதானமாயிருங்கள். அந்நிய தேவர்களின் பேரைச் சொல்லவேண்டாம்; அது உன் வாயிலிருந்து பிறக்கக் கேட்கப்படவும் வேண்டாம்.',	2,	23,	13),
(2159,	'Three times thou shalt keep a feast unto me in the year.',	'வருஷத்தில் மூன்றுதரம் எனக்குப்பண்டிகை ஆசரிப்பாயாக.',	2,	23,	14),
(2160,	'Thou shalt keep the feast of unleavened bread: (thou shalt eat unleavened bread seven days, as I commanded thee, in the time appointed of the month Abib; for in it thou camest out from Egypt: and none shall appear before me empty:)',	'புளிப்பில்லா அப்பப்பண்டிகையைக் கொண்டாடி, நான் உனக்குக் கட்டளையிட்டபடியே ஆபிப் மாதத்தின் குறித்தகாலத்தில் ஏழுநாள் புளிப்பில்லா அப்பம் புசிப்பாயாக; அந்த மாதத்தில் எகிப்திலிருந்து புறப்பட்டாயே, என் சந்நிதியில் வெறுங்கையாய் வரவேண்டாம்.',	2,	23,	15),
(2161,	'And the feast of harvest, the firstfruits of thy labours, which thou hast sown in the field: and the feast of ingathering, which is in the end of the year, when thou hast gathered in thy labours out of the field.',	'நீ வயலில் விதைத்த உன் பயிர் வேலைகளின் முதற்பலனைச் செலுத்துகிற அறுப்புக்கால பண்டிகையையும், வருஷமுடிவிலே நீ வயலில் உன் வேலைகளின் பலனைச் சேர்த்துத் தீர்ந்தபோது, சேர்ப்புக்கால பண்டிகையையும் ஆசரிப்பாயாக.',	2,	23,	16),
(2162,	'Three times in the year all thy males shall appear before the LORD God.',	'வருஷத்தில் மூன்றுதரம் உன் ஆண்மக்கள் எல்லாரும் கர்த்தராகிய ஆண்டவருடைய சந்நிதியில் வரக்கடவர்கள்.',	2,	23,	17),
(2163,	'Thou shalt not offer the blood of my sacrifice with leavened bread; neither shall the fat of my sacrifice remain until the morning.',	'எனக்கு இடும் பலியின் இரத்தத்தைப் புளித்தமாவுடன் செலுத்தவேண்டாம், எனக்கு இடும் பலியின் கொழுப்பை விடியற்காலம்வரைக்கும் வைக்கவும் வேண்டாம்.',	2,	23,	18),
(2164,	'The first of the firstfruits of thy land thou shalt bring into the house of the LORD thy God. Thou shalt not seethe a kid in his mother\'s milk.',	'உன் நிலத்தில் முதல் விளைச்சல்களின் முதற் கனியை உன் தேவனாகிய கர்த்தருடைய ஆலயத்துக்குக் கொண்டுவருவாயாக; வெள்ளாட்டுக்குட்டியை அதின் தாயின் பாலிலே சமைக்கவேண்டாம்.',	2,	23,	19),
(2165,	'Behold, I send an Angel before thee, to keep thee in the way, and to bring thee into the place which I have prepared.',	'வழியில் உன்னைக் காக்கிறதற்கும், நான் ஆயத்தம்பண்ணின ஸ்தானத்துக்கு உன்னைக் கொண்டுபோய்ச் சேர்க்கிறதற்கும், இதோ, நான் ஒரு தூதனை உனக்கு முன்னே அனுப்புகிறேன்.',	2,	23,	20),
(2166,	'Beware of him, and obey his voice, provoke him not; for he will not pardon your transgressions: for my name is in him.',	'அவர் சமுகத்தில் எச்சரிக்கையாயிருந்து, அவர் வாக்குக்குச் செவிகொடு; அவரைக் கோபப்படுத்தாதே; உங்கள் துரோகங்களை அவர் பொறுப்பதில்லை; என் நாமம் அவர் உள்ளத்தில் இருக்கிறது.',	2,	23,	21),
(2167,	'But if thou shalt indeed obey his voice, and do all that I speak; then I will be an enemy unto thine enemies, and an adversary unto thine adversaries.',	'நீ அவர் வாக்கை நன்றாய்க் கேட்டு, நான் சொல்வதையெல்லாம் செய்வாயாகில், நான் உன் சத்துருக்களுக்குச் சத்துருவாயும், உன் விரோதிகளுக்கு விரோதியாயும் இருப்பேன்.',	2,	23,	22),
(2168,	'For mine Angel shall go before thee, and bring thee in unto the Amorites, and the Hittites, and the Perizzites, and the Canaanites, the Hivites, and the Jebusites: and I will cut them off.',	'என் தூதனானவர் உனக்குமுன்சென்று, எமோரியரும், ஏத்தியரும், பெரிசியரும், கானானியரும், ஏவியரும், எபூசியரும், இருக்கிற இடத்துக்கு உன்னை நடத்திக்கொண்டுபோவார்; அவர்களை நான் அதம்பண்ணுவேன்.',	2,	23,	23),
(2169,	'Thou shalt not bow down to their gods, nor serve them, nor do after their works: but thou shalt utterly overthrow them, and quite break down their images.',	'நீ அவர்களுடைய தேவர்களைப்பணிந்துகொள்ளாமலும், சேவியாமலும், அவர்கள் செய்கைகளின்படி செய்யாமலும், அவர்களை நிர்மூலம்பண்ணி, அவர்களுடைய சிலைகளை உடைத்துப்போடுவாயாக.',	2,	23,	24),
(2170,	'And ye shall serve the LORD your God, and he shall bless thy bread, and thy water; and I will take sickness away from the midst of thee.',	'உங்கள் தேவனாகிய கர்த்தரையே சேவிக்கக்கடவீர்கள்; அவர் உன் அப்பத்தையும் உன் தண்ணீரையும் ஆசீர்வதிப்பார். வியாதியை உன்னிலிருந்து விலக்குவேன்.',	2,	23,	25),
(2171,	'There shall nothing cast their young, nor be barren, in thy land: the number of thy days I will fulfil.',	'கர்ப்பம் விழுகிறதும், மலடும் உன் தேசத்தில் இருப்பதில்லை; உன் ஆயுசு நாட்களைப் பூரணப்படுத்துவேன்.',	2,	23,	26),
(2172,	'I will send my fear before thee, and will destroy all the people to whom thou shalt come, and I will make all thine enemies turn their backs unto thee.',	'எனக்குப் பயப்படும் பயத்தை உனக்குமுன் செல்லும்படி செய்வேன். நீ செல்லும் இடமெங்குமுள்ள ஜனங்கள் எல்லாரையும் கலங்கடித்து, உன் சத்துருக்கள் எல்லாரையும் முதுகு காட்டப்பண்ணுவேன்.',	2,	23,	27),
(2173,	'And I will send hornets before thee, which shall drive out the Hivite, the Canaanite, and the Hittite, from before thee.',	'உன் முகத்திற்கு முன்னின்று ஏவியரையும் கானானியரையும் ஏத்தியரையும் துரத்திவிட, குளவிகளை உனக்கு முன்னே அனுப்புவேன்.',	2,	23,	28),
(2174,	'I will not drive them out from before thee in one year; lest the land become desolate, and the beast of the field multiply against thee.',	'தேசம் பாழாய்ப்போகாமலும், காட்டுமிருகங்கள் உனக்கு விரோதமாய்ப் பெருகாமலும் இருக்கும்படி, நான் அவர்களை ஒரே வருஷத்திற்குள்ளே உன் முன்னின்று துரத்திவிடாமல்,',	2,	23,	29),
(2175,	'By little and little I will drive them out from before thee, until thou be increased, and inherit the land.',	'நீ விருத்தியடைந்து, தேசத்தைச் சுதந்தரித்துக்கொள்ளும்வரைக்கும், அவர்களைக் கொஞ்சம் கொஞ்சமாய் உன் முன்னின்று துரத்திவிடுவேன்.',	2,	23,	30),
(2176,	'And I will set thy bounds from the Red sea even unto the sea of the Philistines, and from the desert unto the river: for I will deliver the inhabitants of the land into your hand; and thou shalt drive them out before thee.',	'சிவந்த சமுத்திரம் தொடங்கி பெலிஸ்தரின் சமுத்திரம்வரைக்கும், வனாந்தரம் தொடங்கி நதிவரைக்கும் உன் எல்லையாயிருக்கும்படி செய்வேன்; நான் அந்தத் தேசத்தின் குடிகளை உங்கள் கையில் ஒப்புக்கொடுப்பேன்; நீ அவர்களை உன் முன்னின்று துரத்திவிடுவாய்.',	2,	23,	31),
(2177,	'Thou shalt make no covenant with them, nor with their gods.',	'அவர்களோடும் அவர்கள் தேவர்களோடும் நீ உடன்படிக்கைபண்ணாதிருப்பாயாக.',	2,	23,	32),
(2178,	'They shall not dwell in thy land, lest they make thee sin against me: for if thou serve their gods, it will surely be a snare unto thee.',	'அவர்கள் உன்னை எனக்கு விரோதமாகப் பாவஞ்செய்யப்பண்ணாதபடிக்கு உன் தேசத்திலே குடியிருக்கவேண்டாம்; நீ அவர்கள் தேவர்களைச் சேவித்தால், அது உனக்குக் கண்ணியாயிருக்கும் என்றார்.  ',	2,	23,	33),
(2179,	'And he said unto Moses, Come up unto the LORD, thou, and Aaron, Nadab, and Abihu, and seventy of the elders of Israel; and worship ye afar off.',	'பின்பு அவர் மோசேயை நோக்கி: நீயும் ஆரோனும் நாதாபும் அபியூவும் இஸ்ரவேலின் மூப்பரில் எழுபதுபேரும் கர்த்தரிடத்தில் ஏறிவந்து, தூரத்திலிருந்து பணிந்துகொள்ளுங்கள்.',	2,	24,	1),
(2180,	'And Moses alone shall come near the LORD: but they shall not come nigh; neither shall the people go up with him.',	'மோசே மாத்திரம் கர்த்தரிடத்தில் சமீபித்து வரலாம்; அவர்கள் சமீபித்து வரலாகாது; ஜனங்கள் அவனோடேகூட ஏறிவரவேண்டாம் என்றார்.',	2,	24,	2),
(2181,	'And Moses came and told the people all the words of the LORD, and all the judgments: and all the people answered with one voice, and said, All the words which the LORD hath said will we do.',	'மோசே வந்து, கர்த்தருடைய வார்த்தைகள் யாவையும் நியாயங்கள் யாவையும் ஜனங்களுக்கு அறிவித்தான்; அப்பொழுது ஜனங்கள் எல்லாரும் ஏகசத்தமாய்: கர்த்தர் அருளின எல்லா வார்த்தைகளின்படியும் செய்வோம் என்று பிரதியுத்தரம் சொன்னார்கள்.',	2,	24,	3),
(2182,	'And Moses wrote all the words of the LORD, and rose up early in the morning, and builded an altar under the hill, and twelve pillars, according to the twelve tribes of Israel.',	'மோசே கர்த்தருடைய வார்த்தைகளையெல்லாம் எழுதிவைத்து, அதிகாலமே எழுந்து, மலையின் அடியில் ஒரு பலிபீடத்தைக் கட்டி, இஸ்ரவேலுடைய பன்னிரண்டு கோத்திரங்களுடைய இலக்கத்தின்படியே பன்னிரண்டு தூண்களை நிறுத்தினான்.',	2,	24,	4),
(2183,	'And he sent young men of the children of Israel, which offered burnt offerings, and sacrificed peace offerings of oxen unto the LORD.',	'இஸ்ரவேல் புத்திரரின் வாலிபரை அனுப்பினான்; அவர்கள் சர்வாங்கதகனபலிகளைச் செலுத்தி, கர்த்தருக்குச் சமாதானபலிகளாகக் காளைகளைப் பலியிட்டார்கள்.',	2,	24,	5),
(2184,	'And Moses took half of the blood, and put it in basons; and half of the blood he sprinkled on the altar.',	'அப்பொழுது மோசே அந்த இரத்தத்தில் பாதி எடுத்து, பாத்திரங்களில் வார்த்து, பாதி இரத்தத்தைப் பலிபீடத்தின்மேல் தெளித்து,',	2,	24,	6),
(2185,	'And he took the book of the covenant, and read in the audience of the people: and they said, All that the LORD hath said will we do, and be obedient.',	'உடன்படிக்கையின் புஸ்தகத்தை எடுத்து, ஜனங்களின் காது கேட்க வாசித்தான்; அவர்கள் கர்த்தர் சொன்னபடியெல்லாம் செய்து, கீழ்ப்படிந்து நடப்போம் என்றார்கள்.',	2,	24,	7),
(2186,	'And Moses took the blood, and sprinkled it on the people, and said, Behold the blood of the covenant, which the LORD hath made with you concerning all these words.',	'அப்பொழுது மோசே இரத்தத்தை எடுத்து, ஜனங்களின்மேல் தெளித்து, இந்த வார்த்தைகள் யாவையுங்குறித்து கர்த்தர் உங்களோடே பண்ணின உடன்படிக்கையின் இரத்தம் இதுவே என்றான்.',	2,	24,	8),
(2187,	'Then went up Moses, and Aaron, Nadab, and Abihu, and seventy of the elders of Israel:',	'பின்பு மோசேயும் ஆரோனும் நாதாபும் அபியூவும், இஸ்ரவேலருடைய மூப்பரின் எழுபதுபேரும் ஏறிப்போய்,',	2,	24,	9),
(2188,	'And they saw the God of Israel: and there was under his feet as it were a paved work of a sapphire stone, and as it were the body of heaven in his clearness.',	'இஸ்ரவேலின் தேவனைத் தரிசித்தார்கள். அவருடைய பாதத்தின்கீழே நீலக்கல்லிழைத்த வேலைக்கு ஒப்பாகவும் தெளிந்த வானத்தின் பிரபைக்கு ஒப்பாகவும் இருந்தது.',	2,	24,	10),
(2189,	'And upon the nobles of the children of Israel he laid not his hand: also they saw God, and did eat and drink.',	'அவர் இஸ்ரவேல் புத்திரருடைய அதிபதிகள்மேல் தம்முடைய கையை நீட்டவில்லை; அவர்கள் தேவனைத் தரிசித்து, பின்பு புசித்துக் குடித்தார்கள்.',	2,	24,	11),
(2190,	'And the LORD said unto Moses, Come up to me into the mount, and be there: and I will give thee tables of stone, and a law, and commandments which I have written; that thou mayest teach them.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ மலையின்மேல் என்னிடத்திற்கு ஏறிவந்து, அங்கே இரு நான் உனக்குக் கற்பலகைகளையும், நீ அவர்களுக்கு உபதேசிப்பதற்கு, நான் எழுதின நியாயப்பிரமாணத்தையும் கற்பனைகளையும் கொடுப்பேன் என்றார்.',	2,	24,	12),
(2191,	'And Moses rose up, and his minister Joshua: and Moses went up into the mount of God.',	'அப்பொழுது மோசே தன் ஊழியக்காரனாகிய யோசுவாவோடே எழுந்து போனான். மோசே தேவ பர்வதத்தில் ஏறிப்போகையில்,',	2,	24,	13),
(2192,	'And he said unto the elders, Tarry ye here for us, until we come again unto you: and, behold, Aaron and Hur are with you: if any man have any matters to do, let him come unto them.',	'அவன் மூப்பரை நோக்கி: நாங்கள் உங்களிடத்தில் திரும்பிவருமட்டும், நீங்கள் இங்கே எங்களுக்காகக் காத்திருங்கள்; ஆரோனும் ஊரும் உங்களிடத்தில் இருக்கிறார்கள்; ஒருவனுக்கு யாதொரு காரியம் உண்டானால், அவன் அவர்களிடத்தில் போகலாம் என்றான்.',	2,	24,	14),
(2193,	'And Moses went up into the mount, and a cloud covered the mount.',	'மோசே மலையின்மேல் ஏறினபோது, ஒரு மேகம் மலையை மூடிற்று.',	2,	24,	15),
(2194,	'And the glory of the LORD abode upon mount Sinai, and the cloud covered it six days: and the seventh day he called unto Moses out of the midst of the cloud.',	'கர்த்தருடைய மகிமை சீனாய்மலையின்மேல் தங்கியிருந்தது; மேகம் ஆறுநாள் அதை மூடியிருந்தது; ஏழாம்நாளில் அவர் மேகத்தின் நடுவிலிருந்து மோசேயைக் கூப்பிட்டார்.',	2,	24,	16),
(2195,	'And the sight of the glory of the LORD was like devouring fire on the top of the mount in the eyes of the children of Israel.',	'மலையின் கொடுமுடியிலே கர்த்தருடைய மகிமையின் காட்சி இஸ்ரவேல் புத்திரருடைய கண்களுக்குப் பட்சிக்கிற அக்கினியைப்போல் இருந்தது.',	2,	24,	17),
(2196,	'And Moses went into the midst of the cloud, and gat him up into the mount: and Moses was in the mount forty days and forty nights.',	'மோசே மேகத்தின் நடுவிலே பிரவேசித்து, மலையின்மேல் ஏறி, இரவும் பகலும் நாற்பதுநாள் மலையில் இருந்தான்.  ',	2,	24,	18),
(2197,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	2,	25,	1),
(2198,	'Speak unto the children of Israel, that they bring me an offering: of every man that giveth it willingly with his heart ye shall take my offering.',	'இஸ்ரவேல் புத்திரர் எனக்குக் காணிக்கையைக் கொண்டுவரும்படி அவர்களுக்குச் சொல்லு; மனப்பூர்வமாய் உற்சாகத்துடன் கொடுப்பவன் எவனோ அவனிடத்தில் எனக்குக் காணிக்கையை வாங்குவீர்களாக.',	2,	25,	2),
(2199,	'And this is the offering which ye shall take of them; gold, and silver, and brass,',	'நீங்கள் அவர்களிடத்தில் வாங்க வேண்டிய காணிக்கையாவன, பொன்னும், வெள்ளியும், வெண்கலமும்,',	2,	25,	3),
(2200,	'And blue, and purple, and scarlet, and fine linen, and goats\' hair,',	'இளநீலநூலும், இரத்தாம்பர நூலும், சிவப்பு நூலும், மெல்லிய பஞ்சு நூலும், வெள்ளாட்டு மயிரும்,',	2,	25,	4),
(2201,	'And rams\' skins dyed red, and badgers\' skins, and shittim wood,',	'சிவப்புத்தீர்ந்த ஆட்டுக்கடாத்தோலும், தகசுத்தோலும், சீத்திம் மரமும்,',	2,	25,	5),
(2202,	'Oil for the light, spices for anointing oil, and for sweet incense,',	'விளக்கெண்ணெயும், அபிஷேகதைலத்துக்குப் பரிமளவர்க்கங்களும், தூபத்துக்குச் சுகந்தவர்க்கங்களும்,',	2,	25,	6),
(2203,	'Onyx stones, and stones to be set in the ephod, and in the breastplate.',	'ஏபோத்திலும் மார்ப்பதக்கத்திலும் பதிக்கும் கோமேதகக் கற்களும் இரத்தினங்களுமே.',	2,	25,	7),
(2204,	'And let them make me a sanctuary; that I may dwell among them.',	'அவர்கள் நடுவிலே நான் வாசம்பண்ண, எனக்கு ஒரு பரிசுத்த ஸ்தலத்தை உண்டாக்குவார்களாக.',	2,	25,	8),
(2205,	'According to all that I shew thee, after the pattern of the tabernacle, and the pattern of all the instruments thereof, even so shall ye make it.',	'நான் உனக்குக் காண்பிக்கும் வாசஸ்தலத்தின் மாதிரியின்படியும், அதினுடைய எல்லாத் தட்டுமுட்டுகளின் மாதிரியின்படியும் அதைச் செய்வீர்களாக.',	2,	25,	9),
(2206,	'And they shall make an ark of shittim wood: two cubits and a half shall be the length thereof, and a cubit and a half the breadth thereof, and a cubit and a half the height thereof.',	'சீத்திம் மரத்தினால் ஒரு பெட்டியைப் பண்ணக்கடவர்கள்; அதின் நீளம் இரண்டரை முழமும், அதின் அகலம் ஒன்றரை முழமும், அதின் உயரம் ஒன்றரை முழமுமாயிருப்பதாக.',	2,	25,	10),
(2207,	'And thou shalt overlay it with pure gold, within and without shalt thou overlay it, and shalt make upon it a crown of gold round about.',	'அதை எங்கும் பசும்பொன் தகட்டால் மூடுவாயாக; நீ அதின் உட்புறத்தையும் வெளிப்புறத்தையும் அதினால் மூடி, அதின்மேல் சுற்றிலும் பொன்னினால் திரணையை உண்டாக்கி,',	2,	25,	11),
(2208,	'And thou shalt cast four rings of gold for it, and put them in the four corners thereof; and two rings shall be in the one side of it, and two rings in the other side of it.',	'அதற்கு நாலு பொன் வளையங்களை வார்ப்பித்து, அவைகளை அதின் நாலு மூலைகளிலும் போட்டு, ஒரு பக்கத்தில் இரண்டு வளையங்களும், மறுபக்கத்தில் இரண்டு வளையங்களும் இருக்கும்படி தைத்து,',	2,	25,	12),
(2209,	'And thou shalt make staves of shittim wood, and overlay them with gold.',	'சீத்திம் மரத்தால் தண்டுகளைச் செய்து, அவைகளைப் பொன்தகட்டால் மூடி,',	2,	25,	13),
(2210,	'And thou shalt put the staves into the rings by the sides of the ark, that the ark may be borne with them.',	'அந்தத் தண்டுகளால் பெட்டியைச் சுமக்கும்படி, அவைகளைப் பெட்டியின் பக்கங்களிலிருக்கும் வளையங்களிலே பாய்ச்சக்கடவாய்.',	2,	25,	14),
(2211,	'The staves shall be in the rings of the ark: they shall not be taken from it.',	'அந்தத் தண்டுகள் பெட்டியிலிருந்து கழற்றப்படாமல், அதின் வளையங்களிலே இருக்கவேண்டும்.',	2,	25,	15),
(2212,	'And thou shalt put into the ark the testimony which I shall give thee.',	'நான் உனக்குக் கொடுக்கும் சாட்சிப்பிரமாணத்தை அந்தப்பெட்டியிலே வைப்பாயாக.',	2,	25,	16),
(2213,	'And thou shalt make a mercy seat of pure gold: two cubits and a half shall be the length thereof, and a cubit and a half the breadth thereof.',	'பசும்பொன்னினாலே கிருபாசனத்தைப்பண்ணுவாயாக; அது இரண்டரை முழ நீளமும் ஒன்றரை முழ அகலமுமாய் இருக்கக்கடவது.',	2,	25,	17),
(2214,	'And thou shalt make two cherubims of gold, of beaten work shalt thou make them, in the two ends of the mercy seat.',	'பொன்னினால் இரண்டு கேருபீன்களைச் செய்வாயாக; பொன்னைத் தகடாய் அடித்து, அவைகளைச் செய்து, கிருபாசனத்தின் இரண்டு ஓரங்களிலும் வைப்பாயாக.',	2,	25,	18),
(2215,	'And make one cherub on the one end, and the other cherub on the other end: even of the mercy seat shall ye make the cherubims on the two ends thereof.',	'ஒருபுறத்து ஓரத்தில் ஒரு கேருபீனையும் மறுபுறத்து ஓரத்தில் மற்றக் கேருபீனையும் பண்ணிவை; அந்தக் கேருபீன்கள் கிருபாசனத்தின் இரண்டு ஓரங்களிலும் அதனோடே ஏகவேலையாயிருக்கும்படி, அவைகளைப் பண்ணக்கடவாய்.',	2,	25,	19),
(2216,	'And the cherubims shall stretch forth their wings on high, covering the mercy seat with their wings, and their faces shall look one to another; toward the mercy seat shall the faces of the cherubims be.',	'அந்தக் கேருபீன்கள் தங்கள் செட்டைகளை உயர விரித்து, தங்கள் செட்டைகளால் கிருபாசனத்தை மூடுகிறவைகளும் ஒன்றுக்கொன்று எதிர்முகமுள்ளவைகளுமாய் இருக்கக்கடவது; கேருபீன்களின் முகங்கள் கிருபாசனத்தை நோக்குகிறவைகளாயிருப்பதாக.',	2,	25,	20),
(2217,	'And thou shalt put the mercy seat above upon the ark; and in the ark thou shalt put the testimony that I shall give thee.',	'கிருபாசனத்தை பெட்டியின்மீதில் வைத்து, பெட்டிக்குள்ளே நான் உனக்குக் கொடுக்கும் சாட்சிப்பிரமாணத்தை வைப்பாயாக.',	2,	25,	21),
(2218,	'And there I will meet with thee, and I will commune with thee from above the mercy seat, from between the two cherubims which are upon the ark of the testimony, of all things which I will give thee in commandment unto the children of Israel.',	'அங்கே நான் உன்னைச் சந்திப்பேன்; கிருபாசனத்தின்மீதிலும் சாட்சிப்பெட்டியின்மேல் நிற்கும் இரண்டு கேருபீன்களின் நடுவிலும் இருந்து நான் இஸ்ரவேல் புத்திரருக்காக உனக்குக் கற்பிக்கப் போகிறவைகளையெல்லாம் உன்னோடே சொல்லுவேன்.',	2,	25,	22),
(2219,	'Thou shalt also make a table of shittim wood: two cubits shall be the length thereof, and a cubit the breadth thereof, and a cubit and a half the height thereof.',	'சீத்திம் மரத்தால் ஒரு மேஜையையும் பண்ணுவாயாக; அது இரண்டு முழ நீளமும் ஒரு முழ அகலமும் ஒன்றரை முழ உயரமுமாய் இருக்கக்கடவது.',	2,	25,	23),
(2220,	'And thou shalt overlay it with pure gold, and make thereto a crown of gold round about.',	'அதைப் பசும்பொன் தகட்டால் மூடி, சுற்றிலும் அதற்குப் பொன்னினால் திரணையை உண்டாக்கி,',	2,	25,	24),
(2221,	'And thou shalt make unto it a border of an hand breadth round about, and thou shalt make a golden crown to the border thereof round about.',	'சுற்றிலும் அதற்கு நாலு விரற்கடையான சட்டத்தையும், அதின் சட்டத்திற்குச் சுற்றிலும் பொன்னினால் திரணையையும் உண்டாக்கி,',	2,	25,	25),
(2222,	'And thou shalt make for it four rings of gold, and put the rings in the four corners that are on the four feet thereof.',	'அதற்கு நாலு பொன்வளையங்களைப் பண்ணி, அவைகளை அதின் நாலு கால்களுக்கு இருக்கும் நாலு மூலைகளிலும் தைக்கக்கடவாய்.',	2,	25,	26),
(2223,	'Over against the border shall the rings be for places of the staves to bear the table.',	'அந்த வளையங்கள் மேஜையைச் சுமக்கும் தண்டுகளுக்கு இடங்களாயிருக்கும்படி, சட்டத்தின் அருகே இருக்கவேண்டும்.',	2,	25,	27),
(2224,	'And thou shalt make the staves of shittim wood, and overlay them with gold, that the table may be borne with them.',	'அந்தத் தண்டுகளைச் சீத்திம் மரத்தினால் செய்து, அவைகளைப் பொன்தகட்டால் மூடக்கடவாய்; அவைகளால் மேஜை சுமக்கப்படவேண்டும்.',	2,	25,	28),
(2225,	'And thou shalt make the dishes thereof, and spoons thereof, and covers thereof, and bowls thereof, to cover withal: of pure gold shalt thou make them.',	'அதற்குரிய தட்டுகளையும், தூபக்கரண்டிகளையும், கிண்ணங்களையும், பானபலி கரகங்களையும் பண்ணக்கடவாய்; அவைகளைப் பசும்பொன்னினால் பண்ணக்கடவாய்.',	2,	25,	29),
(2226,	'And thou shalt set upon the table shewbread before me alway.',	'மேஜையின்மேல் நித்தமும் என் சந்நிதியில் சமுகத்தப்பங்களை வைக்கக்கடவாய்.',	2,	25,	30),
(2227,	'And thou shalt make a candlestick of pure gold: of beaten work shall the candlestick be made: his shaft, and his branches, his bowls, his knops, and his flowers, shall be of the same.',	'பசும்பொன்னினால் ஒரு குத்துவிளக்கையும் உண்டாக்குவாயாக; அது பொன்னினால் அடிப்புவேலையாய்ச் செய்யப்படவேண்டும்; அதின் தண்டும் கிளைகளும் மொக்குகளும் பழங்களும் பூக்களும் பொன்னினால் செய்யப்படவேண்டும்.',	2,	25,	31),
(2228,	'And six branches shall come out of the sides of it; three branches of the candlestick out of the one side, and three branches of the candlestick out of the other side:',	'ஆறு கிளைகள் அதின் பக்கங்களில் விடவேண்டும்; குத்துவிளக்கின் மூன்றுகிளைகள் அதின் ஒரு பக்கத்திலும், குத்துவிளக்கின் மூன்று கிளைகள் அதின் மறுபக்கத்திலும் விடவேண்டும்.',	2,	25,	32),
(2229,	'Three bowls made like unto almonds, with a knop and a flower in one branch; and three bowls made like almonds in the other branch, with a knop and a flower: so in the six branches that come out of the candlestick.',	'ஒவ்வொரு கிளையிலே வாதுமைக்கொட்டைக்கு ஒப்பான மூன்று மொக்குகளும், ஒரு பழமும், ஒரு பூவும் இருப்பதாக; குத்துவிளக்கிலிருந்து புறப்படும் ஆறு கிளைகளிலும் அப்படியே இருக்கவேண்டும்.',	2,	25,	33),
(2230,	'And in the candlesticks shall be four bowls made like unto almonds, with their knops and their flowers.',	'விளக்குத்தண்டிலோ, வாதுமைக் கொட்டைக்கு ஒப்பான நாலு மொக்குகளும், பழங்களும், பூக்களும் இருப்பதாக.',	2,	25,	34),
(2231,	'And there shall be a knop under two branches of the same, and a knop under two branches of the same, and a knop under two branches of the same, according to the six branches that proceed out of the candlestick.',	'அதிலிருந்து புறப்படும் இரண்டு கிளைகளின்கீழ் ஒரு பழமும், வேறு இரண்டு கிளைகளின்கீழ் ஒரு பழமும், மற்ற இரண்டு கிளைகளின்கீழ் ஒரு பழமும் இருப்பதாக; விளக்குத்தண்டிலிருந்து புறப்படும் ஆறு கிளைகளுக்கும் அப்படியே இருக்கவேண்டும்.',	2,	25,	35),
(2232,	'Their knops and their branches shall be of the same: all it shall be one beaten work of pure gold.',	'அவைகளின் பழங்களும் அவைகளின் கிளைகளும் பொன்னினால் உண்டானவைகளாயிருப்பதாக; அவையெல்லாம் தகடாய் அடித்த பசும்பொன்னால் செய்யப்பட்ட ஒரே வேலையாயிருக்கவேண்டும்.',	2,	25,	36),
(2233,	'And thou shalt make the seven lamps thereof: and they shall light the lamps thereof, that they may give light over against it.',	'அதில் ஏழு அகல்களைச் செய்வாயாக; அதற்கு நேரெதிராய் எரியும்படிக்கு அவைகள் ஏற்றப்படக்கடவது.',	2,	25,	37),
(2234,	'And the tongs thereof, and the snuffdishes thereof, shall be of pure gold.',	'அதின் கத்தரிகளும் சாம்பல் பாத்திரங்களும் பசும்பொன்னினால் செய்யப்படுவதாக.',	2,	25,	38),
(2235,	'Of a talent of pure gold shall he make it, with all these vessels.',	'அதையும், அதற்குரிய பணிமுட்டுகள் யாவையும் ஒரு தாலந்து பசும்பொன்னினால் பண்ணவேண்டும்.',	2,	25,	39),
(2236,	'And look that thou make them after their pattern, which was shewed thee in the mount.',	'மலையிலே உனக்குக் காண்பிக்கப்பட்ட மாதிரியின்படியே அவைகளைச் செய்ய எச்சரிக்கையாயிரு.  ',	2,	25,	40),
(2237,	'Moreover thou shalt make the tabernacle with ten curtains of fine twined linen, and blue, and purple, and scarlet: with cherubims of cunning work shalt thou make them.',	'மேலும் திரித்த மெல்லிய பஞ்சுநூலினாலும், இளநீலநூலினாலும், இரத்தாம்பரநூலினாலும், சிவப்பு நூலினாலும் நெய்யப்பட்ட பத்து மூடுதிரைகளால் வாசஸ்தலத்தை உண்டுபண்ணுவாயாக; அவைகளில் விசித்திரவேலையாய்க் கேருபீன்களைச் செய்யக்கடவாய்.',	2,	26,	1),
(2238,	'The length of one curtain shall be eight and twenty cubits, and the breadth of one curtain four cubits: and every one of the curtains shall have one measure.',	'ஒவ்வொரு மூடுதிரையும் இருபத்தெட்டு முழ நீளமும், நாலு முழ அகலமுமாயிருப்பதாக; மூடுதிரைகளெல்லாம் ஒரே அளவாயிருக்கவேண்டும்.',	2,	26,	2),
(2239,	'The five curtains shall be coupled together one to another; and other five curtains shall be coupled one to another.',	'ஐந்து மூடுதிரை ஒன்றோடொன்று இணைக்கப்பட்டிருக்கவேண்டும்; மற்ற ஐந்து மூடுதிரைகளும் ஒன்றோடொன்று இணைக்கப்பட்டிருக்கவேண்டும்.',	2,	26,	3),
(2240,	'And thou shalt make loops of blue upon the edge of the one curtain from the selvedge in the coupling; and likewise shalt thou make in the uttermost edge of another curtain, in the coupling of the second.',	'இணைக்கப்பட்ட ஒரு மூடுதிரையின் கடைஓரத்தில் இளநீலநூலால் காதுகளை உண்டுபண்ணு; இணைக்கப்பட்ட மற்ற மூடுதிரையின் கடைஓரத்திலும் அப்படியே செய்வாயாக.',	2,	26,	4),
(2241,	'Fifty loops shalt thou make in the one curtain, and fifty loops shalt thou make in the edge of the curtain that is in the coupling of the second; that the loops may take hold one of another.',	'காதுகள் ஒன்றோடொன்று இணையும்படி ஒரு மூடுதிரையில் ஐம்பது காதுகளையும், இணைக்கப்பட்ட மற்ற மூடுதிரையின் ஓரத்தில் ஐம்பது காதுகளையும் உண்டுபண்ணுவாயாக.',	2,	26,	5),
(2242,	'And thou shalt make fifty taches of gold, and couple the curtains together with the taches: and it shall be one tabernacle.',	'ஐம்பது பொன் கொக்கிகளையும் பண்ணி, மூடுதிரைகளை ஒன்றோடொன்று அந்தக் கொக்கிகளால் இணைத்துவிடுவாயாக. அப்பொழுது அது ஒரே வாசஸ்தலமாகும்.',	2,	26,	6),
(2243,	'And thou shalt make curtains of goats\' hair to be a covering upon the tabernacle: eleven curtains shalt thou make.',	'வாசஸ்தலத்தின்மேல் கூடாரமாகப்போடும்படி ஆட்டுமயிரால் பதினொரு மூடுதிரைகளை உண்டுபண்ணுவாயாக.',	2,	26,	7),
(2244,	'The length of one curtain shall be thirty cubits, and the breadth of one curtain four cubits: and the eleven curtains shall be all of one measure.',	'ஒவ்வொரு மூடுதிரை முப்பது முழ நீளமும், நாலு முழ அகலமுமாய் இருக்கவேண்டும்; பதினொரு மூடுதிரைகளும் ஒரே அளவாயிருக்கவேண்டும்.',	2,	26,	8),
(2245,	'And thou shalt couple five curtains by themselves, and six curtains by themselves, and shalt double the sixth curtain in the forefront of the tabernacle.',	'ஐந்து மூடுதிரைகளை ஒன்றாகவும், ஆறு மூடுதிரைகளை ஒன்றாகவும் இணைக்கவேண்டும்; ஆறாம் மூடுதிரையைக் கூடாரத்தின் முகப்பிற்கு முன்னே மடித்துப்போடுவாயாக.',	2,	26,	9),
(2246,	'And thou shalt make fifty loops on the edge of the one curtain that is outmost in the coupling, and fifty loops in the edge of the curtain which coupleth the second.',	'இணைக்கப்பட்ட ஒரு மூடுதிரையின் கடை ஓரத்தில் ஐம்பது காதுகளையும், இணைக்கப்பட்ட மற்ற மூடுதிரையின் ஓரத்தில் ஐம்பது காதுகளையும் உண்டுபண்ணி,',	2,	26,	10),
(2247,	'And thou shalt make fifty taches of brass, and put the taches into the loops, and couple the tent together, that it may be one.',	'ஐம்பது வெண்கலக் கொக்கிகளைச் செய்து, கொக்கிகளைக் காதுகளில் மாட்டி, ஒரே கூடாரமாகும்படி அதை இணைத்துவிடுவாயாக.',	2,	26,	11),
(2248,	'And the remnant that remaineth of the curtains of the tent, the half curtain that remaineth, shall hang over the backside of the tabernacle.',	'கூடாரத்தின் மூடுதிரைகளில் மிச்சமான பாதிமூடுதிரை வாசஸ்தலத்தின் பின்புறத்தில் தொங்கவேண்டும்.',	2,	26,	12),
(2249,	'And a cubit on the one side, and a cubit on the other side of that which remaineth in the length of the curtains of the tent, it shall hang over the sides of the tabernacle on this side and on that side, to cover it.',	'கூடாரத்தினுடைய மூடுதிரைகளின் நீளத்திலே மீதியானதில், இந்தப்புறத்தில் ஒரு முழமும் அந்தப்புறத்தில் ஒரு முழமும் வாசஸ்தலத்தை மூடும்படி அதின் பக்கங்களிலே தொங்கவேண்டும்.',	2,	26,	13),
(2250,	'And thou shalt make a covering for the tent of rams\' skins dyed red, and a covering above of badgers\' skins.',	'சிவப்புத்தீர்ந்த ஆட்டுக்கடாத் தோலினால் கூடாரத்திற்கு ஒரு மூடியையும், அதின்மேல் தகசுத்தோலால் ஒரு மூடியையும் உண்டுபண்ணுவாயாக.',	2,	26,	14),
(2251,	'And thou shalt make boards for the tabernacle of shittim wood standing up.',	'வாசஸ்தலத்துக்கு நிமிர்ந்துநிற்கும் பலகைகளையும் சீத்திம் மரத்தால் உண்டுபண்ணுவாயாக.',	2,	26,	15),
(2252,	'Ten cubits shall be the length of a board, and a cubit and a half shall be the breadth of one board.',	'ஒவ்வொரு பலகையும் பத்து முழ நீளமும் ஒன்றரை முழ அகலமுமாய் இருக்கவேண்டும்.',	2,	26,	16),
(2253,	'Two tenons shall there be in one board, set in order one against another: thus shalt thou make for all the boards of the tabernacle.',	'ஒவ்வொரு பலகைக்கும் ஒன்றோடொன்று ஒத்து இசைந்திருக்கும் இரண்டு கழுந்துகள் இருக்கவேண்டும்; வாசஸ்தலத்தின் பலகைகளுக்கெல்லாம் இப்படியே செய்வாயாக.',	2,	26,	17),
(2254,	'And thou shalt make the boards for the tabernacle, twenty boards on the south side southward.',	'வாசஸ்தலத்துக்காகச் செய்யப்படுகிற பலகைகளில் இருபது பலகை தெற்கே தென்திசைக்கு எதிராக நிற்கக்கடவது.',	2,	26,	18),
(2255,	'And thou shalt make forty sockets of silver under the twenty boards; two sockets under one board for his two tenons, and two sockets under another board for his two tenons.',	'அந்த இருபது பலகைகளின்கீழே வைக்கும் நாற்பது வெள்ளிப் பாதங்களை உண்டுபண்ணுவாயாக; ஒரு பலகையின் கீழ் அதின் இரண்டு கழுந்துகளுக்கும் இரண்டு பாதங்களும், மற்றப் பலகையின் கீழ் அதின் இரண்டு கழுந்துகளுக்கும் இரண்டு பாதங்களும் இருக்கவேண்டும்.',	2,	26,	19),
(2256,	'And for the second side of the tabernacle on the north side there shall be twenty boards:',	'வாசஸ்தலத்தின் மறுபக்கமாகிய வடபுறத்திலும் இருபது பலகைகளையும்,',	2,	26,	20),
(2257,	'And their forty sockets of silver; two sockets under one board, and two sockets under another board.',	'அவைகளின் கீழ் நாற்பது வெள்ளிப்பாதங்களையும் உண்டுபண்ணுவாயாக; ஒரு பலகையின் கீழ் இரண்டு பாதங்களும், மற்றப் பலகையின் கீழ் இரண்டு பாதங்களும் இருக்கவேண்டும்.',	2,	26,	21),
(2258,	'And for the sides of the tabernacle westward thou shalt make six boards.',	'வாசஸ்தலத்தின் மேற்புறத்திற்கு ஆறு பலகைகளையும்,',	2,	26,	22),
(2259,	'And two boards shalt thou make for the corners of the tabernacle in the two sides.',	'வாசஸ்தலத்தின் இருபக்கத்திலுமுள்ள மூலைகளுக்கு இரண்டு பலகைகளையும் உண்டுபண்ணுவாயாக.',	2,	26,	23),
(2260,	'And they shall be coupled together beneath, and they shall be coupled together above the head of it unto one ring: thus shall it be for them both; they shall be for the two corners.',	'அவைகள் கீழே இசைக்கப்பட்டிருக்கவேண்டும்; மேலேயும் ஒரு வளையத்தினால் இசைக்கப்பட்டிருக்கவேண்டும்; இரண்டு மூலைகளுக்கும் அப்படியே இருக்கவேண்டும்; அவைகள் இரண்டு மூலைகளுக்காகும்.',	2,	26,	24),
(2261,	'And they shall be eight boards, and their sockets of silver, sixteen sockets; two sockets under one board, and two sockets under another board.',	'அந்தப்படி எட்டுப் பலகைகள் இருக்கவேண்டும்; ஒவ்வொரு பலகையின் கீழ் இரண்டு இரண்டு பாதங்களாகப் பதினாறு வெள்ளிப் பாதங்களும் இருக்கவேண்டும்.',	2,	26,	25),
(2262,	'And thou shalt make bars of shittim wood; five for the boards of the one side of the tabernacle,',	'சீத்திம் மரத்தால் வாசஸ்தலத்தின் ஒரு பக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும்,',	2,	26,	26),
(2263,	'And five bars for the boards of the other side of the tabernacle, and five bars for the boards of the side of the tabernacle, for the two sides westward.',	'வாசஸ்தலத்தின் மறுபக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும், வாசஸ்தலத்தின் மேற்புறமான பின்பக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும் பண்ணுவாயாக.',	2,	26,	27),
(2264,	'And the middle bar in the midst of the boards shall reach from end to end.',	'நடுத்தாழ்ப்பாள் ஒரு முனை தொடங்கி மறுமுனைமட்டும் பலகைகளின் மையத்தில் உருவப் பாய்ச்சப்பட்டிருக்கவேண்டும்.',	2,	26,	28),
(2265,	'And thou shalt overlay the boards with gold, and make their rings of gold for places for the bars: and thou shalt overlay the bars with gold.',	'பலகைகளைப் பொன்தகட்டால் மூடி, தாழ்ப்பாள்களின் இடங்களாகிய அவைகளின் வளையங்களைப் பொன்னினால் பண்ணி, தாழ்ப்பாள்களைப் பொன் தகட்டால் மூடக்கடவாய்.',	2,	26,	29),
(2266,	'And thou shalt rear up the tabernacle according to the fashion thereof which was shewed thee in the mount.',	'இவ்விதமாக மலையின்மேல் உனக்குக் காண்பிக்கப்பட்ட மாதிரியின்படியே வாசஸ்தலத்தை நிறுத்துவாயாக.',	2,	26,	30),
(2267,	'And thou shalt make a vail of blue, and purple, and scarlet, and fine twined linen of cunning work: with cherubims shall it be made:',	'இளநீலநூலும் இரத்தாம்பரநூலும் சிவப்புநூலும் திரித்த மெல்லிய பஞ்சுநூலுமான இவற்றால் ஒரு திரைச்சீலையை உண்டுபண்ணக்கடவாய்; அதிலே விசித்திரவேலையால் செய்யப்பட்ட கேருபீன்கள் வைக்கப்படவேண்டும்.',	2,	26,	31),
(2268,	'And thou shalt hang it upon four pillars of shittim wood overlaid with gold: their hooks shall be of gold, upon the four sockets of silver.',	'சீத்திம் மரத்தினால் செய்து, பொன் தகட்டால் மூடப்பட்ட நாலு தூண்களிலே அதைத் தொங்கவிடு; அந்தத் தூண்கள் நாலு வெள்ளிப் பாதங்கள்மேல் நிற்கவும், அவைகளின் கொக்கிகள் பொன்னினால் செய்யப்படவும் வேண்டும்.',	2,	26,	32),
(2269,	'And thou shalt hang up the vail under the taches, that thou mayest bring in thither within the vail the ark of the testimony: and the vail shall divide unto you between the holy place and the most holy.',	'கொக்கிகளின்கீழே அந்தத் திரைச்சீலையைத் தொங்கவிட்டு, சாட்சிப்பெட்டியை அங்கே திரைக்குள்ளாக வைக்கக்கடவாய்; அந்தத் திரைச்சீலை பரிசுத்த ஸ்தலத்திற்கும் மகா பரிசுத்த ஸ்தலத்திற்கும் பிரிவை உண்டாக்கும்.',	2,	26,	33),
(2270,	'And thou shalt put the mercy seat upon the ark of the testimony in the most holy place.',	'மகா பரிசுத்த ஸ்தலத்திலே சாட்சிப்பெட்டியின்மீதில் கிருபாசனத்தை வைப்பாயாக;',	2,	26,	34),
(2271,	'And thou shalt set the table without the vail, and the candlestick over against the table on the side of the tabernacle toward the south: and thou shalt put the table on the north side.',	'திரைக்குப் புறம்பாக மேஜையையும், மேஜைக்கு எதிரே வாசஸ்தலத்தின் தென்புறமாகக் குத்துவிளக்கையும் வைத்து, மேஜையை வடபுறமாக வைப்பாயாக.',	2,	26,	35),
(2272,	'And thou shalt make an hanging for the door of the tent, of blue, and purple, and scarlet, and fine twined linen, wrought with needlework.',	'இளநீலநூலும் இரத்தாம்பரநூலும் சிவப்புநூலும் திரித்த மெல்லிய பஞ்சுநூலுமாகிய இவற்றால் சித்திரத் தையல் வேலையான ஒரு தொங்குதிரையும் கூடாரத்தின் வாசலுக்கு உண்டாக்கி,',	2,	26,	36),
(2273,	'And thou shalt make for the hanging five pillars of shittim wood, and overlay them with gold, and their hooks shall be of gold: and thou shalt cast five sockets of brass for them.',	'அந்தத் தொங்குதிரைக்குச் சீத்திம் மரத்தால் ஐந்து தூண்களைச் செய்து, அவைகளைப் பொன்தகட்டால் மூடி, அவைகளுக்குப் பொன் கொக்கிகளை உண்டாக்கி, அவைகளுக்கு ஐந்து வெண்கலப்பாதங்களை வார்ப்பிக்கக்கடவாய்.  ',	2,	26,	37),
(2274,	'And thou shalt make an altar of shittim wood, five cubits long, and five cubits broad; the altar shall be foursquare: and the height thereof shall be three cubits.',	'ஐந்து முழ நீளமும் ஐந்து முழ அகலமுமாக சீத்திம் மரத்தால் பலிபீடத்தையும் உண்டுபண்ணுவாயாக; அது சதுரமும் மூன்று முழ உயரமுமாயிருப்பதாக.',	2,	27,	1),
(2275,	'And thou shalt make the horns of it upon the four corners thereof: his horns shall be of the same: and thou shalt overlay it with brass.',	'அதின் நாலு மூலைகளிலும் நாலு கொம்புகளை உண்டாக்குவாயாக; அதின் கொம்புகள் அதனோடே ஏகமாய் இருக்கவேண்டும்; அதை வெண்கலத் தகட்டால் மூடவேண்டும்.',	2,	27,	2),
(2276,	'And thou shalt make his pans to receive his ashes, and his shovels, and his basons, and his fleshhooks, and his firepans: all the vessels thereof thou shalt make of brass.',	'அதின் சாம்பலை எடுக்கத்தக்க சட்டிகளையும் கரண்டிகளையும் கிண்ணிகளையும் முள்துறடுகளையும் நெருப்புச்சட்டிகளையும் உண்டாக்குவாயாக; அதின் பணிமுட்டுகளையெல்லாம் வெண்கலத்தால் பண்ணுவாயாக.',	2,	27,	3),
(2277,	'And thou shalt make for it a grate of network of brass; and upon the net shalt thou make four brasen rings in the four corners thereof.',	'வலைப்பின்னல்போன்ற ஒரு வெண்கலச் சல்லடையைப் பண்ணி, அந்தச் சல்லடையின் நாலு மூலைகளிலும் நாலு வெண்கல வளையங்களை உண்டாக்கி,',	2,	27,	4),
(2278,	'And thou shalt put it under the compass of the altar beneath, that the net may be even to the midst of the altar.',	'அந்தச் சல்லடை பலிபீடத்தின் பாதியுயரத்தில் இருக்கும்படி அதைத் தாழப்பலிபீடத்தின் சுற்றடைப்புக்குக் கீழாக வைப்பாயாக.',	2,	27,	5),
(2279,	'And thou shalt make staves for the altar, staves of shittim wood, and overlay them with brass.',	'பலிபீடத்துக்குச் சீத்திம் மரத்தால் தண்டுகளையும் பண்ணி, அவைகளை வெண்கலத்தகட்டால் மூடுவாயாக.',	2,	27,	6),
(2280,	'And the staves shall be put into the rings, and the staves shall be upon the two sides of the altar, to bear it.',	'பலிபீடத்தைச் சுமக்கத்தக்கதாக அந்தத் தண்டுகள் அதின் இரண்டு பக்கங்களிலும் வளையங்களிலே பாய்ச்சப்பட்டிருக்கவேண்டும்.',	2,	27,	7),
(2281,	'Hollow with boards shalt thou make it: as it was shewed thee in the mount, so shall they make it.',	'அதை உள்வெளிவிட்டுப் பலகைகளினாலே பண்ணவேண்டும்; மலையில் உனக்குக் காண்பிக்கப்பட்டபடியே அதைப்பண்ணக்கடவர்கள்.',	2,	27,	8),
(2282,	'And thou shalt make the court of the tabernacle: for the south side southward there shall be hangings for the court of fine twined linen of an hundred cubits long for one side:',	'வாசஸ்தலத்துக்குப் பிராகாரத்தையும் உண்டுபண்ணுவாயாக; தெற்கே தென்திசைக்கு எதிரான பிராகாரத்துக்குத் திரித்த மெல்லிய பஞ்சுநூலால் செய்யப்பட்ட நூறுமுழ நீளமான தொங்குதிரைகள் இருக்கவேண்டும்.',	2,	27,	9),
(2283,	'And the twenty pillars thereof and their twenty sockets shall be of brass; the hooks of the pillars and their fillets shall be of silver.',	'அவைகளுக்கு வெண்கலத்தினாலே இருபது தூண்களும், இருபது பாதங்களும் இருக்கவேண்டும்; தூண்களின் கொக்கிகளும் அவைகளின் பூண்களும் வெள்ளியினால் செய்யப்படவேண்டும்.',	2,	27,	10),
(2284,	'And likewise for the north side in length there shall be hangings of an hundred cubits long, and his twenty pillars and their twenty sockets of brass; the hooks of the pillars and their fillets of silver.',	'அப்படியே வடபக்கத்தின் நீளத்திற்கும் நூறுமுழ நீளமான தொங்குதிரைகள் இருக்கவேண்டும்; அவைகளுக்கு இருபது தூண்களும், அவைகளுக்கு இருபது பாதங்களும் வெண்கலமாயிருக்கவேண்டும்; தூண்களின் கொக்கிகளும் பூண்களும் வெள்ளியினால் செய்யப்படவேண்டும்.',	2,	27,	11),
(2285,	'And for the breadth of the court on the west side shall be hangings of fifty cubits: their pillars ten, and their sockets ten.',	'பிராகாரத்தின் மேற்பக்கமான அகலத்திற்கு ஐம்பது முழ நீளமான தொங்குதிரைகள் இருக்கவேண்டும்; அவைகளுக்குப் பத்துத் தூண்களும், அவைகளுக்குப் பத்துப் பாதங்களும் இருக்கவேண்டும்.',	2,	27,	12),
(2286,	'And the breadth of the court on the east side eastward shall be fifty cubits.',	'சூரியன் உதிக்கிற திசையாகிய கீழ்ப்பக்கத்தின் பிராகாரம் ஐம்பது முழ அகலமாயிருக்கவேண்டும்.',	2,	27,	13),
(2287,	'The hangings of one side of the gate shall be fifteen cubits: their pillars three, and their sockets three.',	'அங்கே ஒரு புறத்திற்குப் பதினைந்து முழ நீளமான தொங்குதிரைகளும், அவைகளுக்கு மூன்று தூண்களும், அவைகளுக்கு மூன்று பாதங்களும் இருக்கவேண்டும்.',	2,	27,	14),
(2288,	'And on the other side shall be hangings fifteen cubits: their pillars three, and their sockets three.',	'மறுபுறத்துக்குப் பதினைந்து முழ நீளமான தொங்குதிரைகளும், அவைகளுக்கு மூன்று தூண்களும், அவைகளுக்கு மூன்று பாதங்களும் இருக்கவேண்டும்.',	2,	27,	15),
(2289,	'And for the gate of the court shall be an hanging of twenty cubits, of blue, and purple, and scarlet, and fine twined linen, wrought with needlework: and their pillars shall be four, and their sockets four.',	'பிராகாரத்தின் வாசலுக்கு இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் சித்திரத் தையல்வேலையாய்ச் செய்யப்பட்ட இருபதுமுழ நீளமான ஒரு தொங்குதிரையும் அதற்கு நாலு தூண்களும், அவைகளுக்கு நாலு பாதங்களும் இருக்கவேண்டும்.',	2,	27,	16),
(2290,	'All the pillars round about the court shall be filleted with silver; their hooks shall be of silver, and their sockets of brass.',	'சுற்றுப் பிராகாரத்தின் தூண்களெல்லாம் வெள்ளியினால் பூண் கட்டப்பட்டிருக்கவேண்டும்; அவைகளின் கொக்கிகள் வெள்ளியினாலும் அவைகளின் பாதங்கள் வெண்கலத்தினாலும் செய்யப்பட்டிருக்கவேண்டும்.',	2,	27,	17),
(2291,	'The length of the court shall be an hundred cubits, and the breadth fifty every where, and the height five cubits of fine twined linen, and their sockets of brass.',	'பிராகாரத்தின் நீளம் நூறுமுழமும், இருபுறத்து அகலம் ஐம்பது ஐம்பது முழமும், உயரம் ஐந்து முழமுமாயிருப்பதாக; அதின் தொங்கல்கள் திரித்த மெல்லிய பஞ்சுநூலினால் செய்யப்பட்டு, அதின் தூண்களின் பாதங்கள் வெண்கலமாயிருக்கவேண்டும்.',	2,	27,	18),
(2292,	'All the vessels of the tabernacle in all the service thereof, and all the pins thereof, and all the pins of the court, shall be of brass.',	'வாசஸ்தலத்துக்கடுத்த சகல பணிவிடைக்குத் தேவையான எல்லாப் பணிமுட்டுகளும், அதின் எல்லா முளைகளும், பிராகாரத்தின் எல்லா முளைகளும் வெண்கலமாயிருக்கவேண்டும்.',	2,	27,	19),
(2293,	'And thou shalt command the children of Israel, that they bring thee pure oil olive beaten for the light, to cause the lamp to burn always.',	'குத்துவிளக்கு எப்பொழுதும் எரிந்துகொண்டிருக்கும்படி இடித்துப் பிழிந்த தெளிவான ஒலிவ எண்ணெயை உன்னிடத்தில் கொண்டுவரும்படி இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடுவாயாக.',	2,	27,	20),
(2294,	'In the tabernacle of the congregation without the vail, which is before the testimony, Aaron and his sons shall order it from evening to morning before the LORD: it shall be a statute for ever unto their generations on the behalf of the children of Israel.',	'ஆசரிப்புக் கூடாரத்தில் சாட்சி சந்நிதிக்கு முன்னிருக்கும் திரைச்சீலைக்கு வெளிப்புறமாக ஆரோனும் அவன் குமாரரும் சாயங்காலம் தொடங்கி விடியற்காலம்மட்டும் கர்த்தருடைய சந்நிதானத்தில் அந்த விளக்கை எரியவைக்கக்கடவர்கள்; இது இஸ்ரவேல் புத்திரருக்கு தலைமுறை தலைமுறையாக நித்திய கட்டளையாயிருக்கக்கடவது.  ',	2,	27,	21),
(2295,	'And take thou unto thee Aaron thy brother, and his sons with him, from among the children of Israel, that he may minister unto me in the priest\'s office, even Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron\'s sons.',	'உன் சகோதரனாகிய ஆரோன் எனக்கு ஆசாரிய ஊழியம் செய்யும்படிக்கு, நீ ஆரோனையும் அவனோடேகூட அவன் குமாரராகிய நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்னும் ஆரோனின் குமாரரையும் இஸ்ரவேல் புத்திரரிலிருந்து பிரித்து, உன்னிடத்தில் சேர்த்துக்கொள்வாயாக.',	2,	28,	1),
(2296,	'And thou shalt make holy garments for Aaron thy brother for glory and for beauty.',	'உன் சகோதரனாகிய ஆரோனுக்கு, மகிமையும் அலங்காரமுமாய் இருக்கும் பொருட்டு, பரிசுத்த வஸ்திரங்களை உண்டுபண்ணுவாயாக.',	2,	28,	2),
(2297,	'And thou shalt speak unto all that are wise hearted, whom I have filled with the spirit of wisdom, that they may make Aaron\'s garments to consecrate him, that he may minister unto me in the priest\'s office.',	'ஆரோன் எனக்கு ஆசாரிய ஊழியம் செய்யத்தக்கதாக அவனைப் பரிசுத்தப்படுத்தும்படி அவனுக்கு வஸ்திரங்களை உண்டாக்கும்பொருட்டு, நான் ஞானத்தின் ஆவியால் நிரப்பின விவேகமான இருதயமுள்ள யாவரோடும் நீ சொல்லுவாயாக.',	2,	28,	3),
(2298,	'And these are the garments which they shall make; a breastplate, and an ephod, and a robe, and a broidered coat, a mitre, and a girdle: and they shall make holy garments for Aaron thy brother, and his sons, that he may minister unto me in the priest\'s office.',	'அவர்கள் உண்டாக்கவேண்டிய வஸ்திரங்களாவன; மார்ப்பதக்கமும், ஏபோத்தும், அங்கியும், விசித்திரமான உள்சட்டையும், பாகையும், இடைக்கச்சையுமே. உன் சகோதரனாகிய ஆரோன் எனக்கு ஆசாரிய ஊழியம் செய்யும்படி, அவனுக்கும் அவன் குமாரருக்கும் பரிசுத்த வஸ்திரங்களை உண்டுபண்ணவேண்டும்.',	2,	28,	4),
(2299,	'And they shall take gold, and blue, and purple, and scarlet, and fine linen.',	'அவர்கள் பொன்னும் இளநீலநூலும் இரத்தாம்பரநூலும் சிவப்புநூலும் மெல்லிய பஞ்சுநூலும் சேகரிப்பார்களாக.',	2,	28,	5),
(2300,	'And they shall make the ephod of gold, of blue, and of purple, of scarlet, and fine twined linen, with cunning work.',	'ஏபோத்தைப் பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் விசித்திரவேலையாய்ச் செய்யக்கடவர்கள்.',	2,	28,	6),
(2301,	'It shall have the two shoulderpieces thereof joined at the two edges thereof; and so it shall be joined together.',	'அது ஒன்றாக இணைக்கப்படும் பொருட்டு, இரண்டு தோள்த்துண்டுகளின்மேலும், அதின் இரண்டு முனைகளும் சேர்க்கப்படவேண்டும்.',	2,	28,	7),
(2302,	'And the curious girdle of the ephod, which is upon it, shall be of the same, according to the work thereof; even of gold, of blue, and purple, and scarlet, and fine twined linen.',	'அந்த ஏபோத்தின்மேல் இருக்கவேண்டிய விசித்திரமான கச்சை அந்த வேலைக்கு ஒப்பாகவே, பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் பண்ணப்பட்டு, அதனோடே ஏகமாயிருக்கவேண்டும்.',	2,	28,	8),
(2303,	'And thou shalt take two onyx stones, and grave on them the names of the children of Israel:',	'பின்னும் நீ இரண்டு கோமேதகக்கற்களை எடுத்து, இஸ்ரவேல் புத்திரரின் நாமங்களை அவைகளில் வெட்டுவாயாக.',	2,	28,	9),
(2304,	'Six of their names on one stone, and the other six names of the rest on the other stone, according to their birth.',	'அவர்கள் பிறந்த வரிசையின்படியே, அவர்களுடைய நாமங்களில் ஆறு நாமங்கள் ஒரு கல்லிலும், மற்ற ஆறு நாமங்கள் மறு கல்லிலும் இருக்கவேண்டும்.',	2,	28,	10),
(2305,	'With the work of an engraver in stone, like the engravings of a signet, shalt thou engrave the two stones with the names of the children of Israel: thou shalt make them to be set in ouches of gold.',	'இரத்தினங்களில் முத்திரை வெட்டுகிறவர்கள் செய்யும் வேலைக்கு ஒப்பாக அந்த இரண்டு கற்களிலும் இஸ்ரவேல் புத்திரரின் நாமங்களை வெட்டி, அவைகளைப் பொன் குவளைகளில் பதிப்பாயாக.',	2,	28,	11),
(2306,	'And thou shalt put the two stones upon the shoulders of the ephod for stones of memorial unto the children of Israel: and Aaron shall bear their names before the LORD upon his two shoulders for a memorial.',	'ஆரோன் கர்த்தருக்கு முன்பாகத் தன் இரண்டு தோள்களின்மேலும் இஸ்ரவேல் புத்திரரின் நாமங்களை ஞாபகக்குறியாகச் சுமந்துவர, அந்த இரண்டு கற்களையும் ஏபோத்து தோள்களின்மேல் அவர்களை நினைக்கும்படியான கற்களாக வைக்கக்கடவாய்.',	2,	28,	12),
(2307,	'And thou shalt make ouches of gold;',	'பொன்னினால் வளையங்களைப்பண்ணி,',	2,	28,	13),
(2308,	'And two chains of pure gold at the ends; of wreathen work shalt thou make them, and fasten the wreathen chains to the ouches.',	'சரியான அளவுக்குப் பின்னல்வேலையான இரண்டு சங்கிலிகளையும், பசும்பொன்னினால் உண்டாக்கி, அந்தச் சங்கிலிகளை அந்த வளையங்களில் பூட்டுவாயாக.',	2,	28,	14),
(2309,	'And thou shalt make the breastplate of judgment with cunning work; after the work of the ephod thou shalt make it; of gold, of blue, and of purple, and of scarlet, and of fine twined linen, shalt thou make it.',	'நியாயவிதி மார்ப்பதக்கத்தையும் விசித்திரவேலையாய்ச் செய்வாயாக; அதை ஏபோத்து வேலைக்கு ஒப்பாகப் பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்வாயாக.',	2,	28,	15),
(2310,	'Foursquare it shall be being doubled; a span shall be the length thereof, and a span shall be the breadth thereof.',	'அது சதுரமும் இரட்டையும், ஒரு சாண் நீளமும் ஒரு சாண் அகலமுமாய் இருக்கவேண்டும்.',	2,	28,	16),
(2311,	'And thou shalt set in it settings of stones, even four rows of stones: the first row shall be a sardius, a topaz, and a carbuncle: this shall be the first row.',	'அதிலே நாலு பத்தி இரத்தினக்கற்களை நிறையப் பதிப்பாயாக; முதலாம் பத்தி பத்மராகமும் புஷ்பராகமும் மாணிக்கமும்,',	2,	28,	17),
(2312,	'And the second row shall be an emerald, a sapphire, and a diamond.',	'இரண்டாம் பத்தி மரகதமும் இந்திரநீலமும் வச்சிரமும்,',	2,	28,	18),
(2313,	'And the third row a ligure, an agate, and an amethyst.',	'மூன்றாம் பத்தி கெம்பும் வைடூரியமும் சுகந்தியும்,',	2,	28,	19),
(2314,	'And the fourth row a beryl, and an onyx, and a jasper: they shall be set in gold in their inclosings.',	'நாலாம் பத்தி படிகப்பச்சையும் கோமேதகமும் யஸ்பியுமாய் இருப்பதாக; இவைகள் அந்தந்தப் பத்தியில் பொன்னினாலே பதித்திருக்கவேண்டும்.',	2,	28,	20),
(2315,	'And the stones shall be with the names of the children of Israel, twelve, according to their names, like the engravings of a signet; every one with his name shall they be according to the twelve tribes.',	'இந்தக் கற்கள் இஸ்ரவேல் புத்திரருடைய நாமங்களின்படியே பன்னிரண்டும், அவர்களுடைய நாமங்கள் அவைகளில் வெட்டப்பட்டவைகளுமாய் இருக்கவேண்டும்; பன்னிரண்டு கோத்திரங்களில் ஒவ்வொன்றினுடைய நாமம் ஒவ்வொன்றிலே முத்திரைவெட்டாய் வெட்டியிருக்கவேண்டும்.',	2,	28,	21),
(2316,	'And thou shalt make upon the breastplate chains at the ends of wreathen work of pure gold.',	'மார்ப்பதக்கத்திற்கு அதின் பக்கங்களிலே பின்னல்வேலையான பசும்பொன் சங்கிலிகளையும் பண்ணி,',	2,	28,	22),
(2317,	'And thou shalt make upon the breastplate two rings of gold, and shalt put the two rings on the two ends of the breastplate.',	'அந்த மார்ப்பதக்கத்திற்கு இரண்டு பொன் வளையங்களையும் பண்ணி, அந்த இரண்டு வளையங்களையும் மார்ப்பதக்கத்தின் இரண்டு பக்கங்களிலே வைத்து,',	2,	28,	23),
(2318,	'And thou shalt put the two wreathen chains of gold in the two rings which are on the ends of the breastplate.',	'பொன்னினால் செய்த அந்த இரண்டு பின்னல் வேலையான சங்கிலிகளையும் மார்ப்பதக்கத்தின் பக்கங்களில் இருக்கிற இரண்டு வளையங்களில் மாட்டி,',	2,	28,	24),
(2319,	'And the other two ends of the two wreathen chains thou shalt fasten in the two ouches, and put them on the shoulderpieces of the ephod before it.',	'அவ்விரண்டு பின்னல் வேலையான சங்கிலிகளின் இரண்டு நுனிகளை ஏபோத்துத் தோள்த்துண்டின்மேல் அதின் முன்புறத்தில் இருக்கிற இரண்டு வளையங்களில் மாட்டுவாயாக.',	2,	28,	25),
(2320,	'And thou shalt make two rings of gold, and thou shalt put them upon the two ends of the breastplate in the border thereof, which is in the side of the ephod inward.',	'நீ இரண்டு பொன்வளையங்களைப் பண்ணி, அவைகளை ஏபோத்தின் கீழ்ப்புறத்திற்கு எதிரான மார்ப்பதக்கத்தினுடைய மற்ற இரண்டு பக்கங்களிலும் அதினுடைய ஓரத்திற்குள்ளாக வைத்து,',	2,	28,	26),
(2321,	'And two other rings of gold thou shalt make, and shalt put them on the two sides of the ephod underneath, toward the forepart thereof, over against the other coupling thereof, above the curious girdle of the ephod.',	'வேறே இரண்டு பொன்வளையங்களைப் பண்ணி, அவைகளை ஏபோத்தின் முன்புறத்து இரண்டு கீழ்ப்பக்கங்களில் அதின் இணைப்புக்கு எதிராகவும், ஏபோத்தின் விசித்திரமான கச்சைக்கு மேலாகவும் வைத்து,',	2,	28,	27),
(2322,	'And they shall bind the breastplate by the rings thereof unto the rings of the ephod with a lace of blue, that it may be above the curious girdle of the ephod, and that the breastplate be not loosed from the ephod.',	'மார்ப்பதக்கம் ஏபோத்தின் விசித்திரமான கச்சைக்கு மேலாக இருக்கும்படிக்கும், அது ஏபோத்திலிருந்து நீங்காதபடிக்கும், அதை அதின் வளையங்களால் ஏபோத்து வளையங்களோடே இளநீல நாடாவினால் கட்டவேண்டும்.',	2,	28,	28),
(2323,	'And Aaron shall bear the names of the children of Israel in the breastplate of judgment upon his heart, when he goeth in unto the holy place, for a memorial before the LORD continually.',	'ஆரோன் பரிசுத்த ஸ்தலத்திற்குள் பிரவேசிக்கும்போது, இஸ்ரவேல் புத்திரரின் நாமங்களைத் தன் இருதயத்தின்மேலிருக்கும் நியாயவிதி மார்ப்பதக்கத்திலே கர்த்தருடைய சந்நிதானத்தில் ஞாபகக்குறியாக எப்பொழுதும் தரித்துக்கொள்ளக்கடவன்.',	2,	28,	29),
(2324,	'And thou shalt put in the breastplate of judgment the Urim and the Thummim; and they shall be upon Aaron\'s heart, when he goeth in before the LORD: and Aaron shall bear the judgment of the children of Israel upon his heart before the LORD continually.',	'நியாயவிதி மார்ப்பதக்கத்திலே ஊரீம் தும்மீம் என்பவைகளை வைப்பாயாக; ஆரோன் கர்த்தருடைய சந்நிதானத்தில் பிரவேசிக்கும்போது, அவைகள் அவன் இருதயத்தின்மேல் இருக்கவேண்டும்; ஆரோன் தன் இருதயத்தின்மேல் இஸ்ரவேல் புத்திரருடைய நியாயவிதியைக் கர்த்தருடைய சந்நிதானத்தில் எப்பொழுதும் தரித்துக்கொள்ளவேண்டும்.',	2,	28,	30),
(2325,	'And thou shalt make the robe of the ephod all of blue.',	'ஏபோத்தின் கீழ் அங்கியை முழுவதும் இளநீலநூலால் உண்டாக்கக்கடவாய்.',	2,	28,	31),
(2326,	'And there shall be an hole in the top of it, in the midst thereof: it shall have a binding of woven work round about the hole of it, as it were the hole of an habergeon, that it be not rent.',	'தலை நுழைகிற அதின் துவாரம் அதின் நடுவில் இருக்கவும், அதின் துவாரத்துக்கு நெய்யப்பட்ட வேலையான ஒரு நாடா சுற்றிலும் இருக்கவும் வேண்டும்; அது கிழியாதபடிக்கு மார்க்கவசத்தின் துவாரத்துக்கு ஒத்ததாக இருக்கவேண்டும்.',	2,	28,	32),
(2327,	'And beneath upon the hem of it thou shalt make pomegranates of blue, and of purple, and of scarlet, round about the hem thereof; and bells of gold between them round about:',	'அதின் கீழோரங்களில் இளநீலநூல் இரத்தாம்பரநூல் சிவப்புநூல் வேலையால் செய்யப்பட்ட மாதளம்பழங்களையும், அவைகளுக்கு இடையிடையே சுற்றிலும் பொன்மணிகளையும் அதின் ஓரங்களில் சுற்றிலும் தொங்கும்படி பண்ணிவைக்கவேண்டும்.',	2,	28,	33),
(2328,	'A golden bell and a pomegranate, a golden bell and a pomegranate, upon the hem of the robe round about.',	'அங்கியின் ஓரங்களில் சுற்றிலும் ஒரு பொன்மணியும் ஒரு மாதளம்பழமும், ஒரு பொன்மணியும் ஒரு மாதளம்பழமுமாய்த் தொங்குவதாக.',	2,	28,	34),
(2329,	'And it shall be upon Aaron to minister: and his sound shall be heard when he goeth in unto the holy place before the LORD, and when he cometh out, that he die not.',	'ஆரோன் ஆராதனை செய்யக் கர்த்தருடைய சந்நிதியில் பரிசுத்த ஸ்தலத்துக்குள் பிரவேசிக்கும்போதும், வெளியே வரும்போதும், அவன் சாகாதபடிக்கு, அதின் சத்தம் கேட்கப்படும்படி அதைத் தரித்துக்கொள்ளவேண்டும்.',	2,	28,	35),
(2330,	'And thou shalt make a plate of pure gold, and grave upon it, like the engravings of a signet, HOLINESS TO THE LORD.',	'பசும்பொன்னினால் ஒரு பட்டத்தைப்பண்ணி, கர்த்தருக்குப் பரிசுத்தம் என்று அதிலே முத்திரை வெட்டாக வெட்டி,',	2,	28,	36),
(2331,	'And thou shalt put it on a blue lace, that it may be upon the mitre; upon the forefront of the mitre it shall be.',	'அது பாகையிலிருக்கும்படி அதை இளநீல நாடாவினால் பாகையின் முகப்பிலே கட்டுவாயாக.',	2,	28,	37),
(2332,	'And it shall be upon Aaron\'s forehead, that Aaron may bear the iniquity of the holy things, which the children of Israel shall hallow in all their holy gifts; and it shall be always upon his forehead, that they may be accepted before the LORD.',	'இஸ்ரவேல் புத்திரர் தங்கள் பரிசுத்த காணிக்கைகளாகப் படைக்கும் பரிசுத்தமானவைகளின் தோஷத்தை ஆரோன் சுமக்கும்படி, அது ஆரோனுடைய நெற்றியின்மேல் இருப்பதாக; கர்த்தருடைய சந்நிதியில் அவர்கள் அங்கிகரிக்கப்படும்படி, அது எப்பொழுதும் அவன் நெற்றியின்மேல் இருக்கவேண்டும்.',	2,	28,	38),
(2333,	'And thou shalt embroider the coat of fine linen, and thou shalt make the mitre of fine linen, and thou shalt make the girdle of needlework.',	'மெல்லிய பஞ்சுநூலால் விசித்திரமான உள்சட்டையும், மெல்லிய பஞ்சுநூலால் பாகையையும் உண்டாக்கி, இடைக்கச்சையைச் சித்திரத்தையல் வேலையாகப்பண்ணுவாயாக.',	2,	28,	39),
(2334,	'And for Aaron\'s sons thou shalt make coats, and thou shalt make for them girdles, and bonnets shalt thou make for them, for glory and for beauty.',	'ஆரோனுடைய குமாரருக்கும், மகிமையும் அலங்காரமுமாயிருக்கும் பொருட்டு, அங்கிகளையும், இடைக்கச்சைகளையும், குல்லாக்களையும் உண்டுபண்ணுவாயாக.',	2,	28,	40),
(2335,	'And thou shalt put them upon Aaron thy brother, and his sons with him; and shalt anoint them, and consecrate them, and sanctify them, that they may minister unto me in the priest\'s office.',	'உன் சகோதரனாகிய ஆரோனும் அவனோடேகூட அவன் குமாரரும் எனக்கு ஆசாரிய ஊழியம் செய்யும்படிக்கு, நீ அந்த வஸ்திரங்களை அவர்களுக்கு உடுத்தி, அவர்களை அபிஷேகஞ்செய்து, அவர்களைப் பிரதிஷ்டைபண்ணி, அவர்களைப் பரிசுத்தப்படுத்துவாயாக.',	2,	28,	41),
(2336,	'And thou shalt make them linen breeches to cover their nakedness; from the loins even unto the thighs they shall reach:',	'அவர்களுடைய நிர்வாணத்தை மூடும்படிக்கு, இடுப்புத்தொடங்கி முழங்கால்மட்டும் உடுத்த சணல்நூல் சல்லடங்களையும் உண்டுபண்ணுவாயாக.',	2,	28,	42),
(2337,	'And they shall be upon Aaron, and upon his sons, when they come in unto the tabernacle of the congregation, or when they come near unto the altar to minister in the holy place; that they bear not iniquity, and die: it shall be a statute for ever unto him and his seed after him.',	'ஆரோனும் அவன் குமாரரும் பரிசுத்த ஸ்தலத்திலே ஆராதனைசெய்ய ஆசரிப்புக் கூடாரத்திற்குள் பிரவேசிக்கும்போதும் பலிபீடத்தண்டைக்குச் சேரும்போதும், அக்கிரமம் சுமந்து அவர்கள் சாகாதபடிக்கு, அவைகளைத் தரித்திருக்கவேண்டும்; இது அவனுக்கும் அவனுக்குப் பின்வரும் சந்ததிக்கும் நித்திய கட்டளை.  ',	2,	28,	43),
(2338,	'And this is the thing that thou shalt do unto them to hallow them, to minister unto me in the priest\'s office: Take one young bullock, and two rams without blemish,',	'அவர்கள் எனக்கு ஆசாரிய ஊழியம் செய்யும்படி அவர்களைப் பரிசுத்தப்படுத்தும்பொருட்டு, நீ அவர்களுக்குச் செய்யவேண்டியதாவது: ஒரு காளையையும் பழுதற்ற இரண்டு ஆட்டுக்கடாக்களையும் தெரிந்துகொள்வாயாக.',	2,	29,	1),
(2339,	'And unleavened bread, and cakes unleavened tempered with oil, and wafers unleavened anointed with oil: of wheaten flour shalt thou make them.',	'புளிப்பில்லா அப்பத்தையும், எண்ணெயிலே பிசைந்த புளிப்பில்லா அதிரசங்களையும், எண்ணெய் பூசப்பட்ட புளிப்பில்லா அடைகளையும் கோதுமையின் மெல்லியமாவினால்பண்ணி,',	2,	29,	2),
(2340,	'And thou shalt put them into one basket, and bring them in the basket, with the bullock and the two rams.',	'அவைகளை ஒரு கூடையிலே வைத்து, கூடையோடே அவைகளையும் காளையையும் இரண்டு ஆட்டுக்கடாக்களையும் கொண்டுவந்து,',	2,	29,	3),
(2341,	'And Aaron and his sons thou shalt bring unto the door of the tabernacle of the congregation, and shalt wash them with water.',	'ஆரோனையும் அவன் குமாரரையும் ஆசரிப்புக் கூடாரத்தின் வாசல் முன்பாகச் சேரப்பண்ணி, அவர்களைத் தண்ணீரினால் கழுவி,',	2,	29,	4),
(2342,	'And thou shalt take the garments, and put upon Aaron the coat, and the robe of the ephod, and the ephod, and the breastplate, and gird him with the curious girdle of the ephod:',	'அந்த வஸ்திரங்கள எடுத்து, ஆரோனுக்கு உள்சட்டையையும், ஏபோத்தின் கீழ் அங்கியையும், ஏபோத்தையும், மார்ப்பதக்கத்தையும் தரித்து, ஏபோத்தின் விசித்திரமான கச்சையையும் அவனுக்குக் கட்டி,',	2,	29,	5),
(2343,	'And thou shalt put the mitre upon his head, and put the holy crown upon the mitre.',	'அவன் தலையிலே பாகையையும் வைத்து, பரிசுத்த கிரீடத்தைப் பாகையின்மேல் தரித்து,',	2,	29,	6),
(2344,	'Then shalt thou take the anointing oil, and pour it upon his head, and anoint him.',	'அபிஷேக தைலத்தையும் எடுத்து, அவன் தலையின்மேல் வார்த்து, அவனை அபிஷேகஞ்செய்வாயாக.',	2,	29,	7),
(2345,	'And thou shalt bring his sons, and put coats upon them.',	'பின்பு அவன் குமாரரைச் சேரப்பண்ணி, ஆசாரிய ஊழியம் அவர்களுக்கு நித்திய கட்டளையாக இருக்கும்படி, அவர்களுக்கும் அங்கிகளை உடுத்துவாயாக.',	2,	29,	8),
(2346,	'And thou shalt gird them with girdles, Aaron and his sons, and put the bonnets on them: and the priest\'s office shall be theirs for a perpetual statute: and thou shalt consecrate Aaron and his sons.',	'ஆரோனுக்கும் அவன் குமாரருக்கும் இடைக்கச்சைகளைக் கட்டி, அவன் குமாரருக்குக் குல்லாக்களையும் தரித்து, இப்படியே ஆரோனையும் அவன் குமாரரையும் பிரதிஷ்டைபண்ணுவாயாக.',	2,	29,	9),
(2347,	'And thou shalt cause a bullock to be brought before the tabernacle of the congregation: and Aaron and his sons shall put their hands upon the head of the bullock.',	'காளையை ஆசரிப்புக் கூடாரத்துக்கு முன்பாகக் கொண்டுவருவாயாக; அப்பொழுது ஆரோனும் அவன் குமாரரும் தங்கள் கைகளைக் காளையினுடைய தலையின்மேல் வைக்கக்கடவர்கள்.',	2,	29,	10),
(2348,	'And thou shalt kill the bullock before the LORD, by the door of the tabernacle of the congregation.',	'பின்பு நீ அந்தக் காளையை ஆசரிப்புக் கூடாரத்து வாசலண்டையிலே கர்த்தருடைய சந்நிதானத்தில் அடித்து,',	2,	29,	11),
(2349,	'And thou shalt take of the blood of the bullock, and put it upon the horns of the altar with thy finger, and pour all the blood beside the bottom of the altar.',	'அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, உன் விரலினால் பலிபீடத்தின் கொம்புகள்மேல் இட்டு, மற்ற இரத்தம் முழுவதையும் பலிபீடத்தின் அடியிலே ஊற்றி,',	2,	29,	12),
(2350,	'And thou shalt take all the fat that covereth the inwards, and the caul that is above the liver, and the two kidneys, and the fat that is upon them, and burn them upon the altar.',	'குடல்களை மூடிய கொழுப்பு யாவையும், கல்லீரலின்மேலுள்ள சவ்வையும், இரண்டு குண்டிக்காய்களையும், அவைகளின்மேலுள்ள கொழுப்பையும் எடுத்து, பலிபீடத்தின்மேல் தகித்துப்போட்டு,',	2,	29,	13),
(2351,	'But the flesh of the bullock, and his skin, and his dung, shalt thou burn with fire without the camp: it is a sin offering.',	'காளையின் மாம்சத்தையும் அதின் தோலையும் அதின் சாணியையும் பாளயத்துக்குப் புறம்பே அக்கினியால் சுட்டெரிக்கக்கடவாய்; இது பாவநிவாரணபலி.',	2,	29,	14),
(2352,	'Thou shalt also take one ram; and Aaron and his sons shall put their hands upon the head of the ram.',	'பின்பு அந்த ஆட்டுக்கடாக்களில் ஒன்றைக் கொண்டுவந்து நிறுத்துவாயாக; அதினுடைய தலையின்மேல் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளை வைக்கக்கடவர்கள்.',	2,	29,	15),
(2353,	'And thou shalt slay the ram, and thou shalt take his blood, and sprinkle it round about upon the altar.',	'அந்தக் கடாவை அடித்து, அதின் இரத்தத்தைப் பிடித்து, பலிபீடத்தின் மேல் சுற்றிலும் தெளித்து,',	2,	29,	16),
(2354,	'And thou shalt cut the ram in pieces, and wash the inwards of him, and his legs, and put them unto his pieces, and unto his head.',	'ஆட்டுக்கடாவைச் சந்துசந்தாகத்துண்டித்து, அதின் குடல்களையும் அதின் தொடைகளையும் கழுவி, அவைகளை அந்தத் துண்டங்களின்மேலும் அதின் தலையின்மேலும் வைத்து,',	2,	29,	17),
(2355,	'And thou shalt burn the whole ram upon the altar: it is a burnt offering unto the LORD: it is a sweet savour, an offering made by fire unto the LORD.',	'ஆட்டுக்கடா முழுவதையும் பலிபீடத்தின்மேல் தகித்துவிடுவாயாக; இது கர்த்தருக்குச் செலுத்தும் சர்வாங்கதகனபலி; இது சுகந்த வாசனையும் கர்த்தருக்குச் செலுத்தும் தகனபலியுமாய் இருக்கும்.',	2,	29,	18),
(2356,	'And thou shalt take the other ram; and Aaron and his sons shall put their hands upon the head of the ram.',	'பின்பு மற்ற ஆட்டுக்கடாவையும் கொண்டுவந்து நிறுத்துவாயாக; அதினுடைய தலையின்மேல் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளை வைக்கக்கடவர்கள்.',	2,	29,	19),
(2357,	'Then shalt thou kill the ram, and take of his blood, and put it upon the tip of the right ear of Aaron, and upon the tip of the right ear of his sons, and upon the thumb of their right hand, and upon the great toe of their right foot, and sprinkle the blood upon the altar round about.',	'அப்பொழுது அந்தக் கடாவை அடித்து, அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, ஆரோனின் வலதுகாது மடலிலும், அவன் குமாரரின் வலதுகாது மடலிலும், அவர்கள் வலதுகையின் பெருவிரலிலும், அவர்கள் வலதுகாலின் பெருவிரலிலும் இட்டு, மற்ற இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்து,',	2,	29,	20),
(2358,	'And thou shalt take of the blood that is upon the altar, and of the anointing oil, and sprinkle it upon Aaron, and upon his garments, and upon his sons, and upon the garments of his sons with him: and he shall be hallowed, and his garments, and his sons, and his sons\' garments with him.',	'பலிபீடத்தின்மேலிருக்கும் இரத்தத்திலும் அபிஷேகதைலத்திலும் கொஞ்சம் எடுத்து, ஆரோனும் அவன் வஸ்திரங்களும் அவனுடைய குமாரரும் அவர்களுடைய வஸ்திரங்களும் பரிசுத்தமாக்கப் படும்படி, அவன்மேலும் அவன் வஸ்திரங்கள்மேலும் அவனுடைய குமாரர்மேலும் அவர்களுடைய வஸ்திரங்கள்மேலும் தெளிப்பாயாக.',	2,	29,	21),
(2359,	'Also thou shalt take of the ram the fat and the rump, and the fat that covereth the inwards, and the caul above the liver, and the two kidneys, and the fat that is upon them, and the right shoulder; for it is a ram of consecration:',	'அந்த ஆட்டுக்கடா பிரதிஷ்டையின் ஆட்டுக்கடாவானதால், அதிலுள்ள கொழுப்பையும் வாலையும் குடல்களை மூடிய கொழுப்பையும் கல்லீரலின்மேலுள்ள சவ்வையும் இரண்டு குண்டிக்காய்களையும் அவைகளின்மேலுள்ள கொழுப்பையும் வலதுபக்கத்து முன்னந்தொடையையும்,',	2,	29,	22),
(2360,	'And one loaf of bread, and one cake of oiled bread, and one wafer out of the basket of the unleavened bread that is before the LORD:',	'கர்த்தருடைய சந்நிதானத்தில் வைத்திருக்கிற புளிப்பில்லா அப்பங்களுள்ள கூடையில் ஒரு அப்பத்தையும் எண்ணெயிட்ட அப்பமாகிய ஒரு அதிரசத்தையும் ஒரு அடையையும் எடுத்து,',	2,	29,	23),
(2361,	'And thou shalt put all in the hands of Aaron, and in the hands of his sons; and shalt wave them for a wave offering before the LORD.',	'அவைகள் எல்லாவற்றையும் ஆரோனின் உள்ளங்கைகளிலும் அவன் குமாரரின் உள்ளங்கைகளிலும் வைத்து, அவைகளைக் கர்த்தருடைய சந்நிதானத்தில் அசைவாட்டப்படும் காணிக்கையாக அசைவாட்டி,',	2,	29,	24),
(2362,	'And thou shalt receive them of their hands, and burn them upon the altar for a burnt offering, for a sweet savour before the LORD: it is an offering made by fire unto the LORD.',	'பின்பு அவைகளை அவர்கள் கைகளிலிருந்து எடுத்து, பலிபீடத்தின்மேல் சர்வாங்கதகனபலியோடு வைத்து, கர்த்தருடைய சந்நிதானத்தில் சுகந்த வாசனையாகத் தகிக்கக்கடவாய்; இது கர்த்தருக்குச் செலுத்தப்படும் தகனபலி.',	2,	29,	25),
(2363,	'And thou shalt take the breast of the ram of Aaron\'s consecration, and wave it for a wave offering before the LORD: and it shall be thy part.',	'ஆரோனுடைய பிரதிஷ்டையின் ஆட்டுக்கடாவிலே மார்க்கண்டத்தை எடுத்து, அதைக் கர்த்தருடைய சந்நிதானத்தில் அசைவாட்டப்படும் காணிக்கையாக அசைவாட்டக்கடவாய்; அது உன் பங்காயிருக்கும்.',	2,	29,	26),
(2364,	'And thou shalt sanctify the breast of the wave offering, and the shoulder of the heave offering, which is waved, and which is heaved up, of the ram of the consecration, even of that which is for Aaron, and of that which is for his sons:',	'மேலும், ஆரோனுடைய பிரதிஷ்டைக்கும் அவன் குமாரருடைய பிரதிஷ்டைக்கும் நியமித்த ஆட்டுக்கடாவில் அசைவாட்டப்படுகிற மார்க்கண்டத்தையும் ஏறெடுத்துப் படைக்கப்படுகிற முன்னந்தொடையையும் பரிசுத்தப்படுத்துவாயாக.',	2,	29,	27),
(2365,	'And it shall be Aaron\'s and his sons\' by a statute for ever from the children of Israel: for it is an heave offering: and it shall be an heave offering from the children of Israel of the sacrifice of their peace offerings, even their heave offering unto the LORD.',	'அது ஏறெடுத்துப் படைக்கிற படைப்பானதினால், இஸ்ரவேல் புத்திரர் பலியிடுகிறவைகளில் அவைகளே நித்திய கட்டளையாக ஆரோனையும் அவன் குமாரரையும் சேர்வதாக; இஸ்ரவேல் புத்திரர் கர்த்தருடைய சந்நிதானத்தில் ஏறெடுத்துப் படைக்கிற சமாதானபலிகளில் அவைகளே ஏறெடுத்துப் படைக்கும் படைப்பாயிருக்கவேண்டும்.',	2,	29,	28),
(2366,	'And the holy garments of Aaron shall be his sons\' after him, to be anointed therein, and to be consecrated in them.',	'ஆரோனின் பரிசுத்த வஸ்திரங்கள், அவனுக்குப்பின், அவனுடைய குமாரரைச் சேரும்; அவர்கள் அவைகளை உடுத்திக்கொண்டு, அபிஷேகம்பண்ணப்பட்டுப் பிரதிஷ்டையாக்கப்படுவார்கள்.',	2,	29,	29),
(2367,	'And that son that is priest in his stead shall put them on seven days, when he cometh into the tabernacle of the congregation to minister in the holy place.',	'அவனுடைய குமாரரில் அவன் பட்டத்திற்கு வருகிற ஆசாரியன் பரிசுத்த ஸ்தலத்தில் ஆராதனை செய்வதற்கு ஆசரிப்புக் கூடாரத்தில் பிரவேசிக்கும்போது, அவைகளை ஏழுநாள்மட்டும் உடுத்திக்கொள்ளக்கடவன்.',	2,	29,	30),
(2368,	'And thou shalt take the ram of the consecration, and seethe his flesh in the holy place.',	'பிரதிஷ்டையின் ஆட்டுக்கடாவைக் கொண்டுவந்து, அதின் மாம்சத்தைப் பரிசுத்த இடத்தில் வேவிப்பாயாக.',	2,	29,	31),
(2369,	'And Aaron and his sons shall eat the flesh of the ram, and the bread that is in the basket by the door of the tabernacle of the congregation.',	'அந்த ஆட்டுக்கடாவின் மாம்சத்தையும், கூடையிலிருக்கிற அப்பத்தையும், ஆரோனும் அவன் குமாரரும் ஆசரிப்புக்கூடாரத்தின் வாசலிலே புசிக்கக்கடவர்கள்.',	2,	29,	32),
(2370,	'And they shall eat those things wherewith the atonement was made, to consecrate and to sanctify them: but a stranger shall not eat thereof, because they are holy.',	'அவர்களைப் பிரதிஷ்டைப்பண்ணிப் பரிசுத்தப்படுத்தும்பொருட்டு, அவைகளால் பாவநிவிர்த்தி செய்யப்பட்டபடியால், அவைகளை அவர்கள் புசிக்கக்கடவர்கள்; அந்நியனோ அவைகளைப் புசிக்கலாகாது; அவைகள் பரிசுத்தமானவைகள்.',	2,	29,	33),
(2371,	'And if ought of the flesh of the consecrations, or of the bread, remain unto the morning, then thou shalt burn the remainder with fire: it shall not be eaten, because it is holy.',	'பிரதிஷ்டையின் மாம்சத்திலும் அப்பத்திலும் ஏதாகிலும் விடியற்காலம் மட்டும் மீந்திருந்ததானால், அதை அக்கினியாலே சுட்டெரிப்பாயாக; அது புசிக்கப்படலாகாது, அது பரிசுத்தமானது.',	2,	29,	34),
(2372,	'And thus shalt thou do unto Aaron, and to his sons, according to all things which I have commanded thee: seven days shalt thou consecrate them.',	'இந்தப்பிரகாரம் நான் உனக்குக் கட்டளையிட்டபடி எல்லாவற்றையும் நீ ஆரோனுக்கும் அவன் குமாரருக்கும் செய்வாயாக; ஏழுநாளளவும் நீ அவர்களைப் பிரதிஷ்டைபண்ணி,',	2,	29,	35),
(2373,	'And thou shalt offer every day a bullock for a sin offering for atonement: and thou shalt cleanse the altar, when thou hast made an atonement for it, and thou shalt anoint it, to sanctify it.',	'பாவநிவிர்த்திக்காக ஒவ்வொரு நாளிலும் ஒவ்வொரு காளையைப் பாவ நிவாரண பலியாகப் பலியிட்டு; பலிபீடத்துக்காகப் பிராயச்சித்தம் செய்தபின், அந்தப் பலிபீடத்தைச் சுத்திசெய்யவேண்டும்; அதைப் பரிசுத்தப்படுத்தும்படி அதை அபிஷேகம்பண்ணக்கடவாய்.',	2,	29,	36),
(2374,	'Seven days thou shalt make an atonement for the altar, and sanctify it; and it shall be an altar most holy: whatsoever toucheth the altar shall be holy.',	'ஏழுநாளளவும் பலிபீடத்திற்காகப் பிராயச்சித்தஞ்செய்து, அதைப் பரிசுத்தமாக்கக்கடவாய்; பலிபீடமானது மகா பரிசுத்தமாயிருக்கும்; பலிபீடத்தைத் தொடுகிறதெல்லாம் பரிசுத்தமாகும்.',	2,	29,	37),
(2375,	'Now this is that which thou shalt offer upon the altar; two lambs of the first year day by day continually.',	'பலிபீடத்தின்மேல் நீ பலியிடவேண்டியது என்னவெனில்; இடைவிடாமல் ஒவ்வொருநாளிலும் ஒருவயதான இரண்டு ஆட்டுக்குட்டிகளைப் பலியிடவேண்டும்.',	2,	29,	38),
(2376,	'The one lamb thou shalt offer in the morning; and the other lamb thou shalt offer at even:',	'ஒரு ஆட்டுக்குட்டியைக் காலையிலும், மற்ற ஆட்டுக்குட்டியை மாலையிலும் பலியிடுவாயாக.',	2,	29,	39),
(2377,	'And with the one lamb a tenth deal of flour mingled with the fourth part of an hin of beaten oil; and the fourth part of an hin of wine for a drink offering.',	'ஒரு மரக்காலிலே பத்திலொரு பங்கானதும், இடித்துப் பிழிந்த காற்படி எண்ணெயிலே பிசைந்ததுமாகிய மெல்லிய மாவையும், பானபலியாகக் கால்படி திராட்சரசத்தையும், ஒரு ஆட்டுக்குட்டியுடனே படைப்பாயாக.',	2,	29,	40),
(2378,	'And the other lamb thou shalt offer at even, and shalt do thereto according to the meat offering of the morning, and according to the drink offering thereof, for a sweet savour, an offering made by fire unto the LORD.',	'மற்ற ஆட்டுக்குட்டியை மாலையிலே பலியிட்டு, காலையிலே செலுத்தின போஜனபலிக்கும் பானபலிக்கும் ஒத்தபிரகாரம் அதைக் கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாகப் படைக்கக்கடவாய்.',	2,	29,	41),
(2379,	'This shall be a continual burnt offering throughout your generations at the door of the tabernacle of the congregation before the LORD: where I will meet you, to speak there unto thee.',	'உன்னுடனே பேசும்படி நான் உங்களைச் சந்திக்கும் இடமாயிருக்கிற ஆசரிப்புக் கூடாரத்தினுடைய வாசலாகிய கர்த்தருடைய சந்நிதியிலே, உங்கள் தலைமுறைதோறும் செலுத்தப்படவேண்டிய நித்திய சர்வாங்க தகனபலி இதுவே.',	2,	29,	42),
(2380,	'And there I will meet with the children of Israel, and the tabernacle shall be sanctified by my glory.',	'அங்கே இஸ்ரவேல் புத்திரரைச் சந்திப்பேன்; அந்த ஸ்தலம் என்னுடைய மகிமையினால் பரிசுத்தமாக்கப்படும்.',	2,	29,	43),
(2381,	'And I will sanctify the tabernacle of the congregation, and the altar: I will sanctify also both Aaron and his sons, to minister to me in the priest\'s office.',	'ஆசரிப்புக் கூடாரத்தையும் பலிபீடத்தையும் நான் பரிசுத்தமாக்குவேன்; எனக்கு ஆசாரிய ஊழியம் செய்யும்படிக்கு, ஆரோனையும் அவன் குமாரரையும் பரிசுத்தப்படுத்தி,',	2,	29,	44),
(2382,	'And I will dwell among the children of Israel, and will be their God.',	'இஸ்ரவேல் புத்திரரின் நடுவே நான் வாசம்பண்ணி, அவர்களுக்குத் தேவனாயிருப்பேன்.',	2,	29,	45),
(2383,	'And they shall know that I am the LORD their God, that brought them forth out of the land of Egypt, that I may dwell among them: I am the LORD their God.',	'தங்கள் நடுவே நான் வாசம்பண்ணும்படி, தங்களை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணின நான் தங்கள் தேவனாகிய கர்த்தர் என்று அவர்கள் அறிவார்கள்; நானே அவர்கள் தேவனாகிய கர்த்தர்.  ',	2,	29,	46),
(2384,	'And thou shalt make an altar to burn incense upon: of shittim wood shalt thou make it.',	'தூபங்காட்டுகிறதற்கு ஒரு தூபபீடத்தையும் சீத்திம் மரத்தினால் உண்டாக்குவாயாக.',	2,	30,	1),
(2385,	'A cubit shall be the length thereof, and a cubit the breadth thereof; foursquare shall it be: and two cubits shall be the height thereof: the horns thereof shall be of the same.',	'அது ஒரு முழ நீளமும் ஒரு முழ அகலமுமான சதுரமும், இரண்டு முழ உயரமுமாய் இருக்கவேண்டும், அதின் கொம்புகள் அதனோடே ஏகமுமாயிருக்க வேண்டும்.',	2,	30,	2),
(2386,	'And thou shalt overlay it with pure gold, the top thereof, and the sides thereof round about, and the horns thereof; and thou shalt make unto it a crown of gold round about.',	'அதின் மேற்புறத்தையும் சுற்றுப்புறத்தையும் அதின் கொம்புகளையும் பசும்பொன்தகட்டால் மூடி, சுற்றிலும் அதற்குப் பொன்திரணையை உண்டுபண்ணி,',	2,	30,	3),
(2387,	'And two golden rings shalt thou make to it under the crown of it, by the two corners thereof, upon the two sides of it shalt thou make it; and they shall be for places for the staves to bear it withal.',	'அந்தத் திரணையின்கீழே அதின் இரண்டு பக்கங்களிலும் அதைச் சுமக்கும் தண்டுகளின் இடங்களாகிய அதின் இரண்டு பக்கத்து இரண்டு மூலைகளிலும் இரண்டு பொன் வளையங்களை உண்டாக்குவாயாக.',	2,	30,	4),
(2388,	'And thou shalt make the staves of shittim wood, and overlay them with gold.',	'அந்தத் தண்டுகளையும் சீத்திம் மரத்தால் பண்ணி, அவைகளையும் பொன்தகட்டால் மூடக்கடவாய்.',	2,	30,	5),
(2389,	'And thou shalt put it before the vail that is by the ark of the testimony, before the mercy seat that is over the testimony, where I will meet with thee.',	'சாட்சிப்பெட்டிக்கு முன்னிருக்கும் திரைச்சீலைக்கும், நான் உன்னைச் சந்திக்கும் இடமாகிய சாட்சி சந்நிதியின்மேலுள்ள கிருபாசனத்துக்கும் முன்பாக அதை வைக்கக்கடவாய்.',	2,	30,	6),
(2390,	'And Aaron shall burn thereon sweet incense every morning: when he dresseth the lamps, he shall burn incense upon it.',	'ஆரோன் காலைதோறும் அதின்மேல் சுகந்த தூபங்காட்டவேண்டும்; மாலையில் விளக்கேற்றும்போதும் அதின்மேல் தூபங்காட்டக்கடவன்; விளக்குகளை விளக்கும்போதும் அதின்மேல் தூபங்காட்டவேண்டும்.',	2,	30,	7),
(2391,	'And when Aaron lighteth the lamps at even, he shall burn incense upon it, a perpetual incense before the LORD throughout your generations.',	'உங்கள் தலைமுறைதோறும் கர்த்தருடைய சந்நிதியில் காட்டவேண்டிய நித்திய தூபம் இதுவே.',	2,	30,	8),
(2392,	'Ye shall offer no strange incense thereon, nor burnt sacrifice, nor meat offering; neither shall ye pour drink offering thereon.',	'அதின்மேல் அந்நிய தூபத்தையாகிலும், தகனபலியையாகிலும், போஜனபலியையாகிலும் படைக்கவேண்டாம்; அதின்மேல் பானபலியை ஊற்றவும்வேண்டாம்.',	2,	30,	9),
(2393,	'And Aaron shall make an atonement upon the horns of it once in a year with the blood of the sin offering of atonements: once in the year shall he make atonement upon it throughout your generations: it is most holy unto the LORD.',	'வருஷத்தில் ஒருமுறை ஆரோன் பாவநிவாரணபலியின் இரத்தத்தினால் அதின் கொம்புகளின்மேல் பிராயச்சித்தம்பண்ணுவானாக; உங்கள் தலைமுறைதோறும் வருஷத்தில் ஒருமுறை அதின்மேல் பிராயச்சித்தம்பண்ணுவானாக; அது கர்த்தருக்கு மகா பரிசுத்தமானது என்றார்.',	2,	30,	10),
(2394,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	2,	30,	11),
(2395,	'When thou takest the sum of the children of Israel after their number, then shall they give every man a ransom for his soul unto the LORD, when thou numberest them; that there be no plague among them, when thou numberest them.',	'நீ இஸ்ரவேல் புத்திரரை அவர்கள் இலக்கத்தின்படி கணக்குப்பார்க்கும் பொருட்டு, அவர்களை எண்ணும்போது, அவர்களுக்குள்ளே ஒரு வாதை உண்டாகாதபடிக்கு, அவர்களில் ஒவ்வொருவனும் எண்ணப்படும் சமயத்தில் தன்தன் ஆத்துமாவுக்காகக் கர்த்தருக்கு மீட்கும் பொருளைக் கொடுக்கக்கடவன்.',	2,	30,	12),
(2396,	'This they shall give, every one that passeth among them that are numbered, half a shekel after the shekel of the sanctuary: (a shekel is twenty gerahs:) an half shekel shall be the offering of the LORD.',	'எண்ணப்படுகிறவர்களின் தொகையிலே சேருகிற ஒவ்வொருவனும் பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்கின்படி அரைச்சேக்கல் கொடுக்கவேண்டும்; ஒரு சேக்கலுக்கு இருபது கேரா; கர்த்தருக்குச் செலுத்தப்படுவது அரைச்சேக்கல்.',	2,	30,	13),
(2397,	'Every one that passeth among them that are numbered, from twenty years old and above, shall give an offering unto the LORD.',	'எண்ணப்படுகிறவர்களின் தொகையிலே சேருகிற இருபது வயது முதற்கொண்டு அதற்கு மேற்பட்ட ஒவ்வொருவனும் அதைக் கர்த்தருக்குச் செலுத்தவேண்டும்.',	2,	30,	14),
(2398,	'The rich shall not give more, and the poor shall not give less than half a shekel, when they give an offering unto the LORD, to make an atonement for your souls.',	'உங்கள் ஆத்துமாக்களுக்காகப் பாவநிவிர்த்திபண்ணும்படி நீங்கள் கர்த்தருக்குக் காணிக்கை செலுத்தும்போது, ஐசுவரியவான் அரைச்சேக்கலுக்கு அதிகமாய்க் கொடுக்கவும் வேண்டாம், தரித்திரன் அதற்குக் குறைவாகக் கொடுக்கவும் வேண்டாம்.',	2,	30,	15),
(2399,	'And thou shalt take the atonement money of the children of Israel, and shalt appoint it for the service of the tabernacle of the congregation; that it may be a memorial unto the children of Israel before the LORD, to make an atonement for your souls.',	'அந்தப் பாவநிவிர்த்தி பணத்தை நீ இஸ்ரவேல் புத்திரர் கையில் வாங்கி, அதை ஆசரிப்புக் கூடாரத்தின் திருப்பணிக்குக் கொடுப்பாயாக; அது கர்த்தருடைய சந்நிதியில் உங்கள் ஆத்துமாக்களுக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, இஸ்ரவேல் புத்திரருக்கு ஞாபகக்குறியாயிருக்கும் என்றார்.',	2,	30,	16),
(2400,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	2,	30,	17),
(2401,	'Thou shalt also make a laver of brass, and his foot also of brass, to wash withal: and thou shalt put it between the tabernacle of the congregation and the altar, and thou shalt put water therein.',	'கழுவுகிறதற்கு வெண்கலத்தால் ஒரு தொட்டியையும், வெண்கலத்தால் அதின் பாதத்தையும் உண்டாக்கி, அதை ஆசரிப்புக் கூடாரத்திற்கும் பலிபீடத்திற்கும் நடுவே வைத்து, அதிலே தண்ணீர் வார்ப்பாயாக.',	2,	30,	18),
(2402,	'For Aaron and his sons shall wash their hands and their feet thereat:',	'அதனிடத்தில் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளையும் தங்கள் கால்களையும் கழுவக்கடவர்கள்.',	2,	30,	19),
(2403,	'When they go into the tabernacle of the congregation, they shall wash with water, that they die not; or when they come near to the altar to minister, to burn offering made by fire unto the LORD:',	'அவர்கள் ஆசரிப்புக் கூடாரத்திற்குள் பிரவேசிக்கும்போதும், கர்த்தருக்குத் தகனத்தைக் கொளுத்தவும் பலிபீடத்தினிடத்தில் ஆராதனைசெய்யவும் சேரும்போதும், அவர்கள் சாகாதபடிக்குத் தண்ணீரினால் தங்களைக் கழுவக்கடவர்கள்.',	2,	30,	20),
(2404,	'So they shall wash their hands and their feet, that they die not: and it shall be a statute for ever to them, even to him and to his seed throughout their generations.',	'அவர்கள் சாகாதபடிக்குத் தங்கள் கைகளையும் தங்கள் கால்களையும் கழுவக்கடவர்கள்; இது தலைமுறைதோறும் அவனுக்கும் அவன் சந்ததியாருக்கும் நித்திய கட்டளையாயிருக்கும் என்றார்.',	2,	30,	21),
(2405,	'Moreover the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	2,	30,	22),
(2406,	'Take thou also unto thee principal spices, of pure myrrh five hundred shekels, and of sweet cinnamon half so much, even two hundred and fifty shekels, and of sweet calamus two hundred and fifty shekels,',	'மேன்மையான சுகந்தவர்க்கங்களாகிய சுத்தமான வெள்ளைப்போளத்தில் பரிசுத்த ஸ்தலத்தின் சேக்கலின்படி ஐந்நூறு சேக்கல் எடையையும், சுகந்த கருவாப்பட்டையிலே அதில் பாதியாகிய இருநூற்று ஐம்பது சேக்கல் எடையையும், சுகந்த வசம்பில் இருநூற்று ஐம்பது சேக்கல் எடையையும்,',	2,	30,	23),
(2407,	'And of cassia five hundred shekels, after the shekel of the sanctuary, and of oil olive an hin:',	'இலவங்கப்பட்டையில் ஐந்நூறு சேக்கல் எடையையும், ஒலிவ எண்ணெயில் ஒரு குடம் எண்ணெயையும் எடுத்து,',	2,	30,	24),
(2408,	'And thou shalt make it an oil of holy ointment, an ointment compound after the art of the apothecary: it shall be an holy anointing oil.',	'அதனால், பரிமள தைலக்காரன் செய்வதுபோல, கூட்டப்பட்ட பரிமளதைலமாகிய சுத்தமான அபிஷேக தைலத்தை உண்டுபண்ணுவாயாக; அது பரிசுத்த அபிஷேக தைலமாயிருக்கக்கடவது.',	2,	30,	25),
(2409,	'And thou shalt anoint the tabernacle of the congregation therewith, and the ark of the testimony,',	'அதினாலே ஆசரிப்புக் கூடாரத்தையும், சாட்சிப்பெட்டியையும்,',	2,	30,	26),
(2410,	'And the table and all his vessels, and the candlestick and his vessels, and the altar of incense,',	'மேஜையையும், அதின் பணிமுட்டுகள் எல்லாவற்றையும், குத்துவிளக்கையும், அதின் கருவிகளையும், தூபபீடத்தையும்,',	2,	30,	27),
(2411,	'And the altar of burnt offering with all his vessels, and the laver and his foot.',	'தகன பலிபீடத்தையும் அதின் பணிமுட்டுகள் எல்லாவற்றையும், தொட்டியையும், அதின் பாதத்தையும் அபிஷேகம்பண்ணி,',	2,	30,	28),
(2412,	'And thou shalt sanctify them, that they may be most holy: whatsoever toucheth them shall be holy.',	'அவைகள் மகா பரிசுத்தமாயிருக்கும்படிக்கு, அவைகளைப் பரிசுத்தப்படுத்துவாயாக; அவைகளைத் தொடுகிறதெல்லாம் பரிசுத்தமாயிருக்கும்.',	2,	30,	29),
(2413,	'And thou shalt anoint Aaron and his sons, and consecrate them, that they may minister unto me in the priest\'s office.',	'ஆரோனும் அவன் குமாரரும் எனக்கு ஆசாரிய ஊழியம் செய்யும்படிக்கு, நீ அவர்களை அபிஷேகம்பண்ணி, அவர்களைப் பரிசுத்தப்படுத்துவாயாக.',	2,	30,	30),
(2414,	'And thou shalt speak unto the children of Israel, saying, This shall be an holy anointing oil unto me throughout your generations.',	'இஸ்ரவேல் புத்திரரோடே நீ பேசிச்சொல்லவேண்டியதாவது: உங்கள் தலைமுறைதோறும் இது எனக்குரிய பரிசுத்த அபிஷேக தைலமாயிருக்கவேண்டும்.',	2,	30,	31),
(2415,	'Upon man\'s flesh shall it not be poured, neither shall ye make any other like it, after the composition of it: it is holy, and it shall be holy unto you.',	'இது மனிதருடைய சரீரத்தின்மேல் வார்க்கப்படலாகாது; இது செய்யப்பட்ட முறையின்படி அவர்கள் வேறொரு தைலத்தைச் செய்யவுங்கூடாது; இது பரிசுத்தமானது, இது உங்களுக்குப் பரிசுத்தமாயிருப்பதாக.',	2,	30,	32),
(2416,	'Whosoever compoundeth any like it, or whosoever putteth any of it upon a stranger, shall even be cut off from his people.',	'இந்த முறையின்படியே தைலங்கூட்டுகிறவனும், அதில் எடுத்து அந்நியன்மேல் வார்க்கிறவனும், தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோகக்கடவன் என்று சொல் என்றார்.',	2,	30,	33),
(2417,	'And the LORD said unto Moses, Take unto thee sweet spices, stacte, and onycha, and galbanum; these sweet spices with pure frankincense: of each shall there be a like weight:',	'பின்னும் கர்த்தர் மோசேயை நோக்கி: சுத்த வெள்ளைப்போளமும் குங்கிலியமும் அல்பான் பிசினுமாகிய கந்தவர்க்கங்களையும் சுத்தமான சாம்பிராணியையும் நீ சமநிறையாக எடுத்து,',	2,	30,	34),
(2418,	'And thou shalt make it a perfume, a confection after the art of the apothecary, tempered together, pure and holy:',	'தைலக்காரன் செய்கிறதுபோல அதற்குப் பரிமளமேற்றி, துப்புரவான பரிசுத்த தூபவர்க்கமாக்கி,',	2,	30,	35),
(2419,	'And thou shalt beat some of it very small, and put of it before the testimony in the tabernacle of the congregation, where I will meet with thee: it shall be unto you most holy.',	'அதில் கொஞ்சம் எடுத்துப் பொடியாக இடித்து, நான் உன்னைச் சந்திக்கும் ஆசரிப்புக் கூடாரத்திலிருக்கும் சாட்சி சந்நிதியில் வைப்பாயாக; அது உங்களுக்கு மகா பரிசுத்தமாயிருக்கக்கடவது.',	2,	30,	36),
(2420,	'And as for the perfume which thou shalt make, ye shall not make to yourselves according to the composition thereof: it shall be unto thee holy for the LORD.',	'இந்தத் தூபவர்க்கத்தை நீ செய்யவேண்டிய முறையின்படி உங்களுக்காகச் செய்துகொள்ளலாகாது; இது கர்த்தருக்கென்று உனக்குப் பரிசுத்தமாயிருப்பதாக.',	2,	30,	37),
(2421,	'Whosoever shall make like unto that, to smell thereto, shall even be cut off from his people.',	'இதற்கு ஒப்பானதை முகருகிறதற்காகச் செய்கிறவன் தன் ஜனத்தில் இராதபடி அறுப்புண்டுபோகக்கடவன் என்றார்.  ',	2,	30,	38),
(2422,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	2,	31,	1),
(2423,	'See, I have called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah:',	'நான் யூதாவின் கோத்திரத்தில் ஊருடைய மகனான ஊரியின் குமாரன் பெசலெயேலைப் பேர்சொல்லி அழைத்து,',	2,	31,	2),
(2424,	'And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship,',	'விநோதமான வேலைகளை அவன் யோசித்துச் செய்கிறதற்கும், பொன்னிலும் வெள்ளியிலும் வெண்கலத்திலும் வேலைசெய்கிறதற்கும்,',	2,	31,	3),
(2425,	'To devise cunning works, to work in gold, and in silver, and in brass,',	'இரத்தினங்களை முத்திரைவெட்டாக வெட்டிப் பதிக்கிறதற்கும், மரத்தில் சித்திரவேலைகளைச் செய்கிறதற்கும்,',	2,	31,	4),
(2426,	'And in cutting of stones, to set them, and in carving of timber, to work in all manner of workmanship.',	'மற்றும் சகலவித வேலைகளையும் யூகித்துச் செய்கிறதற்கும் வேண்டிய ஞானமும் புத்தியும் அறிவும் அவனுக்கு உண்டாக, அவனை தேவஆவியினால் நிரப்பினேன்.',	2,	31,	5),
(2427,	'And I, behold, I have given with him Aholiab, the son of Ahisamach, of the tribe of Dan: and in the hearts of all that are wise hearted I have put wisdom, that they may make all that I have commanded thee;',	'மேலும், தாண் கோத்திரத்திலுள்ள அகிசாமாகின் குமாரனாகிய அகோலியாபையும் அவனோடே துணையாகக் கூட்டினதுமன்றி, ஞான இருதயமுள்ள யாவருடைய இருதயத்திலும் ஞானத்தை அருளினேன்; நான் உனக்குக் கட்டளையிட்டயாவையும் அவர்கள் செய்வார்கள்.',	2,	31,	6),
(2428,	'The tabernacle of the congregation, and the ark of the testimony, and the mercy seat that is thereupon, and all the furniture of the tabernacle,',	'ஆசரிப்புக் கூடாரத்தையும் சாட்சிப்பெட்டியையும் அதின்மேலுள்ள கிருபாசனத்தையும், கூடாரத்திலுள்ள சகல பணிமுட்டுகளையும்,',	2,	31,	7),
(2429,	'And the table and his furniture, and the pure candlestick with all his furniture, and the altar of incense,',	'மேஜையையும் அதின் பணிமுட்டுகளையும், சுத்தமான குத்துவிளக்கையும் அதின் சகல கருவிகளையும், தூபபீடத்தையும்,',	2,	31,	8),
(2430,	'And the altar of burnt offering with all his furniture, and the laver and his foot,',	'தகனபலிபீடத்தையும் அதின் சகல பணிமுட்டுகளையும், தொட்டியையும் அதின் பாதத்தையும்,',	2,	31,	9),
(2431,	'And the cloths of service, and the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest\'s office,',	'ஆராதனை வஸ்திரங்களையும், ஆசாரிய ஊழியம் செய்வதற்கான ஆசாரியனாகிய ஆரோனின் பரிசுத்த வஸ்திரங்களையும், அவன் குமாரரின் வஸ்திரங்களையும்,',	2,	31,	10),
(2432,	'And the anointing oil, and sweet incense for the holy place: according to all that I have commanded thee shall they do.',	'அபிஷேக தைலத்தையும், பரிசுத்த ஸ்தலத்துக்குச் சுகந்தவர்க்கங்களாகிய தூபவர்க்கத்தையும், நான் உனக்குக் கட்டளையிட்டபடியே, அவர்கள் செய்யவேண்டும் என்றார்.',	2,	31,	11),
(2433,	'And the LORD spake unto Moses, saying,',	'மேலும், கர்த்தர் மோசேயினிடத்தில்:',	2,	31,	12),
(2434,	'Speak thou also unto the children of Israel, saying, Verily my sabbaths ye shall keep: for it is a sign between me and you throughout your generations; that ye may know that I am the LORD that doth sanctify you.',	'நீ இஸ்ரவேல் புத்திரரை நோக்கி, நீங்கள் என் ஓய்வுநாட்களை ஆசரிக்க வேண்டும்; உங்களைப் பரிசுத்தப்படுத்துகிற கர்த்தர் நான் என்பதை நீங்கள் அறியும்படி, இது உங்கள் தலைமுறைதோறும் எனக்கும் உங்களுக்கும் அடையாளமாயிருக்கும்.',	2,	31,	13),
(2435,	'Ye shall keep the sabbath therefore; for it is holy unto you: every one that defileth it shall surely be put to death: for whosoever doeth any work therein, that soul shall be cut off from among his people.',	'ஆகையால், ஓய்வுநாளை ஆசரிப்பீர்களாக; அது உங்களுக்குப் பரிசுத்தமானது; அதைப் பரிசுத்தக்குலைச்சலாக்குகிறவன் கொலையுண்ணக்கடவன்; அதிலே வேலைசெய்கிற எந்த ஆத்துமாவும் தன் ஜனத்தின் நடுவில் இராதபடிக்கு அறுப்புண்டுபோவான்.',	2,	31,	14),
(2436,	'Six days may work be done; but in the seventh is the sabbath of rest, holy to the LORD: whosoever doeth any work in the sabbath day, he shall surely be put to death.',	'ஆறுநாளும் வேலைசெய்யலாம்; ஏழாம் நாளோ வேலை ஒழிந்திருக்கும் ஓய்வுநாள்; அது கர்த்தருக்குப் பரிசுத்தமானது; ஓய்வுநாளில் வேலைசெய்கிறவன் எவனும் கொலைசெய்யப்படவேண்டும்.',	2,	31,	15),
(2437,	'Wherefore the children of Israel shall keep the sabbath, to observe the sabbath throughout their generations, for a perpetual covenant.',	'ஆகையால், இஸ்ரவேல் புத்திரர் தங்கள் தலைமுறைதோறும் ஓய்வுநாளை நித்திய உடன்படிக்கையாக ஆசரிக்கும்படி, அதைக் கைக்கொள்ளக்கடவர்கள்.',	2,	31,	16),
(2438,	'It is a sign between me and the children of Israel for ever: for in six days the LORD made heaven and earth, and on the seventh day he rested, and was refreshed.',	'அது என்றைக்கும் எனக்கும் இஸ்ரவேல் புத்திரருக்கும் அடையாளமாயிருக்கும்; ஆறுநாளைக்குள்ளே கர்த்தர் வானத்தையும் பூமியையும் உண்டாக்கி, ஏழாம் நாளிலே ஓய்ந்திருந்து பூரித்தார் என்றார்.',	2,	31,	17),
(2439,	'And he gave unto Moses, when he had made an end of communing with him upon mount Sinai, two tables of testimony, tables of stone, written with the finger of God.',	'சீனாய்மலையில் அவர் மோசேயோடே பேசி முடிந்தபின், தேவனுடைய விரலினால் எழுதப்பட்ட கற்பலகைகளாகிய சாட்சியின் இரண்டு பலகைகளை அவனிடத்தில் கொடுத்தார்.  ',	2,	31,	18),
(2440,	'And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him.',	'மோசே மலையிலிருந்து இறங்கிவரத் தாமதிக்கிறதை ஜனங்கள் கண்டபோது, அவர்கள் ஆரோனிடத்தில் கூட்டங்கூடி. அவனை நோக்கி: எகிப்துதேசத்திலிருந்து எங்களை அழைத்துக்கொண்டு வந்த அந்த மோசேக்கு என்ன சம்பவித்ததோ அறியோம்; ஆதலால் நீர் எழுந்து எங்களுக்கு முன்செல்லும் தெய்வங்களை எங்களுக்காக உண்டுபண்ணும் என்றார்கள்.',	2,	32,	1),
(2441,	'And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me.',	'அதற்கு ஆரோன்: உங்கள் மனைவிகள் குமாரர் குமாரத்திகளுடைய காதுகளில் இருக்கிற பொன்னணிகளைக் கழற்றி, என்னிடத்தில் கொண்டுவாருங்கள் என்றான்.',	2,	32,	2),
(2442,	'And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron.',	'ஜனங்கள் எல்லாரும் தங்கள் காதுகளில் இருந்த பொன்னணிகளைக் கழற்றி, ஆரோனிடத்தில் கொண்டுவந்தார்கள்.',	2,	32,	3),
(2443,	'And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy gods, O Israel, which brought thee up out of the land of Egypt.',	'அவர்கள் கையிலிருந்து அவன் அந்தப் பொன்னை வாங்கி, சிற்பக்கருவியினால் கருப்பிடித்து, ஒரு கன்றுக்குட்டியை வார்ப்பித்தான். அப்பொழுது அவர்கள்: இஸ்ரவேலரே, உங்களை எகிப்துதேசத்திலிருந்து அழைத்துக்கொண்டுவந்த உங்கள் தெய்வங்கள் இவைகளே என்றார்கள்.',	2,	32,	4),
(2444,	'And when Aaron saw it, he built an altar before it; and Aaron made proclamation, and said, To morrow is a feast to the LORD.',	'ஆரோன் அதைப் பார்த்து, அதற்கு முன்பாக ஒரு பலிபீடத்தைக் கட்டி, நாளைக்குக் கர்த்தருக்குப் பண்டிகை என்று கூறினான்.',	2,	32,	5),
(2445,	'And they rose up early on the morrow, and offered burnt offerings, and brought peace offerings; and the people sat down to eat and to drink, and rose up to play.',	'மறுநாள் அவர்கள் அதிகாலையில் எழுந்து, சர்வாங்கதகனபலிகளையிட்டு, சமாதானபலிகளைச் செலுத்தினார்கள்; பின்பு, ஜனங்கள் புசிக்கவும் குடிக்கவும் உட்கார்ந்து, விளையாட எழுந்தார்கள்.',	2,	32,	6),
(2446,	'And the LORD said unto Moses, Go, get thee down; for thy people, which thou broughtest out of the land of Egypt, have corrupted themselves:',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ இறங்கிப்போ; எகிப்துதேசத்திலிருந்து நீ நடத்திக்கொண்டுவந்த உன் ஜனங்கள் தங்களைக் கெடுத்துக்கொண்டார்கள்.',	2,	32,	7),
(2447,	'They have turned aside quickly out of the way which I commanded them: they have made them a molten calf, and have worshipped it, and have sacrificed thereunto, and said, These be thy gods, O Israel, which have brought thee up out of the land of Egypt.',	'அவர்களுக்கு நான் விதித்த வழியை அவர்கள் சீக்கிரமாய் விட்டு விலகினார்கள்; அவர்கள் தங்களுக்கு ஒரு கன்றுக்குட்டியை வார்ப்பித்து, அதைப்பணிந்துகொண்டு, அதற்குப் பலியிட்டு: இஸ்ரவேலரே, உங்களை எகிப்துதேசத்திலிருந்து அழைத்துக்கொண்டுவந்த உங்கள் தெய்வங்கள் இவைகளே என்று சொன்னார்கள் என்றார்.',	2,	32,	8),
(2448,	'And the LORD said unto Moses, I have seen this people, and, behold, it is a stiffnecked people:',	'பின்னும் கர்த்தர் மோசேயை நோக்கி: இந்த ஜனங்களைப் பார்த்தேன்; இவர்கள் வணங்காக்கழுத்துள்ள ஜனங்கள்.',	2,	32,	9),
(2449,	'Now therefore let me alone, that my wrath may wax hot against them, and that I may consume them: and I will make of thee a great nation.',	'ஆகையால் என் கோபம் இவர்கள் மேல் மூளவும், நான் இவர்களை அழித்துப்போடவும் நீ என்னை விட்டுவிடு; உன்னை ஒரு பெரிய ஜாதியாக்குவேன் என்றார்.',	2,	32,	10),
(2450,	'And Moses besought the LORD his God, and said, LORD, why doth thy wrath wax hot against thy people, which thou hast brought forth out of the land of Egypt with great power, and with a mighty hand?',	'மோசே தன் தேவனாகிய கர்த்தரை நோக்கி: கர்த்தாவே, தேவரீர் மகா பலத்தினாலும் வல்லமையுள்ள கையினாலும் எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணின உம்முடைய ஜனங்களுக்கு விரோதமாக உம்முடைய கோபம் பற்றியெரிவதென்ன?',	2,	32,	11),
(2451,	'Wherefore should the Egyptians speak, and say, For mischief did he bring them out, to slay them in the mountains, and to consume them from the face of the earth? Turn from thy fierce wrath, and repent of this evil against thy people.',	'மலைகளில் அவர்களைக்கொன்று போடவும், பூமியின்மேல் இராதபடிக்கு அவர்களை நிர்மூலமாக்கவும், அவர்களுக்குத் தீங்குசெய்யும்பொருட்டே அவர்களைப் புறப்படப்பண்ணினார் என்று எகிப்தியர் சொல்லுவானேன்? உம்முடைய கோபத்தின் உக்கிரத்தை விட்டுத் திரும்பி, உமது ஜனங்களுக்குத் தீங்குசெய்யாதபடிக்கு, அவர்கள்மேல் பரிதாபங்கொள்ளும்.',	2,	32,	12),
(2452,	'Remember Abraham, Isaac, and Israel, thy servants, to whom thou swarest by thine own self, and saidst unto them, I will multiply your seed as the stars of heaven, and all this land that I have spoken of will I give unto your seed, and they shall inherit it for ever.',	'உமது தாசராகிய ஆபிரகாமையும் ஈசாக்கையும் இஸ்ரவேலையும் நினைத்தருளும்: உங்கள் சந்ததியை வானத்து நட்சத்திரங்களைப்போலப் பெருகப்பண்ணி, நான் சொன்ன இந்தத் தேசம் முழுவதையும் உங்கள் சந்ததியார் என்றைக்கும் சுதந்தரித்துக்கொள்ளும்படிக்கு, அவர்களுக்குக் கொடுப்பேன் என்று உம்மைக்கொண்டே அவர்களுக்கு ஆணையிட்டுச் சொன்னீரே என்று கெஞ்சிப் பிரார்த்தித்தான்.',	2,	32,	13),
(2453,	'And the LORD repented of the evil which he thought to do unto his people.',	'அப்பொழுது கர்த்தர் தமது ஜனங்ளுக்குச் செய்ய நினைத்த தீங்கைச்செய்யாதபடிக்குப் பரிதாபங்கொண்டார்.',	2,	32,	14),
(2454,	'And Moses turned, and went down from the mount, and the two tables of the testimony were in his hand: the tables were written on both their sides; on the one side and on the other were they written.',	'பின்பு மோசே மலையிலிருந்து இறங்கினான்; சாட்சிப்பலகைகள் இரண்டும் அவன் கையில் இருந்தது; அந்தப் பலகைகள் இருபுறமும் எழுதப்பட்டிருந்தது, அவைகள் இந்தப்பக்கத்திலும் அந்தப்பக்கத்திலும் எழுதப்பட்டிருந்தது.',	2,	32,	15),
(2455,	'And the tables were the work of God, and the writing was the writing of God, graven upon the tables.',	'அந்தப் பலகைகள் தேவனால் செய்யப்பட்டதாயும், அவைகளிலே பதிந்த எழுத்து தேவனால் எழுதப்பட்ட எழுத்துமாயிருந்தது.',	2,	32,	16),
(2456,	'And when Joshua heard the noise of the people as they shouted, he said unto Moses, There is a noise of war in the camp.',	'ஜனங்கள் ஆரவாரம் பண்ணுகிறதை யோசுவா கேட்டு, மோசேயை நோக்கி: பாளயத்தில் யுத்தத்தின் இரைச்சல் உண்டாயிருக்கிறது என்றான்.',	2,	32,	17),
(2457,	'And he said, It is not the voice of them that shout for mastery, neither is it the voice of them that cry for being overcome: but the noise of them that sing do I hear.',	'அதற்கு மோசே: அது ஜெயதொனியாகிய சத்தமும் அல்ல, அபஜெயதொனியாகிய சத்தமும் அல்ல; பாடலின் சத்தம் எனக்குக் கேட்கிறது என்றான்.',	2,	32,	18),
(2458,	'And it came to pass, as soon as he came nigh unto the camp, that he saw the calf, and the dancing: and Moses\' anger waxed hot, and he cast the tables out of his hands, and brake them beneath the mount.',	'அவன் பாளயத்துக்குச் சமீபித்து, அந்தக் கன்றுக்குட்டியையும் நடனத்தையும் கண்டபோது, மோசே கோபம் மூண்டவனாகி, தன் கையிலே இருந்த பலகைகளை மலையின் அடியிலே எறிந்து உடைத்துப்போட்டு;',	2,	32,	19),
(2459,	'And he took the calf which they had made, and burnt it in the fire, and ground it to powder, and strawed it upon the water, and made the children of Israel drink of it.',	'அவர்கள் உண்டுபண்ணின கன்றுக்குட்டியை எடுத்து, அக்கினியில் சுட்டெரித்து, அதைப் பொடியாக அரைத்து, தண்ணீரின்மேல் தூவி, அதை இஸ்ரவேல் புத்திரர் குடிக்கும்படி செய்தான்.',	2,	32,	20),
(2460,	'And Moses said unto Aaron, What did this people unto thee, that thou hast brought so great a sin upon them?',	'பின்பு, மோசே ஆரோனை நோக்கி: நீ இந்த ஜனங்கள்மேல் இந்தப் பெரும்பாதகத்தைச் சுமத்துகிறதற்கு, இவர்கள் உனக்கு என்ன செய்தார்கள் என்றான்.',	2,	32,	21),
(2461,	'And Aaron said, Let not the anger of my lord wax hot: thou knowest the people, that they are set on mischief.',	'அதற்கு ஆரோன்: என் ஆண்டவனுக்குக் கோபம் மூளாதிருப்பதாக; இது பொல்லாத ஜனம் என்று நீர் அறிந்திருக்கிறீர்.',	2,	32,	22),
(2462,	'For they said unto me, Make us gods, which shall go before us: for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him.',	'இவர்கள் என்னை நோக்கி: எங்களுக்கு முன்செல்லும் தெய்வங்களை எங்களுக்கு உண்டுபண்ணும்; எகிப்துதேசத்திலிருந்து எங்களை அழைத்துக்கொண்டுவந்த அந்த மோசேக்கு என்ன சம்பவித்ததோ அறியோம் என்றார்கள்.',	2,	32,	23),
(2463,	'And I said unto them, Whosoever hath any gold, let them break it off. So they gave it me: then I cast it into the fire, and there came out this calf.',	'அப்பொழுது நான்: பொன்னுடைமை உடையவர்கள் எவர்களோ அவர்கள் அதைக் கழற்றித் தரக்கடவர்கள் என்றேன்; அவர்கள் அப்படியே செய்தார்கள்; அதை அக்கினியிலே போட்டேன், அதிலிருந்து இந்தக் கன்றுக்குட்டி வந்தது என்றான்.',	2,	32,	24),
(2464,	'And when Moses saw that the people were naked; (for Aaron had made them naked unto their shame among their enemies:)',	'ஜனங்கள் தங்கள் பகைவருக்குள் அவமானப்படத்தக்கதாக ஆரோன் அவர்களை நிர்வாணமாக்கியிருந்தான். அவர்கள் நிர்வாணமாயிருக்கிறதை மோசே கண்டு,',	2,	32,	25),
(2465,	'Then Moses stood in the gate of the camp, and said, Who is on the LORD\'s side? let him come unto me. And all the sons of Levi gathered themselves together unto him.',	'பாளயத்தின் வாசலில் நின்று: கர்த்தருடைய பட்சத்தில் இருக்கிறவர்கள் யார்? அவர்கள் என்னிடத்தில் சேரக்கடவர்கள் என்றான். அப்பொழுது லேவியின் புத்திரர் எல்லாரும் அவனிடத்தில் கூடிவந்தார்கள்.',	2,	32,	26),
(2466,	'And he said unto them, Thus saith the LORD God of Israel, Put every man his sword by his side, and go in and out from gate to gate throughout the camp, and slay every man his brother, and every man his companion, and every man his neighbour.',	'அவன் அவர்களை நோக்கி: உங்களில் ஒவ்வொருவனும் தன் பட்டயத்தைத் தன் அரையிலே கட்டிக்கொண்டு, பாளயமெங்கும் உள்ளும் புறம்பும் வாசலுக்கு வாசல் போய், ஒவ்வொருவனும் தன்தன் சகோதரனையும் ஒவ்வொருவனும் தன்தன் சிநேகிதனையும் ஒவ்வொருவனும் தன்தன் அயலானையும் கொன்றுபோடக்கடவன் என்று இஸ்ரவேலின் தேவனாகிய கர்த்தர் சொல்லுகிறார் என்றான்.',	2,	32,	27),
(2467,	'And the children of Levi did according to the word of Moses: and there fell of the people that day about three thousand men.',	'லேவியின் புத்திரர் மோசே சொன்னபடியே செய்தார்கள்; அந்நாளில் ஜனங்களில் ஏறக்குறைய மூவாயிரம்பேர் விழுந்தார்கள்.',	2,	32,	28),
(2468,	'For Moses had said, Consecrate yourselves today to the LORD, even every man upon his son, and upon his brother; that he may bestow upon you a blessing this day.',	'கர்த்தர் இன்றைக்கு உங்களுக்கு ஆசீர்வாதம் அளிக்கும்படி, இன்றைக்கு நீங்கள் அவனவன் தன்தன் மகனுக்கும் சகோதரனுக்கும் விரோதமாயிருக்கிறதினால், கர்த்தருக்கு உங்களைப் பிரதிஷ்டைபண்ணுங்கள் என்று மோசே சொல்லியிருந்தான்.',	2,	32,	29),
(2469,	'And it came to pass on the morrow, that Moses said unto the people, Ye have sinned a great sin: and now I will go up unto the LORD; peradventure I shall make an atonement for your sin.',	'மறுநாளில் மோசே ஜனங்களை நோக்கி: நீங்கள் மகா பெரிய பாவஞ்செய்தீர்கள்; உங்களுக்காகப் பாவநிவிர்த்தி செய்யக்கூடுமோ என்று அறிய இப்பொழுது நான் கர்த்தரிடத்திற்கு ஏறிப்போகிறேன் என்றான்.',	2,	32,	30),
(2470,	'And Moses returned unto the LORD, and said, Oh, this people have sinned a great sin, and have made them gods of gold.',	'அப்படியே மோசே கர்த்தரிடத்திற்குத் திரும்பிப்போய்: ஐயோ, இந்த ஜனங்கள் பொன்னினால் தங்களுக்குத் தெய்வங்களை உண்டாக்கி, மகா பெரியபாவம் செய்திருக்கிறார்கள்.',	2,	32,	31),
(2471,	'Yet now, if thou wilt forgive their sin--; and if not, blot me, I pray thee, out of thy book which thou hast written.',	'ஆகிலும், தேவரீர் அவர்கள் பாவத்தை மன்னித்தருளுவீரானால் மன்னித்தருளும்; இல்லாவிட்டால் நீர் எழுதின உம்முடைய புஸ்தகத்திலிருந்து என் பேரைக் கிறுக்கிப்போடும் என்றான்.',	2,	32,	32),
(2472,	'And the LORD said unto Moses, Whosoever hath sinned against me, him will I blot out of my book.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: எனக்கு விரோதமாய்ப் பாவம் செய்தவன் எவனோ, அவன் பேரை என் புஸ்தகத்திலிருந்து கிறுக்கிப்போடுவேன்.',	2,	32,	33),
(2473,	'Therefore now go, lead the people unto the place of which I have spoken unto thee: behold, mine Angel shall go before thee: nevertheless in the day when I visit I will visit their sin upon them.',	'இப்பொழுது நீ போய், நான் உனக்குச் சொன்ன இடத்துக்கு ஜனங்களை அழைத்துக்கொண்டுபோ; என் தூதனானவர் உனக்குமுன் செல்லுவார்; ஆகிலும், நான் விசாரிக்கும் நாளில் அவர்களுடைய பாவத்தை அவர்களிடத்தில் விசாரிப்பேன் என்றார்.',	2,	32,	34),
(2474,	'And the LORD plagued the people, because they made the calf, which Aaron made.',	'ஆரோன் செய்த கன்றுக்குட்டியை ஜனங்கள் செய்வித்ததின் நிமித்தம் கர்த்தர் அவர்களை உபாதித்தார்.  ',	2,	32,	35),
(2475,	'And the LORD said unto Moses, Depart, and go up hence, thou and the people which thou hast brought up out of the land of Egypt, unto the land which I sware unto Abraham, to Isaac, and to Jacob, saying, Unto thy seed will I give it:',	'கர்த்தர் மோசேயை நோக்கி: நீயும், எகிப்துதேசத்திலிருந்து நீ அழைத்துக்கொண்டு வந்த ஜனங்களும் இவ்விடத்தைவிட்டுப் புறப்பட்டு. உன் சந்ததிக்குக் கொடுப்பேன் என்று நான் ஆபிரகாமுக்கும் ஈசாக்குக்கும் யாக்கோபுக்கும் ஆணையிட்டுக்கொடுத்த பாலும் தேனும் ஓடுகிற தேசத்துக்குப் போங்கள்.',	2,	33,	1),
(2476,	'And I will send an angel before thee; and I will drive out the Canaanite, the Amorite, and the Hittite, and the Perizzite, the Hivite, and the Jebusite:',	'நான் ஒரு தூதனை உங்களுக்கு முன்பாக அனுப்பி, கானானியனையும் எமோரியனையும் ஏத்தியனையும் பெரிசியனையும் ஏவியனையும் எபூசியனையும் துரத்திவிடுவேன்.',	2,	33,	2),
(2477,	'Unto a land flowing with milk and honey: for I will not go up in the midst of thee; for thou art a stiffnecked people: lest I consume thee in the way.',	'ஆனாலும், வழியிலே நான் உங்களை நிர்மூலம்பண்ணாதபடிக்கு, நான் உங்கள் நடுவே செல்லமாட்டேன், நீங்கள் வணங்காக்கழுத்துள்ள ஜனங்கள் என்றார்.',	2,	33,	3),
(2478,	'And when the people heard these evil tidings, they mourned: and no man did put on him his ornaments.',	'துக்கமான இவ்வார்த்தைகளை ஜனங்கள் கேட்டபோது, ஒருவரும் தங்கள் ஆபரணங்களைப் போட்டுக்கொள்ளாமல் துக்கித்துக்கொண்டிருந்தார்கள்.',	2,	33,	4),
(2479,	'For the LORD had said unto Moses, Say unto the children of Israel, Ye are a stiffnecked people: I will come up into the midst of thee in a moment, and consume thee: therefore now put off thy ornaments from thee, that I may know what to do unto thee.',	'ஏனென்றால், நீங்கள் வணங்காக்கழுத்துள்ள ஜனங்கள், நான் ஒரு நிமிஷத்தில் உங்கள் நடுவில் எழும்பி, உங்களை நிர்மூலம்பண்ணுவேன்; ஆகையால், நீங்கள் போட்டிருக்கிற உங்கள் ஆபரணங்களைக் கழற்றிப்போடுங்கள்; அப்பொழுது நான் உங்களுக்குச் செய்யவேண்டியதை அறிவேன் என்று இஸ்ரவேல் புத்திரருக்குச் சொல் என்று கர்த்தர் மோசேயோடே சொல்லியிருந்தார்.',	2,	33,	5),
(2480,	'And the children of Israel stripped themselves of their ornaments by the mount Horeb.',	'ஆகையால், இஸ்ரவேல் புத்திரர் ஓரேப் மலையருகே தங்கள் ஆபரணங்களைக் கழற்றிப்போட்டார்கள்.',	2,	33,	6),
(2481,	'And Moses took the tabernacle, and pitched it without the camp, afar off from the camp, and called it the Tabernacle of the congregation. And it came to pass, that every one which sought the LORD went out unto the tabernacle of the congregation, which was without the camp.',	'மோசே கூடாரத்தைப் பெயர்த்து, அதைப் பாளயத்துக்குப் புறம்பே தூரத்திலே போட்டு, அதற்கு ஆசரிப்புக்கூடாரம் என்று பேரிட்டான். கர்த்தரைத்தேடும் யாவரும் பாளயத்துக்குப் புறம்பான ஆசரிப்புக் கூடாரத்துக்குப் போவார்கள்.',	2,	33,	7),
(2482,	'And it came to pass, when Moses went out unto the tabernacle, that all the people rose up, and stood every man at his tent door, and looked after Moses, until he was gone into the tabernacle.',	'மோசே கூடாரத்துக்குப் போகும்போது, ஜனங்கள் எல்லாரும் எழுந்திருந்து, தங்கள் தங்கள் கூடாரவாசலில் நின்றுகொண்டு, அவன் கூடாரத்துக்குள் பிரவேசிக்குமட்டும், அவன் பின்னே பார்த்துக்கொண்டிருந்தார்கள்.',	2,	33,	8),
(2483,	'And it came to pass, as Moses entered into the tabernacle, the cloudy pillar descended, and stood at the door of the tabernacle, and the Lord talked with Moses.',	'மோசே கூடாரத்துக்குள் பிரவேசிக்கையில், மேகஸ்தம்பம் இறங்கி, கூடாரவாசலில் நின்றது; கர்த்தர் மோசேயோடே பேசினார்.',	2,	33,	9),
(2484,	'And all the people saw the cloudy pillar stand at the tabernacle door: and all the people rose up and worshipped, every man in his tent door.',	'ஜனங்கள் எல்லாரும் மேகஸ்தம்பம் கூடாரவாசலில் நிற்கக்கண்டார்கள்; ஜனங்கள் எல்லாரும் எழுந்திருந்து, தங்கள் தங்கள் கூடாரவாசலில் பணிந்துகொண்டார்கள்.',	2,	33,	10),
(2485,	'And the LORD spake unto Moses face to face, as a man speaketh unto his friend. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle.',	'ஒருவன் தன் சிநேகிதனோடே பேசுவதுபோல, கர்த்தர் மோசேயோடே முகமுகமாய்ப் பேசினார்; பின்பு, அவன் பாளையத்துக்குத் திரும்பினான்; நூனின் குமாரனாகிய யோசுவா என்னும் அவனுடைய பணிவிடைக்காரனாகிய வாலிபன் ஆசரிப்புக் கூடாரத்தை விட்டுப் பிரியாதிருந்தான்.',	2,	33,	11),
(2486,	'And Moses said unto the LORD, See, thou sayest unto me, Bring up this people: and thou hast not let me know whom thou wilt send with me. Yet thou hast said, I know thee by name, and thou hast also found grace in my sight.',	'மோசே கர்த்தரை நோக்கி: தேவரீர் இந்த ஜனங்களை அழைத்துக்கொண்டுபோ என்று சொன்னீர்; ஆகிலும், என்னோடேகூட இன்னாரை அனுப்புவேன் என்பதை எனக்கு நீர் அறிவிக்கவில்லை; என்றாலும், உன்னைப் பேர்சொல்லி அழைத்து அறிந்திருக்கிறேன் என்றும், என் கண்களில் உனக்குக் கிருபை கிடைத்தது என்றும், தேவரீர் சொன்னதுண்டே;',	2,	33,	12),
(2487,	'Now therefore, I pray thee, if I have found grace in thy sight, shew me now thy way, that I may know thee, that I may find grace in thy sight: and consider that this nation is thy people.',	'உம்முடைய கண்களில் இப்பொழுது எனக்குக் கிருபை கிடைத்ததானால் நான் உம்மை அறிவதற்கும், உம்முடைய கண்களில் எனக்குக் கிருபை கிடைப்பதற்கும், உம்முடைய வழியை எனக்கு அறிவியும்; இந்த ஜாதி உம்முடைய ஜனமென்று நினைத்தருளும் என்றான்.',	2,	33,	13),
(2488,	'And he said, My presence shall go with thee, and I will give thee rest.',	'அதற்கு அவர்: என் சமுகம் உனக்கு முன்பாகச் செல்லும், நான் உனக்கு இளைப்பாறுதல் தருவேன் என்றார்.',	2,	33,	14),
(2489,	'And he said unto him, If thy presence go not with me, carry us not up hence.',	'அப்பொழுது அவன் அவரை நோக்கி: உம்முடைய சமுகம் என்னோடேகூடச் செல்லாமற்போனால், எங்களை இவ்விடத்திலிருந்து கொண்டுபோகாதிரும்.',	2,	33,	15),
(2490,	'For wherein shall it be known here that I and thy people have found grace in thy sight? is it not in that thou goest with us? so shall we be separated, I and thy people, from all the people that are upon the face of the earth.',	'எனக்கும் உமது ஜனங்களுக்கும் உம்முடைய கண்களிலே கிருபை கிடைத்ததென்பது எதினால் அறியப்படும்; நீர் எங்களோடே வருவதினால் அல்லவா? இப்படியே பூமியின்மேலுள்ள ஜனங்கள் எல்லாரிலும், நானும் உம்முடைய ஜனங்களும் விசேஷித்தவர்கள் என்று விளங்கும் என்றான்.',	2,	33,	16),
(2491,	'And the LORD said unto Moses, I will do this thing also that thou hast spoken: for thou hast found grace in my sight, and I know thee by name.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: நீ சொன்ன இந்த வார்த்தையின்படியே செய்வேன்; என் கண்களில் உனக்குக் கிருபை கிடைத்தது; உன்னைப்பேர்சொல்லி அழைத்து அறிந்திருக்கிறேன் என்றார்.',	2,	33,	17),
(2492,	'And he said, I beseech thee, shew me thy glory.',	'அப்பொழுது அவன்: உம்முடைய மகிமையை எனக்குக் காண்பித்தருளும் என்றான்.',	2,	33,	18),
(2493,	'And he said, I will make all my goodness pass before thee, and I will proclaim the name of the LORD before thee; and will be gracious to whom I will be gracious, and will shew mercy on whom I will shew mercy.',	'அதற்கு அவர்: என்னுடைய தயையை எல்லாம் நான் உனக்கு முன்பாகக் கடந்துபோகப்பண்ணி, கர்த்தருடைய நாமத்தை உனக்கு முன்பாகக்கூறுவேன்; எவன்மேல் கிருபையாயிருக்கச் சித்தமாயிருப்பேனோ, அவன்மேல் கிருபையாயிருப்பேன்; எவன்மேல் இரக்கமாயிருக்கச் சித்தமாயிருப்பேனோ, அவன்மேல் இரக்கமாயிருப்பேன் என்று சொல்லி,',	2,	33,	19),
(2494,	'And he said, Thou canst not see my face: for there shall no man see me, and live.',	'நீ என் முகத்தைக் காணமாட்டாய், ஒரு மனுஷனும் என்னைக் கண்டு உயிரோடிருக்கக்கூடாது என்றார்.',	2,	33,	20),
(2495,	'And the LORD said, Behold, there is a place by me, and thou shalt stand upon a rock:',	'பின்னும் கர்த்தர்: இதோ, என்னண்டையில் ஒரு இடம் உண்டு; நீ அங்கே கன்மலையில் நில்லு.',	2,	33,	21),
(2496,	'And it shall come to pass, while my glory passeth by, that I will put thee in a clift of the rock, and will cover thee with my hand while I pass by:',	'என் மகிமை கடந்துபோகும்போது, நான் உன்னை அந்தக் கன்மலையின் வெடிப்பிலே வைத்து, நான் கடந்துபோகுமட்டும் என் கரத்தினால் உன்னை மூடுவேன்;',	2,	33,	22),
(2497,	'And I will take away mine hand, and thou shalt see my back parts: but my face shall not be seen.',	'பின்பு, என் கரத்தை எடுப்பேன்; அப்பொழுது என் பின்பக்கத்தைக் காண்பாய்; என் முகமோ காணப்படாது என்றார்.  ',	2,	33,	23),
(2498,	'And the LORD said unto Moses, Hew thee two tables of stone like unto the first: and I will write upon these tables the words that were in the first tables, which thou brakest.',	'கர்த்தர் மோசேயை நோக்கி: முந்தின கற்பலகைகளுக்கு ஒத்த இரண்டு கற்பலகைகளை இழைத்துக்கொள்; நீ உடைத்துப்போட்ட முந்தின பலகைகளில் இருந்த வார்த்தைகளை அவைகளில் எழுதுவேன்.',	2,	34,	1),
(2499,	'And be ready in the morning, and come up in the morning unto mount Sinai, and present thyself there to me in the top of the mount.',	'விடியற்காலத்தில் நீ ஆயத்தமாகி, சீனாய் மலையில் ஏறி, அங்கே மலையின் உச்சியில் காலமே என் சமுகத்தில் வந்து நில்.',	2,	34,	2),
(2500,	'And no man shall come up with thee, neither let any man be seen throughout all the mount; neither let the flocks nor herds feed before that mount.',	'உன்னோடே ஒருவனும் அங்கே வரக்கூடாது; மலையிலெங்கும் ஒருவனும் காணப்படவுங்கூடாது; இந்த மலையின் சமீபத்தில் ஆடுமாடு மேயவுங்கூடாது என்றார்.',	2,	34,	3),
(2501,	'And he hewed two tables of stone like unto the first; and Moses rose up early in the morning, and went up unto mount Sinai, as the LORD had commanded him, and took in his hand the two tables of stone.',	'அப்பொழுது மோசே முந்தின கற்பலகைகளுக்கு ஒத்த இரண்டு கற்பலகைகளை இழைத்து, அதிகாலமே எழுந்திருந்து, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே அவ்விரண்டு கற்பலகைகளையும் தன் கையிலே எடுத்துக்கொண்டு, சீனாய் மலையில் ஏறினான்.',	2,	34,	4),
(2502,	'And the LORD descended in the cloud, and stood with him there, and proclaimed the name of the LORD.',	'கர்த்தர் ஒரு மேகத்தில் இறங்கி, அங்கே அவன் அருகே நின்று, கர்த்தருடைய நாமத்தைக் கூறினார்.',	2,	34,	5),
(2503,	'And the LORD passed by before him, and proclaimed, The LORD, The LORD God, merciful and gracious, longsuffering, and abundant in goodness and truth,',	'கர்த்தர் அவனுக்கு முன்பாகக் கடந்துபோகிறபோது, அவர்: கர்த்தர், கர்த்தர்; இரக்கமும், கிருபையும், நீடிய சாந்தமும், மகா தயையும், சத்தியமுமுள்ள தேவன்.',	2,	34,	6),
(2504,	'Keeping mercy for thousands, forgiving iniquity and transgression and sin, and that will by no means clear the guilty; visiting the iniquity of the fathers upon the children, and upon the children\'s children, unto the third and to the fourth generation.',	'ஆயிரம் தலைமுறைகளுக்கு இரக்கத்தைக் காக்கிறவர்; அக்கிரமத்தையும் மீறுதலையும் பாவத்தையும் மன்னிக்கிறவர்; குற்றவாளியைக் குற்றமற்றவனாக விடாமல், பிதாக்கள் செய்த அக்கிரமத்தைப் பிள்ளைகளிடத்திலும், பிள்ளைகளுடைய பிள்ளைகளிடத்திலும் மூன்றாம் நான்காம் தலைமுறைமட்டும் விசாரிக்கிறவர் என்று கூறினார்.',	2,	34,	7),
(2505,	'And Moses made haste, and bowed his head toward the earth, and worshipped.',	'மோசே தீவிரமாகத் தரைமட்டும் குனிந்து பணிந்துகொண்டு:',	2,	34,	8),
(2506,	'And he said, If now I have found grace in thy sight, O LORD, let my LORD, I pray thee, go among us; for it is a stiffnecked people; and pardon our iniquity and our sin, and take us for thine inheritance.',	'ஆண்டவரே, உம்முடைய கண்களில் எனக்குக் கிருபை கிடைத்ததானால், எங்கள் நடுவில் ஆண்டவர் எழுந்தருளவேண்டும்; இந்த ஜனங்கள் வணங்காக்கழுத்துள்ளவர்கள்; நீரோ, எங்கள் அக்கிரமத்தையும் எங்கள் பாவத்தையும் மன்னித்து, எங்களை உமக்குச் சுதந்தரமாக ஏற்றுக்கொள்ளும் என்றான்.',	2,	34,	9),
(2507,	'And he said, Behold, I make a covenant: before all thy people I will do marvels, such as have not been done in all the earth, nor in any nation: and all the people among which thou art shall see the work of the LORD: for it is a terrible thing that I will do with thee.',	'அதற்கு அவர்: இதோ, நான் ஒரு உடன்படிக்கைபண்ணுகிறேன்; பூமியெங்கும் எந்த ஜாதிகளிடத்திலும் செய்யப்படாத அதிசயங்களை உன் ஜனங்கள் எல்லாருக்கு முன்பாகவும் செய்வேன்; உன்னோடேகூட இருக்கிற ஜனங்கள் எல்லாரும் கர்த்தருடைய செய்கையைக் காண்பார்கள்; உன்னோடேகூட இருந்து, நான் செய்யும் காரியம் பயங்கரமாயிருக்கும்.',	2,	34,	10),
(2508,	'Observe thou that which I command thee this day: behold, I drive out before thee the Amorite, and the Canaanite, and the Hittite, and the Perizzite, and the Hivite, and the Jebusite.',	'இன்று நான் உனக்குக் கட்டளையிடுகிறதைக் கைக்கொள்; எமோரியனையும், கானானியனையும், ஏத்தியனையும், பெரிசியனையும், ஏவியனையும், எபூசியனையும் உனக்கு முன்பாகத் துரத்திவிடுகிறேன்.',	2,	34,	11),
(2509,	'Take heed to thyself, lest thou make a covenant with the inhabitants of the land whither thou goest, lest it be for a snare in the midst of thee:',	'நீ போய்ச் சேருகிற தேசத்தின் குடிகளோடு உடன்படிக்கைபண்ணாதபடிக்கு எச்சரிக்கையாயிரு; பண்ணினால் அது உன் நடுவில் கண்ணியாயிருக்கும்.',	2,	34,	12),
(2510,	'But ye shall destroy their altars, break their images, and cut down their groves:',	'அவர்களுடைய பலிபீடங்களை இடித்து, அவர்கள் சிலைகளைத் தகர்த்து, அவர்கள் தோப்புகளை வெட்டிப்போடுங்கள்.',	2,	34,	13),
(2511,	'For thou shalt worship no other god: for the LORD, whose name is Jealous, is a jealous God:',	'கர்த்தருடைய நாமம் எரிச்சலுள்ளவர் என்பது, அவர் எரிச்சலுள்ள தேவனே; ஆகையால், அந்நிய தேவனை நீ பணிந்துகொள்ளவேண்டாம்.',	2,	34,	14),
(2512,	'Lest thou make a covenant with the inhabitants of the land, and they go a whoring after their gods, and do sacrifice unto their gods, and one call thee, and thou eat of his sacrifice;',	'அந்தத் தேசத்தின் குடிகளோடே உடன்படிக்கைபண்ணுவாயானால், அவர்கள் தங்கள் தேவர்களைச் சோரமார்க்கமாய்ப் பின்பற்றி, தங்களுடைய தேவர்களுக்குப் பலியிடுவார்கள்; ஒருவன் உன்னை அழைக்கையில், நீ போய், அவன் பலியிட்டதிலே புசிப்பாய்;',	2,	34,	15),
(2513,	'And thou take of their daughters unto thy sons, and their daughters go a whoring after their gods, and make thy sons go a whoring after their gods.',	'அவர்கள் குமாரத்திகளில் உன் குமாரருக்குப் பெண்களைக் கொள்ளுவாய்; அவர்கள் குமாரத்திகள் தங்கள் தேவர்களைச் சோரமார்க்கமாய்ப் பின்பற்றுவதும் அல்லாமல், உன் குமாரரையும் தங்கள் தேவர்களைச் சோரமார்க்கமாய்ப் பின்பற்றும்படி செய்வார்கள்.',	2,	34,	16),
(2514,	'Thou shalt make thee no molten gods.',	'வார்ப்பிக்கப்பட்ட தெய்வங்களை உங்களுக்கு உண்டாக்கவேண்டாம்.',	2,	34,	17),
(2515,	'The feast of unleavened bread shalt thou keep. Seven days thou shalt eat unleavened bread, as I commanded thee, in the time of the month Abib: for in the month Abib thou camest out from Egypt.',	'புளிப்பில்லா அப்பப்பண்டிகையை நீங்கள் கைக்கொண்டு, நான் உங்களுக்குக் கட்டளையிட்டபடியே, ஆபீப் மாதத்தில் குறித்த காலத்திலே ஏழுநாள் புளிப்பில்லா அப்பம் புசிக்கக்கடவீர்கள்; ஆபீப் மாதத்திலே எகிப்திலிருந்து புறப்பட்டாயே.',	2,	34,	18),
(2516,	'All that openeth the matrix is mine; and every firstling among thy cattle, whether ox or sheep, that is male.',	'கர்ப்பந்திறந்து பிறக்கிற யாவும், உன் ஆடுமாடுகளின் தலையீற்றான ஆண்கள் யாவும் என்னுடையவைகள்.',	2,	34,	19),
(2517,	'But the firstling of an ass thou shalt redeem with a lamb: and if thou redeem him not, then shalt thou break his neck. All the firstborn of thy sons thou shalt redeem. And none shall appear before me empty.',	'கழுதையின் தலையீற்றை ஒரு ஆட்டுக்குட்டியால் மீட்டுக்கொள்வாயாக; அதை மீட்டுக்கொள்ளாதிருந்தால் அதின் கழுத்தை முறித்துப்போடு; உன் பிள்ளைகளில் முதற்பேறானவைகளையெல்லாம் மீட்டுக்கொள்ளவேண்டும். வெறுங்கையோடே என் சந்நிதியில் ஒருவனும் வரக்கூடாது.',	2,	34,	20),
(2518,	'Six days thou shalt work, but on the seventh day thou shalt rest: in earing time and in harvest thou shalt rest.',	'ஆறுநாள் வேலைசெய்து, ஏழாம் நாளிலே ஓய்ந்திருப்பாயாக; விதைப்புக் காலத்திலும் அறுப்புக் காலத்திலும் ஓய்ந்திருப்பாயாக.',	2,	34,	21),
(2519,	'And thou shalt observe the feast of weeks, of the firstfruits of wheat harvest, and the feast of ingathering at the year\'s end.',	'கோதுமை அறுப்பின் முதற்பலனைச் செலுத்தும் ஏழு வாரங்களின் பண்டிகையையும், வருஷமுடிவிலே சேர்ப்புக்கால பண்டிகையையும் ஆசரிப்பாயாக.',	2,	34,	22),
(2520,	'Thrice in the year shall all your menchildren appear before the LORD God, the God of Israel.',	'வருஷத்தில் மூன்றுதரம் உங்கள் ஆண்மக்கள் எல்லாரும் இஸ்ரவேலின் தேவனாயிருக்கிற கர்த்தராகிய ஆண்டவரின் சந்நிதியில் வரக்கடவர்கள்.',	2,	34,	23),
(2521,	'For I will cast out the nations before thee, and enlarge thy borders: neither shall any man desire thy land, when thou shalt go up to appear before the LORD thy God thrice in the year.',	'நான் புறஜாதிகளை உங்கள் முன்னின்று துரத்திவிட்டு, உங்கள் எல்லைகளை விஸ்தாரமாக்குவேன்; வருஷத்தில் மூன்றுதரம் உங்கள் தேவனாகிய கர்த்தருடைய சந்நிதிக்கு முன்பாகக் காணப்படப் போயிருக்கும்போது ஒருவரும் உங்கள் தேசத்தை இச்சிப்பதில்லை.',	2,	34,	24),
(2522,	'Thou shalt not offer the blood of my sacrifice with leaven; neither shall the sacrifice of the feast of the passover be left unto the morning.',	'எனக்கு இடும் பலியின் இரத்தத்தைப் புளித்தமாவுடன் செலுத்தவேண்டாம்; பஸ்கா பண்டிகையின் பலியை விடியற்காலம்வரைக்கும் வைக்கவும் வேண்டாம்.',	2,	34,	25),
(2523,	'The first of the firstfruits of thy land thou shalt bring unto the house of the LORD thy God. Thou shalt not seethe a kid in his mother\'s milk.',	'உங்கள் நிலத்தில் முதல் முதல் விளைந்த முதற்பலத்தை உங்கள் தேவனாகிய கர்த்தரின் ஆலயத்துக்குக் கொண்டுவாருங்கள். வெள்ளாட்டுக்குட்டியை அதின் தாயின் பாலிலே சமைக்கவேண்டாம் என்றார்.',	2,	34,	26),
(2524,	'And the LORD said unto Moses, Write thou these words: for after the tenor of these words I have made a covenant with thee and with Israel.',	'பின்னும் கர்த்தர் மோசேயை நோக்கி: இந்த வார்த்தைகளை நீ எழுது; இந்த வார்த்தைகளின்படியே உன்னோடும் இஸ்ரவேலோடும் உடன்படிக்கைபண்ணினேன் என்றார்.',	2,	34,	27),
(2525,	'And he was there with the LORD forty days and forty nights; he did neither eat bread, nor drink water. And he wrote upon the tables the words of the covenant, the ten commandments.',	'அங்கே அவன் அப்பம் புசியாமலும் தண்ணீர் குடியாமலும் இரவும் பகலும் நாற்பதுநாள் கர்த்தரோடே இருந்தான்; அவன் பத்துக்கற்பனைகளாகிய உடன்படிக்கையின் வார்த்தைகளைப் பலகைகளில் எழுதினான்.',	2,	34,	28),
(2526,	'And it came to pass, when Moses came down from mount Sinai with the two tables of testimony in Moses\' hand, when he came down from the mount, that Moses wist not that the skin of his face shone while he talked with him.',	'மோசே சாட்சிப் பலகைகள் இரண்டையும் தன் கையில் எடுத்துக்கொண்டு, சீனாய் மலையிலிருந்து இறங்குகிறபோது, தன்னோடே அவர் பேசினதினாலே தன் முகம் பிரகாசித்திருப்பதை அவன் அறியாதிருந்தான்.',	2,	34,	29),
(2527,	'And when Aaron and all the children of Israel saw Moses, behold, the skin of his face shone; and they were afraid to come nigh him.',	'ஆரோனும் இஸ்ரவேல் புத்திரர் எல்லாரும் மோசேயைப் பார்க்கும்போது, அவன் முகம் பிரகாசித்திருப்பதைக் கண்டு, அவன் சமீபத்தில் சேரப்பயந்தார்கள்.',	2,	34,	30),
(2528,	'And Moses called unto them; and Aaron and all the rulers of the congregation returned unto him: and Moses talked with them.',	'மோசே அவர்களை அழைத்தான்; அப்பொழுது ஆரோனும் சபையிலுள்ள பிரபுக்கள் யாவரும் அவனிடத்திற்குத் திரும்பி வந்தார்கள்; மோசே அவர்களோடே பேசினான்.',	2,	34,	31),
(2529,	'And afterward all the children of Israel came nigh: and he gave them in commandment all that the LORD had spoken with him in mount Sinai.',	'பின்பு இஸ்ரவேல் புத்திரர் எல்லாரும் அவனிடத்தில் சேர்ந்தார்கள்; அப்பொழுது அவன் சீனாய் மலையில் கர்த்தர் தன்னோடே பேசினவைகளையெல்லாம் அவர்களுக்குக் கற்பித்தான்.',	2,	34,	32),
(2530,	'And till Moses had done speaking with them, he put a vail on his face.',	'மோசே அவர்களோடே பேசி முடியுமளவும், தன் முகத்தின்மேல் முக்காடு போட்டிருந்தான்.',	2,	34,	33),
(2531,	'But when Moses went in before the LORD to speak with him, he took the vail off, until he came out. And he came out, and spake unto the children of Israel that which he was commanded.',	'மோசே கர்த்தருடைய சந்நிதியில் அவரோடே பேசும்படிக்கு உட்பிரவேசித்ததுமுதல் வெளியே புறப்படும்மட்டும் முக்காடு போடாதிருந்தான்; அவன் வெளியே வந்து தனக்குக் கற்பிக்கப்பட்டதை இஸ்ரவேல் புத்திரரோடே சொல்லும்போது,',	2,	34,	34),
(2532,	'And the children of Israel saw the face of Moses, that the skin of Moses\' face shone: and Moses put the vail upon his face again, until he went in to speak with him.',	'இஸ்ரவேல் புத்திரர் அவன் முகம் பிரகாசித்திருப்பதைக் கண்டார்கள். மோசே அவரோடே பேசும்படிக்கு உள்ளே பிரவேசிக்கும்வரைக்கும், முக்காட்டைத் திரும்பத் தன் முகத்தின்மேல் போட்டுக்கொள்ளுவான்.  ',	2,	34,	35),
(2533,	'And Moses gathered all the congregation of the children of Israel together, and said unto them, These are the words which the LORD hath commanded, that ye should do them.',	'மோசே இஸ்ரவேல், புத்திரராகிய சபையார் எல்லாரையும் கூடிவரச்செய்து, அவர்களை நோக்கி:',	2,	35,	1),
(2534,	'Six days shall work be done, but on the seventh day there shall be to you an holy day, a sabbath of rest to the LORD: whosoever doeth work therein shall be put to death.',	'நீங்கள் ஆறுநாள் வேலைசெய்யவேண்டும், ஏழாம் நாளோ உங்களுக்குப் பரிசுத்த நாளாய் இருப்பதாக; அது கர்த்தருக்கென்று ஓய்ந்திருக்கும் ஓய்வுநாள்; அதிலே வேலைசெய்கிறவன் எவனும் கொலைசெய்யப்படக்கடவன்.',	2,	35,	2),
(2535,	'Ye shall kindle no fire throughout your habitations upon the sabbath day.',	'ஓய்வுநாளில் உங்கள் வாசஸ்தலங்களில் எங்கும் நெருப்பு மூட்டாதிருப்பீர்களாக என்னும் இவ்வார்த்தைகளைக் கைக்கொள்ளும்படி கர்த்தர் கட்டளையிட்டார் என்றான்.',	2,	35,	3),
(2536,	'And Moses spake unto all the congregation of the children of Israel, saying, This is the thing which the LORD commanded, saying,',	'பின்னும் மோசே இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரையும் நோக்கி:',	2,	35,	4),
(2537,	'Take ye from among you an offering unto the LORD: whosoever is of a willing heart, let him bring it, an offering of the LORD; gold, and silver, and brass,',	'உங்களுக்கு உண்டானதிலே கர்த்தருக்கு ஒரு காணிக்கையைக் கொண்டுவந்து செலுத்துங்கள்; மனமுள்ளவன் எவனோ, அவன் அதைக் கொண்டுவரட்டும்; கர்த்தருக்குச் செலுத்தும் காணிக்கை என்னவென்றால், பொன்னும், வெள்ளியும், வெண்கலமும்,',	2,	35,	5),
(2538,	'And blue, and purple, and scarlet, and fine linen, and goats\' hair,',	'இளநீலநூலும், இரத்தாம்பரநூலும், சிவப்புநூலும், மெல்லிய பஞ்சுநூலும், வெள்ளாட்டு மயிரும்,',	2,	35,	6),
(2539,	'And rams\' skins dyed red, and badgers\' skins, and shittim wood,',	'சிவப்புத்தீர்ந்த ஆட்டுக்கடாத்தோலும், தகசுத்தோலும், சீத்திம் மரமும்,',	2,	35,	7),
(2540,	'And oil for the light, and spices for anointing oil, and for the sweet incense,',	'விளக்குக்கு எண்ணெயும், அபிஷேக தைலத்துக்குப் பரிமளவர்க்கங்களும், தூபத்துக்குச் சுகந்தவர்க்கங்களும்,',	2,	35,	8),
(2541,	'And onyx stones, and stones to be set for the ephod, and for the breastplate.',	'ஆசாரியருடைய ஏபோத்திலும் மார்ப்பதக்கத்திலும் பதிக்கத்தக்க கோமேதகம் முதலிய இரத்தினங்களுமே.',	2,	35,	9),
(2542,	'And every wise hearted among you shall come, and make all that the LORD hath commanded;',	'உங்களில் ஞானஇருதயமுள்ள அனைவரும் வந்து, கர்த்தர் கட்டளையிட்டவைகளையெல்லாம் செய்வார்களாக.',	2,	35,	10),
(2543,	'The tabernacle, his tent, and his covering, his taches, and his boards, his bars, his pillars, and his sockets,',	'வாசஸ்தலத்தையும், அதின் கூடாரத்தையும், அதின் மூடியையும், அதின் கொக்கிகளையும், அதின் பலகைகளையும், அதின் தாழ்ப்பாள்களையும், அதின் தூண்களையும், அதின் பாதங்களையும்,',	2,	35,	11),
(2544,	'The ark, and the staves thereof, with the mercy seat, and the vail of the covering,',	'பெட்டியையும், அதின் தண்டுகளையும், கிருபாசனத்தையும், மறைவின் திரைச்சீலையையும்,',	2,	35,	12),
(2545,	'The table, and his staves, and all his vessels, and the shewbread,',	'மேஜையையும், அதின் தண்டுகளையும், அதின் சகல பணிமுட்டுகளையும், சமுகத்தப்பங்களையும்,',	2,	35,	13),
(2546,	'The candlestick also for the light, and his furniture, and his lamps, with the oil for the light,',	'வெளிச்சங்கொடுக்கும் குத்துவிளக்கையும், அதின் கருவிகளையும், அதின் அகல்களையும், வெளிச்சத்துக்கு எண்ணெயையும்,',	2,	35,	14),
(2547,	'And the incense altar, and his staves, and the anointing oil, and the sweet incense, and the hanging for the door at the entering in of the tabernacle,',	'தூபபீடத்தையும், அதின் தண்டுகளையும், அபிஷேகதைலத்தையும், சுகந்த தூபவர்க்கத்தையும், வாசஸ்தலத்தின் வாசலுக்குத் தொங்குதிரையையும்,',	2,	35,	15),
(2548,	'The altar of burnt offering, with his brasen grate, his staves, and all his vessels, the laver and his foot,',	'தகனபலிபீடத்தையும், அதின் வெண்கலச் சல்லடையையும், அதின் தண்டுகளையும், அதின் சகல பணிமுட்டுகளையும், தொட்டியையும், அதின் பாதத்தையும்,',	2,	35,	16),
(2549,	'The hangings of the court, his pillars, and their sockets, and the hanging for the door of the court,',	'பிராகாரத்தின் தொங்குதிரைகளையும், அதின் தூண்களையும், அதின் பாதங்களையும், பிராகாரத்து வாசலின் தொங்குதிரையையும்,',	2,	35,	17),
(2550,	'The pins of the tabernacle, and the pins of the court, and their cords,',	'வாசஸ்தலத்தின் முளைகளையும், பிராகாரத்தின் முளைகளையும், அவைகளின் கயிறுகளையும்,',	2,	35,	18),
(2551,	'The cloths of service, to do service in the holy place, the holy garments for Aaron the priest, and the garments of his sons, to minister in the priest\'s office.',	'பரிசுத்த ஸ்தலத்திலே ஆராதனை செய்வதற்குரிய வஸ்திரங்களையும், ஆசாரிய ஊழியஞ்செய்கிற ஆரோனின் பரிசுத்த வஸ்திரங்களையும் அவன் குமாரரின் வஸ்திரங்களையும் அவர்கள் செய்யக்கடவர்கள் என்றான்.',	2,	35,	19),
(2552,	'And all the congregation of the children of Israel departed from the presence of Moses.',	'அப்பொழுது இஸ்ரவேல் புத்திரராகிய சபையார் எல்லாரும் மோசேயின் சமுகத்தைவிட்டுப் புறப்பட்டார்கள்.',	2,	35,	20),
(2553,	'And they came, every one whose heart stirred him up, and every one whom his spirit made willing, and they brought the LORD\'s offering to the work of the tabernacle of the congregation, and for all his service, and for the holy garments.',	'பின்பு எவர்களை அவர்கள் இருதயம் எழுப்பி, எவர்களை அவர்கள் ஆவி உற்சாகப்படுத்தினதோ, அவர்கள் எல்லாரும் ஆசரிப்புக் கூடாரத்தின் வேலைக்கும், அதின் சகல ஊழியத்துக்கும், பரிசுத்த வஸ்திரங்களுக்கும் ஏற்றவைகளைக் கர்த்தருக்குக் காணிக்கையாகக் கொண்டுவந்தார்கள்.',	2,	35,	21),
(2554,	'And they came, both men and women, as many as were willing hearted, and brought bracelets, and earrings, and rings, and tablets, all jewels of gold: and every man that offered offered an offering of gold unto the LORD.',	'மனப்பூர்வமுள்ள ஸ்திரீ புருஷர் யாவரும், அஸ்தகடகங்கள், காதணிகள், மோதிரங்கள், ஆரங்கள் முதலான சகலவித பொன்னாபரணங்களையும் கொண்டு வந்தார்கள்; கர்த்தருக்குக் காணிக்கை செலுத்தின ஒவ்வொருவனும் பொன்னைக் காணிக்கையாகச் செலுத்தினான்.',	2,	35,	22),
(2555,	'And every man, with whom was found blue, and purple, and scarlet, and fine linen, and goats\' hair, and red skins of rams, and badgers\' skins, brought them.',	'இளநீலநூலையும் இரத்தாம்பரநூலையும் சிவப்புநூலையும் மெல்லிய பஞ்சுநூலையும் வெள்ளாட்டு மயிரையும் சிவப்புத்தீர்ந்த ஆட்டுக்கடாத்தோலையும் தகசுத்தோலையும் தங்களிடத்தில் வைத்திருந்த யாவரும் அவைகளைக் கொண்டுவந்தார்கள்.',	2,	35,	23),
(2556,	'Every one that did offer an offering of silver and brass brought the LORD\'s offering: and every man, with whom was found shittim wood for any work of the service, brought it.',	'வெள்ளியையும் வெண்கலத்தையும் கொடுக்கத்தக்க யாவரும் அவைகளைக் கர்த்தருக்குக் காணிக்கையாகக் கொண்டு வந்தார்கள். பற்பல வேலைகளுக்கு உதவும் சீத்திம் மரத்தைத் தங்களிடத்தில் வைத்திருந்த யாவரும் அவைகளைக் கொண்டுவந்தார்கள்.',	2,	35,	24),
(2557,	'And all the women that were wise hearted did spin with their hands, and brought that which they had spun, both of blue, and of purple, and of scarlet, and of fine linen.',	'ஞான இருதயமுள்ள ஸ்திரீகள் எல்லாரும் தங்கள் கைகளினால் நூற்று, தாங்கள் நூற்ற இளநீலநூலையும் இரத்தாம்பரநூலையும் சிவப்புநூலையும் மெல்லிய பஞ்சுநூலையும் கொண்டுவந்தார்கள்.',	2,	35,	25),
(2558,	'And all the women whose heart stirred them up in wisdom spun goats\' hair.',	'எந்த ஸ்திரீகளுடைய இருதயம் ஞான எழுப்புதல் அடைந்ததோ, அவர்கள் எல்லாரும் வெள்ளாட்டு மயிரைத்திரித்தார்கள்.',	2,	35,	26),
(2559,	'And the rulers brought onyx stones, and stones to be set, for the ephod, and for the breastplate;',	'பிரபுக்கள் ஏபோத்திலும் மார்ப்பதக்கத்திலும் பதிக்கும் கோமேதகம் முதலிய இரத்தினங்களையும்,',	2,	35,	27),
(2560,	'And spice, and oil for the light, and for the anointing oil, and for the sweet incense.',	'பரிமளவர்க்கங்களையும், விளக்கெண்ணெயையும், அபிஷேகதைலத்துக்கும் சுகந்தவர்க்க தூபத்துக்கும் வேண்டியவைகளையும் கொண்டுவந்தார்கள்.',	2,	35,	28),
(2561,	'The children of Israel brought a willing offering unto the LORD, every man and woman, whose heart made them willing to bring for all manner of work, which the LORD had commanded to be made by the hand of Moses.',	'செய்யப்படும்படி கர்த்தர் மோசேயைக்கொண்டு கற்பித்த வேலைக்குரிய யாவையும் கொண்டுவர, இஸ்ரவேல் புத்திரருக்குள் தங்கள் இருதயத்தில் உற்சாகமடைந்த ஸ்திரீ புருஷர் யாவரும் கர்த்தருக்குக் காணிக்கையை மனப்பூர்வமாய்க் கொண்டுவந்தார்கள்.',	2,	35,	29),
(2562,	'And Moses said unto the children of Israel, See, the LORD hath called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah;',	'பின்பு மோசே இஸ்ரவேல் புத்திரரை நோக்கி: பாருங்கள், கர்த்தர் யூதாவின் கோத்திரத்தில் ஊரின் மகனான ஊரியின் குமாரன் பெசலெயேலைப் பேர்சொல்லி அழைத்து,',	2,	35,	30),
(2563,	'And he hath filled him with the spirit of God, in wisdom, in understanding, and in knowledge, and in all manner of workmanship;',	'அவன் விசித்திரமான வேலைகளை யோசித்துச் செய்யவும், பொன்னிலும் வெள்ளியிலும் வெண்கலத்திலும் வேலை செய்யவும்,',	2,	35,	31),
(2564,	'And to devise curious works, to work in gold, and in silver, and in brass,',	'இரத்தினங்களை முத்திரை வெட்டாக வெட்டிப் பதிக்கவும், மரத்தில் சித்திரவேலை செய்து சகல விநோதமான வேலைகளைச் செய்யவும்,',	2,	35,	32),
(2565,	'And in the cutting of stones, to set them, and in carving of wood, to make any manner of cunning work.',	'அவனுக்கு ஞானத்தையும் புத்தியையும் அறிவையும் அருளி, அவன் சகலவித வேலைகளையும் செய்யும்படி தேவஆவியினாலே அவனை நிரப்பினார்.',	2,	35,	33),
(2566,	'And he hath put in his heart that he may teach, both he, and Aholiab, the son of Ahisamach, of the tribe of Dan.',	'அவன் இருதயத்திலும், தாண் கோத்திரத்து அகிசாமாகின் குமாரனாகிய அகோலியாபின் இருதயத்திலும், போதிக்கும் வரத்தையும் அருளினார்.',	2,	35,	34),
(2567,	'Them hath he filled with wisdom of heart, to work all manner of work, of the engraver, and of the cunning workman, and of the embroiderer, in blue, and in purple, in scarlet, and in fine linen, and of the weaver, even of them that do any work, and of those that devise cunning work.',	'சித்திரவேலையையும் சிற்பவேலையையும், இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் மெல்லிய பஞ்சுநூலாலும் செய்யப்படும் விசித்திரத் தையல்வேலையையும், சகல விசித்திர நெசவு வேலைகளையும் விநோதமான வேலைகளை யூகிக்கிறவர்களும் செய்கிறவர்களும் நிறைவேற்றும் சகலவித வேலைகளையும் செய்யும்படிக்கு அவர்களுடைய இருதயத்தை ஞானத்தினால் நிரப்பினார் என்றான்.  ',	2,	35,	35),
(2568,	'Then wrought Bezaleel and Aholiab, and every wise hearted man, in whom the LORD put wisdom and understanding to know how to work all manner of work for the service of the sanctuary, according to all that the LORD had commanded.',	'அப்பொழுது பரிசுத்த ஸ்தலத்துத் திருப்பணிகளுக்கடுத்த சகல வேலைகளையும், கர்த்தர் கற்பித்தபடியெல்லாம், பெசலெயேலும் அகோலியாபும், செய்ய அறியும்படிக்குக் கர்த்தரால் ஞானமும் புத்தியும் பெற்ற விவேக இருதயமுள்ள மற்ற அனைவரும் செய்யத்தொடங்கினார்கள்.',	2,	36,	1),
(2569,	'And Moses called Bezaleel and Aholiab, and every wise hearted man, in whose heart the LORD had put wisdom, even every one whose heart stirred him up to come unto the work to do it:',	'பெசலெயேலையும் அகோலியாபையும், கர்த்தரால் ஞானமடைந்து அந்த வேலைகளைச் செய்யவரும்படி தங்கள் இருதயத்தில் எழுப்புதலடைந்த ஞான இருதயத்தாராகிய எல்லாரையும், மோசே வரவழைத்தான்.',	2,	36,	2),
(2570,	'And they received of Moses all the offering, which the children of Israel had brought for the work of the service of the sanctuary, to make it withal. And they brought yet unto him free offerings every morning.',	'அவர்கள், இஸ்ரவேல் புத்திரர் திருப்பணிக்கடுத்த சகல வேலைகளுக்காகவும் கொண்டுவந்த காணிக்கைப் பொருள்களையெல்லாம், மோசேயினிடத்தில் வாங்கிக்கொண்டார்கள். பின்னும் ஜனங்கள் காலைதோறும் தங்களுக்கு இஷ்டமான காணிக்கைகளை அவனிடத்தில் கொண்டுவந்தார்கள்.',	2,	36,	3),
(2571,	'And all the wise men, that wrought all the work of the sanctuary, came every man from his work which they made;',	'அப்பொழுது பரிசுத்த ஸ்தலத்து வேலைகளைச் செய்கிற விவேகிகள் யாவரும் அவரவர் செய்கிற வேலையின் காரியமாய் வந்து,',	2,	36,	4),
(2572,	'And they spake unto Moses, saying, The people bring much more than enough for the service of the work, which the LORD commanded to make.',	'மோசேயை நோக்கி: கர்த்தர் செய்யும்படி கற்பித்த வேலைக்கு வேண்டியதற்கு அதிகமான பொருள்களை ஜனங்கள் கொண்டுவருகிறார்கள் என்றார்கள்.',	2,	36,	5),
(2573,	'And Moses gave commandment, and they caused it to be proclaimed throughout the camp, saying, Let neither man nor woman make any more work for the offering of the sanctuary. So the people were restrained from bringing.',	'அப்பொழுது மோசே இனி புருஷர்களாவது ஸ்திரீகளாவது பரிசுத்த ஸ்தலத்துக்கென்று காணிக்கையாக ஒரு வேலையும் செய்யவேண்டாம் என்று பாளயம் எங்கும் கூறும்படி கட்டளையிட்டான்; இவ்விதமாய் ஜனங்கள் கொண்டுவருகிறது நிறுத்தப்பட்டது.',	2,	36,	6),
(2574,	'For the stuff they had was sufficient for all the work to make it, and too much.',	'செய்யவேண்டிய எல்லா வேலைகளுக்கும் போதுமான பொருள்கள் இருந்ததுமல்லாமல் அதிகமாயும் இருந்தது.',	2,	36,	7),
(2575,	'And every wise hearted man among them that wrought the work of the tabernacle made ten curtains of fine twined linen, and blue, and purple, and scarlet: with cherubims of cunning work made he them.',	'வேலைசெய்கிறவர்களாகிய ஞான இருதயமுள்ள யாவரும் வாசஸ்தலத்தை உண்டாக்கினார்கள். அதற்குத் திரித்த மெல்லிய பஞ்சுநூலாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும், விநோத நெசவுவேலையாகிய கேருபீன்களுள்ள பத்து மூடுதிரைகளைப் பண்ணினான்.',	2,	36,	8),
(2576,	'The length of one curtain was twenty and eight cubits, and the breadth of one curtain four cubits: the curtains were all of one size.',	'ஒவ்வொரு மூடுதிரை இருபத்தெட்டு முழ நீளமும் நாலு முழ அகலமுமாயிருந்தது; மூடுதிரைகளெல்லாம் ஒரே அளவாயிருந்தது.',	2,	36,	9),
(2577,	'And he coupled the five curtains one unto another: and the other five curtains he coupled one unto another.',	'ஐந்து மூடுதிரைகளை ஒன்றோடொன்று இணைத்து, மற்ற ஐந்து மூடுதிரைகளையும் ஒன்றோடொன்று இணைத்தான்.',	2,	36,	10),
(2578,	'And he made loops of blue on the edge of one curtain from the selvedge in the coupling: likewise he made in the uttermost side of another curtain, in the coupling of the second.',	'இணைக்கப்பட்ட ஒரு மூடுதிரையின் ஓரத்தில் இளநீலநூலால் ஐம்பது காதுகளை உண்டுபண்ணி, அப்படியே இணைக்கப்பட்ட மற்ற மூடுதிரையின் ஓரத்திலும் உண்டுபண்ணினான்.',	2,	36,	11),
(2579,	'Fifty loops made he in one curtain, and fifty loops made he in the edge of the curtain which was in the coupling of the second: the loops held one curtain to another.',	'காதுகள் ஒன்றோடொன்று இணைக்கப்பட்டவைகளாயிருந்தது.',	2,	36,	12),
(2580,	'And he made fifty taches of gold, and coupled the curtains one unto another with the taches: so it became one tabernacle.',	'ஐம்பது பொன் கொக்கிகளையும் பண்ணி, அந்தக் கொக்கிகளால் மூடுதிரைகளை ஒன்றோடொன்று இணைத்துவிட்டான். இவ்விதமாக ஒரே வாசஸ்தலமாயிற்று.',	2,	36,	13),
(2581,	'And he made curtains of goats\' hair for the tent over the tabernacle: eleven curtains he made them.',	'வாசஸ்தலத்தின்மேல் கூடாரமாகப் போடும்படி ஆட்டுமயிரினால் நெய்த பதினொரு மூடுதிரைகளையும் பண்ணினான்.',	2,	36,	14),
(2582,	'The length of one curtain was thirty cubits, and four cubits was the breadth of one curtain: the eleven curtains were of one size.',	'ஒவ்வொரு மூடுதிரை முப்பது முழ நீளமும் நாலு முழ அகலமுமாயிருந்தது. பதினொரு மூடுதிரைகளும் ஒரே அளவாயிருந்தது.',	2,	36,	15),
(2583,	'And he coupled five curtains by themselves, and six curtains by themselves.',	'ஐந்து மூடுதிரைகளை ஒன்றாகவும், மற்ற ஆறு மூடுதிரைகளை ஒன்றாகவும் இணைத்து,',	2,	36,	16),
(2584,	'And he made fifty loops upon the uttermost edge of the curtain in the coupling, and fifty loops made he upon the edge of the curtain which coupleth the second.',	'இணைக்கப்பட்ட ஒரு மூடுதிரையின் ஓரத்தில் ஐம்பது காதுகளையும், இணைக்கப்பட்ட மற்ற மூடுதிரையின் ஓரத்தில் ஐம்பது காதுகளையும் உண்டாக்கி,',	2,	36,	17),
(2585,	'And he made fifty taches of brass to couple the tent together, that it might be one.',	'கூடாரத்தை ஒன்றாய் இணைத்துவிட, ஐம்பது வெண்கலக் கொக்கிகளையும் உண்டாக்கினான்.',	2,	36,	18),
(2586,	'And he made a covering for the tent of rams\' skins dyed red, and a covering of badgers\' skins above that.',	'சிவப்புத்தீர்ந்த ஆட்டுக்கடாத்தோலினால் கூடாரத்துக்கு ஒரு மூடியையும் அதின்மேல் போடத் தகசுத்தோலினால் ஒரு மூடியையும் உண்டுபண்ணினான்.',	2,	36,	19),
(2587,	'And he made boards for the tabernacle of shittim wood, standing up.',	'வாசஸ்தலத்துக்கு நிமிர்ந்துநிற்கும் பலகைகளையும் சீத்திம் மரத்தால் செய்தான்.',	2,	36,	20),
(2588,	'The length of a board was ten cubits, and the breadth of a board one cubit and a half.',	'ஒவ்வொரு பலகையும் பத்துமுழ நீளமும் ஒன்றரைமுழ அகலமுமாயிருந்தது.',	2,	36,	21),
(2589,	'One board had two tenons, equally distant one from another: thus did he make for all the boards of the tabernacle.',	'ஒவ்வொரு பலகைக்கும் ஒன்றுக்கொன்று சமதூரமான இரண்டு கழுந்துகள் இருந்தது; வாசஸ்தலத்தின் பலகைகளுக்கெல்லாம் இப்படியே செய்தான்.',	2,	36,	22),
(2590,	'And he made boards for the tabernacle; twenty boards for the south side southward:',	'வாசஸ்தலத்திற்காகச் செய்யப்பட்ட பலகைகளில் தெற்கே தென்திசைக்கு இருபது பலகைகளை உண்டாக்கி,',	2,	36,	23),
(2591,	'And forty sockets of silver he made under the twenty boards; two sockets under one board for his two tenons, and two sockets under another board for his two tenons.',	'அந்த இருபது பலகைகளின் கீழே வைக்கும் நாற்பது வெள்ளிப் பாதங்களையும் உண்டுபண்ணினான்; ஒரு பலகையின் கீழ் அதின் இரண்டு கழுந்துகளுக்கும் இரண்டு பாதங்களையும், மற்றப் பலகையின்கீழ் அதின் இரண்டு கழுந்துகளுக்கும் இரண்டு பாதங்களையும் பண்ணிவைத்து;',	2,	36,	24),
(2592,	'And for the other side of the tabernacle, which is toward the north corner, he made twenty boards,',	'வாசஸ்தலத்தின் மறுபக்கமாகிய வடபுறத்தில் இருபது பலகைகளையும், அவைகளுக்கு நாற்பது வெள்ளிப்பாதங்களையும் செய்தான்.',	2,	36,	25),
(2593,	'And their forty sockets of silver; two sockets under one board, and two sockets under another board.',	'ஒரு பலகையின்கீழ் இரண்டு பாதங்களும், மற்றப் பலகையின்கீழ் இரண்டு பாதங்களும் செய்தான்.',	2,	36,	26),
(2594,	'And for the sides of the tabernacle westward he made six boards.',	'வாசஸ்தலத்தின் மேல்புறத்திற்கு ஆறு பலகைகளையும்,',	2,	36,	27),
(2595,	'And two boards made he for the corners of the tabernacle in the two sides.',	'வாசஸ்தலத்தின் இருபக்கங்களிலுள்ள மூலைகளுக்கு இரண்டு பலகைகளையும் செய்தான்.',	2,	36,	28),
(2596,	'And they were coupled beneath, and coupled together at the head thereof, to one ring: thus he did to both of them in both the corners.',	'அவைகள் கீழே இசைக்கப்பட்டிருந்தது, மேலேயும் ஒரு வளையத்தினால் இசைக்கப்பட்டிருந்தது; இரண்டு மூலைகளிலுமுள்ள அவ்விரண்டிற்கும் அப்படியே செய்தான்.',	2,	36,	29),
(2597,	'And there were eight boards; and their sockets were sixteen sockets of silver, under every board two sockets.',	'அப்படியே எட்டுப் பலகைகளும், அவைகளுடைய ஒவ்வொரு பலகையின் கீழ் இரண்டிரண்டு பாதங்களாகப் பதினாறு வெள்ளிப்பாதங்களும் இருந்தது.',	2,	36,	30),
(2598,	'And he made bars of shittim wood; five for the boards of the one side of the tabernacle,',	'சீத்திம் மரத்தால் வாசஸ்தலத்தின் ஒரு பக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும்,',	2,	36,	31),
(2599,	'And five bars for the boards of the other side of the tabernacle, and five bars for the boards of the tabernacle for the sides westward.',	'வாசஸ்தலத்தின் மறுபக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும், வாசஸ்தலத்தின் மேல்புறமான பின்பக்கத்துப் பலகைகளுக்கு ஐந்து தாழ்ப்பாள்களையும் பண்ணினான்.',	2,	36,	32),
(2600,	'And he made the middle bar to shoot through the boards from the one end to the other.',	'நடுத்தாழ்ப்பாள் ஒரு முனைதொடங்கி மறுமுனை மட்டும் பலகைகளின் மையத்தில் உருவப்பாயும்படி செய்தான்.',	2,	36,	33),
(2601,	'And he overlaid the boards with gold, and made their rings of gold to be places for the bars, and overlaid the bars with gold.',	'பலகைகளைப் பொன்தகட்டால் மூடி, தாழ்ப்பாள்களின் இடங்களாகிய அவைகளின் வளையங்களைப் பொன்னினால்பண்ணி, தாழ்ப்பாள்களைப் பொன்தகட்டால் மூடினான்.',	2,	36,	34),
(2602,	'And he made a vail of blue, and purple, and scarlet, and fine twined linen: with cherubims made he it of cunning work.',	'இளநீலநூலாலும் இரத்தாம்பரநூலாலும், சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்யப்பட்டதும், விசித்திரவேலையாகிய கேருபீன்களுள்ளதுமான ஒரு திரைச்சீலையை உண்டுபண்ணி,',	2,	36,	35),
(2603,	'And he made thereunto four pillars of shittim wood, and overlaid them with gold: their hooks were of gold; and he cast for them four sockets of silver.',	'அதற்குச் சீத்திம் மரத்தினால் நாலு தூண்களைச் செய்து, அவைகளைப் பொன் தகட்டால் மூடி, அவைகளின் கொக்கிகளைப் பொன்னினால்பண்ணி, அவைகளுக்கு நான்கு வெள்ளிப்பாதங்களை வார்ப்பித்தான்.',	2,	36,	36),
(2604,	'And he made an hanging for the tabernacle door of blue, and purple, and scarlet, and fine twined linen, of needlework;',	'கூடாரவாசலுக்கு இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்த சித்திரத் தையல்வேலையான ஒரு தொங்குதிரையையும்,',	2,	36,	37),
(2605,	'And the five pillars of it with their hooks: and he overlaid their chapiters and their fillets with gold: but their five sockets were of brass.',	'அதின் ஐந்து தூண்களையும், அவைகளின் வளைவாணிகளையும் உண்டாக்கி, அவைகளின் குமிழ்களையும் வளையங்களையும் பொன்தகட்டால் மூடினான்; அவைகளின் ஐந்து பாதங்களும் வெண்கலமாயிருந்தது.  ',	2,	36,	38),
(2606,	'And Bezaleel made the ark of shittim wood: two cubits and a half was the length of it, and a cubit and a half the breadth of it, and a cubit and a half the height of it:',	'பெசலெயேல் சீத்திம் மரத்தினால் பெட்டியை உண்டுபண்ணினான்; அதின் நீளம் இரண்டரை முழமும் அதின் அகலம் ஒன்றரை முழமும் அதின் உயரம் ஒன்றரை முழமுமானது.',	2,	37,	1),
(2607,	'And he overlaid it with pure gold within and without, and made a crown of gold to it round about.',	'அதை உள்ளும் புறம்பும் பசும்பொன் தகட்டால் மூடி, சுற்றிலும் அதற்குப் பொன் திரணையை உண்டாக்கி,',	2,	37,	2),
(2608,	'And he cast for it four rings of gold, to be set by the four corners of it; even two rings upon the one side of it, and two rings upon the other side of it.',	'அதற்கு நான்கு பொன் வளையங்களை வார்ப்பித்து, அவைகளை அதின் நாலு மூலைகளிலும் போட்டு, ஒரு பக்கத்தில் இரண்டு வளையங்களும் மறுபக்கத்தில் இரண்டு வளையங்களும் இருக்கும்படி தைத்து,',	2,	37,	3),
(2609,	'And he made staves of shittim wood, and overlaid them with gold.',	'சீத்திம் மரத்தினால் தண்டுகளைச் செய்து, அவைகளைப் பொன்தகட்டால் மூடி,',	2,	37,	4),
(2610,	'And he put the staves into the rings by the sides of the ark, to bear the ark.',	'அந்த தண்டுகளால் பெட்டியைச் சுமக்கும்படி, அவைகளைப் பெட்டியின் பக்கங்களில் இருக்கும் வளையங்களிலே பாய்ச்சினான்.',	2,	37,	5),
(2611,	'And he made the mercy seat of pure gold: two cubits and a half was the length thereof, and one cubit and a half the breadth thereof.',	'கிருபாசனத்தையும் பசும்பொன்னினால் பண்ணினான்; அது இரண்டரை முழ நீளமும் ஒன்றரை முழ அகலமுமானது.',	2,	37,	6),
(2612,	'And he made two cherubims of gold, beaten out of one piece made he them, on the two ends of the mercy seat;',	'தகடாய் அடிக்கப்பட்ட பொன்னினால் இரண்டு கேருபீன்களையும் உண்டாக்கி, கிருபாசனத்தின் இரண்டு ஓரங்களிலே,',	2,	37,	7),
(2613,	'One cherub on the end on this side, and another cherub on the other end on that side: out of the mercy seat made he the cherubims on the two ends thereof.',	'ஒருபுறத்து ஓரத்தில் ஒரு கேருபீனும் மறுபுறத்து ஓரத்தில் மற்றக் கேருபீனுமாக அந்தக் கேருபீன்களைக் கிருபாசனத்தின் இரண்டு ஓரங்களிலும் அதனோடே ஏக வேலைப்பாடாகவே பண்ணினான்.',	2,	37,	8),
(2614,	'And the cherubims spread out their wings on high, and covered with their wings over the mercy seat, with their faces one to another; even to the mercy seatward were the faces of the cherubims.',	'அந்தக் கேருபீன்கள் தங்கள் செட்டைகளை உயர விரித்து, தங்கள் செட்டைகளால் கிருபாசனத்தை மூடுகிறவைகளும், ஒன்றுக்கொன்று எதிர்முகமுள்ளவைகளுமாயிருந்தது; கேருபீன்களின் முகங்கள் கிருபாசனத்தை நோக்கிக்கொண்டிருந்தது.',	2,	37,	9),
(2615,	'And he made the table of shittim wood: two cubits was the length thereof, and a cubit the breadth thereof, and a cubit and a half the height thereof:',	'மேஜையையும் சீத்திம் மரத்தால் பண்ணினான்; அது இரண்டு முழ நீளமும் ஒரு முழ அகலமும் ஒன்றரை முழ உயரமுமானது.',	2,	37,	10),
(2616,	'And he overlaid it with pure gold, and made thereunto a crown of gold round about.',	'அதைப் பசும்பொன்தகட்டால் மூடி, சுற்றிலும் அதற்குப் பொன் திரணையை உண்டாக்கி,',	2,	37,	11),
(2617,	'Also he made thereunto a border of an handbreadth round about; and made a crown of gold for the border thereof round about.',	'சுற்றிலும் அதற்கு நான்கு விரற்கடையான சட்டத்தையும், அதின் சட்டத்திற்குச் சுற்றிலும் பொன் திரணையையும் உண்டுபண்ணி,',	2,	37,	12),
(2618,	'And he cast for it four rings of gold, and put the rings upon the four corners that were in the four feet thereof.',	'அதற்கு நான்கு பொன்வளையங்களை வார்ப்பித்து, அவைகளை அதின் நாலு கால்களுக்கு இருக்கும் நாலு மூலைகளிலும் தைத்தான்.',	2,	37,	13),
(2619,	'Over against the border were the rings, the places for the staves to bear the table.',	'அந்த வளையங்கள் மேஜையைச் சுமக்கும் தண்டுகளைப் பாய்ச்சும் இடங்களாயிருக்கும்படி சட்டத்தின் அருகே இருந்தது.',	2,	37,	14),
(2620,	'And he made the staves of shittim wood, and overlaid them with gold, to bear the table.',	'மேஜையைச் சுமக்கும் அந்தத் தண்டுகளைச் சீத்திம் மரத்தால் பண்ணி, அவைகளைப் பொன்தகட்டால் மூடி,',	2,	37,	15),
(2621,	'And he made the vessels which were upon the table, his dishes, and his spoons, and his bowls, and his covers to cover withal, of pure gold.',	'மேஜையின்மேலிருக்கும் பாத்திரங்களாகிய அதின் பணிமுட்டுகளையும், அதின் தட்டுகளையும், தூபக்கரண்டிகளையும், அதின் பானபலி கரகங்களையும், மூடுகிறதற்கான அதின் கிண்ணங்களையும் பசும்பொன்னினால் உண்டாக்கினான்.',	2,	37,	16),
(2622,	'And he made the candlestick of pure gold: of beaten work made he the candlestick; his shaft, and his branch, his bowls, his knops, and his flowers, were of the same:',	'குத்துவிளக்கையும் பசும்பொன்னினால் அடிப்புவேலையாய் உண்டாக்கினான்; அதின் தண்டும் கிளைகளும் மொக்குகளும் பழங்களும் பூக்களும் பொன்னினால் செய்யப்பட்டிருந்தது.',	2,	37,	17),
(2623,	'And six branches going out of the sides thereof; three branches of the candlestick out of the one side thereof, and three branches of the candlestick out of the other side thereof:',	'குத்துவிளக்கின் ஒருபக்கத்தில் மூன்று கிளைகளும் அதின் மறுபக்கத்தில் மூன்று கிளைகளுமாக அதின் பக்கங்களில் ஆறு கிளைகள் செய்யப்பட்டது.',	2,	37,	18),
(2624,	'Three bowls made after the fashion of almonds in one branch, a knop and a flower; and three bowls made like almonds in another branch, a knop and a flower: so throughout the six branches going out of the candlestick.',	'ஒவ்வொரு கிளையிலே வாதுமைக்கொட்டைக்கு ஒப்பான மூன்று மொக்குகளும் ஒரு பழமும் ஒரு பூவும் இருந்தது; குத்துவிளக்கில் செய்யப்பட்ட ஆறு கிளைகளிலும் அப்படியே இருந்தது.',	2,	37,	19),
(2625,	'And in the candlestick were four bowls made like almonds, his knops, and his flowers:',	'விளக்குத்தண்டில் வாதுமைக்கொட்டைக்கு ஒப்பான நாலு மொக்குகளும் பழங்களும் பூக்களும் இருந்தது.',	2,	37,	20),
(2626,	'And a knop under two branches of the same, and a knop under two branches of the same, and a knop under two branches of the same, according to the six branches going out of it.',	'அதில் செய்யப்பட்ட இரண்டு கிளைகளின்கீழ் ஒரு பழமும், வேறு இரண்டு கிளைகளின்கீழ் ஒரு பழமும், மற்ற இரண்டு கிளைகளின்கீழ் ஒரு பழமும் இருந்தது; விளக்குத்தண்டில் செய்யப்பட்ட ஆறு கிளைகளுக்கும் அப்படியே இருந்தது.',	2,	37,	21),
(2627,	'Their knops and their branches were of the same: all of it was one beaten work of pure gold.',	'அவைகளின் பழங்களும் அவைகளின் கிளைகளும் பசும்பொன்னினால் ஒரே அடிப்பு வேலையாய்ச் செய்யப்பட்டது.',	2,	37,	22),
(2628,	'And he made his seven lamps, and his snuffers, and his snuffdishes, of pure gold.',	'அதின் ஏழு அகல்களையும், அதின் கத்தரிகளையும், சாம்பல் பாத்திரங்களையும் பசும்பொன்னினால் செய்தான்.',	2,	37,	23),
(2629,	'Of a talent of pure gold made he it, and all the vessels thereof.',	'அதையும் அதின் பணிமுட்டுகள் யாவையும் ஒரு தாலந்து பசும்பொன்னினால் செய்தான்.',	2,	37,	24),
(2630,	'And he made the incense altar of shittim wood: the length of it was a cubit, and the breadth of it a cubit; it was foursquare; and two cubits was the height of it; the horns thereof were of the same.',	'தூபபீடத்தையும் சீத்திம் மரத்தினால் உண்டாக்கினான்; அது ஒரு முழ நீளமும் ஒரு முழ அகலமுமான சதுரமும் இரண்டு முழ உயரமுமாய் இருந்தது; அதின் கொம்புகள் அதனோடே ஏக வேலைப்பாடாயிருந்தது.',	2,	37,	25),
(2631,	'And he overlaid it with pure gold, both the top of it, and the sides thereof round about, and the horns of it: also he made unto it a crown of gold round about.',	'அதின் மேற்புறத்தையும், அதின் சுற்றுப்புறத்தையும், அதின் கொம்புகளையும், பசும்பொன்தகட்டால் மூடி, சுற்றிலும் அதற்குப் பொன் திரணையை உண்டுபண்ணி,',	2,	37,	26),
(2632,	'And he made two rings of gold for it under the crown thereof, by the two corners of it, upon the two sides thereof, to be places for the staves to bear it withal.',	'அந்தத் திரணையின்கீழ் அதின் இரண்டு பக்கங்களில் இருக்கும் இரண்டு மூலைகளிலும் இரண்டு பொன்வளையங்களைப் பண்ணி, அதைச் சுமக்கும் தண்டுகளைப் பாய்ச்சும் இடங்களாகத் தைத்து,',	2,	37,	27),
(2633,	'And he made the staves of shittim wood, and overlaid them with gold.',	'சீத்திம் மரத்தால் அந்தத் தண்டுகளைச் செய்து, அவைகளைப் பொன்தகட்டால் மூடினான்.',	2,	37,	28),
(2634,	'And he made the holy anointing oil, and the pure incense of sweet spices, according to the work of the apothecary.',	'பரிசுத்த அபிஷேகதைலத்தையும், சுத்தமான சுகந்தங்களின் தூபவர்க்கத்தையும், தைலக்காரன் வேலைக்கு ஒப்பாக உண்டுபண்ணினான்.  ',	2,	37,	29),
(2635,	'And he made the altar of burnt offering of shittim wood: five cubits was the length thereof, and five cubits the breadth thereof; it was foursquare; and three cubits the height thereof.',	'தகனபலிபீடத்தையும் சீத்திம் மரத்தால் உண்டாக்கினான்; அது ஐந்து முழநீளமும் ஐந்து முழ அகலமும் சதுரவடிவும் மூன்று முழ உயரமுமானது.',	2,	38,	1),
(2636,	'And he made the horns thereof on the four corners of it; the horns thereof were of the same: and he overlaid it with brass.',	'அதின் நாலு மூலைகளிலும் அதனோடு ஏகமாயிருக்கிற அதின் நாலு கொம்புகளையும் உண்டாக்கி, அதை வெண்கலத்தகட்டால் மூடி,',	2,	38,	2),
(2637,	'And he made all the vessels of the altar, the pots, and the shovels, and the basons, and the fleshhooks, and the firepans: all the vessels thereof made he of brass.',	'அந்தப் பீடத்தின் சகல பணிமுட்டுகளாகிய சாம்பல் எடுக்கத்தக்க சட்டிகளையும், கரண்டிகளையும், கிண்ணிகளையும், முள்துறடுகளையும், நெருப்புச் சட்டிகளையும் உண்டாக்கினான்; அதின் பணிமுட்டுகளையெல்லாம் வெண்கலத்தினால் பண்ணினான்.',	2,	38,	3),
(2638,	'And he made for the altar a brasen grate of network under the compass thereof beneath unto the midst of it.',	'வலைப்பின்னல்போன்ற ஒரு வெண்கலச் சல்லடையையும் பலிபீடத்திற்கு உண்டாக்கி, அதை அந்தப் பீடத்தின் சுற்றுக்குக் கீழே பாதி உயரத்தில் இருக்கத்தக்கதாக வைத்து,',	2,	38,	4),
(2639,	'And he cast four rings for the four ends of the grate of brass, to be places for the staves.',	'அந்த வெண்கலச் சல்லடையின் நாலு மூலைகளிலும் தண்டுகளைப் பாய்ச்சுகிறதற்கு நாலு வளையங்களை வார்ப்பித்து,',	2,	38,	5),
(2640,	'And he made the staves of shittim wood, and overlaid them with brass.',	'அந்தத் தண்டுகளைச் சீத்திம் மரத்தால் பண்ணி, அவைகளை வெண்கலத்தகட்டால் மூடி,',	2,	38,	6),
(2641,	'And he put the staves into the rings on the sides of the altar, to bear it withal; he made the altar hollow with boards.',	'பலிபீடத்தை அவைகளால் சுமக்கத்தக்கதாக, அதின் பக்கங்களிலுள்ள வளையங்களில் பாய்ச்சினான்; பலிபீடத்தை உள்வெளிவிட்டுப் பலகைகளினால் செய்தான்.',	2,	38,	7),
(2642,	'And he made the laver of brass, and the foot of it of brass, of the lookingglasses of the women assembling, which assembled at the door of the tabernacle of the congregation.',	'ஆசரிப்புக் கூடாரத்தின் வாசலில் கூட்டம் கூட்டமாய்க் கூடின ஸ்திரீகளின் தர்ப்பணங்களாலே, வெண்கலத் தொட்டியையும் அதின் வெண்கலப் பாதத்தையும் உண்டாக்கினான்.',	2,	38,	8),
(2643,	'And he made the court: on the south side southward the hangings of the court were of fine twined linen, an hundred cubits:',	'பிராகாரத்தையும் உண்டுபண்ணினான். தெற்கே தென்திசைக்கு எதிரான பிராகாரத்துக்குத் திரித்த மெல்லிய பஞ்சுநூலால் நெய்த நூறு முழ நீளமான தொங்குதிரைகளைச் செய்தான்.',	2,	38,	9),
(2644,	'Their pillars were twenty, and their brasen sockets twenty; the hooks of the pillars and their fillets were of silver.',	'அவைகளின் தூண்கள் இருபது; அவைகளின் வெண்கலப் பாதங்கள் இருபது; தூண்களின் கொக்கிகளும் அவைகளின் பூண்களும் வெள்ளி.',	2,	38,	10),
(2645,	'And for the north side the hangings were an hundred cubits, their pillars were twenty, and their sockets of brass twenty; the hooks of the pillars and their fillets of silver.',	'வடபக்கத்துத் தொங்குதிரைகள் நூறு முழம்; அவைகளின் தூண்கள் இருபது; அவைகளின் வெண்கலப் பாதங்கள் இருபது; தூண்களின் கொக்கிகளும் பூண்களும் வெள்ளி.',	2,	38,	11),
(2646,	'And for the west side were hangings of fifty cubits, their pillars ten, and their sockets ten; the hooks of the pillars and their fillets of silver.',	'மேற்பக்கத்துத் தொங்குதிரைகள் ஐம்பது முழம்; அவைகளின் தூண்கள் பத்து; அவைகளின் பாதங்கள் பத்து; தூண்களின் கொக்கிகளும் அவைகளின் பூண்களும் வெள்ளி.',	2,	38,	12),
(2647,	'And for the east side eastward fifty cubits.',	'சூரியன் உதிக்கிற திசையாகிய கீழ்ப்பக்கத்துத் தொங்குதிரைகள் ஐம்பது முழம்.',	2,	38,	13),
(2648,	'The hangings of the one side of the gate were fifteen cubits; their pillars three, and their sockets three.',	'ஒருபுறத்துத் தொங்குதிரைகள் பதினைந்து முழம்; அவைகளின் தூண்கள் மூன்று; அவைகளின் பாதங்கள் மூன்று.',	2,	38,	14),
(2649,	'And for the other side of the court gate, on this hand and that hand, were hangings of fifteen cubits; their pillars three, and their sockets three.',	'பிராகாரவாசலின் ஒருபுறத்துக்குச் சரியாக மறுபுறத்திலும் தொங்குதிரைகள் பதினைந்து முழம்; அவைகளின் தூண்கள் மூன்று; அவைகளின் பாதங்கள் மூன்று.',	2,	38,	15),
(2650,	'All the hangings of the court round about were of fine twined linen.',	'சுற்றுபிராகாரத்துத் தொங்குதிரைகளெல்லாம் மெல்லிய பஞ்சுநூலால் நெய்யப்பட்டிருந்தது.',	2,	38,	16),
(2651,	'And the sockets for the pillars were of brass; the hooks of the pillars and their fillets of silver; and the overlaying of their chapiters of silver; and all the pillars of the court were filleted with silver.',	'தூண்களின் பாதங்கள் வெண்கலம்; தூண்களின் கொக்கிகளும், பூண்களும் வெள்ளி; அவைகளின் குமிழ்களை மூடிய தகடும் வெள்ளி; பிராகாரத்தின் தூண்களெல்லாம் வெள்ளிப்பூண்கள் போடப்பட்டவைகளுமாயிருந்தது.',	2,	38,	17),
(2652,	'And the hanging for the gate of the court was needlework, of blue, and purple, and scarlet, and fine twined linen: and twenty cubits was the length, and the height in the breadth was five cubits, answerable to the hangings of the court.',	'பிராகார வாசலின் தொங்குதிரை இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்யப்பட்ட விசித்திரத்தையல் வேலையாயிருந்தது; அதின் நீளம் இருபது முழம், அதின் அகலமும் உயரமும் பிராகாரத்தின் தொங்குதிரைகளுக்குச் சரியாய் ஐந்து முழம்.',	2,	38,	18),
(2653,	'And their pillars were four, and their sockets of brass four; their hooks of silver, and the overlaying of their chapiters and their fillets of silver.',	'அவைகளின் தூண்கள் நாலு; அவைகளின் வெண்கலப் பாதங்கள் நாலு; அவைகளின் கொக்கிகள் வெள்ளி; அவைகளின் குமிழ்களை மூடிய தகடும் அவைகளின் பூண்களும் வெள்ளி.',	2,	38,	19),
(2654,	'And all the pins of the tabernacle, and of the court round about, were of brass.',	'வாசஸ்தலத்துக்கும் பிராகாரத்துக்கும் சுற்றிலும் இருந்த முளைகளெல்லாம் வெண்கலம்.',	2,	38,	20),
(2655,	'This is the sum of the tabernacle, even of the tabernacle of testimony, as it was counted, according to the commandment of Moses, for the service of the Levites, by the hand of Ithamar, son to Aaron the priest.',	'மோசேயின் கட்டளைப்படி ஆசாரியனான ஆரோனின் குமாரனாகிய இத்தாமாரின் கையிலே லேவியரின் ஊழியத்திற்கென்று எண்ணிக் கொடுக்கப்பட்ட சாட்சியின் வாசஸ்தலத்துப் பொருள்களின் தொகை இதுவே.',	2,	38,	21),
(2656,	'And Bezaleel the son Uri, the son of Hur, of the tribe of Judah, made all that the LORD commanded Moses.',	'யூதாவின் கோத்திரத்தில் ஊரின் மகனாகிய ஊரியின் குமாரன் பெசலெயேல் கர்த்தர் மோசேக்குக் கற்பித்ததை எல்லாம் செய்தான்.',	2,	38,	22),
(2657,	'And with him was Aholiab, son of Ahisamach, of the tribe of Dan, an engraver, and a cunning workman, and an embroiderer in blue, and in purple, and in scarlet, and fine linen.',	'அவனோடேகூடத் தாண் கோத்திரத்து அகிசாமாகின் குமாரனாகிய அகோலியாப் சித்திரக் கொத்துவேலைக்காரனும், விநோத வேலைகளைச்செய்கிற தொழிலாளியும், இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் மெல்லிய பஞ்சுநூலாலும் சித்திரத் தையல்வேலை செய்கிறவனுமாயிருந்தான்.',	2,	38,	23),
(2658,	'All the gold that was occupied for the work in all the work of the holy place, even the gold of the offering, was twenty and nine talents, and seven hundred and thirty shekels, after the shekel of the sanctuary.',	'பரிசுத்த ஸ்தலத்தின் வேலைகள் யாவற்றிற்கும் காணிக்கையாகக் கொடுக்கப்பட்டுச் செலவான பொன்னெல்லாம் பரிசுத்த ஸ்தலத்தின் சேக்கலின்படி இருபத்தொன்பது தாலந்தும் எழுநூற்று முப்பது சேக்கல் நிறையுமாய் இருந்தது.',	2,	38,	24),
(2659,	'And the silver of them that were numbered of the congregation was an hundred talents, and a thousand seven hundred and threescore and fifteen shekels, after the shekel of the sanctuary:',	'சபையில் எண்ணப்பட்டவர்கள் கொடுத்த வெள்ளி பரிசுத்த ஸ்தலத்தின் சேக்கலின்படி நூறு தாலந்தும், ஆயிரத்தெழுநூற்று எழுபத்தைந்து சேக்கல் நிறையுமாய் இருந்தது.',	2,	38,	25),
(2660,	'A bekah for every man, that is, half a shekel, after the shekel of the sanctuary, for every one that went to be numbered, from twenty years old and upward, for six hundred thousand and three thousand and five hundred and fifty men.',	'எண்ணப்பட்டவர்களின் தொகையில் சேர்ந்த இருபது வயது முதற்கொண்டு அதற்கு மேற்பட்ட ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேர்களில் ஒவ்வொரு தலைக்கு பரிசுத்த ஸ்தலத்தின் சேக்கலின்படி அரைச்சேக்கலாகிய பெக்கா என்னும் விழுக்காடு சேர்ந்தது.',	2,	38,	26),
(2661,	'And of the hundred talents of silver were cast the sockets of the sanctuary, and the sockets of the vail; an hundred sockets of the hundred talents, a talent for a socket.',	'அந்த வெள்ளியில் நூறு தாலந்து வெள்ளியினால் பரிசுத்த ஸ்தலத்தின் பாதங்களும் திரையின் பாதங்களும் வார்ப்பிக்கப்பட்டது; பாதத்துக்கு ஒரு தாலந்து விழுக்காடு நூறு பாதங்களுக்கு நூறு தாலந்து செலவாயிற்று.',	2,	38,	27),
(2662,	'And of the thousand seven hundred seventy and five shekels he made hooks for the pillars, and overlaid their chapiters, and filleted them.',	'அந்த ஆயிரத்தெழுநூற்று எழுபத்தைந்து சேக்கலால் தூண்களுக்குப் பூண்களைப் பண்ணி, அவைகளின் குமிழ்களைத் தகடுகளால் மூடி, அவைகளுக்குப் பூண்களை உண்டாக்கினான்.',	2,	38,	28),
(2663,	'And the brass of the offering was seventy talents, and two thousand and four hundred shekels.',	'காணிக்கையாகச் செலுத்தப்பட்ட வெண்கலமானது எழுபது தாலந்தும் இரண்டாயிரத்து நானூறு சேக்கல் நிறையுமாய் இருந்தது.',	2,	38,	29),
(2664,	'And therewith he made the sockets to the door of the tabernacle of the congregation, and the brasen altar, and the brasen grate for it, and all the vessels of the altar,',	'அதினாலே ஆசரிப்புக் கூடாரவாசல் மறைவின் பாதங்களையும், வெண்கலப்பலிபீடத்தையும், அதின் வெண்கலச் சல்லடையையும், பலிபீடத்தின் சகல பணிமுட்டுகளையும்,',	2,	38,	30),
(2665,	'And the sockets of the court round about, and the sockets of the court gate, and all the pins of the tabernacle, and all the pins of the court round about.',	'சுற்றுப் பிராகாரத்தின் பாதங்களையும், பிராகாரவாசல் மறைவின் பாதங்களையும், வாசஸ்தலத்தின் சகல முளைகளையும், சுற்றுப்பிராகாரத்தின் சகலமுளைகளையும் பண்ணினான்.  ',	2,	38,	31),
(2666,	'And of the blue, and purple, and scarlet, they made cloths of service, to do service in the holy place, and made the holy garments for Aaron; as the LORD commanded Moses.',	'கர்த்தர் மோசேக்குக் கற்பித்தபடியே, அவர்கள் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் பரிசுத்த ஸ்தலத்தில் ஆராதனை செய்கிறதற்கு வேண்டிய வஸ்திரங்களையும், ஆரோனுக்குப் பரிசுத்த வஸ்திரங்களையும் செய்தார்கள்.',	2,	39,	1),
(2667,	'And he made the ephod of gold, blue, and purple, and scarlet, and fine twined linen.',	'ஏபோத்தைப் பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்தான்.',	2,	39,	2),
(2668,	'And they did beat the gold into thin plates, and cut it into wires, to work it in the blue, and in the purple, and in the scarlet, and in the fine linen, with cunning work.',	'அந்தப் பொன்னை, இளநீலநூலோடும் இரத்தாம்பரநூலோடும் சிவப்புநூலோடும் மெல்லிய பஞ்சுநூலோடும் சேர்த்து விசித்திரவேலையாய் நெய்யும்படிக்கு, மெல்லிய தகடுகளாய் அடித்து, அவைகளைச் சரிகைகளாகப் பண்ணினார்கள்.',	2,	39,	3),
(2669,	'They made shoulderpieces for it, to couple it together: by the two edges was it coupled together.',	'இரண்டு தோள்களின்மேலுள்ள அதின் இரண்டு முனைகளையும் சேர்த்தார்கள்; அது ஒன்றாய் இணைக்கப்பட்டிருந்தது.',	2,	39,	4),
(2670,	'And the curious girdle of his ephod, that was upon it, was of the same, according to the work thereof; of gold, blue, and purple, and scarlet, and fine twined linen; as the LORD commanded Moses.',	'அந்த ஏபோத்தின்மேலிருக்கும் விசித்திரமான கச்சை, அந்த வேலைக்கு ஒப்பாகவே பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும், திரித்த மெல்லிய பஞ்சுநூலாலும், கர்த்தர் மோசேக்குக் கற்பித்தபடியே, செய்யப்பட்டது.',	2,	39,	5),
(2671,	'And they wrought onyx stones inclosed in ouches of gold, graven, as signets are graven, with the names of the children of Israel.',	'இஸ்ரவேல் புத்திரரின் நாமங்களை முத்திரை வெட்டுவேலையாகக் கோமேதகக் கற்களில் வெட்டி, அவைகளைப் பொன் குவளைகளில் பதித்தார்கள்.',	2,	39,	6),
(2672,	'And he put them on the shoulders of the ephod, that they should be stones for a memorial to the children of Israel; as the LORD commanded Moses.',	'கர்த்தர் மோசேக்குக் கற்பித்தபடியே, அவைகள் இஸ்ரவேல் புத்திரரைக்குறித்து ஞாபகக்குறிக் கற்களாயிருக்கும்படி ஏபோத்துத் தோள்களின்மேல் அவைகளை வைத்தான்.',	2,	39,	7),
(2673,	'And he made the breastplate of cunning work, like the work of the ephod; of gold, blue, and purple, and scarlet, and fine twined linen.',	'மார்ப்பதக்கத்தை ஏபோத்தின் வேலைக்கு ஒத்த விசித்திரவேலையாகப் பொன்னினாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் திரித்த மெல்லிய பஞ்சுநூலாலும் செய்தான்.',	2,	39,	8),
(2674,	'It was foursquare; they made the breastplate double: a span was the length thereof, and a span the breadth thereof, being doubled.',	'அந்த மார்ப்பதக்கத்தைச் சதுரமும் இரட்டையுமாய்ச் செய்து, ஒரு ஜாண் நீளமும். ஒரு ஜாண் அகலமுமாக்கி,',	2,	39,	9),
(2675,	'And they set in it four rows of stones: the first row was a sardius, a topaz, and a carbuncle: this was the first row.',	'அதிலே நாலு பத்தி ரத்தினக்கற்களைப் பதித்தார்கள்; முதலாம் பத்தி பத்மராகமும் புஷ்பராகமும் மாணிக்கமும்,',	2,	39,	10),
(2676,	'And the second row, an emerald, a sapphire, and a diamond.',	'இரண்டாம் பத்தி மரகதமும் இந்திரநீலமும் வச்சிரமும்,',	2,	39,	11),
(2677,	'And the third row, a ligure, an agate, and an amethyst.',	'மூன்றாம் பத்தி கெம்பும் வைடூரியமும் சுகந்தியும்,',	2,	39,	12),
(2678,	'And the fourth row, a beryl, an onyx, and a jasper: they were inclosed in ouches of gold in their inclosings.',	'நாலாம் பத்தி படிகப்பச்சையும் கோமேதகமும் யஸ்பியுமானது. அவைகள் அந்தந்த இடங்களிலே பொன்குவளைகளில் பதிக்கப்பட்டிருந்தது.',	2,	39,	13),
(2679,	'And the stones were according to the names of the children of Israel, twelve, according to their names, like the engravings of a signet, every one with his name, according to the twelve tribes.',	'இந்தக் கற்கள் இஸ்ரவேல் புத்திரருடைய நாமங்களின்படியே பன்னிரண்டும், அவர்களுடைய நாமங்களுள்ளவைகளுமாயிருந்தது; பன்னிரண்டு கோத்திரங்களில் ஒவ்வொரு கோத்திரத்தின் நாமம் ஒவ்வொன்றில் முத்திரைவெட்டாய் வெட்டியிருந்தது.',	2,	39,	14),
(2680,	'And they made upon the breastplate chains at the ends, of wreathen work of pure gold.',	'மார்ப்பதக்கத்துக்கு அதின் பக்கங்களிலே பின்னல் வேலையான பசும்பொன் சங்கிலிகளையும் பண்ணி,',	2,	39,	15),
(2681,	'And they made two ouches of gold, and two gold rings; and put the two rings in the two ends of the breastplate.',	'இரண்டு பொன் குவளைகளையும் இரண்டு பொன் வளையங்களையும் செய்து, அந்த இரண்டு வளையங்களை மார்ப்பதக்கத்தின் இரண்டு பக்கத்திலும் வைத்து,',	2,	39,	16),
(2682,	'And they put the two wreathen chains of gold in the two rings on the ends of the breastplate.',	'பொன்னினால் செய்த பின்னல் வேலையான அந்த இரண்டு சங்கிலிகளையும் மார்ப்பதக்கத்தின் பக்கங்களில் இருக்கிற இரண்டு வளையங்களிலும் மாட்டி,',	2,	39,	17),
(2683,	'And the two ends of the two wreathen chains they fastened in the two ouches, and put them on the shoulderpieces of the ephod, before it.',	'பின்னல் வேலையான அவ்விரண்டு சங்கிலிகளின் இரண்டு நுனிகளையும் ஏபோத்தின் தோள்புறத்துத் துண்டுகள்மேல் முன்புறத்தில் இருக்கிற இரண்டு குவளைகளிலும் மாட்டினார்கள்.',	2,	39,	18),
(2684,	'And they made two rings of gold, and put them on the two ends of the breastplate, upon the border of it, which was on the side of the ephod inward.',	'பின்னும் இரண்டு வளையங்களைப்பண்ணி, அவைகளை ஏபோத்தின் கீழ்ப்புறத்திற்கு எதிரான மார்ப்பதக்கத்தின் மற்ற இரண்டு பக்கங்களிலும் அதின் ஓரத்தில் வைத்து,',	2,	39,	19),
(2685,	'And they made two other golden rings, and put them on the two sides of the ephod underneath, toward the forepart of it, over against the other coupling thereof, above the curious girdle of the ephod.',	'வேறே இரண்டு பொன்வளையங்களையும் பண்ணி, அவைகளை ஏபோத்தின் முன்புறத்தின் இரண்டு கீழ்ப்பக்கங்களில் அதின் இணைப்புக்கு எதிராகவும், ஏபோத்தின் விசித்திரமான கச்சைக்கு மேலாகவும் வைத்து,',	2,	39,	20),
(2686,	'And they did bind the breastplate by his rings unto the rings of the ephod with a lace of blue, that it might be above the curious girdle of the ephod, and that the breastplate might not be loosed from the ephod; as the LORD commanded Moses.',	'மார்ப்பதக்கம் ஏபோத்தின் விசித்திரமான கச்சைக்கு மேலாக இருக்கும்படிக்கும், ஏபோத்திலிருந்து நீங்கிப்போகாதபடிக்கும், அதை அதின் வளையங்களால் ஏபோத்தின் வளையங்களோடே இளநீல நாடாவினாலே, கர்த்தர் மோசேக்குக் கற்பித்தப்படியே, கட்டினார்கள்.',	2,	39,	21),
(2687,	'And he made the robe of the ephod of woven work, all of blue.',	'ஏபோத்தின் கீழ் அங்கியை முழுவதும் இளநீலநூலால் நெய்தான்.',	2,	39,	22),
(2688,	'And there was an hole in the midst of the robe, as the hole of an habergeon, with a band round about the hole, that it should not rend.',	'அங்கியின் நடுவில் மார்க்கவசத் துவாரத்துக்கு ஒப்பாக ஒரு துவாரமும், அது கிழியாதபடி அந்தத் துவாரத்தைச் சுற்றிலும் ஒரு நாடாவும் தைத்திருந்தது.',	2,	39,	23),
(2689,	'And they made upon the hems of the robe pomegranates of blue, and purple, and scarlet, and twined linen.',	'அங்கியின் கீழ் ஓரங்களில் தொங்கத்தக்கதாகத் திரித்த இளநீலநூலும் இரத்தாம்பரநூலும் சிவப்புநூலுமான வேலையாக மாதளம்பழங்களைப் பண்ணி,',	2,	39,	24),
(2690,	'And they made bells of pure gold, and put the bells between the pomegranates upon the hem of the robe, round about between the pomegranates;',	'பசும்பொன்னினால் மணிகளையும் பண்ணி, அந்த மணிகளை அங்கியின் ஓரங்களில் சுற்றிலும் மாதளம்பழங்களின் இடைஇடையே தொங்கவைத்தார்கள்.',	2,	39,	25),
(2691,	'A bell and a pomegranate, a bell and a pomegranate, round about the hem of the robe to minister in; as the LORD commanded Moses.',	'கர்த்தர் மோசேக்குக் கற்பித்தபடியே ஆராதனைக்குரிய அங்கியின் ஓரத்தைச் சுற்றிலும், ஒரு மணியும் ஒரு மாதளம்பழமும், ஒரு மணியும் ஒரு மாதளம்பழமுமாய் இருந்தது.',	2,	39,	26),
(2692,	'And they made coats of fine linen of woven work for Aaron, and for his sons,',	'ஆரோனுக்கும் அவன் குமாரருக்கும் மெல்லிய பஞ்சுநூலால் நெசவுவேலையான அங்கிகளையும்,',	2,	39,	27),
(2693,	'And a mitre of fine linen, and goodly bonnets of fine linen, and linen breeches of fine twined linen,',	'மெல்லிய பஞ்சுநூலால் பாகையையும், அலங்காரமான குல்லாக்களையும், திரித்த மெல்லிய சணல்நூலால் சல்லடங்களையும்,',	2,	39,	28),
(2694,	'And a girdle of fine twined linen, and blue, and purple, and scarlet, of needlework; as the LORD commanded Moses.',	'திரித்த மெல்லிய பஞ்சுநூலாலும் இளநீலநூலாலும் இரத்தாம்பரநூலாலும் சிவப்புநூலாலும் சித்திரத் தையல்வேலையான இடைக்கச்சையையும், கர்த்தர் மோசேக்குக் கற்பித்தபடியே செய்தார்கள்.',	2,	39,	29),
(2695,	'And they made the plate of the holy crown of pure gold, and wrote upon it a writing, like to the engravings of a signet, HOLINESS TO THE LORD.',	'பரிசுத்த கிரீடத்தின் பட்டத்தையும் பசும்பொன்னினாலே பண்ணி, கர்த்தருக்குப் பரிசுத்தம் என்னும் எழுத்துக்களை அதிலே முத்திரை வெட்டாகவெட்டி,',	2,	39,	30),
(2696,	'And they tied unto it a lace of blue, to fasten it on high upon the mitre; as the LORD commanded Moses.',	'அதை உயரப் பாகையின்மேல் கட்டும்படி, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, இளநீல நாடாவினால் கட்டினார்கள்.',	2,	39,	31),
(2697,	'Thus was all the work of the tabernacle of the tent of the congregation finished: and the children of Israel did according to all that the LORD commanded Moses, so did they.',	'இப்படியே ஆசரிப்புக் கூடாரமாகிய வாசஸ்தலத்தின் வேலையெல்லாம் முடிந்தது; கர்த்தர் மோசேக்குக் கற்பித்தபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்தார்கள்.',	2,	39,	32),
(2698,	'And they brought the tabernacle unto Moses, the tent, and all his furniture, his taches, his boards, his bars, and his pillars, and his sockets,',	'பின்பு. வாசஸ்தலத்தை மோசேயினிடத்தில் கொண்டுவந்தார்கள்; கூடாரத்தையும், அதற்குரிய எல்லாப் பணிமுட்டுகளையும், அதின் துறடுகளையும், அதின் பலகைகளையும், அதின் தாழ்ப்பாள்களையும், அதின் தூண்களையும், அதின் பாதங்களையும்,',	2,	39,	33),
(2699,	'And the covering of rams\' skins dyed red, and the covering of badgers\' skins, and the vail of the covering,',	'சிவப்புத்தீர்ந்த ஆட்டுக்கடாத்தோல் மூடியையும், தகசுத்தோல் மூடியையும், மறைவின் திரைச்சீலையையும்,',	2,	39,	34),
(2700,	'The ark of the testimony, and the staves thereof, and the mercy seat,',	'சாட்சிப்பெட்டியையும், அதின் தண்டுகளையும், கிருபாசனத்தையும்,',	2,	39,	35),
(2701,	'The table, and all the vessels thereof, and the shewbread,',	'மேஜையையும், அதின் எல்லாப் பணிமுட்டுகளையும், சமுகத்தப்பங்களையும்,',	2,	39,	36),
(2702,	'The pure candlestick, with the lamps thereof, even with the lamps to be set in order, and all the vessels thereof, and the oil for light,',	'சுத்தமான குத்துவிளக்கையும், வரிசையாய் ஒழுங்குப்படுத்தப்பட்ட அதின் அகல்களையும், அதின் எல்லாப் பணிமுட்டுகளையும், வெளிச்சத்திற்கு எண்ணெயையும்,',	2,	39,	37),
(2703,	'And the golden altar, and the anointing oil, and the sweet incense, and the hanging for the tabernacle door,',	'பொற்பீடத்தையும், அபிஷேகதைலத்தையும், சுகந்த தூபவர்க்கத்தையும், வாசஸ்தலத்தின் வாசல் தொங்குதிரையையும்,',	2,	39,	38),
(2704,	'The brasen altar, and his grate of brass, his staves, and all his vessels, the laver and his foot,',	'வெண்கலப் பலிபீடத்தையும், அதின் வெண்கலச் சல்லடையையும், அதின் தண்டுகளையும், அதின் சகல பணிமுட்டுகளையும், தொட்டியையும், அதின் பாதத்தையும்,',	2,	39,	39),
(2705,	'The hangings of the court, his pillars, and his sockets, and the hanging for the court gate, his cords, and his pins, and all the vessels of the service of the tabernacle, for the tent of the congregation,',	'பிராகாரத்தின் தொங்குதிரைகளையும், அதின் தூண்களையும், அதின் பாதங்களையும், பிராகாரத்து வாசல் மறைவையும், அதின் கயிறுகளையும், அதின் முளைகளையும், ஆசரிப்புக் கூடாரமான வாசஸ்தலத்தின் வேலைக்கடுத்த சகல பணிமுட்டுகளையும்,',	2,	39,	40),
(2706,	'The cloths of service to do service in the holy place, and the holy garments for Aaron the priest, and his sons\' garments, to minister in the priest\'s office.',	'பரிசுத்த ஸ்தலத்திலே செய்யும் ஆராதனைக்கடுத்த வஸ்திரங்களையும், ஆசாரிய ஊழியஞ்செய்கிற ஆரோனின் பரிசுத்த வஸ்திரங்களையும், அவன் குமாரரின் வஸ்திரங்களையும் கொண்டுவந்தார்கள்.',	2,	39,	41),
(2707,	'According to all that the LORD commanded Moses, so the children of Israel made all the work.',	'கர்த்தர் மோசேக்குக் கற்பித்தபடியெல்லாம் இஸ்ரவேல் புத்திரர் சகல வேலைகளையும் செய்தார்கள்.',	2,	39,	42),
(2708,	'And Moses did look upon all the work, and, behold, they had done it as the LORD had commanded, even so had they done it: and Moses blessed them.',	'மோசே அந்த வேலைகளையெல்லாம் பார்த்தான்; கர்த்தர் கற்பித்தபடியே அதைச் செய்திருந்தார்கள். மோசே அவர்களை ஆசீர்வதித்தான்.  ',	2,	39,	43),
(2709,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	2,	40,	1),
(2710,	'On the first day of the first month shalt thou set up the tabernacle of the tent of the congregation.',	'நீ முதலாம் மாதம் முதல் தேதியில் ஆசரிப்புக் கூடாரத்தின் வாசஸ்தலத்தை ஸ்தாபனம்பண்ணு.',	2,	40,	2),
(2711,	'And thou shalt put therein the ark of the testimony, and cover the ark with the vail.',	'அதிலே சாட்சிப்பெட்டியை வைத்து, பெட்டியைத் திரையினால் மறைத்து,',	2,	40,	3),
(2712,	'And thou shalt bring in the table, and set in order the things that are to be set in order upon it; and thou shalt bring in the candlestick, and light the lamps thereof.',	'மேஜையைக் கொண்டுவந்து, அதில் வைக்கவேண்டியதைக் கிரமமாய் வைத்து, குத்துவிளக்கைக் கொண்டுவந்து, அதின் விளக்குகளை ஏற்றி,',	2,	40,	4),
(2713,	'And thou shalt set the altar of gold for the incense before the ark of the testimony, and put the hanging of the door to the tabernacle.',	'பொன் தூபபீடத்தைச் சாட்சிப்பெட்டிக்கு முன்னே வைத்து, வாசஸ்தலத்து வாசலின் தொங்குதிரையைத் தூக்கிவைக்கக்கடவாய்.',	2,	40,	5),
(2714,	'And thou shalt set the altar of the burnt offering before the door of the tabernacle of the tent of the congregation.',	'பின்பு, தகன பலிபீடத்தை ஆசரிப்புக் கூடாரமாகிய வாசஸ்தலத்தின் வாசலுக்கு முன்பாக வைத்து,',	2,	40,	6),
(2715,	'And thou shalt set the laver between the tent of the congregation and the altar, and shalt put water therein.',	'தொட்டியை ஆசரிப்புக் கூடாரத்துக்கும் பலிபீடத்துக்கும் நடுவே வைத்து, அதிலே தண்ணீர் வார்த்து,',	2,	40,	7),
(2716,	'And thou shalt set up the court round about, and hang up the hanging at the court gate.',	'சுற்றுப் பிராகாரத்தை நிறுத்தி, பிராகாரவாசல் தொங்குதிரையைத் தூக்கிவைத்து,',	2,	40,	8),
(2717,	'And thou shalt take the anointing oil, and anoint the tabernacle, and all that is therein, and shalt hallow it, and all the vessels thereof: and it shall be holy.',	'அபிஷேக தைலத்தை எடுத்து, வாசஸ்தலத்தையும் அதிலுள்ள யாவையும் அபிஷேகம்பண்ணி, அதையும் அதிலுள்ள சகல பணிமுட்டுகளையும் பரிசுத்தப்படுத்துவாயாக; அப்பொழுது பரிசுத்தமாயிருக்கும்.',	2,	40,	9),
(2718,	'And thou shalt anoint the altar of the burnt offering, and all his vessels, and sanctify the altar: and it shall be an altar most holy.',	'தகனபலிபீடத்தையும், அதின் சகல பணிமுட்டுகளையும், அபிஷேகம்பண்ணி, அதைப் பரிசுத்தப்படுத்துவாயாக; அப்பொழுது அது மகா பரிசுத்தமான பலிபீடமாயிருக்கும்.',	2,	40,	10),
(2719,	'And thou shalt anoint the laver and his foot, and sanctify it.',	'தொட்டியையும் அதின் பாதத்தையும் அபிஷேகம்பண்ணி, பரிசுத்தப்படுத்துவாயாக.',	2,	40,	11),
(2720,	'And thou shalt bring Aaron and his sons unto the door of the tabernacle of the congregation, and wash them with water.',	'பின்பு ஆரோனையும் அவன் குமாரரையும் ஆசரிப்புக் கூடாரவாசலில் வரச்செய்து, அவர்களை ஜலத்தினால் ஸ்நானம்பண்ணுவித்து,',	2,	40,	12),
(2721,	'And thou shalt put upon Aaron the holy garments, and anoint him, and sanctify him; that he may minister unto me in the priest\'s office.',	'ஆரோனுக்குப் பரிசுத்த வஸ்திரங்களை உடுத்தி, எனக்கு ஆசாரிய ஊழியம் செய்யும்படிக்கு அவனை அபிஷேகம்பண்ணி, அவனைப் பரிசுத்தப்படுத்துவாயாக.',	2,	40,	13),
(2722,	'And thou shalt bring his sons, and clothe them with coats:',	'அவன் குமாரரையும் வரச்செய்து, அவர்களுக்கு அங்கிளை உடுத்தி,',	2,	40,	14),
(2723,	'And thou shalt anoint them, as thou didst anoint their father, that they may minister unto me in the priest\'s office: for their anointing shall surely be an everlasting priesthood throughout their generations.',	'அவர்கள் எனக்கு ஆசாரிய ஊழியம் செய்யும்படி, அவர்களையும், அவர்கள் தகப்பனை அபிஷேகம்பண்ணினபடியே, அபிஷேகம்பண்ணுவாயாக; அவர்கள் பெறும் அந்த அபிஷேகம் தலைமுறைதோறும் நித்திய ஆசாரியத்துவத்துக்கு ஏதுவாயிருக்கும் என்றார்.',	2,	40,	15),
(2724,	'Thus did Moses: according to all that the LORD commanded him, so did he.',	'கர்த்தர் தனக்குக் கற்பித்தபடியெல்லாம் மோசே செய்தான்.',	2,	40,	16),
(2725,	'And it came to pass in the first month in the second year, on the first day of the month, that the tabernacle was reared up.',	'இரண்டாம் வருஷம் முதலாம் மாதம் முதல் தேதியில் வாசஸ்தலம் ஸ்தாபனம்பண்ணப்பட்டது.',	2,	40,	17),
(2726,	'And Moses reared up the tabernacle, and fastened his sockets, and set up the boards thereof, and put in the bars thereof, and reared up his pillars.',	'மோசே கூடாரத்தை எடுப்பித்தான்; அவன் அதின் பாதங்களை வைத்து, அதின் பலகைகளை நிறுத்தி, அதின் தாழ்ப்பாள்களைப் பாய்ச்சி, அதின் தூண்களை நாட்டி,',	2,	40,	18),
(2727,	'And he spread abroad the tent over the tabernacle, and put the covering of the tent above upon it; as the LORD commanded Moses.',	'வாசஸ்தலத்தின்மேல் கூடாரத்தை விரித்து, அதின்மேல் கூடாரத்தின் மூடியை, கர்த்தர் தனக்குக் கற்பித்தபடியே போட்டான்.',	2,	40,	19),
(2728,	'And he took and put the testimony into the ark, and set the staves on the ark, and put the mercy seat above upon the ark:',	'பின்பு, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, சாட்சிப்பிரமாணத்தை எடுத்து, அதைப் பெட்டியிலே வைத்து, பெட்டியில் தண்டுகளைப்பாய்ச்சி, பெட்டியின்மேல் கிருபாசன மூடியை வைத்து,',	2,	40,	20),
(2729,	'And he brought the ark into the tabernacle, and set up the vail of the covering, and covered the ark of the testimony; as the LORD commanded Moses.',	'பெட்டியை வாசஸ்தலத்துக்குள்ளே கொண்டுபோய், மறைவின் திரைச்சீலையைத் தொங்கவைத்து, சாட்சிப்பெட்டியை மறைத்துவைத்தான்.',	2,	40,	21),
(2730,	'And he put the table in the tent of the congregation, upon the side of the tabernacle northward, without the vail.',	'பின்பு, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, மேஜையை ஆசரிப்புக்கூடாரத்தில் வாசஸ்தலத்தின் வடபுறமாய்த் திரைக்குப் புறம்பாக வைத்து,',	2,	40,	22),
(2731,	'And he set the bread in order upon it before the LORD; as the LORD had commanded Moses.',	'அதின்மேல் கர்த்தருடைய சமுகத்தில் அப்பத்தை வரிசையாக அடுக்கிவைத்தான்.',	2,	40,	23),
(2732,	'And he put the candlestick in the tent of the congregation, over against the table, on the side of the tabernacle southward.',	'பின்பு, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, குத்துவிளக்கை ஆசரிப்புக்கூடாரத்தில் மேஜைக்கு எதிராக வாசஸ்தலத்தின் தென்புறத்திலே வைத்து,',	2,	40,	24),
(2733,	'And he lighted the lamps before the LORD; as the LORD commanded Moses.',	'கர்த்தருடைய சந்நிதியில் விளக்குகளை ஏற்றினான்.',	2,	40,	25),
(2734,	'And he put the golden altar in the tent of the congregation before the vail:',	'பின்பு, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, ஆசரிப்புக் கூடாரத்தில் திரைக்கு முன்பாகப் பொற்பீடத்தை வைத்து,',	2,	40,	26),
(2735,	'And he burnt sweet incense thereon; as the LORD commanded Moses.',	'அதின்மேல் சுகந்தவர்க்கத்தினால் தூபங்காட்டினான்.',	2,	40,	27),
(2736,	'And he set up the hanging at the door of the tabernacle.',	'பின்பு, கர்த்தர் மோசேக்குக் கற்பித்தபடியே, வாசஸ்தலத்தின் தொங்குதிரையைத் தூக்கிவைத்து,',	2,	40,	28),
(2737,	'And he put the altar of burnt offering by the door of the tabernacle of the tent of the congregation, and offered upon it the burnt offering and the meat offering; as the LORD commanded Moses.',	'தகனபலிபீடத்தை ஆசரிப்புக்கூடாரமான வாசஸ்தலத்தின் வாசலுக்கு முன்பாக வைத்து, அதின்மேல் சர்வாங்க தகனபலியையும் போஜனபலியையும் செலுத்தினான்.',	2,	40,	29),
(2738,	'And he set the laver between the tent of the congregation and the altar, and put water there, to wash withal.',	'அவன் ஆசரிப்புக் கூடாரத்துக்கும் பலிபீடத்துக்கும் நடுவே தொட்டியை வைத்து, கழுவுகிறதற்கு அதிலே தண்ணீர் வார்த்தான்.',	2,	40,	30),
(2739,	'And Moses and Aaron and his sons washed their hands and their feet thereat:',	'அவ்விடத்திலே மோசேயும் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளையும் கால்களையும் கழுவினார்கள்.',	2,	40,	31),
(2740,	'When they went into the tent of the congregation, and when they came near unto the altar, they washed; as the LORD commanded Moses.',	'கர்த்தர் மோசேக்குக் கற்பித்தபடியே, அவர்கள் ஆசரிப்புக் கூடாரத்துக்குள்ளே பிரவேசிக்கிறபோதும், பலிபீடத்தண்டையில் சேருகிறபோதும், அவர்கள் கழுவிக்கொள்ளுவார்கள்.',	2,	40,	32),
(2741,	'And he reared up the court round about the tabernacle and the altar, and set up the hanging of the court gate. So Moses finished the work.',	'பின்பு, அவன் வாசஸ்தலத்தையும் பலிபீடத்தையும் சுற்றிப் பிராகாரத்தை நிறுத்தி, பிராகாரத்தின் தொங்குதிரையைத் தொங்கவைத்தான்; இவ்விதமாய் மோசே வேலையை முடித்தான்.',	2,	40,	33),
(2742,	'Then a cloud covered the tent of the congregation, and the glory of the LORD filled the tabernacle.',	'அப்பொழுது ஒரு மேகம் ஆசரிப்புக்கூடாரத்தை மூடினது; கர்த்தருடைய மகிமை வாசஸ்தலத்தை நிரப்பிற்று.',	2,	40,	34),
(2743,	'And Moses was not able to enter into the tent of the congregation, because the cloud abode thereon, and the glory of the LORD filled the tabernacle.',	'மேகம் அதின்மேல் தங்கி, கர்த்தருடைய மகிமை வாசஸ்தலத்தை நிரப்பினதினால், மோசே ஆசரிப்புக் கூடாரத்துக்குள் பிரவேசிக்கக்கூடாமல் இருந்தது.',	2,	40,	35),
(2744,	'And when the cloud was taken up from over the tabernacle, the children of Israel went onward in all their journeys:',	'வாசஸ்தலத்திலிருந்து மேகம் மேலே எழும்பும்போது, இஸ்ரவேல் புத்திரர் பிரயாணம்பண்ணப் புறப்படுவார்கள்.',	2,	40,	36),
(2745,	'But if the cloud were not taken up, then they journeyed not till the day that it was taken up.',	'மேகம் எழும்பாதிருந்தால், அது எழும்பும் நாள்வரைக்கும் பிரயாணம்பண்ணாதிருப்பார்கள்.',	2,	40,	37),
(2746,	'For the cloud of the LORD was upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys.',	'இஸ்ரவேல் வம்சத்தார் பண்ணும் எல்லாப் பிரயாணங்களிலும் அவர்களெல்லாருடைய கண்களுக்கும் பிரத்தியட்சமாகப் பகலில் கர்த்தருடைய மேகமும், இரவில் அக்கினியும், வாசஸ்தலத்தின் மேல் தங்கியிருந்தது.    ',	2,	40,	38),
(2747,	'And the LORD called unto Moses, and spake unto him out of the tabernacle of the congregation, saying,',	'கர்த்தர் ஆசரிப்புக் கூடாரத்திலிருந்து மோசேயைக் கூப்பிட்டு, அவனை நோக்கி:',	3,	1,	1),
(2748,	'Speak unto the children of Israel, and say unto them, If any man of you bring an offering unto the LORD, ye shall bring your offering of the cattle, even of the herd, and of the flock.',	'நீ இஸ்ரவேல் புத்திரரிடத்தில் சொல்லவேண்டியது என்னவென்றால், உங்களில் ஒருவன் கர்த்தருக்குப் பலிசெலுத்த வந்தால், மாட்டுமந்தையிலாவது ஆட்டுமந்தையிலாவது ஒரு மிருகத்தைத் தெரிந்தெடுத்து, பலிசெலுத்தவேண்டும்.',	3,	1,	2),
(2749,	'If his offering be a burnt sacrifice of the herd, let him offer a male without blemish: he shall offer it of his own voluntary will at the door of the tabernacle of the congregation before the LORD.',	'அவன் செலுத்துவது மாட்டுமந்தையிலிருந்து எடுக்கப்பட்ட சர்வாங்க தகனபலியானால், அவன் பழுதற்ற ஒரு காளையைச் செலுத்துவானாக; கர்த்தருடைய சந்நிதியில் தான் அங்கிகரிக்கப்படும்படி, அவன் அதை ஆசரிப்புக்கூடார வாசலில் கொண்டுவந்து,',	3,	1,	3),
(2750,	'And he shall put his hand upon the head of the burnt offering; and it shall be accepted for him to make atonement for him.',	'அது தன் பாவநிவிர்த்திக்கென்று அங்கிகரிக்கப்படும்படி தன் கையை அதின் தலையின்மேல் வைத்து,',	3,	1,	4),
(2751,	'And he shall kill the bullock before the LORD: and the priests, Aaron\'s sons, shall bring the blood, and sprinkle the blood round about upon the altar that is by the door of the tabernacle of the congregation.',	'கர்த்தருடைய சந்நிதியில் அந்தக்காளையைக் கொல்லக்கடவன்; அப்பொழுது ஆரோனின் குமாரராகிய ஆசாரியர்கள் அதின் இரத்தத்தை எடுத்து, அதை ஆசரிப்புக் கூடாரவாசலில் இருக்கிற பலிபீடத்தின்மேல் சுற்றிலும் தெளிக்கக்கடவர்கள்.',	3,	1,	5),
(2752,	'And he shall flay the burnt offering, and cut it into his pieces.',	'பின்பு அவன் அந்தச் சர்வாங்க தகனபலியைத் தோலுரித்து, அதைச் சந்துசந்தாகத் துண்டிக்கக்கடவன்.',	3,	1,	6),
(2753,	'And the sons of Aaron the priest shall put fire upon the altar, and lay the wood in order upon the fire:',	'அப்பொழுது ஆசாரியனாகிய ஆரோனின் குமாரர் பலிபீடத்தின்மேல் அக்கினியைப் போட்டு, அக்கினியின்மேல் கட்டைகளை அடுக்கி,',	3,	1,	7),
(2754,	'And the priests, Aaron\'s sons, shall lay the parts, the head, and the fat, in order upon the wood that is on the fire which is upon the altar:',	'அவன் குமாரராகிய ஆசாரியர்கள், துண்டங்களையும் தலையையும் கொழுப்பையும் பலிபீடத்திலுள்ள அக்கினியில் இருக்கிற கட்டைகளின்மேல் அடுக்கிவைக்கக்கடவர்கள்.',	3,	1,	8),
(2755,	'But his inwards and his legs shall he wash in water: and the priest shall burn all on the altar, to be a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.',	'அதின் குடல்களையும் தொடைகளையும் அவன் தண்ணீரினால் கழுவுவானாக; அவைகளையெல்லாம் ஆசாரியன் பலிபீடத்தின்மேல் சர்வாங்க தகனபலியாகத் தகனிக்கக்கடவன்; இது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.',	3,	1,	9),
(2756,	'And if his offering be of the flocks, namely, of the sheep, or of the goats, for a burnt sacrifice; he shall bring it a male without blemish.',	'அவன் செலுத்துவது செம்மறியாட்டு மந்தையிலுள்ள ஆடுகளிலாவது வெள்ளாட்டு மந்தையிலுள்ள ஆடுகளிலாவது எடுக்கப்பட்ட சர்வாங்க தகனபலியானால், பழுதற்ற ஒரு கடாவைக் கொண்டுவந்து,',	3,	1,	10),
(2757,	'And he shall kill it on the side of the altar northward before the LORD: and the priests, Aaron\'s sons, shall sprinkle his blood round about upon the altar.',	'கர்த்தருடைய சந்நிதியில் பலிபீடத்தின் வடபுறத்தில் அதைக் கொல்லக்கடவன்; அப்பொழுது ஆரோனின் குமாரராகிய ஆசாரியர்கள் அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளிக்கக்கடவர்கள்.',	3,	1,	11),
(2758,	'And he shall cut it into his pieces, with his head and his fat: and the priest shall lay them in order on the wood that is on the fire which is upon the altar:',	'பின்பு அவன் அதைச் சந்துசந்தாகத் துண்டித்து, அதின் தலையையும் கொழுப்பையும் கூடவைப்பானாக; அவைகளை ஆசாரியன் பலிபீடத்திலுள்ள அக்கினியில் இருக்கிற கட்டைகளின்மேல் அடுக்கிவைக்கக்கடவன்.',	3,	1,	12),
(2759,	'But he shall wash the inwards and the legs with water: and the priest shall bring it all, and burn it upon the altar: it is a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.',	'குடல்களையும் தொடைகளையும் அவன் தண்ணீரினால் கழுவுவானாக; அவைகளையெல்லாம் ஆசாரியன் கொண்டுவந்து பலிபீடத்தின்மேல் தகனிக்கக்கடவன்; இது சர்வாங்க தகனபலி; இது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.',	3,	1,	13),
(2760,	'And if the burnt sacrifice for his offering to the LORD be of fowls, then he shall bring his offering of turtledoves, or of young pigeons.',	'அவன் கர்த்தருக்குச் செலுத்துவது பறவைகளிலிருந்து எடுக்கப்பட்ட சர்வாங்க தகனபலியானால், காட்டுப் புறாக்களிலாவது புறாக்குஞ்சுகளிலாவது எடுத்துச் செலுத்தக்கடவன்.',	3,	1,	14),
(2761,	'And the priest shall bring it unto the altar, and wring off his head, and burn it on the altar; and the blood thereof shall be wrung out at the side of the altar:',	'அதை ஆசாரியன் பலிபீடத்தண்டையில் கொண்டுவந்து, அதின் தலையைக்கிள்ளி, பலிபீடத்தில் தகனித்து, அதின் இரத்தத்தைப் பலிபீடத்தின் பக்கத்தில் சிந்தவிட்டு,',	3,	1,	15),
(2762,	'And he shall pluck away his crop with his feathers, and cast it beside the altar on the east part, by the place of the ashes:',	'அதின் இரைப்பையை அதின் மலத்தோடுங்கூட எடுத்து, அதைப் பலிபீடத்தண்டையில் கீழ்புறமாகச் சாம்பல் இருக்கிற இடத்திலே எறிந்துவிட்டு,',	3,	1,	16),
(2763,	'And he shall cleave it with the wings thereof, but shall not divide it asunder: and the priest shall burn it upon the altar, upon the wood that is upon the fire: it is a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.',	'பின்பு அதின் செட்டைகளுடன் அதை இரண்டாக்காமல் பிளப்பானாக; பின்பு ஆசாரியன் அதைப் பலிபீடத்திலுள்ள அக்கினியில் இருக்கிற கட்டைகளின்மேல் தகனிக்கக்கடவன்; இது சர்வாங்க தகனபலி; இது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.  ',	3,	1,	17),
(2764,	'And when any will offer a meat offering unto the LORD, his offering shall be of fine flour; and he shall pour oil upon it, and put frankincense thereon:',	'ஒருவன் போஜனபலியாகிய காணிக்கையைக் கர்த்தருக்குச் செலுத்தவேண்டுமானால், அவன் காணிக்கை மெல்லிய மாவாயிருப்பதாக; அவன் அதின்மேல் எண்ணெய் வார்த்து, அதின்மேல் தூபவர்க்கம் போட்டு,',	3,	2,	1),
(2765,	'And he shall bring it to Aaron\'s sons the priests: and he shall take thereout his handful of the flour thereof, and of the oil thereof, with all the frankincense thereof; and the priest shall burn the memorial of it upon the altar, to be an offering made by fire, of a sweet savour unto the LORD:',	'அதை ஆரோனின் குமாரராகிய ஆசாரியர்களிடத்தில் கொண்டுவருவானாக; அப்பொழுது ஆசாரியன் அந்த மாவிலும் எண்ணெயிலும் ஒரு கைப்பிடி நிறைய தூபவர்க்கம் எல்லாவற்றோடும் எடுத்து, அதைப் பலிபீடத்தின்மேல் ஞாபகக்குறியாகத் தகனிக்கக்கடவன்; அது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.',	3,	2,	2),
(2766,	'And the remnant of the meat offering shall be Aaron\'s and his sons\': it is a thing most holy of the offerings of the LORD made by fire.',	'அந்தப் போஜனபலியில் மீதியாயிருப்பது ஆரோனையும் அவன் குமாரரையும் சேரும்; கர்த்தருக்கு இடும் தகனபலிகளில் இது மகா பரிசுத்தமானது.',	3,	2,	3),
(2767,	'And if thou bring an oblation of a meat offering baken in the oven, it shall be unleavened cakes of fine flour mingled with oil, or unleavened wafers anointed with oil.',	'நீ படைப்பது அடுப்பில் பாகம்பண்ணப்பட்ட போஜனபலியானால், அது எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் செய்த புளிப்பில்லா அதிரசங்களாயாவது, எண்ணெய் பூசப்பட்ட புளிப்பில்லா அடைகளாயாவது இருப்பதாக.',	3,	2,	4),
(2768,	'And if thy oblation be a meat offering baken in a pan, it shall be of fine flour unleavened, mingled with oil.',	'நீ படைப்பது தட்டையான சட்டியில் பாகம்பண்ணப்பட்ட போஜனபலியானால், அது எண்ணெயிலே பிசைந்த புளிப்பில்லா மெல்லிய மாவினால் செய்யப்பட்டதாயிருப்பதாக.',	3,	2,	5),
(2769,	'Thou shalt part it in pieces, and pour oil thereon: it is a meat offering.',	'அதைத் துண்டுதுண்டாகப் பிட்டு, அதின்மேல் எண்ணெய் வார்ப்பாயாக; இது ஒரு போஜனபலி.',	3,	2,	6),
(2770,	'And if thy oblation be a meat offering baken in the fryingpan, it shall be made of fine flour with oil.',	'நீ படைப்பது பொரிக்குஞ்சட்டியில் பாகம்பண்ணப்பட்ட போஜனபலியானால், அது எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் செய்யப்படுவதாக.',	3,	2,	7),
(2771,	'And thou shalt bring the meat offering that is made of these things unto the LORD: and when it is presented unto the priest, he shall bring it unto the altar.',	'இப்படிச் செய்யப்பட்ட போஜனபலியைக் கர்த்தருக்குச் செலுத்துவாயாக; அது ஆசாரியனிடத்தில் கொண்டுவரப்படும்போது, அவன் அதைப் பலிபீடத்தண்டையில் கொண்டுவந்து,',	3,	2,	8),
(2772,	'And the priest shall take from the meat offering a memorial thereof, and shall burn it upon the altar: it is an offering made by fire, of a sweet savour unto the LORD.',	'அந்தப் போஜனபலியிலிருந்து ஆசாரியன் ஞாபகக்குறியாக ஒரு பங்கை எடுத்துப் பலிபீடத்தின்மேல் தகனிக்கக்கடவன்; இது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.',	3,	2,	9),
(2773,	'And that which is left of the meat offering shall be Aaron\'s and his sons\': it is a thing most holy of the offerings of the LORD made by fire.',	'இந்தப் போஜனபலியில் மீதியானது ஆரோனையும் அவன் குமாரரையும் சேரும்; கர்த்தருக்கு இடும் தகனங்களில் இது மகா பரிசுத்தமானது.',	3,	2,	10),
(2774,	'No meat offering, which ye shall bring unto the LORD, shall be made with leaven: for ye shall burn no leaven, nor any honey, in any offering of the LORD made by fire.',	'நீங்கள் கர்த்தருக்குச் செலுத்தும் எந்த போஜனபலியும் புளித்தமாவினால் செய்யப்படாதிருப்பதாக; புளித்தமாவுள்ளதொன்றையும் தேனுள்ளதொன்றையும் கர்த்தருக்குத் தகனபலியாகத் தகனிக்கவேண்டாம்.',	3,	2,	11),
(2775,	'As for the oblation of the firstfruits, ye shall offer them unto the LORD: but they shall not be burnt on the altar for a sweet savour.',	'முதற்கனிகளைக் காணிக்கையாகக்கொண்டுவந்து, அவைகளைக் கர்த்தருக்குச் செலுத்தலாம்; ஆனாலும், பலிபீடத்தின்மேல் அவைகள் சுகந்த வாசனையாகத் தகனிக்கப்படலாகாது.',	3,	2,	12),
(2776,	'And every oblation of thy meat offering shalt thou season with salt; neither shalt thou suffer the salt of the covenant of thy God to be lacking from thy meat offering: with all thine offerings thou shalt offer salt.',	'நீ படைக்கிற எந்த போஜனபலியும் உப்பினால் சாரமாக்கப்படுவதாக; உன் தேவனுடைய உடன்படிக்கையின் உப்பை உன் போஜனபலியிலே குறையவிடாமல், நீ படைப்பது எல்லாவற்றோடும் உப்பையும் படைப்பாயாக.',	3,	2,	13),
(2777,	'And if thou offer a meat offering of thy firstfruits unto the LORD, thou shalt offer for the meat offering of thy firstfruits green ears of corn dried by the fire, even corn beaten out of full ears.',	'முதற்பலன்களை போஜனபலியாக நீ கர்த்தருக்குச் செலுத்தவந்தால், நிறைந்த பச்சையான கதிர்களை நெருப்பிலே வாட்டி உதிர்த்து, அதை உன் முதற்பலனின் போஜனபலியாகக் கொண்டுவரக்கடவாய்.',	3,	2,	14),
(2778,	'And thou shalt put oil upon it, and lay frankincense thereon: it is a meat offering.',	'அதின்மேல் எண்ணெய் வார்த்து, அதின்மேல் தூபவர்க்கத்தைப் போடுவாயாக; இது ஒரு போஜனபலி.',	3,	2,	15),
(2779,	'And the priest shall burn the memorial of it, part of the beaten corn thereof, and part of the oil thereof, with all the frankincense thereof: it is an offering made by fire unto the LORD.',	'பின்பு ஆசாரியன், உதிர்த்த தானியத்திலும் எண்ணெயிலும் எடுத்து, ஞாபக்குறியான பங்கை அதின் தூபவர்க்கம் எல்லாவற்றோடுங்கூடத் தகனிக்கக்கடவன்; இது கர்த்தருக்கு இடும் தகனபலி.  ',	3,	2,	16),
(2780,	'And if his oblation be a sacrifice of peace offering, if he offer it of the herd; whether it be a male or female, he shall offer it without blemish before the LORD.',	'ஒருவன் சமாதானபலியைப் படைக்கவேண்டுமென்று, மாட்டுமந்தையில் எடுத்துச் செலுத்துவானாகில், அது காளையானாலும் சரி, பசுவானாலும் சரி, பழுதற்றிருப்பதை கர்த்தருடைய சந்நிதியில் செலுத்தக்கடவன்.',	3,	3,	1),
(2781,	'And he shall lay his hand upon the head of his offering, and kill it at the door of the tabernacle of the congregation: and Aaron\'s sons the priests shall sprinkle the blood upon the altar round about.',	'அவன் தன் பலியின் தலைமேல் தன் கையை வைத்து, ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக அதைக் கொல்லக்கடவன்; அப்பொழுது ஆரோனின் குமாரராகிய ஆசாரியர் அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளிக்கக்கடவர்கள்.',	3,	3,	2),
(2782,	'And he shall offer of the sacrifice of the peace offering an offering made by fire unto the LORD; the fat that covereth the inwards, and all the fat that is upon the inwards,',	'பின்பு சமாதான பலியிலே குடல்களைமூடிய கொழுப்பையும், குடல்களிலுள்ள கொழுப்பு முழுவதையும்,',	3,	3,	3),
(2783,	'And the two kidneys, and the fat that is on them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.',	'இரண்டு குண்டிக்காய்களையும், அவைகளின்மேல் சிறு குடல்களினிடத்தில் இருக்கிற கொழுப்பையும், குண்டிக்காய்களோடேகூடக் கல்லீரலின்மேல் இருக்கிற ஜவ்வையும் எடுத்து, கர்த்தருக்குத் தகனபலியாகச் செலுத்துவானாக.',	3,	3,	4),
(2784,	'And Aaron\'s sons shall burn it on the altar upon the burnt sacrifice, which is upon the wood that is on the fire: it is an offering made by fire, of a sweet savour unto the LORD.',	'அதை ஆரோனின் குமாரர் பலிபீடத்து அக்கினியிலுள்ள கட்டைகளின்மேல் போட்டிருக்கும் சர்வாங்க தகனபலியின்மீதில் போட்டுத் தகனிக்கக்கடவர்கள்; இது கர்த்தருக்குச் சுகந்த வாசனையான தகனபலி.',	3,	3,	5),
(2785,	'And if his offering for a sacrifice of peace offering unto the LORD be of the flock; male or female, he shall offer it without blemish.',	'அவன் கர்த்தருக்குச் சமாதானபலியைப் படைக்கவேண்டுமென்று ஆட்டு மந்தையிலிருந்து எடுத்துச் செலுத்துவானாகில், அது ஆண் ஆனாலும் சரி, பெண் ஆனாலும் சரி, பழுதற்றிருப்பதைச் செலுத்துவானாக.',	3,	3,	6),
(2786,	'If he offer a lamb for his offering, then shall he offer it before the LORD.',	'அவன் ஆட்டுக்குட்டியைப் பலியாகச் செலுத்தவேண்டுமானால், அதைக் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து,',	3,	3,	7),
(2787,	'And he shall lay his hand upon the head of his offering, and kill it before the tabernacle of the congregation: and Aaron\'s sons shall sprinkle the blood thereof round about upon the altar.',	'தன் பலியின் தலைமேல் தன் கையை வைத்து, ஆசரிப்புக் கூடாரத்துக்கு முன்பாக அதைக் கொல்லக்கடவன்; அப்பொழுது ஆரோனின் குமாரர் அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளிக்கக்கடவர்கள்.',	3,	3,	8),
(2788,	'And he shall offer of the sacrifice of the peace offering an offering made by fire unto the LORD; the fat thereof, and the whole rump, it shall he take off hard by the backbone; and the fat that covereth the inwards, and all the fat that is upon the inwards,',	'பின்பு அவன் சமாதானபலியிலே அதின் கொழுப்பையும், நடுவெலும்பிலிருந்து எடுத்த முழு வாலையும், குடல்களை மூடிய கொழுப்பையும் அவைகளின்மேல் இருக்கிற கொழுப்பு முழுவதையும்,',	3,	3,	9),
(2789,	'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.',	'இரண்டு குண்டிக்காய்களையும், அவைகளின்மேல் சிறு குடல்களினிடத்தில் இருக்கிற கொழுப்பையும், குண்டிக்காய்களோடேகூடக் கல்லீரலின்மேல் இருக்கிற ஜவ்வையும் எடுத்து, கர்த்தருக்குத் தகனபலியாகச் செலுத்தக்கடவன்.',	3,	3,	10),
(2790,	'And the priest shall burn it upon the altar: it is the food of the offering made by fire unto the LORD.',	'அதை ஆசாரியன் பலிபீடத்தின்மேல் தகனிக்கக்கடவன்; இது கர்த்தருக்கு இடும் தகன ஆகாரம்.',	3,	3,	11),
(2791,	'And if his offering be a goat, then he shall offer it before the LORD.',	'அவன் செலுத்துவது வெள்ளாடாயிருக்குமானால், அவன் அதை கர்த்தருடைய சந்நிதியில் கொண்டுவந்து,',	3,	3,	12),
(2792,	'And he shall lay his hand upon the head of it, and kill it before the tabernacle of the congregation: and the sons of Aaron shall sprinkle the blood thereof upon the altar round about.',	'அதின் தலைமேல் தன் கையை வைத்து, ஆசரிப்புக் கூடாரத்துக்கு முன்பாக அதைக் கொல்லக்கடவன்; அப்பொழுது ஆரோனின் குமாரர் அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளிக்கக்கடவர்கள்.',	3,	3,	13),
(2793,	'And he shall offer thereof his offering, even an offering made by fire unto the LORD; the fat that covereth the inwards, and all the fat that is upon the inwards,',	'அவன் அதிலே குடல்களை மூடிய கொழுப்பையும், அவைகள் மேலிருக்கிற கொழுப்பு முழுவதையும்,',	3,	3,	14),
(2794,	'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away.',	'இரண்டு குண்டிக்காய்களையும், அவைகளின்மேல் சிறு குடல்களினிடத்தில் இருக்கிற கொழுப்பையும், குண்டிக்காய்களோடேகூடக் கல்லீரலின்மேல் இருக்கிற ஜவ்வையும் எடுத்து, கர்த்தருக்குத் தகனபலியாகச் செலுத்தக்கடவன்.',	3,	3,	15),
(2795,	'And the priest shall burn them upon the altar: it is the food of the offering made by fire for a sweet savour: all the fat is the LORD\'s.',	'ஆசாரியன் பலிபீடத்தின்மேல் அவைகளைத் தகனிக்கக்கடவன்; இது சுகந்த வாசனையான தகன ஆகாரம்; கொழுப்பு முழுவதும் கர்த்தருடையது.',	3,	3,	16),
(2796,	'It shall be a perpetual statute for your generations throughout all your dwellings, that ye eat neither fat nor blood.',	'கொழுப்பையாவது இரத்தத்தையாவது நீங்கள் புசிக்கலாகாது; இது உங்கள் வாசஸ்தலங்கள் எங்கும் உங்கள் தலைமுறைதோறும் நித்திய கட்டளையாயிருக்கும் என்று சொல் என்றார்.  ',	3,	3,	17),
(2797,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	4,	1),
(2798,	'Speak unto the children of Israel, saying, If a soul shall sin through ignorance against any of the commandments of the LORD concerning things which ought not to be done, and shall do against any of them:',	'நீ இஸ்ரவேல் புத்திரரிடத்தில் சொல்லவேண்டியது என்னவென்றால், ஒருவன் கர்த்தருடைய கட்டளைகளில் யாதொன்றை அறியாமையினால் மீறி, செய்யத்தகாததைச் செய்து பாவத்துக்கு உட்பட்டால் அறியவேண்டியதாவது:',	3,	4,	2),
(2799,	'If the priest that is anointed do sin according to the sin of the people; then let him bring for his sin, which he hath sinned, a young bullock without blemish unto the LORD for a sin offering.',	'அபிஷேகம் பெற்ற ஆசாரியன், ஜனங்கள் குற்றத்திற்கு உட்படத்தக்கதாகப் பாவஞ்செய்தால், தான் செய்த பாவத்தினிமித்தம் பழுதற்ற ஒரு இளங்காளையை பாவநிவாரணபலியாகக் கர்த்தருடைய சந்நிதியில் கொண்டுவரக்கடவன்.',	3,	4,	3),
(2800,	'And he shall bring the bullock unto the door of the tabernacle of the congregation before the LORD; and shall lay his hand upon the bullock\'s head, and kill the bullock before the LORD.',	'அவன் அந்தக் காளையை ஆசரிப்புக்கூடாரவாசலில் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, அதின் தலைமேல் தன் கையை வைத்து, கர்த்தருடைய சந்நிதியில் அதைக் கொல்லக்கடவன்.',	3,	4,	4),
(2801,	'And the priest that is anointed shall take of the bullock\'s blood, and bring it to the tabernacle of the congregation:',	'அப்பொழுது, அபிஷேகம் பெற்ற ஆசாரியன் அந்தக் காளையின் இரத்தத்தில் கொஞ்சம் எடுத்து, அதை ஆசரிப்புக்கூடாரத்தில் கொண்டுவந்து,',	3,	4,	5),
(2802,	'And the priest shall dip his finger in the blood, and sprinkle of the blood seven times before the LORD, before the vail of the sanctuary.',	'தன் விரலை இரத்தத்தில் தோய்த்து, பரிசுத்த ஸ்தலத்தின் திரைக்கு எதிரே கர்த்தருடைய சந்நிதியில் ஏழுதரம் தெளிக்கக்கடவன்.',	3,	4,	6),
(2803,	'And the priest shall put some of the blood upon the horns of the altar of sweet incense before the LORD, which is in the tabernacle of the congregation; and shall pour all the blood of the bullock at the bottom of the altar of the burnt offering, which is at the door of the tabernacle of the congregation.',	'பின்பு, ஆசாரியன் அந்த இரத்தத்தில் கொஞ்சம் எடுத்து, ஆசரிப்புக் கூடாரத்திலே கர்த்தருடைய சந்நிதியில் இருக்கும் சுகந்த தூபபீடத்துக் கொம்புகளின்மேல் பூசி, காளையினுடைய மற்ற இரத்தம் முழுவதையும் ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாக இருக்கிற தகனபலிபீடத்தின் அடியிலே ஊற்றிவிட்டு,',	3,	4,	7),
(2804,	'And he shall take off from it all the fat of the bullock for the sin offering; the fat that covereth the inwards, and all the fat that is upon the inwards,',	'பாவநிவாரணபலியான காளையின் எல்லாக் கொழுப்புமாகிய குடல்களை மூடிய கொழுப்பையும், அவைகள்மேல் இருக்கிற கொழுப்பு முழுவதையும்,',	3,	4,	8),
(2805,	'And the two kidneys, and the fat that is upon them, which is by the flanks, and the caul above the liver, with the kidneys, it shall he take away,',	'இரண்டு குண்டிக்காய்களையும், அவைகள்மேல் சிறு குடல்களினிடத்தில் இருக்கிற கொழுப்பையும், குண்டிக்காய்களோடேகூடக் கல்லீரலின்மேல் இருக்கிற ஜவ்வையும்,',	3,	4,	9),
(2806,	'As it was taken off from the bullock of the sacrifice of peace offerings: and the priest shall burn them upon the altar of the burnt offering.',	'சமாதானபலியின் காளையிலிருந்து எடுக்கிறதுபோல அதிலிருந்து எடுத்து, அவைகளைத் தகனபலிபீடத்தின்மேல் தகனிக்கக்கடவன்.',	3,	4,	10),
(2807,	'And the skin of the bullock, and all his flesh, with his head, and with his legs, and his inwards, and his dung,',	'காளையின் தோலையும், அதின் மாம்சம் முழுவதையும், அதின் தலையையும், தொடைகளையும், அதன் குடல்களையும், அதன் சாணியையும்,',	3,	4,	11),
(2808,	'Even the whole bullock shall he carry forth without the camp unto a clean place, where the ashes are poured out, and burn him on the wood with fire: where the ashes are poured out shall he be burnt.',	'காளை முழுவதையும் பாளயத்துக்குப் புறம்பே சாம்பல் கொட்டுகிற சுத்தமான இடத்திலே கொண்டுபோய், கட்டைகளின்மேல் போட்டு, அக்கினியாலே சுட்டெரிக்கக்கடவன்; சாம்பல் கொட்டியிருக்கிற இடத்திலே அதைச்சுட்டெரிக்கக்கடவன்.',	3,	4,	12),
(2809,	'And if the whole congregation of Israel sin through ignorance, and the thing be hid from the eyes of the assembly, and they have done somewhat against any of the commandments of the LORD concerning things which should not be done, and are guilty;',	'இஸ்ரவேல் சபையார் எல்லாரும் அறியாமையினால் பாவஞ்செய்து, காரியம் தங்கள் கண்களுக்கு மறைவாயிருக்கிறதினால், கர்த்தருடைய கட்டளைகளில் யாதொன்றை மீறி, செய்யத்தகாததைச் செய்து, பாவத்துக்குட்பட்டுக் குற்றவாளிகளானால்,',	3,	4,	13),
(2810,	'When the sin, which they have sinned against it, is known, then the congregation shall offer a young bullock for the sin, and bring him before the tabernacle of the congregation.',	'அவர்கள் செய்த பாவம் தெரியவரும்போது, சபையார் அந்தப் பாவத்தினிமித்தம் ஒரு இளங்காளையை ஆசரிப்புக் கூடாரத்துக்கு முன்பாகப் பலியிடக் கொண்டுவரவேண்டும்.',	3,	4,	14),
(2811,	'And the elders of the congregation shall lay their hands upon the head of the bullock before the LORD: and the bullock shall be killed before the LORD.',	'சபையின் மூப்பர் கர்த்தருடைய சந்நிதியில் தங்கள் கைகளை அதின் தலைமேல் வைக்கக்கடவர்கள்; பின்பு கர்த்தருடைய சந்நிதியில் அந்தக் காளையைக் கொல்லவேண்டும்.',	3,	4,	15),
(2812,	'And the priest that is anointed shall bring of the bullock\'s blood to the tabernacle of the congregation:',	'அப்பொழுது, அபிஷேகம் பெற்ற ஆசாரியன் அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, ஆசரிப்புக்கூடாரத்தில் கொண்டுவந்து,',	3,	4,	16),
(2813,	'And the priest shall dip his finger in some of the blood, and sprinkle it seven times before the LORD, even before the vail.',	'தன் விரலை இரத்தத்தில் தோய்த்து, கர்த்தருடைய சந்நிதியில் திரைக்கு எதிரே ஏழுதரம் தெளித்து,',	3,	4,	17),
(2814,	'And he shall put some of the blood upon the horns of the altar which is before the LORD, that is in the tabernacle of the congregation, and shall pour out all the blood at the bottom of the altar of the burnt offering, which is at the door of the tabernacle of the congregation.',	'ஆசரிப்புக் கூடாரத்தில் கர்த்தருடைய சந்நிதியில் இருக்கும் பலிபீடத்தின் கொம்புகளின்மேல் அந்த இரத்தத்தில் கொஞ்சம் பூசி, மற்ற இரத்தமெல்லாம் ஆசரிப்புக் கூடாரவாசலில் இருக்கிற தகனபலிபீடத்தின் அடியிலே ஊற்றிவிட்டு,',	3,	4,	18),
(2815,	'And he shall take all his fat from him, and burn it upon the altar.',	'அதின் கொழுப்பு முழுவதையும் அதிலிருந்து எடுத்து, பலிபீடத்தின்மேல் தகனித்து,',	3,	4,	19),
(2816,	'And he shall do with the bullock as he did with the bullock for a sin offering, so shall he do with this: and the priest shall make an atonement for them, and it shall be forgiven them.',	'பாவநிவாரணபலியின் காளையைச் செய்தபிரகாரம் இந்தக் காளையையும் செய்து, இவ்வண்ணமாய் ஆசாரியன் அவர்களுக்குப் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவர்களுக்கு மன்னிக்கப்படும்.',	3,	4,	20),
(2817,	'And he shall carry forth the bullock without the camp, and burn him as he burned the first bullock: it is a sin offering for the congregation.',	'பின்பு காளையைப் பாளயத்துக்குப் புறம்பே கொண்டுபோய், முந்தின காளையைச் சுட்டெரித்ததுபோலச் சுட்டெரிக்கக்கடவன்; இது சபைக்காகச் செய்யப்படும் பாவநிவாரணபலி.',	3,	4,	21),
(2818,	'When a ruler hath sinned, and done somewhat through ignorance against any of the commandments of the LORD his God concerning things which should not be done, and is guilty;',	'ஒரு பிரபு தன் தேவனாகிய கர்த்தருடைய கட்டளைகளில் யாதொன்றை மீறி, அறியாமையினால் செய்யத்தகாததைச் செய்து, பாவத்துக்குட்பட்டுக் குற்றவாளியானால்,',	3,	4,	22),
(2819,	'Or if his sin, wherein he hath sinned, come to his knowledge; he shall bring his offering, a kid of the goats, a male without blemish:',	'தான் செய்தது பாவம் என்று தனக்குத் தெரியவரும்போது, அவன் வெள்ளாடுகளில் பழுதற்ற ஒரு இளங்கடாவைப் பலியாகக் கொண்டுவந்து,',	3,	4,	23),
(2820,	'And he shall lay his hand upon the head of the goat, and kill it in the place where they kill the burnt offering before the LORD: it is a sin offering.',	'அந்தக் கடாவின் தலைமேல் தன் கையை வைத்து, கர்த்தருடைய சந்நிதியில் சர்வாங்கதகனபலி கொல்லப்படும் இடத்தில் அதைக்கொல்லக்கடவன்; இது பாவநிவாரணபலி.',	3,	4,	24),
(2821,	'And the priest shall take of the blood of the sin offering with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out his blood at the bottom of the altar of burnt offering.',	'அப்பொழுது ஆசாரியன் அதின் இரத்தத்தில் கொஞ்சம் தன் விரலால் எடுத்து, தகனபலிபீடத்துக் கொம்புகளின்மேல் பூசி, மற்ற இரத்தத்தைத் தகனபலிபீடத்தின் அடியிலே ஊற்றிவிட்டு,',	3,	4,	25),
(2822,	'And he shall burn all his fat upon the altar, as the fat of the sacrifice of peace offerings: and the priest shall make an atonement for him as concerning his sin, and it shall be forgiven him.',	'அதின் கொழுப்பு முழுவதையும், சமாதானபலியின் கொழுப்பைப்போல, பலிபீடத்தின்மேல் தகனித்து, இவ்வண்ணமாய் ஆசாரியன் அவன் செய்த பாவத்தைக்குறித்து அவனுக்காகப் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.',	3,	4,	26),
(2823,	'And if any one of the common people sin through ignorance, while he doeth somewhat against any of the commandments of the LORD concerning things which ought not to be done, and be guilty;',	'சாதாரண ஜனங்களில் ஒருவன் அறியாமையினால் கர்த்தரின் கட்டளைகளில் யாதொன்றை மீறி, செய்யத்தகாததைச் செய்து, பாவத்துக்குட்பட்டுக் குற்றவாளியானால்,',	3,	4,	27),
(2824,	'Or if his sin, which he hath sinned, come to his knowledge: then he shall bring his offering, a kid of the goats, a female without blemish, for his sin which he hath sinned.',	'தான் செய்தது பாவம் என்று தனக்குத் தெரியவரும்போது. அவன் தான் செய்த பாவத்தினிமித்தம் வெள்ளாடுகளில் பழுதற்ற ஒரு பெண்குட்டியைப் பலியாகக் கொண்டுவந்து,',	3,	4,	28),
(2825,	'And he shall lay his hand upon the head of the sin offering, and slay the sin offering in the place of the burnt offering.',	'பாவநிவாரணபலியின் தலைமேல் தன் கையை வைத்து, சர்வாங்கதகனபலியிடும் இடத்தில் அந்தப் பாவநிவாரணபலியைக் கொல்லக்கடவன்.',	3,	4,	29),
(2826,	'And the priest shall take of the blood thereof with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out all the blood thereof at the bottom of the altar.',	'அப்பொழுது ஆசாரியன் அதின் இரத்தத்தில் கொஞ்சம் தன் விரலால் எடுத்து, தகனபலிபீடத்துக் கொம்புகளின்மேல் பூசி, மற்ற இரத்தமெல்லாம் பலிபீடத்தின் அடியிலே ஊற்றிவிட்டு,',	3,	4,	30),
(2827,	'And he shall take away all the fat thereof, as the fat is taken away from off the sacrifice of peace offerings; and the priest shall burn it upon the altar for a sweet savour unto the LORD; and the priest shall make an atonement for him, and it shall be forgiven him.',	'சமாதானபலியிலிருந்து கொழுப்பை எடுப்பதுபோல, அதின் கொழுப்பு முழுவதையும் எடுத்து, ஆசாரியன் பலிபீடத்தின்மேல் கர்த்தருக்குச் சுகந்த வாசனையாகத் தகனித்து, இவ்வண்ணமாய் அவனுக்குப் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.',	3,	4,	31),
(2828,	'And if he bring a lamb for a sin offering, he shall bring it a female without blemish.',	'அவன் பாவநிவாரணபலியாக ஒரு ஆட்டுகுட்டியைக் கொண்டுவருவானாகில், பழுதற்ற பெண்குட்டியைக் கொண்டுவந்து,',	3,	4,	32),
(2829,	'And he shall lay his hand upon the head of the sin offering, and slay it for a sin offering in the place where they kill the burnt offering.',	'அந்தப் பாவநிவாரணபலியின் தலைமேல் தன் கையை வைத்து, சர்வாங்கதகனபலி கொல்லப்படும் இடத்தில் அதைப் பாவநிவாரணபலியாகக் கொல்லக்கடவன்.',	3,	4,	33),
(2830,	'And the priest shall take of the blood of the sin offering with his finger, and put it upon the horns of the altar of burnt offering, and shall pour out all the blood thereof at the bottom of the altar:',	'அப்பொழுது ஆசாரியன் அந்தப்பாவநிவாரணபலியின் இரத்தத்தில் கொஞ்சம் தன் விரலால் எடுத்து, தகனபலிபீடத்துக் கொம்புகளின்மேல் பூசி, மற்ற இரத்தமெல்லாம் பலிபீடத்தின் அடியிலே ஊற்றிவிட்டு,',	3,	4,	34),
(2831,	'And he shall take away all the fat thereof, as the fat of the lamb is taken away from the sacrifice of the peace offerings; and the priest shall burn them upon the altar, according to the offerings made by fire unto the LORD: and the priest shall make an atonement for his sin that he hath committed, and it shall be forgiven him.',	'சமாதானபலியான ஆட்டுக்குட்டியின் கொழுப்பை எடுக்கிறதுபோல அதன் கொழுப்பு முழுவதையும் எடுத்து, கர்த்தருக்கு இடப்படும் தகனபலிகளைப்போல, பலிபீடத்தின்மேல் ஆசாரியன் தகனிக்கவேண்டும்; இவ்வண்ணமாய் அவன் செய்த பாவத்துக்கு ஆசாரியன் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.  ',	3,	4,	35),
(2832,	'And if a soul sin, and hear the voice of swearing, and is a witness, whether he hath seen or known of it; if he do not utter it, then he shall bear his iniquity.',	'சாட்சியாகிய ஒருவன், இடப்பட்ட ஆணையைக் கேட்டிருந்தும், தான் கண்டதையும் அறிந்ததையும் தெரிவியாதிருந்து பாவஞ்செய்தால், அவன் தன் அக்கிரமத்தைச் சுமப்பான்.',	3,	5,	1),
(2833,	'Or if a soul touch any unclean thing, whether it be a carcase of an unclean beast, or a carcase of unclean cattle, or the carcase of unclean creeping things, and if it be hidden from him; he also shall be unclean, and guilty.',	'அசுத்தமான காட்டு மிருகத்தின் உடலையாவது, அசுத்தமான நாட்டு மிருகத்தின் உடலையாவது, அசுத்தமான ஊரும் பிராணிகளின் உடலையாவது, இவ்வித அசுத்தமான யாதொரு வஸ்துவையாவது, ஒருவன் அறியாமல் தொட்டால், அவன் தீட்டும் குற்றமும் உள்ளவனாவான்.',	3,	5,	2),
(2834,	'Or if he touch the uncleanness of man, whatsoever uncleanness it be that a man shall be defiled withal, and it be hid from him; when he knoweth of it, then he shall be guilty.',	'அல்லது எந்த அசுத்தத்தினாலாகிலும் தீட்டுப்பட்ட ஒரு மனிதனை ஒருவன் அறியாமல் தொட்டு, பின்பு அதை அறிந்துகொண்டால், அவன் குற்றமுள்ளவனாவான்.',	3,	5,	3),
(2835,	'Or if a soul swear, pronouncing with his lips to do evil, or to do good, whatsoever it be that a man shall pronounce with an oath, and it be hid from him; when he knoweth of it, then he shall be guilty in one of these.',	'மனிதர் பதறி ஆணையிடும் எந்தக்காரியத்திலானாலும், ஒருவன் தீமை செய்கிறதற்காவது நன்மை செய்கிறதற்காவது, தன் மனம் அறியாமல், தன் உதடுகளினால் பதறி ஆணையிட்டு, பின்பு அவன் அதை அறிந்துகொண்டால், அதைக்குறித்துக் குற்றமுள்ளவனாவான்.',	3,	5,	4),
(2836,	'And it shall be, when he shall be guilty in one of these things, that he shall confess that he hath sinned in that thing:',	'இப்படிப்பட்டவைகள் ஒன்றில், ஒருவன் குற்றமுள்ளவனாகும்போது, அவன் தான் செய்தது பாவம் என்று அறிக்கையிட்டு,',	3,	5,	5),
(2837,	'And he shall bring his trespass offering unto the LORD for his sin which he hath sinned, a female from the flock, a lamb or a kid of the goats, for a sin offering; and the priest shall make an atonement for him concerning his sin.',	'தான் செய்த பாவத்துக்குப் பாவநிவாரணபலியாக, ஆடுகளிலாவது வெள்ளாடுகளிலாவது, ஒரு பெண்குட்டியைக் குற்றநிவாரண பலியாகக் கர்த்தருடைய சந்நிதியில் கொண்டுவரவேண்டும்; அதினாலே ஆசாரியன் அவன் செய்த பாவத்தைக்குறித்து அவனுக்காகப் பாவநிவிர்த்தி செய்யக்கடவன்.',	3,	5,	6),
(2838,	'And if he be not able to bring a lamb, then he shall bring for his trespass, which he hath committed, two turtledoves, or two young pigeons, unto the LORD; one for a sin offering, and the other for a burnt offering.',	'ஆட்டுக்குட்டியைக் கொண்டுவர அவனுக்குச் சக்தியில்லாதிருந்தால், அவன் செய்த குற்றத்தினிமித்தம் இரண்டு காட்டுப்புறாக்களையாவது, இரண்டு புறாக்குஞ்சுகளையாவது, ஒன்றைப் பாவநிவாரண பலியாகவும் மற்றொன்றைச் சர்வாங்க தகனபலியாகவும், கர்த்தருடைய சந்நிதியில் கொண்டுவரக்கடவன்.',	3,	5,	7),
(2839,	'And he shall bring them unto the priest, who shall offer that which is for the sin offering first, and wring off his head from his neck, but shall not divide it asunder:',	'அவைகளை ஆசாரியனிடத்தில் கொண்டுவருவானாக; அவன் பாவநிவாரண பலிக்கானதை முன்னே செலுத்தி, அதின் தலையை அதின் கழுத்தினிடத்தில் கிள்ளி, அதை இரண்டாக்காமல் வைத்து,',	3,	5,	8),
(2840,	'And he shall sprinkle of the blood of the sin offering upon the side of the altar; and the rest of the blood shall be wrung out at the bottom of the altar: it is a sin offering.',	'அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, பலிபீடத்தின் பக்கத்தில் தெளித்து, மீதியான இரத்தத்தைப் பலிபீடத்தின் அடியிலே வடியவிடுவானாக; இது பாவநிவாரணபலி.',	3,	5,	9),
(2841,	'And he shall offer the second for a burnt offering, according to the manner: and the priest shall make an atonement for him for his sin which he hath sinned, and it shall be forgiven him.',	'மற்றதை நியமத்தின்படியே அவன் தகனபலியாய்ச் செலுத்தக்கடவன்; இவ்விதமாக அவன் செய்த பாவத்தை ஆசாரியன் நிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.',	3,	5,	10),
(2842,	'But if he be not able to bring two turtledoves, or two young pigeons, then he that sinned shall bring for his offering the tenth part of an ephah of fine flour for a sin offering; he shall put no oil upon it, neither shall he put any frankincense thereon: for it is a sin offering.',	'இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது கொண்டுவர அவனுக்குச் சக்தியில்லாதிருந்தால், பாவம் செய்தவன் பாவநிவாரணத்துக்காக ஒரு எப்பா அளவான மெல்லிய மாவிலே பத்தில் ஒரு பங்கைத் தன் காணிக்கையாகக் கொண்டுவருவானாக; அது பாவநிவாரண பலியாயிருப்பதினால், அதின்மேல் எண்ணெய் வார்க்காமலும் தூபவர்க்கம் போடாமலும் இருந்து,',	3,	5,	11),
(2843,	'Then shall he bring it to the priest, and the priest shall take his handful of it, even a memorial thereof, and burn it on the altar, according to the offerings made by fire unto the LORD: it is a sin offering.',	'அதை ஆசாரியனிடத்தில் கொண்டுவரவேண்டும்; அதிலே ஆசாரியன் ஞாபகக்குறியான பங்காகத் தன் கைப்பிடி நிறைய எடுத்து, கர்த்தருக்கு இடும் தகனபலிகளைப்போல, பலிபீடத்தின் மேல் தகனிக்கக்கடவன்; இது பாவநிவாரணபலி.',	3,	5,	12),
(2844,	'And the priest shall make an atonement for him as touching his sin that he hath sinned in one of these, and it shall be forgiven him: and the remnant shall be the priest\'s, as a meat offering.',	'இவ்விதமாக மேற்சொல்லிய காரியங்கள் ஒன்றில் அவன் செய்த பாவத்துக்காக ஆசாரியன் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும், மீதியானது போஜனபலியைப்போல ஆசாரியனைச் சேரும் என்றார்.',	3,	5,	13),
(2845,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	5,	14),
(2846,	'If a soul commit a trespass, and sin through ignorance, in the holy things of the LORD; then he shall bring for his trespass unto the LORD a ram without blemish out of the flocks, with thy estimation by shekels of silver, after the shekel of the sanctuary, for a trespass offering.',	'ஒருவன் கர்த்தருக்குரிய பரிசுத்தமானவைகளில் குற்றஞ்செய்து, அறியாமையினால் பாவத்துக்குட்பட்டால், அவன் தன் குற்றத்தினிமித்தம் பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்கின்படியே, நீ அவன்மேல் சுமத்தும் அபராதம் எவ்வளவோ, அவ்வளவு வெள்ளிச் சேக்கல் பெறும் பழுதற்ற ஒரு ஆட்டுக்கடாவை குற்றநிவாரணபலியாகக் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து,',	3,	5,	15),
(2847,	'And he shall make amends for the harm that he hath done in the holy thing, and shall add the fifth part thereto, and give it unto the priest: and the priest shall make an atonement for him with the ram of the trespass offering, and it shall be forgiven him.',	'பரிசுத்தமானதைக்குறித்துத் தான் செய்த தப்பிதத்தினால் உண்டான நஷ்டத்தைச் செலுத்தி, அதினோடு ஐந்தில் ஒரு பங்கை அதிகமாகக் கூட்டி, ஆசாரியனுக்குக் கொடுப்பானாக; குற்றநிவாரணபலியாகிய ஆட்டுக்கடாவினாலே அவனுக்காக ஆசாரியன் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.',	3,	5,	16),
(2848,	'And if a soul sin, and commit any of these things which are forbidden to be done by the commandments of the LORD; though he wist it not, yet is he guilty, and shall bear his iniquity.',	'ஒருவன் செய்யத்தகாதென்று கர்த்தருடைய கட்டளைகளினால் விலக்கப்பட்ட யாதொன்றைச் செய்து பாவத்துக்குட்பட்டால், அதை அவன் அறியாமையினால் செய்தாலும், அவன் குற்றமுள்ளவனாயிருந்து, தன் அக்கிரமத்தைச் சுமப்பான்.',	3,	5,	17),
(2849,	'And he shall bring a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest: and the priest shall make an atonement for him concerning his ignorance wherein he erred and wist it not, and it shall be forgiven him.',	'அதினிமித்தம் அவன் குற்றநிவாரணபலியாக, உன் மதிப்புக்குச் சரியான பழுதற்ற ஒரு ஆட்டுக்கடாவை ஆசாரியனிடத்தில் கொண்டுவருவானாக; அவன் அறியாமல் செய்த தப்பிதத்தை ஆசாரியன் அவனுக்காக நிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அது அவனுக்கு மன்னிக்கப்படும்.',	3,	5,	18),
(2850,	'It is a trespass offering: he hath certainly trespassed against the LORD.',	'இது குற்றநிவாரணபலி; அவன் கர்த்தருக்கு விரோதமாய்க் குற்றஞ்செய்தான் என்பது நிச்சயம் என்றார்.  ',	3,	5,	19),
(2851,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	6,	1),
(2852,	'If a soul sin, and commit a trespass against the LORD, and lie unto his neighbour in that which was delivered him to keep, or in fellowship, or in a thing taken away by violence, or hath deceived his neighbour;',	'ஒருவன் கர்த்தருக்கு விரோதமாக அநியாயம் செய்து, தன் வசத்தில் ஒப்புவிக்கப்பட்ட பொருளிலாவது, கொடுக்கல் வாங்கலிலாவது, தன் அயலானுக்கு மாறாட்டம்பண்ணி, அல்லது ஒரு வஸ்துவைப் பலாத்காரமாய்ப் பறித்துக்கொண்டு, அல்லது தன் அயலானுக்கு இடுக்கண்செய்து,',	3,	6,	2),
(2853,	'Or have found that which was lost, and lieth concerning it, and sweareth falsely; in any of all these that a man doeth, sinning therein:',	'அல்லது காணாமற்போனதைக் கண்டடைந்தும் அதை மறுதலித்து, அதைக்குறித்துப் பொய்யாணையிட்டு, மனிதர் செய்யும் இவைமுதலான யாதொரு காரியத்தில் பாவஞ்செய்தானேயாகில்,',	3,	6,	3),
(2854,	'Then it shall be, because he hath sinned, and is guilty, that he shall restore that which he took violently away, or the thing which he hath deceitfully gotten, or that which was delivered him to keep, or the lost thing which he found,',	'அவன் செய்த பாவத்தினாலே குற்றவாளியானபடியால், தான் பலாத்காரமாய்ப் பறித்துக்கொண்டதையும், இடுக்கண்செய்து பெற்றுக்கொண்டதையும், தன் வசத்திலே ஒப்புவிக்கப்பட்டதையும், காணாமற்போயிருந்து தான் கண்டெடுத்ததையும்,',	3,	6,	4),
(2855,	'Or all that about which he hath sworn falsely; he shall even restore it in the principal, and shall add the fifth part more thereto, and give it unto him to whom it appertaineth, in the day of his trespass offering.',	'பொய்யாணையிட்டுச் சம்பாதித்த பொருளையும் திரும்பக் கொடுக்கக்கடவன்; அந்த முதலைக் கொடுக்கிறதும் அல்லாமல், அதினோடு ஐந்தில் ஒரு பங்கு அதிகமாகவுங் கூட்டி, அதைத் தான் குற்றநிவாரணபலியை இடும் நாளில், அதற்குரியவனுக்குக் கொடுத்துவிட்டு,',	3,	6,	5),
(2856,	'And he shall bring his trespass offering unto the LORD, a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest:',	'தன் குற்றநிவாரணபலியாக, உன் மதிப்புக்குச் சரியான பழுதற்ற ஆட்டுக்கடாவைக் கர்த்தருக்குச் செலுத்தும்படி, அதை ஆசாரியனிடத்தில் குற்றநிவாரணபலியாகக் கொண்டுவருவானாக.',	3,	6,	6),
(2857,	'And the priest shall make an atonement for him before the LORD: and it shall be forgiven him for any thing of all that he hath done in trespassing therein.',	'கர்த்தருடைய சந்நிதியில் அவன் பாவத்தை ஆசாரியன் நிவிர்த்திசெய்யக்கடவன்; அப்பொழுது அவன் குற்றவாளியாகச் செய்த அப்படிப்பட்ட எந்தக்காரியமும் அவனுக்கு மன்னிக்கப்படும் என்றார்.',	3,	6,	7),
(2858,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	6,	8),
(2859,	'Command Aaron and his sons, saying, This is the law of the burnt offering: It is the burnt offering, because of the burning upon the altar all night unto the morning, and the fire of the altar shall be burning in it.',	'நீ ஆரோனுக்கும் அவன் குமாரருக்கும் கற்பிக்கவேண்டிய சர்வாங்க தகனபலிக்குரிய பிரமாணம் என்னவென்றால், சர்வாங்க தகனபலியானது இராமுழுவதும் விடியற்காலமட்டும் பலிபீடத்தின்மேல் எரியவேண்டும்; பலிபீடத்தின் மேலுள்ள அக்கினி எரிந்துகொண்டே இருக்கவேண்டும்.',	3,	6,	9),
(2860,	'And the priest shall put on his linen garment, and his linen breeches shall he put upon his flesh, and take up the ashes which the fire hath consumed with the burnt offering on the altar, and he shall put them beside the altar.',	'ஆசாரியன் தன் சணல்நூல் அங்கியைத் தரித்து, தன் சணல்நூல் ஜல்லடத்தை அரையில் போட்டுக்கொண்டு, பலிபீடத்தின்மேல் அக்கினியில் எரிந்த சர்வாங்க தகனபலியின் சாம்பலை எடுத்து, பலிபீடத்துப் பக்கத்தில் கொட்டி,',	3,	6,	10),
(2861,	'And he shall put off his garments, and put on other garments, and carry forth the ashes without the camp unto a clean place.',	'பின்பு தன் வஸ்திரங்களைக் கழற்றி, வேறு வஸ்திரங்களை உடுத்திக்கொண்டு, அந்தச் சாம்பலைப் பாளயத்துக்குப் புறம்பே சுத்தமான ஒரு இடத்திலே கொண்டுபோய்க் கொட்டக்கடவன்.',	3,	6,	11),
(2862,	'And the fire upon the altar shall be burning in it; it shall not be put out: and the priest shall burn wood on it every morning, and lay the burnt offering in order upon it; and he shall burn thereon the fat of the peace offerings.',	'பலிபீடத்தின்மேலிருக்கிற அக்கினி அவியாமல் எரிந்துகொண்டிருக்கவேண்டும்; ஆசாரியன் காலைதோறும் அதின்மேல் எரியும்படி கட்டைகளைப் போட்டு, அதின்மேல் சர்வாங்க தகனபலியை வரிசையாக வைத்து, அதின்மேல் சமாதானபலிகளின் கொழுப்பைப் போட்டுத் தகனிக்கக்கடவன்.',	3,	6,	12),
(2863,	'The fire shall ever be burning upon the altar; it shall never go out.',	'பலிபீடத்தின்மேல் அக்கினி எப்பொழுதும் எரிந்துகொண்டிருக்கவேண்டும்; அது ஒருபொழுதும் அவிந்துபோகலாகாது.',	3,	6,	13),
(2864,	'And this is the law of the meat offering: the sons of Aaron shall offer it before the LORD, before the altar.',	'போஜனபலியின் பிரமாணம் என்னவென்றால், ஆரோனின் குமாரர் அதைக் கர்த்தருடைய சந்நிதியில் பலிபீடத்துக்கு முன்னே படைக்கவேண்டும்.',	3,	6,	14),
(2865,	'And he shall take of it his handful, of the flour of the meat offering, and of the oil thereof, and all the frankincense which is upon the meat offering, and shall burn it upon the altar for a sweet savour, even the memorial of it, unto the LORD.',	'அவன் போஜனபலியின் மெல்லிய மாவிலும் அதின் எண்ணெயிலும் தன் கைப்பிடி நிறைய எடுத்து, போஜனபலியின்மேலுள்ள தூபவர்க்கம் யாவற்றோடும் கூட அதை ஞாபகக்குறியாகப் பலிபீடத்தின்மேல் கர்த்தருக்குச் சுகந்த வாசனையாகத் தகனிக்கக்கடவன்.',	3,	6,	15),
(2866,	'And the remainder thereof shall Aaron and his sons eat: with unleavened bread shall it be eaten in the holy place; in the court of the tabernacle of the congregation they shall eat it.',	'அதில் மீதியானதை ஆரோனும் அவன் குமாரரும் புசிப்பார்களாக; அது புளிப்பில்லா அப்பத்துடன் பரிசுத்த ஸ்தலத்தில் புசிக்கப்படக்கடவது; ஆசரிப்புக் கூடாரத்தின் பிராகாரத்தில் அதைப் புசிக்கவேண்டும்.',	3,	6,	16),
(2867,	'It shall not be baken with leaven. I have given it unto them for their portion of my offerings made by fire; it is most holy, as is the sin offering, and as the trespass offering.',	'அதைப் புளித்தமாவுள்ளதாகப் பாகம்பண்ணவேண்டாம்; அது எனக்கு இடப்படும் தகனங்களில் நான் அவர்களுக்குக் கொடுத்த அவர்களுடைய பங்கு; அது பாவநிவாரண பலியைப்போலும் குற்றநிவாரண பலியைப்போலும் மகா பரிசுத்தமானது.',	3,	6,	17),
(2868,	'All the males among the children of Aaron shall eat of it. It shall be a statute for ever in your generations concerning the offerings of the LORD made by fire: every one that toucheth them shall be holy.',	'ஆரோனின் பிள்ளைகளில் ஆண்மக்கள் யாவரும் அதைப் புசிப்பார்களாக; கர்த்தருக்கு இடப்படும் தகனபலிகளில் அது உங்கள் தலைமுறைதோறும் நித்திய கட்டளையாய் இருக்கக்கடவது; அவைகளைத் தொடுகிறவனெவனும் பரிசுத்தமாய் இருப்பான் என்று சொல் என்றார்.',	3,	6,	18),
(2869,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	6,	19),
(2870,	'This is the offering of Aaron and of his sons, which they shall offer unto the LORD in the day when he is anointed; the tenth part of an ephah of fine flour for a meat offering perpetual, half of it in the morning, and half thereof at night.',	'ஆரோன் அபிஷேகம் பண்ணப்படும் நாளில், அவனும் அவன் குமாரரும் கர்த்தருக்குச் செலுத்தவேண்டிய படைப்பு என்னவென்றால், ஒரு எப்பா அளவான மெல்லிய மாவிலே பத்தில் ஒரு பங்கை, காலையில் பாதியும் மாலையில் பாதியும், நித்திய போஜனபலியாகச் செலுத்தக்கடவர்கள்.',	3,	6,	20),
(2871,	'In a pan it shall be made with oil; and when it is baken, thou shalt bring it in: and the baken pieces of the meat offering shalt thou offer for a sweet savour unto the LORD.',	'அது சட்டியிலே எண்ணெய்விட்டுப் பாகம்பண்ணப்படக்கடவது; பாகம்பண்ணப்பட்டபின்பு அதைக் கொண்டுவந்து, போஜனபலியாகப் பாகம்பண்ணப்பட்ட துண்டுகளைக் கர்த்தருக்குச் சுகந்த வாசனையாகப் படைக்கக்கடவாய்.',	3,	6,	21),
(2872,	'And the priest of his sons that is anointed in his stead shall offer it: it is a statute for ever unto the LORD; it shall be wholly burnt.',	'அவன் குமாரரில் அவனுடைய ஸ்தலத்திலே அபிஷேகம்பண்ணப்படுகிற ஆசாரியனும் அப்படியே செய்யக்கடவன்; அது முழுவதும் தகனிக்கப்படவேண்டும்; அது கர்த்தர் நியமித்த நித்திய கட்டளை.',	3,	6,	22),
(2873,	'For every meat offering for the priest shall be wholly burnt: it shall not be eaten.',	'ஆசாரியனுக்காக இடப்படும் எந்தப் போஜனபலியும் புசிக்கப்படாமல், முழுவதும் தகனிக்கப்படவேண்டும் என்றார்.',	3,	6,	23),
(2874,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	6,	24),
(2875,	'Speak unto Aaron and to his sons, saying, This is the law of the sin offering: In the place where the burnt offering is killed shall the sin offering be killed before the LORD: it is most holy.',	'நீ ஆரோனோடும் அவன் குமாரரோடும் சொல்லவேண்டியதாவது, பாவநிவாரணபலியின் பிரமாணம் என்னவென்றால், சர்வாங்கதகனபலி கொல்லப்படும் இடத்தில் பாவநிவாரணபலியும் கர்த்தருடைய சந்நிதியில் கொல்லப்படக்கடவது; அது மகா பரிசுத்தமானது.',	3,	6,	25),
(2876,	'The priest that offereth it for sin shall eat it: in the holy place shall it be eaten, in the court of the tabernacle of the congregation.',	'பாவநிவிர்த்திசெய்ய அதைப் பலியிடுகிற ஆசாரியன் அதைப் புசிக்கக்கடவன்; ஆசரிப்புக் கூடாரத்தின் பிராகாரமாகிய பரிசுத்த ஸ்தலத்திலே அது புசிக்கப்படவேண்டும்.',	3,	6,	26),
(2877,	'Whatsoever shall touch the flesh thereof shall be holy: and when there is sprinkled of the blood thereof upon any garment, thou shalt wash that whereon it was sprinkled in the holy place.',	'அதின் மாம்சத்தில் படுகிறது எதுவும் பரிசுத்தமாயிருக்கும்; அதின் இரத்தத்திலே கொஞ்சம் ஒரு வஸ்திரத்தில் தெறித்ததானால், இரத்தந்தெறித்த வஸ்திரத்தைப் பரிசுத்த ஸ்தலத்தில் கழுவவேண்டும்.',	3,	6,	27),
(2878,	'But the earthen vessel wherein it is sodden shall be broken: and if it be sodden in a brasen pot, it shall be both scoured, and rinsed in water.',	'அது சமைக்கப்பட்ட மண்பாண்டம் உடைக்கப்படவேண்டும்; செப்புப்பானையில் சமைக்கப்பட்டதானால், அது விளக்கப்பட்டுத் தண்ணீரில் கழுவப்படவேண்டும்.',	3,	6,	28),
(2879,	'All the males among the priests shall eat thereof: it is most holy.',	'ஆசாரியரில் ஆண்மக்கள் யாவரும் அதைப் புசிப்பார்களாக; அது மகா பரிசுத்தமானது.',	3,	6,	29),
(2880,	'And no sin offering, whereof any of the blood is brought into the tabernacle of the congregation to reconcile withal in the holy place, shall be eaten: it shall be burnt in the fire.',	'எந்தப் பாவநிவாரணபலியின் இரத்தத்தில் கொஞ்சம் பரிசுத்த ஸ்தலத்தில் பாவநிவிர்த்தியின்பொருட்டு ஆசரிப்புக்கூடாரத்திற்குள்ளே கொண்டுவரப்பட்டதோ, அந்தப் பலி புசிக்கப்படலாகாது, அது அக்கினியிலே தகனிக்கப்படவேண்டும்.  ',	3,	6,	30),
(2881,	'Likewise this is the law of the trespass offering: it is most holy.',	'குற்றநிவாரணபலியின் பிரமாணம் என்னவென்றால், அது மகா பரிசுத்தமானது.',	3,	7,	1),
(2882,	'In the place where they kill the burnt offering shall they kill the trespass offering: and the blood thereof shall he sprinkle round about upon the altar.',	'சர்வாங்க தகனபலி கொல்லப்படும் இடத்தில், குற்றநிவாரணபலியும் கொல்லப்படவேண்டும்; அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்து,',	3,	7,	2),
(2883,	'And he shall offer of it all the fat thereof; the rump, and the fat that covereth the inwards,',	'அதினுடைய கொழுப்பு முழுவதையும், அதின் வாலையும், குடல்களை மூடிய கொழுப்பையும்,',	3,	7,	3),
(2884,	'And the two kidneys, and the fat that is on them, which is by the flanks, and the caul that is above the liver, with the kidneys, it shall he take away:',	'இரண்டு குண்டிக்காய்களையும், அவைகளின்மேல் சிறுகுடல்களினிடத்திலிருக்கிற கொழுப்பையும், குண்டிக்காய்களோடே கூடக் கல்லீரலின்மேல் இருக்கிற ஜவ்வையும் எடுத்துச் செலுத்துவானாக.',	3,	7,	4),
(2885,	'And the priest shall burn them upon the altar for an offering made by fire unto the LORD: it is a trespass offering.',	'இவைகளை ஆசாரியன் பலிபீடத்தின்மேல் கர்த்தருக்குத் தகனபலியாகத் தகனிக்கக்கடவன்; அது குற்றநிவாரணபலி.',	3,	7,	5),
(2886,	'Every male among the priests shall eat thereof: it shall be eaten in the holy place: it is most holy.',	'ஆசாரியரில் ஆண்மக்கள் யாவரும் அதைப் புசிப்பார்களாக; அது பரிசுத்த ஸ்தலத்தில் புசிக்கப்படவேண்டும்; அது மகா பரிசுத்தமானது.',	3,	7,	6),
(2887,	'As the sin offering is, so is the trespass offering: there is one law for them: the priest that maketh atonement therewith shall have it.',	'பாவநிவாரணபலி எப்படியோ குற்ற நிவாரணபலியும் அப்படியே; அவ்விரண்டிற்கும் பிரமாணம் ஒன்றே; அதினாலே பாவநிவிர்த்தி செய்த ஆசாரியனை அது சேரும்.',	3,	7,	7),
(2888,	'And the priest that offereth any man\'s burnt offering, even the priest shall have to himself the skin of the burnt offering which he hath offered.',	'ஒருவருடைய சர்வாங்க தகனபலியைச் செலுத்தின ஆசாரியன் தான் செலுத்தின தகனபலியின் தோலைத் தனக்காக வைத்துக்கொள்ளவேண்டும்.',	3,	7,	8),
(2889,	'And all the meat offering that is baken in the oven, and all that is dressed in the fryingpan, and in the pan, shall be the priest\'s that offereth it.',	'அடுப்பிலே பாகம்பண்ணப்பட்டதும், சட்டியிலும் தட்டின்மேலும் சமைக்கப்பட்டதுமான போஜனபலி யாவும் அதைச் செலுத்துகிற ஆசாரியனுடையவைகளாயிருக்கும்.',	3,	7,	9),
(2890,	'And every meat offering, mingled with oil, and dry, shall all the sons of Aaron have, one as much as another.',	'எண்ணெயிலே பிசைந்ததும் எண்ணெயிலே பிசையாததுமான சகல போஜனபலியும் ஆரோனுடைய குமாரர் யாவருக்கும் சரிபங்காகச் சேரவேண்டும்.',	3,	7,	10),
(2891,	'And this is the law of the sacrifice of peace offerings, which he shall offer unto the LORD.',	'கர்த்தருக்குச் செலுத்துகிற சமாதானபலிகளின் பிரமாணம் என்னவென்றால்,',	3,	7,	11),
(2892,	'If he offer it for a thanksgiving, then he shall offer with the sacrifice of thanksgiving unleavened cakes mingled with oil, and unleavened wafers anointed with oil, and cakes mingled with oil, of fine flour, fried.',	'அதை ஸ்தோத்திரத்துக்காகச் செலுத்துவானானால், அவன் ஸ்தோத்திர பலியோடுகூட எண்ணெயிலே பிசைந்த புளிப்பில்லா அதிரசங்களையும், எண்ணெய் பூசப்பட்ட புளிப்பில்லா அடைகளையும், எண்ணெயிலே பிசைந்து வறுக்கப்பட்ட மெல்லிய மாவினால் செய்த அதிரசங்களையும் படைக்கக்கடவன்.',	3,	7,	12),
(2893,	'Besides the cakes, he shall offer for his offering leavened bread with the sacrifice of thanksgiving of his peace offerings.',	'அவைகளைப் படைக்கிறதும் அல்லாமல், புளித்தமாவினால் செய்த அப்பத்தையும், தன்னுடைய சமாதானபலியாகிய ஸ்தோத்திரபலியோடுகூட படைக்கவேண்டும்.',	3,	7,	13),
(2894,	'And of it he shall offer one out of the whole oblation for an heave offering unto the LORD, and it shall be the priest\'s that sprinkleth the blood of the peace offerings.',	'அந்தப் படைப்பு முழுவதிலும் வகைக்கு ஒவ்வொன்றை எடுத்துக் கர்த்தருக்கு ஏறெடுத்துப் படைக்கும் பலியாகச் செலுத்துவானாக; அது சமாதானபலியின் இரத்தத்தைத் தெளித்த ஆசாரியனுடையதாகும்.',	3,	7,	14),
(2895,	'And the flesh of the sacrifice of his peace offerings for thanksgiving shall be eaten the same day that it is offered; he shall not leave any of it until the morning.',	'சமாதானபலியாகிய ஸ்தோத்திரபலியின் மாம்சமானது செலுத்தப்பட்ட அன்றைத்தினமே புசிக்கப்படவேண்டும்; அதில் ஒன்றும் விடியற்காலமட்டும் வைக்கப்படலாகாது.',	3,	7,	15),
(2896,	'But if the sacrifice of his offering be a vow, or a voluntary offering, it shall be eaten the same day that he offereth his sacrifice: and on the morrow also the remainder of it shall be eaten:',	'அவன் செலுத்தும் பலி பொருத்தனையாயாவது உற்சாகபலியாயாவது இருக்குமானால், அது செலுத்தப்படும் நாளிலும், அதில் மீதியானது மறுநாளிலும் புசிக்கப்படலாம்.',	3,	7,	16),
(2897,	'But the remainder of the flesh of the sacrifice on the third day shall be burnt with fire.',	'பலியின் மாம்சத்தில் மீதியாயிருக்கிறது மூன்றாம் நாளில் அக்கினியிலே சுட்டெரிக்கப்படக்கடவது.',	3,	7,	17),
(2898,	'And if any of the flesh of the sacrifice of his peace offerings be eaten at all on the third day, it shall not be accepted, neither shall it be imputed unto him that offereth it: it shall be an abomination, and the soul that eateth of it shall bear his iniquity.',	'சமாதானபலியின் மாம்சத்தில் மீதியானது மூன்றாம் நாளில் புசிக்கப்படுமானால், அது அங்கிகரிக்கப்படாது; அதைச் செலுத்தினவனுக்கு அது பலிக்காது; அது அருவருப்பாயிருக்கும்; அதைப் புசிக்கிறவன் தன் அக்கிரமத்தைச் சுமப்பான்.',	3,	7,	18),
(2899,	'And the flesh that toucheth any unclean thing shall not be eaten; it shall be burnt with fire: and as for the flesh, all that be clean shall eat thereof.',	'தீட்டான எந்த வஸ்துவிலாவது அந்த மாம்சம் பட்டதானால் அது புசிக்கப்படாமல் அக்கினியிலே சுட்டெரிக்கப்படக்கடவது; மற்ற மாம்சத்தையோ சுத்தமாயிருக்கிறவனெவனும் புசிக்கலாம்.',	3,	7,	19),
(2900,	'But the soul that eateth of the flesh of the sacrifice of peace offerings, that pertain unto the LORD, having his uncleanness upon him, even that soul shall be cut off from his people.',	'ஒருவன் தீட்டுள்ளவனாயிருக்கையில் கர்த்தருடைய சமாதானபலியின் மாம்சத்தைப் புசித்தால், அவன் தன் ஜனத்தாரில் இராதபடிக்கு அறுப்புண்டுபோவான்.',	3,	7,	20),
(2901,	'Moreover the soul that shall touch any unclean thing, as the uncleanness of man, or any unclean beast, or any abominable unclean thing, and eat of the flesh of the sacrifice of peace offerings, which pertain unto the LORD, even that soul shall be cut off from his people.',	'மனுஷருடைய தீட்டையாவது, தீட்டான மிருகத்தையாவது, அருவருக்கப்படத்தக்க தீட்டான மற்ற எந்த வஸ்துவையாவது ஒருவன் தொட்டிருந்து, கர்த்தருடைய சமாதானபலியின் மாம்சத்திலே புசித்தால், அவன் தன் ஜனங்களில் இராதபடிக்கு அறுப்புண்டுபோவான் என்றார்.',	3,	7,	21),
(2902,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	7,	22),
(2903,	'Speak unto the children of Israel, saying, Ye shall eat no manner of fat, of ox, or of sheep, or of goat.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால், மாடு, ஆடு, வெள்ளாடு என்பவைகளின் கொழுப்பை நீங்கள் புசிக்கலாகாது.',	3,	7,	23),
(2904,	'And the fat of the beast that dieth of itself, and the fat of that which is torn with beasts, may be used in any other use: but ye shall in no wise eat of it.',	'தானாய்ச் செத்த மிருகத்தின் கொழுப்பையும், பீறுண்ட மிருகத்தின் கொழுப்பையும் பலவித வேலைகளுக்கு வழங்கலாம்; ஆனாலும் நீங்கள் அதை ஒருபோதும் புசிக்கலாகாது.',	3,	7,	24),
(2905,	'For whosoever eateth the fat of the beast, of which men offer an offering made by fire unto the LORD, even the soul that eateth it shall be cut off from his people.',	'கர்த்தருக்குத் தகனபலியாகச் செலுத்தப்படும் மிருகத்தின் கொழுப்பைப் புசிக்கிற எந்த ஆத்துமாவும் தன் ஜனங்களில் இராதபடிக்கு அறுப்புண்டுபோவான்.',	3,	7,	25),
(2906,	'Moreover ye shall eat no manner of blood, whether it be of fowl or of beast, in any of your dwellings.',	'உங்கள் வாசஸ்தலங்களில் எங்கும் யாதொரு பறவையின் இரத்தத்தையாவது, யாதொரு மிருகத்தின் இரத்தத்தையாவது புசிக்கலாகாது.',	3,	7,	26),
(2907,	'Whatsoever soul it be that eateth any manner of blood, even that soul shall be cut off from his people.',	'எவ்வித இரத்தத்தையாகிலும் புசிக்கிற எவனும் தன் ஜனங்களில் இராதபடிக்கு அறுப்புண்டுபோவான் என்று சொல் என்றார்.',	3,	7,	27),
(2908,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	7,	28),
(2909,	'Speak unto the children of Israel, saying, He that offereth the sacrifice of his peace offerings unto the LORD shall bring his oblation unto the LORD of the sacrifice of his peace offerings.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால், கர்த்தருக்குச் சமாதானபலி செலுத்துகிறவன் தான் செலுத்தும் சமாதானபலியைக் கர்த்தருடைய சந்நிதியில் கொண்டுவருவானாக.',	3,	7,	29),
(2910,	'His own hands shall bring the offerings of the LORD made by fire, the fat with the breast, it shall he bring, that the breast may be waved for a wave offering before the LORD.',	'கர்த்தருக்குத் தகனபலியாகப் படைப்பவைகளை அவன் கைகளே கொண்டுவரவேண்டும்; மார்க்கண்டத்தையும் அதனோடுகூட அதின்மேல் வைத்த கொழுப்பையும் கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டும்படிக்குக் கொண்டுவரக்கடவன்.',	3,	7,	30),
(2911,	'And the priest shall burn the fat upon the altar: but the breast shall be Aaron\'s and his sons\'.',	'அப்பொழுது ஆசாரியன் அந்தக் கொழுப்பைப் பலிபீடத்தின்மேல் தகனிக்கவேண்டும்; மார்க்கண்டமோ ஆரோனையும் அவன் குமாரரையும் சேரும்.',	3,	7,	31),
(2912,	'And the right shoulder shall ye give unto the priest for an heave offering of the sacrifices of your peace offerings.',	'உங்கள் சமாதானபலிகளில் வலது முன்னந்தொடையை ஏறெடுத்துப்படைக்கும் பலியாகப் படைக்கும்படி ஆசாரியனிடத்தில் கொடுப்பீர்களாக.',	3,	7,	32),
(2913,	'He among the sons of Aaron, that offereth the blood of the peace offerings, and the fat, shall have the right shoulder for his part.',	'ஆரோனுடைய குமாரரில், சமாதானபலியின் இரத்தத்தையும் கொழுப்பையும் செலுத்துகிறவனுக்கு, வலது முன்னந்தொடை பங்காகச் சேரும்.',	3,	7,	33),
(2914,	'For the wave breast and the heave shoulder have I taken of the children of Israel from off the sacrifices of their peace offerings, and have given them unto Aaron the priest and unto his sons by a statute for ever from among the children of Israel.',	'இஸ்ரவேல் புத்திரரின் சமாதானபலிகளில் அசைவாட்டும் மார்க்கண்டத்தையும் ஏறெடுத்துப்படைக்கும் முன்னந்தொடையையும் நான் அவர்கள் கையில் வாங்கி, அவைகளை ஆசாரியனாகிய ஆரோனுக்கும் அவன் குமாரருக்கும் இஸ்ரவேல் புத்திரருக்குள் நடக்கும் நித்திய கட்டளையாகக் கொடுத்தேன் என்று சொல் என்றார்.',	3,	7,	34),
(2915,	'This is the portion of the anointing of Aaron, and of the anointing of his sons, out of the offerings of the LORD made by fire, in the day when he presented them to minister unto the LORD in the priest\'s office;',	'கர்த்தருக்கு ஆசாரிய ஊழியம் செய்யும்படி ஆரோனும் அவன் குமாரரும் நியமிக்கப்பட்ட நாளிலே, இது அபிஷேகம் பண்ணப்பட்ட அவர்களுக்குக் கர்த்தருடைய தகனபலிகளில் கிடைக்கும்படி உண்டான கட்டளை.',	3,	7,	35),
(2916,	'Which the LORD commanded to be given them of the children of Israel, in the day that he anointed them, by a statute for ever throughout their generations.',	'இப்படி அவர்களுக்கு இஸ்ரவேல் புத்திரர் தங்கள் தலைமுறைதோறும் நித்திய நியமமாகக் கொடுக்கும்படி கர்த்தர் அவர்களை அபிஷேகம்பண்ணின நாளிலே கட்டளையிட்டார்.',	3,	7,	36),
(2917,	'This is the law of the burnt offering, of the meat offering, and of the sin offering, and of the trespass offering, and of the consecrations, and of the sacrifice of the peace offerings;',	'சர்வாங்கதகனபலிக்கும் போஜனபலிக்கும் பாவநிவாரணபலிக்கும் குற்றநிவாரணபலிக்கும் பிரதிஷ்டைபலிகளுக்கும் சமாதானபலிகளுக்கும் அடுத்த பிரமாணம் இதுவே.',	3,	7,	37),
(2918,	'Which the LORD commanded Moses in mount Sinai, in the day that he commanded the children of Israel to offer their oblations unto the LORD, in the wilderness of Sinai.',	'கர்த்தருக்குத் தங்கள் பலிகளைச் செலுத்தவேண்டும் என்று அவர் இஸ்ரவேல் புத்திரருக்குச் சீனாய் வனாந்தரத்திலே கற்பிக்கும்போது இவைகளை மோசேக்குச் சீனாய்மலையில் கட்டளையிட்டார்.  ',	3,	7,	38),
(2919,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	3,	8,	1),
(2920,	'Take Aaron and his sons with him, and the garments, and the anointing oil, and a bullock for the sin offering, and two rams, and a basket of unleavened bread;',	'நீ ஆரோனையும் அவன் குமாரரையும் வரவழைத்து, வஸ்திரங்களையும், அபிஷேகத்தைலத்தையும், பாவநிவாரணபலிக்கு ஒரு காளையையும், இரண்டு ஆட்டுக்கடாக்களையும், ஒரு கூடையில் புளிப்பில்லா அப்பங்களையும் கொண்டுவந்து,',	3,	8,	2),
(2921,	'And gather thou all the congregation together unto the door of the tabernacle of the congregation.',	'சபையையெல்லாம் ஆசரிப்புக்கூடாரவாசலுக்கு முன்பாகக் கூடிவரச்செய் என்றார்.',	3,	8,	3),
(2922,	'And Moses did as the LORD commanded him; and the assembly was gathered together unto the door of the tabernacle of the congregation.',	'கர்த்தர் தனக்குக் கட்டளையிட்டபடியே மோசே செய்தான்; சபை ஆசரிப்புக் கூடாரவாசலுக்கு முன்பாகக் கூடினபோது,',	3,	8,	4),
(2923,	'And Moses said unto the congregation, This is the thing which the LORD commanded to be done.',	'மோசே சபையை நோக்கி: செய்யும்படி கர்த்தர் கட்டளையிட்ட காரியம் இதுவே என்று சொல்லி,',	3,	8,	5),
(2924,	'And Moses brought Aaron and his sons, and washed them with water.',	'கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, மோசே ஆரோனையும் அவன் குமாரரையும் வரவழைத்து, அவர்களை ஜலத்தினால் ஸ்நானம்பண்ணுவித்து,',	3,	8,	6),
(2925,	'And he put upon him the coat, and girded him with the girdle, and clothed him with the robe, and put the ephod upon him, and he girded him with the curious girdle of the ephod, and bound it unto him therewith.',	'அவனுக்கு உள்ளங்கியைப் போட்டு, இடைக்கச்சையைக் கட்டி, மேலங்கியை உடுத்தி, ஏபோத்தைத் தரித்து, அதின்மேல் ஏபோத்தின் விசித்திரமான கச்சையைக்கட்டி,',	3,	8,	7),
(2926,	'And he put the breastplate upon him: also he put in the breastplate the Urim and the Thummim.',	'அவனுக்கு மார்ப்பதக்கத்தை அணிந்து, மார்ப்பதக்கத்திலே ஊரீம் தும்மீம் என்பவைகளையும் வைத்து,',	3,	8,	8),
(2927,	'And he put the mitre upon his head; also upon the mitre, even upon his forefront, did he put the golden plate, the holy crown; as the LORD commanded Moses.',	'அவன் தலையிலே பாகையைத் தரித்து, பாகையின்மேல் அவன் நெற்றியிலே பரிசுத்த கிரீடம் என்னும் பொற்பட்டத்தைத் கட்டினான்.',	3,	8,	9),
(2928,	'And Moses took the anointing oil, and anointed the tabernacle and all that was therein, and sanctified them.',	'பின்பு மோசே, அபிஷேகதைலத்தை எடுத்து, வாசஸ்தலத்தையும் அதிலுள்ள யாவற்றையும் அபிஷேகம்பண்ணி, பரிசுத்தப்படுத்தி,',	3,	8,	10),
(2929,	'And he sprinkled thereof upon the altar seven times, and anointed the altar and all his vessels, both the laver and his foot, to sanctify them.',	'அதில் கொஞ்சம் எடுத்து, பலிபீடத்தின்மேல் ஏழுதரம் தெளித்து, பலிபீடத்தையும் அதின் சகல பணிமுட்டுகளையும், தொட்டியையும் அதின் பாதத்தையும் பரிசுத்தப்படுத்தும்படிக்கு அபிஷேகம்பண்ணி,',	3,	8,	11),
(2930,	'And he poured of the anointing oil upon Aaron\'s head, and anointed him, to sanctify him.',	'அபிஷேகதைலத்திலே கொஞ்சம் ஆரோனுடைய சிரசின்மேல் வார்த்து, அவனைப் பரிசுத்தப்படுத்தும்படி அபிஷேகம்பண்ணினான்.',	3,	8,	12),
(2931,	'And Moses brought Aaron\'s sons, and put coats upon them, and girded them with girdles, and put bonnets upon them; as the LORD commanded Moses.',	'பின்பு மோசே, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, ஆரோனின் குமாரரை வரவழைத்து, அவர்களுக்கு அங்கிகளை உடுத்தி, இடைக்கச்சைகளைக்கட்டி, குல்லாக்களைத் தரித்து,',	3,	8,	13),
(2932,	'And he brought the bullock for the sin offering: and Aaron and his sons laid their hands upon the head of the bullock for the sin offering.',	'பாவநிவாரண பலிக்கான காளையைக் கொண்டுவந்தான்; அதினுடைய தலையின்மேல் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளை வைத்தார்கள்;',	3,	8,	14),
(2933,	'And he slew it; and Moses took the blood, and put it upon the horns of the altar round about with his finger, and purified the altar, and poured the blood at the bottom of the altar, and sanctified it, to make reconciliation upon it.',	'அப்பொழுது அது கொல்லப்பட்டது; மோசே அதின் இரத்தத்தை எடுத்து, தன் விரலினால் பலிபீடத்தின் கொம்புகளின்மேல் சுற்றிலும் பூசி, பலிபீடத்திற்காகப் பிராயச்சித்தஞ்செய்து, மற்ற இரத்தத்தைப் பலிபீடத்தின் அடியில் ஊற்றிவிட்டு, அதின்மேல் பாவநிவிர்த்தி செய்யும்பொருட்டு அதைப் பரிசுத்தப்படுத்தினான்.',	3,	8,	15),
(2934,	'And he took all the fat that was upon the inwards, and the caul above the liver, and the two kidneys, and their fat, and Moses burned it upon the altar.',	'பின்பு மோசே, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, குடல்கள்மேல் இருந்த கொழுப்பு முழுவதையும், கல்லீரலின்மேல் இருந்த ஜவ்வையும், இரண்டு குண்டிக்காய்களையும், அவைகளின் கொழுப்பையும் எடுத்து, பலிபீடத்தின்மேல் தகனித்து,',	3,	8,	16),
(2935,	'But the bullock, and his hide, his flesh, and his dung, he burnt with fire without the camp; as the LORD commanded Moses.',	'காளையையும் அதின் தோலையும் மாம்சத்தையும் சாணியையும் பாளயத்துக்குப் புறம்பே அக்கினியிலே சுட்டெரித்தான்.',	3,	8,	17),
(2936,	'And he brought the ram for the burnt offering: and Aaron and his sons laid their hands upon the head of the ram.',	'பின்பு அவன் சர்வாங்க தகனபலிக்கு ஆட்டுக்கடாவைக்கொண்டு வந்தான்; அதின் தலையின்மேல் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளை வைத்தார்கள்.',	3,	8,	18),
(2937,	'And he killed it; and Moses sprinkled the blood upon the altar round about.',	'அப்பொழுது அது கொல்லப்பட்டது; மோசே அதின் இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்தான்.',	3,	8,	19),
(2938,	'And he cut the ram into pieces; and Moses burnt the head, and the pieces, and the fat.',	'ஆட்டுக்கடா சந்துசந்தாகத் துண்டிக்கப்பட்டது; கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, மோசே அதின் தலையையும் துண்டங்களையும் கொழுப்பையும் தகனித்தான்.',	3,	8,	20),
(2939,	'And he washed the inwards and the legs in water; and Moses burnt the whole ram upon the altar: it was a burnt sacrifice for a sweet savour, and an offering made by fire unto the LORD; as the LORD commanded Moses.',	'குடல்களையும் தொடைகளையும் தண்ணீரால் கழுவினபின், மோசே ஆட்டுக்கடா முழுவதையும் பலிபீடத்தின்மேல் கர்த்தருக்குச் சுகந்த வாசனைக்கான சர்வாங்க தகனபலியாகத் தகனித்தான்.',	3,	8,	21),
(2940,	'And he brought the other ram, the ram of consecration: and Aaron and his sons laid their hands upon the head of the ram.',	'பின்பு பிரதிஷ்டைப்படுத்துவதற்குரிய மற்ற ஆட்டுக்கடாவைக் கொண்டுவந்தான்; அதின் தலையின்மேல் ஆரோனும் அவன் குமாரரும் தங்கள் கைகளை வைத்தார்கள்.',	3,	8,	22),
(2941,	'And he slew it; and Moses took of the blood of it, and put it upon the tip of Aaron\'s right ear, and upon the thumb of his right hand, and upon the great toe of his right foot.',	'பின்பு அது கொல்லப்பட்டது; மோசே அதின் இரத்தத்தில் கொஞ்சம் எடுத்து, ஆரோனுடைய வலதுகாதின் மடலிலும் வலதுகையின் பெருவிரலிலும் வலதுகாலின் பெருவிரலிலும் பூசினான்.',	3,	8,	23),
(2942,	'And he brought Aaron\'s sons, and Moses put of the blood upon the tip of their right ear, and upon the thumbs of their right hands, and upon the great toes of their right feet: and Moses sprinkled the blood upon the altar round about.',	'பின்பு ஆரோனுடைய குமாரரையும் அழைத்தான்; மோசே அந்த இரத்தத்திலே கொஞ்சம் அவர்களுடைய வலது காதின் மடலிலும் வலது கையின் பெருவிரலிலும் வலது காலின் பெருவிரலிலும் பூசி, இரத்தத்தைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்து,',	3,	8,	24),
(2943,	'And he took the fat, and the rump, and all the fat that was upon the inwards, and the caul above the liver, and the two kidneys, and their fat, and the right shoulder:',	'கொழுப்பையும், வாலையும், குடல்கள் மேலிருந்த கொழுப்பு முழுவதையும், கல்லீரலின் மேலிருந்த ஜவ்வையும், இரண்டு குண்டிக்காய்களையும், அவைகளின் கொழுப்பையும், வலது முன்னந்தொடையையும் எடுத்து,',	3,	8,	25),
(2944,	'And out of the basket of unleavened bread, that was before the LORD, he took one unleavened cake, and a cake of oiled bread, and one wafer, and put them on the fat, and upon the right shoulder:',	'கர்த்தருடைய சந்நிதியில் வைத்திருந்த புளிப்பில்லா அப்பங்களின் கூடையிலுள்ள புளிப்பில்லா அதிரசத்தில் ஒன்றையும், எண்ணெயிட்ட அப்பமாகிய அதிரசத்தில் ஒன்றையும், ஒரு அடையையும் எடுத்து, அந்தக் கொழுப்பின்மேலும், முன்னந்தொடையின்மேலும் வைத்து,',	3,	8,	26),
(2945,	'And he put all upon Aaron\'s hands, and upon his sons\' hands, and waved them for a wave offering before the LORD.',	'அவைகளையெல்லாம் ஆரோனுடைய உள்ளங்கைகளிலும் அவன் குமாரருடைய உள்ளங்கைகளிலும் வைத்து, அசைவாட்டும் பலியாகக் கர்த்தருடைய சந்நிதியில் அசைவாட்டி,',	3,	8,	27),
(2946,	'And Moses took them from off their hands, and burnt them on the altar upon the burnt offering: they were consecrations for a sweet savour: it is an offering made by fire unto the LORD.',	'பின்பு மோசே அவைகளை அவர்கள் உள்ளங்கைகளிலிருந்து எடுத்து, பலிபீடத்தின்மேலிருக்கிற தகனபலியின்மேல் தகனித்தான்; அவைகள் சுகந்தவாசனையான பிரதிஷ்டைப் பலிகள்; இது கர்த்தருக்குத் தகனபலியானது.',	3,	8,	28),
(2947,	'And Moses took the breast, and waved it for a wave offering before the LORD: for of the ram of consecration it was Moses\' part; as the LORD commanded Moses.',	'பின்பு மோசே மார்க்கண்டத்தை எடுத்து, அதைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டினான். கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே பிரதிஷ்டையின் ஆட்டுக்கடாவிலே அது மோசேயின் பங்காயிற்று.',	3,	8,	29),
(2948,	'And Moses took of the anointing oil, and of the blood which was upon the altar, and sprinkled it upon Aaron, and upon his garments, and upon his sons, and upon his sons\' garments with him; and sanctified Aaron, and his garments, and his sons, and his sons\' garments with him.',	'மோசே அபிஷேகதைலத்திலும், பலிபீடத்தின்மேலிருந்த இரத்தத்திலும் கொஞ்சம் எடுத்து, ஆரோன்மேலும் அவன் வஸ்திரங்கள்மேலும், அவன் குமாரர்மேலும் அவர்கள் வஸ்திரங்கள்மேலும் தெளித்து, ஆரோனையும் அவன் வஸ்திரங்களையும், அவன் குமாரரையும், அவன் குமாரரின் வஸ்திரங்களையும் பரிசுத்தப்படுத்தினான்.',	3,	8,	30),
(2949,	'And Moses said unto Aaron and to his sons, Boil the flesh at the door of the tabernacle of the congregation: and there eat it with the bread that is in the basket of consecrations, as I commanded, saying, Aaron and his sons shall eat it.',	'பின்பு மோசே ஆரோனையும் அவன் குமாரரையும் நோக்கி: நீங்கள் அந்த மாம்சத்தை ஆசரிப்புக் கூடாரவாசலிலே வேவித்து, ஆரோனும் அவன் குமாரரும், அதைப் புசிப்பார்களாக என்று கட்டளையிட்டிருக்கிறபடியே, அங்கே அதையும் உங்கள் பிரதிஷ்டைப் பலிகளுள்ள கூடையில் இருக்கிற அப்பத்தையும் புசித்து,',	3,	8,	31),
(2950,	'And that which remaineth of the flesh and of the bread shall ye burn with fire.',	'மாம்சத்திலும் அப்பத்திலும் மீதியானதை அக்கினியிலே சுட்டெரித்து,',	3,	8,	32),
(2951,	'And ye shall not go out of the door of the tabernacle of the congregation in seven days, until the days of your consecration be at an end: for seven days shall he consecrate you.',	'பிரதிஷ்டையின் நாட்கள் நிறைவேறும்வரைக்கும், ஏழுநாள் ஆசரிப்புக் கூடாரவாசலை விட்டுப் புறப்படாதிருங்கள்; ஏழுநாளளவும் நீங்கள் பிரதிஷ்டைப்படுத்தப்படுவீர்கள்.',	3,	8,	33),
(2952,	'As he hath done this day, so the LORD hath commanded to do, to make an atonement for you.',	'இன்று செய்ததுபோல, உங்கள் பாவநிவிர்த்திக்காக இனிமேலும் செய்யவேண்டும் என்று கர்த்தர் கட்டளையிட்டார்.',	3,	8,	34),
(2953,	'Therefore shall ye abide at the door of the tabernacle of the congregation day and night seven days, and keep the charge of the LORD, that ye die not: for so I am commanded.',	'நீங்கள் சாகாதபடிக்கு ஏழுநாள் இரவும் பகலும் ஆசரிப்புக் கூடாரவாசலிலிருந்து கர்த்தருடைய காவலைக் காக்கக்கடவீர்கள்; இப்படி நான் கற்பிக்கப்பட்டேன் என்றான்.',	3,	8,	35),
(2954,	'So Aaron and his sons did all things which the LORD commanded by the hand of Moses.',	'கர்த்தர் மோசேயைக்கொண்டு கட்டளையிட்ட எல்லாக் காரியங்களையும் ஆரோனும் அவன் குமாரரும் செய்தார்கள்.  ',	3,	8,	36),
(2955,	'And it came to pass on the eighth day, that Moses called Aaron and his sons, and the elders of Israel;',	'எட்டாம் நாளிலே மோசே ஆரோனையும் அவன் குமாரரையும் இஸ்ரவேலின் மூப்பரையும் அழைத்து,',	3,	9,	1),
(2956,	'And he said unto Aaron, Take thee a young calf for a sin offering, and a ram for a burnt offering, without blemish, and offer them before the LORD.',	'ஆரோனை நோக்கி: நீ பாவநிவாரணபலியாகப் பழுதற்ற ஒரு கன்றுக்குட்டியையும், சர்வாங்க தகனபலியாகப் பழுதற்ற ஒரு ஆட்டுக்கடாவையும் தெரிந்துகொண்டு, கர்த்தருடைய சந்நிதியில் பலியிடக்கடவாய்.',	3,	9,	2),
(2957,	'And unto the children of Israel thou shalt speak, saying, Take ye a kid of the goats for a sin offering; and a calf and a lamb, both of the first year, without blemish, for a burnt offering;',	'மேலும் இஸ்ரவேல் புத்திரரை நோக்கி: கர்த்தருடைய சந்நிதியில் பலியிடும்படிக்கு, நீங்கள் பாவநிவாரணபலியாகப் பழுதற்ற ஒரு வெள்ளாட்டுக்கடாவையும், சர்வாங்க தகனபலியாக ஒருவயதான பழுதற்ற ஒரு கன்றுக்குட்டியையும், ஒரு ஆட்டுக்குட்டியையும்,',	3,	9,	3),
(2958,	'Also a bullock and a ram for peace offerings, to sacrifice before the LORD; and a meat offering mingled with oil: for to day the LORD will appear unto you.',	'சமாதானபலிகளாக ஒரு காளையையும், ஒரு ஆட்டுக்கடாவையும், எண்ணெயிலே பிசைந்த போஜனபலியையும் கொண்டுவாருங்கள்; இன்று கர்த்தர் உங்களுக்குத் தரிசனமாவார் என்று சொல் என்றான்.',	3,	9,	4),
(2959,	'And they brought that which Moses commanded before the tabernacle of the congregation: and all the congregation drew near and stood before the LORD.',	'மோசே கட்டளையிட்டவைகளை அவர்கள் ஆசரிப்புக் கூடாரத்துக்கு முன்பாகக் கொண்டுவந்தார்கள். சபையார் எல்லாரும் சேர்ந்து, கர்த்தருடைய சந்நிதியில் நின்றார்கள்.',	3,	9,	5),
(2960,	'And Moses said, This is the thing which the LORD commanded that ye should do: and the glory of the LORD shall appear unto you.',	'அப்பொழுது மோசே: கர்த்தர் கட்டளையிட்ட இந்தக் காரியத்தைச் செய்யுங்கள்; கர்த்தருடைய மகிமை உங்களுக்குக் காணப்படும் என்றான்.',	3,	9,	6),
(2961,	'And Moses said unto Aaron, Go unto the altar, and offer thy sin offering, and thy burnt offering, and make an atonement for thyself, and for the people: and offer the offering of the people, and make an atonement for them; as the LORD commanded.',	'மோசே ஆரோனை நோக்கி: நீ பலிபீடத்தண்டையில் சேர்ந்து, கர்த்தர் கட்டளையிட்டபடியே, உன் பாவநிவாரணபலியையும் உன் சர்வாங்க தகனபலியையும் செலுத்தி, உனக்காகவும் ஜனங்களுக்காகவும் பாவநிவிர்த்தி செய்து, ஜனங்களுடைய பலியையும் செலுத்தி, அவர்களுக்காகவும் பாவநிவிர்த்தி செய் என்றான்.',	3,	9,	7),
(2962,	'Aaron therefore went unto the altar, and slew the calf of the sin offering, which was for himself.',	'அப்பொழுது ஆரோன் பலிபீடத்தண்டையில் சேர்ந்து, தன் பாவநிவாரணபலியாகிய கன்றுக்குட்டியைக் கொன்றான்.',	3,	9,	8),
(2963,	'And the sons of Aaron brought the blood unto him: and he dipped his finger in the blood, and put it upon the horns of the altar, and poured out the blood at the bottom of the altar:',	'ஆரோனின் குமாரர் அதின் இரத்தத்தை அவனிடத்தில் கொண்டுவந்தார்கள்; அவன் தன் விரலை அந்த இரத்தத்தில் தோய்த்து, பலிபீடத்தின் கொம்புகளின் மேல் பூசி, மற்ற இரத்தத்தைப் பலிபீடத்தின் அடியிலே ஊற்றி,',	3,	9,	9),
(2964,	'But the fat, and the kidneys, and the caul above the liver of the sin offering, he burnt upon the altar; as the LORD commanded Moses.',	'பாவநிவாரணபலியின் கொழுப்பையும், குண்டிக்காய்களையும், கல்லீரலில் எடுத்த ஜவ்வையும், கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, பலிபீடத்தின்மேல் தகனித்து,',	3,	9,	10),
(2965,	'And the flesh and the hide he burnt with fire without the camp.',	'மாம்சத்தையும் தோலையும் பாளயத்துக்குப் புறம்பே அக்கினியிலே சுட்டெரித்தான்.',	3,	9,	11),
(2966,	'And he slew the burnt offering; and Aaron\'s sons presented unto him the blood, which he sprinkled round about upon the altar.',	'பின்பு சர்வாங்கதகனபலியையும் கொன்றான்; ஆரோனின் குமாரர் அதின் இரத்தத்தை அவனிடத்தில் கொண்டுவந்தார்கள்; அதை அவன் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்தான்.',	3,	9,	12),
(2967,	'And they presented the burnt offering unto him, with the pieces thereof, and the head: and he burnt them upon the altar.',	'சர்வாங்கதகனபலியின் துண்டங்களையும் தலையையும் அவனிடத்தில் கொண்டுவந்தார்கள்; அவன் அவைகளைப் பலிபீடத்தின்மேல் தகனித்து,',	3,	9,	13),
(2968,	'And he did wash the inwards and the legs, and burnt them upon the burnt offering on the altar.',	'குடல்களையும் தொடைகளையும் கழுவி, பலிபீடத்தின்மேல் இருந்த சர்வாங்க தகனபலியின்மேல் தகனித்தான்.',	3,	9,	14),
(2969,	'And he brought the people\'s offering, and took the goat, which was the sin offering for the people, and slew it, and offered it for sin, as the first.',	'பின்பு அவன் ஜனங்களின் பலியைக்கொண்டுவந்து, ஜனங்களின் பாவநிவிர்த்திக்குரிய வெள்ளாட்டுக்கடாவைக்கொன்று, முந்தினதைப் பலியிட்டது போல, அதைப் பாவநிவாரணபலியாக்கி,',	3,	9,	15),
(2970,	'And he brought the burnt offering, and offered it according to the manner.',	'சர்வாங்கதகனபலியையும் கொண்டுவந்து, நியமத்தின்படி அதைப் பலியிட்டு,',	3,	9,	16),
(2971,	'And he brought the meat offering, and took an handful thereof, and burnt it upon the altar, beside the burnt sacrifice of the morning.',	'போஜனபலியையும் கொண்டுவந்து, அதில் கைநிறைய எடுத்து, அதைக் காலையில் செலுத்தும் சர்வாங்கதகனபலியுடனே பலிபீடத்தின்மேல் தகனித்தான்.',	3,	9,	17),
(2972,	'He slew also the bullock and the ram for a sacrifice of peace offerings, which was for the people: and Aaron\'s sons presented unto him the blood, which he sprinkled upon the altar round about,',	'பின்பு ஜனங்களின் சமாதானபலிகளாகிய காளையையும் ஆட்டுக்கடாவையும் கொன்றான்; ஆரோனின் குமாரர் அதின் இரத்தத்தை அவனிடத்தில் கொண்டுவந்தார்கள்; அவன் அதைப் பலிபீடத்தின்மேல் சுற்றிலும் தெளித்து,',	3,	9,	18),
(2973,	'And the fat of the bullock and of the ram, the rump, and that which covereth the inwards, and the kidneys, and the caul above the liver:',	'காளையிலும் ஆட்டுக்கடாவிலும் எடுத்த கொழுப்பையும், வாலையும், குடல்களை மூடிய ஜவ்வையும், குண்டிக்காய்களையும், கல்லீரலின்மேல் இருந்த ஜவ்வையும் கொண்டுவந்து,',	3,	9,	19),
(2974,	'And they put the fat upon the breasts, and he burnt the fat upon the altar:',	'கொழுப்பை மார்க்கண்டங்களின்மேல் வைத்தார்கள்; அந்தக் கொழுப்பைப் பலிபீடத்தின்மேல் தகனித்தான்.',	3,	9,	20),
(2975,	'And the breasts and the right shoulder Aaron waved for a wave offering before the LORD; as Moses commanded.',	'மார்க்கண்டங்களையும் வலது முன்னந்தொடையையும், மோசே கட்டளையிட்டபடியே, ஆரோன் கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டினான்.',	3,	9,	21),
(2976,	'And Aaron lifted up his hand toward the people, and blessed them, and came down from offering of the sin offering, and the burnt offering, and peace offerings.',	'பின்பு ஆரோன் ஜனங்களுக்கு நேராகத் தன் கைகளை உயர்த்தி, அவர்களை ஆசீர்வதித்து, தான் பாவநிவாரணபலியையும், சர்வாங்கதகனபலியையும், சமாதானபலிகளையும் செலுத்தின இடத்திலிருந்து இறங்கினான்.',	3,	9,	22),
(2977,	'And Moses and Aaron went into the tabernacle of the congregation, and came out, and blessed the people: and the glory of the LORD appeared unto all the people.',	'பின்பு மோசேயும் ஆரோனும் ஆசரிப்புக்கூடாரத்துக்குள் பிரவேசித்து, வெளியே வந்து, ஜனங்களை ஆசீர்வதித்தார்கள்; அப்பொழுது கர்த்தருடைய மகிமை சகல ஜனங்களுக்கும் காணப்பட்டது.',	3,	9,	23),
(2978,	'And there came a fire out from before the LORD, and consumed upon the altar the burnt offering and the fat: which when all the people saw, they shouted, and fell on their faces.',	'அன்றியும் கர்த்தருடைய சந்நிதியிலிருந்து அக்கினி புறப்பட்டு, பலிபீடத்தின்மேல் இருந்த சர்வாங்க தகனபலியையும் கொழுப்பையும் எரித்துவிட்டது; ஜனங்களெல்லாரும் அதைக் கண்டபோது ஆரவாரித்து முகங்குப்புற விழுந்தார்கள்.  ',	3,	9,	24),
(2979,	'And Nadab and Abihu, the sons of Aaron, took either of them his censer, and put fire therein, and put incense thereon, and offered strange fire before the LORD, which he commanded them not.',	'பின்பு ஆரோனின் குமாரராகிய நாதாபும் அபியூவும் தன்தன் தூபகலசத்தை எடுத்து, அவைகளில் அக்கினியையும் அதின்மேல் தூபவர்க்கத்தையும் போட்டு, கர்த்தர் தங்களுக்குக் கட்டளையிடாத அந்நிய அக்கினியை அவருடைய சந்நிதியில் கொண்டுவந்தார்கள்.',	3,	10,	1),
(2980,	'And there went out fire from the LORD, and devoured them, and they died before the LORD.',	'அப்பொழுது அக்கினி கர்த்தருடைய சந்நிதியிலிருந்து புறப்பட்டு, அவர்களைப் பட்சித்தது; அவர்கள் கர்த்தருடைய சந்நிதியில் செத்தார்கள்.',	3,	10,	2),
(2981,	'Then Moses said unto Aaron, This is it that the LORD spake, saying, I will be sanctified in them that come nigh me, and before all the people I will be glorified. And Aaron held his peace.',	'அப்பொழுது மோசே ஆரோனை நோக்கி: என்னிடத்தில் சேருகிறவர்களால் நான் பரிசுத்தம் பண்ணப்பட்டு, சகல ஜனங்களுக்கும் முன்பாக நான் மகிமைப்படுவேன் என்று கர்த்தர் சொன்னது இதுதான் என்றான்; ஆரோன் பேசாதிருந்தான்.',	3,	10,	3),
(2982,	'And Moses called Mishael and Elzaphan, the sons of Uzziel the uncle of Aaron, and said unto them, Come near, carry your brethren from before the sanctuary out of the camp.',	'பின்பு மோசே ஆரோனின் சிறிய தகப்பனான ஊசியேலின் குமாரராகிய மீசவேலையும் எல்சாபானையும் அழைத்து: நீங்கள் கிட்டவந்து, உங்கள் சகோதரரைப் பரிசுத்த ஸ்தலத்துக்கு முன்னின்று எடுத்து, பாளயத்துக்குப் புறம்பே கொண்டுபோங்கள் என்றான்.',	3,	10,	4),
(2983,	'So they went near, and carried them in their coats out of the camp; as Moses had said.',	'மோசே சொன்னபடி அவர்கள் கிட்டவந்து, அவர்களை அவர்கள் உடுத்தியிருந்த சட்டைகளோடும் எடுத்துப் பாளயத்துக்குப் புறம்பே கொண்டுபோனார்கள்.',	3,	10,	5),
(2984,	'And Moses said unto Aaron, and unto Eleazar and unto Ithamar, his sons, Uncover not your heads, neither rend your clothes; lest ye die, and lest wrath come upon all the people: but let your brethren, the whole house of Israel, bewail the burning which the LORD hath kindled.',	'மோசே ஆரோனையும் எலெயாசார் இத்தாமார் என்னும் அவன் குமாரரையும் நோக்கி: நீங்கள் சாகாதபடிக்கும், சபையனைத்தின்மேலும் கடுங்கோபம் வராதபடிக்கும், நீங்கள் உங்கள் தலைப்பாகையை எடுத்துப்போடாமலும், உங்கள் வஸ்திரங்களைக் கிழிக்காமலும் இருப்பீர்களாக; உங்கள் சகோதரராகிய இஸ்ரவேல் குடும்பத்தார் யாவரும் கர்த்தர் கொளுத்தின இந்த அக்கினிக்காகப் புலம்புவார்களாக.',	3,	10,	6),
(2985,	'And ye shall not go out from the door of the tabernacle of the congregation, lest ye die: for the anointing oil of the LORD is upon you. And they did according to the word of Moses.',	'நீங்கள் சாகாதபடிக்கு ஆசரிப்புக்கூடாரவாசலிலிருந்து புறப்படாதிருங்கள்; கர்த்தருடைய அபிஷேகதைலம் உங்கள்மேல் இருக்கிறதே என்றான்; அவர்கள் மோசேயினுடைய வார்த்தையின்படியே செய்தார்கள்.',	3,	10,	7),
(2986,	'And the LORD spake unto Aaron, saying,',	'கர்த்தர் ஆரோனை நோக்கி:',	3,	10,	8),
(2987,	'Do not drink wine nor strong drink, thou, nor thy sons with thee, when ye go into the tabernacle of the congregation, lest ye die: it shall be a statute for ever throughout your generations:',	'நீயும் உன்னோடேகூட உன் குமாரரும் சாகாதிருக்கவேண்டுமானால், ஆசரிப்புக் கூடாரத்துக்குள் பிரவேசிக்கிறபோது, திராட்சரசத்தையும் மதுவையும் குடிக்கவேண்டாம்.',	3,	10,	9),
(2988,	'And that ye may put difference between holy and unholy, and between unclean and clean;',	'பரிசுத்தமுள்ளதற்கும் பரிசுத்தமில்லாததற்கும், தீட்டுள்ளதற்கும் தீட்டில்லாததற்கும், வித்தியாசம் பண்ணும்படிக்கும்,',	3,	10,	10),
(2989,	'And that ye may teach the children of Israel all the statutes which the LORD hath spoken unto them by the hand of Moses.',	'கர்த்தர் மோசேயைக்கொண்டு இஸ்ரவேல் புத்திரருக்குச் சொன்ன சகலபிரமாணங்களையும் அவர்களுக்குப் போதிக்கும்படிக்கும், இது உங்கள் தலைமுறைதோறும் நித்திய கட்டளையாயிருக்கும் என்றார்.',	3,	10,	11),
(2990,	'And Moses spake unto Aaron, and unto Eleazar and unto Ithamar, his sons that were left, Take the meat offering that remaineth of the offerings of the LORD made by fire, and eat it without leaven beside the altar: for it is most holy:',	'மோசே ஆரோனையும் மீதியாயிருந்த அவன் குமாரராகிய எலெயாசாரையும் இத்தாமாரையும் நோக்கி: நீங்கள் கர்த்தருடைய தகனபலிகளில் மீதியான போஜனபலியை எடுத்து, பலிபீடத்தண்டையிலே புளிப்பில்லாததாகப் புசியுங்கள்; அது மகா பரிசுத்தமானது.',	3,	10,	12),
(2991,	'And ye shall eat it in the holy place, because it is thy due, and thy sons\' due, of the sacrifices of the LORD made by fire: for so I am commanded.',	'அதைப் பரிசுத்த ஸ்தலத்திலே புசியுங்கள்; அது கர்த்தருடைய தகனபலிகளில் உனக்கும் உன் குமாரருக்கும் ஏற்படுத்தப்பட்டதாயிருக்கிறது; இப்படிக்கட்டளை பெற்றிருக்கிறேன்.',	3,	10,	13),
(2992,	'And the wave breast and heave shoulder shall ye eat in a clean place; thou, and thy sons, and thy daughters with thee: for they be thy due, and thy sons\' due, which are given out of the sacrifices of peace offerings of the children of Israel.',	'அசைவாட்டும் மார்க்கண்டத்தையும், ஏறெடுத்துப் படைக்கும் முன்னந்தொடையையும், நீயும் உன்னோடேகூட உன் குமாரரும் குமாரத்திகளும் சுத்தமான ஸ்தலத்திலே புசிப்பீர்களாக; இஸ்ரவேல் புத்திரருடைய சமாதானபலிகளில் அவைகள் உனக்கும் உன் பிள்ளைகளுக்கும் கிடைக்கும்படி ஏற்படுத்தப்பட்டிருக்கிறது.',	3,	10,	14),
(2993,	'The heave shoulder and the wave breast shall they bring with the offerings made by fire of the fat, to wave it for a wave offering before the LORD; and it shall be thine, and thy sons\' with thee, by a statute for ever; as the LORD hath commanded.',	'கொழுப்பாகிய தகனபலிகளோடே அவர்கள் கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டும்படி ஏறெடுத்துப் படைக்கும் முன்னந்தொடையையும், அசைவாட்டும் மார்க்கண்டத்தையும் கொண்டுவருவார்கள்; அது கர்த்தர் கட்டளையிட்டபடியே உனக்கும் உன் பிள்ளைகளுக்கும் நித்திய கட்டளையாக ஏற்படுத்தப்பட்டிருக்கிறது என்றான்.',	3,	10,	15),
(2994,	'And Moses diligently sought the goat of the sin offering, and, behold, it was burnt: and he was angry with Eleazar and Ithamar, the sons of Aaron which were left alive, saying,',	'பாவநிவாரணபலியாகச் செலுத்தப்பட்ட வெள்ளாட்டுக்கடாவை மோசே தேடிப்பார்த்தான்; அது தகனிக்கப்பட்டிருந்தது; ஆகையால், மீதியாயிருந்த எலெயாசார் இத்தாமார் என்னும் ஆரோனின் குமாரர்மேல் அவன் கோபங்கொண்டு:',	3,	10,	16),
(2995,	'Wherefore have ye not eaten the sin offering in the holy place, seeing it is most holy, and God hath given it you to bear the iniquity of the congregation, to make atonement for them before the LORD?',	'பாவநிவாரணபலியை நீங்கள் பரிசுத்த ஸ்தலத்தில் புசியாமற்போனதென்ன? அது மகா பரிசுத்தமாயிருக்கிறதே; சபையின் அக்கிரமத்தைச் சுமந்து தீர்ப்பதற்குக் கர்த்தருடைய சந்நிதியில் அவர்களுக்காகப் பாவநிவிர்த்தி செய்யும்பொருட்டு, அதை உங்களுக்கு கொடுத்தாரே.',	3,	10,	17),
(2996,	'Behold, the blood of it was not brought in within the holy place: ye should indeed have eaten it in the holy place, as I commanded.',	'அதின் இரத்தம் பரிசுத்த ஸ்தலத்துக்குள்ளே கொண்டுவரப்படவில்லையே; நான் கட்டளையிட்டபடி நீங்கள் அதைப்பரிசுத்த ஸ்தலத்தில் புசிக்கவேண்டியதாயிருந்ததே என்றான்.',	3,	10,	18),
(2997,	'And Aaron said unto Moses, Behold, this day have they offered their sin offering and their burnt offering before the LORD; and such things have befallen me: and if I had eaten the sin offering to day, should it have been accepted in the sight of the LORD?',	'அப்பொழுது ஆரோன் மோசையை நோக்கி: அவர்கள் தங்கள் பாவநிவாரணபலியையும், தங்கள் சர்வாங்கதகனபலியையும் கர்த்தருடைய சந்நிதியில் செலுத்தின இன்றுதானே எனக்கு இப்படி நேரிட்டதே; பாவநிவாரணபலியை இன்று நான் புசித்தேனானால், அது கர்த்தரின் பார்வைக்கு நன்றாய் இருக்குமோ என்றான்.',	3,	10,	19),
(2998,	'And when Moses heard that, he was content.',	'மோசே அதைக் கேட்டபோது அமைதலாயிருந்தான்.  ',	3,	10,	20),
(2999,	'And the LORD spake unto Moses and to Aaron, saying unto them,',	'கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	3,	11,	1),
(3000,	'Speak unto the children of Israel, saying, These are the beasts which ye shall eat among all the beasts that are on the earth.',	'நீங்கள் இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால், பூமியிலிருக்கிற சகல மிருகங்களிலும் நீங்கள் புசிக்கத்தக்க ஜீவ ஜந்துக்கள் யாதெனில்:',	3,	11,	2),
(3001,	'Whatsoever parteth the hoof, and is clovenfooted, and cheweth the cud, among the beasts, that shall ye eat.',	'மிருகங்களில் விரிகுளம்புள்ளதாயிருந்து, குளம்புகள் இரண்டாகப் பிரிந்திருக்கிறதும் அசைபோடுகிறதுமானவைகளையெல்லாம் நீங்கள் புசிக்கலாம்.',	3,	11,	3),
(3002,	'Nevertheless these shall ye not eat of them that chew the cud, or of them that divide the hoof: as the camel, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.',	'ஆனாலும், அசைபோடுகிறதும் விரிகுளம்புள்ளதுமானவைகளில் ஒட்டகமானது அசைபோடுகிறதாயிருந்தாலும், அதற்கு விரிகுளம்பில்லாதபடியால், அது உங்களுக்கு அசுத்தமாயிருக்கும்.',	3,	11,	4),
(3003,	'And the coney, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.',	'குழிமுசலானது அசைபோடுகிறதாயிருந்தாலும், அதற்கு விரிகுளம்பில்லை; அது உங்களுக்கு அசுத்தமாயிருக்கும்.',	3,	11,	5),
(3004,	'And the hare, because he cheweth the cud, but divideth not the hoof; he is unclean unto you.',	'முயலானது அசைபோடுகிறதாயிருந்தும், அதற்கு விரிகுளம்பில்லை; அது உங்களுக்கு அசுத்தமாயிருக்கும்.',	3,	11,	6),
(3005,	'And the swine, though he divide the hoof, and be clovenfooted, yet he cheweth not the cud; he is unclean to you.',	'பன்றியின் குளம்பு விரிகுளம்பும் இரண்டாகப் பிரிந்ததுமாயிருந்தும், அது அசைபோடாது; அது உங்களுக்கு அசுத்தமாயிருக்கும்.',	3,	11,	7),
(3006,	'Of their flesh shall ye not eat, and their carcase shall ye not touch; they are unclean to you.',	'இவைகளின் மாம்சத்தைப் புசிக்கவும், இவைகளின் உடல்களைத் தொடவும் வேண்டாம்; இவைகள் உங்களுக்குத் தீட்டாயிருக்கக்கடவது.',	3,	11,	8),
(3007,	'These shall ye eat of all that are in the waters: whatsoever hath fins and scales in the waters, in the seas, and in the rivers, them shall ye eat.',	'ஜலத்திலிருக்கிறவைகளில் நீங்கள் புசிக்கத்தக்கது யாதெனில்: கடல்களும் ஆறுகளுமாகிய தண்ணீர்களிலே சிறகும் செதிளும் உள்ளவைகளையெல்லாம் நீங்கள் புசிக்கலாம்.',	3,	11,	9),
(3008,	'And all that have not fins and scales in the seas, and in the rivers, of all that move in the waters, and of any living thing which is in the waters, they shall be an abomination unto you:',	'ஆனாலும், கடல்களும் ஆறுகளுமாகிய தண்ணீர்களில் நீந்துகிறதும் வாழ்கிறதுமான பிராணிகளில் சிறகும் செதிளும் இல்லாதவைகள் யாவும் உங்களுக்கு அருவருப்பாயிருப்பதாக.',	3,	11,	10),
(3009,	'They shall be even an abomination unto you; ye shall not eat of their flesh, but ye shall have their carcases in abomination.',	'அவைகள் உங்களுக்கு அருவருப்பாயிருக்கக்கடவது; அவைகளின் மாம்சத்தைப் புசியாதிருந்து, அவைகளின் உடல்களை அருவருப்பீர்களாக.',	3,	11,	11),
(3010,	'Whatsoever hath no fins nor scales in the waters, that shall be an abomination unto you.',	'தண்ணீர்களிலே சிறகும் செதிளும் இல்லாத யாவும் உங்களுக்கு அருவருப்பாயிருக்கக்கடவது.',	3,	11,	12),
(3011,	'And these are they which ye shall have in abomination among the fowls; they shall not be eaten, they are an abomination: the eagle, and the ossifrage, and the ospray,',	'பறவைகளில் நீங்கள் புசியாமல் அருவருக்கவேண்டியவைகள் யாதெனில்: கழுகும், கருடனும், கடலுராஞ்சியும்,',	3,	11,	13),
(3012,	'And the vulture, and the kite after his kind;',	'பருந்தும், சகலவித வல்லூறும்,',	3,	11,	14),
(3013,	'Every raven after his kind;',	'சகலவித காகங்களும்,',	3,	11,	15),
(3014,	'And the owl, and the night hawk, and the cuckow, and the hawk after his kind,',	'தீக்குருவியும், கூகையும், செம்புகமும், சகலவித டேகையும்,',	3,	11,	16),
(3015,	'And the little owl, and the cormorant, and the great owl,',	'ஆந்தையும், நீர்க்காகமும், கோட்டானும்,',	3,	11,	17),
(3016,	'And the swan, and the pelican, and the gier eagle,',	'நாரையும், கூழக்கடாவும், குருகும்,',	3,	11,	18),
(3017,	'And the stork, the heron after her kind, and the lapwing, and the bat.',	'கொக்கும், சகலவித ராஜாளியும், புழுக்கொத்தியும், வௌவாலும் ஆகிய இவைகளே.',	3,	11,	19),
(3018,	'All fowls that creep, going upon all four, shall be an abomination unto you.',	'பறக்கிறவைகளில் நாலுகாலால் நடமாடுகிற ஊரும்பிராணிகள் யாவும் உங்களுக்கு அருவருப்பாயிருப்பதாக.',	3,	11,	20),
(3019,	'Yet these may ye eat of every flying creeping thing that goeth upon all four, which have legs above their feet, to leap withal upon the earth;',	'ஆகிலும், பறக்கிறவைகளில் நாலுகாலால் நடமாடுகிற யாவிலும், நீங்கள் புசிக்கத்தக்கது யாதெனில்: தரையிலே தத்துகிறதற்குக் கால்களுக்குமேல் தொடைகள் உண்டாயிருக்கிறவைகளிலே,',	3,	11,	21),
(3020,	'Even these of them ye may eat; the locust after his kind, and the bald locust after his kind, and the beetle after his kind, and the grasshopper after his kind.',	'வெட்டுக்கிளி ஜாதியாயிருக்கிறதையும், சோலையாம் என்னும் கிளிஜாதியாயிருக்கிறதையும், அர்கொல் என்னும் கிளிஜாதியாயிருக்கிறதையும், ஆகாபு என்னும் கிளிஜாதியாயிருக்கிறதையும் நீங்கள் புசிக்கலாம்.',	3,	11,	22),
(3021,	'But all other flying creeping things, which have four feet, shall be an abomination unto you.',	'பறக்கிறவைகளில் நாலு காலால் நடமாடுகிற மற்ற யாவும் உங்களுக்கு அருவருப்பாயிருப்பதாக.',	3,	11,	23),
(3022,	'And for these ye shall be unclean: whosoever toucheth the carcase of them shall be unclean until the even.',	'அவைகளாலே தீட்டுப்படுவீர்கள்; அவைகளின் உடலைத் தொடுகிறவன் எவனும் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	24),
(3023,	'And whosoever beareth ought of the carcase of them shall wash his clothes, and be unclean until the even.',	'அவைகளின் உடலைச் சுமந்தவன் எவனும் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	25),
(3024,	'The carcases of every beast which divideth the hoof, and is not clovenfooted, nor cheweth the cud, are unclean unto you: every one that toucheth them shall be unclean.',	'விரிநகங்களுள்ளவைகளாயிருந்தும், இருபிளவான குளம்பில்லாமலும் அசைபோடாமலும் இருக்கிற மிருகங்கள் யாவும் உங்களுக்கு அசுத்தமாயிருப்பதாக; அவைகளைத் தொடுகிறவன் எவனும் தீட்டுப்படுவான்.',	3,	11,	26),
(3025,	'And whatsoever goeth upon his paws, among all manner of beasts that go on all four, those are unclean unto you: whoso toucheth their carcase shall be unclean until the even.',	'நாலுகாலால் நடக்கிற சகல ஜீவன்களிலும் தங்கள் உள்ளங்கால்களை ஊன்றி நடக்கிற யாவும் உங்களுக்கு அசுத்தமாயிருப்பதாக; அவைகளின் உடலைத்தொடுகிறவன் எவனும் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	27),
(3026,	'And he that beareth the carcase of them shall wash his clothes, and be unclean until the even: they are unclean unto you.',	'அவைகளின் உடலைச் சுமந்தவன் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்; இவைகள் உங்களுக்குத் தீட்டாயிருக்கக்கடவது.',	3,	11,	28),
(3027,	'These also shall be unclean unto you among the creeping things that creep upon the earth; the weasel, and the mouse, and the tortoise after his kind,',	'தரையில் ஊருகிற பிராணிகளில் உங்களுக்கு அசுத்தமானவைகள் எவையெனில்: பெருச்சாளியும், எலியும், சகலவிதமான ஆமையும்,',	3,	11,	29),
(3028,	'And the ferret, and the chameleon, and the lizard, and the snail, and the mole.',	'உடும்பும், அழுங்கும், ஓணானும், பல்லியும், பச்சோந்தியும் ஆகிய இவைகளே.',	3,	11,	30),
(3029,	'These are unclean to you among all that creep: whosoever doth touch them, when they be dead, shall be unclean until the even.',	'சகல ஊரும் பிராணிகளிலும் இவைகள் உங்களுக்குத் தீட்டாயிருக்கக்கடவது; அவைகளில் செத்ததைத் தொடுகிறவன் எவனும் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	31),
(3030,	'And upon whatsoever any of them, when they are dead, doth fall, it shall be unclean; whether it be any vessel of wood, or raiment, or skin, or sack, whatsoever vessel it be, wherein any work is done, it must be put into water, and it shall be unclean until the even; so it shall be cleansed.',	'அவைகளில் செத்தது ஒன்று யாதொன்றின்மேல் விழுந்தால் அது தீட்டுப்பட்டிருக்கும்; அது மரப்பாத்திரமானாலும், வஸ்திரமானாலும், தோலானாலும், பையானாலும், வேலை செய்கிறதற்கேற்ற ஆயுதமானாலும் சாயங்காலம்மட்டும் தீட்டாயிருக்கும்; அது தண்ணீரில் போடப்படவேண்டும், அப்பொழுது சுத்தமாகும்.',	3,	11,	32),
(3031,	'And every earthen vessel, whereinto any of them falleth, whatsoever is in it shall be unclean; and ye shall break it.',	'அவைகளில் ஒன்று மண்பாண்டத்திற்குள் விழுந்தால், அதற்குள் இருக்கிறவை யாவும் தீட்டுப்பட்டிருக்கும்; அதை உடைத்துப்போடவேண்டும்.',	3,	11,	33),
(3032,	'Of all meat which may be eaten, that on which such water cometh shall be unclean: and all drink that may be drunk in every such vessel shall be unclean.',	'புசிக்கத்தக்க போஜனபதார்த்தத்தின்மேல் அந்தத் தண்ணீர் பட்டால், அது தீட்டாகும்; குடிக்கத்தக்க எந்தப்பானமும் அப்படிப்பட்ட பாத்திரத்தினால் தீட்டுப்படும்.',	3,	11,	34),
(3033,	'And every thing whereupon any part of their carcase falleth shall be unclean; whether it be oven, or ranges for pots, they shall be broken down: for they are unclean and shall be unclean unto you.',	'அவைகளின் உடலில் யாதொன்று எதின்மேல் விழுதோ, அதுவும் தீட்டுப்படும்; அடுப்பானாலும் மண்தொட்டியானாலும் தகர்க்கப்படுவதாக; அவைகள் தீட்டுப்பட்டிருக்கும்; ஆகையால், அவைகள் உங்களுக்குத் தீட்டாயிருக்கக்கடவது.',	3,	11,	35),
(3034,	'Nevertheless a fountain or pit, wherein there is plenty of water, shall be clean: but that which toucheth their carcase shall be unclean.',	'ஆனாலும், நீரூற்றும் மிகுந்த ஜலம் உண்டாகிய கிணறும், சுத்தமாயிருக்கும்; அவைகளிலுள்ள உடலைத் தொடுகிறவனோ தீட்டுப்படுவான்.',	3,	11,	36),
(3035,	'And if any part of their carcase fall upon any sowing seed which is to be sown, it shall be clean.',	'மேற்சொல்லியவைகளின் உடலில் யாதொன்று விதைத்தானியத்தின்மேல் விழுந்தால், அது தீட்டுப்படாது.',	3,	11,	37),
(3036,	'But if any water be put upon the seed, and any part of their carcase fall thereon, it shall be unclean unto you.',	'அந்த உடலில் யாதொன்று தண்ணீர் வார்க்கப்பட்டிருக்கிற விதையின்மேல் விழுந்ததானால், அது உங்களுக்குத் தீட்டாயிருக்கக்கடவது.',	3,	11,	38),
(3037,	'And if any beast, of which ye may eat, die; he that toucheth the carcase thereof shall be unclean until the even.',	'உங்களுக்கு ஆகாரத்துக்கான ஒரு மிருகம் செத்தால், அதின் உடலைத்தொடுகிறவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	39),
(3038,	'And he that eateth of the carcase of it shall wash his clothes, and be unclean until the even: he also that beareth the carcase of it shall wash his clothes, and be unclean until the even.',	'அதின் மாம்சத்தைப் புசித்தவன் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்; அதின் உடலை எடுத்துப்போனவனும் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அவனும் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	11,	40),
(3039,	'And every creeping thing that creepeth upon the earth shall be an abomination; it shall not be eaten.',	'தரையில் ஊருகிற பிராணிகளெல்லாம் உங்களுக்கு அருவருப்பாயிருக்கக்கடவது; அவை புசிக்கப்படலாகாது.',	3,	11,	41),
(3040,	'Whatsoever goeth upon the belly, and whatsoever goeth upon all four, or whatsoever hath more feet among all creeping things that creep upon the earth, them ye shall not eat; for they are an abomination.',	'தரையில் ஊருகிற சகல பிராணிகளிலும், வயிற்றினால் நகருகிறவைகளையும், நாலுகாலால் நடமாடுகிறவைகளையும் அநேகங் கால்களுள்ளவைகளையும் புசியாதிருப்பீர்களாக; அவைகள் அருவருப்பானவைகள்.',	3,	11,	42),
(3041,	'Ye shall not make yourselves abominable with any creeping thing that creepeth, neither shall ye make yourselves unclean with them, that ye should be defiled thereby.',	'ஊருகிற எந்தப் பிராணிகளிலும் உங்களை அருவருப்பாக்கிக்கொள்ளாமலும், அவைகளால் தீட்டுப்படாமலும் இருப்பீர்களாக; அவைகளாலே நீங்கள் தீட்டுப்படுவீர்கள்.',	3,	11,	43),
(3042,	'For I am the LORD your God: ye shall therefore sanctify yourselves, and ye shall be holy; for I am holy: neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth.',	'நான் உங்கள் தேவனாகிய கர்த்தர், நான் பரிசுத்தர்; ஆகையால், தரையில் ஊருகிற எந்தப் பிராணிகளிலும் உங்களைத் தீட்டுப்படுத்தாமல், உங்களைப் பரிசுத்தமாக்கிக்கொண்டு, பரிசுத்தராயிருப்பீர்களாக.',	3,	11,	44),
(3043,	'For I am the LORD that bringeth you up out of the land of Egypt, to be your God: ye shall therefore be holy, for I am holy.',	'நான் உங்கள் தேவனாயிருக்கும்படி உங்களை எகிப்து தேசத்திலிருந்து வரப்பண்ணின கர்த்தர், நான் பரிசுத்தர்; ஆகையால். நீங்களும் பரிசுத்தராயிருப்பீர்களாக.',	3,	11,	45),
(3044,	'This is the law of the beasts, and of the fowl, and of every living creature that moveth in the waters, and of every creature that creepeth upon the earth:',	'சுத்தமானதற்கும் அசுத்தமானதற்கும், புசிக்கத்தக்க ஜந்துக்களுக்கும் புசிக்கத்தகாத ஜந்துக்களுக்கும் வித்தியாசம் பண்ணும்பொருட்டு,',	3,	11,	46),
(3045,	'To make a difference between the unclean and the clean, and between the beast that may be eaten and the beast that may not be eaten.',	'மிருகத்துக்கும், பறவைகளுக்கும், தண்ணீர்களில் நீந்துகிற சகல ஜீவஜந்துக்களுக்கும், பூமியின்மேல் ஊருகிற சகல பிராணிகளுக்கும் அடுத்த பிரமாணம் இதுவே என்று சொல்லுங்கள் என்றார்.  ',	3,	11,	47),
(3046,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	12,	1),
(3047,	'Speak unto the children of Israel, saying, If a woman have conceived seed, and born a man child: then she shall be unclean seven days; according to the days of the separation for her infirmity shall she be unclean.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்ல வேண்டியது என்னவென்றால்: ஒரு ஸ்திரீ கர்ப்பவதியாகி ஆண்பிள்ளையைப் பெற்றால், அவள் சூதகஸ்திரீ விலக்கமாயிருக்கும் நாட்களுக்குச் சரியாக ஏழுநாள் தீட்டாயிருப்பாள்.',	3,	12,	2),
(3048,	'And in the eighth day the flesh of his foreskin shall be circumcised.',	'எட்டாம் நாளிலே அந்தப் பிள்ளையினுடைய நுனித்தோலின் மாம்சம் விருத்தசேதனம் பண்ணப்படக்கடவது.',	3,	12,	3),
(3049,	'And she shall then continue in the blood of her purifying three and thirty days; she shall touch no hallowed thing, nor come into the sanctuary, until the days of her purifying be fulfilled.',	'பின்பு அவள் முப்பத்துமூன்றுநாள் தன் உதிரச் சுத்திகரிப்பு நிலையிலே இருந்து, சுத்திகரிப்பின் நாட்கள் நிறைவேறுமளவும் பரிசுத்தமான யாதொரு வஸ்துவைத் தொடவும் பரிசுத்த ஸ்தலத்துக்குள் வரவுங் கூடாது.',	3,	12,	4),
(3050,	'But if she bear a maid child, then she shall be unclean two weeks, as in her separation: and she shall continue in the blood of her purifying threescore and six days.',	'பெண்பிள்ளயைப் பெற்றாளாகில், அவள், இரண்டு வாரம் சூதகஸ்திரீயைப்போலத் தீட்டாயிருந்து, பின்பு அறுபத்தாறுநாள் உதிரச் சுத்திகரிப்பு நிலையிலே இருக்கக்கடவள்.',	3,	12,	5),
(3051,	'And when the days of her purifying are fulfilled, for a son, or for a daughter, she shall bring a lamb of the first year for a burnt offering, and a young pigeon, or a turtledove, for a sin offering, unto the door of the tabernacle of the congregation, unto the priest:',	'அவள் ஆண்பிள்ளையையாவது பெண்பிள்ளையையாவது பெற்றதற்காக அவளுடைய சுத்திகரிப்பின் நாட்கள் நிறைவேறினபின்பு, அவள் ஒருவயதான ஆட்டுக்குட்டியை சர்வாங்கதகனபலியாகவும், ஒரு புறாக்குஞ்சையாவது காட்டுப்புறாவையாவது பாவநிவாரண பலியாகவும், ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்திற்குக் கொண்டுவரக்கடவள்.',	3,	12,	6),
(3052,	'Who shall offer it before the LORD, and make an atonement for her; and she shall be cleansed from the issue of her blood. This is the law for her that hath born a male or a female.',	'அதை அவன் கர்த்தருடைய சந்நிதியில் பலியிட்டு, அவளுக்காகப் பாவநிவிர்த்தி செய்வானாக; அப்பொழுது அவள் தன் உதிர ஊறலின் தீட்டு நீங்கிச்சுத்தமாவாள். இது ஆண்பிள்ளையையாவது பெண்பிள்ளையையாவது பெற்றவளைக்குறித்த பிரமாணம்.',	3,	12,	7),
(3053,	'And if she be not able to bring a lamb, then she shall bring two turtles, or two young pigeons; the one for the burnt offering, and the other for a sin offering: and the priest shall make an atonement for her, and she shall be clean.',	'ஆட்டுக்குட்டியைக் கொண்டுவர அவளுக்குச் சக்தியில்லாதிருந்தால், இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது, ஒன்றைச் சர்வாங்க தகனபலியாகவும் மற்றொன்றைப் பாவநிவாரணபலியாகவும் கொண்டுவரக்கடவள்; அதினால் ஆசாரியன் அவளுக்காகப் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அவள் சுத்தமாவாள் என்று சொல் என்றார்.  ',	3,	12,	8),
(3054,	'And the LORD spake unto Moses and Aaron, saying,',	'பின்னும் கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	3,	13,	1),
(3055,	'When a man shall have in the skin of his flesh a rising, a scab, or bright spot, and it be in the skin of his flesh like the plague of leprosy; then he shall be brought unto Aaron the priest, or unto one of his sons the priests:',	'ஒரு மனிதனுடைய சரீரத்தின்மேல் குஷ்டரோகம்போலிருக்கிற ஒரு தடிப்பாவது அசறாவது வெள்ளைப்படராவது உண்டானால், அவன் ஆசாரியனாகிய ஆரோனிடத்திலாகிலும், ஆசாரியராகிய அவன் குமாரரில் ஒருவனிடத்திலாகிலும் கொண்டுவரப்படக்கடவன்.',	3,	13,	2),
(3056,	'And the priest shall look on the plague in the skin of the flesh: and when the hair in the plague is turned white, and the plague in sight be deeper than the skin of his flesh, it is a plague of leprosy: and the priest shall look on him, and pronounce him unclean.',	'அப்பொழுது ஆசாரியன் அவன் சரீரத்தின்மேல் இருக்கிற ரோகத்தைப் பார்க்கவேண்டும்; ரோகம் இருக்கும் இடத்தில் மயிர் வெளுத்தும், ரோகமுள்ள இடம் அவனுடைய மற்றச் சரீரத்தைப்பார்க்கிலும் அதிகமாய்க் குழிந்தும் இருந்தால் அது குஷ்டரோகம்; ஆசாரியன் அவனைப் பார்த்தபின்பு, அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்.',	3,	13,	3),
(3057,	'If the bright spot be white in the skin of his flesh, and in sight be not deeper than the skin, and the hair thereof be not turned white; then the priest shall shut up him that hath the plague seven days:',	'அவன் சரீரத்தின்மேல் வெள்ளைப்படர்ந்திருந்தாலும், அவ்விடம் அவனுடைய மற்றத் தோலைப்பார்க்கிலும் அதிக பள்ளமாயிராமலும், அதின் மயிர் வெள்ளையாக மாறாமலும் இருந்தால், ஆசாரியன் அவனை ஏழுநாள் அடைத்து வைத்து,',	3,	13,	4),
(3058,	'And the priest shall look on him the seventh day: and, behold, if the plague in his sight be at a stay, and the plague spread not in the skin; then the priest shall shut him up seven days more:',	'ஏழாம் நாளில் அவனைப் பார்க்கக்கடவன்; தோலில் ரோகம் அதிகப்படாமல், அவன் பார்வைக்கு ரோகம் நின்றிருந்தால், ஆசாரியன் இரண்டாந்தரம் அவனை ஏழுநாள் அடைத்துவைத்து,',	3,	13,	5),
(3059,	'And the priest shall look on him again the seventh day: and, behold, if the plague be somewhat dark, and the plague spread not in the skin, the priest shall pronounce him clean: it is but a scab: and he shall wash his clothes, and be clean.',	'இரண்டாந்தரம் அவனை ஏழாம் நாளில் பார்க்கக்கடவன்; தோலில் ரோகம் அதிகப்படாமல் சுருங்கியிருந்தால், ஆசாரியன் அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்; அது அசறு; அவன் தன் வஸ்திரங்களைத் தோய்த்துச் சுத்தமாயிருப்பானாக.',	3,	13,	6),
(3060,	'But if the scab spread much abroad in the skin, after that he hath been seen of the priest for his cleansing, he shall be seen of the priest again.',	'தன்னைச் சுத்தமுள்ளவன் என்று தீர்க்கிறதற்கு அவன் தன்னை ஆசாரியனுக்குக் காண்பித்த பின்பு, அசறு தோலில் அதிகமாய்ப் படர்ந்திருந்தால், அவன் மறுபடியும் ஆசாரியனுக்குத் தன்னைக் காண்பிக்கக்கடவன்.',	3,	13,	7),
(3061,	'And if the priest see that, behold, the scab spreadeth in the skin, then the priest shall pronounce him unclean: it is a leprosy.',	'அப்பொழுது அசறு தோலிலே படர்ந்தது என்று ஆசாரியன் கண்டால், ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அது குஷ்டரோகம்.',	3,	13,	8),
(3062,	'When the plague of leprosy is in a man, then he shall be brought unto the priest;',	'குஷ்டரோகம் ஒரு மனிதனுக்கு இருந்தால், அவனை ஆசாரியனிடத்தில் கொண்டுவரவேண்டும்.',	3,	13,	9),
(3063,	'And the priest shall see him: and, behold, if the rising be white in the skin, and it have turned the hair white, and there be quick raw flesh in the rising;',	'அப்பொழுது ஆசாரியன் அவனைப் பார்த்து, தோலிலே வெள்ளையான தடிப்பிருந்து, அது மயிரை வெண்மையாக மாறப்பண்ணிற்றென்றும், அந்தத் தடிப்புள்ள இடத்திலே இரணமாம்சம் உண்டென்றும் கண்டால்,',	3,	13,	10),
(3064,	'It is an old leprosy in the skin of his flesh, and the priest shall pronounce him unclean, and shall not shut him up: for he is unclean.',	'அது அவன் சரீரத்திலுள்ள நாள்பட்ட குஷ்டம்; அவன் தீட்டுள்ளவன். ஆதலால், ஆசாரியன் அவனை அடைத்து வைக்காமல், தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்.',	3,	13,	11),
(3065,	'And if a leprosy break out abroad in the skin, and the leprosy cover all the skin of him that hath the plague from his head even to his foot, wheresoever the priest looketh;',	'ஆசாரியன் பார்க்கிற இடங்களெங்கும் தோலிலே குஷ்டம் தோன்றி, அந்த ரோகமுள்ளவனுடைய தலைதொடங்கி அவன் கால்மட்டும் அது தேகமுழுவதையும் மூடியிருக்கக்கண்டால்,',	3,	13,	12),
(3066,	'Then the priest shall consider: and, behold, if the leprosy have covered all his flesh, he shall pronounce him clean that hath the plague: it is all turned white: he is clean.',	'அப்பொழுது ஆசாரியன் பார்த்து, குஷ்டம் அவன் சரீரம் முழுவதையும் மூடியிருந்தால், அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்; அவன் உடம்பெல்லாம் வெண்மையாய்ப்போனபடியால், அவன் சுத்தமுள்ளவன்.',	3,	13,	13),
(3067,	'But when raw flesh appeareth in him, he shall be unclean.',	'ஆனாலும், இரணமாம்சம் அவனில் காணப்பட்டால், அவன் தீட்டுள்ளவன்.',	3,	13,	14),
(3068,	'And the priest shall see the raw flesh, and pronounce him to be unclean: for the raw flesh is unclean: it is a leprosy.',	'ஆகையால், இரணமாம்சத்தை ஆசாரியன் காணும்போது, அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; இரணமாம்சம் தீட்டுள்ளது; அது குஷ்டம்.',	3,	13,	15),
(3069,	'Or if the raw flesh turn again, and be changed unto white, he shall come unto the priest;',	'அல்லது, இரணமாம்சம் மாறி வெண்மையானால், அவன் ஆசாரியனிடத்துக்கு வரவேண்டும்.',	3,	13,	16),
(3070,	'And the priest shall see him: and, behold, if the plague be turned into white; then the priest shall pronounce him clean that hath the plague: he is clean.',	'ஆசாரியன் அவனைப் பார்த்து, ரோகமுள்ள இடம் வெண்மையாக மாறினதென்று கண்டால், ஆசாரியன் அவனைச்சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்; அவன் சுத்தமுள்ளவன்.',	3,	13,	17),
(3071,	'The flesh also, in which, even in the skin thereof, was a boil, and is healed,',	'சரீரத்தின்மேல் புண் உண்டாயிருந்து ஆறிப்போய்,',	3,	13,	18),
(3072,	'And in the place of the boil there be a white rising, or a bright spot, white, and somewhat reddish, and it be shewed to the priest;',	'அவ்விடத்திலே ஒரு வெள்ளைத்தடிப்பாவது சிவப்புக்கலந்த ஒரு வெள்ளைப்படராவது உண்டானால், அதை ஆசாரியனுக்குக் காண்பிக்கவேண்டும்.',	3,	13,	19),
(3073,	'And if, when the priest seeth it, behold, it be in sight lower than the skin, and the hair thereof be turned white; the priest shall pronounce him unclean: it is a plague of leprosy broken out of the boil.',	'ஆசாரியன் அதைப் பார்த்து, அவ்விடம் மற்றத் தோலைப்பார்க்கிலும் குழிந்திருக்கவும், அதின் மயிர் வெள்ளையாக மாறியிருக்கவும் கண்டால், ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கவேண்டும்; அது புண்ணில் எழும்பின குஷ்டம்.',	3,	13,	20),
(3074,	'But if the priest look on it, and, behold, there be no white hairs therein, and if it be not lower than the skin, but be somewhat dark; then the priest shall shut him up seven days:',	'ஆசாரியன் அதைப் பார்த்து, அதில் வெள்ளைமயிர் இல்லை என்றும், அது மற்றத்தோலைப்பார்க்கிலும் குழிந்திராமல் சுருங்கியிருக்கிறது என்றும் கண்டானாகில், அவனை ஏழுநாள் அடைத்துவைத்து,',	3,	13,	21),
(3075,	'And if it spread much abroad in the skin, then the priest shall pronounce him unclean: it is a plague.',	'அது தோலில் அதிகமாய்ப் படர்ந்திருக்கக்கண்டால், அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அது குஷ்டந்தான்.',	3,	13,	22),
(3076,	'But if the bright spot stay in his place, and spread not, it is a burning boil; and the priest shall pronounce him clean.',	'அந்த வெள்ளைப்படர் அதிகப்படாமல், அவ்வளவில் நின்றிருக்குமாகில், அது புண்ணின் தழும்பாயிருக்கும்; ஆகையால், ஆசாரியன் அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்.',	3,	13,	23),
(3077,	'Or if there be any flesh, in the skin whereof there is a hot burning, and the quick flesh that burneth have a white bright spot, somewhat reddish, or white;',	'ஒருவனுடைய சரீரத்தின்மேல் நெருப்புப்பட்டதினாலே வெந்து, அந்த வேக்காடு ஆறிப்போன இடத்திலே சிவப்பான படராவது வெண்மையான படராவது உண்டானால்,',	3,	13,	24),
(3078,	'Then the priest shall look upon it: and, behold, if the hair in the bright spot be turned white, and it be in sight deeper than the skin; it is a leprosy broken out of the burning: wherefore the priest shall pronounce him unclean: it is the plague of leprosy.',	'ஆசாரியன் அதைப் பார்க்கக்கடவன்; அந்தப் படரிலே மயிர் வெண்மையாக மாறி, அவ்விடம் மற்றத் தோலைப் பார்க்கிலும் பள்ளமாயிருந்தால், அது வேக்காட்டினால் எழும்பின குஷ்டம்; ஆகையால், ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அது குஷ்டரோகந்தான்.',	3,	13,	25),
(3079,	'But if the priest look on it, and, behold, there be no white hair in the bright spot, and it be no lower than the other skin, but be somewhat dark; then the priest shall shut him up seven days:',	'ஆசாரியன் அதைப் பார்க்கிறபோது, படரிலே வெள்ளைமயிர் இல்லை என்றும், அது மற்றத் தோலைப்பார்க்கிலும் குழிந்திராமல், சுருங்கியிருக்கிறது என்றும் கண்டானாகில், அவனை ஏழுநாள் அடைத்துவைத்து,',	3,	13,	26),
(3080,	'And the priest shall look upon him the seventh day: and if it be spread much abroad in the skin, then the priest shall pronounce him unclean: it is the plague of leprosy.',	'ஏழாம்நாளில் அவனைப் பார்க்கக்கடவன்; அது தோலில் அதிகமாய்ப் படர்ந்திருந்தால், ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அது குஷ்டரோகம்.',	3,	13,	27),
(3081,	'And if the bright spot stay in his place, and spread not in the skin, but it be somewhat dark; it is a rising of the burning, and the priest shall pronounce him clean: for it is an inflammation of the burning.',	'படரானது தோலில் பெருகாமல், அவ்வளவில் நின்று சுருங்கியிருந்ததாகில், அது சூட்டினால் உண்டான தழும்பு; ஆசாரியன் அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்; அது சூட்டினால் வந்த வேக்காடு.',	3,	13,	28),
(3082,	'If a man or woman have a plague upon the head or the beard;',	'புருஷனுக்காகிலும் ஸ்திரீக்காகிலும் தலையிலாவது தாடியிலாவது ஒரு சொறி உண்டானால்,',	3,	13,	29),
(3083,	'Then the priest shall see the plague: and, behold, if it be in sight deeper than the skin; and there be in it a yellow thin hair; then the priest shall pronounce him unclean: it is a dry scall, even a leprosy upon the head or beard.',	'ஆசாரியன் அதைப் பார்த்து, அவ்விடம் மற்றத் தோலைப்பார்க்கிலும் பள்ளமும் அதிலே மயிர் பொன் நிறமும் மிருதுவுமாயிருக்கக்கண்டால், ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அது தலையிலும் தாடியிலும் உண்டாகிற சொறிகுஷ்டம்.',	3,	13,	30),
(3084,	'And if the priest look on the plague of the scall, and, behold, it be not in sight deeper than the skin, and that there is no black hair in it; then the priest shall shut up him that hath the plague of the scall seven days:',	'ஆசாரியன் அந்தச் சொறிகுஷ்டத்தைப் பார்க்கும்போது, அவ்விடம் மற்றத்தோலைப்பார்க்கிலும் பள்ளமாயிராமலும், அதிலே கறுத்த மயிர் இல்லாமலும் இருக்கக்கண்டால், ஆசாரியன் அவனை ஏழுநாள் அடைத்துவைத்து,',	3,	13,	31),
(3085,	'And in the seventh day the priest shall look on the plague: and, behold, if the scall spread not, and there be in it no yellow hair, and the scall be not in sight deeper than the skin;',	'ஏழாம்நாளில் ஆசாரியன் அதைப்பார்க்கக்கடவன்; அந்தச் சொறி இடங்கொள்ளாமலும், அதிலே பொன்நிறமயிர் இல்லாமலும், அவ்விடம் மற்றத் தோலைப்பார்க்கிலும் பள்ளமில்லாமலும் இருந்தால்,',	3,	13,	32),
(3086,	'He shall be shaven, but the scall shall he not shave; and the priest shall shut up him that hath the scall seven days more:',	'அந்தச் சொறியுள்ள இடந்தவிர, மற்ற யாவையும் அவன் சிரைத்துக்கொள்ளக்கடவன்; பின்பு, ஆசாரியன் இரண்டாந்தரம் அவனை ஏழுநாள் அடைத்துவைத்து,',	3,	13,	33),
(3087,	'And in the seventh day the priest shall look on the scall: and, behold, if the scall be not spread in the skin, nor be in sight deeper than the skin; then the priest shall pronounce him clean: and he shall wash his clothes, and be clean.',	'ஏழாம்நாளில் அதைப் பார்க்கக்கடவன்; சொறி தோலில் இடங்கொள்ளாமலும், அவ்விடம் மற்றத் தோலைப்பார்க்கிலும் பள்ளமில்லாமலும் இருந்தால், ஆசாரியன் அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்; அவன் தன் வஸ்திரங்களைத் தோய்த்தபின் சுத்தமாயிருப்பான்.',	3,	13,	34),
(3088,	'But if the scall spread much in the skin after his cleansing;',	'அவன் சுத்தமுள்ளவன் என்று தீர்க்கப்பட்டபின், அந்தச் சொறி தோலில் இடங்கொண்டதானால்,',	3,	13,	35),
(3089,	'Then the priest shall look on him: and, behold, if the scall be spread in the skin, the priest shall not seek for yellow hair; he is unclean.',	'ஆசாரியன் அவனைப் பார்க்கக்கடவன்; சொறி தோலில் இடங்கொண்டிருந்தால், அப்பொழுது மயிர் பொன்நிறமா அல்லவா என்று ஆசாரியன் விசாரிக்க வேண்டியதில்லை; அவன் தீட்டுள்ளவனே.',	3,	13,	36),
(3090,	'But if the scall be in his sight at a stay, and that there is black hair grown up therein; the scall is healed, he is clean: and the priest shall pronounce him clean.',	'அவன் பார்வைக்கு அந்தச் சொறி நீங்கி, அதில் கறுத்தமயிர் முளைத்ததேயாகில், சொறி சொஸ்தமாயிற்று; அவன் சுத்தமுள்ளவன்; ஆசாரியன் அவனைச் சுத்தமுள்ளவன் என்று தீர்க்கக்கடவன்.',	3,	13,	37),
(3091,	'If a man also or a woman have in the skin of their flesh bright spots, even white bright spots;',	'ஒரு புருஷனுக்காகிலும் ஸ்திரீக்காகிலும் அவர்கள் சரீரத்தின்மேல் வெள்ளைப் புள்ளிகள் உண்டாயிருந்தால்,',	3,	13,	38),
(3092,	'Then the priest shall look: and, behold, if the bright spots in the skin of their flesh be darkish white; it is a freckled spot that groweth in the skin; he is clean.',	'ஆசாரியன் பார்க்கக்கடவன்; அவர்கள் சரீரத்திலே மங்கின வெள்ளைப் புள்ளிகள் இருந்தால், அது தோலில் எழும்புகிற வெள்ளைத்தேமல்; அவர்கள் சுத்தமுள்ளவர்கள்.',	3,	13,	39),
(3093,	'And the man whose hair is fallen off his head, he is bald; yet is he clean.',	'ஒருவனுடைய தலைமயிர் உதிர்ந்து, அவன் மொட்டையனானாலும், அவன் சுத்தமாயிருக்கிறான்.',	3,	13,	40),
(3094,	'And he that hath his hair fallen off from the part of his head toward his face, he is forehead bald: yet is he clean.',	'அவனுடைய முன்னந்தலை மயிர் உதிர்ந்தால், அவன் அரைமொட்டையன்; அவனும் சுத்தமாயிருக்கிறான்.',	3,	13,	41),
(3095,	'And if there be in the bald head, or bald forehead, a white reddish sore; it is a leprosy sprung up in his bald head, or his bald forehead.',	'மொட்டைத்தலையிலாவது அரைமொட்டைத்தலையிலாவது சிவப்புக்கலந்த வெண்மையான படர் உண்டானால், அது அதில் எழும்புகிற குஷ்டம்.',	3,	13,	42),
(3096,	'Then the priest shall look upon it: and, behold, if the rising of the sore be white reddish in his bald head, or in his bald forehead, as the leprosy appeareth in the skin of the flesh;',	'ஆசாரியன் அவனைப் பார்க்கக்கடவன்; அவனுடைய மொட்டைத்தலையிலாவது அரைமொட்டைத்தலையிலாவது, மற்ற அங்கங்களின்மேல் உண்டாகும் குஷ்டத்தைப்போல, சிவப்புக்கலந்த வெண்மையான தடிப்பு இருக்கக்கண்டால்,',	3,	13,	43),
(3097,	'He is a leprous man, he is unclean: the priest shall pronounce him utterly unclean; his plague is in his head.',	'அவன் குஷ்டரோகி, அவன் தீட்டுள்ளவன்; ஆசாரியன் அவனைத் தீட்டுள்ளவன் என்று தீர்க்கக்கடவன்; அவன் வியாதி அவன் தலையிலே இருக்கிறது.',	3,	13,	44),
(3098,	'And the leper in whom the plague is, his clothes shall be rent, and his head bare, and he shall put a covering upon his upper lip, and shall cry, Unclean, unclean.',	'அந்த வியாதி உண்டாயிருக்கிற குஷ்டரோகி வஸ்திரம் கிழிந்தவனாயும், தன் தலையை மூடாதவனாயும் இருந்து, அவன் தன் தாடியை மூடிக்கொண்டு, &quot;தீட்டு, தீட்டு&quot; என்று சத்தமிடவேண்டும்.',	3,	13,	45),
(3099,	'All the days wherein the plague shall be in him he shall be defiled; he is unclean: he shall dwell alone; without the camp shall his habitation be.',	'அந்த வியாதி அவனில் இருக்கும் நாள்வரைக்கும் தீட்டுள்ளவனாக எண்ணப்படக்கடவன்; அவன் தீட்டுள்ளவனே; ஆகையால், அவன் தனியே குடியிருக்கவேண்டும்; அவன் குடியிருப்பு பாளயத்துக்குப் புறம்பே இருக்கக்கடவது.',	3,	13,	46),
(3100,	'The garment also that the plague of leprosy is in, whether it be a woollen garment, or a linen garment;',	'ஆட்டுமயிர் வஸ்திரத்திலாவது, பஞ்சுநூல் வஸ்திரத்திலாவது,',	3,	13,	47),
(3101,	'Whether it be in the warp, or woof; of linen, or of woollen; whether in a skin, or in any thing made of skin;',	'பஞ்சுநூல் அல்லது ஆட்டுமயிரான பாவிலாவது, ஊடையிலாவது, ஒரு தோலிலாவது, தோலினால் செய்த எந்தவித வஸ்துவிலாவது குஷ்டதோஷம் தோன்றி,',	3,	13,	48),
(3102,	'And if the plague be greenish or reddish in the garment, or in the skin, either in the warp, or in the woof, or in any thing of skin; it is a plague of leprosy, and shall be shewed unto the priest:',	'வஸ்திரத்திலாவது, தோலிலாவது, பாவிலாவது, ஊடையிலாவது, தோலினால் செய்த எந்தவித வஸ்துவிலாவது குஷ்டதோஷம் பச்சையாயாவது சிவப்பாயாவது காணப்பட்டால் அது குஷ்டமாயிருக்கும்; அதை ஆசாரியனுக்குக் காண்பிக்கவேண்டும்.',	3,	13,	49),
(3103,	'And the priest shall look upon the plague, and shut up it that hath the plague seven days:',	'ஆசாரியன் அதைப் பார்த்து, ஏழுநாள் அடைத்துவைத்து,',	3,	13,	50),
(3104,	'And he shall look on the plague on the seventh day: if the plague be spread in the garment, either in the warp, or in the woof, or in a skin, or in any work that is made of skin; the plague is a fretting leprosy; it is unclean.',	'ஏழாம் நாளிலே அதைப் பார்க்கக்கடவன்; வஸ்திரத்திலாவது, பாவிலாவது, ஊடையிலாவது, தோலிலாவது, தோலினால் செய்த எந்தவித வஸ்துவிலாவது அது அதிகப்பட்டிருந்தால், அது அரிக்கிற குஷ்டம்; அது தீட்டாயிருக்கும்.',	3,	13,	51),
(3105,	'He shall therefore burn that garment, whether warp or woof, in woollen or in linen, or any thing of skin, wherein the plague is: for it is a fretting leprosy; it shall be burnt in the fire.',	'அந்தத் தோஷம் இருக்கிற ஆட்டுமயிரினாலும் பஞ்சுநூலினாலும் செய்த வஸ்திரத்தையும் பாவையும், ஊடையையும், தோலினால் செய்த எந்தவித வஸ்துவையும் சுட்டெரிக்கக்கடவன்; அது அரிக்கிற குஷ்டம்; ஆகையால் அக்கினியில் சுட்டெரிக்கப்படவேண்டும்.',	3,	13,	52),
(3106,	'And if the priest shall look, and, behold, the plague be not spread in the garment, either in the warp, or in the woof, or in any thing of skin;',	'வஸ்திரத்தின் பாவிலாவது, ஊடையிலாவது, தோலினால் செய்த எந்தவித வஸ்துவிலாவது, அந்த தோஷம் அதிகப்படவில்லை என்று ஆசாரியன் கண்டால்,',	3,	13,	53),
(3107,	'Then the priest shall command that they wash the thing wherein the plague is, and he shall shut it up seven days more:',	'அப்பொழுது ஆசாரியன் அதைக்கழுவச்சொல்லி, இரண்டாந்தரம் ஏழுநாள் அடைத்துவைத்து,',	3,	13,	54),
(3108,	'And the priest shall look on the plague, after that it is washed: and, behold, if the plague have not changed his colour, and the plague be not spread; it is unclean; thou shalt burn it in the fire; it is fret inward, whether it be bare within or without.',	'அது கழுவப்பட்டபின்பு, அதைப் பார்க்கக்கடவன்; அந்தத் தோஷம் அதிகப்படாதிருந்தாலும், அது நிறம் மாறாததாயிருந்தால் தீட்டாயிருக்கும்; அக்கினியில் அதைச் சுட்டெரிக்கவேண்டும்; அது அவ்வஸ்திரத்தின் உட்புறத்திலும் வெளிப்புறத்திலும் உருவ அரிக்கும்.',	3,	13,	55),
(3109,	'And if the priest look, and, behold, the plague be somewhat dark after the washing of it; then he shall rend it out of the garment, or out of the skin, or out of the warp, or out of the woof:',	'கழுவப்பட்டபின்பு அது குறுகிற்றென்று ஆசாரியன் கண்டானேயாகில், அதை வஸ்திரத்திலாவது, தோலிலாவது, பாவிலாவது, ஊடையிலாவது இராதபடிக்கு எடுத்துப்போடவேண்டும்.',	3,	13,	56),
(3110,	'And if it appear still in the garment, either in the warp, or in the woof, or in any thing of skin; it is a spreading plague: thou shalt burn that wherein the plague is with fire.',	'அது இன்னும் வஸ்திரத்திலாவது, பாவிலாவது, ஊடையிலாவது, தோலினால் செய்த எந்தவித வஸ்துவிலாவது காணப்பட்டால், அது படருகிற தோஷம்; ஆகையினால் அது உள்ளதை அக்கினியில் சுட்டெரிக்கவேண்டும்.',	3,	13,	57),
(3111,	'And the garment, either warp, or woof, or whatsoever thing of skin it be, which thou shalt wash, if the plague be departed from them, then it shall be washed the second time, and shall be clean.',	'வஸ்திரத்தின் பாவாவது, ஊடையாவது, தோலினால் செய்த எந்தவித வஸ்துவாவது கழுவப்பட்டபின்பு, அந்தத் தோஷம் அதை விட்டுப் போயிற்றேயானால், இரண்டாந்தரம் கழுவப்படவேண்டும்; அப்பொழுது சுத்தமாயிருக்கும்.',	3,	13,	58),
(3112,	'This is the law of the plague of leprosy in a garment of woollen or linen, either in the warp, or woof, or any thing of skins, to pronounce it clean, or to pronounce it unclean.',	'ஆட்டுமயிராலாகிலும் பஞ்சுநூலாலாகிலும் நெய்த வஸ்திரத்தையாவது, பாவையாவது, ஊடையையாவது, தோலினால் செய்த எந்தவித வஸ்துவையாவது, சுத்தமென்றாவது தீட்டென்றாவது தீர்க்கிறதற்கு, அதினுடைய குஷ்டதோஷத்துக்கடுத்த பிரமாணம் இதுவே என்றார்.  ',	3,	13,	59),
(3113,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	14,	1),
(3114,	'This shall be the law of the leper in the day of his cleansing: He shall be brought unto the priest:',	'குஷ்டரோகியினுடைய சுத்திகரிப்பின் நாளில் அவனுக்கடுத்த பிரமாணம் என்னவென்றால்: அவன் ஆசாரியனிடத்தில் கொண்டுவரப்படவேண்டும்.',	3,	14,	2),
(3115,	'And the priest shall go forth out of the camp; and the priest shall look, and, behold, if the plague of leprosy be healed in the leper;',	'ஆசாரியன் பாளயத்துக்குப் புறம்பே போய்; குஷ்டரோகியின் குஷ்டவியாதி சொஸ்தமாயிற்று என்று கண்டால்,',	3,	14,	3),
(3116,	'Then shall the priest command to take for him that is to be cleansed two birds alive and clean, and cedar wood, and scarlet, and hyssop:',	'சுத்திகரிக்கப்படவேண்டியவனுக்காக, உயிரோடிருக்கும் சுத்தமான இரண்டு குருவிகளையும், கேதுருக் கட்டையையும், சிவப்புநூலையும், ஈசோப்பையும் வாங்கிவரக் கட்டைளையிடக்கடவன்.',	3,	14,	4),
(3117,	'And the priest shall command that one of the birds be killed in an earthen vessel over running water:',	'பின்பு, ஆசாரியன் அந்தக் குருவிகளில் ஒன்றை ஒரு மண்பாண்டத்திலுள்ள ஊற்றுநீர்மேல் கொல்லச்சொல்லி,',	3,	14,	5),
(3118,	'As for the living bird, he shall take it, and the cedar wood, and the scarlet, and the hyssop, and shall dip them and the living bird in the blood of the bird that was killed over the running water:',	'உயிருள்ள குருவியையும், கேதுருக்கட்டையையும், சிவப்புநூலையும், ஈசோப்பையும் எடுத்து, இவைகளையும் உயிருள்ள குருவியையும் ஊற்றுநீர்மேல் கொல்லப்பட்ட குருவியின் இரத்தத்திலே தோய்த்து,',	3,	14,	6),
(3119,	'And he shall sprinkle upon him that is to be cleansed from the leprosy seven times, and shall pronounce him clean, and shall let the living bird loose into the open field.',	'குஷ்டம் நீங்கச் சுத்திரிக்கப்படுகிறவன்மேல் ஏழுதரம் தெளித்து, அவனை சுத்தம்பண்ணி, உயிருள்ள குருவியை வெளியிலே விட்டுவிடக்கடவன்.',	3,	14,	7),
(3120,	'And he that is to be cleansed shall wash his clothes, and shave off all his hair, and wash himself in water, that he may be clean: and after that he shall come into the camp, and shall tarry abroad out of his tent seven days.',	'சுத்திகரிக்கப்படுகிறவன் தன் வஸ்திரங்களைத் தோய்த்து, தன் மயிர் முழுவதையும் சிரைத்து, தான் சுத்தமாகும்படி ஜலத்தில் ஸ்நானம்பண்ணி, பின்பு பாளயத்தில் பிரவேசித்து, தன் கூடாரத்துக்குப் புறம்பே ஏழுநாள் தங்கி,',	3,	14,	8),
(3121,	'But it shall be on the seventh day, that he shall shave all his hair off his head and his beard and his eyebrows, even all his hair he shall shave off: and he shall wash his clothes, also he shall wash his flesh in water, and he shall be clean.',	'ஏழாம் நாளிலே தன் தலையையும் தாடியையும் புருவங்களையும் தன்னுடைய மயிர்முழுவதையும் சிரைத்து, தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்தில் ஸ்நானம்பண்ணவேண்டும்; அப்பொழுது சுத்தமாயிருப்பான்.',	3,	14,	9),
(3122,	'And on the eighth day he shall take two he lambs without blemish, and one ewe lamb of the first year without blemish, and three tenth deals of fine flour for a meat offering, mingled with oil, and one log of oil.',	'எட்டாம்நாளிலே அவன் பழுதற்ற இரண்டு ஆட்டுக்குட்டிகளையும், ஒருவயதான பழுதற்ற ஒரு பெண்ணாட்டுக்குட்டியையும், போஜனபலிக்காக எண்ணெயிலே பிசைந்த ஒரு மரக்காலில் பத்தில் மூன்று பங்காகிய மெல்லிய மாவையும், ஆழாக்கு எண்ணெயையும் கொண்டுவரக்கடவன்.',	3,	14,	10),
(3123,	'And the priest that maketh him clean shall present the man that is to be made clean, and those things, before the LORD, at the door of the tabernacle of the congregation:',	'சுத்திகரிக்கிற ஆசாரியன் சுத்திகரிக்கப்படும் மனிதனையும் அவ்வஸ்துக்களையும் ஆசரிப்புக் கூடாரவாசலிலே கர்த்தருடைய சந்நிதியில் நிறுத்தக்கடவன்.',	3,	14,	11),
(3124,	'And the priest shall take one he lamb, and offer him for a trespass offering, and the log of oil, and wave them for a wave offering before the LORD:',	'பின்பு, ஆசாரியன் ஒரு ஆட்டுக்குட்டியைப் பிடித்து, அதையும் அந்த ஆழாக்கு எண்ணெயையும் குற்றநிவாரணபலியாகக் கொண்டுவந்து, கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டி,',	3,	14,	12),
(3125,	'And he shall slay the lamb in the place where he shall kill the sin offering and the burnt offering, in the holy place: for as the sin offering is the priest\'s, so is the trespass offering: it is most holy:',	'பாவநிவாரணபலியும் சர்வாங்கதகனபலியும் இடும் பரிசுத்த ஸ்தலத்திலே அந்த ஆட்டுக்குட்டியைக் கொல்லக்கடவன்; குற்றநிவாரணபலி பாவநிவாரணபலியைப்போல ஆசாரியனுக்கு உரியது; அது மகா பரிசுத்தமானது.',	3,	14,	13),
(3126,	'And the priest shall take some of the blood of the trespass offering, and the priest shall put it upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot:',	'அந்த குற்றநிவாரணபலியின் இரத்தத்தில் ஆசாரியன் கொஞ்சம் எடுத்து, சுத்திகரிக்கப்படுகிறவன் வலதுகாதின் மடலிலும், அவன் வலதுகையின் பெருவிரலிலும், வலதுகாலின் பெருவிரலிலும் பூசக்கடவன்.',	3,	14,	14),
(3127,	'And the priest shall take some of the log of oil, and pour it into the palm of his own left hand:',	'பின்பு, ஆசாரியன் அந்த ஆழாக்கு எண்ணெயிலே கொஞ்சம் தன் இடதுகையில் வார்த்து,',	3,	14,	15),
(3128,	'And the priest shall dip his right finger in the oil that is in his left hand, and shall sprinkle of the oil with his finger seven times before the LORD:',	'தன் இடதுகையிலுள்ள எண்ணெயில் தன் வலதுகையின் விரலைத் தோய்த்து, தன் விரலினால் ஏழுதரம் அந்த எண்ணெயில் எடுத்து, கர்த்தருடைய சந்நிதியில் தெளித்து,',	3,	14,	16),
(3129,	'And of the rest of the oil that is in his hand shall the priest put upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot, upon the blood of the trespass offering:',	'தன் உள்ளங்கையில் இருக்கிற மீதியான எண்ணெயிலே கொஞ்சம் எடுத்து சுத்திகரிக்கபடுகிறவன் வலதுகாதின் மடலிலும், அவன் வலதுகையின் பெருவிரலிலும், வலதுகாலின் பெருவிரலிலும், முந்தப் பூசியிருக்கிற குற்றநிவாரண பலியினுடைய இரத்தத்தின்மேல் பூசி,',	3,	14,	17),
(3130,	'And the remnant of the oil that is in the priest\'s hand he shall pour upon the head of him that is to be cleansed: and the priest shall make an atonement for him before the LORD.',	'தன் உள்ளங்கையில் இருக்கிற மீதியான எண்ணெயைச் சுத்திகரிக்கபடுகிறவன் தலையிலே வார்த்து, கர்த்தருடைய சந்நிதியில் அவனுக்காகப் பாவநிவிர்த்தி செய்யக்கடவன்.',	3,	14,	18),
(3131,	'And the priest shall offer the sin offering, and make an atonement for him that is to be cleansed from his uncleanness; and afterward he shall kill the burnt offering:',	'ஆசாரியன் பாவநிவாரணபலியையும் செலுத்தி, சுத்திகரிக்கப்படுகிறவனின் தீட்டு நீங்க, அவனுக்குப் பாவநிவிர்த்தி செய்து, பின்பு சர்வாங்கதகனபலியைக் கொன்று,',	3,	14,	19),
(3132,	'And the priest shall offer the burnt offering and the meat offering upon the altar: and the priest shall make an atonement for him, and he shall be clean.',	'சர்வாங்கதகனபலியையும் போஜனபலியையும் பலிபீடத்தின்மேல் வைத்து, அவனுக்காகப் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அவன் சுத்தமாயிருப்பான்.',	3,	14,	20),
(3133,	'And if he be poor, and cannot get so much; then he shall take one lamb for a trespass offering to be waved, to make an atonement for him, and one tenth deal of fine flour mingled with oil for a meat offering, and a log of oil;',	'அவன் இம்மாத்திரம் செய்யத்திராணியற்ற தரித்திரனாயிருந்தால், அவன் தன் பாவநிவிர்த்திக்கென்று அசைவாட்டும் குற்றநிவாரணபலியாக ஒரு ஆட்டுக்குட்டியையும், போஜனபலிக்கு எண்ணெயில் பிசைந்த ஒரு மரக்கால் மெல்லிய மாவிலே பத்தில் ஒரு பங்கையும், ஆழாக்கு எண்ணெயையும்,',	3,	14,	21),
(3134,	'And two turtledoves, or two young pigeons, such as he is able to get; and the one shall be a sin offering, and the other a burnt offering.',	'தன் திராணிக்குத் தக்கபடி இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது, ஒன்று பாவநிவாரணபலியாகவும், மற்றொன்று சர்வாங்கதகனபலியாகவும் செலுத்தும்படி வாங்கி,',	3,	14,	22),
(3135,	'And he shall bring them on the eighth day for his cleansing unto the priest, unto the door of the tabernacle of the congregation, before the LORD.',	'தான் சுத்திகரிக்கப்படும்படி எட்டாம் நாளில் ஆசரிப்புக் கூடாரவாசலிலே கர்த்தருடைய சந்நிதியில் ஆசாரியனிடத்துக்குக் கொண்டுவருவானாக.',	3,	14,	23),
(3136,	'And the priest shall take the lamb of the trespass offering, and the log of oil, and the priest shall wave them for a wave offering before the LORD:',	'அப்பொழுது ஆசாரியன் குற்றநிவாரணபலிக்குரிய ஆட்டுக்குட்டியையும் அந்த ஆழாக்கு எண்ணெயையும் வாங்கி, கர்த்தருடைய சந்நிதியில் அசைவாட்டும் போஜனபலியாக அசைவாட்டி,',	3,	14,	24),
(3137,	'And he shall kill the lamb of the trespass offering, and the priest shall take some of the blood of the trespass offering, and put it upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot:',	'குற்றநிவாரணபலிக்கான அந்த ஆட்டுக்குட்டியைக் கொன்று, குற்றநிவாரணபலியின் இரத்தத்தில் கொஞ்சம் எடுத்து, சுத்திகரிக்கப்படுகிறவன் வலதுகாதின் மடலிலும், அவன் வலதுகையின் பெருவிரலிலும், வலதுகாலின் பெருவிரலிலும் பூசி,',	3,	14,	25),
(3138,	'And the priest shall pour of the oil into the palm of his own left hand:',	'அந்த எண்ணெயிலே கொஞ்சம் தன் இடதுகையில் வார்த்து,',	3,	14,	26),
(3139,	'And the priest shall sprinkle with his right finger some of the oil that is in his left hand seven times before the LORD:',	'தன் இடதுகையிலுள்ள எண்ணெயிலே தன் வலதுவிரலைத் தோய்த்து, கர்த்தருடைய சந்நிதியில் ஏழுதரம் தெளித்து,',	3,	14,	27),
(3140,	'And the priest shall put of the oil that is in his hand upon the tip of the right ear of him that is to be cleansed, and upon the thumb of his right hand, and upon the great toe of his right foot, upon the place of the blood of the trespass offering:',	'தன் உள்ளங்கையில் இருக்கிற எண்ணெயில் கொஞ்சம் எடுத்துச் சுத்திகரிக்கப்படுகிறவன் வலதுகாதின் மடலிலும், அவன் வலதுகையின் பெருவிரலிலும், வலதுகாலின் பெருவிரலிலும் குற்றநிவாரணபலியின் இரத்தம் பூசியிருக்கிற இடத்தின்மேல் பூசி,',	3,	14,	28),
(3141,	'And the rest of the oil that is in the priest\'s hand he shall put upon the head of him that is to be cleansed, to make an atonement for him before the LORD.',	'தன் உள்ளங்கையில் இருக்கிற மற்ற எண்ணெயைச் சுத்திகரிக்கப்படுகிறவன் தலையின்மேல் அவனுக்காகக் கர்த்தருடைய சந்நிதியில் பாவநிவிர்த்தி செய்யும்படி தடவி,',	3,	14,	29),
(3142,	'And he shall offer the one of the turtledoves, or of the young pigeons, such as he can get;',	'பின்பு, அவன் தன் திராணிக்கும் தகுதிக்கும் தக்கதாய் காட்டுப்புறாக்களையாவது புறாக்குஞ்சுகளையாவது கொண்டுவந்து,',	3,	14,	30),
(3143,	'Even such as he is able to get, the one for a sin offering, and the other for a burnt offering, with the meat offering: and the priest shall make an atonement for him that is to be cleansed before the LORD.',	'அவைகளில் ஒன்றைப் பாவநிவாரணபலியும், மற்றொன்றைச் சர்வாங்கதகனபலியுமாக்கி, போஜனபலியோடேகூடச் செலுத்தி, இப்படியே ஆசாரியன் சுத்திகரிக்கப்படுகிறவனுக்காக, கர்த்தருடைய சந்நிதியில் பாவநிவிர்த்தி செய்யக்கடவன்.',	3,	14,	31),
(3144,	'This is the law of him in whom is the plague of leprosy, whose hand is not able to get that which pertaineth to his cleansing.',	'தன் சுத்திகரிப்புக்கு வேண்டியவைகளைச் சம்பாதிக்கக்கூடாத குஷ்டரோகியைக் குறித்த பிரமாணம் இதுவே என்றார்.',	3,	14,	32),
(3145,	'And the LORD spake unto Moses and unto Aaron, saying,',	'பின்னும் கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	3,	14,	33),
(3146,	'When ye be come into the land of Canaan, which I give to you for a possession, and I put the plague of leprosy in a house of the land of your possession;',	'நான் உங்களுக்குக் காணியாட்சியாகக் கொடுக்கும் கானான் தேசத்திலே நீங்கள் போய்ச் சேர்ந்தபின்பு, உங்கள் காணியாட்சியான தேசத்தில் ஒரு வீட்டிலே குஷ்டரோகத்தை நான் வரப்பண்ணினால்,',	3,	14,	34),
(3147,	'And he that owneth the house shall come and tell the priest, saying, It seemeth to me there is as it were a plague in the house:',	'அந்த வீட்டிற்கு உடையவன் வந்து, வீட்டிலே தோஷம் வந்திருக்கிறதாகத் தோன்றுகிறது என்று ஆசாரியனுக்கு அறிவிக்கக்கடவன்.',	3,	14,	35),
(3148,	'Then the priest shall command that they empty the house, before the priest go into it to see the plague, that all that is in the house be not made unclean: and afterward the priest shall go in to see the house:',	'அப்பொழுது வீட்டிலுள்ள யாவும் தீட்டுப்படாதபடிக்கு, ஆசாரியன் அந்தத் தோஷத்தைப் பார்க்கப் போகும்முன்னே வீட்டை ஒழித்துவைக்கும்படி சொல்லி, பின்பு வீட்டைப் பார்க்கும்படி போய்,',	3,	14,	36),
(3149,	'And he shall look on the plague, and, behold, if the plague be in the walls of the house with hollow strakes, greenish or reddish, which in sight are lower than the wall;',	'அந்தத் தோஷம் இருக்கிற இடத்தைப் பார்க்கக்கடவன்; அப்பொழுது வீட்டுச் சுவர்களிலே கொஞ்சம் பச்சையும் கொஞ்சம் சிவப்புமான குழி விழுந்திருந்து, அவைகள் மற்றச் சுவரைப்பார்க்கிலும் பள்ளமாயிருக்கக்கண்டால்,',	3,	14,	37),
(3150,	'Then the priest shall go out of the house to the door of the house, and shut up the house seven days:',	'ஆசாரியன் வீட்டைவிட்டுப் புறப்பட்டு வாசற்படியிலே வந்து, வீட்டை ஏழுநாள் அடைத்துவைத்து,',	3,	14,	38),
(3151,	'And the priest shall come again the seventh day, and shall look: and, behold, if the plague be spread in the walls of the house;',	'ஏழாம்நாளிலே திரும்பப் போய்ப்பார்த்து, தோஷம் வீட்டுச் சுவர்களில் படர்ந்ததென்று கண்டால்,',	3,	14,	39),
(3152,	'Then the priest shall command that they take away the stones in which the plague is, and they shall cast them into an unclean place without the city:',	'தோஷம் இருக்கும் அவ்விடத்துக்கல்லுகளைப் பெயர்க்கவும், பட்டணத்துக்குப் புறம்பே அசுத்தமான ஒரு இடத்திலே போடவும் அவன் கட்டளையிட்டு,',	3,	14,	40),
(3153,	'And he shall cause the house to be scraped within round about, and they shall pour out the dust that they scrape off without the city into an unclean place:',	'வீட்டை உள்ளே சுற்றிலும் செதுக்கச்சொல்லி, செதுக்கிப்போட்ட மண்ணைப் பட்டணத்துக்குப் புறம்பே அசுத்தமான ஒரு இடத்திலே கொட்டவும்,',	3,	14,	41),
(3154,	'And they shall take other stones, and put them in the place of those stones; and he shall take other morter, and shall plaister the house.',	'வேறே கல்லுகளை எடுத்துவந்து, அந்தக் கல்லுகளுக்குப் பதிலாகக் கட்டி, வேறே சாந்தை எடுத்து வீட்டைப் பூசவும் கட்டளையிடுவானாக.',	3,	14,	42),
(3155,	'And if the plague come again, and break out in the house, after that he hath taken away the stones, and after he hath scraped the house, and after it is plaistered;',	'கல்லுகளைப் பெயர்த்து, வீட்டைச்செதுக்கி, நவமாய்ப் பூசினபின்பும், அந்தத் தோஷம் திரும்ப வீட்டில் வந்ததானால்,',	3,	14,	43),
(3156,	'Then the priest shall come and look, and, behold, if the plague be spread in the house, it is a fretting leprosy in the house; it is unclean.',	'ஆசாரியன் போய்ப் பார்க்கக்கடவன்; தோஷம் வீட்டில் படர்ந்ததானால், அது வீட்டை அரிக்கிற குஷ்டம்; அது தீட்டாயிருக்கும்.',	3,	14,	44),
(3157,	'And he shall break down the house, the stones of it, and the timber thereof, and all the morter of the house; and he shall carry them forth out of the city into an unclean place.',	'ஆகையால் வீடுமுழுவதையும் இடித்து, அதின் கல்லுகளையும், மரங்களையும், அதின் சாந்து எல்லாவற்றையும் பட்டணத்துக்குப் புறம்பே அசுத்தமான இடத்திலே கொண்டுபோகவேண்டும்.',	3,	14,	45),
(3158,	'Moreover he that goeth into the house all the while that it is shut up shall be unclean until the even.',	'வீடு அடைக்கப்பட்டிருக்கும் நாட்களில் அதற்குள் பிரவேசிக்கிறவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்.',	3,	14,	46),
(3159,	'And he that lieth in the house shall wash his clothes; and he that eateth in the house shall wash his clothes.',	'அந்த வீட்டிலே படுத்தவன் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்; அந்த வீட்டிலே சாப்பிட்டவனும் தன் வஸ்திரங்களைத் தோய்க்கக்கடவன்.',	3,	14,	47),
(3160,	'And if the priest shall come in, and look upon it, and, behold, the plague hath not spread in the house, after the house was plaistered: then the priest shall pronounce the house clean, because the plague is healed.',	'ஆசாரியன் திரும்ப வந்து, வீடு பூசப்பட்டபின்பு வீட்டிலே அந்தத் தோஷம் படரவில்லை என்று கண்டானேயாகில், தோஷம் நிவிர்த்தியானபடியால், ஆசாரியன் அந்த வீட்டைச் சுத்தம் என்று தீர்க்கக்கடவன்.',	3,	14,	48),
(3161,	'And he shall take to cleanse the house two birds, and cedar wood, and scarlet, and hyssop:',	'அப்பொழுது வீட்டிற்குத் தோஷங்கழிக்க, இரண்டு குருவிகளையும், கேதுருக்கட்டையையும், சிவப்புநூலையும், ஈசோப்பையும் எடுத்து,',	3,	14,	49),
(3162,	'And he shall kill the one of the birds in an earthen vessel over running water:',	'ஒரு குருவியை ஒரு மண்பாண்டத்திலுள்ள ஊற்றுநீரின்மேல் கொன்று,',	3,	14,	50),
(3163,	'And he shall take the cedar wood, and the hyssop, and the scarlet, and the living bird, and dip them in the blood of the slain bird, and in the running water, and sprinkle the house seven times:',	'கேதுருக்கட்டையையும், ஈசோப்பையும், சிவப்புநூலையும், உயிருள்ள குருவியையும் எடுத்து, இவைகளைக் கொல்லப்பட்ட குருவியின் இரத்தத்திலும் ஊற்று நீரிலும் தோய்த்து, வீட்டின்மேல் ஏழுதரம் தெளித்து,',	3,	14,	51),
(3164,	'And he shall cleanse the house with the blood of the bird, and with the running water, and with the living bird, and with the cedar wood, and with the hyssop, and with the scarlet:',	'குருவியின் இரத்தத்தினாலும், ஊற்றுநீரினாலும், உயிருள்ள குருவியினாலும், கேதுருக்கட்டையினாலும் ஈசோப்பினாலும், சிவப்புநூலினாலும் வீட்டிற்குத் தோஷங்கழித்து,',	3,	14,	52),
(3165,	'But he shall let go the living bird out of the city into the open fields, and make an atonement for the house: and it shall be clean.',	'உயிருள்ள குருவியைப் பட்டணத்துக்குப் புறம்பே வெளியிலே விட்டுவிட்டு, இப்படி வீட்டிற்குப் பிராயச்சித்தம் செய்யக்கடவன்; அப்பொழுது அது சுத்தமாயிருக்கும்.',	3,	14,	53),
(3166,	'This is the law for all manner of plague of leprosy, and scall,',	'இது சகலவித குஷ்டரோகத்துக்கும், சொறிக்கும்,',	3,	14,	54),
(3167,	'And for the leprosy of a garment, and of a house,',	'வஸ்திரக் குஷ்டத்துக்கும், வீட்டுக்குஷ்டத்துக்கும்,',	3,	14,	55),
(3168,	'And for a rising, and for a scab, and for a bright spot:',	'தடிப்புக்கும், அசறுக்கும், வெள்ளைப்படருக்கும் அடுத்த பிரமாணம்.',	3,	14,	56),
(3169,	'To teach when it is unclean, and when it is clean: this is the law of leprosy.',	'குஷ்டம் எப்பொழுது தீட்டுள்ளது என்றும், எப்பொழுது தீட்டில்லாதது என்றும் தெரிவிப்பதற்குக் குஷ்டரோகத்துக்கு அடுத்த பிரமாணம் இதுவே என்றார்.  ',	3,	14,	57),
(3170,	'And the LORD spake unto Moses and to Aaron, saying,',	'பின்னும் கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	3,	15,	1),
(3171,	'Speak unto the children of Israel, and say unto them, When any man hath a running issue out of his flesh, because of his issue he is unclean.',	'நீங்கள் இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: ஒருவனுக்குப் பிரமியம் உண்டானால், அவன் தன் பிரமியத்தினாலே தீட்டானவன்.',	3,	15,	2),
(3172,	'And this shall be his uncleanness in his issue: whether his flesh run with his issue, or his flesh be stopped from his issue, it is his uncleanness.',	'அவனுடைய மாம்சத்திலுள்ள பிரமியம் ஊறிக்கொண்டிருந்தாலும், அவன் பிரமியம் அடைபட்டிருந்தாலும், அதினால் அவனுக்குத் தீட்டுண்டாகும்.',	3,	15,	3),
(3173,	'Every bed, whereon he lieth that hath the issue, is unclean: and every thing, whereon he sitteth, shall be unclean.',	'பிரமியமுள்ளவன் படுக்கிற எந்தப் படுக்கையும் தீட்டாகும்; அவன் எதின்மேல் உட்காருகிறானோ அதுவும் தீட்டாகும்.',	3,	15,	4),
(3174,	'And whosoever toucheth his bed shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'அவன் படுக்கையைத் தொடுகிறவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகக்கடவன்; சாயங்காலம்மட்டும் அவன் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	5),
(3175,	'And he that sitteth on any thing whereon he sat that hath the issue shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'பிரமியம் உள்ளவன் உட்கார்ந்ததின்மேல் உட்காருகிறவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பபட்டிருப்பானாக.',	3,	15,	6),
(3176,	'And he that toucheth the flesh of him that hath the issue shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'பிரமியம் உள்ளவனின் சரீரத்தைத் தொடுகிறவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	7),
(3177,	'And if he that hath the issue spit upon him that is clean; then he shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'பிரமியம் உள்ளவன் சுத்தமாயிருக்கிற ஒருவன்மேல் துப்பினால், இவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	8),
(3178,	'And what saddle soever he rideth upon that hath the issue shall be unclean.',	'பிரமியம் உள்ளவன் ஏறும் எந்தச்சேணமும் தீட்டாயிருக்கும்.',	3,	15,	9),
(3179,	'And whosoever toucheth any thing that was under him shall be unclean until the even: and he that beareth any of those things shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'அவனுக்குக் கீழிருந்த எதையாகிலும் தொடுகிறவன் சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்; அதை எடுத்துக்கொண்டு போகிறவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	10),
(3180,	'And whomsoever he toucheth that hath the issue, and hath not rinsed his hands in water, he shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'பிரமியம் உள்ளவன் தன் கைகளைத் தண்ணீரினால் கழுவாமல் ஒருவனைத் தொட்டால், இவன் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	11),
(3181,	'And the vessel of earth, that he toucheth which hath the issue, shall be broken: and every vessel of wood shall be rinsed in water.',	'பிரமியம் உள்ளவன் தொட்ட மண்பாண்டம் உடைக்கப்படவும், மரச்சாமான் எல்லாம் தண்ணீரினால் கழுவப்படவும் வேண்டும்.',	3,	15,	12),
(3182,	'And when he that hath an issue is cleansed of his issue; then he shall number to himself seven days for his cleansing, and wash his clothes, and bathe his flesh in running water, and shall be clean.',	'பிரமியம் உள்ளவன் தன் பிரமியம் நீங்கிச் சுத்தமானால், தன் சுத்திகரிப்புக்கென்று ஏழுநாள் எண்ணிக்கொண்டிருந்து, தன் வஸ்திரங்களைத் தோய்த்து, தன் தேகத்தை ஊற்றுநீரில் கழுவக்கடவன்; அப்பொழுது சுத்தமாயிருப்பான்.',	3,	15,	13),
(3183,	'And on the eighth day he shall take to him two turtledoves, or two young pigeons, and come before the LORD unto the door of the tabernacle of the congregation, and give them unto the priest:',	'எட்டாம்நாளிலே, அவன் இரண்டு காட்டுப்புறாக்களையாவது, இரண்டு புறாக்குஞ்சுகளையாவது, ஆசரிப்புக்கூடாரவாசலிலே கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, ஆசாரியனிடத்தில் கொடுக்கக்கடவன்.',	3,	15,	14),
(3184,	'And the priest shall offer them, the one for a sin offering, and the other for a burnt offering; and the priest shall make an atonement for him before the LORD for his issue.',	'ஆசாரியன் அவைகளில் ஒன்றைப்பாவநிவாரணபலியும் மற்றொன்றைச் சர்வாங்கதகனபலியுமாக்கி, அவனுக்காகக் கர்த்தருடைய சந்நிதியில் அவன் பிரமியத்தினிமித்தம் பாவநிவிர்த்தி செய்யவேண்டும்.',	3,	15,	15),
(3185,	'And if any man\'s seed of copulation go out from him, then he shall wash all his flesh in water, and be unclean until the even.',	'ஒருவனிலிருந்து இந்திரியம் கழிந்ததுண்டானால், அவன் தண்ணீரில் முழுகவேண்டும்; சாயங்காலம்மட்டும் அவன் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	16),
(3186,	'And every garment, and every skin, whereon is the seed of copulation, shall be washed with water, and be unclean until the even.',	'கழிந்த இந்திரியம் பட்ட வஸ்திரமும் தோலும் தண்ணீரினால் கழுவப்பட்டு, சாயங்காலம்மட்டும் தீட்டாயிருப்பதாக.',	3,	15,	17),
(3187,	'The woman also with whom man shall lie with seed of copulation, they shall both bathe themselves in water, and be unclean until the even.',	'இந்திரியம் கழிந்தவனோடே ஸ்திரீ படுத்துக்கொண்டிருந்தால், இருவரும் தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பார்களாக.',	3,	15,	18),
(3188,	'And if a woman have an issue, and her issue in her flesh be blood, she shall be put apart seven days: and whosoever toucheth her shall be unclean until the even.',	'சூதகஸ்திரீ தன் சரீரத்திலுள்ள உதிர ஊரலினிமித்தம் ஏழுநாள் தன் விலக்கத்தில் இருக்கக்கடவள்; அவளைத் தொடுகிறவன் எவனும் சாயங்காலம் மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	19),
(3189,	'And every thing that she lieth upon in her separation shall be unclean: every thing also that she sitteth upon shall be unclean.',	'அவள் விலக்கலாயிருக்கையில், எதின்மேல் படுத்துக்கொள்ளுகிறாளோ எதின்மேல் உட்காருகிறாளோ அதெல்லாம் தீட்டாயிருக்கும்.',	3,	15,	20),
(3190,	'And whosoever toucheth her bed shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'அவள் படுக்கையைத் தொடுகிறவன் எவனும் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	21),
(3191,	'And whosoever toucheth any thing that she sat upon shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'அவள் உட்கார்ந்த மணையைத்தொடுகிறவன் எவனும் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	22),
(3192,	'And if it be on her bed, or on any thing whereon she sitteth, when he toucheth it, he shall be unclean until the even.',	'அவள் படுக்கையின்மேலாகிலும், அவள் உட்கார்ந்த மணையின்மேலாகிலும் இருந்த எதையாகிலும் தொட்டவன், சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	23),
(3193,	'And if any man lie with her at all, and her flowers be upon him, he shall be unclean seven days; and all the bed whereon he lieth shall be unclean.',	'ஒருவன் அவளோடே படுத்துக்கொண்டதும், அவள் தீட்டு அவன்மேல் பட்டதுமுண்டானால், அவன் ஏழுநாள் தீட்டாயிருப்பானாக; அவன் படுக்கிறபடுக்கையும் தீட்டுப்படும்.',	3,	15,	24),
(3194,	'And if a woman have an issue of her blood many days out of the time of her separation, or if it run beyond the time of her separation; all the days of the issue of her uncleanness shall be as the days of her separation: she shall be unclean.',	'ஒரு ஸ்திரீ விலகியிருக்கவேண்டியகாலம் அல்லாமல் அவளுடைய உதிரம் அநேகநாள் ஊறிக்கொண்டிருந்தால், அல்லது அந்தக் காலத்துக்கு மிஞ்சி அது கண்டிருக்கும் நாளெல்லாம் ஊறிக்கொண்டிருந்தால், தன் விலக்கத்தின் நாட்களிலிருந்ததுபோல அவள் தீட்டாயிருப்பாளாக.',	3,	15,	25),
(3195,	'Every bed whereon she lieth all the days of her issue shall be unto her as the bed of her separation: and whatsoever she sitteth upon shall be unclean, as the uncleanness of her separation.',	'அந்த நாட்களெல்லாம் அவள் படுக்கும் எந்தப் படுக்கையும், அவள் விலக்கத்தின் படுக்கையைப்போல, அவளுக்குத் தீட்டாயிருக்கும்; அவள் உட்கார்ந்த மணையும், அவளுடைய விலக்கத்தின் தீட்டைப்போலவே தீட்டாயிருக்கும்.',	3,	15,	26),
(3196,	'And whosoever toucheth those things shall be unclean, and shall wash his clothes, and bathe himself in water, and be unclean until the even.',	'அப்படிப்பட்டவைகளைத் தொடுகிறவன் எவனும் தன் வஸ்திரங்களைத் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பானாக.',	3,	15,	27),
(3197,	'But if she be cleansed of her issue, then she shall number to herself seven days, and after that she shall be clean.',	'அவள் தன் உதிர ஊறல் நின்று சுத்தமானபோது, அவள் ஏழுநாள் எண்ணிக்கொள்வாளாக; அதின்பின்பு சுத்தமாயிருப்பாள்.',	3,	15,	28),
(3198,	'And on the eighth day she shall take unto her two turtles, or two young pigeons, and bring them unto the priest, to the door of the tabernacle of the congregation.',	'எட்டாம்நாளிலே இரண்டு காட்டுப்புறாக்களையாவது, இரண்டு புறாக்குஞ்சுகளையாவது, ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்தில் கொண்டுவரக்கடவள்.',	3,	15,	29),
(3199,	'And the priest shall offer the one for a sin offering, and the other for a burnt offering; and the priest shall make an atonement for her before the LORD for the issue of her uncleanness.',	'ஆசாரியன் அவைகளில் ஒன்றைப் பாவநிவாரணபலியும், மற்றொன்றைச் சர்வாங்க தகனபலியுமாக்கி, அவளுக்காகக் கர்த்தருடைய சந்நிதியில் அவளுடைய உதிர ஊறலினிமித்தம் பாவநிவிர்த்தி செய்யக்கடவன்.',	3,	15,	30),
(3200,	'Thus shall ye separate the children of Israel from their uncleanness; that they die not in their uncleanness, when they defile my tabernacle that is among them.',	'இஸ்ரவேல் புத்திரர் தங்கள் நடுவே இருக்கிற என்னுடைய வாசஸ்தலத்தைத் தீட்டுப்படுத்தி, தங்கள் தீட்டுகளால் சாகாதபடிக்கு, இப்படி நீங்கள் அவர்கள் தீட்டுகளுக்கு அவர்களை விலக்கிவைக்கக்கடவீர்கள்.',	3,	15,	31),
(3201,	'This is the law of him that hath an issue, and of him whose seed goeth from him, and is defiled therewith;',	'பிரமியமுள்ளவனுக்கும், இந்திரியக்கழிவினாலே தீட்டானவனுக்கும்,',	3,	15,	32),
(3202,	'And of her that is sick of her flowers, and of him that hath an issue, of the man, and of the woman, and of him that lieth with her that is unclean.',	'சூதக பலவீனமுள்ளவளுக்கும், பிரமியமுள்ள ஸ்திரீ புருஷருக்கும், தீட்டாயிருக்கிறவளோடே படுத்துக்கொண்டவனுக்கும் ஏற்ற பிரமாணம் இதுவே என்றார்.  ',	3,	15,	33),
(3203,	'And the LORD spake unto Moses after the death of the two sons of Aaron, when they offered before the LORD, and died;',	'ஆரோனின் இரண்டு குமாரர் கர்த்தருடைய சந்நிதியிலே சேர்ந்து மரித்துப்போனபின்பு, கர்த்தர் மோசேயை நோக்கி:',	3,	16,	1),
(3204,	'And the LORD said unto Moses, Speak unto Aaron thy brother, that he come not at all times into the holy place within the vail before the mercy seat, which is upon the ark; that he die not: for I will appear in the cloud upon the mercy seat.',	'கிருபாசனத்தின்மேல் ஒரு மேகத்தில் நான் காணப்படுவேன்; ஆதலால் உன் சகோதரனாகிய ஆரோன் சாகாதபடி, பரிசுத்த ஸ்தலத்திலே திரைக்கு உட்புறத்திலிருக்கிற பெட்டியின்மேலுள்ள கிருபாசன மூடிக்கு முன்பாகச் சகல வேளையிலும் வரவேண்டாம் என்று அவனுக்குச் சொல்.',	3,	16,	2),
(3205,	'Thus shall Aaron come into the holy place: with a young bullock for a sin offering, and a ram for a burnt offering.',	'ஆரோன் பரிசுத்த ஸ்தலத்துக்குள் பிரவேசிக்கவேண்டிய விதமாவது: அவன் ஒரு காளையைப் பாவநிவாரணபலியாகவும், ஒரு ஆட்டுக்கடாவைச் சர்வாங்க தகனபலியாகவும் செலுத்திப் பிரவேசிக்கவேண்டும்.',	3,	16,	3),
(3206,	'He shall put on the holy linen coat, and he shall have the linen breeches upon his flesh, and shall be girded with a linen girdle, and with the linen mitre shall he be attired: these are holy garments; therefore shall he wash his flesh in water, and so put them on.',	'அவன் பரிசுத்தமான சணல்நூல்சட்டையைத் தரித்து, தன் அரைக்குச் சணல்நூல் ஜல்லடத்தைப் போட்டு, சணல்நூல் இடைக்கச்சையைக் கட்டி, சணல்நூல் பாகையைத் தரித்துக்கொண்டிருக்கவேண்டும்; அவைகள் பரிசுத்த வஸ்திரங்கள்; அவன் ஜலத்திலே ஸ்நானம்பண்ணி, அவைகளைத் தரித்துக்கொண்டு,',	3,	16,	4),
(3207,	'And he shall take of the congregation of the children of Israel two kids of the goats for a sin offering, and one ram for a burnt offering.',	'இஸ்ரவேல் புத்திரராகிய சபையாரிடத்திலே, பாவநிவாரணபலியாக இரண்டு வெள்ளாட்டுக்கடாக்களையும், சர்வாங்கதகனபலியாக ஒரு ஆட்டுகடாவையும் வாங்கக்கடவன்.',	3,	16,	5),
(3208,	'And Aaron shall offer his bullock of the sin offering, which is for himself, and make an atonement for himself, and for his house.',	'பின்பு ஆரோன் தனக்காகவும் தன் வீட்டாருக்காகவும் பாவநிவிர்த்தி செய்யும்படிக்கு, தன்னுடைய பாவநிவாரணபலியின் காளையைச் சேரப்பண்ணி,',	3,	16,	6),
(3209,	'And he shall take the two goats, and present them before the LORD at the door of the tabernacle of the congregation.',	'அந்த இரண்டு வெள்ளாட்டுக்கடாக்களையும் கொண்டுவந்து, ஆசரிப்புக்கூடாரவாசலிலே கர்த்தருடைய சந்நிதியில் நிறுத்தி,',	3,	16,	7),
(3210,	'And Aaron shall cast lots upon the two goats; one lot for the LORD, and the other lot for the scapegoat.',	'அந்த இரண்டு வெள்ளாட்டுக்கடாக்களையுங்குறித்துக் கர்த்தருக்கென்று ஒரு சீட்டும், போக்காடாக விடப்படும் வெள்ளாட்டுக்கடாவுக்கென்று ஒரு சீட்டும் போட்டு,',	3,	16,	8),
(3211,	'And Aaron shall bring the goat upon which the LORD\'s lot fell, and offer him for a sin offering.',	'கர்த்தருக்கென்று சீட்டு விழுந்த வெள்ளாட்டுக்கடாவைப் பாவநிவாரணபலியாகச் சேரப்பண்ணி,',	3,	16,	9),
(3212,	'But the goat, on which the lot fell to be the scapegoat, shall be presented alive before the LORD, to make an atonement with him, and to let him go for a scapegoat into the wilderness.',	'போக்காடாக விடப்படச் சீட்டு விழுந்த வெள்ளாட்டுக்கடாவை, அதைக் கொண்டு பாவநிவிர்த்தி உண்டாக்கவும் அதைப் போக்காடாக வனாந்தரத்திலே போகவிடவும், கர்த்தருடைய சந்நிதியில் உயிரோடே நிறுத்தி;',	3,	16,	10),
(3213,	'And Aaron shall bring the bullock of the sin offering, which is for himself, and shall make an atonement for himself, and for his house, and shall kill the bullock of the sin offering which is for himself:',	'பின்பு ஆரோன் தனக்காவும் தன் வீட்டாருக்காகவும் பாவநிவிர்த்தி செய்யும்படி, தன்னுடைய பாவநிவாரணத்துக்கான காளையைக் கொண்டுவந்து, அதைக்கொன்று,',	3,	16,	11),
(3214,	'And he shall take a censer full of burning coals of fire from off the altar before the LORD, and his hands full of sweet incense beaten small, and bring it within the vail:',	'கர்த்தருடைய சந்நிதியிலிருக்கும் பலிபீடத்தின்மேலுள்ள நெருப்புத்தணலினால் தூபகலசத்தை நிரப்பி, பொடியாக்கப்பட்ட சுகந்த தூபவர்க்கத்திலே தன் கைப்பிடிகள் நிறைய எடுத்து, திரைக்கு உட்புறமாகக் கொண்டுவந்து,',	3,	16,	12),
(3215,	'And he shall put the incense upon the fire before the LORD, that the cloud of the incense may cover the mercy seat that is upon the testimony, that he die not:',	'தான் சாகாதபடிக்கு தூபமேகமானது சாட்சிப்பெட்டியின்மேல் இருக்கும் கிருபாசனத்தை மூடத்தக்கதாக, கர்த்தருடைய சந்நிதியில் அக்கினியின்மேல் தூபவர்க்கத்தைப் போடக்கடவன்.',	3,	16,	13),
(3216,	'And he shall take of the blood of the bullock, and sprinkle it with his finger upon the mercy seat eastward; and before the mercy seat shall he sprinkle of the blood with his finger seven times.',	'பின்பு காளையின் இரத்தத்திலே கொஞ்சம் எடுத்து, கீழ்ப்புறமாக நின்று, தன் விரலினால் கிருபாசனத்தின்மேல் தெளித்து, அந்த இரத்தத்தில் கொஞ்சம் எடுத்துக் கிருபாசனத்துக்கு முன்பாக ஏழுதரம் தன் விரலினால் தெளிக்கக்கடவன்.',	3,	16,	14),
(3217,	'Then shall he kill the goat of the sin offering, that is for the people, and bring his blood within the vail, and do with that blood as he did with the blood of the bullock, and sprinkle it upon the mercy seat, and before the mercy seat:',	'பின்பு ஜனத்தினுடைய பாவநிவாரணபலியான வெள்ளாட்டுக்கடாவை அவன் கொன்று, அதின் இரத்தத்தைத் திரைக்கு உட்புறமாகக் கொண்டுவந்து, காளையின் இரத்தத்தைத் தெளித்தது போல, அதின் இரத்தத்தையும் கிருபாசனத்தின்மேலும் அதற்கு முன்பாகவும் தெளித்து,',	3,	16,	15),
(3218,	'And he shall make an atonement for the holy place, because of the uncleanness of the children of Israel, and because of their transgressions in all their sins: and so shall he do for the tabernacle of the congregation, that remaineth among them in the midst of their uncleanness.',	'இஸ்ரவேல் புத்திரருடைய தீட்டுகளினிமித்தமும், அவர்களுடைய சகல பாவங்களினாலும் உண்டான அவர்களுடைய மீறுதல்களினிமித்தமும், பரிசுத்த ஸ்தலத்திற்காகப் பிராயச்சித்தஞ்செய்து, அவர்களிடத்தில் அவர்களுடைய தீட்டுகளுக்குள்ளே நிற்கிற ஆசரிப்புக் கூடாரத்திற்காகவும் அப்படியே செய்யக்கடவன்.',	3,	16,	16),
(3219,	'And there shall be no man in the tabernacle of the congregation when he goeth in to make an atonement in the holy place, until he come out, and have made an atonement for himself, and for his household, and for all the congregation of Israel.',	'பாவநிவிர்த்தி செய்யும்படி அவன் பரிசுத்த ஸ்தலத்துக்குள் பிரவேசித்து, தனக்காகவும் தன் வீட்டாருக்காகவும் இஸ்ரவேல் சபையார் அனைவருக்காகவும் பாவநிவிர்த்தி செய்து, வெளியே வருமளவும் ஆசரிப்புக் கூடாரத்தில் ஒருவரும் இருக்கலாகாது.',	3,	16,	17),
(3220,	'And he shall go out unto the altar that is before the LORD, and make an atonement for it; and shall take of the blood of the bullock, and of the blood of the goat, and put it upon the horns of the altar round about.',	'பின்பு அவன் கர்த்தருடைய சந்நிதியில் இருக்கிற பலிபீடத்தண்டை வந்து, அதற்காகப் பிராயச்சித்தஞ்செய்து, காளையின் இரத்தத்திலும் வெள்ளாட்டுக் கடாவின் இரத்தத்திலும் கொஞ்சம் எடுத்து, பலிபீடத்துக் கொம்புகளின் மேல் சுற்றிலும் பூசி,',	3,	16,	18),
(3221,	'And he shall sprinkle of the blood upon it with his finger seven times, and cleanse it, and hallow it from the uncleanness of the children of Israel.',	'தன் விரலினால் அந்த இரத்தத்தில் எடுத்து, ஏழுதரம் அதின்மேல் தெளித்து, அதை இஸ்ரவேல் புத்திரரின் தீட்டுகள் நீங்கச் சுத்திகரித்து, பரிசுத்தப்படுத்தக்கடவன்.',	3,	16,	19),
(3222,	'And when he hath made an end of reconciling the holy place, and the tabernacle of the congregation, and the altar, he shall bring the live goat:',	'அவன் இப்படிப் பரிசுத்த ஸ்தலத்துக்கும் ஆசரிப்புக் கூடாரத்துக்கும் பலிபீடத்துக்கும் பிராயச்சித்தஞ்செய்து தீர்ந்தபின்பு, உயிரோடிருக்கிற வெள்ளாட்டுக்கடாவைச் சேரப்பண்ணி,',	3,	16,	20),
(3223,	'And Aaron shall lay both his hands upon the head of the live goat, and confess over him all the iniquities of the children of Israel, and all their transgressions in all their sins, putting them upon the head of the goat, and shall send him away by the hand of a fit man into the wilderness:',	'அதின் தலையின்மேல் ஆரோன் தன் இரண்டு கைகளையும் வைத்து, அதின்மேல் இஸ்ரவேல் புத்திரருடைய சகல அக்கிரமங்களையும் அவர்களுடைய எல்லாப் பாவங்களினாலும் உண்டான அவர்களுடைய சகல மீறுதல்களையும் அறிக்கையிட்டு, அவைகளை வெள்ளாட்டுக்கடாவினுடைய தலையின்மேல் சுமத்தி, அதை அதற்கான ஆள்வசமாய் வனாந்தரத்துக்கு அனுப்பிவிடக்கடவன்.',	3,	16,	21),
(3224,	'And the goat shall bear upon him all their iniquities unto a land not inhabited: and he shall let go the goat in the wilderness.',	'அந்த வெள்ளாட்டுக்கடா அவர்களுடைய அக்கிரமங்களையெல்லாம் தன்மேல் சுமந்துகொண்டு, குடியில்லாத தேசத்துக்குப் போவதாக; அவன் அந்த வெள்ளாட்டுக்கடாவை வனாந்தரத்திலே போக விடக்கடவன்.',	3,	16,	22),
(3225,	'And Aaron shall come into the tabernacle of the congregation, and shall put off the linen garments, which he put on when he went into the holy place, and shall leave them there:',	'ஆரோன் ஆசரிப்புக் கூடாரத்துக்குள் வந்து, தான் பரிசுத்த ஸ்தலத்துக்குள் பிரவேசிக்கும்போது, உடுத்தியிருந்த சணல்நூல் வஸ்திரங்களைக் களைந்து, அங்கே வைத்துவிட்டு,',	3,	16,	23),
(3226,	'And he shall wash his flesh with water in the holy place, and put on his garments, and come forth, and offer his burnt offering, and the burnt offering of the people, and make an atonement for himself, and for the people.',	'பரிசுத்த இடத்திலே ஜலத்தில் ஸ்நானம்பண்ணி, தன் வஸ்திரங்களை உடுத்திக்கொண்டு, வெளியே வந்து, தன் சர்வாங்கதகனபலியையும் ஜனங்களின் சர்வாங்கதகனபலியையும் இட்டு, தனக்காகவும் ஜனங்களுக்காகவும் பாவநிவிர்த்தி செய்து,',	3,	16,	24),
(3227,	'And the fat of the sin offering shall he burn upon the altar.',	'பாவநிவாரணபலியின் கொழுப்பைப் பலிபீடத்தின்மேல் தகனிக்கக்கடவன்.',	3,	16,	25),
(3228,	'And he that let go the goat for the scapegoat shall wash his clothes, and bathe his flesh in water, and afterward come into the camp.',	'போகவிடப்படும் போக்காடாகிய வெள்ளாட்டுக்கடாவைக் கொண்டுபோய் விட்டவன், தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்தில் ஸ்நானம்பண்ணி, பின்பு பாளயத்துக்குள் வருவானாக.',	3,	16,	26),
(3229,	'And the bullock for the sin offering, and the goat for the sin offering, whose blood was brought in to make atonement in the holy place, shall one carry forth without the camp; and they shall burn in the fire their skins, and their flesh, and their dung.',	'பாவநிவிர்த்திக்கென்று பரிசுத்த ஸ்தலத்துக்குள் இரத்தம் கொண்டுவரப்பட்ட பாவநிவாரணபலியாகிய காளையையும், பாவநிவாரணபலியாகிய வெள்ளாட்டுக்கடாவையும், பாளயத்துக்குப் புறம்பே கொண்டுபோய், அவைகளின் தோலையும், மாம்சத்தையும், சாணியையும் அக்கினியிலே சுட்டெரிக்கக்கடவர்கள்.',	3,	16,	27),
(3230,	'And he that burneth them shall wash his clothes, and bathe his flesh in water, and afterward he shall come into the camp.',	'அவைகளைச் சுட்டெரித்தவன் தன் வஸ்திரங்களைத் தோய்த்து, ஜலத்திலே ஸ்நானம்பண்ணி, பின்பு பாளயத்துக்குள் வருவானாக.',	3,	16,	28),
(3231,	'And this shall be a statute for ever unto you: that in the seventh month, on the tenth day of the month, ye shall afflict your souls, and do no work at all, whether it be one of your own country, or a stranger that sojourneth among you:',	'ஏழாம் மாதம் பத்தாம் தேதியிலே, சுதேசியானாலும், உங்களுக்குள் தங்கும் பரதேசியானாலும், தங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்துவதுமன்றி, ஒரு வேலையும் செய்யாமல் இருக்கவேண்டும்; இது உங்களுக்கு நித்திய கட்டளையாய் இருக்கக்கடவது.',	3,	16,	29),
(3232,	'For on that day shall the priest make an atonement for you, to cleanse you, that ye may be clean from all your sins before the LORD.',	'கர்த்தருடைய சந்நிதியில் உங்கள் பாவமெல்லாம் நீங்கிச் சுத்திகரிக்கப்படும்படி, அந்நாளில் உங்களைச் சுத்திகரிக்கும் பொருட்டு, உங்களுக்காகப் பாவநிவிர்த்தி செய்யப்படும்.',	3,	16,	30),
(3233,	'It shall be a sabbath of rest unto you, and ye shall afflict your souls, by a statute for ever.',	'உங்களுக்கு அது விசேஷித்த ஓய்வு நாள்; அதிலே உங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்தக்கடவீர்கள்; இது நித்திய கட்டளை.',	3,	16,	31),
(3234,	'And the priest, whom he shall anoint, and whom he shall consecrate to minister in the priest\'s office in his father\'s stead, shall make the atonement, and shall put on the linen clothes, even the holy garments:',	'அபிஷேகம் பெற்றவனும், தன் தகப்பன் பட்டத்திற்கு வந்து ஆசாரிய ஊழியஞ்செய்யப் பிரதிஷ்டைபண்ணப்பட்டவனுமாகிய ஆசாரியனே பாவநிவிர்த்தி செய்யக்கடவன். அவன் பரிசுத்த வஸ்திரங்களாகிய சணல்நூல் வஸ்திரங்களை உடுத்திக்கொண்டு,',	3,	16,	32),
(3235,	'And he shall make an atonement for the holy sanctuary, and he shall make an atonement for the tabernacle of the congregation, and for the altar, and he shall make an atonement for the priests, and for all the people of the congregation.',	'பரிசுத்த ஸ்தலத்துக்கும் ஆசரிப்புக்கூடாரத்துக்கும், பலிபீடத்துக்கும், பிராயச்சித்தஞ்செய்து, ஆசாரியருக்காகவும் சபையின் சகல ஜனங்களுக்காகவும் பாவநிவிர்த்தி செய்யக்கடவன்.',	3,	16,	33),
(3236,	'And this shall be an everlasting statute unto you, to make an atonement for the children of Israel for all their sins once a year. And he did as the LORD commanded Moses.',	'இப்படி வருஷத்தில் ஒருமுறை இஸ்ரவேல் புத்திரருக்காக, அவர்களுடைய சகல பாவங்களுக்கும் பாவநிவிர்த்தி செய்வது, உங்களுக்கு நித்திய கட்டளையாயிருக்கக்கடவது என்று சொல் என்றார். கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே ஆரோன் செய்தான்.  ',	3,	16,	34),
(3237,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	17,	1),
(3238,	'Speak unto Aaron, and unto his sons, and unto all the children of Israel, and say unto them; This is the thing which the LORD hath commanded, saying,',	'நீ ஆரோனோடும் அவன் குமாரரோடும் இஸ்ரவேல் புத்திரர் அனைவரோடும் சொல்லவேண்டியதாவது; கர்த்தர் கட்டளையிடுகிறது என்னவென்றால்:',	3,	17,	2),
(3239,	'What man soever there be of the house of Israel, that killeth an ox, or lamb, or goat, in the camp, or that killeth it out of the camp,',	'இஸ்ரவேல் குடும்பத்தாரில் எவனாகிலும் மாட்டையாவது செம்மறியாட்டையாவது வெள்ளாட்டையாவது ஆசரிப்புக் கூடாரவாசலாகிய கர்த்தருடைய வாசஸ்தலத்துக்கு முன்பாக, கர்த்தருக்குச் செலுத்தும்படி கொண்டுவராமல்,',	3,	17,	3),
(3240,	'And bringeth it not unto the door of the tabernacle of the congregation, to offer an offering unto the LORD before the tabernacle of the LORD; blood shall be imputed unto that man; he hath shed blood; and that man shall be cut off from among his people:',	'பாளயத்துக்குள்ளேயாகிலும் பாளயத்துக்குப் புறம்பேயாகிலும் அதைக் கொன்றால், அது அந்த மனிதனுக்கு இரத்தப்பழியாக எண்ணப்படும் அந்த மனிதன் இரத்தம் சிந்தினபடியால், தன் ஜனத்தில் இராமல் அறுப்புண்டுபோவான்.',	3,	17,	4),
(3241,	'To the end that the children of Israel may bring their sacrifices, which they offer in the open field, even that they may bring them unto the LORD, unto the door of the tabernacle of the congregation, unto the priest, and offer them for peace offerings unto the LORD.',	'ஆகையால் இஸ்ரவேல் புத்திரர் வெளியிலே பலியிடுகிற தங்கள் பலிகளை, ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்தில் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, அங்கே அவைகளைக் கர்த்தருக்குச் சமாதானபலிகளாகச் செலுத்தக்கடவர்கள்.',	3,	17,	5),
(3242,	'And the priest shall sprinkle the blood upon the altar of the LORD at the door of the tabernacle of the congregation, and burn the fat for a sweet savour unto the LORD.',	'அங்கே ஆசாரியன் இரத்தத்தை ஆசரிப்புக் கூடாரவாசலிலிருக்கிற கர்த்தருடைய பலிபீடத்தின்மேல் தெளித்து, கொழுப்பைக் கர்த்தருக்குச் சுகந்த வாசனையாகத் தகனிக்கக்கடவன்.',	3,	17,	6),
(3243,	'And they shall no more offer their sacrifices unto devils, after whom they have gone a whoring. This shall be a statute for ever unto them throughout their generations.',	'தாங்கள் சோரமார்க்கமாய்ப் பின்பற்றுகிற பேய்களுக்குத் தங்கள் பலிகளை இனிச் செலுத்தாதிருப்பார்களாக; இது அவர்கள் தலைமுறைதோறும் அவர்களுக்கு நித்திய கட்டளையாயிருக்கக்கடவது.',	3,	17,	7),
(3244,	'And thou shalt say unto them, Whatsoever man there be of the house of Israel, or of the strangers which sojourn among you, that offereth a burnt offering or sacrifice,',	'மேலும் நீ அவர்களை நோக்கி: இஸ்ரவேல் குடும்பத்தாரிலும் உங்கள் நடுவே தங்குகிற அந்நியர்களிலும் எவனாகிலும் சர்வாங்கதகனபலி முதலானவைகளையிட்டு,',	3,	17,	8),
(3245,	'And bringeth it not unto the door of the tabernacle of the congregation, to offer it unto the LORD; even that man shall be cut off from among his people.',	'அதை ஆசரிப்புக் கூடாரவாசலிலே கர்த்தருக்குச் செலுத்தும்படி கொண்டுவராவிட்டால், அவன் தன் ஜனத்தில் இராமல் அறுப்புண்டுபோவான் என்று சொல்.',	3,	17,	9),
(3246,	'And whatsoever man there be of the house of Israel, or of the strangers that sojourn among you, that eateth any manner of blood; I will even set my face against that soul that eateth blood, and will cut him off from among his people.',	'இஸ்ரவேல் குடும்பத்தாரிலும் உங்களுக்குள் தங்கும் அந்நியர்களிலும் எவனாகிலும் இரத்தம் என்னப்பட்டதைப் புசித்தால், இரத்தத்தைப் புசித்த அவனுக்கு விரோதமாக நான் என் முகத்தைத் திருப்பி, அவன் தன் ஜனத்தில் இராதபடிக்கு அவனை அறுப்புண்டுபோகப்பண்ணுவேன்.',	3,	17,	10),
(3247,	'For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it is the blood that maketh an atonement for the soul.',	'மாம்சத்தின் உயிர் இரத்தத்தில் இருக்கிறது; நான் அதை உங்களுக்குப் பலிபீடத்தின்மேல் உங்கள் ஆத்துமாக்களுக்காகப் பாவநிவிர்த்தி செய்யும்படிக்குக் கட்டளையிட்டேன்; ஆத்துமாவிற்காகப் பாவநிவிர்த்தி செய்கிறது இரத்தமே.',	3,	17,	11),
(3248,	'Therefore I said unto the children of Israel, No soul of you shall eat blood, neither shall any stranger that sojourneth among you eat blood.',	'அதினிமித்தம் உங்களில் ஒருவனும் இரத்தம் புசிக்கவேண்டாம், உங்கள் நடுவே தங்குகிற அந்நியனும் இரத்தம் புசிக்கவேண்டாம் என்று இஸ்ரவேல் புத்திரருக்குச் சொன்னேன்.',	3,	17,	12),
(3249,	'And whatsoever man there be of the children of Israel, or of the strangers that sojourn among you, which hunteth and catcheth any beast or fowl that may be eaten; he shall even pour out the blood thereof, and cover it with dust.',	'இஸ்ரவேல் புத்திரரிலும் உங்களுக்குள் தங்குகிற அந்நியர்களிலும் எவனாகிலும் புசிக்கத்தக்க ஒரு மிருகத்தையாவது ஒரு பட்சியையாவது வேட்டையாடிப் பிடித்தால், அவன் அதின் இரத்தத்தைச் சிந்தப்பண்ணி, மண்ணினால் அதை மூடக்கடவன்.',	3,	17,	13),
(3250,	'For it is the life of all flesh; the blood of it is for the life thereof: therefore I said unto the children of Israel, Ye shall eat the blood of no manner of flesh: for the life of all flesh is the blood thereof: whosoever eateth it shall be cut off.',	'சகல மாம்சத்துக்கும் இரத்தம் உயிராயிருக்கிறது; இரத்தம் ஜீவனுக்குச் சமானம்; ஆகையால் எந்த மாம்சத்தின் இரத்தத்தையும் புசிக்கவேண்டாம்; சகல மாம்சத்தின் உயிரும் அதின் இரத்தந்தானே; அதைப் புசிக்கிற எவனும் அறுப்புண்டுபோவான் என்று இஸ்ரவேல் புத்திரருக்குச் சொன்னேன்.',	3,	17,	14),
(3251,	'And every soul that eateth that which died of itself, or that which was torn with beasts, whether it be one of your own country, or a stranger, he shall both wash his clothes, and bathe himself in water, and be unclean until the even: then shall he be clean.',	'தானாய் இறந்துபோனதையாவது, பீறுண்டதையாவது, புசித்தவன் எவனும் அவன் சுதேசியானாலும் பரதேசியானாலும், தன் வஸ்திரங்களைச் தோய்த்து, தண்ணீரில் முழுகி, சாயங்காலம்மட்டும் தீட்டாயிருப்பானாக; பின்பு சுத்தமாயிருப்பான்.',	3,	17,	15),
(3252,	'But if he wash them not, nor bathe his flesh; then he shall bear his iniquity.',	'அவன் தன் வஸ்திரங்களைத் தோய்க்காமலும், ஸ்நானம்பண்ணாமலும் இருந்தால், தன் அக்கிரமத்தைச் சுமப்பான் என்று சொல் என்றார்.  ',	3,	17,	16),
(3253,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	18,	1),
(3254,	'Speak unto the children of Israel, and say unto them, I am the LORD your God.',	'நீ இஸ்ரவேல் புத்திரருக்குச் சொல்லவேண்டியது என்னவென்றால்: நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	18,	2),
(3255,	'After the doings of the land of Egypt, wherein ye dwelt, shall ye not do: and after the doings of the land of Canaan, whither I bring you, shall ye not do: neither shall ye walk in their ordinances.',	'நீங்கள் குடியிருந்த எகிப்துதேசத்தாருடைய செய்கையின்படி செய்யாமலும், நான் உங்களை அழைத்துப்போகிற கானான் தேசத்தாருடைய செய்கையின்படி செய்யாமலும், அவர்களுடைய முறைமைகளின்படி நடவாமலும்,',	3,	18,	3),
(3256,	'Ye shall do my judgments, and keep mine ordinances, to walk therein: I am the LORD your God.',	'என்னுடைய நியாயங்களின்படி செய்து, என்னுடைய கட்டளைகளைக் கைக்கொண்டு நடவுங்கள்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	18,	4),
(3257,	'Ye shall therefore keep my statutes, and my judgments: which if a man do, he shall live in them: I am the LORD.',	'ஆகையால் என் கட்டளைகளையும் என் நியாயங்களையும் கைக்கொள்ளக்கடவீர்கள்; அவைகளின்படி செய்கிறவன் எவனும் அவைகளால் பிழைப்பான்; நான் கர்த்தர்.',	3,	18,	5),
(3258,	'None of you shall approach to any that is near of kin to him, to uncover their nakedness: I am the LORD.',	'ஒருவனும் தனக்கு நெருங்கின இனமாகிய ஒருத்தியை நிர்வாணமாக்கும்படி அவளைச் சேரலாகாது; நான் கர்த்தர்.',	3,	18,	6),
(3259,	'The nakedness of thy father, or the nakedness of thy mother, shalt thou not uncover: she is thy mother; thou shalt not uncover her nakedness.',	'உன் தகப்பனையாவது உன் தாயையாவது நிர்வாணமாக்கலாகாது; அவள் உன் தாயானவள்; அவளை நிர்வாணமாக்கலாகாது.',	3,	18,	7),
(3260,	'The nakedness of thy father\'s wife shalt thou not uncover: it is thy father\'s nakedness.',	'உன் தகப்பனுடைய மனைவியை நிர்வாணமாக்கலாகாது; அது உன் தகப்பனுடைய நிர்வாணம்.',	3,	18,	8),
(3261,	'The nakedness of thy sister, the daughter of thy father, or daughter of thy mother, whether she be born at home, or born abroad, even their nakedness thou shalt not uncover.',	'உன் தகப்பனுக்காவது உன் தாய்க்காவது வீட்டிலாகிலும் புறத்திலாகிலும் பிறந்த குமாரத்தியாகிய உன் சகோதரியை நிர்வாணமாக்கலாகாது.',	3,	18,	9),
(3262,	'The nakedness of thy son\'s daughter, or of thy daughter\'s daughter, even their nakedness thou shalt not uncover: for theirs is thine own nakedness.',	'உன் குமாரனுடைய மகளையாவது உன் குமாரத்தியினுடைய மகளையாவது நிர்வாணமாக்கலாகாது; அது உன்னுடைய நிர்வாணம்.',	3,	18,	10),
(3263,	'The nakedness of thy father\'s wife\'s daughter, begotten of thy father, she is thy sister, thou shalt not uncover her nakedness.',	'உன் தகப்பனுடைய மனைவியினிடத்தில் உன் தகப்பனுக்குப் பிறந்த குமாரத்தியை நிர்வாணமாக்கலாகாது; அவள் உனக்குச் சகோதரி.',	3,	18,	11),
(3264,	'Thou shalt not uncover the nakedness of thy father\'s sister: she is thy father\'s near kinswoman.',	'உன் தகப்பனுடைய சகோதரியை நிர்வாணமாக்கலாகாது; அவள் உன் தகப்பனுக்கு நெருங்கின இனமானவள்.',	3,	18,	12),
(3265,	'Thou shalt not uncover the nakedness of thy mother\'s sister: for she is thy mother\'s near kinswoman.',	'உன் தாயினுடைய சகோதரியை நிர்வாணமாக்கலாகாது; அவள் உன் தாய்க்கு நெருங்கின இனமானவள்.',	3,	18,	13),
(3266,	'Thou shalt not uncover the nakedness of thy father\'s brother, thou shalt not approach to his wife: she is thine aunt.',	'உன் தகப்பனுடைய சகோதரனை நிர்வாணமாக்கலாகாது; அவன் மனைவியைச் சேராயாக; அவள் உன் தகப்பனுடைய சகோதரி.',	3,	18,	14),
(3267,	'Thou shalt not uncover the nakedness of thy daughter in law: she is thy son\'s wife; thou shalt not uncover her nakedness.',	'உன் மருமகளை நிர்வாணமாக்கலாகாது; அவள் உன் குமாரனுக்கு மனைவி, அவளை நிர்வாணமாக்கலாகாது.',	3,	18,	15),
(3268,	'Thou shalt not uncover the nakedness of thy brother\'s wife: it is thy brother\'s nakedness.',	'உன் சகோதரனுடைய மனைவியை நிர்வாணமாக்கலாகாது; அது உன் சகோதரனுடைய நிர்வாணம்.',	3,	18,	16),
(3269,	'Thou shalt not uncover the nakedness of a woman and her daughter, neither shalt thou take her son\'s daughter, or her daughter\'s daughter, to uncover her nakedness; for they are her near kinswomen: it is wickedness.',	'ஒரு ஸ்திரீயையும் அவள் மகளையும் நிர்வாணமாக்கலாகாது; அவளுடைய குமாரரின் மகளையும் குமாரத்தியின் மகளையும் நிர்வாணமாக்குபடி விவாகம்பண்ணலாகாது; இவர்கள் அவளுக்கு நெருங்கின இனமானவர்கள்; அது முறைகேடு.',	3,	18,	17),
(3270,	'Neither shalt thou take a wife to her sister, to vex her, to uncover her nakedness, beside the other in her life time.',	'உன் மனைவி உயிரோடிருக்கையில், அவளுக்கு உபத்திரவமாக அவள் சகோதரியையும் நிர்வாணமாக்கும்பொருட்டு அவளை விவாகம் பண்ணலாகாது.',	3,	18,	18),
(3271,	'Also thou shalt not approach unto a woman to uncover her nakedness, as long as she is put apart for her uncleanness.',	'ஸ்திரீயானவள் சூதகத்தால் விலக்கத்திலிருக்கையில், அவளை நிர்வாணமாக்க அவளோடே சேராதே.',	3,	18,	19),
(3272,	'Moreover thou shalt not lie carnally with thy neighbour\'s wife, to defile thyself with her.',	'பிறனுடைய மனைவியோடே சேரும்படி சயனித்து, அவளால் உன்னைத் தீட்டுப்படுத்திக் கொள்ளவேண்டாம்.',	3,	18,	20),
(3273,	'And thou shalt not let any of thy seed pass through the fire to Molech, neither shalt thou profane the name of thy God: I am the LORD.',	'நீ உன் சந்ததியில் யாரையாகிலும் மோளேகுக்கென்று தீக்கடக்கும்படி இடங்கொடாதே; உன் தேவனுடைய நாமத்தைப் பரிசுத்தக் குலைச்சலாக்காதே; நான் கர்த்தர்.',	3,	18,	21),
(3274,	'Thou shalt not lie with mankind, as with womankind: it is abomination.',	'பெண்ணோடு சம்யோகம் பண்ணுகிறதுபோல ஆணோடே சம்யோகம் பண்ணவேண்டாம்; அது அருவருப்பானது.',	3,	18,	22),
(3275,	'Neither shalt thou lie with any beast to defile thyself therewith: neither shall any woman stand before a beast to lie down thereto: it is confusion.',	'யாதொரு மிருகத்தோடும் நீ புணர்ச்சிசெய்து, அதினாலே உன்னைத்தீட்டுப்படுத்த வேண்டாம்; ஸ்திரீயானவள் மிருகத்தோடே புணரும்படி அதற்கு முன்பாக நிற்கலாகாது; அது அருவருப்பான தாறுமாறு.',	3,	18,	23),
(3276,	'Defile not ye yourselves in any of these things: for in all these the nations are defiled which I cast out before you:',	'இவைகளில் ஒன்றினாலும் உங்களைத் தீட்டுப்படுத்தாதிருங்கள்; நான் உங்கள் முன்னின்று துரத்திவிடுகிற ஜாதிகள் இவைகளெல்லாவற்றினாலும் தங்களைத் தீட்டுப்படுத்தியிருக்கிறார்கள்; தேசமும் தீட்டுப்படுத்தப்பட்டிருக்கிறது.',	3,	18,	24),
(3277,	'And the land is defiled: therefore I do visit the iniquity thereof upon it, and the land itself vomiteth out her inhabitants.',	'ஆகையால் அதின் அக்கிரமத்தை விசாரிப்பேன்; தேசம் தன் குடிகளைக் கக்கிப்போடும்.',	3,	18,	25),
(3278,	'Ye shall therefore keep my statutes and my judgments, and shall not commit any of these abominations; neither any of your own nation, nor any stranger that sojourneth among you:',	'இந்த அருவருப்புகளையெல்லாம் உங்களுக்குமுன் இருந்த அந்த தேசத்தின் மனிதர் செய்ததினாலே தேசம் தீட்டாயிற்று.',	3,	18,	26),
(3279,	'(For all these abominations have the men of the land done, which were before you, and the land is defiled;)',	'இப்பொழுதும் உங்களுக்கு முன் இருந்த ஜாதிகளை தேசம் கக்கிப்போட்டதுபோல, நீங்கள் அதைத் தீட்டுப்படுத்தும்போது அது உங்களையும் கக்கிப்போடாதபடிக்கு,',	3,	18,	27),
(3280,	'That the land spue not you out also, when ye defile it, as it spued out the nations that were before you.',	'நீங்கள் என் கட்டளைகளையும் என் நியாயங்களையும் கைக்கொண்டு, தேசத்திலே பிறந்தவனானாலும் உங்கள் நடுவே தங்குகிற அந்நியனானாலும் இந்த அருவருப்புகளில் ஒன்றையும் செய்யவேண்டாம்.',	3,	18,	28),
(3281,	'For whosoever shall commit any of these abominations, even the souls that commit them shall be cut off from among their people.',	'இப்படிபட்ட அருவருப்பானவைகளில் யாதொன்றை யாராவது செய்தால், செய்த அந்த ஆத்துமாக்கள் ஜனத்தில் இராதபடிக்கு அறுப்புண்டு போவார்கள்.',	3,	18,	29),
(3282,	'Therefore shall ye keep mine ordinance, that ye commit not any one of these abominable customs, which were committed before you, and that ye defile not yourselves therein: I am the LORD your God.',	'ஆகையால் உங்களுக்குமுன் செய்யப்பட்ட அருவருப்பான முறைமைகளில் யாதொன்றை நீங்கள் செய்து, அவைகளால் உங்களைத் தீட்டுப்படுத்திக்கொள்ளாதபடிக்கு என் கட்டளையைக் கைக்கொள்ளுங்கள்; நான் உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.  ',	3,	18,	30),
(3283,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	19,	1),
(3284,	'Speak unto all the congregation of the children of Israel, and say unto them, Ye shall be holy: for I the LORD your God am holy.',	'நீ இஸ்ரவேல் புத்திரரின் சபை அனைத்தோடும் சொல்லவேண்டியது என்னவென்றால்: உங்கள் தேவனும் கர்த்தருமாகிய நான் பரிசுத்தர், ஆகையால் நீங்களும் பரிசுத்தராயிருங்கள்.',	3,	19,	2),
(3285,	'Ye shall fear every man his mother, and his father, and keep my sabbaths: I am the LORD your God.',	'உங்களில் அவனவன் தன்தன் தாய்க்கும் தன்தன் தகப்பனுக்கும் பயந்திருக்கவும், என் ஓய்வு நாட்களை ஆசரிக்கவும்கடவீர்கள்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	3),
(3286,	'Turn ye not unto idols, nor make to yourselves molten gods: I am the LORD your God.',	'விக்கிரகங்களை நாடாமலும், வார்ப்பிக்கப்பட்ட தெய்வங்களை உங்களுக்கு உண்டாக்காமலும் இருப்பீர்களாக; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	4),
(3287,	'And if ye offer a sacrifice of peace offerings unto the LORD, ye shall offer it at your own will.',	'நீங்கள் சமாதானபலியைக் கர்த்தருக்குச் செலுத்தினால், அதை மனோற்சாகமாய்ச் செலுத்துங்கள்.',	3,	19,	5),
(3288,	'It shall be eaten the same day ye offer it, and on the morrow: and if ought remain until the third day, it shall be burnt in the fire.',	'நீங்கள் அதைச் செலுத்துகிற நாளிலும் மறுநாளிலும் அதைப் புசிக்கவேண்டும்; மூன்றாம் நாள்மட்டும் மீதியானது அக்கினியிலே சுட்டெரிக்கப்படக்கடவது.',	3,	19,	6),
(3289,	'And if it be eaten at all on the third day, it is abominable; it shall not be accepted.',	'மூன்றாம் நாளில் அதில் ஏதாகிலும் புசிக்கப்பட்டால் அருவருப்பாயிருக்கும்; அது அங்கிகரிக்கப்படமாட்டாது.',	3,	19,	7),
(3290,	'Therefore every one that eateth it shall bear his iniquity, because he hath profaned the hallowed thing of the LORD: and that soul shall be cut off from among his people.',	'அதைப் புசிக்கிறவன் கர்த்தருக்குப் பரிசுத்தமானதைப் பரிசுத்தக்குலைச்சலாக்கினபடியால் அவன் தன் அக்கிரமத்தைச் சுமந்து, தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோவான்.',	3,	19,	8),
(3291,	'And when ye reap the harvest of your land, thou shalt not wholly reap the corners of thy field, neither shalt thou gather the gleanings of thy harvest.',	'நீங்கள் தேசத்தின் பயிரை அறுக்கும்போது, உன் வயலின் ஓரத்திலிருக்கிறதைத் தீர அறுக்காமலும், சிந்திக்கிடக்கிற கதிர்களைப் பொறுக்காமலும்,',	3,	19,	9),
(3292,	'And thou shalt not glean thy vineyard, neither shalt thou gather every grape of thy vineyard; thou shalt leave them for the poor and stranger: I am the LORD your God.',	'உன் திராட்சத்தோட்டத்திலே பின் அறுப்பை அறுக்காமலும், அதிலே சிந்திக்கிடக்கிற பழங்களைப் பொறுக்காமலும், அவைகளை எளியவனுக்கும் பரதேசிக்கும் விட்டுவிடுவாயாக; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	10),
(3293,	'Ye shall not steal, neither deal falsely, neither lie one to another.',	'நீங்கள் களவுசெய்யாமலும், வஞ்சனைபண்ணாமலும், ஒருவருக்கொருவர் பொய் சொல்லாமலும் இருங்கள்.',	3,	19,	11),
(3294,	'And ye shall not swear by my name falsely, neither shalt thou profane the name of thy God: I am the LORD.',	'என் நாமத்தைக்கொண்டு பொய்யாணையிடுகிறதினால், உங்கள் தேவனுடைய நாமத்தைப் பரிசுத்தக்குலைச்சலாக்காமலும் இருப்பீர்களாக; நான் கர்த்தர்.',	3,	19,	12),
(3295,	'Thou shalt not defraud thy neighbour, neither rob him: the wages of him that is hired shall not abide with thee all night until the morning.',	'பிறனை ஒடுக்காமலும் கொள்ளையிடாமலும் இருப்பாயாக; கூலிக்காரனுடைய கூலி விடியற்காலம்மட்டும் உன்னிடத்தில் இருக்கலாகாது.',	3,	19,	13),
(3296,	'Thou shalt not curse the deaf, nor put a stumblingblock before the blind, but shalt fear thy God: I am the LORD.',	'செவிடனை நிந்தியாமலும், குருடனுக்கு முன்னே தடுக்கலை வையாமலும், உன் தேவனுக்குப் பயந்திருப்பாயாக; நான் கர்த்தர்.',	3,	19,	14),
(3297,	'Ye shall do no unrighteousness in judgment: thou shalt not respect the person of the poor, nor honor the person of the mighty: but in righteousness shalt thou judge thy neighbour.',	'நியாயவிசாரணையில் அநியாயம் செய்யாதிருங்கள்; சிறியவனுக்கு முகதாட்சிணியம் செய்யாமலும், பெரியவனுடைய முகத்துக்கு அஞ்சாமலும், நீதியாகப் பிறனுக்கு நியாயந்தீர்ப்பாயாக.',	3,	19,	15),
(3298,	'Thou shalt not go up and down as a talebearer among thy people: neither shalt thou stand against the blood of thy neighbour; I am the LORD.',	'உன் ஜனங்களுக்குள்ளே அங்குமிங்கும் கோள்சொல்லித் திரியாயாக; பிறனுடைய இரத்தப்பழிக்கு உட்படவேண்டாம்; நான் கர்த்தர்.',	3,	19,	16),
(3299,	'Thou shalt not hate thy brother in thine heart: thou shalt in any wise rebuke thy neighbour, and not suffer sin upon him.',	'உன் சகோதரனை உன் உள்ளத்தில் பகையாயாக; பிறன்மேல் பாவம் சுமராதபடிக்கு அவனை எப்படியும் கடிந்து கொள்ளவேண்டும்.',	3,	19,	17),
(3300,	'Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.',	'பழிக்குப்பழி வாங்காமலும் உன் ஜனப்புத்திரர் மேல் பொறாமைகொள்ளாமலும், உன்னில் நீ அன்புகூறுவதுபோல் பிறனிலும் அன்புகூருவாயாக; நான் கர்த்தர்.',	3,	19,	18),
(3301,	'Ye shall keep my statutes. Thou shalt not let thy cattle gender with a diverse kind: thou shalt not sow thy field with mingled seed: neither shall a garment mingled of linen and woollen come upon thee.',	'என் கட்டளைகளைக் கைக்கொள்வீர்களாக; உன் மிருகஜீவன்களை வேறு ஜாதியோடே பொலியவிடாயாக; உன் வயலிலே வெவ்வேறு வகையான விதைகளைக் கலந்து விதையாயாக; சணல்நூலும் கம்பளிநூலும் கலந்த வஸ்திரத்தை உடுத்தாதிருப்பாயாக.',	3,	19,	19),
(3302,	'And whosoever lieth carnally with a woman, that is a bondmaid, betrothed to an husband, and not at all redeemed, nor freedom given her; she shall be scourged; they shall not be put to death, because she was not free.',	'ஒருவனுக்கு அடிமையானவள் ஒரு புருஷனுக்கு நியமிக்கப்பட்டவளாயிருந்து, முற்றிலும் மீட்கப்படாமலும் தன்னிச்சையாய் விடப்படாமலுமிருக்க, அவளோடே ஒருவன் சம்யோகமாய்ச் சயனம்பண்ணினால், அவர்கள் கொலை செய்யப்படாமல், அடிக்கப்படவேண்டும்; அவள் சுயாதீனமுள்ளவள் அல்ல.',	3,	19,	20),
(3303,	'And he shall bring his trespass offering unto the LORD, unto the door of the tabernacle of the congregation, even a ram for a trespass offering.',	'அவன் தன் குற்றநிவாரணபலியாய் ஆசரிப்புக் கூடாரவாசலிலே கர்த்தருடைய சந்நிதியில் ஒரு ஆட்டுக்கடாவைக் கொண்டுவரக்கடவன்.',	3,	19,	21),
(3304,	'And the priest shall make an atonement for him with the ram of the trespass offering before the LORD for his sin which he hath done: and the sin which he hath done shall be forgiven him.',	'அதினாலே ஆசாரியன் அவன் செய்த பாவத்தினிமித்தம் அவனுக்காகக் கர்த்தருடைய சந்நிதியில் பாவநிவிர்த்தி செய்யக்கடவன்; அப்பொழுது அவன் செய்த பாவம் அவனுக்கு மன்னிக்கப்படும்.',	3,	19,	22),
(3305,	'And when ye shall come into the land, and shall have planted all manner of trees for food, then ye shall count the fruit thereof as uncircumcised: three years shall it be as uncircumcised unto you: it shall not be eaten of.',	'நீங்கள் அந்த தேசத்தில் வந்து, புசிக்கத்தக்க கனிகளைத் தருகிற பலவித மரங்களை நாட்டினபின்பு அவைகளின் கனிகளை விருத்தசேதனமில்லாதவைகளென்று எண்ணுவீர்களாக; மூன்று வருஷம் அது புசிக்கப்படாமல், விருத்தசேதனமில்லாததாய் உங்களுக்கு எண்ணப்படவேண்டும்.',	3,	19,	23),
(3306,	'But in the fourth year all the fruit thereof shall be holy to praise the LORD withal.',	'பின்பு நாலாம் வருஷத்திலே அவைகளின் கனிகளெல்லாம் கர்த்தருக்குத் துதிசெலுத்துகிறதற்கேற்ற பரிசுத்தமாயிருக்கும்.',	3,	19,	24),
(3307,	'And in the fifth year shall ye eat of the fruit thereof, that it may yield unto you the increase thereof: I am the LORD your God.',	'ஐந்தாம் வருஷத்திலே அவைகளின் கனிகளைப் புசிக்கலாம்; இப்படி அவைகளின் பலன் உங்களுக்குப் பெருகும்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	25),
(3308,	'Ye shall not eat any thing with the blood: neither shall ye use enchantment, nor observe times.',	'யாதொன்றையும் இரத்தத்துடன் புசிக்கவேண்டாம். குறிகேளாமலும், நாள்பாராமலும் இருப்பீர்களாக.',	3,	19,	26),
(3309,	'Ye shall not round the corners of your heads, neither shalt thou mar the corners of thy beard.',	'உங்கள் தலைமயிரைச் சுற்றி ஒதுக்காமலும், தாடியின் ஓரங்களைக் கத்தரிக்காமலும்,',	3,	19,	27),
(3310,	'Ye shall not make any cuttings in your flesh for the dead, nor print any marks upon you: I am the LORD.',	'செத்தவனுக்காக உங்கள் சரீரத்தைக் கீறிக்கொள்ளாமலும், அடையாளமான எழுத்துக்களை உங்கள்மேல் குத்திக்கொள்ளாமலும் இருப்பீர்களாக; நான் கர்த்தர்.',	3,	19,	28),
(3311,	'Do not prostitute thy daughter, to cause her to be a whore; lest the land fall to whoredom, and the land become full of wickedness.',	'தேசத்தார் வேசித்தனம்பண்ணி தேசமெங்கும் முறைகேடான பாவம் நிறையாதபடிக்கு உன் குமாரத்தியை வேசித்தனம்பண்ண விடுகிறதினாலே பரிசுத்தக் குலைச்சலாக்காயாக.',	3,	19,	29),
(3312,	'Ye shall keep my sabbaths, and reverence my sanctuary: I am the LORD.',	'என் ஓய்வுநாட்களை ஆசரித்து, என் பரிசுத்த ஸ்தலத்தைக்குறித்துப் பயபக்தியாயிருப்பீர்களாக; நான் கர்த்தர்.',	3,	19,	30),
(3313,	'Regard not them that have familiar spirits, neither seek after wizards, to be defiled by them: I am the LORD your God.',	'அஞ்சனம் பார்க்கிறவர்களை நாடி, குறிசொல்லுகிறவர்களைத் தேடாதிருங்கள்; அவர்களாலே தீட்டுப்படவேண்டாம்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	31),
(3314,	'Thou shalt rise up before the hoary head, and honour the face of the old man, and fear thy God: I am the LORD.',	'நரைத்தவனுக்கு முன்பாக எழுந்து, முதிர்வயதுள்ளவன் முகத்தைக் கனம்பண்ணி, உன் தேவனுக்குப் பயப்படுவாயாக; நான் கர்த்தர்.',	3,	19,	32),
(3315,	'And if a stranger sojourn with thee in your land, ye shall not vex him.',	'யாதொரு அந்நியன் உங்கள் தேசத்தில் உங்களோடே தங்கினால், அவனைச் சிறுமைப்படுத்தவேண்டாம்.',	3,	19,	33),
(3316,	'But the stranger that dwelleth with you shall be unto you as one born among you, and thou shalt love him as thyself; for ye were strangers in the land of Egypt: I am the LORD your God.',	'உங்களிடத்தில் வாசம்பண்ணுகிற அந்நியனைச் சுதேசிபோல எண்ணி, நீங்கள் உங்களில் அன்புகூருகிறதுபோல அவனிலும் அன்புகூருவீர்களாக; நீங்களும் எகிப்துதேசத்தில் அந்நியராயிருந்தீர்களே; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	34),
(3317,	'Ye shall do no unrighteousness in judgment, in meteyard, in weight, or in measure.',	'நியாயவிசாரணையிலும், அளவிலும், நிறையிலும், படியிலும் அநியாயம் செய்யாதிருப்பீர்களாக.',	3,	19,	35),
(3318,	'Just balances, just weights, a just ephah, and a just hin, shall ye have: I am the LORD your God, which brought you out of the land of Egypt.',	'சுமுத்திரையான தராசும், சுமுத்திரையான நிறைகல்லும், சுமுத்திரையான மரக்காலும், சுமுத்திரையான படியும் உங்களுக்கு இருக்கவேண்டும்; நான் உங்களை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின உங்கள் தேவனாகிய கர்த்தர்.',	3,	19,	36),
(3319,	'Therefore shall ye observe all my statutes, and all my judgments, and do them: I am the LORD.',	'ஆகையால் என்னுடைய கட்டளைகள் யாவையும் என்னுடைய நியாயங்கள் யாவையும் கைக்கொண்டு, அவைகளின்படி நடக்கக்கடவீர்கள்; நான் கர்த்தர் என்று சொல் என்றார்.  ',	3,	19,	37),
(3320,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	3,	20,	1),
(3321,	'Again, thou shalt say to the children of Israel, Whosoever he be of the children of Israel, or of the strangers that sojourn in Israel, that giveth any of his seed unto Molech; he shall surely be put to death: the people of the land shall stone him with stones.',	'பின்னும் நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்; இஸ்ரவேல் புத்திரரிலும் இஸ்ரவேலில் வாசம்பண்ணுகிற அந்நியர்களிலும் எவனாகிலும் தன் சந்ததியில் ஒரு பிள்ளையை மோளேகுக்குக் கொடுத்தால், அவன் கொலைசெய்யப்படவேண்டும்; தேசத்தின் ஜனங்கள் அவன்மேல் கல்லெறியவேண்டும்.',	3,	20,	2),
(3322,	'And I will set my face against that man, and will cut him off from among his people; because he hath given of his seed unto Molech, to defile my sanctuary, and to profane my holy name.',	'அவன் என் பரிசுத்த ஸ்தலத்தைத் தீட்டுப்படுத்தி, என் பரிசுத்த நாமத்தைப் பரிசுத்தக் குலைச்சலாக்கும்படிக்கு, தன் சந்ததியில் ஒரு பிள்ளையை மோளேகுக்குக் கொடுத்ததினாலே, நான் அப்படிப்பட்டவனுக்கு விரோதமாக எதிர்த்து நின்று, அவனைத் தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டு போகப்பண்ணுவேன்.',	3,	20,	3),
(3323,	'And if the people of the land do any ways hide their eyes from the man, when he giveth of his seed unto Molech, and kill him not:',	'அவன் தன் சந்ததியில் ஒரு பிள்ளையை மோளேகுக்குக் கொடுக்கும்போது, தேசத்தின் ஜனங்கள் அவனைக் கொலைசெய்யாதபடிக்குக் கண்சாடையாயிருந்தால்,',	3,	20,	4),
(3324,	'Then I will set my face against that man, and against his family, and will cut him off, and all that go a whoring after him, to commit whoredom with Molech, from among their people.',	'நான் அந்த மனிதனுக்கும் அவன் குடும்பத்துக்கும் விரோதமாக எதிர்த்து நின்று, அவனையும், அவன் பிறகே மோளேகை விபசாரமார்க்கமாய்ப் பின்பற்றின யாவரையும், தங்கள் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோகப்பண்ணுவேன்.',	3,	20,	5),
(3325,	'And the soul that turneth after such as have familiar spirits, and after wizards, to go a whoring after them, I will even set my face against that soul, and will cut him off from among his people.',	'அஞ்சனம் பார்க்கிறவர்களையும் குறிசொல்லுகிறவர்களையும் பின்தொடர்ந்து சோரம்போக எந்த ஆத்துமா அவர்களை நாடுகிறானோ, அந்த ஆத்துமாவுக்கு விரோதமாக எதிர்த்துநின்று, அவனைத் தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோகப்பண்ணுவேன்.',	3,	20,	6),
(3326,	'Sanctify yourselves therefore, and be ye holy: for I am the LORD your God.',	'ஆதலால் நீங்கள் உங்களைப் பரிசுத்தப்படுத்திப் பரிசுத்தராயிருங்கள்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	20,	7),
(3327,	'And ye shall keep my statutes, and do them: I am the LORD which sanctify you.',	'என் கட்டளைகளைக் கைக்கொண்டு நடவுங்கள்; நான் உங்களைப் பரிசுத்தமாக்குகிற கர்த்தர்.',	3,	20,	8),
(3328,	'For every one that curseth his father or his mother shall be surely put to death: he hath cursed his father or his mother; his blood shall be upon him.',	'தன் தகப்பனையாவது தன் தாயையாவது சபிக்கிற எவனும் கொலைசெய்யப்படக்கடவன்; அவன் தன் தகப்பனையும் தன் தாயையும் சபித்தான், அவன் இரத்தப்பழி அவன்மேல் இருப்பதாக.',	3,	20,	9),
(3329,	'And the man that committeth adultery with another man\'s wife, even he that committeth adultery with his neighbour\'s wife, the adulterer and the adulteress shall surely be put to death.',	'ஒருவன் பிறனுடைய மனைவியோடே விபசாரம் செய்தால், பிறன் மனைவியோடே விபசாரம் செய்த அந்த விபசாரனும் அந்த விபசாரியும் கொலைசெய்யப்படக்கடவர்கள்.',	3,	20,	10),
(3330,	'And the man that lieth with his father\'s wife hath uncovered his father\'s nakedness: both of them shall surely be put to death; their blood shall be upon them.',	'தன் தகப்பன் மனைவியோடே சயனிக்கிறவன் தன் தகப்பனை நிர்வாணமாக்கினபடியால், இருவரும் கொலைசெய்யப்படக்கடவர்கள்; அவர்கள் இரத்தப்பழி அவர்கள்மேல் இருப்பதாக.',	3,	20,	11),
(3331,	'And if a man lie with his daughter in law, both of them shall surely be put to death: they have wrought confusion; their blood shall be upon them.',	'ஒருவன் தன் மருமகளோடே சயனித்தால், இருவரும் கொலைசெய்யப்படக்கடவர்கள்; அருவருப்பான தாறுமாறு பண்ணினார்கள்; அவர்கள் இரத்தப்பழி அவர்கள்மேல் இருப்பதாக.',	3,	20,	12),
(3332,	'If a man also lie with mankind, as he lieth with a woman, both of them have committed an abomination: they shall surely be put to death; their blood shall be upon them.',	'ஒருவன் பெண்ணோடே சம்யோகம்பண்ணுகிறதுபோல ஆணோடே சம்யோகம்பண்ணினால், அருவருப்பான காரியம் செய்த அவ்விருவரும் கொலைசெய்யப்படக்கடவர்கள்; அவர்கள் இரத்தப்பழி அவர்கள்மேல் இருப்பதாக.',	3,	20,	13),
(3333,	'And if a man take a wife and her mother, it is wickedness: they shall be burnt with fire, both he and they; that there be no wickedness among you.',	'ஒருவன் ஒரு ஸ்திரீயையும் அவள் தாயையும் படைத்தால், அது முறைகேடு; இவ்வித முறைகேடு உங்களுக்குள் இராதபடிக்கு, அவனையும் அவர்களையும் அக்கினியில் சுட்டெரிக்கவேண்டும்.',	3,	20,	14),
(3334,	'And if a man lie with a beast, he shall surely be put to death: and ye shall slay the beast.',	'ஒருவன் மிருகத்தோடே புணர்ந்தால், அவன் கொலைசெய்யப்படக்கடவன்; அந்த மிருகத்தையும் கொல்லக்கடவீர்கள்.',	3,	20,	15),
(3335,	'And if a woman approach unto any beast, and lie down thereto, thou shalt kill the woman, and the beast: they shall surely be put to death; their blood shall be upon them.',	'ஒரு ஸ்திரீ யாதொரு மிருகத்தோடே சேர்ந்து சயனித்தால், அந்த ஸ்திரீயையும் அந்த மிருகத்தையும் கொல்லக்கடவாய்; இருஜீவனும் கொலைசெய்யப்படவேண்டும்; அவைகளின் இரத்தப்பழி அவைகளின்மேல் இருப்பதாக.',	3,	20,	16),
(3336,	'And if a man shall take his sister, his father\'s daughter, or his mother\'s daughter, and see her nakedness, and she see his nakedness; it is a wicked thing; and they shall be cut off in the sight of their people: he hath uncovered his sister\'s nakedness; he shall bear his iniquity.',	'ஒருவன் தன் தகப்பனுக்காவது தன் தாய்க்காவது குமாரத்தியாயிருக்கிற தன் சகோதரியைச் சேர்த்துக்கொண்டு, அவன் அவளுடைய நிர்வாணத்தையும், அவள் அவனுடைய நிர்வாணத்தையும் பார்த்தால், அது பாதகம்; அவர்கள் தங்கள் ஜனங்களின் கண்களுக்கு முன்பாக அறுப்புண்டு போகக்கடவர்கள்; அவன் தன் சகோதரியை நிர்வாணப்படுத்தினான்; அவன் தன் அக்கிரமத்தைச் சுமப்பான்.',	3,	20,	17),
(3337,	'And if a man shall lie with a woman having her sickness, and shall uncover her nakedness; he hath discovered her fountain, and she hath uncovered the fountain of her blood: and both of them shall be cut off from among their people.',	'ஒருவன் சூதகஸ்திரீயோடே சயனித்து, அவளை நிர்வாணமாக்கினால், அவன் அவளுடைய உதிர ஊற்றைத் திறந்து, அவளும் தன் உதிர ஊற்றை வெளிப்படுத்தினபடியால், இருவரும் தங்கள் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோகவேண்டும்.',	3,	20,	18),
(3338,	'And thou shalt not uncover the nakedness of thy mother\'s sister, nor of thy father\'s sister: for he uncovereth his near kin: they shall bear their iniquity.',	'உன் தாயினுடைய சகோதரியையும் உன் தகப்பனுடைய சகோதரியையும் நிர்வாணமாக்காயாக, அப்படிப்பட்டவன் தன் நெருங்கிய இனத்தை அவமானமாக்கினான்; அவர்கள் தங்கள் அக்கிரமத்தைச் சுமப்பார்கள்.',	3,	20,	19),
(3339,	'And if a man shall lie with his uncle\'s wife, he hath uncovered his uncle\'s nakedness: they shall bear their sin; they shall die childless.',	'ஒருவன் தன் தகப்பனின் சகோதரனுடைய மனைவியோடே சயனித்தால், அவன் தன் தகப்பனின் சகோதரனை நிர்வாணமாக்கினான்; அவர்கள் தங்கள் பாவத்தைச் சுமப்பார்கள், சந்தானமில்லாமல் சாவார்கள்.',	3,	20,	20),
(3340,	'And if a man shall take his brother\'s wife, it is an unclean thing: he hath uncovered his brother\'s nakedness; they shall be childless.',	'ஒருவன் தன் சகோதரன் மனைவியை விவாகம்பண்ணினால், அது அசுத்தம்; தன் சகோதரனை நிர்வாணமாக்கினான், அவர்கள் சந்தானமற்றிருப்பார்கள்.',	3,	20,	21),
(3341,	'Ye shall therefore keep all my statutes, and all my judgments, and do them: that the land, whither I bring you to dwell therein, spue you not out.',	'ஆகையால் நீங்கள் குடியிருப்பதற்காக நான் உங்களைக் கொண்டுபோகிற தேசம் உங்களைக் கக்கிப்போடாதபடிக்கு, நீங்கள் என் கட்டளைகள் யாவையும் என்னுடைய நியாயங்கள் யாவையும் கைக்கொண்டு நடவுங்கள்.',	3,	20,	22),
(3342,	'And ye shall not walk in the manners of the nation, which I cast out before you: for they committed all these things, and therefore I abhorred them.',	'நான் உங்களுக்கு முன்பாகத் துரத்திவிடுகிற ஜனத்தினுடைய வழிபாடுகளில் நடவாதிருங்கள்; அவர்கள் இப்படிப்பட்ட காரியங்களையெல்லாம் செய்தபடியால் நான் அவர்களை அரோசித்தேன்.',	3,	20,	23),
(3343,	'But I have said unto you, Ye shall inherit their land, and I will give it unto you to possess it, a land that floweth with milk and honey: I am the LORD your God, which have separated you from other people.',	'நீங்கள் அவர்கள் தேசத்தைச் சுதந்தரிப்பீர்கள் என்று உங்களோடே சொன்னேன்; பாலும் தேனும் ஒடுகிற அந்த தேசத்தை உங்களுக்குச் சுதந்தரமாகக் கொடுப்பேன்; உங்களை மற்ற ஜனங்களை விட்டுப் பிரித்தெடுத்த உங்கள் தேவனாகிய கர்த்தர் நானே.',	3,	20,	24),
(3344,	'Ye shall therefore put difference between clean beasts and unclean, and between unclean fowls and clean: and ye shall not make your souls abominable by beast, or by fowl, or by any manner of living thing that creepeth on the ground, which I have separated from you as unclean.',	'ஆகையால் சுத்தமான மிருகங்களுக்கும் அசுத்தமான மிருகங்களுக்கும், சுத்தமான பறவைகளுக்கும் அசுத்தமான பறவைகளுக்கும் நீங்கள் வித்தியாசம்பண்ணி, நான் உங்களுக்குத் தீட்டாக எண்ணச்சொல்லி விலக்கின மிருகங்களாலும் பறவைகளாலும் தரையிலே ஊருகிற யாதொரு பிராணிகளாலும் உங்களை அருவருப்பாக்காதிருப்பீர்களாக.',	3,	20,	25),
(3345,	'And ye shall be holy unto me: for I the LORD am holy, and have severed you from other people, that ye should be mine.',	'கர்த்தராகிய நான் பரிசுத்தராயிருக்கிறபடியினாலே நீங்களும் எனக்கேற்ற பரிசுத்தவான்களாயிருப்பீர்களாக; நீங்கள் என்னுடையவர்களாயிருக்கும்படிக்கு, உங்களை மற்ற ஜனங்களைவிட்டுப் பிரித்தெடுத்தேன்.',	3,	20,	26),
(3346,	'A man also or woman that hath a familiar spirit, or that is a wizard, shall surely be put to death: they shall stone them with stones: their blood shall be upon them.',	'அஞ்சனம் பார்க்கிறவர்களும் குறிசொல்லுகிறவர்களுமாயிருக்கிற புருஷனாகிலும் ஸ்திரீயாகிலும் கொலைசெய்யப்படவேண்டும்; அவர்கள்மேல் கல்லெறிவார்களாக; அவர்கள் இரத்தப்பழி அவர்கள்மேல் இருக்கக்கடவது என்று சொல் என்றார்.  ',	3,	20,	27),
(3347,	'And the LORD said unto Moses, Speak unto the priests the sons of Aaron, and say unto them, There shall none be defiled for the dead among his people:',	'பின்பு கர்த்தர் மோசேயை நோக்கி: ஆரோனின் குமாரராகிய ஆசாரியர்களில் ஒருவனும் தன் ஜனத்தாரில் இறந்துபோன யாதொருவருக்காகத் தங்களைத் தீட்டுப்படுத்தலாகாதென்று அவர்களோடே சொல்.',	3,	21,	1),
(3348,	'But for his kin, that is near unto him, that is, for his mother, and for his father, and for his son, and for his daughter, and for his brother.',	'தன் தாயும், தன் தகப்பனும், தன் குமாரனும், தன் குமாரத்தியும், தன் சகோதரனும்,',	3,	21,	2),
(3349,	'And for his sister a virgin, that is nigh unto him, which hath had no husband; for her may he be defiled.',	'புருஷனுக்கு வாழ்க்கைப்படாமல் தன்னிடத்திலிருக்கிற கன்னியாஸ்திரீயான தன் சகோதரியுமாகிய தனக்கு நெருங்கிய இனமான இவர்களுடைய சாவுக்காகத் தீட்டுப்படலாம்.',	3,	21,	3),
(3350,	'But he shall not defile himself, being a chief man among his people, to profane himself.',	'தன் ஜனத்தாரில் பெரியவனாகிய அவன் வேறொருவருக்காகவும் தன்னைப் பரிசுத்தக்குலைச்சலாக்கித் தீட்டுப்படுத்தலாகாது.',	3,	21,	4),
(3351,	'They shall not make baldness upon their head, neither shall they shave off the corner of their beard, nor make any cuttings in their flesh.',	'அவர்கள் தங்கள் தலையை மொட்டையடிக்காமலும், தங்கள் தாடியின் ஓரங்களைச் சிரைத்துப்போடாமலும், தங்கள் தேகத்தைக் கீறிக்கொள்ளாமலும் இருப்பார்களாக.',	3,	21,	5),
(3352,	'They shall be holy unto their God, and not profane the name of their God: for the offerings of the LORD made by fire, and the bread of their God, they do offer: therefore they shall be holy.',	'தங்கள் தேவனுடைய நாமத்தைப் பரிசுத்தக் குலைச்சலாக்காமல் அவருக்கேற்ற பரிசுத்தராயிருப்பார்களாக; அவர்கள் கர்த்தரின் தகனபலிகளையும் தங்கள் தேவனுடைய அப்பத்தையும் செலுத்துகிறவர்களாதலால் பரிசுத்தராயிருக்கவேண்டும்.',	3,	21,	6),
(3353,	'They shall not take a wife that is a whore, or profane; neither shall they take a woman put away from her husband: for he is holy unto his God.',	'அவர்கள் தங்கள் தேவனுக்குப் பரிசுத்தமானவர்கள், ஆகையால் வேசியையாகிலும் கற்புக்குலைந்தவளையாகிலும் விவாகம்பண்ணார்களாக; தன் புருஷனாலே தள்ளப்பட்ட ஸ்திரீயையும் விவாகம்பண்ணார்களாக.',	3,	21,	7),
(3354,	'Thou shalt sanctify him therefore; for he offereth the bread of thy God: he shall be holy unto thee: for I the LORD, which sanctify you, am holy.',	'அவன் தேவனுடைய அப்பத்தைச் செலுத்துகிறபடியால் நீ அவனைப் பரிசுத்தப்படுத்தவேண்டும்; உங்களைப் பரிசுத்தமாக்குகிற கர்த்தராகிய நான் பரிசுத்தராயிருக்கிறபடியால், அவனும் உனக்கு முன்பாகப் பரிசுத்தனாயிருப்பானாக.',	3,	21,	8),
(3355,	'And the daughter of any priest, if she profane herself by playing the whore, she profaneth her father: she shall be burnt with fire.',	'ஆசாரியனுடைய குமாரத்தி, வேசித்தனம்பண்ணி, தன்னைப் பரிசுத்தக்குலைச்சலாக்கினால், அவள் தன் தகப்பனையும் பரிசுத்தக் குலைச்சலாக்குகிறாள்; அவள் அக்கினியிலே சுட்டெரிக்கப்படக்கடவள்.',	3,	21,	9),
(3356,	'And he that is the high priest among his brethren, upon whose head the anointing oil was poured, and that is consecrated to put on the garments, shall not uncover his head, nor rend his clothes;',	'தன் சகோதரருக்குள்ளே பிரதான ஆசாரியனாக தன் சிரசில் அபிஷேகதைலம் வார்க்கப்பட்டவனும், அவனுக்குரிய வஸ்திரங்களைத் தரிக்கும்படி பிரதிஷ்டை பண்ணப்பட்டவனுமாயிருக்கிறவன் எவனோ, அவன் தன் பாகையை எடுக்காமலும், தன் வஸ்திரங்களைக் கிழித்துக்கொள்ளாமலும்,',	3,	21,	10),
(3357,	'Neither shall he go in to any dead body, nor defile himself for his father, or for his mother;',	'பிரேதம் கிடக்கும் இடத்தில் போகாமலும், தன் தகப்பனுக்காகவும் தன் தாய்க்காகவும் தன்னைத் தீட்டுப்படுத்திக்கொள்ளாமலும்,',	3,	21,	11),
(3358,	'Neither shall he go out of the sanctuary, nor profane the sanctuary of his God; for the crown of the anointing oil of his God is upon him: I am the LORD.',	'பரிசுத்த ஸ்தலத்திலிருந்து புறப்படாமலும் தன் தேவனுடைய பரிசுத்த ஸ்தலத்தைப் பரிசுத்தக் குலைச்சலாக்காமலும் இருப்பானாக; அவனுடைய தேவனின் அபிஷேகதைலம் என்னும் கிரீடம் அவன்மேல் இருக்கிறதே: நான் கர்த்தர்.',	3,	21,	12),
(3359,	'And he shall take a wife in her virginity.',	'கன்னிகையாயிருக்கிற பெண்ணை அவன் விவாகம்பண்ணவேண்டும்.',	3,	21,	13),
(3360,	'A widow, or a divorced woman, or profane, or an harlot, these shall he not take: but he shall take a virgin of his own people to wife.',	'விதவையையானாலும் தள்ளப்பட்டவளையானாலும் கற்புக்குலைந்தவளையானாலும் வேசியையானாலும் விவாகம்பண்ணாமல், தன் ஜனங்களுக்குள்ளே ஒரு கன்னிகையை விவாகம்பண்ணக்கடவன்.',	3,	21,	14),
(3361,	'Neither shall he profane his seed among his people: for I the LORD do sanctify him.',	'அவன் தன் வித்தைத் தன் ஜனங்களுக்குள்ளே பரிசுத்தக் குலைச்சலாக்காமல் இருப்பானாக; நான் அவனைப் பரிசுத்தமாக்குகிற கர்த்தர் என்று சொல் என்றார்.',	3,	21,	15),
(3362,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	21,	16),
(3363,	'Speak unto Aaron, saying, Whosoever he be of thy seed in their generations that hath any blemish, let him not approach to offer the bread of his God.',	'நீ ஆரோனோடே சொல்லவேண்டியது என்னவென்றால்: உன் சந்ததியாருக்குள்ளே அங்கவீனமுள்ளவன் தலைமுறைதோறும் தேவனுடைய அப்பத்தைச் செலுத்தும்படி சேரலாகாது.',	3,	21,	17),
(3364,	'For whatsoever man he be that hath a blemish, he shall not approach: a blind man, or a lame, or he that hath a flat nose, or any thing superfluous,',	'அங்கவீனமுள்ள ஒருவனும் அணுகலாகாது; குருடனானாலும், சப்பாணியானாலும், குறுகின அல்லது நீண்ட அவயவமுள்ளவனானாலும்,',	3,	21,	18),
(3365,	'Or a man that is brokenfooted, or brokenhanded,',	'காலொடிந்தவனானாலும், கையொடிந்தவனானாலும்,',	3,	21,	19),
(3366,	'Or crookbackt, or a dwarf, or that hath a blemish in his eye, or be scurvy, or scabbed, or hath his stones broken;',	'கூனனானாலும், குள்ளனானாலும், பூவிழுந்த கண்ணனானாலும், சொறியனானாலும், அசறுள்ளவனானாலும், விதை நசுங்கினவனானாலும் அணுகலாகாது.',	3,	21,	20),
(3367,	'No man that hath a blemish of the seed of Aaron the priest shall come nigh to offer the offerings of the LORD made by fire: he hath a blemish; he shall not come nigh to offer the bread of his God.',	'ஆசாரியனாகிய ஆரோனின் சந்ததியாரில் அங்கவீனமுள்ள ஒருவனும் கர்த்தரின் தகனபலிகளைச் செலுத்தச் சேரலாகாது; அவன் அங்கவீனமுள்ளவனாகையால், அவன் தேவனுடைய அப்பத்தைச் செலுத்தச் சேரலாகாது.',	3,	21,	21),
(3368,	'He shall eat the bread of his God, both of the most holy, and of the holy.',	'அவன் தன் தேவனுடைய அப்பமாகிய மகா பரிசுத்தமானவைகளிலும் மற்ற பரிசுத்தமானவைகளிலும் புசிக்கலாம்.',	3,	21,	22),
(3369,	'Only he shall not go in unto the vail, nor come nigh unto the altar, because he hath a blemish; that he profane not my sanctuaries: for I the LORD do sanctify them.',	'ஆனாலும் அவன் அங்கவீனமுள்ளவனாகையால், அவன் என் பரிசுத்த ஸ்தலங்களைப் பரிசுத்தக் குலைச்சலாக்காதபடிக்குத் திரைக்குள்ளே போகாமலும் பலிபீடத்தண்டையில் சேராமலும் இருப்பானாக; நான் அவர்களைப் பரிசுத்தமாக்குகிற கர்த்தர் என்று சொல் என்றார்.',	3,	21,	23),
(3370,	'And Moses told it unto Aaron, and to his sons, and unto all the children of Israel.',	'மோசே இவைகளை ஆரோனோடும் அவன் குமாரரோடும் இஸ்ரவேல் புத்திரர் அனைவரோடும் சொன்னான்.  ',	3,	21,	24),
(3371,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	22,	1),
(3372,	'Speak unto Aaron and to his sons, that they separate themselves from the holy things of the children of Israel, and that they profane not my holy name in those things which they hallow unto me: I am the LORD.',	'இஸ்ரவேல் புத்திரர் எனக்கென்று நியமித்துச் செலுத்துகிற பரிசுத்த வஸ்துக்களைக்குறித்து ஆரோனும் அவன் குமாரரும் என் பரிசுத்த நாமத்தைப் பரிசுத்தக் குலைச்சலாக்காதபடிக்கு எச்சரிக்கையாய் இருக்கவேண்டும் என்று அவர்களோடே சொல்; நான் கர்த்தர்.',	3,	22,	2),
(3373,	'Say unto them, Whosoever he be of all your seed among your generations, that goeth unto the holy things, which the children of Israel hallow unto the LORD, having his uncleanness upon him, that soul shall be cut off from my presence: I am the LORD.',	'அன்றியும் நீ அவர்களை நோக்கி: உங்கள் தலைமுறைகளிலுள்ள சந்ததியாரில் எவனாகிலும் தான் தீட்டுப்பட்டிருக்கும்போது, இஸ்ரவேல் புத்திரர் கர்த்தருக்கு நியமித்துச் செலுத்துகிற பரிசுத்தமானவைகளண்டையில் சேர்ந்தால், அந்த ஆத்துமா என் சந்நிதியில் இராதபடிக்கு அறுப்புண்டுபோவான் என்று சொல்; நான் கர்த்தர்.',	3,	22,	3),
(3374,	'What man soever of the seed of Aaron is a leper, or hath a running issue; he shall not eat of the holy things, until he be clean. And whoso toucheth any thing that is unclean by the dead, or a man whose seed goeth from him;',	'ஆரோனின் சந்ததியாரில் எவன் குஷ்டரோகியோ, எவன் பிரமியமுள்ளவனோ, அவன் சுத்தமாகும்மட்டும் பரிசுத்தமானவைகளில் புசிக்கலாகாது; பிணத்தினாலே தீட்டானவைகளில் எதையாகிலும் தொட்டவனும், இந்திரியங்கழிந்தவனும்,',	3,	22,	4),
(3375,	'Or whosoever toucheth any creeping thing, whereby he may be made unclean, or a man of whom he may take uncleanness, whatsoever uncleanness he hath;',	'தீட்டுப்படுத்துகிற யாதொரு ஊரும் பிராணியையாகிலும் தீட்டுள்ள மனிதனையாகிலும் தொட்டவனும்,',	3,	22,	5),
(3376,	'The soul which hath touched any such shall be unclean until even, and shall not eat of the holy things, unless he wash his flesh with water.',	'சாயங்காலம்மட்டும் தீட்டுப்பட்டிருப்பான்; அவன் ஜலத்தில் ஸ்நானம்பண்ணும்வரைக்கும் பரிசுத்தமானவைகளில் புசிக்கலாகாது.',	3,	22,	6),
(3377,	'And when the sun is down, he shall be clean, and shall afterward eat of the holy things; because it is his food.',	'சூரியன் அஸ்தமித்தபின்பு சுத்தமாயிருப்பான்; அதன்பின்பு அவன் பரிசுத்தமானவைகளில் புசிக்கலாம்; அது அவனுடைய ஆகாரம்.',	3,	22,	7),
(3378,	'That which dieth of itself, or is torn with beasts, he shall not eat to defile himself therewith; I am the LORD.',	'தானாய்ச் செத்ததையும் பீறுண்டதையும் அவன் புசிக்கிறதினாலே தன்னைத் தீட்டுப்படுத்தலாகாது; நான் கர்த்தர்.',	3,	22,	8),
(3379,	'They shall therefore keep mine ordinance, lest they bear sin for it, and die therefore, if they profane it: I the LORD do sanctify them.',	'ஆகையால் பரிசுத்தமானதை அவர்கள் பரிசுத்தக்குலைச்சலாக்குகிறதினாலே, பாவம் சுமந்து அதினிமித்தம் சாகாதபடிக்கு, என் கட்டளையைக் காக்கக்கடவர்கள்; நான் அவர்களைப் பரிசுத்தமாக்குகிற கர்த்தர்.',	3,	22,	9),
(3380,	'There shall no stranger eat of the holy thing: a sojourner of the priest, or an hired servant, shall not eat of the holy thing.',	'அந்நியன் ஒருவனும் பரிசுத்தமானவைகளில் புசிக்கலாகாது; ஆசாரியன் வீட்டில் தங்கியிருக்கிறவனும் கூலிவேலை செய்கிறவனும் பரிசுத்தமானதில் புசிக்கலாகாது.',	3,	22,	10),
(3381,	'But if the priest buy any soul with his money, he shall eat of it, and he that is born in his house: they shall eat of his meat.',	'ஆசாரியனால் பணத்துக்குக் கொள்ளப்பட்டவனும், அவன் வீட்டிலே பிறந்தவனும் அவனுடைய ஆகாரத்தில் புசிக்கலாம்.',	3,	22,	11),
(3382,	'If the priest\'s daughter also be married unto a stranger, she may not eat of an offering of the holy things.',	'ஆசாரியனுடைய குமாரத்தி அந்நியனுக்கு வாழ்க்கைப்பட்டால், அவள் பரிசுத்தமானவைகளின் படைப்பிலே புசிக்கலாகாது.',	3,	22,	12),
(3383,	'But if the priest\'s daughter be a widow, or divorced, and have no child, and is returned unto her father\'s house, as in her youth, she shall eat of her father\'s meat: but there shall be no stranger eat thereof.',	'விதவையாய்ப்போன, அல்லது தள்ளப்பட்டவளான ஆசாரியனுடைய குமாரத்தி பிள்ளையில்லாதிருந்து, தன் தகப்பன் வீட்டில் தன்னுடைய இளவயதில் இருந்ததுபோல திரும்பவந்து இருந்தாளேயாகில், அவள் தன் தகப்பன் ஆகாரத்தில் புசிக்கலாம்; அந்நியனாகிய ஒருவனும் அதில் புசிக்கலாகாது.',	3,	22,	13),
(3384,	'And if a man eat of the holy thing unwittingly, then he shall put the fifth part thereof unto it, and shall give it unto the priest with the holy thing.',	'ஒருவன் அறியாமல் பரிசுத்தமானதில் புசித்ததுண்டானால், அவன் அதிலே ஐந்தில் ஒரு பங்கு அதிகமாய்க் கூட்டி பரிசுத்தமானவைகளோடுங்கூட ஆசாரியனுக்குக் கொடுக்கக்கடவன்.',	3,	22,	14),
(3385,	'And they shall not profane the holy things of the children of Israel, which they offer unto the LORD;',	'அவர்கள் கர்த்தருக்குப் படைக்கிற இஸ்ரவேல் புத்திரருடைய பரிசுத்தமானவைகளைப் பரிசுத்தக்குலைச்சலாக்காமலும்,',	3,	22,	15),
(3386,	'Or suffer them to bear the iniquity of trespass, when they eat their holy things: for I the LORD do sanctify them.',	'அவைகளைப் புசிக்கிறதினால் அவர்கள்மேல் குற்றமான அக்கிரமத்தைச் சுமரப்பண்ணாமலும் இருப்பார்களாக; நான் அவர்களைப் பரிசுத்தமாக்குகிற கர்த்தர் என்று சொல் என்றார்.',	3,	22,	16),
(3387,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	22,	17),
(3388,	'Speak unto Aaron, and to his sons, and unto all the children of Israel, and say unto them, Whatsoever he be of the house of Israel, or of the strangers in Israel, that will offer his oblation for all his vows, and for all his freewill offerings, which they will offer unto the LORD for a burnt offering;',	'நீ ஆரோனோடும் அவன் குமாரரோடும் இஸ்ரவேல் புத்திரர் அனைவரோடும் சொல்லவேண்டியது என்னவென்றால்: இஸ்ரவேல் குடும்பத்தாரிலும் இஸ்ரவேலில் தங்குகிற அந்நியர்களிலும் தங்களுடைய பொருத்தனைகளின்படியாகிலும் உற்சாகத்தின்படியாகிலும் சர்வாங்க தகனபலிகளாகக் கர்த்தருக்குத் தங்கள் காணிக்கையை எவர்கள் செலுத்தப்போகிறார்களோ,',	3,	22,	18),
(3389,	'Ye shall offer at your own will a male without blemish, of the beeves, of the sheep, or of the goats.',	'அவர்கள் தங்கள் மனதின்படியே மாடுகளிலாகிலும் ஆடுகளிலாகிலும் வெள்ளாடுகளிலாகிலும் பழுதற்ற ஒரு ஆணைப் பிடித்துவந்து செலுத்துவார்களாக.',	3,	22,	19),
(3390,	'But whatsoever hath a blemish, that shall ye not offer: for it shall not be acceptable for you.',	'பழுதுள்ள ஒன்றையும் செலுத்தவேண்டாம்; அது உங்கள்நிமித்தம் அங்கிகரிக்கப்படுவதில்லை.',	3,	22,	20),
(3391,	'And whosoever offereth a sacrifice of peace offerings unto the LORD to accomplish his vow, or a freewill offering in beeves or sheep, it shall be perfect to be accepted; there shall be no blemish therein.',	'ஒருவன் விசேஷித்த பொருத்தனையாயாவது, உற்சாகமாயாவது, கர்த்தருக்கு மாடுகளிலாகிலும் ஆடுகளிலாகிலும் சமாதானபலிகளைச் செலுத்தப்போனால், அது அங்கிகரிக்கப்படும்படி, ஒரு பழுதுமில்லாமல் உத்தமமாயிருக்கவேண்டும்.',	3,	22,	21),
(3392,	'Blind, or broken, or maimed, or having a wen, or scurvy, or scabbed, ye shall not offer these unto the LORD, nor make an offering by fire of them upon the altar unto the LORD.',	'குருடு, நெரிசல், முடம், கழலை, சொறி, புண் முதலிய பழுதுள்ளவைகளை நீங்கள் கர்த்தருக்குச் செலுத்தாமலும், அவைகளாலே கர்த்தருக்குப் பலிபீடத்தின்மேல் தகனபலியிடாமலும் இருப்பீர்களாக.',	3,	22,	22),
(3393,	'Either a bullock or a lamb that hath any thing superfluous or lacking in his parts, that mayest thou offer for a freewill offering; but for a vow it shall not be accepted.',	'நீண்ட அல்லது குறுகின அவயவமுள்ள மாட்டையும் ஆட்டையும் நீ உற்சாகபலியாக இடலாம்; பொருத்தனைக்காக அது அங்கிகரிக்கப்படமாட்டாது.',	3,	22,	23),
(3394,	'Ye shall not offer unto the LORD that which is bruised, or crushed, or broken, or cut; neither shall ye make any offering thereof in your land.',	'விதை நசுங்கினதையும் நொறுங்கினதையும் காயம்பட்டதையும் விதை அறுக்கப்பட்டதையும் நீங்கள் கர்த்தருக்குச் செலுத்தாமலும், அவைகளை உங்கள் தேசத்தில் பலியிடாமலும் இருப்பீர்களாக.',	3,	22,	24),
(3395,	'Neither from a stranger\'s hand shall ye offer the bread of your God of any of these; because their corruption is in them, and blemishes be in them: they shall not be accepted for you.',	'அந்நிய புத்திரன் கையிலும் இப்படிப்பட்டதை வாங்கி, தேவனுக்கு அப்பமாகச் செலுத்தீர்களாக; அவைகளின் கேடும் பழுதும் அவைகளில் இருக்கிறது; அவைகள் உங்களுக்காக அங்கிகரிக்கப்படுவதில்லை என்று சொல் என்றார்.',	3,	22,	25),
(3396,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	22,	26),
(3397,	'When a bullock, or a sheep, or a goat, is brought forth, then it shall be seven days under the dam; and from the eighth day and thenceforth it shall be accepted for an offering made by fire unto the LORD.',	'ஒரு கன்றாவது செம்மறியாட்டுக்குட்டியாவது வெள்ளாட்டுக்குட்டியாவது பிறந்தால், அது ஏழுநாள் தன் தாயினிடத்தில் இருக்கக்கடவது; எட்டாம் நாள் முதல் அது கர்த்தருக்குத் தகனபலியாக அங்கிகரிக்கப்படும்.',	3,	22,	27),
(3398,	'And whether it be cow, or ewe, ye shall not kill it and her young both in one day.',	'பசுவையும் அதின் கன்றையும், ஆட்டையும் அதின் குட்டியையும் ஒரே நாளில் கொல்லவேண்டாம்.',	3,	22,	28),
(3399,	'And when ye will offer a sacrifice of thanksgiving unto the LORD, offer it at your own will.',	'கர்த்தருக்கு ஸ்தோத்திரபலியைச் செலுத்துவீர்களானால் மனப்பூர்வமாய் அதைச் செலுத்துவீர்களாக.',	3,	22,	29),
(3400,	'On the same day it shall be eaten up; ye shall leave none of it until the morrow: I am the LORD.',	'அந்நாளிலேதான் அது புசிக்கப்படவேண்டும்; விடியற்காலம்மட்டும் நீங்கள் அதில் ஒன்றும் மீதியாக வைக்கவேண்டாம்; நான் கர்த்தர்.',	3,	22,	30),
(3401,	'Therefore shall ye keep my commandments, and do them: I am the LORD.',	'நீங்கள் என் கட்டளைகளைக் கைக்கொண்டு, அவைகளின்படி செய்யக்கடவீர்கள்; நான் கர்த்தர்.',	3,	22,	31),
(3402,	'Neither shall ye profane my holy name; but I will be hallowed among the children of Israel: I am the LORD which hallow you,',	'என் பரிசுத்த நாமத்தைப் பரிசுத்தக்குலைச்சலாக்காதிருப்பீர்களாக; நான் இஸ்ரவேல் புத்திரர் நடுவே பரிசுத்தர் என்று மதிக்கப்படுவேன்; நான் உங்களைப் பரிசுத்தமாக்குகிற கர்த்தர்.',	3,	22,	32),
(3403,	'That brought you out of the land of Egypt, to be your God: I am the LORD.',	'நான் உங்களுக்கு தேவனாயிருப்பதற்காக, உங்களை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணினேன்; நான் கர்த்தர் என்று சொல் என்றார்.  ',	3,	22,	33),
(3404,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	23,	1),
(3405,	'Speak unto the children of Israel, and say unto them, Concerning the feasts of the LORD, which ye shall proclaim to be holy convocations, even these are my feasts.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: சபைகூடி வந்து பரிசுத்த நாட்களாக ஆசரிக்கும்படி, நீங்கள் கூறவேண்டிய கர்த்தருடைய பண்டிகை நாட்களாவன:',	3,	23,	2),
(3406,	'Six days shall work be done: but the seventh day is the sabbath of rest, an holy convocation; ye shall do no work therein: it is the sabbath of the LORD in all your dwellings.',	'ஆறுநாளும் வேலைசெய்யவேண்டும்; ஏழாம்நாள் பரிசுத்த சபைகூடுதலான ஓய்வுநாள், அதில் ஒரு வேலையும் செய்யவேண்டாம்; அது உங்கள் வாசஸ்தலங்களிலெல்லாம் கர்த்தருக்கென்று ஓய்ந்திருக்கும் நாளாயிருப்பதாக.',	3,	23,	3),
(3407,	'These are the feasts of the LORD, even holy convocations, which ye shall proclaim in their seasons.',	'சபைகூடிவந்து பரிசுத்தமாய் ஆசரிக்கும்படி, நீங்கள் குறித்தகாலத்தில் கூறவேண்டிய கர்த்தரின் பண்டிகைகளாவன:',	3,	23,	4),
(3408,	'In the fourteenth day of the first month at even is the LORD\'s passover.',	'முதலாம் மாதம் பதினாலாம் தேதி அந்திநேரமாகிய வேளையிலே கர்த்தரின் பஸ்கா பண்டிகையும்,',	3,	23,	5),
(3409,	'And on the fifteenth day of the same month is the feast of unleavened bread unto the LORD: seven days ye must eat unleavened bread.',	'அந்த மாதம் பதினைந்தாம் தேதியிலே, கர்த்தருக்குப் புளிப்பில்லா அப்பப்பண்டிகையுமாய் இருக்கும்; ஏழுநாள் புளிப்பில்லா அப்பங்களைப் புசிக்கவேண்டும்.',	3,	23,	6),
(3410,	'In the first day ye shall have an holy convocation: ye shall do no servile work therein.',	'முதலாம் நாள் உங்களுக்குப் பரிசுத்தமான சபைகூடுதல்; அதிலே சாதாரணமான யாதொரு வேலையும் செய்யவேண்டாம்.',	3,	23,	7),
(3411,	'But ye shall offer an offering made by fire unto the LORD seven days: in the seventh day is an holy convocation: ye shall do no servile work therein.',	'ஏழுநாளும் கர்த்தருக்குத் தகனபலியிடவேண்டும்; ஏழாம்நாள் பரிசுத்தமான சபைகூடுதல்; அதில் சாதாரணமான யாதொரு வேலையும் செய்யலாகாது என்று சொல் என்றார்.',	3,	23,	8),
(3412,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	23,	9),
(3413,	'Speak unto the children of Israel, and say unto them, When ye be come into the land which I give unto you, and shall reap the harvest thereof, then ye shall bring a sheaf of the firstfruits of your harvest unto the priest:',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நான் உங்களுக்குக் கொடுக்கும் தேசத்தில் நீங்கள் போய்ச் சேர்ந்து, அதின் வெள்ளாண்மையை அறுக்கும்போது, உங்கள் அறுப்பின் முதற்பலனாகிய ஒரு கதிர்க்கட்டை ஆசாரியனிடத்தில் கொண்டுவரக்கடவீர்கள்.',	3,	23,	10),
(3414,	'And he shall wave the sheaf before the LORD, to be accepted for you: on the morrow after the sabbath the priest shall wave it.',	'உங்களுக்காக அது அங்கிகரிக்கப்படும்படி, ஆசாரியன் அந்தக்கதிர்க்கட்டை ஓய்வுநாளுக்கு மறுநாளில் கர்த்தருடைய சந்நிதியில் அசைவாட்டவேண்டும்.',	3,	23,	11),
(3415,	'And ye shall offer that day when ye wave the sheaf an he lamb without blemish of the first year for a burnt offering unto the LORD.',	'நீங்கள் அந்தக் கதிர்க்கட்டை அசைவாட்டும் நாளில் கர்த்தருக்குச் சர்வாங்க தகனபலியாக ஒருவயதான பழுதற்ற ஒரு ஆட்டுக்குட்டியையும்,',	3,	23,	12),
(3416,	'And the meat offering thereof shall be two tenth deals of fine flour mingled with oil, an offering made by fire unto the LORD for a sweet savour: and the drink offering thereof shall be of wine, the fourth part of an hin.',	'கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாக ஒரு மரக்காலிலே பத்தில் இரண்டு பங்கானதும் எண்ணெயிலே பிசைந்ததுமான மெல்லிய மாவாகிய போஜனபலியையும், திராட்சப்பழரசத்திலே காற்படியாகிய பானபலியையும் செலுத்தக்கடவீர்கள்.',	3,	23,	13),
(3417,	'And ye shall eat neither bread, nor parched corn, nor green ears, until the selfsame day that ye have brought an offering unto your God: it shall be a statute for ever throughout your generations in all your dwellings.',	'உங்கள் தேவனுக்குக் காணிக்கையை நீங்கள் கொண்டுவரும் அந்நாள் மட்டும், அப்பமும் வாட்டிய கதிரும் பச்சைக்கதிரும் புசியீர்களாக; இது உங்கள் வாசஸ்தலங்களிலெல்லாம் உங்கள் தலைமுறைதோறும் செல்லவேண்டிய நித்திய கட்டளை.',	3,	23,	14),
(3418,	'And ye shall count unto you from the morrow after the sabbath, from the day that ye brought the sheaf of the wave offering; seven sabbaths shall be complete:',	'நீங்கள் அசைவாட்டும் கதிர்க்கட்டைக் கொண்டுவரும் ஓய்வுநாளுக்கு மறுநாள் முதற்கொண்டு எண்ணத்துவக்கி, ஏழுவாரங்கள் நிறைவேறினபின்பு,',	3,	23,	15),
(3419,	'Even unto the morrow after the seventh sabbath shall ye number fifty days; and ye shall offer a new meat offering unto the LORD.',	'ஏழாம் ஓய்வுநாளுக்கு மறுநாளாகிய ஐம்பதாம் நாள்மட்டும் எண்ணி, கர்த்தருக்குப் புதிய போஜனபலியைச் செலுத்தக்கடவீர்கள்.',	3,	23,	16),
(3420,	'Ye shall bring out of your habitations two wave loaves of two tenth deals; they shall be of fine flour; they shall be baken with leaven; they are the firstfruits unto the LORD.',	'நீங்கள் ஒரு மரக்காலிலே பத்தில் இரண்டு பங்காகிய மெல்லிய மாவிலே புளிப்பாகப் பாகம்பண்ணப்பட்ட அசைவாட்டும் காணிக்கையாயிருக்கிற இரண்டு அப்பங்களை உங்கள் வாசஸ்தலங்களிலிருந்து கர்த்தருக்கென்று முதற்பலனாகக் கொண்டுவந்து,',	3,	23,	17),
(3421,	'And ye shall offer with the bread seven lambs without blemish of the first year, and one young bullock, and two rams: they shall be for a burnt offering unto the LORD, with their meat offering, and their drink offerings, even an offering made by fire, of sweet savour unto the LORD.',	'அப்பத்தோடேகூடக் கர்த்தருக்குச் சர்வாங்கதகனபலியாக, ஒருவயதான பழுதற்ற ஏழு ஆட்டுக்குட்டிகளையும், ஒரு காளையையும், இரண்டு ஆட்டுக்கடாக்களையும், கர்த்தருக்குச் சுகந்த வாசனையான தகனபலியாக அவைகளுக்கு அடுத்த போஜனபலியையும், பானபலியையும் செலுத்தி,',	3,	23,	18),
(3422,	'Then ye shall sacrifice one kid of the goats for a sin offering, and two lambs of the first year for a sacrifice of peace offerings.',	'வெள்ளாடுகளில் ஒரு கடாவைப் பாவநிவாரணபலியாகவும், ஒருவயதான இரண்டு ஆட்டுக்குட்டிகளைச் சமாதானபலியாகவும் இடக்கடவீர்கள்.',	3,	23,	19),
(3423,	'And the priest shall wave them with the bread of the firstfruits for a wave offering before the LORD, with the two lambs: they shall be holy to the LORD for the priest.',	'அவைகளை ஆசாரியன் முதற்பலனாகிய அப்பத்தோடும் இரண்டு ஆட்டுக்குட்டிகளோடுங்கூட கர்த்தருடைய சந்நிதியில் அசைவாட்டும் பலியாக அசைவாட்டக்கடவன்; கர்த்தருக்குப் பரிசுத்தமாகிய அவைகள் ஆசாரியனுடையவைகளாகும்.',	3,	23,	20),
(3424,	'And ye shall proclaim on the selfsame day, that it may be an holy convocation unto you: ye shall do no servile work therein: it shall be a statute for ever in all your dwellings throughout your generations.',	'அந்த நாள் உங்களுக்குச் சபைகூடும் பரிசுத்த நாள் என்று கூறவேண்டும்; அதிலே சாதாரணமான யாதொரு வேலையும் செய்யலாகாது; இது உங்கள் வாசஸ்தலங்களிலெல்லாம் உங்கள் தலைமுறைதோறும் செல்லவேண்டிய நித்திய கட்டளை.',	3,	23,	21),
(3425,	'And when ye reap the harvest of your land, thou shalt not make clean riddance of the corners of thy field when thou reapest, neither shalt thou gather any gleaning of thy harvest: thou shalt leave them unto the poor, and to the stranger: I am the LORD your God.',	'உங்கள் தேசத்தின் வெள்ளாண்மையை நீங்கள் அறுக்கையில், வயலின் ஓரத்தில் இருக்கிறதை முற்றிலும் அறுக்காமலும், சிந்திக்கிடக்கிற கதிர்களைப் பொறுக்காமலும், எளியவனுக்கும் பரதேசிக்கும் அவைகளை விட்டுவிடவேண்டும்; நான் உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.',	3,	23,	22),
(3426,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	23,	23),
(3427,	'Speak unto the children of Israel, saying, In the seventh month, in the first day of the month, shall ye have a sabbath, a memorial of blowing of trumpets, an holy convocation.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: உங்களுக்கு ஏழாம் மாதம் முதலாந்தேதி எக்காளச்சத்தத்தால் ஞாபக்குறியாகக் கொண்டாடுகிற பண்டிகை என்கிற சபை கூடும் பரிசுத்த ஓய்வுநாளாய் இருப்பதாக.',	3,	23,	24),
(3428,	'Ye shall do no servile work therein: but ye shall offer an offering made by fire unto the LORD.',	'அதிலே சாதாரணமான யாதொரு வேலையும் செய்யாமல், கர்த்தருக்குத் தகனபலி செலுத்தவேண்டும் என்று சொல் என்றார்.',	3,	23,	25),
(3429,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	23,	26),
(3430,	'Also on the tenth day of this seventh month there shall be a day of atonement: it shall be an holy convocation unto you; and ye shall afflict your souls, and offer an offering made by fire unto the LORD.',	'அந்த ஏழாம் மாதம் பத்தாந்தேதி உங்களுக்குப் பாவநிவிர்த்தி செய்யும் நாளும் சபைகூடும் பரிசுத்தநாளுமாயிருப்பதாக; அப்பொழுது நீங்கள் உங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்தி, கர்த்தருக்குத் தகனபலி செலுத்தக்கடவீர்கள்.',	3,	23,	27),
(3431,	'And ye shall do no work in that same day: for it is a day of atonement, to make an atonement for you before the LORD your God.',	'அந்த நாள் உங்கள் தேவனாகிய கர்த்தருடைய சந்நிதியில் உங்களுக்காகப் பாவநிவிர்த்தி செய்யப்படும் பாவநிவாரண நாளாயிருக்கிறபடியால், அதிலே யாதொரு வேலையும் செய்யவேண்டாம்.',	3,	23,	28),
(3432,	'For whatsoever soul it be that shall not be afflicted in that same day, he shall be cut off from among his people.',	'அந்நாளிலே தன்னைத் தாழ்மைப்படுத்தாத எந்த ஆத்துமாவும் தன் ஜனத்தில் இராதபடிக்கு அறுப்புண்டுபோவான்.',	3,	23,	29),
(3433,	'And whatsoever soul it be that doeth any work in that same day, the same soul will I destroy from among his people.',	'அந்நாளிலே ஒரு ஆத்துமா யாதொரு வேலையைச் செய்தால், அந்த ஆத்துமாவை அவன் ஜனத்தின் நடுவிலே வைக்காமல் அழிப்பேன்.',	3,	23,	30),
(3434,	'Ye shall do no manner of work: it shall be a statute for ever throughout your generations in all your dwellings.',	'அதில் நீங்கள் எந்த வேலையும் செய்யாதிருப்பது உங்கள் வாசஸ்தலங்களிலெல்லாம் உங்கள் தலைமுறைதோறும் செல்லவேண்டிய நித்தியகட்டளை.',	3,	23,	31),
(3435,	'It shall be unto you a sabbath of rest, and ye shall afflict your souls: in the ninth day of the month at even, from even unto even, shall ye celebrate your sabbath.',	'அது உங்களுக்கு விசேஷித்த ஓய்வு நாள்; அதில் உங்கள் ஆத்துமாக்களைத் தாழ்மைப்படுத்தவேண்டும்; அந்த மாதத்தின் ஒன்பதாந்தேதி சாயங்காலம் துவக்கி, மறுநாள் சாயங்காலம்மட்டும் உங்கள் ஓய்வை ஆசரிக்கக்கடவீர்கள் என்றார்.',	3,	23,	32),
(3436,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	23,	33),
(3437,	'Speak unto the children of Israel, saying, The fifteenth day of this seventh month shall be the feast of tabernacles for seven days unto the LORD.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: அந்த ஏழாம் மாதம் பதினைந்தாந்தேதிமுதல் ஏழுநாளளவும் கர்த்தருக்கு ஆசரிக்கும் கூடாரப்பண்டிகையாயிருப்பதாக.',	3,	23,	34),
(3438,	'On the first day shall be an holy convocation: ye shall do no servile work therein.',	'முதலாம் நாள் சபைகூடும் பரிசுத்தநாள்; அதிலே சாதாரணமான யாதொரு வேலையும் செய்யலாகாது.',	3,	23,	35),
(3439,	'Seven days ye shall offer an offering made by fire unto the LORD: on the eighth day shall be an holy convocation unto you; and ye shall offer an offering made by fire unto the LORD: it is a solemn assembly; and ye shall do no servile work therein.',	'ஏழுநாளும் கர்த்தருக்குத் தகனபலி செலுத்தக்கடவீர்கள்; எட்டாம் நாள் உங்களுக்குச் சபைகூடும் பரிசுத்தநாள்; அதிலே கர்த்தருக்குத் தகனபலி செலுத்தக்கடவீர்கள்; அது ஆசரிக்கப்படும் நாள்; அதிலே சாதாரணமான யாதொரு வேலையும் செய்யவேண்டாம்.',	3,	23,	36),
(3440,	'These are the feasts of the LORD, which ye shall proclaim to be holy convocations, to offer an offering made by fire unto the LORD, a burnt offering, and a meat offering, a sacrifice, and drink offerings, every thing upon his day:',	'நீங்கள் கர்த்தருடைய ஓய்வுநாட்களில் செலுத்துவதும் தவிர, நீங்கள் கர்த்தருக்குப் படைக்கிற உங்கள் எல்லாக் காணிக்கைகளும் பொருத்தனைகளும் உற்சாகபலிகளும் தவிர,',	3,	23,	37),
(3441,	'Beside the sabbaths of the LORD, and beside your gifts, and beside all your vows, and beside all your freewill offerings, which ye give unto the LORD.',	'நீங்கள் அந்தந்த நாளுக்குத்தக்கதாய்க் கர்த்தருக்குச் சர்வாங்க தகனபலி, போஜனபலி, இரத்தபலி, பானபலி முதலானவைகளைச் செலுத்தும்படி சபைகூடி வந்து, பரிசுத்தமாய் ஆசரிப்பதற்காக நீங்கள் கூறவேண்டிய கர்த்தருடைய பண்டிகைகள் இவைகளே.',	3,	23,	38),
(3442,	'Also in the fifteenth day of the seventh month, when ye have gathered in the fruit of the land, ye shall keep a feast unto the LORD seven days: on the first day shall be a sabbath, and on the eighth day shall be a sabbath.',	'நிலத்தின் பலனை நீங்கள் சேர்த்து வைக்கும் ஏழாம் மாதம் பதினைந்தாந்தேதிமுதல் கர்த்தருக்குப் பண்டிகையை ஏழுநாள் ஆசரிக்கக்கடவீர்கள்; முதலாம் நாளிலும் ஓய்வு; எட்டாம் நாளிலும் ஓய்வு.',	3,	23,	39),
(3443,	'And ye shall take you on the first day the boughs of goodly trees, branches of palm trees, and the boughs of thick trees, and willows of the brook; and ye shall rejoice before the LORD your God seven days.',	'முதல் நாளிலே அலங்காரமான விருட்சங்களின் கனிகளையும் பேரீச்சின் ஓலைகளையும் தழைத்திருக்கிற விருட்சங்களின் கிளைகளையும் ஆற்றலரிகளையும் கொண்டுவந்து, உங்கள் தேவனாகிய கர்த்தருடைய சந்நிதியில் ஏழுநாளும் மகிழ்ச்சியாயிருங்கள்.',	3,	23,	40),
(3444,	'And ye shall keep it a feast unto the LORD seven days in the year. It shall be a statute for ever in your generations: ye shall celebrate it in the seventh month.',	'வருஷந்தோறும் ஏழுநாள் கர்த்தருக்கு இந்தப் பண்டிகையை ஆசரிக்கக்கடவீர்கள்; இது உங்கள் தலைமுறைதோறும் செல்லவேண்டிய நித்திய கட்டளை; ஏழாம் மாதத்தில் அதை ஆசரிக்கவேண்டும்.',	3,	23,	41),
(3445,	'Ye shall dwell in booths seven days; all that are Israelites born shall dwell in booths:',	'நான் இஸ்ரவேல் புத்திரரை எகிப்து தேசத்திலிருந்து புறப்படப்பண்ணினபோது, அவர்களைக் கூடாரங்களில் குடியிருக்கப்பண்ணினதை உங்கள் சந்ததியார் அறியும்படிக்கு,',	3,	23,	42),
(3446,	'That your generations may know that I made the children of Israel to dwell in booths, when I brought them out of the land of Egypt: I am the LORD your God.',	'ஏழுநாள் கூடாரங்களில் குடியிருக்கக்கடவீர்கள்; இஸ்ரவேலில் பிறந்தவர்கள் எல்லாரும் கூடாரங்களில் வாசம்பண்ணவேண்டும்; நான் உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.',	3,	23,	43),
(3447,	'And Moses declared unto the children of Israel the feasts of the LORD.',	'அப்படியே மோசே கர்த்தருடைய பண்டிகைகளை இஸ்ரவேல் புத்திரருக்குத் தெரிவித்தான்.  ',	3,	23,	44),
(3448,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	24,	1),
(3449,	'Command the children of Israel, that they bring unto thee pure oil olive beaten for the light, to cause the lamps to burn continually.',	'குத்துவிளக்கு எப்பொழுதும் எரிந்துகொண்டிருக்கும்படி அதற்காக இடித்துப்பிழிந்த தெளிவான ஒலிவ எண்ணெயை இஸ்ரவேல் புத்திரர் உன்னிடத்தில் கொண்டுவரும்படி அவர்களுக்குக் கட்டளையிடு.',	3,	24,	2),
(3450,	'Without the vail of the testimony, in the tabernacle of the congregation, shall Aaron order it from the evening unto the morning before the LORD continually: it shall be a statute for ever in your generations.',	'ஆசரிப்புக் கூடாரத்தில் சாட்சிசந்நிதியின் திரைக்கு வெளிப்புறமாக ஆரோன் அதை எப்பொழுதும் சாயங்காலம் தொடங்கி விடியற்காலம்மட்டும் கர்த்தருடைய சந்நிதியில் எரியும்படி ஏற்றக்கடவன்; இது உங்கள் தலைமுறைதோறும் செல்லவேண்டிய நித்தியகட்டளை.',	3,	24,	3),
(3451,	'He shall order the lamps upon the pure candlestick before the LORD continually.',	'அவன் எப்பொழுதும் கர்த்தருடைய சந்நிதியில் பரிசுத்தமான குத்துவிளக்கின்மேல் இருக்கிற விளக்குகளை எரியவைக்கக்கடவன்.',	3,	24,	4),
(3452,	'And thou shalt take fine flour, and bake twelve cakes thereof: two tenth deals shall be in one cake.',	'அன்றியும் நீ மெல்லிய மாவை எடுத்து, அதைப் பன்னிரண்டு அப்பங்களாகச் சுடுவாயாக; ஒவ்வொரு அப்பம் மரக்காலிலே பத்தில் இரண்டுபங்கு மாவினால் செய்யப்படவேண்டும்.',	3,	24,	5),
(3453,	'And thou shalt set them in two rows, six on a row, upon the pure table before the LORD.',	'அவைகளை நீ கர்த்தருடைய சந்நிதியில் பரிசுத்தமான மேஜையின்மேல் இரண்டு அடுக்காக, ஒவ்வொரு அடுக்கில் அவ்வாறு அப்பம் இருக்கும்படியாக வைத்து,',	3,	24,	6),
(3454,	'And thou shalt put pure frankincense upon each row, that it may be on the bread for a memorial, even an offering made by fire unto the LORD.',	'ஒவ்வொரு அடுக்கினிடத்தில் சுத்தமான தூபவர்க்கம் போடக்கடவாய்; அது அப்பத்தோடிருந்து, ஞாபகக்குறியாகக் கர்த்தருக்கேற்ற தகனபலியாயிருக்கும்.',	3,	24,	7),
(3455,	'Every sabbath he shall set it in order before the LORD continually, being taken from the children of Israel by an everlasting covenant.',	'அப்பத்தை நித்திய உடன்படிக்கையாக இஸ்ரவேல் புத்திரர் கையிலே வாங்கி, ஓய்வுநாள்தோறும் கர்த்தருடைய சந்நிதியில் அடுக்கிவைக்கக்கடவன்.',	3,	24,	8),
(3456,	'And it shall be Aaron\'s and his sons\'; and they shall eat it in the holy place: for it is most holy unto him of the offerings of the LORD made by fire by a perpetual statute.',	'அது ஆரோனையும் அவன் குமாரரையும் சேரும்; அதைப் பரிசுத்த இடத்திலே புசிக்கக்கடவர்கள்; நித்தியகட்டளையாக கர்த்தருக்கு இடப்படும் தகனபலிகளில் அது அவனுக்கு மகா பரிசுத்தமாயிருக்கும் என்றார்.',	3,	24,	9),
(3457,	'And the son of an Israelitish woman, whose father was an Egyptian, went out among the children of Israel: and this son of the Israelitish woman and a man of Israel strove together in the camp;',	'அக்காலத்திலே இஸ்ரவேல் ஜாதியான ஸ்திரீக்கும் எகிப்திய புருஷனுக்கும் பிறந்த புத்திரனாகிய ஒருவன் இஸ்ரவேல் புத்திரரோடேகூடப் புறப்பட்டு வந்திருந்தான்; இவனும் இஸ்ரவேலனாகிய ஒரு மனிதனும் பாளயத்திலே சண்டைபண்ணினார்கள்.',	3,	24,	10),
(3458,	'And the Israelitish woman\'s son blasphemed the name of the Lord, and cursed. And they brought him unto Moses: (and his mother\'s name was Shelomith, the daughter of Dibri, of the tribe of Dan:)',	'அப்பொழுது இஸ்ரவேல் ஜாதியான அந்த ஸ்திரீயின் மகன் கர்த்தரின் நாமத்தை நிந்தித்துத் தூஷித்தான். அவனை மோசேயினிடத்தில் கொண்டுவந்தார்கள். அவன் தாயின் பேர் செலோமித்; அவள் தாண் கோத்திரத்தானாகிய திப்ரியின் குமாரத்தி.',	3,	24,	11),
(3459,	'And they put him in ward, that the mind of the LORD might be shewed them.',	'கர்த்தரின் வாக்கினாலே தங்களுக்கு உத்தரவு வருமட்டும், அவனைக் காவல்படுத்தினார்கள்.',	3,	24,	12),
(3460,	'And the LORD spake unto Moses, saying,',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி:',	3,	24,	13),
(3461,	'Bring forth him that hath cursed without the camp; and let all that heard him lay their hands upon his head, and let all the congregation stone him.',	'தூஷித்தவனைப் பாளயத்துக்குப் புறம்பே கொண்டுபோ; கேட்டவர்கள் எல்லாரும் தங்கள் கைகளை அவன் தலையின்மேல் வைப்பார்களாக; பின்பு சபையார் எல்லாரும் அவனைக் கல்லெறியக்கடவர்கள்.',	3,	24,	14),
(3462,	'And thou shalt speak unto the children of Israel, saying, Whosoever curseth his God shall bear his sin.',	'மேலும் நீ இஸ்ரவேல் புத்திரரை நோக்கி: எவனாகிலும் தன் தேவனைத் தூஷித்தால், அவன் தன் பாவத்தைச் சுமப்பான்.',	3,	24,	15),
(3463,	'And he that blasphemeth the name of the LORD, he shall surely be put to death, and all the congregation shall certainly stone him: as well the stranger, as he that is born in the land, when he blasphemeth the name of the Lord, shall be put to death.',	'கர்த்தருடைய நாமத்தை நிந்திக்கிறவன் கொலைசெய்யப்படவேண்டும்; சபையார் எல்லாரும் அவனைக் கல்லெறியவேண்டும்; பரதேசியானாலும் சுதேசியானாலும் கர்த்தரின் நாமத்தைத் தூஷிக்கிறவன் கொலைசெய்யப்படவேண்டும்.',	3,	24,	16),
(3464,	'And he that killeth any man shall surely be put to death.',	'ஒரு மனிதனைக் கொல்லுகிறவன் எவனோ அவன் கொலைசெய்யப்படவேண்டும்.',	3,	24,	17),
(3465,	'And he that killeth a beast shall make it good; beast for beast.',	'மிருகத்தைக் கொன்றவன் மிருகத்துக்கு மிருகம் கொடுக்கக்கடவன்.',	3,	24,	18),
(3466,	'And if a man cause a blemish in his neighbour; as he hath done, so shall it be done to him;',	'ஒருவன் பிறனை ஊனப்படுத்தினால், அவன் செய்தபடியே அவனுக்கும் செய்யப்படக்கடவது.',	3,	24,	19),
(3467,	'Breach for breach, eye for eye, tooth for tooth: as he hath caused a blemish in a man, so shall it be done to him again.',	'நொறுக்குதலுக்கு நொறுக்குதல், கண்ணுக்குக் கண், பல்லுக்குப் பல்; அவன் ஒரு மனிதனை ஊனப்படுத்தினது போல அவனும் ஊனப்படுத்தப்படவேண்டும்.',	3,	24,	20),
(3468,	'And he that killeth a beast, he shall restore it: and he that killeth a man, he shall be put to death.',	'மிருகத்தைக் கொன்றவன் பதில் கொடுக்கவேண்டும்; மனிதனைக் கொன்றவனோ கொலைசெய்யப்படக்கடவன்.',	3,	24,	21),
(3469,	'Ye shall have one manner of law, as well for the stranger, as for one of your own country: for I am the LORD your God.',	'உங்களில் பரதேசிக்கும் சுதேசிக்கும் ஒரே நியாயம் இருக்கவேண்டும்; நான் உங்கள் தேவனாகிய கர்த்தர் என்று சொல் என்றார்.',	3,	24,	22),
(3470,	'And Moses spake to the children of Israel, that they should bring forth him that had cursed out of the camp, and stone him with stones. And the children of Israel did as the LORD commanded Moses.',	'அப்படியே, தூஷித்தவனைப் பாளயத்துக்குப் புறம்பே கொண்டுபோய், அவனைக் கல்லெறியும்படி மோசே இஸ்ரவேல் புத்திரரோடே சொன்னான்; கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே செய்தார்கள்.  ',	3,	24,	23),
(3471,	'And the LORD spake unto Moses in mount Sinai, saying,',	'கர்த்தர் சீனாய்மலையில் மோசேயை நோக்கி:',	3,	25,	1),
(3472,	'Speak unto the children of Israel, and say unto them, When ye come into the land which I give you, then shall the land keep a sabbath unto the LORD.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: நான் உங்களுக்குக் கொடுக்கும் தேசத்திலே நீங்கள் போய்ச் சேர்ந்திருக்கும்போது, தேசம் கர்த்தருக்கென்று ஓய்வு கொண்டாடவேண்டும்.',	3,	25,	2),
(3473,	'Six years thou shalt sow thy field, and six years thou shalt prune thy vineyard, and gather in the fruit thereof;',	'ஆறுவருஷம் உன் வயலை விதைத்து, உன் திராட்சத்தோட்டத்தைக் கிளைகழித்து, அதின் பலனைச் சேர்ப்பாயாக.',	3,	25,	3),
(3474,	'But in the seventh year shall be a sabbath of rest unto the land, a sabbath for the LORD: thou shalt neither sow thy field, nor prune thy vineyard.',	'ஏழாம் வருஷத்திலோ, கர்த்தருக்கென்று ஓய்ந்திருக்கும் ஓய்வு தேசத்திற்கு இருக்கவேண்டும்; அதில் உன் வயலை விதைக்காமலும், உன் திராட்சத்தோட்டத்தைக் கிளைகழிக்காமலும்,',	3,	25,	4),
(3475,	'That which groweth of its own accord of thy harvest thou shalt not reap, neither gather the grapes of thy vine undressed: for it is a year of rest unto the land.',	'தானாய் விளைந்து பயிரானதை அறுக்காமலும், கிளைகழிக்காதே விட்ட திராட்சச்செடியின் பழங்களைச் சேர்க்காமலும் இருப்பாயாக; தேசத்துக்கு அது ஓய்வு வருஷமாயிருக்கக்கடவது.',	3,	25,	5),
(3476,	'And the sabbath of the land shall be meat for you; for thee, and for thy servant, and for thy maid, and for thy hired servant, and for thy stranger that sojourneth with thee.',	'தேசத்தின் ஓய்விலே பயிராகிறது உங்களுக்கு ஆகாரமாயிருப்பதாக; உன் வேலைக்காரனுக்கும், உன் வேலைக்காரிக்கும், உன் கூலிக்காரனுக்கும், உன்னிடத்தில் தங்குகிற அந்நியனுக்கும்,',	3,	25,	6),
(3477,	'And for thy cattle, and for the beast that are in thy land, shall all the increase thereof be meat.',	'உன் நாட்டு மிருகத்துக்கும், உன் தேசத்தில் இருக்கிற காட்டு மிருகத்துக்கும் அதில் விளைந்திருப்பதெல்லாம் ஆகாரமாயிருப்பதாக.',	3,	25,	7),
(3478,	'And thou shalt number seven sabbaths of years unto thee, seven times seven years; and the space of the seven sabbaths of years shall be unto thee forty and nine years.',	'அன்றியும், ஏழு ஓய்வு வருஷங்களுள்ள ஏழு ஏழு வருஷங்களை எண்ணுவாயாக; அந்த ஏழு ஓய்வு வருஷங்களும் நாற்பத்தொன்பது வருஷமாகும்.',	3,	25,	8),
(3479,	'Then shalt thou cause the trumpet of the jubile to sound on the tenth day of the seventh month, in the day of atonement shall ye make the trumpet sound throughout all your land.',	'அப்பொழுதும் ஏழாம் மாதம் பத்தாந்தேதியில் எக்காளச்சத்தம் தொனிக்கும்படி செய்யவேண்டும்; பாவநிவாரணநாளில் உங்கள் தேசமெங்கும் எக்காளச்சத்தம் தொனிக்கும்படி செய்யவேண்டும்.',	3,	25,	9),
(3480,	'And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family.',	'ஐம்பதாம் வருஷத்தைப் பரிசுத்தமாக்கி, தேசமெங்கும் அதின் குடிகளுக்கெல்லாம் விடுதலை கூறக்கடவீர்கள்; அது உங்களுக்கு யூபிலி வருஷம்; அதிலே உங்களில் ஒவ்வொருவனும் தன்தன் காணியாட்சிக்கும் தன் தன் குடும்பத்துக்கும் திரும்பிப் போகக்கடவன்.',	3,	25,	10),
(3481,	'A jubile shall that fiftieth year be unto you: ye shall not sow, neither reap that which groweth of itself in it, nor gather the grapes in it of thy vine undressed.',	'அந்த ஐம்பதாம் வருஷம் உங்களுக்கு யூபிலி வருஷமாயிருப்பதாக; அதிலே விதைக்காமலும், தானாய் விளைந்து பயிரானதை அறுக்காமலும், கிளைகழிக்காமல் விடப்பட்ட திராட்சச்செடியின் பழங்களைச் சேர்க்காமலும் இருப்பீர்களாக.',	3,	25,	11),
(3482,	'For it is the jubile; it shall be holy unto you: ye shall eat the increase thereof out of the field.',	'அது யூபிலி வருஷம்; அது உங்களுக்குப் பரிசுத்தமாயிருக்கவேண்டும்; அந்த வருஷத்தில் வயல்வெளியில் விளைந்தவைகளை நீங்கள் புசிக்கவேண்டும்.',	3,	25,	12),
(3483,	'In the year of this jubile ye shall return every man unto his possession.',	'அந்த யூபிலி வருஷத்தில் உங்களில் அவனவன் தன்தன் காணியாட்சிக்குத் திரும்பிப்போகக்கடவன்.',	3,	25,	13),
(3484,	'And if thou sell ought unto thy neighbour, or buyest ought of thy neighbour\'s hand, ye shall not oppress one another:',	'ஆகையால், பிறனுக்கு எதையாவது விற்றாலும், அவனிடத்தில் எதையாவது கொண்டாலும் ஒருவருக்கொருவர் அநியாயம் செய்யக்கூடாது.',	3,	25,	14),
(3485,	'According to the number of years after the jubile thou shalt buy of thy neighbour, and according unto the number of years of the fruits he shall sell unto thee:',	'யூபிலி வருஷத்துக்குப் பின்வரும் வருஷங்களின் தொகைக்கேற்கப் பிறனிடத்தில் கொள்ளுவாயாக; பலனுள்ள வருஷங்களின் தொகைக்கேற்க அவன் உனக்கு விற்பானாக.',	3,	25,	15),
(3486,	'According to the multitude of years thou shalt increase the price thereof, and according to the fewness of years thou shalt diminish the price of it: for according to the number of the years of the fruits doth he sell unto thee.',	'பலனுள்ள வருஷங்களின் இலக்கத்தைப் பார்த்து அவன் உனக்கு விற்கிறபடியால், வருஷங்களின் தொகை ஏறினால் விலையேறவும், வருஷங்களின் தொகை குறைந்தால், விலை குறையவும் வேண்டும்.',	3,	25,	16),
(3487,	'Ye shall not therefore oppress one another; but thou shalt fear thy God:for I am the LORD your God.',	'உங்களில் ஒருவனும் பிறனுக்கு அநியாயம் செய்யக்கூடாது; உன் தேவனுக்குப் பயப்படவேண்டும்; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	25,	17),
(3488,	'Wherefore ye shall do my statutes, and keep my judgments, and do them; and ye shall dwell in the land in safety.',	'என் கட்டளைகளின்படி செய்து, என் நியாயங்களைக் கைக்கொண்டு அவைகளின்படி நடக்கக்கடவீர்கள்; அப்பொழுது தேசத்திலே சுகமாய்க் குடியிருப்பீர்கள்.',	3,	25,	18),
(3489,	'And the land shall yield her fruit, and ye shall eat your fill, and dwell therein in safety.',	'பூமி தன் கனியைத் தரும்; நீங்கள் திருப்தியாகச் சாப்பிட்டு, அதில் சுகமாய்க் குடியிருப்பீர்கள்.',	3,	25,	19),
(3490,	'And if ye shall say, What shall we eat the seventh year? behold, we shall not sow, nor gather in our increase:',	'ஏழாம் வருஷத்தில் எதைப் புசிப்போம்? நாங்கள் விதைக்காமலும், விளைந்ததைச் சேர்க்காமலும் இருக்கவேண்டுமே! என்று சொல்வீர்களானால்,',	3,	25,	20),
(3491,	'Then I will command my blessing upon you in the sixth year, and it shall bring forth fruit for three years.',	'நான் ஆறாம் வருஷத்தில் உங்களுக்கு ஆசீர்வாதத்தை அநுக்கிரகம்பண்ணுவேன்; அது உங்களுக்கு மூன்று வருஷத்தின் பலனைத் தரும்.',	3,	25,	21),
(3492,	'And ye shall sow the eighth year, and eat yet of old fruit until the ninth year; until her fruits come in ye shall eat of the old store.',	'நீங்கள் எட்டாம் வருஷத்திலே விதைத்து, ஒன்பதாம் வருஷம்மட்டும் பழைய பலனிலே சாப்பிடுவீர்கள்; அதின் பலன் விளையும்வரைக்கும் பழைய பலனைச் சாப்பிடுவீர்கள்.',	3,	25,	22),
(3493,	'The land shall not be sold for ever: for the land is mine, for ye are strangers and sojourners with me.',	'தேசம் என்னுடையதாயிருக்கிறபடியால், நீங்கள் நிலங்களை அறுதியாய் விற்கவேண்டாம்; நீங்கள் பரதேசிகளும் என்னிடத்தில் புறக்குடிகளுமாயிருக்கிறீர்கள்.',	3,	25,	23),
(3494,	'And in all the land of your possession ye shall grant a redemption for the land.',	'உங்கள் காணியாட்சியான தேசமெங்கும் நிலங்களை மீட்டுக்கொள்ள இடங்கொடுக்கக்கடவீர்கள்.',	3,	25,	24),
(3495,	'If thy brother be waxen poor, and hath sold away some of his possession, and if any of his kin come to redeem it, then shall he redeem that which his brother sold.',	'உங்கள் சகோதரன் தரித்திரப்பட்டு, தன் காணியாட்சியிலே சிலதை விற்றால், அவன் இனத்தான் ஒருவன் வந்து, தன் சகோதரன் விற்றதை மீட்கக்கடவன்.',	3,	25,	25),
(3496,	'And if the man have none to redeem it, and himself be able to redeem it;',	'அதை மீட்க ஒருவனும் இல்லாமல், தானே அதை மீட்கத்தக்கவனானால்,',	3,	25,	26),
(3497,	'Then let him count the years of the sale thereof, and restore the overplus unto the man to whom he sold it; that he may return unto his possession.',	'அதை விற்றபின் சென்ற வருஷங்களின் தொகையைத் தள்ளி, மீந்த தொகையை ஏற்றி, கொண்டவனுக்குக் கொடுத்து, அவன் தன் காணியாட்சிக்குத் திரும்பிப்போகக்கடவன்.',	3,	25,	27),
(3498,	'But if he be not able to restore it to him, then that which is sold shall remain in the hand of him that hath bought it until the year of jubile: and in the jubile it shall go out, and he shall return unto his possession.',	'அப்படிக் கொடுப்பதற்கான நிர்வாகம் அவனுக்கு இல்லாவிட்டால், அவன் விற்றது வாங்கினவன் கையிலே யூபிலி வருஷம்மட்டும் இருந்து, யூபிலி வருஷத்திலே அது விடுதலையாகும்; அப்பொழுது அவன் தன் காணியாட்சிக்குத் திரும்பப்போவான்.',	3,	25,	28),
(3499,	'And if a man sell a dwelling house in a walled city, then he may redeem it within a whole year after it is sold; within a full year may he redeem it.',	'ஒருவன் மதில்சூழ்ந்த பட்டணத்திலுள்ள தன் வாசஸ்தலமாகிய வீட்டை விற்றால், அதை விற்ற ஒரு வருஷத்துக்குள் அதை மீட்டுக்கொள்ளலாம்; ஒரு வருஷத்துக்குள்ளாகவே அதை மீட்டுக்கொள்ளவேண்டும்.',	3,	25,	29),
(3500,	'And if it be not redeemed within the space of a full year, then the house that is in the walled city shall be established for ever to him that bought it throughout his generations: it shall not go out in the jubile.',	'ஒரு வருஷத்துக்குள்ளே அதை மீட்டுக்கொள்ளாதிருந்தால், மதில்சூழ்ந்த பட்டணத்திலுள்ள அந்த வீடு தலைமுறைதோறும் அதை வாங்கினவனுக்கே உரியதாகும்; யூபிலி வருஷத்திலும் அது விடுதலையாகாது.',	3,	25,	30),
(3501,	'But the houses of the villages which have no wall round about them shall be counted as the fields of the country: they may be redeemed, and they shall go out in the jubile.',	'மதில்சூழப்படாத கிராமங்களிலுள்ள வீடுகளோ, தேசத்தின் நிலங்கள்போலவே எண்ணப்படும்; அவைகள் மீட்கப்படலாம்; யூபிலி வருஷத்தில் அவைகள் விடுதலையாகும்.',	3,	25,	31),
(3502,	'Notwithstanding the cities of the Levites, and the houses of the cities of their possession, may the Levites redeem at any time.',	'லேவியரின் காணியாட்சியாகிய பட்டணங்களிலுள்ள வீடுகளையோ லேவியர் எக்காலத்திலும் மீட்டுக்கொள்ளலாம்.',	3,	25,	32),
(3503,	'And if a man purchase of the Levites, then the house that was sold, and the city of his possession, shall go out in the year of jubile: for the houses of the cities of the Levites are their possession among the children of Israel.',	'இஸ்ரவேல் புத்திரருக்குள்ளே லேவியருடைய பட்டணங்களிலுள்ள வீடுகள் அவர்களுக்குரிய காணியாட்சியானபடியால், லேவியரிடத்தில் அவனுடைய காணியாட்சிப் பட்டணத்திலுள்ள வீட்டை ஒருவன் வாங்கினால், விற்கப்பட்ட அந்த வீடு யூபிலி வருஷத்தில் விடுதலையாகும்.',	3,	25,	33),
(3504,	'But the field of the suburbs of their cities may not be sold; for it is their perpetual possession.',	'அவர்கள் பட்டணங்களைச் சூழ்ந்த வெளிநிலம் விற்கப்படலாகாது; அது அவர்களுக்கு நித்திய காணியாட்சியாயிருக்கும்.',	3,	25,	34),
(3505,	'And if thy brother be waxen poor, and fallen in decay with thee; then thou shalt relieve him: yea, though he be a stranger, or a sojourner; that he may live with thee.',	'உன் சகோதரன் தரித்திரப்பட்டு, கையிளைத்துப்போனவனானால் அவனை ஆதரிக்கவேண்டும்; பரதேசியைப்போலும் தங்கவந்தவனைப்போலும் அவன் உன்னோடே பிழைப்பானாக.',	3,	25,	35),
(3506,	'Take thou no usury of him, or increase: but fear thy God; that thy brother may live with thee.',	'நீ அவன் கையில் வட்டியாவது பொலிசையாவது வாங்காமல், உன் தேவனுக்குப் பயந்து, உன் சகோதரன் உன்னோடே பிழைக்கும்படி செய்வாயாக.',	3,	25,	36),
(3507,	'Thou shalt not give him thy money upon usury, nor lend him thy victuals for increase.',	'அவனுக்கு உன் பணத்தை வட்டிக்கும், உன் தானியத்தைப் பொலிசைக்கும் கொடாயாக.',	3,	25,	37),
(3508,	'I am the LORD your God, which brought you forth out of the land of Egypt, to give you the land of Canaan, and to be your God.',	'உங்களுக்குக் கானான் தேசத்தைக் கொடுத்து, உங்களுக்கு தேவனாயிருக்கும்படி, உங்களை எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின உங்கள் தேவனாகிய கர்த்தர் நானே.',	3,	25,	38),
(3509,	'And if thy brother that dwelleth by thee be waxen poor, and be sold unto thee; thou shalt not compel him to serve as a bondservant:',	'உன் சகோதரன் தரித்திரனாகி, உனக்கு விலைப்பட்டுப்போனால், அவனை அடிமையைப்போல ஊழியஞ்செய்ய நெருக்கவேண்டாம்.',	3,	25,	39),
(3510,	'But as an hired servant, and as a sojourner, he shall be with thee, and shall serve thee unto the year of jubile.',	'அவன் கூலிக்காரனைப்போலவும் தங்கவந்தவனைப்போலவும் உன்னோடே இருந்து, யூபிலி வருஷம்மட்டும் உன்னிடத்தில் சேவிக்கக்கடவன்.',	3,	25,	40),
(3511,	'And then shall he depart from thee, both he and his children with him, and shall return unto his own family, and unto the possession of his fathers shall he return.',	'பின்பு, தன் பிள்ளைகளோடுங்கூட உன்னை விட்டு நீங்கலாகி, தன் குடும்பத்தாரிடத்துக்கும் தன் பிதாக்களின் காணியாட்சிக்கும் திரும்பிப்போகக்கடவன்.',	3,	25,	41),
(3512,	'For they are my servants, which I brought forth out of the land of Egypt: they shall not be sold as bondmen.',	'அவர்கள் நான் எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின என்னுடைய ஊழியக்காரர்; ஆகையால், அவர்கள் அடிமைகளாக விற்கப்படலாகாது.',	3,	25,	42),
(3513,	'Thou shalt not rule over him with rigour; but shalt fear thy God.',	'நீ அவனைக் கொடூரமாய் ஆளாமல், உன் தேவனுக்குப் பயந்திரு.',	3,	25,	43),
(3514,	'Both thy bondmen, and thy bondmaids, which thou shalt have, shall be of the heathen that are round about you; of them shall ye buy bondmen and bondmaids.',	'உனக்கு இருக்கும் ஆண் அடிமையும் பெண் அடிமையும் சுற்றிலும் இருக்கிற புறஜாதிகளாயிருக்கவேண்டும்; அவர்களில் நீ ஆண் அடிமையையும் பெண் அடிமையையும் விலைக்கு வாங்கலாம்.',	3,	25,	44),
(3515,	'Moreover of the children of the strangers that do sojourn among you, of them shall ye buy, and of their families that are with you, which they begat in your land: and they shall be your possession.',	'உங்களிடத்திலே பரதேசிகளாய்த் தங்குகிற அந்நிய புத்திரரிலும், உங்கள் தேசத்தில் உங்களிடத்திலே பிறந்திருக்கிற அவர்களுடைய குடும்பத்தாரிலும் நீங்கள் உங்களுக்கு அடிமைகளைக்கொண்டு, அவர்களை உங்களுக்குச் சுதந்தரமாக்கலாம்.',	3,	25,	45),
(3516,	'And ye shall take them as an inheritance for your children after you, to inherit them for a possession; they shall be your bondmen for ever: but over your brethren the children of Israel, ye shall not rule one over another with rigour.',	'அவர்களை உங்களுக்குப் பின்வரும் உங்கள் சந்ததியாரும் சுதந்தரிக்கும்படி நீங்கள் அவர்களைச் சுதந்தரமாக்கிக்கொள்ளலாம்; என்றைக்கும் அவர்கள் உங்களுக்கு அடிமைகளாயிருக்கலாம்; உங்கள் சகோதரராகிய இஸ்ரவேல் புத்திரரோ ஒருவரையொருவர் கொடூரமாக ஆளக்கூடாது.',	3,	25,	46),
(3517,	'And if a sojourner or stranger wax rich by thee, and thy brother that dwelleth by him wax poor, and sell himself unto the stranger or sojourner by thee, or to the stock of the stranger\'s family:',	'உன்னிடத்தில் இருக்கிற பரதேசியும் அந்நியனும் செல்வனாயிருக்க, அவனிடத்தில் இருக்கிற உன் சகோதரன் தரித்திரப்பட்டு, அந்தப் பரதேசிக்காவது, அந்நியனுக்காவது, பரதேசியின் குடும்பத்தாரில் எவனுக்காவது அவன் விலைப்பட்டுப்போனால்,',	3,	25,	47),
(3518,	'After that he is sold he may be redeemed again; one of his brethren may redeem him:',	'அவன் விலைப்பட்டுப்போனபின் திரும்ப மீட்கப்படலாம்; அவன் சகோதரரில் ஒருவன் அவனை மீட்கலாம்.',	3,	25,	48),
(3519,	'Either his uncle, or his uncle\'s son, may redeem him, or any that is nigh of kin unto him of his family may redeem him; or if he be able, he may redeem himself.',	'அவனுடைய பிதாவின் சகோதரனாவது, அந்தச் சகோதரனுடைய புத்திரனாவது, அவன் குடும்பத்திலுள்ள அவனைச் சேர்ந்த இனத்தாரில் எவனாவது அவனை மீட்கலாம்; தன்னால் கூடுமானால், தன்னைத்தானே மீட்டுக்கொள்ளலாம்.',	3,	25,	49),
(3520,	'And he shall reckon with him that bought him from the year that he was sold to him unto the year of jubile: and the price of his sale shall be according unto the number of years, according to the time of an hired servant shall it be with him.',	'அவன் தான் விலைப்பட்ட வருஷந்தொடங்கி, யூபிலி வருஷம்வரைக்கும் உண்டான காலத்தைத் தன்னை விலைக்குக் கொண்டவனுடன் கணக்குப் பார்க்கக்கடவன்; அவனுடைய விலைக்கிரயம் கூலிக்காரனுடைய காலக்கணக்குப்போல, வருஷத்தொகைக்கு ஒத்துப்பார்க்கவேண்டும்.',	3,	25,	50),
(3521,	'If there be yet many years behind, according unto them he shall give again the price of his redemption out of the money that he was bought for.',	'இன்னும் அநேக வருஷங்கள் இருந்தால், அவன் தன் விலைக்கிரயத்திலே அவைகளுக்குத் தக்கதைத் தன்னை மீட்கும்பொருளாகத் திரும்பக்கொடுக்கக்கடவன்.',	3,	25,	51),
(3522,	'And if there remain but few years unto the year of jubile, then he shall count with him, and according unto his years shall he give him again the price of his redemption.',	'யூபிலி வருஷம்மட்டும் மீதியாயிருக்கிற வருஷங்கள் கொஞ்சமேயானால், அவனோடே கணக்குப் பார்த்து, தன் வருஷங்களுக்குத்தக்கதை, தன்னை மீட்கும் பொருளாகத் திரும்பக் கொடுக்கவேண்டும்.',	3,	25,	52),
(3523,	'And as a yearly hired servant shall he be with him: and the other shall not rule with rigour over him in thy sight.',	'இவன் வருஷத்திற்கு வருஷம் கூலிபொருந்திக்கொண்ட கூலிக்காரனைப் போல, அவனிடத்தில் இருக்கவேண்டும்; அவன் இவனை உனக்கு முன்பாகக் கொடூரமாய் ஆளக்கூடாது.',	3,	25,	53),
(3524,	'And if he be not redeemed in these years, then he shall go out in the year of jubile, both he, and his children with him.',	'இப்படி இவன் மீட்டுக்கொள்ளப்படாதிருந்தால், இவனும் இவனோடுகூட இவன் பிள்ளைகளும் யூபிலி வருஷத்தில் விடுதலையாவார்கள்.',	3,	25,	54),
(3525,	'For unto me the children of Israel are servants; they are my servants whom I brought forth out of the land of Egypt: I am the LORD your God.',	'இஸ்ரவேல் புத்திரர் என் ஊழியக்காரர்; அவர்கள் நான் எகிப்துதேசத்திலிருந்து புறப்படப்பண்ணின என் ஊழியக்காரரே; நான் உங்கள் தேவனாகிய கர்த்தர்.  ',	3,	25,	55),
(3526,	'Ye shall make you no idols nor graven image, neither rear you up a standing image, neither shall ye set up any image of stone in your land, to bow down unto it: for I am the LORD your God.',	'நீங்கள் உங்களுக்கு விக்கிரகங்களையும் சுரூபங்களையும் உண்டாக்காமலும், உங்களுக்குச் சிலையை நிறுத்தாமலும், சித்திரந்தீர்ந்த கல்லை நமஸ்கரிக்கும்பொருட்டு உங்கள் தேசத்தில் வைக்காமலும் இருப்பீர்களாக; நான் உங்கள் தேவனாகிய கர்த்தர்.',	3,	26,	1),
(3527,	'Ye shall keep my sabbaths, and reverence my sanctuary: I am the LORD.',	'என் ஓய்வுநாட்களை ஆசரித்து, என் பரிசுத்த ஸ்தலத்தைக்குறித்துப் பயபக்தியாயிருப்பீர்களாக; நான் கர்த்தர்.',	3,	26,	2),
(3528,	'If ye walk in my statutes, and keep my commandments, and do them;',	'நீங்கள் என் கட்டளைகளின்படி நடந்து, என் கற்பனைகளைக் கைக்கொண்டு, அவைகளின்படி செய்தால்,',	3,	26,	3),
(3529,	'Then I will give you rain in due season, and the land shall yield her increase, and the trees of the field shall yield their fruit.',	'நான் ஏற்ற காலத்தில் உங்களுக்கு மழை பெய்யப்பண்ணுவேன்; பூமி தன் பலனையும், வெளியிலுள்ள மரங்கள் தங்கள் கனியையும் கொடுக்கும்.',	3,	26,	4),
(3530,	'And your threshing shall reach unto the vintage, and the vintage shall reach unto the sowing time: and ye shall eat your bread to the full, and dwell in your land safely.',	'திராட்சப்பழம் பறிக்குங் காலம் வரைக்கும் போரடிப்புக் காலம் இருக்கும்; விதைப்புக் காலம்வரைக்கும் திராட்சப்பழம் பறிக்குங் காலம் இருக்கும்; நீங்கள் உங்கள் அப்பத்தைத் திருப்தியாகச் சாப்பிட்டு, உங்கள் தேசத்தில் சுகமாய்க் குடியிருப்பீர்கள்.',	3,	26,	5),
(3531,	'And I will give peace in the land, and ye shall lie down, and none shall make you afraid: and I will rid evil beasts out of the land, neither shall the sword go through your land.',	'தேசத்தில் சமாதானம் கட்டளையிடுவேன்; தத்தளிக்கப்பண்ணுவார் இல்லாமல் படுத்துக்கொள்வீர்கள்; துஷ்ட மிருகங்களைத் தேசத்தில் இராதபடிக்கு ஒழியப்பண்ணுவேன்; பட்டயம் உங்கள் தேசத்தில் உலாவுவதில்லை.',	3,	26,	6),
(3532,	'And ye shall chase your enemies, and they shall fall before you by the sword.',	'உங்கள் சத்துருக்களைத் துரத்துவீர்கள்; அவர்கள் உங்கள் முன்பாகப் பட்டயத்தால் விழுவார்கள்.',	3,	26,	7),
(3533,	'And five of you shall chase an hundred, and an hundred of you shall put ten thousand to flight: and your enemies shall fall before you by the sword.',	'உங்களில் ஐந்துபேர் நூறுபேரைத் துரத்துவார்கள்; உங்களில் நூறுபேர் பதினாயிரம்பேரைத் துரத்துவார்கள்; உங்கள் சத்துருக்கள் உங்களுக்கு முன்பாகப் பட்டயத்தால் விழுவார்கள்.',	3,	26,	8),
(3534,	'For I will have respect unto you, and make you fruitful, and multiply you, and establish my covenant with you.',	'நான் உங்கள்மேல் கண்ணோக்கமாயிருந்து, உங்களைப் பலுகவும் பெருகவும் பண்ணி, உங்களோடே என் உடன்படிக்கையைத் திடப்படுத்துவேன்.',	3,	26,	9),
(3535,	'And ye shall eat old store, and bring forth the old because of the new.',	'போன வருஷத்துப் பழைய தானியத்தைச் சாப்பிட்டு, புதிய தானியத்துக்கு இடமுண்டாகும்படி, பழையதை விலக்குவீர்கள்.',	3,	26,	10),
(3536,	'And I set my tabernacle among you: and my soul shall not abhor you.',	'உங்கள் நடுவில் என் வாசஸ்தலத்தை ஸ்தாபிப்பேன்; என் ஆத்துமா உங்களை அரோசிப்பதில்லை.',	3,	26,	11),
(3537,	'And I will walk among you, and will be your God, and ye shall be my people.',	'நான் உங்கள் நடுவிலே உலாவி, உங்கள் தேவனாயிருப்பேன், நீங்கள் என் ஜனமாயிருப்பீர்கள்.',	3,	26,	12),
(3538,	'I am the LORD your God, which brought you forth out of the land of Egypt, that ye should not be their bondmen; and I have broken the bands of your yoke, and made you go upright.',	'நீங்கள் எகிப்தியருக்கு அடிமைகளாயிராதபடிக்கு, நான் அவர்கள் தேசத்திலிருந்து உங்களைப் புறப்படப்பண்ணி, உங்கள் நுகத்தடிகளை முறித்து, உங்களை நிமிர்ந்து நடக்கப்பண்ணின உங்கள் தேவனாகிய கர்த்தர்.',	3,	26,	13),
(3539,	'But if ye will not hearken unto me, and will not do all these commandments;',	'நீங்கள் எனக்குச் செவிகொடாமலும், இந்தக் கற்பனைகள் எல்லாவற்றின்படி செய்யாமலும்,',	3,	26,	14),
(3540,	'And if ye shall despise my statutes, or if your soul abhor my judgments, so that ye will not do all my commandments, but that ye break my covenant:',	'என் கட்டளைகளை வெறுத்து, உங்கள் ஆத்துமா என் நியாயங்களை அரோசித்து, என் கற்பனைகள் எல்லாவற்றின்படி.யும் செய்யாதபடிக்கு, என் உடன்படிக்கையை நீங்கள் மீறிப்போடுவீர்களாகில்:',	3,	26,	15),
(3541,	'I also will do this unto you; I will even appoint over you terror, consumption, and the burning ague, that shall consume the eyes, and cause sorrow of heart: and ye shall sow your seed in vain, for your enemies shall eat it.',	'நான் உங்களுக்குச் செய்வது என்னவென்றால், கண்களைப் பூத்துப்போகப்பண்ணுகிறதற்கும், இருதயத்தைத் துயரப்படுத்துகிறதற்கும், திகிலையும் ஈளையையும் காய்ச்சலையும் உங்களுக்கு வரப்பண்ணுவேன்; நீங்கள் விதைக்கும் விதை விருதாவாயிருக்கும்; உங்கள் சத்துருக்கள் அதின் பலனைத் தின்பார்கள்.',	3,	26,	16),
(3542,	'And I will set my face against you, and ye shall be slain before your enemies: they that hate you shall reign over you; and ye shall flee when none pursueth you.',	'நான் உங்களுக்கு விரோதமாக என் முகத்தைத் திருப்புவேன்; உங்கள் சத்துருக்களுக்கு முன்பாக முறிய அடிக்கப்படுவீர்கள்; உங்கள் பகைஞர் உங்களை ஆளுவார்கள்; துரத்துவார் இல்லாதிருந்தும் ஓடுவீர்கள்.',	3,	26,	17),
(3543,	'And if ye will not yet for all this hearken unto me, then I will punish you seven times more for your sins.',	'இவ்விதமாய் நான் உங்களுக்குச் செய்தும், இன்னும் நீங்கள் எனக்குச் செவிகொடாதிருந்தால், உங்கள் பாவங்களினிமித்தம் பின்னும் ஏழத்தனையாக உங்களைத் தண்டித்து,',	3,	26,	18),
(3544,	'And I will break the pride of your power; and I will make your heaven as iron, and your earth as brass:',	'உங்கள் வல்லமையின் பெருமையை முறித்து, உங்கள் வானத்தை இரும்பைப் போலவும், உங்கள் பூமியை வெண்கலத்தைப்போலவும் ஆக்குவேன்.',	3,	26,	19),
(3545,	'And your strength shall be spent in vain: for your land shall not yield her increase, neither shall the trees of the land yield their fruits.',	'உங்கள் பெலன் விருதாவிலே செலவழியும், உங்கள் தேசம் தன் பலனையும், தேசத்தின் மரங்கள் தங்கள் கனிகளையும் கொடுக்கமாட்டாது.',	3,	26,	20),
(3546,	'And if ye walk contrary unto me, and will not hearken unto me; I will bring seven times more plagues upon you according to your sins.',	'நீங்கள் எனக்குச் செவிகொடுக்க மனதில்லாமல், எனக்கு எதிர்த்து நடப்பீர்களானால், நான் உங்கள் பாவங்களுக்குத்தக்கதாக இன்னும் ஏழத்தனை வாதையை உங்கள்மேல் வரப்பண்ணி,',	3,	26,	21),
(3547,	'I will also send wild beasts among you, which shall rob you of your children, and destroy your cattle, and make you few in number; and your high ways shall be desolate.',	'உங்களுக்குள்ளே வெளியின் துஷ்ட மிருகங்களை வரவிடுவேன்; அவைகள் உங்களைப் பிள்ளைகளற்றவர்களாக்கி, உங்கள் மிருகஜீவன்களை அழித்து, உங்களைக் குறைந்துபோகப்பண்ணும்; உங்கள் வழிகள் பாழாய்க் கிடக்கும்.',	3,	26,	22),
(3548,	'And if ye will not be reformed by me by these things, but will walk contrary unto me;',	'நான் செய்யும் தண்டனையினால் நீங்கள் குணப்படாமல், எனக்கு எதிர்த்து நடந்தால்,',	3,	26,	23),
(3549,	'Then will I also walk contrary unto you, and will punish you yet seven times for your sins.',	'நான் உங்களுக்கு எதிர்த்து நடந்து, உங்கள் பாவங்களினிமித்தம் ஏழத்தனையாக வாதித்து,',	3,	26,	24),
(3550,	'And I will bring a sword upon you, that shall avenge the quarrel of my covenant: and when ye are gathered together within your cities, I will send the pestilence among you; and ye shall be delivered into the hand of the enemy.',	'என் உடன்படிக்கையை மீறினதற்குப் பழிவாங்கும் பட்டயத்தை உங்கள்மேல் வரப்பண்ணி, நீங்கள் உங்கள் பட்டணங்களில் சேர்ந்தபின், கொள்ளைநோயை உங்கள் நடுவிலே அனுப்புவேன்; சத்துருவின் கையில் ஒப்புக்கொடுக்கப்படுவீர்கள்.',	3,	26,	25),
(3551,	'And when I have broken the staff of your bread, ten women shall bake your bread in one oven, and they shall deliver you your bread again by weight: and ye shall eat, and not be satisfied.',	'உங்கள் அப்பம் என்னும் ஆதரவு கோலை நான் முறித்துப்போடும்போது, பத்து ஸ்திரீகள் ஒரே அடுப்பில் உங்கள் அப்பத்தைச் சுட்டு, அதைத் திரும்ப உங்களுக்கு நிறுத்துக்கொடுப்பார்கள்; நீங்கள் சாப்பிட்டும் திருப்தியடையமாட்டீர்கள்.',	3,	26,	26),
(3552,	'And if ye will not for all this hearken unto me, but walk contrary unto me;',	'இன்னும் இவைகளெல்லாவற்றாலும் நீங்கள் எனக்குச் செவிகொடாமல், எனக்கு எதிர்த்து நடந்தால்,',	3,	26,	27),
(3553,	'Then I will walk contrary unto you also in fury; and I, even I, will chastise you seven times for your sins.',	'நானும் உக்கிரத்தோடே உங்களுக்கு எதிர்த்து நடந்து, நானே உங்கள் பாவங்களினிமித்தம் உங்களை ஏழத்தனையாய்த் தண்டிப்பேன்.',	3,	26,	28),
(3554,	'And ye shall eat the flesh of your sons, and the flesh of your daughters shall ye eat.',	'உங்கள் குமாரரின் மாம்சத்தையும் உங்கள் குமாரத்திகளின் மாம்சத்தையும் புசிப்பீர்கள்.',	3,	26,	29),
(3555,	'And I will destroy your high places, and cut down your images, and cast your carcases upon the carcases of your idols, and my soul shall abhor you.',	'நான் உங்கள் மேடைகளை அழித்து, உங்கள் விக்கிரகச் சிலைகளை நிர்த்தூளியாக்கி, உங்கள் உடல்களை உங்கள் நரகலான தேவர்களுடைய உடல்கள்மேல் எறிவேன்; என் ஆத்துமா உங்களை அரோசிக்கும்.',	3,	26,	30),
(3556,	'And I will make your cities waste, and bring your sanctuaries unto desolation, and I will not smell the savour of your sweet odours.',	'நான் உங்கள் பட்டணங்களை வெறுமையும், உங்கள் பரிசுத்த ஸ்தலங்களைப் பாழுமாக்கி, உங்கள் சுகந்த வாசனையை முகராதிருப்பேன்.',	3,	26,	31),
(3557,	'And I will bring the land into desolation: and your enemies which dwell therein shall be astonished at it.',	'நான் தேசத்தைப் பாழாக்குவேன்; அதிலே குடியிருக்கிற உங்கள் சத்துருக்கள் பிரமிப்பார்கள்.',	3,	26,	32),
(3558,	'And I will scatter you among the heathen, and will draw out a sword after you: and your land shall be desolate, and your cities waste.',	'ஜாதிகளுக்குள்ளே உங்களைச் சிதற அடித்து, உங்கள் பின்னாகப் பட்டயத்தை உருவுவேன்; உங்கள் தேசம் பாழும், உங்கள் பட்டணங்கள் வனாந்தரமுமாகும்.',	3,	26,	33),
(3559,	'Then shall the land enjoy her sabbaths, as long as it lieth desolate, and ye be in your enemies\' land; even then shall the land rest, and enjoy her sabbaths.',	'நீங்கள் உங்கள் சத்துருக்களின் தேசத்தில் இருக்கும்போது, தேசமானது பாழாய்க்கிடக்கிற நாளெல்லாம் தன் ஓய்வுநாட்களை இரம்மியமாய் அநுபவிக்கும்; அப்பொழுது தேசம் ஓய்வடைந்து, தன் ஓய்வுநாட்களை இரம்மியமாய் அநுபவிக்கும்.',	3,	26,	34),
(3560,	'As long as it lieth desolate it shall rest; because it did not rest in your sabbaths, when ye dwelt upon it.',	'நீங்கள் அதிலே குடியிருக்கும்போது, அது உங்கள் ஓய்வு வருஷங்களில் ஓய்வடையாதபடியினாலே, அது பாழாய்க்கிடக்கும் நாளெல்லாம் ஓய்வடைந்திருக்கும்.',	3,	26,	35),
(3561,	'And upon them that are left alive of you I will send a faintness into their hearts in the lands of their enemies; and the sound of a shaken leaf shall chase them; and they shall flee, as fleeing from a sword; and they shall fall when none pursueth.',	'உங்களில் உயிரோடு மீதியாயிருப்பவர்களின் இருதயங்கள் தங்கள் சத்துருக்களின் தேசங்களில் மனத்தளர்ச்சி அடையும்படி செய்வேன்; அசைகிற இலையின் சத்தமும் அவர்களை ஓட்டும்; அவர்கள் பட்டயத்திற்குத் தப்பி ஓடுகிறது போல ஓடி, துரத்துவார் இல்லாமல் விழுவார்கள்.',	3,	26,	36),
(3562,	'And they shall fall one upon another, as it were before a sword, when none pursueth: and ye shall have no power to stand before your enemies.',	'துரத்துவார் இல்லாமல், பட்டயத்துக்கு முன் விழுவதுபோல, ஒருவர்மேல் ஒருவர் இடறிவிழுவார்கள்; உங்கள் சத்துருக்களுக்குமுன் நிற்க உங்களுக்குப் பெலன் இராது.',	3,	26,	37),
(3563,	'And ye shall perish among the heathen, and the land of your enemies shall eat you up.',	'புறஜாதிகளுக்குள்ளே அழிந்துபோவீர்கள்; உங்கள் சத்துருக்களின் தேசம் உங்களைப் பட்சிக்கும்.',	3,	26,	38),
(3564,	'And they that are left of you shall pine away in their iniquity in your enemies\' lands; and also in the iniquities of their fathers shall they pine away with them.',	'உங்களில் தப்பினவர்கள் தங்கள் அக்கிரமங்களினிமித்தமும், தங்கள் பிதாக்களின் அக்கிரமங்களினிமித்தமும், உங்கள் சத்துருக்களின் தேசங்களில் வாடிப்போவார்கள்.',	3,	26,	39),
(3565,	'If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;',	'அவர்கள் எனக்கு விரோதமாகத் துரோகம்பண்ணி நடப்பித்த தங்கள் அக்கிரமத்தையும், தங்கள் பிதாக்களின் அக்கிரமத்தையும் அறிக்கையிடுகிறதுமன்றி,',	3,	26,	40),
(3566,	'And that I also have walked contrary unto them, and have brought them into the land of their enemies; if then their uncircumcised hearts be humbled, and they then accept of the punishment of their iniquity:',	'அவர்கள் எனக்கு எதிர்த்து நடந்தபடியினால், நானும் அவர்களுக்கு எதிர்த்து நடந்து, அவர்களுடைய சத்துருக்களின் தேசத்திலே அவர்களைக் கொண்டுபோய் விட்டதையும் அறிக்கையிட்டு, விருத்த சேதனமில்லாத தங்கள் இருதயத்தைத் தாழ்த்தி, தங்கள் அக்கிரமத்துக்குக் கிடைத்த தண்டனையை நியாயம் என்று ஒத்துக்கொண்டால்,',	3,	26,	41),
(3567,	'Then will I remember my covenant with Jacob, and also my covenant with Isaac, and also my covenant with Abraham will I remember; and I will remember the land.',	'நான் யாக்கோபோடே பண்ணின என் உடன்படிக்கையையும், ஈசாக்கோடே பண்ணின என் உடன்படிக்கையையும், ஆபிரகாமோடே பண்ணின என் உடன்படிக்கையையும் நினைப்பேன்; தேசத்தையும் நினைப்பேன்.',	3,	26,	42),
(3568,	'The land also shall be left of them, and shall enjoy her sabbaths, while she lieth desolate without them: and they shall accept of the punishment of their iniquity: because, even because they despised my judgments, and because their soul abhorred my statutes.',	'தேசம் அவர்களாலே விடப்பட்டு, பாழாய்க்கிடக்கிறதினாலே தன் ஓய்வுநாட்களை இரம்மியமாய் அநுபவிக்கும்; அவர்கள் என் நியாயங்களை அவமதித்து, அவர்களுடைய ஆத்துமா என் கட்டளைகளை வெறுத்தபடியினால் அடைந்த தங்களுடைய அக்கிரமத்தின் தண்டனையை நியாயம் என்று ஒத்துக்கொள்ளுவார்கள்.',	3,	26,	43),
(3569,	'And yet for all that, when they be in the land of their enemies, I will not cast them away, neither will I abhor them, to destroy them utterly, and to break my covenant with them: for I am the LORD their God.',	'அவர்கள் தங்கள் சத்துருக்களின் தேசத்திலிருந்தாலும், நான் அவர்களை நிர்மூலமாக்கத்தக்கதாகவும், நான் அவர்களோடே பண்ணின என் உடன்படிக்கையை அபத்தமாக்கத்தக்கதாகவும், நான் அவர்களைக் கைவிடவும் வெறுக்கவும் மாட்டேன்; நான் அவர்கள் தேவனாகிய கர்த்தர்.',	3,	26,	44),
(3570,	'But I will for their sakes remember the covenant of their ancestors, whom I brought forth out of the land of Egypt in the sight of the heathen, that I might be their God: I am the LORD.',	'அவர்களுடைய தேவனாயிருக்கும்படிக்கு, நான் புறஜாதிகளின் கண்களுக்கு முன்பாக எகிப்துதேசத்திலிருந்து அவர்களைப் புறப்படச்செய்து, அவர்களுடைய முன்னோர்களோடே நான் பண்ணின உடன்படிக்கையை அவர்கள்நிமித்தம் நினைவுகூருவேன்; நான் கர்த்தர் என்று சொல் என்றார்.',	3,	26,	45),
(3571,	'These are the statutes and judgments and laws, which the LORD made between him and the children of Israel in mount Sinai by the hand of Moses.',	'கர்த்தர் தமக்கும் இஸ்ரவேல் சந்ததியாருக்கும் நடுவே இருக்கும்படி மோசேயைக்கொண்டு, சீனாய்மலையின்மேல் கொடுத்த கட்டளைகளும் நியாயங்களும் இவைகளே.  ',	3,	26,	46),
(3572,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	3,	27,	1),
(3573,	'Speak unto the children of Israel, and say unto them, When a man shall make a singular vow, the persons shall be for the LORD by thy estimation.',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: யாதாமொருவர் ஒரு விசேஷித்த பொருத்தனை பண்ணியிருந்தால், பொருத்தனை பண்ணப்பட்டவர்கள் உன் மதிப்பின்படி கர்த்தருக்கு உரியவர்கள்.',	3,	27,	2),
(3574,	'And thy estimation shall be of the male from twenty years old even unto sixty years old, even thy estimation shall be fifty shekels of silver, after the shekel of the sanctuary.',	'இருபது வயதுமுதல் அறுபது வயதுக்கு உட்பட்ட ஆண்பிள்ளையை நீ பரிசுத்த ஸ்தலத்தின் சேக்கலாகிய ஐம்பது வெள்ளிச்சேக்கலாகவும்,',	3,	27,	3),
(3575,	'And if it be a female, then thy estimation shall be thirty shekels.',	'பெண்பிள்ளையை முப்பது சேக்கலாகவும் மதிப்பாயாக.',	3,	27,	4),
(3576,	'And if it be from five years old even unto twenty years old, then thy estimation shall be of the male twenty shekels, and for the female ten shekels.',	'ஐந்து வயதுமுதல் இருபது வயதுக்கு உட்பட்ட ஆண்பிள்ளையை இருபது சேக்கலாகவும், பெண்பிள்ளையைப் பத்துச்சேக்கலாகவும்,',	3,	27,	5),
(3577,	'And if it be from a month old even unto five years old, then thy estimation shall be of the male five shekels of silver, and for the female thy estimation shall be three shekels of silver.',	'ஒரு மாதம்முதல் ஐந்து வயதுக்கு உட்பட்ட ஆண்பிள்ளையை ஐந்து வெள்ளிச்சேக்கலாகவும், பெண்பிள்ளையை மூன்று வெள்ளிச்சேக்கலாகவும்,',	3,	27,	6),
(3578,	'And if it be from sixty years old and above; if it be a male, then thy estimation shall be fifteen shekels, and for the female ten shekels.',	'அறுபது வயதுதொடங்கி, அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளையைப் பதினைந்து சேக்கலாகவும், பெண்பிள்ளையைப் பத்துச் சேக்கலாகவும் மதிக்கக்கடவாய்.',	3,	27,	7),
(3579,	'But if he be poorer than thy estimation, then he shall present himself before the priest, and the priest shall value him; according to his ability that vowed shall the priest value him.',	'உன் மதிப்பின்படி செலுத்தக்கூடாத தரித்திரனாயிருந்தால், அவன் ஆசாரியனுக்கு முன்பாக வந்து நிற்கக்கடவன்; ஆசாரியன் அவனை மதிப்பானாக; பொருத்தனைபண்ணினவனுடைய திராணிக்கேற்றபடி ஆசாரியன் அவனை மதிக்கக்கடவன்.',	3,	27,	8),
(3580,	'And if it be a beast, whereof men bring an offering unto the LORD, all that any man giveth of such unto the LORD shall be holy.',	'ஒருவன் பொருத்தனைபண்ணினது கர்த்தருக்குப் பலியிடப்படத்தக்க மிருக ஜீவனானால் அவன் கர்த்தருக்குக் கொடுக்கிற அப்படிப்பட்டதெல்லாம் பரிசுத்தமாயிருப்பதாக.',	3,	27,	9),
(3581,	'He shall not alter it, nor change it, a good for a bad, or a bad for a good: and if he shall at all change beast for beast, then it and the exchange thereof shall be holy.',	'அதை மாற்றாமலும் வேறுபடுத்தாமலும் இருப்பானாக; இளப்பமானதற்குப் பதிலாக நலமானதையும், நலமானதற்குப் பதிலாக இளப்பமானதையும் செலுத்தாமல் இருப்பானாக; அவன் மிருகத்திற்குப் பதிலாக மிருகத்தை மாற்றிக் கொடுப்பானாகில், அப்பொழுது அதுவும் அதற்குப் பதிலாகக் கொடுத்ததும் பரிசுத்தமாயிருப்பதாக.',	3,	27,	10),
(3582,	'And if it be any unclean beast, of which they do not offer a sacrifice unto the LORD, then he shall present the beast before the priest:',	'அது கர்த்தருக்குப் பலியிடப்படத்தகாத சுத்தமல்லாத யாதொரு மிருகமானால், அதை ஆசாரியனுக்கு முன்பாக நிறுத்தக்கடவன்.',	3,	27,	11),
(3583,	'And the priest shall value it, whether it be good or bad: as thou valuest it, who art the priest, so shall it be.',	'ஆசாரியன் அது நல்லதானாலும் இளப்பமானதானாலும் அதை மதிப்பானாக; உன் மதிப்பின்படியே இருக்கக்கடவது.',	3,	27,	12),
(3584,	'But if he will at all redeem it, then he shall add a fifth part thereof unto thy estimation.',	'அதை மீட்டுக்கொள்ள மனதாயிருந்தானாகில், உன் மதிப்போடே ஐந்தில் ஒரு பங்கைக் கூட்டிக் கொடுக்கக்கடவன்.',	3,	27,	13),
(3585,	'And when a man shall sanctify his house to be holy unto the LORD, then the priest shall estimate it, whether it be good or bad: as the priest shall estimate it, so shall it stand.',	'ஒருவன் தன் வீட்டைக் கர்த்தருக்குப் பரிசுத்தம் என்று நேர்ந்துகொண்டால், ஆசாரியன் அதின் நலத்துக்கும் இளப்பத்துக்கும்தக்கதாக அதை மதிக்கக்கடவன்; ஆசாரியன் மதிக்கிறபடி அது இருக்கக்கடவது.',	3,	27,	14),
(3586,	'And if he that sanctified it will redeem his house, then he shall add the fifth part of the money of thy estimation unto it, and it shall be his.',	'தன் வீட்டைப் பரிசுத்தம் என்று நேர்ந்துகொண்டவன் அதை மீட்டுக்கொள்ள மனதாயிருந்தால், நீ மதிக்கும் திரவியத்தோடே ஐந்தில் ஒரு பங்கைக் கூட்டிக் கொடுக்கக்கடவன்; அப்பொழுது அது அவனுடையதாகும்.',	3,	27,	15),
(3587,	'And if a man shall sanctify unto the LORD some part of a field of his possession, then thy estimation shall be according to the seed thereof: an homer of barley seed shall be valued at fifty shekels of silver.',	'ஒருவன் தன் காணியாட்சியான வயலில் யாதொரு பங்கைக் கர்த்தருக்குப் பரிசுத்தம் என்று நேர்ந்துகொண்டால், உன் மதிப்பு அதின் விதைப்புக்குத்தக்கதாய் இருக்கவேண்டும்; ஒரு கலம் வாற்கோதுமை விதைக்கிற வயல் ஐம்பது வெள்ளிச் சேக்கலாக மதிக்கப்படவேண்டும்.',	3,	27,	16),
(3588,	'If he sanctify his field from the year of jubile, according to thy estimation it shall stand.',	'யூபிலி வருஷமுதல் அவன் தன் வயலைப் பரிசுத்தம் என்று நேர்ந்துகொண்டால், அது உன் மதிப்பின்படி இருக்கவேண்டும்.',	3,	27,	17),
(3589,	'But if he sanctify his field after the jubile, then the priest shall reckon unto him the money according to the years that remain, even unto the year of the jubile, and it shall be abated from thy estimation.',	'யூபிலி வருஷத்துக்குப்பின் தன் வயலைப் பரிசுத்தம் என்று நேர்ந்துகொண்டானானால், யூபிலி வருஷம்மட்டுமுள்ள மற்ற வருஷங்களின்படியே ஆசாரியன் திரவியத்தைக் கணக்குப்பார்த்து, அதற்குத்தக்கது உன் மதிப்பிலே தள்ளப்படவேண்டும்.',	3,	27,	18),
(3590,	'And if he that sanctified the field will in any wise redeem it, then he shall add the fifth part of the money of thy estimation unto it, and it shall be assured to him.',	'வயலைப் பரிசுத்தம் என்று நேர்ந்துகொண்டவன் அதை மீட்டுக்கொள்ள மனதாயிருந்தால், உன் மதிப்பான திரவியத்தோடே ஐந்தில் ஒரு பங்கைக் கூட்டிக்கொடுக்கக்கடவன்; அப்பொழுது அது அவனுக்கு உறுதியாகும்.',	3,	27,	19),
(3591,	'And if he will not redeem the field, or if he have sold the field to another man, it shall not be redeemed any more.',	'அவன் வயலை மீட்டுக்கொள்ளாமல், வயலை வேறோருவனுக்கு விற்றுப்போட்டால், அது திரும்ப மீட்கப்படாமல்,',	3,	27,	20),
(3592,	'But the field, when it goeth out in the jubile, shall be holy unto the LORD, as a field devoted; the possession thereof shall be the priest\'s.',	'யூபிலி வருஷத்தில் மீட்கப்படும்போது, சாபத்தீடான வயலாகக் கர்த்தருக்கென்று நியமிக்கப்பட்டதாயிருக்கக்கடவது; அது ஆசாரியனுக்குக் காணியாட்சியாகும்.',	3,	27,	21),
(3593,	'And if a man sanctify unto the LORD a field which he hath bought, which is not of the fields of his possession;',	'ஒருவன் தனக்குக் காணியாட்சி வயலாயிராமல் தான் விலைக்கு வாங்கின ஒரு வயலைக் கர்த்தருக்குப் பரிசுத்தம் என்று நேர்ந்துகொண்டால்,',	3,	27,	22),
(3594,	'Then the priest shall reckon unto him the worth of thy estimation, even unto the year of the jubile: and he shall give thine estimation in that day, as a holy thing unto the LORD.',	'அது யூபிலி வருஷம்மட்டும், உன் மதிப்பின்படி பெறும்விலை இன்னதென்று ஆசாரியன் அவனோடே கணக்குப்பார்த்து, அந்த உன் மதிப்பை, கர்த்தருக்குப் பரிசுத்தமாயிருக்கும்படி, அவன் அந்நாளிலே கொடுக்கக்கடவன்.',	3,	27,	23),
(3595,	'In the year of the jubile the field shall return unto him of whom it was bought, even to him to whom the possession of the land did belong.',	'யார் கையிலே அந்த வயலைக் கொண்டானோ, அந்தக் காணியாட்சிக்காரன் வசமாய் அது யூபிலி வருஷத்தில் திரும்பச்சேரும்.',	3,	27,	24),
(3596,	'And all thy estimations shall be according to the shekel of the sanctuary: twenty gerahs shall be the shekel.',	'உன் மதிப்பெல்லாம் பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்காயிருக்கக்கடவது; ஒரு சேக்கலானது இருபது கேரா.',	3,	27,	25),
(3597,	'Only the firstling of the beasts, which should be the LORD\'s firstling, no man shall sanctify it; whether it be ox, or sheep: it is the LORD\'s.',	'தலையீற்றானவைகள் கர்த்தருடையது, ஆகையால் ஒருவரும் தலையீற்றாகிய மிருகஜீவனைப் பரிசுத்தம் என்று நேர்ந்துகொள்ளலாகாது; அது மாடானாலும் ஆடானாலும் கர்த்தருடையது.',	3,	27,	26),
(3598,	'And if it be of an unclean beast, then he shall redeem it according to thine estimation, and shall add a fifth part of it thereto: or if it be not redeemed, then it shall be sold according to thy estimation.',	'சுத்தமல்லாத மிருகத்தினுடைய தலையீற்றானால், அதை அவன் உன் மதிப்பின்படி மீட்டுக்கொண்டு, அதனுடனே ஐந்தில் ஒரு பங்கைக் கூட்டிக்கொடுக்கக்கடவன்; மீட்கப்படாமலிருந்தால், உன் மதிப்பின்படி அது விற்கப்படக்கடவது.',	3,	27,	27),
(3599,	'Notwithstanding no devoted thing, that a man shall devote unto the LORD of all that he hath, both of man and beast, and of the field of his possession, shall be sold or redeemed: every devoted thing is most holy unto the LORD.',	'ஒருவன் தன் வசத்திலுள்ள நரஜீவனிலாவது, மிருகஜீவனிலாவது, காணியாட்சி நிலத்திலாவது, எதையாகிலும் கர்த்தருக்கென்று சாபத்தீடாக நேர்ந்துகொண்டால், அது விற்கப்படவும் மீட்கப்படவும் கூடாது; நேர்ந்துகொள்ளப்பட்டவைகளெல்லாம் கர்த்தருக்காகப் பரிசுத்தமாயிருக்கும்.',	3,	27,	28),
(3600,	'None devoted, which shall be devoted of men, shall be redeemed; but shall surely be put to death.',	'நரஜீவனில் சாபத்தீடாக நியமிக்கப்பட்டவைகளெல்லாம் மீட்கப்படாமல் கொலைசெய்யப்படக்கடவது.',	3,	27,	29),
(3601,	'And all the tithe of the land, whether of the seed of the land, or of the fruit of the tree, is the LORD\'s: it is holy unto the LORD.',	'தேசத்திலே நிலத்தின் வித்திலும், விருட்சங்களின் கனியிலும், தசமபாகம் எல்லாம் கர்த்தருக்கு உரியது; அது கர்த்தருக்குப் பரிசுத்தமானது.',	3,	27,	30),
(3602,	'And if a man will at all redeem ought of his tithes, he shall add thereto the fifth part thereof.',	'ஒருவன் தன் தசமபாகத்திலே எவ்வளவாவது மீட்டுக்கொள்ள மனதாயிருந்தானானால், அதனுடன் ஐந்தில் ஒரு பங்கைக் கூட்டிக் கொடுக்கக்கடவன்.',	3,	27,	31),
(3603,	'And concerning the tithe of the herd, or of the flock, even of whatsoever passeth under the rod, the tenth shall be holy unto the LORD.',	'கோலின் கீழ்ப்பட்ட ஆடுமாடுகளிலே பத்தில் ஒரு பங்காகிறதெல்லாம் கர்த்தருக்குப் பரிசுத்தமானது.',	3,	27,	32),
(3604,	'He shall not search whether it be good or bad, neither shall he change it: and if he change it at all, then both it and the change thereof shall be holy; it shall not be redeemed.',	'அது நல்லதோ இளப்பமானதோ என்று அவன் பார்க்கவேண்டாம்; அதை மாற்றவும் வேண்டாம்; மாற்றினால், அதுவும் அதற்குப் பதிலாகக் கொடுக்கப்பட்டதுமாகிய இரண்டும் பரிசுத்தமாகும்; அது மீட்கப்படக்கூடாதென்று அவர்களோடே சொல் என்றார்.',	3,	27,	33),
(3605,	'These are the commandments, which the LORD commanded Moses for the children of Israel in mount Sinai.',	'இஸ்ரவேல் புத்திரருக்குச் சொல்லும்படி கர்த்தர் சீனாய்மலையில் மோசேக்கு விதித்த கட்டளைகள் இவைகளே.    ',	3,	27,	34),
(3606,	'And the LORD spake unto Moses in the wilderness of Sinai, in the tabernacle of the congregation, on the first day of the second month, in the second year after they were come out of the land of Egypt, saying,',	'இஸ்ரவேலர் எகிப்துதேசத்திலிருந்து புறப்பட்ட இரண்டாம் வருஷம் இரண்டாம் மாதம் முதல் தேதியில், கர்த்தர் சீனாய் வனாந்தரத்திலிருக்கிற ஆசரிப்புக் கூடாரத்திலே மோசேயை நோக்கி:',	4,	1,	1),
(3607,	'Take ye the sum of all the congregation of the children of Israel, after their families, by the house of their fathers, with the number of their names, every male by their polls;',	'நீங்கள் இஸ்ரவேல் புத்திரரின் முழுச்சபையாயிருக்கிற அவர்கள் பிதாக்களுடைய வீட்டு வம்சங்களிலுள்ள புருஷர்களாகிய சகல தலைகளையும் பேர்பேராக எண்ணித் தொகையேற்றுங்கள்.',	4,	1,	2),
(3608,	'From twenty years old and upward, all that are able to go forth to war in Israel: thou and Aaron shall number them by their armies.',	'இஸ்ரவேலிலே இருபது வயதுள்ளவர்கள்முதல் யுத்தத்துக்குப் புறப்படத்தக்கவர்கள் எல்லாரையும் அவர்கள் சேனைகளின்படி நீயும் ஆரோனும் எண்ணிப் பார்ப்பீர்களாக.',	4,	1,	3),
(3609,	'And with you there shall be a man of every tribe; every one head of the house of his fathers.',	'ஒவ்வொரு கோத்திரத்துக்கு ஒவ்வொரு மனிதன் உங்களோடே இருப்பானாக; அவன் தன் பிதாக்களின் வம்சத்துக்குத் தலைவனாயிருக்கவேண்டும்.',	4,	1,	4),
(3610,	'And these are the names of the men that shall stand with you: of the tribe of Reuben; Elizur the son of Shedeur.',	'உங்களோடே நிற்கவேண்டிய மனிதருடைய நாமங்களாவன: ரூபன் கோத்திரத்தில் சேதேயூருடைய குமாரன் எலிசூர்.',	4,	1,	5),
(3611,	'Of Simeon; Shelumiel the son of Zurishaddai.',	'சிமியோன் கோத்திரத்தில் சூரிஷதாயின் குமாரன் செலூமியேல்.',	4,	1,	6),
(3612,	'Of Judah; Nahshon the son of Amminadab.',	'யூதா கோத்திரத்தில் அம்மினதாபின் குமாரன் நகசோன்.',	4,	1,	7),
(3613,	'Of Issachar; Nethaneel the son of Zuar.',	'இசக்கார் கோத்திரத்தில் சூவாரின் குமாரன் நெதனெயேல்.',	4,	1,	8),
(3614,	'Of Zebulun; Eliab the son of Helon.',	'செபுலோன் கோத்திரத்தில் ஏலோனின் குமாரன் எலியாப்.',	4,	1,	9),
(3615,	'Of the children of Joseph: of Ephraim; Elishama the son of Ammihud: of Manasseh; Gamaliel the son of Pedahzur.',	'யோசேப்பின் குமாரராகிய எப்பிராயீம் கோத்திரத்தில் அம்மியூதின் குமாரன் எலிஷாமா; மனாசே கோத்திரத்தில் பெதாசூரின் குமாரன் கமாலியேல்.',	4,	1,	10),
(3616,	'Of Benjamin; Abidan the son of Gideoni.',	'பென்யமீன் கோத்திரத்தில் கீதெயோனின் குமாரன் அபீதான்.',	4,	1,	11),
(3617,	'Of Dan; Ahiezer the son of Ammishaddai.',	'தாண் கோத்திரத்தில் அம்மீஷதாயின் குமாரன் அகியேசேர்.',	4,	1,	12),
(3618,	'Of Asher; Pagiel the son of Ocran.',	'ஆசேர் கோத்திரத்தில் ஓகிரானின் குமாரன் பாகியேல்.',	4,	1,	13),
(3619,	'Of Gad; Eliasaph the son of Deuel.',	'காத் கோத்திரத்தில் தேகுவேலின் குமாரன் எலியாசாப்.',	4,	1,	14),
(3620,	'Of Naphtali; Ahira the son of Enan.',	'நப்தலி கோத்திரத்தில் ஏனானின் குமாரன் அகீரா.',	4,	1,	15),
(3621,	'These were the renowned of the congregation, princes of the tribes of their fathers, heads of thousands in Israel.',	'இவர்களே சபையில் ஏற்படுத்தப்பட்டவர்களும், தங்கள் தங்கள் பிதாக்களுடைய கோத்திரங்களில் பிரபுக்களும், இஸ்ரவேலில் ஆயிரவர்களுக்குத் தலைவருமாயிருப்பவர்கள் என்றார்.',	4,	1,	16),
(3622,	'And Moses and Aaron took these men which are expressed by their names:',	'அப்படியே மோசேயும் ஆரோனும் பேர்பேராகக் குறிக்கப்பட்ட இந்த மனிதரைக் கூட்டிக்கொண்டு,',	4,	1,	17),
(3623,	'And they assembled all the congregation together on the first day of the second month, and they declared their pedigrees after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, by their polls.',	'இரண்டாம் மாதம் முதல் தேதியில் சபையார் எல்லாரையும் கூடிவரச்செய்தார்கள். அப்பொழுது அவர்கள் தங்கள்தங்கள் குடும்பத்தின்படிக்கும், பிதாக்களுடைய வம்சத்தின்படிக்கும், நாமத்தொகையின்படிக்கும், இருபது வயதுள்ளவர்கள்முதல் தலைதலையாகத் தங்கள் வம்ச உற்பத்தியைத் தெரிவித்தார்கள்.',	4,	1,	18),
(3624,	'As the LORD commanded Moses, so he numbered them in the wilderness of Sinai.',	'இப்படிக் கர்த்தர் கட்டளையிட்டபடியே, மோசே அவர்களைச் சீனாய் வனாந்தரத்தில் எண்ணிப்பார்த்தான்.',	4,	1,	19),
(3625,	'And the children of Reuben, Israel\'s eldest son, by their generations, after their families, by the house of their fathers, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;',	'இஸ்ரவேலின் மூத்தகுமாரனாகிய ரூபன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,',	4,	1,	20),
(3626,	'Those that were numbered of them, even of the tribe of Reuben, were forty and six thousand and five hundred.',	'ரூபன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.',	4,	1,	21),
(3627,	'Of the children of Simeon, by their generations, after their families, by the house of their fathers, those that were numbered of them, according to the number of the names, by their polls, every male from twenty years old and upward, all that were able to go forth to war;',	'சிமியோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் தலைதலையாக எண்ணப்பட்டபோது,',	4,	1,	22),
(3628,	'Those that were numbered of them, even of the tribe of Simeon, were fifty and nine thousand and three hundred.',	'சிமியோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.',	4,	1,	23),
(3629,	'Of the children of Gad, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'காத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	24),
(3630,	'Those that were numbered of them, even of the tribe of Gad, were forty and five thousand six hundred and fifty.',	'காத் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.',	4,	1,	25),
(3631,	'Of the children of Judah, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'யூதா புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	26),
(3632,	'Those that were numbered of them, even of the tribe of Judah, were threescore and fourteen thousand and six hundred.',	'யூதா கோத்திரத்தில் எண்ணப்பட்டவர்கள், எழுபத்து நாலாயிரத்து அறுநூறுபேர்.',	4,	1,	27),
(3633,	'Of the children of Issachar, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'இசக்கார் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	28),
(3634,	'Those that were numbered of them, even of the tribe of Issachar, were fifty and four thousand and four hundred.',	'இசக்கார் கோத்திரத்தில் எண்ணப்பட்டவர்கள் ஐம்பத்து நாலாயிரத்து நானூறுபேர்.',	4,	1,	29),
(3635,	'Of the children of Zebulun, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'செபுலோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	30),
(3636,	'Those that were numbered of them, even of the tribe of Zebulun, were fifty and seven thousand and four hundred.',	'செபுலோன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்தேழாயிரத்து நானூறுபேர்.',	4,	1,	31),
(3637,	'Of the children of Joseph, namely, of the children of Ephraim, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'யோசேப்பின் குமாரரில் எப்பிராயீம் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	32),
(3638,	'Those that were numbered of them, even of the tribe of Ephraim, were forty thousand and five hundred.',	'எப்பிராயீம் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பதினாயிரத்து ஐந்நூறுபேர்.',	4,	1,	33),
(3639,	'Of the children of Manasseh, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'மனாசே புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	34),
(3640,	'Those that were numbered of them, even of the tribe of Manasseh, were thirty and two thousand and two hundred.',	'மனாசே கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தீராயிரத்து இருநூறுபேர்.',	4,	1,	35),
(3641,	'Of the children of Benjamin, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'பென்யமீன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	36),
(3642,	'Those that were numbered of them, even of the tribe of Benjamin, were thirty and five thousand and four hundred.',	'பென்யமீன் கோத்திரத்தில் எண்ணப்பட்டவர்கள், முப்பத்தையாயிரத்து நானூறுபேர்.',	4,	1,	37),
(3643,	'Of the children of Dan, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'தாண் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	38),
(3644,	'Those that were numbered of them, even of the tribe of Dan, were threescore and two thousand and seven hundred.',	'தாண் கோத்திரத்தில் எண்ணப்பட்டவர்கள், அறுபத்தீராயிரத்து எழுநூறுபேர்.',	4,	1,	39),
(3645,	'Of the children of Asher, by their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'ஆசேர் புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள் முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	40),
(3646,	'Those that were numbered of them, even of the tribe of Asher, were forty and one thousand and five hundred.',	'ஆசேர் கோத்திரத்தில் எண்ணப்பட்டவர்கள், நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.',	4,	1,	41),
(3647,	'Of the children of Naphtali, throughout their generations, after their families, by the house of their fathers, according to the number of the names, from twenty years old and upward, all that were able to go forth to war;',	'நப்தலி புத்திரருடைய பிதாக்களின் வீட்டு வம்சத்தாரில் இருபது வயதுள்ளவர்கள்முதல் யுத்தத்திற்குப் புறப்படத்தக்க புருஷர்கள் எல்லாரும் எண்ணப்பட்டபோது,',	4,	1,	42),
(3648,	'Those that were numbered of them, even of the tribe of Naphtali, were fifty and three thousand and four hundred.',	'நப்தலி கோத்திரத்தில் எண்ணப்பட்டவர்கள், ஐம்பத்து மூவாயிரத்து நானூறுபேர்.',	4,	1,	43),
(3649,	'These are those that were numbered, which Moses and Aaron numbered, and the princes of Israel, being twelve men: each one was for the house of his fathers.',	'எண்ணப்பட்டவர்கள் இவர்களே; மோசேயும் ஆரோனும் இஸ்ரவேலுடைய பிதாக்களின் வம்சத்தில் ஒவ்வொரு வம்சத்துக்கு ஒவ்வொரு பிரபுவாகிய பன்னிரண்டுபேரும் எண்ணினார்கள்.',	4,	1,	44),
(3650,	'So were all those that were numbered of the children of Israel, by the house of their fathers, from twenty years old and upward, all that were able to go forth to war in Israel;',	'இஸ்ரவேல் புத்திரருடைய பிதாக்களின் வம்சத்தில் இருபது வயதுள்ளவர்கள்முதல், இஸ்ரவேலில் யுத்தத்திற்குப் புறப்படத்தக்கவர்களாகிய எண்ணப்பட்ட பேர்கள் எல்லாரும்,',	4,	1,	45),
(3651,	'Even all they that were numbered were six hundred thousand and three thousand and five hundred and fifty.',	'ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.',	4,	1,	46),
(3652,	'But the Levites after the tribe of their fathers were not numbered among them.',	'லேவியர் தங்கள் பிதாக்களுடைய கோத்திரத்தின்படியே, மற்றவர்களுடனே எண்ணப்படவில்லை.',	4,	1,	47),
(3653,	'For the LORD had spoken unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	4,	1,	48),
(3654,	'Only thou shalt not number the tribe of Levi, neither take the sum of them among the children of Israel:',	'நீ லேவி கோத்திரத்தாரை மாத்திரம் எண்ணாமலும், இஸ்ரவேல் புத்திரருக்குள்ளே அவர்கள் தொகையை ஏற்றாமலும்,',	4,	1,	49),
(3655,	'But thou shalt appoint the Levites over the tabernacle of testimony, and over all the vessels thereof, and over all things that belong to it: they shall bear the tabernacle, and all the vessels thereof; and they shall minister unto it, and shall encamp round about the tabernacle.',	'லேவியரைச் சாட்சியின் வாசஸ்தலத்திற்கும், அதினுடைய சகல பணிமுட்டுகளுக்கும், அதிலுள்ள சமஸ்த பொருள்களுக்கும் விசாரிப்புக்காரராக ஏற்படுத்து; அவர்கள் வாசஸ்தலத்தையும் அதின் சகல பணிமுட்டுகளையும் சுமப்பார்களாக; அதினிடத்தில் ஊழியம் செய்து, வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.',	4,	1,	50),
(3656,	'And when the tabernacle setteth forward, the Levites shall take it down: and when the tabernacle is to be pitched, the Levites shall set it up: and the stranger that cometh nigh shall be put to death.',	'வாசஸ்தலம் புறப்படும்போது, லேவியர் அதை இறக்கிவைத்து, அது ஸ்தாபனம் பண்ணப்படும்போது, லேவியர் அதை எடுத்து நிறுத்தக்கடவர்கள்; அந்நியன் அதற்குச் சமீபத்தில் வந்தால் கொலை செய்யப்படக்கடவன்.',	4,	1,	51),
(3657,	'And the children of Israel shall pitch their tents, every man by his own camp, and every man by his own standard, throughout their hosts.',	'இஸ்ரவேல் புத்திரர் தங்கள் தங்கள் பாளயத்தோடும், தங்கள் தங்கள் சேனையின் கொடியோடும் கூடாரம் போடக்கடவர்கள்.',	4,	1,	52),
(3658,	'But the Levites shall pitch round about the tabernacle of testimony, that there be no wrath upon the congregation of the children of Israel: and the Levites shall keep the charge of the tabernacle of testimony.',	'இஸ்ரவேல் புத்திரராகிய சபையின்மேல் கடுங்கோபம் வராதபடிக்கு லேவியர் சாட்சியின் வாசஸ்தலத்தைச் சுற்றிலும் பாளயமிறங்கி, லேவியர் சாட்சியின் வாசஸ்தலத்தைக் காவல்காப்பார்களாக என்றார்.',	4,	1,	53),
(3659,	'And the children of Israel did according to all that the LORD commanded Moses, so did they.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி எல்லாவற்றையும் இஸ்ரவேல் புத்திரர் செய்தார்கள்.  ',	4,	1,	54),
(3660,	'And the LORD spake unto Moses and unto Aaron, saying,',	'கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	4,	2,	1),
(3661,	'Every man of the children of Israel shall pitch by his own standard, with the ensign of their father\'s house: far off about the tabernacle of the congregation shall they pitch.',	'இஸ்ரவேல் புத்திரர் அவரவர் தங்கள் தங்கள் பிதாக்களுடைய வம்சத்தின் விருதாகிய தங்கள் தங்கள் கொடியண்டையிலே தங்கள் கூடாரங்களைப் போட்டு, ஆசரிப்புக் கூடாரத்திற்கு எதிராகச் சுற்றிலும் பாளயமிறங்கக்கடவர்கள்.',	4,	2,	2),
(3662,	'And on the east side toward the rising of the sun shall they of the standard of the camp of Judah pitch throughout their armies: and Nahshon the son of Amminadab shall be captain of the children of Judah.',	'யூதாவின் பாளயத்துக் கொடியையுடைய சேனைகள் சூரியன் உதிக்கும் கீழ்ப்புறத்திலே பாளயமிறங்கவேண்டும்; அம்மினதாபின் குமாரனாகிய நகசோன் யூதா சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	3),
(3663,	'And his host, and those that were numbered of them, were threescore and fourteen thousand and six hundred.',	'எண்ணப்பட்ட அவனுடைய சேனை எழுபத்துநாலாயிரத்து அறுநூறுபேர்.',	4,	2,	4),
(3664,	'And those that do pitch next unto him shall be the tribe of Issachar: and Nethaneel the son of Zuar shall be captain of the children of Issachar.',	'அவன் அருகே இசக்கார் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூவாரின் குமாரன் நெதநெயேல் இசக்கார் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	5),
(3665,	'And his host, and those that were numbered thereof, were fifty and four thousand and four hundred.',	'எண்ணப்பட்ட அவனுடைய சேனை ஐம்பத்து நாலாயிரத்து நானூறுபேர்.',	4,	2,	6),
(3666,	'Then the tribe of Zebulun: and Eliab the son of Helon shall be captain of the children of Zebulun.',	'அவன் அருகே செபுலோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏலோனின் குமாரனாகிய எலியாப் செபுலோன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	7),
(3667,	'And his host, and those that were numbered thereof, were fifty and seven thousand and four hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தேழாயிரத்து நானூறுபேர்.',	4,	2,	8),
(3668,	'All that were numbered in the camp of Judah were an hundred thousand and fourscore thousand and six thousand and four hundred, throughout their armies. These shall first set forth.',	'எண்ணப்பட்ட யூதாவின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்பத்து ஆறாயிரத்து நானூறுபேர்; இவர்கள் பிரயாணத்திலே முதற்பாளயமாய்ப் போகக்கடவர்கள்.',	4,	2,	9),
(3669,	'On the south side shall be the standard of the camp of Reuben according to their armies: and the captain of the children of Reuben shall be Elizur the son of Shedeur.',	'ரூபனுடைய பாளயத்துக் கொடியையுடைய சேனைகள் தென்புறத்தில் பாளயமிறங்கவேண்டும்; சேதேயூரின் குமாரனாகிய எலிசூர் ரூபன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	10),
(3670,	'And his host, and those that were numbered thereof, were forty and six thousand and five hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தாறாயிரத்து ஐந்நூறுபேர்.',	4,	2,	11),
(3671,	'And those which pitch by him shall be the tribe of Simeon: and the captain of the children of Simeon shall be Shelumiel the son of Zurishaddai.',	'அவன் அருகே சிமியோன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; சூரிஷதாயின் குமாரனாகிய செலூமியேல் சிமியோன் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	12),
(3672,	'And his host, and those that were numbered of them, were fifty and nine thousand and three hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்தொன்பதினாயிரத்து முந்நூறுபேர்.',	4,	2,	13),
(3673,	'Then the tribe of Gad: and the captain of the sons of Gad shall be Eliasaph the son of Reuel.',	'அவன் அருகே காத் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; தேகுவேலின் குமாரனாகிய எலியாசாப் காத் சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	14),
(3674,	'And his host, and those that were numbered of them, were forty and five thousand and six hundred and fifty.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தையாயிரத்து அறுநூற்று ஐம்பதுபேர்.',	4,	2,	15),
(3675,	'All that were numbered in the camp of Reuben were an hundred thousand and fifty and one thousand and four hundred and fifty, throughout their armies. And they shall set forth in the second rank.',	'எண்ணப்பட்ட ரூபனின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து ஐம்பத்து ஓராயிரத்து நானூற்று ஐம்பதுபேர்; இவர்கள் பிராயணத்தில் இரண்டாம் பாளயமாய்ப் போகக்கடவர்கள்.',	4,	2,	16),
(3676,	'Then the tabernacle of the congregation shall set forward with the camp of the Levites in the midst of the camp: as they encamp, so shall they set forward, every man in his place by their standards.',	'பின்பு ஆசரிப்புக்கூடாரம் லேவியரின் சேனையோடே பாளயங்களின் நடுவே பிரயாணப்பட்டுப் போகவேண்டும்; எப்படிப் பாளயமிறங்குகிறார்களோ, அப்படியே அவரவர் தங்கள் வரிசையிலே தங்கள் கொடிகளோடே பிரயாணமாய்ப் போகக்கடவர்கள்.',	4,	2,	17),
(3677,	'On the west side shall be the standard of the camp of Ephraim according to their armies: and the captain of the sons of Ephraim shall be Elishama the son of Ammihud.',	'எப்பிராயீமுடைய பாளயத்துக்கொடியையுடைய சேனைகள் மேல்புறத்தில் இறங்கவேண்டும், அம்மியூதின் குமாரனாகிய எலிஷாமா எப்பிராயீமின் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	18),
(3678,	'And his host, and those that were numbered of them, were forty thousand and five hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பதினாயிரத்து ஐந்நூறுபேர்.',	4,	2,	19),
(3679,	'And by him shall be the tribe of Manasseh: and the captain of the children of Manasseh shall be Gamaliel the son of Pedahzur.',	'அவன் அருகே மனாசே கோத்திரத்தார் பாளயமிறங்கவேண்டும்; பெதாசூரின் குமாரனாகிய கமாலியேல் மனாசே சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	20),
(3680,	'And his host, and those that were numbered of them, were thirty and two thousand and two hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தீராயிரத்து இருநூறுபேர்.',	4,	2,	21),
(3681,	'Then the tribe of Benjamin: and the captain of the sons of Benjamin shall be Abidan the son of Gideoni.',	'அவன் அருகே பென்யமீன் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; கீதெயோனின் குமாரனாகிய அபீதான் பென்யமீன் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	22),
(3682,	'And his host, and those that were numbered of them, were thirty and five thousand and four hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் முப்பத்தையாயிரத்து நானூறுபேர்.',	4,	2,	23),
(3683,	'All that were numbered of the camp of Ephraim were an hundred thousand and eight thousand and an hundred, throughout their armies. And they shall go forward in the third rank.',	'எண்ணப்பட்ட எப்பிராயீமின் பாளயத்தார் எல்லாரும் தங்கள் சேனைகளின்படியே இலட்சத்து எண்ணாயிரத்து நூறுபேர்; இவர்கள் பிரயாணத்தில் மூன்றாம் பாளயமாய்ப் போகக்கடவர்கள்.',	4,	2,	24),
(3684,	'The standard of the camp of Dan shall be on the north side by their armies: and the captain of the children of Dan shall be Ahiezer the son of Ammishaddai.',	'தாணுடைய பாளயத்துக் கொடியையுடைய சேனைகள் வடபுறத்தில் இறங்கவேண்டும்; அம்மிஷதாயின் குமாரனாகிய அகியேசேர் தாண் வம்சத்திற்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	25),
(3685,	'And his host, and those that were numbered of them, were threescore and two thousand and seven hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் அறுபத்தீராயிரத்து எழுநூறுபேர்.',	4,	2,	26),
(3686,	'And those that encamp by him shall be the tribe of Asher: and the captain of the children of Asher shall be Pagiel the son of Ocran.',	'அவன் அருகே ஆசேர் கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஓகிரானின் குமாரனாகிய பாகியேல் ஆசேர் சந்ததிக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	27),
(3687,	'And his host, and those that were numbered of them, were forty and one thousand and five hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் நாற்பத்தோராயிரத்து ஐந்நூறுபேர்.',	4,	2,	28),
(3688,	'Then the tribe of Naphtali: and the captain of the children of Naphtali shall be Ahira the son of Enan.',	'அவன் அருகே நப்தலி கோத்திரத்தார் பாளயமிறங்கவேண்டும்; ஏனானின் குமாரனாகிய அகீரா நப்தலி சந்ததியாருக்குச் சேனாபதியாயிருக்கக்கடவன்.',	4,	2,	29),
(3689,	'And his host, and those that were numbered of them, were fifty and three thousand and four hundred.',	'அவனுடைய சேனையில் எண்ணப்பட்டவர்கள் ஐம்பத்து மூவாயிரத்து நானூறுபேர்.',	4,	2,	30),
(3690,	'All they that were numbered in the camp of Dan were an hundred thousand and fifty and seven thousand and six hundred. They shall go hindmost with their standards.',	'எண்ணப்பட்ட தாணின் பாளயத்தார் எல்லாரும் இலட்சத்து ஐம்பத்தேழாயிரத்து அறுநூறுபேர்; இவர்கள் தங்கள் கொடிகளோடே பின்பாளயமாய்ப் போகக்கடவர்கள்.',	4,	2,	31),
(3691,	'These are those which were numbered of the children of Israel by the house of their fathers: all those that were numbered of the camps throughout their hosts were six hundred thousand and three thousand and five hundred and fifty.',	'இவர்களே தங்கள் தங்கள் பிதாக்களின் வம்சத்தின்படி இஸ்ரவேல் புத்திரரில் எண்ணப்பட்டவர்கள். பாளயங்களிலே தங்கள் தங்கள் சேனைகளின்படியே எண்ணப்பட்டவர்கள் எல்லாரும் ஆறுலட்சத்து மூவாயிரத்து ஐந்நூற்று ஐம்பது பேராயிருந்தார்கள்.',	4,	2,	32),
(3692,	'But the Levites were not numbered among the children of Israel; as the LORD commanded Moses.',	'லேவியரோ, கர்த்தர் மோசேக்குக் கட்டளையிட்டபடி, இஸ்ரவேல் புத்திரருக்குள்ளே எண்ணப்படவில்லை.',	4,	2,	33),
(3693,	'And the children of Israel did according to all that the LORD commanded Moses: so they pitched by their standards, and so they set forward, every one after their families, according to the house of their fathers.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியெல்லாம் இஸ்ரவேல் புத்திரர் செய்து, தங்கள் தங்கள் கொடிகளின்கீழ் பாளயமிறங்கி, தங்கள் தங்கள் பிதாக்களுடைய வம்சங்களின்படியே பிரயாணப்பட்டுப் போனார்கள்.  ',	4,	2,	34),
(3694,	'These also are the generations of Aaron and Moses in the day that the LORD spake with Moses in mount Sinai.',	'சீனாய் மலையில் கர்த்தர் மோசேயோடே பேசின நாளிலே, ஆரோன் மோசே என்பவர்களுடைய வம்சவரலாறாவது:',	4,	3,	1),
(3695,	'And these are the names of the sons of Aaron; Nadab the firstborn, and Abihu, Eleazar, and Ithamar.',	'ஆரோனுடைய குமாரர், முதல் பிறந்தவனாகிய நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்பவர்களே.',	4,	3,	2),
(3696,	'These are the names of the sons of Aaron, the priests which were anointed, whom he consecrated to minister in the priest\'s office.',	'ஆசாரிய ஊழியம் செய்கிறதற்கு அவனால் பிரதிஷ்டை செய்யப்பட்டு அபிஷேகம் பெற்ற ஆசாரியரான ஆரோனுடைய குமாரரின் நாமங்கள் இவைகளே.',	4,	3,	3),
(3697,	'And Nadab and Abihu died before the LORD, when they offered strange fire before the LORD, in the wilderness of Sinai, and they had no children: and Eleazar and Ithamar ministered in the priest\'s office in the sight of Aaron their father.',	'நாதாபும் அபியூவும் சீனாய் வனாந்தரத்தில் அந்நிய அக்கினியைக் கர்த்தருடைய சந்நிதியில் கொண்டுவந்தபோது, கர்த்தருடைய சந்நிதியில் மரித்துப்போனார்கள்; அவர்களுக்குப் பிள்ளைகள் இல்லை; எலெயாசாரும் இத்தாமாருமே தங்கள் தகப்பனாகிய ஆரோனுக்கு முன்பாக ஆசாரிய ஊழியம் செய்தார்கள்;',	4,	3,	4),
(3698,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	4,	3,	5),
(3699,	'Bring the tribe of Levi near, and present them before Aaron the priest, that they may minister unto him.',	'நீ லேவிகோத்திரத்தாரைச் சேர்த்து, அவர்கள் ஆசாரியனாகிய ஆரோனுக்குப் பணிவிடை செய்யும்படி அவர்களை நிறுத்து.',	4,	3,	6),
(3700,	'And they shall keep his charge, and the charge of the whole congregation before the tabernacle of the congregation, to do the service of the tabernacle.',	'அவர்கள் ஆசரிப்புக் கூடாரத்துக்கு முன்பாக அவனுடைய காவலையும் எல்லாச் சபையின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடை வேலைகளைச் செய்யக்கடவர்கள்.',	4,	3,	7),
(3701,	'And they shall keep all the instruments of the tabernacle of the congregation, and the charge of the children of Israel, to do the service of the tabernacle.',	'அவர்கள் ஆசரிப்புக் கூடாரத்தின் தட்டுமுட்டு முதலானவைகளையும், இஸ்ரவேல் புத்திரரின் காவலையும் காத்து, வாசஸ்தலத்தின் பணிவிடைகளைச் செய்யக்கடவர்கள்.',	4,	3,	8),
(3702,	'And thou shalt give the Levites unto Aaron and to his sons: they are wholly given unto him out of the children of Israel.',	'ஆகையால் லேவியரை ஆரோனிடத்திலும் அவன் குமாரரிடத்திலும் ஒப்புக்கொடுப்பாயாக; இஸ்ரவேல் புத்திரரில் இவர்கள் முற்றிலும் அவனுக்கு ஒப்புக்கொடுக்கப்பட்டிருக்கிறார்கள்.',	4,	3,	9),
(3703,	'And thou shalt appoint Aaron and his sons, and they shall wait on their priest\'s office: and the stranger that cometh nigh shall be put to death.',	'ஆரோனையும் அவன் குமாரரையுமோ, தங்கள் ஆசாரிய ஊழியத்தைச் செய்வதற்காக நியமிக்கக்கடவாய், அந்த ஊழியத்தைச் செய்யும்படி சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன் என்றார்.',	4,	3,	10),
(3704,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	4,	3,	11),
(3705,	'And I, behold, I have taken the Levites from among the children of Israel instead of all the firstborn that openeth the matrix among the children of Israel: therefore the Levites shall be mine;',	'இஸ்ரவேல் புத்திரரில் கர்ப்பந்திறந்து பிறக்கிற முதற்பேறான யாவுக்கும் பதிலாக, நான் லேவியரை இஸ்ரவேல் புத்திரரிலிருந்து எடுத்துக்கொண்டேன்; அவர்கள் என்னுடையவர்களாயிருக்கிறார்கள்.',	4,	3,	12),
(3706,	'Because all the firstborn are mine; for on the day that I smote all the firstborn in the land of Egypt I hallowed unto me all the firstborn in Israel, both man and beast: mine shall they be: I am the LORD.',	'முதற்பேறானவையெல்லாம் என்னுடையவை; நான் எகிப்துதேசத்தில் முதற்பேறான யாவையும் சங்கரித்த நாளில், இஸ்ரவேலில் மனிதர்முதல் மிருகஜீவன் மட்டுமுள்ள முதற்பேறான யாவையும் எனக்கென்று பரிசுத்தப்படுத்தினதினாலே, அவைகள் என்னுடையவைகளாயிருக்கும்; நான் கர்த்தர் என்றார்.',	4,	3,	13),
(3707,	'And the LORD spake unto Moses in the wilderness of Sinai, saying,',	'பின்னும் கர்த்தர் சீனாய் வனாந்தரத்தில் மோசேயை நோக்கி:',	4,	3,	14),
(3708,	'Number the children of Levi after the house of their fathers, by their families: every male from a month old and upward shalt thou number them.',	'லேவிபுத்திரரை அவர்கள் பிதாக்களின் வம்சங்களின்படியே எண்ணுவாயாக; அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் எண்ணுவாயாக என்றார்.',	4,	3,	15),
(3709,	'And Moses numbered them according to the word of the LORD, as he was commanded.',	'அப்பொழுது கர்த்தருடைய வாக்கின்படி, மோசே தனக்குக் கற்பிக்கப்பட்ட பிரகாரம் அவர்களை எண்ணினான்.',	4,	3,	16),
(3710,	'And these were the sons of Levi by their names; Gershon, and Kohath, and Merari.',	'லேவியின் குமாரர் தங்கள் நாமங்களின்படியே, கெர்சோன், கோகாத், மெராரி என்பவர்கள்.',	4,	3,	17),
(3711,	'And these are the names of the sons of Gershon by their families; Libni, and Shimei.',	'தங்கள் வம்சத்தின்படியே கெர்சோனுடைய குமாரரின் நாமங்கள், லிப்னீ, சீமேயி என்பவைகள்.',	4,	3,	18),
(3712,	'And the sons of Kohath by their families; Amram, and Izehar, Hebron, and Uzziel.',	'தங்கள் வம்சங்களின்படியே கோகாத்துடைய குமாரர் அம்ராம், இத்சேயார், எப்ரோன், ஊசியேல் என்பவர்கள்.',	4,	3,	19),
(3713,	'And the sons of Merari by their families; Mahli, and Mushi. These are the families of the Levites according to the house of their fathers.',	'தங்கள் வம்சங்களின்படியே மெராரியினுடைய குமாரர், மகேலி, மூசி என்பவர்கள்; இவர்களே லேவியருடைய பிதாக்களின் வம்சத்தார்.',	4,	3,	20),
(3714,	'Of Gershon was the family of the Libnites, and the family of the Shimites: these are the families of the Gershonites.',	'கெர்சோனின் வழியாய் லிப்னீயரின் வம்சமும் சீமேயியர் வம்சமும் தோன்றின; இவைகளே கெர்சோனியரின் வம்சங்கள்.',	4,	3,	21),
(3715,	'Those that were numbered of them, according to the number of all the males, from a month old and upward, even those that were numbered of them were seven thousand and five hundred.',	'அவர்களில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஏழாயிரத்து ஐந்நூறுபேராயிருந்தார்கள்.',	4,	3,	22),
(3716,	'The families of the Gershonites shall pitch behind the tabernacle westward.',	'கெர்சோனியரின் வம்சங்கள் வாசஸ்தலத்தின் பின்புறத்தில் மேற்கே பாளயமிறங்கவேண்டும்.',	4,	3,	23),
(3717,	'And the chief of the house of the father of the Gershonites shall be Eliasaph the son of Lael.',	'கெர்சோனியருடைய தகப்பன் வம்சத்துக்குத் தலைவன் லாயேலின் குமாரனாகிய எலியாசாப் என்பவன்.',	4,	3,	24),
(3718,	'And the charge of the sons of Gershon in the tabernacle of the congregation shall be the tabernacle, and the tent, the covering thereof, and the hanging for the door of the tabernacle of the congregation,',	'ஆசரிப்புக் கூடாரத்திலே கெர்சோன் புத்திரரின் காவலாவது: வாசஸ்தலமும், கூடாரமும், அதின் மூடியும், ஆசரிப்புக் கூடாரவாசல் மறைவும்,',	4,	3,	25),
(3719,	'And the hangings of the court, and the curtain for the door of the court, which is by the tabernacle, and by the altar round about, and the cords of it for all the service thereof.',	'வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தின் தொங்குதிரைகளும், பிராகாரவாசல் மூடுதிரையும், அவைகளின் வேலைகளுக்கெல்லாம் உரிய அவைகளின் கயிறுகளுமே.',	4,	3,	26),
(3720,	'And of Kohath was the family of the Amramites, and the family of the Izeharites, and the family of the Hebronites, and the family of the Uzzielites: these are the families of the Kohathites.',	'கோகாத்தின் வழியாய் அம்ராமியரின் வம்சமும் இத்சேயாரின் வம்சமும் எப்ரோனியரின் வம்சமும் ஊசியேலரின் வம்சமும் தோன்றின; இவைகளே கோகாத்தியரின் வம்சங்கள்.',	4,	3,	27),
(3721,	'In the number of all the males, from a month old and upward, were eight thousand and six hundred, keeping the charge of the sanctuary.',	'ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, பரிசுத்த ஸ்தலத்துக்குரியவைகளைக் காப்பவர்கள், எண்ணாயிரத்து அறுநூறுபேராயிருந்தார்கள்.',	4,	3,	28),
(3722,	'The families of the sons of Kohath shall pitch on the side of the tabernacle southward.',	'கோகாத் புத்திரரின் வம்சங்கள் வாசஸ்தலத்தின் தென்புறமான பக்கத்திலே பாளயமிறங்கவேண்டும்.',	4,	3,	29),
(3723,	'And the chief of the house of the father of the families of the Kohathites shall be Elizaphan the son of Uzziel.',	'அவர்களின் தலைவன், ஊசியேலின் குமாரனாகிய எல்சாபான்.',	4,	3,	30),
(3724,	'And their charge shall be the ark, and the table, and the candlestick, and the altars, and the vessels of the sanctuary wherewith they minister, and the hanging, and all the service thereof.',	'அவர்களுடைய காவலாவது: பெட்டியும், மேஜையும், குத்துவிளக்கும், பீடங்களும், ஆராதனைக்கேற்ற பரிசுத்த ஸ்தலத்தின் பணிமுட்டுகளும், தொங்குதிரையும், அதினுடைய எல்லா வேலைகளுக்கும் ஏற்றவைகளுமே.',	4,	3,	31),
(3725,	'And Eleazar the son of Aaron the priest shall be chief over the chief of the Levites, and have the oversight of them that keep the charge of the sanctuary.',	'ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார் என்பவன் லேவியருடைய தலைவர்களுக்குத் தலைவனாய்ப் பரிசுத்த ஸ்தலத்தைக் காவல்காக்கிறவர்களுக்கு விசாரிப்புக்காரனாயிருக்கவேண்டும்.',	4,	3,	32),
(3726,	'Of Merari was the family of the Mahlites, and the family of the Mushites: these are the families of Merari.',	'மெராரியின் வழியாய் மகேலியரின் வம்சமும் மூசியரின் வம்சமும் தோன்றின; இவைகளே மெராரியின் வம்சங்கள்.',	4,	3,	33),
(3727,	'And those that were numbered of them, according to the number of all the males, from a month old and upward, were six thousand and two hundred.',	'அவர்களில் ஒரு மாதம் முதல் அதற்குமேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளெல்லாம் எண்ணப்பட்டபோது, எண்ணப்பட்டவர்கள் ஆறாயிரத்து இருநூறுபேராயிருந்தார்கள்.',	4,	3,	34),
(3728,	'And the chief of the house of the father of the families of Merari was Zuriel the son of Abihail: these shall pitch on the side of the tabernacle northward.',	'அபியாயேலின் குமாரனாகிய சூரியேல் என்பவன் அவர்களுக்குத் தலைவனாயிருந்தான்; இவர்கள் வாசஸ்தலத்தின் வடபுறமான பக்கத்தில் பாளயமிறங்கவேண்டும்.',	4,	3,	35),
(3729,	'And under the custody and charge of the sons of Merari shall be the boards of the tabernacle, and the bars thereof, and the pillars thereof, and the sockets thereof, and all the vessels thereof, and all that serveth thereto,',	'அவர்களுடைய காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும், அதினுடைய எல்லாப் பணிமுட்டுகளும், அதற்கடுத்தவைகள் அனைத்தும்,',	4,	3,	36),
(3730,	'And the pillars of the court round about, and their sockets, and their pins, and their cords.',	'சுற்றுப்பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளுமே.',	4,	3,	37),
(3731,	'But those that encamp before the tabernacle toward the east, even before the tabernacle of the congregation eastward, shall be Moses, and Aaron and his sons, keeping the charge of the sanctuary for the charge of the children of Israel; and the stranger that cometh nigh shall be put to death.',	'ஆசரிப்புக் கூடாரமாகிய வாசஸ்தலத்துக்கு முன்பாக, சூரியன் உதிக்கும் கீழ்ப்புறத்திலே மோசேயும் ஆரோனும் அவன் குமாரரும் கூடாரங்களைப் போட்டு இறங்கி, இஸ்ரவேல் புத்திரரின் காவலுக்குப் பதிலாகப் பரிசுத்த ஸ்தலத்தைக் காவல் காக்கவேண்டும். வாசஸ்தலத்தில் சேருகிற அந்நியன் கொலைசெய்யப்படக்கடவன்.',	4,	3,	38),
(3732,	'All that were numbered of the Levites, which Moses and Aaron numbered at the commandment of the LORD, throughout their families, all the males from a month old and upward, were twenty and two thousand.',	'மோசேயும், ஆரோனும், கர்த்தருடைய வாக்கின்படி, லேவியரில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள ஆண்பிள்ளைகளையெல்லாம் அவர்களுடைய வம்சங்களின்படியே எண்ணினார்கள்; அவர்கள் இருபத்தீராயிரம்பேராயிருந்தார்கள்.',	4,	3,	39),
(3733,	'And the LORD said unto Moses, Number all the firstborn of the males of the children of Israel from a month old and upward, and take the number of their names.',	'அதன் பின்பு கர்த்தர் மோசேயை நோக்கி: நீ இஸ்ரவேல் புத்திரரில் ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளையெல்லாம் எண்ணி அவர்கள் நாமங்களைத் தொகையேற்றி,',	4,	3,	40),
(3734,	'And thou shalt take the Levites for me (I am the LORD) instead of all the firstborn among the children of Israel; and the cattle of the Levites instead of all the firstlings among the cattle of the children of Israel.',	'இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவுக்கும் பதிலாக லேவியரையும், இஸ்ரவேல் புத்திரரின் மிருகஜீவன்களிலுள்ள தலையீற்றான யாவுக்கும் பதிலாக லேவியரின் மிருகஜீவன்களையும் எனக்கென்று பிரித்தெடு; நான் கர்த்தர் என்றார்.',	4,	3,	41),
(3735,	'And Moses numbered, as the LORD commanded him, all the firstborn among the children of Israel.',	'அப்பொழுது மோசே, கர்த்தர் தனக்குக் கட்டளையிட்டபடியே, இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவரையும் எண்ணினான்.',	4,	3,	42),
(3736,	'And all the firstborn males by the number of names, from a month old and upward, of those that were numbered of them, were twenty and two thousand two hundred and threescore and thirteen.',	'ஒரு மாதம் முதல் அதற்கு மேற்பட்ட வயதுள்ள முதற்பேறான ஆண்பிள்ளைகளெல்லாரும் பேர்பேராக எண்ணப்பட்டபோது, இருபத்தீராயிரத்து இருநூற்று எழுபத்துமூன்றுபேராயிருந்தார்கள்.',	4,	3,	43),
(3737,	'And the LORD spake unto Moses, saying,',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி:',	4,	3,	44),
(3738,	'Take the Levites instead of all the firstborn among the children of Israel, and the cattle of the Levites instead of their cattle; and the Levites shall be mine: I am the LORD.',	'நீ இஸ்ரவேல் புத்திரரிலுள்ள முதற்பேறான யாவருக்கும் பதிலாக லேவியரையும், அவர்களுடைய மிருகஜீவன்களுக்குப்பதிலாக லேவியரின் மிருகஜீவன்களையும் பிரித்தெடு; லேவியர் என்னுடையவர்களாயிருப்பார்கள்; நான் கர்த்தர்.',	4,	3,	45),
(3739,	'And for those that are to be redeemed of the two hundred and threescore and thirteen of the firstborn of the children of Israel, which are more than the Levites;',	'இஸ்ரவேல் புத்திரருடைய முதற்பேறுகளில் லேவியரின் தொகைக்கு அதிகமாயிருந்து, மீட்கப்படவேண்டிய இருநூற்று எழுபத்துமூன்றுபேரிடத்திலும்,',	4,	3,	46),
(3740,	'Thou shalt even take five shekels apiece by the poll, after the shekel of the sanctuary shalt thou take them: (the shekel is twenty gerahs:)',	'நீ தலைக்கு ஐந்து சேக்கல் வீதமாகப் பரிசுத்த சேக்கல் கணக்கின்படி வாங்குவாயாக; அந்தச் சேக்கலானது இருபது கேரா.',	4,	3,	47),
(3741,	'And thou shalt give the money, wherewith the odd number of them is to be redeemed, unto Aaron and to his sons.',	'லேவியருடைய தொகைக்கு அதிகமானவர்கள் மீட்கப்படும் திரவியத்தை ஆரோனுக்கும் அவன் குமாரருக்கும் கொடுப்பாயாக என்றார்.',	4,	3,	48),
(3742,	'And Moses took the redemption money of them that were over and above them that were redeemed by the Levites:',	'அப்படியே லேவியரால் மீட்கப்பட்டவர்களின் தொகைக்கு அதிகமாயிருந்து, இன்னும் மீட்கப்படவேண்டியவர்களுக்கு ஈடாக மோசே இஸ்ரவேல் புத்திரருடைய முதற்பேறானவர்களிடத்தில்,',	4,	3,	49),
(3743,	'Of the firstborn of the children of Israel took he the money; a thousand three hundred and threescore and five shekels, after the shekel of the sanctuary:',	'ஆயிரத்து முந்நூற்று அறுபத்தைந்து சேக்கலாகிய திரவியத்தை, பரிசுத்த ஸ்தலத்துச் சேக்கல் கணக்கின்படி வாங்கி,',	4,	3,	50),
(3744,	'And Moses gave the money of them that were redeemed unto Aaron and to his sons, according to the word of the LORD, as the LORD commanded Moses.',	'கர்த்தருடைய வாக்கின்படியே மீட்கப்பட்டவர்களின் கிரயத்தை ஆரோனுக்கும் அவன் குமாரருக்கும், கர்த்தர் தனக்குக் கட்டளையிட்டபடியே கொடுத்தான்.  ',	4,	3,	51),
(3745,	'And the LORD spake unto Moses and unto Aaron, saying,',	'கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	4,	4,	1),
(3746,	'Take the sum of the sons of Kohath from among the sons of Levi, after their families, by the house of their fathers,',	'லேவியின் புத்திரருக்குள்ளே இருக்கிற கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களில்,',	4,	4,	2),
(3747,	'From thirty years old and upward even until fifty years old, all that enter into the host, to do the work in the tabernacle of the congregation.',	'ஆசரிப்புக் கூடாரத்திலே வேலைசெய்யும் சேனைக்கு உட்படத்தக்க முப்பது வயது முதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகையிடுவாயாக.',	4,	4,	3),
(3748,	'This shall be the service of the sons of Kohath in the tabernacle of the congregation, about the most holy things:',	'ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரரின் பணிவிடை மகா பரிசுத்தமானவைகளுக்குரியது.',	4,	4,	4),
(3749,	'And when the camp setteth forward, Aaron shall come, and his sons, and they shall take down the covering vail, and cover the ark of testimony with it:',	'பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் வந்து, மறைவின் திரைச்சீலையை இறக்கி, அதினாலே சாட்சியின் பெட்டியை மூடி,',	4,	4,	5),
(3750,	'And shall put thereon the covering of badgers\' skins, and shall spread over it a cloth wholly of blue, and shall put in the staves thereof.',	'அதின்மேல் தகசுத்தோல் மூடியைப்போட்டு, அதின்மேல் முற்றிலும் நீலமானதுப்பட்டியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சி,',	4,	4,	6),
(3751,	'And upon the table of shewbread they shall spread a cloth of blue, and put thereon the dishes, and the spoons, and the bowls, and covers to cover withal: and the continual bread shall be thereon:',	'சமுகத்தப்ப மேஜையின்மேல் நீலத்துப்பட்டியை விரித்து, தட்டுகளையும் தூபக்கரண்டிகளையும் கிண்ணங்களையும் மூடுகிற தட்டுகளையும் அதின்மேல் வைப்பார்களாக; நித்திய அப்பமும் அதின்மேல் இருக்கக்கடவது.',	4,	4,	7),
(3752,	'And they shall spread upon them a cloth of scarlet, and cover the same with a covering of badgers\' skins, and shall put in the staves thereof.',	'அவைகளின்மேல் அவர்கள் சிவப்புத்துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,',	4,	4,	8),
(3753,	'And they shall take a cloth of blue, and cover the candlestick of the light, and his lamps, and his tongs, and his snuffdishes, and all the oil vessels thereof, wherewith they minister unto it:',	'இளநீலத் துப்பட்டியை எடுத்து, குத்துவிளக்குத்தண்டையும், அதின் அகல்களையும், அதின் கத்தரிகளையும், சாம்பல் பாத்திரங்களையும், அதற்குரிய எண்ணெய்ப் பாத்திரங்களையும் மூடி,',	4,	4,	9),
(3754,	'And they shall put it and all the vessels thereof within a covering of badgers\' skins, and shall put it upon a bar.',	'அதையும் அதற்கடுத்த தட்டுமுட்டுகள் யாவையும் தகசுத்தோல் மூடிக்குள்ளே போட்டு, அதை ஒரு தண்டிலே கட்டி,',	4,	4,	10),
(3755,	'And upon the golden altar they shall spread a cloth of blue, and cover it with a covering of badgers\' skins, and shall put to the staves thereof:',	'பொற்பீடத்தின்மேல் இளநீலத் துப்பட்டியை விரித்து, அதைத் தகசுத்தோல் மூடியால் மூடி, அதின் தண்டுகளைப் பாய்ச்சி,',	4,	4,	11),
(3756,	'And they shall take all the instruments of ministry, wherewith they minister in the sanctuary, and put them in a cloth of blue, and cover them with a covering of badgers\' skins, and shall put them on a bar:',	'பரிசுத்த ஸ்தலத்தில் வழங்கும் ஆராதனைக்கேற்ற சகல தட்டுமுட்டுகளையும் எடுத்து, இளநீலத் துப்பட்டியிலே போட்டு, தகசுத்தோல் மூடியினால் மூடி, தண்டின்மேல் கட்டி,',	4,	4,	12),
(3757,	'And they shall take away the ashes from the altar, and spread a purple cloth thereon:',	'பலிபீடத்தைச் சாம்பலற விளக்கி, அதின்மேல் இரத்தாம்பரத் துப்பட்டியை விரித்து,',	4,	4,	13),
(3758,	'And they shall put upon it all the vessels thereof, wherewith they minister about it, even the censers, the fleshhooks, and the shovels, and the basons, all the vessels of the altar; and they shall spread upon it a covering of badgers\' skins, and put to the staves of it.',	'அதின்மேல் ஆராதனைக்கேற்ற சகல பணிமுட்டுகளாகிய கலசங்களையும், முள்துறடுகளையும், சாம்பல் எடுக்கும் கரண்டிகளையும், கலசங்களையும், பலிபீடத்திற்கடுத்த எல்லாப் பாத்திரங்களையும், அதின்மேல் வைத்து, அதின்மேல் தகசுத்தோல் மூடியை விரித்து, அதின் தண்டுகளைப் பாய்ச்சக்கடவர்கள்.',	4,	4,	14),
(3759,	'And when Aaron and his sons have made an end of covering the sanctuary, and all the vessels of the sanctuary, as the camp is to set forward; after that, the sons of Kohath shall come to bear it: but they shall not touch any holy thing, lest they die. These things are the burden of the sons of Kohath in the tabernacle of the congregation.',	'பாளயம் புறப்படும்போது, ஆரோனும் அவன் குமாரரும் பரிசுத்த ஸ்தலத்தையும் அதினுடைய சகல பணிமுட்டுகளையும் மூடித் தீர்ந்தபின்பு, கோகாத் புத்திரர் அதை எடுத்துக்கொண்டுபோகிறதற்கு வரக்கடவர்கள்; அவர்கள் சாகாதபடிக்கு பரிசுத்தமானதைத் தொடாதிருக்கக்கடவர்கள்; ஆசரிப்புக் கூடாரத்திலே கோகாத் புத்திரர் சுமக்கும் சுமை இதுவே.',	4,	4,	15),
(3760,	'And to the office of Eleazar the son of Aaron the priest pertaineth the oil for the light, and the sweet incense, and the daily meat offering, and the anointing oil, and the oversight of all the tabernacle, and of all that therein is, in the sanctuary, and in the vessels thereof.',	'ஆசாரியனாகிய ஆரோனின் குமாரன் எலெயாசார், விளக்குக்கு எண்ணெயையும், சுகந்த தூபவர்க்கத்தையும், தினந்தோறும் இடும் போஜனபலியையும், அபிஷேகதைலத்தையும், வாசஸ்தலம் முழுவதையும், அதிலுள்ள யாவையும், பரிசுத்த ஸ்தலத்தையும் அதின் பணிமுட்டுகளையும், விசாரிக்கக்கடவன் என்றார்.',	4,	4,	16),
(3761,	'And the LORD spake unto Moses and unto Aaron saying,',	'கர்த்தர் மோசேயையும் ஆரோனையும் நோக்கி:',	4,	4,	17),
(3762,	'Cut ye not off the tribe of the families of the Kohathites from among the Levites:',	'லேவியருக்குள்ளே கோகாத் வம்சமாகிய கோத்திரத்தார் அழிந்துபோகாதபடி பாருங்கள்.',	4,	4,	18),
(3763,	'But thus do unto them, that they may live, and not die, when they approach unto the most holy things: Aaron and his sons shall go in, and appoint them every one to his service and to his burden:',	'அவர்கள் மகா பரிசுத்தமானவைகளைக் கிட்டுகையில், சாகாமல் உயிரோடிருக்கும்படிக்கு, நீங்கள் அவர்களுக்காகச் செய்யவேண்டியதாவது:',	4,	4,	19),
(3764,	'But they shall not go in to see when the holy things are covered, lest they die.',	'ஆரோனும் அவன் குமாரரும் வந்து, அவர்களில் அவனவனை அவனவன் செய்யும் வேலைக்கும் அவனவன் சுமக்கும் சுமைக்கும் நியமிக்கக்கடவர்கள்; அவர்களோ சாகாதபடிக்குப் பரிசுத்தமானவைகள் மூடப்படும்போது பார்க்கிறதற்கு உட்பிரவேசியாமல் இருப்பார்களாக என்றார்.',	4,	4,	20),
(3765,	'And the LORD spake unto Moses, saying,',	'பின்னும், கர்த்தர் மோசேயை நோக்கி:',	4,	4,	21),
(3766,	'Take also the sum of the sons of Gershon, throughout the houses of their fathers, by their families;',	'கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,',	4,	4,	22),
(3767,	'From thirty years old and upward until fifty years old shalt thou number them; all that enter in to perform the service, to do the work in the tabernacle of the congregation.',	'முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணி, தொகை ஏற்றுவாயாக.',	4,	4,	23),
(3768,	'This is the service of the families of the Gershonites, to serve, and for burdens:',	'பணிவிடை செய்கிறதிலும் சுமக்கிறதிலும் கெர்சோன் வம்சத்தாரின் வேலையாவது:',	4,	4,	24),
(3769,	'And they shall bear the curtains of the tabernacle, and the tabernacle of the congregation, his covering, and the covering of the badgers\' skins that is above upon it, and the hanging for the door of the tabernacle of the congregation,',	'அவர்கள் வாசஸ்தலத்துக்கும் ஆசரிப்புக் கூடாரத்துக்கும் உரிய தொங்குதிரையையும், மூடியையும், அவைகளின் மேல் இருக்கிற தகசுத்தோல் மூடியையும், ஆசரிப்புக் கூடாரவாசல் மறைவையும்,',	4,	4,	25),
(3770,	'And the hangings of the court, and the hanging for the door of the gate of the court, which is by the tabernacle and by the altar round about, and their cords, and all the instruments of their service, and all that is made for them: so shall they serve.',	'பிராகாரத்தின் தொங்குதிரைகளையும், வாசஸ்தலத்தண்டையிலும் பலிபீடத்தண்டையிலும் சுற்றிலும் இருக்கிற பிராகாரத்தினுடைய வாசல் தொங்குதிரையையும், அவைகளின் கயிறுகளையும், அவைகளின் வேலைக்கடுத்த கருவிகள் யாவையும் சுமந்து, அவைகளுக்காகச் செய்யவேண்டிய யாவையும் செய்யக்கடவர்கள்.',	4,	4,	26),
(3771,	'At the appointment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burdens, and in all their service: and ye shall appoint unto them in charge all their burdens.',	'கெர்சோன் புத்திரர் சுமக்கவேண்டிய சுமைகளும் செய்யவேண்டிய பணிவிடைகளாகிய சகல வேலைகளும் ஆரோனும் அவன் குமாரரும் சொல்லுகிறபடியே செய்யவேண்டும்; அவர்கள் சுமக்கவேண்டிய சகல சுமைகளையும் நீங்கள் நியமித்து, அவர்களிடத்தில் ஒப்புவியுங்கள்.',	4,	4,	27),
(3772,	'This is the service of the families of the sons of Gershon in the tabernacle of the congregation: and their charge shall be under the hand of Ithamar the son of Aaron the priest.',	'கெர்சோன் புத்திரரின் வம்சத்தார் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடை இதுதான்; அவர்களை வேலைகொள்ளும் விசாரணை, ஆசாரியனாகிய ஆரோனின் குமாரன் இத்தாமாருடைய கைக்குள் இருக்கவேண்டும்.',	4,	4,	28),
(3773,	'As for the sons of Merari, thou shalt number them after their families, by the house of their fathers;',	'மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை வேலைசெய்யும் சேனைக்கு உட்படத்தக்க,',	4,	4,	29),
(3774,	'From thirty years old and upward even unto fifty years old shalt thou number them, every one that entereth into the service, to do the work of the tabernacle of the congregation.',	'முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணக்கடவாய்.',	4,	4,	30),
(3775,	'And this is the charge of their burden, according to all their service in the tabernacle of the congregation; the boards of the tabernacle, and the bars thereof, and the pillars thereof, and sockets thereof,',	'ஆசரிப்புக் கூடாரத்தில் அவர்கள் செய்யும் எல்லாப் பணிவிடைக்கும் அடுத்த காவல் விசாரிப்பாவது: வாசஸ்தலத்தின் பலகைகளும், தாழ்ப்பாள்களும், தூண்களும், பாதங்களும்,',	4,	4,	31),
(3776,	'And the pillars of the court round about, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name ye shall reckon the instruments of the charge of their burden.',	'சுற்றிலும் இருக்கிற பிராகாரத்தின் தூண்களும், அவைகளின் பாதங்களும், முளைகளும், கயிறுகளும், அவைகளின் சகல கருவிகளும், அவற்றிற்கு அடுத்த மற்றெல்லா வேலையும்தானே; அவர்கள் சுமந்து காவல்காக்கும்படி ஒப்புவிக்கப்படுகிறவைகளைப் பேர்பேராக எண்ணக்கடவீர்கள்.',	4,	4,	32),
(3777,	'This is the service of the families of the sons of Merari, according to all their service, in the tabernacle of the congregation, under the hand of Ithamar the son of Aaron the priest.',	'ஆசாரியனாகிய ஆரோனுடைய குமாரனான இத்தாமாருடைய கைக்குள்ளாக மெராரி புத்திரரின் வம்சத்தார் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடைக்கு அடுத்த எல்லா வேலையும் இதுவே என்றார்.',	4,	4,	33),
(3778,	'And Moses and Aaron and the chief of the congregation numbered the sons of the Kohathites after their families, and after the house of their fathers,',	'அப்படியே மோசேயும் ஆரோனும் சபையின் பிரபுக்களும் கோகாத் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களின்படி ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,',	4,	4,	34),
(3779,	'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation:',	'முப்பது வயது முதல் ஐம்பது வயதுவரைக்குமுள்ள எல்லாரையும் எண்ணினார்கள்.',	4,	4,	35);
INSERT INTO `bible_verses` (`id`, `english_verse`, `tamil_verse`, `book_id`, `chapter_id`, `verse_id`) VALUES
(3780,	'And those that were numbered of them by their families were two thousand seven hundred and fifty.',	'அவர்கள் வம்சங்களில் எண்ணப்பட்டவர்கள் இரண்டாயிரத்து எழுநூற்று ஐம்பதுபேர்.',	4,	4,	36),
(3781,	'These were they that were numbered of the families of the Kohathites, all that might do service in the tabernacle of the congregation, which Moses and Aaron did number according to the commandment of the LORD by the hand of Moses.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, மோசேயினாலும் ஆரோனாலும் கோகாத் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலை செய்கிறதற்காக எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.',	4,	4,	37),
(3782,	'And those that were numbered of the sons of Gershon, throughout their families, and by the house of their fathers,',	'கெர்சோன் புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,',	4,	4,	38),
(3783,	'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,',	'முப்பது வயது முதல் ஐம்பது வயது வரைக்குமுள்ள எல்லாரும் எண்ணப்பட்டார்கள்.',	4,	4,	39),
(3784,	'Even those that were numbered of them, throughout their families, by the house of their fathers, were two thousand and six hundred and thirty.',	'அவர்களில் எண்ணப்பட்டவர்கள் அவரவர் குடும்பத்தின்படிக்கும், பிதாக்களுடைய வம்சத்தின்படிக்கும் இரண்டாயிரத்து அறுநூற்று முப்பதுபேர்.',	4,	4,	40),
(3785,	'These are they that were numbered of the families of the sons of Gershon, of all that might do service in the tabernacle of the congregation, whom Moses and Aaron did number according to the commandment of the LORD.',	'மோசேயினாலும் ஆரோனாலும் கர்த்தர் கட்டளையிட்டபடியே கெர்சோன் புத்திரரின் வம்சத்தாரில் ஆசரிப்புக் கூடாரத்தில் வேலைசெய்ய எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.',	4,	4,	41),
(3786,	'And those that were numbered of the families of the sons of Merari, throughout their families, by the house of their fathers,',	'மெராரி புத்திரருடைய பிதாக்களின் வீட்டு வம்சங்களிலும் ஆசரிப்புக் கூடாரத்திலே பணிவிடை செய்யும் சேனைக்கு உட்படத்தக்க,',	4,	4,	42),
(3787,	'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,',	'முப்பது வயதுமுதல் ஐம்பது வயதுள்ளவர்கள் எல்லாரும் எண்ணப்பட்டார்கள்.',	4,	4,	43),
(3788,	'Even those that were numbered of them after their families, were three thousand and two hundred.',	'அவர்களில் எண்ணப்பட்டவர்கள் தங்கள் குடும்பங்களின்படியே மூவாயிரத்து இருநூறுபேர்.',	4,	4,	44),
(3789,	'These be those that were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the word of the LORD by the hand of Moses.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே மோசேயினாலும் ஆரோனாலும் மெராரி புத்திரரின் குடும்பத்தாரில் எண்ணித் தொகையிடப்பட்டவர்கள் எல்லாரும் இவர்களே.',	4,	4,	45),
(3790,	'All those that were numbered of the Levites, whom Moses and Aaron and the chief of Israel numbered, after their families, and after the house of their fathers,',	'லேவியருடைய பிதாக்களின் வீட்டு வம்சங்களில் முப்பது வயதுமுதல் ஐம்பது வயதுவரைக்குமுள்ளவர்கள் ஆசரிப்புக் கூடாரத்திலே செய்யும் பணிவிடை வேலைக்கும் சுமையின் வேலைக்கும் உட்படத்தக்கவர்களும்,',	4,	4,	46),
(3791,	'From thirty years old and upward even unto fifty years old, every one that came to do the service of the ministry, and the service of the burden in the tabernacle of the congregation.',	'மோசேயினாலும் ஆரோனாலும் இஸ்ரவேலின் பிரபுக்களாலும் எண்ணப்பட்டவர்களும் ஆகிய எல்லாரும்,',	4,	4,	47),
(3792,	'Even those that were numbered of them, were eight thousand and five hundred and fourscore,',	'எண்ணாயிரத்து ஐந்நூற்று எண்பதுபேராயிருந்தார்கள்.',	4,	4,	48),
(3793,	'According to the commandment of the LORD they were numbered by the hand of Moses, every one according to his service, and according to his burden: thus were they numbered of him, as the LORD commanded Moses.',	'கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே, அவர்கள் தங்கள் தங்கள் பணிவிடைக்கென்றும் தங்கள் தங்கள் சுமைக்கென்றும் மோசேயினால் எண்ணப்பட்டார்கள்; இவ்விதமாய், கர்த்தர் மோசேக்குக் கட்டளையிட்டபடியே அவர்கள் அவனால் எண்ணப்பட்டார்கள்.  ',	4,	4,	49),
(3794,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	4,	5,	1),
(3795,	'Command the children of Israel, that they put out of the camp every leper, and every one that hath an issue, and whosoever is defiled by the dead:',	'குஷ்டரோகிகள் யாவரையும், பிரமியமுள்ளவர்கள் யாவரையும், சவத்தினால் தீட்டுப்பட்டவர்கள் யாவரையும் பாளயத்திலிருந்து விலக்கிவிட இஸ்ரவேல் புத்திரருக்குக் கட்டளையிடு.',	4,	5,	2),
(3796,	'Both male and female shall ye put out, without the camp shall ye put them; that they defile not their camps, in the midst whereof I dwell.',	'ஆண்பிள்ளையானாலும் பெண்பிள்ளையானாலும் அப்படிப்பட்டவர்களை நீங்கள் விலக்கி, நான் வாசம்பண்ணுகிற தங்கள் பாளயங்களை அவர்கள் தீட்டுப்படுத்தாதபடிக்கு, நீங்கள் அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிடக்கடவீர்கள் என்றார்.',	4,	5,	3),
(3797,	'And the children of Israel did so, and put them out without the camp: as the LORD spake unto Moses, so did the children of Israel.',	'கர்த்தர் மோசேக்குச் சொன்னபடியே, இஸ்ரவேல் புத்திரர் செய்து, அவர்களைப் பாளயத்திற்குப் புறம்பாக்கிவிட்டார்கள்.',	4,	5,	4),
(3798,	'And the LORD spake unto Moses, saying,',	'மேலும் கர்த்தர் மோசேயை நோக்கி:',	4,	5,	5),
(3799,	'Speak unto the children of Israel, When a man or woman shall commit any sin that men commit, to do a trespass against the LORD, and that person be guilty;',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: ஒரு புருஷனானாலும் ஸ்திரீயானாலும், கர்த்தருடைய கட்டளையை மீறி மனிதர் செய்யும் பாவங்களில் யாதொரு பாவத்தைச் செய்து குற்றவாளியானால்,',	4,	5,	6),
(3800,	'Then they shall confess their sin which they have done: and he shall recompense his trespass with the principal thereof, and add unto it the fifth part thereof, and give it unto him against whom he hath trespassed.',	'அவர்கள் தாங்கள் செய்த பாவத்தை அறிக்கையிடக்கடவர்கள்; அப்படிப்பட்டவன் தான் செய்த குற்றத்தினிமித்தம் அபராதத்தின் முதலோடே ஐந்தில் ஒரு பங்கை அதிகமாய்க் கூட்டி, தான் குற்றஞ்செய்தவனுக்குச் செலுத்தக்கடவன்.',	4,	5,	7),
(3801,	'But if the man have no kinsman to recompense the trespass unto, let the trespass be recompensed unto the LORD, even to the priest; beside the ram of the atonement, whereby an atonement shall be made for him.',	'அதைக் கேட்டு வாங்குகிறதற்கு இனத்தான் ஒருவனும் இல்லாதிருந்தால், அப்பொழுது அவனுக்காகப் பாவநிவிர்த்தி செய்யும்படி ஆட்டுக்கடா செலுத்தப்படுவதுமல்லாமல், கர்த்தருக்கு அந்த அபராதம் செலுத்தப்பட்டு, அது ஆசாரியனைச் சேரவேண்டும்.',	4,	5,	8),
(3802,	'And every offering of all the holy things of the children of Israel, which they bring unto the priest, shall be his.',	'இஸ்ரவேல் புத்திரர் ஏறெடுத்துப் படைக்கும்படி, ஆசாரியனிடத்தில் கொண்டுவருகிற எல்லாப் பரிசுத்தமான படைப்பும் அவனுடையதாயிருக்கும்.',	4,	5,	9),
(3803,	'And every man\'s hallowed things shall be his: whatsoever any man giveth the priest, it shall be his.',	'ஒவ்வொருவரும் படைக்கும் பரிசுத்தமான வஸ்துக்கள் அவனுடையதாயிருக்கும்; ஒருவன் ஆசாரியனுக்குக் கொடுக்கிறது எதுவும் அவனுக்கே உரியது என்று சொல் என்றார்.',	4,	5,	10),
(3804,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	4,	5,	11),
(3805,	'Speak unto the children of Israel, and say unto them, If any man\'s wife go aside, and commit a trespass against him,',	'நீ இஸ்ரவேல் புத்திரருக்குச் சொல்லவேண்டியது என்னவென்றால்: ஒருவனுடைய மனைவி பிறர்முகம் பார்த்து, புருஷனுக்குத் துரோகம்பண்ணி,',	4,	5,	12),
(3806,	'And a man lie with her carnally, and it be hid from the eyes of her husband, and be kept close, and she be defiled, and there be no witness against her, neither she be taken with the manner;',	'ஒருவனோடே சம்யோகமாய்ச் சயனித்திருந்த விஷயத்தில் அவள் தீட்டுப்பட்டவளாயிருந்தும், அவளுடைய புருஷன் கண்களுக்கு அது மறைக்கப்பட்டு வெளிக்கு வராமல் இருக்கிறபோதும், சாட்சியில்லாமலும் அவள் கையும் களவுமாகப் பிடிக்கப்படாமலும் இருக்கிறபோதும்,',	4,	5,	13),
(3807,	'And the spirit of jealousy come upon him, and he be jealous of his wife, and she be defiled: or if the spirit of jealousy come upon him, and he be jealous of his wife, and she be not defiled:',	'எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் அவனுடைய மனைவி தீட்டுப்படுத்தப்பட்டிருக்க, தீட்டுப்படுத்தப்பட்ட தன் மனைவியின்மேல் குரோதங்கொண்டிருந்தாலும், அல்லது அவன் மனைவி தீட்டுப்படுத்தப்படாதிருக்க, எரிச்சலின் ஆவி அவன்மேல் வந்து, அவன் அவள்மேல் குரோதங்கொண்டிருந்தாலும்,',	4,	5,	14),
(3808,	'Then shall the man bring his wife unto the priest, and he shall bring her offering for her, the tenth part of an ephah of barley meal; he shall pour no oil upon it, nor put frankincense thereon; for it is an offering of jealousy, an offering of memorial, bringing iniquity to remembrance.',	'அந்தப் புருஷன் தன் மனைவியை ஆசாரியனிடத்தில் அழைத்துக்கொண்டுவந்து, அவள் நிமித்தம் ஒரு எப்பா அளவான வாற்கோதுமை மாவிலே பத்தில் ஒரு பங்கைப் படைப்பாகக் கொடுக்கக்கடவன்; அது எரிச்சலின் காணிக்கையும் அக்கிரமத்தை நினைப்பூட்டும் காணிக்கையுமாய் இருப்பதினால், அதின்மேல் எண்ணெய் வார்க்காமலும் தூபவர்க்கம் போடாமலும் இருப்பானாக.',	4,	5,	15),
(3809,	'And the priest shall bring her near, and set her before the LORD:',	'ஆசாரியன் அவளைச் சமீபத்தில் அழைத்து, கர்த்தருடைய சந்நிதியில் நிறுத்தி,',	4,	5,	16),
(3810,	'And the priest shall take holy water in an earthen vessel; and of the dust that is in the floor of the tabernacle the priest shall take, and put it into the water:',	'ஒரு மண்பாண்டத்திலே பரிசுத்த ஜலம் வார்த்து, வாசஸ்தலத்தின் தரையிலிருக்கும் புழுதியிலே கொஞ்சம் எடுத்து, அந்த ஜலத்தில் போட்டு,',	4,	5,	17),
(3811,	'And the priest shall set the woman before the LORD, and uncover the woman\'s head, and put the offering of memorial in her hands, which is the jealousy offering: and the priest shall have in his hand the bitter water that causeth the curse:',	'ஸ்திரீயைக் கர்த்தருடைய சந்நிதியில் நிறுத்தி, அவள் முக்காட்டை நீக்கி, எரிச்சலின் காணிக்கையாகிய நினைப்பூட்டுதலின் காணிக்கையை அவள் உள்ளங்கையிலே வைப்பானாக; சாபகாரணமான கசப்பான ஜலம் ஆசாரியன் கையில் இருக்கவேண்டும்.',	4,	5,	18),
(3812,	'And the priest shall charge her by an oath, and say unto the woman, If no man have lain with thee, and if thou hast not gone aside to uncleanness with another instead of thy husband, be thou free from this bitter water that causeth the curse:',	'பின்பு ஆசாரியன் அவளை ஆணையிடுவித்து: ஒருவனும் உன்னோடே சயனியாமலும், உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ தீட்டுப்படத்தக்கதாய்ப் பிறர்முகம் பாராமலும் இருந்தால், சாபகாரணமான இந்தக் கசப்பான ஜலத்தின் தோஷத்துக்கு நீங்கலாயிருப்பாய்.',	4,	5,	19),
(3813,	'But if thou hast gone aside to another instead of thy husband, and if thou be defiled, and some man have lain with thee beside thine husband:',	'உன் புருஷனுக்கு உட்பட்டிருக்கிற நீ பிறர்முகம் பார்த்து, உன் புருஷனோடேயன்றி அந்நியனோடே சம்யோகமாய் சயனித்து தீட்டுப்பட்டிருப்பாயானால்,',	4,	5,	20),
(3814,	'Then the priest shall charge the woman with an oath of cursing, and the priest shall say unto the woman, The LORD make thee a curse and an oath among thy people, when the LORD doth make thy thigh to rot, and thy belly to swell;',	'கர்த்தர் உன் இடுப்பு சூம்பவும், உன் வயிறு வீங்கவும்பண்ணி, உன்னை உன் ஜனங்களுக்குள்ளே சாபமும் ஆணையிடுங்குறியுமாக வைப்பாராக.',	4,	5,	21),
(3815,	'And this water that causeth the curse shall go into thy bowels, to make thy belly to swell, and thy thigh to rot: And the woman shall say, Amen, amen.',	'சாபகாரணமான இந்த ஜலம் உன் வயிறு வீங்கவும் இடுப்பு சூம்பவும் பண்ணும்படி, உன் குடலுக்குள் பிரவேசிக்கக்கடவது என்கிற சாபவார்த்தையாலே ஸ்திரீயை ஆணையிடுவித்துச் சொல்வானாக. அதற்கு அந்த ஸ்திரீ: ஆமென், ஆமென், என்று சொல்லக்கடவள்.',	4,	5,	22),
(3816,	'And the priest shall write these curses in a book, and he shall blot them out with the bitter water:',	'பின்பு ஆசாரியன் இந்தச் சாபவார்த்தைகளை ஒரு சீட்டில் எழுதி, அவைகளைக் கசப்பான ஜலத்தினால் கழுவிப்போட்டு,',	4,	5,	23),
(3817,	'And he shall cause the woman to drink the bitter water that causeth the curse: and the water that causeth the curse shall enter into her, and become bitter.',	'சாபகாரணமான அந்தக் கசப்பான ஜலத்தை அவள் குடிக்கும்படி பண்ணுவான்; அப்பொழுது சாபகாரணமான அந்த ஜலம் அவளுக்குள் இறங்கிக் கசப்பாகும்.',	4,	5,	24),
(3818,	'Then the priest shall take the jealousy offering out of the woman\'s hand, and shall wave the offering before the LORD, and offer it upon the altar:',	'பின்பு ஆசாரியன் எரிச்சலின் காணிக்கையை அந்த ஸ்திரீயின் கையிலிருந்து வாங்கி, அதைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டி, பீடத்தின்மேல் செலுத்தி,',	4,	5,	25),
(3819,	'And the priest shall take an handful of the offering, even the memorial thereof, and burn it upon the altar, and afterward shall cause the woman to drink the water.',	'ஞாபகக்குறியாக அதிலே ஒரு கைப்பிடி நிறைய எடுத்து, பீடத்தின்மேல் தகனித்து, பின்பு ஸ்திரீக்கு அந்த ஜலத்தைக்குடிக்கும்படி கொடுக்கக்கடவன்.',	4,	5,	26),
(3820,	'And when he hath made her to drink the water, then it shall come to pass, that, if she be defiled, and have done trespass against her husband, that the water that causeth the curse shall enter into her, and become bitter, and her belly shall swell, and her thigh shall rot: and the woman shall be a curse among her people.',	'அந்த ஜலத்தைக் குடிக்கச் செய்த பின்பு சம்பவிப்பதாவது: அவள் தீட்டுப்பட்டு, தன் புருஷனுக்குத் துரோகம்பண்ணியிருந்தால், சாபகாரணமான அந்த ஜலம் அவளுக்குள் பிரவேசித்துக் கசப்புண்டானதினால், அவள் வயிறு வீங்கி, அவள் இடுப்பு சூம்பும்; இப்படியே அந்த ஸ்திரீ தன் ஜனங்களுக்குள்ளே சாபமாக இருப்பாள்.',	4,	5,	27),
(3821,	'And if the woman be not defiled, but be clean; then she shall be free, and shall conceive seed.',	'அந்த ஸ்திரீ தீட்டுப்படாமல் சுத்தமாயிருந்தால், அவள் அதற்கு நீங்கலாகி, கர்ப்பந்தரிக்கத்தக்கவளாயிருப்பாள்.',	4,	5,	28),
(3822,	'This is the law of jealousies, when a wife goeth aside to another instead of her husband, and is defiled;',	'ஒரு ஸ்திரீ தன் புருஷனோடேயன்றி அந்நிய புருஷனோடே சேர்ந்து தீட்டுப்பட்டதினால் உண்டான எரிச்சலுக்கும்,',	4,	5,	29),
(3823,	'Or when the spirit of jealousy cometh upon him, and he be jealous over his wife, and shall set the woman before the LORD, and the priest shall execute upon her all this law.',	'புருஷன்மேல் எரிச்சலின் ஆவி வருகிறதினால், அவன் தன் மனைவியின்மேல் அடைந்த சமுசயத்துக்கும் அடுத்த பிரமாணம் இதுவே. அவன் கர்த்தருடைய சந்நிதியில் தன் மனைவியை நிறுத்துவானாக; ஆசாரியன் இந்தப் பிரமாணத்தின்படியெல்லாம் அவளுக்குச் செய்யக்கடவன்.',	4,	5,	30),
(3824,	'Then shall the man be guiltless from iniquity, and this woman shall bear her iniquity.',	'புருஷனானவன் அக்கிரமத்திற்கு நீங்கலாயிருப்பான்; அப்படிப்பட்ட ஸ்திரீயோ, தன் அக்கிரமத்தைச் சுமப்பாள் என்று சொல் என்றார்.  ',	4,	5,	31),
(3825,	'And the LORD spake unto Moses, saying,',	'கர்த்தர் மோசேயை நோக்கி:',	4,	6,	1),
(3826,	'Speak unto the children of Israel, and say unto them, When either man or woman shall separate themselves to vow a vow of a Nazarite, to separate themselves unto the LORD:',	'நீ இஸ்ரவேல் புத்திரரோடே சொல்லவேண்டியது என்னவென்றால்: புருஷனாகிலும் ஸ்திரீயாகிலும் கர்த்தருக்கென்று விரதம் பண்ணிக்கொண்டவர்களாயிருக்கும்படி நசரேய விரதமாகிய ஒரு விசேஷித்த பொருத்தனையைப்பண்ணினால்,',	4,	6,	2),
(3827,	'He shall separate himself from wine and strong drink, and shall drink no vinegar of wine, or vinegar of strong drink, neither shall he drink any liquor of grapes, nor eat moist grapes, or dried.',	'அப்படிப்பட்டவன் திராட்சரசத்தையும் மதுபானத்தையும் விலக்கக்கடவன்; அவன் திராட்சரசத்தின் காடியையும் மற்ற மதுபானத்தின் காடியையும், திராட்சரசத்தினால் செய்த எவ்விதமான பானத்தையும் குடியாமலும், திராட்சப்பழங்களையாவது திராட்சவற்றல்களையாவது புசியாமலும்,',	4,	6,	3),
(3828,	'All the days of his separation shall he eat nothing that is made of the vine tree, from the kernels even to the husk.',	'தான் நசரேயனாயிருக்கும் நாளெல்லாம் திராட்சச்செடி விதைமுதல் தோல்வரையிலுள்ளவைகளினால் செய்யப்பட்ட யாதொன்றையும் புசியாமலும் இருக்கக்கடவன்.',	4,	6,	4),
(3829,	'All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth himself unto the LORD, he shall be holy, and shall let the locks of the hair of his head grow.',	'அவன் நசரேய விரதங்காக்கும் நாளெல்லாம் சவரகன் கத்தி அவன் தலையின்மேல் படலாகாது; அவன் கர்த்தருக்கென்று விரதங்காக்கும் காலம் நிறைவேறுமளவும் பரிசுத்தமாயிருந்து, தன் தலைமயிரை வளரவிடக்கடவன்.',	4,	6,	5),
(3830,	'All the days that he separateth himself unto the LORD he shall come at no dead body.',	'அவன் கர்த்தருக்கென்று விரதங்காக்கும் நாளெல்லாம் யாதொரு பிரேதத்தண்டையில் போகக்கூடாது.',	4,	6,	6),
(3831,	'He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die: because the consecration of his God is upon his head.',	'அவன் தன் தேவனுக்கென்று செய்த நசரேய விரதம் அவன் தலைமேல் இருக்கிறபடியால், மரணமடைந்த தன் தகப்பனாலாகிலும் தாயினாலாகிலும் சகோதரனாலாகிலும் சகோதரியினாலாகிலும் தன்னைத் தீட்டுப்படுத்தலாகாது.',	4,	6,	7),
(3832,	'All the days of his separation he is holy unto the LORD.',	'அவன் நசரேயனாயிருக்கும் நாளெல்லாம் கர்த்தருக்குப் பரிசுத்தமாயிருப்பான்.',	4,	6,	8),
(3833,	'And if any man die very suddenly by him, and he hath defiled the head of his consecration; then he shall shave his head in the day of his cleansing, on the seventh day shall he shave it.',	'அவனண்டையிலே ஒருவன் சடுதியில் மரணமடைந்ததினால், நசரேய விரதமுள்ள அவனுடைய தலை தீட்டுப்பட்டதேயாகில், அவன் தன் சுத்திகரிப்பின் நாளாகிய ஏழாம் நாளில் தன் தலைமயிரைச் சிரைத்துக்கொண்டு,',	4,	6,	9),
(3834,	'And on the eighth day he shall bring two turtles, or two young pigeons, to the priest, to the door of the tabernacle of the congregation:',	'எட்டாம் நாளில் இரண்டு காட்டுப்புறாக்களையாவது இரண்டு புறாக்குஞ்சுகளையாவது ஆசரிப்புக் கூடாரவாசலில் ஆசாரியனிடத்தில் கொண்டுவரக்கடவன்.',	4,	6,	10),
(3835,	'And the priest shall offer the one for a sin offering, and the other for a burnt offering, and make an atonement for him, for that he sinned by the dead, and shall hallow his head that same day.',	'அப்பொழுது ஆசாரியன் ஒன்றைப்பாவநிவாரணபலியாகவும், மற்றொன்றைச் சர்வாங்க தகனபலியாகவும் செலுத்தி, பிணத்தினால் அவனுக்கு உண்டான தீட்டை நிவிர்த்திசெய்து, அவன் தலையை அந்நாளில் பரிசுத்தப்படுத்துவானாக.',	4,	6,	11),
(3836,	'And he shall consecrate unto the LORD the days of his separation, and shall bring a lamb of the first year for a trespass offering: but the days that were before shall be lost, because his separation was defiled.',	'அவன் திரும்பவும் தன் விரதநாட்களைக் கர்த்தருக்கென்று காத்து, ஒரு வருஷத்து ஆட்டுக்குட்டியைக் குற்றநிவாரணபலியாகக் கொண்டுவரக்கடவன்; அவனுடைய நசரேய விரதம் தீட்டுப்பட்டதினால் சென்ற நாட்கள் விருதாவாகும்.',	4,	6,	12),
(3837,	'And this is the law of the Nazarite, when the days of his separation are fulfilled: he shall be brought unto the door of the tabernacle of the congregation:',	'நசரேயனுக்குரிய பிரமாணமாவது: அவன் விரதங்காக்கும் நாட்கள் நிறைவேறின அன்றே, அவன் ஆசரிப்புக் கூடாரவாசலிலே வந்து,',	4,	6,	13),
(3838,	'And he shall offer his offering unto the LORD, one he lamb of the first year without blemish for a burnt offering, and one ewe lamb of the first year without blemish for a sin offering, and one ram without blemish for peace offerings,',	'சர்வாங்க தகனபலியாக ஒருவருஷத்து பழுதற்ற ஒரு ஆட்டுக்குட்டியையும், பாவநிவாரணபலியாக ஒருவருஷத்து பழுதற்ற ஒரு பெண்ணாட்டுக்குட்டியையும், சமாதானபலியாக பழுதற்ற ஒரு ஆட்டுக்கடாவையும்,',	4,	6,	14),
(3839,	'And a basket of unleavened bread, cakes of fine flour mingled with oil, and wafers of unleavened bread anointed with oil, and their meat offering, and their drink offerings.',	'ஒரு கூடையில் எண்ணெயிலே பிசைந்த புளிப்பில்லாத மெல்லிய மாவினால் செய்த அதிரசங்களையும், எண்ணெய் தடவப்பட்ட புளிப்பில்லாத அடைகளையும், அவைகளுக்கு அடுத்த போஜனபலியையும், பானபலிகளையும் கர்த்தருக்குத் தன் காணிக்கையாகச் செலுத்தக்கடவன்.',	4,	6,	15),
(3840,	'And the priest shall bring them before the LORD, and shall offer his sin offering, and his burnt offering:',	'அவைகளை ஆசாரியன் கர்த்தருடைய சந்நிதியில் கொண்டுவந்து, அவனுடைய பாவநிவாரணபலியையும் அவனுடைய சர்வாங்கதகனபலியையும் செலுத்தி,',	4,	6,	16),
(3841,	'And he shall offer the ram for a sacrifice of peace offerings unto the LORD, with the basket of unleavened bread: the priest shall offer also his meat offering, and his drink offering.',	'ஆட்டுக்கடாவைக் கூடையிலிருக்கும் புளிப்பில்லாத அப்பங்களோடுங்கூடக் கர்த்தருக்குச் சமாதான பலியாகச் செலுத்தி, அவனுடைய போஜனபலியையும் பானபலியையும் படைப்பானாக.',	4,	6,	17),
(3842,	'And the Nazarite shall shave the head of his separation at the door of the tabernacle of the congregation, and shall take the hair of the head of his separation, and put it in the fire which is under the sacrifice of the peace offerings.',	'அப்பொழுது நசரேயன் ஆசரிப்புக் கூடாரவாசலிலே, பொருத்தனை செய்யப்பட்ட தன் தலையைச் சிரைத்து, பொருத்தனை செய்யப்பட்ட தன் தலைமயிரை எடுத்து, சமாதானபலியின்கீழ் எரிகிற அக்கினியில் போடக்கடவன்.',	4,	6,	18),
(3843,	'And the priest shall take the sodden shoulder of the ram, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them upon the hands of the Nazarite, after the hair of his separation is shaven:',	'நசரேயன் பொருத்தனை செய்யப்பட்ட தன் தலைமயிரைச் சிரைத்துக்கொண்டபின்பு, ஆசாரியன் ஆட்டுக்கடாவினுடைய வேவிக்கப்பட்ட ஒரு முன்னந்தொடையையும், கூடையில் இருக்கிறவைகளிலே புளிப்பில்லாத ஒரு அதிரசத்தையும் புளிப்பில்லாத ஒரு அடையையும் எடுத்து, அவனுடைய உள்ளங்கைகளில் வைத்து,',	4,	6,	19),
(3844,	'And the priest shall wave them for a wave offering before the LORD: this is holy for the priest, with the wave breast and heave shoulder: and after that the Nazarite may drink wine.',	'அவைகளைக் கர்த்தருடைய சந்நிதியில் அசைவாட்டக்கடவன்; அது அசைவாட்டப்பட்ட மார்க்கண்டத்தோடும், ஏறெடுத்துப் படைக்கப்பட்ட முன்னந்தொடையோடும், ஆசாரியனைச் சேரும்; அது பரிசுத்தமானது. பின்பு நசரேயன் திராட்சரசம் குடிக்கலாம்.',	4,	6,	20),
(3845,	'This is the law of the Nazarite who hath vowed, and of his offering unto the LORD for his separation, beside that that his hand shall get: according to the vow which he vowed, so he must do after the law of his separation.',	'பொருத்தனைபண்ணின நசரேயனுக்கும், அவன் தன் கைக்கு உதவுகிறதையல்லாமல், தன் நசரேய விரதத்தினிமித்தம் கர்த்தருக்குச் செலுத்தும் காணிக்கைக்கும் அடுத்த பிரமாணம் இதுவே. அவன் செய்த பொருத்தனையின்படியே தன் பொருத்தனையின் பிரமாணத்துக்கேற்க செய்து தீரவேண்டும் என்று சொல் என்றார்.',	4,	6,	21),
(3846,	'And the LORD spake unto Moses, saying,',	'பின்னும் கர்த்தர் மோசேயை நோக்கி:',	4,	6,	22),
(3847,	'Speak unto Aaron and unto his sons, saying, On this wise ye shall bless the children of Israel, saying unto them,',	'நீ ஆரோனோடும் அவன் குமாரரோடும் சொல்லவேண்டியது என்னவென்றால்: நீங்கள் இஸ்ரவேல் புத்திரரை ஆசீர்வதிக்கும்போது, அவர்களைப் பார்த்துச் சொல்லவேண்டியதாவது:',	4,	6,	23),
(3848,	'The LORD bless thee, and keep thee:',	'கர்த்தர் உன்னை ஆசீர்வதித்து, உன்னைக் காக்கக்கடவர்.',	4,	6,	24),
(3849,	'The LORD make his face shine upon thee, and be gracious unto thee:',	'கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரகாசிக்கப்பண்ணி, உன்மேல் கிருபையாயிருக்கக்கடவர்.',	4,	6,	25),
(3850,	'The LORD lift up his countenance upon thee, and give thee peace.',	'கர்த்தர் தம்முடைய முகத்தை உன்மேல் பிரசன்னமாக்கி, உனக்குச் சமாதானம் கட்டளையிடக்கடவர் என்பதே.',	4,	6,	26),
(3851,	'And they shall put my name upon the children of Israel, and I will bless them.',	'இவ்விதமாய் அவர்கள் என் நாமத்தை இஸ்ரவேல் புத்திரர்மேல் கூறக்கடவர்கள்; அப்பொழுது நான் அவர்களை ஆசீர்வதிப்பேன் என்று சொல் என்றார்.  ',	4,	6,	27),
(3852,	'And it came to pass on the day that Moses had fully set up the tabernacle, and had anointed it, and sanctified it, and all the instruments thereof, both the altar and all the vessels thereof, and had anointed them, and sanctified them;',	'மோசே வாசஸ்தலத்தை ஸ்தாபனம்பண்ணி, அதையும் அதின் எல்லாப் பணிமுட்டுகளையும், பலிபீடத்தையும் அதின் எல்லாப் பணிமுட்டுகளையும் அபிஷேகம்பண்ணி, பரிசுத்தப்படுத்தி முடித்த நாளில்,',	4,	7,	1),
(3853,	'That the princes of Israel, heads of the house of their fathers, who were the princes of the tribes, and were over them that were numbered, offered:',	'தங்கள் பிதாக்களுடைய வம்சத்தலைவரும், எண்ணப்பட்டவர்களின் விசாரிப்புக்கு வைக்கப்பட்ட கோத்திரப் பிரபுக்களுமாகிய இஸ்ரவேலின் பிரபுக்கள் காணிக்கைகளைச் செலுத்தினார்கள்.',	4,	7,	2),
(3854,	'And they brought their offering before the LORD, six covered wagons, and twelve oxen; a wagon for two of the princes, and for each one an ox: and they brought them before the tabernacle.',	'தங்கள் காணிக்கையாக, ஆறு கூண்டு வண்டில்களையும், பன்னிரண்டு மாடுகளையும் இரண்டிரண்டு பிரபுக்களுக்கு ஒவ்வொரு வண்டிலும், ஒவ்வொரு பிரபுக்கு ஒவ்வொரு மாடுமாக, கர்த்தருக்குச் செலுத்த வாசஸ்தலத்திற்கு முன்பாகக் கொண்டுவந்தார்கள்.',	4,	7,	3),
(3855,	'And the LORD spake unto Moses, saying,',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி:',	4,	7,	4),
(3856,	'Take it of them, that they may be to do the service of the tabernacle of the congregation; and thou shalt give them unto the Levites, to every man according to his service.',	'நீ அவர்களிடத்தில் ஆசரிப்புக் கூடாரத்தின் ஊழியத்திற்காக அவைகளை வாங்கி. லேவியருக்கு அவரவர் வேலைக்குத் தக்கவைகளாகப் பங்கிட்டுக் கொடு என்றார்.',	4,	7,	5),
(3857,	'And Moses took the wagons and the oxen, and gave them unto the Levites.',	'அப்பொழுது மோசே அந்த வண்டில்களையும் மாடுகளையும் வாங்கி, லேவியருக்குக் கொடுத்தான்.',	4,	7,	6),
(3858,	'Two wagons and four oxen he gave unto the sons of Gershon, according to their service:',	'இரண்டு வண்டில்களையும் நான்கு மாடுகளையும் கெர்சோன் புத்திரருக்கு, அவர்கள் வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.',	4,	7,	7),
(3859,	'And four wagons and eight oxen he gave unto the sons of Merari, according unto their service, under the hand of Ithamar the son of Aaron the priest.',	'நான்கு வண்டில்களையும் எட்டு மாடுகளையும் மெராரியின் புத்திரருக்கு, ஆசாரியனாகிய ஆரோனின் குமாரர் இத்தாமாருடைய கையின் கீழிருக்கிற அவர்களுடைய வேலைக்குத்தக்க பங்காகக் கொடுத்தான்.',	4,	7,	8),
(3860,	'But unto the sons of Kohath he gave none: because the service of the sanctuary belonging unto them was that they should bear upon their shoulders.',	'கோகாத்தின் புத்திரருக்கோ ஒன்றும் கொடுக்கவில்லை; தோள்மேல் சுமப்பதே அவர்களுக்குரிய பரிசுத்த ஸ்தலத்தின் வேலையாயிருந்தது.',	4,	7,	9),
(3861,	'And the princes offered for dedicating of the altar in the day that it was anointed, even the princes offered their offering before the altar.',	'பலிபீடம் அபிஷேகம்பண்ணப்பட்ட நாளிலே, பிரபுக்கள் அதின் பிரதிஷ்டைக்காகக் காணிக்கைகளைச் செலுத்தி, பலிபீடத்துக்கு முன்பாகத் தங்கள் காணிக்கைகளைக் கொண்டுவந்தார்கள்.',	4,	7,	10),
(3862,	'And the LORD said unto Moses, They shall offer their offering, each prince on his day, for the dedicating of the altar.',	'அப்பொழுது கர்த்தர் மோசேயை நோக்கி: பலிபீடத்தின் பிரதிஷ்டைக்காக ஒவ்வொரு பிரபுவும் தன்தன் நாளில் தன்தன் காணிக்கையைச் செலுத்தக்கடவன் என்றார்.',	4,	7,	11),
(3863,	'And he that offered his offering the first day was Nahshon the son of Amminadab, of the tribe of Judah:',	'அப்படியே முதலாம் நாளில் தன் காணிக்கையைச் செலுத்தினவன் யூதா கோத்திரத்தானாகிய அம்மினதாபின் குமாரன் நகசோன்.',	4,	7,	12),
(3864,	'And his offering was one silver charger, the weight thereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them were full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	13),
(3865,	'One spoon of ten shekels of gold, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	14),
(3866,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	15),
(3867,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	16),
(3868,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nahshon the son of Amminadab.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது அம்மினதாபின் குமாரனாகிய நகசோனின் காணிக்கை.',	4,	7,	17),
(3869,	'On the second day Nethaneel the son of Zuar, prince of Issachar, did offer:',	'இரண்டாம் நாளில் இசக்காரின் பிரபுவாகிய சூவாரின் குமாரன் நெதனெயேல் காணிக்கை செலுத்தினான்.',	4,	7,	18),
(3870,	'He offered for his offering one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு, எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	19),
(3871,	'One spoon of gold of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	20),
(3872,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	21),
(3873,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	22),
(3874,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Nethaneel the son of Zuar.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூவாரின் குமாரனாகிய நெதனெயேலின் காணிக்கை.',	4,	7,	23),
(3875,	'On the third day Eliab the son of Helon, prince of the children of Zebulun, did offer:',	'மூன்றாம் நாளில் ஏலோனின் குமாரனாகிய எலியாப் என்னும் செபுலோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.',	4,	7,	24),
(3876,	'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	25),
(3877,	'One golden spoon of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	26),
(3878,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	27),
(3879,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	28),
(3880,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliab the son of Helon.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும் ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது ஏலோனின் குமாரனாகிய எலியாபின் காணிக்கை.',	4,	7,	29),
(3881,	'On the fourth day Elizur the son of Shedeur, prince of the children of Reuben, did offer:',	'நான்காம் நாளில் சேதேயூரின் குமாரனாகிய எலிசூர் என்னும் ரூபன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.',	4,	7,	30),
(3882,	'His offering was one silver charger of the weight of an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	31),
(3883,	'One golden spoon of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	32),
(3884,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	33),
(3885,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	34),
(3886,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Elizur the son of Shedeur.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்காடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சேதேயூரின் குமாரனாகிய எலிசூரின் காணிக்கை.',	4,	7,	35),
(3887,	'On the fifth day Shelumiel the son of Zurishaddai, prince of the children of Simeon, did offer:',	'ஐந்தாம் நாளில் சூரிஷதாயின் குமாரனாகிய செலூமியேல் என்னும் சிமியோன் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.',	4,	7,	36),
(3888,	'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிகலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	37),
(3889,	'One golden spoon of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	38),
(3890,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	39),
(3891,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	40),
(3892,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Shelumiel the son of Zurishaddai.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது சூரிஷதாயின் குமாரனாகிய செலூமியேலின் காணிக்கை.',	4,	7,	41),
(3893,	'On the sixth day Eliasaph the son of Deuel, prince of the children of Gad, offered:',	'ஆறாம் நாளிலே தேகுவேலின் குமாரனாகிய எலியாசாப் என்னும் காத் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.',	4,	7,	42),
(3894,	'His offering was one silver charger of the weight of an hundred and thirty shekels, a silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	43),
(3895,	'One golden spoon of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	44),
(3896,	'One young bullock, one ram, one lamb of the first year, for a burnt offering:',	'சர்வாங்கதகனபலியாக ஒரு காளையும், ஒரு ஆட்டுக்கடாவும், ஒருவயதான ஒரு ஆட்டுக்குட்டியும்,',	4,	7,	45),
(3897,	'One kid of the goats for a sin offering:',	'பாவநிவாரணபலியாக ஒரு வெள்ளாட்டுக்கடாவும்,',	4,	7,	46),
(3898,	'And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliasaph the son of Deuel.',	'சமாதானபலியாக இரண்டு மாடுகளும், ஐந்து ஆட்டுக்கடாக்களும், ஐந்து வெள்ளாட்டுக்கடாக்களும், ஒருவயதான ஐந்து ஆட்டுக்குட்டிகளுமே; இது தேகுவேலின் குமாரனாகிய எலியாசாபின் காணிக்கை.',	4,	7,	47),
(3899,	'On the seventh day Elishama the son of Ammihud, prince of the children of Ephraim, offered:',	'ஏழாம் நாளில் அம்மீயூதின் குமாரனாகிய எலிஷாமா என்னும் எப்பிராயீம் புத்திரரின் பிரபு காணிக்கை செலுத்தினான்.',	4,	7,	48),
(3900,	'His offering was one silver charger, the weight whereof was an hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mingled with oil for a meat offering:',	'அவன் காணிக்கையாவது: போஜனபலியாகப் படைக்கும்பொருட்டு எண்ணெயிலே பிசைந்த மெல்லிய மாவினால் நிறைந்ததும், பரிசுத்த ஸ்தலத்தின் சேக்கல் கணக்காக நூற்றுமுப்பது சேக்கல் நிறையுள்ளதுமான ஒரு வெள்ளித்தாலமும், எழுபது சேக்கல் நிறையுள்ள ஒரு வெள்ளிக்கலமும் ஆகிய இவ்விரண்டும்,',	4,	7,	49),
(3901,	'One golden spoon of ten shekels, full of incense:',	'தூபவர்க்கம் நிறைந்த பத்துச்சேக்கல் நிறையுள்ள பொன்னினால் செய்த ஒரு தூபகரண்டியும்,',	4,	7,	50),
